    /**
     * The empty band the docked frame holds above the board, in px: room for
     * the key preview bubbles, plus whatever a bar row keeps held open while
     * it is out (the on-demand tools row, see RowRevealHeadroom), the room a
     * panel's height bar holds for a drag, and resize mode's reserved band
     * (#643). Window, not keyboard: [onComputeInsets] keeps it out of the
     * app's content and visible insets, so the app is laid out to the board
     * and a tap in the band is the app's (resize mode keeps those taps).
     */
    private var windowHeadroomPx = 0

    fun onWindowHeadroom(px: Int) {
        if (px == windowHeadroomPx) return
        windowHeadroomPx = px
        // Insets are only re-queried on a window layout pass; force one.
        window?.window?.decorView?.requestLayout()
    }

    // ---- full-screen handwriting (issue #386) ----

    /** The compact bar's rectangle in IME-window pixels, for the touchable region. */
    private var hwFullScreenBarBounds: android.graphics.Rect? = null

    private val hwFullScreenControls = HandwritingFullScreenControls(
        onToggle = ::onHandwritingFullScreenToggle,
        onInkToggle = ::onHandwritingInkToggle,
        onBarBounds = ::onHandwritingFullScreenBarBounds,
    )

    /**
     * The panel's expand button, or the bar's shrink one. Pending ink goes:
     * it was drawn in the other canvas's coordinates, and recognising it
     * against this one's size would read it as a different shape.
     */
    private fun onHandwritingFullScreenToggle() {
        vibrate()
        dropKeyboardHandwritingInk()
        hwFullScreenBarBounds = null
        _uiState.update {
            it.copy(
                handwriting = it.handwriting.copy(
                    fullScreen = !it.handwriting.fullScreen,
                    fullScreenInk = true,
                ),
            )
        }
        // A landscape extract editor would cover the app the ink is for.
        updateFullscreenMode()
        // Insets are only re-queried on a window layout pass; force one.
        window?.window?.decorView?.requestLayout()
    }

    /** Pen-button mode: the canvas catches touches as ink, or lets them through. */
    private fun onHandwritingInkToggle() {
        vibrate()
        _uiState.update {
            it.copy(handwriting = it.handwriting.copy(fullScreenInk = !it.handwriting.fullScreenInk))
        }
        window?.window?.decorView?.requestLayout()
    }

    private fun onHandwritingFullScreenBarBounds(bounds: IntRect) {
        val rect = android.graphics.Rect(bounds.left, bounds.top, bounds.right, bounds.bottom)
        if (rect != hwFullScreenBarBounds) {
            hwFullScreenBarBounds = rect
            window?.window?.decorView?.requestLayout()
        }
    }

    // ---- floating mode ----

    /** Panel bounds in IME-window coordinates, for the touchable region. */
    private var floatingPanelBounds: android.graphics.Rect? = null

    fun onFloatingBounds(bounds: IntRect) {
        val rect = android.graphics.Rect(bounds.left, bounds.top, bounds.right, bounds.bottom)
        if (rect != floatingPanelBounds) {
            floatingPanelBounds = rect
            // Insets are only re-queried on a window layout pass; the panel
            // can move without the view tree changing size, so force one.
            window?.window?.decorView?.requestLayout()
        }
    }

    /**
     * Floats or docks the keyboard in the orientation it is held in: each
     * remembers its own (#584), so the toolbar tool and the dock button never
     * reach the other one.
     */
    fun onFloatingChange(enabled: Boolean) {
        vibrate()
        if (!enabled) floatingPanelBounds = null
        val landscape = landscapeNow()
        serviceScope.launch { settingsRepository.setFloatingKeyboard(landscape, enabled) }
    }

    private fun landscapeNow(): Boolean =
        resources.configuration.orientation == Configuration.ORIENTATION_LANDSCAPE

    /** The keyboard floats in the orientation it is held in right now. */
    private fun floatingNow(): Boolean = _uiState.value.settings.floatingFor(landscapeNow())

    /**
     * The keep-on-screen tool; the Layout screen's row writes the same
     * setting (issue #58). Pinning again after a hide is a fresh ask, so the
     * suspension from that hide and this field's re-show budget both start
     * over.
     */
    fun onPersistentChange(enabled: Boolean) {
        vibrate()
        pinSuspended = false
        pinReshowStreak = 0
        serviceScope.launch { settingsRepository.setPersistentKeyboard(enabled) }
    }

    fun onFloatingMoved(xFraction: Float, yFraction: Float) {
        serviceScope.launch { settingsRepository.setFloatingPosition(xFraction, yFraction) }
    }

    /**
     * Every geometry change the UI hands back: the floating grip and the
     * inline resize tool share this slot (see [SizingAction] for why one slot).
     */
    fun onSizingAction(action: SizingAction) {
        when (action) {
            is SizingAction.Floating -> serviceScope.launch {
                settingsRepository.setFloatingSize(action.widthDp, action.heightScale)
            }
            is SizingAction.ResizeCommit -> {
                serviceScope.launch {
                    settingsRepository.setVariantSizing(
                        variant = action.variant,
                        keyHeightDp = action.keyHeightDp,
                        numberRowHeightDp = action.numberRowHeightDp,
                        bottomPaddingDp = action.bottomPaddingDp,
                        sidePadLeftScale = action.sidePadLeftScale,
                        sidePadRightScale = action.sidePadRightScale,
                    )
                }
                _uiState.update { it.copy(resize = false) }
            }
            SizingAction.ResizeCancel -> _uiState.update { it.copy(resize = false) }
        }
    }

    /**
     * Floating mode: the compose root covers the whole IME window, but the
     * app behind must neither resize nor lose touches. Content insets say
     * "the keyboard occupies nothing"; the touchable region shrinks to the
     * floating panel so all other touches pass through.
     */
    override fun onComputeInsets(outInsets: Insets) {
        super.onComputeInsets(outInsets)
        // The collapsed voice bar wins over floating mode because it is what
        // the screen actually shows — KeyboardScreen branches to it first.
        if (voiceBarShowing()) {
            val decorHeight = window?.window?.decorView?.height ?: return
            val bounds = voiceBarBounds
            // A horizontal bar resting at the bottom lets the app resize to
            // just above it, keeping the text field in view while dictating.
            // A bar dragged anywhere else floats over a full-sized app.
            // Judged from the published rectangle, not the stored bias — the
            // rectangle is always current, the bias is a DataStore round
            // trip behind a drag.
            val docked = bounds != null && !_uiState.value.settings.voiceBar.vertical &&
                bounds.bottom >= decorHeight - voiceBarDockSlopPx()
            val topInset = if (docked && bounds != null) bounds.top else decorHeight
            outInsets.contentTopInsets = topInset
            outInsets.visibleTopInsets = topInset
            // Until the bar has published a rectangle the whole window stays
            // touchable — an empty region would make the bar itself untappable.
            if (bounds != null) {
                outInsets.touchableInsets = Insets.TOUCHABLE_INSETS_REGION
                outInsets.touchableRegion.setEmpty()
                outInsets.touchableRegion.set(bounds)
            }
            return
        }
        if (handwritingFullScreen(_uiState.value)) {
            // Full-screen handwriting: the app keeps its whole height under
            // the see-through canvas. The window takes every touch while the
            // pen-button canvas is catching ink, and only the bar's otherwise
            // — the stylus mode never catches here at all, Android's own
            // stylus window does. Until the bar has published a rectangle
            // the whole window stays touchable, so the bar is never dead.
            val state = _uiState.value
            val decorHeight = window?.window?.decorView?.height ?: return
            outInsets.contentTopInsets = decorHeight
            outInsets.visibleTopInsets = decorHeight
            val catching = handwritingFullScreenManual(state) &&
                state.handwriting.fullScreenInk &&
                state.handwriting.status == HandwritingStatus.READY
            val bar = hwFullScreenBarBounds
            if (catching || bar == null) {
                outInsets.touchableInsets = Insets.TOUCHABLE_INSETS_FRAME
            } else {
                outInsets.touchableInsets = Insets.TOUCHABLE_INSETS_REGION
                outInsets.touchableRegion.setEmpty()
                outInsets.touchableRegion.set(bar)
            }
            return
        }
        if (!floatingNow()) {
            // Docked: the frame's held bands are transparent window over the
            // app, not keyboard. Both insets, so the app resizes to the board
            // and a tap in a band reaches it — the touchable inset follows
            // the visible one by default.
            val headroom = windowHeadroomPx
            if (headroom > 0) {
                outInsets.contentTopInsets += headroom
                outInsets.visibleTopInsets += headroom
            }
            boardTopInWindow = outInsets.visibleTopInsets
            boardTopOnScreen()?.let {
                noteBoardTop(it)
                noteBoardGrowth(it)
                liftFloatingButtons(it)
            }
            // Resize mode's band is the app, dimmed, under a scrim that eats
            // every touch, and a top handle dragged taller than the keyboard
            // entered sits in it: the whole window stays ours (issue #643).
            if (_uiState.value.resize) {
                outInsets.touchableInsets = Insets.TOUCHABLE_INSETS_FRAME
            }
            return
        }
        val decorHeight = window?.window?.decorView?.height ?: return
        outInsets.contentTopInsets = decorHeight
        outInsets.visibleTopInsets = decorHeight
        outInsets.touchableInsets = Insets.TOUCHABLE_INSETS_REGION
        outInsets.touchableRegion.setEmpty()
        floatingPanelBounds?.let { outInsets.touchableRegion.set(it) }
    }

    /**
     * How close to the window's bottom the horizontal bar must sit to count
     * as docked (nav bar plus margin, generously): everything below the
     * gesture area reads as "at the bottom".
     */
    private fun voiceBarDockSlopPx(): Int =
        (VOICE_BAR_DOCK_SLOP_DP * resources.displayMetrics.density).toInt()

    /**
     * Never use the fullscreen (extract) editor while floating or collapsed to
     * the bar — nor over a window with no editor that a pinned keyboard is
     * kept up on, where an extract view would have nothing to extract.
     *
     * Nor on a tablet or an unfolded foldable. The platform's default turns it
     * on for any landscape screen, so an app whose field doesn't opt out
     * (Signal does not) got a blank editor over most of a Pixel Fold. LatinIME
     * and Gboard keep it to phones; so do we. Reads the configuration live
     * rather than [deviceForm]: `super.onConfigurationChanged` re-evaluates
     * this before that flow has caught up with an unfold.
     *
     * And not when the user has turned it off (#883): a phone held sideways
     * then keeps the app in view above the keys.
     */
    override fun onEvaluateFullscreenMode(): Boolean =
        if (floatingNow() || voiceBarShowing() ||
            !_uiState.value.settings.layoutBehavior.landscapeFullscreen ||
            handwritingFullScreen(_uiState.value) ||
            (pinnedNow() && isNullField()) ||
            DeviceForm.of(resources.configuration.smallestScreenWidthDp).isTablet
        ) {
            false
        } else {
            super.onEvaluateFullscreenMode()
        }

    /**
     * The platform sizes the soft-input window here on every show, and on some
     * Android TV builds (Chromecast with Google TV and Skyworth sets, Android
     * 14, Play vitals for 0.5.14) that window has already been detached when
     * `showWindow` gets to it: `Window.setLayout` stores the size, then
     * `WindowManagerGlobal.updateViewLayout` throws "View not attached to
     * window manager" and takes the process down. The size is kept on the
     * window's attributes before the throw and applied when it is added again,
     * so dropping that one dispatch loses nothing.
     */
    override fun onConfigureWindow(win: android.view.Window, isFullscreen: Boolean, isCandidatesOnly: Boolean) {
        try {
            super.onConfigureWindow(win, isFullscreen, isCandidatesOnly)
        } catch (detached: IllegalArgumentException) {
            DebugLog.w("ime", "IME window not attached while configuring it: ${detached.message}")
        }
    }

    /**
     * The focused window has no editor: the framework serves it through a
     * fallback connection whose buffer no app reads, so only key events reach
     * it. Where a pinned keyboard (issue #58) sits most of the time.
     */
    private fun isNullField(): Boolean = currentInputEditorInfo.isNullClass()

    /**
     * A text field in a web page, Chrome's or a WebView's: Chromium declares
     * every one of them, textarea and contenteditable included, as the web
     * edit-text variation.
     */
    private fun isWebEditField(): Boolean {
        val inputType = currentInputEditorInfo?.inputType ?: return false
        return inputType and InputType.TYPE_MASK_CLASS == InputType.TYPE_CLASS_TEXT &&
            inputType and InputType.TYPE_MASK_VARIATION == InputType.TYPE_TEXT_VARIATION_WEB_EDIT_TEXT
    }

    /** A physical keyboard is attached and not folded away. */
    private fun hasHardwareKeyboard(): Boolean {
        val config = resources.configuration
        return config.keyboard == Configuration.KEYBOARD_QWERTY &&
            config.hardKeyboardHidden != Configuration.HARDKEYBOARDHIDDEN_YES
    }

    /**
     * Keep the input view on screen even with a hardware keyboard when the
     * user wants the toolbar-only view — otherwise the platform hides it, and
     * the toolbar (with the keys gated off in Compose) would never show.
     */
    override fun onEvaluateInputViewShown(): Boolean {
        // A physical-keyboard shortcut asked for a tool, so there has to be
        // somewhere to draw it — even though a hardware keyboard would normally
        // mean no input view at all. Dropped again when the tool closes.
        if (forcedInputView) return true
        // A physical keyboard's conversion reading: its candidates are how the
        // language is typed at all, so the strip comes up for them (#419).
        if (candidateInputView) return true
        // A pinned keyboard is wanted whatever the field — or the lack of one.
        if (pinnedNow()) return true
        val toolbar = _uiState.value.settings.toolbarBehavior
        // Nothing to force-show when the toolbar itself is off — that would be a
        // blank sliver (no toolbar, and the keys are gated off too).
        if (toolbar.enabled && toolbar.onlyWithHardwareKeyboard && hasHardwareKeyboard()) {
            return true
        }
        return super.onEvaluateInputViewShown()
    }

    /**
     * A pinned keyboard (issue #58) the user has hidden: it stays down until
     * the system next shows it on its own, which is the user tapping a field.
     * Without this a pinned keyboard could never be closed at all. Cleared in
     * [onStartInputView] — a re-show never runs while suspended, so any start
     * that arrives then is the system's.
     */
    private var pinSuspended = false

    /**
     * What the notification's buttons do, which is what the toolbar's own
     * controls already do.
     *
     * "Show" is a summon ([summonKeyboard]): a show request through the
     * framework rather than [showWindow], so its own bookkeeping stays right,
     * that keeps the keyboard up over a window with no field until the user
     * puts it away. It clears the suspension a user-initiated hide left
     * behind — pressing "Show" is that user changing their mind.
     */
    private val keyboardControlHost = object : KeyboardControls.Host {
        override fun showKeyboard() = summonKeyboard()

        override fun setPinned(pinned: Boolean) {
            onPersistentChange(pinned)
        }

        override fun repostControls() =
            updateKeyboardControls(_uiState.value.settings.persistentKeyboard)

        override fun syncSummonButton() = this@WMKeyboardService.syncSummonButton()
    }

    /** Whether a layout switch is announced to other apps; see [KeyboardAutomation.EVENT_LAYOUT_CHANGED]. */
    @Volatile
    private var announceLayouts = false

    /**
     * What an automation intent acts through: each is the path the keyboard's
     * own control for the same thing takes (the 🌐 key's [onLayoutSelected],
     * the Modes tool, the toolbar), so a change from Tasker or adb is recorded,
     * mirrored and re-bound exactly like one made on the keys. Whether it is
     * allowed at all was settled by the receiver before any of these runs.
     */
    private val automationHost = object : KeyboardAutomation.Host {
        override val settings: KeyboardSettings get() = _uiState.value.settings
        override val layoutId: String get() = _uiState.value.layoutId
        override fun selectLayout(layoutId: String) = onLayoutSelected(layoutId)
        override fun selectMode(modeId: String?) = onModeSelect(modeId)
        override fun showKeyboard() = keyboardControlHost.showKeyboard()
        override fun setPinned(pinned: Boolean) = onPersistentChange(pinned)

        override fun openTool(tool: ToolbarTool): String? {
            if (!isSupportedTool(tool)) return "this build has no ${tool.name} tool"
            val before = _uiState.value.panel
            // onPanelChange toggles, so asking for the open panel would close it.
            if (before.name == tool.name) return null
            runToolFromKey(tool)
            return if (_uiState.value.panel == before) "the ${tool.name} tool cannot open here" else null
        }

        override fun addWord(word: String) = addWordsByHand(listOf(word to false))

        override fun typeText(text: String): String? {
            automationFieldRefusal()?.let { return it }
            insertSnippetText(text, text.length)
            return null
        }

        override fun typeSnippet(name: String): String? {
            automationFieldRefusal()?.let { return it }
            if (!::snippetStore.isInitialized) return "snippets are not loaded yet"
            val items = snippetStore.items()
            val snippet = items.firstOrNull { it.trigger?.equals(name, ignoreCase = true) == true }
                ?: items.firstOrNull { it.label.equals(name, ignoreCase = true) }
                ?: return "no snippet is called \"$name\""
            onSnippetTapped(snippet)
            return null
        }

        override fun startResize() {
            if (!_uiState.value.resize) onResizeToggle()
        }
    }

    /**
     * Why automation may not type into the field in front of the user, or
     * null when it may. A password field is refused outright: another app
     * typing there is the one case where "the user allowed it" is not enough.
     */
    private fun automationFieldRefusal(): String? {
        val info = currentInputEditorInfo
        if (currentInputConnection == null || info == null || info.inputType == InputType.TYPE_NULL) {
            return "no text field is focused"
        }
        if (info.isSecureField()) return "the focused field is a password field"
        return null
    }

    /**
     * Redraws the shade's controls for the current pin state, which decides
     * both the words and whether there is an "Unpin" button.
     */
    private fun updateKeyboardControls(pinned: Boolean) {
        // A post the user does not want is a no-op: the switch is checked
        // inside [WmNotifications.post], not here.
        KeyboardControls.post(this, pinned)
    }

    /** Re-shows spent on the current field; see [reshowPinned]. */
    private var pinReshowStreak = 0

    /** A re-show is already on its way and will judge the state when it runs. */
    private var pinReshowQueued = false

    /** When the latest re-shows ran, in uptime millis; see [pinReshowsRunAway]. */
    private val pinReshowTimes = ArrayDeque<Long>()

    /**
     * Whether re-shows are coming faster than any user could cause, across
     * fields. [pinReshowStreak] is per field, so a loop that swaps between a
     * field and no field resets it every turn and never runs out: a pinned
     * keyboard over the settings app opened its test field, the field closed
     * with the keyboard's next hide, and the re-show opened it again, over
     * and over, until the system's recent apps button froze too (#665).
     * Past [PIN_RESHOW_BURST] in [PIN_RESHOW_BURST_MS], pinning stands down
     * until the user next brings the keyboard up.
     */
    private fun pinReshowsRunAway(): Boolean {
        val now = SystemClock.uptimeMillis()
        while (pinReshowTimes.isNotEmpty() && now - pinReshowTimes.first() > PIN_RESHOW_BURST_MS) {
            pinReshowTimes.removeFirst()
        }
        if (pinReshowTimes.size >= PIN_RESHOW_BURST) {
            DebugLog.w("ime", "pinned keyboard re-shown ${pinReshowTimes.size}x in ${PIN_RESHOW_BURST_MS}ms; standing down")
            pinReshowTimes.clear()
            pinSuspended = true
            return true
        }
        pinReshowTimes.addLast(now)
        return false
    }

    /** The keyboard should be up whether or not any field wants it. */
    private fun pinnedNow(): Boolean =
        (_uiState.value.settings.persistentKeyboard || summonedNow()) && !pinSuspended

    /**
     * When the keyboard was last summoned (issue #374) — the shade's "Show",
     * the floating button, an automation intent — in uptime millis, or 0 for
     * no summon in force. A summon is a one-off pin: the keyboard comes up
     * whether or not a field wants it, and stays up over this app's fieldless
     * windows until the user puts it away.
     */
    private var summonedAt = 0L

    /** The summon got the keyboard on screen; it now lasts until a hide. */
    private var summonHeld = false
        set(value) {
            field = value
            summonHolding.value = value
        }

    /**
     * [summonHeld] as a flow, for the Back callback: from Android 14 Back
     * hides through a private overload, never the [requestHideSelf] override,
     * so a summoned keyboard took the user's Back for an app's hide and
     * [reshowPinned] put it back (#756). See [onPinnedBack].
     */
    private val summonHolding = MutableStateFlow(false)

    /** The floating button's quick menu is open, and Back closes it first (#938). */
    private val floatingMenuOpen = MutableStateFlow(false)

    /** The app a held summon belongs to; switching to another one ends it. */
    private var summonPackage: String? = null

    /** The show requests a summon is still making; see [summonKeyboard]. */
    private var summonJob: Job? = null

    /**
     * A summon is in force: either it has the keyboard on screen, or it is
     * still within the few hundred milliseconds it takes the window it was
     * aimed at to get the focus back.
     */
    private fun summonedNow(): Boolean =
        summonHeld || (summonedAt != 0L && summonPending())

    private fun summonPending(): Boolean =
        summonedAt != 0L && SystemClock.uptimeMillis() - summonedAt < SUMMON_PENDING_MS

    /**
     * Brings the keyboard up whether or not anything on screen wants text
     * (issue #374), the way Hacker's Keyboard's notification does.
     *
     * The request is `SHOW_FORCED`, and that is most of the fix. Pressing the
     * shade's button moves the focus to the system UI and back again, and a
     * window regaining the focus with no text field in it gets the keyboard
     * hidden by Android with a "not always" hide, which a plain show loses to
     * and a forced one survives. The rest is timing: the first request can
     * land while the shade still has the focus, so it is repeated a few times
     * over [SUMMON_PENDING_MS] until the keyboard is up, and the pin machinery
     * ([pinnedNow], [reshowPinned]) puts it back if an app takes it down. The
     * floating button ([FloatingButton]) never moves the focus, so its first
     * request is normally the one that lands.
     *
     * Never over the lock screen, the same rule pinning keeps.
     */
    private fun summonKeyboard() {
        if (isDeviceLocked()) return
        pinSuspended = false
        pinReshowStreak = 0
        summonedAt = SystemClock.uptimeMillis()
        summonHeld = false
        summonPackage = null
        summonJob?.cancel()
        summonJob = serviceScope.launch {
            for (wait in SUMMON_RETRY_DELAYS_MS) {
                delay(wait)
                if (!summonedNow() || summonHeld || isInputViewShown) return@launch
                forcedShowUp = true
                requestShowSelf(summonShowFlags())
            }
        }
    }

    /**
     * Show flags for a request a summon makes. Forced, so the "hide not
     * always" Android sends a window with no field leaves it alone; see
     * [summonKeyboard]. The flag is deprecated from API 33 for the reason it
     * is wanted here: it keeps the keyboard up after the window that asked
     * for it has stopped wanting it.
     */
    @Suppress("DEPRECATION")
    private fun summonShowFlags(): Int = InputMethodManager.SHOW_FORCED

    /**
     * A forced show of ours is what keeps the window up. Android holds on to
     * "forced" until something hides the keyboard outright, so it can outlive
     * the summon that asked for it; see [dropStaleForcedShow]. Cleared when the
     * window goes.
     */
    private var forcedShowUp = false

    /**
     * Takes down a keyboard that is only still up because a summon forced it,
     * now that the summon is over and the window in front has no field. Without
     * this, leaving the summoned app for another fieldless screen (the home
     * screen, a game) would carry the keyboard along: the "not always" hide
     * Android sends there is exactly the one a forced show ignores. Posted, so
     * it judges the state after the focus change has settled, and through the
     * base class so it is not taken for the user's own hide.
     */
    private fun dropStaleForcedShow(attribute: EditorInfo?) {
        if (!forcedShowUp || pinnedNow() || !attribute.isNullClass()) return
        serviceScope.launch {
            delay(PIN_RESHOW_DELAY_MS)
            if (forcedShowUp && !pinnedNow() && isInputViewShown && isNullField()) {
                hideWithoutSuspending()
            }
        }
    }

    private fun hideWithoutSuspending() = super.requestHideSelf(0)

    /** Ends a summon: the user put the keyboard away, or a field took it over. */
    private fun clearSummon() {
        summonedAt = 0L
        summonHeld = false
        summonPackage = null
        summonJob?.cancel()
        summonJob = null
    }

    /**
     * The floating button (#755), created the first time it is wanted. The
     * delegate is kept so [onDestroy] can tell whether there is one to take
     * down without making one.
     */
    private val floatingButtonDelegate = lazy {
        FloatingButton(
            context = this,
            host = object : FloatingButton.Host {
                override fun runFloatingAction(action: FloatingAction) = onFloatingAction(action)

                override fun floatingButtonMoved(xFraction: Float, yFraction: Float) {
                    serviceScope.launch { settingsRepository.setSummonButtonPosition(xFraction, yFraction) }
                }

                override fun floatingMenuChanged(open: Boolean) {
                    floatingMenuOpen.value = open
                }

                // Over the keys (#926), the button's windows are panels of this one.
                override fun keyboardWindowToken(): IBinder? =
                    window?.window?.decorView?.windowToken ?: window?.window?.attributes?.token

                override fun keyboardWindowOrigin(): IntArray? =
                    window?.window?.decorView?.takeIf { it.isAttachedToWindow }?.let { decor ->
                        IntArray(2).also { decor.getLocationOnScreen(it) }
                    }

                override fun floatingButtonDismissed() {
                    floatingButtonDismissed = true
                    syncSummonButton()
                    val toast = if (windowOnScreen) {
                        R.string.ime_floating_button_hidden_open_toast
                    } else {
                        R.string.ime_floating_button_hidden_toast
                    }
                    Toast.makeText(this@WMKeyboardService, toast, Toast.LENGTH_SHORT).show()
                }
            },
        )
    }
    private val floatingButton by floatingButtonDelegate

    /**
     * A drop on the target, or the Hide action, put the button away until the
     * keyboard next opens or closes, whichever comes first: reset on every
     * change of the window's visibility.
     */
    private var floatingButtonDismissed = false

    /**
     * Puts the floating button (#374, #697, #755) on screen or takes it off:
     * on while its switch is on and the overlay grant is held, and, as the
     * page sets it, not while the keyboard is up or the screen is landscape.
     * The lock screen needs no check of its own: Android draws it over every
     * app overlay.
     *
     * Overlay windows sit below the keyboard's, so a docked keyboard lifts the
     * button clear of itself ([FloatingButton.keepAbove]), and the keyboard
     * action turns into the way to put the keyboard away: a field-less screen,
     * where it was summoned, often has no other.
     */
    private fun syncSummonButton(setting: SummonButtonSettings = _uiState.value.settings.summonButton) {
        val canDraw = Settings.canDrawOverlays(this)
        val landscape = resources.configuration.orientation == Configuration.ORIENTATION_LANDSCAPE
        val wanted = setting.enabled && !floatingButtonDismissed && canDraw &&
            (setting.whileTyping || !windowOnScreen) &&
            !(setting.hideInLandscape && landscape)
        if (wanted) {
            floatingButton.update(setting, keyboardUp = windowOnScreen)
            floatingButton.keepAbove(if (windowOnScreen) boardTopOnScreen() else null)
            floatingButton.show(setting.xFraction, setting.yFraction)
        } else if (floatingButtonDelegate.isInitialized()) {
            floatingButton.hide()
        }
    }

    /** The docked keyboard's top moved: lift the floating button clear of it. */
    private fun liftFloatingButtons(topPx: Int?) {
        if (floatingButtonDelegate.isInitialized()) floatingButton.keepAbove(topPx)
    }

    /** One of the floating button's gestures, or a quick menu slot (#755). */
    private fun onFloatingAction(action: FloatingAction) {
        when (action) {
            FloatingAction.Keyboard -> onSummonButtonTap()
            FloatingAction.AskAi -> askAiAboutScreen()
            FloatingAction.LookUp -> lookUpOnScreen()
            is FloatingAction.Tool -> runToolFromFloatingButton(action.tool)
            is FloatingAction.App -> openAppFromFloatingButton(action.packageName)
            // The button answers these itself.
            FloatingAction.Menu, FloatingAction.Hide, FloatingAction.None, is FloatingAction.Category -> Unit
        }
    }

    /**
     * A floating button slot that opens an app (#922): its launcher entry,
     * started the way the app launcher tool starts one. An app that has gone
     * since it was picked says so rather than doing nothing.
     */
    private fun openAppFromFloatingButton(packageName: String) {
        val intent = launcherIntentFor(packageName)
        val foreground = currentInputEditorInfo?.packageName.takeIf { windowOnScreen }
        if (intent == null || !startLauncherIntent(intent, LauncherOpenMode.NORMAL, foreground)) {
            Toast.makeText(this, R.string.ime_floating_app_missing, Toast.LENGTH_SHORT).show()
        }
    }

    /** The keyboard action: up when it is down, down when it is up (#697). */
    private fun onSummonButtonTap() {
        if (windowOnScreen) requestHideSelf(0) else summonKeyboard()
    }

    /**
     * A tool fired from the floating button (#755): what a key bound to it
     * does, once the keyboard is up. Most tools are a panel of the keyboard,
     * so a press while it is down summons it first and the tool runs as it
     * arrives ([onScreenAgain]); the voice tool from the button is the one
     * that was asked for, and it is a panel like the rest.
     */
    private fun runToolFromFloatingButton(tool: ToolbarTool) {
        if (!isSupportedTool(tool)) return
        if (windowOnScreen || tool in FloatingToolsWithoutKeyboard) {
            floatingPendingTool = null
            runToolFromKey(tool)
            return
        }
        floatingPendingTool = tool
        floatingPendingAt = SystemClock.uptimeMillis()
        summonKeyboard()
    }

    /** A tool waiting for the keyboard a floating button press summoned; see [runToolFromFloatingButton]. */
    private var floatingPendingTool: ToolbarTool? = null
    private var floatingPendingAt = 0L

    /**
     * The floating AI button's tap (#697): reads the app on screen, when the
     * screen reading service is on, and opens the Ask AI sheet with it. Read
     * here and now, before the sheet opens, because once it is up the screen
     * in front is the sheet. The text travels as an extra; the service caps
     * it well under what an intent can carry.
     */
    private fun askAiAboutScreen() {
        val screen = runCatching { ScreenContextService.current?.read() }.getOrNull()
        val intent = Intent()
            .setClassName(packageName, AskAiLaunch.ACTIVITY)
            // A fresh sheet every press: a sheet still open from the last one
            // would be about the last screen.
            .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK)
            .putExtra(AskAiLaunch.EXTRA_FROM_BUTTON, true)
        if (screen != null && screen.text.isNotBlank()) {
            intent.putExtra(AskAiLaunch.EXTRA_SCREEN_TEXT, screen.text)
                .putExtra(AskAiLaunch.EXTRA_SCREEN_PACKAGE, screen.packageName)
        }
        runCatching { startActivity(intent) }
            .onFailure { DebugLog.w("ime", "ask ai sheet failed to open: ${it.message}") }
    }

    /**
     * The floating button's Look up (#765): waits for a tap on a word, reads
     * the text under it through the screen reading service, and opens the
     * Look up card with it. The overlay that takes the tap is gone before the
     * read, so the read sees the app. With the service off, the card opens
     * on its own to say how to turn it on.
     */
    private fun lookUpOnScreen() {
        if (ScreenContextService.current == null) {
            openLookupCard { it.putExtra(com.wasimaster.wmkeyboard.ime.lookup.LookupLaunch.EXTRA_SCREEN_MISSING, true) }
            return
        }
        floatingButton.pickPoint { x, y ->
            serviceScope.launch {
                val tap = withContext(Dispatchers.IO) {
                    runCatching { ScreenContextService.current?.textAt(x, y) }.getOrNull()
                }
                if (tap == null) {
                    Toast.makeText(this@WMKeyboardService, R.string.ime_floating_pick_nothing, Toast.LENGTH_SHORT).show()
                    return@launch
                }
                openLookupCard { intent ->
                    val launch = com.wasimaster.wmkeyboard.ime.lookup.LookupLaunch
                    intent.putExtra(launch.EXTRA_TEXT, tap.text)
                        .putExtra(launch.EXTRA_OFFSET, tap.offset)
                        .putExtra(launch.EXTRA_PACKAGE, tap.packageName)
                        .putExtra(launch.EXTRA_BOUNDS, tap.bounds)
                        .putExtra(launch.EXTRA_RECTS_FROM, tap.rectsFrom)
                    tap.rects?.let { intent.putExtra(launch.EXTRA_RECTS, it) }
                }
            }
        }
    }

    /** Starts the Look up card afresh, [extras] filling in what it is about. */
    private fun openLookupCard(extras: (Intent) -> Unit) {
        val intent = Intent()
            .setClassName(packageName, com.wasimaster.wmkeyboard.ime.lookup.LookupLaunch.ACTIVITY)
            // A fresh card every time: one still open would be about the last word.
            .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK)
        extras(intent)
        runCatching { startActivity(intent) }
            .onFailure { DebugLog.w("ime", "look up card failed to open: ${it.message}") }
    }

    /**
     * Every hide the keyboard asks for itself is the user's: the hide tool,
     * the toolbar swipe, Back. A pinned keyboard honours those and stays down
     * until the system next shows it. The hides an *app* asks for never come
     * this way, and those are the ones pinning exists to override.
     */
    override fun requestHideSelf(flags: Int) {
        if (_uiState.value.settings.persistentKeyboard) pinSuspended = true
        clearSummon()
        super.requestHideSelf(flags)
    }

    /**
     * Back with nothing of the keyboard's open, while pinned (#665). From
     * Android 14 the framework's own Back handling hides through a private
     * `requestHideSelf(flags, reason)` overload, never the public one
     * overridden above, so a pinned keyboard read the user's Back as an app
     * hiding it and put itself straight back: the keyboard flashed, and a
     * browser's address bar could never be left. Hiding through the override
     * suspends pinning the way the hide tool does.
     */
    private fun onPinnedBack() {
        requestHideSelf(0)
    }

    /**
     * Puts a pinned keyboard back after something other than the user took it
     * down: a field losing focus, an app hiding the IME, a switch to a window
     * with no editor at all. Goes through the framework's own show request
     * rather than showWindow, so its visibility bookkeeping stays right.
     * Posted rather than inline, since the callers run inside the framework's
     * hide and start sequences, and one delayed request coalesces the burst a
     * window switch produces. Bounded: at most [PIN_RESHOW_LIMIT] per field,
     * so an app that hides the keyboard every time it appears gets a few
     * flashes and then wins until the next field. Never over the lock screen:
     * the clipboard and the tools must not follow the user there.
     */
    private fun reshowPinned() {
        if (!pinnedNow() || pinReshowQueued || pinReshowStreak >= PIN_RESHOW_LIMIT) return
        if (isDeviceLocked()) return
        pinReshowQueued = true
        serviceScope.launch {
            delay(PIN_RESHOW_DELAY_MS)
            pinReshowQueued = false
            if (!pinnedNow() || isInputViewShown || isDeviceLocked()) return@launch
            if (pinReshowsRunAway()) return@launch
            pinReshowStreak++
            if (summonedNow()) {
                forcedShowUp = true
                requestShowSelf(summonShowFlags())
            } else {
                requestShowSelf(0)
            }
        }
    }

    /**
     * The screen size the keyboard is drawing on, as a flow so it can join the
     * settings pipeline rather than being read at each use site.
     *
     * Lives here rather than in [SettingsRepository] because the repository is
     * constructed ad hoc in a dozen places with no shared lifecycle — a
     * ComponentCallbacks registered there would leak one per construction — and
     * because its preference mapping deliberately touches no Context so it can
     * run off the main thread.
     *
     * Lazy, and it must stay lazy: a service is constructed before
     * attachBaseContext runs, so a plain initialiser here reads `resources`
     * through a ContextWrapper whose base is still null and takes the whole
     * keyboard down with an NPE in <init> — the IME never starts at all. Every
     * reader below runs after onCreate, so the first touch is always safe.
     */
    private val deviceForm by lazy {
        MutableStateFlow(DeviceForm.of(resources.configuration.smallestScreenWidthDp))
    }

    /** Docking or undocking a hardware keyboard flips the toolbar-only view. */
    override fun onConfigurationChanged(newConfig: Configuration) {
        super.onConfigurationChanged(newConfig)
        refreshHardwareKeyboardState()
        // Folding, unfolding, or moving to another display. Rotation never
        // reaches here in a way that matters: smallestScreenWidthDp is the
        // smaller dimension either way up, which is the whole point of reading
        // it rather than the current width.
        deviceForm.value = DeviceForm.of(newConfig.smallestScreenWidthDp)
        // Any configuration change can swap the ScreenVariant out from under
        // an open resize session, and its preview would then belong to the
        // wrong variant. Drop the session; nothing was persisted.
        if (_uiState.value.resize) {
            _uiState.update { it.copy(resize = false) }
        }
        // Floating is per orientation (#584): turning into a docked one leaves
        // the old panel's rectangle as the touchable region until it is dropped.
        if (!floatingNow() && floatingPanelBounds != null) {
            floatingPanelBounds = null
            window?.window?.decorView?.requestLayout()
        }
        // A rotation or a fold changes the room the floating button has, and
        // may be the landscape it stays out of.
        if (floatingButtonDelegate.isInitialized()) floatingButton.relayout()
        syncSummonButton()
    }

    /** Push the current hardware-keyboard presence into the UI state. */
    private fun refreshHardwareKeyboardState() {
        val present = hasHardwareKeyboard()
        if (present != _uiState.value.hardwareKeyboardPresent) {
            _uiState.update { it.copy(hardwareKeyboardPresent = present) }
        }
    }

    /**
     * Clipboard data is credential-protected and must not be exposed through
     * the IME while either direct boot or the keyguard is active.
     */
    private fun isClipboardAccessible(): Boolean =
        userUnlocked && !isDeviceLocked()

    /**
     * True while the device lock screen (keyguard) is showing — secure or
     * swipe-only. Read on each field start to drive the "hide toolbar &
     * clipboard on lock screen" privacy setting.
     */
    private fun isDeviceLocked(): Boolean =
        (getSystemService(Context.KEYGUARD_SERVICE) as? KeyguardManager)?.isKeyguardLocked == true

    /**
     * The keyguard went away under a field that started while it was up
     * (issue #492). Turning the screen on restarts the field the keyboard was
     * left in, often before the unlock has finished, and the app getting its
     * window back starts nothing new. So [KeyboardUiState.deviceLocked] stayed
     * true for the rest of the session: with "hide on the lock screen" on, the
     * strip and its tools never came back, and the clipboard stayed empty.
     */
    private val keyguardReceiver = object : BroadcastReceiver() {
        override fun onReceive(context: Context?, intent: Intent?) {
            if (intent?.action == Intent.ACTION_USER_PRESENT) onKeyguardGone()
        }
    }

    /** For the rest of the process's life, like [registerPackageChangeReceiver]. */
    private fun registerKeyguardReceiver() {
        ContextCompat.registerReceiver(
            this, keyguardReceiver, IntentFilter(Intent.ACTION_USER_PRESENT),
            ContextCompat.RECEIVER_NOT_EXPORTED,
        )
    }

    private var keyguardWatchJob: Job? = null

    /**
     * Re-reads the keyguard while a field the board shows started under it
     * (#793). Unlocking with a fingerprint from a dark screen turns the screen
     * on and dismisses the keyguard in one go: the field restart lands while
     * [KeyguardManager.isKeyguardLocked] still says locked, and USER_PRESENT
     * arrives either before that restart or while the keyguard is still
     * animating away, so [onKeyguardGone] finds nothing to undo or nothing
     * gone. No broadcast follows, and the strip stayed hidden. Polled only
     * while the window is on screen; [onWindowShown] covers the way back.
     */
    private fun watchKeyguard() {
        if (keyguardWatchJob?.isActive == true) return
        keyguardWatchJob = serviceScope.launch {
            while (_uiState.value.deviceLocked && windowOnScreen) {
                delay(KEYGUARD_POLL_MS)
                if (!isDeviceLocked()) {
                    onKeyguardGone()
                    break
                }
            }
        }
    }

    /** Puts back what the field start withheld for the lock screen, once it is gone. */
    private fun onKeyguardGone() {
        if (!_uiState.value.deviceLocked) return
        if (isDeviceLocked()) {
            // Still going away (USER_PRESENT beats the keyguard's own exit).
            watchKeyguard()
            return
        }
        _uiState.update {
            it.copy(
                deviceLocked = false,
                clipboardItems = if (userUnlocked) clipboardStore.items() else it.clipboardItems,
            )
        }
        syncKdeConnect()
        syncHomeAssistant()
    }

    override fun onStartInput(attribute: EditorInfo?, restarting: Boolean) {
        super.onStartInput(attribute, restarting)
        inputStarts++
        // Runs for every field even while the soft view stays hidden
        // (hardware-keyboard typing), where onStartInputView never fires:
        // the previous field's cached selection and half-typed word must not
        // leak into this one. `restarting` (same editor, e.g. a programmatic
        // text change) keeps the word being typed — web views restart input
        // liberally and dropping it there would chop words mid-typing.
        expectedSelStart = attribute?.initialSelStart ?: -1
        expectedSelEnd = attribute?.initialSelEnd ?: -1
        trackCaretAtFieldStart(expectedSelStart, expectedSelEnd)
        // A drag still holding the magnifier up follows the field onto its new
        // connection; the one it was reading from is gone.
        if (caretMagnifier.active) {
            caretMagnifier.rebind(
                currentInputConnection,
                expectedSelStart,
                expectedSelEnd,
                hidesTypedText(attribute?.inputType ?: 0),
            )
        }
        // Whatever word was being followed, its field is gone or its text has
        // changed under it; nothing about it can be trusted from here.
        revision = null
        // An action the last field asked for is not this one's. A field that
        // speaks the protocol is asked for its own: the launcher answers the
        // support probe with the action, and the one it may have sent while
        // its connection was being made arrived before this start and is gone.
        appEnterAction = null
        if (attribute?.privateImeOptions?.contains(PRIVATE_OPTION_APP_IME_ACTION) == true) {
            currentInputConnection?.performPrivateCommand(PRIVATE_COMMAND_ACTION_PROBE, null)
        }
        if (!restarting) {
            // The conversions backspace can re-pick (#711) were written into
            // the field that just went.
            recentConversions.clear()
            conversionDeleted = ""
            conversionRepick = null
            // Chips withdrawn because focus moved here were not tapped.
            inlineFieldStartedAt = SystemClock.uptimeMillis()
            // The rewrites the bar remembered were about the old field, and a
            // conversion still running was for it too.
            macroUndo.clear()
            macroJob?.cancel()
            macroSeq++
            // And the words Learn from text read: they were this field's.
            if (_uiState.value.panel == PanelMode.LEARN_FROM_TEXT) {
                learnJob?.cancel()
                _uiState.update { it.copy(panel = PanelMode.NONE, learnFromText = null, panelFocus = null) }
            }
            // And so were the find panel's matches.
            if (_uiState.value.panel == PanelMode.FIND_REPLACE) {
                findJob?.cancel()
                _uiState.update { it.copy(panel = PanelMode.NONE, findReplace = null, panelFocus = null) }
            }
        }
        if (restarting) {
            // Same field, new connection: the composing span went with the old
            // one. See [reattachComposing] — and note this runs on its own when
            // the soft view is hidden (hardware-keyboard typing), where
            // onStartInputView never fires to do it.
            reattachComposing(expectedSelStart, expectedSelEnd)
        } else {
            composing = StringBuilder()
            previousWord = null
            invalidateRecentWords()
            lastGestureWord = null
            lastRevertible = null
            clearSwapOffer()
            // Someone else's field, someone else's text: the chip's word is
            // not behind this caret and must never be searched for there.
            clearUndoChip()
            clearCaretWord()
            pendingAutoSpace = false
            pendingPunctuationSpace = false
            pendingWordSpace = false
            glueNextWord = false
            setNoSpaceArmed(false)
            // The last field's text is behind us and nobody is going back to
            // edit it, so the unknown words still waiting in it have settled.
            // This is also how a message field that was *sent* gets counted
            // when the app restarts input instead of clearing the text. No
            // correction verification: the editor answering reads is this new
            // field, and its text says nothing about the old one's.
            flushLearningBuffer(verifyCorrections = false)
            // A different field is a different run of typing, and the blocks an
            // undo puts on a correction are scoped to the run that earned them.
            // What should outlive it is in the persisted pair counts by now,
            // an undo still waiting included: the user left with it standing.
            settlePendingUndo(kept = true)
            correctionStats.endFieldSession()
            declinedSpots.clear()
            chipOpenRestore = null
            clearLearnOffer()
            clearCorrectionOffer()
            // A genuinely different field. Whatever a plugin was collecting
            // belonged to the last one, and the keys belong to this one.
            stopPlugins()
            // A new field gets its own re-show budget (see reshowPinned).
            pinReshowStreak = 0
            // And its own typing speed (#796), from its own first words.
            stopLiveWpm()
            // And no recent words (#787): those belonged to the last field.
            clearRecentBar()
            // A summon belongs to the app it was made in. While it is still
            // settling the focus is moving between the shade and that app, so
            // the latest start is the app; once it holds the keyboard, a start
            // in another app is the user leaving, and the keyboard goes back
            // to coming up for fields only.
            val pkg = attribute?.packageName
            if (summonHeld && !summonPending()) {
                if (pkg != null && summonPackage != null && pkg != summonPackage) clearSummon()
            } else if (summonedAt != 0L) {
                summonPackage = pkg
            }
        }
        // The toolbar's incognito badge describes the field that has focus
        // now. It used to be worked out in onStartInputView alone, so a start
        // that never drew the keys (a window with no field, a pinned or
        // summoned keyboard, the round trip through another keyboard) left
        // the last private tab's badge standing on the bar until some other
        // field brought the keys up (#665). Same answer startInputView gives.
        val fieldIncognito = fieldWantsIncognito(baseSettings ?: _uiState.value.settings, attribute)
        if (_uiState.value.fieldIncognito != fieldIncognito) {
            // Which app and flag turned the badge on, for the next report
            // of one nobody asked for (#665).
            if (fieldIncognito) {
                DebugLog.i(
                    "ime",
                    "field asks for incognito: ${attribute?.packageName} imeOptions " +
                        "0x${Integer.toHexString(attribute?.imeOptions ?: 0)} private ${attribute?.privateImeOptions}",
                )
            }
            _uiState.update { it.copy(fieldIncognito = fieldIncognito) }
        }
        // The same for what kind of field it is (#845). With a physical
        // keyboard the keys stay hidden and startInputView never runs, so
        // these described the last field the keys were shown in: a password
        // field reached that way was composed, autocorrected on Enter,
        // learned and counted, and a plain field after a password or email
        // one got no typing help. The hardware gate, learning, statistics,
        // the recent-word bar and the live speed all read them. The layouts
        // for the kind wait for the keys to come up, where startInputView
        // works the rest out.
        val secure = attribute.isSecureField()
        val kind = attribute.fieldKind()
        val nullField = attribute.isNullClass()
        val noSuggestions = attribute.suppressesSuggestions(
            (baseSettings ?: _uiState.value.settings).suggestionSources.inAllFields,
        )
        _uiState.value.let { s ->
            if (s.secureField != secure || s.fieldKind != kind || s.nullField != nullField ||
                s.fieldNoSuggestions != noSuggestions
            ) {
                _uiState.update {
                    it.copy(secureField = secure, fieldKind = kind, nullField = nullField, fieldNoSuggestions = noSuggestions)
                }
            }
        }
        // A forced show that outlived its summon does not get to follow the
        // user onto a screen with no field.
        dropStaleForcedShow(attribute)
        // Runs for windows with no editor too, which is where a pinned
        // keyboard most needs putting back: the system never shows it there
        // on its own.
        reshowPinned()
    }

    /**
     * An app telling the keyboard what Enter should be in its field (#908),
     * see [appEnterAction]. The key redraws at once and fires that action
     * from then on, IME_FLAG_NO_ENTER_ACTION or not. An id that is no
     * standard action is ignored, so the key never draws one thing and
     * fires another.
     */
    override fun onAppPrivateCommand(action: String?, data: Bundle?) {
        super.onAppPrivateCommand(action, data)
        if (action != APP_COMMAND_IME_ACTION || data == null) return
        val id = data.getInt(APP_COMMAND_IME_ACTION, EditorInfo.IME_ACTION_UNSPECIFIED)
        val face = standardEnterAction(id)
        if (face == EnterAction.DEFAULT) return
        appEnterAction = id
        _uiState.update { it.copy(enterAction = face, enterActionLabel = null) }
    }

    override fun onStartInputView(info: EditorInfo?, restarting: Boolean) =
        trace(ImeTrace.START_INPUT_VIEW) { startInputView(info, restarting) }

    private fun startInputView(info: EditorInfo?, restarting: Boolean) {
        super.onStartInputView(info, restarting)
        // A tap in another field, or before the keyboard went away, is not the
        // tap before this one.
        multitap.end()
        // The keyboard is up, by the system's hand or ours; a hide that
        // suspended pinning has run its course.
        pinSuspended = false
        // A real text field has the keyboard now, and the ordinary rules for
        // fields apply to it again: a summon was for windows without one.
        if (summonedAt != 0L && !info.isNullClass()) clearSummon()
        // The app's tool shortcut screen (#970) names a tool in its field's
        // private options: the panel opens once this start has settled.
        if (!restarting && info?.packageName == packageName) {
            KeyboardAutomation.toolFromPrivateOptions(info.privateImeOptions)?.let { tool ->
                Handler(Looper.getMainLooper()).post { automationHost.openTool(tool) }
            }
        }
        // Set before the lifecycle is resumed: a panel that reacts to ON_RESUME
        // (the media one re-checks notification access there) would otherwise
        // ask about a keyboard this flag still calls hidden.
        keyboardVisible = true
        // Back on screen inside the idle window: whatever is still loaded stays.
        idleReleaseJob?.cancel()
        idleReleaseJob = null
        // And the process it is drawing in.
        gpuRecycleJob?.cancel()
        gpuRecycleJob = null
        onScreenAgain()
        lifecycleOwner.onResume()
        // Starts the media-session listener the toolbar's auto-pin needs, and
        // catches music that began while the keyboard was away.
        syncMediaTracking()
        syncKdeConnect()
        syncHomeAssistant()
        // Ready before the first press of the mic, not after it (#305).
        refreshVoiceBias()
        refreshHardwareKeyboardState()
        // The battery level is read here rather than subscribed to: this is the
        // moment it can start mattering, and a keyboard that wakes on every
        // percentage point to decide whether to save power is self-defeating.
        powerSaver.refresh()
        // Same reasoning for the network: the callback may have fired while
        // this process was gone, and this is the moment the answer starts
        // mattering again.
        networkWatcher.refresh()
        // A rotating background moves on at the start of a session and never
        // during one: a photo changing under the keys while somebody is typing
        // reads as a glitch rather than a feature, and an in-session timer
        // would be a leak waiting to happen. The swap itself is a local file
        // read and one preference write, so it costs nothing here.
        maybeRotateBackground()
        // Same rule, same moment, for an auto theme half that selects at random.
        maybeShuffleTheme()
        // And for the app's own colours: read as the keyboard comes up in it,
        // never changed under the keys mid-session.
        AppColors.onApp(
            context = this,
            scope = serviceScope,
            packageName = info?.packageName,
            enabled = _uiState.value.settings.appColors.enabled,
        )
        // Covers the OEMs where `zen_mode` is unreadable and the observer never
        // fires — see refreshDndState.
        refreshDndState()
        // Shown again over the same input (hidden with Back, then the field
        // tapped): the EditorInfo is the one the field started with, and its
        // initial selection is the caret from before anything was typed — 0
        // in a chat box that started empty. The editor kept reporting the
        // caret while the keys were down, so the cached one is the live one.
        // Taken from the stale EditorInfo, the resume below read the word
        // behind the real caret and placed it at the old one (#718). A cache
        // some edit invalidated stays unknown (-1) rather than going stale.
        val reshown = inputStarts == inputStartsAtLastView
        inputStartsAtLastView = inputStarts
        if (!reshown) {
            expectedSelStart = info?.initialSelStart ?: -1
            expectedSelEnd = info?.initialSelEnd ?: -1
        }
        trackCaretAtFieldStart(expectedSelStart, expectedSelEnd)
        // A job debounced against the previous field must not land its strip
        // (or commit resolution) on this one — the secure-field gates in
        // refreshSuggestions return before they ever cancel.
        suggestionJob?.cancel()
        smartJob?.cancel()
        clearAiSuggest()
        gestureJob?.cancel()
        commitResolution = null
        // `restarting` is the same field reporting itself again — a programmatic
        // text change, or a web view resetting its connection, both of which
        // happen mid-word and neither of which the user did. The word being
        // typed is still in the field, so blanking the buffer here split it in
        // two: the strip lost the prefix and the next space autocorrected the
        // tail on its own ("keyboard" typed through a restart committing as
        // "keybcard"). The restart does end the editor's composing span though,
        // so the buffer has to be re-attached to a fresh one or dropped — kept
        // with no span behind it, the next setComposingText *inserts* it at the
        // caret and the half-typed word appears twice.
        revision = null
        if (restarting) {
            reattachComposing(info?.initialSelStart ?: -1, info?.initialSelEnd ?: -1)
        } else {
            // A buffer still here is a word the caret re-armed while the keys
            // were down: the hide's own finishComposingText echoes back after
            // onFinishInputView, and that echo resumes the word behind the
            // caret like any other. Dropped without its region, the next letter
            // replaced the whole word and a backspace took the character in
            // front of it instead (#718). Finishing never changes the text, and
            // the entry read below re-arms the word properly.
            if (composing.isNotEmpty()) currentInputConnection?.finishComposingText()
            composing = StringBuilder()
            previousWord = null
            invalidateRecentWords()
            lastGestureWord = null
            lastRevertible = null
            clearSwapOffer()
            // Someone else's field, someone else's text: the chip's word is
            // not behind this caret and must never be searched for there.
            clearUndoChip()
            clearCaretWord()
            // The last field's language mix must not color this one; the
            // entry re-read below re-seeds it from this field's own words.
            suggestionEngine?.clearFieldContext()
            // A field found in Zawgyi was that field; this one is read afresh.
            zawgyiField = false
            zawgyiFieldOffered = false
            clearZawgyiOffer()
        }
        // The Fancy tool's automatic pass, run here rather than when the
        // keyboard closed: this is the first moment the work is safe again (the
        // buffer above is settled, the mic is released, no panel is open), and
        // the user sees the same thing either way — the keyboard comes back
        // typing plainly. A restart is the same field reporting itself, so the
        // request waits for a real new session instead of ending this one.
        if (fancyToolAutoOffPending && !restarting) {
            fancyToolAutoOffPending = false
            val state = _uiState.value
            if (state.language.id == FancyStyles.LANG_ID) turnFancyOff(state, quiet = true)
        }
        smartMutedAfter = null
        stickerMutedAfter = null
        patternMutedAfter = null
        // The digits the strip was completing were in the old field.
        numberRun = null
        numberRunPending = false
        // A new field is a fresh audience for the intent chips; a restart is
        // the same field talking, where a retired hint stays retired.
        if (!restarting) {
            intentChipsRetired.clear()
            contactChipsRetired.clear()
            repeatChipsRetired.clear()
            aiSuggestSuppressed = false
        }
        if (!restarting) {
            // Same for the vocabulary nudges — unless the cooldown is a day,
            // in which case today's already-shown words carry over.
            vocabRetired.clear()
            if (_uiState.value.settings.vocabulary.cooldown == VocabCooldown.ONCE_PER_DAY) {
                vocabRetired += vocabPrefs.nudgedOn(vocabToday())
            }
            if (_uiState.value.vocabDaily != null) _uiState.update { it.copy(vocabDaily = null) }
        }
        // A chip offering to rewrite a span of the last field has no business
        // being up over this one.
        clearSnippetOffer()
        // The settings app edits snippets in the same file this reads, so a
        // pattern added there has to reach the keyboard without waiting for
        // the snippet panel to be opened.
        reloadSnippetsIfChanged()
        resetHardwareKeyState()
        // Covers the permission being granted after the setting was on.
        if (_uiState.value.settings.suggestionSources.contacts && contactNames.isEmpty) {
            loadContactNames()
        }
        if (_uiState.value.settings.suggestionSources.contactEmails && contactEmails.isEmpty) {
            loadContactEmails()
        }
        if (_uiState.value.settings.smartChips.contacts && contactPhones.isEmpty) {
            loadContactPhones()
        }
        // A dictionary downloaded (or deleted) in Settings goes live here, on
        // the next field focus — token-guarded, so this is a cheap no-op when
        // nothing on disk changed.
        serviceScope.launch { reloadDownloadedDictionaries() }
        // Same for vocabulary packs and the learning record the settings app
        // writes; and the first field of the day may get the word of the day.
        serviceScope.launch {
            reloadVocabIndex()
            if (!restarting) maybeOfferWordOfTheDay()
        }
        // A CJK dictionary pack finished (or was deleted) in Settings since the
        // tables were last parsed, or a list was imported for a language that
        // converts: reload so it goes live on this focus. The token compare is
        // a few file checks — cheap enough per focus, and the re-parse only
        // runs for a table whose sources actually changed.
        if (loadedCjkPackToken != cjkTablesToken()) {
            serviceScope.launch { loadCjkConversionTables() }
        }
        // Mozc picked but not open yet: its library or dictionary may have
        // landed since (a download, an offline import), or the phone was
        // unlocked. Opening runs in the background; asking again is cheap.
        if (MozcEngine.enabled && !MozcRuntime.ready) MozcRuntime.prepare(this)
        // Likewise an input method imported in Settings, or a layout bound to
        // one switched on there.
        reloadImportedInputMethods()
        hwJob?.cancel()
        hwGeneration++
        val secure = info.isSecureField()
        val fieldKind = info.fieldKind()
        val nullField = info.isNullClass()
        // Keyboard-mode resolution: a manual pick from the Modes tool lives as
        // long as the user stays in the same app, unless they asked for it to
        // last until they change it. Clearing on the next app was right for a
        // mode picked in passing and wrong for one picked deliberately, and the
        // keyboard could not tell the two apart.
        val pkg = info?.packageName
        val manualSticks = _uiState.value.settings.rows.manualModeDuration ==
            ManualModeDuration.UNTIL_CHANGED
        if (pkg != null && pkg != currentPackage && !manualSticks && manualModeId != null) {
            manualModeId = null
            saveManualMode(null)
        }
        // A pick still waiting to be stored belongs to the app it was made in:
        // per-app memory reads a different id in the next app, which the pending
        // one would otherwise outrank for as long as the write took to land.
        if (pkg != null && pkg != currentPackage) pendingLayoutId = null
        if (pkg != null) currentPackage = pkg
        refreshPerAppContext()
        currentFieldHint = info?.hintText?.toString()?.takeIf { it.isNotBlank() }
        // Whether a code chip may show here, when the user has asked for code
        // boxes only. The field's own words go in alongside its input class,
        // because a code box built out of a text input says what it is even
        // when its input type does not (see [looksLikeCodeField]).
        val codeField = looksLikeCodeField(
            fieldKind,
            currentFieldHint,
            info?.label?.toString(),
            info?.fieldName,
        )
        currentModeFields = buildSet {
            if (secure) add(ModeField.PASSWORD)
            // The shape of a text box (one line, many lines, no suggestions)
            // on top of its kind — the only thing that tells a file manager's
            // rename box from its text editor (issue #186).
            addAll(textShapeFields(info?.inputType ?: 0, secure))
            when (fieldKind) {
                FieldKind.EMAIL -> add(ModeField.EMAIL)
                FieldKind.URI -> add(ModeField.URL)
                FieldKind.NUMBER -> add(ModeField.NUMBER)
                FieldKind.PHONE -> add(ModeField.PHONE)
                // Plain prose. A password box reports TEXT too, so it is
                // excluded — modes bound to TEXT (chat composers, document
                // bodies) must never take over a login form.
                FieldKind.TEXT -> if (!secure) {
                    add(ModeField.TEXT)
                    // A text box hosted by the system UI is the inline
                    // notification reply — the one field whose package can
                    // never name the app the user is actually replying to.
                    if (pkg in notificationShellPackages) {
                        add(ModeField.NOTIFICATION_REPLY)
                    }
                }
                else -> {}
            }
        }
        val base = baseSettings
        // Read the field-detection settings from the base so a per-app mode
        // can't quietly switch either of them off.
        val fieldSettings = base ?: _uiState.value.settings
        // Incognito the field asked for, e.g. a Chrome incognito tab.
        val fieldIncognito = fieldWantsIncognito(fieldSettings, info)
        val fieldNoSuggestions =
            info.suppressesSuggestions(fieldSettings.suggestionSources.inAllFields)
        val activeMode = base?.let {
            resolveKeyboardMode(
                it.keyboardModes, currentPackage, currentModeFields, manualModeId,
                currentFieldHint,
            )
        }
        // Language the field asks for, layered over the base for this app (the
        // per-app remembered layout when that is on, else the global pick).
        // FORCE_ASCII is a hard constraint (the app cannot store what a Bengali
        // mode types) so it outranks a hintLocales preference, which is only ever
        // advisory. Both are compared against — and fall back to — that base.
        // Neither ever reaches outside the enabled list: with no Latin layout
        // enabled a FORCE_ASCII field used to open on the built-in English one,
        // which a user who removed English then met in every field that set
        // the flag (#783).
        //
        // The active mode's layout goes on in the same place (#885): applyMode
        // only rewrites the settings' activeLayoutId, and the grid is resolved
        // from the base, so Passwords → Layout → QWERTY never left Bangla. As a
        // field override it lasts for this field, a globe or spacebar switch
        // still takes the user off it, and the next field without the mode
        // opens on their own layout again. FORCE_ASCII still outranks it when
        // the mode names a layout the field cannot take.
        val current = base ?: _uiState.value.settings
        val baseSpec = resolveLayout(current.customLayouts, baseLayoutId(current))
        val modeSpec = activeMode?.layoutId
            ?.takeIf { it in current.enabledLayoutIds }
            ?.let { id -> resolveLayout(current.customLayouts, id).takeIf { it.id == id } }
        fieldLayoutOverride = when {
            info.forcesAscii() && (modeSpec ?: baseSpec).script().id != ScriptId.LATIN ->
                current.enabledLayoutIds.firstOrNull {
                    resolveLayout(current.customLayouts, it).script().id == ScriptId.LATIN
                }
            modeSpec != null -> modeSpec.id.takeIf { it != baseSpec.id }
            // hintLocales names a language, not a layout, so it picks the first
            // enabled layout that types that language.
            else -> info.hintedLanguage(current.enabledLanguages)
                ?.takeIf { it.id != baseSpec.language().id }
                ?.let { hinted ->
                    current.enabledLayoutIds.firstOrNull {
                        resolveLayout(current.customLayouts, it).language().id == hinted.id
                    }
                }
        }
        val fieldSpec = activeLayoutSpec(current)
        val deviceLocked = isDeviceLocked()
        val clipboardAccessible = userUnlocked && !deviceLocked
        // A field switch closes any open panel below; a GIF/sticker search
        // that was up survives it for the next open.
        stashMediaSearch(_uiState.value)
        // Hoisted out of the copy below so the grid expands against the same
        // digit-row answer the renderer draws with — on a tablet that row is
        // where backspace lives.
        val modeSettings = base?.applyMode(activeMode) ?: _uiState.value.settings
        // Keeps the rule engine paired with the grid on screen: a
        // language switch must not leave the old keyboard's rules
        // running against the new grid.
        syncKeymanSession(fieldSpec)
        syncEngineBlacklist(fieldSpec.language().id)
        // The word lists follow the layout too. A field can open on a layout
        // the settings never emitted, the app's remembered one or the one its
        // language hint asks for, and the engine went on reading the last
        // app's language under the new one's name until the next manual
        // switch (#484). Read before the update below replaces layoutId.
        val engine = suggestionEngine
        if (engine != null &&
            (engine.primaryLanguageId != fieldSpec.language().id || _uiState.value.layoutId != fieldSpec.id)
        ) {
            bindEngineToLayout(fieldSpec, current)
        }
        // The phonetic switches are per language too, and the settings
        // collector only ever set them for the saved layout: an app that
        // reopens on its remembered Avro left the engine on the English
        // layout's answers, so the fixed strip never fixed anything (#575).
        syncPhoneticAutoEnglish(modeSettings, fieldSpec)
        syncPhoneticFixedStrip(modeSettings, fieldSpec)
        syncLegacyOutput(modeSettings, fieldSpec)
        // GIFs and stickers queued in the last field don't follow the user
        // into this one; a restart is still the same field, so they go on.
        if (!restarting) mediaSendQueue.clear()
        _uiState.update {
            it.copy(
                settings = modeSettings,
                language = fieldSpec.language(),
                script = fieldSpec.script(),
                composer = fieldSpec.resolvedComposer(),
                // A locked Ctrl crossing an app boundary is the worst failure
                // this feature can have: every letter after it becomes a
                // shortcut in an app the user never armed it for.
                modifiers = Modifiers.None,
                layoutId = fieldSpec.id,
                layoutName = fieldSpec.name,
                layouts = resolveLayoutSet(
                    fieldSpec,
                    fieldKind,
                    deviceForm.value,
                    modeSettings.numberRow,
                    modeSettings.customLayouts,
                ),
                activeModeId = activeMode?.id,
                noModePicked = manualModeId == NoKeyboardModeId,
                activeSymbolSetId = null,
                // Harmless reset: the strip persists the pick on tap, so the
                // persisted style takes over seamlessly on the next field.
                activeFancyStyleId = null,
                // A panel dies with the field — unless its layout says to keep
                // it open (issue #60, the same switch a key layer has), in
                // which case it stays until a key, a tool or Back closes it.
                // A restart is not a new field (#612): it is the same field
                // reporting itself after the app set its text, which a
                // browser's address bar does for its own clear and "edit this
                // address" buttons. Closing the panel there took the clipboard
                // down under the user's finger. The panel stays, and so does
                // whatever was half done in it.
                panel = if (restarting || panelLayoutPersists(it)) it.panel else PanelMode.NONE,
                // A fresh field starts on the letter layer; a restart of the
                // same field keeps whatever layer the user was on. So does a
                // layer its author marked persistent (issue #60): that one
                // stays until a key or a tool takes the user off it, and a
                // close-and-reopen or a change of app is neither. Judged on
                // the grid that *was* showing, before the set is swapped.
                layoutMode = if (restarting || currentLayout(it).persistent) {
                    it.layoutMode
                } else {
                    LayoutMode.LETTERS
                },
                // Selection mode belongs to the text it was armed over. A
                // restart is the same field reporting itself (a programmatic
                // edit, a web view resetting its connection), where the mode is
                // still about the text the user is working on, so it stays.
                selectionMode = if (restarting) it.selectionMode else false,
                // The finger is not on the tool any more either way: this runs
                // between sessions, not during a hold.
                selectionHold = false,
                fieldKind = fieldKind,
                codeField = codeField,
                nullField = nullField,
                television = television,
                fieldAlignment = if (television) info.requestedAlignment() else null,
                fieldNoSuggestions = fieldNoSuggestions,
                fieldIncognito = fieldIncognito,
                emojiSearchActive = restarting && it.emojiSearchActive,
                emojiQuery = if (restarting) it.emojiQuery else "",
                kaomojiText = if (restarting) it.kaomojiText else null,
                dictionarySearchActive = restarting && it.dictionarySearchActive,
                clipboardSearchActive = restarting && it.clipboardSearchActive,
                clipboardQuery = if (restarting) it.clipboardQuery else "",
                snippetSearchActive = restarting && it.snippetSearchActive,
                snippetQuery = if (restarting) it.snippetQuery else "",
                // The toolbox's search and an open folder's name box are per
                // field, like the snippets search above (#687, #709).
                toolboxView = if (restarting) it.toolboxView else it.toolboxView.copy(
                    searchActive = false,
                    query = "",
                    nameDraft = null,
                ),
                // A clip half-edited survives the same field restarting, the
                // way a selection mode does; another field closes the editor,
                // and Combine with it (#612).
                clipEdit = if (restarting) it.clipEdit else null,
                clipCombine = if (restarting) it.clipCombine else null,
                mediaSearchActive = restarting && it.mediaSearchActive,
                mediaQuery = if (restarting) it.mediaQuery else "",
                mediaDownloadingId = null,
                mediaDownloadProgress = null,
                mediaQueue = if (restarting) it.mediaQueue else emptyList(),
                launcherDetail = null,
                // An app folder's name box is per field like the toolbox's;
                // the open folder itself stays, as the grid does.
                launcherView = it.launcherView.copy(nameDraft = null),
                // A run belongs to the field it was started over; moving to
                // another one abandons it rather than resuming half-typed.
                typingTest = TypingTestUi(),
                translate = TranslateUi(),
                grammar = GrammarUi(available = grammarAvailable || grammarProbePending()),
                composingPreview = "",
                suggestions = emptyList(),
                octopus = emptyMap(),
                emojiSuggestions = emptyList(),
                morsePending = "",
                // A tool-keyword chip ("wiki") belongs to the field it was
                // typed in; a fresh (often empty) field must not inherit it.
                // onUpdateSelection re-derives it once the new field settles,
                // but that can lag the switch, leaving a stale chip up.
                smart = null,
                // The same for the stickers a trigger offered (#329): the new
                // field may take no images at all.
                stickerOffer = null,
                // What this editor takes through commitContent, read once here
                // rather than at send time so the media panels can show up
                // front that a GIF has nowhere to land (see [acceptsRichMedia]).
                fieldContentMimeTypes = info
                    ?.let { editorInfo -> EditorInfoCompat.getContentMimeTypes(editorInfo).toList() }
                    .orEmpty(),
                secureField = secure,
                passwordManagerApp = if (secure) passwordManagerApp() else null,
                deviceLocked = deviceLocked,
                // Against the layout this field opens on: the state still holds
                // the last field's script until this update lands.
                shiftState = autoCapitalizeShift(fieldSpec.script(), fieldSpec.language()),
                shiftPressedByUser = false,
                clipboardItems = if (clipboardAccessible) clipboardStore.items() else emptyList(),
                clipboardSuggestion = if (clipboardAccessible) it.clipboardSuggestion else null,
                // The row of recent copies is only ever up by hand, for the
                // field it was asked for in (#612).
                recentClipsOpen = false,
                clipChipHeld = false,
                enterAction = info.enterAction(),
                enterActionLabel = info?.actionLabel?.toString()?.takeIf { label -> label.isNotBlank() },
                handwriting = it.handwriting.copy(strokes = emptyList(), recognizing = false),
                voice = it.voice.copy(
                    status = VoiceStatus.IDLE, partial = "", level = 0f,
                    strip = false, canUndo = false,
                ),
            )
        }
        if (deviceLocked) watchKeyguard()
        // Left with voice typing on screen: it opens again here, listening (#699).
        resumeVoiceSurface()
        // Chord and morse state belongs to the field it was typed over.
        resetChordInputs()
        refreshKarContext()
        // The rule engine's context and deadkeys belong to the field they were
        // typed in. A new field that reports no caret move would otherwise be
        // typed against the last one's text. A keyboard with a NewContext group
        // then picks the layer for where the caret has landed, as KeymanWeb does
        // on focus.
        keymanSession?.markStale()
        if (!restarting) runKeymanNewContext()
        // The first field this process shows the keyboard for is where a layer
        // the user asked to keep comes back (issue #227). Deferred until the
        // stored settings land, because the flag is re-read off the layouts as
        // they are then; the flag is set here so the wait runs once, not once
        // per field.
        if (!persistentSurfaceRestored) {
            persistentSurfaceRestored = true
            serviceScope.launch {
                storedSettingsApplied.await()
                restorePersistentSurface()
            }
        }
        // Register follows the field: a chat composer and an email body want
        // differently-ranked strips (no-op unless the setting is on).
        pushRegister(_uiState.value.settings)
        // A code captured before this field opened: offer it — or hide it —
        // for the field the keyboard just landed in.
        maybeShowOtpSuggestion()
        // Same question for a code the user copied by hand: a code box is the
        // one field where a sensitive clip is what you came to paste.
        maybeShowCopiedCodeSuggestion()
        // Read the text already sitting around the caret now, on entry. A field
        // that comes back with its text and caret unchanged (returning to a
        // search bar after a search, re-opening a draft) never fires
        // onUpdateSelection, so waiting for it left the keyboard blind to the
        // existing text: no resumed word, no context, and edits fighting a
        // state built for an empty field.
        currentInputConnection?.let { ic ->
            // Same collapsed-caret gate as the onUpdateSelection call site: a
            // range selection has no word to resume. The caret settled above:
            // the field's initial one, or the live one on a re-show (#718).
            if (info != null && expectedSelStart >= 0 && expectedSelStart == expectedSelEnd) {
                restartSuggestionsAtCursor(ic, expectedSelStart)
            } else {
                syncPreviousWordFromField(ic)
                refreshSuggestions()
            }
        }
        // A fresh field is a fresh view of the emoji row, so taps from the last
        // one can reorder it now (see [publishEmojiHistory]).
        publishEmojiHistory()
        // A location permission answer arrives the same way the scanned
        // pages below do: the trampoline finished and the field came back.
        locationTool.onKeyboardShown()
        // And a clock grant (exact alarms, full screen) given on a system screen.
        if (clockToolDelegate.isInitialized()) clockTool.onKeyboardShown()
        // And the microphone or music grant the Music ID panel asked for.
        if (musicToolDelegate.isInitialized()) musicTool.onKeyboardShown()
        // And a calendar grant, which may have a Save or a Delete waiting on it.
        if (calendarToolDelegate.isInitialized()) calendarTool.onKeyboardShown()
        // And a Home Assistant sign-in that came back from the browser.
        if (haToolDelegate.isInitialized()) haTool.onKeyboardShown()
        // The gallery's grant, or what its system picker handed back (#708):
        // the picks join the open panel, or in a Play build go straight out.
        if (galleryToolDelegate.isInitialized() || com.wasimaster.wmkeyboard.app.GalleryPickActivity.hasPending()) {
            galleryTool.onKeyboardShown()
        }
        // The Send files tool's picks, or its Nearby permission answered (#729).
        if (sendToolDelegate.isInitialized() || com.wasimaster.wmkeyboard.app.SendPickActivity.hasPending()) {
            sendTool.onKeyboardShown()
        }
        // Same for the images permission the reply panel's screenshot button
        // asked for: open the picker it was pressed for.
        resumeReplyShotsAfterGrant()
        // And the AI chat's, for the screenshot it was asking for.
        resumeChatShotAfterGrant()
        // And whatever the chat's "+" menu brought back from a picker (#882).
        if (com.wasimaster.wmkeyboard.app.AiChatPickActivity.hasPending()) takeAiChatPicks()
        // Pages from a just-finished document scan: the scanner activity
        // ran while the keyboard was down, so they can only insert now,
        // as the target field regains the input connection.
        commitScanPages(DocScanActivity.consumePendingPages())
        // Fresh field: re-arm the on-keyboard writing hint and check the model
        // up front so the first swipe writes rather than nagging.
        hwModelHintShown = false
        hwKeyboardArmed = keyboardHandwriteActive(_uiState.value)
        if (hwKeyboardArmed) refreshHandwritingStatus()
        // A field can already hold a selection when the keyboard comes back to
        // it (the user selected, switched app, and returned), and no
        // onUpdateSelection follows a selection that never changed.
        refreshSelectionMacros()
    }

    override fun onUpdateSelection(
        oldSelStart: Int,
        oldSelEnd: Int,
        newSelStart: Int,
        newSelEnd: Int,
        candidatesStart: Int,
        candidatesEnd: Int,
    ) {
        // The settings app's own fields live in this process, and there the
        // echo is not a message at all. Every hop from our commitText to the
        // editor and back through InputMethodManager.updateSelection is a local
        // binder, so this runs *inside* the commitText that caused it, before
        // the caller has cleared its buffer — and the edits it makes from in
        // there (the region re-arm, a finishComposingText) land inside the
        // editor's own callback. Compose's RecordingInputConnection hands its
        // pending commands to that callback before clearing them, so a nested
        // edit applies the outer one a second time: "test." came out as
        // "test.test" (#544), and with a snippet expanding, the nesting fed on
        // itself until the app froze and died (#543). Posted, the echo arrives
        // the way every other app's does, after the keystroke has finished.
        if (currentInputEditorInfo?.packageName == packageName) {
            inProcessEchoHandler.post {
                trace(ImeTrace.UPDATE_SELECTION) {
                    updateSelection(oldSelStart, oldSelEnd, newSelStart, newSelEnd, candidatesStart, candidatesEnd)
                }
            }
            return
        }
        trace(ImeTrace.UPDATE_SELECTION) {
            updateSelection(oldSelStart, oldSelEnd, newSelStart, newSelEnd, candidatesStart, candidatesEnd)
        }
    }

    /** Delivers [onUpdateSelection] for an editor in this process; see there. */
    private val inProcessEchoHandler = Handler(Looper.getMainLooper())

    /**
     * The end of the word that was underlined when a tap moved the caret off
     * it, the caret the tap left, and when; -1 when nothing is being watched.
     * See [undoCaretSnapBack].
     */
    private var snapBackFrom = -1
    private var snapBackTo = -1
    private var snapBackArmedAt = 0L

    /** Called where a tap in a web field ends a composition; see [undoCaretSnapBack]. */
    private fun armCaretSnapBackGuard(from: Int, to: Int) {
        if (from == to) return
        snapBackFrom = from
        snapBackTo = to
        snapBackArmedAt = SystemClock.uptimeMillis()
    }

    /**
     * Puts the caret back where a tap left it when a web editor throws it back
     * to the end of the word that was being typed (#679).
     *
     * A code editor in a page (CodeMirror in ViolentMonkey, the editor on
     * notes.futo.tech) keeps its own model of the selection and does not take
     * the page's selection changes while a composition is open. A tap away
     * from an underlined word is one of those, so its model still holds the
     * old caret; the [finishComposingText] the tap leads to ends the
     * composition, the editor redraws the line from its model, and the caret
     * lands back behind the word. Where the new spot resumed a word of its own
     * the region moved with the tap and nothing snapped, which is why only a
     * tap onto a spot with no word to underline jumped.
     *
     * So for a moment after such a tap, a collapsed caret reported exactly at
     * the old word's end is taken for that redraw and the tap's caret is set
     * again. Returns true when it did, and the update is not acted on.
     */
    private fun undoCaretSnapBack(newSelStart: Int, newSelEnd: Int): Boolean {
        val from = snapBackFrom
        if (from < 0) return false
        if (SystemClock.uptimeMillis() - snapBackArmedAt > CARET_SNAP_BACK_WINDOW_MS) {
            snapBackFrom = -1
            return false
        }
        if (newSelStart != newSelEnd || newSelStart != from) return false
        val to = snapBackTo
        snapBackFrom = -1
        snapBackTo = -1
        if (composing.isNotEmpty()) return false
        val ic = currentInputConnection ?: return false
        DebugLog.d("ime", "caret snapped back to $from after a tap at $to; setting it again")
        return ic.setSelection(to, to)
    }

    /**
     * Where the composing word started when [absorbGluedWord] last looked in
     * front of it, so each word pays for that read once and not on every
     * keystroke's echo.
     */
    private var gluedCheckedAt = -1

    /**
     * The caret offset just behind a space this keyboard committed, taken from
     * that commit's own echo, or -1. A word whose composing region starts here
     * starts after a space, so [absorbGluedWord] has nothing to look for and
     * skips its read into the app.
     */
    private var ownSpaceEndsAt = -1

    /** Set by [onSpace]; the next echo with no composing region records [ownSpaceEndsAt]. */
    private var ownSpaceEchoPending = false

    /**
     * The caret [commitComposing] just left behind a word ending in a letter,
     * or -1. Read by [onSpace] straight after the commit.
     */
    private var plainCommitEnd = -1

    /**
     * Where [onSpace] expects the caret after "word ", with the caps mode the
     * field gives that spot ([capsAfterWordAndSpace]), or -1. The echo landing
     * exactly there takes the answer instead of asking the editor again.
     */
    private var ownSpaceCaret = -1
    private var ownSpaceCaps = 0

    /**
     * Takes the rest of the word into the composition when the letters being
     * typed went on straight from the end of a word already in the field.
     *
     * Backspace "excepted" to "except" and type "io", and the keyboard is meant
     * to be finishing "exceptio". It does when the caret's echo arrives first,
     * because the echo re-arms "except" as the composing word
     * ([restartSuggestionsAtCursor]). But echoes queue behind fast backspaces,
     * the re-arm then checks the caret has not moved on and stands down, and
     * the next letter starts a word of its own: only "io" was underlined, and
     * the strip offered words for "io" (#662). The commit then saw the buffer
     * glued to a word and typed it as it stood, which kept the text right but
     * the strip and the correction wrong for the whole word.
     *
     * This is the late half of the same re-arm. On the echo of the new word's
     * own keystroke it looks once in front of the region, and when a word ends
     * exactly there it widens the region over that word and puts the word in
     * the buffer, the same as a resume would have. Only for the composers whose
     * buffer is the field's text, and not in front of an elided prefix ("l'"),
     * which ends a word rather than starting one, nor inside a word the caret
     * was dropped into the middle of.
     */
    private fun absorbGluedWord(selStart: Int, selEnd: Int, candidatesStart: Int, candidatesEnd: Int) {
        if (composing.isEmpty() || candidatesStart < 0 || selStart != selEnd || selEnd != candidatesEnd) return
        if (candidatesStart == gluedCheckedAt) return
        // Started right behind the keyboard's own space: not glued to anything,
        // and known without asking the editor (see [ownSpaceEndsAt]).
        if (candidatesStart == ownSpaceEndsAt) {
            gluedCheckedAt = candidatesStart
            return
        }
        val state = _uiState.value
        if (state.composer.isTransliterating || state.layouts.ambiguousKeys ||
            !state.resumesWords || duetWord.active || inlineEmojiQuery() != null || fancyOutputStyle(state) != null ||
            !composingResumable(state.composer, suggestionEngine?.hasWordSources == true)
        ) {
            return
        }
        val text = composedPreview(state, composing.toString())
        if (candidatesEnd - candidatesStart != text.length) return
        val ic = currentInputConnection ?: return
        val before = ic.getTextBeforeCursor(text.length + GLUED_WORD_LOOKBACK, 0)?.toString() ?: return
        // The field has moved on past this echo (a stale one is not a no: the
        // next echo asks again).
        if (!before.endsWith(text)) return
        val ahead = before.substring(0, before.length - text.length)
        val head = ahead.takeLastWhile { isComposingWordChar(it) }
        if (head.isEmpty()) {
            // The ordinary case, a word started after a space: settled for
            // this word with the one read.
            gluedCheckedAt = candidatesStart
            return
        }
        // Only now the whole-text read that proves the echo is live, since
        // widening the region from a stale offset would put it over the
        // wrong characters.
        if (!caretStillAt(ic, selStart)) return
        gluedCheckedAt = candidatesStart
        // A run of word characters as long as the read is a token or an
        // address, not a word anybody is finishing.
        if (head.length >= GLUED_WORD_LOOKBACK) return
        if (Elisions.rulesFor(state.language.id)?.endsWithElidedPrefix(ahead) == true) return
        val after = ic.getTextAfterCursor(1, 0)
        if (!after.isNullOrEmpty() && continuesWordAhead(after[0])) return
        if (!ic.setComposingRegion(candidatesStart - head.length, candidatesEnd)) return
        val word = head + composing.toString()
        composing = StringBuilder(word)
        composingCaseTrusted = false
        gluedCheckedAt = candidatesStart - head.length
        val context = ahead.substring(0, ahead.length - head.length)
        setContextFrom(context)
        rebuildRecentWords(context)
        _uiState.update { it.copy(composingPreview = head + text) }
        refreshSuggestions()
    }

    /**
     * A collapsed caret inside (or at the end of) a Japanese reading being
     * composed: becomes [readingCaret], so the reading stays open and the next
     * key is typed there (#960). True when it did; false leaves the update to
     * the rules for an ordinary composing word, which end the composition.
     */
    private fun moveReadingCaret(selStart: Int, selEnd: Int, candidatesStart: Int, candidatesEnd: Int): Boolean {
        if (candidatesStart < 0 || candidatesEnd <= candidatesStart || !editsInsideReading(_uiState.value)) {
            readingCaretEchoes.clear()
            return false
        }
        readingRegionStart = candidatesStart
        if (selStart != selEnd || selStart < candidatesStart || selStart > candidatesEnd) {
            readingCaretEchoes.clear()
            return false
        }
        if (readingCaretEchoes.isNotEmpty()) {
            // One of ours: settled up to it.
            val ours = readingCaretEchoes.indexOf(selStart)
            if (ours >= 0) {
                repeat(ours + 1) { readingCaretEchoes.removeFirst() }
                return true
            }
            // A rewrite's own echo, ahead of the caret put back after it.
            if (selStart == candidatesEnd) return true
            readingCaretEchoes.clear()
        }
        val was = readingCaret
        readingCaret = if (selStart == candidatesEnd) {
            -1
        } else {
            val buffer = composing.toString()
            _uiState.value.composer.bufferIndex(buffer, selStart - candidatesStart)
                .let { if (it >= buffer.length) -1 else it }
        }
        if (readingCaret != was) publishKanaVariantReady()
        return true
    }

    private fun updateSelection(
        oldSelStart: Int,
        oldSelEnd: Int,
        newSelStart: Int,
        newSelEnd: Int,
        candidatesStart: Int,
        candidatesEnd: Int,
    ) {
        super.onUpdateSelection(oldSelStart, oldSelEnd, newSelStart, newSelEnd, candidatesStart, candidatesEnd)
        if (tracedConnection is TracingInputConnection) {
            TracingInputConnection.noteSelection(
                oldSelStart, oldSelEnd, newSelStart, newSelEnd, candidatesStart, candidatesEnd,
            )
        }
        lastSelectionUpdateAt = SystemClock.uptimeMillis()
        // The first half of a caret nudge (#662): the caret is on its way
        // straight back, so nothing about where it is now is worth acting on.
        if (revealDetourStart >= 0) {
            val detour = minOf(newSelStart, newSelEnd) == revealDetourStart &&
                maxOf(newSelStart, newSelEnd) == revealDetourEnd
            revealDetourStart = -1
            revealDetourEnd = -1
            if (detour) return
        }
        if (undoCaretSnapBack(newSelStart, newSelEnd)) return
        expectedSelStart = newSelStart
        expectedSelEnd = newSelEnd
        recentEchoOwed = false
        if (recentBarAwaitsEcho) scheduleRecentBar()
        noteTypedCaret(oldSelEnd, newSelStart, newSelEnd)
        // The space commit's echo is the first one with no composing region:
        // the letter echoes still queued ahead of it all carry the word's.
        var ownSpaceEcho = false
        if (ownSpaceEchoPending && candidatesStart < 0) {
            ownSpaceEchoPending = false
            ownSpaceEndsAt = if (newSelStart == newSelEnd && newSelStart > 0) newSelStart else -1
            ownSpaceEcho = ownSpaceCaret >= 0 && newSelStart == newSelEnd && newSelStart == ownSpaceCaret
            ownSpaceCaret = -1
        }
        if (newSelStart != lastRevealedCaret || newSelEnd != lastRevealedCaret) lastRevealedCaret = -1
        if (selectionAnchor != newSelStart && selectionAnchor != newSelEnd) selectionAnchor = -1
        trackCaretAtFieldStart(newSelStart, newSelEnd)
        caretMagnifier.onSelection(newSelStart, newSelEnd)
        // Marks the engine's context stale unless this is the echo of its own
        // edit. No text is read here: this runs on every keystroke, and a read
        // would undo what the expected-selection cache exists to save.
        keymanSession?.let { session ->
            session.onSelectionReported(newSelStart, newSelEnd)
            // The user moved the caret: a keyboard with a NewContext group looks
            // at where it landed and may pick a layer for it.
            if (session.stale && newSelStart == newSelEnd && session.processor.hasNewContext) {
                runKeymanNewContext()
            }
        }
        glideReadings.onCaret(newSelStart, newSelEnd)
        noteCaretForLearning(oldSelStart, oldSelEnd, newSelStart, newSelEnd)
        noteCaretForRevision(newSelStart, newSelEnd)
        // Each undo chip entry keeps its own anchor, forgiving forwards where
        // [revertAnchor] is not: typing on is precisely what it is built to
        // survive. What one cannot survive is the caret going back through the
        // word it names, or landing somewhere else entirely — then it can no
        // longer say which occurrence of that word it meant, and the search
        // behind the tap would be a guess. Judged entry by entry: backspacing
        // into the newest correction leaves the older ones in front of the
        // caret, still good.
        if (undoChain.isNotEmpty()) {
            if (newSelStart != newSelEnd) {
                clearUndoChip()
            } else {
                val newest = undoChain.last()
                for (entry in undoChain) {
                    if (entry.caret == -1) entry.caret = newSelStart
                }
                undoChain.removeAll {
                    newSelStart < it.caret || newSelStart > it.caret + UNDO_CHIP_LOOKBEHIND
                }
                if (undoChain.lastOrNull() !== newest) showNextUndo()
            }
        }
        // Same rule for the text a chip's gear took out: only at the caret the
        // delete left, recorded from its echo when it was not known up front.
        chipOpenRestore?.let { restore ->
            when {
                newSelStart != newSelEnd -> chipOpenRestore = null
                restore.caret == -1 -> chipOpenRestore = restore.copy(caret = newSelStart)
                newSelStart != restore.caret -> chipOpenRestore = null
            }
        }
        // Immediate-revert states are only valid at the caret position their
        // commit left behind; see [revertAnchor]. The first update after
        // arming is the commit's own echo and records the anchor, anything
        // that moves the caret afterwards disarms them.
        if (lastRevertible != null || lastGestureWord != null || pendingAutoSpace ||
            pendingWordSpace || deferredWordSpace
        ) {
            val settling = SystemClock.uptimeMillis() - revertArmedAt < REVERT_SETTLE_MS
            fun disarm() {
                lastRevertible = null
                // The chips describe text at a caret position that has just
                // stopped being where the caret is.
                clearSwapOffer()
                lastGestureWord = null
                pendingAutoSpace = false
                pendingPunctuationSpace = false
                pendingWordSpace = false
                deferredWordSpace = false
            }
            when {
                // A range selection is never one of our own commit echoes.
                newSelStart != newSelEnd -> disarm()
                revertAnchor == -1 || settling -> revertAnchor = newSelStart
                newSelStart != revertAnchor -> disarm()
            }
        }
        val wasComposing = composing.isNotEmpty()
        val caretInReading = wasComposing && moveReadingCaret(newSelStart, newSelEnd, candidatesStart, candidatesEnd)
        val cursorOutsideCandidates =
            cursorLeftComposingRegion(newSelStart, newSelEnd, candidatesStart, candidatesEnd)
        // A caret placed *inside* the composing word (a tap mid-word) also ends
        // the composition. Keeping it meant the next keystroke rewrote the
        // whole region via setComposingText — which snaps the cursor to the
        // word's end, so the tap appeared to not move the cursor at all and
        // the letter landed at the end of the word instead of where it was
        // put. The keyboard's own composing edits always leave the collapsed
        // caret exactly at candidatesEnd, so a caret strictly before it can
        // only be the user's. Dropping composition here lets the fall-through
        // below re-derive the context at the new caret, mid-word taps landing
        // in the no-resume branch of restartSuggestionsAtCursor.
        // A Japanese reading is the exception: there a caret inside it is
        // where the next key goes (#960), handled above.
        val cursorInsideCandidates = !caretInReading && candidatesStart >= 0 && candidatesEnd > candidatesStart &&
            newSelStart == newSelEnd &&
            newSelStart >= candidatesStart && newSelStart < candidatesEnd

        // The editor can also throw the composition away wholesale: a search
        // box's clear button, or an app replacing its own text, empties the
        // field with setText and reports a caret at 0 with no candidates. The
        // rule above lets that through — there is no region to have left — and
        // the buffer then outlives an empty field, so the next keystroke's
        // setComposingText puts the whole old word back in front of whatever
        // is typed or pasted next (issue #192, SeriesGuide's movie search).
        // A caret the composed text cannot fit in front of is that case.
        val composedText = if (wasComposing) composedPreview(_uiState.value, composing.toString()) else ""
        val compositionVanished = wasComposing && !_uiState.value.composer.isConversion &&
            compositionCannotPrecedeCaret(
                oldSelStart, newSelStart, newSelEnd, candidatesStart, composedText.length,
            )
        // A Chinese reading kept on the strip has no region to step out of
        // (#973): a caret moved off where it sits ends it all the same.
        val readingLeft = wasComposing && hiddenReadingLeft(newSelStart, newSelEnd, candidatesStart)
        val composingDropped = wasComposing &&
            (cursorOutsideCandidates || cursorInsideCandidates || compositionVanished || readingLeft)
        if (composingDropped) {
            if ((cursorOutsideCandidates || cursorInsideCandidates) && newSelStart == newSelEnd &&
                candidatesEnd >= 0 && isWebEditField()
            ) {
                armCaretSnapBackGuard(from = candidatesEnd, to = newSelStart)
            }
            composing = StringBuilder()
            currentInputConnection?.finishComposingText()
            suggestionJob?.cancel()
            _uiState.update {
                it.copy(
                    composingPreview = "",
                    suggestions = emptyList(),
                    emojiSuggestions = emptyList(),
                    octopus = emptyMap(),
                )
            }
        }
        // The editor can also finish a composition on its own: a TextWatcher
        // that restyles the text (chat apps marking mentions/markdown) drops
        // the composing span without moving the caret or telling the IME. The
        // buffer then has no region behind it, so the commit on space *inserts*
        // the word instead of replacing it — the word doubles. An update that
        // reports no candidates while a composition is supposedly alive, with
        // the collapsed caret still exactly where it was left, sitting right
        // after text that reads back as the buffer's own output, is that state:
        // quietly re-arm the region. Editors that simply never report
        // candidates re-set the identical region, a no-op. Same readback guard
        // as [reattachComposing]; conversion composers are excluded because
        // their prefix commits manage the region themselves.
        var composingReplaced = false
        if (!composingDropped && composing.isNotEmpty() && candidatesStart < 0 &&
            newSelStart == newSelEnd && !_uiState.value.composer.isConversion
        ) {
            val ic = currentInputConnection
            val text = composedText
            if (ic != null && text.isNotEmpty() && newSelStart >= text.length &&
                caretStillAt(ic, newSelStart)
            ) {
                if (ic.getTextBeforeCursor(text.length, 0)?.toString() == text) {
                    ic.setComposingRegion(newSelStart - text.length, newSelStart)
                } else {
                    // The caret is settled and what sits in front of it is not
                    // the buffer: the editor put other text there (a search
                    // box filling in a picked suggestion, say). The word being
                    // composed is gone from the field, and a buffer kept past
                    // that would be inserted again by the next keystroke, the
                    // same way as above (#192). Dropping it costs the strip
                    // the word's prefix and never touches the field.
                    composingReplaced = true
                }
            }
        }
        if (composingReplaced) {
            // The buffer goes and the region behind it goes with it. The
            // editor reported none — that is the branch's own condition — but
            // an editor that restyles as you type is exactly the one that
            // stops reporting a region it still holds, and a span nothing is
            // tracking silently moves the next positional edit somewhere else
            // (#267, and see [onSuggestionTapped]). Finishing a composition
            // never changes the text, only the span, so where the report was
            // honest this costs nothing.
            currentInputConnection?.finishComposingText()
            composing = StringBuilder()
            suggestionJob?.cancel()
            _uiState.update {
                it.copy(
                    composingPreview = "",
                    suggestions = emptyList(),
                    emojiSuggestions = emptyList(),
                    octopus = emptyMap(),
                )
            }
        }
        if (!composingDropped && !composingReplaced) {
            absorbGluedWord(newSelStart, newSelEnd, candidatesStart, candidatesEnd)
        }
        // Partial dictation results are cumulative per utterance, so they
        // can't follow a cursor jump without duplicating what's already
        // committed — end the session instead, keeping the partial.
        val voiceStatus = _uiState.value.voice.status
        val partialInField = (voiceStatus == VoiceStatus.LISTENING || voiceStatus == VoiceStatus.FINISHING) &&
            _uiState.value.voice.partial.isNotEmpty() &&
            // Interactive voice typing puts no partial in the field, so a
            // cursor jump costs it nothing: the next phrase lands wherever
            // the caret now is. Moving the caret mid-sentence is a normal
            // part of using the keys while the microphone is open.
            !interactiveVoice()
        // asr4all's words wait in the field while its last moment decodes.
        val asr4allFinishing = voiceStatus == VoiceStatus.TRANSCRIBING && asr4allComposed
        if ((partialInField || asr4allFinishing) && cursorOutsideCandidates) cancelVoice()
        // The caret right behind a letter of the word being composed: no caps
        // mode asks for a capital there (TextUtils.getCapsMode answers 0 for a
        // letter before the caret, sentence and word modes alike), so the shift
        // can be settled without the round trip into the app. This is the
        // echo of almost every keystroke.
        val composedNow = if (composing.isNotEmpty()) composedPreview(_uiState.value, composing.toString()) else ""
        val caretAfterLetter = composedNow.isNotEmpty() && newSelStart == newSelEnd &&
            candidatesEnd >= 0 && newSelEnd == candidatesEnd &&
            Character.isLetterOrDigit(composedNow.codePointBefore(composedNow.length))
        refreshShiftForContext(caretAfterLetter, knownCaps = if (ownSpaceEcho) ownSpaceCaps else null)
        refreshKarContext()
        // Tool chips and the word strip both read the text around the cursor, so
        // they have to be re-derived after a cursor jump or an edit made from
        // outside the keyboard, not only after a keystroke. A settled plain
        // caret re-reads the whole context — the word it landed on and the strip
        // — via restartSuggestionsAtCursor (which folds in the chip refresh). An
        // active word still being composed in place, or a range selection being
        // dragged out, only refreshes the chips.
        if ((!wasComposing || composingDropped || composingReplaced) && composing.isEmpty() &&
            newSelStart == newSelEnd
        ) {
            currentInputConnection?.let { restartSuggestionsAtCursor(it, newSelStart) }
        } else {
            // The mid-word strip goes the same way for the same reason: a
            // selection dragged out over the word it was about, or a buffer
            // now being typed, is no longer a caret parked inside that word.
            clearCaretWord()
            refreshSmartSuggestion()
            // The snippet chip reads the same text and goes stale the same way
            // — a selection dragged out over the span it names is no longer a
            // caret sitting after it.
            refreshSnippetOffer(_uiState.value)
            // A single word highlighted is a question about that word (#413):
            // the strip answers with its other spellings, the way it does for
            // a caret parked inside one, and a pick goes in over the selection.
            if (newSelStart != newSelEnd && composing.isEmpty()) {
                publishSelectedWordSuggestions(newSelStart, newSelEnd)
            }
        }
        // The grammar strip follows the field: any text or cursor change
        // while it is open re-extracts and re-lints (offline, so cheap).
        // Translate deliberately does NOT — it translates its own typed
        // query, never the field.
        if (_uiState.value.panel == PanelMode.GRAMMAR) scheduleGrammarCheck()
        // The find panel's matches follow the field the same way.
        if (_uiState.value.panel == PanelMode.FIND_REPLACE) refreshFindMatches(reselect = false, immediate = false)
        // The AI panel's action chips are enabled by there being text to act
        // on, so they follow the field the same way.
        if (_uiState.value.panel == PanelMode.AI) refreshAiHasText()
        // The macro bar is about the selection itself rather than about the
        // text around a caret, so it follows every update and not only the
        // settled-caret branch above.
        refreshSelectionMacros(newSelStart, newSelEnd)
    }

    /**
     * Tells the system autofill service how much room the strip has, which
     * is what makes password-manager chips appear there at all.
     *
     * Declining (returning null) is the documented way to opt out, and it
     * declines only when both lanes are switched off. Incognito is not a
     * reason: it promises that nothing typed is remembered, and a chip the
     * password manager draws remembers nothing — the keyboard never even
     * sees what is in it. Declining under incognito was how a login form in
     * a private tab, or under the Incognito tool, lost its saved-login chips
     * altogether (issue #151).
     */
    /**
     * Same question as [KeyboardUiState.incognitoOn], asked before the state
     * exists: the platform builds the autofill request during onStartInput,
     * ahead of onStartInputView, so the field flag has to come straight off
     * [currentInputEditorInfo] rather than the cached UI state.
     */
    private fun incognitoForAutofillRequest(): Boolean {
        val settings = _uiState.value.settings
        return settings.incognito || fieldWantsIncognito(settings, currentInputEditorInfo)
    }

    /**
     * How many chips each lane may show right now: credentials from the
     * autofill service first, platform smart replies second. Zero means the
     * lane is switched off, and (0, 0) means nothing may be requested at all.
     *
     * Incognito closes the reply lane only. A smart reply is the system
     * reading the conversation on screen, which is the same thing incognito
     * exists to stop everywhere else. A saved-login chip is the opposite
     * case: the manager offers what it already holds, the keyboard learns
     * nothing from it, and a private session is exactly where the user is
     * logging in (#151).
     */
    private fun inlineChipBudgets(): Pair<Int, Int> {
        val settings = _uiState.value.settings
        // Password-manager chips off closes *both* lanes, not just its own.
        //
        // There is one inline request per field and it covers the two lanes
        // together, so asking for replies also opts the field into the inline
        // path — and the manager then sends its credentials down it instead of
        // drawing its dropdown. The keyboard would drop them (this lane is
        // off) and the user would be left with neither the chips nor the
        // dropdown the setting promises them. The platform gives no way to
        // take one and decline the other: onInlineSuggestionsResponse returns
        // a boolean the framework wires to a Consumer and discards, so there
        // is no handing them back either.
        //
        // Replies are the smaller loss, and only in the configuration where
        // someone has said they want their manager's own UI (#250).
        if (!settings.suggestionSources.inlineAutofill) return 0 to 0
        val platform = if (settings.suggestionStrip.systemSmartReplies && !incognitoForAutofillRequest()) {
            InlineAutofill.MAX_PLATFORM_CHIPS
        } else {
            0
        }
        return InlineAutofill.MAX_AUTOFILL_CHIPS to platform
    }

    override fun onCreateInlineSuggestionsRequest(uiExtras: Bundle): InlineSuggestionsRequest? {
        if (!InlineAutofill.supported) return null
        val (autofillBudget, platformBudget) = inlineChipBudgets()
        val context = inlineChipContext()
        val density = context.resources.displayMetrics
        val stripHeightPx = (INLINE_CHIP_HEIGHT_DP * density.density).toInt()
        return runCatching {
            InlineAutofill.request(
                context = context,
                uiExtras = uiExtras,
                stripHeightPx = stripHeightPx,
                maxWidthPx = density.widthPixels,
                autofillBudget = autofillBudget,
                platformBudget = platformBudget,
                palette = inlineChipPalette,
            )
        }.getOrNull()
    }

    /**
     * The context the chips are measured and inflated against: the display the
     * keyboard is actually on, not the service's own.
     *
     * They differ the moment the keyboard is not on the default display — a
     * desktop-mode window, an external screen — where the service's resources
     * still describe the built-in panel. Sizing a chip by the wrong metrics is
     * the visible half; the surface belongs to the other process and is handed
     * a display too, which is the half that does not merely look wrong.
     *
     * Only Android 11 and 12 need the detour. From 12L the IME context is a
     * window-provider context that re-resolves its own resources when the
     * window moves, so it already *is* the display context; before 11 none of
     * this code runs at all.
     */
    @Suppress("DEPRECATION")
    private fun inlineChipContext(): Context {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S_V2) return this
        return runCatching {
            val windows = getSystemService(Context.WINDOW_SERVICE) as WindowManager
            createDisplayContext(windows.defaultDisplay)
        }.getOrDefault(this)
    }

    /**
     * The strip's chip colours as the composition last resolved them, or null
     * before it has drawn once. Written from the keyboard's own composition
     * (see [InlineChipPaletteReport]) because the autofill request is built
     * during onStartInput, with no composition in reach.
     */
    @Volatile
    private var inlineChipPalette: InlineChipPalette? = null

    /** Stable across recompositions, as [systemNavBarPainter] is. */
    private val inlineChipPaletteReporter = InlineChipPaletteReporter { palette ->
        inlineChipPalette = palette
    }

    /**
     * The answer, mixing the manager's credential chips with whatever the
     * platform decided to send. Returning true claims the suggestions so the
     * platform does not fall back to its own dropdown over the keyboard.
     */
    override fun onInlineSuggestionsResponse(response: InlineSuggestionsResponse): Boolean {
        if (!InlineAutofill.supported) return false
        val (autofillBudget, platformBudget) = inlineChipBudgets()
        if (autofillBudget + platformBudget == 0) return false
        if (response.inlineSuggestions.isEmpty()) onInlineChipsWithdrawn()
        val generation = ++inlineResponseGeneration
        val lanes = InlineAutofill.split(
            suggestions = response.inlineSuggestions,
            autofillBudget = autofillBudget,
            platformBudget = platformBudget,
        )
        InlineAutofill.inflateAll(
            context = inlineChipContext(),
            lanes = lanes,
        ) { chips ->
            // Inflation is remote and asynchronous, so an older response can
            // finish after a newer one — or after the chips were dismissed or
            // the field was left. Only the latest answer may reach the strip;
            // a late one would put back chips the platform already withdrew,
            // whose surfaces are dead and draw blank (#398).
            if (generation != inlineResponseGeneration) return@inflateAll
            _uiState.update {
                it.copy(autofillChips = chips.autofill, smartReplyChips = chips.platform)
            }
        }
        return true
    }

    /**
     * Bumped by every inline response and every local withdrawal of the chips,
     * so an inflation still in flight can tell it has been overtaken. Main
     * thread only: responses and inflate callbacks both arrive there.
     */
    private var inlineResponseGeneration = 0

    /**
     * When the keyboard last did something that can make the platform filter
     * its chips down to nothing: a keypress (every one of those goes through
     * [vibrate]) or any edit reaching the field, including a glide, a paste or
     * a hardware key, all of which arrive here as a selection update.
     */
    private var lastSelectionUpdateAt = 0L

    /**
     * Whether [settingsRepository] has emitted from credential storage yet, so
     * the clipboard limits in [KeyboardUiState.settings] are the user's own
     * rather than the defaults. Until then the history store prunes nothing.
     */
    private var clipboardLimitsKnown = false

    /** The repository's last emission, before any of the keyboard's views. */
    private var lastStoredSettings: KeyboardSettings? = null

    /** [lastStoredSettings] at the unlock: the mirror's, not the real store's. */
    private var lockedStoredSettings: KeyboardSettings? = null

    /** Hands the clipboard settings the store enforces to [clipboardStore]. */
    private fun configureClipboardStore(settings: KeyboardSettings) {
        clipboardStore.expiryMillis = settings.clipboard.expiryHours * 60L * 60 * 1000
        clipboardStore.maxItems = settings.clipboard.maxItems
        clipboardStore.maxTextChars = settings.clipboard.maxTextChars
        clipboardStore.keepRichText = settings.clipboard.keepRichText
        clipboardStore.pinnedLast = settings.clipboard.pinnedLast
        clipboardStore.pinnedInPlace = settings.clipboard.pinnedInPlace
        clipboardStore.sensitiveExpiryMillis =
            if (settings.clipboard.sensitiveHandling == SensitiveClipHandling.SHORT_LIVED) {
                settings.clipboard.sensitiveExpiryMinutes * 60L * 1000
            } else {
                0L
            }
    }

    /** When a key last typed into the field, for the 🌐 guard: see [globeTapGuarded]. */
    private var lastTypedKeyAt = 0L

    /** The run of taps a [Key.multitap] key is in, if any (discussion #372). */
    private val multitap = MultitapCycle()

    /**
     * What the last tap of the open multitap run typed, exactly as it reached
     * the buffer or the field — the text the next tap of the run takes back.
     */
    private var multitapWrote: String? = null

    /** How the last tap of an open Keyman multitap run typed; see [onKeymanMultitapKey]. */
    private var keymanMultitapWrote: KeymanMultitapStep? = null

    /** The Keyman layer the open multitap run began on. */
    private var keymanMultitapLayer: String? = null

    /** What a tap of a Keyman multitap run did, and so how to take it back. */
    private sealed interface KeymanMultitapStep {
        /** The engine typed it, into the field and its own context. */
        class Engine(val session: KeymanSession, val tap: KeymanTap) : KeymanMultitapStep

        /** It went down the ordinary path as [text], with no rules to run. */
        class Typed(val text: String) : KeymanMultitapStep

        /** It typed nothing: a layer switch. */
        data object Nothing : KeymanMultitapStep
    }

    /** The last onStartInput for a different field than the one before it. */
    private var inlineFieldStartedAt = 0L

    private val inlineChipTapFeedback = Runnable {
        if (inlineFieldStartedAt < inlineChipsWithdrawnAt) vibrate()
    }
    private var inlineChipsWithdrawnAt = 0L

    /**
     * The chips were taken back — the keyboard's only sign that one of them was
     * tapped, which is why it is the one place a chip tap can buzz (#250).
     *
     * A chip is a surface the other process draws and owns, and its touch never
     * enters this window: the renderer hands the click straight to the
     * autofill system, and the only thing sent back is this, the empty
     * response that hides the row just before the manager fills the field. So
     * a tap is read from the withdrawal, less the other things that also
     * withdraw them: typing that the chips no longer match (the keyboard or
     * the field moved first), and focus going to another field (a new start,
     * before this or just after, which is why the buzz waits a moment for one).
     *
     * A manager whose vault is locked answers a tap by opening its unlock
     * screen instead, with no withdrawal, and that tap stays silent.
     */
    private fun onInlineChipsWithdrawn() {
        val state = _uiState.value
        if (state.autofillChips.isEmpty() && state.smartReplyChips.isEmpty()) return
        if (!windowOnScreen) return
        val now = SystemClock.uptimeMillis()
        val lastLocal = maxOf(lastVibrateAt, lastSelectionUpdateAt, inlineFieldStartedAt)
        if (now - lastLocal < INLINE_CHIP_QUIET_MS) return
        inlineChipsWithdrawnAt = now
        feedbackHandler.removeCallbacks(inlineChipTapFeedback)
        feedbackHandler.postDelayed(inlineChipTapFeedback, INLINE_CHIP_TAP_CONFIRM_MS)
    }

    /**
     * Dismiss chip on the strip: drop them until the next response. Both lanes
     * go, since the ✕ says "stop offering me things about this field" and the
     * two lanes are answering the same one.
     */
    fun onDismissInlineSuggestions() {
        vibrate()
        inlineResponseGeneration++
        _uiState.update { it.copy(autofillChips = emptyList(), smartReplyChips = emptyList()) }
    }

    /**
     * The hide-keyboard tool and the toolbar and spacebar swipe-downs: close
     * the keyboard. With a tool field's keys up under its panel, only those
     * go down (#961), and the panel stays to be read.
     */
    fun onHideKeyboard() {
        if (lowerCaptureKeys()) return
        requestHideSelf(0)
    }

    /**
     * The Leave field action (#626): out of the field, not only the keyboard
     * down. Nothing lets a keyboard take another app's focus away, but an
     * Esc does it in the apps that answer one. A browser's address bar takes
     * two: the first drops its suggestions, the second the focus. So one Esc,
     * the keyboard put away, and a second Esc a moment later only if a real
     * field of the same app is still bound, so an app that already let go is
     * not sent a stray Esc that could shut a dialog behind it.
     */
    fun onLeaveField() {
        val ic = currentInputConnection
        if (ic == null || isNullField()) {
            requestHideSelf(0)
            return
        }
        commitComposing(ic, autocorrect = false)
        sendEscape(ic)
        val app = currentInputEditorInfo?.packageName
        requestHideSelf(0)
        serviceScope.launch {
            delay(LEAVE_FIELD_SECOND_ESC_MS)
            val still = currentInputConnection ?: return@launch
            if (currentInputStarted && !isNullField() && currentInputEditorInfo?.packageName == app) {
                sendEscape(still)
            }
        }
    }

    private fun sendEscape(ic: InputConnection) {
        val time = SystemClock.uptimeMillis()
        ic.sendKeyEvent(shortcutEvent(time, KeyEvent.ACTION_DOWN, KeyEvent.KEYCODE_ESCAPE, 0))
        ic.sendKeyEvent(shortcutEvent(time, KeyEvent.ACTION_UP, KeyEvent.KEYCODE_ESCAPE, 0))
    }

    /**
     * The window is on screen again: the composition takes new state from here
     * on, starting with everything it missed while it was away. Called from
     * both doors, onStartInputView and onWindowShown, because either can be
     * the first one on a given device.
     */
    private fun onScreenAgain() {
        // The floating button lifts above the keyboard and its keyboard
        // action turns into a hide (#697); a drop that put it away lasted
        // until exactly now. Only on a real arrival: this also runs for every
        // new field while the keyboard stays up.
        val arriving = !windowOnScreen
        if (arriving) floatingButtonDismissed = false
        windowOnScreen = true
        KeyboardPassthrough.setKeyboardShown(true)
        syncSummonButton()
        // A tool the floating button asked for while the keyboard was down,
        // now that there is a keyboard for its panel (#755). Posted, not run
        // here: serviceScope is Main.immediate, and run in place the panel it
        // opened was closed again a few lines on by startInputView's "a panel
        // dies with the field", so emoji, clipboard and voice brought up a
        // bare keyboard.
        floatingPendingTool?.let { tool ->
            floatingPendingTool = null
            if (arriving && SystemClock.uptimeMillis() - floatingPendingAt < FLOATING_TOOL_WAIT_MS) {
                serviceScope.launch(Dispatchers.Main) { runToolFromKey(tool) }
            }
        }
        // Held up over the settings app with no field there (pinned or
        // summoned): it opens its test field, the way its keyboard button
        // would. Only then: a keyboard that is merely still on screen while
        // one of its own buttons opens the settings app (a tool's hold, the
        // plugins manager) also lands on a null field of this package for a
        // moment, and opening the test field under it made the keyboard
        // bounce up and down (#725).
        KeyboardControls.setUpOverOwnApp(
            pinnedNow() && isNullField() && currentInputEditorInfo?.packageName == packageName,
        )
        // The summon that asked for this got what it wanted.
        if (summonedNow()) {
            summonHeld = true
            if (summonPackage == null) summonPackage = currentInputEditorInfo?.packageName
        }
        _shownState.value = _uiState.value
        // Asked again on every showing, early enough to beat the first frame:
        // a window that went away may come back with the bar requested again.
        showSystemKeyboardBar(!_uiState.value.settings.layoutBehavior.hideSystemKeyboardBar)
        // Ask for the window's insets afresh (#463): the navigation bar the
        // keyboard pads itself clear of is read from them, and a window coming
        // back from another keyboard must not keep the ones it left with.
        inputRootView?.requestApplyInsets()
        // Nor a height hold learned while it was last up (#669).
        (inputRootView?.parent as? StableMeasureFrame)?.onShownAgain()
    }

    /**
     * The window is really on screen. onStartInputView has normally resumed the
     * owner already; this is the OEM path where a window arrives without one.
     */
    override fun onWindowShown() {
        super.onWindowShown()
        onScreenAgain()
        onKeyguardGone()
        lifecycleOwner.onResume()
        jankMonitor.start(window.window)
    }

    /**
     * The window is off screen — the last callback of a hide, after
     * onFinishInputView has paused the owner. Stopping it here rather than
     * there is what tells the Recomposer and every lifecycle-scoped collector
     * that there is nothing left to keep up to date.
     */
    override fun onWindowHidden() {
        super.onWindowHidden()
        // Off screen: a screenshot from now on has no keyboard in it (#234).
        noteBoardTop(0)
        // Nothing to draw from here until the window comes back, so the
        // composition stops being handed new state — see [_shownState].
        windowOnScreen = false
        KeyboardPassthrough.setKeyboardShown(false)
        keyguardWatchJob?.cancel()
        forcedShowUp = false
        lifecycleOwner.onStop()
        jankMonitor.stop()
        // A drop made while the keyboard was up lasted until now.
        floatingButtonDismissed = false
        // A chat name the model proposed on the keyboard's chat and nobody
        // answered is declined as the keyboard goes (#882). Only from the
        // panel: the app's own chat types with this keyboard too, and hiding
        // it there is not an answer to anything.
        if (_uiState.value.aiChatShown) AiChatController.declineRenameAsk()
        syncSummonButton()
        KeyboardControls.setUpOverOwnApp(false)
    }

    override fun onFinishInputView(finishingInput: Boolean) {
        // Before the base class lets go of the connection: the address is
        // read off the field that is closing.
        rememberTypedEmail()
        rememberTypedNumber()
        super.onFinishInputView(finishingInput)
        keyboardVisible = false
        // A continuation asked for in the closing field has nowhere to go.
        clearAiSuggest()
        // A speed test under way when the keyboard goes has nobody watching it.
        if (speedTestDelegate.isInitialized()) speedTest.cancel()
        // Keys held for a two-thumb read were meant for the field now closing.
        keysBehindDuet.clear()
        // No finger outlives the window it was on (#743).
        keysTouched = false
        barsTouched = 0
        // Nor does a space a letter could take back, or the band over its pause (#747).
        allUpSpace = null
        if (_uiState.value.allUpCountdown != null) _uiState.update { it.copy(allUpCountdown = null) }
        // The next show is a first show, which the app answers itself.
        boardTopForReveal = -1
        // The next keyboard says which microphone its first dictation uses.
        lastMicNotice = null
        // The drag that put it up cannot finish with the keyboard gone.
        caretMagnifier.stop()
        // Sent copies the app has long since read go from the media cache.
        if (galleryToolDelegate.isInitialized()) galleryTool.onFinish()
        // The ring belongs to the board that is going away: a new session gets
        // a fresh one, seeded where [KeyGridFocus.show] puts it rather than on
        // whatever key the last field was left pointing at.
        panelFocus.keyGrid.reset()
        lifecycleOwner.onPause()
        // The window is gone, so the media-session listener goes with it.
        syncMediaTracking()
        syncKdeConnect()
        syncHomeAssistant()
        // Refilling the pool waits until the keyboard is going away, so a
        // download can never race the first frame of a session.
        topUpBackgroundPool()
        // The key grid publishes its own pass-through rectangle while it is on
        // screen (see KeyRows); the window going away is the one case Compose
        // can miss, and a stale carve-out would keep a slab of the screen from
        // reaching TalkBack. Withdrawn rather than cleared: the grid will not
        // publish it again when the next field brings the same board back.
        KeyboardPassthrough.setKeyboardShown(false)
        stopReadAloud()
        stopReadBack()
        vocabProgress.save()
        // Nothing is showing a vocabulary card once the window is gone; the
        // nudges only need the triggers, which stay. The next card reads the
        // packs again.
        vocabIndex?.releaseRecords()
        // The word card is about a word on a strip that is going away — and
        // its spelling editor owns the keys, so it goes with it (#138).
        if (_uiState.value.wordCard != null || _uiState.value.wordSpell != null) {
            _uiState.update { it.copy(wordCard = null, wordSpell = null) }
        }
        // So are the synonyms: a pick would land in whatever field comes next.
        if (_uiState.value.synonyms != null) closeSynonyms()
        // The chat composer gives the keys back with the window: a keyboard
        // that came up in the next field already swallowing keystrokes would
        // be a trap. The draft stays. The on-device session is left alone — the
        // chat screen in the settings app may be the one holding it, and this
        // keyboard hides and shows under that screen all the time.
        if (_uiState.value.aiChat.composing) {
            _uiState.update { it.copy(aiChat = it.aiChat.copy(composing = false)) }
        }
        // The note editor gives the keys back with the window too (#560); its
        // draft is written first, so nothing typed is lost.
        if (_uiState.value.notes.editing != null) notesFlushEdit(leaveEditor = true)
        // A word still composing settles into the field as typed. Leaving the
        // editor's region active while our mirror is wiped on the next
        // onStartInputView meant the first keystroke after a hide→reshow
        // replaced the stranded region — deleting the half-typed word.
        if (composing.isNotEmpty()) {
            currentInputConnection?.finishComposingText()
            composing = StringBuilder()
            _uiState.update {
                it.copy(composingPreview = "", suggestions = emptyList(), emojiSuggestions = emptyList(), octopus = emptyMap())
            }
        }
        // A pending morse commit timer must not fire into whatever field the
        // user lands on next; a half-typed chord dies with the view too.
        resetChordInputs()
        // Latches die with the keyboard, locked ones included.
        clearModifiers()
        // So does a held Selection mode: the button went with the window, so no
        // release is coming to end it. The sticky mode survives, the same as
        // every other switched-on tool.
        if (_uiState.value.selectionHold) {
            _uiState.update { it.copy(selectionHold = false) }
        }
        selectionTaps.reset()
        selectKeyTaps.reset()
        // The typing speed was the closing field's (#796).
        stopLiveWpm()
        clearRecentBar()
        // And a held trackpad: no release is coming for it either.
        trackpadHeld = false
        // A backspace swipe caught mid-drag by the window going away: the
        // preview it left in the field is the editor's business now, but the
        // offsets it measured describe a session that has ended.
        resetDeleteSwipe()
        resetHardwareKeyState()
        // An open resize session dies with the view, unsaved by design: Done
        // is the only path that persists.
        if (_uiState.value.resize) {
            _uiState.update { it.copy(resize = false) }
        }
        // The keyboard is leaving the screen, so any plugin drawn on it stops
        // here too -- along with the routing that was sending keys to its box.
        stopPlugins()
        // Credentials — and replies to the conversation — for the field just
        // left must not linger over the next one, which may belong to another
        // app entirely. Nor may an inflation still running for it land later.
        inlineResponseGeneration++
        if (_uiState.value.autofillChips.isNotEmpty() ||
            _uiState.value.smartReplyChips.isNotEmpty()
        ) {
            _uiState.update { it.copy(autofillChips = emptyList(), smartReplyChips = emptyList()) }
        }
        // Which voice view the keyboard is leaving on, for the next show to
        // open again (#699). Read before the cancel below settles the session.
        persistentSurface.saveVoice(voiceSurfaceToResume(_uiState.value))
        // The keyboard is going away mid-dictation: release the mic (the
        // privacy indicator must never outlive the keyboard) and keep the
        // partial that was already on screen.
        cancelVoice()
        // The same for a Music ID clip in progress.
        if (musicToolDelegate.isInitialized()) musicTool.release()
        // The language the field asked for dies with the field; leaving it
        // set would apply an ASCII lock or a locale hint to whatever the
        // user types in next.
        fieldLayoutOverride = null
        // Fancy Text is a one-off for most people: one nickname, one message.
        // The switch back is only armed here and runs on the next
        // onStartInputView, which is where a layout change is safe to make.
        if (_uiState.value.settings.layoutBehavior.fancyToolAutoOff &&
            fancyToolReturnLayoutId != null
        ) {
            fancyToolAutoOffPending = true
        }
        // The keyboard going away is the plainest "this text is finished"
        // there is, and the one the request for this asked for by name. Before
        // the saves, so anything it promotes lands in the same write.
        clearLearnOffer()
        clearCorrectionOffer()
        finishRevisionOnLeave()
        flushLearningBuffer()
        // Where the user was, for the keyboard that comes back — which is
        // usually a new process, this one having been stopped in the meantime
        // (issue #227). Read after the closes above, so nothing that did not
        // survive this hide is put back by the next show.
        _uiState.value.let { state ->
            persistentSurface.save(
                panel = state.panel.name.takeIf { panelLayoutPersists(state) },
                layer = state.layoutMode.name.takeIf { currentLayout(state).persistent },
                secondaryLayoutId = state.secondaryLayoutId
                    ?.takeIf { state.layoutMode == LayoutMode.SECONDARY },
            )
        }
        // Off the main thread: the learned-words file alone runs to megabytes,
        // and encoding it here held the main thread for 100-200 ms on every
        // hide after typing (CPH2481, measured). Each store snapshots itself
        // under its own lock, so typing into the next field is safe meanwhile.
        serviceScope.launch(persistDispatcher) { saveLearningStores() }
        // Only a torch this keyboard lit: one switched on from the quick
        // settings tile or the camera app is the user's, and closing the
        // keyboard over it is no reason to put it out (#602).
        if (_uiState.value.settings.sensorTools.flashlightAutoOff && _uiState.value.torchOn && torchLitHere) {
            setTorch(false)
        }
        // Nothing is on screen to need a model loaded. Armed after the saves
        // and before [reshowPinned], which either brings the keyboard back —
        // and [startInputView] disarms it — or leaves it away for good.
        scheduleIdleRelease()
        // A GPU model that failed leaves its memory behind until the process
        // ends; with the keyboard gone, now is when to end it.
        scheduleGpuRecycle()
        // Last: everything above has settled the field the keyboard is
        // leaving, and a pinned keyboard is about to be asked back.
        reshowPinned()
    }

    override fun onDestroy() {
        DebugLog.i("ime", "service destroyed")
        holdMediaFocus(false)
        // The controls promise a keyboard to come back to; without one running
        // they are three buttons that do nothing.
        KeyboardControls.host = null
        KeyboardControls.clear(this)
        KeyboardAutomation.host = null
        // So is the floating button: it is the keyboard's, and another one is
        // in charge now.
        if (floatingButtonDelegate.isInitialized()) floatingButton.hide()
        summonJob?.cancel()
        if (musicToolDelegate.isInitialized()) musicTool.release()
        // Hunspell's dictionaries are native memory the process keeps otherwise.
        hunspellChecker?.second?.close()
        hunspellChecker = null
        divvunChecker?.second?.close()
        divvunChecker = null
        voikkoChecker?.second?.close()
        voikkoChecker = null
        indicXlit?.shutdown()
        indicXlit = null
        if (latinXlitDelegate.isInitialized()) latinXlit.shutdown()
        pluginRuntime?.shutdown()
        pluginRuntime = null
        vocabSpeaker?.shutdown()
        vocabSpeaker = null
        vocabProgress.save()
        KeyboardPassthrough.publishRegion(null)
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            getSystemService(WindowManager::class.java)
                .removeCrossWindowBlurEnabledListener(crossWindowBlurListener)
        }
        powerSaver.stop()
        networkWatcher.stop()
        (getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager)
            .removePrimaryClipChangedListener(clipboardListener)
        KeyboardClipboard.isPrivate = false
        KeyboardClipboard.onPrivateCopy = null
        if (unlockReceiverRegistered) {
            runCatching { unregisterReceiver(unlockReceiver) }
            unlockReceiverRegistered = false
        }
        if (torchCameraId != null) {
            (getSystemService(Context.CAMERA_SERVICE) as CameraManager)
                .unregisterTorchCallback(torchCallback)
        }
        zenObserver?.let { contentResolver.unregisterContentObserver(it) }
        zenObserver = null
        userDictObserver?.let { runCatching { contentResolver.unregisterContentObserver(it) } }
        userDictObserver = null
        // The deferred buzz used to be cancelled by serviceScope.cancel() below;
        // on a Handler it has to be taken off the queue by hand.
        feedbackHandler.removeCallbacks(deferredVibrate)
        // Lets a press already queued play out, then ends the thread.
        feedbackPlayerThread.quitSafely()
        // The link to a paired computer is this service's to hold; the hub
        // outlives it only for as long as a settings screen still wants it.
        KdeConnectHub.release(KdeConnectHub.Reason.PANEL)
        KdeConnectHub.release(KdeConnectHub.Reason.KEYBOARD)
        KdeConnectHub.release(KdeConnectHub.Reason.SERVICE)
        com.wasimaster.wmkeyboard.ime.homeassistant.SmartHomeHub.release(com.wasimaster.wmkeyboard.ime.homeassistant.SmartHomeHub.Reason.PANEL)
        com.wasimaster.wmkeyboard.ime.homeassistant.SmartHomeHub.release(com.wasimaster.wmkeyboard.ime.homeassistant.SmartHomeHub.Reason.KEYBOARD)
        finishRevisionOnLeave()
        flushLearningBuffer()
        // Blocking, and on the same queue as the hide's saves: the process is
        // going, so this waits for a hide's save still in flight and then
        // writes whatever changed since.
        runBlocking(persistDispatcher) {
            saveLearningStores()
            clipboardStore.save()
        }
        micBlockWatcher.stop()
        voiceEngine.cancel()
        whisperRecorder?.let { rec -> whisperRecorder = null; runCatching { rec.stop() } }
        carriedMic?.let { carried -> carriedMic = null; runCatching { carried.recorder.stop() } }
        voiceMicRoute.release()
        voiceMicWatcher.stop()
        mediaController.stop()
        hwRecognizer.close()
        releaseTranslateEngine()
        LocalLlmEngine.release()
        WhisperEngine.release()
        WhisperCpp.release()
        serviceScope.cancel()
        // Before the owner is destroyed: super.onDestroy runs a full input
        // teardown, and onFinishInputView pauses the owner on the way out.
        super.onDestroy()
        lifecycleOwner.onDestroy()
    }

    /**
     * Moves a rotating theme on to its next photo, if one is due.
     *
     * Everything here is local: the decision is a pure function over stored
     * timestamps, and applying it is a file that is already on disk plus one
     * preference write. Nothing touches the network, so this is safe at the
     * moment the keyboard is coming up.
     */
    private fun maybeRotateBackground() {
        val current = _uiState.value.settings
        val photos = current.photoBackground
        if (!photos.rotateEnabled || !userUnlocked) return
        val themeId = current.keyboardThemeId
        if (!photos.rotates(themeId, themeId)) return
        val state = PhotoBackgroundManager.rotationStates.value[themeId]
        val due = isRotationDue(
            interval = photos.interval,
            state = state ?: RotationState(),
            nowEpochMs = System.currentTimeMillis(),
            nowElapsedMs = SystemClock.elapsedRealtime(),
            sessionStarted = true,
        )
        if (!due) return
        serviceScope.launch {
            PhotoBackgroundManager.rotate(
                context = this@WMKeyboardService,
                repository = settingsRepository,
                themeId = themeId,
                current = state,
                wantWide = photos.landscapeOnly,
                sources = photos.sources,
            )
        }
    }

    /**
     * Selects the next theme for an auto theme half that runs at random, if one
     * is due.
     *
     * Called at the same moment as [maybeRotateBackground] and for the same
     * reason: the theme changing under the keys mid-sentence reads as a fault,
     * so a random half moves between sessions and never during one. The whole
     * decision is a pure function over two stored clocks, and applying it is one
     * preference write that the theme provider then crossfades.
     */
    private fun maybeShuffleTheme() {
        val auto = _uiState.value.settings.autoTheme
        val due = isThemeShuffleDue(
            auto = auto,
            nowEpochMs = System.currentTimeMillis(),
            nowElapsedMs = SystemClock.elapsedRealtime(),
            sessionStarted = true,
        )
        if (!due) return
        serviceScope.launch { settingsRepository.shuffleAutoThemeNow() }
    }

    /**
     * Recomputes [dataSaverStatus] for one settings or network emission.
     *
     * Grants are dropped whenever the network itself changes, and only then:
     * a yes given on one connection is an answer about that connection, but
     * re-asking every time a settings save happens to re-emit would make the
     * offer worthless.
     */
    private fun updateDataSaverStatus(
        config: DataSaverSettings,
        network: DeviceNetworkState,
        active: Boolean,
    ) {
        val networkChanged = grantedNetwork != network
        grantedNetwork = network
        dataSaverStatus = dataSaverStatus.copy(
            active = active,
            settings = config,
            grants = if (networkChanged) emptySet() else dataSaverStatus.grants,
        )
    }

    /**
     * The user tapped "use mobile data": [feature] is allowed for the rest of
     * this session, and the ui state is republished so the panel that asked
     * stops asking.
     */
    private fun grantMetered(feature: MeteredFeature) {
        if (dataSaverStatus.allows(feature)) return
        dataSaverStatus = dataSaverStatus.granting(feature)
        _uiState.update { it.copy(dataSaver = dataSaverStatus) }
    }

    /**
     * Turns a retry on a data-saver notice into the grant it means.
     *
     * The notice reuses the panels' existing retry action rather than growing
     * a callback of its own: [ui.KeyboardScreen]'s parameter list is already
     * at the JVM's 64K method ceiling, and a retry on a panel that is only
     * empty because of data saving can mean nothing else.
     */
    private fun grantMeteredForPanel(state: KeyboardUiState) {
        val feature = when (state.panel) {
            PanelMode.GIF -> MeteredFeature.MEDIA_SEARCH
                .takeIf { (state.gif as? MediaUi.Metered)?.canAllow == true }
            PanelMode.STICKER -> MeteredFeature.MEDIA_SEARCH
                .takeIf { (state.sticker as? MediaUi.Metered)?.canAllow == true }
            PanelMode.WEB_SEARCH -> MeteredFeature.WEB_SEARCH.takeIf {
                (state.webSearch as? WebSearchUi.Metered)?.canAllow == true ||
                    (state.imageSearch as? ImageSearchUi.Metered)?.canAllow == true
            }
            else -> null
        } ?: return
        grantMetered(feature)
    }

    /** Refills the rotation pool, if the settings and the network allow it. */
    private fun topUpBackgroundPool() {
        val current = _uiState.value.settings
        val photos = current.photoBackground
        if (!photos.rotateEnabled || !userUnlocked) return
        serviceScope.launch {
            val connectivity = getSystemService(ConnectivityManager::class.java)
            PhotoBackgroundManager.topUpPool(
                context = this@WMKeyboardService,
                settings = photos,
                keys = ToolApiKeys.photoKeys(current),
                sources = ToolApiKeys.photoSources(current),
                conditions = PhotoNetworkConditions(
                    unlocked = userUnlocked,
                    // A build without the internet permission (#292) never
                    // fetches, so it never tops up.
                    online = InternetPermission.granted,
                    metered = runCatching { connectivity?.isActiveNetworkMetered }.getOrNull() ?: true,
                    powerSaving = current.powerSaving.dropBackgroundNetwork,
                    highContrastKeys = current.accessibility.highContrast,
                ),
            )
            PhotoBackgroundManager.prunePool(this@WMKeyboardService, photos)
            // Housekeeping rides along with the top-up, which already only
            // happens as the keyboard is going away.
            PhotoBackgroundManager.sweep(
                context = this@WMKeyboardService,
                repository = settingsRepository,
                themes = current.customThemes,
            )
        }
    }

    override fun onTrimMemory(level: Int) {
        super.onTrimMemory(level)
        // Decoded background photos: a few MB that the next draw can rebuild
        // from the file. Trimmed at every level, since holding them through an
        // idle hour is part of what gets a keyboard killed.
        BackgroundBitmapCache.trim(level)
        @Suppress("DEPRECATION")
        if (level >= ComponentCallbacks2.TRIM_MEMORY_MODERATE) {
            releaseHeavyEngines(onScreen = true)
        }
    }

    /**
     * Frees every optional subsystem that holds real memory: the local model,
     * the transcriber, the translator, the ink recognizer, decoded app icons,
     * media thumbnails and the GIF packs' database handles.
     *
     * [onScreen] says whether to respect the open panel. From trim-memory the
     * keyboard may well be in front of the user, so the panel they are looking
     * at keeps what it needs — dropping the launcher's icons under a scrolling
     * finger would blank the grid and re-decode every tile. From
     * [scheduleIdleRelease] the window is long gone and the stored panel is
     * only what the *next* keyboard will open on, so nothing is spared.
     *
     * Everything here reloads on demand and every `release` is non-blocking —
     * the engines skip the free outright while a generation or a lint is
     * running — so being wrong costs one reload, not a failure.
     */
    private fun releaseHeavyEngines(onScreen: Boolean) {
        val panel = if (onScreen) _uiState.value.panel else null
        // A cached local model pins hundreds of MB to a few GB (issue #476).
        LocalLlmEngine.release()
        WhisperEngine.release()
        WhisperCpp.release()
        // Only between dictations: the program is the running stream's.
        if (asr4allJob?.isActive != true && EtNative.isOpen) {
            serviceScope.launch(EtNative.dispatcher) { if (asr4allJob?.isActive != true) EtNative.release() }
        }
        if (asr4allJob?.isActive != true &&
            (SherpaEngine.isOpen || OmnilingualEngine.isOpen || DictationPunctuation.isOpen)
        ) {
            serviceScope.launch(SherpaNative.dispatcher) {
                if (asr4allJob?.isActive != true) {
                    SherpaEngine.release()
                    OmnilingualEngine.release()
                    DictationPunctuation.release()
                }
            }
        }
        // Strong noise reduction's idle model; a clip recording now keeps its own.
        StrongDenoise.release()
        // Smart Turn's model; the next pause opens it again.
        SmartTurn.release()
        // Reloads on the next translation; the panel's state is untouched.
        if (translateEngineLoaded) OfflineTranslation.release()
        // Vocabulary cards: read back from the pack files on demand.
        if (panel != PanelMode.VOCABULARY) vocabIndex?.releaseRecords()
        // Decoded app icons: megabytes of ARGB the package manager can hand back.
        if (panel != PanelMode.APP_LAUNCHER) launcherIconCache.evictAll()
        // The ink recognizer pins its ML Kit model — tens of megabytes for one
        // script. Rebuilt by the next stroke; `recognize` prepares the runtime.
        if (panel != PanelMode.HANDWRITING) hwRecognizer.close()
        // Open SQLite handles, one per installed GIF pack.
        if (panel != PanelMode.GIF) {
            com.wasimaster.wmkeyboard.core.tools.offlinegif.OfflineGifPacks.releaseDatabases()
        }
        // And one per imported dictionary (#765).
        if (panel != PanelMode.DICTIONARY) {
            com.wasimaster.wmkeyboard.core.tools.yomichan.YomichanDictionaries.releaseDatabases()
        }
        // Media thumbnails: a tenth of the heap, shared by every media panel,
        // so they only go when none of them is the one on screen.
        if (panel == null || panel == PanelMode.NONE) trimMediaImageMemory()
        // The Unicode name index: tens of megabytes of character names, built
        // the first time somebody searched the emoji panel for one. Rebuilt by
        // the next such search.
        if (panel != PanelMode.EMOJI) UnicodeNames.release()
        // The OCR engine's loaded language pack: tens of megabytes of native
        // memory. The scanner panel frees it when it closes, so this is the
        // backstop for the panel never getting the chance — and a no-op where
        // the library never loaded.
        if (panel != PanelMode.OCR) TesseractOcr.release()
        // Harper's rule sets, one per dialect, built on the first lint and
        // until now never freed — and the spell-checker service lints in this
        // process too, so a user who never opened the grammar tool could still
        // be carrying them. No-op when nothing has linted yet.
        if (panel != PanelMode.GRAMMAR) GrammarChecker.release()
        if (!onScreen) BackgroundBitmapCache.evictAll()
    }

    /** Pending [releaseHeavyEngines]; see [scheduleIdleRelease]. */
    private var idleReleaseJob: Job? = null

    /**
     * Arms the idle release: if the keyboard stays away for
     * [IDLE_RELEASE_MS], everything [releaseHeavyEngines] frees is freed.
     *
     * Trim-memory was the only thing that ever did this, and for an input
     * method that is not enough. The system trims *background* processes under
     * pressure, and it is reluctant to pick on the process drawing the
     * keyboard; a user who ran one AI action could sit at a few gigabytes of
     * resident model for hours without the callback ever arriving, which is
     * what issue #476 is reports of. Waiting for the window to go away and
     * then some turns "the system is desperate" into "the user has stopped
     * typing", which is the moment a keyboard should be cheap.
     *
     * The delay is what keeps this off the ordinary path: the keyboard hides
     * every time a field loses focus, so anything short would be releasing
     * models between one text box and the next. Two minutes of *continuous*
     * absence is not app-switching, and [startInputView] cancels on the way
     * back in.
     */
    private fun scheduleIdleRelease() {
        idleReleaseJob?.cancel()
        idleReleaseJob = serviceScope.launch {
            delay(IDLE_RELEASE_MS)
            releaseHeavyEngines(onScreen = false)
            DebugLog.i("ime", "idle: released the heavy engines")
            // A GPU engine released just now may have kept its memory too.
            recycleIfGpuStranded()
        }
    }

    /** Pending [recycleIfGpuStranded]; see [scheduleGpuRecycle]. */
    private var gpuRecycleJob: Job? = null

    /**
     * Arms [recycleIfGpuStranded] for shortly after the keyboard hides, when a
     * GPU model engine has come and gone in this process. Free otherwise: one
     * volatile read.
     */
    private fun scheduleGpuRecycle() {
        if (!LocalLlmEngine.gpuMemoryMayBeStranded() && !LocalLlmEngine.waitsForGpuRestart()) return
        gpuRecycleJob?.cancel()
        gpuRecycleJob = serviceScope.launch {
            delay(GPU_RECYCLE_DELAY_MS)
            recycleIfGpuStranded()
        }
    }

    /**
     * Ends this process when a GPU model engine that is gone left its memory
     * behind. On Mali the OpenCL context LiteRT made outlives the engine, and
     * after one failed run on a CPH2481 (Helio G99) the idle keyboard held
     * 2.2 GB of GL memory while the phone swapped itself to a crawl; nothing
     * short of the process ending gives it back. The system binds the
     * keyboard again on the next field, and [persistentSurface] already plans
     * for a show landing in a new process.
     *
     * The same when Compute = GPU waits for a new process to reach a GGUF
     * model: llama.cpp's GPU build of its library can only load in a process
     * that has not loaded a CPU build yet.
     *
     * Only with the keyboard away, no screen of the app started (they share
     * this process) and no model download running, and only after the stores
     * are on disk.
     */
    private suspend fun recycleIfGpuStranded() {
        val restartForGpu = LocalLlmEngine.waitsForGpuRestart()
        if (!LocalLlmEngine.gpuMemoryMayBeStranded() && !restartForGpu) return
        if (keyboardVisible || StartedActivities.count > 0 || LocalLlmDownloadManager.isBusy) return
        val strandedKb = withContext(Dispatchers.Default) { LocalLlmEngine.strandedGpuMemoryKb() }
        if (strandedKb < GPU_STRANDED_KB && !restartForGpu) return
        DebugLog.i(
            "ime",
            if (strandedKb >= GPU_STRANDED_KB) {
                "recycling the process: ${strandedKb / 1024} MB of GPU memory left by the model"
            } else {
                "recycling the process: Compute = GPU needs llama.cpp's GPU build"
            },
        )
        withContext(persistDispatcher) {
            saveLearningStores()
            clipboardStore.save()
        }
        if (keyboardVisible || StartedActivities.count > 0) return
        android.os.Process.killProcess(android.os.Process.myPid())
    }

    override fun onLowMemory() {
        super.onLowMemory()
        BackgroundBitmapCache.evictAll()
    }

    // ---- key handling ----

    // No vibrate() here: press-time haptics fire from the UI's pointer-down
    // callback (onKeyPressed) so feedback lands on touch, not on release.
    fun onKey(key: Key) = trace(ImeTrace.KEY) { if (!deferBehindDuet(key)) handleKey(key) }

    /**
     * Keys pressed while a two-thumb word's latest gesture is still being
     * read, waiting for that reading in the order they came (#744).
     */
    private val keysBehindDuet = ArrayDeque<Key>()

    /**
     * Holds [key] back while the two-thumb word in progress is still being
     * read, when it may end that word: Space, a mark, Enter, anything but one
     * more letter. Ending it there used to read the whole word again on the
     * main thread ([settleDuet]), a full gesture decode under the key press;
     * now the key waits for the decode already running, as the all-thumbs-up
     * pause does, and goes through once the word on screen is the whole word
     * (#640). Every key after it queues behind it, so the field still reads
     * word, then its space or mark, then whatever came next. A letter with
     * nothing queued is not held: it joins the word and starts a newer read.
     */
    private fun deferBehindDuet(key: Key): Boolean {
        if (keysBehindDuet.isNotEmpty()) {
            keysBehindDuet.addLast(key)
            return true
        }
        if (!duetDecodePending()) return false
        val text = key.output ?: key.label
        if (key.action == KeyAction.Text && text.length == 1 && text[0].isLetter()) return false
        keysBehindDuet.addLast(key)
        serviceScope.launch {
            while (keysBehindDuet.isNotEmpty()) {
                // A letter let through below starts a newer read of the word,
                // which the key after it waits for in turn.
                while (duetDecodePending()) duetJob?.join()
                val next = keysBehindDuet.removeFirstOrNull() ?: break
                trace(ImeTrace.KEY) { handleKey(next) }
            }
        }
        return true
    }

    /** Whether the two-thumb word on screen is behind its gestures, with their read still running. */
    private fun duetDecodePending(): Boolean =
        duetWord.active && duetShownGeneration != duetGeneration && duetJob?.isActive == true

    private fun handleKey(key: Key) {
        // Before the key runs: a space must find the rejection already
        // recorded, or it corrects the restored word straight back.
        if (!key.action.deletesBackward()) settlePendingUndoOnKey(key.action)
        // The strip's remembered numbers were about the caret before this key
        // (#431); its echo re-reads them. A space or an enter ends the run of
        // digits, which is the moment it is worth remembering.
        numberRun = null
        if (numberRunPending && (
                key.action == KeyAction.Space || key.action == KeyAction.Enter ||
                    key.action == KeyAction.Newline || key.action == KeyAction.EditorAction
                )
        ) {
            rememberTypedNumber()
        }
        // Space, backspace and enter on a Keyman layout: the layer may say what
        // modifiers the rules see them with and where they lead, and the
        // keyboard's PostKeystroke group runs after them as after every other
        // keystroke — a space that ends a sentence is where one puts shift
        // back on. A Keyman key runs all of that itself, after its own rules.
        val frameId = when (key.action) {
            KeyAction.Space -> "K_SPACE"
            KeyAction.Delete -> "K_BKSP"
            KeyAction.Enter, KeyAction.Newline, KeyAction.EditorAction -> "K_ENTER"
            else -> null
        }
        val frame = frameId?.let { currentLayout(_uiState.value).keymanFrames[it] }
        val keymanStart = if (frameId != null && (frame != null || keymanSession != null)) activeKeymanLayer() else null
        pendingKeymanFrame = frame
        keymanFrameRuleLayer = false
        try {
            dispatchKey(key)
        } finally {
            pendingKeymanFrame = null
        }
        if (keymanStart != null) {
            // A rule's own `layer()` beats the key's, as in KeymanWeb.
            val keyLayer = frame?.nextLayer.takeIf { !keymanFrameRuleLayer }
            keyLayer?.let { switchToKeymanLayer(it) }
            runKeymanPostKeystroke(keymanStart, changed = keyLayer != null || keymanFrameRuleLayer)
        }
    }

    /** The frame key being pressed, while it is: see [onKey]. */
    private var pendingKeymanFrame: KeymanTarget? = null

    /** Whether the rules picked a layer for the frame key being pressed. */
    private var keymanFrameRuleLayer = false

    private fun dispatchKey(key: Key) {
        // A 🌐 tap straight out of typing is a thumb that missed the spacebar
        // or the comma, when the user asked for that to be ignored. Dropped
        // before anything else runs, so it costs the field nothing at all.
        if (key.action == KeyAction.LanguageSwitch &&
            globeTapGuarded(
                SystemClock.uptimeMillis(),
                lastTypedKeyAt,
                _uiState.value.settings.layoutBehavior.globeTypingGuardMs,
            )
        ) {
            return
        }
        if (key.action.typesIntoField()) lastTypedKeyAt = SystemClock.uptimeMillis()
        stopVoiceForManualInput()
        // Armed by the enter key itself, below, and spent by the caret update
        // that answers it. Cleared here so a field that reports no update at
        // all cannot leave it armed over the next word the user types.
        wordEndedByEnter = false
        // Typing deliberately does NOT dismiss the recent-copy strip chip. It
        // used to (Gboard style), but the common case is typing a few words and
        // *then* wanting the copy — a username before a pasted password, a
        // sentence before a pasted link. The chip has its own dismiss button and
        // shares the strip with candidates, so it costs nothing to leave up.
        // Shift keeps the gesture word so alternates can be re-cased;
        // Delete keeps it so one backspace can undo the whole swipe.
        if (key.action != KeyAction.Shift && key.action != KeyAction.Delete) {
            lastGestureWord = null
        }
        // The auto-space cancel is a one-shot for the shift press immediately
        // after the ". " — any other key means the user typed on past it.
        if (key.action != KeyAction.Shift) pendingAutoSpace = false
        // Any other key ends a run of 🌐 presses: tap 🌐, type a word, tap 🌐
        // again means "go back", not "one further along" (#311).
        if (key.action != KeyAction.LanguageSwitch) settleLanguageBurst()
        // Spent by the key that ended the word it was armed for. A commit made
        // from somewhere else — a panel opening, text inserted by a tool — must
        // not leave one behind for whatever key comes next.
        swallowTerminatorAfterCommit = false
        // Both records of a space the keyboard typed — the one that ended a
        // word, and the one that followed a mark — survive the same three sorts
        // of key. A Text key, where a closing mark takes the space back and
        // anything else spends it (see [processTypedText]); Space, which is
        // swallowed rather than doubled; and any key that types nothing at all,
        // which is what puts the symbols page back in reach: `:` and `/` live
        // there, so reaching either meant a `?123` press, and that press used to
        // count as typing on past the space (issue #34).
        //
        // The Text case is cleared by [processTypedText] itself as well, since
        // letters and marks are the same action and only the text says which
        // one this is.
        //
        // No space, as a key, a flick or its hold, is the key those spaces are
        // kept for: it is what takes the keyboard's space back out (#939).
        val noSpaceKey = (key.action as? KeyAction.Edit)?.op.let {
            it == TextEditAction.NO_SPACE || it == TextEditAction.NO_SPACE_NEXT
        }
        if (key.action != KeyAction.Text && key.action != KeyAction.Space &&
            !key.action.commitsNoText() && !noSpaceKey
        ) {
            pendingPunctuationSpace = false
            pendingWordSpace = false
        }
        // A pending Ctrl/Alt/Meta turns the next key into a shortcut, so it is
        // intercepted ahead of the normal dispatch: KeyAction.Text would
        // otherwise push the letter through the composing buffer and Ctrl+C
        // would type a "c". Modifier keys fall through so Ctrl and Alt can be
        // latched together, and so does Shift, which composes rather than fires.
        val modifiers = _uiState.value.modifiers
        val isShortcut = !modifiers.isEmpty &&
            key.action !is KeyAction.Mod &&
            key.action != KeyAction.Shift
        if (isShortcut) {
            // While the keys are typing on a paired computer, a chord is the
            // computer's chord: Ctrl+C there copies there (#285).
            if (kdeSendChord(key, modifiers)) {
                consumeModifiers()
                consumeShift()
                return
            }
            // The result is deliberately ignored: a character with no keycode
            // has no event to send, and the latch is spent either way so the
            // user can see the modifier was used up rather than left armed.
            sendShortcut(key, modifiers)
            consumeModifiers()
            consumeShift()
            return
        }
        // A pending morse sequence commits before any non-morse key acts, so
        // "··· <space>" spells "s " rather than losing the s — the same
        // flush-before contract the composing buffer has. Delete stays out of
        // it: it edits the pending sequence itself (see [onDelete]).
        if (morse.isPending &&
            key.action != KeyAction.MorseDot && key.action != KeyAction.MorseDash &&
            key.action != KeyAction.Delete && key.action != KeyAction.Shift
        ) {
            commitMorse()
        }
        // Any other key ends a multitap run; space decides for itself, because on
        // a Cheonjiin pad ending the run is what it is pressed for.
        val cycles = key.multitap.isNotEmpty() && (key.action == KeyAction.Text || key.action is KeyAction.KeymanKey)
        if (key.action != KeyAction.Space && !cycles) {
            multitap.end()
        }
        when (key.action) {
            KeyAction.Text -> if (key.multitap.isNotEmpty()) onMultitapKey(key) else onTextKey(key)
            // A key of a converted Keyman layout, with no rule engine attached
            // yet. It types its own cap, which is what it would do anyway on a
            // device that has the layout but not the keyboard's rules — the
            // grid stays an ordinary usable keyboard rather than going dead.
            is KeyAction.KeymanKey -> if (key.multitap.isNotEmpty()) {
                onKeymanMultitapKey(key)
            } else {
                onKeymanKeyPress(key, key.action as KeyAction.KeymanKey)
            }
            KeyAction.Shift -> onShift()
            KeyAction.CapsLock -> onCapsLock()
            KeyAction.Delete -> onDelete()
            KeyAction.ForwardDelete -> onForwardDelete()
            KeyAction.Space -> {
                onSpace()
                returnFromSymbolsAfterSpace()
            }
            KeyAction.Enter -> onEnter()
            // The enter key's long-press alternate, and any layout that binds a
            // newline key of its own: a line break, never the field's action.
            KeyAction.Newline -> onNewline()
            // The enter key's hold while a shift has turned the key into a line
            // break: the field's action, which the shift would otherwise block.
            KeyAction.EditorAction -> onEditorAction()
            KeyAction.Symbols -> toggleSymbols()
            KeyAction.Letters -> _uiState.update {
                it.copy(layoutMode = LayoutMode.LETTERS, fnLocked = false, fnReturn = null)
            }
            KeyAction.LanguageSwitch -> switchLanguage()
            KeyAction.InputMethodPicker -> showInputMethodPicker()
            is KeyAction.SwitchInputMethod -> switchToInputMethod((key.action as KeyAction.SwitchInputMethod).id)
            KeyAction.Emoji -> onPanelChange(emojiOpenerTarget(), haptic = false)
            // The toolbox, from a key (#970): what the toolbar's launcher opens.
            KeyAction.Toolbox -> onPanelChange(PanelMode.TOOLBOX, haptic = false)
            // Produced only by a long-press on ?123 when the opt-in is set.
            KeyAction.Numpad -> {
                releaseUserShift()
                onPanelChange(PanelMode.NUMPAD, haptic = false)
            }
            // A key — or a long-press alternate — bound to a tool: voice, the
            // edit pad, the clipboard. Runs whether or not the tool is on the
            // toolbar; see [runToolFromKey].
            is KeyAction.Tool -> runToolFromKey((key.action as KeyAction.Tool).tool)
            // One of the user's secondary layouts, shown over the letters the
            // way ?123 shows the symbols; a second press takes it down again.
            is KeyAction.Layout -> openSecondaryLayout((key.action as KeyAction.Layout).id)
            // A page key of a paginated layout: one of this layout's own extra
            // grids, in place of the letters (issue #498).
            is KeyAction.LayerSwitch -> openNamedLayer((key.action as KeyAction.LayerSwitch).layer)
            // One of the user's keyboard modes, the Modes panel's pick in one
            // press; a second press goes back to automatic.
            is KeyAction.Mode -> onModeKey((key.action as KeyAction.Mode).id)
            is KeyAction.Mod -> onModifier((key.action as KeyAction.Mod).key)
            KeyAction.KanaVariant -> cycleKanaVariant()
            // The 나랏글 pad's 획추가 and 쌍자음 keys (#599).
            KeyAction.AddStroke -> rewriteLastJamo { buffer, composer ->
                HangulStrokes.addStroke(buffer, vowelPairs = composer === NaratgeulComposer)
            }
            KeyAction.DoubleConsonant -> rewriteLastJamo { buffer, composer ->
                HangulStrokes.doubleConsonant(buffer, vowelPairs = composer === NaratgeulComposer)
            }
            // A syllable picked from a 九宫格 pad's reading column (#635).
            KeyAction.ReadingColumn -> pickConversionReading(key.output.orEmpty())
            // The Simplified/Traditional switch on the Pinyin '词 key's hold (#962).
            KeyAction.HanScript -> onTraditionalOutputToggle()
            KeyAction.Fn -> onFn()
            is KeyAction.BrailleDot -> onBrailleDot(key.action as KeyAction.BrailleDot)
            KeyAction.MorseDot -> onMorseSignal(dash = false)
            KeyAction.MorseDash -> onMorseSignal(dash = true)
            // A key carrying its own modifiers, so it fires with no latch. An
            // arrow, Home or End goes to the keyboard's own field first while
            // one has the keys (#414): the clip editor's caret, not the app's.
            is KeyAction.SendKey -> {
                val send = key.action as KeyAction.SendKey
                if (send.isShiftEnter()) {
                    // Enter tapped under a held shift, or a drag off shift onto
                    // it: Enter itself with the shift held, so the word ends,
                    // autocorrect runs, and the field decides between a line
                    // break and its action the way onEnter always does.
                    onEnter(heldShift = true)
                } else if (!captureCaretKeyCode(send.keyCode)) {
                    sendShortcut(key, Modifiers.None)
                }
            }
            // Fire the user's broadcast; types nothing.
            is KeyAction.Broadcast -> sendKeyBroadcast((key.action as KeyAction.Broadcast).action)
            // A text-editing key on a panel layout (or on a typing grid). The
            // key has already buzzed on the way down, so the handler must not.
            // Select goes the long way round for its tap ladder (issue #41);
            // everything else is one operation per press.
            is KeyAction.Edit -> {
                val op = (key.action as KeyAction.Edit).op
                // On the typing grid a Shift the user put up turns a move into
                // Shift+Arrow, as it does for an arrow key sent as a key event
                // (#970). Not on a panel grid, which has no Shift of its own to
                // read: one left up there is a leftover (see [onCursorTool]).
                val extend = _uiState.value.panel == PanelMode.NONE && _uiState.value.shiftSelectsText
                if (op == TextEditAction.SELECT) onSelectKeyTap() else onTextEdit(op, extendSelection = extend, haptic = false)
            }
            // A panel component's cell. The panel grid never dispatches one;
            // this is the exhaustive `when` insisting the case be decided.
            is KeyAction.Field -> Unit
            // A deliberate gap in the grid, and a key from a build that knows an
            // action this one does not. Both swallow the tap: a custom layout is
            // repaired before it can be enabled, so neither should reach a
            // keyboard the user is typing on.
            KeyAction.None, is KeyAction.Unknown -> Unit
        }
        // A one-shot Fn springs back after the key it modified, the same way an
        // armed shift is spent. After dispatch, not before, so the key that
        // fires is the Fn layer's key and not the one it replaced.
        if (key.action != KeyAction.Fn) consumeFn()
    }

    private var lastFnTapTime = 0L

    /**
     * Tap switches to the Fn layer for one key and springs back; a quick second
     * tap sticks. Springing back is what makes a one-off Esc or F5 cheap — the
     * common case is a single function key, not a run of them.
     */
    private fun onFn() {
        val now = System.currentTimeMillis()
        val doubleTap = now - lastFnTapTime < SHIFT_DOUBLE_TAP_MS
        lastFnTapTime = now
        _uiState.update {
            when {
                // A layout can be shared without its Fn layer, or the layer
                // deleted while a key pointing at it survives. Do nothing rather
                // than switch to a grid that is really a copy of the letters.
                it.layouts.fn == null -> it
                it.layoutMode == LayoutMode.FN && doubleTap -> it.copy(fnLocked = true)
                it.layoutMode == LayoutMode.FN -> it.copy(
                    layoutMode = it.fnReturn ?: LayoutMode.LETTERS,
                    fnLocked = false,
                    fnReturn = null,
                )
                else -> it.copy(
                    layoutMode = LayoutMode.FN,
                    fnReturn = it.layoutMode,
                    fnLocked = false,
                )
            }
        }
    }

    private fun consumeFn() {
        _uiState.update {
            if (it.layoutMode != LayoutMode.FN || it.fnLocked) {
                it
            } else {
                it.copy(layoutMode = it.fnReturn ?: LayoutMode.LETTERS, fnReturn = null)
            }
        }
    }

    private val modifierTapTimes = EnumMap<ModifierKey, Long>(ModifierKey::class.java)

    /**
     * The same three-state gesture as [onShift], reusing its double-tap window.
     *
     * A timer-free OFF → ARMED → LOCKED → OFF cycle was the alternative and was
     * rejected: arming Ctrl and immediately changing your mind would leave it
     * *locked*, which is the one state where every following letter silently
     * becomes a shortcut.
     */
    private fun onModifier(key: ModifierKey) {
        val now = System.currentTimeMillis()
        val doubleTap = now - (modifierTapTimes[key] ?: 0L) < SHIFT_DOUBLE_TAP_MS
        modifierTapTimes[key] = now
        _uiState.update { state ->
            val current = state.modifiers[key]
            val next = when {
                doubleTap && current != ModifierState.LOCKED -> ModifierState.LOCKED
                current == ModifierState.OFF -> ModifierState.ARMED
                else -> ModifierState.OFF
            }
            state.copy(modifiers = state.modifiers.with(key, next))
        }
    }

    /** Twin of [consumeShift]: drops the armed latches, keeps the locked ones. */
    private fun consumeModifiers() {
        _uiState.update {
            if (it.modifiers.isEmpty) it else it.copy(modifiers = it.modifiers.consumed())
        }
    }

    /** Clears every latch, locked ones included. */
    private fun clearModifiers() {
        modifierTapTimes.clear()
        _uiState.update {
            if (it.modifiers == Modifiers.None) it else it.copy(modifiers = Modifiers.None)
        }
    }

    /**
     * Sends [key] as a hardware-style key event with [modifiers] and any pending
     * shift folded in. Returns false when the key has no keycode to send, so the
     * caller decides what to do with the keystroke rather than this guessing.
     *
     * Modifiers are wrapped as real KEYCODE_CTRL_LEFT down/up pairs rather than
     * sent as bare meta flags — the same lesson [sendEditorKey] already learned
     * for shift, since TextView reads modifier state off the modifier key's own
     * events rather than off getMetaState().
     */
    /**
     * Fire a [KeyAction.Broadcast] key's intent (A62). Wrapped defensively: a
     * malformed action or a locked-down OEM must never take the keyboard down,
     * and a blank action is a no-op. The keyboard's own package is set as the
     * target when a receiver in it exists is irrelevant here — the intent is
     * left implicit so any app's registered receiver can observe it, which is
     * the automation use case (Tasker et al.).
     */
    private fun sendKeyBroadcast(action: String) {
        val trimmed = action.trim()
        if (trimmed.isEmpty()) return
        runCatching { sendBroadcast(android.content.Intent(trimmed)) }
    }

    private fun sendShortcut(key: Key, modifiers: Modifiers): Boolean {
        val ic = currentInputConnection ?: return false
        val state = _uiState.value
        val shift = state.shiftState != ShiftState.OFF

        val action = key.action
        val explicit = action as? KeyAction.SendKey

        // Ctrl+A/C/V/X have a first-class InputConnection route that works in
        // WebViews and Compose text fields, where a raw Ctrl+C reaches nothing.
        // The choice has to be made here rather than after the send:
        // InputConnection.sendKeyEvent reports that an event was queued, never
        // that anything acted on it, so "send it and check" cannot be written.
        //
        // Ctrl arrives two ways: latched by a press on the modifier key, or
        // written into the key itself — a layout's own Ctrl+C key, and the chord
        // a modifier drag builds (issue #67). Both take this route, or the drag
        // would be the one Ctrl+C on the keyboard that copies nothing in a
        // Compose field.
        val ctrlHeld = modifiers.ctrl != ModifierState.OFF ||
            ((explicit?.meta ?: 0) and KeyEvent.META_CTRL_ON) != 0
        if (ctrlHeld && !state.settings.rawClipboardShortcuts) {
            clipboardShortcutFor(key)?.let { onClipboardKey(it); return true }
        }

        // KEYCODE_UNKNOWN means "work it out from the label". That is how a
        // chord built in the composable names a text key: the character map that
        // answers "which key writes a c" is loaded here, not up there. A layout
        // that stored a zero keycode meant nothing by it either — the event it
        // sent was inert — so nothing that used to work changes.
        val code = explicit?.keyCode?.takeIf { it != KeyEvent.KEYCODE_UNKNOWN }
            ?: keyCodeForChar((key.output ?: key.label).singleOrNull() ?: return false)
            ?: return false

        val caret = code in CARET_KEY_CODES
        if (caret) {
            endCompositionForCaretKey(ic)
            lastCaretScrubMs = SystemClock.uptimeMillis()
        } else {
            commitComposing(ic, autocorrect = false)
        }
        lastGestureWord = null
        var meta = modifiers.metaFlags() or (explicit?.meta ?: 0)
        // A layout's own arrow key (or Home/End/PageUp/PageDown) extends the
        // selection under selection mode or a shift the user put up, the same as
        // the toolbar's cursor tools and the spacebar scrub. A shift nobody
        // pressed is excluded there, and only there: on an arrow it would turn a
        // tap at a sentence start into a selection the next keystroke overwrites,
        // while on a letter it is the auto-capital that was asked for.
        val shifted = if (caret) state.caretExtendsSelection else shift
        if (shifted) meta = meta or KeyEvent.META_SHIFT_ON or KeyEvent.META_SHIFT_LEFT_ON
        if (caret && shifted) {
            noteSelectionAnchor()
            // Shift+Up/Down in a one-line field selects to its start or end,
            // as a desktop text box does; the arrow itself stepped into a
            // search box's dropdown or out of the field (#613).
            val vertical = code == KeyEvent.KEYCODE_DPAD_UP || code == KeyEvent.KEYCODE_DPAD_DOWN
            val chord = KeyEvent.META_CTRL_ON or KeyEvent.META_ALT_ON or KeyEvent.META_META_ON
            if (vertical && meta and chord == 0 &&
                extendSelectionToEdgeDirectly(ic, up = code == KeyEvent.KEYCODE_DPAD_UP)
            ) {
                return true
            }
        }

        // Press order mirrors a hardware keyboard: modifiers down outermost and
        // released in reverse, so an editor that pairs down and up events never
        // ends up with a modifier still held after the shortcut.
        val holds = buildList {
            if (meta and KeyEvent.META_CTRL_ON != 0) add(KeyEvent.KEYCODE_CTRL_LEFT)
            if (meta and KeyEvent.META_ALT_ON != 0) add(KeyEvent.KEYCODE_ALT_LEFT)
            if (meta and KeyEvent.META_META_ON != 0) add(KeyEvent.KEYCODE_META_LEFT)
            if (meta and KeyEvent.META_SHIFT_ON != 0) add(KeyEvent.KEYCODE_SHIFT_LEFT)
        }
        val time = SystemClock.uptimeMillis()
        for (hold in holds) ic.sendKeyEvent(shortcutEvent(time, KeyEvent.ACTION_DOWN, hold, meta))
        ic.sendKeyEvent(shortcutEvent(time, KeyEvent.ACTION_DOWN, code, meta))
        ic.sendKeyEvent(shortcutEvent(time, KeyEvent.ACTION_UP, code, meta))
        for (hold in holds.asReversed()) {
            ic.sendKeyEvent(shortcutEvent(time, KeyEvent.ACTION_UP, hold, meta))
        }
        return true
    }

    /** The clipboard action Ctrl plus this key stands for, if any. */
    private fun clipboardShortcutFor(key: Key): ClipboardKeyAction? =
        when ((key.output ?: key.label).lowercase()) {
            "a" -> ClipboardKeyAction.SELECT_ALL
            "c" -> ClipboardKeyAction.COPY
            "v" -> ClipboardKeyAction.PASTE
            "x" -> ClipboardKeyAction.CUT
            else -> null
        }

    /**
     * FLAG_SOFT_KEYBOARD keeps apps from dropping out of touch mode — which
     * moves focus and hides the caret — the way a hardware keypress does, and
     * the virtual device id matches the character map the keycodes came from.
     * The two older senders ([onUndoRedo], [sendEditorKey]) omit these and are
     * deliberately left alone rather than changed as a side effect of this.
     */
    private fun shortcutEvent(time: Long, action: Int, code: Int, meta: Int) = KeyEvent(
        time, time, action, code, 0, meta,
        KeyCharacterMap.VIRTUAL_KEYBOARD, 0,
        KeyEvent.FLAG_SOFT_KEYBOARD or KeyEvent.FLAG_KEEP_TOUCH_MODE,
    )

    /**
     * Keycode for a character, or null when the virtual keyboard's map has none.
     *
     * ASCII letters and digits are answered by arithmetic — KEYCODE_A..Z and
     * KEYCODE_0..9 are contiguous blocks, and they cover essentially every real
     * shortcut — which keeps a JNI call off the keystroke path. Everything else
     * goes through KeyCharacterMap, whose getEvents() documents itself as
     * unsuitable for text entry; it is used here purely as a character-to-keycode
     * lookup, which is what it is actually good at.
     *
     * Characters it cannot map (Bengali letters, ৳, the combining accents) return
     * null and the keystroke is dropped. Committing the text anyway was the
     * alternative and was rejected: a Ctrl press that quietly types "ব" into a
     * document is worse than one that visibly does nothing.
     */
    private fun keyCodeForChar(char: Char): Int? {
        val lower = char.lowercaseChar()
        if (lower in 'a'..'z') return KeyEvent.KEYCODE_A + (lower - 'a')
        if (lower in '0'..'9') return KeyEvent.KEYCODE_0 + (lower - '0')
        val events = runCatching { virtualKeyMap.getEvents(charArrayOf(lower)) }
            .getOrNull() ?: return null
        return events.firstOrNull {
            it.action == KeyEvent.ACTION_DOWN && !KeyEvent.isModifierKey(it.keyCode)
        }?.keyCode
    }

    /**
     * Loaded once: KeyCharacterMap.load crosses into native code, and the
     * BUILT_IN_KEYBOARD device's map can legitimately be empty — which is the
     * case the virtual device id exists to avoid.
     */
    private val virtualKeyMap: KeyCharacterMap by lazy {
        KeyCharacterMap.load(KeyCharacterMap.VIRTUAL_KEYBOARD)
    }

    /**
     * Called from the popup with an alternate character. Routed through [onKey]
     * rather than straight to [onTextKey] so an alternate picked under a latched
     * Ctrl behaves like the base key instead of typing itself.
     */
    fun onText(text: String) {
        vibrate()
        onKey(Key(label = text))
    }

    /**
     * A tap of a [Key.multitap] key: the key itself when it starts a run, and
     * otherwise the next entry of its cycle in place of what the tap before it
     * typed — ㄱ, ㅋ, ㄲ on a Cheonjiin consonant, `.` `,` `?` `!` on Samsung's
     * punctuation key (discussion #372).
     *
     * The previous step is only taken back if it is still exactly what sits at
     * the end of the buffer or in front of the caret. When it is not — the
     * field changed under the run — the tap starts a new run instead of
     * deleting something the user did not type with this key.
     */
    private fun onMultitapKey(key: Key) {
        val now = SystemClock.uptimeMillis()
        var tap = multitap.press(key, now)
        var fromField = false
        if (tap.replaces != null) {
            val taken = multitapWrote?.let { takeBackMultitapStep(it) }
            if (taken == null) tap = multitap.restart(key, now) else fromField = taken
        }
        // Later steps are their own text: the key's shift label belongs to the
        // key, not to every letter its cycle passes through.
        val step = if (tap.replaces == null) key else key.copy(output = tap.text, shiftLabel = null, multitap = emptyList())
        multitapWrote = keyOutput(step, _uiState.value)
        onTextKey(step)
        if (fromField) {
            // The step taken back may have ended a sentence and armed a capital
            // that the step replacing it (`.` becoming `,`) does not earn.
            _uiState.update {
                if (it.shiftState == ShiftState.ON && !it.shiftPressedByUser) {
                    it.copy(shiftState = autoCapitalizeShift())
                } else {
                    it
                }
            }
        }
    }

    /**
     * Removes [wrote], the previous step of a multitap run, from the end of the
     * composing buffer or else from in front of the caret. Null when it is in
     * neither place; otherwise whether it came out of the field.
     */
    private fun takeBackMultitapStep(wrote: String): Boolean? {
        // A keyboard-owned field has the keys, so the step is in its buffer.
        if (_uiState.value.captureTarget() != null) return takeBackCaptureMultitapStep(wrote)
        val ic = currentInputConnection ?: return null
        if (composing.isNotEmpty()) {
            if (!composing.endsWith(wrote)) return null
            // The same bookkeeping a backspace does on the buffer: the touch,
            // key and hint twins stay one entry per buffer character.
            val length = wrote.length
            composing.setLength(composing.length - length)
            repeat(length) { composingTouch.removeLastOrNull() }
            repeat(length) { composingKeys.removeLastOrNull() }
            repeat(length) { composingHints.removeLastOrNull() }
            ambiguousReading = null
            // A step that was the whole buffer (ㄱ becoming ㅋ as the first
            // letter) leaves the region on screen for the next step to
            // overwrite. Writing the empty buffer out ends the composition, and
            // its echo — caret at the word's start, no region — arrives after
            // the next step is already in the buffer and reads as the editor
            // throwing the word away: the buffer is dropped, the consonant is
            // committed bare, and the vowel after it no longer joins it (#598).
            if (composing.isNotEmpty()) updateComposingText(ic)
            return false
        }
        val before = ic.getTextBeforeCursor(wrote.length + 1, 0)?.toString() ?: return null
        val length = when {
            before.endsWith(wrote) -> wrote.length
            // The space the auto-space rule typed after a `.`: it goes with the
            // `.`, and the step replacing it earns its own if it is owed one.
            pendingPunctuationSpace && before.endsWith("$wrote ") -> wrote.length + 1
            else -> return null
        }
        pendingPunctuationSpace = false
        pendingWordSpace = false
        revision?.expectDelete(length, 0)
        if (expectedSelStart >= 0) noteDeletedForLearning(expectedSelStart - length, expectedSelStart)
        ic.deleteSurroundingText(length, 0)
        syncPreviousWordFromField(ic)
        return true
    }

    private fun onTextKey(key: Key) {
        val output = keyOutput(key, _uiState.value)
        // What this key could have meant, for the append to pair with the
        // character it commits — the twin of [pendingTouch], and set here for
        // the same reason: the key is known at the press and gone by the time
        // the text reaches the buffer. Null for an ordinary key, and null for
        // an alternate picked out of a popup (which arrives as a synthetic
        // one-character key), so a long press spells a letter outright on a
        // board that otherwise guesses.
        pendingKeyLetters = key.letterSet().takeIf { it.length > 1 }
        // Its corner hint too, for the number prediction (#181) — read off the
        // key as the layout rewrote it, so a number row that is showing has
        // already taken the digits away and there is nothing to read. Nothing
        // at all from a key whose hold is spoken for: the digit is a promise
        // the popup keeps, and a key that repeats instead never opens one.
        pendingKeyHint = key.longPress.firstOrNull()
            ?.removePrefix(VERBATIM_DIGITS)
            ?.takeIf { key.opensAlternatesPopup() }
        // No space armed for this key (#863) is spent by it.
        unspacedKey = _uiState.value.noSpaceArmed
        if (unspacedKey) setNoSpaceArmed(false)
        // A converted Keyman layout owns its own dead keys, in its own context,
        // where its rules can match them. Running ours as well would apply an
        // accent twice.
        try {
            processTypedText(output, applyDeadKeys = keymanSession == null)
        } finally {
            unspacedKey = false
        }
        returnFromSymbolsAfter(output)
    }

    /**
     * One key of a converted Keyman layout, in KeymanWeb's order: the rules
     * first, then the key's own `nextlayer` — which a rule's `layer()`
     * overrides, because KeymanWeb applies the rule's store write after the
     * key's switch — then the keyboard's `begin PostKeystroke` group.
     *
     * With no rules on the device the key types its fallback and still switches
     * layers, so the grid stays an ordinary usable keyboard.
     *
     * True when the key went down that ordinary path, through [onTextKey],
     * which a multitap run needs to know to take it back again.
     */
    private fun onKeymanKeyPress(key: Key, keyman: KeyAction.KeymanKey): Boolean {
        val startLayer = activeKeymanLayer()
        if (keyman.isLayerSwitch) {
            switchToKeymanLayer(keyman.nextLayer ?: return false)
            runKeymanPostKeystroke(startLayer, changed = true)
            return false
        }
        val outcome = runKeymanRules(keyman)
        var ordinary = false
        if (outcome == null) {
            if (!typeKeymanFallback(key)) {
                onTextKey(key)
                ordinary = true
            }
        } else {
            // The engine typed instead of [processTypedText], which is where a
            // Text key normally spends these. Leaving them armed would hand a
            // later key a space it did not earn.
            pendingWordSpace = false
            pendingPunctuationSpace = false
        }
        val target = outcome?.layer ?: keyman.nextLayer
        when {
            target != null -> switchToKeymanLayer(target)
            // Our shift is one-shot, like every other layout's here. A keyboard
            // that decides for itself when shift lets go does so in its
            // PostKeystroke group, and is left to.
            keymanSession?.processor?.hasPostKeystroke != true -> consumeShift()
        }
        runKeymanPostKeystroke(startLayer, changed = target != null)
        return ordinary
    }

    /**
     * A tap of a Keyman key with a repeated-tap cycle, KeymanWeb's way: the
     * first tap is the key itself, and each later tap takes the previous one
     * back out, rewinding the engine's context to what it was before the run
     * began, deadkeys included, then presses the cycle's next key through the
     * rules as if it were the first thing typed there. A step that names no
     * layer of its own goes back to the layer the run began on.
     *
     * The previous tap is only taken back when it is still exactly what sits
     * behind the caret. When it is not, the tap starts a new run, as on a
     * plain [Key.multitap] key ([onMultitapKey]).
     */
    private fun onKeymanMultitapKey(key: Key) {
        val now = SystemClock.uptimeMillis()
        var tap = multitap.press(key, now)
        val ic = currentInputConnection
        // One batch for the take-back and the step, so the editor reports one
        // caret move, where the step left it, and the engine knows it for its
        // own echo rather than calling its context stale.
        ic?.beginBatchEdit()
        try {
            if (tap.replaces != null && !takeBackKeymanMultitapStep()) tap = multitap.restart(key, now)
            val startLayer = activeKeymanLayer()
            if (tap.replaces == null) keymanMultitapLayer = startLayer
            val step = key.multitapKey(multitap.step)
            var action = step.action as KeyAction.KeymanKey
            val home = keymanMultitapLayer
            if (tap.replaces != null && action.nextLayer == null && home != null && home != startLayer) {
                action = action.copy(nextLayer = home)
            }
            val session = keymanSession
            val recording = session != null && beginKeymanTap(session, ic)
            val typed = keyOutput(step, _uiState.value)
            val ordinary = onKeymanKeyPress(step, action)
            val record = if (recording) session?.endTap() else null
            keymanMultitapWrote = when {
                ordinary -> KeymanMultitapStep.Typed(typed)
                session != null && record != null -> KeymanMultitapStep.Engine(session, record)
                // Recorded, but with nothing to put back: the next tap starts over.
                recording -> null
                else -> KeymanMultitapStep.Nothing
            }
        } finally {
            ic?.endBatchEdit()
        }
    }

    /**
     * Brings the engine's context into line with the field before a tap of a
     * Keyman multitap run, and starts recording what the tap does to both.
     * False when the engine will not be the one typing it.
     */
    private fun beginKeymanTap(session: KeymanSession, ic: InputConnection?): Boolean {
        if (ic == null || session.disabled || _uiState.value.keysTakenByKeyboard) return false
        // The same as [runKeymanRules] would do, done first so the context the
        // tap is recorded from is the one it is typed into.
        if (composing.isNotEmpty()) {
            commitComposing(ic, autocorrect = false)
            session.markStale()
        }
        session.syncIfNeeded(expectedSelStart) {
            ic.getTextBeforeCursor(KEYMAN_CONTEXT_UNITS, 0) ?: ""
        }
        return session.beginTap()
    }

    /**
     * Takes the previous tap of the open Keyman multitap run back out of the
     * field, the way it went in. False when it can no longer be found there.
     */
    private fun takeBackKeymanMultitapStep(): Boolean = when (val wrote = keymanMultitapWrote) {
        null -> false
        KeymanMultitapStep.Nothing -> true
        is KeymanMultitapStep.Typed -> takeBackMultitapStep(wrote.text) != null
        is KeymanMultitapStep.Engine -> takeBackKeymanTap(wrote)
    }

    /** [takeBackKeymanMultitapStep] for a tap the engine typed, with the session that typed it. */
    private fun takeBackKeymanTap(wrote: KeymanMultitapStep.Engine): Boolean {
        val ic = currentInputConnection ?: return false
        val session = keymanSession?.takeIf { it === wrote.session } ?: return false
        val undo = session.takeBack(wrote.tap, expectedSelStart) {
            ic.getTextBeforeCursor(KEYMAN_CONTEXT_UNITS, 0) ?: ""
        } ?: return false
        applyKeymanEdit(ic, session, undo)
        return true
    }

    /**
     * Types a key the rules passed on — a `U_` key no rule names, say — the way
     * KeymanWeb's default output does: straight into the field, and into the
     * engine's own context, so a deadkey waiting there survives it. Our
     * composing machinery has no business with a Keyman layout's text, and
     * re-reading the field instead would drop every deadkey. False when no
     * engine is attached, and the key goes down the ordinary path.
     */
    private fun typeKeymanFallback(key: Key): Boolean {
        val session = keymanSession ?: return false
        val state = _uiState.value
        if (state.keysTakenByKeyboard || session.disabled) return false
        val ic = currentInputConnection ?: return false
        if (composing.isNotEmpty()) {
            commitComposing(ic, autocorrect = false)
            session.markStale()
        }
        val text = keyOutput(key, state)
        if (text.isEmpty()) return true
        if (hasSelection(ic)) return false
        session.syncIfNeeded(expectedSelStart) {
            ic.getTextBeforeCursor(KEYMAN_CONTEXT_UNITS, 0) ?: ""
        }
        val edit = ProcessorResult.Edit(deleteBefore = 0, insert = text)
        ic.commitText(text, 1)
        session.processor.onTextTyped(text)
        session.onEdited(edit)
        pendingWordSpace = false
        pendingPunctuationSpace = false
        return true
    }

    /** What the rules made of a key: the layer they asked for, if any. */
    private class KeymanOutcome(val layer: String?)

    /**
     * Runs one key through the rule engine. Null when the engine did not take
     * it — no session, a keyboard buffer owns the keys, the engine declined a
     * key that has text of its own to fall back on — and the caller types the
     * key the ordinary way.
     */
    private fun runKeymanRules(keyman: KeyAction.KeymanKey): KeymanOutcome? {
        val session = keymanSession ?: return null
        val state = _uiState.value
        // While a search box or a typing test owns the keys, what the user types
        // must not reach the app behind the keyboard, so the engine stays out of
        // it and the text goes down the ordinary local-buffer path.
        if (state.keysTakenByKeyboard) return null
        val ic = currentInputConnection ?: return null

        // A `T_`/`U_` key is known to the rules by its place in the keyboard's
        // key dictionary. KeymanWeb's default output for a key no rule takes is
        // narrow: a `U_` key types its code points, and nothing else types
        // anything — a `T_` key, and a `K_` key the rules pass on (the engine
        // types the US character itself where one applies, so a pass here is
        // always a key with none). A key with no name at all is one of ours,
        // a gesture entry with only text, and types that.
        val named = keyman.id
        val vkey = if (named != null) session.processor.keyForName(named) ?: 0 else keyman.vkey
        val unicode = named?.startsWith("U_") == true
        if (vkey == 0) return if (named == null || unicode) null else KeymanOutcome(null)

        // A word our own path started — a long-press alternate, a key the
        // engine passed on — is still a composing region. commitText replaces
        // a region rather than inserting after it, so the engine's output
        // would silently overwrite that word. End it as typed first; the
        // caret move that follows is what marks the context stale.
        if (composing.isNotEmpty()) {
            commitComposing(ic, autocorrect = false)
            session.markStale()
        }

        // One read per caret move, none per keystroke: the flag is set by
        // onUpdateSelection and resolved here, lazily.
        session.syncIfNeeded(expectedSelStart) {
            ic.getTextBeforeCursor(KEYMAN_CONTEXT_UNITS, 0) ?: ""
        }

        val layouts = state.layouts
        val modifiers = keyman.modifiers or
            KeymanSeam.runtimeModifiers(state.layoutMode, state.shiftState, layouts.keymanShift != null)
        session.processor.setLayer(KeymanLayers.keymanId(activeKeymanLayer()))
        return when (val result = session.process(ProcessorKey(vkey, modifiers))) {
            null, is ProcessorResult.Failed -> null
            is ProcessorResult.Declined -> if (unicode) null else KeymanOutcome(null)
            is ProcessorResult.Edit -> {
                applyKeymanEdit(ic, session, result)
                KeymanOutcome(result.nextLayer?.let(KeymanLayers::specKey))
            }
        }
    }

    /**
     * Keyman's `begin PostKeystroke`: after every keystroke, with `&newLayer`
     * and `&oldLayer` saying what the keystroke switched, the keyboard may pick
     * a layer — returning from shift after one letter, say. Readonly: it never
     * edits text.
     */
    private fun runKeymanPostKeystroke(startLayer: String, changed: Boolean) {
        val session = keymanSession ?: return
        if (!session.processor.hasPostKeystroke || _uiState.value.keysTakenByKeyboard) return
        val ic = currentInputConnection ?: return
        // Text this keystroke typed by our own path has not come back through
        // onUpdateSelection yet, so the context is refreshed from the field now:
        // the group reads it.
        session.markStale()
        session.syncIfNeeded(expectedSelStart) {
            ic.getTextBeforeCursor(KEYMAN_CONTEXT_UNITS, 0) ?: ""
        }
        val now = activeKeymanLayer()
        session.processor.setLayer(KeymanLayers.keymanId(now))
        val layer = session.processor.onPostKeystroke(
            newLayer = if (changed) KeymanLayers.keymanId(now) else "",
            oldLayer = if (changed) KeymanLayers.keymanId(startLayer) else "",
        )
        layer?.let { switchToKeymanLayer(KeymanLayers.specKey(it)) }
    }

    /**
     * Keyman's `begin NewContext`, for a field just entered or a caret the user
     * moved: the keyboard reads the text around it and may pick a layer — the
     * shift layer at the start of a sentence, typically.
     */
    private fun runKeymanNewContext() {
        val session = keymanSession ?: return
        if (!session.processor.hasNewContext || _uiState.value.keysTakenByKeyboard) return
        val ic = currentInputConnection ?: return
        val before = ic.getTextBeforeCursor(KEYMAN_CONTEXT_UNITS, 0) ?: ""
        session.processor.setLayer(KeymanLayers.keymanId(activeKeymanLayer()))
        val layer = session.processor.onNewContext(before)
        session.reset(before, expectedSelStart)
        layer?.let { switchToKeymanLayer(KeymanLayers.specKey(it)) }
    }

    /** The Keyman layer on screen, as its key in the layout's layers. */
    private fun activeKeymanLayer(): String {
        val state = _uiState.value
        return KeymanSeam.activeLayerKey(
            state.layoutMode,
            state.shiftState,
            state.namedLayer,
            hasCapsGrid = state.layouts.keymanCaps != null,
        )
    }

    /**
     * Offers a frame key to the rule engine before the keyboard's own handler
     * takes it. Returns true when the engine typed something.
     *
     * Space and backspace convert to [KeyAction.Space] and [KeyAction.Delete]
     * rather than to engine keys, so long-press repeat, auto-space and
     * double-space-period keep working. That leaves the keyboards whose rules
     * *do* fire on those keys — a syllable finalised on space, a cluster
     * deleted whole on backspace — with nothing, which is what this restores:
     * the engine is asked first and only a decline falls through.
     *
     * The prefilter is what keeps it cheap. On the overwhelming majority of
     * keyboards no rule mentions either key, [KeyProcessor.matches] says so
     * without touching the context, and the ordinary path runs as before.
     */
    private fun runKeymanFrameKey(vkey: Int): Boolean {
        val session = keymanSession ?: return false
        val state = _uiState.value
        if (state.keysTakenByKeyboard) return false
        // A pending composition belongs to our own composer, and the engine
        // keeps its own context. Letting both edit one keystroke deletes twice.
        if (composing.isNotEmpty()) return false
        val ic = currentInputConnection ?: return false

        // The frame key sits on whatever layer is showing, and is pressed with
        // that layer's modifiers, as KeymanWeb reads them off its name — or with
        // its own, where the layout gave it a `layer` of its own.
        val layer = KeymanLayers.keymanId(activeKeymanLayer())
        val modifiers = (pendingKeymanFrame?.modifiers ?: KeymanLayers.modifiers(layer)) or
            KeymanSeam.runtimeModifiers(state.layoutMode, state.shiftState, state.layouts.keymanShift != null)
        // Backspace always goes to the engine: with no rule of its own it pops a
        // waiting deadkey before any character, which is Keyman's backspace and
        // not ours. Space only when a rule could want it, so the ordinary
        // spacebar — auto-space, double-space period — keeps working.
        if (vkey != VK_BACKSPACE && !session.processor.matches(vkey, modifiers)) {
            // KeymanWeb types a default space only on a plain or shifted layer;
            // on an Alt or Ctrl one, space with no rule of its own is nothing.
            return vkey == VK_SPACE && modifiers and KeymanLayers.CTRL_ALT != 0
        }
        // A selection is the editor's to delete, not the rules'.
        if (hasSelection(ic)) return false

        session.processor.setLayer(layer)
        session.syncIfNeeded(expectedSelStart) {
            ic.getTextBeforeCursor(KEYMAN_CONTEXT_UNITS, 0) ?: ""
        }
        val result = session.process(ProcessorKey(vkey, modifiers)) ?: return false
        val edit = result as? ProcessorResult.Edit
            ?: return vkey == VK_SPACE && modifiers and KeymanLayers.CTRL_ALT != 0
        applyKeymanEdit(ic, session, edit)
        edit.nextLayer?.let {
            keymanFrameRuleLayer = true
            switchToKeymanLayer(KeymanLayers.specKey(it))
        }
        return true
    }

    /**
     * Applies a rule engine edit as one editor transaction.
     *
     * Not through the composing region. `setComposingText` replaces the whole
     * region and snaps the caret to its end, it underlines what it holds — and
     * engine output is committed text, not a candidate — and every piece of
     * machinery that hangs off "a region is open" (autocorrect, learning,
     * snippet triggers, revert) is wrong for rule output. The delete count also
     * routinely reaches text typed before this keyboard was even active, which
     * no region could cover.
     */
    private fun applyKeymanEdit(
        ic: InputConnection,
        session: KeymanSession,
        edit: ProcessorResult.Edit,
    ) {
        if (edit.isNoOp) {
            // A pure dead key: the marker lives in the engine's context and
            // nothing reaches the field. Issuing an empty transaction here makes
            // some editors scroll.
            session.onEdited(edit)
            return
        }
        ic.beginBatchEdit()
        if (edit.deleteBefore > 0) ic.deleteSurroundingText(edit.deleteBefore, 0)
        if (edit.insert.isNotEmpty()) ic.commitText(edit.insert, 1)
        ic.endBatchEdit()
        session.onEdited(edit)
    }

    /**
     * Shows the Keyman layer keyed [name] in the layout's layers — from a key's
     * `nextlayer`, a rule's `layer()`, or the keyboard's PostKeystroke and
     * NewContext groups.
     *
     * `shift` and `caps` are our shift state rather than places, so they set it
     * and the letters page draws the layout's own shift or caps grid. A layer
     * this layout does not have goes to the letters, which is what KeymanWeb
     * does with one.
     */
    private fun switchToKeymanLayer(requested: String) {
        val state = _uiState.value
        val layouts = state.layouts
        val defined = layouts.keymanLayerKeys
        val name = when {
            defined == null || requested in defined -> requested
            // Shift with no page of its own is still our shift state.
            requested == KeymanLayers.SHIFT && defined.none { it.startsWith(KeymanLayers.PREFIX) } -> requested
            else -> LayoutLayer.LETTERS.key
        }
        if (state.layoutMode == LayoutMode.LETTERS) dropKeyboardHandwritingInk()
        _uiState.update {
            when {
                name == KeymanLayers.SHIFT && it.layoutMode == LayoutMode.LETTERS &&
                    it.shiftState != ShiftState.OFF -> it
                name == KeymanLayers.SHIFT -> it.copy(
                    layoutMode = LayoutMode.LETTERS,
                    shiftState = ShiftState.ON,
                    fnLocked = false,
                    fnReturn = null,
                )
                name == KeymanLayers.CAPS -> it.copy(
                    layoutMode = LayoutMode.LETTERS,
                    shiftState = ShiftState.CAPS_LOCK,
                    fnLocked = false,
                    fnReturn = null,
                )
                name == LayoutLayer.SYMBOLS.key -> it.copy(layoutMode = LayoutMode.SYMBOLS)
                name == LayoutLayer.SYMBOLS_SHIFTED.key -> it.copy(layoutMode = LayoutMode.SYMBOLS_SHIFTED)
                name in layouts.named -> it.copy(
                    layoutMode = LayoutMode.NAMED,
                    namedLayer = name,
                    shiftState = ShiftState.OFF,
                    fnLocked = false,
                    fnReturn = null,
                )
                else -> it.copy(
                    layoutMode = LayoutMode.LETTERS,
                    shiftState = ShiftState.OFF,
                    fnLocked = false,
                    fnReturn = null,
                )
            }
        }
    }

    /**
     * Attaches or drops the rule engine when the active layout changes.
     *
     * Called wherever the layout is resolved, so a language switch cannot leave
     * the previous keyboard's rules running against the new grid.
     */
    private fun syncKeymanSession(spec: LayoutSpec) {
        // A Keyman page belongs to the layout it came from. KeymanWeb goes back
        // to `default` on a keyboard change, and a page left named here would
        // come back up the next time this layout does.
        if (spec.id != keymanPageLayoutId) {
            keymanPageLayoutId = spec.id
            _uiState.update {
                if (it.layoutMode == LayoutMode.NAMED) it.copy(layoutMode = LayoutMode.LETTERS, namedLayer = null) else it
            }
        }
        val binding = spec.keyman
        if (binding == null) {
            keymanSession = null
            return
        }
        if (keymanSession?.processor?.let { true } == true &&
            activeKeymanKeyboardId == binding.keyboardId
        ) {
            return
        }
        activeKeymanKeyboardId = binding.keyboardId
        keymanSession = keymanRules.processorFor(binding)?.let { KeymanSession(it) }
    }

    private var activeKeymanKeyboardId: String? = null

    /** The layout the Keyman page on screen belongs to; see [syncKeymanSession]. */
    private var keymanPageLayoutId: String? = null

    /** Keyman's own virtual keys for the two frame keys the engine may claim. */
    private val VK_BACKSPACE = 8
    private val VK_SPACE = 32

    /**
     * Springs ?123 back to the letters after one of the user's listed
     * characters, when the symbols-return setting is on. The emoji panel's
     * "return to keyboard after inserting" is the same bargain: a full stop is
     * a detour into the other grid, not a move to it.
     *
     * Only single-character keys count. A `.com` or an emoticon key is a phrase
     * the user went to ?123 to type, and it usually is not the last one.
     */
    private fun returnFromSymbolsAfter(output: String) {
        if (output.length != 1) return
        val state = _uiState.value
        if (state.layoutMode != LayoutMode.SYMBOLS &&
            state.layoutMode != LayoutMode.SYMBOLS_SHIFTED
        ) {
            return
        }
        val behavior = state.settings.layoutBehavior
        if (!behavior.symbolsReturnToLetters) return
        if (output[0] !in behavior.symbolsReturnCharSet()) return
        _uiState.update { it.copy(layoutMode = LayoutMode.LETTERS) }
    }

    /**
     * The spacebar's twin of [returnFromSymbolsAfter] (#359): the number is
     * done and a word comes next. After [onSpace] rather than inside it,
     * because every one of its early returns — a space confirmed rather than
     * typed, a double-space full stop — still ends the number.
     */
    private fun returnFromSymbolsAfterSpace() {
        val state = _uiState.value
        if (state.layoutMode != LayoutMode.SYMBOLS &&
            state.layoutMode != LayoutMode.SYMBOLS_SHIFTED
        ) {
            return
        }
        if (!state.settings.layoutBehavior.symbolsReturnOnSpace) return
        _uiState.update { it.copy(layoutMode = LayoutMode.LETTERS) }
    }

    /**
     * One braille dot key event — the press when [KeyAction.BrailleDot.release]
     * is false, the lift when true (the pointer handler synthesizes the lift as
     * a copy; see the chord branch in the keyboard view). Dots gather on the
     * way down; the cell decodes and commits when the last held finger lifts,
     * which is what makes simultaneous "dots 1+4+5" one `d` and not three
     * letters. Decoded text runs through [processTypedText] so it behaves
     * exactly like typed text (word buffer, autospace, field intercepts);
     * dead keys are skipped because braille has none.
     */
    private fun onBrailleDot(action: KeyAction.BrailleDot) {
        if (!action.release) {
            brailleChord.down(action.dot)
            return
        }
        val cell = brailleChord.up() ?: return
        val text = brailleGrade1.decode(cell)
        if (text.isNotEmpty()) processTypedText(text, applyDeadKeys = false)
    }

    /**
     * One morse signal. The sequence accumulates in [morse] and the decoded
     * character commits after [KeyboardSettings.morseCommitMs] of silence,
     * Gboard's model;
     * every signal restarts the pause. A non-morse key flushes the pending
     * sequence first (see [onKey]) and backspace edits it (see [onDelete]),
     * so the timer never races the user's next intent.
     */
    private fun onMorseSignal(dash: Boolean) {
        morse.signal(dash)
        _uiState.update { it.copy(morsePending = morse.display) }
        morseJob?.cancel()
        morseJob = serviceScope.launch {
            delay(_uiState.value.settings.morseCommitMs.toLong())
            commitMorse()
        }
    }

    /**
     * Decodes and commits the pending morse sequence. A sequence that spells
     * nothing is dropped — a bad chord should cost its own letter, not poison
     * the next one. Shift applies to the decoded letter the way it would to a
     * typed one (the morse grid has no shift key, but autocapitalize and a
     * hardware shift still arm it).
     */
    private fun commitMorse() {
        morseJob?.cancel()
        morseJob = null
        val decoded = morse.take()
        _uiState.update { it.copy(morsePending = "") }
        if (decoded == null) return
        val state = _uiState.value
        val cased = if (state.shiftState != ShiftState.OFF) decoded.uppercase() else decoded
        processTypedText(cased, applyDeadKeys = false)
        // Easter egg: three letters spelling SOS light a short-lived note in
        // the strip, once per service lifetime. Purely additive — the decoded
        // letter above is already committed either way.
        if (morse.recordDecoded(decoded) && !morseSosEggShown) {
            morseSosEggShown = true
            _uiState.update { it.copy(morseSosEgg = true) }
            morseSosEggJob?.cancel()
            morseSosEggJob = serviceScope.launch {
                delay(MORSE_SOS_EGG_MS)
                _uiState.update { it.copy(morseSosEgg = false) }
            }
        }
    }

    /**
     * Drops any half-typed chord or morse sequence: field switches, language
     * or layout switches, and panels taking the keys out from under a chord
     * all pass through here. Cheap enough to call unconditionally.
     */
    private fun resetChordInputs() {
        brailleChord.reset()
        brailleGrade1.reset()
        morseJob?.cancel()
        morseJob = null
        // reset() also drops the SOS watch window: letters keyed into two
        // different fields are not one distress call.
        val hadPending = morse.isPending
        morse.reset()
        if (hadPending) {
            _uiState.update { it.copy(morsePending = "") }
        }
        morseSosEggJob?.cancel()
        morseSosEggJob = null
        if (_uiState.value.morseSosEgg) {
            _uiState.update { it.copy(morseSosEgg = false) }
        }
    }

    // ---- the keyboard's own text fields ----

    /**
     * One place where a keystroke reaches a keyboard-owned buffer, and one
     * caret for whichever of them is focused (#161).
     *
     * Before this, each buffer had a branch of its own in seven different
     * ladders, every branch appended to the end of a plain `String`, and none
     * of them could be glided into or suggested for because there was no caret
     * to insert a word at or a word span to replace. [CaptureTarget] names the
     * focused buffer once and these functions do the rest.
     *
     * Two buffers keep their own path because they are not plain text: the
     * typing test scores keystrokes in the order they were made, and the word
     * card's [WordSpell] carries a selection as well as a caret (#204). Both
     * are routed here first so callers still have one question to ask.
     */
    private fun captureTyped(text: String): Boolean {
        val state = _uiState.value
        val target = state.captureTarget() ?: return false
        when (target) {
            CaptureTarget.TYPING_TEST -> { typingTestType(text); return true }
            CaptureTarget.WORD_SPELL -> {
                wordSpellEdit { it.typed(text, UserLexicon.MAX_WORD_LENGTH) }
                return true
            }
            else -> Unit
        }
        if (kdeTypedUnderModifiers(target, text)) return true
        val before = state.captureCaretText() ?: return false
        // The space a mark left behind (#880), while the caret still sits
        // right after it. One-shot: spent by this key whatever it is.
        val markSpace = captureMarkSpace?.takeIf {
            it.key == state.captureKey() && it.text == before.text && it.at == before.at && !before.hasSelection
        }
        captureMarkSpace = null
        // A space pressed after it is already there, as in the app's field.
        if (markSpace != null && text == " ") return true
        // A key a transliterator spells with (Hangul jamo, a Telex letter)
        // joins the word it is composing here as it would in the app's field
        // (#454), rather than landing as the bare key.
        val run = if (composesInCapture(state.composer)) liveCaptureComposition(state, before) else null
        if (capturesComposingKey(state.composer, target, text, run)) {
            rewriteCaptureComposition(state, target, before, run, run?.keys.orEmpty() + text)
            return true
        }
        // What each field will take of what was typed. The two numeric ones
        // filter rather than accept, and the cluster-shaping scripts need to
        // know the character the new one lands *after* — which, with a caret,
        // is the one before the caret and not the last one in the buffer.
        val insert = when (target) {
            CaptureTarget.CALC -> mapCalcChars(text)
            CaptureTarget.CONVERTER -> converterInsert(before, text)
            CaptureTarget.EMOJI_SEARCH, CaptureTarget.MEDIA_SEARCH ->
                fixedLayoutContextualVowel(text, before.text.getOrNull(before.at - 1))
            else -> text
        }
        if (insert.isEmpty()) return true
        // A mark straight after the space hugs the mark before it: `?!`, `.)`,
        // the closing quote of `"hi."`.
        val base = if (markSpace != null && insert.length == 1 && isAutoSpacedMark(insert[0])) {
            before.deletedBackward(1)
        } else {
            before
        }
        var after = base.typed(insert)
        // A sentence typed into a tool's field spaces after its marks the way
        // the app's field does (#880), stepping over a space already there.
        val spaced = target.prose && insert.length == 1 && captureSpacesAfterMark(state, after, insert[0])
        if (spaced) after = if (after.text.startsWith(" ", after.at)) after.caretAt(after.at + 1) else after.typed(" ")
        captureWrite(target, before, after)
        if (spaced) {
            val written = _uiState.value.captureCaretText()
            val key = _uiState.value.captureKey()
            if (written != null && key != null) captureMarkSpace = CaptureMarkSpace(key, written.text, written.at)
        }
        return true
    }

    /** The space [captureTyped] put after a mark: in which field, and the text and caret it left. */
    private data class CaptureMarkSpace(val key: String, val text: String, val at: Int)

    private var captureMarkSpace: CaptureMarkSpace? = null

    /**
     * Whether [mark], just typed to give [after], is followed by a space in a
     * prose field: [shouldAutoSpaceAfterPunctuation]'s rule, read off the
     * field's own text rather than an editor's. No number or address dot, and
     * a closing bracket only where it ends what it closes.
     */
    private fun captureSpacesAfterMark(state: KeyboardUiState, after: CaretText, mark: Char): Boolean {
        if (!state.settings.autoText.spaceAfterPunctuation || state.composer.isConversion || unspacedKey) return false
        val head = after.text.substring(0, (after.at - 1).coerceAtLeast(0))
        return when (mark) {
            in AUTO_SPACE_PUNCTUATION -> !markContinuesNumber(head) && !markContinuesAddress(head, mark)
            SPACED_CLOSER -> closerTakesSpace(after.text.substring(after.at))
            else -> false
        }
    }

    /**
     * Backspace in a keyboard-owned field: the character before the caret, a
     * whole emoji or conjunct at a time, exactly as the field path deletes.
     * The old per-buffer `dropLast(1)` took half an emoji and could only ever
     * delete from the end.
     *
     * Returns true whenever a field has the keys, *including* when the caret
     * is already at the start with nothing to delete — falling through there
     * would delete from the app behind the keyboard.
     */
    private fun captureBackspace(): Boolean {
        val state = _uiState.value
        val target = state.captureTarget() ?: return false
        when (target) {
            CaptureTarget.TYPING_TEST -> { typingTestBackspace(); return true }
            CaptureTarget.WORD_SPELL -> { wordSpellEdit { it.deletedBackward() }; return true }
            else -> Unit
        }
        val before = state.captureCaretText() ?: return false
        if (!before.hasSelection && before.at <= 0) {
            // Nothing left of this line to take back, but the computer's field
            // may well hold more: the key goes there as itself.
            if (target == CaptureTarget.KDE_REMOTE) kdeSendSpecial(KdeSpecialKey.BACKSPACE)
            return true
        }
        // Inside a word a transliterator is composing, backspace takes back
        // the last key rather than the whole syllable it helped build (#454).
        val run = if (composesInCapture(state.composer)) liveCaptureComposition(state, before) else null
        if (run != null) {
            val keys = if (state.composer.isConversion) state.composer.backspaceBuffer(run.keys) else run.keys.dropLast(1)
            rewriteCaptureComposition(state, target, before, run, keys)
            return true
        }
        val length = charDeleteLength(before.text.substring(0, before.at))
        captureWrite(target, before, before.deletedBackward(length))
        return true
    }

    /**
     * A word a transliterating composer is spelling in a keyboard-owned field
     * (#454): the [keys] typed so far and where their rendering starts in the
     * buffer named [key]. The app's field keeps the same thing in its composing
     * region; these fields have none, so the service holds it here.
     */
    private data class CaptureComposition(val key: String, val start: Int, val keys: String)

    /** The word [CaptureComposition] describes, while there is one. */
    private var captureComposition: CaptureComposition? = null

    /**
     * Whether [composer] turns its keys into script text by itself, which is
     * what a keyboard-owned field can show: Hangul, Cheonjiin, Telex and VNI,
     * Khipro, and every conversion IME (kana, pinyin, zhuyin, cangjie, stroke,
     * jyutping). Not a phonetic one like Avro, whose buffer stays roman here
     * and is converted by the field's own suggestions.
     *
     * The converters were excluded until #527, on the reasoning that their
     * output is a pick off the strip rather than a rendering of the buffer.
     * Half of that is true and the other half is the bug: a kana IME's buffer
     * renders perfectly well on its own — it is kana — and leaving it out meant
     * a Japanese user typing into the dictionary tool's search box got the
     * letters `ka` instead of か, no 小゛゜ key, and no way to reach a kanji.
     * The pick is handled too, by [captureConversionPick].
     */
    private fun composesInCapture(composer: Composer): Boolean =
        composer.isTransliterating && composer.phoneticLanguage == null

    /**
     * Whether [text] is a key [composer] spells with and so joins the word it
     * composes in [target], by the rule the app's field uses for its buffer.
     */
    private fun capturesComposingKey(
        composer: Composer,
        target: CaptureTarget,
        text: String,
        run: CaptureComposition?,
    ): Boolean {
        if (!composesInCapture(composer) || !target.takesWords || text.length != 1) return false
        val c = text[0]
        val keys = run?.keys.orEmpty()
        return c.isLetter() || composer.buffersChar(c, keys) ||
            (composer.bufferDigits && c.isDigit() && (keys.isNotEmpty() || composer.digitsStartBuffer))
    }

    /**
     * The composing word, while the buffer still shows it where it was left
     * with the caret at its end; else null, and the word is let go. Anything
     * that moved the caret or changed the text around it ends the word, as a
     * tap elsewhere ends composing in the app's field.
     */
    private fun liveCaptureComposition(state: KeyboardUiState, before: CaretText): CaptureComposition? {
        val live = captureCompositionIfLive(state, before)
        if (live == null) captureComposition = null
        return live
    }

    /**
     * [liveCaptureComposition] without letting the word go — for the readers
     * that only want to *look* at the run (the candidate strip), which must not
     * end a word merely by being asked about it.
     */
    private fun captureCompositionIfLive(state: KeyboardUiState, before: CaretText): CaptureComposition? {
        val run = captureComposition ?: return null
        val shown = state.composer.composeBuffer(run.keys)
        val live = run.key == state.captureKey() && !before.hasSelection &&
            before.at == run.start + shown.length &&
            before.text.regionMatches(run.start, shown, 0, shown.length)
        return run.takeIf { live }
    }

    /**
     * Puts the rendering of [keys] where [run]'s was, or at the caret (in place
     * of any selection) when no word is being composed, and keeps composing
     * from there. Empty [keys] take the word out and end it.
     */
    private fun rewriteCaptureComposition(
        state: KeyboardUiState,
        target: CaptureTarget,
        before: CaretText,
        run: CaptureComposition?,
        keys: String,
    ) {
        val composer = state.composer
        val base = if (run == null) before.withoutSelection() else before
        val start = run?.start ?: base.at
        val oldLength = run?.let { composer.composeBuffer(it.keys).length } ?: 0
        val shown = composer.composeBuffer(keys)
        val text = base.text.substring(0, start) + shown + base.text.substring(start + oldLength)
        captureWrite(target, before, CaretText(text, start + shown.length), keepsComposing = true)
        // After the write, which lets every other edit's word go.
        captureComposition = if (keys.isEmpty()) {
            null
        } else {
            state.captureKey()?.let { CaptureComposition(it, start, keys) }
        }
        // The strip's watcher fired on the write, before the run above existed,
        // and the caret settling after it is no change it would see: without
        // this a conversion IME's first reading in a tool's field had no
        // candidates at all (#942).
        refreshCaptureSuggestions()
        publishKanaVariantReady()
    }

    /**
     * [takeBackMultitapStep] for a keyboard-owned field: the step comes off the
     * composing word or from in front of the caret there, never off the app's
     * field behind the keyboard.
     */
    private fun takeBackCaptureMultitapStep(wrote: String): Boolean? {
        val state = _uiState.value
        val target = state.captureTarget() ?: return null
        if (target == CaptureTarget.TYPING_TEST || target.ownsCaret) return null
        val before = state.captureCaretText() ?: return null
        val run = if (composesInCapture(state.composer)) liveCaptureComposition(state, before) else null
        if (run != null) {
            if (!run.keys.endsWith(wrote)) return null
            rewriteCaptureComposition(state, target, before, run, run.keys.dropLast(wrote.length))
            return false
        }
        if (before.hasSelection || !before.text.substring(0, before.at).endsWith(wrote)) return null
        captureWrite(target, before, before.deletedBackward(wrote.length))
        return false
    }

    /** Forward delete in a keyboard-owned field; see [captureBackspace]. */
    private fun captureForwardDelete(): Boolean {
        val state = _uiState.value
        val target = state.captureTarget() ?: return false
        when (target) {
            CaptureTarget.TYPING_TEST -> return true
            CaptureTarget.WORD_SPELL -> { wordSpellEdit { it.deletedForward() }; return true }
            // The caret here is always at the end of the line; what is after
            // it is on the computer.
            CaptureTarget.KDE_REMOTE -> { kdeSendSpecial(KdeSpecialKey.DELETE, keepLine = true); return true }
            else -> Unit
        }
        val before = state.captureCaretText() ?: return false
        captureWrite(target, before, before.deletedForward())
        return true
    }

    /**
     * The spacebar while a keyboard-owned field has the keys. True whenever
     * one does, so the press can never reach the app behind the keyboard —
     * including in the fields where a space means nothing and the press is
     * simply spent.
     *
     * The clipboard search used to be missing from this ladder, so a space
     * pressed while filtering clips went into whatever was being written
     * behind the panel. That is the class of bug one ladder exists to end.
     */
    private fun captureSpace(): Boolean {
        val target = _uiState.value.captureTarget() ?: return false
        when (target) {
            CaptureTarget.TYPING_TEST -> typingTestSpace()
            // A single word: the respelling draft (#138) and the Learn
            // speller (#174) have no spaces in them, and neither does an
            // amount. The press is spent rather than passed on.
            CaptureTarget.WORD_SPELL, CaptureTarget.LEARN_EDIT, CaptureTarget.CONVERTER -> Unit
            // Everything else takes it at the caret — including the
            // calculator, whose `mod ` operator is spelled with one, and the
            // dictionary, where "give up" is a legitimate lookup.
            else -> captureTyped(" ")
        }
        return true
    }

    /**
     * Enter while a keyboard-owned field has the keys — mostly the field's own
     * action rather than a newline. True whenever one has them, so the press
     * can never reach the app behind the panel.
     *
     * The emoji and clipboard searches were both missing from this ladder, so
     * Enter while filtering either one put a newline into whatever was being
     * written behind it. They spend the press instead: a search box's Enter
     * has nothing to run, and a keyboard-owned field's keystroke is never the
     * field's.
     */
    private fun captureEnter(): Boolean {
        val state = _uiState.value
        when (state.captureTarget() ?: return false) {
            // Enter is not part of a run, and letting it through would put a
            // newline in the field behind the panel.
            CaptureTarget.TYPING_TEST -> Unit
            // Enter is the tick on the word card's spelling bar (#138).
            CaptureTarget.WORD_SPELL -> commitWordSpell()
            // Enter runs the Custom action rather than dropping a newline.
            CaptureTarget.AI_CUSTOM -> onAiRunCustom()
            // A chat message is free text, so Enter is a line break unless the
            // user asked for it to send (#280); the Send button always sends.
            CaptureTarget.AI_CHAT ->
                if (state.aiChat.renaming >= 0) {
                    // Enter keeps a chat's new name (#882): a name has one line.
                    onAiChatAction(AiChatAction.CommitRename)
                } else if (state.settings.ai.chatEnterSends) {
                    onAiChatAction(AiChatAction.Send)
                } else {
                    captureTyped("\n")
                }
            // Enter adds the message that was typed and clears the box for the
            // next one: gathering several in a row is the normal flow here.
            CaptureTarget.AI_REPLY -> onReplyTypedDone()
            CaptureTarget.KDE_HOST -> onKdeAction(KdeAction.SubmitHost)
            // Enter is the computer's Enter, and the line starts over.
            CaptureTarget.KDE_REMOTE -> kdeSendSpecial(KdeSpecialKey.ENTER)
            CaptureTarget.KDE_COMPOSE -> kdeSendComposed(withEnter = true)
            // Enter finishes typing into a plugin's box: it gives the keys
            // back to the field.
            CaptureTarget.PLUGIN -> onPluginInputFocus(null)
            // Enter in the find field walks to the next match; in the replace
            // field it replaces the current one.
            CaptureTarget.FIND_QUERY, CaptureTarget.FIND_REPLACEMENT -> onFindReplaceEnter()
            // Enter in the spelling editor keeps the spelling.
            CaptureTarget.LEARN_EDIT -> onLearnEditDone()
            CaptureTarget.DICTIONARY_SEARCH -> onDictionaryLookup(state.dictionaryQuery)
            // Enter in the calculator is the `=` key. Only when no focus ring
            // is up — [handlePanelNavKey] consumes Enter first while one is.
            CaptureTarget.CALC -> calcEvaluate()
            // The converters convert live; Enter has nothing to run.
            CaptureTarget.CONVERTER -> Unit
            CaptureTarget.MEDIA_SEARCH ->
                // QR builds its content as you type, so Enter adds a newline
                // to the buffer (WiFi/vCard payloads span lines) rather than
                // searching. Translate follows the text live and its box holds
                // several lines, so Enter is a line break there too. Every
                // other media box runs the search.
                if (state.panel == PanelMode.QR_GEN || state.panel == PanelMode.TRANSLATE) {
                    captureTyped("\n")
                } else {
                    runMediaSearch()
                }
            CaptureTarget.EMOJI_SEARCH, CaptureTarget.CLIPBOARD_SEARCH, CaptureTarget.SNIPPET_SEARCH -> Unit
            // Searching notes filters as you type; Enter has nothing to run.
            CaptureTarget.NOTE_SEARCH -> Unit
            // A title is one line: Enter moves on to the body.
            CaptureTarget.NOTE_TITLE -> onNoteEditFocus(NoteEditField.BODY, caret = null)
            // A note is free text, so Enter is a line break, and inside a list
            // it carries the list on (see NotesLogic.enter).
            CaptureTarget.NOTE_BODY -> {
                val before = state.captureCaretText()
                if (before != null) captureWrite(CaptureTarget.NOTE_BODY, before, NotesLogic.enter(before))
            }
            // Enter finishes a new tag's name.
            CaptureTarget.NOTE_TAG -> onNoteTagCommit()
            // Search adds its best match; a label is kept. Either way the keys go back.
            CaptureTarget.CLOCK_SEARCH, CaptureTarget.CLOCK_LABEL -> state.clockText?.let(clockTool::onTextEnter)
            // A new task is added and the box waits for the next; an edit is kept.
            CaptureTarget.TODO_TEXT -> state.todoText?.let(todoTool::onTextEnter)
            // Search opens the first tile, Assist sends the sentence, a code or value is kept.
            CaptureTarget.HA_SEARCH, CaptureTarget.HA_ASSIST, CaptureTarget.HA_TEXT -> state.haText?.let(haTool::onTextEnter)
            // A caption, or words on a photo, can run over lines; Done finishes
            // them. A photo search is one line, and Enter hands the keys back.
            CaptureTarget.GALLERY_TEXT -> {
                val entry = state.galleryText
                if (entry != null && entry.field == com.wasimaster.wmkeyboard.ime.gallery.GalleryTextField.SEARCH) {
                    galleryTool.onTextEnter(entry)
                } else {
                    captureTyped("\n")
                }
            }
            // A title moves on to the place, a guest is added, a place is kept;
            // notes are free text, so Enter is a line break in them.
            CaptureTarget.CALENDAR_TITLE, CaptureTarget.CALENDAR_LOCATION, CaptureTarget.CALENDAR_GUEST ->
                state.calendarText?.let(calendarTool::onTextEnter)
            CaptureTarget.CALENDAR_NOTES -> captureTyped("\n")
            // A password, a link or an address is one line; Enter hands it in.
            CaptureTarget.SEND_PASSWORD, CaptureTarget.SEND_LINK, CaptureTarget.SEND_INSTANCE ->
                state.sendText?.let(sendTool::onTextEnter)
            // A clip is free text, so Enter is a line break in it; saving is
            // the editor's own button.
            // The tags editor is one list: Enter keeps it (#612).
            CaptureTarget.CLIP_EDIT -> if (state.clipEdit?.tags == true) onClipEditSave() else captureTyped("\n")
            // A line break is a fair thing to join clips with; the other two
            // boxes move on, and the last one combines (#612).
            CaptureTarget.CLIP_JOINER -> captureTyped("\n")
            // The prefix, the combination and the result share a target (#612).
            CaptureTarget.CLIP_BASE -> when (state.clipCombine?.focused) {
                ClipCombineField.TEMPLATE -> onClipCombineSave()
                ClipCombineField.RESULT -> captureTyped("\n")
                else -> onClipCombineFocus(ClipCombineField.APPEND)
            }
            CaptureTarget.CLIP_APPEND -> onClipCombineFocus(ClipCombineField.TEMPLATE)
            // The search opens its first match (#687); a folder's name is kept (#709).
            CaptureTarget.TOOLBOX_SEARCH -> onToolboxSearchEnter()
            CaptureTarget.TOOLBOX_FOLDER_NAME -> onToolboxFolderRenameDone(keep = true)
            CaptureTarget.LAUNCHER_FOLDER_NAME -> onLauncherFolderRenameDone(keep = true)
            // The search puts its first match in, a face is saved, a tag is kept.
            CaptureTarget.KAOMOJI_SEARCH, CaptureTarget.KAOMOJI_FACE, CaptureTarget.KAOMOJI_TAG ->
                state.kaomojiText?.let(kaomojiTool::onTextEnter)
            // The text to repeat may run over lines; the separator box is one
            // line, and Enter keeps it and hands the keys back.
            CaptureTarget.REPEAT_TEXT -> captureTyped("\n")
            CaptureTarget.REPEAT_SEPARATOR -> onTextRepeat(TextRepeatAction.Focus(null))
        }
        return true
    }

    /**
     * The caret moved by [delta] characters, or put at [index] when one is
     * given — a tap in the middle of the text, which is what a real field does
     * and none of these could (#161).
     */
    fun onCaptureCaretMove(delta: Int, extend: Boolean = false): Boolean {
        val state = _uiState.value
        val target = state.captureTarget() ?: return false
        if (target == CaptureTarget.KDE_REMOTE) {
            // This line has no caret to move; the computer's field does.
            if (delta != 0) {
                kdeSendSpecial(
                    if (delta < 0) KdeSpecialKey.LEFT else KdeSpecialKey.RIGHT,
                    KdeModifiers(shift = extend),
                    times = kotlin.math.abs(delta),
                )
            }
            return true
        }
        if (!target.movableCaret) return true
        if (target == CaptureTarget.WORD_SPELL) {
            wordSpellEdit { it.caretMoved(delta, extend) }
            return true
        }
        val before = state.captureCaretText() ?: return false
        captureCaretTo(before.caretMoved(delta, extend))
        return true
    }

    /**
     * The caret put at the start or end of the focused keyboard-owned field —
     * what the vertical scrub, Home and End ask of a one-line buffer.
     */
    fun onCaptureCaretToEdge(end: Boolean, extend: Boolean = false): Boolean {
        val state = _uiState.value
        val target = state.captureTarget() ?: return false
        if (!target.movableCaret) return true
        if (target == CaptureTarget.WORD_SPELL) {
            wordSpellEdit { it.caretAt(if (end) it.draft.length else 0, extend) }
            return true
        }
        val before = state.captureCaretText() ?: return false
        captureCaretTo(before.caretAt(if (end) before.text.length else 0, extend))
        return true
    }

    /**
     * A hardware arrow, Home or End while a keyboard-owned field has the keys:
     * that field's caret moves, not the app's. Shift extends in the one buffer
     * that has a selection to extend (#204, and the shared caret since #352).
     */
    private fun captureCaretKey(event: KeyEvent): Boolean {
        val handled = captureCaretKeyCode(event.keyCode, event.isShiftPressed)
        if (handled) consumeHardwareKey(event.keyCode)
        return handled
    }

    /**
     * The caret move [keyCode] asks of the keyboard-owned field that has the
     * keys, or false when none has them or the code is not a caret key. The
     * one table behind both a hardware arrow and an on-screen arrow key, so
     * the arrow row under the keyboard moves the clip editor's caret the way a
     * physical arrow always has (#414).
     */
    private fun captureCaretKeyCode(keyCode: Int, extend: Boolean = false): Boolean {
        if (_uiState.value.captureTarget() == null) return false
        return when (keyCode) {
            KeyEvent.KEYCODE_DPAD_LEFT -> onCaptureCaretMove(-1, extend)
            KeyEvent.KEYCODE_DPAD_RIGHT -> onCaptureCaretMove(1, extend)
            KeyEvent.KEYCODE_DPAD_UP, KeyEvent.KEYCODE_MOVE_HOME ->
                onCaptureCaretToEdge(end = false, extend = extend)
            KeyEvent.KEYCODE_DPAD_DOWN, KeyEvent.KEYCODE_MOVE_END ->
                onCaptureCaretToEdge(end = true, extend = extend)
            else -> false
        }
    }

    /**
     * The focus switch on a tool's field (#665): the keys go to the app's
     * field, or come back to the tool's. Everything a key can do follows it
     * at once — typing, Backspace, Enter, the caret keys, undo and redo,
     * paste, a glide — because every one of those asks
     * [KeyboardUiState.captureTarget], and that is the one place this answers.
     */
    fun onCaptureFocusSwitch() {
        val state = _uiState.value
        val key = state.panelFieldKey() ?: return
        if (state.panelFieldTarget()?.handsKeysToApp != true) return
        vibrate()
        // Either way the rows come back up (#961): the switch is about where they type.
        if (state.captureKeysLowered) _uiState.update { it.copy(captureLowered = null) }
        if (state.captureHandedToApp) {
            takeCaptureKeysBack()
            return
        }
        // A dictation into the field would land nowhere once it lets go.
        if (state.voice.field == key) endFieldVoice()
        captureComposition = null
        _uiState.update { it.copy(captureToApp = key, captureSuggestions = emptyList()) }
    }

    /**
     * The tool's field takes the keys back from the app's field (#665). A
     * word still composing over there is settled first, the way it is when
     * any tool opens: the keys are about to stop reaching it.
     */
    private fun takeCaptureKeysBack() {
        currentInputConnection?.let { commitComposing(it, autocorrect = false) }
        lastGestureWord = null
        _uiState.update { it.copy(captureToApp = null) }
    }

    /**
     * Whether a tool field has its key rows up under the panel, so they can be
     * put down (#961). What Back, the hide-keyboard gestures and the strip's
     * button all ask before they do anything else.
     */
    private fun captureKeysLowerable(state: KeyboardUiState): Boolean =
        state.panel != PanelMode.NONE && state.panelFieldTarget()?.lowersKeys == true &&
            keyRowsUnderPanel(state)

    /**
     * The tool field's key rows go down (#961) and the panel takes their
     * height back, so what it holds can be seen: a translation, the clips a
     * search found. The field keeps its text and its caret, and a tap on it
     * brings the rows up again. False when no field had rows up.
     *
     * The media panels' search boxes (Translate, GIFs, Wikipedia, the web
     * search) have always had a box that holds a query without being typed
     * into, and their panels draw their results around that state, so they
     * go back to it; every other field is marked put down, the way the focus
     * switch marks one (#665).
     */
    private fun lowerCaptureKeys(): Boolean {
        val state = _uiState.value
        if (!captureKeysLowerable(state)) return false
        val key = state.panelFieldKey() ?: return false
        // A dictation would go on with nothing on screen to say it is listening.
        if (state.voice.field == key) endFieldVoice()
        if (state.panelFieldTarget() == CaptureTarget.MEDIA_SEARCH) {
            _uiState.update { it.copy(mediaSearchActive = false) }
        } else {
            _uiState.update { it.copy(captureLowered = key) }
        }
        return true
    }

    /** The button at the end of a tool field's strip (#961). */
    fun onCaptureKeysLower() {
        if (lowerCaptureKeys()) vibrate()
    }

    /** The caret put where a tap landed in the field's text. */
    fun onCaptureCaretTap(index: Int) {
        // A tap on a tool field that handed its keys to the app is a tap to
        // type there again (#665); the caret stays where it was left.
        if (_uiState.value.captureHandedToApp) {
            takeCaptureKeysBack()
            return
        }
        // A field whose keys were put down brings them up (#961), and the
        // caret goes where the tap landed, as on any field.
        if (_uiState.value.captureKeysLowered) _uiState.update { it.copy(captureLowered = null) }
        val state = _uiState.value
        val target = state.captureTarget() ?: return
        if (!target.movableCaret) return
        if (target == CaptureTarget.WORD_SPELL) {
            wordSpellEdit { it.caretAt(index, extend = false) }
            return
        }
        val before = state.captureCaretText() ?: return
        captureCaretTo(before.caretAt(index))
    }

    /**
     * A selection made on the field itself (#352): a long press on a word, or
     * one of its handles dragged. [anchor] is the end that stays, [caret] the
     * one that moves; equal, it is just the caret.
     */
    fun onCaptureSelect(anchor: Int, caret: Int) {
        if (_uiState.value.captureHandedToApp) {
            takeCaptureKeysBack()
            return
        }
        if (_uiState.value.captureKeysLowered) _uiState.update { it.copy(captureLowered = null) }
        val state = _uiState.value
        val target = state.captureTarget() ?: return
        if (!target.movableCaret) return
        if (target == CaptureTarget.WORD_SPELL) {
            wordSpellEdit { it.caretAt(anchor, extend = false).caretAt(caret, extend = true) }
            return
        }
        val before = state.captureCaretText() ?: return
        captureCaretTo(before.selected(anchor, caret))
    }

    /** Cut, Copy, Paste or Select all on the focused keyboard-owned field (#352). */
    fun onCaptureSelectionAction(action: CaptureSelectionAction) {
        val state = _uiState.value
        val target = state.captureTarget() ?: return
        // The word card and the typing test run editors of their own.
        if (target == CaptureTarget.WORD_SPELL || !target.movableCaret) return
        val before = state.captureCaretText() ?: return
        vibrate()
        when (action) {
            CaptureSelectionAction.SELECT_ALL -> captureCaretTo(before.selectedAll())
            CaptureSelectionAction.COPY, CaptureSelectionAction.CUT -> {
                if (!before.hasSelection) return
                KeyboardClipboard.copy(this, before.selectedText)
                if (action == CaptureSelectionAction.CUT) {
                    captureWrite(target, before, before.withoutSelection())
                } else {
                    captureCaretTo(before.collapsed().caretAt(before.selectionEnd))
                }
            }
            CaptureSelectionAction.PASTE -> capturePaste()
            CaptureSelectionAction.UNDO -> captureUndo(target, before)
            CaptureSelectionAction.REDO -> captureRedo(target, before)
        }
    }

    /**
     * What each keyboard-owned field looked like before its recent edits (#665),
     * by field key, oldest first, and the text the field held after the last
     * edit this history saw. A field whose text has since changed some other
     * way — a tool's prefill, the same box opened on another note — no longer
     * matches [CaptureHistory.lastText], and its history is dropped rather
     * than undone onto text it never described.
     */
    private class CaptureHistory(val steps: ArrayDeque<CaretText>, var lastText: String) {
        /** What the undos took back, newest last, for the redo button; any new edit drops it. */
        val redo = ArrayDeque<CaretText>()
    }

    private val captureHistories = HashMap<String, CaptureHistory>()

    /** When the last edit was recorded, so a burst of typing undoes as one step. */
    private var captureHistoryAt = 0L

    /** True while an undo writes, which must not record itself as an edit. */
    private var captureUndoing = false

    /**
     * Notes [before] as the state an undo goes back to, unless it belongs to the
     * same burst of typing as the step before it: keys pressed less than
     * [CAPTURE_UNDO_GROUP_MS] apart undo together, the way a word does in a
     * text editor. A change of more than one character (a paste, a suggestion,
     * a cut) is always a step of its own.
     */
    private fun recordCaptureEdit(key: String, before: CaretText, after: CaretText) {
        if (captureUndoing) return
        val now = SystemClock.uptimeMillis()
        val history = captureHistories[key]
            ?.takeIf { it.lastText == before.text }
            ?: CaptureHistory(ArrayDeque(), before.text).also { captureHistories[key] = it }
        val big = kotlin.math.abs(after.text.length - before.text.length) > 1
        // A new edit after an undo starts another branch; what was undone is gone.
        history.redo.clear()
        if (history.steps.isEmpty() || big || now - captureHistoryAt > CAPTURE_UNDO_GROUP_MS) {
            history.steps.addLast(before)
            while (history.steps.size > CAPTURE_UNDO_MAX) history.steps.removeFirst()
        }
        // A big change closes its step, so the next key starts a new one.
        captureHistoryAt = if (big) 0L else now
    }

    /** The undo button on a keyboard-owned field's strip (#665): one step back. */
    private fun captureUndo(target: CaptureTarget, now: CaretText) {
        val key = _uiState.value.captureKey() ?: return
        val history = captureHistories[key]
        val previous = history?.takeIf { it.lastText == now.text }?.steps?.removeLastOrNull()
        if (previous == null) {
            captureHistories.remove(key)
            if (_uiState.value.captureUndo != null) _uiState.update { it.copy(captureUndo = null) }
            return
        }
        history.redo.addLast(now)
        captureUndoing = true
        try {
            captureWrite(target, now, previous)
        } finally {
            captureUndoing = false
        }
        captureHistoryAt = 0L
    }

    /** The redo button beside it: puts back what the last undo took away. */
    private fun captureRedo(target: CaptureTarget, now: CaretText) {
        val key = _uiState.value.captureKey() ?: return
        val history = captureHistories[key]?.takeIf { it.lastText == now.text } ?: return
        val next = history.redo.removeLastOrNull() ?: return
        history.steps.addLast(now)
        captureUndoing = true
        try {
            captureWrite(target, now, next)
        } finally {
            captureUndoing = false
        }
        captureHistoryAt = 0L
    }

    /**
     * The clipboard's text typed into the focused keyboard-owned field (#434),
     * through the ladder so each field filters it as it filters keys. True
     * whenever such a field took the paste, even an empty one, so it never
     * falls through to the app behind the panel; false when no field that can
     * take text has the keys, so the paste goes to the app as it always did.
     *
     * The system clipboard first, as text only: coercing would paste a copied
     * image as its content:// address. The history's newest text is the
     * fallback for a clip the system will not hand over.
     */
    private fun capturePaste(): Boolean {
        val target = _uiState.value.captureTarget() ?: return false
        // The word card and the typing test run editors of their own.
        if (target == CaptureTarget.WORD_SPELL || !target.movableCaret) return false
        if (!isClipboardAccessible()) return true
        val system = runCatching {
            (getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager)
                .primaryClip?.takeIf { it.itemCount > 0 }?.getItemAt(0)?.text?.toString()
        }.getOrNull()
        val clip = KeyboardClipboard.held ?: system?.takeIf { it.isNotEmpty() } ?: clipboardStore.latestText().orEmpty()
        if (clip.isNotEmpty()) captureTyped(clip)
        return true
    }

    /** Moves the shared caret, and its selection, without touching the text. */
    private fun captureCaretTo(caret: CaretText) {
        val state = _uiState.value
        val key = state.captureKey() ?: return
        _uiState.update {
            it.copy(captureCaret = CaptureCaret(key, caret.at, state.captureBuffer(), caret.anchorAt))
        }
    }

    /**
     * Writes [after] into whichever buffer [target] names, then settles the
     * caret and the strip.
     *
     * The caret is read back off the state rather than taken from [after]:
     * three of these buffers cap their own length (a plugin box, the two Find
     * fields, the Learn speller), so what lands can be shorter than what was
     * asked for, and a caret past the end of the text would draw outside it.
     */
    private fun captureWrite(
        target: CaptureTarget,
        before: CaretText,
        after: CaretText,
        keepsComposing: Boolean = false,
    ) {
        // Any edit ends a transliterated word; the one that continues it sets
        // it again straight after (see [rewriteCaptureComposition]).
        captureComposition = null
        val key = _uiState.value.captureKey()
        if (after.text != before.text && key != null &&
            target != CaptureTarget.TYPING_TEST && target != CaptureTarget.WORD_SPELL
        ) {
            recordCaptureEdit(key, before, after)
        }
        if (after.text != before.text) {
            if (target == CaptureTarget.TYPING_TEST || target == CaptureTarget.WORD_SPELL) return
            // Two halves rather than one `when`: each branch that copies the ui
            // state inlines a call carrying every one of its fields, and the
            // single `when` took this method past the 10,000 dex instructions
            // at which ART stops compiling it.
            if (!captureWriteTools(target, after.text)) captureWriteLists(target, after.text)
        }
        val written = _uiState.value.captureBuffer()
        val at = if (written == after.text) after.at else written.length
        val anchor = if (written == after.text) after.anchorAt else at
        // The history follows the field to whatever its setter kept, so the
        // next edit, or an undo, still recognises it as the same text.
        val history = key?.let { captureHistories[it] }
        history?.lastText = written
        val undo = if (key != null && history != null && (history.steps.isNotEmpty() || history.redo.isNotEmpty())) {
            CaptureUndoMark(key, written, canUndo = history.steps.isNotEmpty(), canRedo = history.redo.isNotEmpty())
        } else {
            null
        }
        _uiState.update {
            it.copy(captureCaret = key?.let { k -> CaptureCaret(k, at, written, anchor) }, captureUndo = undo)
        }
        // The run was just let go, so the 小゛゜ key goes back to what it was
        // (#527). The callers that set a new run straight afterwards say so and
        // publish once themselves, rather than flipping the flag twice — and
        // with it the key grid's `remember` — on every keystroke.
        if (!keepsComposing) publishKanaVariantReady()
    }

    /** [captureWrite]'s tool fields. False when [target] is not one of them. */
    private fun captureWriteTools(target: CaptureTarget, text: String): Boolean {
        when (target) {
            CaptureTarget.AI_CUSTOM -> aiCustomInputEdit { text }
            CaptureTarget.AI_CHAT -> aiChatDraft(text)
            CaptureTarget.AI_REPLY -> aiReplyTyped(text)
            CaptureTarget.KDE_HOST ->
                _uiState.update { it.copy(kde = it.kde.copy(hostDraft = text.take(KDE_HOST_MAX))) }
            CaptureTarget.KDE_REMOTE -> kdeRemoteLine(text)
            CaptureTarget.KDE_COMPOSE ->
                _uiState.update { it.copy(kde = it.kde.copy(line = text.take(KdeConnectHub.LINE_MAX))) }
            CaptureTarget.PLUGIN -> pluginInputEdit { text }
            CaptureTarget.FIND_QUERY, CaptureTarget.FIND_REPLACEMENT -> findReplaceEdit { text }
            CaptureTarget.LEARN_EDIT -> learnEdit { text }
            CaptureTarget.CALC -> calcEdit { text }
            CaptureTarget.CONVERTER -> converterEdit { text }
            CaptureTarget.EMOJI_SEARCH -> {
                updateQuery { it.copy(emojiQuery = text) }
                refreshKarContext()
                refreshEmojiResults()
            }
            CaptureTarget.MEDIA_SEARCH -> {
                updateQuery { it.copy(mediaQuery = text) }
                refreshKarContext()
                // QR encodes locally as you type — no network search to schedule.
                if (_uiState.value.panel != PanelMode.QR_GEN) scheduleMediaLiveSearch()
            }
            CaptureTarget.DICTIONARY_SEARCH -> updateQuery { it.copy(dictionaryQuery = text) }
            CaptureTarget.CLIPBOARD_SEARCH -> {
                updateQuery { it.copy(clipboardQuery = text) }
                queryMeaningClips(text)
            }
            CaptureTarget.REPEAT_TEXT, CaptureTarget.REPEAT_SEPARATOR -> _uiState.update {
                it.copy(textRepeat = it.textRepeat.withFocusedText(text.take(TEXT_REPEAT_BOX_MAX)))
            }
            else -> return false
        }
        return true
    }

    /** [captureWrite]'s search, clipboard, note, clock, gallery and toolbox fields. */
    private fun captureWriteLists(target: CaptureTarget, text: String) {
        when (target) {
            CaptureTarget.CLIP_EDIT -> clipEditDraft { text }
            CaptureTarget.CLIP_JOINER, CaptureTarget.CLIP_BASE, CaptureTarget.CLIP_APPEND ->
                _uiState.update { state ->
                    state.copy(clipCombine = state.clipCombine?.withFocusedText(text))
                }
            CaptureTarget.SNIPPET_SEARCH -> {
                updateQuery { it.copy(snippetQuery = text) }
                queryMeaningSnippets(text)
            }
            // The search filters as it is typed; the drafts are written to
            // the store a moment after the typing pauses (see noteEditDraft).
            CaptureTarget.NOTE_SEARCH -> {
                publishNotes { it.copy(query = text, held = null) }
                queryMeaningNotes(text)
            }
            CaptureTarget.NOTE_TITLE ->
                noteEditDraft { it.copy(titleDraft = text.replace("\n", " ").take(NoteStore.MAX_TITLE_LENGTH)) }
            CaptureTarget.NOTE_BODY -> noteEditDraft { it.copy(bodyDraft = text.take(NoteEdit.EDITOR_MAX_LENGTH)) }
            CaptureTarget.NOTE_TAG -> noteEditDraft { it.copy(tagDraft = text.trimStart().take(NoteStore.MAX_TAG_LENGTH)) }
            CaptureTarget.TODO_TEXT -> _uiState.update { state ->
                state.copy(
                    todoText = state.todoText?.copy(
                        text = text.replace("\n", " ").take(com.wasimaster.wmkeyboard.core.todo.TodoStore.MAX_TEXT_LENGTH),
                    ),
                )
            }
            CaptureTarget.CLOCK_SEARCH, CaptureTarget.CLOCK_LABEL -> {
                val limit = com.wasimaster.wmkeyboard.ime.clock.ClockController.LABEL_MAX
                val entry = _uiState.value.clockText?.copy(text = text.replace("\n", " ").take(limit))
                _uiState.update { it.copy(clockText = entry) }
                entry?.let(clockTool::onText)
            }
            CaptureTarget.HA_SEARCH, CaptureTarget.HA_ASSIST, CaptureTarget.HA_TEXT -> {
                val limit = com.wasimaster.wmkeyboard.ime.homeassistant.HaController.TEXT_MAX
                val entry = _uiState.value.haText?.copy(text = text.replace("\n", " ").take(limit))
                _uiState.update { it.copy(haText = entry) }
                entry?.let(haTool::onText)
            }
            CaptureTarget.CALENDAR_TITLE, CaptureTarget.CALENDAR_LOCATION,
            CaptureTarget.CALENDAR_NOTES, CaptureTarget.CALENDAR_GUEST,
            -> {
                val current = _uiState.value.calendarText
                val entry = current?.copy(
                    text = if (target == CaptureTarget.CALENDAR_NOTES) {
                        text.take(com.wasimaster.wmkeyboard.ime.calendar.CalendarController.NOTES_MAX)
                    } else {
                        text.replace("\n", " ").take(com.wasimaster.wmkeyboard.ime.calendar.CalendarController.TITLE_MAX)
                    },
                )
                _uiState.update { it.copy(calendarText = entry) }
                entry?.let(calendarTool::onText)
            }
            CaptureTarget.GALLERY_TEXT -> {
                val limit = com.wasimaster.wmkeyboard.ime.gallery.GalleryController.CAPTION_MAX
                val entry = _uiState.value.galleryText?.copy(text = text.take(limit))
                _uiState.update { it.copy(galleryText = entry) }
                entry?.let(galleryTool::onText)
            }
            CaptureTarget.SEND_PASSWORD, CaptureTarget.SEND_LINK, CaptureTarget.SEND_INSTANCE -> {
                val limit = when (target) {
                    CaptureTarget.SEND_PASSWORD -> com.wasimaster.wmkeyboard.ime.send.SendController.PASSWORD_MAX
                    CaptureTarget.SEND_LINK -> com.wasimaster.wmkeyboard.ime.send.SendController.LINK_MAX
                    else -> com.wasimaster.wmkeyboard.ime.send.SendController.INSTANCE_MAX
                }
                val entry = _uiState.value.sendText?.copy(text = text.replace("\n", "").take(limit))
                _uiState.update { it.copy(sendText = entry) }
                entry?.let(sendTool::onText)
            }
            CaptureTarget.TOOLBOX_SEARCH ->
                updateQuery { it.copy(toolboxView = it.toolboxView.copy(query = text)) }
            CaptureTarget.TOOLBOX_FOLDER_NAME -> _uiState.update {
                it.copy(
                    toolboxView = it.toolboxView.copy(
                        nameDraft = text.replace("\n", " ").take(TOOLBOX_FOLDER_NAME_MAX),
                    ),
                )
            }
            CaptureTarget.LAUNCHER_FOLDER_NAME -> _uiState.update {
                it.copy(
                    launcherView = it.launcherView.copy(
                        nameDraft = text.replace("\n", " ")
                            .take(com.wasimaster.wmkeyboard.core.settings.LAUNCHER_FOLDER_NAME_MAX),
                    ),
                )
            }
            CaptureTarget.KAOMOJI_SEARCH, CaptureTarget.KAOMOJI_FACE, CaptureTarget.KAOMOJI_TAG -> {
                val limit = com.wasimaster.wmkeyboard.core.emoji.KaomojiStore.MAX_TEXT_LENGTH
                val entry = _uiState.value.kaomojiText?.copy(text = text.replace("\n", " ").take(limit))
                _uiState.update { it.copy(kaomojiText = entry) }
                entry?.let(kaomojiTool::onText)
            }
            else -> Unit
        }
    }

    /**
     * What the converters will take of [text] at the caret: digits up to the
     * field's cap, and a decimal point only while the amount has none. The
     * same rule the append-only path had, asked of an insert instead.
     */
    private fun converterInsert(before: CaretText, text: String): String {
        val room = (CONVERTER_VALUE_MAX - before.text.length).coerceAtLeast(0)
        var hasDot = '.' in before.text
        val out = StringBuilder()
        for (c in text) {
            when {
                c.isDigit() && out.length < room -> out.append(c)
                c == '.' && !hasDot -> { out.append(c); hasDot = true }
            }
        }
        return out.toString()
    }

    /**
     * The suggestion strip for a keyboard-owned field.
     *
     * The same engine and the same lookup the field's own strip uses — the
     * word in front of the caret, with the word before it as context — so
     * these fields predict as well as the app behind them does. Only the
     * destination differs: [KeyboardUiState.captureSuggestions] is drawn in the
     * row above the keys, because the panel has taken the toolbar's row, and a
     * word picked there must never reach the field behind the keyboard.
     *
     * The typing test keeps [refreshTypingSuggestions]: it predicts against the
     * prompt it is scoring, not against a free-text buffer.
     */
    private fun startCaptureSuggestionWatcher() {
        serviceScope.launch {
            _uiState
                // Everything the strip is a function of: which field has the
                // keys, what is in it, and where the caret stands. Driven off
                // the state rather than called at each edit site, so a query
                // set any other way — dictated, pasted, prefilled by a tool —
                // gets the same strip the keys would have given it.
                .map { Triple(it.captureKey(), it.captureBuffer(), it.captureCaretIndex()) }
                .distinctUntilChanged()
                .collect { refreshCaptureSuggestions() }
        }
        // The focus switch (#665) is about the box it was pressed on: once the
        // tool has no box focused (a search closed, an edit saved), the mark
        // goes, so the box opens with the keys next time.
        serviceScope.launch {
            _uiState
                .map { it.panelFieldKey() == null && it.captureToApp != null }
                .distinctUntilChanged()
                .collect { stale -> if (stale) _uiState.update { it.copy(captureToApp = null) } }
        }
        // Keys put down (#961) are about the box they were put down from too:
        // focus another box, or close this one, and the next box opens with
        // its keys up.
        serviceScope.launch {
            _uiState
                .map { it.captureLowered != null && it.captureLowered != it.panelFieldKey() }
                .distinctUntilChanged()
                .collect { stale -> if (stale) _uiState.update { it.copy(captureLowered = null) } }
        }
    }

    private fun refreshCaptureSuggestions() {
        val state = _uiState.value
        val target = state.captureTarget()
        captureSuggestJob?.cancel()
        val caret = state.captureCaretText()
        if (target != null && caret != null && refreshCaptureCandidates(state, caret)) return
        if (target == null || !target.takesWords || caret == null || !state.settings.suggestions) {
            if (state.captureSuggestions.isNotEmpty()) {
                _uiState.update { it.copy(captureSuggestions = emptyList()) }
            }
            return
        }
        val word = caret.wordAtCaret()
        val previous = caret.wordBeforeCaret()
        val phonetic = state.composer.phoneticLanguage
        val slots = state.settings.suggestionStrip.slotCount
        val key = state.captureKey()
        val snapshot = caret
        val ask = captureSuggestSource(target, caret, word, previous, phonetic, slots) ?: return
        captureSuggestJob = serviceScope.launch {
            delay(CAPTURE_SUGGEST_DEBOUNCE_MS)
            val words = withContext(Dispatchers.Default) { ask() }
            _uiState.update { s ->
                // Only for the buffer and the caret it was asked about.
                if (s.captureKey() != key || s.captureCaretText() != snapshot) s
                else s.copy(captureSuggestions = words)
            }
        }
    }

    /**
     * The conversion candidates for the word a keyboard-owned field is
     * composing, in place of its word-list suggestions (#527). True whenever
     * this composer converts, so the ladder above stops there — a kana reading
     * has nothing to say to the Latin word list.
     *
     * Drawn whatever **Suggestions** is set to, and with no debounce, for the
     * reason the composing itself runs regardless: for a conversion IME the
     * strip is not a convenience over typing, it is the only way to reach a
     * kanji at all. Ranking is off the main thread as everywhere else; the
     * answer lands only if the buffer and caret are still the ones it was
     * asked about.
     */
    private fun refreshCaptureCandidates(state: KeyboardUiState, caret: CaretText): Boolean {
        val composer = state.composer
        if (!composer.isConversion || !composesInCapture(composer)) return false
        val reading = captureCompositionIfLive(state, caret)?.keys?.takeIf { it.isNotEmpty() }
        if (reading == null) {
            if (state.captureSuggestions.isNotEmpty() || state.conversionReadings.isNotEmpty()) {
                _uiState.update { it.copy(captureSuggestions = emptyList(), conversionReadings = emptyList()) }
            }
            return true
        }
        val slots = state.settings.suggestionStrip.slotCount
        val key = state.captureKey()
        captureSuggestJob = serviceScope.launch {
            val (words, readings) = withContext(Dispatchers.Default) {
                composer.candidates(reading, slots) to composer.readings(reading)
            }
            _uiState.update { s ->
                if (s.captureKey() != key || s.captureCaretText() != caret) s
                else s.copy(captureSuggestions = words, conversionReadings = readings)
            }
        }
        return true
    }

    /**
     * A conversion candidate picked off a keyboard-owned field's strip: it
     * replaces the part of the composing run it covers and the rest keeps
     * composing, which is [commitConversionPrefix] without an InputConnection
     * to commit through (#527).
     *
     * Resolved by strip position, never by text: a candidate's text does not
     * identify it — `ja_kana` lists 行 under four different readings — and the
     * list on screen *is* [KeyboardUiState.captureSuggestions], so the position
     * is exact. False when the tap cannot be matched to it, and the caller
     * falls back to inserting the word as a plain suggestion pick.
     */
    private fun captureConversionPick(
        state: KeyboardUiState,
        target: CaptureTarget,
        before: CaretText,
        run: CaptureComposition,
        chosen: String,
    ): Boolean {
        val composer = state.composer
        val index = state.captureSuggestions.indexOf(chosen)
        if (index < 0) return false
        val consumed = composer.consumedForIndex(run.keys, index).coerceIn(1, run.keys.length)
        if (learningAllowed) composer.learnChoice(run.keys, index)
        val rest = composer.remainderAfterCommit(run.keys.substring(consumed))
        val shown = composer.composeBuffer(run.keys)
        val tail = composer.composeBuffer(rest)
        val text = before.text.substring(0, run.start) + chosen + tail +
            before.text.substring(run.start + shown.length)
        // No trailing space: a conversion commit never adds one, here or in a
        // field. captureWrite lets the word go, so the tail is re-seated after.
        captureWrite(
            target,
            before,
            CaretText(text, run.start + chosen.length + tail.length),
            keepsComposing = true,
        )
        captureComposition = if (rest.isEmpty()) {
            null
        } else {
            _uiState.value.captureKey()?.let { CaptureComposition(it, run.start + chosen.length, rest) }
        }
        publishKanaVariantReady()
        return true
    }

    /**
     * Where [refreshCaptureSuggestions] gets [target]'s words from, or null
     * when that source has not loaded yet.
     *
     * Two sources, because two of these boxes are searching two different
     * things. Everything that holds prose — the AI prompt, a plugin's field,
     * Find and replace — is completed against the language's word list, which
     * is what its text is going to be read as. The emoji panel's search box is
     * not: it queries the emoji catalog, so the word list would offer it
     * spellings no emoji is filed under ("cathedral" for "cat"), and every one
     * of those picks lands on an empty grid. It gets the catalog's own query
     * terms instead — keywords in every language merged into it, shortcode
     * names, the synonyms the search expands — so a chip always has results
     * behind it.
     *
     * The other three searches stay on the word list: the clipboard and the
     * personal dictionary are searched over the user's own text, and a media
     * query is a phrase for a remote service, so prose is what all three want.
     */
    private fun captureSuggestSource(
        target: CaptureTarget,
        caret: CaretText,
        // Qualified: this class carries a private `CaretWord` of its own, for
        // the strip's view of the word around the field's caret.
        word: com.wasimaster.wmkeyboard.ime.CaretWord,
        previous: String?,
        phonetic: String?,
        slots: Int,
    ): (() -> List<String>)? {
        if (target == CaptureTarget.EMOJI_SEARCH) {
            val index = emojiSearch ?: return null
            // The rest of the query, the word being typed aside: emoji search
            // accumulates over the query's words, so those are what a
            // completion has to share an emoji with.
            val rest = (caret.text.take(word.start) + " " + caret.text.drop(word.end))
                .split(' ', '\t', '\n')
                .filter { it.isNotBlank() }
            return { index.completions(word.typed, context = rest, limit = slots) }
        }
        val engine = suggestionEngine ?: return null
        return {
            // An empty word in front of the caret is the between-words case,
            // and `suggest` answers that with next-word predictions itself —
            // the same split the field's own strip makes.
            engine.suggest(
                composing = word.typed,
                previousWord = previous,
                phoneticLanguage = phonetic,
                limit = slots,
            )
        }
    }

    /** Debounce for [refreshCaptureSuggestions]; the field strip's own pace. */
    private var captureSuggestJob: Job? = null

    /**
     * A word picked off a keyboard-owned field's strip: it replaces the word
     * at the caret and leaves a space behind it, exactly as a pick does in a
     * real field. Nothing is learned from it — the word came from the word
     * list, and a search query is not writing.
     *
     * A conversion IME's candidate is a different thing with the same gesture,
     * and goes to [captureConversionPick]: it commits a prefix of the reading,
     * adds no space, and *is* learned, because which kanji a reading means is
     * not a search term (#527).
     */
    fun onCaptureSuggestion(word: String) {
        val state = _uiState.value
        val target = state.captureTarget() ?: return
        if (!target.takesWords) return
        vibrate()
        if (target == CaptureTarget.WORD_SPELL) {
            // The card is choosing one spelling, so a pick is the whole draft
            // and no space follows it.
            wordSpellEdit { it.copy(draft = word, cursor = word.length, anchor = word.length) }
            return
        }
        val before = state.captureCaretText() ?: return
        // A conversion pick commits the reading it covers and leaves the tail
        // composing, rather than replacing the "word" at the caret (#527).
        val run = if (state.composer.isConversion && composesInCapture(state.composer)) {
            liveCaptureComposition(state, before)
        } else {
            null
        }
        if (run != null && captureConversionPick(state, target, before, run, word)) {
            consumeShift()
            return
        }
        captureWrite(target, before, before.replacedWordAtCaret(word, spaceAfter = true))
        consumeShift()
    }

    /**
     * A glide drawn while a keyboard-owned field has the keys (#161).
     *
     * Decoded by the same engine and the same word list a field glide is, then
     * inserted at the field's own caret, one word per segment of a chained
     * stroke. Nothing reaches the app behind the keyboard, and nothing is
     * learned: a query is not writing, so a glide into one must not teach the
     * dictionary what the user was looking for.
     */
    private fun captureGlide(
        target: CaptureTarget,
        segments: List<List<GesturePoint>>,
        keys: List<KeyCenter>,
        keyWidthPx: Float,
        verdict: GlideVerdict,
        shift: ShiftState,
    ) {
        // Retires every preview from this stroke, in flight or queued, once
        // the word on screen is read: the lift owes it the word (#816).
        gestureGeneration.incrementAndGet()
        gestureJob?.cancel()
        val shownAtLift = previewGate.shown
        clearGlidePreview()
        if (verdict is GlideVerdict.Cancel) return
        val chosen = (verdict as? GlideVerdict.Word)?.word
        val steadiness = _uiState.value.settings.gesture.previewSteadiness
        // Under two-thumb typing a swipe that lands against letters is the
        // next piece of their word, as in the app's own field (#831): one
        // word, read again whole, with no space put in front of it.
        // Two-thumb only: an ordinary glide here ends with no space, and the
        // next one brings it (#300), so it must never join the last.
        val joins = chosen == null && segments.size == 1 &&
            _uiState.value.settings.gesture.twoThumbGlide && swipeJoinsWord(_uiState.value)
        gestureJob = serviceScope.launch {
            if (joins && captureJoinSwipe(target, segments.single(), keys, keyWidthPx)) {
                consumeShift()
                return@launch
            }
            for ((index, segment) in segments.withIndex()) {
                val last = index == segments.lastIndex
                val reading = withContext(Dispatchers.Default) {
                    glideDecode(segment, keys, keyWidthPx, guessAhead = last)
                }
                val picked = chosen?.takeIf { last }
                    ?: previewGate.commit(reading.words, reading.scores, steadiness, shownAtLift.takeIf { last })
                    ?: reading.words.firstOrNull()
                    ?: continue
                val word = glideCased(picked, shift, verdict.caseAt(index), segment, keys, keyWidthPx)
                // Re-read between segments: each one has moved the caret.
                val state = _uiState.value
                if (state.captureTarget() != target) return@launch
                val before = state.captureCaretText() ?: return@launch
                // A glide adds a word, spaced off whatever it lands next to —
                // except at the very end of a search query, where a trailing
                // space would hold the results back a word. The space arrives
                // with the next stroke instead, which is why this must not
                // replace the word at the caret the way a pick does (#300).
                captureWrite(target, before, before.glided(word))
            }
            consumeShift()
        }
    }

    /**
     * A two-thumb swipe in a keyboard-owned field joining the letters right
     * before its caret (#831). Those letters go in as taps where their keys
     * are, the swipe after them, and the word is read as the app's field
     * reads a two-thumb word; the reading replaces the letters, with no space
     * after it, so the next swipe or tap carries on the same word. False, with
     * nothing written, when no letters touch the caret, or they are not all
     * on this grid: the swipe is then a word of its own.
     */
    private suspend fun captureJoinSwipe(
        target: CaptureTarget,
        segment: List<GesturePoint>,
        keys: List<KeyCenter>,
        keyWidthPx: Float,
    ): Boolean {
        val start = _uiState.value.captureCaretText()?.takeIf { !it.hasSelection } ?: return false
        val span = start.wordAtCaret()
        val head = span.typed.takeIf { it.isNotEmpty() && span.end == start.at } ?: return false
        val gestures = DuetWord()
        if (!gestures.seed(head, null, keys, keyWidthPx)) return false
        gestures.addSwipe(segment, keys, keyWidthPx)
        val tokens = gestures.snapshot()
        val read = withContext(Dispatchers.Default) {
            duetReading(tokens, null, keys, keyWidthPx).words.firstOrNull()
                ?: duetPrefix(tokens, keys, keyWidthPx)
        } ?: gestures.literal()
        // The letters set the word's case, as typed letters do in the field.
        val word = when {
            head.length > 1 && head.all { !it.isLetter() || it.isUpperCase() } -> read.uppercase()
            head.first().isUpperCase() -> read.replaceFirstChar { it.uppercase() }
            else -> read
        }
        val state = _uiState.value
        if (state.captureTarget() != target) return true
        val before = state.captureCaretText() ?: return true
        // Something else wrote the box while the word was read.
        if (before != start) return true
        captureWrite(target, before, before.replacedWordAtCaret(word, spaceAfter = false))
        return true
    }

    /**
     * Shared path for one typed character, whether it came from a soft key
     * ([onTextKey]) or a physical keyboard ([handleHardwareKeyDown]).
     *
     * [applyDeadKeys] is true only for soft keys. A physical key's character
     * already carries the hardware layout's own shift and AltGr, and its dead
     * keys are composed by the framework before the IME sees them, so running
     * our dead-key state machine over it as well would double-apply accents.
     */
    private fun processTypedText(input: String, applyDeadKeys: Boolean) {
        commitSteppedCandidateBeforeTyping()
        closeRecentClips()
        val state = _uiState.value
        var text = input
        // A typed character is new text, so the span a pattern was told to
        // leave alone is no longer the span in front of the caret.
        patternMutedAfter = null
        // Any new input ends the window in which backspace reverts the
        // previous autocorrect.
        lastRevertible = null
        clearSwapOffer()
        // The mid-word strip is about the field as it was before this
        // keystroke; the caret's own settle re-derives it afterwards.
        clearCaretWord()
        // Khipro reads a word typed on a hardware keyboard against its desktop
        // spec (1 is ১, . is ।), one typed on the keys against the touchscreen
        // one. Chosen by the key that starts the word and kept to its end, so
        // one word never reads half one way and half the other.
        val khipro = state.composer
        if (khipro is KhiproComposer && composing.isEmpty()) {
            khipro.startWord(hardwareKeyboard = hardwareKeyTyping)
            refreshKhiproSpecsIfDue()
        }
        // One-shot, spent by this keystroke whatever it turns out to be: a mark
        // takes the keyboard's own space back, and anything else simply types
        // past it. Both kinds of space count — the one that ended a word (glide
        // or strip pick) and the one that followed a punctuation mark, which is
        // what makes the closing quote of `"hi."` hug the full stop instead of
        // landing a space past it (issue #34).
        val followsWordSpace = pendingWordSpace || pendingPunctuationSpace
        // The all-thumbs-up space a letter here may take back (#747): one-shot
        // like the flag, and only while the space behind the caret is ours.
        val allUpSpaceBehind = allUpSpace.takeIf { pendingWordSpace }
        allUpSpace = null
        pendingWordSpace = false
        pendingPunctuationSpace = false
        val spaceOwed = deferredWordSpace
        deferredWordSpace = false

        if (applyDeadKeys) {
            // Dead keys: the accent arms and waits, then fuses with the next
            // letter. Pressing the same accent twice types it literally, which
            // is the standard escape hatch for wanting the accent on its own.
            val pressedMark = DeadKeys.markOf(text)
            val armedMark = pendingDeadKey
            when {
                pressedMark != null && pressedMark == armedMark -> {
                    setPendingDeadKey(null)
                    text = DeadKeys.standalone(pressedMark)
                }
                pressedMark != null -> {
                    setPendingDeadKey(pressedMark)
                    // Nothing typed yet; the letter the accent lands on spends it.
                    deferredWordSpace = spaceOwed
                    consumeShift()
                    return
                }
                armedMark != null -> {
                    setPendingDeadKey(null)
                    text = DeadKeys.apply(armedMark, text)
                }
            }
        }

        // The keyboard's own fields take the character before any suggestion or
        // field machinery sees it — the typing test, which scores keystrokes
        // instead of committing them; the AI Custom instruction; a plugin's
        // text box; Find and replace; the Learn speller; the calculator and the
        // converters; the word card; and the four search queries. Returning
        // here, before the field is touched, is the whole guarantee: what the
        // user types into one of these never reaches the app behind the
        // keyboard. [captureTyped] is the single ladder that decides which.
        if (captureTyped(text)) {
            consumeShift()
            return
        }

        val ic = currentInputConnection ?: return
        // Past every keyboard-buffer and search intercept: this keystroke's
        // text is going to the field, so it is typing worth counting.
        recordStat { onTyped(text, System.currentTimeMillis(), SystemClock.uptimeMillis()) }
        // Fancy Text: the letters stay plain from here on, composed and
        // corrected like any other word, and [FancyOutputConnection] styles
        // whatever is committed (#950). Upside-down is the exception: it swaps
        // each key for its glyph at the last moment, after every keyboard-buffer
        // and search intercept above (those want plain, searchable letters) and
        // before the field sees anything, and never composes.
        val fancyStyle = fancyStyleFor(state)
        val fancyByKey = fancyStyle != null && !fancyComposes(state)
        if (fancyByKey) text = applyFancyStyle(text, fancyStyle)
        if (!fancyByKey && typeMyanmarVisualOrder(ic, text)) {
            consumeShift()
            return
        }
        // contextualForm is the identity for every composer except the
        // cluster-shaping (fixed Indic) ones, so only they are worth the
        // synchronous getTextBeforeCursor round-trip on the keypress path.
        // A non-empty buffer already *is* the text in front of the caret — a
        // resume mirrors the field's word into it and updateComposingText writes
        // it back verbatim — so while one is open the round-trip is skipped and
        // the answer comes from the buffer instead.
        if (state.composer.isClusterShaping) {
            val key = text
            val previous = composing.lastOrNull() ?: ic.getTextBeforeCursor(1, 0)?.lastOrNull()
            val glide = lastVowelGlide
            lastVowelGlide = null
            val now = SystemClock.uptimeMillis()
            val twice = glide != null && state.settings.suggestionStrip.bengaliVowelTwice &&
                composing.isEmpty() && glide.key == key && now - glide.at <= VOWEL_TWICE_MS &&
                ic.getTextBeforeCursor(glide.text.length, 0)?.toString() == glide.text
            if (twice && glide != null) {
                // The second press of #900: the glide the first one typed
                // becomes the vowel itself, য়া → আ, য়ে → এ.
                ic.deleteSurroundingText(glide.text.length, 0)
                invalidateExpectedSelection()
                text = BengaliGraphemes.vowelKeyText(key.single(), BengaliGraphemes.VowelKeyForm.INDEPENDENT) ?: key
            } else {
                text = fixedLayoutContextualVowel(key, previous)
                if (text != key && text.firstOrNull() == BENGALI_YA) lastVowelGlide = VowelGlide(key, text, now)
            }
        }

        // Typing over a selection replaces it and puts the cursor after the
        // new character, like every other keyboard. Never route through the
        // composing buffer in that case.
        if (hasSelection(ic)) {
            dropComposingForSelectionEdit(ic)
            // Bracket/brace/quote over a selection wraps it in the pair
            // ("foo" → "(foo)") instead of replacing it, and leaves the inner
            // text selected so it can be wrapped or re-cased again. Either half
            // of the pair wraps: ")" over "foo" is "(foo)" too.
            val pair = if (state.settings.textEditing.wrapSelectionWithPair && text.length == 1) {
                WRAP_PAIRS[text[0]]?.let { text to it } ?: WRAP_OPENERS[text[0]]?.let { it to text }
            } else {
                null
            }
            if (pair != null) {
                val (opener, closer) = pair
                val selected = ic.getSelectedText(0)?.toString().orEmpty()
                invalidateExpectedSelection()
                ic.beginBatchEdit()
                ic.commitText("$opener$selected$closer", 1)
                val end = ic.getExtractedText(ExtractedTextRequest(), 0)?.selectionEnd
                if (end != null) {
                    val innerEnd = end - closer.length
                    val innerStart = innerEnd - selected.length
                    if (innerStart in 0..innerEnd) ic.setSelection(innerStart, innerEnd)
                }
                ic.endBatchEdit()
                consumeShift()
                _uiState.update {
                    it.copy(composingPreview = "", suggestions = emptyList(), emojiSuggestions = emptyList(), octopus = emptyMap())
                }
                return
            }
            armSelectionRevision(ic)
            invalidateExpectedSelection()
            commitTypedCharacter(ic, text)
            consumeShift()
            _uiState.update {
                it.copy(
                    composingPreview = "",
                    suggestions = emptyList(),
                    emojiSuggestions = emptyList(),
                    octopus = emptyMap(),
                )
            }
            if (text.length == 1 && text[0] in SENTENCE_ENDERS) {
                previousWord = WordContext.SENTENCE_START
                previousWord2 = null
                previousWord3 = null
                // The undo chip is scoped to the sentence it corrected: past
                // the full stop the user has moved on, and a chip still
                // offering to rewrite a word two sentences back is a trap.
                clearUndoChip()
                maybeAutoCapitalize()
            }
            return
        }

        // A cluster-shaping layout composes only what a resume put in the buffer
        // (see composingMode below), and what continues *that* word is not always
        // a single letter: a Bengali vowel key becomes a kar — a combining mark,
        // which no letter test accepts — after a consonant, and the য়-glide form
        // it takes after another vowel is two characters. Both belong to the word
        // being composed, so both have to extend the buffer rather than break it
        // and commit the resumed word after a single keypress.
        val clusterContinuation = state.composer.isClusterShaping && composing.isNotEmpty() &&
            text.isNotEmpty() && text.all { isComposingWordChar(it) }
        // VNI spells Vietnamese tones/marks with digits, so a digit typed *while a
        // syllable is composing* feeds the buffer (the transducer eats it) instead
        // of committing. A digit on an empty buffer is a literal digit as usual —
        // except for a composer whose whole alphabet is digits (T9 pinyin), where
        // that rule would make the first key of every word commit as a number.
        val singleWordChar = text.length == 1 && (
            text[0].isLetter() || text[0] == '\'' ||
                state.composer.buffersChar(text[0], composing) ||
                (
                    state.composer.bufferDigits && text[0].isDigit() &&
                        (composing.isNotEmpty() || state.composer.digitsStartBuffer)
                    ) ||
                (
                    // Number-row slip capture: a digit typed *inside* a word
                    // joins the composing buffer so autocorrect can read it as
                    // the letter below it ("as3" → "ase"). Word-initial digits
                    // still commit literally ("3pm"), and without the number
                    // row on screen a digit was a long-press or symbols-layer
                    // choice — deliberate, never buffered.
                    text[0].isDigit() && composing.isNotEmpty() &&
                        state.settings.numberRow &&
                        state.settings.suggestionStrip.numberRowCorrections &&
                        state.allowsTypingIntelligence
                    ) ||
                (
                    // A hyphen after a letter joins the word: "well-pai"
                    // completes to "well-paid", not "paid". Not on a board
                    // whose buffer is an input spelling or a run of anchor
                    // letters rather than the word in the field.
                    joinsComposingWord(text[0], composing) &&
                        !state.composer.isTransliterating &&
                        !state.layouts.ambiguousKeys
                    )
            )
        val isWordChar = singleWordChar || clusterContinuation
        // Avro is a transliterating input method: its composing must run even
        // in password fields and with the strip off, or the roman keys commit
        // untransliterated and no Bengali is produced. English composing
        // exists to feed suggestions and autocorrect, so it stays gated on
        // those ([KeyboardUiState.composesWords] — which is also what lets a
        // URL bar compose once the strip is on it, #98).
        //
        // Fancy Text composes plain letters and styles them on the way out
        // (#950), except upside-down, styled key by key above: its glyphs
        // have no dictionary, and half are pairs that would fail isWordChar.
        //
        // A cluster-shaping layout (Probhat, Jatiya, fixed Devanagari…) types
        // its script straight into the field, so it does not compose *words* —
        // but it does have to keep composing one that a caret landing on it
        // re-armed ([restartSuggestionsAtCursor]), or the resume buys a single
        // keypress and drops the region again. So: never starts a buffer, always
        // continues the one it was handed, and the next word boundary ends it.
        val composingMode = !fancyByKey &&
            (!state.composer.isClusterShaping || composing.isNotEmpty()) &&
            (state.composer.isTransliterating || state.composesWords)

        // Before any of the branches below, because three of them write text and
        // each used to answer this differently: the colon went to the emoji
        // search, the apostrophe went into the composing buffer as a word
        // character, and only the third took the space back. A mark that hugs
        // the word in front of it hugs it whichever path it leaves by
        // (issue #123). Letters and digits are not marks, so a word typed after
        // a glide keeps its space exactly as before.
        //
        // ...unless this language spaces the mark instead ("Bonjour !", #215).
        // Then the space in front is not a slip to be swallowed, it is the
        // thing being typed, and the rules below put the language's own
        // no-break space there. Null means the mark takes no space *here* —
        // at the start of a line, or after another mark — and the ordinary
        // hugging applies after all.
        // A key No space was armed for (#863) has no space put in front of it.
        // Nor is the space already in front of it taken back: armed, `best .`
        // keeps the space after `best` (#863).
        val spacedRun = if (unspacedKey) null else spacedMarkRun(ic, text, state)
        val ateAutoSpace = spacedRun == null && !unspacedKey &&
            takeBackAutoSpace(ic, text, state, followsWordSpace)

        // ":" on a word boundary opens inline emoji search: the colon and the
        // letters after it go into the composing buffer, and refreshSuggestions
        // turns that buffer into emoji instead of words. Nothing else needs to
        // track a mode — "composing starts with a colon" *is* the mode, so
        // backspacing the colon away ends it on its own.
        // A colon the language spaces is punctuation, not the opening of a
        // shortcode: in French "voici :" ends a clause. Only where the space
        // belongs, so ":tada:" at the start of a line still opens the search.
        if (state.settings.suggestionSources.inlineEmojiSearch && text == ":" &&
            composing.isEmpty() && composingMode && spacedRun == null
        ) {
            // Which of the two this colon turns out to be is not knowable yet,
            // so the space above is taken now and handed back if a shortcode
            // does complete.
            emojiQueryAteSpace = ateAutoSpace
            commitComposing(ic, autocorrect = false)
            appendComposing(text)
            updateComposingText(ic)
            refreshSuggestions()
            consumeShift()
            return
        }

        // ...and the closing ":" finishes it the way GitHub, Discord and Slack
        // do: ":tada:" becomes 🎉 outright. Exact shortcodes only — a partial
        // or unknown name stays the literal text the user typed, so the colon
        // never eats something it couldn't name.
        if (state.settings.suggestionSources.inlineEmojiSearch && text == ":" && composing.startsWith(":")) {
            val emoji = emojiShortcodes.exact(composing.substring(1))
            if (emoji != null) {
                revision = null
                composing = StringBuilder()
                // The query turned out to be a search after all, so the space
                // the opening colon took back belongs to the emoji: ":tada:"
                // after a glided word is "hello 🎉", not "hello🎉".
                val restored = if (emojiQueryAteSpace) " " else ""
                emojiQueryAteSpace = false
                ic.commitText(restored + applyEmojiTone(emoji), 1)
                learnEmoji(emoji)
                recordEmojiUse(emoji)
                _uiState.update {
                    it.copy(
                        composingPreview = "",
                        suggestions = emptyList(),
                        octopus = emptyMap(),
                        emojiSuggestions = emptyList(),
                        inlineEmoji = false,
                    )
                }
                consumeShift()
                return
            }
        }

        // An apostrophe after a prefix that elides ends the prefix instead of
        // joining the word: "l'" commits and "alp…" composes on its own, so its
        // completion is "alphabet" and lands as "l'alphabet" rather than in
        // place of the "l'" (#215). English keeps the apostrophe in the
        // buffer, where it is a letter inside "don't".
        val elisionBreak = composing.isNotEmpty() && text.length == 1 &&
            WordContext.isApostrophe(text[0]) &&
            Elisions.rulesFor(state.language.id)?.isPrefix(composing) == true
        // A word picked in front of a mark held its space back (#679): a
        // letter now starts the next word, so the space goes in first, between
        // the two words and still in front of the mark.
        if (spaceOwed && composing.isEmpty() && text.firstOrNull()?.isLetterOrDigit() == true) {
            ic.commitText(" ", 1)
            invalidateExpectedSelection()
        }
        // A letter straight after an all-thumbs-up space may carry the word
        // before it on instead (#747): the space goes, and the word is open
        // again for this letter to join.
        if (allUpSpaceBehind != null && isWordChar && composingMode && !elisionBreak && composing.isEmpty()) {
            reopenAfterAllUpSpace(ic, state, allUpSpaceBehind, setOf(text.lowercase()))
        }
        // Keys typed into another word on Khipro are a piece of that word: a
        // kar put back into কিঞ্চ|ত, not an English word (#986). Asked once,
        // where the word starts, so the keystrokes after it pay nothing.
        if (isWordChar && composingMode && !elisionBreak && composing.isEmpty() &&
            state.composer.completionLanguage != null
        ) {
            completionInsideWord =
                ic.getTextBeforeCursor(1, 0)?.lastOrNull()?.let(WordContext::isWordChar) == true ||
                ic.getTextAfterCursor(1, 0)?.firstOrNull()?.let(::continuesWordAhead) == true
        }
        if (isWordChar && composingMode && !elisionBreak && duetTap(text)) {
            consumeShift()
        } else if (isWordChar && composingMode && !elisionBreak) {
            appendComposing(text)
            // A tapped word ends at the all-thumbs-up pause too (#676).
            allUpArmed = true
            updateComposingText(ic)
            // A trigger set to expand immediately fires on this letter, with
            // nothing after it (`btw`, `;;addr`).
            if (tryImmediateExpansion(ic, text, state)) {
                consumeShift()
                return
            }
            // A reopened word that this letter leads nowhere is two words
            // after all, and splits back where its space was.
            if (reopenedHolds(complete = false)) refreshSuggestions() else splitReopenedWord(ic)
            consumeShift()
        } else {
            // A pattern may fire here too, but only for the marks that really
            // end a word. This branch also takes every symbol-layer insert,
            // every slash and every digit, and a pattern eating text behind one
            // of those is not what anybody typed.
            val endsWord = text.length == 1 &&
                (text[0] in SENTENCE_ENDERS || text[0] in AUTO_SPACE_PUNCTUATION)
            // A full stop ends a word as squarely as a space does, so the
            // apostrophe a contraction is missing goes back the same way:
            // "thats." was the one ending that left it out (#240). Only for
            // the marks that end a word — a slash or a symbol-layer insert is
            // a character landing mid-thought, not a word being finished.
            // Autocorrect only when asked for (#562): a mark is also typed for
            // its own sake, after an abbreviation or a name no list holds, so
            // by default the space bar is still where a word gets
            // second-guessed.
            val committedWord = commitComposing(
                ic,
                autocorrect = endsWord && state.settings.correction.enabledFor(state.language.id) &&
                    state.settings.correction.onPunctuation,
                fixApostrophes = endsWord && state.settings.autoText.apostrophe,
                expandPatterns = endsWord,
            )
            // Nothing of ours was composing, but the editor may still hold a
            // region the keyboard has already let go of: a word the caret
            // paused in mid-scrub, re-armed, then left behind. The mark's
            // commitText would replace that region instead of landing at the
            // caret, and "word!" with the caret after the quote became "? !"
            // (#365). Finishing never changes the text, only the span.
            if (!committedWord) ic.finishComposingText()
            if (swallowTerminatorAfterCommit) {
                swallowTerminatorAfterCommit = false
                consumeShift()
                return
            }
            // A closer typed straight onto the one the auto-close rule put
            // there steps over it instead of doubling it. Before every spacing
            // rule below, because nothing is being typed: the caret moves and
            // the field is left exactly as it stands.
            val steppedOver = typeOverCloser(ic, text, state)
            if (steppedOver != null) {
                // Stepping over ")" closes the bracket as surely as typing it
                // does, so the space after punctuation follows it the same way.
                if (steppedOver) insertPunctuationSpace(ic)
                consumeShift()
                return
            }
            // The user's own space in front of a mark, under the rule that asks
            // for it: "Hey ." is a slip, and the mark lands on the word. The
            // keyboard's own auto-space was already taken back above.
            val hugged = if (spacedRun != null) null else takeBackStraySpace(ic, text, state)
            val autoSpace = shouldAutoSpaceAfterPunctuation(ic, state, text)
            if (autoSpace) {
                // A run of marks ("...", "?!") must not be pulled apart by the
                // spaces this rule types, so the one from the previous mark is
                // taken back before the new mark lands.
                val before = ic.getTextBeforeCursor(2, 0)?.toString().orEmpty()
                if (before.length == 2 && before[1] == ' ' && before[0] in AUTO_SPACE_PUNCTUATION) {
                    ic.deleteSurroundingText(1, 0)
                }
            }
            // Last thing before the mark lands, so the word it attaches to is
            // already in the field and any pattern expansion above has had its
            // say. Returns what stood there before — usually nothing, sometimes
            // the plain space the user or the keyboard typed.
            val spacedOver = if (spacedRun == null) null else insertSpaceBeforeMark(ic, text, state)
            commitTypedCharacter(ic, text)
            if (hugged != null) {
                // One backspace puts the space back, the same as any other
                // correction: the rule removed something the user typed.
                lastRevertible = RevertibleCommit(
                    RevertibleCommit.Kind.JOIN, original = hugged + text, committed = text,
                )
                armRevertGuard()
            } else if (isSpacedOpener(text, state)) {
                // "«" opens a French quotation and the space is part of it, so
                // it is typed here rather than left for the user — and, being
                // in the field already, there is no bare opener for a glided
                // word to go up against.
                ic.commitText(SpacedPunctuation.SPACE.toString(), 1)
                invalidateExpectedSelection()
                lastRevertible = RevertibleCommit(
                    RevertibleCommit.Kind.JOIN,
                    original = text,
                    committed = text + SpacedPunctuation.SPACE,
                )
                armRevertGuard()
            } else if (spacedOver != null) {
                // The mirror of the hug undo: this rule *added* a space, so one
                // backspace takes it back out and leaves whatever the user had
                // there. A French writer quoting code gets "x?" in one press.
                lastRevertible = RevertibleCommit(
                    RevertibleCommit.Kind.JOIN,
                    original = spacedOver + text,
                    committed = SpacedPunctuation.SPACE + text,
                )
                armRevertGuard()
            }
            // A trigger that ends in this very mark (#471) fires now that the
            // mark is in the field, before the bracket and the spacing rules
            // put anything after it.
            if (trySuffixExpansion(ic, text, state)) {
                consumeShift()
                return
            }
            // ...and one set to expand immediately, for the characters that
            // land here rather than in a buffer: every letter in a field that
            // composes nothing, a word-initial digit, a bare symbol trigger.
            if (tryImmediateExpansion(ic, text, state)) {
                consumeShift()
                return
            }
            // The other half of an opening bracket, behind the caret. Last of
            // the rules that touch the field, so it closes what actually
            // landed after the spacing rules above have had their say.
            autoCloseBracket(ic, text, state)
            // Second look, now that the mark is in the field. The commit above
            // matched over the word alone, and a pattern about the mark itself
            // ("hi ." to "hi.") has nothing to match until the mark has landed.
            // Only when the first look changed nothing: after an expansion the
            // field holds the snippet's output, not the user's words, and a
            // pattern must not get to eat its own result.
            if (endsWord && !patternFiredAtCommit && tryPatternExpansion(ic, "", state)) {
                if (swallowTerminatorAfterCommit) {
                    // The caret was parked inside the expansion; a space typed
                    // there would split it, the same as on the commit path.
                    swallowTerminatorAfterCommit = false
                    consumeShift()
                    return
                }
            }
            if (autoSpace) insertPunctuationSpace(ic)
            // Consume one-shot shift before evaluating auto-capitalize, so a
            // sentence ender can turn shift back on for the next sentence.
            consumeShift()
            if (text.length == 1 && text[0] in SENTENCE_ENDERS) {
                // The next word starts a sentence: its bigram context is the
                // sentinel, not the word before the full stop.
                previousWord = WordContext.SENTENCE_START
                previousWord2 = null
                previousWord3 = null
                // ...and the undo chip belongs to the sentence just closed.
                clearUndoChip()
                maybeAutoCapitalize()
                showSentenceOpeners()
            }
            // Email fields commit straight through (no composing buffer), so the
            // contact-email strip has to be refreshed off the committed text.
            if (emailFieldForceActive(state)) refreshEmailFieldSuggestions()
        }
    }

    /**
     * Whether the just-typed [text] should be followed by a space typed for the
     * user (see [AutoTextSettings.spaceAfterPunctuation]).
     *
     * Structured fields are excluded through [KeyboardUiState.allowsTypingIntelligence],
     * which is exactly the URL / email / password / keypad set: a space inserted
     * into an address or a password is a typo, not a courtesy. Scripts that
     * write without spaces (Chinese, Japanese, Thai…) are excluded too — their
     * punctuation is followed by nothing, and the wide forms (。、！) are not in
     * [AUTO_SPACE_PUNCTUATION] for the same reason. A mark typed straight after
     * a digit is part of the number ("5,000", "5:00") and gets no space
     * (#206, [markContinuesNumber]), and a full stop inside an email address
     * typed into a plain text field is the address's own dot ([markContinuesAddress]);
     * the field is read last, and only for a mark. A closing [SPACED_CLOSER] is
     * spaced too, but only where it ends the text it closes ([closerTakesSpace]),
     * and so is a closing quote (#662, [closingQuoteTakesSpace]).
     *
     * The closers are also spaced in a browser's address bar once what is being
     * typed there is a search, which is what a space in it says (#662): the
     * quote that closes `"exact phrase"` is followed by the next word, the same
     * as in a message. Marks keep out of it: a full stop or a colon typed there
     * is far more often part of an address.
     *
     * [overCloser] is for a closer the caret is about to step over rather
     * than type ([typeOverCloser]), asked before the step, with the text
     * after the closer read one character on. Asked after the step, the
     * answer hung on the editor having moved the caret already, and a
     * browser applies a `setSelection` later than the next read: the read
     * still found the `)` in front of the caret and no space followed (#679).
     */
    private fun shouldAutoSpaceAfterPunctuation(
        ic: InputConnection,
        state: KeyboardUiState,
        text: String,
        overCloser: Boolean = false,
    ): Boolean {
        if (!state.settings.autoText.spaceAfterPunctuation || state.composer.isConversion || text.length != 1) {
            return false
        }
        // No space armed for this key (#863): the `.` of `github.com`.
        if (unspacedKey) return false
        val mark = text[0]
        if (mark == SPACED_CLOSER || mayCloseQuote(mark)) {
            val prose = state.allowsTypingIntelligence
            val search = !prose && state.allowsBracketPairs && state.fieldKind == FieldKind.URI
            if (!prose && !search) return false
            // Read once, and only now that the mark is one of these.
            var line: String? = null
            fun before(): String = line ?: quoteContext(ic).also { line = it }
            if (search && !typedAsSearch(before())) return false
            if (mark != SPACED_CLOSER && !closingQuoteTakesSpace(mark, ::before)) return false
            // No number test: "(page 5)" ends on a digit and is still a
            // closed bracket, not part of the number.
            val skip = if (overCloser) 1 else 0
            return closerTakesSpace(ic.getTextAfterCursor(1 + skip, 0)?.drop(skip))
        }
        return state.allowsTypingIntelligence &&
            mark in AUTO_SPACE_PUNCTUATION &&
            (ic.getTextBeforeCursor(ADDRESS_LOOKBACK, 0) ?: "").let { before ->
                !markContinuesNumber(before) && !markContinuesAddress(before, mark)
            }
    }

    /**
     * Commits [typed] closed up onto the full stop in front of it, taking back
     * the space the auto-space after punctuation put between them, when the
     * word is a domain ending or a file extension ([dotSuffixJoin]). Says
     * whether it did.
     *
     * Only on a board whose buffer is the text in the field: a transliterating
     * or ambiguous one holds keystrokes, not the word they spell. A backspace
     * straight afterwards puts the space back.
     */
    private fun joinDotSuffix(ic: InputConnection, typed: String, state: KeyboardUiState): Boolean {
        if (!state.settings.autoText.spaceAfterPunctuation || !state.allowsTypingIntelligence ||
            state.composer.isTransliterating || state.layouts.ambiguousKeys
        ) {
            return false
        }
        val before = ic.getTextBeforeCursor(typed.length + DOT_SUFFIX_LOOKBACK, 0) ?: return false
        if (before.length <= typed.length || !before.endsWith(typed)) return false
        val word = dotSuffixJoin(before.subSequence(0, before.length - typed.length), typed) ?: return false
        ic.beginBatchEdit()
        ic.commitText("", 1)
        ic.deleteSurroundingText(1, 0)
        ic.commitText(word, 1)
        ic.endBatchEdit()
        invalidateExpectedSelection()
        composing = StringBuilder()
        _uiState.update {
            it.copy(composingPreview = "", suggestions = emptyList(), emojiSuggestions = emptyList(), octopus = emptyMap())
        }
        lastRevertible = RevertibleCommit(RevertibleCommit.Kind.JOIN, original = " $typed", committed = word)
        armRevertGuard()
        return true
    }

    /**
     * Whether [c] is a mark the auto-space after punctuation follows, so the
     * space in front of the caret after it is one the keyboard typed: the
     * ordinary marks, the closing bracket and the closing quotes. The space
     * press and the shift press that take that space back ask this.
     */
    private fun isAutoSpacedMark(c: Char): Boolean =
        c in AUTO_SPACE_PUNCTUATION || c == SPACED_CLOSER || mayCloseQuote(c)

    /**
     * Types the space that follows an auto-spaced punctuation mark, unless the
     * text already continues with one — pressing "," in the middle of "a, b"
     * must not push a second space in.
     *
     * Arms the same one-shot cancel the ". " from a double space uses: a shift
     * press right afterwards takes the space back (see [onShift]), a space
     * press is swallowed rather than doubled (see [onSpace]), and a closing
     * mark takes it back the way it takes back a glide's (see [swallowsAutoSpace]).
     */
    private fun insertPunctuationSpace(ic: InputConnection) {
        if (stepOverFollowingSpace(ic)) return
        mirrorTypedIntoRevision(ic, " ")
        ic.commitText(" ", 1)
        pendingAutoSpace = true
        pendingPunctuationSpace = true
        // The caret anchor has to be re-taken from this commit's own echo, or
        // the selection update it triggers reads as "the user moved the caret"
        // and disarms the cancel before it can ever be used.
        armRevertGuard()
    }

    /**
     * Moves the caret past the space already in front of it, and says whether
     * there was one to move past.
     *
     * Every rule that types a space after something — a word ended by the
     * space bar, an auto-spaced mark, a glided word — used to stop short when
     * the text already went on with a space, which left the caret in front of
     * it: "auto⌶ space", type "matic" and a space, and the next word ran into
     * the one after it ("automatic⌶ space" then "automaticword space"). From
     * there every later space and mark landed in front of that same old space,
     * so the auto-spacing looked switched off for the rest of the sentence
     * (#508, #662). Other keyboards step over it, so the caret lands at the
     * start of the next word: "automatic ⌶space".
     *
     * The space is taken from in front of the caret and put back behind it
     * rather than the caret being moved, because a caret move needs the
     * caret's offset and not every editor will give it. The text is the same
     * either way, the very same character included, a no-break space or a tab.
     * A line break is not a space here, for the reason [spacedAfterCaret] gives.
     * [trustWeb] lets a web editor's text count, for a caller that knows it is
     * real.
     */
    private fun stepOverFollowingSpace(ic: InputConnection, trustWeb: Boolean = false): Boolean {
        if (!trustWeb && isWebEditField()) return false
        val next = ic.getTextAfterCursor(1, 0)
        if (next == null || !spacedAfterCaret(next)) return false
        val gap = next.subSequence(0, 1).toString()
        mirrorTypedIntoRevision(ic, gap)
        ic.beginBatchEdit()
        ic.deleteSurroundingText(0, 1)
        ic.commitText(gap, 1)
        ic.endBatchEdit()
        invalidateExpectedSelection()
        return true
    }

    /**
     * The text in front of the caret that tells an opening quote from a closing
     * one — see [closesQuote]. Read only when the typed character is a quote,
     * because this is an editor round trip and every other keystroke would pay
     * for it and throw the answer away.
     *
     * [QUOTE_CONTEXT_CHARS] is the window. The count only has to reach back to
     * the start of the line, and a quotation that opened more than that many
     * characters ago is one nobody is still closing by hand.
     */
    private fun quoteContext(ic: InputConnection): String =
        ic.getTextBeforeCursor(QUOTE_CONTEXT_CHARS, 0)?.toString().orEmpty()

    /**
     * Takes back the space in front of the caret when [text] is a mark that
     * hugs the word before it, and says whether it removed one.
     *
     * The space in front of the caret was the keyboard's, not the user's: a
     * mark landing on it belongs to the word ("hello." not "hello ."), so it
     * comes back out before the mark commits. A user's own space is left alone,
     * which is what [follows] carries — theirs to keep.
     *
     * A method rather than four lines inline because the inline emoji search
     * takes the colon on its own path, and a colon that hugs on one path and
     * floats on the other is the whole of issue #123.
     */
    private fun takeBackAutoSpace(
        ic: InputConnection,
        text: String,
        state: KeyboardUiState,
        follows: Boolean,
    ): Boolean {
        if (!follows || !swallowsAutoSpace(text, state.fieldKind) { quoteContext(ic) }) return false
        if (ic.getTextBeforeCursor(1, 0)?.toString() != " ") return false
        ic.deleteSurroundingText(1, 0)
        return true
    }

    /**
     * The marks the active language keeps a space in *front* of, or "" when
     * nothing here spaces anything — no language table, the setting off, or a
     * field the keyboard keeps its hands out of.
     *
     * The conversion guard is [takeBackStraySpace]'s: while a transliterating
     * composer is mid-conversion the marks are input, not punctuation.
     */
    private fun spacedMarks(state: KeyboardUiState): String =
        if (state.settings.autoText.languagePunctuationSpacing &&
            state.allowsTypingIntelligence &&
            !state.composer.isConversion
        ) {
            state.language.spacedPunctuation
        } else {
            ""
        }

    /**
     * How many characters in front of the caret the language's space should
     * replace when [text] lands, or null when this mark takes no space here.
     *
     * Costs an editor read, so the mark is checked against the language's list
     * first: on every other keystroke, and in every language that spaces
     * nothing, this answers null without touching the field.
     */
    private fun spacedMarkRun(ic: InputConnection, text: String, state: KeyboardUiState): Int? {
        val marks = spacedMarks(state)
        if (marks.isEmpty() || text.length != 1 || text[0] !in marks) return null
        val before = ic.getTextBeforeCursor(SpacedPunctuation.LOOKBACK, 0) ?: return null
        return SpacedPunctuation.spacesToReplace(before, text[0], marks)
    }

    /**
     * Whether [text] is a mark the active language keeps a space *after* — the
     * opening guillemet, and so far only that.
     *
     * No field read and no position test, unlike the marks that take a space in
     * front. An opener has nothing behind it that the space could belong to:
     * wherever it lands, the quotation starts after it.
     */
    private fun isSpacedOpener(text: String, state: KeyboardUiState): Boolean {
        if (!state.settings.autoText.languagePunctuationSpacing ||
            !state.allowsTypingIntelligence || state.composer.isConversion
        ) {
            return false
        }
        val openers = state.language.spacedOpeners
        return openers.isNotEmpty() && text.length == 1 && text[0] in openers
    }

    /**
     * Types the other half of the opening bracket [text] behind the caret, so
     * the next character lands inside the pair (issue #319).
     *
     * Called after [text] itself has landed. The membership test comes before
     * the editor read, so every other keystroke — and every keystroke at all
     * while the setting is off — pays nothing for this. Structured fields are
     * excluded the way every other typing rule excludes them: a bracket in a
     * password is a character, not a pair.
     */
    private fun autoCloseBracket(ic: InputConnection, text: String, state: KeyboardUiState) {
        if (!state.settings.textEditing.autoCloseBrackets || !state.allowsBracketPairs) return
        if (text.length != 1 || text[0] !in AUTO_CLOSE_PAIRS) return
        val closer = autoCloseCloserFor(text[0], ic.getTextAfterCursor(1, 0)) ?: return
        // The closer goes in like any typed character and the caret is then put
        // back where it stood, between the two halves. A commit with
        // newCursorPosition 0 says the same thing in one call, but only a plain
        // EditText honours it: a web editor (notes.futo.tech, any page that
        // runs its own beforeinput handler) and the custom inputs of apps like
        // Discord insert the text themselves and leave the caret after it, so
        // the pair came out with the caret outside (#617). Where the field will
        // not say where its caret is, that one call is still the best on offer.
        val caret = caretOffset(ic)
        if (caret == null) {
            ic.commitText(closer, 0)
        } else {
            ic.beginBatchEdit()
            ic.commitText(closer, 1)
            ic.setSelection(caret, caret)
            ic.endBatchEdit()
        }
        invalidateExpectedSelection()
    }

    /**
     * Where the collapsed caret is, as an offset into the whole text, or null
     * when the editor will not say. Asked of the editor rather than of
     * expectedSel*, which is a mirror any edit this keystroke made has
     * already invalidated. [ExtractedText.selectionEnd] counts from
     * [ExtractedText.startOffset], which a field that extracts only part of a
     * long text puts somewhere past 0.
     */
    private fun caretOffset(ic: InputConnection): Int? {
        val extracted = ic.getExtractedText(ExtractedTextRequest(), 0) ?: return null
        if (extracted.selectionEnd < 0) return null
        return extracted.startOffset + extracted.selectionEnd
    }

    /**
     * Whether this backspace is undoing an auto-closed pair, so it should take
     * both halves rather than strand the closer. [before] is the text already
     * read from behind the caret.
     *
     * The opener is tested before the field is read again, so an ordinary
     * backspace — and every backspace at all while the setting is off — costs
     * nothing here. Held repeats run this path many times a second.
     */
    private fun deletesAutoClosedPair(
        ic: InputConnection,
        before: CharSequence,
        state: KeyboardUiState,
    ): Boolean {
        if (!state.settings.textEditing.autoCloseBrackets || !state.allowsBracketPairs) {
            return false
        }
        val opener = before.lastOrNull() ?: return false
        if (opener !in AUTO_CLOSE_PAIRS) return false
        return deletesEmptyPair(before, ic.getTextAfterCursor(1, 0))
    }

    /**
     * Steps the caret over the closing bracket already in front of it instead
     * of typing a second one, and says whether it did.
     *
     * The habit of typing both halves is what this is for: with auto-close on,
     * "(" then ")" would otherwise read "())". Nothing is inserted or deleted,
     * so no spacing, pattern or learning rule has anything to act on — hence
     * the early return at the call site.
     *
     * Null when it did not step. Otherwise whether the space after
     * punctuation follows the closer, decided before the caret moves (see
     * the `overCloser` note on [shouldAutoSpaceAfterPunctuation]).
     */
    private fun typeOverCloser(ic: InputConnection, text: String, state: KeyboardUiState): Boolean? {
        if (!state.settings.textEditing.autoCloseBrackets || !state.allowsBracketPairs) {
            return null
        }
        if (text.length != 1 || text[0] !in AUTO_CLOSE_CLOSERS) return null
        if (!typesOverCloser(text[0], ic.getTextAfterCursor(1, 0))) return null
        val end = caretOffset(ic) ?: return null
        val spaced = shouldAutoSpaceAfterPunctuation(ic, state, text, overCloser = true)
        invalidateExpectedSelection()
        ic.setSelection(end + 1, end + 1)
        return spaced
    }

    /**
     * Puts the language's no-break space in front of [text], and says what was
     * standing there before (so a backspace can put it back), or null when
     * nothing was done.
     *
     * Called after the composing word has committed, and re-reading the field
     * rather than trusting the count taken before it: a pattern expansion on
     * the way through can rewrite the very text the space attaches to.
     */
    private fun insertSpaceBeforeMark(ic: InputConnection, text: String, state: KeyboardUiState): String? {
        val run = spacedMarkRun(ic, text, state) ?: return null
        val removed = if (run > 0) {
            val existing = ic.getTextBeforeCursor(run, 0)?.toString() ?: return null
            ic.deleteSurroundingText(run, 0)
            existing
        } else {
            ""
        }
        ic.commitText(SpacedPunctuation.SPACE.toString(), 1)
        invalidateExpectedSelection()
        return removed
    }

    /**
     * Takes back the spaces the user typed in front of the caret when [text]
     * is a mark on the [AutoTextSettings.hugPunctuationMarks] list, and says
     * what it removed (so a backspace can put it back), or null.
     *
     * The decision is [straySpacesBefore]'s; this only reads the field and
     * edits it. Structured fields are out for the same reason they are out of
     * [shouldAutoSpaceAfterPunctuation]: a space in an address or a password
     * is the user's business.
     */
    private fun takeBackStraySpace(ic: InputConnection, text: String, state: KeyboardUiState): String? {
        val autoText = state.settings.autoText
        if (!autoText.hugPunctuation || !state.allowsTypingIntelligence || state.composer.isConversion) {
            return null
        }
        val mark = text.singleOrNull() ?: return null
        val before = ic.getTextBeforeCursor(HUG_LOOKBACK, 0) ?: return null
        val spaces = straySpacesBefore(before, mark, autoText.hugPunctuationMarks)
        if (spaces == 0) return null
        ic.deleteSurroundingText(spaces, 0)
        invalidateExpectedSelection()
        return " ".repeat(spaces)
    }

    /**
     * The Fancy Text style in force, or null everywhere outside the fancy
     * layout. The session override (the strip's tap, for instant response)
     * wins over the persisted pick.
     */
    private fun fancyStyleFor(state: KeyboardUiState): FancyStyle? =
        if (state.language.id == FancyStyles.LANG_ID) {
            // A font the user has since deleted falls back to the default style
            // rather than to null, which would read as "not the fancy keyboard".
            FancyStyles.byId(
                state.activeFancyStyleId ?: state.settings.layoutBehavior.fancyStyleId,
            ) ?: FancyStyles.byId(FancyStyles.DEFAULT_ID)
        } else {
            null
        }

    /** [text] restyled, or unchanged when no fancy style is in force. */
    private fun applyFancyStyle(text: String, style: FancyStyle?): String =
        if (style != null) FancyStyles.transform(text, style) else text

    /**
     * Whether Fancy Text composes plain words, with suggestions and
     * autocorrection, and styles them on their way into the field (#950).
     * Every style but upside-down: its letters only read right once the
     * whole line is reversed, so it keeps typing glyph by glyph.
     */
    private fun fancyComposes(state: KeyboardUiState): Boolean =
        fancyStyleFor(state)?.let { it.assembly != FancyAssembly.REVERSED } == true

    /**
     * The style the field's text is written in while Fancy Text composes, or
     * null when what goes into the field is what was typed: off the fancy
     * layout, on Normal, and on upside-down, which styles each key itself.
     * Non-null routes every commit through [FancyOutputConnection].
     */
    private fun fancyOutputStyle(state: KeyboardUiState): FancyStyle? =
        fancyStyleFor(state)?.takeIf { it.id != FancyStyles.NORMAL_ID && it.assembly != FancyAssembly.REVERSED }

    /** [text] as the field holds it once committed: styled under [fancyOutputStyle]. */
    private fun fieldForm(text: String, state: KeyboardUiState = _uiState.value): String =
        applyFancyStyle(text, fancyOutputStyle(state))

    /** A style chip on the fancy strip: instant in-session, persisted behind. */
    fun onFancyStyleSelect(id: String) {
        vibrate()
        _uiState.update { it.copy(activeFancyStyleId = id) }
        // The word being typed takes the new style at once, not at its next letter.
        if (composing.isNotEmpty()) currentInputConnection?.let(::updateComposingText)
        serviceScope.launch { settingsRepository.setFancyStyle(id) }
    }

    /**
     * The layout the Fancy tool switched away from, and the marker that the tool
     * — rather than the 🌐 key — is what put Fancy Text on screen. Session-only
     * on purpose: it says where to go back to, which is a fact about this
     * sitting at the keyboard and not a setting to carry into the next one.
     */
    private var fancyToolReturnLayoutId: String? = null

    /** Set when the keyboard closed with Fancy Text on and the setting asks for the switch back. */
    private var fancyToolAutoOffPending = false

    /**
     * The Fancy tool: put the fancy layout on the keyboard, or take it back off.
     *
     * Turning it on adds the layout to the enabled cycle when it isn't there
     * already, so a user who never opened the language settings still gets it in
     * one press. Turning it off returns to the layout it came from and takes the
     * cycle back to what it was, unless
     * [LayoutBehaviorSettings.fancyToolKeepsLanguage] says to leave it.
     */
    fun onFancyToggle() {
        vibrate()
        val state = _uiState.value
        if (state.language.id == FancyStyles.LANG_ID) turnFancyOff(state) else turnFancyOn(state)
    }

    private fun turnFancyOn(state: KeyboardUiState) {
        val behavior = state.settings.layoutBehavior
        fancyToolReturnLayoutId = state.layoutId
        // A pinned style applies to the session only. Writing it through would
        // make the tool quietly replace whatever style the strip last chose.
        val style = behavior.fancyToolStyleId?.let { FancyStyles.byId(it) }
        if (style != null) _uiState.update { it.copy(activeFancyStyleId = style.id) }
        val enabled = state.settings.enabledLayoutIds
        if (AssetLayouts.FANCY_ID !in enabled) {
            serviceScope.launch {
                settingsRepository.setEnabledLayoutIds(enabled + AssetLayouts.FANCY_ID)
            }
        }
        onLayoutSelected(AssetLayouts.FANCY_ID, recordRecent = false)
        val active = style ?: fancyStyleFor(_uiState.value)
        Toast.makeText(
            this,
            if (active != null) {
                getString(R.string.ime_service_fancy_on_style_toast, active.name)
            } else {
                getString(R.string.ime_service_fancy_on_toast)
            },
            Toast.LENGTH_SHORT,
        ).show()
    }

    /** [turnFancyOn]'s opposite. [quiet] is the automatic pass, which says nothing. */
    private fun turnFancyOff(state: KeyboardUiState, quiet: Boolean = false) {
        // The word being typed is written in the style it was typed in, before
        // the session style is let go of below.
        currentInputConnection?.let { commitComposing(it, autocorrect = false) }
        val remaining = state.settings.enabledLayoutIds.filter { it != AssetLayouts.FANCY_ID }
        val target = layoutAfterFancy(fancyToolReturnLayoutId, remaining)
        fancyToolReturnLayoutId = null
        // The session style dies with the layout, so the next time the tool runs
        // it starts from the pinned or persisted style rather than this one.
        _uiState.update { it.copy(activeFancyStyleId = null) }
        // Never empty the cycle: one layout has to stay enabled, and a user with
        // only Fancy Text enabled asked for exactly that.
        if (!state.settings.layoutBehavior.fancyToolKeepsLanguage && remaining.isNotEmpty()) {
            serviceScope.launch { settingsRepository.setEnabledLayoutIds(remaining) }
        }
        onLayoutSelected(target, recordRecent = false)
        if (!quiet) {
            Toast.makeText(this, getString(R.string.ime_service_fancy_off_toast), Toast.LENGTH_SHORT)
                .show()
        }
    }

    private fun keyOutput(key: Key, state: KeyboardUiState): String {
        val base = key.output ?: key.label
        // The number row's other numeral system, picked from a hold (#309):
        // typed as offered, not cased and not rewritten back.
        if (base.startsWith(VERBATIM_DIGITS)) return base.substring(VERBATIM_DIGITS.length)
        // A key off a Keyman shift or caps page is already the shifted key its
        // author drew; casing it again would type a different letter.
        if (key.action is KeyAction.KeymanKey && state.layouts.keymanShift != null) {
            return applyNumerals(base, state)
        }
        val shiftLabel = key.shiftLabel
        val out = when {
            state.shiftState != ShiftState.OFF && shiftLabel != null -> shiftLabel
            else -> shiftCased(base, state.shiftCasesText())
        }
        return applyNumerals(out, state)
    }

    /**
     * Rewrites ASCII digits in a committed key output to the chosen numeral
     * system. Numeric/phone/date/time keypads keep ASCII under the default
     * [NumeralCommitScope.TEXT_ONLY] so those fields stay machine-parseable;
     * [NumeralCommitScope.EVERYWHERE] types native digits there too, and
     * [NumeralCommitScope.DISPLAY_ONLY] never rewrites. A no-op for Latin and
     * for text with no digits.
     */
    private fun applyNumerals(text: String, state: KeyboardUiState): String {
        val apply = when (state.settings.layoutBehavior.numeralCommitScope) {
            NumeralCommitScope.DISPLAY_ONLY -> false
            NumeralCommitScope.EVERYWHERE -> true
            NumeralCommitScope.TEXT_ONLY -> !state.fieldKind.isNumericPad
        }
        if (!apply) return text
        val digits = resolveNumeralDigits(
            state.settings.layoutBehavior.numeralSystemFor(state.language.id),
            state.language,
        )
        return mapDigits(text, digits)
    }

    /**
     * The য়-glide a fixed Bengali vowel key just typed after another vowel:
     * which key ([key], its kar), what it wrote, and when. A second press of
     * the same key soon after turns it into the independent vowel, under
     * [com.wasimaster.wmkeyboard.core.settings.SuggestionStripSettings.bengaliVowelTwice]
     * (#900). Spent by the next key whatever it is.
     */
    private class VowelGlide(val key: String, val text: String, val at: Long)

    private var lastVowelGlide: VowelGlide? = null

    /**
     * Fixed Bengali layouts (Probhat, Jatiya): a vowel-sign key yields the
     * kar form (া, ি, …) after a consonant it can attach to, the য়-glide
     * (য়া, য়ে) after another vowel — so কা + আ gives কায়া, never the
     * invalid কাআ — and the independent vowel (আ, ই, …) at a word start.
     */
    /**
     * Burmese typed in drawn order ([MyanmarVisualOrder]): a consonant after a
     * ေ that is still waiting for one goes in front of it, and a medial after
     * a consonant's ေ goes in front of the ေ. True when the key was typed here.
     *
     * Not on a converted Keyman layout, whose own rules order its output, and
     * not while writing Zawgyi, which stores ေ in front of its consonant on
     * purpose.
     */
    private fun typeMyanmarVisualOrder(ic: InputConnection, text: String): Boolean {
        if (text.length != 1 || !MyanmarVisualOrder.reorders(text[0])) return false
        if (keymanSession != null || outputEncoding == OutputEncoding.ZawgyiOutput || hasSelection(ic)) return false
        // Marks commit the buffer as they land, so the ေ is in the field; a
        // buffer still open here is a resumed word, and the ေ ends it.
        val before = composing.takeIf { it.isNotEmpty() }?.toString()
            ?: ic.getTextBeforeCursor(MYANMAR_ORDER_CONTEXT, 0)?.toString()
            ?: return false
        val edit = MyanmarVisualOrder.reorder(before, text) ?: return false
        if (composing.isNotEmpty()) commitComposing(ic, autocorrect = false)
        ic.beginBatchEdit()
        revision?.expectDelete(edit.delete, 0)
        ic.deleteSurroundingText(edit.delete, 0)
        commitTypedCharacter(ic, edit.text)
        ic.endBatchEdit()
        invalidateExpectedSelection()
        _uiState.update {
            it.copy(composingPreview = "", suggestions = emptyList(), emojiSuggestions = emptyList(), octopus = emptyMap())
        }
        return true
    }

    private fun fixedLayoutContextualVowel(text: String, previous: Char?): String =
        _uiState.value.composer.contextualForm(text, previous)

    /**
     * Recomputes [KeyboardUiState.vowelForm] from the character before the
     * cursor (or the emoji query) so the fixed-layout vowel keys track the
     * word position both in output and on the key labels.
     */
    private fun refreshKarContext() {
        if (!_uiState.value.composer.isClusterShaping) return
        // A keyboard-owned field answers from its own caret, not from the end
        // of its text: with a movable caret (#161) those stopped being the
        // same character.
        val caret = _uiState.value.captureCaretText()
        val previous = if (caret != null) {
            caret.text.getOrNull(caret.at - 1)
        } else {
            currentInputConnection?.getTextBeforeCursor(1, 0)?.lastOrNull()
        }
        val form = BengaliGraphemes.vowelFormAfter(previous)
        _uiState.update { if (it.vowelForm == form) it else it.copy(vowelForm = form) }
    }

    private fun onShift() {
        // With a selection, shift re-cases the selected text (lower → Title →
        // UPPER) rather than arming shift for the next character. Falls through
        // to normal shift when nothing is selected or the feature is off.
        //
        // Not while that same shift is the modifier holding the selection open
        // ([KeyboardUiState.shiftSelectsText]): every selection dragged out with
        // shift+arrow — the toolbar's cursor tools, a layout's arrow keys, the
        // spacebar scrub — ends with a live selection and a shift still up, and
        // re-casing there would leave the user no way to put the shift back
        // down. Press it once to release the modifier; press it again, with the
        // selection still standing and the shift now down, to re-case.
        //
        // A shift the re-case itself put up ([syncShiftToCase]) is not that
        // modifier: it only mirrors the selection's new case, and taking it
        // for one stopped the cycle at Title — the second press armed shift
        // instead of going on to UPPER.
        if (_uiState.value.settings.textEditing.recapitalizeSelectionWithShift &&
            (!_uiState.value.shiftSelectsText || _uiState.value.shiftState == shiftFromRecase)
        ) {
            val target = _uiState.value.captureTarget()
            val caret = _uiState.value.captureCaretText()
            val spell = _uiState.value.wordSpell
            if (target != null && spell == null) {
                // A keyboard-owned box has the keys: its selection or nothing
                // (#612). Falling through to the app's field re-cased the
                // browser bar's word behind the clip editor and swallowed the
                // press, so shift never went up for the letter after it.
                if (caret != null && caret.hasSelection) {
                    caret.recased(::nextCaseForm)?.let { next ->
                        captureWrite(target, caret, next)
                        syncShiftToCase(next.selectedText)
                        return
                    }
                }
            } else if (spell != null) {
                // The spelling bar's own selection, never one standing in the
                // app behind it (#204).
                spell.recased(::nextCaseForm)?.let { next ->
                    _uiState.update { it.copy(wordSpell = next) }
                    syncShiftToCase(next.draft.substring(next.selectionStart, next.selectionEnd))
                    return
                }
            } else {
                val ic = currentInputConnection
                if (ic != null) {
                    if (hasSelection(ic)) {
                        if (recapitalizeSelection(ic)) return
                    } else if (recapitalizeWordAtCaret(ic, _uiState.value.settings.textEditing)) {
                        return
                    }
                }
            }
        }
        // Cancel a just-inserted auto-space after punctuation — the ". " from a
        // double space, or the space the auto-space-after-punctuation rule
        // types. Either leaves a trailing space, and one shift press removes it
        // rather than arming caps, so a sentence can be continued without it.
        //
        // Only while auto-capitalization has shift up for the next sentence,
        // where the press would otherwise just put it back down. With shift
        // down — after a comma, or with auto-capitalization off — the press is
        // the user asking for a capital, and the space stays (issue #542).
        val autoCapped = _uiState.value.let { it.shiftState == ShiftState.ON && !it.shiftPressedByUser }
        if (pendingAutoSpace && autoCapped) {
            pendingAutoSpace = false
            pendingPunctuationSpace = false
            val ic = currentInputConnection
            if (ic != null) {
                val before = ic.getTextBeforeCursor(2, 0)?.toString().orEmpty()
                if (before.length == 2 && before[1] == ' ' && isAutoSpacedMark(before[0])) {
                    ic.deleteSurroundingText(1, 0)
                    // The ". " also armed auto-cap for a new sentence; cancelling
                    // the break cancels that too, so typing continues in case.
                    consumeShift()
                    return
                }
            }
        }
        // A shift pressed here is the user's own, whatever a re-case left up.
        shiftFromRecase = null
        val now = System.currentTimeMillis()
        // The caps-lock double-tap window is user-tunable (A47); Fn and the
        // modifier keys keep the fixed SHIFT_DOUBLE_TAP_MS.
        val capsLockMs = _uiState.value.settings.layoutBehavior.shiftCapsLockMs
        val doubleTap = now - lastShiftTapTime < capsLockMs
        lastShiftTapTime = now
        _uiState.update {
            val next = when {
                doubleTap && it.shiftState != ShiftState.CAPS_LOCK -> ShiftState.CAPS_LOCK
                it.shiftState == ShiftState.OFF -> ShiftState.ON
                else -> ShiftState.OFF
            }
            it.copy(
                shiftState = next,
                // The one place a shift is the user's own doing, which is what
                // Shift+Enter's newline override keys off.
                shiftPressedByUser = next != ShiftState.OFF,
            )
        }
    }

    /**
     * The dedicated ⇪ key: caps lock on or off, nothing in between.
     *
     * Deliberately not [onShift] with the double-tap pre-armed. This key exists
     * only on grids wide enough to also carry a real shift key, so the two split
     * the job — shift arms for one letter, this one sticks — and routing it
     * through the tap-timing path would make a single press mean ON, which is the
     * other key's answer.
     */
    private fun onCapsLock() {
        _uiState.update {
            val next =
                if (it.shiftState == ShiftState.CAPS_LOCK) ShiftState.OFF else ShiftState.CAPS_LOCK
            it.copy(shiftState = next, shiftPressedByUser = next != ShiftState.OFF)
        }
    }

    private fun consumeShift() {
        _uiState.update {
            if (it.shiftState == ShiftState.ON) {
                it.copy(shiftState = ShiftState.OFF, shiftPressedByUser = false)
            } else {
                it
            }
        }
    }

    /**
     * Puts down a shift the user put up, the lock included (#613): after a cut
     * or a paste, and on the way from the letters to the symbols or the number
     * pad, the way a physical keyboard's shift is let go of once the shortcut
     * is done. Left up, it kept every caret move after it a selection.
     * A shift the field armed by itself is not the user's, and stays; the
     * caret update after a paste re-arms auto-capitalize where it belongs.
     */
    private fun releaseUserShift() {
        _uiState.update {
            if (it.shiftPressedByUser && it.shiftState != ShiftState.OFF) {
                it.copy(shiftState = ShiftState.OFF, shiftPressedByUser = false)
            } else {
                it
            }
        }
    }

    /**
     * Re-cases the current selection to the next form in the cycle
     * lower → Title → UPPER → lower and keeps it selected, so repeated shift
     * presses walk the cycle. Returns false (leaving the selection alone) when
     * there is nothing to change — e.g. a caseless script like Bengali.
     */
    private fun recapitalizeSelection(ic: InputConnection): Boolean {
        val selected = ic.getSelectedText(0)?.toString().orEmpty()
        if (selected.isEmpty()) return false
        val next = nextCaseForm(selected)
        if (next == selected) return false
        dropComposingForSelectionEdit(ic)
        ic.beginBatchEdit()
        ic.commitText(next, 1)
        val end = ic.getExtractedText(ExtractedTextRequest(), 0)?.selectionEnd
        if (end != null) ic.setSelection((end - next.length).coerceAtLeast(0), end)
        ic.endBatchEdit()
        syncShiftToCase(next)
        return true
    }

    /**
     * Re-cases the word the collapsed caret is touching, the way SwiftKey's
     * shift does (#662): `cursor⌶ touching` with
     * [TextEditingSettings.shiftRecasesWordAtCaret], `cur⌶sor touching` with
     * [TextEditingSettings.shiftRecasesWordAroundCaret]. One step of
     * lower → Title → UPPER, with the caret left where it was so the next press
     * takes the next step, and the keyboard's shift moved to the same case
     * ([syncShiftToCase]), so UPPER is caps lock and typing goes on in it.
     *
     * False, and the shift arms as usual, when the caret touches no word or
     * only stands in front of one, the word has no case to change, or a word
     * is being typed: the shift pressed in the middle of typing one is for the
     * next letter, which is the whole of what a shift has always meant. That
     * holds with no composing word too (a field that takes no suggestions, an
     * address bar) and for a word backspace has just resumed, where
     * [typedCaretAt] is what knows the caret got there by typing. A word the
     * caret was only put back next to is not being typed.
     *
     * The case forms must keep the word's length, because the caret goes back
     * to the same offset; [nextCaseForm] promises it, and the guard below stays
     * as the backstop.
     */
    private fun recapitalizeWordAtCaret(ic: InputConnection, editing: TextEditingSettings): Boolean {
        if (!editing.shiftRecasesWordAtCaret && !editing.shiftRecasesWordAroundCaret) return false
        if (composing.isNotEmpty() && composing.toString() != resumedWord) return false
        if (typedCaretAt >= 0 && typedCaretAt == expectedSelEnd && expectedSelStart == expectedSelEnd) {
            return false
        }
        val before = ic.getTextBeforeCursor(CARET_WORD_AHEAD, 0)?.toString() ?: return false
        val after = ic.getTextAfterCursor(CARET_WORD_AHEAD, 0)?.toString() ?: return false
        val head = before.takeLastWhile { isComposingWordChar(it) }
        val tail = after.takeWhile { isComposingWordChar(it) }
        if (head.isEmpty()) return false
        if (if (tail.isEmpty()) !editing.shiftRecasesWordAtCaret else !editing.shiftRecasesWordAroundCaret) return false
        val word = head + tail
        val next = nextCaseForm(word)
        if (next == word || next.length != word.length) return false
        val caret = caretOffset(ic)
        // The re-case's own echoes move the caret too, and are not typing.
        typedCaretAt = -1
        typedCaretResetAt = SystemClock.uptimeMillis()
        dropComposingForSelectionEdit(ic)
        ic.beginBatchEdit()
        ic.deleteSurroundingText(head.length, tail.length)
        if (caret != null) {
            ic.commitText(next, 1)
            ic.setSelection(caret, caret)
        } else {
            // No offset to put the caret back at: the two halves go in either
            // side of it instead, which a plain editor honours.
            ic.commitText(next.substring(0, head.length), 1)
            ic.commitText(next.substring(head.length), 0)
        }
        ic.endBatchEdit()
        invalidateExpectedSelection()
        syncShiftToCase(next)
        return true
    }

    /**
     * The collapsed caret a run of typing has left, or -1: set on the echo of
     * a keystroke that moved the caret a few characters on or back, kept while the
     * caret stays there, and dropped by any other move. Only
     * [recapitalizeWordAtCaret] reads it, to tell a word just typed with no
     * composing region from one the caret was put next to.
     */
    private var typedCaretAt = -1

    /** When [recapitalizeWordAtCaret] last edited; a keystroke before it no longer counts. */
    private var typedCaretResetAt = 0L

    private fun noteTypedCaret(oldSelEnd: Int, newSelStart: Int, newSelEnd: Int) {
        typedCaretAt = when {
            newSelStart != newSelEnd -> -1
            newSelEnd != oldSelEnd && abs(newSelEnd - oldSelEnd) <= TYPED_CARET_STEP_MAX &&
                lastTypedKeyAt > typedCaretResetAt &&
                SystemClock.uptimeMillis() - lastTypedKeyAt < TYPED_CARET_ECHO_MS -> newSelEnd
            newSelEnd == typedCaretAt -> typedCaretAt
            else -> -1
        }
    }

    /**
     * Moves the keyboard's own case to match [text]'s, which is where the
     * selection's case has just been put (#525).
     *
     * Without this the shift key re-cased the selection and left the keys
     * where they were, so taking a word to UPPER and carrying on typing in
     * upper case meant un-selecting the word, pressing shift again, and
     * re-selecting — every other keyboard with this feature moves both with
     * the one press. Title case maps to the one-shot shift and UPPER to caps
     * lock, which is what each would have typed. A caseless script (Bengali,
     * and the mixed forms the cycle normalizes rather than steps) has no case
     * for the keys to show, so the state is left alone.
     */
    private fun syncShiftToCase(text: String) {
        val next = shiftStateForCase(text) ?: return
        shiftFromRecase = next
        _uiState.update {
            if (it.shiftState == next) {
                it
            } else {
                // Same pairing as [onShift]: a shift that is up is one the user
                // put up, which is what Shift+Enter's newline override reads.
                it.copy(shiftState = next, shiftPressedByUser = next != ShiftState.OFF)
            }
        }
    }

    /**
     * The shift state [syncShiftToCase] last put up, so [onShift] can tell it
     * from a shift the user pressed to hold a selection open; null once the
     * user has pressed shift themselves.
     */
    private var shiftFromRecase: ShiftState? = null

    /**
     * Advances [s] one step through lower → Title → UPPER → lower. Every form
     * keeps the spelling, so `ß` steps to `ẞ` and back rather than to `SS` (#715).
     */
    private fun nextCaseForm(s: String): String {
        val lower = s.lowercaseKeepingLength()
        val upper = s.uppercaseKeepingLength()
        val title = toTitleCase(s)
        return when {
            s == lower -> title
            s == title && title != upper -> upper
            s == upper -> lower
            else -> lower // mixed case → normalize to lower to restart the cycle
        }
    }

    private fun onDelete() {
        glueNextWord = false
        // A word being corrected is not finished: the all-thumbs-up pause
        // waits for the next letter before it types anything (#676).
        allUpArmed = false
        // Backspace is the answer "no" to an add-word chip: the user is taking
        // the word back rather than keeping it, so the offer goes with it. The
        // near-miss chip goes for the plainer reason that the word it is about
        // is being deleted.
        if (learnOfferWord != null) clearLearnOffer()
        if (correctionOfferFor != null) clearCorrectionOffer()
        closeRecentClips()
        // Backspace with a morse sequence pending edits the sequence, not the
        // field — Gboard's contract. It only falls through to a real delete
        // once the sequence is empty.
        if (morse.isPending) {
            morse.backspace()
            _uiState.update { it.copy(morsePending = morse.display) }
            morseJob?.cancel()
            morseJob = if (morse.isPending) {
                serviceScope.launch {
                    delay(_uiState.value.settings.morseCommitMs.toLong())
                    commitMorse()
                }
            } else {
                null
            }
            return
        }
        val state = _uiState.value
        // A stepping space bar's highlight is a conversion in progress, and
        // backspace backs out of it to the reading, as in Mozc (#419).
        if (state.candidateCursor >= 0 && composing.isNotEmpty() && state.composer.isConversion &&
            spaceStepsCandidates(state)
        ) {
            _uiState.update { it.copy(candidateCursor = -1) }
            return
        }
        // Backspace while handwritten ink is waiting for recognition throws
        // the ink away instead of deleting committed text — the natural
        // "no, not that" while writing. Applies to the panel and to
        // handwriting drawn straight on the keys.
        if ((state.panel == PanelMode.HANDWRITING || keyboardHandwriteActive(state)) &&
            state.handwriting.strokes.isNotEmpty()
        ) {
            hwJob?.cancel()
            hwGeneration++
            _uiState.update {
                it.copy(handwriting = it.handwriting.copy(strokes = emptyList(), recognizing = false))
            }
            return
        }
        // A keyboard-owned field deletes from its own caret, never from the app
        // behind the keyboard — including when the caret is already at the
        // start and there is nothing to take.
        if (captureBackspace()) return
        deleteFromField()
    }

    /**
     * How much of [before] one character-sized delete takes: a whole
     * multi-code-point emoji (☠️, 👍🏽, 👨‍👩‍👧) rather than a piece of one, a
     * whole Bengali-style conjunct where the language asks for it, and
     * otherwise [Graphemes.backspaceLength] — one code point, so a surrogate
     * pair is never halved and a typed accent or harakah comes off on its own,
     * but an invisible part (a variation selector, the LF of CR LF, a Hangul
     * jamo) together with what it belongs to. 0 for empty text.
     *
     * Shared by the backspace key and the character-mode backspace swipe, so
     * the two cannot disagree about what one character is.
     */
    private fun charDeleteLength(before: CharSequence): Int {
        if (before.isEmpty()) return 0
        val state = _uiState.value
        val emojiLength = EmojiGraphemes.deleteLength(before)
        return when {
            emojiLength > 0 -> emojiLength
            state.language.id in state.settings.conjunctBackspaceLanguages ->
                state.composer.deleteLength(before).coerceAtLeast(1)
            else -> Graphemes.backspaceLength(before)
        }
    }

    /**
     * One backspace against the real text field, regardless of any active
     * panel search: selection first, then gesture-word / autocorrect undo,
     * then composing, then a full grapheme cluster. Split from [onDelete]
     * so the emoji search bar's field-backspace can reach it while the
     * backspace key is busy editing the query.
     */
    private fun deleteFromField() {
        // Inside rather than in onDelete, so the emoji bar's field-backspace
        // gets the same offer.
        if (runKeymanFrameKey(VK_BACKSPACE)) return
        val state = _uiState.value
        val ic = currentInputConnection ?: return
        settlePendingUndoOnDelete()
        recordStat { onBackspace(System.currentTimeMillis(), SystemClock.uptimeMillis()) }
        // The mid-word strip describes the field as it was before this delete.
        clearCaretWord()
        // Deleting with an active selection removes the selected text only.
        if (hasSelection(ic)) {
            dropComposingForSelectionEdit(ic)
            noteDeletedForLearning(expectedSelStart, expectedSelEnd)
            invalidateExpectedSelection()
            ic.commitText("", 1)
            return
        }
        // The text a chip's gear took out comes back on the first backspace
        // after its tool, while nothing has been typed since (#665).
        chipOpenRestore?.let { restore ->
            chipOpenRestore = null
            if (composing.isEmpty() && (restore.caret < 0 || restore.caret == expectedSelStart)) {
                ic.commitText(restore.text, 1)
                syncPreviousWordFromField(ic)
                refreshSuggestions()
                return
            }
        }
        // Backspace straight after a glide removes the whole swiped word —
        // a wrong swipe shouldn't cost a letter-by-letter cleanup. Unless the
        // user turned that off (#455): a swipe that got a letter or two wrong
        // is fixed faster by deleting those letters than by redrawing it, so
        // the word stops being one unit and this press deletes like any other.
        if (lastGestureWord != null && !state.settings.gesture.backspaceUndoesGlide) {
            lastGestureWord = null
            lastGestureStroke = null
            pendingWordSpace = false
        }
        lastGestureWord?.let { word ->
            lastGestureWord = null
            val stroke = lastGestureStroke
            lastGestureStroke = null
            pendingWordSpace = false
            // A two-thumb word of several gestures loses only its latest one,
            // as it would have before it was typed (#858).
            val duet = committedDuet?.takeIf { it.word == word && stroke == null }
            committedDuet = null
            if (composing.isEmpty()) {
                // The space the glide typed goes with the word: undoing the
                // swipe must leave the caret where the swipe found it.
                val len = glideCommitLength(ic, word)
                if (len > 0 && duet != null) {
                    unlearnHand()
                    reopenCommittedDuet(ic, duet, len, dropLast = true)
                    return
                }
                if (len > 0) {
                    ic.deleteSurroundingText(len, 0)
                    // A word the user took back was a wrong reading of the
                    // stroke, and a wrong word laid over a stroke taught the
                    // hand model wrong offsets. The shape that read it that
                    // way, if one of the user's own did, is marked against.
                    unlearnHand()
                    stroke?.shape?.let { glideShapes.reject(it.layoutKey, word, it.shape) }
                    // The stroke waits for the word the user meant instead of
                    // being thrown away here (issue #213): whatever they commit
                    // in its place claims it, and teaches the hand model and the
                    // shape store the way a strip pick over an un-backspaced
                    // glide already does.
                    undoneGlide = stroke?.let {
                        UndoneGlide(it, word, SystemClock.uptimeMillis())
                    }
                    // The undone word is gone as bigram context; whatever now
                    // precedes the caret is the real one.
                    syncPreviousWordFromField(ic)
                    // The decode the user just took back is not evidence of
                    // anything, the same as when the strip replaces it.
                    learningBuffer.drop(word)
                    // Both lists: the bar is up while either has content, so
                    // clearing only the words left a stale emoji row holding
                    // it open.
                    _uiState.update {
                        it.copy(suggestions = emptyList(), emojiSuggestions = emptyList(), octopus = emptyMap())
                    }
                    // Undoing a swipe is the clearest "not that one" there is,
                    // so the stroke goes back through the decoder with the
                    // vocabulary cap off and the word it already gave ruled
                    // out, and whatever it finds waits on the strip.
                    if (stroke != null) {
                        noteGlideUndone(word)
                        glideDeepRetry(stroke, rejected = word)
                    }
                    return
                }
            }
        }
        // Backspace straight after an autocorrect or a snippet expansion takes
        // it back: what the keyboard put in the field becomes what the user
        // typed again. An undone autocorrect also joins the personal dictionary
        // so it is never auto-"fixed" again — deleting the fix is the strongest
        // "I meant what I typed".
        lastRevertible?.let { revert ->
            lastRevertible = null
            clearSwapOffer()
            val allowed = when (revert.kind) {
                RevertibleCommit.Kind.AUTOCORRECT -> state.settings.correction.revertOnBackspace
                // A pattern snippet eats several typed words at once, so being
                // able to take it back is not a preference. There is also no
                // settings field left to hang one on.
                RevertibleCommit.Kind.SNIPPET -> true
                // Undoing a tapped join is not a preference either.
                RevertibleCommit.Kind.JOIN -> true
                // Nor is undoing a tapped revision chip.
                RevertibleCommit.Kind.REVISION -> true
                // The keyboard chose the script, the way it chooses a
                // correction, so the same switch says whether backspace argues.
                RevertibleCommit.Kind.SCRIPT -> state.settings.correction.revertOnBackspace
            }
            if (composing.isEmpty() && allowed) {
                // A correction is always followed by the space that triggered
                // it, but an expansion can be followed by a newline, a full
                // stop, or nothing at all when a {cursor} marker swallowed the
                // key. Reading one character past the commit and putting
                // whatever it is back verbatim beats guessing which it was.
                //
                // A word corrected by a mark (#562) under the auto-space rule
                // has two characters behind it, the mark and its space. Those
                // two exactly, and nothing else, count as a two-character tail.
                //
                // Probed as the field holds it: styled, under Fancy Text, and
                // the original goes back through the same styling (#950).
                val committed = fieldForm(revert.committed, state)
                val wide = ic.getTextBeforeCursor(committed.length + 2, 0)?.toString()
                val markAndSpace = wide != null && wide.length == committed.length + 2 &&
                    wide.endsWith(' ') && wide[wide.length - 2] in AUTO_SPACE_PUNCTUATION &&
                    wide.dropLast(2) == committed
                val probe = if (markAndSpace) wide else wide?.takeLast(committed.length + 1)
                val tail = when {
                    markAndSpace -> probe.orEmpty().takeLast(2)
                    probe != null && probe.length > committed.length -> probe.takeLast(1)
                    else -> ""
                }
                if (probe != null && probe.dropLast(tail.length) == committed) {
                    ic.beginBatchEdit()
                    ic.deleteSurroundingText(probe.length, 0)
                    ic.commitText(revert.original + tail, 1)
                    ic.endBatchEdit()
                    revertCommitted(ic, revert, state, tail)
                    return
                }
                // Nothing followed the commit after all — a mark that hugged
                // the word in front of it with no auto-space behind — so the
                // extra character read is the one *before* it. Tried second,
                // because when something does follow and happens to spell the
                // commit's own tail ("hi.." after "hi ."), the read above is
                // the right one.
                if (probe != null && probe.endsWith(committed)) {
                    ic.beginBatchEdit()
                    ic.deleteSurroundingText(committed.length, 0)
                    ic.commitText(revert.original, 1)
                    ic.endBatchEdit()
                    revertCommitted(ic, revert, state, tail = "")
                    return
                }
            }
        }
        // A two-thumb word takes back its latest tap or swipe (#638) — even
        // before its first reading lands, while the buffer is still empty and
        // this press would otherwise delete the text in front of it (#732).
        if (duetWord.active && duetBackspace(ic)) return
        if (composing.isNotEmpty()) {
            // A correction re-armed as the composing word and backspaced is
            // being deleted all the same; the buffer path just never reaches
            // [noteDeletedForLearning].
            if (expectedSelStart > 0) declinedSpots.onDeleted(expectedSelStart - 1, expectedSelStart)
            // Mid-reading (#960): the key in front of the caret goes, the rest
            // of the reading stays, and at its start there is nothing to take.
            val readingAt = readingCaret
            if (readingAt in 0 until composing.length && editsInsideReading(state)) {
                if (readingAt == 0) return
                val whole = composing.toString()
                val head = state.composer.backspaceBuffer(whole.substring(0, readingAt))
                composing.setLength(0)
                composing.append(head).append(whole, readingAt, whole.length)
                composingTouch.clear()
                composingKeys.clear()
                composingHints.clear()
                ambiguousReading = null
                readingCaret = head.length
                updateComposingText(ic)
                refreshSuggestions()
                return
            }
            // The buffer is the field's own text, so a backspace has to take the
            // same thing off it that the branch below would take off the field —
            // for a cluster-shaping layout, a whole conjunct rather than one code
            // unit, which would shed a base and leave its hasant dangling. Gated
            // on the same per-language setting for the same reason: whichever way
            // the user set backspace, it must not change under a resumed word.
            //
            // Never on a keypad (#332). There the buffer holds each key's anchor,
            // not the word the field shows, so a "cluster" read off it is a run
            // of unrelated keypresses; one backspace takes back one press, and
            // the reading is decoded afresh from the presses that are left.
            //
            // Vietnamese is the exception, and for the same reason its buffer is
            // not the field's text at all: it holds keys (`huowngs`) where the
            // field holds a word (`hướng`), so a press has to take off a *letter*
            // — one press for `hướng` where the keys would cost two. Which keys
            // that is the composer works out ([Composer.backspaceBuffer]); a
            // tone key goes only when the letter it marks is the one going.
            // A conversion composer decides too: a syllable picked on a 九宫格
            // pad goes back to its digits whole rather than losing a letter
            // and reading as another syllable (#635).
            val before = composing.toString()
            val after = if (isVietnameseTransliterator(state) || state.composer.isConversion) {
                state.composer.backspaceBuffer(before)
            } else {
                val length = if (
                    !state.layouts.ambiguousKeys &&
                    state.language.id in state.settings.conjunctBackspaceLanguages
                ) {
                    state.composer.deleteLength(composing).coerceIn(1, composing.length)
                } else {
                    1
                }
                before.dropLast(length)
            }
            composing.setLength(0)
            composing.append(after)
            if (before.startsWith(after)) {
                repeat(before.length - after.length) {
                    composingTouch.removeLastOrNull()
                    composingKeys.removeLastOrNull()
                    composingHints.removeLastOrNull()
                }
            } else {
                // The keys were re-spelled rather than cut, so nothing is known
                // about the new ones — the same boundary a re-armed word is, and
                // the frames go the same way (see the `composing` setter).
                composingTouch.clear()
                composingKeys.clear()
                composingHints.clear()
            }
            ambiguousReading = null
            updateComposingText(ic)
            refreshSuggestions()
        } else if (isNullField()) {
            // A window with no editor — what a pinned keyboard (issue #58) is
            // kept up over — is served by the framework's fallback connection,
            // whose deleteSurroundingText edits a buffer no app ever reads.
            // The key event is the only backspace that arrives, which is the
            // rule the platform keyboard applies to TYPE_NULL too.
            sendDownUpKeyEvents(KeyEvent.KEYCODE_DEL)
        } else {
            // Delete a full surrogate pair / grapheme; optionally a whole
            // Bengali conjunct cluster as one unit. The lookback has to
            // outrun the longest emoji ZWJ/tag sequence, not just a pair.
            val before = ic.getTextBeforeCursor(64, 0)
            // An empty pair goes out whole (issue #319): the caret between an
            // opening bracket and its own closer is the state auto-close left
            // behind, so the backspace that undoes that press has to undo all
            // of it rather than strand the closer.
            if (before != null && deletesAutoClosedPair(ic, before, state)) {
                revision?.expectDelete(1, 1)
                if (expectedSelStart >= 0) {
                    noteDeletedForLearning(expectedSelStart - 1, expectedSelStart + 1)
                }
                ic.deleteSurroundingText(1, 1)
                val left = before.subSequence(0, before.length - 1)
                setContextFrom(left)
                rebuildRecentWords(left)
                refreshSuggestions()
                return
            }
            // Nothing behind the caret: the app is the one that knows what a
            // backspace at the start of its field means. A block editor (Notion,
            // issue #494) joins the line to the block above, which it does for
            // a key event and never for deleteSurroundingText, a no-op here.
            if (before != null && before.isEmpty()) {
                sendDownUpKeyEvents(KeyEvent.KEYCODE_DEL)
                return
            }
            // An editor that will not say what is behind the cursor still owes
            // the press a delete, so an unknown answer is one code unit.
            val deleteLength = charDeleteLength(before ?: "").coerceAtLeast(1)
            revision?.expectDelete(deleteLength, 0)
            if (expectedSelStart >= 0) {
                noteDeletedForLearning(expectedSelStart - deleteLength, expectedSelStart)
            }
            // A code editor in a page (CodeMirror, issue #494) acts on the key
            // and puts back a delete made straight on its text. The browser
            // then picks how much goes, which is one grapheme, the same as
            // deleteLength unless this language deletes whole conjuncts; those
            // keep the direct delete so the setting still means what it says.
            if (state.settings.textEditing.webBackspaceKeyEvents && isWebEditField() &&
                state.language.id !in state.settings.conjunctBackspaceLanguages
            ) {
                sendDownUpKeyEvents(KeyEvent.KEYCODE_DEL)
            } else {
                ic.deleteSurroundingText(deleteLength, 0)
            }
            // Backspacing through committed text is the one way the word
            // behind the cursor changes without passing through learn(), so
            // the strip used to keep predicting from a word the user had
            // already erased. In an empty field that left it offering bigrams
            // for text that was no longer there — and since the bar and its
            // chevron are shown exactly while the strip has content, neither
            // would go away. Re-derive the context, then refresh: with no word
            // behind the cursor the engine returns nothing and the bar folds.
            //
            // Derived from the text already in hand rather than asking the
            // editor for the same 64 characters a second time: that read is a
            // blocking round-trip into the focused app, and holding backspace
            // repeats this whole path many times a second, which is exactly
            // when the app on the other side is least able to answer promptly.
            // Every branch of the `when` above bounds deleteLength by what
            // `before` holds, so the guard only falls through if that ever
            // stops being true.
            if (before != null && deleteLength <= before.length) {
                val left = before.subSequence(0, before.length - deleteLength)
                setContextFrom(left)
                rebuildRecentWords(left)
                if (state.composer.isConversion) noteConversionDeleted(before, left)
            } else {
                conversionDeleted = ""
                syncPreviousWordFromField(ic)
            }
            refreshSuggestions()
        }
    }

    /**
     * Cleans up after one backspace took a commit back.
     *
     * This is where the two kinds part company. Rejecting an autocorrect is a
     * statement about a word, so the correction is retired and the word taught;
     * taking back a snippet expansion says nothing about anybody's vocabulary,
     * so it teaches nothing and only puts the context back where it was.
     */
    private fun revertCommitted(
        ic: InputConnection,
        revert: RevertibleCommit,
        state: KeyboardUiState,
        tail: String,
    ) {
        // A stale precompute for this word would hand the old answer to the
        // next commit before the strip catches up.
        commitResolution = null
        when (revert.kind) {
            RevertibleCommit.Kind.AUTOCORRECT -> {
                // The rejection itself waits for the next key: see
                // [PendingUndo]. An older one still waiting was kept.
                settlePendingUndo(kept = true)
                pendingUndo = PendingUndo(revert, tail)
                declinedSpots.undone(revert.original)
                // Judged here and now, so the settle pass must not judge it
                // again on the way out and count the rejection twice.
                correctionWatch.drop(revert.original, revert.committed)
                // The chip's newest entry may be this correction, and this
                // correction is no longer in the field. Older entries stand
                // in front of it and are untouched.
                dropUndoFor(revert.original, revert.committed)
                previousWord = revert.original.trim { !WordContext.isWordChar(it) }
                    .lowercase().ifEmpty { null }
                invalidateRecentWords()
            }
            RevertibleCommit.Kind.SNIPPET -> {
                // The restored words are back to being exactly what the user
                // typed, and the caret may be sitting at the end of the last
                // one — where the keyboard re-arms it as a composing word. The
                // next space would then expand it straight back, so that one
                // span is muted until something else is typed.
                patternMutedAfter = revert.original
                syncPreviousWordFromField(ic)
            }
            RevertibleCommit.Kind.JOIN -> {
                // The two original words are back; re-derive context from the
                // field. No rejectCorrection (the user asked for the join by
                // tapping) and no unlearning of a real dictionary word.
                syncPreviousWordFromField(ic)
                invalidateRecentWords()
            }
            RevertibleCommit.Kind.REVISION -> {
                // Same shape as a join: the original words are back, context
                // re-derives from the field, and nothing needs unlearning.
                syncPreviousWordFromField(ic)
                invalidateRecentWords()
            }
            RevertibleCommit.Kind.SCRIPT -> {
                // The word stands in the other script now. The one the keyboard
                // chose was never the user's, so it is not counted; the flip is
                // remembered against the spelling; and the field's language is
                // read again, since the word that tipped it has changed sides.
                learningBuffer.drop(revert.committed)
                revert.script?.let(::noteScriptFlip)
                dropUndoFor(revert.original, revert.committed)
                invalidateRecentWords()
                syncPreviousWordFromField(ic)
            }
        }
    }

    /**
     * Records the rejection [pendingUndo] holds when [kept], drops it otherwise.
     */
    private fun settlePendingUndo(kept: Boolean) {
        val revert = pendingUndo?.revert ?: return
        pendingUndo = null
        if (!kept) return
        // Undoing the correction retires that exact pair: without this the
        // next space corrected the word straight back. Unconditional, unlike
        // the personal dictionary entry below — a rejection has to hold in
        // incognito and with learning off too. Other corrections of the same
        // typed word stay live.
        suggestionEngine?.rejectCorrection(revert.original, revert.committed)
        recordStat { onAutocorrectUndone() }
        // The restored word's commit was worked out while the rejection still
        // waited, so it holds the very correction just turned down: Enter,
        // or Space, would apply it straight back from there (#866).
        commitResolution = null
        val state = _uiState.value
        if (state.settings.learnFromTyping &&
            !(state.incognitoOn && state.settings.incognitoPausesLearning) &&
            !state.secureField
        ) {
            // Counted, not learned outright. Reaching for backspace is strong
            // evidence — worth several ordinary sightings — but it is not
            // proof: undoing a correction is also what you do when the
            // correction was simply not the word you wanted, and this used to
            // be the shortest path from one stray swipe to a misspelling nailed
            // into the dictionary forever. Nothing is lost by waiting either,
            // because [rejectCorrection] above has already stopped this exact
            // correction from firing again.
            noteRevertedWord(revert.original, state)
        }
    }

    /**
     * How much of [PendingUndo.tail] still follows the restored word right
     * behind the caret, or -1 when the word itself is no longer there whole.
     */
    private fun pendingUndoTailLeft(pending: PendingUndo): Int {
        val word = pending.revert.original
        val before = currentInputConnection
            ?.getTextBeforeCursor(word.length + pending.tail.length, 0)
            ?.toString() ?: return -1
        for (left in pending.tail.length downTo 0) {
            if (before.endsWith(word + pending.tail.take(left))) return left
        }
        return -1
    }

    /**
     * A key other than backspace after an undo. The word is kept when the user
     * moves on from it; a letter typed straight onto its end is editing it into
     * another word, which says nothing about the correction.
     */
    private fun settlePendingUndoOnKey(action: KeyAction) {
        val pending = pendingUndo ?: return
        val left = pendingUndoTailLeft(pending)
        val endsWord = action == KeyAction.Space || action == KeyAction.Enter ||
            action == KeyAction.Newline || action == KeyAction.EditorAction
        settlePendingUndo(kept = left > 0 || (left == 0 && endsWord))
    }

    /**
     * A backspace after an undo. Taking off the space behind the word leaves
     * it standing; reaching the word means it is being deleted, not kept.
     */
    private fun settlePendingUndoOnDelete() {
        val pending = pendingUndo ?: return
        if (pendingUndoTailLeft(pending) <= 0) settlePendingUndo(kept = false)
    }

    /**
     * A pick off the strip of a phonetic layout that writes two scripts. Only
     * the word the keyboard had weighed against its own choice says anything
     * about script: a sibling or a completion is a different word, not the same
     * one written differently.
     */
    private fun noteScriptPick(suggestion: String) {
        val language = _uiState.value.composer.phoneticLanguage ?: return
        val engine = suggestionEngine ?: return
        val typed = composing.toString()
        if (typed.isEmpty() || !engine.phoneticAutoEnglish) return
        val commit = engine.phoneticCommit(language, typed, previousWord, previousWord2) ?: return
        if (suggestion != commit.alternate) return
        val to = if (commit.script == PhoneticScript.LATIN) PhoneticScript.NATIVE else PhoneticScript.LATIN
        noteScriptFlip(ScriptFlip(language, typed, to))
    }

    /** The user took the other script for a spelling; see [PhoneticScriptChoices]. */
    private fun noteScriptFlip(flip: ScriptFlip) {
        if (!learningAllowed) return
        suggestionEngine?.recordScriptChoice(flip.languageId, flip.spelling, flip.to)
    }

    /**
     * Pushes the English-words switch to the engine, and redraws the word
     * being typed when it has just changed: the strip's toggle is reached for
     * exactly when the preview has gone Latin under a word that was not
     * English, and it has to come back before the space bar is pressed.
     *
     * The switch is per language, so it is read for the layout now on screen
     * ([spec]) — here rather than in [bindEngineToLayout], which would set the
     * flag quietly and leave this nothing to notice. The sound-alike switch
     * rides along for the same reason: it changes what a space commits.
     */
    private fun syncPhoneticAutoEnglish(settings: KeyboardSettings, spec: LayoutSpec) {
        val engine = suggestionEngine ?: return
        val next = typesEnglishAsEnglish(settings, spec.resolvedComposer())
        val siblingsOff = settings.suggestionStrip.phoneticSiblingsOffLangs
        val contextOff = settings.suggestionStrip.phoneticContextOffLangs
        if (engine.phoneticAutoEnglish == next && engine.phoneticSiblingsOff == siblingsOff &&
            engine.phoneticContextOff == contextOff
        ) {
            return
        }
        engine.phoneticAutoEnglish = next
        engine.phoneticSiblingsOff = siblingsOff
        engine.phoneticContextOff = contextOff
        commitResolution = null
        if (composing.isEmpty() || _uiState.value.composer.let {
                it.phoneticLanguage == null && it.completionLanguage == null
            }
        ) {
            return
        }
        currentInputConnection?.let { updateComposingText(it) }
        refreshSuggestions()
    }

    /**
     * Whether [composer]'s layout commits English words as English. A layout
     * that spells its words outright (Khipro, #487) has a switch of its own,
     * apart from its language's phonetic layout, and off by default (#986).
     */
    private fun typesEnglishAsEnglish(settings: KeyboardSettings, composer: Composer): Boolean =
        composer.completionLanguage?.let { settings.suggestionStrip.khiproEnglishFor(it) }
            ?: settings.suggestionStrip.phoneticEnglishFor(composer.phoneticLanguage)

    /**
     * Picks the legacy encoding for the layout now on screen ([spec]): ANSI
     * for a Bengali layout while Bengali's ANSI button is lit, Zawgyi for a
     * Burmese one while its Zawgyi button is lit or the field was found to be
     * Zawgyi and the user said to write it ([zawgyiField]), Unicode otherwise.
     * A word still being typed commits in whatever the output was when it
     * started, because the layout switch commits it before calling here.
     */
    private fun syncLegacyOutput(settings: KeyboardSettings, spec: LayoutSpec) {
        val strip = settings.suggestionStrip
        val langId = spec.language().id
        setOutputEncoding(
            when {
                strip.bengaliAnsiFor(langId) -> OutputEncoding.Ansi(BijoyAnsi.Version.of(strip.bengaliAnsiVersion))
                langId == "my" && (strip.burmeseZawgyiFor(langId) || zawgyiField) -> OutputEncoding.ZawgyiOutput
                else -> null
            },
        )
    }

    /** [outputEncoding] set, with the strip's Zawgyi button lit to match. */
    private fun setOutputEncoding(encoding: OutputEncoding?) {
        outputEncoding = encoding
        if (encoding == null) legacyConnection = null
        val zawgyi = encoding == OutputEncoding.ZawgyiOutput
        if (_uiState.value.zawgyiOutput != zawgyi) _uiState.update { it.copy(zawgyiOutput = zawgyi) }
    }

    /**
     * Pushes where each phonetic language shows Avro's candidate list to the
     * engine, and rebuilds the strip of a word being typed when it changed.
     */
    private fun syncPhoneticCandidateLists(settings: KeyboardSettings) {
        val engine = suggestionEngine ?: return
        val next = settings.suggestionStrip.phoneticCandidateLists
        if (engine.phoneticCandidateLists == next) return
        engine.phoneticCandidateLists = next
        loadAvroDesktop(engine, next)
        if (composing.isEmpty() || _uiState.value.composer.phoneticLanguage == null) return
        refreshSuggestions()
    }

    /**
     * Loads desktop Avro's data (`assets/avro/`) into [engine] while Bangla
     * shows a candidate list, and lets it go when none does: its dictionary is
     * a few megabytes the keyboard has no other use for.
     */
    private fun loadAvroDesktop(engine: SuggestionEngine, lists: Map<String, PhoneticCandidateList>) {
        val wanted = (lists["bn"] ?: PhoneticCandidateList.OFF) != PhoneticCandidateList.OFF
        if (!wanted) {
            engine.avroDesktop = null
            avroDesktop = null
            return
        }
        // Kept across engines: a dictionary reload builds a new engine, and
        // the data it would read again has not changed.
        avroDesktop?.let {
            engine.avroDesktop = it
            return
        }
        if (avroDesktopLoading) return
        avroDesktopLoading = true
        // Avro's dictionary is a download: asked for the moment the list is
        // turned on, and read in when it lands (see the completions above).
        // Until then the list searches the keyboard's own words.
        if (userUnlocked && !AvroDictionaryDownloads.isDownloaded(filesDir)) AvroDictionaryDownloads.start(filesDir)
        serviceScope.launch {
            val loaded = withContext(Dispatchers.IO) {
                val dictionary = AvroDictionaryDownloads.file(filesDir).takeIf { userUnlocked && it.isFile }
                runCatching {
                    AvroDesktop.load(
                        open = { name -> assets.open("avro/$name") },
                        dictionary = dictionary?.let { file -> { file.inputStream() } },
                    )
                }.getOrNull()
            }
            avroDesktopLoading = false
            val current = suggestionEngine ?: return@launch
            if (loaded == null || current.phoneticCandidateLists["bn"].let { it == null || it == PhoneticCandidateList.OFF }) {
                return@launch
            }
            avroDesktop = loaded
            current.avroDesktop = loaded
            if (composing.isNotEmpty() && _uiState.value.composer.phoneticLanguage != null) refreshSuggestions()
        }
    }

    /**
     * Makes the Khipro grid glidable (#541): the Khipro spellings of every word
     * of the Bangla list the engine holds (bundled, downloaded and imported),
     * cached under `dict/bn` (see [KhiproGlideSpellings]), with the user's own
     * Bangla words walked first. Rebuilt when the list or the learned words
     * change.
     *
     * The spellings come from the table the data repo publishes
     * ([KhiproGlideDownloads]), fetched the first time this runs; gliding waits
     * for it. Only when it cannot be had (offline, or a build with no internet)
     * are they all worked out on the device by running Khipro backwards, which
     * on a downloaded list is minutes of every core (#593).
     */
    private fun ensureKhiproGlide() {
        val engine = suggestionEngine ?: return
        val words = engine.bengaliIndex.sortedWords ?: return
        val learned = userLexicon.mutationCount()
        val unlocked = userUnlocked
        val table = KhiproGlideDownloads.file(filesDir).takeIf { unlocked && it.isFile }
        val tableSize = table?.length() ?: -1L
        val spec = KhiproSpecs.activeRevision()
        if (khiproGlideList === words && khiproGlideLearned == learned && khiproGlideTable == tableSize &&
            khiproGlideSpec == spec
        ) {
            return
        }
        if (khiproGlideJob?.isActive == true) return
        if (unlocked && table == null && !KhiproGlideDownloads.failed) {
            // Back here through the completions once it lands or fails.
            KhiproGlideDownloads.start(filesDir)
            return
        }
        val dir = File(File(filesDir, "dict"), "bn")
        khiproGlideJob = serviceScope.launch {
            // Shown only when the spellings are really being worked out, which
            // on a downloaded list is minutes; a cached list says nothing.
            var notify: DownloadNotifications.Handle? = null
            val (main, personal) = withContext(Dispatchers.Default) {
                val main = khiproGlideMain.takeIf {
                    khiproGlideList === words && khiproGlideTable == tableSize && khiproGlideSpec == spec
                }
                    ?: if (unlocked) {
                        val downloaded = KhiproSpecs.state.value.takeIf { it.downloaded }?.revision
                        KhiproGlideSpellings.load(words, dir, premade = table, downloadedSpec = downloaded) { done, total ->
                            synchronized(this@WMKeyboardService) {
                                val handle = notify ?: DownloadNotifications.start(
                                    this@WMKeyboardService,
                                    KHIPRO_GLIDE_NOTIFY_KEY,
                                    getString(R.string.khipro_glide_preparing_title),
                                ).also { notify = it }
                                handle.progress(
                                    done.toLong(),
                                    total.toLong(),
                                    getString(R.string.khipro_glide_preparing_progress, done, total),
                                )
                            }
                        }
                    } else {
                        null
                    }
                val own = userLexicon.allWords().filter { (word, _) -> word.any { it in '\u0980'..'\u09FF' } }
                main to KhiproGlideSpellings.ofWords(own)
            }
            if (main != null) notify?.done() else notify?.failed()
            khiproGlideMain = main
            khiproGlideList = words
            khiproGlideLearned = learned
            khiproGlideTable = tableSize
            khiproGlideSpec = spec
            romanizedGlides = romanizedGlides +
                (KHIPRO_GLIDE to RomanizedIndex.deterministic(main ?: PackedTrie.EMPTY, personal, KhiproRomanizer.KEYS, Khipro::convert))
            glideSourcesEpoch.update { it + 1 }
        }
    }

    /**
     * The spellings a swipe over the Pinyin board decodes into (#580), built
     * from the pinyin table once it is loaded and again whenever it changes.
     * Off the main thread: it walks every row of the table.
     */
    private fun ensurePinyinGlide() {
        val table = CjkDictionaries.pinyin
        if (table.isEmpty || pinyinGlideTable === table || pinyinGlideJob?.isActive == true) return
        pinyinGlideJob = serviceScope.launch {
            val trie = withContext(Dispatchers.Default) {
                PackedTrie.of(PinyinGlide.spellings(table, PinyinSyllables.valid))
            }
            pinyinGlideTable = table
            romanizedGlides = romanizedGlides +
                (PINYIN_GLIDE to RomanizedIndex.deterministic(trie, PackedTrie.EMPTY, PINYIN_GLIDE_KEYS) { it })
            glideSourcesEpoch.update { it + 1 }
        }
    }

    private var pinyinGlideJob: Job? = null
    private var pinyinGlideTable: ConversionDictionary? = null

    /**
     * The spellings a swipe over a kana board decodes into (#958), built from
     * the Japanese table once it is loaded and again whenever it changes. Off
     * the main thread: it walks every row of the table, a million of them.
     */
    private fun ensureKanaGlide() {
        val table = CjkDictionaries.japanese
        if (table.isEmpty || kanaGlideTable === table || kanaGlideJob?.isActive == true) return
        kanaGlideJob = serviceScope.launch {
            val trie = withContext(Dispatchers.Default) { PackedTrie.of(KanaGlide.spellings(table)) }
            kanaGlideTable = table
            romanizedGlides = romanizedGlides +
                (KANA_GLIDE to RomanizedIndex.deterministic(trie, PackedTrie.EMPTY, KanaGlide.KEYS, KanaGlide::reading))
            glideSourcesEpoch.update { it + 1 }
        }
    }

    private var kanaGlideJob: Job? = null
    private var kanaGlideTable: ConversionDictionary? = null

    /**
     * A swipe over a board whose words are readings — Pinyin (#580), Kana JIS
     * (#958): the stroke decodes into a reading, which joins the composing
     * buffer as if typed, and the strip converts it. Nothing is committed and
     * no space follows — the reading is only the start of a pick, and a second
     * swipe carries the same sentence on.
     */
    private fun readingGlide(points: List<GesturePoint>, keys: List<KeyCenter>, keyWidthPx: Float) {
        gestureGeneration.incrementAndGet()
        suggestionJob?.cancel()
        gestureJob?.cancel()
        clearGlidePreview()
        val composer = _uiState.value.composer
        gestureJob = serviceScope.launch {
            val reading = withContext(Dispatchers.Default) { glideDecode(points, keys, keyWidthPx) }
            val word = reading.words.firstOrNull()
            val spelled = if (composer.glidesKanaReadings) {
                word?.filter { it in 'ぁ'..'ゖ' || it == 'ー' }
            } else {
                word?.lowercase()?.filter { it in 'a'..'z' }
            }
            if (spelled.isNullOrEmpty()) return@launch
            val ic = currentInputConnection ?: return@launch
            if (_uiState.value.composer !== composer) return@launch
            appendComposing(spelled)
            updateComposingText(ic)
            refreshSuggestions()
        }
    }

    private var khiproGlideJob: Job? = null
    private var khiproGlideMain: WordSource? = null
    private var khiproGlideList: SortedWords? = null
    private var khiproGlideLearned = -1L
    private var khiproGlideTable = -1L
    private var khiproGlideSpec: String? = null

    /**
     * Looks for a newer Khipro spec set (#909), at most once a day, as a word
     * starts on a Khipro layout: the layout is in use, so its fixes are worth
     * the 200 KB. Data saving holding background downloads back holds this too.
     */
    private fun refreshKhiproSpecsIfDue() {
        if (!userUnlocked || !KhiproSpecs.isDue()) return
        val saver = dataSaverStatus
        val allowed = !(saver.active && saver.settings.downloads.stopsBackgroundWork)
        if (!allowed) return
        serviceScope.launch(Dispatchers.IO) { KhiproSpecs.refreshIfDue(allowed = true) }
    }

    /** Desktop Avro's data while a Bangla candidate list is on; see [loadAvroDesktop]. */
    private var avroDesktop: AvroDesktop? = null
    private var avroDesktopLoading = false

    /**
     * Pushes the fixed-strip setting of the layout now on screen ([spec]) to
     * the engine, and rebuilds the strip of a word being typed when it changed,
     * so the chips rearrange under the finger rather than at the next letter.
     */
    private fun syncPhoneticFixedStrip(settings: KeyboardSettings, spec: LayoutSpec) {
        val engine = suggestionEngine ?: return
        val language = spec.resolvedComposer().phoneticLanguage
        val next = settings.suggestionStrip.phoneticFixedStripFor(language)
        if (engine.phoneticFixedStrip == next) return
        engine.phoneticFixedStrip = next
        commitResolution = null
        if (composing.isEmpty() || _uiState.value.composer.phoneticLanguage == null) return
        refreshSuggestions()
    }

    /**
     * Whether the word a completion layout (Khipro) is composing began with a
     * word character right behind or in front of the caret, typed into the
     * middle of another word. Set where such a word starts, the only way its
     * buffer starts, since these layouts never resume one.
     */
    private var completionInsideWord = false

    /**
     * [latin] with the capital a sentence opens on, when the field asks for
     * one. A phonetic layout's own script has no case, so shift is never armed
     * there and an English word committed from it would otherwise always open
     * a message in lower case. [typed] with a capital of its own is left as the
     * user wrote it.
     */
    private fun sentenceCasedLatin(latin: String, typed: String, state: KeyboardUiState): String {
        if (!state.settings.autoText.capitalize || typed.any { it.isUpperCase() }) return latin
        if (previousWord != WordContext.SENTENCE_START) return latin
        val inputType = currentInputEditorInfo?.inputType ?: return latin
        if (inputType and InputType.TYPE_MASK_CLASS != InputType.TYPE_CLASS_TEXT ||
            inputType and InputType.TYPE_TEXT_FLAG_CAP_SENTENCES == 0
        ) {
            return latin
        }
        return latin.replaceFirstChar { it.uppercase() }
    }

    /**
     * The English word [buffer] commits as on a layout whose keys spell the
     * word outright (Khipro), or null when it commits what they spell (#487).
     * One answer for the preview, the strip and the space bar. Never for keys
     * typed inside another word ([completionInsideWord]): `if` there is the
     * ি going back into a word, and English stays a chip on the strip (#986).
     */
    private fun completionLatin(state: KeyboardUiState, buffer: String): String? {
        val language = state.composer.completionLanguage ?: return null
        if (buffer.isEmpty() || !state.allowsTypingIntelligence || completionInsideWord) return null
        val latin = suggestionEngine?.completionLatin(language, buffer, state.composer.composeBuffer(buffer))
            ?: return null
        return sentenceCasedLatin(latin, buffer, state)
    }

    /** Whether [word] is in Latin letters, on a layout whose own words are not. */
    private fun isLatinOnPhonetic(word: String, state: KeyboardUiState): Boolean {
        val scheme = PhoneticSchemes.forLanguage(
            state.composer.phoneticLanguage ?: state.composer.completionLanguage,
        ) ?: return false
        return word.none(scheme.isNative) && word.any { it in 'a'..'z' || it in 'A'..'Z' }
    }

    /**
     * The language a committed [word] is learned under. A phonetic layout's
     * language, except for a word it committed in Latin letters: that one is
     * English, and filed under Bengali it would be damped in English fields and
     * counted as Bengali by the field's language detection.
     */
    private fun learnLanguageId(word: String, state: KeyboardUiState): String =
        if (isLatinOnPhonetic(word, state)) "en" else nativeOnLatin(word, state) ?: state.language.id

    /**
     * The phonetic secondary whose script [word] is in, on a keyboard that is
     * not phonetic: a reading picked from the strip (मराठी on English) is that
     * language's word, and filed under English it would count as English in
     * the field's language detection.
     */
    private fun nativeOnLatin(word: String, state: KeyboardUiState): String? {
        if (state.composer.phoneticLanguage != null || state.composer.completionLanguage != null) return null
        return phoneticSecondaryIds(state.settings, state.language.id)
            .firstOrNull { id -> PhoneticSchemes.forLanguage(id)?.let { word.any(it.isNative) } == true }
    }

    /**
     * The ⌦ key: deletes forward, over the character *after* the cursor.
     *
     * A panel search owns the keys while it is open, and its query is a plain
     * string with no caret inside it — there is no "after the cursor" to act
     * on, and reaching past the panel would edit field text the user cannot
     * see. So the key stands down in those contexts rather than doing
     * something surprising.
     */
    private fun onForwardDelete() {
        // Every keyboard-owned field has a caret now (#161), so every one of
        // them has an "after the cursor" to delete from.
        if (captureForwardDelete()) return
        deleteForwardFromField()
    }

    /**
     * One forward delete against the real text field: a selection if there is
     * one, otherwise the whole grapheme cluster after the cursor.
     *
     * Composing text sits *before* the caret, so it is never what forward
     * delete removes — but editing around a live composing region strands its
     * underline, so the buffer is committed as-is (never autocorrected: the
     * user did not signal the word was finished) before the deletion lands.
     */
    private fun deleteForwardFromField() {
        val ic = currentInputConnection ?: return
        // The tail this delete eats into is half of what the mid-word strip is
        // about, so that strip goes with it.
        clearCaretWord()
        // A selection is what gets deleted, exactly as backspace does.
        if (hasSelection(ic)) {
            dropComposingForSelectionEdit(ic)
            noteDeletedForLearning(expectedSelStart, expectedSelEnd)
            invalidateExpectedSelection()
            ic.commitText("", 1)
            return
        }
        if (composing.isNotEmpty()) commitComposing(ic, autocorrect = false)
        // A TYPE_NULL editor reads back as empty however much it holds, so the
        // lookahead below would call every ⌦ a no-op. The key event is the only
        // forward delete such an editor hears, exactly as backspace already
        // sends one there (issue #268).
        if (isNullField()) {
            sendDownUpKeyEvents(KeyEvent.KEYCODE_FORWARD_DEL)
            return
        }
        // The lookahead has to outrun the longest emoji ZWJ/tag sequence, the
        // same way backspace's lookback does.
        val after = ic.getTextAfterCursor(64, 0)
        if (after.isNullOrEmpty()) return
        val forward = Graphemes.firstLength(after).coerceAtLeast(1)
        // Mirrored for the same reason backspace mirrors its own deletions:
        // a caret parked inside a word is being followed, and an edit the
        // mirror never heard about leaves it a character behind the field.
        revision?.expectDelete(0, forward)
        if (expectedSelStart >= 0) noteDeletedForLearning(expectedSelStart, expectedSelStart + forward)
        invalidateExpectedSelection()
        ic.deleteSurroundingText(0, forward)
        // Nothing before the cursor moved, so the bigram context still holds;
        // only the strip's completion view of the field changed.
        refreshSuggestions()
    }

    /**
     * Deletes the word after the cursor: one step of a forward delete swipe,
     * and one tick of a held ⌦ that clears words (issues #226 and #216).
     *
     * The mirror of [onDeleteWord], including taking the whitespace the cursor
     * sits on along with the word past it, so holding ⌦ chews forward through
     * a sentence the way ctrl+delete does on a desktop.
     */
    /**
     * One word out of the focused keyboard-owned field (#612): the one before
     * the caret, or after it for ⌦, measured by the same rule as the app's
     * field, with a selection going first the way a press takes it. False
     * where the field has no caret of its own to measure from (the word card,
     * the typing test, the computer's line) or a transliterator is mid-word,
     * so the caller deletes one character as before.
     */
    private fun captureDeleteWord(forward: Boolean): Boolean {
        val state = _uiState.value
        val target = state.captureTarget() ?: return false
        if (target == CaptureTarget.WORD_SPELL || target == CaptureTarget.KDE_REMOTE || !target.movableCaret) return false
        val before = state.captureCaretText() ?: return false
        if (composesInCapture(state.composer) && liveCaptureComposition(state, before) != null) return false
        if (before.hasSelection) {
            captureWrite(target, before, before.withoutSelection())
            return true
        }
        val at = before.at
        val head = before.text.substring(0, at)
        val tail = before.text.substring(at)
        val length = if (forward) WordDelete.lengthAfter(tail, deleteWordBreaks())
        else WordDelete.lengthBefore(head, deleteWordBreaks())
        if (length <= 0) return true
        val after = if (forward) {
            CaretText(head + tail.substring(length.coerceAtMost(tail.length)), at)
        } else {
            val from = (at - length).coerceAtLeast(0)
            CaretText(head.substring(0, from) + tail, from)
        }
        captureWrite(target, before, after)
        return true
    }

    private fun onForwardDeleteWord() {
        // Every box that eats keystrokes has no "after the cursor" of its own,
        // which is the whole reason [onForwardDelete] stands down in one; a
        // word step has no more business reaching past it than a character one.
        if (!forwardDeleteOwnsBuffer()) {
            if (!captureDeleteWord(forward = true)) onForwardDelete()
            return
        }
        val ic = currentInputConnection ?: return
        clearCaretWord()
        if (hasSelection(ic)) {
            dropComposingForSelectionEdit(ic)
            noteDeletedForLearning(expectedSelStart, expectedSelEnd)
            invalidateExpectedSelection()
            ic.commitText("", 1)
            return
        }
        // Composing text sits before the caret, so it is never what a forward
        // delete takes — but editing around a live region strands its
        // underline. Committed as it stands, never autocorrected: the user did
        // not signal the word was finished.
        if (composing.isNotEmpty()) commitComposing(ic, autocorrect = false)
        // The mirror of the word backspace above: no readable text, no word to
        // measure, so one character goes instead of none (issue #268).
        if (isNullField()) {
            sendDownUpKeyEvents(KeyEvent.KEYCODE_FORWARD_DEL)
            return
        }
        val after = ic.getTextAfterCursor(96, 0) ?: return
        val length = WordDelete.lengthAfter(after, deleteWordBreaks())
        if (length <= 0) return
        revision?.expectDelete(0, length)
        if (expectedSelStart >= 0) noteDeletedForLearning(expectedSelStart, expectedSelStart + length)
        invalidateExpectedSelection()
        ic.deleteSurroundingText(0, length)
        refreshSuggestions()
    }

    /**
     * Whether ⌦ is acting on the real text field rather than standing down in
     * favour of one of the keyboard's own text boxes.
     *
     * One question now, not a hand-written list: the list used to name every
     * buffer but the spelling draft, on the reasoning that a plain string has
     * nothing after a cursor. They all have a cursor since #161, so they all
     * take their own forward delete.
     */
    private fun forwardDeleteOwnsBuffer(): Boolean = _uiState.value.captureTarget() == null

    /**
     * Whether a forward delete would still remove anything, so the held-repeat
     * loop stops at the end of the text instead of buzzing against nothing.
     */
    fun canForwardDelete(): Boolean {
        val state = _uiState.value
        state.wordSpell?.let { return it.hasSelection || it.cursor < it.draft.length }
        // A keyboard-owned field stops the held key at the end of its own text.
        state.captureTarget()?.let { target ->
            if (!target.movableCaret) return false
            val caret = state.captureCaretText() ?: return false
            return caret.hasSelection || caret.at < caret.text.length
        }
        val ic = currentInputConnection ?: return false
        if (hasSelection(ic)) return true
        // Same blind buffer as in [canDeleteField] (issue #268): a TYPE_NULL
        // editor's "" is not an end of text, so the held key keeps going.
        if (isNullField()) return true
        // A null answer means the editor can't say — keep deleting rather than
        // stopping a working key; only a definite "" stops it.
        val after = ic.getTextAfterCursor(1, 0) ?: return true
        return after.isNotEmpty()
    }

    /**
     * Re-reads the completed word before the cursor and makes it the
     * prediction context, or clears it when there is none.
     *
     * A cursor sitting mid-word has no *completed* previous word, so it
     * predicts from nothing rather than from the fragment it is inside.
     */
    private fun syncPreviousWordFromField(ic: InputConnection) {
        val before = readableContext(ic.getTextBeforeCursor(64, 0))
        setContextFrom(before)
        rebuildRecentWords(before)
        seedFieldLanguageMix()
        // The caret moved, or a field opened: the remembered commits no
        // longer line up with the words in front of it.
        suggestionEngine?.clearCommits()
        pushSentenceContext()
    }

    /**
     * Re-derives the engine's per-field language mix from [recentWords] —
     * the tokens [rebuildRecentWords] just read off the field — so the mix
     * always describes the words in front of the user. Runs wherever the
     * field is re-read: entry, caret jumps, post-edit re-syncs. Between
     * re-reads the engine keeps itself current from each committed word.
     */
    private fun seedFieldLanguageMix() {
        val engine = suggestionEngine ?: return
        if (engine.fieldDetectionShift <= 0.0) {
            engine.clearFieldContext()
            return
        }
        val words = ArrayList<String>(recentWords.size)
        for (token in recentWords) {
            val word = token.trim { !it.isLetter() }
            if (word.isNotEmpty()) words.add(word)
        }
        // Where this app's fields usually start, when the user lets the
        // keyboard remember that; the field's own words then decay it.
        val prior = currentPackage
            ?.takeIf { _uiState.value.settings.suggestionStrip.languageDetectionByApp }
            ?.let { appLanguageMix.prior(it) }
        engine.seedFieldContext(words, prior)
    }

    /**
     * Credits the app in focus with the languages that own [word], for the
     * prior [seedFieldLanguageMix] starts its fields from. Kept even while
     * detection itself is off, so the habit is ready the day it is turned on;
     * never kept when the user has said not to remember apps.
     */
    private fun noteAppLanguage(word: String) {
        val pkg = currentPackage ?: return
        if (!_uiState.value.settings.suggestionStrip.languageDetectionByApp) return
        val engine = suggestionEngine ?: return
        appLanguageMix.record(pkg, engine.owningLanguages(word))
    }

    /**
     * The engine's calibrated detection shift for the current settings: 0
     * (off) unless the user has left field-language detection on, else the
     * strength they chose.
     */
    private fun fieldDetectionShift(settings: KeyboardSettings): Double =
        if (!settings.suggestionStrip.languageDetection) {
            SuggestionEngine.FIELD_SHIFT_OFF
        } else {
            when (settings.suggestionStrip.languageDetectionStrength) {
                LanguageDetectionStrength.GENTLE -> SuggestionEngine.FIELD_SHIFT_GENTLE
                LanguageDetectionStrength.BALANCED -> SuggestionEngine.FIELD_SHIFT_BALANCED
                LanguageDetectionStrength.AGGRESSIVE -> SuggestionEngine.FIELD_SHIFT_AGGRESSIVE
            }
        }

    /**
     * Adds a freshly committed [word] to the pattern gate's memory.
     *
     * Called wherever [previousWord] takes a word the keyboard just put in the
     * field, so the two never disagree about what was typed.
     */
    private fun pushRecentWord(word: String) {
        if (word.isEmpty()) return
        recentWords.addLast(word)
        while (recentWords.size > RECENT_WORDS) recentWords.removeFirst()
        recentWordsValid = true
    }

    /**
     * Refills the pattern gate's memory from text a caller has already read.
     *
     * Always from real field text, never from what the keyboard believes it
     * committed. A gate that drifts is worse than one that is simply empty, and
     * every caller here is somewhere [previousWord] is being re-derived from
     * the same characters — so this costs nothing extra.
     */
    private fun rebuildRecentWords(text: CharSequence?) {
        recentWords.clear()
        recentWordsValid = true
        if (text == null) return
        var end = text.length
        while (end > 0 && recentWords.size < RECENT_WORDS) {
            while (end > 0 && WordContext.isSpaceLike(text[end - 1])) end--
            if (end == 0) break
            var start = end
            while (start > 0 && !WordContext.isSpaceLike(text[start - 1])) start--
            recentWords.addFirst(text.subSequence(start, end).toString())
            end = start
        }
    }

    /** Forgets the recent words, so the gate reads the field rather than guess. */
    private fun invalidateRecentWords() {
        recentWords.clear()
        recentWordsValid = false
    }

    /**
     * The completed word ending [text] — the bigram context for whatever comes
     * next — or null when [text] ends inside a word (a fragment is no context)
     * or holds no word at all.
     */
    private fun completedWordBefore(text: CharSequence?): String? =
        WordContext.completedWordBefore(text, SENTENCE_ENDERS)

    /** Sets the context words from the text before the caret. */
    private fun setContextFrom(text: CharSequence?) {
        // Under Fancy Text the words behind the caret are styled; the context is their plain spelling.
        val plain = if (text != null && fancyOutputStyle(_uiState.value) != null) FancyStyles.unstyle(text) else text
        val (prev1, prev2, prev3) = WordContext.lastThreeWords(plain, SENTENCE_ENDERS)
        previousWord = prev1
        previousWord2 = prev2
        previousWord3 = prev3
    }

    /**
     * Mirrors whether the caret sits collapsed at the start of the field into
     * [KeyboardUiState.caretAtFieldStart]. Taken from the editor's own reports
     * rather than from where the strip's words came from: some thirty paths
     * write the strip, and a flag each of them had to clear would go stale.
     * An unknown selection (-1) is not the start.
     */
    private fun trackCaretAtFieldStart(selStart: Int, selEnd: Int) {
        val atStart = selStart == 0 && selEnd == 0
        if (_uiState.value.caretAtFieldStart != atStart) {
            _uiState.update { it.copy(caretAtFieldStart = atStart) }
        }
    }

    /**
     * Re-reads the context around a cursor that moved without going through a
     * keystroke — a tap elsewhere, a selection-handle drag, a spacebar-swipe
     * caret move, or an edit the app itself made — so the strip reflects where
     * the caret *now* sits instead of the word last typed.
     *
     * When the caret lands at the end of a word, that word is re-entered as the
     * composing region: the strip offers its completions and corrections, and
     * typing on extends it, exactly as if it were being typed fresh (with the
     * word before it restored as the bigram context). Otherwise only the
     * preceding-word context is re-derived — a caret mid-word or after a
     * separator has no word to resume, so it predicts the next one (or clears).
     *
     * Any language that has something to complete from and whose composer can
     * say what to put behind the region — see [composingResumable], which is
     * where the transliterating layouts drop out. The cluster-shaping ones
     * (Probhat, Jatiya, fixed Devanagari…) are in: they do not compose while
     * typing, but a word handed to them here is their own script and they keep
     * composing it until the next boundary (see [processTypedText]'s
     * `composingMode`). Vietnamese is in too, and is the one that hands back
     * something other than the word: its buffer is the keystrokes that spell it
     * ([Composer.resumeBuffer]), so a tone key typed after the resume lands on
     * the word rather than being spelled into it.
     * [newSelStart] is the caret offset the field just reported, used to place
     * the composing region.
     */
    private fun restartSuggestionsAtCursor(ic: InputConnection, newSelStart: Int) {
        // The caret went somewhere: the next word is not the one No space
        // meant to join on (#851). The echo of No space's own edit, landing
        // where it left the caret, is not that (#867).
        if (!glueNextWord || newSelStart != glueCaret) glueNextWord = false
        glueCaret = -1
        scheduleRecentBar()
        // The caret settling where a Retype left it (#791): the strip stays on
        // the word that was taken out, rather than predicting past it.
        retypeOffer?.let { offer ->
            if (composing.isEmpty() && (offer.start < 0 || offer.start == newSelStart)) {
                clearCaretWord()
                publishRetypeOffer(RetypeOffer(offer.word, newSelStart, offer.readings))
                return
            }
        }
        val state = _uiState.value
        // Whatever the caret was sitting in before this update, it is being
        // answered again from scratch below.
        clearCaretWord()
        resumedWord = null
        numberRun = null
        numberRunPending = false
        caretSettleJob?.cancel()
        caretSettleJob = null
        // The caret settling right after a swipe is the commit's own echo:
        // keep the gesture alternates on the strip (tap-to-replace) instead
        // of re-deriving completions for the word just committed. Any real
        // caret move disarms lastGestureWord first (see revertAnchor), so
        // this never suppresses a genuine context re-read.
        if (lastGestureWord != null) {
            refreshSmartSuggestion()
            return
        }
        // Same for the caret settling after a snippet expansion. An expansion
        // that ends in a letter would otherwise have its last word re-armed as
        // composing, and backspace edits a composing buffer instead of taking
        // the expansion back — which is the one thing backspace has to do here.
        if (lastRevertible?.kind == RevertibleCommit.Kind.SNIPPET) {
            refreshSmartSuggestion()
            return
        }
        // And for the caret settling after the enter key. The word it ended has
        // gone to the app — searched for, or sent — and re-arming it as the
        // composing region puts the keyboard back inside text it has finished
        // with: the next enter commits that buffer over again, which in a
        // message box the app has meanwhile emptied means the message is
        // retyped and sent a second time, and a third (#236). See
        // [wordEndedByEnter], which this spends.
        if (wordEndedByEnter) {
            wordEndedByEnter = false
            refreshSmartSuggestion()
            return
        }
        // And for the caret settling in the middle of a code being typed one
        // character at a time ([commitCodeToField]). Each of those commits
        // echoes back as a caret move, and none of them is the user arriving
        // anywhere: the word at the caret is the one the keyboard is still
        // writing. Re-armed as the composing region, it is replaced by the very
        // next character of the same run — the first characters of a pasted
        // code were eaten this way, in a Vietnamese layout, where a word read
        // out of the field can be spelled back into keys and so takes the
        // region. The panel's own tap is unaffected either way, because a
        // resume is blocked while a panel owns the screen.
        //
        // The job outlives the last character on purpose: the echoes of a
        // batch are delivered after it, and a run that ended first left the
        // caret of its own finished code to be read as a word (see
        // [CODE_ECHO_SETTLE_MS]).
        if (codeEntryJob?.isActive == true) {
            refreshSmartSuggestion()
            return
        }
        val scrubbing = SystemClock.uptimeMillis() - lastCaretScrubMs < CARET_SCRUB_WINDOW_MS
        // A drag is still in progress, so this landing spot is not the one the
        // user means. The editor sends no update when the finger finally stops,
        // so the re-read has to be scheduled here or it never happens at all
        // (see [caretSettleJob]).
        if (scrubbing) {
            caretSettleJob = serviceScope.launch {
                delay(CARET_SCRUB_WINDOW_MS)
                caretSettleJob = null
                val settled = currentInputConnection
                if (settled != null && expectedSelStart >= 0 && expectedSelStart == expectedSelEnd) {
                    restartSuggestionsAtCursor(settled, expectedSelStart)
                }
            }
        }
        // No resume while a panel owns the screen: a word re-armed as
        // composing behind an open Grammar/AI/Translate panel hijacks that
        // panel's replace-field commit onto the composing region. Write-on-
        // keys handwriting and an in-flight Whisper transcription commit
        // their own text the same way, so they must not race a resume either.
        // Interactive voice typing is the exception to the dictation clause
        // above: it puts nothing of its own in the composing region, it
        // flushes whatever is being composed before its phrase lands, and
        // correcting a word by hand mid-session is what the mode is for.
        val voiceBlocksResume = when (state.voice.status) {
            VoiceStatus.LISTENING, VoiceStatus.FINISHING, VoiceStatus.TRANSCRIBING ->
                !state.settings.voiceBar.interactiveTyping()
            else -> false
        }
        val canResume = !scrubbing && state.settings.suggestions &&
            state.panel == PanelMode.NONE &&
            !keyboardHandwriteActive(state) &&
            !state.secureField && !state.fieldNoSuggestions &&
            state.resumesWords &&
            // Nothing of the keyboard's own has the keys: a caret settling in
            // the app behind an open search box is not a word the user is
            // writing, and resuming it would compose into text they cannot see.
            state.captureTarget() == null &&
            !voiceBlocksResume &&
            // A Keyman rule engine types committed text and keeps its own
            // context. A word re-armed as composing behind it is a region the
            // engine's next commitText replaces wholesale, so every key would
            // overwrite the one before it.
            keymanSession == null &&
            // ANSI in the field is Latin letters standing for Bengali glyphs,
            // Zawgyi is Burmese in glyph order. Composed again, either would be
            // read, corrected and converted as though it were the Unicode the
            // keyboard typed.
            outputEncoding == null &&
            // Fancy Text's words are styled in the field, and the buffer holds
            // plain letters: a word read back from there is not one it can take.
            fancyOutputStyle(state) == null &&
            // Last, so the one term that asks the engine anything is only
            // reached once the screen and the field have already said yes.
            composingResumable(state.composer, suggestionEngine?.hasWordSources == true)

        // Held outside the block so the fall-through below can reuse it rather
        // than asking the editor for the same 64 characters again — that read
        // is a blocking round-trip into the focused app, and this runs from
        // onUpdateSelection.
        var beforeText: CharSequence? = null
        if (canResume && newSelStart >= 0) {
            val before = ic.getTextBeforeCursor(64, 0)
            beforeText = before
            // Enough to carry the rest of the word the caret may be sitting
            // inside; the resume test below only ever looks at the first
            // character, so the wider window costs nothing extra (one read
            // either way).
            val after = ic.getTextAfterCursor(CARET_WORD_AHEAD, 0)
            // The word the caret is parked at the end of, or null — see
            // [resumableWordAt], which is also where "what counts as part of a
            // word" lives now that the answer is not "a letter".
            val word = resumableWordAt(before, after)
            if (word != null && before != null) {
                // Mark the existing word as composing without disturbing it,
                // then mirror it into the buffer so a keystroke extends it
                // and a backspace shortens it. previousWord comes from the
                // text ahead of the word, not the caret (which is inside it).
                // Mirror ONLY if the editor accepted the region: some editors
                // (web views, odd search boxes) refuse setComposingRegion, and
                // a buffer with no region behind it makes the next
                // setComposingText insert the whole word again at the caret —
                // the word "reappears" and the existing text can't be edited.
                // And only if newSelStart is still the live caret: the word was
                // read at the *current* cursor, so pairing it with a stale echo
                // offset puts the region over the wrong span (see caretStillAt).
                //
                // The buffer is the composer's own reading of the word, which is
                // the word itself for most layouts and the keystrokes that spell
                // it for Vietnamese (Telex `toois` behind the field's `tối`), so
                // the next tone key lands on the word the caret came back to
                // instead of being spelled into it. A composer that cannot read
                // this word back — one of the several spellings that would not
                // compose it — leaves the caret where the fall-through below
                // treats it: read-only.
                val buffer = state.composer.resumeBuffer(word)
                if (buffer != null && caretStillAt(ic, newSelStart) &&
                    ic.setComposingRegion(newSelStart - word.length, newSelStart)
                ) {
                    composing = StringBuilder(buffer)
                    composingCaseTrusted = false
                    // Went back to this word: if a glide wrote it, the strip
                    // offers that stroke's other readings (#115).
                    resumedWord = word
                    resumedWordStart = newSelStart - word.length
                    armComposingRevision(word, newSelStart)
                    val ahead = before.subSequence(0, before.length - word.length)
                    setContextFrom(ahead)
                    rebuildRecentWords(ahead)
                    _uiState.update { it.copy(composingPreview = word) }
                    refreshSuggestions()
                    return
                }
            }
            // Nothing to resume, but the caret may still be *touching* a word:
            // dropped into the middle of one, or parked right in front of it.
            // That word gets the strip too — a caret on a word is the user
            // looking at that word (#32) — read-only, because a composing
            // region cannot hold a caret in its middle (see [caretWord]).
            //
            // Or parked at the end of one the resume above turned down: an
            // editor that refused the region, an echo the caret had already
            // moved past, a spelling the composer cannot read back. Read-only
            // too, with nothing ahead of the caret, so `word| to` still puts
            // the word on the strip instead of predicting past it (#413).
            val touching = caretWordAt(before, after) ?: word?.let { it to "" }
            if (touching != null) {
                val (head, tail) = touching
                // Context comes from the text ahead of the word, not from the
                // caret, which is inside it — same rule as the resume above.
                val ahead = before?.let { it.subSequence(0, it.length - head.length) }
                setContextFrom(ahead)
                rebuildRecentWords(ahead)
                caretWord = CaretWord(head, tail, newSelStart - head.length)
                armFieldRevision(head, tail, newSelStart)
                refreshSuggestions()
                return
            }
        }
        // No word to resume: predict from the completed word behind the caret,
        // or clear when there is none. refreshSuggestions self-gates on the
        // field flags, so this stays correct in secure / no-suggestion fields.
        // `beforeText` is null exactly when the branch above never read it.
        val cached = beforeText
        if (cached != null) {
            setContextFrom(cached)
            rebuildRecentWords(cached)
        } else {
            syncPreviousWordFromField(ic)
        }
        noteNumberRun(ic, cached)
        refreshSuggestions()
    }

    /**
     * Whether numbers are being remembered and offered here (#431): the
     * setting, and never in a password box, where a PIN is exactly the number
     * nobody wants kept. Incognito and learning being off stop the
     * remembering in [rememberTypedNumber], not the offering.
     */
    private fun typedNumbersOn(state: KeyboardUiState): Boolean =
        state.settings.suggestionSources.typedNumbers && !state.secureField

    /**
     * Reads the run of digits the caret has just landed after, for the strip
     * to complete ([numberRun]) and for the key that ends it to remember
     * ([numberRunPending]). [before] is the text the caller already read, when
     * it read any; otherwise this asks the editor, but only with the setting
     * on, since it runs on every caret echo.
     */
    private fun noteNumberRun(ic: InputConnection, before: CharSequence?) {
        val state = _uiState.value
        val remembering = typedNumbersOn(state)
        if (!remembering && !klingonNumbersOn(state)) {
            numberRunPending = false
            return
        }
        val digits = TypedNumbers.runBefore(before ?: ic.getTextBeforeCursor(NUMBER_RUN_LOOKBEHIND, 0))
        numberRun = digits
        numberRunPending = remembering && digits != null
    }

    /**
     * Whether digits typed here are offered in Klingon words ([KlingonNumbers]):
     * on a Klingon layout, outside a password box. Independent of remembering
     * numbers, which is about the user's own numbers rather than how to say one.
     */
    private fun klingonNumbersOn(state: KeyboardUiState): Boolean =
        state.language.id == KlingonSuffixes.LANGUAGE && !state.secureField

    /**
     * Keeps the number the caret sits right after, if there is one standing
     * on its own (#431). Read live rather than taken from [numberRun], which
     * was dropped by the very key that ends the run and may in any case trail
     * a fast typist by a digit. Learning off, incognito and a field that keeps
     * the keyboard's hands off all keep it out, the same as a word.
     */
    private fun rememberTypedNumber() {
        if (!numberRunPending) return
        numberRunPending = false
        val state = _uiState.value
        if (!typedNumbersOn(state) || !learningAllowed || !userUnlocked) return
        val ic = currentInputConnection ?: return
        val digits = TypedNumbers.runBefore(ic.getTextBeforeCursor(NUMBER_RUN_LOOKBEHIND, 0)) ?: return
        typedNumbers.record(digits)
    }

    /**
     * Puts the remembered numbers that go on from [digits] on the strip, and says
     * whether there were any. None leaves the strip to the ordinary next-word
     * pass, which is what it showed after digits before this existed. A cheap
     * scan of a capped list, so it runs inline.
     */
    private fun publishTypedNumbers(digits: String): Boolean {
        val state = _uiState.value
        // In Klingon the number said in words leads, then the remembered ones.
        val spoken = if (klingonNumbersOn(state)) KlingonNumbers.spell(digits) else null
        val remembered = if (typedNumbersOn(state)) typedNumbers.complete(digits, NUMBER_SUGGESTION_LIMIT) else emptyList()
        val numbers = listOfNotNull(spoken) + remembered
        if (numbers.isEmpty()) return false
        suggestionJob?.cancel()
        _uiState.update {
            it.copy(
                suggestions = numbers,
                phoneticCandidates = emptyList(),
                emojiSuggestions = emptyList(),
                punctuationSuggestions = emptyList(),
                nextLetterBias = emptyMap(),
                octopus = emptyMap(),
                inlineEmoji = false,
                joinSuggestion = null,
                revisionSuggestion = null,
                autocorrectWord = null,
            )
        }
        return true
    }

    /** The editor's caret as it is now, read live; null for a range or an editor that will not say. */
    private fun liveCollapsedCaret(ic: InputConnection): Int? {
        val extracted = ic.getExtractedText(ExtractedTextRequest(), 0) ?: return null
        if (extracted.selectionStart < 0 || extracted.selectionStart != extracted.selectionEnd) return null
        return extracted.startOffset + extracted.selectionStart
    }

    /**
     * Whether a selection update moved the caret off a reading kept on the
     * strip (#973). An echo at [hiddenReadingCaret] is the keyboard's own; one
     * anywhere else may only be an older echo queued behind it, so the live
     * caret decides, and an editor that will not say where its caret is is
     * taken at the echo's word.
     */
    private fun hiddenReadingLeft(newSelStart: Int, newSelEnd: Int, candidatesStart: Int): Boolean {
        val at = hiddenReadingCaret
        if (at < 0 || candidatesStart >= 0 || !_uiState.value.readingInKeyboard()) return false
        if (newSelStart == at && newSelEnd == at) return false
        val ic = currentInputConnection ?: return false
        return liveCollapsedCaret(ic) != at
    }

    /**
     * Whether [reportedSelStart] is still where the editor's caret actually
     * sits. Selection updates queue behind fast keystrokes and backspaces, so
     * an echo can describe a caret the field has since moved past — and a
     * composing region placed from those stale offsets lands on the wrong
     * characters (the visible symptom is the underline hugging only the last
     * letter of a word). The extracted text is read live, so a mismatch means
     * "skip and wait for the next echo". Editors that don't support extraction
     * return null and are taken at their word, which is today's behavior.
     */
    private fun caretStillAt(ic: InputConnection, reportedSelStart: Int): Boolean {
        val extracted = ic.getExtractedText(ExtractedTextRequest(), 0) ?: return true
        if (extracted.selectionStart < 0) return true
        return extracted.startOffset + extracted.selectionStart == reportedSelStart
    }

    /**
     * [caretStillAt] for an edit that deletes (#844): an editor that will not
     * say where its caret is fails, rather than being taken at its word. A
     * Retype measured from a stale offset there deleted characters before
     * the real caret that were never the word.
     */
    private fun caretProvenAt(ic: InputConnection, reportedSelStart: Int): Boolean {
        val extracted = ic.getExtractedText(ExtractedTextRequest(), 0) ?: return false
        if (extracted.selectionStart < 0) return false
        return extracted.startOffset + extracted.selectionStart == reportedSelStart
    }

    /**
     * The word [retypeWord] would take, without taking it: the one being
     * typed, as shown, or the word behind the caret by the same rules. Null
     * when Retype would do nothing.
     */
    private fun retypeTarget(): String? {
        if (backspaceEditsBuffer() || isNullField()) return null
        if (composing.isNotEmpty()) return _uiState.value.composingPreview.ifEmpty { composing.toString() }
        val ic = currentInputConnection ?: return null
        if (expectedSelStart < 0 || expectedSelStart != expectedSelEnd) return null
        // [retypeWord] wants the caret proven before it deletes, so an editor
        // that will not say where it is is offered nothing (#872).
        if (!caretProvenAt(ic, expectedSelStart)) return null
        val before = runCatching { ic.getTextBeforeCursor(RETYPE_LOOKBEHIND, 0)?.toString() }.getOrNull() ?: return null
        val body = if (before.endsWith(' ') && !before.endsWith("  ")) before.dropLast(1) else before
        val word = body.takeLastWhile { isComposingWordChar(it) }
        if (word.none { it.isLetter() } || (word.length == body.length && before.length >= RETYPE_LOOKBEHIND)) return null
        return word
    }

    /**
     * Deletes the word before the cursor — one step of the backspace swipe.
     * Trailing whitespace goes with the word, so repeated steps chew back
     * through a sentence the way ctrl+backspace does on a desktop.
     */
    private fun onDeleteWord() {
        // A panel search owns the backspace key while it is open; word-deleting
        // the real field behind it would edit text the user cannot see. The
        // same goes for every other box that eats keystrokes — a plugin's text
        // box, the AI instruction, the typing test — which onDelete already
        // handles and this had drifted out of step with. A box with a caret
        // takes the word too (#612): a held delete set to clear words cleared
        // one letter at a time in the clip editor and Find and replace.
        if (backspaceEditsBuffer()) {
            if (!captureDeleteWord(forward = false)) onDelete()
            return
        }
        val ic = currentInputConnection ?: return
        // One swipe, one event — however many characters it takes with it.
        recordStat { onBackspace(System.currentTimeMillis(), SystemClock.uptimeMillis()) }
        clearCaretWord()
        if (hasSelection(ic)) {
            dropComposingForSelectionEdit(ic)
            invalidateExpectedSelection()
            ic.commitText("", 1)
            return
        }
        // A word in progress lives in the composing buffer, not the field.
        if (composing.isNotEmpty()) {
            composing.setLength(0)
            duetWord.clear()
            composingTouch.clear()
            composingKeys.clear()
            composingHints.clear()
            ambiguousReading = null
            keystrokeTiming.reset()
            updateComposingText(ic)
            refreshSuggestions()
            return
        }
        // Nothing readable behind the cursor in a TYPE_NULL editor, so there is
        // no word boundary to find: the step degrades to the one character the
        // key event can delete rather than to nothing at all (issue #268).
        if (isNullField()) {
            sendDownUpKeyEvents(KeyEvent.KEYCODE_DEL)
            return
        }
        val before = ic.getTextBeforeCursor(96, 0) ?: return
        // At the start of the field, the app's own backspace; see deleteFromField.
        if (before.isEmpty()) {
            sendDownUpKeyEvents(KeyEvent.KEYCODE_DEL)
            return
        }
        val length = WordDelete.lengthBefore(before, deleteWordBreaks())
        if (length > 0) {
            revision?.expectDelete(length, 0)
            if (expectedSelStart >= 0) noteDeletedForLearning(expectedSelStart - length, expectedSelStart)
            ic.deleteSurroundingText(length, 0)
            lastGestureWord = null
            lastRevertible = null
            clearSwapOffer()
            // The word that was deleted is gone as context, but whatever now
            // sits behind the cursor is the real one — nulling it outright
            // meant a swipe-delete mid-sentence stopped predicting until the
            // next word was typed.
            syncPreviousWordFromField(ic)
            // Both lists; see the gesture-undo path above.
            _uiState.update {
                it.copy(suggestions = emptyList(), emojiSuggestions = emptyList(), octopus = emptyMap())
            }
        }
    }

    /**
     * Retype (#791): takes the word right behind the caret back out of the
     * field so it can be typed again, and keeps what else it could have been.
     *
     * The target is the word that ends at the caret, or one space before it,
     * the space a pick or a glide leaves after a word; with a word still being
     * typed it is that word. Anything else behind the caret (a mark, a line
     * break, two spaces) is not a word to retype, and nothing happens rather
     * than reaching further back for one. Nothing happens either with a
     * selection, in a field that will not say what is behind its caret, or
     * when the caret is no longer where the keyboard last saw it: a stale
     * offset would take the wrong characters out.
     *
     * The word goes, and the caret is left where the word began. The space
     * goes with it only when the keyboard put it there ([pendingWordSpace]);
     * one the user typed stays, after the caret (#823). The strip then offers the word itself first, so one tap puts it
     * back, then whatever else its swipe read ([glideReadings]); a tapped word
     * has nothing more to offer, and nothing is made up for it. The word is
     * deleted the way a backspace swipe deletes one, so it is dropped from
     * the learning buffer with it.
     */
    private fun retypeWord() {
        if (backspaceEditsBuffer()) return
        val ic = currentInputConnection ?: return
        if (hasSelection(ic) || isNullField()) return
        val engine = suggestionEngine
        if (composing.isNotEmpty()) {
            // The word as the field shows it (#840): a transliterating
            // composer's buffer is its keys, and Telex's `huowngs` put back
            // is not the `hướng` that was taken out.
            val keys = composing.toString()
            val word = _uiState.value.composingPreview.ifEmpty { keys }
            val shown = _uiState.value.suggestions
                .filterNot { it.equals(word, ignoreCase = true) }
                .filterNot { it != word && it == keys && _uiState.value.composer.isTransliterating }
                .filterNot { engine?.suppresses(it) == true }
            composing.setLength(0)
            duetWord.clear()
            composingTouch.clear()
            composingKeys.clear()
            composingHints.clear()
            ambiguousReading = null
            keystrokeTiming.reset()
            updateComposingText(ic)
            clearCaretWord()
            publishRetypeOffer(RetypeOffer(word, -1, shown))
            return
        }
        val at = expectedSelStart
        if (at < 0 || !caretProvenAt(ic, at)) return
        val before = runCatching { ic.getTextBeforeCursor(RETYPE_LOOKBEHIND, 0)?.toString() }.getOrNull() ?: return
        val trailing = before.endsWith(' ') && !before.endsWith("  ")
        val body = if (trailing) before.dropLast(1) else before
        val keepSpace = trailing && !pendingWordSpace
        var from = body.length
        while (from > 0 && isComposingWordChar(body[from - 1])) from--
        val word = body.substring(from)
        // No letter, no word; and one that runs back past what was read may
        // be longer than it looks.
        if (word.none { it.isLetter() } || (from == 0 && before.length >= RETYPE_LOOKBEHIND)) return
        val length = before.length - from
        val start = at - length
        val readings = glideReadings.readingsAt(word, start).filterNot { engine?.suppresses(it) == true }
        recordStat { onBackspace(System.currentTimeMillis(), SystemClock.uptimeMillis()) }
        clearCaretWord()
        revision?.expectDelete(length, 0)
        noteDeletedForLearning(start, at)
        ic.beginBatchEdit()
        ic.deleteSurroundingText(length, 0)
        // Put back in front of the caret, so the word typed again lands
        // before it as the old one stood.
        if (keepSpace) ic.commitText(" ", 0)
        ic.endBatchEdit()
        pendingWordSpace = false
        lastGestureWord = null
        lastRevertible = null
        clearSwapOffer()
        syncPreviousWordFromField(ic)
        publishRetypeOffer(RetypeOffer(word, start, readings))
    }

    /**
     * Puts a Retype's word and its readings on the strip, and keeps them as
     * the offer. A strip refresh still waiting from before would land after
     * it and replace it (#844), so it is called off.
     */
    private fun publishRetypeOffer(offer: RetypeOffer) {
        suggestionJob?.cancel()
        retypeOffer = offer
        _uiState.update {
            it.copy(suggestions = offer.offered, emojiSuggestions = emptyList(), octopus = emptyMap())
        }
    }

    /**
     * Whether the backspace key is currently editing one of the keyboard's own
     * text boxes — a panel search, a plugin input, the typing test — rather
     * than the field behind it. Every one of them is a buffer the service owns
     * in [KeyboardUiState], with no cursor of its own in the editor, so nothing
     * that works through the input connection applies while one is up.
     */
    private fun backspaceEditsBuffer(): Boolean {
        val state = _uiState.value
        return state.captureTarget() != null ||
            ((state.panel == PanelMode.HANDWRITING || keyboardHandwriteActive(state)) &&
                state.handwriting.strokes.isNotEmpty())
    }

    // ---- backspace swipe with preview (issue #36) ----

    /**
     * How much text either side of the cursor a delete swipe reads when it
     * starts.
     *
     * Read once and kept, so dragging back costs nothing and the editor is not
     * asked the same question on every pointer event. It is also the swipe's
     * reach: at the shipped step sizes even the character mode would need
     * metres of dragging to walk past it.
     */
    private val deleteSwipeLookback = 1024

    /** True once a delete swipe has taken the field's selection over. */
    private var deleteSwipeActive = false

    /**
     * Which way the live swipe eats: ⌦ grows the selection past the cursor,
     * backspace grows it behind (issue #226).
     *
     * Part of the swipe's state rather than an argument to the commit and
     * cancel calls, because by then the gesture has nothing left to say: both
     * of those only have to undo or keep what [onDeleteSwipeSelect] already
     * put on the screen.
     */
    private var deleteSwipeForward = false

    /** Right edge of the preview: where the selection ended when the swipe began. */
    private var deleteSwipeEnd = -1

    /** Left edge before the swipe grew it — the old selection start, or the caret. */
    private var deleteSwipeBase = -1

    /** Units the preview currently covers, so a repeat of the same step is free. */
    private var deleteSwipeUnits = 0

    /**
     * The text the swipe walks through, read once when it started: behind
     * [deleteSwipeBase] for a backspace swipe, past [deleteSwipeEnd] for a
     * forward one.
     */
    private var deleteSwipeText: CharSequence = ""

    /** How far into [deleteSwipeText] 1, 2, 3... units reach, in UTF-16 units. */
    private val deleteSwipeSteps = ArrayList<Int>()

    /**
     * One step of a delete swipe that deletes as it goes (the preview turned
     * off, or an editor that could not show one), and one tick of a hold that
     * clears words (issue #216).
     */
    fun onDeleteSwipeUnit(byWord: Boolean, forward: Boolean) {
        if (forward) {
            if (byWord) onForwardDeleteWord() else onForwardDelete()
            return
        }
        if (byWord) {
            onDeleteWord()
            return
        }
        // A swipe is not a tap: its first step must delete the character the
        // finger asked for, not spend itself undoing an autocorrect or a
        // glide the way a deliberate backspace press does. The word path
        // drops both for the same reason.
        lastGestureWord = null
        lastRevertible = null
        onDelete()
    }

    /**
     * Selects the [units] units before where the swipe started, previewing
     * what a release would delete. See [DeleteSwipeCallbacks.onSelect] for the
     * return value.
     */
    fun onDeleteSwipeSelect(units: Int, byWord: Boolean, forward: Boolean): Int {
        // A keyboard-owned field with a caret has a selection of its own
        // (#352), so it previews the swipe as the app's field does (#880).
        captureDeleteSwipeSelect(units, byWord, forward)?.let { return it }
        // Nothing to preview against a buffer the keyboard draws itself: it
        // has no selection, so the gesture falls back to deleting as it goes.
        // ⌦ asks its own question, since it stands down in a few places
        // backspace still works in, and works in one (the spelling draft)
        // backspace calls a buffer.
        if (if (forward) forwardDeleteOwnsBuffer() else backspaceEditsBuffer()) return -1
        // A word a composer is still converting (pinyin, Telex, kana) is its
        // keys, not the text on screen, and a selection has to turn it into
        // plain text before it can cover it: what was left of `weishenme`
        // after the swipe was letters no longer read as pinyin (#853). So the
        // swipe deletes as it goes there, through the buffer, as a press does.
        if (!deleteSwipeActive && !forward && composing.isNotEmpty() && _uiState.value.composer.isTransliterating) {
            return -1
        }
        val ic = currentInputConnection ?: return -1
        if (deleteSwipeActive && deleteSwipeForward != forward) resetDeleteSwipe()
        if (!deleteSwipeActive && !beginDeleteSwipe(ic, forward)) return -1
        val covered = minOf(units.coerceAtLeast(0), growDeleteSwipeSteps(units, byWord))
        if (covered == deleteSwipeUnits) return covered
        val length = if (covered <= 0) 0 else deleteSwipeSteps[covered - 1]
        // The swipe only ever moves the edge it eats from; the other one is
        // where the cursor (or the selection that was already there) left it.
        val start = if (forward) deleteSwipeBase else (deleteSwipeBase - length).coerceAtLeast(0)
        val end = if (forward) deleteSwipeEnd + length else deleteSwipeEnd
        ic.setSelection(start, end)
        // Recorded directly for the reason selectWordAtCursor does it: the
        // editor's echo is behind, and until it lands a backspace would go by
        // the stale collapsed caret instead of the range now selected.
        expectedSelStart = start
        expectedSelEnd = end
        deleteSwipeUnits = covered
        return covered
    }

    /**
     * The text of the keyboard-owned field a delete swipe started in, or null
     * while the swipe is in the app's field. See [captureDeleteSwipeSelect].
     */
    private var captureSwipeStart: CaretText? = null

    /**
     * [onDeleteSwipeSelect] for a keyboard-owned field with a caret (#880):
     * the swipe selects what a release would delete, in the field's own
     * selection, and dragging back gives it back. Null when the swipe is not
     * in such a field, or is in a word a composer is still converting, where
     * it deletes as it goes through the buffer like a press.
     */
    private fun captureDeleteSwipeSelect(units: Int, byWord: Boolean, forward: Boolean): Int? {
        val state = _uiState.value
        val target = state.captureTarget() ?: return null
        if (target == CaptureTarget.TYPING_TEST || target == CaptureTarget.WORD_SPELL || !target.movableCaret) return null
        if (captureSwipeStart != null && deleteSwipeForward != forward) {
            captureSwipeStart?.let(::captureCaretTo)
            captureSwipeStart = null
            resetDeleteSwipe()
        }
        val start = captureSwipeStart ?: run {
            val before = state.captureCaretText() ?: return null
            if (composesInCapture(state.composer) && captureCompositionIfLive(state, before) != null) return null
            captureSwipeStart = before
            deleteSwipeBase = before.selectionStart
            deleteSwipeEnd = before.selectionEnd
            deleteSwipeText = if (forward) before.text.substring(deleteSwipeEnd) else before.text.substring(0, deleteSwipeBase)
            deleteSwipeForward = forward
            deleteSwipeSteps.clear()
            deleteSwipeUnits = 0
            deleteSwipeActive = true
            before
        }
        val covered = minOf(units.coerceAtLeast(0), growDeleteSwipeSteps(units, byWord))
        if (covered == deleteSwipeUnits) return covered
        val length = if (covered <= 0) 0 else deleteSwipeSteps[covered - 1]
        val from = if (forward) deleteSwipeBase else (deleteSwipeBase - length).coerceAtLeast(0)
        val to = if (forward) deleteSwipeEnd + length else deleteSwipeEnd
        captureCaretTo(start.selected(from, to))
        deleteSwipeUnits = covered
        return covered
    }

    /** The finger lifted over a preview: delete what it selected. */
    fun onDeleteSwipeCommit() {
        captureSwipeStart?.let { start ->
            captureSwipeStart = null
            val target = _uiState.value.captureTarget()
            val now = _uiState.value.captureCaretText()
            if (target != null && now != null && deleteSwipeUnits > 0 && now.hasSelection) {
                captureWrite(target, now, now.withoutSelection())
            } else {
                captureCaretTo(start)
            }
            resetDeleteSwipe()
            return
        }
        val ic = currentInputConnection
        if (!deleteSwipeActive || ic == null || deleteSwipeUnits <= 0) {
            resetDeleteSwipe()
            return
        }
        val forward = deleteSwipeForward
        // One swipe, one event — however many characters it takes with it.
        // Counted as a backspace only when it was one: a ⌦ swipe eats text the
        // typist has not written yet, which is not what the corrections figure
        // is about.
        if (!forward) {
            recordStat {
                onBackspace(System.currentTimeMillis(), SystemClock.uptimeMillis())
                onWordDeleted()
            }
        }
        clearCaretWord()
        dropComposingForSelectionEdit(ic)
        // The swipe recorded the range it selected (see growDeleteSwipe).
        noteDeletedForLearning(expectedSelStart, expectedSelEnd)
        invalidateExpectedSelection()
        ic.commitText("", 1)
        lastGestureWord = null
        lastRevertible = null
        clearSwapOffer()
        if (forward) {
            // Nothing before the cursor moved, so the bigram context still
            // holds and only the strip's view of the tail changed — the same
            // reasoning [deleteForwardFromField] works by.
            resetDeleteSwipe()
            refreshSuggestions()
            return
        }
        // What was deleted is gone as context; whatever now sits behind the
        // cursor is the real previous word. Same reasoning as [onDeleteWord].
        syncPreviousWordFromField(ic)
        _uiState.update {
            it.copy(suggestions = emptyList(), emojiSuggestions = emptyList(), octopus = emptyMap())
        }
        resetDeleteSwipe()
    }

    /** The swipe ended with nothing selected: put the field back, delete nothing. */
    fun onDeleteSwipeCancel() {
        captureSwipeStart?.let { start ->
            captureSwipeStart = null
            captureCaretTo(start)
            resetDeleteSwipe()
            return
        }
        val ic = currentInputConnection
        if (deleteSwipeActive && ic != null && deleteSwipeUnits > 0) {
            ic.setSelection(deleteSwipeBase, deleteSwipeEnd)
            expectedSelStart = deleteSwipeBase
            expectedSelEnd = deleteSwipeEnd
        }
        resetDeleteSwipe()
    }

    /**
     * Takes the selection over for a new swipe. False when this editor cannot
     * say where its cursor is, which is the one case the preview cannot work
     * in at all.
     */
    private fun beginDeleteSwipe(ic: InputConnection, forward: Boolean): Boolean {
        // A word in progress has to become ordinary text before a selection
        // can cover it: a selection inside a composing region is honored
        // differently by every editor, and the preview has to show exactly
        // what the release will take.
        dropComposingForSelectionEdit(ic)
        // A TYPE_NULL editor answers every read with an empty buffer sitting at
        // offset 0 — convincing enough to pass the checks below, and then every
        // step of the swipe covers nothing. Refusing the preview outright sends
        // the gesture down the delete-as-you-go path, whose key events are the
        // only edits such an editor hears (issue #268).
        if (isNullField()) return false
        val extracted = ic.getExtractedText(ExtractedTextRequest(), 0) ?: return false
        val start = extracted.selectionStart
        val end = extracted.selectionEnd
        if (start < 0 || end < 0) return false
        deleteSwipeBase = extracted.startOffset + minOf(start, end)
        deleteSwipeEnd = extracted.startOffset + maxOf(start, end)
        if (deleteSwipeBase < 0 || deleteSwipeEnd < deleteSwipeBase) return false
        // The text on the side the swipe eats into: before [deleteSwipeBase]
        // going left, past [deleteSwipeEnd] going right. Either call reads from
        // the live selection edge, which is the edge that matters, because
        // nothing has moved the selection yet.
        deleteSwipeText = (
            if (forward) {
                ic.getTextAfterCursor(deleteSwipeLookback, 0)
            } else {
                ic.getTextBeforeCursor(deleteSwipeLookback, 0)
            }
            ) ?: ""
        deleteSwipeForward = forward
        deleteSwipeSteps.clear()
        deleteSwipeUnits = 0
        deleteSwipeActive = true
        return true
    }

    /**
     * Walks another unit back for every one [units] asks for that has not been
     * measured yet, and returns how many are known. Fewer than asked means the
     * swipe has reached the start of what it read.
     */
    private fun growDeleteSwipeSteps(units: Int, byWord: Boolean): Int {
        val text = deleteSwipeText
        while (deleteSwipeSteps.size < units) {
            val taken = deleteSwipeSteps.lastOrNull() ?: 0
            if (taken >= text.length) break
            // What is left to eat, with the part already covered trimmed off
            // the near end — the tail of the text going left, the head of it
            // going right.
            val rest = if (deleteSwipeForward) {
                text.subSequence(taken, text.length)
            } else {
                text.subSequence(0, text.length - taken)
            }
            val step = when {
                deleteSwipeForward && byWord -> WordDelete.lengthAfter(rest, deleteWordBreaks())
                deleteSwipeForward -> Graphemes.firstLength(rest).coerceAtLeast(1)
                byWord -> WordDelete.lengthBefore(rest, deleteWordBreaks())
                else -> charDeleteLength(rest)
            }
            if (step <= 0) break
            deleteSwipeSteps.add(taken + step)
        }
        return deleteSwipeSteps.size
    }

    /**
     * An upward swipe on ⌫ clears the whole field. This selects all of it as
     * the swipe's preview, whatever **Show what you will delete** says, so the
     * lift's [onDeleteSwipeCommit] deletes it and a drag back down's
     * [onDeleteSwipeCancel] puts the old cursor back: a whole message is too
     * much to take on a stray flick with no way to see it coming. False where
     * the field cannot be selected whole (an editor that hands over only part
     * of its text, or a buffer the keyboard draws), and the swipe then does
     * nothing.
     */
    fun onDeleteSwipeSelectAll(): Boolean {
        val state = _uiState.value
        state.captureTarget()?.let { target ->
            if (target == CaptureTarget.TYPING_TEST || target == CaptureTarget.WORD_SPELL || !target.movableCaret) return false
            if (captureSwipeStart != null) return deleteSwipeUnits > 0
            val before = state.captureCaretText() ?: return false
            if (before.text.isEmpty()) return false
            captureSwipeStart = before
            deleteSwipeBase = before.selectionStart
            deleteSwipeEnd = before.selectionEnd
            deleteSwipeUnits = 1
            deleteSwipeActive = true
            captureCaretTo(before.selectedAll())
            return true
        }
        if (backspaceEditsBuffer()) return false
        val ic = currentInputConnection ?: return false
        if (deleteSwipeActive) resetDeleteSwipe()
        if (!beginDeleteSwipe(ic, forward = false)) return false
        // Read after beginDeleteSwipe has turned any composing word into
        // plain text. Only an editor that hands over everything from offset 0
        // can be selected whole; a window of a longer field would leave the
        // rest behind and call the field cleared.
        val text = runCatching { ic.getExtractedText(ExtractedTextRequest(), 0) }.getOrNull()
            ?.takeIf { it.startOffset == 0 }?.text
        if (text.isNullOrEmpty()) {
            resetDeleteSwipe()
            return false
        }
        ic.setSelection(0, text.length)
        expectedSelStart = 0
        expectedSelEnd = text.length
        deleteSwipeUnits = 1
        return true
    }

    /** Forgets a swipe, without touching the field. */
    private fun resetDeleteSwipe() {
        deleteSwipeActive = false
        deleteSwipeUnits = 0
        deleteSwipeBase = -1
        deleteSwipeEnd = -1
        deleteSwipeForward = false
        deleteSwipeText = ""
        deleteSwipeSteps.clear()
    }

    private fun onSpace() {
        glueNextWord = false
        setNoSpaceArmed(false)
        // Ahead of the input-connection check: every keyboard-owned field must
        // take a space — or spend the press — even in a window that has no
        // editor focused at all. A typing test scores space as the word
        // separator, an instruction or a query takes it at its caret, and the
        // fields a space means nothing in eat the press rather than letting it
        // reach the app behind the keyboard.
        if (captureSpace()) return
        val ic = currentInputConnection ?: return
        val state = _uiState.value
        val now = System.currentTimeMillis()
        // One-shot, spent by this press whatever it ends up doing.
        val followsPunctuationSpace = pendingPunctuationSpace
        pendingPunctuationSpace = false
        val followsWordSpace = pendingWordSpace
        pendingWordSpace = false
        // Same as a typed character: the mid-word strip described the field
        // before this press.
        clearCaretWord()

        // On a Cheonjiin pad a space straight after a consonant tap says "next
        // letter", not "next word": ㄱ ㄱ is ㅋ, so ㄱ, space, ㄱ is how 먹고 is
        // spelled (discussion #372). The press only closes the run; the next one
        // is a real space, and so is one after the run has timed out.
        val closesMultitap = composing.isNotEmpty() && state.composer.spaceEndsMultitap &&
            multitap.isLive(SystemClock.uptimeMillis())
        multitap.end()
        if (closesMultitap) return

        // Space over a selection replaces it; skip autocorrect/double-space.
        if (hasSelection(ic)) {
            // A browser's address bar shows its inline completion as a
            // selection after the caret, so a trigger typed there always
            // arrives with one. The expansion replaces it the way the space
            // would have.
            if (tryUncomposedTrigger(ic, state, endedBySpace = true)) {
                if (swallowTerminatorAfterCommit) {
                    swallowTerminatorAfterCommit = false
                } else {
                    ic.commitText(spaceText(state), 1)
                }
                lastSpaceTime = 0
                return
            }
            dropComposingForSelectionEdit(ic)
            invalidateExpectedSelection()
            ic.commitText(spaceText(state), 1)
            recordStat { onSeparator(now, SystemClock.uptimeMillis()) }
            lastSpaceTime = 0
            maybeAutoCapitalize()
            return
        }

        // The space after "hello," was typed a keystroke ago by the auto-space
        // rule. Habit still reaches for the spacebar, and obeying it here would
        // give "hello,  world" — so the press is spent confirming the space
        // that is already there. Pressing space again inserts a real one, since
        // the one-shot is gone by then.
        if (followsPunctuationSpace) {
            val before = ic.getTextBeforeCursor(2, 0)?.toString().orEmpty()
            if (before.length == 2 && before[1] == ' ' && isAutoSpacedMark(before[0])) {
                lastSpaceTime = now
                maybeAutoCapitalize()
                return
            }
        }

        // Same story for the space a glide typed: the finger lifts and the
        // thumb reaches for the spacebar out of habit. Spending the press on
        // the space already there keeps [lastSpaceTime] armed, so a second
        // press still turns it into ". " the way it would after typing.
        if (followsWordSpace) {
            val before = ic.getTextBeforeCursor(2, 0)?.toString().orEmpty()
            if (before.length == 2 && before[1] == ' ' && !before[0].isWhitespace()) {
                lastSpaceTime = now
                maybeAutoCapitalize()
                // The press also settles the word behind that space, the way a
                // space settles a typed one: a swipe's alternates stop being the
                // answer and the strip moves on to what comes next. Nothing is
                // committed here, so no selection update arrives to re-derive
                // any of it — without this the alternates stayed up and the
                // next-word predictions only appeared on a second press (#35).
                // The context is re-read from the field because a swipe commits
                // without going through the paths that keep [previousWord]
                // current.
                lastGestureWord = null
                syncPreviousWordFromField(ic)
                refreshSuggestions()
                return
            }
        }

        if (runKeymanFrameKey(VK_SPACE)) {
            lastSpaceTime = now
            return
        }

        // Conversion IME (Pinyin, Japanese): space commits the top candidate for
        // the leading syllable(s) and re-converts the tail — no trailing literal
        // space (CJK runs words together). An empty buffer falls through to a
        // plain space.
        if (composing.isNotEmpty() && state.composer.isConversion) {
            // The stepping space bar of Japanese IMEs (#419): the first press
            // highlights the top candidate, each one after moves on, and Enter
            // types it. With nothing ranked yet there is nothing to step
            // through, so the press converts as it always has.
            if (spaceStepsCandidates(state) && state.suggestions.isNotEmpty()) {
                val size = state.suggestions.size
                _uiState.update { it.copy(candidateCursor = (it.candidateCursor + 1).mod(size)) }
                lastSpaceTime = now
                return
            }
            // The arrow keys moved off the first candidate: that is the pick.
            if (commitHighlightedCandidate()) {
                lastSpaceTime = now
                return
            }
            val buf = composing.toString()
            val top = state.composer.candidates(buf).firstOrNull()
            if (top != null) {
                commitConversionPrefix(ic, top, index = 0)
            } else {
                commitConversionPrefix(ic, state.composer.composeBuffer(buf))
            }
            lastSpaceTime = now
            return
        }

        // The word and the space that ends it are one edit as far as the app is
        // concerned: batching them means one selection update instead of two,
        // which is what keeps the backspace-to-revert window armed (see
        // [revertArmedAt]) and stops the corrected word flashing on its own for
        // a frame. Only the composing paths below can have started a batch —
        // every early return past this point runs with an empty buffer.
        val batched = composing.isNotEmpty()
        if (batched) ic.beginBatchEdit()
        // A word the caret only landed on and nobody typed into is not a word
        // being ended: the space press there is the user making room for a new
        // word, and stepping over the gap ahead would glue that word to the next.
        val typedWord = composing.isNotEmpty() && composing.toString() != resumedWord
        val committed = commitComposing(
            ic,
            autocorrect = state.settings.correction.enabledFor(state.language.id),
            fixApostrophes = state.settings.autoText.apostrophe,
            expandPatterns = true,
        ) || tryUncomposedTrigger(ic, state, endedBySpace = true)
        if (!committed) noteUncomposedRecentWord(ic, state)
        // The expansion left the caret inside itself, at its {cursor} marker.
        // A space committed there lands in the middle of the text the snippet
        // inserted, so this press is spent on the expansion instead.
        if (swallowTerminatorAfterCommit) {
            swallowTerminatorAfterCommit = false
            if (batched) ic.endBatchEdit()
            lastSpaceTime = now
            return
        }

        // How close together the two spaces have to be. One number for both
        // rules below, so the tab and the full stop never disagree about what
        // counts as a double space.
        val doubleSpaceWindow = state.settings.textEditing.doubleSpaceWindowMs
        // Double-tap space inserts a tab. Checked before the period rule so
        // enabling it wins, and unlike the period it works anywhere a space
        // was just typed (indenting at a line start has no word before it).
        if (!committed && state.settings.autoText.doubleSpaceTab && now - lastSpaceTime < doubleSpaceWindow) {
            val before = ic.getTextBeforeCursor(1, 0)?.toString().orEmpty()
            if (before == " ") {
                ic.deleteSurroundingText(1, 0)
                ic.commitText("\t", 1)
                lastSpaceTime = 0
                return
            }
        }

        // Double-space inserts ". "
        // Only in plain text fields: a double space in an email, URI or
        // number box must stay two spaces, not become ". ".
        if (!committed && state.settings.autoText.doubleSpacePeriod &&
            state.fieldKind == FieldKind.TEXT && now - lastSpaceTime < doubleSpaceWindow
        ) {
            val before = ic.getTextBeforeCursor(2, 0)?.toString().orEmpty()
            if (before.endsWith(" ") && before.length == 2 && !before[0].isWhitespace()) {
                ic.deleteSurroundingText(1, 0)
                ic.commitText(". ", 1)
                lastSpaceTime = 0
                // Arm the shift-to-cancel: a shift press now drops this space.
                pendingAutoSpace = true
                armRevertGuard()
                maybeAutoCapitalize()
                return
            }
        }
        // A word being followed in the field ends at this space when the caret
        // is at its end, and gains the space when it is inside it.
        val space = spaceText(state)
        // A word typed into the middle of a sentence ends in front of the space
        // that was already there, and the press steps over it rather than
        // doubling it: "auto ⌶ space", type "added" and a space, and the field
        // reads "auto added ⌶space" with the caret at the next word (#508,
        // #662). The pick from the strip has done the same since #508.
        if (!(typedWord && committed && stepOverFollowingSpace(ic))) {
            mirrorTypedIntoRevision(ic, space)
            ic.commitText(space, 1)
        }
        // The one plain-space landing: the confirm-a-space-already-there and
        // double-space returns above add no character worth counting.
        recordStat { onSeparator(now, SystemClock.uptimeMillis()) }
        if (batched) ic.endBatchEdit()
        lastSpaceTime = now
        // Only for a real space: the ideographic one is a character
        // [isComposingWordChar] may not treat as a break.
        ownSpaceEchoPending = space == " "
        // "word " just went in, and the commit knows where it ended: the caps
        // mode there needs no read, here or in the echo that follows.
        val wordEnd = if (committed && space == " ") plainCommitEnd else -1
        ownSpaceCaret = if (wordEnd >= 0) wordEnd + 1 else -1
        if (ownSpaceCaret >= 0) {
            ownSpaceCaps = capsAfterWordAndSpace()
            maybeAutoCapitalize(knownCaps = ownSpaceCaps)
        } else {
            maybeAutoCapitalize()
        }
        // Next-word predictions (learned bigrams, including word → emoji)
        // appear once the word is committed.
        refreshSuggestions()
    }

    /**
     * What the space bar types in [state]'s language: the ideographic space
     * U+3000 where the user asked for full-width spaces (#341), otherwise an
     * ASCII one.
     *
     * Only the two landings that put a space into the text ask this. The
     * confirm-a-space-already-there paths and the double-space rules keep
     * testing for the ASCII space, and that is what they should do: both are
     * habits of Latin typing, and a full-width space after a word is not a
     * space an auto-space rule typed.
     */
    private fun spaceText(state: KeyboardUiState): String =
        if (state.language.id in state.settings.cjk.fullWidthSpaceLanguages) IDEOGRAPHIC_SPACE else " "

    /**
     * [hardwareShift] is the physical keyboard's own shift, read from the key
     * event's meta state. Null for a tap on the on-screen Enter, which asks the
     * ui state instead. They are deliberately separate: a physical shift is
     * held, not latched, so it never appears in [KeyboardUiState.shiftState].
     *
     * [ignoreShift] leaves Shift+Enter's override out entirely, for the one
     * caller that exists to get past it ([onEditorAction]).
     *
     * [heldShift] is the on-screen shift held down under the Enter tap, or
     * dragged onto it, rather than latched by a tap. Like the physical one it
     * never reaches [KeyboardUiState.shiftState], so it is passed in.
     */
    private fun onEnter(
        hardwareShift: Boolean? = null,
        ignoreShift: Boolean = false,
        heldShift: Boolean = false,
    ) {
        val state = _uiState.value
        glueNextWord = false
        setNoSpaceArmed(false)
        // Enter belongs to whichever keyboard-owned field has the keys, and
        // never to the app behind the panel.
        if (captureEnter()) return
        val ic = currentInputConnection ?: return
        // A conversion reading still waiting: Enter confirms it as typed, and
        // that is all it does — the hiragana or the letters, no candidate, no
        // newline, no send (#514, #515). Space and a tapped candidate convert.
        // Unless a candidate has been highlighted with the arrow keys or a
        // stepping space bar, in which case Enter is what picks it (#419).
        if (composing.isNotEmpty() && state.composer.isConversion) {
            if (!commitHighlightedCandidate()) commitConversionAsTyped(ic)
            return
        }
        // Whether this ends up a newline or an editor action, it ends the
        // word the same way a space does, autocorrect included. A word ended
        // by Enter was typed exactly like one ended by space, and committing
        // it as typed sent `juz` where the strip already showed `już` (#200).
        // Unless the user asked Enter to leave the word alone (#457): a query
        // sent with Enter is sent before the correction can be read.
        recordStat { onSeparator(System.currentTimeMillis(), SystemClock.uptimeMillis()) }
        commitComposing(
            ic,
            autocorrect = state.settings.correction.enabledFor(state.language.id) &&
                state.settings.correction.onEnter,
            fixApostrophes = state.settings.autoText.apostrophe,
            expandPatterns = true,
        ) || tryUncomposedTrigger(ic, state)
        // The word is over, however this key ends up reaching the field. What
        // follows hands the field to the app, so the caret update that comes
        // back must not re-compose the word this just finished (#236).
        wordEndedByEnter = true
        // Same as the spacebar: a newline typed at a caret parked inside an
        // expansion would break the text the snippet just inserted.
        if (swallowTerminatorAfterCommit) {
            swallowTerminatorAfterCommit = false
            return
        }
        // Shift held over Enter overrides the field's action: in a chat app the
        // box declares Send, so this is the only way to put a line break in a
        // message without sending it. The key draws the newline glyph while the
        // override is live (see enterActionFor), so it still does what it shows.
        val shifted = !ignoreShift && (hardwareShift ?: (heldShift || state.softShiftForcesNewline))
        val forceNewline = shifted && state.settings.layoutBehavior.shiftEnterNewline
        // Same decoder that labels the key, so Enter always does what the
        // key is drawing — including an app's own actionId behind a custom
        // actionLabel. Null means "no action": type a real newline.
        val fieldAction = appEnterAction ?: currentInputEditorInfo.editorActionId()
        val action = if (forceNewline) null else fieldAction
        // A line break on a list line carries the list on (#694); on an empty
        // item it ends the list, and that is all this Enter does.
        val listStep = if (action == null) listStepAtCaret(ic, state) else null
        if (listStep is ListContinuation.Step.End) {
            ic.deleteSurroundingText(listStep.length, 0)
            maybeAutoCapitalize()
            return
        }
        val listMarker = (listStep as? ListContinuation.Step.Continue)?.marker
        // A line break starts the next line afresh: the word before it is not
        // the context of the first one after it (#889), as a full stop's is not.
        if (action == null) {
            previousWord = WordContext.SENTENCE_START
            previousWord2 = null
            previousWord3 = null
        }
        if (action != null) {
            ic.performEditorAction(action)
            // The action is the app's to answer, and a message box answers it by
            // emptying itself. Neither the cached caret nor the words the
            // pattern gate remembers survive that, and an app that empties the
            // field without reporting it would otherwise have the keyboard's own
            // stale idea of the text used against it (#236).
            invalidateExpectedSelection()
            invalidateRecentWords()
        } else if (forceNewline && fieldAction != null) {
            // Committed rather than sent as a key event, which is what the
            // override needs and what a plain newline does not. A field that
            // declares an action is a single-line TextView, and TextView answers
            // KEYCODE_ENTER on one of those by firing the editor action — so the
            // raw event sent the WhatsApp message the override had just decided
            // not to send. commitText has nothing to intercept it.
            typeNewline(ic)
            listMarker?.let { ic.commitText(it, 1) }
            // The shift deliberately survives, unlike the letter case that
            // spends it: it is being held down as a modifier for as long as the
            // user wants line breaks, so a second Enter must break the line too
            // rather than sending the half-written message. It drops the way it
            // always does — the next letter spends it, or a second shift tap
            // puts it down. maybeAutoCapitalize only arms an OFF shift, so it
            // leaves this one alone.
            maybeAutoCapitalize()
        } else if (hardwareShift == null && currentInputEditorInfo.refusesEnterKeyEvent()) {
            // A multi-line box that also flew IME_FLAG_NO_ENTER_ACTION: it
            // asked for a line break in as many words as EditorInfo has, so
            // the break is committed rather than sent as a key event. Discord's
            // message box is one (#214), and its edit text — React Native's —
            // submits on a KEYCODE_ENTER it sees, which sent the message the
            // flag had just said not to send.
            //
            // Soft presses only (hardwareShift is null for one). A physical
            // Enter *is* a key event, and an app that reads one as "send" while
            // the on-screen key breaks the line — which is what Discord and
            // every desktop chat client do — is entitled to keep telling them
            // apart.
            typeNewline(ic)
            listMarker?.let { ic.commitText(it, 1) }
            maybeAutoCapitalize()
        } else {
            // No action declared at all: a genuinely multi-line field, a web
            // page, a terminal. These want the key event — a committed "\n"
            // reaches a page behind keyCode 229 with no Enter for its handlers
            // to see, which is the mirror image of the digit case above.
            //
            // A user's shift rides along on it. Google Docs, Word and every
            // contenteditable page read Shift+Enter as a line break inside the
            // paragraph and a bare Enter as a new paragraph, and a committed
            // "\n" is the bare one to all of them. A plain multi-line EditText
            // types the same newline either way.
            if (shifted) {
                sendShiftedEnter(ic)
            } else {
                ic.sendKeyEvent(KeyEvent(KeyEvent.ACTION_DOWN, KeyEvent.KEYCODE_ENTER))
                ic.sendKeyEvent(KeyEvent(KeyEvent.ACTION_UP, KeyEvent.KEYCODE_ENTER))
            }
            listMarker?.let { ic.commitText(it, 1) }
            maybeAutoCapitalize()
        }
        if (action == null) showSentenceOpeners()
    }

    /**
     * The strip after a sentence end or a line break, published as openers so
     * it rests behind the toolbar (#889, #911). The word committed in front of
     * the mark had already refilled the strip with words to follow *it*, and
     * nothing refreshed it after the mark: whether the toolbar came up was
     * left to whichever selection echo happened to rebuild the strip.
     */
    private fun showSentenceOpeners() {
        if (composing.isNotEmpty() || previousWord != WordContext.SENTENCE_START) return
        val (words, emojis) = nextWordStrip()
        _uiState.update {
            it.copy(suggestions = words, emojiSuggestions = emojis, sentenceOpeners = words, autocorrectWord = null)
        }
    }

    /**
     * What Enter does to the list on the caret's line ([ListContinuation]),
     * when "Continue lists" is on and the field is plain text. Null with a
     * selection, which Enter replaces, and on a line longer than the
     * look-back, whose start this cannot see.
     */
    private fun listStepAtCaret(ic: InputConnection, state: KeyboardUiState): ListContinuation.Step? {
        if (!state.settings.autoText.continueLists) return null
        if (state.secureField || state.nullField || state.fieldKind != FieldKind.TEXT) return null
        if (!ic.getSelectedText(0).isNullOrEmpty()) return null
        val before = ic.getTextBeforeCursor(LIST_LINE_LOOKBACK, 0)?.toString() ?: return null
        val lineStart = before.lastIndexOf('\n')
        if (lineStart < 0 && before.length >= LIST_LINE_LOOKBACK) return null
        val after = ic.getTextAfterCursor(LIST_LINE_LOOKBACK, 0)?.toString().orEmpty()
        return ListContinuation.onEnter(before.substring(lineStart + 1), after.substringBefore('\n'))
    }

    /**
     * Shift+Enter as a hardware keyboard sends it: shift down, Enter down and
     * up with the shift mask on both, shift up. Editors that tell a line break
     * from a paragraph break read the mask; some only track the shift key's
     * own down and up, so both are sent.
     */
    private fun sendShiftedEnter(ic: InputConnection) {
        val meta = KeyEvent.META_SHIFT_ON or KeyEvent.META_SHIFT_LEFT_ON
        val time = SystemClock.uptimeMillis()
        ic.sendKeyEvent(shortcutEvent(time, KeyEvent.ACTION_DOWN, KeyEvent.KEYCODE_SHIFT_LEFT, meta))
        ic.sendKeyEvent(shortcutEvent(time, KeyEvent.ACTION_DOWN, KeyEvent.KEYCODE_ENTER, meta))
        ic.sendKeyEvent(shortcutEvent(time, KeyEvent.ACTION_UP, KeyEvent.KEYCODE_ENTER, meta))
        ic.sendKeyEvent(shortcutEvent(time, KeyEvent.ACTION_UP, KeyEvent.KEYCODE_SHIFT_LEFT, 0))
    }

    /**
     * Puts a line break in the field without going near the editor action, for
     * the two paths that mean it: Shift+Enter's override and a [KeyAction.Newline]
     * key (which is what the enter key's long-press alternate is).
     *
     * See [KeyAction.Newline] for why this is a commit and not a key event.
     */
    private fun typeNewline(ic: InputConnection) {
        ic.commitText("\n", 1)
    }

    /**
     * A key — in practice the enter key's long-press alternate — that types a
     * line break whatever the field declares.
     *
     * Ends the word the same way [onEnter] does, because it is the same
     * character landing: the composing buffer flushes first, and a snippet
     * expansion that has parked the caret inside itself swallows the break
     * rather than breaking the text it just inserted.
     */
    /**
     * [KeyAction.EditorAction]: Enter as if no shift were up, which is the
     * enter key's hold while Shift+Enter's override has the key.
     *
     * The shift the user put up to break lines goes down with it. It was held
     * for the length of the message, and the message is gone: kept, it would
     * turn the next Enter in the emptied box into a line break too.
     */
    private fun onEditorAction() {
        val shiftForNewlines = _uiState.value.softShiftForcesNewline
        onEnter(ignoreShift = true)
        if (shiftForNewlines) consumeShift()
    }

    private fun onNewline() {
        val ic = currentInputConnection ?: return
        recordStat { onSeparator(System.currentTimeMillis(), SystemClock.uptimeMillis()) }
        val state = _uiState.value
        val settings = state.settings
        commitComposing(
            ic,
            autocorrect = settings.correction.enabledFor(state.language.id) && settings.correction.onEnter,
            fixApostrophes = settings.autoText.apostrophe,
            expandPatterns = true,
        )
        // Same as [onEnter]: the break ends the word, so the caret update it
        // causes must not re-arm it as composing (#236).
        wordEndedByEnter = true
        if (swallowTerminatorAfterCommit) {
            swallowTerminatorAfterCommit = false
            return
        }
        typeNewline(ic)
        maybeAutoCapitalize()
    }

    private fun toggleSymbols() {
        // Leaving the letter layer ends the on-keyboard writing surface, and
        // the shift the user locked over the letters (#613).
        if (_uiState.value.layoutMode == LayoutMode.LETTERS) {
            dropKeyboardHandwritingInk()
            releaseUserShift()
        }
        _uiState.update {
            it.copy(
                layoutMode = when (it.layoutMode) {
                    LayoutMode.LETTERS -> LayoutMode.SYMBOLS
                    LayoutMode.SYMBOLS -> LayoutMode.SYMBOLS_SHIFTED
                    LayoutMode.SYMBOLS_SHIFTED -> LayoutMode.SYMBOLS
                    // ?123 from the Fn layer leaves it, lock and all: the user
                    // asked for a different grid, not for Fn to persist under it.
                    LayoutMode.FN -> LayoutMode.SYMBOLS
                    // Same from a secondary layout: its ?123 key is a way out.
                    LayoutMode.SECONDARY -> LayoutMode.SYMBOLS
                    // And from a Keyman layer, whose ?123 key leaves it too.
                    LayoutMode.NAMED -> LayoutMode.SYMBOLS
                },
                fnLocked = false,
                fnReturn = null,
            )
        }
    }

    /**
     * Shows a secondary layout (issue #62) — or, when it is the one already
     * showing, goes back to the letters, so the key that opened it is also the
     * key that closes it. A key naming a layout this state cannot show (deleted,
     * or no longer secondary) does nothing rather than switching to something
     * arbitrary, the same dead-key outcome a tool key for a missing tool gets.
     */
    private fun openSecondaryLayout(id: String) {
        val state = _uiState.value
        if (id !in state.layouts.secondaries) return
        if (state.layoutMode == LayoutMode.SECONDARY && state.secondaryLayoutId == id) {
            closeSecondaryLayout()
            return
        }
        // Leaving the letter layer ends the on-keyboard writing surface.
        if (state.layoutMode == LayoutMode.LETTERS) dropKeyboardHandwritingInk()
        _uiState.update {
            it.copy(
                layoutMode = LayoutMode.SECONDARY,
                secondaryLayoutId = id,
                fnLocked = false,
                fnReturn = null,
                // The picker's job is done the moment it has picked.
                panel = if (it.panel == PanelMode.CUSTOM_LAYOUTS) PanelMode.NONE else it.panel,
            )
        }
    }

    private fun closeSecondaryLayout() {
        _uiState.update {
            it.copy(layoutMode = LayoutMode.LETTERS, fnLocked = false, fnReturn = null)
        }
    }

    /**
     * Shows one of the active layout's own extra grids — a page of a paginated
     * layout (issue #498) — by its key in the layout's layers.
     *
     * Not a toggle, unlike [openSecondaryLayout]: a `2/4` key means "page
     * three", and the page it lands on carries its own key onward. The letters
     * layer, and a name this layout does not define, both land on the letters,
     * so a page key that outlived its page cannot strand the user on a grid
     * with no way back.
     *
     * [switchToKeymanLayer] is the rules engine's version of this and stays
     * separate: that one also has to read `shift` and `caps` as our shift state
     * rather than as places, which is a Keyman rule and not something a page key
     * should inherit.
     */
    private fun openNamedLayer(name: String) {
        val state = _uiState.value
        val known = name in state.layouts.named
        // Leaving the letter layer ends the on-keyboard writing surface.
        if (state.layoutMode == LayoutMode.LETTERS) dropKeyboardHandwritingInk()
        _uiState.update {
            if (known) {
                it.copy(layoutMode = LayoutMode.NAMED, namedLayer = name, fnLocked = false, fnReturn = null)
            } else {
                it.copy(layoutMode = LayoutMode.LETTERS, namedLayer = null, fnLocked = false, fnReturn = null)
            }
        }
    }

    /**
     * Whether the panel on screen is a panel layout whose grid asked to stay
     * open across a change of field (issue #60). Only the panels that
     * *are* layouts can; every other panel is chrome the field owns.
     */
    private fun panelLayoutPersists(state: KeyboardUiState): Boolean {
        val kind = state.panel.layoutKind ?: return false
        return state.panelLayout(kind).grid.persistent
    }

    /** Where the user was when the keyboard last went away — see the class. */
    private val persistentSurface by lazy { PersistentSurfacePrefs(this) }

    /** Whether [restorePersistentSurface] has already been asked for, this process. */
    private var persistentSurfaceRestored = false

    /**
     * Puts back the panel or key layer the keyboard was showing when it last
     * left the screen, for a grid whose author switched "Keep this layer open"
     * on (issue #60). Runs once per process, on the first field to show the
     * view, and only once the stored settings have landed.
     *
     * The flag is re-read off the layouts as they are *now* rather than trusted
     * from the recording: a switch turned off in the editor since, a layout
     * deleted, a secondary grid renamed — none of them may resurrect a layer.
     * That check is the same one the change-of-field path makes, run against a
     * candidate state rather than the live one.
     */
    private fun restorePersistentSurface() {
        val panelName = persistentSurface.panel
        val layerName = persistentSurface.layer
        if (panelName == null && layerName == null) return
        _uiState.update { state ->
            val panel = PanelMode.entries.firstOrNull { it.name == panelName }
                ?.takeIf { mode ->
                    mode.layoutKind?.let { state.panelLayout(it).grid.persistent } == true
                }
            val layered = LayoutMode.entries.firstOrNull { it.name == layerName }
                ?.let { mode ->
                    state.copy(
                        layoutMode = mode,
                        secondaryLayoutId = if (mode == LayoutMode.SECONDARY) {
                            persistentSurface.secondaryLayoutId ?: state.secondaryLayoutId
                        } else {
                            state.secondaryLayoutId
                        },
                    )
                }
                ?.takeIf { currentLayout(it).persistent }
            val restored = layered ?: state
            if (panel != null) restored.copy(panel = panel) else restored
        }
    }

    /**
     * The Secondary layout tool. A secondary layout up, however it got there, is
     * taken down: the tool is lit whenever one is showing, and a lit toggle has
     * to be the way down. Otherwise it shows the layout pinned on the tool's
     * page, or the only one there is — and with several and nothing pinned it
     * opens a picker of them (issue #62's follow-up: one tool tied to one grid
     * meant re-pinning the tool for every other grid).
     */
    private fun onCustomLayoutToggle() {
        val state = _uiState.value
        val grids = state.layouts.secondaries
        if (grids.isEmpty()) return
        if (state.layoutMode == LayoutMode.SECONDARY) {
            vibrate()
            closeSecondaryLayout()
            return
        }
        val pinned = state.settings.layoutBehavior.customLayoutToolId?.takeIf { it in grids }
        val id = pinned ?: grids.keys.singleOrNull()
        if (id != null) {
            vibrate()
            openSecondaryLayout(id)
        } else {
            onPanelChange(PanelMode.CUSTOM_LAYOUTS)
        }
    }

    /**
     * The user's secondary layouts, compiled, cached against the identity of
     * the custom-layout list: the settings object holds one instance until a
     * layout changes, so this is a map lookup on the hot path and a rebuild of
     * a handful of grids when the editor saves.
     */
    private fun secondaryGrids(customs: List<LayoutSpec>): Map<String, KeyboardLayout> {
        secondaryGridCache?.let { (cached, grids) -> if (cached === customs) return grids }
        val grids = compileSecondaryGrids(customs)
        secondaryGridCache = customs to grids
        return grids
    }

    private var secondaryGridCache: Pair<List<LayoutSpec>, Map<String, KeyboardLayout>>? = null

    /**
     * The grids reachable from the focused field, compiled once here rather than
     * per recomposition.
     *
     * Resolution lives in the service because it is the side that owns the
     * layout store, and because [keyRowsHeight] has to be a pure function of
     * state: the reserved row span is the maximum over *every* reachable layer,
     * which the rendering code — looking at one layer at a time — could never
     * compute for itself.
     *
     * The result is memoised so the returned instance is reference-stable.
     * [KeyboardUiState]'s generated `equals` walks its fields, so handing out a
     * fresh set per emission would make every state comparison walk every key.
     */
    /**
     * The layout being typed on: the field's override if it asked for one,
     * otherwise the user's choice. Resolved rather than raw, so an id whose
     * layout was deleted heals to the default instead of selecting nothing.
     */
    private fun activeLayoutSpec(settings: KeyboardSettings): LayoutSpec =
        resolveLayout(settings.customLayouts, fieldLayoutOverride ?: baseLayoutId(settings))

    /**
     * Resolves the bound layout's composer again after a [ConversionEngines]
     * change. Skipped while a reading is composing: the buffer belongs to the
     * composer that took it, and the next field or settings emission resolves
     * again anyway.
     */
    private fun reresolveComposer() {
        if (composing.isNotEmpty()) return
        val state = _uiState.value
        val composer = resolveLayout(state.settings.customLayouts, state.layoutId).resolvedComposer()
        if (composer !== state.composer) _uiState.update { it.copy(composer = composer) }
    }

    /**
     * The layout to type on before any field override: the one remembered for the
     * focused app when per-app memory is on, otherwise the global choice. A
     * remembered id whose layout has since been deleted heals back to the global
     * pick rather than snapping to the default.
     *
     * An explicit pick that has not been persisted yet ([pendingLayoutId]) wins
     * over the stored one, and clears itself the moment the store catches up.
     */
    private fun baseLayoutId(settings: KeyboardSettings): String {
        val stored = storedLayoutId(settings)
        val pending = pendingLayoutId ?: return stored
        if (stored == pending) {
            pendingLayoutId = null
            return stored
        }
        return pending
    }

    /**
     * [baseLayoutId] as the settings alone see it, before any pending pick.
     *
     * A remembered id has to still be one of the enabled layouts, not merely
     * exist: built-ins never stop existing, so an app last typed in English
     * kept reopening on English after English was removed from the list (#783).
     */
    private fun storedLayoutId(settings: KeyboardSettings): String {
        if (!settings.perAppLanguage.enabled) return settings.activeLayoutId
        val remembered = settings.perAppLanguage.layoutByPackage[currentPackage]
            ?.takeIf { id -> id in settings.enabledLayoutIds }
            ?.takeIf { id -> resolveLayout(settings.customLayouts, id).id == id }
        return remembered ?: settings.activeLayoutId
    }

    /**
     * The layout [onLayoutSelected] has just moved to, held until the settings
     * flow reports it back.
     *
     * The settings collector re-derives the active layout from the stored ids on
     * *every* emission, and the writes behind a pick are asynchronous — so any
     * other settings write racing one lands with the new layout on screen but the
     * old id still in the store, and the collector snaps the keyboard back to the
     * old layout for a frame.
     *
     * The Fancy tool does exactly that: it enables the fancy layout (one write)
     * and then selects it (another). The first write's emission rolled the pick
     * back, so the fancy style strip appeared, vanished for a frame and came back
     * — a 40dp row flickering in and out, taking the whole keyboard's height with
     * it. Holding the pick here until it is stored keeps the two writes looking
     * like the one action they are.
     */
    private var pendingLayoutId: String? = null

    /**
     * The grids the keyboard draws for [spec], repaired.
     *
     * Repaired *here* because this is the last gate before a layout becomes the
     * thing you type on, and it is the only one that catches an edit made after
     * the layout was turned on. `setActiveLayoutId` repairs what it stores, but
     * the editor saves on every keystroke — deliberately, so it does not fight
     * you — and nothing re-checked an already-enabled layout afterwards. Delete
     * the row that carries ⌫ from a layout that is on and the live keyboard lost
     * its backspace, which is the one outcome the repair pass exists to prevent.
     * The editor still reads the layout unrepaired, so the grid it shows is what
     * the user is building.
     *
     * Cached against the spec rather than its id alone: keyed on the id, an edit
     * never reached a keyboard whose process was still alive, so the grid stayed
     * at whatever it was when the layout was first drawn. Structural equality
     * short-circuits on identity, and the settings flow hands back the same
     * instance until something actually changes.
     */
    private fun resolveLayoutSet(
        spec: LayoutSpec,
        fieldKind: FieldKind,
        form: DeviceForm,
        numberRowShown: Boolean,
        customs: List<LayoutSpec>,
    ): LayoutSet {
        val key = LayoutSetKey(spec.id, fieldKind, form, numberRowShown)
        // The secondary grids ride along by reference, so an edit to one of
        // them — which re-decodes the custom list — misses the cache too.
        val secondaries = secondaryGrids(customs)
        layoutSetCache[key]?.let { (cached, set) ->
            if (cached == spec && set.secondaries === secondaries) return set
        }
        val set = compileLayoutSet(spec, fieldKind, form, numberRowShown, secondaries, television)
        layoutSetCache[key] = spec to set
        return set
    }

    /**
     * What a cached [LayoutSet] was resolved *for*.
     *
     * The screen form and the digit-row setting are part of the key, not just the
     * id and the field: both reshape the grid, and keyed without them an unfold
     * would keep serving the phone layout for as long as the process lived —
     * a bug that survives a green test run because nothing else re-resolves.
     */
    private data class LayoutSetKey(
        val layoutId: String,
        val fieldKind: FieldKind,
        val form: DeviceForm,
        val numberRowShown: Boolean,
    )

    private val layoutSetCache = HashMap<LayoutSetKey, Pair<LayoutSpec, LayoutSet>>()

    private fun switchLanguage() {
        val state = _uiState.value
        if (state.settings.globeRecentOrder) {
            switchLanguageRecent(hardware = false)
            return
        }
        // Cycles layout ids, not modes: three custom layouts all based on
        // English are three distinct stops, where cycling modes would collapse
        // them into one and make them unreachable from the keyboard.
        val ids = state.settings.switchLayoutIds()
        onLayoutSelected(ids[(ids.indexOf(state.layoutId) + 1).mod(ids.size)])
    }

    /**
     * Opens the system's keyboard picker, the "Choose input method" list that
     * holds every keyboard turned on for the device. Reached from a key bound
     * to [KeyAction.InputMethodPicker] and from the last row of the language
     * list.
     *
     * The buffer is committed first. The picker hands the field to another
     * keyboard, and text left composing at that moment belongs to a keyboard
     * that is about to stop owning the input connection, which is how a
     * half-typed word disappears on the switch.
     *
     * The platform only grants this to the keyboard that owns the current input
     * connection, which is exactly what we are, so unlike the crash screen's
     * copy of this there is no dance to work out whether it appeared. It is
     * still wrapped: an OEM build that refuses outright must not take the
     * keyboard down with it, and the input-method settings screen reaches the
     * same place in two more presses.
     */
    /**
     * Switches straight to the keyboard whose input-method id is [id] (issue
     * #354), committing the buffer first for the reason [showInputMethodPicker]
     * gives.
     *
     * Anything that stops the switch — a blank id, a keyboard that has since
     * been disabled or uninstalled, a platform that refuses — ends at the
     * system picker instead, so the key still gets the user to another
     * keyboard. `switchInputMethod` is API 28; below that the picker is the
     * only way, which is also what an unset key does.
     */
    private fun switchToInputMethod(id: String) {
        val enabled = getSystemService(InputMethodManager::class.java)
            ?.enabledInputMethodList.orEmpty().any { it.id == id }
        if (id.isNotBlank() && enabled && Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
            currentInputConnection?.let { commitComposing(it, autocorrect = false) }
            if (runCatching { switchInputMethod(id) }.isSuccess) return
        }
        showInputMethodPicker()
    }

    private fun showInputMethodPicker() {
        currentInputConnection?.let { commitComposing(it, autocorrect = false) }
        val imm = getSystemService(InputMethodManager::class.java)
        if (imm != null && runCatching { imm.showInputMethodPicker() }.isSuccess) return
        runCatching {
            startActivity(
                Intent(Settings.ACTION_INPUT_METHOD_SETTINGS)
                    .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK),
            )
        }
    }

    /**
     * Points the engine at the language and the grid [spec] describes: the
     * word sources it reads, and the geometry it weights typos against.
     *
     * The settings collector runs this on every emission, but a language
     * switch cannot wait for one. Telling the store which layout is active is
     * a round trip through DataStore, and until it comes back the engine is
     * still reading the language the user just left — which is why the strip
     * went on offering that language until the next keystroke (#233).
     */
    private fun bindEngineToLayout(
        spec: LayoutSpec,
        settings: KeyboardSettings,
        onlyIfChanged: Boolean = false,
    ) {
        val engine = suggestionEngine ?: return
        // Fancy Text is styled English: its words are English's (#950).
        val lang = spec.language().takeUnless { it.id == FancyStyles.LANG_ID } ?: LanguageRegistry.byId("en")
        // The settings collector passes [onlyIfChanged]: it runs this on every
        // emission, and an unrelated toggle in the settings app (same process,
        // same main thread) re-opened the n-gram packs from disk and handed the
        // engine a new proximity grid each time. Everything below is read from
        // these inputs; anything that changes the packs on disk outside them
        // (a download landing, a list imported) sets the engine itself.
        val binding = listOf(
            engine,
            spec,
            settings.numberRow && settings.suggestionStrip.numberRowCorrections,
            settings.secondaryLanguages[lang.id],
            customDictionaries,
            correctionMemory.version,
            userUnlocked,
            _uiState.value.settings.suggestionStrip.wordPairsEnabledFor(lang.id),
            _uiState.value.settings.suggestionStrip.wordPairsEnabledFor("en"),
            // The spelling libraries arriving (fetched from the dictionary
            // screen while the keyboard runs) are a reason to bind again;
            // Hunspell's and divvunspell's share one module.
            HunspellRuntime.moduleReady,
        )
        if (onlyIfChanged && binding == engineBinding) return
        engineBinding = binding
        // Typo weighting follows the grid actually on screen, so a
        // rearranged custom layout weights its own neighbours.
        engine.proximity = KeyProximity.forLayout(
            spec,
            numberRow = settings.numberRow && settings.suggestionStrip.numberRowCorrections,
        )
        // The letters a space-bar miss lands on follow the layout too —
        // this was a QWERTY constant for every layout before.
        engine.spaceAdjacentKeys = KeyProximity.spaceAdjacentKeys(spec)
            .ifEmpty { SuggestionEngine.SPACE_ADJACENT_DEFAULT }
        // Slips are a property of where the keys sit, so they follow the
        // layout as well; the setter ignores an unchanged snapshot.
        engine.editHabits = correctionMemory.habitsFor(spec.id)
        // Only English drives the bundled English word list; every other
        // language (with no bundled dictionary) drops it so autocorrect and
        // completions never offer English for their words. Bengali routes
        // through its own transliteration path either way.
        engine.englishSources = lang.isEnglish
        engine.primaryLanguageId = lang.id
        // Imported word lists are per language, so the active one follows the
        // mode: a French list never reaches English.
        engine.customDictionary = customDictionaries[lang.id] ?: PackedTrie.EMPTY
        refreshWordChecker(engine, lang.id)
        engine.ngramPack = loadNgramPack(lang.id)
        refreshContextModel()
        // Secondary languages feed the strip alongside the primary. English
        // rides its bundled list (englishAsSecondary); every other language
        // its imported list. Each is tagged with its id so its share of the
        // strip adapts to how much the user actually types it.
        val secondaryIds = settings.secondaryLanguages[lang.id].orEmpty()
        // Every secondary gets a slot, empty source and all. [customDictionaries]
        // only holds the languages with something on disk now, and a secondary
        // with no list is still a secondary: the engine gates whole behaviours
        // on this list being non-empty, so dropping the empty ones would make
        // "configured but has no words yet" mean "not configured".
        engine.secondaryDictionaries = secondaryIds.filter { it != "en" }
            .map { id -> SecondaryDictionary(id, customDictionaries[id] ?: PackedTrie.EMPTY) }
        engine.englishAsSecondary = "en" in secondaryIds && !lang.isEnglish
        // A phonetic secondary (Marathi on English) reads the Latin letters
        // through its own scheme and offers its words in its own script.
        engine.phoneticSecondaries = phoneticSecondaryIds(settings, lang.id)
        // English's own word pairs, for the word after an English one typed on
        // a layout that is not English's (`hello` on Avro).
        engine.secondaryEnglishNgramPack =
            if (engine.englishAsSecondary) loadNgramPack("en") else NgramPack.EMPTY
    }

    /** What [bindEngineToLayout] last bound the engine from. */
    private var engineBinding: List<Any?>? = null

    /**
     * The Hunspell checker the engine holds, keyed by what it was opened from
     * ([HunspellRuntime.signatureOf]), so a re-bind over the same files keeps
     * it instead of reading a large dictionary again. One language's at a time:
     * a German dictionary is tens of megabytes of native memory.
     */
    private var hunspellChecker: Pair<String, HunspellChecker>? = null

    /**
     * The GiellaLT speller the engine holds, keyed the same way
     * ([DivvunRuntime.signatureOf]). Also one language's at a time: the
     * archive is mapped, not read, but a North Sámi one is 80 MB of address
     * space and page cache.
     */
    private var divvunChecker: Pair<String, DivvunChecker>? = null

    /**
     * The Voikko checker the engine holds, keyed the same way
     * ([VoikkoRuntime.signatureOf]). Finnish only, so one at most.
     */
    private var voikkoChecker: Pair<String, VoikkoChecker>? = null

    /** What [refreshWordChecker] last gave the engine, so a stale run can tell whether it is still there. */
    private var engineWordChecker: WordChecker? = null

    /** The last [refreshWordChecker] run; each waits for the one before, so two never open at once. */
    private var wordCheckerJob: Job? = null

    /**
     * Gives [engine] the spelling checkers for [langId]: Hunspell over its
     * imported `.aff` and `.dic`, and the GiellaLT speller downloaded or
     * imported for it, either, both (one [WordChecker.of] the two) or none.
     * A language with a Voikko dictionary (Finnish) is checked with Voikko in
     * Hunspell's place: Hunspell is not even opened then.
     * None is the keyboard as it was before them: no imported pair or
     * speller, a list switched off, or a build or install without the
     * libraries (fetched from the language's dictionary screen, never from
     * here). Opening reads files, so it happens off the main thread and the
     * engine checks without them until then.
     */
    private fun refreshWordChecker(engine: SuggestionEngine, langId: String) {
        val previous = wordCheckerJob
        wordCheckerJob = serviceScope.launch {
            previous?.join()
            val heldHunspell = hunspellChecker
            val heldDivvun = divvunChecker
            val heldVoikko = voikkoChecker
            val (nextHunspell, nextDivvun, nextVoikko) = withContext(Dispatchers.IO) {
                val voikkoSignature = if (userUnlocked) VoikkoRuntime.signatureOf(filesDir, langId) else ""
                val voikko = when {
                    voikkoSignature.isEmpty() -> null
                    heldVoikko?.first == voikkoSignature -> heldVoikko
                    else -> VoikkoRuntime.open(filesDir, langId)?.let { voikkoSignature to it }
                }
                val files = if (userUnlocked && voikko == null) {
                    CustomDictionaries.hunspellFiles(filesDir, langId)
                } else {
                    emptyList()
                }
                val signature = HunspellRuntime.signatureOf(files)
                val hunspell = when {
                    files.isEmpty() -> null
                    heldHunspell?.first == signature -> heldHunspell
                    else -> HunspellRuntime.open(files)?.let { signature to it }
                }
                val spellerSignature = if (userUnlocked) DivvunRuntime.signatureOf(filesDir, langId) else ""
                val divvun = when {
                    spellerSignature.isEmpty() -> null
                    heldDivvun?.first == spellerSignature -> heldDivvun
                    else -> DivvunRuntime.open(filesDir, cacheDir, langId)?.let { spellerSignature to it }
                }
                Triple(hunspell, divvun, voikko)
            }
            hunspellChecker = nextHunspell
            divvunChecker = nextDivvun
            voikkoChecker = nextVoikko
            val held = engineWordChecker
            if (suggestionEngine === engine && _uiState.value.language.id == langId) {
                val next = WordChecker.of(listOfNotNull(nextVoikko?.second, nextHunspell?.second, nextDivvun?.second))
                engine.wordChecker = next
                engineWordChecker = next
            } else if (held != null && engine.wordChecker === held) {
                engine.wordChecker = WordChecker.NONE
                engineWordChecker = null
            }
            // Closed after the engine lets go of them; a call already inside
            // finishes first, since closing takes the same lock.
            if (heldHunspell != null && heldHunspell !== nextHunspell) heldHunspell.second.close()
            if (heldDivvun != null && heldDivvun !== nextDivvun) heldDivvun.second.close()
            if (heldVoikko != null && heldVoikko !== nextVoikko) heldVoikko.second.close()
        }
    }

    /**
     * A run of 🌐 presses in recently-used order (#311). [order] is snapshotted
     * on the first press, so the presses walk one fixed list rather than the
     * list reordering under them, and only where the run ends is recorded —
     * the layouts passed on the way were not used. Alt+Tab, for languages.
     */
    private class LanguageBurst(
        val origin: String,
        val order: List<String>,
        var index: Int,
        var lastPressAt: Long,
    )

    private var languageBurst: LanguageBurst? = null

    /**
     * The 🌐 key (or a physical keyboard's language key) with
     * [KeyboardSettings.globeRecentOrder] on. One press goes back to the layout
     * used before this one; each further press within [LANGUAGE_BURST_MS] of the
     * last goes one further back. The walk is shown in the language list from
     * the second on-screen press (the first only toggles, and a list over the
     * keys would catch the word typed straight after it), and from the first on
     * a physical keyboard, whose user is not about to tap the screen.
     */
    private fun switchLanguageRecent(hardware: Boolean): Boolean {
        val state = _uiState.value
        val ids = state.settings.switchLayoutIds()
        if (ids.size < 2) return false
        val now = SystemClock.uptimeMillis()
        val running = languageBurst?.takeIf {
            now - it.lastPressAt <= LANGUAGE_BURST_MS && it.order.getOrNull(it.index) == state.layoutId
        }
        val burst = running?.also { it.index = (it.index + 1).mod(it.order.size) }
            ?: recentLayoutOrder(state.settings.recentLayoutIds, ids, state.layoutId).let { order ->
                LanguageBurst(
                    origin = state.layoutId,
                    order = order,
                    index = if (order.first() == state.layoutId) 1 else 0,
                    lastPressAt = now,
                )
            }
        burst.lastPressAt = now
        languageBurst = burst
        if (hardware) vibrate()
        onLayoutSelected(burst.order[burst.index], recordRecent = false)
        if (hardware || running != null) {
            _uiState.update {
                it.copy(
                    languageSwitch = LanguageSwitchState(
                        layoutIds = burst.order,
                        candidate = burst.index,
                        browsing = false,
                        shownAt = now,
                    ),
                )
            }
            ensureInputViewShown()
        }
        serviceScope.launch {
            delay(LANGUAGE_BURST_MS)
            if (languageBurst === burst && burst.lastPressAt == now) settleLanguageBurst()
        }
        return true
    }

    /**
     * Ends the run of 🌐 presses: the layout it landed on moves to the front of
     * the recent list, the one it started from right behind it, and the list
     * it showed comes down. Nothing is recorded when something else moved the
     * keyboard meanwhile (a row tapped in the list records itself), or when
     * the walk came all the way round to where it started.
     */
    private fun settleLanguageBurst() {
        val burst = languageBurst ?: return
        languageBurst = null
        val session = _uiState.value.languageSwitch
        if (session != null && !session.browsing && session.layoutIds === burst.order) {
            cancelLanguageBrowse()
        }
        val landed = burst.order[burst.index]
        if (landed == _uiState.value.layoutId && landed != burst.origin) {
            serviceScope.launch { settingsRepository.setActiveLayoutId(landed, recentFrom = burst.origin) }
        }
    }

    /**
     * Hands the word being typed to the layout being switched to as its roman
     * buffer, and returns it — or null, which leaves the switch committing the
     * word as it always has.
     *
     * Switching to Avro in the middle of "tumi" used to commit the "tu" as
     * Latin, so the Bengali only started at the switch and the word had to be
     * typed again from the beginning (#522). Carried instead, the roman letters
     * become the new composer's buffer and read as তু, and the "mi" that
     * follows extends the same word.
     *
     * Two places hold the letters. A board that composes has them in
     * [composing], where the switch takes them straight over; a field typed
     * into without composing (one that asked for no suggestions, or a board
     * that commits every key) has them in the editor, and they are read back
     * and marked as the composing region the way a caret landing on a word
     * does ([restartSuggestionsAtCursor]) — which, like that resume, is
     * abandoned when the editor refuses the region rather than inserting the
     * word a second time.
     *
     * The costly reads are last: the gates above them are all field reads of
     * state the service already has.
     */
    private fun carryWordForSwitch(ic: InputConnection, spec: LayoutSpec): String? {
        val state = _uiState.value
        if (!state.settings.carryWordOnLanguageSwitch) return null
        // Only *into* a layout that spells its words in roman letters: Avro,
        // Hindi phonetic, Khipro.
        if (!spec.resolvedComposer().isRomanBuffer) return null
        // And only *out of* a board whose letters are those same roman ones —
        // a Latin keyboard, or another phonetic layout. Probhat's buffer is
        // Bengali, Hangul's is jamo, a conversion reading stands for a choice
        // of outputs, and a board with several letters to a key holds anchors
        // that stand for other letters entirely: none of them is a spelling
        // another transliterator could read.
        if (!state.composer.isRomanBuffer && state.script.id != ScriptId.LATIN) return null
        if (state.composer.isConversion || state.layouts.ambiguousKeys) return null
        // Something else owns the keys or the field's text is not what it looks
        // like: a keyboard-owned field composes in its own buffer, a Keyman
        // engine keeps its own context, and ANSI or Zawgyi output is glyphs
        // standing for the letters typed.
        if (state.captureTarget() != null || keymanSession != null) return null
        if (outputEncoding != null) return null
        val buffered = composing.toString()
        if (buffered.isNotEmpty()) {
            return carriedRomanWord(buffered)?.also { carryComposing(it) }
        }
        // Nothing is being composed, so the word has to come out of the field.
        // Never out of a password one: its text is the user's secret, and the
        // keyboard has no business putting it back through a transliterator.
        if (state.secureField) return null
        val caret = expectedSelStart
        if (caret < 0 || caret != expectedSelEnd) return null
        val before = ic.getTextBeforeCursor(CARRIED_WORD_MAX + 1, 0)
        val word = resumableWordAt(before, ic.getTextAfterCursor(1, 0))
            ?.let { carriedRomanWord(it) }
            ?: return null
        if (word.length > caret) return null
        if (!caretStillAt(ic, caret)) return null
        if (!ic.setComposingRegion(caret - word.length, caret)) return null
        carryComposing(word)
        return word
    }

    /**
     * Ends a Chinese or Cantonese reading the way [CjkSettings.readingOnSwitch]
     * asks, when the layout changes under it before it was converted (#973):
     * typed as keyed, the way fcitx5 does it, or dropped. False when there is
     * no such reading or the setting converts it, which is the ordinary commit.
     */
    private fun endReadingForSwitch(ic: InputConnection): Boolean {
        val state = _uiState.value
        if (composing.isEmpty() || !state.hanReading() || state.captureTarget() != null) return false
        val policy = state.settings.cjk.readingOnSwitch
        if (policy == ReadingOnSwitch.CONVERT) return false
        suggestionJob?.cancel()
        readingCaret = -1
        if (policy == ReadingOnSwitch.TYPED) {
            commitConversionAsTyped(ic)
        } else {
            ic.setComposingText("", 1)
            ic.finishComposingText()
            CjkContext.before = ""
            afterConversionFlushed()
        }
        return true
    }

    /** The carried word becomes the composing buffer, with no history behind
     * it: the taps were made on another board's keys, and the capitals it may
     * have been typed with are gone ([carriedRomanWord]), so nothing about the
     * spelling is the user's own. */
    private fun carryComposing(word: String) {
        suggestionJob?.cancel()
        composing = StringBuilder(word)
        composingCaseTrusted = false
    }

    /**
     * Spacebar swipe (or 🌐 cycle): switch to an explicit layout.
     *
     * [recordRecent] false keeps the switch out of the recently-used list: the
     * steps of a 🌐 run (recorded once, where it ends) and the Fancy Text tool
     * stepping in and out of its own layout.
     */
    fun onLayoutSelected(layoutId: String, recordRecent: Boolean = true) {
        val from = _uiState.value.layoutId
        val spec = resolveLayout(_uiState.value.settings.customLayouts, layoutId)
        // A word half-typed in roman letters carries into a transliterating
        // layout rather than being committed as Latin, so switching to Avro
        // in the middle of "tumi" converts the "tu" already typed instead of
        // leaving it to be typed again (#522). Non-null means the buffer now
        // belongs to the new layout and the commit is skipped; the composing
        // region is rewritten in the new script by the [updateComposingText]
        // below, once the state and the engine have followed the switch.
        val carried = currentInputConnection?.let { carryWordForSwitch(it, spec) }
        if (carried == null) {
            currentInputConnection?.let { if (!endReadingForSwitch(it)) commitComposing(it, autocorrect = false) }
        }
        // An explicit switch beats what the field asked for: the user can
        // see the box they are typing in, FORCE_ASCII and hintLocales are
        // only the app's guess.
        fieldLayoutOverride = null
        // Claimed before the state update, so a settings emission arriving
        // between here and the store catching up does not roll the pick back.
        pendingLayoutId = spec.id
        // Keeps the rule engine paired with the grid on screen: a
        // language switch must not leave the old keyboard's rules
        // running against the new grid.
        syncKeymanSession(spec)
        syncEngineBlacklist(spec.language().id)
        val shift = shiftAcrossScriptChange(spec.script(), spec.language())
        _uiState.update {
            it.copy(
                language = spec.language(),
                script = spec.script(),
                composer = spec.resolvedComposer(),
                shiftState = shift ?: it.shiftState,
                shiftPressedByUser = if (shift != null) false else it.shiftPressedByUser,
                layoutId = spec.id,
                layoutName = spec.name,
                layouts = resolveLayoutSet(
                    spec,
                    it.fieldKind,
                    deviceForm.value,
                    it.settings.numberRow,
                    it.settings.customLayouts,
                ),
                layoutMode = LayoutMode.LETTERS,
                // Words floating over the old layout's keys stop meaning anything
                // here, and a conversion layout never rebuilds them (#1027).
                octopus = emptyMap(),
                octopusGlide = emptyMap(),
            )
        }
        // A chord or morse sequence half-typed on the old layout must not leak
        // into the new one (or worse, keep a dot counted as held forever).
        resetChordInputs()
        // A layout with its own sound pack has to have it decoded before the
        // first key of the new layout, for the reason the warm-up preload
        // exists: a pack that arrives a few keystrokes late reads as the pack
        // not working.
        preloadLayoutSoundPack(from, spec.id)
        refreshKarContext()
        // The engine follows the switch in the same frame, and the strip is
        // rebuilt off it. Left to the settings write at the bottom of this
        // function to come back round, both went on answering in the language
        // just left, so the strip offered its words until the next keystroke
        // moved it (#233).
        bindEngineToLayout(spec, _uiState.value.settings)
        syncPhoneticAutoEnglish(_uiState.value.settings, spec)
        syncPhoneticFixedStrip(_uiState.value.settings, spec)
        syncLegacyOutput(_uiState.value.settings, spec)
        // The carried word is still roman in the field; here is the first point
        // the new composer, the engine and the phonetic flags are all in place,
        // so this is where it becomes Bengali (or Devanagari) on screen.
        if (carried != null) currentInputConnection?.let { updateComposingText(it) }
        refreshSuggestions()
        // The typing test follows the language: a prompt dealt in one
        // language cannot be typed on another's keys, so the switch re-deals.
        // The panel's own language chip lands here too, via the same layout
        // switch the spacebar makes.
        _uiState.value.let { switched ->
            if (switched.panel == PanelMode.TYPING_TEST &&
                switched.typingTest.languageId != switched.language.id
            ) {
                startTypingTest()
            }
        }
        // The handwriting model follows the input language; a switch while
        // the panel is open — or while writing on the keys — re-checks the new
        // model and drops pending ink.
        if (_uiState.value.panel == PanelMode.HANDWRITING ||
            keyboardHandwriteActive(_uiState.value)
        ) {
            refreshHandwritingStatus()
        }
        // Same for dictation: restart the session in the new language. The
        // collapsed bar's language switch lands here too — but only mid-
        // session: the bar idles with the mic closed, and a language change
        // must not open it uninvited.
        // A dictation with languages of its own (#416) has nothing to restart
        // for, nor does a switch between two layouts of the same language.
        if ((_uiState.value.panel == PanelMode.VOICE || (voiceBarShowing() && voiceActive())) &&
            voiceLanguageIds() != voiceSessionLanguages
        ) {
            startVoice()
        }
        val recentFrom = from.takeIf { recordRecent && it != spec.id }
        serviceScope.launch { settingsRepository.setActiveLayoutId(spec.id, recentFrom) }
        // Per-app memory: an explicit pick is what this app should reopen on.
        // The global write above still moves, so apps with no stored pick keep
        // following the last-used layout.
        if (_uiState.value.settings.perAppLanguage.enabled) {
            currentPackage?.let { pkg ->
                serviceScope.launch { settingsRepository.setAppLayout(pkg, spec.id) }
            }
        }
        mirrorSubtypeToOs(spec)
    }

    /** Resource id for the subtype label the switcher shows, per the label setting. */
    private fun subtypeNameResId(settings: KeyboardSettings): Int =
        if (settings.subtypeAppNameFirst) R.string.subtype_app_label else 0

    /**
     * The IME's manifest label, the name the picker shows for it, or 0 when it
     * cannot be read. Used as [languageOnlySubtype]'s name so that subtype
     * reads exactly as the keyboard does without one.
     */
    private val imeLabelRes: Int by lazy {
        runCatching {
            @Suppress("DEPRECATION")
            packageManager.getServiceInfo(ComponentName(this, javaClass), 0).labelRes
        }.getOrDefault(0)
    }

    /**
     * Mirrors the enabled layouts to the OS as additional input-method subtypes,
     * so the system language switcher lists them and can switch between them.
     *
     * Off (the [KeyboardSettings.osLanguageSwitcher] toggle) registers a single
     * [languageOnlySubtype] for the active layout's language, named after the
     * keyboard, so the picker still lists it under its own name while the
     * system spell checker learns what language is being typed. The settings
     * flow emits on every language switch, which is what keeps it current;
     * it is rewritten only when the language changes, not the layout.
     * Diffed against the last write via [registeredSubtypeSig].
     */
    // The String-id overload is deprecated on new SDKs but is the only one that
    // exists at minSdk 24 — the typed replacement is API 36+.
    @Suppress("DEPRECATION")
    private fun registerSubtypes(settings: KeyboardSettings) {
        // What the keyboard's own switcher lists, so a language hidden from it
        // is hidden from the system's too (#988). The active layout stays: the
        // framework answers its subtype going away by moving to another one.
        val listed = settings.switchLayoutIds().toSet()
        val ids = settings.enabledLayoutIds.ifEmpty { listOf(BuiltInLayouts.DEFAULT_ID) }
            .filter { it in listed || it == settings.activeLayoutId }
            .ifEmpty { listOf(BuiltInLayouts.DEFAULT_ID) }
        val nameResId = subtypeNameResId(settings)
        val languageOnly = if (settings.osLanguageSwitcher || imeLabelRes == 0) {
            null
        } else {
            languageOnlySubtype(resolveLayout(settings.customLayouts, settings.activeLayoutId), imeLabelRes)
        }
        val sig = if (!settings.osLanguageSwitcher) "off#${languageOnly?.languageTag.orEmpty()}"
        else "${ids.joinToString(",")}#$nameResId"
        if (sig == registeredSubtypeSig) return
        val subtypes = if (settings.osLanguageSwitcher) {
            ids.map { subtypeFor(resolveLayout(settings.customLayouts, it), nameResId) }.toTypedArray()
        } else {
            listOfNotNull(languageOnly).toTypedArray()
        }
        val imm = getSystemService(InputMethodManager::class.java) ?: return
        runCatching { imm.setAdditionalInputMethodSubtypes(imeId, subtypes) }
            .onSuccess {
                registeredSubtypeSig = sig
                enableSubtypes(imm, subtypes.map { it.hashCode() }.toIntArray())
                // Make it the current one rather than wait for the framework to
                // notice the old one is gone. The echo is ignored while off.
                if (languageOnly != null && Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
                    runCatching { switchInputMethod(imeId, languageOnly) }
                }
            }
    }

    /**
     * Registering a subtype is not the same as it being *enabled*, and only
     * enabled ones reach the switcher. With nothing explicitly enabled — the
     * default for every IME — the framework derives the enabled set from the
     * system locales, which on a normal single-locale phone is exactly one
     * keyboard subtype. That is why the switcher listed one language however
     * many we registered.
     *
     * API 34+ lets an IME write its own entry in
     * `Settings.Secure.ENABLED_INPUT_METHODS`. The framework keys the entry on
     * [InputMethodSubtype.hashCode], which is the explicit [stableSubtypeId] we
     * hand the builder in [subtypeFor] and [languageOnlySubtype]. Below 34 the
     * switcher-off subtype is enabled anyway: it is the only one registered, and
     * the framework falls back to an IME's first keyboard subtype when none
     * matches the system locale.
     *
     * On 24–33 there is no such API: the languages have to be ticked by hand in
     * the system subtype enabler, which the settings screen links to.
     *
     * Written before the first unlock this is volatile (the framework says so),
     * hence the re-register in [onUserUnlocked].
     */
    private fun enableSubtypes(imm: InputMethodManager, hashes: IntArray) {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.UPSIDE_DOWN_CAKE) return
        runCatching { imm.setExplicitlyEnabledInputMethodSubtypes(imeId, hashes) }
    }

    /**
     * Best-effort nudge of the OS switcher to match an in-app language switch so
     * the system UI's current subtype stays in sync. Skipped when the switcher
     * is turned off. API 28+ only; on 24–27 the OS→app direction still works, we
     * just don't push the other way. Swallowed: the subtype may not be
     * registered yet on a cold switch, and this is cosmetic — [onLayoutSelected]
     * has already moved the keyboard.
     */
    private fun mirrorSubtypeToOs(spec: LayoutSpec) {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.P) return
        val settings = _uiState.value.settings
        if (!settings.osLanguageSwitcher) return
        runCatching { switchInputMethod(imeId, subtypeFor(spec, subtypeNameResId(settings))) }
    }

    /**
     * The OS switcher (or system language shortcut) picked one of our subtypes:
     * follow it. Ignored when the switcher is off (the one subtype registered
     * then carries no layout).
     * Guarded against the echo from [mirrorSubtypeToOs] — when we are already on
     * that layout there is nothing to do, which also stops the in-app→OS→in-app
     * loop.
     *
     * Only a layout that is still enabled is followed. The framework remembers
     * the last selected subtype across our re-registrations and hands it back
     * when the keyboard starts, so a layout the user has since removed (English,
     * typically, the one onboarding started on) came back on every field (#783).
     */
    override fun onCurrentInputMethodSubtypeChanged(newSubtype: InputMethodSubtype) {
        super.onCurrentInputMethodSubtypeChanged(newSubtype)
        val settings = _uiState.value.settings
        if (!settings.osLanguageSwitcher) return
        val layoutId = layoutIdOf(newSubtype)?.takeIf { it in settings.enabledLayoutIds } ?: return
        if (layoutId != _uiState.value.layoutId) onLayoutSelected(layoutId)
    }

    // ---- composing & suggestions ----

    /**
     * What the field holds for the buffer currently being typed.
     *
     * For Avro that is the transliteration, except where the fixed-spelling
     * map has an entry for exactly this buffer: "tmr" reads তোমার as the r
     * lands rather than waiting for the space. Showing it early is safe
     * precisely because the map is what a space would have committed anyway —
     * it wins [SuggestionEngine.suggest]'s Bengali path outright — so this is
     * the preview catching up with the commit, not a second opinion that might
     * disagree with it. Every caller that has to recognise the field's own text
     * as this buffer's output derives it from here for that reason.
     */
    private fun composedPreview(state: KeyboardUiState, buffer: String): String {
        // Fancy Text composes plain letters and the field shows them styled,
        // so everything that measures or reads back the region finds the
        // styled word it holds (#950).
        fancyOutputStyle(state)?.let { return FancyStyles.transform(buffer, it) }
        if (state.layouts.ambiguousKeys && buffer.isNotEmpty()) {
            ambiguousReading?.takeIf { it.first == buffer }?.let { return it.second }
            val reading = ambiguousDecode(buffer) ?: buffer
            ambiguousReading = buffer to reading
            return reading
        }
        if (!state.composer.isTransliterating) return buffer
        state.composer.phoneticLanguage?.let { language ->
            // An English word the space bar is about to commit as English
            // shows as English, for the reason the map's spelling shows early.
            suggestionEngine?.phoneticLatinPreview(language, buffer, previousWord)?.let {
                return sentenceCasedLatin(it, buffer, state)
            }
            suggestionEngine?.phoneticSpelling(language, buffer, previousWord, previousWord2)?.let { return it }
        }
        completionLatin(state, buffer)?.let { return it }
        return state.composer.composeBuffer(buffer)
    }

    /**
     * The best reading of an ambiguous buffer: what the user has actually
     * spelled with the keys they pressed, where the buffer itself holds only
     * the anchor letter of each.
     *
     * Null when nothing decodes — a run of keys no word starts with — and the
     * caller then shows the anchors, which is at least a truthful count of the
     * keystrokes and is what a long press has to be used to fix.
     *
     * Synchronous, and on the main thread, which is deliberate. On a board with
     * three letters to a key the reading is not a suggestion sitting beside the
     * text — it *is* the text, the only feedback that the keypress landed on
     * the right word, and a reading that arrives a frame late reads as the
     * keyboard dropping keystrokes. The walk it costs is the one the strip's
     * async pass is about to make anyway, and it makes it against the same
     * buffer, the same taps and the same key sets — so that pass finds it in
     * the engine's ranked-walk cache rather than repeating it.
     */
    private fun ambiguousDecode(buffer: String): String? {
        val engine = suggestionEngine ?: return null
        val keys = composingKeyFrame()?.takeIf { it.isAmbiguous } ?: return null
        return engine.suggest(
            composing = buffer,
            previousWord = previousWord,
            previousWord2 = previousWord2,
            limit = 1,
            touch = composingTouchFrame(),
            keys = keys,
        ).firstOrNull()
    }

    /**
     * Whether a caret inside the composing reading edits it rather than ending
     * it (#960): a conversion reading that stays kana until it is converted,
     * not split into segments (Mozc's arrows own those), in the app's field.
     */
    private fun editsInsideReading(state: KeyboardUiState): Boolean {
        val composer = state.composer
        return composer.isConversion && composer.keepsUnconvertedReading && composing.isNotEmpty() &&
            state.captureTarget() == null && composer.focusedSegment(composing.toString()) == null
    }

    private fun updateComposingText(ic: InputConnection) {
        val preview = composedPreview(_uiState.value, composing.toString())
        // A fragment typed into a word the user came back to rewrites itself
        // whole on every keystroke; the field-mode revision mirrors exactly that.
        revision?.takeIf { it.mode == WordRevision.Mode.FIELD }?.let { r ->
            r.expectReplaceBefore(revisionFragment.length, preview)
            revisionFragment = preview
        }
        // A Chinese reading kept on the strip (#973) leaves the field with no
        // region at all: an empty composing text clears one left from before
        // the setting changed, and a pick's commitText then lands at the caret.
        val inKeyboard = _uiState.value.readingInKeyboard()
        ic.setComposingText(if (inKeyboard) "" else segmentMarked(preview), 1)
        if (!inKeyboard || composing.isEmpty()) {
            hiddenReadingCaret = -1
        } else if (hiddenReadingCaret < 0) {
            // Read once per reading and once per pick, never per key: the
            // field does not change while the reading is typed.
            hiddenReadingCaret = liveCollapsedCaret(ic) ?: expectedSelStart.takeIf { it == expectedSelEnd } ?: -1
        }
        // Mid-reading, setComposingText left the caret at the region's end:
        // back to where the next key goes (#960).
        val caret = readingCaret
        if (!inKeyboard && caret in 0 until composing.length && readingRegionStart >= 0 &&
            editsInsideReading(_uiState.value)
        ) {
            val offset = _uiState.value.composer.previewOffset(composing.toString(), caret)
                .coerceIn(0, preview.length)
            val at = readingRegionStart + offset
            if (readingCaretEchoes.size >= READING_ECHOES_MAX) readingCaretEchoes.removeFirst()
            readingCaretEchoes.addLast(at)
            ic.setSelection(at, at)
        } else {
            readingCaret = -1
        }
        _uiState.update { it.copy(composingPreview = preview) }
        publishComposingRoman()
        publishKanaVariantReady()
    }

    /**
     * [preview] with a reading's segments marked, while a segmenting
     * composer (Mozc) has it split: the focused segment shaded, the others
     * underlined, as Mozc's own keyboard draws them, so the arrow keys'
     * resizing shows where the boundary went. Unmarked otherwise; the app
     * draws its own composing underline then.
     */
    private fun segmentMarked(preview: String): CharSequence {
        val composer = _uiState.value.composer
        if (!composer.segmentsReading) return preview
        val focus = composer.focusedSegment(composing.toString()) ?: return preview
        if (focus.first < 0 || focus.last >= preview.length || focus.isEmpty()) return preview
        return SpannableString(preview).apply {
            setSpan(UnderlineSpan(), 0, preview.length, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE or Spanned.SPAN_COMPOSING)
            setSpan(BackgroundColorSpan(SEGMENT_FOCUS_COLOR), focus.first, focus.last + 1, Spanned.SPAN_EXCLUSIVE_EXCLUSIVE)
        }
    }

    /**
     * Mirrors whether the reading's last kana has a 小゛゜ form into
     * [KeyboardUiState.kanaVariantReady], which turns a
     * [com.wasimaster.wmkeyboard.core.layout.Key.kanaVariantWhileComposing] key
     * into the 小゛゜ key (issue #340). Asked at the same two places the roman
     * mirror is, for the same reason: they are every way the buffer changes.
     *
     * False on any board without such a key, because the flag is a key of the
     * grid's `remember` — see [LayoutSet.hasKanaVariantKeys].
     */
    private fun publishKanaVariantReady() {
        val state = _uiState.value
        // A keyboard-owned field composes in [captureComposition], not in the
        // service's buffer, and that buffer still holds whatever the app's
        // field was left half-way through (#527).
        val last = if (state.captureTarget() != null) {
            captureComposition?.keys?.lastOrNull()
        } else if (readingCaret in 1 until composing.length) {
            composing[readingCaret - 1]
        } else {
            composing.lastOrNull()
        }
        val ready = last != null && state.layouts.hasKanaVariantKeys && Kana.cycleVariant(last) != last
        if (state.kanaVariantReady != ready) {
            _uiState.update { it.copy(kanaVariantReady = ready) }
        }
    }

    /**
     * Mirrors the roman buffer into [KeyboardUiState.composingRoman], which is
     * what the transliteration key hints are drawn from.
     *
     * Called from the two places the buffer can change: this property's setter
     * for a wholesale replacement (commit, field change, re-arm), and
     * [updateComposingText] for the in-place edits (append, backspace), which
     * every one of those edits already calls.
     *
     * Empty unless the hints are actually on. The mirror is a `remember` key of
     * the whole key grid, so publishing it where nothing draws it would rebuild
     * all ~40 key bodies on every keystroke for nothing.
     */
    private fun publishComposingRoman() {
        val state = _uiState.value
        val roman = if (state.transliterationHintsShown()) composing.toString() else ""
        if (state.composingRoman != roman) {
            _uiState.update { it.copy(composingRoman = roman) }
        }
    }

    /**
     * Inserts panel-produced text (an emoji, a paste, a translation, an AI
     * result) at the cursor. Any word still being composed is committed as
     * typed first: a bare commitText would *replace* the active composing
     * region, eating the word — and skipping the flush leaves a stale buffer
     * that the next setComposingText re-inserts wherever the cursor has
     * moved to since, making the "previous word" reappear out of nowhere.
     */
    private fun commitToField(text: String) {
        val ic = currentInputConnection ?: return
        commitComposing(ic, autocorrect = false)
        ic.commitText(text, 1)
    }

    /**
     * Puts a single typed character into the field, as a real key event when it
     * is an ASCII digit and as a commit for everything else.
     *
     * A committed character reaches a web page as an `input` event behind a
     * `keydown` that carries no key at all (`keyCode` 229 — the code every
     * browser uses for "the IME is composing"). Pages that police their own
     * fields on `keydown` — one-character-per-box verification forms above all,
     * which typically test the pressed key against `/[0-9]/` and cancel
     * anything else — throw that event away, and the digit never lands: the
     * user types and the box stays empty, with nothing on screen to say why.
     * A key event carries the real key, so those handlers see a digit and let
     * it through, and every ordinary editor treats it exactly like the commit
     * it replaces.
     *
     * The same fix AOSP's own keyboard carries, for the same reason, and the
     * reason digits are the only characters it applies to: `KEYCODE_0`..`_9`
     * are the only ones whose key event is unambiguous on every layout.
     */
    private fun commitTypedCharacter(ic: InputConnection, text: String) {
        mirrorTypedIntoRevision(ic, text)
        // A styled digit is no key: it goes in as text, to be styled.
        val digit = text.singleOrNull()?.takeIf { it in '0'..'9' && fancyOutputStyle(_uiState.value) == null }
        if (digit != null) {
            sendDownUpKeyEvents(KeyEvent.KEYCODE_0 + (digit - '0'))
        } else {
            ic.commitText(text, 1)
        }
    }

    /**
     * Types a one-time code into the field, one character at a time when
     * [OtpSettings.perDigitEntry] is on.
     *
     * The box a code goes into is very often a *row* of boxes, each holding one
     * character and moving the focus on by itself once it has one. A code
     * committed whole lands entirely in the first box, where all but the first
     * character is discarded by its own length limit — the user sees one digit
     * of six appear and the rest vanish. Typed character by character, each box
     * gets the one character it wants and hands over to the next, which is what
     * the form was built for; a plain single field sees the same code arrive,
     * just over a few frames instead of one.
     *
     * The input connection is re-read on every character rather than captured
     * once, because the focus moving between boxes is exactly what replaces it.
     * The gap between characters is what gives the page's own focus handler
     * time to run — without it every character races the same box.
     */
    private fun commitCodeToField(code: String) {
        if (code.length <= 1 || !_uiState.value.settings.otp.perDigitEntry) {
            commitToField(code)
            return
        }
        currentInputConnection?.let { commitComposing(it, autocorrect = false) }
        codeEntryJob?.cancel()
        codeEntryJob = serviceScope.launch {
            // Paced by the field rather than by a clock (#508). A fixed step
            // raced the form's own focus handler: a character sent while the
            // next box was still taking over went to a connection already
            // closed, and 098805 arrived as 08805. So each character waits
            // for the box it filled to hand over, however long that takes.
            // A field that does not hand over after the first character is
            // one field, and the rest goes in at once rather than trickling.
            var boxes = false
            var i = 0
            while (i < code.length) {
                val ic = currentInputConnection ?: break
                val starts = inputStarts
                commitTypedCharacter(ic, code[i].toString())
                i++
                if (i == code.length) break
                val handedOver = withTimeoutOrNull(CODE_BOX_HANDOFF_MS) {
                    while (inputStarts == starts) delay(CODE_ENTRY_POLL_MS)
                } != null
                if (handedOver) {
                    boxes = true
                    // The new box's connection is up; give its view a frame.
                    delay(CODE_ENTRY_POLL_MS)
                } else if (!boxes) {
                    val rest = currentInputConnection ?: break
                    if (code.all { it in '0'..'9' }) {
                        rest.beginBatchEdit()
                        while (i < code.length) commitTypedCharacter(rest, code[i++].toString())
                        rest.endBatchEdit()
                    } else {
                        // Digits go in as key events and letters as text, and
                        // the two do not keep their order in one field: a hex
                        // colour came out scrambled. One field takes the rest
                        // as one run of text.
                        val tail = code.substring(i)
                        mirrorTypedIntoRevision(rest, tail)
                        rest.commitText(tail, 1)
                        i = code.length
                    }
                }
            }
            // Every commit above echoes back as a caret move, and the batch's
            // echoes are all delivered after it — that is, after the last
            // character is in the field and this loop is done. The run stays in
            // flight until they have landed, or the resume reads one of them as
            // the user having come back to the code (see [CODE_ECHO_SETTLE_MS]).
            delay(CODE_ECHO_SETTLE_MS)
        }
    }

    /**
     * Types [text] into the field one character at a time, at the code's own
     * pace. Shared by [commitCodeToField] and the typed-out paste of
     * [ClipboardSettings.typeOutPastes] (#418).
     *
     * Steps by grapheme cluster, not by `Char`: a code is ASCII, but a pasted
     * clip can hold an emoji or a combining mark, and committing half a
     * surrogate pair or a base letter without its accent puts something in the
     * field that was never in the clip.
     */
    private fun commitCharacterByCharacter(text: String) {
        currentInputConnection?.let { commitComposing(it, autocorrect = false) }
        codeEntryJob?.cancel()
        codeEntryJob = serviceScope.launch {
            val clusters = java.text.BreakIterator.getCharacterInstance().apply { setText(text) }
            var start = clusters.first()
            var end = clusters.next()
            while (end != java.text.BreakIterator.DONE) {
                val ic = currentInputConnection ?: break
                commitTypedCharacter(ic, text.substring(start, end))
                delay(CODE_ENTRY_STEP_MS)
                start = end
                end = clusters.next()
            }
        }
    }

    /**
     * Re-establishes the editor-side composing span for the word still in
     * [composing] after the input connection restarted, or drops the buffer when
     * the field no longer backs it. [start] and [end] are the selection the
     * editor reported with the restart.
     *
     * A restart leaves the text but takes the span, so the buffer and the field
     * disagree until one of them gives. Keeping the buffer alone is the worse
     * half: with no span to replace, the next [updateComposingText] inserts the
     * whole buffer at the caret and the word being typed shows up twice.
     * Re-attaching keeps both — the word carries on being typed as if nothing
     * happened.
     *
     * Only ever attaches over text that still reads back as the buffer's own
     * output, so a stale or bogus [start] can't put the span over somebody
     * else's characters; anything short of an exact match drops the buffer,
     * which costs the word's prefix on the strip but never corrupts the field.
     */
    private fun reattachComposing(start: Int, end: Int) {
        if (composing.isEmpty()) return
        // A reading kept on the strip (#973) has no span in the field to lose:
        // it carries on from the keyboard as if nothing had happened.
        if (_uiState.value.readingInKeyboard()) return
        val ic = currentInputConnection
        // What the field actually holds for this buffer: a transliterating
        // composer's text is the composed form, not the roman source mirrored
        // in the buffer. Same derivation as [updateComposingText].
        val text = composedPreview(_uiState.value, composing.toString())
        val reattached = ic != null && text.isNotEmpty() &&
            start == end && start >= text.length &&
            ic.getTextBeforeCursor(text.length, 0)?.toString() == text &&
            ic.setComposingRegion(start - text.length, start)
        if (reattached) {
            _uiState.update { it.copy(composingPreview = text) }
            return
        }
        composing = StringBuilder()
        suggestionJob?.cancel()
        // The word behind the caret is the bigram context now that it is no
        // longer being composed, so predictions carry on from it.
        if (ic != null) syncPreviousWordFromField(ic)
        _uiState.update {
            it.copy(composingPreview = "", suggestions = emptyList(), emojiSuggestions = emptyList(), octopus = emptyMap())
        }
    }

    /**
     * Ends any active composition ahead of an edit that must target the
     * *selection*. With a composing region alive, commitText targets the
     * region instead (InputConnection contract) — replacing the whole word
     * when only part of it is selected — and the stale local mirror would
     * re-insert the word at the caret on the next keystroke. finishComposingText
     * turns the region into ordinary text without touching the selection, so
     * the caller's commitText then affects exactly the selected range.
     */
    private fun dropComposingForSelectionEdit(ic: InputConnection) {
        ic.finishComposingText()
        if (composing.isEmpty()) return
        composing = StringBuilder()
        suggestionJob?.cancel()
        _uiState.update {
            it.copy(composingPreview = "", suggestions = emptyList(), emojiSuggestions = emptyList(), octopus = emptyMap())
        }
    }

    /**
     * Commits the composing region. In Avro mode the top phonetic
     * suggestion wins (dictionary sibling over literal); in English mode
     * autocorrect may replace the typed word. Returns true if anything
     * was committed.
     */
    private fun commitComposing(
        ic: InputConnection,
        autocorrect: Boolean,
        fixApostrophes: Boolean = false,
        /**
         * Whether a *pattern* snippet may fire. A pattern consumes committed
         * text behind the caret, so only the callers where the user has just
         * ended a word — space, enter, a full stop — may set it. Every other
         * call here is incidental: a panel opening, a forward delete, a layout
         * switch, a cursor scrub. A pattern firing from one of those would eat
         * text the user never touched. The word trigger is unaffected, since it
         * only ever consumes the composing buffer.
         */
        expandPatterns: Boolean = false,
    ): Boolean {
        // A word read off gestures is already the decoder's answer, chosen from
        // the dictionary with every tap and swipe as evidence; correcting it
        // again as if its letters had been typed one by one would second-guess
        // the better reading with a worse one (#638).
        // A word ended while its latest gesture is still being read: read it
        // now, so what is typed is the whole word and not the last reading.
        if (duetWord.active && duetShownGeneration != duetGeneration) settleDuet(ic)
        if (autocorrect && duetWord.active) {
            return commitComposing(ic, autocorrect = false, fixApostrophes = fixApostrophes, expandPatterns = expandPatterns)
        }
        // Spent by whichever key ended this word; a commit that does not park
        // the caret must not leave a stale one behind for the next.
        swallowTerminatorAfterCommit = false
        patternFiredAtCommit = false
        plainCommitEnd = -1
        if (composing.isEmpty()) return false
        // A hyphen the word ended on was typed to start a compound that never
        // came ("well-" then a space). The word in front of it commits the way
        // the hyphen used to commit it — as typed, uncorrected — and the hyphen
        // lands after it as the punctuation it turned out to be, so neither a
        // correction nor the lexicon ever sees a word spelled with it.
        val danglingHyphen = composing.length > 1 && composing[composing.length - 1] == COMPOUND_HYPHEN &&
            !_uiState.value.composer.isTransliterating
        if (danglingHyphen) {
            ic.beginBatchEdit()
            // Trimmed in place, the way a backspace trims it, so the head keeps
            // its taps. The field still shows the hyphen inside the composing
            // region; the head's commit below replaces the whole region.
            // A frame already out of step with the buffer stays out of step.
            val length = composing.length
            if (composingTouch.size == length) composingTouch.removeAt(length - 1)
            if (composingKeys.size == length) composingKeys.removeAt(length - 1)
            if (composingHints.size == length) composingHints.removeAt(length - 1)
            composing.setLength(length - 1)
            commitComposing(ic, autocorrect = false)
            ic.commitText(COMPOUND_HYPHEN.toString(), 1)
            ic.endBatchEdit()
            return true
        }
        // The gestures behind a two-thumb word, kept past the setter below
        // that clears them: they are what this word teaches (#741).
        val duetGestures = if (duetWord.active) {
            recordDuetWord()
            DuetGestures(duetWord.snapshot(), duetWord.keys, duetWord.keyWidthPx, duetShownComplete)
        } else {
            null
        }
        // A strip refresh still debounced for this word must not land after
        // the commit and repaint candidates for text that is no longer being
        // composed (the tail of this function publishes the next-word strip).
        suggestionJob?.cancel()
        val typed = composing.toString()
        val state = _uiState.value
        // Snapshot of the taps behind this word, taken before the buffer (and
        // with it the frame) is replaced below; it rides to the settle.
        val taps = composingTouchFrame()
        val tapKeys = suggestionEngine?.touchModel

        // An abandoned inline emoji query (":smi" then space) is literal text:
        // never transliterated, autocorrected, or learned as a word.
        if (inlineEmojiQuery() != null) {
            ic.commitText(typed, 1)
            composing = StringBuilder()
            _uiState.update {
                it.copy(composingPreview = "", suggestions = emptyList(), emojiSuggestions = emptyList(), octopus = emptyMap())
            }
            return true
        }
        // A word that exactly matches a snippet trigger expands to that
        // snippet's text instead of committing literally, and a pattern
        // snippet may then match the words behind it. Most specific first: a
        // trigger that reaches back past the buffer (`:shrug`, `gr db`) asks
        // for everything a plain one does and more, so it goes first or a
        // plain "db" would shadow "gr db"; a literal trigger then beats a
        // pattern, so a careless `^(.+)$` cannot shadow the whole list.
        //
        // All three are skipped for transliterating/conversion composers
        // (Pinyin, Vietnamese, …) — their buffer holds an input spelling, not
        // the trigger the user meant to type. All three also come before
        // apostrophes and autocorrect, so a trigger is matched as it was
        // actually typed.
        if (!state.composer.isTransliterating && !state.composer.isConversion) {
            if (tryPrefixExpansion(ic, typed)) return true
            // A trigger that asks first has already put its chip on the strip
            // (see [refreshSnippetOffer]); the word it matched commits as
            // ordinary text, and the offer goes with it.
            val snippet = snippetStore.matchTrigger(typed)?.takeIf { !snippetStore.offers(it) }
            if (snippet != null) {
                val expanded = SnippetStore.expandWithCursor(
                    snippet.text,
                    context = snippetContext(ic),
                    casing = SnippetStore.casingFor(snippet, typed),
                )
                commitSplitAtCaret(ic, expanded.text, expanded.cursorOffset)
                afterSnippetExpansion(
                    inserted = expanded.text,
                    original = null,
                    caretParked = expanded.cursorOffset < expanded.text.length,
                )
                publishSwapSet(
                    snippet = snippet,
                    typed = typed,
                    inserted = expanded.text,
                    insertedCaret = expanded.cursorOffset,
                    original = null,
                )
                return true
            }
            if (expandPatterns && tryPatternExpansion(ic, typed, state)) return true
        }
        // Conversion IME (Pinyin, Japanese): flush the whole reading as a
        // sequence of best candidates, each consuming its own syllables, so the
        // callers that aren't the space bar — cursor scrub, layout switch,
        // defocus — never drop the unconverted tail. The space bar takes the
        // interactive one-step path (commitConversionPrefix) instead.
        //
        // Japanese keeps its kana instead (#616): ending なるといいです with ！
        // typed NARUTOイイデス！. Only space and a picked candidate convert,
        // as Enter already had it (#514); a candidate the arrow keys or a
        // stepping space bar highlighted is still the pick.
        if (state.composer.isConversion) {
            if (state.composer.keepsUnconvertedReading) {
                commitHighlightedCandidate()
                if (composing.isNotEmpty()) commitConversionAsTyped(ic)
            } else {
                flushConversion(ic)
            }
            return true
        }
        // "google. com": the auto-space after the full stop went in before the
        // word showed it was a domain ending. Ahead of autocorrect, which
        // would otherwise turn "com" into "come".
        if (joinDotSuffix(ic, typed, state)) return true
        // A buffer glued to word characters already in the field is the tail
        // of a bigger word, not a word of its own: the caret was parked at a
        // word's end and the composition started before the resume could arm
        // the rest of it (a tap's selection echo races the next keystroke).
        // Correcting the fragment corrupts the word it hangs off — "i" typed
        // onto "hind" must not become "I" — and a suffix is neither a typo to
        // guess at nor a word worth learning.
        //
        // Measured against what the field holds for this buffer, not the
        // buffer itself. They are the same text on an ordinary board; on an
        // ambiguous one the field shows the reading, and a reading longer
        // than its anchors ("this" for the three keys t-g-u) would otherwise
        // look like a word glued to the buffer and the space would commit the
        // anchors in its place (issue #145).
        val fieldText = composedPreview(state, typed)
        val gluedToWord = (fixApostrophes || autocorrect) &&
            state.allowsTypingIntelligence && !state.composer.isTransliterating &&
            ic.getTextBeforeCursor(fieldText.length + ELISION_LOOKBACK, 0)
                ?.takeIf { it.length > fieldText.length }
                ?.let { before ->
                    val ahead = before.subSequence(0, before.length - fieldText.length)
                    // An elided prefix and its apostrophe ("l'", "qu'") end a
                    // word rather than start one: the buffer after them is a
                    // word of its own, corrected and learned as one (#215).
                    isComposingWordChar(ahead[ahead.length - 1]) &&
                        Elisions.rulesFor(state.language.id)?.endsWithElidedPrefix(ahead) != true
                } == true
        // Apostrophe restoration outranks autocorrect: "dont" is a known
        // contraction slip, not a typo for "font"/"done" to be guessed at.
        // Which route the language takes — English's table of contractions,
        // an elision language's own word lists — is the engine's to know
        // (#215, #240).
        val apostrophized =
            if (fixApostrophes && state.allowsTypingIntelligence && !gluedToWord) {
                suggestionEngine?.elide(typed)
            } else {
                null
            }
        // The async suggestion job precomputes this word's commit resolution off
        // the main thread; use it only while it still matches [typed] (a
        // mismatch means the job hasn't caught up), else compute synchronously.
        // Either way the result is fresh — the commit never uses a stale strip.
        val pre = commitResolution?.takeIf { it.typed == typed }
            ?: if (autocorrect && !gluedToWord && apostrophized == null && latinResolution(state, typed)) {
                awaitCommitResolution(typed)
            } else {
                null
            }
        var corrected: String? = null
        // A candidate that came close to being applied without getting there.
        // Published as a chip below, once the word is actually in the field.
        var offered: String? = null
        // How unremarkable the correction was, for the undo chip's gate below.
        // 1 — nothing to remark on — is the right answer for every branch that
        // corrects nothing at all.
        var obviousness = 1.0
        // On a phonetic layout that could have committed this buffer in either
        // script: the other script's word, which a backspace or the chip flips to.
        var scriptAlternate: String? = null
        // The word a Vietnamese buffer commits, composed ahead of the branch
        // that ranks it: the undo below has to put this back, not the keystrokes
        // that spelled it. Null for every other composer.
        val vietnameseComposed =
            if (isVietnameseTransliterator(state)) state.composer.composeBuffer(typed) else null
        // The word the field holds before this commit replaces it: the
        // composer's own spelling for Vietnamese, the buffer itself for every
        // other composer. Everything that has to name the word being replaced —
        // the undo, the near-miss chip, the correction span — names this, and
        // never the keystrokes that spelled it.
        val fieldWord = vietnameseComposed ?: typed
        // Where this word starts in the field, for [declinedSpots]; -1 unknown.
        val wordStart = if (expectedSelStart >= fieldText.length) expectedSelStart - fieldText.length else -1
        // The user has turned a correction of this word down at this very spot
        // often enough: it goes in as typed, and is not offered either.
        val declinedHere = wordStart >= 0 &&
            declinedSpots.blocks(wordStart, fieldWord, state.settings.correction.stopAfterDeclines)
        val output = when {
            state.composer.phoneticLanguage != null -> {
                val language = state.composer.phoneticLanguage.orEmpty()
                val top = if (pre != null && pre.isPhonetic) {
                    scriptAlternate = pre.phoneticAlternate
                    pre.phoneticTop
                } else {
                    val commit = suggestionEngine?.phoneticCommit(language, typed, previousWord, previousWord2)
                    scriptAlternate = commit?.alternate
                    commit?.output
                } ?: state.composer.composeBuffer(typed)
                val led = neuralCommit(state, language, typed, top) ?: top
                if (isLatinOnPhonetic(led, state)) sentenceCasedLatin(led, typed, state) else led
            }
            // Vietnamese commits a composed Vietnamese word, and a word list
            // knows more about that word than the composer does: the spelling
            // with the tone or the letter the user left out is in the list, and
            // the one the keystrokes composed is not. Ranked on the composed
            // text, because the buffer holds keystrokes ("tieengs") that no list
            // has heard of. A word the list does hold is protected from
            // correction, so a real word is committed as the user wrote it.
            // Asked for separately (VietnameseSettings.restoreMarks): typing
            // without marks is a choice people make, and autocorrect being on
            // for their other languages does not say they want marks added.
            vietnameseComposed != null && autocorrect && state.settings.vietnamese.restoreMarks &&
                state.allowsTypingIntelligence && !gluedToWord -> {
                val decision = suggestionEngine?.decideCorrection(
                    vietnameseComposed,
                    timingMultiplier = timingMultiplier(),
                    previousWord = previousWord,
                ) ?: SuggestionEngine.NO_CORRECTION
                corrected = decision.apply?.takeIf { it != vietnameseComposed && !declinedHere }
                offered = decision.offer?.takeIf { it != vietnameseComposed && !declinedHere }
                obviousness = decision.obviousness
                corrected ?: vietnameseComposed
            }
            // Other transliterators (Hangul) commit the composed text
            // directly, with no dictionary pass. A layout whose keys spell the
            // word outright (Khipro) commits the English word they spell; the
            // Vietnamese pair commits the word its own list knows. The two
            // never both answer — `completionLanguage` is set on the layouts
            // that have no Vietnamese dictionary pass, and [vietnameseComposed]
            // on the one that has no completion language. An imported m17n
            // method commits what its rules leave once the word closes.
            state.composer.isTransliterating ->
                completionLatin(state, typed) ?: vietnameseComposed
                    ?: state.composer.finishBuffer(typed)
            // An ambiguous board commits its reading, always. There is no
            // confidence gate here and there should not be: the buffer holds
            // anchor letters, so "leave it as typed" is not a conservative
            // choice but a wrong one, and this is a decode rather than a
            // correction — nothing was misspelled to revert to. A reading the
            // user did not want is changed the way T9 always changed it, by
            // picking another from the strip. The anchors stand only when
            // nothing decodes at all, which is a word the dictionary has never
            // seen and the long-press letters exist to spell.
            state.layouts.ambiguousKeys && !gluedToWord ->
                (pre?.ambiguousTop ?: ambiguousDecode(typed)) ?: typed
            apostrophized != null -> apostrophized
            autocorrect && state.allowsTypingIntelligence && !gluedToWord -> {
                val decision = if (pre != null && !pre.isPhonetic) {
                    SuggestionEngine.CorrectionDecision(
                        pre.correction, pre.offer, pre.certainty, pre.complexity,
                    )
                } else {
                    suggestionEngine?.decideCorrection(
                        typed,
                        touch = taps,
                        timingMultiplier = timingMultiplier(),
                        previousWord = previousWord,
                    ) ?: SuggestionEngine.NO_CORRECTION
                }
                corrected = decision.apply?.takeIf { it != typed && !declinedHere }
                offered = decision.offer?.takeIf { it != typed && !declinedHere }
                obviousness = decision.obviousness
                corrected ?: typed
            }
            else -> typed
        }
        // The word the user came back to and retyped, if this buffer was one:
        // what the *buffer* held against what it holds now, never the output.
        // An autocorrect landing on top is the engine's doing, and the pair it
        // makes is not one the user taught; a fragment glued to a word is not
        // a word at all. See [WordRevision].
        val replaces = revision?.takeIf { it.mode == WordRevision.Mode.COMPOSING }?.let { r ->
            revision = null
            // An ambiguous board is excluded for the reason a transliterator
            // is: what the buffer held is anchor letters, not a spelling, so
            // "the word as the user left it" cannot be read off it and the
            // pair it would teach is between two things nobody typed.
            if (corrected != null || gluedToWord || state.composer.isTransliterating ||
                state.layouts.ambiguousKeys
            ) {
                null
            } else {
                r.finish(typed)?.let { resolveRevision(it) }
            }
        }
        // A fragment typed into a word being followed in the field commits
        // over its own region; the mirror has to see it land.
        revision?.takeIf { it.mode == WordRevision.Mode.FIELD }?.let { r ->
            r.expectReplaceBefore(revisionFragment.length, output)
            revisionFragment = ""
        }
        val scriptFlip = scriptAlternate?.takeIf { it != output }?.let {
            ScriptFlip(
                state.composer.phoneticLanguage.orEmpty(),
                typed,
                if (isLatinOnPhonetic(output, state)) PhoneticScript.NATIVE else PhoneticScript.LATIN,
            )
        }
        val revertible = corrected?.let {
            // The undo puts back what the user had in the field, and one
            // backspace has to take the correction back the same way.
            RevertibleCommit(
                RevertibleCommit.Kind.AUTOCORRECT,
                original = fieldWord,
                committed = it,
            )
        } ?: apostrophized?.takeIf { it == output }?.let {
            // A repaired apostrophe — or the lone "i" made "I" — is the
            // keyboard rewriting a word just as surely, and one backspace has
            // to take it back the same way (#402). Its undo is remembered
            // against the pair like any correction's, which is what keeps the
            // next space from repairing it straight back.
            RevertibleCommit(RevertibleCommit.Kind.AUTOCORRECT, original = fieldWord, committed = it)
        } ?: scriptFlip?.let {
            RevertibleCommit(
                RevertibleCommit.Kind.SCRIPT,
                original = if (it.to == PhoneticScript.LATIN) {
                    sentenceCasedLatin(scriptAlternate.orEmpty(), typed, state)
                } else {
                    scriptAlternate.orEmpty()
                },
                committed = output,
                script = it,
            )
        }
        lastRevertible = revertible
        if (corrected != null && revertible != null && revertible.kind == RevertibleCommit.Kind.AUTOCORRECT) {
            declinedSpots.fired(wordStart, revertible.original, revertible.committed)
            // Only the engine's own guesses: an apostrophe repair is a table,
            // not a judgement the gate could learn to make more carefully.
            //
            // The adaptive gate learns from the fired/reverted ratio, but not
            // yet: firing is not a verdict. The correction waits in the watch
            // until the text around it settles, and is counted then — with the
            // taps behind it, which a kept correction turns into evidence of
            // where this hand lands.
            judgeCorrections(
                correctionWatch.push(revertible.original, revertible.committed, taps, tapKeys),
            )
            recordStat { onAutocorrect(offer = false, System.currentTimeMillis()) }
            armRevertGuard()
        } else if (revertible != null) {
            armRevertGuard()
        }
        armUndoChip(ic, fieldText, fieldWord, corrected, obviousness, state)
        if (revertible != null && revertible.kind == RevertibleCommit.Kind.SCRIPT &&
            state.settings.suggestionStrip.undoCorrectionChip
        ) {
            // The same chip, offering the other script. No obviousness gate: a
            // script the keyboard picked for a word both languages have is
            // never obvious, which is what made it a flip in the first place.
            pushUndo(
                UndoableCorrection(
                    revertible.original, output, revertible.script, wordContext(ic, fieldText),
                ),
            )
        }
        // Armed before the commit lands so the strip refresh that follows it
        // publishes the chip; cleared here too, so a commit with no near miss
        // takes the previous word's offer down with it.
        correctionOfferFor = offered?.let { fieldWord }
        pendingCorrectionOffer = offered
        ic.commitText(
            if (revertible == null || revertible.kind == RevertibleCommit.Kind.SCRIPT) {
                output
            } else {
                // The mark covers the corrected word, not whatever the commit
                // glued after it.
                markAutoCorrection(output, revertible.original, revertible.committed.length)
            },
            1,
        )
        // An autocorrected word was the engine's choice, not the user's —
        // it earns no personal-dictionary reinforcement, only the bigram.
        // Conversion-IME output (Hanzi/Kanji) is never learned into the lexicon,
        // and neither is a fragment glued onto an existing word.
        if (!state.composer.isConversion && !gluedToWord) {
            // An autocorrected word is the engine's spelling, not the user's,
            // so it teaches no casing either — it arrives at reinforcement 0,
            // which already keeps it out of the lexicon.
            // The strip's other readings of the word, for the context
            // revision to weigh once the next word shows what was meant.
            suggestionEngine?.noteCommit(output, state.suggestions)
            learn(
                output,
                reinforcement = if (corrected != null) 0 else 1,
                caseTrusted = composingCaseTrusted && corrected == null,
                origin = if (duetGestures != null) WordOrigin.DUET else WordOrigin.TYPED,
                replaces = replaces,
                typed = typed,
                taps = taps,
                keys = tapKeys,
                unspelled = duetGestures?.complete == false,
            )
            duetGestures?.let { learnDuetGestures(output, it) }
        }
        composing = StringBuilder()
        // Where the caret now sits, for [onSpace]'s caps answer: known only
        // when the word's start was, and only for a word ending in a letter.
        plainCommitEnd = if (wordStart >= 0 && output.isNotEmpty() &&
            Character.isLetterOrDigit(output.codePointBefore(output.length))
        ) {
            wordStart + fieldForm(output, state).length
        } else {
            -1
        }
        // Whatever was resolving belonged to the word just committed.
        pendingResolution = null
        // Refill the strip in the same frame the word commits. Blanking it
        // and waiting for the async refresh left it empty for a frame or
        // two after every space, which read as a flicker.
        val (nextWords, nextEmojis) = nextWordStrip()
        _uiState.update {
            it.copy(
                composingPreview = "",
                suggestions = nextWords,
                emojiSuggestions = nextEmojis,
                autocorrectWord = null,
            )
        }
        return true
    }

    /**
     * Commits [text] and leaves the caret at [caret] inside it.
     *
     * Committing the head, then the tail with `newCursorPosition = 0`, parks
     * the caret between them: the contract puts a non-positive position at the
     * start of the text just inserted. Asking the editor where the text landed
     * instead costs a second blocking read and relies on arithmetic the
     * contract does not promise — a single-line field strips the newlines out
     * of a multi-line snippet on the way in, and the answer lands elsewhere.
     */
    private fun commitSplitAtCaret(ic: InputConnection, text: String, caret: Int) {
        val split = caret.coerceIn(0, text.length)
        val head = text.substring(0, split)
        // Chromium's address bar takes any edit that starts at offset 0 and
        // adds more than one character for a paste, and runs the paste
        // sanitiser over the whole field: `javascript:` is stripped and
        // whitespace collapsed (#471). An expansion into an empty address bar
        // is exactly that edit, so there the first character goes in on its
        // own and the rest lands at offset 1, the way typing would put it.
        val lead = if (_uiState.value.fieldKind == FieldKind.URI && head.length > 1) {
            head.offsetByCodePoints(0, 1).takeIf { it < head.length }
        } else {
            null
        }
        if (lead != null) {
            ic.commitText(head.substring(0, lead), 1)
            ic.commitText(head.substring(lead), 1)
        } else {
            ic.commitText(head, 1)
        }
        val tail = text.substring(split)
        if (tail.isEmpty()) return
        ic.commitText(tail, 0)
        parkCaretBeforeTail(ic, tail)
    }

    /**
     * Some editors take no notice of `newCursorPosition` and leave the caret
     * after whatever was committed (#471: Xed, FUTO Notes), so a `{cursor}`
     * marker landed at the end of the snippet. Checked once the tail is in:
     * when the caret is not in front of it but right behind it, it is walked
     * back by hand. Only on this path — a snippet with a marker — so the extra
     * reads cost nothing anywhere else, and nothing is moved unless the text
     * behind the caret is exactly the tail, which also leaves a field that
     * rewrote the text (a single-line box dropping newlines) alone.
     */
    private fun parkCaretBeforeTail(ic: InputConnection, tail: String) {
        val after = runCatching { ic.getTextAfterCursor(tail.length, 0)?.toString() }.getOrNull()
        if (after == null || after == tail) return
        val before = runCatching { ic.getTextBeforeCursor(tail.length, 0)?.toString() }.getOrNull()
        if (before != tail) return
        val extracted = runCatching {
            ic.getExtractedText(android.view.inputmethod.ExtractedTextRequest(), 0)
        }.getOrNull()
        if (extracted != null && extracted.selectionStart >= 0 && extracted.selectionStart == extracted.selectionEnd) {
            val at = extracted.startOffset + extracted.selectionStart - tail.length
            if (at >= 0 && ic.setSelection(at, at)) return
        }
        // No offsets to set: one left arrow per character of the tail.
        repeat(tail.codePointCount(0, tail.length)) { sendDownUpKeyEvents(KeyEvent.KEYCODE_DPAD_LEFT) }
    }

    /**
     * The state every snippet expansion leaves behind.
     *
     * An expansion is not typing. Nothing about it is learned — the text is
     * boilerplate, and [learn] would split a whole signature into words and
     * bigrams — and the strip is cleared rather than refilled, because with a
     * `{cursor}` marker the caret may be sitting in the middle of it. What it
     * must do is move the prediction context onto the text it inserted: the
     * word the strip was predicting from is no longer in the field at all.
     *
     * [original] is the text the expansion replaced, when one backspace should
     * be able to put it back, and null when the expansion cannot be undone.
     */
    private fun afterSnippetExpansion(inserted: String, original: String?, caretParked: Boolean) {
        // The buffer became boilerplate, not a spelling of anything.
        revision = null
        composing = StringBuilder()
        // In a password field (#555) the inserted text is a secret, and the
        // field has no strip to predict for anyway.
        setContextFrom(inserted.takeUnless { _uiState.value.secureField })
        invalidateRecentWords()
        commitResolution = null
        lastGestureWord = null
        // The caret moved with no onUpdateSelection echo yet, so the cached
        // selection would still answer for where it used to be.
        invalidateExpectedSelection()
        swallowTerminatorAfterCommit = caretParked
        lastRevertible = original
            ?.takeIf { inserted.length <= SNIPPET_REVERT_MAX }
            ?.let { RevertibleCommit(RevertibleCommit.Kind.SNIPPET, original = it, committed = inserted) }
        if (lastRevertible != null) armRevertGuard()
        _uiState.update {
            it.copy(composingPreview = "", suggestions = emptyList(), emojiSuggestions = emptyList(), octopus = emptyMap())
        }
    }

    /**
     * A trigger typed into a field where nothing composes (#471): a browser's
     * address bar asks for no suggestions, so its letters go straight into the
     * field and [commitComposing] never sees a word to match. The trigger is
     * read back off the field instead, when the space or Enter that ends it
     * lands. Returns true when it expanded one.
     *
     * Only where the buffer is off, so an ordinary text box keeps its one
     * matching path, and in a password field only when the user has turned
     * [SuggestionStripSettings.snippetsInSecureFields] on (#555). There the
     * Space that ended the trigger ([endedBySpace]) is spent on the expansion
     * rather than typed, since a space after it would land in the password;
     * Enter still fires the field's action. The read is skipped outright for
     * a user with no triggers.
     *
     * A field that composes gets this path for one shape only: a trigger
     * whose word opens with a digit (#554, #815). A word-initial digit commits
     * literally (`3pm`), so `123`, or the `1` of `#1` typed on the number pad,
     * never reaches the buffer and [commitComposing] has nothing to match;
     * every other trigger was already looked up there.
     *
     * In a number, phone, date or time field this is the only path, and a
     * snippet expands there only when its text is what the field takes
     * ([snippetFitsField]); one with letters in it is left as typed.
     */
    private fun tryUncomposedTrigger(
        ic: InputConnection,
        state: KeyboardUiState,
        endedBySpace: Boolean = false,
    ): Boolean {
        if (composing.isNotEmpty() || secureFieldRefusesSnippets(state) || state.nullField) return false
        if (state.composer.isTransliterating || state.composer.isConversion) return false
        val digitLedOnly = state.composesWords
        val prefixes = snippetStore.hasPrefixTriggers()
        if (digitLedOnly && !snippetStore.hasDigitLedTriggers() && !prefixes) return false
        if (snippetStore.expandingTriggers().isEmpty() && !prefixes) return false
        val read = ic.getTextBeforeCursor(UNCOMPOSED_TRIGGER_LOOKBACK, 0)?.toString() ?: return false
        val run = read.substring(read.indexOfLast { it.isWhitespace() } + 1)
        if (run.isEmpty()) return false
        // A trigger's word as the snippets index spells one, digits included,
        // so `#1` is the lead-in `#` and the word `1` (#815).
        val wordStart = run.indexOfLast { !SnippetMatcher.isTriggerWordChar(it) } + 1
        val word = run.substring(wordStart)
        // In a field that composes, the buffer already matched every trigger
        // whose word opens with a letter.
        if (digitLedOnly && word.firstOrNull()?.isDigit() != true) return false
        // The run as a plain trigger first, then its last word finishing a
        // prefix trigger (`:shrug`, `gr db`), the same order the buffer uses.
        val consumed: String
        val snippet: Snippet
        val plain = snippetStore.matchTrigger(run)?.takeIf { !snippetStore.offers(it) }
        if (plain != null) {
            consumed = run
            snippet = plain
        } else {
            if (!prefixes || word.isEmpty() || !snippetStore.couldFinishPrefix(word)) return false
            val before = read.substring(0, read.length - word.length)
            val hit = snippetStore.matchPrefix(word, before) ?: return false
            consumed = before.takeLast(hit.prefix.length) + word
            snippet = hit.snippet
        }
        val expanded = SnippetStore.expandWithCursor(
            snippet.text,
            context = snippetContext(ic),
            casing = SnippetStore.casingFor(snippet, consumed),
        )
        if (!snippetFitsField(expanded.text, state.fieldKind)) return false
        stopVoiceForManualInput()
        ic.beginBatchEdit()
        ic.deleteSurroundingText(consumed.length, 0)
        commitSplitAtCaret(ic, expanded.text, expanded.cursorOffset)
        ic.endBatchEdit()
        afterSnippetExpansion(
            inserted = expanded.text,
            original = consumed,
            caretParked = expanded.cursorOffset < expanded.text.length,
        )
        if (endedBySpace && state.secureField) swallowTerminatorAfterCommit = true
        return true
    }

    /**
     * Whether a password field keeps triggers out: always, unless the user
     * opted in with [SuggestionStripSettings.snippetsInSecureFields] (#555).
     * Only the two trigger shapes that consume nothing but what was just typed
     * ask this — [tryUncomposedTrigger] and [trySuffixExpansion]. Patterns,
     * the ask-first chips and the automation API keep their own refusals.
     */
    private fun secureFieldRefusesSnippets(state: KeyboardUiState): Boolean =
        state.secureField && !state.settings.suggestionStrip.snippetsInSecureFields

    /**
     * Expands a trigger that ends in the symbol just typed (#471): `js:` the
     * moment the colon lands, with "js" already committed in front of it.
     *
     * The counterpart of [tryPrefixExpansion] for the other end of a trigger.
     * A trigger's last character is what the keyboard can look up for free,
     * and a symbol is one the composing buffer never holds, so the lookup is
     * on the symbol itself and the rest is confirmed by reading the field
     * back, as the uncomposed path does. The read happens only once the index
     * has said a trigger ends in this symbol at all. Returns true when it
     * committed something.
     */
    private fun trySuffixExpansion(ic: InputConnection, typed: String, state: KeyboardUiState): Boolean {
        if (typed.length != 1 || secureFieldRefusesSnippets(state) || state.nullField) return false
        if (!snippetStore.hasSuffixTriggers() || !snippetStore.couldEndWith(typed[0])) return false
        val read = ic.getTextBeforeCursor(SnippetMatcher.MAX_PREFIX + 1, 0)?.toString() ?: return false
        if (!read.endsWith(typed)) return false
        val hit = snippetStore.matchSuffix(read)?.takeIf { !snippetStore.offers(it.snippet) } ?: return false
        // What the user actually typed, case included, is what is taken back
        // and what a revert puts back.
        val consumed = read.takeLast(hit.typed.length)
        stopVoiceForManualInput()
        val expanded = SnippetStore.expandWithCursor(
            hit.snippet.text,
            context = snippetContext(ic),
            casing = SnippetStore.casingFor(hit.snippet, consumed),
        )
        lastRevertible = null
        ic.beginBatchEdit()
        ic.deleteSurroundingText(consumed.length, 0)
        commitSplitAtCaret(ic, expanded.text, expanded.cursorOffset)
        ic.endBatchEdit()
        afterSnippetExpansion(
            inserted = expanded.text,
            original = consumed,
            caretParked = expanded.cursorOffset < expanded.text.length,
        )
        return true
    }

    /**
     * Expands a trigger set to fire on its own last keystroke
     * ([Snippet.immediate]) the moment [typed] finishes it: `btw`, `:sig` or
     * `;;addr`, with no space, punctuation or Enter after it. Returns true when
     * it changed the field.
     *
     * Called after the keystroke has landed, from both places a typed
     * character can land: the composing buffer and the plain commit. The
     * trigger is matched against the field rather than the buffer, because a
     * lead-in (`:`, `gr `) was committed before the word that ends it began,
     * and a field that composes nothing has no buffer at all. The read only
     * happens once the index has said, from [typed] and the buffer alone, that
     * this keystroke could finish one.
     *
     * Two ways to keep a trigger as typed. The escape character
     * ([SuggestionStripSettings.snippetEscape], a backslash by default) typed
     * in front of it stops it firing and is itself taken away, so `\btw` leaves
     * "btw". And one backspace straight after an expansion puts the trigger
     * back, through the same [RevertibleCommit] every expansion uses. Either
     * way the trigger then stands, since an immediate trigger is never looked
     * up again when the word ends.
     *
     * Same refusals as the other trigger paths: none while a composer is
     * spelling something else (transliteration, conversion, a phonetic or an
     * ambiguous board), and none in a password field unless the user allowed
     * snippets there.
     */
    private fun tryImmediateExpansion(ic: InputConnection, typed: String, state: KeyboardUiState): Boolean {
        if (typed.isEmpty() || !snippetStore.hasImmediateTriggers()) return false
        if (secureFieldRefusesSnippets(state) || state.nullField) return false
        if (state.composer.isTransliterating || state.composer.isConversion ||
            state.composer.phoneticLanguage != null || state.layouts.ambiguousKeys
        ) {
            return false
        }
        if (!snippetStore.couldFinishImmediate(typed.last(), composing)) return false
        // One character past the longest trigger: what stands in front of it
        // decides both the word boundary and the escape.
        val want = minOf(snippetStore.immediateReach(), IMMEDIATE_TRIGGER_LOOKBACK) + 1
        val read = ic.getTextBeforeCursor(want, 0)?.toString() ?: return false
        // A buffer the field does not show yet would be deleted from the wrong
        // place, so the field has to agree with it before anything is matched.
        if (composing.isNotEmpty() && !read.endsWith(composing)) return false
        val hit = snippetStore.matchImmediate(read) ?: return false
        val consumed = read.takeLast(hit.typed.length)
        val escape = state.settings.suggestionStrip.snippetEscape.firstOrNull()
        val ahead = read.getOrNull(read.length - consumed.length - 1)
        // A buffer reaching back past the trigger would reach past the escape
        // too, and that is a word the escape is inside, not one it stands before.
        if (escape != null && ahead == escape && composing.length <= consumed.length) {
            dropImmediateEscape(ic, consumed)
            return true
        }
        val expanded = SnippetStore.expandWithCursor(
            hit.snippet.text,
            context = snippetContext(ic),
            casing = SnippetStore.casingFor(hit.snippet, consumed),
        )
        if (!snippetFitsField(expanded.text, state.fieldKind)) return false
        stopVoiceForManualInput()
        lastRevertible = null
        ic.beginBatchEdit()
        // Same reason as [tryPatternExpansion]: a live composing region and
        // deleteSurroundingText disagree about which characters they mean.
        ic.finishComposingText()
        revision = null
        composing = StringBuilder()
        ic.deleteSurroundingText(consumed.length, 0)
        commitSplitAtCaret(ic, expanded.text, expanded.cursorOffset)
        ic.endBatchEdit()
        afterSnippetExpansion(
            inserted = expanded.text,
            original = consumed,
            // No terminator was typed, so there is none to swallow: the next
            // space is one the user means.
            caretParked = false,
        )
        publishSwapSet(
            snippet = hit.snippet,
            typed = consumed,
            inserted = expanded.text,
            insertedCaret = expanded.cursorOffset,
            original = consumed,
        )
        return true
    }

    /**
     * Takes the escape character in front of [consumed] out of the field and
     * leaves the trigger exactly as typed. A word still composing stays
     * composing, so the strip and the next letter carry on as if the escape
     * had never been there.
     */
    private fun dropImmediateEscape(ic: InputConnection, consumed: String) {
        val buffered = composing.toString()
        ic.beginBatchEdit()
        ic.finishComposingText()
        revision = null
        ic.deleteSurroundingText(consumed.length + 1, 0)
        ic.commitText(consumed.dropLast(buffered.length), 1)
        if (buffered.isNotEmpty()) ic.setComposingText(buffered, 1)
        ic.endBatchEdit()
        invalidateExpectedSelection()
        invalidateRecentWords()
        if (buffered.isNotEmpty()) refreshSuggestions()
    }

    /**
     * Expands the snippet whose trigger ends in [typed] but starts before it —
     * `:shrug` behind a run of punctuation, `gr db` behind an earlier word.
     * Returns true when it committed something.
     *
     * This is the path every Espanso package needs, and the path a multi-word
     * trigger needs. Espanso's convention puts a `:` or `;` in front of an
     * ordinary word, and the keyboard's composing buffer never holds one: the
     * punctuation was committed to the field the moment it was typed, and only
     * "shrug" is in the buffer when the space lands. The earlier words of
     * "gr db" are in the field for exactly the same reason. So the lookup is on
     * the buffer, and what comes in front of it is confirmed by reading back a
     * short span of the field.
     *
     * The gate is the same shape as [patternGateOpen]'s. A user with no such
     * trigger pays one map lookup on a string already in memory, and the read
     * only happens once that lookup has said a match is possible at all.
     */
    private fun tryPrefixExpansion(ic: InputConnection, typed: String): Boolean {
        if (typed.isEmpty() || !snippetStore.hasPrefixTriggers()) return false
        if (!snippetStore.couldFinishPrefix(typed)) return false
        // One character more than the longest lead-in, so the boundary check in
        // [SnippetIndex.matchPrefix] can see what sits in front of a lead-in
        // that fills the whole span.
        val want = SnippetMatcher.MAX_PREFIX + typed.length + 1
        val read = ic.getTextBeforeCursor(want, 0) ?: return false
        // The buffer is still composing, so the read ends with it. What sits in
        // front of that is what the lead-in has to match.
        val before = read.toString().removeSuffix(typed)
        if (before.length == read.length) return false
        val hit = snippetStore.matchPrefix(typed, before) ?: return false
        stopVoiceForManualInput()
        // Taken from the field rather than from the trigger: the lead-in
        // matched case-insensitively, so what has to be deleted — and what a
        // revert has to put back — is what the user actually typed.
        val consumed = before.takeLast(hit.prefix.length) + typed
        val expanded = SnippetStore.expandWithCursor(
            hit.snippet.text,
            context = snippetContext(ic),
            // The whole trigger as typed, not just its last word: "GR DB" is a
            // shout and "gr db" is not, and the buffer alone cannot tell them
            // apart from "Gr db".
            casing = SnippetStore.casingFor(hit.snippet, consumed),
        )
        ic.beginBatchEdit()
        // Same reason as [tryPatternExpansion]: a live composing region and
        // deleteSurroundingText disagree about which characters they mean.
        ic.finishComposingText()
        revision = null
        composing = StringBuilder()
        ic.deleteSurroundingText(consumed.length, 0)
        commitSplitAtCaret(ic, expanded.text, expanded.cursorOffset)
        ic.endBatchEdit()
        afterSnippetExpansion(
            inserted = expanded.text,
            original = consumed,
            caretParked = expanded.cursorOffset < expanded.text.length,
        )
        publishSwapSet(
            snippet = hit.snippet,
            typed = consumed,
            inserted = expanded.text,
            insertedCaret = expanded.cursorOffset,
            original = consumed,
        )
        return true
    }

    /**
     * Expands the pattern snippet that fits the words behind the cursor, if
     * there is one. Returns true when it committed something.
     *
     * The costly half of the gate lives here. Only once [patternGateOpen] has
     * said a match is even possible does this read the field, and that one read
     * does both jobs: it is what the match is measured against, and it refills
     * the gate's memory of recent words.
     *
     * The read is also the probe. Nothing before the batch edit has any effect
     * on the field, so a dead connection, an editor that answers null, or a
     * window that turns out not to match all fall through to the ordinary
     * literal commit.
     *
     * [typed] may be empty: a mark that ends a word calls this a second time
     * once the mark is in the field, with nothing composing, so a pattern
     * about the mark itself (`\s+([.,?!:;])`, which pulls a stray space back
     * out from in front of a full stop) gets to see it. The window then is
     * simply the text behind the caret.
     */
    private fun tryPatternExpansion(ic: InputConnection, typed: String, state: KeyboardUiState): Boolean {
        // Only the patterns that expand on their own are this path's business.
        // The ones that ask first are offered by [refreshSnippetOffer] while the
        // words are still being typed, and firing one here would answer for the
        // user instead of asking.
        if (!snippetStore.hasAutoPatterns()) return false
        // A pattern rewrites text the user already committed, and it runs a
        // regular expression the user (or an installed add-on) wrote over a
        // window of the field. Both are reasons to stay out of the fields the
        // keyboard keeps its hands off. The composing gate already excludes
        // them, but that is an accident of how composing works, not a decision.
        if (!state.allowsTypingIntelligence || state.secureField || state.fieldNoSuggestions) {
            return false
        }
        if (!patternGateOpen(typed)) return false
        val before = ic.getTextBeforeCursor(SnippetMatcher.MAX_WINDOW, 0) ?: return false
        // Composing text is part of the field's own text, so the window
        // normally ends with the word being committed. An editor that
        // disagrees gets it appended rather than losing the match.
        val window = if (before.endsWith(typed)) before.toString() else before.toString() + typed
        rebuildRecentWords(window.dropLast(typed.length))
        val hit = snippetStore.matchPattern(
            window = window,
            // A window that came back short is the whole field, so a match may
            // start at its first character. A full one may have been cut mid
            // word, and matching that half would delete text whose start the
            // user cannot see.
            atFieldStart = before.length < SnippetMatcher.MAX_WINDOW,
            context = snippetContext(ic, withSelection = false),
        ) ?: return false
        // Text a backspace just restored must not expand straight back.
        if (hit.consumedText == patternMutedAfter) return false
        ic.beginBatchEdit()
        // The composing region has to be finished before the delete. With one
        // alive, deleteSurroundingText skips the composing text and takes the
        // characters in front of it instead (BaseInputConnection), while
        // Compose's own editor does not skip it at all — the same call deletes
        // different characters in an EditText and in a BasicTextField.
        // Finishing first turns the word into plain committed text for both.
        ic.finishComposingText()
        revision = null
        composing = StringBuilder()
        ic.deleteSurroundingText(hit.consumedChars, 0)
        commitSplitAtCaret(ic, hit.text, hit.cursorOffset)
        ic.endBatchEdit()
        afterSnippetExpansion(
            inserted = hit.text,
            original = hit.consumedText,
            caretParked = hit.cursorOffset < hit.text.length,
        )
        publishSwapSet(
            snippet = hit.snippet,
            typed = null,
            inserted = hit.text,
            insertedCaret = hit.cursorOffset,
            original = hit.consumedText,
            match = hit,
        )
        patternFiredAtCommit = true
        return true
    }

    /**
     * Whether a pattern snippet could possibly match here, answered without
     * touching the input connection.
     *
     * A false answer is final. A true answer only buys the right to read the
     * field, so an untrustworthy ring answers true: a missed update then costs
     * one read rather than a feature that quietly stops working.
     */
    private fun patternGateOpen(typed: String): Boolean {
        if (!recentWordsValid) return true
        // There need not be a word in the buffer at all. The offer path asks
        // this question on every field entry and after every commit, when
        // nothing is composing, and a pattern that matches the words already in
        // the field is still a match — so an empty buffer only skips its own
        // half of the question rather than answering the whole of it.
        if (typed.isNotEmpty() && snippetStore.couldStartPattern(typed[0])) return true
        return recentWords.any { snippetStore.couldStartPattern(it[0]) }
    }

    /** Takes down whatever the strip was offering, if anything. */
    private fun clearSnippetOffer() {
        snippetOfferJob?.cancel()
        if (_uiState.value.snippetOffers != null) _uiState.update { it.copy(snippetOffers = null) }
    }

    /**
     * Takes down a set of swap chips, if that is what is up.
     *
     * Swap chips are about text already in the field rather than about the
     * composing buffer, so nothing re-derives them: they have to be taken down
     * by whatever changes the text they were talking about. Called from every
     * place that ends the backspace-revert window, which is the same set of
     * events for the same reason.
     */
    private fun clearSwapOffer() {
        if (_uiState.value.snippetOffers?.kind == SnippetOfferKind.SWAP) clearSnippetOffer()
    }

    /** Publishes [offers], or takes the chips down when it is null. */
    private fun publishSnippetOffer(offers: SnippetOfferSet?) {
        // The add-word chip answers through the same callback, so a snippet
        // offer arriving takes it down: whichever chip is up owns the answer.
        if (offers != null) clearLearnOffer()
        val current = _uiState.value.snippetOffers
        // A walk into a linked snippet survives the offer being derived again
        // for the same trigger. Without this, every refresh that lands on the
        // identical match — a selection echo, a debounced pattern job finishing
        // — would throw the user back to the top level mid-tap.
        val next = if (
            offers != null && current != null && current.path.isNotEmpty() &&
            current.kind == offers.kind && current.rootId == offers.rootId &&
            current.consumed == offers.consumed && current.rootChips == offers.rootChips
        ) {
            offers.copy(path = current.path, chips = current.chips)
        } else {
            offers
        }
        if (current != next) _uiState.update { it.copy(snippetOffers = next) }
    }

    /** A candidate as the strip draws it. */
    private fun chipOf(candidate: SnippetCandidate): SnippetChip = SnippetChip(
        snippetId = candidate.snippetId,
        label = candidate.label,
        text = candidate.text,
        cursorOffset = candidate.cursorOffset,
        drillable = candidate.drillable,
    )

    /**
     * What [snippet] has to offer here: its own expansions and the default
     * expansion of everything it links to, expanded against this field.
     *
     * [match] is a pattern hit, whose captures every expansion is templated
     * with and whose own text is kept verbatim for the first candidate; [typed]
     * is the trigger as it was actually typed, which decides the casing.
     */
    private fun snippetCandidates(
        snippet: Snippet,
        typed: String? = null,
        match: SnippetMatch? = null,
        withSelection: Boolean = false,
    ): List<SnippetCandidate> {
        val context = snippetContext(currentInputConnection, withSelection = withSelection)
        return if (match != null) {
            snippetStore.candidates(match, context = context)
        } else {
            snippetStore.candidates(snippet, typed = typed, context = context)
        }
    }

    /**
     * The chips for a snippet that matched but inserted nothing, or null when
     * it has nothing to say.
     *
     * [consumed] is what taking a chip takes back out of the field, and
     * [composed] whether that is exactly the word still being composed. See
     * [SnippetOfferSet].
     */
    private fun pickSet(
        snippet: Snippet,
        typed: String?,
        consumed: String,
        composed: Boolean,
        match: SnippetMatch? = null,
    ): SnippetOfferSet? {
        val chips = snippetCandidates(snippet, typed, match).map(::chipOf)
        if (chips.isEmpty()) return null
        return SnippetOfferSet(
            kind = SnippetOfferKind.PICK,
            rootId = snippet.id,
            rootLabel = snippet.label,
            consumed = consumed,
            composed = composed,
            rootChips = chips,
        )
    }

    /**
     * Offers the rest of what a snippet had to say, after its first expansion
     * has already replaced the trigger.
     *
     * Only when there is more than one thing: a snippet with a single expansion
     * behaves exactly as it always has, right down to leaving the strip alone.
     * The same gates as the ask-first chip apply — a field that wanted a quiet
     * strip does not get chips just because an expansion fired in it.
     */
    @Suppress("LongParameterList")
    private fun publishSwapSet(
        snippet: Snippet,
        typed: String?,
        inserted: String,
        insertedCaret: Int,
        original: String?,
        match: SnippetMatch? = null,
    ) {
        val state = _uiState.value
        if (!snippetChipField(state) || state.secureField || state.fieldNoSuggestions ||
            state.panel != PanelMode.NONE
        ) {
            return
        }
        val candidates = snippetCandidates(snippet, typed, match)
        if (candidates.size < 2) return
        publishSnippetOffer(
            SnippetOfferSet(
                kind = SnippetOfferKind.SWAP,
                rootId = snippet.id,
                rootLabel = snippet.label,
                inserted = inserted,
                insertedCaret = insertedCaret.coerceIn(0, inserted.length),
                original = original,
                current = candidates.indexOfFirst { it.text == inserted },
                rootChips = candidates.map(::chipOf),
            ),
        )
        // The chips outlive the commit's own selection echo, so the window that
        // tells an echo from a real caret move has to be open for them too.
        armRevertGuard()
    }

    /**
     * Whether the field is one a snippet's chips may sit over: a text field,
     * or a browser's address bar (#471). The address bar composes once the
     * strip is on it ([KeyboardUiState.composesWords]), and a trigger
     * that asks first expands there the moment it is let in, as one that does
     * not ask already did. Asking only [KeyboardUiState.allowsTypingIntelligence]
     * left those triggers dead in every address bar: no chip, and no expansion
     * either, since asking is what holds the expansion back.
     */
    private fun snippetChipField(state: KeyboardUiState): Boolean =
        state.allowsTypingIntelligence || (state.fieldKind == FieldKind.URI && !state.secureField)

    /**
     * Offers whatever snippet the text in front of the cursor matches, when
     * that snippet asks before it expands.
     *
     * This is derived state, recomputed from the field rather than remembered
     * from a commit, and that is what makes the chip arrive when the trigger is
     * typed instead of when the space is. Type "hello Jo" and the offer is
     * already there, reading "Hello, Jo!"; the next letter re-derives it. There
     * is nothing to keep in sync and nothing to go stale — an edit, a caret
     * jump, a change made from outside the keyboard all end up back here.
     *
     * Two gates keep it off the typing path for everyone else. A user with no
     * asking snippets does no work at all, and a plain trigger is answered by a
     * map lookup with no round-trip. Only an asking *pattern* costs a read of
     * the field, and that one is debounced onto a worker the way the smart chip
     * is, because it happens on every keystroke rather than once a word.
     */
    private fun refreshSnippetOffer(state: KeyboardUiState) {
        // Swap chips are about text that is already in the field, so they are
        // not derived from the buffer and must not be taken down by a pass over
        // it — the space that fired the expansion calls straight through here a
        // line later. [clearSwapOffer] is what ends them.
        if (_uiState.value.snippetOffers?.kind == SnippetOfferKind.SWAP) return
        snippetOfferJob?.cancel()
        // The chip needs a strip to sit on, so a field that asked for a quiet
        // one gets neither the offer nor the expansion behind it. Same fields
        // [tryPatternExpansion] stays out of, for the same reason. A composing
        // buffer holding an input spelling (Avro, Pinyin) is not a trigger and
        // not a word a pattern can read.
        // The number pad over a text field still has the strip (#815).
        val allowed = snippetChipField(state) && !state.secureField &&
            !state.fieldNoSuggestions && (state.panel == PanelMode.NONE || state.panel == PanelMode.NUMPAD) &&
            !state.composer.isTransliterating && !state.composer.isConversion
        if (!allowed) {
            publishSnippetOffer(null)
            return
        }
        val typed = composing.toString()
        val trigger = typed
            .takeIf { it.isNotEmpty() && snippetStore.hasConfirmTriggers() }
            ?.let { snippetStore.matchTrigger(it) }
            ?.takeIf { snippetStore.offers(it) }
        // A prefix trigger sits between the two: the lookup is free like a plain
        // trigger's, but confirming what sits in front of the buffer costs the
        // same read a pattern does. So it rides the same debounced job.
        val wantPrefix = typed.isNotEmpty() && snippetStore.hasConfirmPrefixTriggers() &&
            snippetStore.couldFinishPrefix(typed)
        // Most specific first, the same order the commit path uses: a trigger
        // that reaches back past the buffer outranks a plain one that happens
        // to be its last word. Only once no such trigger is possible can a
        // plain match answer without a read.
        if (trigger != null && !wantPrefix) {
            // The selection is not worth a blocking round-trip on the typing
            // path: a word only composes with the caret collapsed.
            publishSnippetOffer(pickSet(trigger, typed, consumed = typed, composed = true))
            return
        }
        // Not in a browser's address bar: a pattern that expands on its own
        // stays out of one ([tryPatternExpansion]), and one that asks first
        // keeps to the same fields.
        val wantPattern = state.allowsTypingIntelligence && snippetStore.hasConfirmPatterns() &&
            patternGateOpen(typed)
        if (!wantPrefix && !wantPattern) {
            publishSnippetOffer(null)
            return
        }
        val ic = currentInputConnection
        if (ic == null) {
            // No read is possible, so nothing can outrank the plain match that
            // was held back above. It still stands on the buffer alone.
            publishSnippetOffer(
                trigger?.let { pickSet(it, typed, consumed = typed, composed = true) },
            )
            return
        }
        // A trigger's offer is about the buffer, and the buffer has just
        // changed into something that is not that trigger, so it goes now
        // rather than after the read. A pattern's offer is left up until the
        // read answers: it usually still matches, and blanking it first is a
        // chip that blinks on every keystroke. Not when a plain match is
        // waiting on the read to see whether something beats it: that chip is
        // about the buffer that is still there, and taking it down would make
        // it blink once a keystroke.
        if (_uiState.value.snippetOffers?.composed == true && trigger == null) {
            publishSnippetOffer(null)
        }
        snippetOfferJob = serviceScope.launch {
            // Debounced ahead of the read, for the reason spelled out in
            // [refreshSmartSuggestion]: one keystroke reaches here twice, and
            // sleeping first means the second scheduling cancels the first
            // while it is still asleep rather than after it has already paid
            // for a round-trip into the app being typed into.
            delay(SNIPPET_OFFER_DEBOUNCE_MS)
            val window = withContext(Dispatchers.Default) {
                ic.getTextBeforeCursor(SnippetMatcher.MAX_WINDOW, 0)?.toString()
            }
            if (window == null) {
                publishSnippetOffer(
                    trigger?.let { pickSet(it, typed, consumed = typed, composed = true) },
                )
                return@launch
            }
            // The gate was read before the sleep; a panel opening or a field
            // turning out to be secure does not cancel this job.
            val still = _uiState.value
            if ((still.panel != PanelMode.NONE && still.panel != PanelMode.NUMPAD) || still.secureField ||
                still.fieldNoSuggestions
            ) {
                publishSnippetOffer(null)
                return@launch
            }
            // An expansion may have fired while this was asleep; its chips are
            // about text in the field and this job's answer is about a buffer
            // that no longer exists.
            if (still.snippetOffers?.kind == SnippetOfferKind.SWAP) return@launch
            // The prefix trigger goes first, for the same reason it does on the
            // commit path: it is the more specific rule.
            if (wantPrefix) {
                val before = window.removeSuffix(typed)
                val prefix = if (before.length == window.length) {
                    null
                } else {
                    snippetStore.matchPrefix(typed, before, confirm = true)
                }
                if (prefix != null) {
                    // From the field, not from the trigger: the lead-in matched
                    // case-insensitively, so this is what accepting deletes.
                    val consumed = before.takeLast(prefix.prefix.length) + typed
                    publishSnippetOffer(
                        pickSet(
                            snippet = prefix.snippet,
                            typed = consumed,
                            // Not `composed`: the span reaches back past the
                            // buffer over text the editor already has, so
                            // accepting has to find and delete it the way a
                            // pattern's offer does rather than just replace the
                            // composing region.
                            consumed = consumed,
                            composed = false,
                        ),
                    )
                    return@launch
                }
            }
            // No trigger reached back past the buffer after all, so the plain
            // match held back above gets its turn.
            if (trigger != null) {
                publishSnippetOffer(pickSet(trigger, typed, consumed = typed, composed = true))
                return@launch
            }
            if (!wantPattern) {
                publishSnippetOffer(null)
                return@launch
            }
            // The space that ends a word is already in the field by the time
            // anyone can tap, and `(.+)` would swallow it into the capture. The
            // match is made against the text without it; [onSnippetOfferAccept]
            // finds the same trailing run again and puts it back.
            val hit = snippetStore.matchPattern(
                window = window.trimEnd(),
                atFieldStart = window.length < SnippetMatcher.MAX_WINDOW,
                context = snippetContext(ic, withSelection = false),
                confirm = true,
            )
            publishSnippetOffer(
                hit?.let {
                    pickSet(
                        snippet = it.snippet,
                        typed = null,
                        consumed = it.consumedText,
                        composed = false,
                        match = it,
                    )
                },
            )
        }
    }

    /**
     * The app behind the phone's autofill service (#1003), by its label, when
     * there is one with a screen to open and the chip is on. Read at the start
     * of a password field, off the settings and the package manager alone.
     */
    private fun passwordManagerApp(): String? {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.P) return null
        if (!_uiState.value.settings.suggestionSources.passwordManagerChip) return null
        val pkg = passwordManagerPackage() ?: return null
        return runCatching {
            packageManager.getApplicationLabel(packageManager.getApplicationInfo(pkg, 0)).toString()
        }.getOrNull()
    }

    private fun passwordManagerPackage(): String? {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.P) return null
        val service = runCatching {
            getSystemService(android.view.autofill.AutofillManager::class.java)?.autofillServiceComponentName
        }.getOrNull() ?: return null
        return service.packageName.takeIf { packageManager.getLaunchIntentForPackage(it) != null }
    }

    /**
     * The chip was tapped (#1003): the manager's app opens over this one, to
     * unlock and copy a password. What it copies comes back on the strip's
     * paste chip, and a copy made in a password field stays masked there.
     */
    private fun openPasswordManager() {
        val pkg = passwordManagerPackage() ?: return
        val launch = packageManager.getLaunchIntentForPackage(pkg) ?: return
        vibrate()
        runCatching { startActivity(launch.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)) }
    }

    /**
     * An ask-first chip on the strip was answered.
     *
     * One entry point for all of them — the snippet offer, the add-word offer,
     * the sandbox offer and the missing-word-list chip — picked apart by state here rather than by more
     * parameters on [ui.KeyboardScreen], whose argument list already compiles
     * to a method at the JVM's 64K ceiling. They never share the strip: the
     * chip that is up is the one this answers, and the UI renders them in this
     * same order of precedence.
     */
    fun onStripOfferAction(action: StripOfferAction) {
        if (action == StripOfferAction.ToggleAnsi) {
            onAnsiOutputToggle()
            return
        }
        if (action == StripOfferAction.ToggleZawgyi) {
            onZawgyiOutputToggle()
            return
        }
        if (action == StripOfferAction.ToggleTraditional) {
            onTraditionalOutputToggle()
            return
        }
        if (action == StripOfferAction.OpenPasswordManager) {
            openPasswordManager()
            return
        }
        if (action == StripOfferAction.DismissPasswordManager) {
            _uiState.update { it.copy(passwordManagerApp = null) }
            return
        }
        if (_uiState.value.learnOffer != null) {
            when (action) {
                is StripOfferAction.Accept -> acceptLearnOffer()
                StripOfferAction.Decline -> declineLearnOffer()
                // The add-word chip has nothing to walk into.
                else -> Unit
            }
            return
        }
        if (_uiState.value.sandboxOffer != null) {
            when (action) {
                is StripOfferAction.Accept -> acceptSandboxOffer()
                StripOfferAction.Decline -> declineSandboxOffer()
                // The chip stays up: the user comes back to answer it.
                StripOfferAction.Explain -> openSetting(SANDBOX_SETTING)
                // Nor has the sandbox chip.
                else -> Unit
            }
            return
        }
        // Behind the snippet offer, which the strip shows in its place.
        if (_uiState.value.snippetOffers == null && _uiState.value.glideWordListOffer != null) {
            when (action) {
                is StripOfferAction.Accept -> acceptGlideWordListOffer()
                StripOfferAction.Decline -> clearGlideWordListOffer()
                else -> Unit
            }
            return
        }
        // The other download chip, and it cannot share the strip with the one
        // above: that one is only ever raised for a composer that does not
        // convert, this one only for one that does.
        if (_uiState.value.conversionPackOffer != null) {
            when (action) {
                is StripOfferAction.Accept -> acceptConversionPackOffer()
                StripOfferAction.Decline -> clearConversionPackOffer()
                else -> Unit
            }
            return
        }
        // Last of the chips: it is about a word already in the field, so
        // anything asking about what is being typed right now comes first.
        _uiState.value.glideSearchChip?.let { word ->
            _uiState.update { it.copy(glideSearchChip = null) }
            when (action) {
                // Down on the tap, not when the search lands: the deep decode
                // takes long enough to look ignored.
                is StripOfferAction.Accept -> searchAllWordsForCaretWord(word)
                else -> Unit
            }
            return
        }
        // Behind the snippet offer, which the strip shows in its place, and
        // after every chip about the word being typed.
        val zawgyiOffer = _uiState.value.zawgyiOffer
        if (_uiState.value.snippetOffers == null && zawgyiOffer != null) {
            when (action) {
                is StripOfferAction.Accept -> acceptZawgyiOffer(zawgyiOffer)
                StripOfferAction.Decline -> clearZawgyiOffer()
                else -> Unit
            }
            return
        }
        when (action) {
            is StripOfferAction.Accept -> onSnippetOfferPick(action.index)
            is StripOfferAction.Drill -> onSnippetOfferDrill(action.index)
            StripOfferAction.Back -> onSnippetOfferBack()
            StripOfferAction.Decline -> clearSnippetOffer()
            StripOfferAction.Explain -> Unit
            StripOfferAction.ToggleAnsi, StripOfferAction.ToggleZawgyi, StripOfferAction.ToggleTraditional,
            StripOfferAction.OpenPasswordManager, StripOfferAction.DismissPasswordManager,
            -> Unit
        }
    }

    /**
     * Puts the Zawgyi chip up for pasted [text] when it is Zawgyi beyond doubt
     * and the field is not being written in Zawgyi anyway: pasted into a
     * Unicode field it reads as garbage, and converting it is one tap.
     */
    private fun offerZawgyiForPaste(text: String) {
        if (outputEncoding == OutputEncoding.ZawgyiOutput) return
        if (text.length > MAX_ZAWGYI_PASTE || !Zawgyi.hasMyanmar(text)) return
        if (!Zawgyi.isConfidentlyZawgyi(text)) return
        _uiState.update { it.copy(zawgyiOffer = ZawgyiOffer.Pasted(text)) }
    }

    /**
     * The text before the caret as the engine should read it. While the field
     * is written in Zawgyi it holds glyph order, so it is turned back into the
     * Unicode the user typed, or prediction reads every word as a misspelling.
     * A Burmese field found to be in Zawgyi already, typed by someone else or
     * before the keyboard, is read the same way, and asked about once: the
     * strip offers to write Zawgyi here too.
     */
    private fun readableContext(before: CharSequence?): CharSequence? {
        if (before != null && fancyOutputStyle(_uiState.value) != null) return FancyStyles.unstyle(before)
        if (before == null || !Zawgyi.hasMyanmar(before)) return before
        val text = before.toString()
        // A field written in Zawgyi can still hold Unicode from before the
        // button went on, so it is only read back when it leans Zawgyi.
        if (outputEncoding == OutputEncoding.ZawgyiOutput) {
            return if (Zawgyi.probability(text) > 0.5) Zawgyi.toUnicode(text) else before
        }
        if (_uiState.value.language.id != "my") return before
        if (!Zawgyi.isConfidentlyZawgyi(text)) return before
        if (!zawgyiFieldOffered && !_uiState.value.secureField) {
            zawgyiFieldOffered = true
            _uiState.update { it.copy(zawgyiOffer = ZawgyiOffer.Field) }
        }
        return Zawgyi.toUnicode(text)
    }

    /**
     * The Zawgyi chip was tapped. Pasted text is replaced with its Unicode,
     * provided it is still right behind the caret; a field found in Zawgyi is
     * written in Zawgyi from here on, until the field is left.
     */
    private fun acceptZawgyiOffer(offer: ZawgyiOffer) {
        vibrate()
        clearZawgyiOffer()
        when (offer) {
            is ZawgyiOffer.Pasted -> {
                val ic = currentInputConnection ?: return
                commitComposing(ic, autocorrect = false)
                val before = ic.getTextBeforeCursor(offer.text.length, 0)?.toString()
                if (before != offer.text) {
                    Toast.makeText(this, getString(R.string.ime_zawgyi_paste_moved_toast), Toast.LENGTH_SHORT).show()
                    return
                }
                ic.beginBatchEdit()
                ic.deleteSurroundingText(offer.text.length, 0)
                ic.commitText(Zawgyi.toUnicode(offer.text), 1)
                ic.endBatchEdit()
            }
            ZawgyiOffer.Field -> {
                currentInputConnection?.let { commitComposing(it, autocorrect = false) }
                zawgyiField = true
                syncLegacyOutput(_uiState.value.settings, activeLayoutSpec(_uiState.value.settings))
                Toast.makeText(this, getString(R.string.ime_zawgyi_field_toast), Toast.LENGTH_SHORT).show()
            }
        }
    }

    /** Takes the Zawgyi chip down, answered or overtaken by typing. */
    private fun clearZawgyiOffer() {
        if (_uiState.value.zawgyiOffer != null) _uiState.update { it.copy(zawgyiOffer = null) }
    }

    /**
     * Puts the add-word chip on the strip for [word].
     *
     * Only ever reached with `askBeforeLearning` on. The offer is about the
     * word that was just committed, so a newer one replaces it outright: the
     * chip follows the typing rather than queueing up behind it.
     */
    private fun offerToLearn(word: String, caseTrusted: Boolean) {
        if (learnOfferWord == word) return
        learnOfferWord = word
        learnOfferCaseTrusted = caseTrusted
        // The two ask-first chips answer through the same callback, so only one
        // of them may be up at a time.
        clearSnippetOffer()
        _uiState.update { it.copy(learnOffer = word) }
    }

    /** Takes the add-word chip down, whether or not it was answered. */
    private fun clearLearnOffer() {
        learnOfferWord = null
        learnOfferCaseTrusted = false
        if (_uiState.value.learnOffer != null) _uiState.update { it.copy(learnOffer = null) }
    }

    /** "Yes, that is a word": into the dictionary at full strength. */
    private fun acceptLearnOffer() {
        val word = _uiState.value.learnOffer ?: return
        val trusted = learnOfferCaseTrusted
        vibrate()
        clearLearnOffer()
        pendingLearn.forget(word)
        // addWord, not learnWord: the user was asked outright and said yes, so
        // the word competes with real vocabulary immediately and is never
        // corrected away.
        // The chip shows the word as it was committed, which at a sentence
        // start means auto-capitalize's capital rather than the user's. Saying
        // yes to that is a vote for the word, never for the capital — so an
        // untrusted spelling is filed in lower case (#44), where a later
        // deliberate "Boston" can still teach it.
        val spelling = if (trusted) word else word.lowercase()
        // Answered by hand, so the commit that finishes the word adds nothing
        // to it — see [handAddedWord] (#115).
        handAddedWord = WordKey.of(word)
        userLexicon.addWord(spelling, caseEvidence = trusted)
        if (_uiState.value.settings.addWordsToSystemDictionary) {
            serviceScope.launch(Dispatchers.IO) {
                SystemUserDictionary.add(applicationContext, spelling)
            }
        }
        refreshSuggestions()
    }

    /** "No": drop it and stop asking about that word. */
    private fun declineLearnOffer() {
        val word = _uiState.value.learnOffer ?: return
        vibrate()
        clearLearnOffer()
        pendingLearn.decline(word)
    }

    /**
     * Inserts the offer the strip was showing.
     *
     * A trigger's offer replaces the composing region, which is what an
     * ordinary [InputConnection.commitText] does anyway. A pattern's offer has
     * to find its span again, since it reaches back over words the editor has
     * already taken, and the key that ended the last one may have landed since.
     * Both are put back on a backspace, exactly as an expansion that fired on
     * its own is.
     *
     * Either way the offer is checked against the field before anything is
     * edited. It is derived state, refreshed a frame behind the keystrokes, so
     * a tap can always land just after the text it was about stopped being
     * there — and an expansion that deletes the wrong span is far worse than
     * one that does nothing.
     */
    fun onSnippetOfferPick(index: Int) {
        val offers = _uiState.value.snippetOffers ?: return
        val chip = offers.visibleChips().getOrNull(index) ?: return
        when (offers.kind) {
            SnippetOfferKind.PICK -> onSnippetOfferAccept(offers, chip)
            SnippetOfferKind.SWAP -> onSnippetSwap(offers, chip)
        }
    }

    /**
     * Shows what the linked snippet behind the chip at [index] has to offer.
     *
     * Bounded by the walk itself: a snippet already on the path is not entered
     * again, so a loop in the graph is a dead end rather than an endless one.
     */
    private fun onSnippetOfferDrill(index: Int) {
        val offers = _uiState.value.snippetOffers ?: return
        val chip = offers.visibleChips().getOrNull(index) ?: return
        if (!chip.drillable || !offers.canDrill(chip.snippetId)) return
        val chips = snippetStore
            .drillIn(chip.snippetId, context = snippetContext(currentInputConnection, false))
            .map(::chipOf)
        if (chips.isEmpty()) return
        vibrate()
        _uiState.update {
            it.copy(
                snippetOffers = offers.copy(path = offers.path + chip.snippetId, chips = chips),
            )
        }
    }

    /** Goes back up one level of a walk into linked snippets. */
    private fun onSnippetOfferBack() {
        val offers = _uiState.value.snippetOffers ?: return
        if (offers.path.isEmpty()) return
        val path = offers.path.dropLast(1)
        val chips = if (path.isEmpty()) {
            offers.rootChips
        } else {
            snippetStore
                .drillIn(path.last(), context = snippetContext(currentInputConnection, false))
                .map(::chipOf)
                .ifEmpty { offers.rootChips }
        }
        vibrate()
        _uiState.update { it.copy(snippetOffers = offers.copy(path = path, chips = chips)) }
    }

    /**
     * Replaces the expansion already in the field with another of the ones the
     * same trigger offered.
     *
     * The text is verified before anything is edited, exactly as the ask-first
     * path verifies its span and for the same reason: the chips outlive the
     * commit by design, so a tap can land after the field has moved on. What
     * this puts in inherits the undo the expansion had, so backspace still
     * restores the trigger rather than the expansion it replaced.
     */
    private fun onSnippetSwap(offers: SnippetOfferSet, chip: SnippetChip) {
        val ic = currentInputConnection ?: return
        val head = offers.inserted.take(offers.insertedCaret)
        val rest = offers.inserted.drop(offers.insertedCaret)
        val tail = if (rest.isEmpty()) {
            val before = ic
                .getTextBeforeCursor(SNIPPET_REVERT_MAX + SNIPPET_OFFER_TAIL_MAX, 0)
                ?.toString()
                .orEmpty()
            val at = before.lastIndexOf(offers.inserted)
            // Nothing may sit between the expansion and the cursor but the key
            // that ended the word it replaced.
            before
                .takeIf { at >= 0 }
                ?.substring(at + offers.inserted.length)
                ?.takeIf { it.length <= SNIPPET_OFFER_TAIL_MAX && it.none(Char::isLetterOrDigit) }
                ?: run {
                    clearSnippetOffer()
                    return
                }
        } else {
            // The caret is parked inside the expansion, so the text straddles
            // it and both halves have to still be there.
            val before = ic.getTextBeforeCursor(head.length, 0)?.toString().orEmpty()
            val after = ic.getTextAfterCursor(rest.length, 0)?.toString().orEmpty()
            if (before != head || after != rest) {
                clearSnippetOffer()
                return
            }
            ""
        }
        stopVoiceForManualInput()
        vibrate()
        val inserted = chip.text + tail
        val marker = chip.cursorOffset.takeIf { it < chip.text.length }
        ic.beginBatchEdit()
        ic.finishComposingText()
        revision = null
        composing = StringBuilder()
        ic.deleteSurroundingText(head.length + tail.length, rest.length)
        commitSplitAtCaret(ic, inserted, marker ?: inserted.length)
        ic.endBatchEdit()
        afterSnippetExpansion(
            inserted = inserted,
            original = offers.original?.let { it + tail },
            caretParked = false,
        )
        // Republished rather than taken down: the other expansions are still
        // what this trigger had to say, and one wrong tap should be one tap
        // from being right again.
        publishSnippetOffer(
            offers.copy(
                inserted = inserted,
                insertedCaret = marker ?: inserted.length,
                original = offers.original,
                current = offers.rootChips.indexOfFirst { it.text == chip.text },
                path = emptyList(),
                chips = offers.rootChips,
            ),
        )
        armRevertGuard()
    }

    private fun onSnippetOfferAccept(offers: SnippetOfferSet, chip: SnippetChip) {
        val offer = offers
        val ic = currentInputConnection ?: return
        val tail = if (offer.composed) {
            // The buffer is the span. Nothing follows it — a terminator would
            // have committed it — so the only question is whether it is still
            // the word the chip was offering for.
            if (composing.toString() != offer.consumed) {
                clearSnippetOffer()
                return
            }
            ""
        } else {
            val before = ic
                .getTextBeforeCursor(SnippetMatcher.MAX_WINDOW + SNIPPET_OFFER_TAIL_MAX, 0)
                ?.toString()
                .orEmpty()
            val at = before.lastIndexOf(offer.consumed)
            // The span has to still be in front of the cursor with nothing
            // behind it but the key that ended the word: the space the match
            // was made without, or a full stop and its space.
            before
                .takeIf { at >= 0 }
                ?.substring(at + offer.consumed.length)
                ?.takeIf { it.length <= SNIPPET_OFFER_TAIL_MAX && it.none(Char::isLetterOrDigit) }
                ?: run {
                    clearSnippetOffer()
                    return
                }
        }
        stopVoiceForManualInput()
        vibrate()
        val inserted = chip.text + tail
        val original = offer.consumed + tail
        // With no marker in it the caret belongs after everything this puts in,
        // the trailing space included; a marker is an instruction about where
        // inside the snippet's own text to stop.
        val marker = chip.cursorOffset.takeIf { it < chip.text.length }
        ic.beginBatchEdit()
        if (!offer.composed) {
            // Same reason as [tryPatternExpansion]: a live composing region and
            // deleteSurroundingText disagree about which characters they mean.
            // A pattern's span ends in the word still being typed, so there
            // usually is one.
            ic.finishComposingText()
            revision = null
            composing = StringBuilder()
            ic.deleteSurroundingText(offer.consumed.length + tail.length, 0)
        }
        commitSplitAtCaret(ic, inserted, marker ?: inserted.length)
        ic.endBatchEdit()
        afterSnippetExpansion(
            inserted = inserted,
            original = original,
            // Nothing to swallow: this expansion was tapped, so no terminator
            // key is on its way in behind it.
            caretParked = false,
        )
        clearSnippetOffer()
    }

    /**
     * Flushes a conversion buffer whole: repeatedly commits the top candidate
     * for what remains and drops the input chars it consumed, until the buffer
     * is empty. A reading with no dictionary match commits raw (consuming all),
     * so the loop always terminates; the guard is a belt-and-braces backstop.
     * Used by every non-space commit path — the space bar goes one step at a
     * time through [commitConversionPrefix].
     */
    private fun flushConversion(ic: InputConnection) {
        readingCaret = -1
        val composer = _uiState.value.composer
        var guard = 0
        var converted = false
        while (composing.isNotEmpty() && guard++ < 64) {
            val buf = composing.toString()
            val top = composer.candidates(buf).firstOrNull()
            val chosen = top?.let { composer.committedText(buf, 0, it) } ?: composer.composeBuffer(buf)
            val consumed = if (top != null) {
                composer.consumedForIndex(buf, 0)
            } else {
                composer.consumedFor(buf, chosen)
            }.coerceIn(1, composing.length)
            ic.commitText(chosen, 1)
            composing.delete(0, consumed)
            val rest = composer.remainderAfterCommit(composing.toString())
            if (rest.length != composing.length) composing = StringBuilder(rest)
            if (top != null) {
                CjkContext.committed(chosen)
                rememberConversion(chosen, buf.substring(0, consumed))
            } else {
                CjkContext.before = ""
            }
            converted = top != null
        }
        afterConversionFlushed(predict = converted)
    }

    /** Enter's side of a conversion reading: commits [Composer.typedReading] whole. */
    private fun commitConversionAsTyped(ic: InputConnection) {
        ic.commitText(_uiState.value.composer.typedReading(composing.toString()), 1)
        consumeShift()
        CjkContext.before = ""
        afterConversionFlushed()
    }

    /**
     * What the conversion composer offers after [context] (联想), under the
     * strip's own gates: unlike the candidates, these are suggestions. Kept
     * in [conversionPredictions] with the context they answer, so a tap on
     * one is recognised as a prediction and not a stale candidate.
     */
    private fun conversionPredictions(context: String): List<String> {
        val state = _uiState.value
        if (!state.composer.isConversion || context.isEmpty() && !state.composer.predictsFromAnyText) {
            return clearConversionPredictions()
        }
        if (!state.settings.suggestions || state.secureField || state.fieldNoSuggestions ||
            !state.allowsTypingIntelligence
        ) {
            return clearConversionPredictions()
        }
        val words = state.composer.predictions(context, state.settings.suggestionStrip.slotCount.coerceAtLeast(CONVERSION_PREDICTIONS))
        conversionPredictions = context to words
        return words
    }

    private fun clearConversionPredictions(): List<String> {
        conversionPredictions = null
        return emptyList()
    }

    /** The context the strip's predictions answer, and the predictions. */
    private var conversionPredictions: Pair<String, List<String>>? = null

    /**
     * Conversions committed into this field lately, oldest first: what went
     * in, and the reading that spelled it. Backspace taking one back out puts
     * that reading's other conversions on the strip (#711), the pick the user
     * would have made had the right one been first. Never kept for a password
     * box, and dropped with the field.
     */
    private val recentConversions = ArrayDeque<Pair<String, String>>()

    /** What consecutive backspaces have taken out of the field, in field order (#711). */
    private var conversionDeleted = ""

    /** The Han text the last of those backspaces left in front of the caret. */
    private var conversionDeletedLeft = ""

    /** Other conversions of [reading] on the strip, offered with [left] before the caret. */
    private class ConversionRepick(val reading: String, val left: String, val words: List<String>)

    /** The re-pick the strip shows, while it shows one. */
    private var conversionRepick: ConversionRepick? = null

    private fun rememberConversion(written: String, reading: String) {
        conversionDeleted = ""
        conversionRepick = null
        if (_uiState.value.secureField || reading.isEmpty()) return
        recentConversions.addLast(written to reading)
        while (recentConversions.size > RECENT_CONVERSIONS) recentConversions.removeFirst()
    }

    /**
     * Adds what one backspace took ([before] less [left]) to the run being
     * deleted. A backspace anywhere else than where the last one left the
     * caret starts the run again.
     */
    private fun noteConversionDeleted(before: CharSequence, left: CharSequence) {
        val gone = before.subSequence(left.length, before.length).toString()
        val continues = conversionDeleted.isNotEmpty() && CjkContext.hanTail(before) == conversionDeletedLeft
        conversionDeleted = (if (continues) gone + conversionDeleted else gone).take(CONVERSION_DELETED_MAX)
        conversionDeletedLeft = CjkContext.hanTail(left)
    }

    /**
     * The reading of the conversion backspace has just taken out whole, while
     * the caret is still where that left it. Null otherwise: a word only half
     * deleted is still partly in the field, and its reading would write the
     * half that stayed a second time.
     */
    private fun repickReading(left: String): String? {
        if (conversionDeleted.isEmpty() || left != conversionDeletedLeft) return null
        return recentConversions.lastOrNull { it.first == conversionDeleted }?.second
    }

    /**
     * The conversion strip with nothing composing, worked out from the field
     * rather than from the keystroke that led there: a caret moved, a
     * backspace, or the echo of the keyboard's own commit.
     *
     * The echo is the one that mattered. It comes back after a candidate is
     * committed and used to empty the strip under the 联想 that commit had just
     * put up, before anyone could tap one (#710). The field now says what is
     * behind the caret and the strip follows on from it (#711): the other
     * conversions of a word backspace has just taken out, or what comes next.
     */
    private fun refreshConversionStripAtCaret(state: KeyboardUiState) {
        // An editor that will not say keeps whatever the last commit put up.
        val before = currentInputConnection?.getTextBeforeCursor(CjkContext.KEEP, 0) ?: return
        val left = CjkContext.hanTail(before)
        CjkContext.fromField(before)
        val reading = repickReading(left)
        if (reading == null) {
            conversionRepick = null
            showConversionPredictions(left)
            return
        }
        // The echo of the backspace that put it up.
        if (conversionRepick?.let { it.reading == reading && it.left == left } == true) return
        val composer = state.composer
        suggestionJob = serviceScope.launch {
            // Only the conversions that spell the whole reading: one that
            // covers its first syllable would leave the rest unwritten.
            val words = withContext(suggestionDispatcher) {
                val all = composer.candidates(reading)
                all.filterIndexed { i, _ -> composer.consumedForIndex(reading, i) == reading.length }
            }
            if (composing.isNotEmpty() || _uiState.value.composer !== composer) return@launch
            if (words.isEmpty()) {
                showConversionPredictions(left)
                return@launch
            }
            conversionRepick = ConversionRepick(reading, left, words)
            conversionPredictions = null
            _uiState.update {
                it.copy(
                    suggestions = words,
                    emojiSuggestions = emptyList(),
                    conversionReadings = emptyList(),
                    autocorrectWord = null,
                    punctuationSuggestions = emptyList(),
                    inlineEmoji = false,
                )
            }
        }
    }

    /** What follows [left] on the strip, the word engine's next words when the composer has none. */
    private fun showConversionPredictions(left: String) {
        // The echo of a commit asks about the context that commit has already
        // answered, and the strip it put up stays as it is.
        if (left.isNotEmpty() && conversionPredictions?.first == left) return
        val predicted = conversionPredictions(left)
        val (nextWords, nextEmojis) = if (predicted.isEmpty()) nextWordStrip() else emptyList<String>() to emptyList()
        _uiState.update {
            it.copy(
                suggestions = predicted.ifEmpty { nextWords },
                emojiSuggestions = nextEmojis,
                conversionReadings = emptyList(),
                autocorrectWord = null,
                punctuationSuggestions = emptyList(),
                inlineEmoji = false,
            )
        }
    }

    /**
     * A re-pick tapped (#711): it goes in where the backspaced word was, and
     * is taught under the reading the way a pick while composing is. False
     * when [chosen] is not one of them.
     */
    private fun commitConversionRepick(ic: InputConnection, chosen: String): Boolean {
        val offer = conversionRepick ?: return false
        if (chosen !in offer.words) return false
        val composer = _uiState.value.composer
        ic.commitText(chosen, 1)
        val index = composer.candidates(offer.reading, CANDIDATE_GRID_LIMIT).indexOf(chosen)
        if (index >= 0 && learningAllowed) composer.learnChoice(offer.reading, index)
        CjkContext.before = offer.left + chosen
        rememberConversion(chosen, offer.reading)
        val next = conversionPredictions(CjkContext.before)
        _uiState.update {
            it.copy(suggestions = next, emojiSuggestions = emptyList(), autocorrectWord = null, candidateCursor = -1)
        }
        CjkLearning.store?.let { store -> serviceScope.launch(Dispatchers.IO) { store.save() } }
        return true
    }

    /**
     * A prediction tapped with nothing composing: it goes in as it stands,
     * no space, and the strip predicts again from the longer context. False
     * when [chosen] is not one of the strip's predictions.
     */
    private fun commitConversionPrediction(ic: InputConnection, chosen: String): Boolean {
        val (context, words) = conversionPredictions ?: return false
        if (chosen !in words) return false
        val composer = _uiState.value.composer
        ic.commitText(chosen, 1)
        conversionDeleted = ""
        if (learningAllowed) composer.learnPrediction(context, chosen)
        CjkContext.before = context + chosen
        val next = conversionPredictions(CjkContext.before)
        _uiState.update {
            it.copy(suggestions = next, emojiSuggestions = emptyList(), autocorrectWord = null, candidateCursor = -1)
        }
        CjkLearning.store?.let { store -> serviceScope.launch(Dispatchers.IO) { store.save() } }
        return true
    }

    /**
     * The buffer is spent: clears it and turns the strip to next-word
     * suggestions — the composer's own (联想) after a conversion when it has
     * any, the word engine's otherwise.
     */
    private fun afterConversionFlushed(predict: Boolean = false) {
        composing = StringBuilder()
        val (nextWords, nextEmojis) = nextWordStrip()
        val predicted = if (predict) conversionPredictions(CjkContext.before) else emptyList()
        _uiState.update {
            it.copy(
                composingPreview = "",
                suggestions = predicted.ifEmpty { nextWords },
                conversionReadings = emptyList(),
                emojiSuggestions = nextEmojis,
                autocorrectWord = null,
                candidateCursor = -1,
            )
        }
        syncHardwareCandidateWindow()
    }

    /**
     * Commits a single chosen conversion candidate and keeps the tail: deletes
     * only the input chars [chosen] consumed, then re-converts whatever is left
     * so the next syllable's candidates appear immediately. Tapping 你 for
     * `nihao` commits 你 and leaves `hao` composing. Never learns (Hanzi/Kanji
     * are not lexicon words) and never adds a trailing space.
     */
    private fun commitConversionPrefix(ic: InputConnection, chosen: String, index: Int = -1, piece: String? = null) {
        if (composing.isEmpty()) {
            if (!commitConversionRepick(ic, chosen)) commitConversionPrediction(ic, chosen)
            return
        }
        // A pick converts from the reading's start; whatever is left is edited at its end.
        readingCaret = -1
        val composer = _uiState.value.composer
        val buf = composing.toString()
        // By strip position when the caller knows it, which is exact even where a
        // candidate's text is reachable at two different spans; by text otherwise,
        // which is what the raw-reading fallback needs since it is in no list.
        val consumed = if (index >= 0) {
            composer.consumedForIndex(buf, index)
        } else {
            composer.consumedFor(buf, chosen)
        }.coerceIn(1, buf.length)
        // Only a real pick from the strip or grid, and never the raw-reading
        // fallback: index is -1 there, and there is nothing to learn from a
        // reading the dictionary could not convert. Not hooked into
        // flushConversion either — that auto-commits whatever already ranked
        // first, so learning it would only entrench the existing order.
        // A single character of the candidate ([piece], 以词定字) consumes the
        // candidate's whole reading but teaches nothing about the word.
        // With a later segment focused (Mozc), the segments before it go in too.
        val written = piece ?: if (index >= 0) composer.committedText(buf, index, chosen) else chosen
        if (index >= 0 && piece == null && learningAllowed) composer.learnChoice(buf, index)
        ic.commitText(written, 1)
        // The rest of a reading kept on the strip now sits after the pick: read
        // again by the [updateComposingText] below (#973).
        hiddenReadingCaret = -1
        composing.delete(0, consumed)
        val rest = composer.remainderAfterCommit(composing.toString())
        if (rest.length != composing.length) composing = StringBuilder(rest)
        // The raw reading is no Chinese for the next buffer to follow on from.
        if (index >= 0 || piece != null) CjkContext.committed(written) else CjkContext.before = ""
        // A single character of a word (以词定字) does not spell the reading
        // it consumed, so backspace has nothing to re-pick it from.
        if (index >= 0 && piece == null) rememberConversion(written, buf.substring(0, consumed))
        consumeShift()
        if (composing.isEmpty()) {
            val (nextWords, nextEmojis) = nextWordStrip()
            val predicted = if (index >= 0 || piece != null) conversionPredictions(CjkContext.before) else emptyList()
            _uiState.update {
                it.copy(
                    composingPreview = "",
                    suggestions = predicted.ifEmpty { nextWords },
                    conversionReadings = emptyList(),
                    emojiSuggestions = nextEmojis,
                    autocorrectWord = null,
                    // The reading is fully committed, so there is nothing left to
                    // choose. Leaving the grid up would strand the user staring at
                    // an empty panel with the keyboard hidden behind it.
                    panel = if (it.panel == PanelMode.CANDIDATES) PanelMode.NONE else it.panel,
                    expandedCandidates = emptyList(),
                    candidateCursor = -1,
                )
            }
            syncHardwareCandidateWindow()
        } else {
            // Re-show the remaining pinyin/kana as the composing region and
            // convert it — the next chunk's candidates fill the strip.
            updateComposingText(ic)
            refreshSuggestions()
        }
    }

    /**
     * The Japanese flick pad's 小゛゜ key: cycles the last kana in the composing
     * buffer through its small / dakuten / handakuten forms (か→が, は→ば→ぱ). The
     * kana lives in the composing buffer while the reading is still being typed,
     * so this rewrites the last char in place and re-converts; a no-op when the
     * buffer is empty or the last char has no variant.
     */
    private fun cycleKanaVariant() {
        if (cycleCaptureKanaVariant()) return
        val ic = currentInputConnection ?: return
        if (composing.isEmpty()) return
        // The kana in front of the caret, which is the last one unless the
        // reading is being edited in the middle (#960).
        val at = if (readingCaret in 1 until composing.length) readingCaret - 1 else composing.length - 1
        val last = composing[at]
        val cycled = Kana.cycleVariant(last)
        if (cycled == last) return
        composing.setCharAt(at, cycled)
        updateComposingText(ic)
        refreshSuggestions()
    }

    /**
     * [cycleKanaVariant] for a keyboard-owned field (#527). True whenever one
     * has the keys — including when there is no kana to cycle — so the press is
     * spent here rather than rewriting a word in the app behind the panel.
     */
    private fun cycleCaptureKanaVariant(): Boolean {
        val state = _uiState.value
        val target = state.captureTarget() ?: return false
        if (!composesInCapture(state.composer)) return true
        val before = state.captureCaretText() ?: return true
        val run = liveCaptureComposition(state, before) ?: return true
        val last = run.keys.lastOrNull() ?: return true
        val cycled = Kana.cycleVariant(last)
        if (cycled == last) return true
        rewriteCaptureComposition(state, target, before, run, run.keys.dropLast(1) + cycled)
        return true
    }

    /**
     * The 나랏글 (Naratgeul) pad's 획추가 and 쌍자음 keys (#599): [edit] gives the
     * composing buffer back with one jamo changed, and the composer re-reads
     * it, so 롬 becomes 롭 without anything being decomposed. The edit keeps
     * the buffer's length, which is what keeps the touch, key and hint twins
     * one entry per buffer character. A no-op when nothing is composing or the
     * last letter has no other form, as the 小゛゜ key is.
     */
    private fun rewriteLastJamo(edit: (buffer: String, composer: Composer) -> String?) {
        val state = _uiState.value
        val target = state.captureTarget()
        if (target != null) {
            // A keyboard-owned field has the keys, so the press is spent there
            // whether or not it changes anything (#527).
            if (!composesInCapture(state.composer)) return
            val before = state.captureCaretText() ?: return
            val run = liveCaptureComposition(state, before) ?: return
            val edited = edit(run.keys, state.composer) ?: return
            rewriteCaptureComposition(state, target, before, run, edited)
            return
        }
        val ic = currentInputConnection ?: return
        if (composing.isEmpty()) return
        val edited = edit(composing.toString(), state.composer) ?: return
        composing.replace(0, composing.length, edited)
        ambiguousReading = null
        updateComposingText(ic)
        refreshSuggestions()
    }

    /**
     * A reading picked from the reading column (#635): the composer settles the
     * next undecided syllable of the buffer as [reading], and the candidates
     * re-convert from what it gives back, so the strip offers only characters
     * read that way and the column moves on to the syllable after. Nothing is
     * committed. Ignored when the buffer has moved on since the column was drawn
     * and [reading] no longer fits it.
     */
    private fun pickConversionReading(reading: String) {
        if (reading.isEmpty()) return
        val state = _uiState.value
        val target = state.captureTarget()
        if (target != null) {
            if (!composesInCapture(state.composer)) return
            val before = state.captureCaretText() ?: return
            val run = liveCaptureComposition(state, before) ?: return
            val picked = state.composer.pickReading(run.keys, reading) ?: return
            rewriteCaptureComposition(state, target, before, run, picked)
            return
        }
        val ic = currentInputConnection ?: return
        if (composing.isEmpty()) return
        val picked = state.composer.pickReading(composing.toString(), reading) ?: return
        // A different length, so the per-key twins no longer line up with the
        // buffer; they go the way they go for any re-spelled buffer.
        composing.replace(0, composing.length, picked)
        composingTouch.clear()
        composingKeys.clear()
        composingHints.clear()
        ambiguousReading = null
        updateComposingText(ic)
        refreshSuggestions()
    }

    /** Set once the Traditional conversion tables have been asked for; they never change after. */
    @Volatile
    private var hanVariantTablesRequested = false

    /**
     * Loads the OpenCC tables behind Traditional output (#609), the first time the
     * toggle is seen on, so nobody writing Simplified pays to parse them. The
     * character and regional tables are bundled; the phrase table is the
     * downloadable `s2t_phrases` pack, re-read by [loadHanPhrases] whenever the
     * packs change. Until the tables land, [HanVariant] is the identity and
     * candidates stay Simplified for a moment. Each table is independently
     * optional — a missing one just leaves its layer inert, and without the
     * phrase pack the conversion is character by character — and each
     * assignment invalidates the candidate caches.
     */
    private fun loadHanVariantTables() {
        if (hanVariantTablesRequested) return
        hanVariantTablesRequested = true
        serviceScope.launch(Dispatchers.Default) {
            fun table(name: String): HanPhraseTable = runCatching {
                assets.open("dictionaries/$name").bufferedReader().useLines(HanPhraseTable::parse)
            }.getOrDefault(HanPhraseTable.EMPTY)
            // Regional tables first: the standard pair is what switches conversion
            // on, and the region must already be there when it does.
            HanVariant.twPhrases = table("tw_phrases.txt")
            HanVariant.twVariantsPhrases = table("tw_variants_phrases.txt")
            HanVariant.twVariants = table("tw_variants.txt")
            HanVariant.hkVariantsPhrases = table("hk_variants_phrases.txt")
            HanVariant.hkVariants = table("hk_variants.txt")
            // Phrases before characters, so there is no window where 头发 is
            // converted letter by letter.
            loadHanPhrases()
            HanVariant.s2t = table("s2t.txt")
        }
    }

    /** The downloaded OpenCC phrase pack into [HanVariant]; empty when it is not on disk. */
    private fun loadHanPhrases() {
        HanVariant.s2tPhrases = CjkDictStore.downloadedFileFor(filesDir, "s2t_phrases")
            ?.let { file -> runCatching { file.bufferedReader().useLines(HanPhraseTable::parse) }.getOrNull() }
            ?: HanPhraseTable.EMPTY
    }

    /**
     * Loads the imported input methods (`.cin` tables, Rime schemas, m17n
     * files) the enabled layouts are bound to, off the main thread, and drops
     * any no enabled layout names. A no-op when memory already matches the
     * disk, which costs a file check per method, so it is asked on every focus.
     */
    private fun reloadImportedInputMethods() {
        if (!userUnlocked) return
        val settings = _uiState.value.settings
        val enabled = settings.enabledLayoutIds.toHashSet()
        val wanted = settings.customLayouts.mapNotNullTo(HashSet()) { spec ->
            spec.inputMethod?.id?.takeIf { spec.id in enabled }
        }
        if (ImportedInputMethods.isCurrent(filesDir, wanted)) return
        serviceScope.launch(Dispatchers.Default) { ImportedInputMethods.load(filesDir, wanted) }
    }

    /** State token the conversion tables were last loaded from; see [cjkTablesToken]. */
    @Volatile
    private var loadedCjkPackToken = Int.MIN_VALUE

    /** What each table was last built from, by pack id, so a change rebuilds that table alone. */
    private val loadedCjkTables = ConcurrentHashMap<String, Int>()

    /**
     * Everything the conversion tables are built from, as one number: which
     * packs are on disk ([CjkDictStore.stateToken]) and, for each language
     * whose imported lists join its table, [conversionListsToken]. Asked on
     * every field focus, so it stays a few file checks and one directory
     * listing per converting language.
     */
    private fun cjkTablesToken(): Int {
        var token = CjkDictStore.stateToken(filesDir)
        for (langId in ConversionWordLists.languages) token = token * 31 + conversionListsToken(langId)
        return token
    }

    /**
     * The imported lists [langId]'s conversion table reads, and whether it
     * reads its pack beside them: a list imported, switched, edited or
     * deleted, or "Use only my word lists" flipped, changes it.
     */
    private fun conversionListsToken(langId: String): Int {
        if (!userUnlocked) return 0
        var h = if (shippedDictionaryEnabled(langId)) 1 else 2
        for (list in CustomDictionaries.lists(filesDir, langId)) {
            h = h * 31 + list.name.hashCode()
            h = h * 31 + list.length().toInt()
            h = h * 31 + list.lastModified().toInt()
        }
        return h
    }

    /**
     * [packId]'s table with what the user imported for [langId] merged in
     * (#633). The lists used to reach only the Latin strip's word tries, which
     * a conversion IME never reads, so a Chinese list changed nothing — and
     * without the pack Chinese could not convert at all, whatever was
     * imported. Only lines that carry a reading join ([ConversionWordLists]);
     * a pack word they repeat keeps the pack's frequency.
     *
     * "Use only my word lists" (#28) drops the pack, the way it drops a
     * downloaded list everywhere else, but only once a list has something to
     * convert with: with nothing imported it would leave the language unable to
     * type a single character, which is not what anyone switching it on meant.
     */
    private fun conversionTable(packId: String, langId: String): ConversionDictionary {
        val pack = CjkDictStore.downloadedFileFor(filesDir, packId)
            ?.let { file -> runCatching { file.bufferedReader().useLines(ConversionDictionary::parse) }.getOrNull() }
            ?: ConversionDictionary.EMPTY
        val reading = ConversionWordLists.readingFor(langId)
        // Direct boot: the imported lists are behind the user's credential.
        if (reading == null || !userUnlocked) return pack
        val scale = ConversionWordLists.Scale.of(pack)
        val rows = CustomDictionaries.lists(filesDir, langId).flatMap { list ->
            runCatching { list.bufferedReader().useLines { ConversionWordLists.rows(it, reading, scale) } }
                .getOrDefault(emptyList())
        }
        if (rows.isEmpty()) return pack
        val base = if (shippedDictionaryEnabled(langId)) pack else ConversionDictionary.EMPTY
        return base.plus(rows)
    }

    /**
     * (Re)loads the Chinese/Japanese conversion tables from their downloaded
     * [CjkDictCatalog] packs and the lists imported for their languages. The
     * packs are large and useful to a minority, so they are not bundled — with
     * neither a pack nor a list on disk the composer types the raw reading with
     * no candidates, and deleting a pack resets it to empty. Records the state
     * token so [onStartInputView] re-parses only when something actually
     * changed, and then only the tables it changed for. All parsing runs off
     * the main thread.
     */
    private suspend fun loadCjkConversionTables() {
        withContext(Dispatchers.Default) {
            val token = cjkTablesToken()
            // Per table: a Chinese list imported has no business re-reading the
            // million-row Japanese pack.
            fun stale(packId: String, langId: String?): Boolean {
                val file = CjkDictStore.downloadedFileFor(filesDir, packId)
                var t = file?.let { it.length().toInt() * 31 + it.lastModified().toInt() } ?: 0
                if (langId != null) t = t * 31 + conversionListsToken(langId)
                return loadedCjkTables.put(packId, t) != t
            }
            // Issue #691: a pack on disk that came out empty failed to parse,
            // most likely for memory at a bad moment (the Japanese one is
            // 40 MB). Its token was already recorded, so nothing tried again
            // until the file changed, and the language sat without candidates
            // until the pack was deleted and downloaded again. Forgetting the
            // token makes the next showing of the keyboard read it afresh.
            fun retryIfEmpty(packId: String, empty: Boolean) {
                if (empty && CjkDictStore.downloadedFileFor(filesDir, packId) != null) {
                    loadedCjkTables.remove(packId)
                }
            }
            if (stale("pinyin", "zh")) {
                CjkDictionaries.pinyin = conversionTable("pinyin", "zh")
                retryIfEmpty("pinyin", CjkDictionaries.pinyin.isEmpty)
                // A new table is new swipe spellings (#580); the gate rebuilds them.
                glideSourcesEpoch.update { it + 1 }
            }
            // Which Mandarin words follow which (#580). Optional: without it
            // the decoder ranks each word by its own frequency alone.
            if (stale("pinyin_ngrams", null)) {
                CjkDictionaries.pinyinNgrams = CjkDictStore.downloadedFileFor(filesDir, "pinyin_ngrams")
                    ?.let { file -> runCatching { file.bufferedReader().useLines(CjkNgrams::parse) }.getOrNull() }
                    ?: CjkNgrams.EMPTY
                retryIfEmpty("pinyin_ngrams", CjkDictionaries.pinyinNgrams.isEmpty)
            }
            if (stale("ja_kana", "ja")) {
                CjkDictionaries.japanese = conversionTable("ja_kana", "ja")
                retryIfEmpty("ja_kana", CjkDictionaries.japanese.isEmpty)
                // New kana swipe spellings too (#958).
                glideSourcesEpoch.update { it + 1 }
            }
            if (stale("stroke", null)) {
                CjkDictionaries.stroke = CjkDictStore.downloadedFileFor(filesDir, "stroke")
                    ?.let { file ->
                        runCatching {
                            file.bufferedReader().useLines {
                                CodeTableDictionary.parse(it, CodeTableDictionary.STROKE_CODE)
                            }
                        }.getOrNull()
                    }
                    ?: CodeTableDictionary.EMPTY
                retryIfEmpty("stroke", CjkDictionaries.stroke.isEmpty)
            }
            if (stale("jyutping", "yue")) {
                CjkDictionaries.jyutping = conversionTable("jyutping", "yue")
                retryIfEmpty("jyutping", CjkDictionaries.jyutping.isEmpty)
            }
            if (stale("cangjie", null)) {
                CjkDictionaries.cangjie = CjkDictStore.downloadedFileFor(filesDir, "cangjie")
                    ?.let { file ->
                        runCatching {
                            file.bufferedReader().useLines {
                                CodeTableDictionary.parse(it, CodeTableDictionary.CANGJIE_CODE)
                            }
                        }.getOrNull()
                    }
                    ?: CodeTableDictionary.EMPTY
                retryIfEmpty("cangjie", CjkDictionaries.cangjie.isEmpty)
            }
            // A pack change can be the phrase pack arriving or going. Only read
            // once Traditional output has asked for its tables; until then
            // [loadHanVariantTables] picks it up itself.
            if (hanVariantTablesRequested) loadHanPhrases()
            // The pinyin syllable inventory is tiny static reference data (~1.8 KB),
            // the only bundled CJK asset — segmentation is ready without a download,
            // though candidates still need the pinyin pack above.
            runCatching {
                assets.open("dictionaries/pinyin_syllables.txt").bufferedReader().useLines {
                    PinyinSyllables.valid = PinyinSyllables.parse(it)
                }
            }
            // T9's digit-code index and Zhuyin's bopomofo table are both derived
            // from that inventory rather than loaded — the 9-key pad, the 注音 pad
            // and the full keyboard share one syllable set and one conversion pack.
            // Cantonese has its own inventory: the readings share no syllable set
            // with Mandarin, so it cannot be derived like the two above. Optional —
            // absent, Jyutping segments nothing and commits the raw roman letters.
            runCatching {
                assets.open("dictionaries/jyutping_syllables.txt").bufferedReader().useLines {
                    JyutpingSyllables.valid = JyutpingSyllables.parse(it)
                }
            }
            T9Pinyin.index = T9Pinyin.buildIndex(PinyinSyllables.valid)
            ZhuyinSyllables.table = ZhuyinSyllables.buildTable(PinyinSyllables.valid)
            // Jianpin's initials are derived from the same inventory: `h` stands
            // for every syllable the inventory starts with h.
            Jianpin.index = Jianpin.build(PinyinSyllables.valid)
            // Which characters the 通用规范汉字表 lists, and at which level: 25 KB,
            // bundled, so a rare character sinks without any pack.
            if (HanLevels.table.isEmpty) {
                runCatching {
                    assets.open("dictionaries/han_levels.txt").bufferedReader().useLines {
                        HanLevels.table = HanLevels.parse(it)
                    }
                }
            }
            loadedCjkPackToken = token
        }
        // The tables are in, so a missing pack is now really missing: the chip
        // for one goes up without waiting for a keystroke, and one for a pack
        // that just landed comes down.
        withContext(Dispatchers.Main) { refreshConversionPackOffer(_uiState.value) }
    }

    /**
     * Next-word predictions for the word just committed, computed inline.
     *
     * Only safe because the empty-composing path is a handful of bigram map
     * lookups — no dictionary completion, no edit-distance search — so it
     * costs less than the dispatch it replaces. Returns words to emojis,
     * matching the split [refreshSuggestions] does.
     */
    /**
     * The (previousWord, typed) pair the offered join chip was computed for,
     * so a stale tap (field changed underneath) can verify before rewriting.
     */
    private var joinContext: Pair<String, String>? = null

    /** The join chip: replace "prev typed" in the field with the joined word. */
    fun onJoinSuggestionTapped() {
        val state = _uiState.value
        val joined = state.joinSuggestion ?: return
        val (prev, typedAt) = joinContext ?: return
        val typed = composing.toString()
        // The chip was computed for this exact composing text.
        if (!typed.equals(typedAt, ignoreCase = true)) return
        val ic = currentInputConnection ?: return
        ic.beginBatchEdit()
        try {
            ic.finishComposingText()
            // Verify the field really ends "prev typed" (plus derive the next
            // bigram context from what precedes it), or do nothing at all.
            val span = prev.length + 1 + typed.length
            val window = ic.getTextBeforeCursor(span + 48, 0)?.toString()
            val tail = window?.takeLast(span)
            if (tail == null || !tail.equals("$prev $typed", ignoreCase = true) ||
                tail[prev.length] != ' '
            ) {
                return
            }
            val beforeContext = window.dropLast(span)
            val display = joinedCase(tail, joined)
            ic.deleteSurroundingText(span, 0)
            ic.commitText(display, 1)
            revision = null
            composing = StringBuilder()
            setContextFrom(beforeContext)
            lastRevertible = RevertibleCommit(
                RevertibleCommit.Kind.JOIN, original = tail, committed = display,
            )
            armRevertGuard()
            learn(joined, reinforcement = 2)
            invalidateExpectedSelection()
        } finally {
            ic.endBatchEdit()
        }
        _uiState.update {
            it.copy(
                composingPreview = "",
                suggestions = emptyList(),
                octopus = emptyMap(),
                emojiSuggestions = emptyList(),
                joinSuggestion = null,
            )
        }
        joinContext = null
        val (words, emojis) = nextWordStrip()
        _uiState.update { it.copy(suggestions = words, emojiSuggestions = emojis, autocorrectWord = null) }
    }

    /**
     * What the revision chip was computed against: (the word to replace, the
     * follower that incriminated it), so a stale tap (field changed
     * underneath) can verify before rewriting.
     */
    private var revisionContext: Pair<String, String>? = null

    /** Slack past the two words for trailing separators and punctuation. */
    private val REVISION_LOOKBEHIND = 16

    /** The fewest samples a chained segment keeps after its spacebar walks are cut for the fallback decode (#968). */
    private val GLIDE_FALLBACK_MIN_POINTS = 3

    /** The pause rescoring's job (see refreshStrip), one at a time. */
    private var pauseRevisionJob: Job? = null

    /** How long the typing must pause before the last few words are re-read. */
    private val REVISION_PAUSE_MS = 1_000L

    /**
     * The revision chip: replace the confusable word before the last commit
     * ("their going" → "they're going"). Verifies the field still ends with
     * exactly that pair (plus whatever separators followed) and rewrites
     * nothing otherwise.
     */
    fun onRevisionSuggestionTapped() {
        val state = _uiState.value
        // The near-miss chip shares this slot and this callback, the way the
        // join chip does, and is picked apart by state here rather than by
        // another [ui.KeyboardScreen] parameter — that argument list already
        // compiles to a method at the JVM's 64K ceiling.
        if (state.revisionSuggestion == null && state.correctionOffer != null) {
            applyCorrectionOffer()
            return
        }
        // Last in the same queue, and for the same reason: the undo chip only
        // ever draws when nothing above it did.
        if (state.revisionSuggestion == null && state.correctionUndo != null) {
            undoLastCorrection()
            return
        }
        val replacement = state.revisionSuggestion ?: return
        val (wrong, follower) = revisionContext ?: return
        if (composing.isNotEmpty()) return
        val ic = currentInputConnection ?: return
        ic.beginBatchEdit()
        try {
            ic.finishComposingText()
            val window = ic
                .getTextBeforeCursor(wrong.length + follower.length + REVISION_LOOKBEHIND, 0)
                ?.toString() ?: return
            // Peel the field tail apart: trailing separators, the follower,
            // the separator run, then the word to replace — each verified
            // against what the chip was computed for.
            val trailing = window.takeLastWhile { !it.isLetter() }
            val tail = window.dropLast(trailing.length)
            if (!tail.endsWith(follower, ignoreCase = true)) return
            val beforeFollower = tail.dropLast(follower.length)
            val sep = beforeFollower.takeLastWhile { !it.isLetter() }
            if (sep.isEmpty()) return
            val core = beforeFollower.dropLast(sep.length)
            if (!core.endsWith(wrong, ignoreCase = true)) return
            // Word boundary: "s o their" must match, "sother" must not.
            if (core.length > wrong.length && core[core.length - wrong.length - 1].isLetter()) {
                return
            }
            val wrongActual = core.takeLast(wrong.length)
            val followerActual = tail.takeLast(follower.length)
            val original = wrongActual + sep + followerActual + trailing
            val display = if (wrongActual.firstOrNull()?.isUpperCase() == true) {
                replacement.replaceFirstChar { it.uppercase() }
            } else {
                replacement
            }
            val committed = display + sep + followerActual + trailing
            ic.deleteSurroundingText(original.length, 0)
            ic.commitText(committed, 1)
            // Context: the revised word replaces the old one two words back,
            // when it was the word two back (one follower).
            if (' ' !in follower) previousWord2 = replacement.lowercase()
            lastRevertible = RevertibleCommit(
                RevertibleCommit.Kind.REVISION, original = original, committed = committed,
            )
            armRevertGuard()
            invalidateRecentWords()
            invalidateExpectedSelection()
        } finally {
            ic.endBatchEdit()
        }
        revisionContext = null
        _uiState.update { it.copy(revisionSuggestion = null) }
    }

    /**
     * The near-miss chip: put the correction that did not quite fire into the
     * field after all, over the word the user typed.
     *
     * Verified against the field before anything is edited, like every other
     * chip that rewrites committed text: the offer is derived state, a frame
     * behind the keystrokes, so a tap can land just after the word it was
     * about stopped being there. The word is followed by whatever key
     * committed it, which is read back and put down again verbatim rather than
     * guessed at.
     *
     * Tapping is also a statement about the correction, so the result joins
     * the watch and reaches the adaptive gate as an accept once it settles —
     * evidence that the gate was too tight for this pair.
     */
    private fun applyCorrectionOffer() {
        val replacement = _uiState.value.correctionOffer ?: return
        val typed = correctionOfferFor ?: return
        if (composing.isNotEmpty()) return
        val ic = currentInputConnection ?: return
        vibrate()
        ic.beginBatchEdit()
        try {
            ic.finishComposingText()
            val window = ic.getTextBeforeCursor(typed.length + CORRECTION_OFFER_TAIL, 0)
                ?.toString() ?: return
            val trailing = window.takeLastWhile { !WordContext.isWordChar(it) }
            if (trailing.length > CORRECTION_OFFER_TAIL) return
            val core = window.dropLast(trailing.length)
            if (!core.endsWith(typed, ignoreCase = true)) return
            // Word boundary: the chip is about a whole word, not a tail of a
            // longer one the user has since typed into.
            if (core.length > typed.length &&
                WordContext.isWordChar(core[core.length - typed.length - 1])
            ) {
                return
            }
            val typedActual = core.takeLast(typed.length)
            val display = if (typedActual.firstOrNull()?.isUpperCase() == true) {
                replacement.replaceFirstChar { it.uppercase() }
            } else {
                replacement
            }
            val original = typedActual + trailing
            val committed = display + trailing
            ic.deleteSurroundingText(original.length, 0)
            // Marked like a correction that fired on its own: the user picked
            // the chip, but the word in the field is still not the word they
            // typed, and the span is what says so to the host.
            ic.commitText(markAutoCorrection(committed, typedActual, display.length), 1)
            previousWord = display.lowercase()
            lastRevertible = RevertibleCommit(
                RevertibleCommit.Kind.AUTOCORRECT, original = original, committed = committed,
            )
            armRevertGuard()
            invalidateRecentWords()
            invalidateExpectedSelection()
            // Watched from here on like any correction that fired on its own,
            // rather than credited outright: the user has accepted the offer,
            // not yet the result, and backspacing it away a second later is a
            // rejection like any other.
            judgeCorrections(correctionWatch.push(typed, replacement))
            recordStat { onAutocorrect(offer = true, System.currentTimeMillis()) }
        } finally {
            ic.endBatchEdit()
        }
        // This is the last correction now, and it is one the user asked for by
        // pressing the chip, so it gets no undo entry of its own. The chain is
        // left as it was: every entry in it stands in front of this word, and
        // the undo chip comes back out from behind the offer.
        clearCorrectionOffer()
    }

    /**
     * Decides whether the correction just committed is worth an undo chip, and
     * adds it to the chain if so.
     *
     * The gate is the whole point. A chip after every correction is one more
     * thing on the strip to learn to ignore, and by the time the one that
     * matters arrives the user has stopped looking — so the corrections that
     * were plainly right and plainly small get nothing. What is left is the
     * guess and the rewrite: the fix the engine only just talked itself into,
     * and the one that changed the word past recognising. Those are the ones
     * that go unnoticed until the message has been sent.
     *
     * A correction that does not pass the gate leaves the chain alone. The
     * chip always names the word it will put back, so an older entry behind a
     * plainly right fix is no lie, and wiping the chain for one would undo
     * the reason it is a chain: three slips in a sentence, every one
     * recoverable.
     *
     * A fix that only changed capitals ("i" to "I", a name from the word list)
     * misspells nothing and never earns an entry.
     *
     * Called before the commit lands, so [fieldText] — the composing word as
     * the field shows it — is still the last thing behind the caret, and what
     * stands in front of it is read from there.
     */
    private fun armUndoChip(
        ic: InputConnection,
        fieldText: String,
        typed: String,
        corrected: String?,
        obviousness: Double,
        state: KeyboardUiState,
    ) {
        if (corrected == null || corrected.equals(typed, ignoreCase = true)) return
        val strip = state.settings.suggestionStrip
        if (!strip.undoCorrectionChip || obviousness >= strip.undoChipObviousness) return
        pushUndo(UndoableCorrection(typed, corrected, before = wordContext(ic, fieldText)))
    }

    /** Adds [entry] as the chain's newest, letting the oldest go past [UNDO_CHAIN_DEPTH]. */
    private fun pushUndo(entry: UndoableCorrection) {
        undoChain.addLast(entry)
        while (undoChain.size > UNDO_CHAIN_DEPTH) undoChain.removeFirst()
    }

    /**
     * The text in front of [fieldText], which must be the last thing behind
     * the caret; null when the field says otherwise or cannot be read.
     */
    private fun wordContext(ic: InputConnection, fieldText: String): String? {
        val read = ic.getTextBeforeCursor(fieldText.length + UNDO_CHIP_CONTEXT, 0)?.toString()
            ?: return null
        if (!read.endsWith(fieldText, ignoreCase = true)) return null
        return read.dropLast(fieldText.length)
    }

    /**
     * Drops the chain's newest entry when it is the correction of [original]
     * into [committed] just taken back some other way — the backspace revert,
     * a script flip undone. Anything older stands in front of that word and is
     * unaffected, and so is the chain when the revert was of a correction too
     * plain to have earned an entry.
     */
    private fun dropUndoFor(original: String, committed: String) {
        val newest = undoChain.lastOrNull() ?: return
        val typed = original.trim { !WordContext.isWordChar(it) }
        val word = committed.trim { !WordContext.isWordChar(it) }
        if (!newest.typed.equals(typed, ignoreCase = true) || !newest.corrected.equals(word, ignoreCase = true)) return
        undoChain.removeLast()
        showNextUndo()
    }

    /** Takes the undo chip down and forgets the whole chain, tapped or not. */
    private fun clearUndoChip() {
        undoChain.clear()
        if (_uiState.value.correctionUndo != null) {
            _uiState.update { it.copy(correctionUndo = null) }
        }
    }

    /**
     * Moves a chip already on the strip to the chain's new newest entry, or
     * takes it down when the chain ran out. A chip that was not showing stays
     * hidden: the strip refresh decides that, for reasons this cannot see.
     */
    private fun showNextUndo() {
        val shown = _uiState.value.correctionUndo ?: return
        val next = undoChain.lastOrNull()?.typed?.takeIf { composing.isEmpty() }
        if (next != shown) _uiState.update { it.copy(correctionUndo = next) }
    }

    /**
     * The undo chip: put back the word the user actually typed, for the
     * newest correction in the chain that can still be found.
     *
     * Unlike the backspace revert, the correction is not necessarily the last
     * thing in the field any more — that is the whole point of the chip — so
     * the word is searched for behind the caret rather than assumed to be
     * sitting against it. It has to stand there as a whole word, with the text
     * that stood in front of it when it was committed, and exactly once: two
     * candidates and there is no honest way to say which one the entry meant,
     * and rewriting the wrong one is the failure this feature exists to
     * prevent. An entry that cannot be verified is dropped without touching
     * the text and the next one down is tried, so one tap always undoes the
     * newest correction that is still really there.
     *
     * Tapping is a rejection in full, the same as backspacing the correction
     * away, and is counted through the same path.
     */
    private fun undoLastCorrection() {
        val state = _uiState.value
        // The composing region is the editor's, and reaching behind it to edit
        // committed text is how word-processor views end up with a composition
        // pointing at the wrong span. The chip is only offered between words
        // for exactly this reason; this guard is the belt to that's braces.
        if (composing.isNotEmpty()) return
        val ic = currentInputConnection ?: return
        vibrate()
        var undo: UndoableCorrection? = null
        ic.beginBatchEdit()
        try {
            while (undo == null) {
                val entry = undoChain.removeLastOrNull() ?: break
                if (rewriteUndone(ic, entry, state)) undo = entry
            }
        } finally {
            ic.endBatchEdit()
        }
        showNextUndo()
        if (undo == null) return
        invalidateRecentWords()
        invalidateExpectedSelection()
        // A stale precompute would hand the old answer to the next commit.
        commitResolution = null
        if (undo.script != null) {
            // A script flipped, not a correction refused: the word the keyboard
            // chose is not counted, the flip is remembered, and there is no
            // pair to retire.
            learningBuffer.drop(undo.corrected)
            noteScriptFlip(undo.script)
            lastRevertible = null
            currentInputConnection?.let { syncPreviousWordFromField(it) }
            return
        }
        // The same verdict backspacing it away carries: this exact pair is
        // retired, and the settle pass must not judge it a second time.
        suggestionEngine?.rejectCorrection(undo.typed, undo.corrected)
        recordStat { onAutocorrectUndone() }
        declinedSpots.undone(undo.typed)
        correctionWatch.drop(undo.typed, undo.corrected)
        if (state.settings.learnFromTyping &&
            !(state.incognitoOn && state.settings.incognitoPausesLearning) &&
            !state.secureField
        ) {
            noteRevertedWord(undo.typed, state)
        }
        currentInputConnection?.let { syncPreviousWordFromField(it) }
    }

    /**
     * Finds [undo]'s word behind the caret and puts the typed word back in
     * its place; false, with the field untouched, when it cannot be found for
     * certain. Runs inside the caller's batch edit.
     */
    private fun rewriteUndone(ic: InputConnection, undo: UndoableCorrection, state: KeyboardUiState): Boolean {
        // Found as the field holds it: styled, under Fancy Text (#950).
        val corrected = fieldForm(undo.corrected, state)
        val before = undo.before
        val wanted = if (before == null) {
            UNDO_CHIP_LOOKBEHIND
        } else {
            UNDO_CHIP_LOOKBEHIND + corrected.length + UNDO_CHIP_CONTEXT
        }
        val window = ic.getTextBeforeCursor(wanted, 0)?.toString() ?: return false
        val at = if (before == null) {
            soleWordIndex(window, corrected)
        } else {
            anchoredWordIndex(window, corrected, before, reachesStart = window.length < wanted)
        } ?: return false
        val end = at + corrected.length
        // The field's own casing wins: auto-capitalise may have made a
        // sentence-initial correction a capital that the typed word never
        // was, and putting the word back must not put the capital back too.
        val standing = window.substring(at, end).let { if (corrected != undo.corrected) FancyStyles.unstyle(it) else it }
        val restored = matchLeadingCase(standing, undo.typed)
        ic.deleteSurroundingText(window.length - at, 0)
        ic.commitText(restored + window.substring(end), 1)
        return true
    }

    /**
     * Where [word] stands in [text] as a whole word, or null unless it stands
     * there exactly once. The sibling of [containsWord] for the one caller
     * that has to point at an occurrence rather than merely find one.
     */
    private fun soleWordIndex(text: String, word: String): Int? = soleIndexWhere(text, word) { true }

    /**
     * Where [word] stands in [text] as a whole word right after [before], or
     * null unless exactly one occurrence does. A [before] shorter than
     * [UNDO_CHIP_CONTEXT] was the field's whole start, so it only matches at
     * the start of [text], and only when [reachesStart] says [text] is the
     * field's start too.
     */
    private fun anchoredWordIndex(text: String, word: String, before: String, reachesStart: Boolean): Int? =
        soleIndexWhere(text, word) { at ->
            at >= before.length && text.regionMatches(at - before.length, before, 0, before.length) &&
                (before.length >= UNDO_CHIP_CONTEXT || (reachesStart && at == before.length))
        }

    /** The one whole-word occurrence of [word] in [text] that [accept] takes, or null for none or several. */
    private inline fun soleIndexWhere(text: String, word: String, accept: (Int) -> Boolean): Int? {
        if (word.isEmpty()) return null
        var found: Int? = null
        var from = 0
        while (true) {
            val at = text.indexOf(word, from, ignoreCase = true)
            if (at < 0) return found
            val before = text.getOrNull(at - 1)
            val after = text.getOrNull(at + word.length)
            if (before?.let(WordContext::isWordChar) != true &&
                after?.let(WordContext::isWordChar) != true &&
                accept(at)
            ) {
                if (found != null) return null
                found = at
            }
            from = at + 1
        }
    }

    /** [word] wearing the leading capital (or lack of one) that [asIn] wears. */
    private fun matchLeadingCase(asIn: String, word: String): String =
        if (asIn.firstOrNull()?.isUpperCase() == true) {
            word.replaceFirstChar { it.uppercase() }
        } else {
            word
        }

    /** Takes the near-miss chip down, answered or not. */
    private fun clearCorrectionOffer() {
        pendingCorrectionOffer = null
        correctionOfferFor = null
        if (_uiState.value.correctionOffer != null) {
            _uiState.update { it.copy(correctionOffer = null) }
        }
    }

    /** Leading capital carries over from either original part. */
    private fun joinedCase(originalSpan: String, joined: String): String =
        if (originalSpan.firstOrNull()?.isUpperCase() == true) {
            joined.replaceFirstChar { it.uppercase() }
        } else {
            joined
        }

    private fun nextWordStrip(): Pair<List<String>, List<String>> {
        val engine = suggestionEngine
        val state = _uiState.value
        if (engine == null || !state.settings.suggestions || state.secureField ||
            state.fieldNoSuggestions
        ) {
            return emptyList<String>() to emptyList()
        }
        val (emojis, words) = engine
            .suggest(
                composing = "", previousWord = previousWord, previousWord2 = previousWord2,
                previousWord3 = previousWord3,
            )
            .partition { isEmojiCandidate(it) }
        return words to if (state.settings.emojiPrediction) {
            (emojis + triggerEmojiForPreviousWord()).distinct()
        } else {
            emptyList()
        }
    }

    /**
     * Word→emoji chips for an idle strip. The word just committed keeps
     * offering its emoji after the space, so "happy birthday " still shows 🎂
     * — before this the chip died the moment the word was no longer being
     * composed, which is exactly when someone reaches for it.
     *
     * Learned bigrams come first where both fire: an emoji this user actually
     * types after this word beats a generic trigger.
     */
    private fun triggerEmojiForPreviousWord(): List<String> {
        if (!_uiState.value.settings.emojiPrediction) return emptyList()
        // After an emoji commit the "previous word" is that emoji; suggesting
        // from it would be a lookup on a glyph, and the chip that was just
        // tapped would come straight back.
        val word = previousWord
            ?.takeUnless { isEmojiCandidate(it) || WordContext.isSentinel(it) }
            ?: return emptyList()
        return emojiSuggester?.suggest(word).orEmpty()
    }

    /**
     * Whether anything the user types may be remembered: the setting, incognito,
     * and whether the field allows typing intelligence at all. Shared by the
     * Latin lexicon and the CJK pick history so the two go quiet together.
     */
    private val learningAllowed: Boolean
        get() {
            val state = _uiState.value
            return state.settings.learnFromTyping &&
                !(state.incognitoOn && state.settings.incognitoPausesLearning) &&
                state.allowsTypingIntelligence
        }

    /**
     * Re-derives the statistics gate, then forwards one event to the
     * counters. The gate is computed at the hook rather than subscribed
     * because [KeyboardUiState.incognitoOn] can flip per field, between
     * settings emissions; power saving needs no mention here because the
     * reduced settings object already has [KeyboardSettings.typingStatsEnabled]
     * switched off. The [TypingStats.enabled] setter itself keeps a paused
     * stretch out of the active-time sums.
     */
    private inline fun recordStat(block: TypingStats.() -> Unit) {
        val state = _uiState.value
        // A password field is never counted (#829): the heatmap's lifetime
        // cells would hold a fresh map's first password as the keys it used.
        typingStats.enabled = state.settings.typingStatsEnabled &&
            !(state.incognitoOn && state.settings.incognitoPausesLearning) &&
            !state.secureField
        // The words-per-language split: the id alone, never the layout.
        typingStats.language = state.language.id
        liveSpeed.privateField = state.liveWpmPrivate
        typingStats.block()
        publishLiveWpm(state.settings.spacebarLiveWpm)
    }

    /**
     * Takes the live speed (#752) off the spacebar and forgets the words
     * behind it (#796): the field it was typed in is gone, or has just turned
     * private or stopped being private.
     */
    private fun stopLiveWpm() {
        liveWpmJob?.cancel()
        liveWpmJob = null
        liveSpeed.reset()
        if (LiveWpmReadout.wpm.intValue != 0) LiveWpmReadout.wpm.intValue = 0
    }

    /**
     * Puts the live speed on the spacebar (#752) after an event fed it, and
     * keeps a slow check running while a number is up, so it goes once the
     * pause is long enough. Off, the readout holds 0 and nothing runs.
     */
    private fun publishLiveWpm(on: Boolean) {
        val reading = if (on) liveSpeed.reading(SystemClock.uptimeMillis()) else 0
        if (LiveWpmReadout.wpm.intValue != reading) LiveWpmReadout.wpm.intValue = reading
        if (reading <= 0 || liveWpmJob?.isActive == true) return
        liveWpmJob = serviceScope.launch {
            while (true) {
                delay(LIVE_WPM_CHECK_MS)
                val now = if (_uiState.value.settings.spacebarLiveWpm) liveSpeed.reading(SystemClock.uptimeMillis()) else 0
                if (LiveWpmReadout.wpm.intValue != now) LiveWpmReadout.wpm.intValue = now
                if (now <= 0) break
            }
        }
    }

    /**
     * A two-thumb word with a swipe in it is about to leave the composing
     * region (#751): one word and one glided word, its swipes' length, and
     * the letters its taps and swipes did not each type. Recorded once, here,
     * whatever ends the word, and before its separator, so a tapped letter
     * that armed the word cannot count it a second time.
     */
    private fun recordDuetWord() {
        val tokens = duetWord.snapshot()
        val swipes = tokens.filterIsInstance<GlideToken.Swipe>()
        if (swipes.isEmpty()) return
        val letters = composing.codePointCount(0, composing.length)
        val distance = swipes.sumOf { glideDistanceMm(it.points) }
        val start = tokens.minOf { it.tStart }
        recordStat {
            onGlideWord(letters, distance, System.currentTimeMillis(), gestures = tokens.size, startUptimeMs = start)
        }
    }

    /**
     * Records one commit against everything that learns from typing.
     *
     * [reinforcement] grades how deliberate the commit was: 2 for a tapped
     * suggestion, 1 for a plainly typed word, 0 for an autocorrect (the word
     * still anchors bigrams but doesn't join the personal lexicon).
     * Multi-word commits ("of the" from a split suggestion) learn each word
     * and the bigrams linking them.
     *
     * Nothing here writes to the personal dictionary on the spot. Every word
     * goes into [learningBuffer] and is counted once the text it landed in
     * settles, so a word the user reads back and takes out was never learned
     * (#101). What splits two ways is what happens *then*: one the keyboard
     * already recognises is counted the moment it settles ([noteKnownWord]),
     * one nothing recognises has to settle several times over before it joins
     * the lexicon at all ([noteUnknownWord]).
     *
     * [caseTrusted] says whether [word]'s capitals are the user's own. Only a
     * trusted spelling teaches the lexicon how the word is written (#44); an
     * auto-capitalized one is still learned as a word, just not as a spelling.
     * It defaults to false so a new call site has to think about it, which is
     * the safe way round: the cost of not trusting a real capital is that the
     * user types it again, while the cost of trusting a false one is a word
     * that comes back wrong for as long as the vote holds.
     */
    @Suppress("LongParameterList")
    private fun learn(
        word: String,
        reinforcement: Int = 1,
        caseTrusted: Boolean = false,
        origin: WordOrigin = WordOrigin.TYPED,
        /**
         * The spelling this commit replaced by hand (see [resolveRevision]),
         * taught as a fix once the word settles. Attached to the last word of a
         * multi-word commit, which is the one that ends where the old word did.
         */
        replaces: String? = null,
        /** What the buffer held at the commit, when the taps below were aimed at it. */
        typed: String? = null,
        taps: List<TouchPoint?>? = null,
        keys: KeyTouchModel? = null,
        /**
         * Whether [word] is letters no one spelled: a two-thumb word whose
         * gestures finished no word, shown as the keys under them (#741). It
         * still lands in the run of words, but an unknown one is never parked
         * in the waiting room, where a few sightings of `qy` would make it a
         * word.
         */
        unspelled: Boolean = false,
    ) {
        // A styled word is never one to learn (#950): Fancy Text learns the
        // plain words it composes, and nothing that reached it already styled.
        if (fancyStyleFor(_uiState.value) != null && FancyStyles.unstyle(word) != word) return
        // Thai, Lao, Khmer and Burmese put no space between words, so a run
        // typed in one go is a phrase: split it where [WordSegments] finds
        // the words, unless the whole run is itself a word the keyboard
        // knows (a list word the segmenter would cut in two stays whole).
        val parts = word.split(' ').flatMap { part ->
            if (WordSegments.hasSegmentedScript(part) && !isKnownWord(part.trim { !WordContext.isWordChar(it) })) {
                WordSegments.split(part)
            } else {
                listOf(part)
            }
        }
        // The pattern gate follows what went into the field, not what the
        // lexicon was allowed to keep, so it is fed on both paths.
        for (part in parts) pushRecentWord(part)
        noteRecentWords(parts)
        scheduleRecentBar()
        // Spent by this commit whatever it turns out to be about: the guard is
        // for the space that finishes the word the user just added by hand, and
        // one commit later it has nothing left to say.
        val added = handAddedWord
        handAddedWord = null
        // A chip asking about the *previous* word has been overtaken: the user
        // typed on rather than answering, which is the answer. Cleared before
        // the gate below so it never outlives the word it was about.
        if (learnOfferWord != null) clearLearnOffer()
        if (!learningAllowed) {
            previousWord3 = previousWord2
            previousWord2 = previousWord
            previousWord = word
            return
        }
        val state = _uiState.value
        var previous = previousWord
        var beforePrevious = previousWord2
        var threeBack = previousWord3
        var lastLearned: String? = null
        // Whether the two words a bigram/trigram would hang off are ones the
        // keyboard actually knows. An n-gram with an unrecognised word at
        // either end is a habit built out of a possible typo, and it surfaces
        // in the strip as a next-word suggestion — exactly the rubbish this
        // gate exists to keep out. The skip-grams (the word two or three back
        // -> this one) only ask about their own two ends: the words between
        // may be anything, since an unknown one is exactly where those stores
        // earn their keep, and they are read by the reranker alone, never
        // offered as a next word.
        var previousKnown = previous == null || isKnownWord(previous)
        var beforePreviousKnown = beforePrevious == null || isKnownWord(beforePrevious)
        var threeBackKnown = threeBack == null || isKnownWord(threeBack)
        for ((index, part) in parts.withIndex()) {
            // Combining marks are part of the word, not a boundary: trimming
            // on isLetter alone learns Bengali হয়েছে as হয়েছ. See WordContext.
            // Trimming only reaches the ends; what is left still has to be a
            // word all the way through (#185), or `man"ager` would be counted,
            // offered on the add chip and, three sightings later, learned.
            val cleaned = part.trim { !WordContext.isWordChar(it) }
            if (cleaned.isEmpty() || !WordContext.isLearnableWord(cleaned)) continue
            val last = index == parts.lastIndex
            // Taps only line up with a single word; a split commit has none.
            val single = parts.size == 1
            // Settles the last strip where the context model and the engine
            // disagreed, when this word was one of their two picks.
            if (single && reinforcement > 0) contextAdapter.noteCommitted(cleaned)
            notePerAppWord(cleaned)
            // Attribute the word to whichever mixed language owns it, so the
            // secondary-dictionary weighting tracks the user's real habit.
            suggestionEngine?.recordUsage(cleaned)
            noteAppLanguage(cleaned)
            // A word on the never-suggest list is neither counted nor parked
            // in the waiting room: learning it would only put it back in the
            // personal dictionary the user just took it out of (#48).
            val blacklisted = state.settings.suggestionSources.blacklisted(cleaned, state.language.id)
            // Put into the dictionary by hand a moment ago: this commit is the
            // same event finishing, not a use of it (#115). The n-grams below
            // still run — the word did land in the field, and the phrase it
            // landed in is real context.
            val byHand = added != null && WordKey.of(cleaned) == added
            val known = !blacklisted && isKnownWord(cleaned)
            var queued = false
            if (known) {
                // Counted only once the text it landed in settles — see
                // [noteKnownWord]. The n-grams below are not deferred with it:
                // they hang off words already in the dictionary either way, and
                // the context they need is the run of words being committed
                // right now, which the buffer does not keep.
                if (!byHand) {
                    queued = noteKnownWord(
                        cleaned, reinforcement, state, caseTrusted, origin,
                        replaces = replaces.takeIf { last },
                        typed = (typed ?: cleaned).takeIf { single } ?: cleaned,
                        taps = taps.takeIf { single },
                        keys = keys,
                    )
                }
            } else if (!byHand && !blacklisted && !unspelled && state.composer.isPlausibleWord(cleaned)) {
                // Nothing recognises this word. It goes into the waiting room
                // instead of the dictionary, and only earns its way in once
                // the user has typed it — and left it alone — enough times.
                //
                // Unless the script says it cannot be a word at all. A
                // transliterator produces its output mechanically, so a Telex
                // buffer that meant an English word comes out as a spelling no
                // Vietnamese syllable has (`tést`) — and three of those would
                // put it in the personal dictionary and then in the strip. The
                // word still committed exactly as typed; it is only the
                // remembering that stops here.
                queued = noteUnknownWord(
                    cleaned, reinforcement, state, caseTrusted, origin,
                    replaces = replaces.takeIf { last },
                    typed = (typed ?: cleaned).takeIf { single } ?: cleaned,
                    taps = taps.takeIf { single },
                    keys = keys,
                )
            }
            // The word pairs are learned from the run of words as it settles,
            // so every word that landed has to be in that run, counted or not.
            // An autocorrected "I", a word just added by hand, one on the
            // never-suggest list: left out, the pair learned across the gap
            // was between two words the user never wrote side by side, and the
            // ones the word itself should have started were never learned.
            if (!queued) {
                settleLearned(
                    learningBuffer.push(cleaned, learnLanguageId(cleaned, state), 0, known = known),
                )
            }
            threeBack = beforePrevious
            threeBackKnown = beforePreviousKnown
            beforePrevious = previous
            beforePreviousKnown = previousKnown
            previous = cleaned
            previousKnown = known
            lastLearned = cleaned
        }
        previousWord3 = threeBack
        previousWord2 = beforePrevious
        previousWord = lastLearned
        pushSentenceContext()
    }

    /**
     * Whether the keyboard already recognises [word] — from a dictionary, the
     * personal lexicon, contacts or installed apps.
     *
     * Falls back to the lexicon alone before the engine exists, which is the
     * cautious answer: an unrecognised word is only held back, never lost.
     */
    private fun isKnownWord(word: String): Boolean =
        suggestionEngine?.isKnownWord(word) ?: userLexicon.contains(word)

    /**
     * A word the keyboard already recognises has been committed.
     *
     * Its spelling was never in doubt — it is in a dictionary, a wordlist, the
     * contacts — so it needs no sighting count. What *is* in doubt is whether
     * the user meant this word, and a glide gets that wrong often enough that
     * counting on the spot filled the personal dictionary with real words the
     * user never typed, each one weighted up in the strip so the wrong decode
     * came back stronger next time (#101).
     *
     * So it waits in [learningBuffer] with everything else and is counted when
     * the text around it stops moving: the keyboard closing, the message being
     * sent, moving to another field, or the buffer filling. Backspacing it or
     * re-picking from the strip drops it before it ever counts.
     */
    @Suppress("LongParameterList")
    private fun noteKnownWord(
        word: String,
        reinforcement: Int,
        state: KeyboardUiState,
        caseTrusted: Boolean,
        origin: WordOrigin,
        replaces: String?,
        typed: String,
        taps: List<TouchPoint?>?,
        keys: KeyTouchModel?,
    ): Boolean {
        // An autocorrect target arrives at 0 and has nothing to teach the
        // lexicon: [UserLexicon.learnWord] would refuse the count anyway. The
        // caller queues it for its place in the run of words alone.
        if (reinforcement <= 0) return false
        val queued = learningBuffer.push(
            word, learnLanguageId(word, state), reinforcement, caseTrusted, known = true,
            origin = origin, replaces = replaces, typed = typed, taps = taps, keys = keys,
        )
        // Between the push and the settle, for the reason [noteUnknownWord]
        // spells out. Here too because the word a misread swipe is corrected
        // to is usually one the dictionary already has — it is the *stroke*
        // that is new, not the word — and claiming only on the unknown path
        // left exactly that case teaching nothing (#213, #135).
        claimUndoneGlide(word)
        settleLearned(queued)
        return true
    }

    /**
     * A word no dictionary knows has been committed.
     *
     * Two ways to deal with it, and the user picks which. Asking outright puts
     * an "add to dictionary?" chip on the strip and learns nothing unless it
     * is tapped. Counting — the default — says nothing and waits: the word is
     * parked in [learningBuffer] until the text around it settles, and only
     * after `newWordSightings` settled uses does it join the lexicon.
     *
     * Either way the word is not learned *now*, which is the whole change: a
     * word learned on first sight is a word autocorrect will never fix again,
     * and most first sightings of an unknown word are typos and sloppy swipes.
     */
    @Suppress("LongParameterList")
    private fun noteUnknownWord(
        word: String,
        reinforcement: Int,
        state: KeyboardUiState,
        caseTrusted: Boolean,
        origin: WordOrigin,
        replaces: String?,
        typed: String,
        taps: List<TouchPoint?>?,
        keys: KeyTouchModel?,
    ): Boolean {
        // An autocorrect target is a dictionary word by construction, so a
        // reinforcement of 0 here means the correction landed on something we
        // do not recognise — no evidence about the user's vocabulary at all.
        if (reinforcement <= 0) return false
        if (pendingLearn.isDeclined(word)) return false
        if (state.settings.suggestionStrip.askBeforeLearning) {
            offerToLearn(word, caseTrusted)
            return false
        }
        val queued = learningBuffer.push(
            word, learnLanguageId(word, state), reinforcement, caseTrusted,
            origin = origin, replaces = replaces, typed = typed, taps = taps, keys = keys,
        )
        // Between the push and the settle: the stroke a backspaced glide left
        // waiting needs this word's entry to exist before it can ride it, and
        // needs to be attached before the entry can settle (issue #213).
        claimUndoneGlide(word)
        settleLearned(queued)
        return true
    }

    /**
     * Counts words whose text has settled, promoting any that have now been
     * seen enough times.
     */
    private fun settleLearned(queued: List<LearningBuffer.Entry>, verify: Boolean = false) {
        if (queued.isEmpty()) return
        val entries = oneEntryPerInstance(queued)
        val settings = _uiState.value.settings
        val languageId = _uiState.value.language.id
        val threshold = settings.suggestionStrip.newWordSightings.coerceAtLeast(1)
        // One bounded read of the field, only if a positional suspect needs it
        // (see [teachRevision]) and only where the field can answer for these
        // words; never on the typing path.
        var window: String? = null
        var windowRead = false
        fun window(): String? {
            if (!windowRead) {
                windowRead = true
                window = if (verify) correctionJudgementWindow() else null
            }
            return window
        }
        var prevWord: String? = null
        var prevWord2: String? = null
        var prevWord3: String? = null

        for (entry in entries) {
            // Blacklisted since the commit: the user has just taken this word
            // out of their dictionary, and the queue must not put it back (#48).
            // Nor join the words either side of it into a pair.
            if (settings.suggestionSources.blacklisted(entry.word, languageId)) {
                prevWord3 = null
                prevWord2 = null
                prevWord = null
                continue
            }
            val word = entry.word
            val known = isKnownWord(word)

            if (entry.contextOnly) {
                // Here for its place in the run alone; see [learn].
            } else if (entry.known) {
                // Recognised when it was typed, and it has to still be
                // recognised now: a language switched off while the word sat
                // here would otherwise walk an unknown word into the lexicon
                // past the sighting gate that exists to stop exactly that.
                if (known) {
                    learnSettledWord(entry, settings)
                    teachRevision(entry, ::window)
                    observeTaps(entry.typed, entry.word, entry.taps, entry.keys, entry.origin)
                    learnGlideShape(entry)
                }
            } else if (known) {
                // Was unknown at commit time but learned in the meantime.
            } else {
                // Graded by how deliberate the commit was, the same way
                // [UserLexicon.learnWord] grades its own counts.
                val seen = pendingLearn.sight(entry.word, entry.langId, weight = entry.weight)
                if (seen >= threshold) {
                    promoteLearned(entry.word, entry.langId, seen, entry.caseTrusted)
                    learnGlideShape(entry)
                }
            }

            // Learn N-grams for settled words across the final corrected sequence
            if (known || isKnownWord(word)) {
                prevWord?.let { p ->
                    userLexicon.learnBigram(p, word)
                    prevWord2?.let { p2 ->
                        userLexicon.learnTrigram(p2, p, word)
                        userLexicon.learnSkip1gram(p2, word)
                    }
                    prevWord3?.let { p3 ->
                        userLexicon.learnSkip2gram(p3, word)
                    }
                }
                prevWord3 = prevWord2
                prevWord2 = prevWord
                prevWord = word
            } else {
                prevWord3 = null
                prevWord2 = null
                prevWord = null
            }
        }
    }

    /**
     * [queued] with the same word committed twice in the same place folded
     * into one — the newest copy, which carries the newest evidence.
     *
     * Going back to a word and finishing it again is the user proofreading one
     * word, not typing it twice, and the personal dictionary counting each pass
     * was the complaint in #115. The caret rule catches most of it by dropping
     * the earlier copy as the caret goes back in; this covers the editors whose
     * selection echoes coalesce, where both copies reach the flush.
     *
     * Judged by anchor, not by spelling alone: "very very" is two words, and
     * their anchors are a word apart. Only copies that end at the same offset —
     * the same instance rewritten in place — are the same use.
     */
    private fun oneEntryPerInstance(
        queued: List<LearningBuffer.Entry>,
    ): List<LearningBuffer.Entry> {
        if (queued.size < 2) return queued
        val kept = ArrayList<LearningBuffer.Entry>(queued.size)
        for (entry in queued) {
            val at = kept.indexOfLast { sameInstance(it, entry) }
            if (at >= 0) kept[at] = entry else kept.add(entry)
        }
        return kept
    }

    /**
     * Whether a loaded wordlist already spells [word] in lower case, so one
     * shifted sighting of a word like "the" does not become its spelling just
     * because the personal dictionary had not counted it yet (#154).
     */
    private fun listedInLowerCase(word: String): Boolean =
        suggestionEngine?.spellsInLowerCase(word) == true

    /** Whether two queued words are the same word in the same place. */
    private fun sameInstance(a: LearningBuffer.Entry, b: LearningBuffer.Entry): Boolean =
        a.anchor >= 0 && b.anchor >= 0 &&
            abs(a.anchor - b.anchor) <= LearningBuffer.ANCHOR_SLACK &&
            WordKey.of(a.word) == WordKey.of(b.word)

    /**
     * A recognised word has settled: count it, at the weight its commit
     * earned.
     */
    private fun learnSettledWord(entry: LearningBuffer.Entry, settings: KeyboardSettings) {
        // Tagged with the language it was typed under so a habit learned under
        // one language can be damped when it crowds another's strip. What the
        // lexicon refuses (#185) is not mirrored either: the platform
        // dictionary is read back as known words, and would hand it back.
        val learned = userLexicon.learnWord(
            entry.word,
            entry.weight,
            langId = entry.langId,
            caseEvidence = entry.caseTrusted,
            listedInLowerCase = entry.caseTrusted && listedInLowerCase(entry.word),
        )
        if (!learned) return
        // Mirror it into Android's shared personal dictionary when the user
        // has opted in — in a spelling we can stand behind: an
        // auto-capitalized word would otherwise put a bogus proper noun into
        // the dictionary every other keyboard reads.
        if (settings.addWordsToSystemDictionary) {
            val mirrored = if (entry.caseTrusted) entry.word else entry.word.lowercase()
            serviceScope.launch(Dispatchers.IO) {
                SystemUserDictionary.add(applicationContext, mirrored)
            }
        }
    }

    /**
     * The user backspaced an autocorrect away, putting [word] back.
     *
     * Worth [REVERT_SIGHTINGS] ordinary sightings, and counted immediately
     * rather than parked in the buffer: the buffer answers "did the user leave
     * this text alone", and they have just told us directly. A word already
     * known needs none of this — it was never the autocorrect's target to
     * begin with, or it has been learned since.
     */
    private fun noteRevertedWord(word: String, state: KeyboardUiState) {
        val cleaned = word.trim { !WordContext.isWordChar(it) }
        if (cleaned.isEmpty() || isKnownWord(cleaned)) return
        // The spelling is whatever was standing in the field before the
        // correction fired, and the shift that produced it is long spent, so
        // it teaches the word but not its casing.
        if (state.settings.suggestionStrip.askBeforeLearning) {
            if (!pendingLearn.isDeclined(cleaned)) offerToLearn(cleaned, caseTrusted = false)
            return
        }
        val seen = pendingLearn.sight(cleaned, state.language.id, weight = REVERT_SIGHTINGS)
        val threshold = state.settings.suggestionStrip.newWordSightings.coerceAtLeast(1)
        if (seen >= threshold) {
            promoteLearned(cleaned, state.language.id, seen, caseTrusted = false)
        }
    }

    /**
     * The text stopped moving: everything still queued has settled.
     *
     * [verifyCorrections] is false where the field this all belongs to is no
     * longer the one the keyboard is attached to. Reading text then would
     * judge these corrections against somebody else's text, so the ones that
     * needed a read simply go unjudged.
     */
    private fun flushLearningBuffer(verifyCorrections: Boolean = true) {
        val drainedLearning = learningBuffer.drain()
        val drainedCorrections = correctionWatch.drain()
        settleLearned(drainedLearning, verify = verifyCorrections)
        judgeCorrections(drainedCorrections, verify = verifyCorrections)
        // The readings are about words in this text, and this text is finished.
        glideReadings.clear()
        resumedWord = null
        // So is any stroke still waiting to be told what it meant: the answer
        // would have to have been in this text (issue #213).
        undoneGlide = null

        // Persist learning stores to disk when new items have been settled.
        if (drainedLearning.isNotEmpty() || drainedCorrections.isNotEmpty()) {
            serviceScope.launch(persistDispatcher) { saveLearningStores() }
        }
    }

    /**
     * Delivers the verdict on corrections whose text has settled.
     *
     * An entry the caret never went back in front of is an accept, and needs
     * no evidence beyond that: the user typed straight past it. One the caret
     * *did* go back in front of is only a suspect, because going back covers
     * everything from rewriting that word to adding a comma three words
     * earlier. Those are settled by reading the field once and asking which
     * spelling is standing there now.
     *
     * Anything the read cannot answer is dropped rather than guessed. That
     * covers the word being deleted outright, the correction having scrolled
     * out of the window, and a message field that was sent (the text is gone
     * by then, so there is nothing left to check). A missing verdict costs the
     * adaptive gate one sample; a wrong one teaches it something false.
     */
    private fun judgeCorrections(entries: List<CorrectionWatch.Entry>, verify: Boolean = true) {
        if (entries.isEmpty()) return
        val undisturbed = entries.filterNot { it.disturbed }
        for (entry in undisturbed) {
            correctionStats.recordKept(entry.typed, entry.corrected)
            recordStat { onAutocorrectKept() }
            // A correction that stood is the plainest word about where the
            // finger landed: those taps were aimed at the corrected letters.
            observeTaps(entry.typed, entry.corrected, entry.taps, entry.keys, WordOrigin.TYPED)
        }
        val suspects = entries.filter { it.disturbed }
        if (suspects.isEmpty() || !verify) return
        val window = correctionJudgementWindow() ?: return
        for (entry in suspects) {
            val kept = containsWord(window, entry.corrected)
            val undone = containsWord(window, entry.typed)
            when {
                // Both readings present somewhere in the window: the user has
                // used each word, and nothing here says which one replaced
                // this correction. No verdict.
                kept && undone -> Unit
                kept -> {
                    correctionStats.recordKept(entry.typed, entry.corrected)
                    recordStat { onAutocorrectKept() }
                    observeTaps(entry.typed, entry.corrected, entry.taps, entry.keys, WordOrigin.TYPED)
                }
                // What the user typed is standing where the fix was. This is
                // the case the immediate-backspace path could never see, and
                // it is read off the field rather than pressed, so it goes in
                // as an indirect verdict: weaker than a backspace, and thrown
                // away entirely when the surviving spelling is not a word (the
                // user reproducing their own typo, not defending it). See
                // [SuggestionEngine.rejectCorrection].
                undone -> {
                    suggestionEngine?.rejectCorrection(entry.typed, entry.corrected, deliberate = false)
                    recordStat { onAutocorrectUndone() }
                }
                else -> Unit
            }
        }
    }

    /**
     * The text a correction verdict is read against, or null when the field
     * cannot answer.
     *
     * Deliberately one read of a bounded window rather than the whole field:
     * this runs at a flush (the keyboard closing, the field changing), never
     * on the typing path, and a correction further back than this has scrolled
     * out of the watch anyway.
     */
    private fun correctionJudgementWindow(): String? {
        val ic = currentInputConnection ?: return null
        val before = ic.getTextBeforeCursor(CORRECTION_JUDGEMENT_WINDOW, 0)?.toString().orEmpty()
        val after = ic.getTextAfterCursor(CORRECTION_JUDGEMENT_WINDOW, 0)?.toString().orEmpty()
        val window = before + after
        // Judged against the words as spelled, not as styled (#950).
        if (fancyOutputStyle(_uiState.value) != null) return FancyStyles.unstyle(window).takeIf { it.isNotBlank() }
        return window.takeIf { it.isNotBlank() }
    }

    /** Whether [word] stands in [text] as a word, not inside a longer one. */
    private fun containsWord(text: String, word: String): Boolean {
        if (word.isEmpty()) return false
        var from = 0
        while (true) {
            val at = text.indexOf(word, from, ignoreCase = true)
            if (at < 0) return false
            val before = text.getOrNull(at - 1)
            val after = text.getOrNull(at + word.length)
            if (before?.let(WordContext::isWordChar) != true &&
                after?.let(WordContext::isWordChar) != true
            ) {
                return true
            }
            from = at + 1
        }
    }

    // ---- Learning from the user's own fixes (WordRevision, CorrectionMemory) ----

    /** Whether manual fixes may be learned from at all, right now. */
    private fun revisionsWanted(): Boolean =
        learningAllowed && _uiState.value.settings.suggestionStrip.learnFromCorrections

    /** A word a revision tracker is worth arming on: word-sized, word characters only. */
    private fun isRevisableWord(word: String): Boolean =
        word.length >= CorrectionMemory.MIN_TYPED_LENGTH &&
            word.length <= CorrectionMemory.MAX_WORD_LENGTH &&
            word.all { isComposingWordChar(it) }

    /**
     * How [word] got into the field, if the caret echo that led here dropped
     * it from the learning buffer; TYPED when nothing says otherwise. Glide
     * and voice output are dictionary words, so the known-original rule keeps
     * them out of the slip counts either way; this is the belt to that brace.
     */
    private fun revisionOriginOf(word: String): WordOrigin =
        lastDropped.firstOrNull { it.word.equals(word, ignoreCase = true) }?.origin
            // A word the caret went back into is no longer dropped on the
            // spot (#159); it waits, suspended, and the buffer still knows
            // how it was committed.
            ?: learningBuffer.originOf(word)
            ?: WordOrigin.TYPED

    /**
     * The caret landed at the end of [word] and the word was re-armed as the
     * composing buffer. A field-mode tracker already following exactly this
     * word carries on in composing mode, keeping the spelling the user first
     * came back to (a fix made in two sittings must teach the whole fix, not
     * its second half); anything else is finished, and a fresh tracker armed.
     */
    private fun armComposingRevision(word: String, caret: Int) {
        val start = caret - word.length
        val live = revision
        if (live != null && live.mode == WordRevision.Mode.FIELD && live.covers(start, word)) {
            live.toComposing()
            return
        }
        if (live != null) finishFieldRevision(currentInputConnection, caret)
        if (!revisionsWanted() || !isRevisableWord(word)) return
        revision = WordRevision(word, start, word.length, WordRevision.Mode.COMPOSING)
        revisionOrigin = revisionOriginOf(word)
    }

    /**
     * The caret landed inside a word — [head] behind it, [tail] ahead — that
     * nothing is following yet. A tracker already live has answered this echo
     * in [noteCaretForRevision]; it is not restarted, or the true original
     * would be lost after the first keystroke, since every edit of ours echoes
     * back through here.
     */
    private fun armFieldRevision(head: String, tail: String, caret: Int) {
        if (revision != null || !revisionsWanted()) return
        val word = head + tail
        if (!isRevisableWord(word)) return
        revisionFragment = ""
        revision = WordRevision(word, caret - head.length, head.length, WordRevision.Mode.FIELD)
        revisionOrigin = revisionOriginOf(word)
    }

    /**
     * A selection is about to be replaced by typing. When it is one whole
     * word, that word is what the mirror starts from: gone the moment the
     * first character lands, which [commitTypedCharacter] then mirrors as an
     * insert. One read, on a path that already reads the selection for the
     * bracket-wrap rule.
     */
    private fun armSelectionRevision(ic: InputConnection) {
        revision = null
        if (!revisionsWanted() || expectedSelStart < 0 || expectedSelEnd <= expectedSelStart) return
        val selected = ic.getSelectedText(0)?.toString() ?: return
        if (!isRevisableWord(selected) || selected.length != expectedSelEnd - expectedSelStart) return
        revisionFragment = ""
        val r = WordRevision(selected, expectedSelStart, selected.length, WordRevision.Mode.FIELD)
        r.expectDelete(selected.length, 0)
        revision = r
        revisionOrigin = revisionOriginOf(selected)
    }

    /**
     * A character the keyboard is about to put in the field, seen by a
     * field-mode tracker. A word character extends the mirror; so does a
     * separator typed *inside* the word (a space put back into "thisis"). A
     * separator at the word's end is the user done with the word, and the
     * word is finished before the separator lands.
     */
    private fun mirrorTypedIntoRevision(ic: InputConnection, text: String) {
        val r = revision?.takeIf { it.mode == WordRevision.Mode.FIELD } ?: return
        val separator = text.isNotEmpty() && text.none { isComposingWordChar(it) }
        if (separator && r.cursor >= r.length) {
            finishFieldRevision(ic, r.start + r.cursor)
        } else {
            r.expectInsert(text)
        }
    }

    /**
     * The caret was reported at [selStart]..[selEnd], for the word revision
     * tracker. A range selection ends the tracking: whatever the user does to
     * a selection, they do to text the mirror cannot follow (typing over a
     * single selected word arms its own tracker). A collapsed caret confirms
     * an edit of ours, moves inside the word, or leaves it — and leaving is
     * when the word is judged, against the field.
     */
    private fun noteCaretForRevision(selStart: Int, selEnd: Int) {
        val r = revision ?: return
        if (selStart != selEnd) {
            revision = null
            return
        }
        if (r.mode != WordRevision.Mode.FIELD) return
        if (r.onCaret(selStart) == WordRevision.Outcome.LEFT) {
            finishFieldRevision(currentInputConnection, selStart)
        }
    }

    /** The keyboard is leaving the field: a word still being followed in it is judged now. */
    private fun finishRevisionOnLeave() {
        if (revision?.mode == WordRevision.Mode.FIELD) {
            finishFieldRevision(currentInputConnection, expectedSelStart)
        }
    }

    /**
     * The composing buffer is being replaced. If it was a word the user came
     * back to, [text] — the buffer as they left it — is what the word became.
     * Commit paths resolve their own revision before this runs (they have to
     * attach it to the word they learn); this catches every other way a
     * composition ends: a tap elsewhere, the keyboard closing, a selection.
     */
    private fun finishComposingRevision(text: String) {
        val r = revision ?: return
        if (r.mode != WordRevision.Mode.COMPOSING) return
        revision = null
        val rev = r.finish(text) ?: return
        noteRevision(rev, revisionOrigin)
    }

    /**
     * The user has left a word they were editing in place. The mirror is
     * checked against the field once; where they disagree the field wins —
     * the word standing at the tracker's start is what the original became.
     * That fallback is what makes edits the mirror never saw (a hardware
     * arrow key, an editor that swallows echoes) safe rather than blinding.
     */
    private fun finishFieldRevision(ic: InputConnection?, caret: Int) {
        val r = revision ?: return
        revision = null
        revisionFragment = ""
        if (r.mode != WordRevision.Mode.FIELD || ic == null || caret < 0) return
        val mirrored = r.current()
        val standing = readSpan(ic, caret, r.start, mirrored.length)
        val revised = if (standing != null && standing == mirrored) {
            mirrored
        } else {
            readSpan(ic, caret, r.start, CorrectionMemory.MAX_WORD_LENGTH)
                ?.takeWhile { isComposingWordChar(it) }
                ?.takeIf { it.isNotEmpty() }
                ?: return
        }
        val rev = r.finish(revised) ?: return
        noteRevision(rev, revisionOrigin)
    }

    /**
     * Up to [length] characters of the field from offset [start], read
     * relative to the caret at [caret] — before it, after it, or across it.
     * Null when the editor answers short of the caret's side; the far side
     * may legitimately end early.
     */
    private fun readSpan(ic: InputConnection, caret: Int, start: Int, length: Int): String? {
        if (start < 0 || length <= 0) return null
        val end = start + length
        val out = StringBuilder(length)
        if (caret > start) {
            val toCaret = caret - start
            val text = ic.getTextBeforeCursor(toCaret, 0)?.toString() ?: return null
            if (text.length < toCaret) return null
            out.append(text, 0, minOf(caret, end) - start)
        }
        if (end > caret) {
            val skip = maxOf(0, start - caret)
            val want = end - maxOf(caret, start)
            val text = ic.getTextAfterCursor(skip + want, 0)?.toString() ?: return null
            if (text.length < skip) return null
            out.append(text, skip, minOf(text.length, skip + want))
        }
        return out.toString()
    }

    /**
     * What a revision teaches — the spelling to attach as `replaces` — or null
     * when nothing. The word rewritten may be an autocorrect's *output* still
     * on the watch: then the real typo is what the user typed before that
     * correction, the correction was wrong (graded so, with the standing word
     * as the survivor so the verdict is believed), and the pair to teach
     * starts from the real typo.
     */
    private fun resolveRevision(rev: Revision): String? {
        if (!revisionsWanted()) return null
        var original = rev.original
        // Where the original word ended, which is where the watch anchored it.
        val originalEnd = rev.anchor - rev.revised.length + rev.original.length
        correctionWatch.find(original, originalEnd)?.let { fired ->
            correctionWatch.remove(fired)
            suggestionEngine?.rejectCorrection(
                fired.typed, fired.corrected, deliberate = false, survivor = rev.revised,
            )
            original = fired.typed
        }
        if (!CorrectionMemory.accepts(original, rev.revised, ::isKnownWord)) return null
        val blacklist = _uiState.value.let { it.settings.suggestionSources.blacklistFor(it.language.id) }
        if (original.lowercase() in blacklist ||
            rev.revised.lowercase().split(' ').any { it in blacklist }
        ) {
            return null
        }
        return original
    }

    /**
     * A word the user rewrote by hand outside any commit path: queue the
     * revised word to settle like a committed one, carrying the spelling it
     * replaced. Anchored at its own end, because the caret echo that follows
     * is wherever the user went next.
     */
    private fun noteRevision(rev: Revision, origin: WordOrigin) {
        val original = resolveRevision(rev) ?: return
        val state = _uiState.value
        val word = rev.revised.substringAfterLast(' ')
        settleLearned(
            learningBuffer.push(
                word, state.language.id, 1, caseTrusted = false, known = true,
                replaces = original, anchor = rev.anchor, typed = word,
                replacesOrigin = origin, revised = rev.revised.takeIf { it != word },
            ),
        )
    }

    /**
     * A settled word that replaced another by hand teaches the pair — and,
     * when the original was the user's own typing of a non-word, the slip
     * behind it. A positional suspect (see [LearningBuffer]) is believed only
     * if the field, read once at the flush, shows the old spelling gone and
     * the new one standing; an unreadable flush teaches nothing from it.
     */
    private fun teachRevision(entry: LearningBuffer.Entry, window: () -> String?) {
        val original = entry.replaces ?: return
        val revised = entry.revised ?: entry.word
        if (entry.suspect) {
            val text = window() ?: return
            if (containsWord(text, original) || !containsWord(text, revised)) return
        }
        if (!CorrectionMemory.accepts(original, revised, ::isKnownWord)) return
        // A slip-sized repair is a typo the user caught, counted whether or
        // not the keyboard is allowed to learn from it.
        recordStat { onHandFix(System.currentTimeMillis()) }
        if (!revisionsWanted()) return
        val blacklist = _uiState.value.let { it.settings.suggestionSources.blacklistFor(it.language.id) }
        if (original.lowercase() in blacklist || revised.lowercase().split(' ').any { it in blacklist }) return
        val kind = revisionKind(entry.replacesOrigin) { isKnownWord(original) }
        correctionMemory.teach(original, revised, _uiState.value.layoutId, kind)
        pushLearnedHabits()
    }

    /**
     * Teaches [tapOffsets] where the finger landed for each letter of a word
     * that settled as [intended]: the taps were aimed at [typed]'s letters,
     * and the alignment says which of those were the letters meant. Only a
     * match or a substitution carries a tap; a missing or stray letter has no
     * key to measure against, and a swapped pair says nothing about either.
     */
    private fun observeTaps(
        typed: String,
        intended: String,
        taps: List<TouchPoint?>?,
        keys: KeyTouchModel?,
        origin: WordOrigin,
    ) {
        if (taps == null || keys == null || origin != WordOrigin.TYPED) return
        if (!_uiState.value.settings.suggestionStrip.adaptToTaps) return
        val t = typed.lowercase()
        if (t.length != taps.size) return
        val observations = ArrayList<KeyOffsets.Observation>(taps.size)
        for (op in EditOps.align(t, intended.lowercase())) {
            val (at, ch) = when (op) {
                is EditOps.Op.Match -> op.at to op.ch
                is EditOps.Op.Sub -> op.at to op.intended
                else -> continue
            }
            val tap = taps.getOrNull(at) ?: continue
            val center = keys.center(ch) ?: continue
            observations.add(KeyOffsets.Observation(center.x, center.y, tap.x, tap.y))
        }
        if (observations.isEmpty()) return
        tapOffsets.observe(observations)
        refreshTouchModelIfMoved()
    }

    /**
     * Hands the reported caret to the settle buffer, which uses it to notice
     * the user going back into text it is holding.
     *
     * The empty-field check is the one thing here that costs anything, and it
     * is what makes this work in a chat app: hitting send empties the field
     * and parks the caret at 0, which is indistinguishable from jumping to the
     * top of a draft until you look. Sent text is as settled as text gets, and
     * a draft the user has jumped to the top of is text they are about to
     * edit — opposite answers, so the one read is worth it. It only ever runs
     * with words queued *and* the caret at 0, so it is not on the typing path.
     */
    private fun noteCaretForLearning(oldSelStart: Int, oldSelEnd: Int, selStart: Int, selEnd: Int) {
        lastDropped = emptyList()
        if (learningBuffer.isEmpty() && correctionWatch.isEmpty()) return
        // A range selection is a selection, not a resting place: anchoring to
        // it would point entries at text that is about to be replaced.
        if (selStart != selEnd) return
        if (selStart == 0 &&
            currentInputConnection?.getTextAfterCursor(1, 0).isNullOrEmpty()
        ) {
            // An empty field that a moment ago was a selection from the top
            // was cut or typed over, not sent: nothing in it stands (#160).
            // The keyboard's own deletes have already been reported to the
            // buffer; this is the app's or a hardware keyboard's.
            if (oldSelStart == 0 && oldSelEnd > 0) learningBuffer.clear()
            // Before the caret is handed on, so a send does not read as the
            // user going back in front of every word in the message.
            flushLearningBuffer()
            return
        }
        val moved = learningBuffer.onCaret(selStart)
        if (moved.dropped.isNotEmpty()) lastDropped = moved.dropped
        // Words the caret jumped clean over on its way back are not being
        // edited: the user has left them and is working somewhere else in the
        // same text, so they count now rather than being thrown away with the
        // one word that is actually being looked at (#115). Unverified, because
        // this is a caret move and a positional suspect is not worth a blocking
        // read of the field here — see [settleLearned].
        settleLearned(moved.settled)
        correctionWatch.onCaret(selStart)
    }

    /**
     * The keyboard has removed `[start, end)` of the field: the words that
     * stood there are gone, not settled (#160). Told before the editor's
     * echo, which alone would read a stretch deleted in one go as text the
     * caret jumped clean over — the delete swipe took whole words out and
     * the personal dictionary counted them. A caller with no idea where the
     * caret is passes -1 and nothing is judged.
     */
    private fun noteDeletedForLearning(start: Int, end: Int) {
        if (start < 0 || end <= start) return
        // The glide readings behind the span move up with the text (#199).
        glideReadings.onDeleted(start, end)
        // Deleting a correction is turning it down as surely as undoing it.
        declinedSpots.onDeleted(start, end)
        if (learningBuffer.isEmpty()) return
        val dropped = learningBuffer.onDeleted(start, end)
        if (dropped.isNotEmpty()) lastDropped = dropped
    }

    /**
     * [word] has been typed and left alone enough times: it is the user's now.
     *
     * Learned with its sighting count rather than a flat 1, so a word that
     * took five uses to get here starts out weighted like the five uses it
     * was.
     */
    private fun promoteLearned(
        word: String,
        langId: String,
        sightings: Int,
        caseTrusted: Boolean,
    ) {
        pendingLearn.forget(word)
        val learned = userLexicon.learnWord(
            word,
            count = sightings,
            langId = langId,
            caseEvidence = caseTrusted,
            listedInLowerCase = caseTrusted && listedInLowerCase(word),
        )
        // Refused by the lexicon (#185): nothing to mirror, see [learnSettledWord].
        if (!learned) return
        if (_uiState.value.settings.addWordsToSystemDictionary) {
            val mirrored = if (caseTrusted) word else word.lowercase()
            serviceScope.launch(Dispatchers.IO) {
                SystemUserDictionary.add(applicationContext, mirrored)
            }
        }
    }

    /**
     * A committed emoji learns the word→emoji bigram ("you" → ❤️ after
     * "I love you ❤️"), so next-word prediction can offer the emoji the
     * next time the phrase is typed. The emoji then becomes the previous
     * "word" so emoji→word habits are learned too.
     */
    private fun learnEmoji(emoji: String) {
        // An emoji ends whatever span a pattern was reaching across, so the
        // gate has to see it land the same way a word does.
        pushRecentWord(emoji)
        val state = _uiState.value
        if (!state.settings.learnFromTyping ||
            (state.incognitoOn && state.settings.incognitoPausesLearning) ||
            !state.allowsTypingIntelligence
        ) {
            previousWord = emoji
            return
        }
        // Same gate as the word bigrams in [learn]: a habit hung off a word
        // nothing recognises is a habit hung off a possible typo, and it comes
        // back as an emoji suggestion after that misspelling forever.
        previousWord?.let { if (isKnownWord(it)) userLexicon.learnBigram(it, emoji) }
        previousWord = emoji
    }

    /**
     * Counts one use of [emoji] towards recents, frequents and the emoji row.
     *
     * Skipped in incognito, which is the one thing "Pause learning" already
     * promised and did not do: its own subtitle says no emoji habits are
     * learned, while every path that commits an emoji recorded one regardless.
     * A private message leaving its emoji at the front of the history tab is
     * exactly what incognito exists to stop.
     *
     * Separate from [learnEmoji], which is about word→emoji prediction and also
     * answers to `learnFromTyping`. The history tab is a list of what the user
     * pressed, not something inferred from it, so turning off learning does not
     * empty it.
     */
    private fun recordEmojiUse(emoji: String) {
        val state = _uiState.value
        if (state.incognitoOn && state.settings.incognitoPausesLearning) return
        emojiUsage.record(emoji)
        emojiHistoryStale = true
        // The count alone; which emoji is the usage store's business.
        recordStat { onEmoji() }
    }

    /**
     * Reads contact display names into [contactNames] (memory only, never
     * persisted). No-op without the permission — the settings app requests
     * it, and [onStartInputView] retries once it has been granted.
     */
    private fun loadContactNames() {
        if (checkSelfPermission(Manifest.permission.READ_CONTACTS) !=
            PackageManager.PERMISSION_GRANTED
        ) {
            return
        }
        serviceScope.launch {
            val loaded = withContext(Dispatchers.IO) {
                runCatching {
                    val names = ArrayList<String>()
                    contentResolver.query(
                        ContactsContract.Contacts.CONTENT_URI,
                        arrayOf(ContactsContract.Contacts.DISPLAY_NAME_PRIMARY),
                        null,
                        null,
                        null,
                    )?.use { cursor ->
                        val nameColumn = cursor.getColumnIndexOrThrow(
                            ContactsContract.Contacts.DISPLAY_NAME_PRIMARY
                        )
                        while (cursor.moveToNext()) {
                            cursor.getString(nameColumn)?.let { names.add(it) }
                        }
                    }
                    ContactNames.fromNames(names)
                }.getOrDefault(ContactNames.EMPTY)
            }
            contactNames = loaded
            suggestionEngine?.contacts = loaded
        }
    }

    /**
     * Reads contact names and phone numbers into [contactPhones] for the
     * call/message chip (memory only, never persisted). No-op without the
     * permission; the settings app requests it, and [onStartInputView] retries
     * once it has been granted.
     */
    private fun loadContactPhones() {
        if (checkSelfPermission(Manifest.permission.READ_CONTACTS) !=
            PackageManager.PERMISSION_GRANTED
        ) {
            return
        }
        serviceScope.launch {
            val loaded = withContext(Dispatchers.IO) {
                runCatching {
                    val entries = ArrayList<ContactPhones.Entry>()
                    contentResolver.query(
                        ContactsContract.CommonDataKinds.Phone.CONTENT_URI,
                        arrayOf(
                            ContactsContract.CommonDataKinds.Phone.CONTACT_ID,
                            ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME_PRIMARY,
                            ContactsContract.CommonDataKinds.Phone.NUMBER,
                            ContactsContract.CommonDataKinds.Phone.IS_SUPER_PRIMARY,
                        ),
                        null,
                        null,
                        null,
                    )?.use { cursor ->
                        val idColumn = cursor.getColumnIndexOrThrow(
                            ContactsContract.CommonDataKinds.Phone.CONTACT_ID
                        )
                        val nameColumn = cursor.getColumnIndexOrThrow(
                            ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME_PRIMARY
                        )
                        val numberColumn = cursor.getColumnIndexOrThrow(
                            ContactsContract.CommonDataKinds.Phone.NUMBER
                        )
                        val primaryColumn = cursor.getColumnIndexOrThrow(
                            ContactsContract.CommonDataKinds.Phone.IS_SUPER_PRIMARY
                        )
                        while (cursor.moveToNext()) {
                            val name = cursor.getString(nameColumn) ?: continue
                            val number = cursor.getString(numberColumn) ?: continue
                            entries.add(
                                ContactPhones.Entry(
                                    name = name,
                                    number = number,
                                    primary = cursor.getInt(primaryColumn) != 0,
                                    contactId = cursor.getLong(idColumn),
                                ),
                            )
                        }
                    }
                    ContactPhones.from(entries)
                }.getOrDefault(ContactPhones.EMPTY)
            }
            // The switch may have gone off while the query ran.
            contactPhones = if (_uiState.value.settings.smartChips.contacts) loaded else ContactPhones.EMPTY
        }
    }

    /**
     * Reads contact email addresses into [contactEmails] (memory only, never
     * persisted). No-op without the permission — the settings app requests it,
     * and [onStartInputView] retries once it has been granted.
     */
    private fun loadContactEmails() {
        if (checkSelfPermission(Manifest.permission.READ_CONTACTS) !=
            PackageManager.PERMISSION_GRANTED
        ) {
            return
        }
        serviceScope.launch {
            val loaded = withContext(Dispatchers.IO) {
                runCatching {
                    val emails = ArrayList<String>()
                    contentResolver.query(
                        ContactsContract.CommonDataKinds.Email.CONTENT_URI,
                        arrayOf(ContactsContract.CommonDataKinds.Email.ADDRESS),
                        null,
                        null,
                        null,
                    )?.use { cursor ->
                        val addressColumn = cursor.getColumnIndexOrThrow(
                            ContactsContract.CommonDataKinds.Email.ADDRESS
                        )
                        while (cursor.moveToNext()) {
                            cursor.getString(addressColumn)?.let { emails.add(it) }
                        }
                    }
                    ContactEmails.fromAddresses(emails)
                }.getOrDefault(ContactEmails.EMPTY)
            }
            contactEmails = loaded
            suggestionEngine?.contactEmails = loaded
        }
    }

    /**
     * Reads the labels of launchable apps into [appNames] (memory only,
     * never persisted). Needs no permission: the launcher-intent query is
     * covered by the <queries> manifest entry.
     */
    private fun loadAppNames() {
        serviceScope.launch {
            val loaded = withContext(Dispatchers.IO) {
                runCatching {
                    val intent = Intent(Intent.ACTION_MAIN)
                        .addCategory(Intent.CATEGORY_LAUNCHER)
                    val pm = packageManager
                    val labels = pm.queryIntentActivities(intent, 0)
                        .map { it.loadLabel(pm).toString() }
                        .distinct()
                    AppNames.fromNames(labels)
                }.getOrDefault(AppNames.EMPTY)
            }
            appNames = loaded
            suggestionEngine?.apps = loaded
        }
    }

    /**
     * Reads Android's personal dictionary into [systemDictionaryWords] and
     * [userDictShortcuts]. Content-provider I/O: call off the main thread.
     * The words honour [SuggestionStripSettings.useSystemDictionary] here,
     * so turning the setting off empties the source; the shortcut map is
     * gated where it is consulted instead, as it always was.
     */
    private fun readSystemDictionary() {
        val settings = _uiState.value.settings.suggestionStrip
        systemDictLoadedWith = settings.useSystemDictionary
        systemDictionaryWords = if (settings.useSystemDictionary) {
            runCatching { SystemUserDictionary.words(applicationContext) }
                .getOrDefault(SystemUserDictionary.Entries.EMPTY)
        } else {
            SystemUserDictionary.Entries.EMPTY
        }
        userDictShortcuts = runCatching { SystemUserDictionary.shortcuts(applicationContext) }
            .getOrDefault(emptyMap())
    }

    /**
     * Re-reads the personal dictionary and hands the words to the engine.
     * Called when the platform reports the list changed and when the setting
     * flips; a no-op before the dictionaries have loaded, since that load
     * reads the list itself.
     */
    private fun reloadSystemDictionary() {
        if (suggestionEngine == null) return
        serviceScope.launch {
            withContext(Dispatchers.IO) { readSystemDictionary() }
            suggestionEngine?.let {
                it.systemWordCases = systemDictionaryWords.shapes
                it.systemDictionary = systemDictionaryWords.source
            }
        }
    }

    /**
     * Keeps [systemDictionaryWords] current across edits made in System
     * settings (or by another keyboard) while this one runs. Registered
     * unconditionally: the observer is free, and the reload it triggers is
     * what honours the setting.
     */
    private fun startUserDictionaryWatch() {
        val observer = object : android.database.ContentObserver(
            android.os.Handler(android.os.Looper.getMainLooper()),
        ) {
            override fun onChange(selfChange: Boolean, uri: android.net.Uri?) {
                super.onChange(selfChange, uri)
                reloadSystemDictionary()
            }
        }
        userDictObserver = observer
        runCatching {
            contentResolver.registerContentObserver(
                android.provider.UserDictionary.Words.CONTENT_URI,
                true,
                observer,
            )
        }
    }

    // ---- app launcher tool ----

    /**
     * The launchable-app list, loaded once per process and reused across panel
     * opens; a package install/remove drops it (see [packageChangeReceiver])
     * so the next open re-enumerates.
     */
    private var launcherAppsCache: List<LauncherApp>? = null

    /** Whether [launcherAppsCache] holds the other profiles' apps (#924). */
    private var launcherAppsCacheWork = false

    /**
     * Decoded app icons, keyed by flattened component. Lives for the process —
     * a panel close is not a reason to re-decode a hundred icons, and a size
     * change only scales what is already decoded.
     *
     * Bounded by **bytes**, like [BackgroundBitmapCache] and
     * [LayoutPreviewCache], and not by entry count. It used to hold 128
     * entries on the claim that that was "under two megabytes", which was off
     * by most of an order of magnitude: [launcherIconFor] decodes every icon
     * at the top of `ICON_SIZE_RANGE` (60 dp) so a size change never re-reads
     * the package manager, and 60 dp on an ordinary xxhdpi phone is 180 px of
     * ARGB_8888 — 127 KB an icon, 16 MB once a user with a full app drawer has
     * scrolled the grid. On the low-memory phones this keyboard has to live on
     * that is the single largest thing a tool can leave behind, and nothing
     * ever dropped it.
     *
     * The budget is a share of the heap rather than a constant because the
     * ceiling that matters is the process's, not the icon's. Four megabytes on
     * a typical device still holds thirty-odd icons, which is more than one
     * screen of the grid and all of its scrollback.
     */
    private val launcherIconCache = object : android.util.LruCache<String, ImageBitmap>(
        (Runtime.getRuntime().maxMemory() / 32)
            .coerceIn(LAUNCHER_ICON_MIN_BUDGET, LAUNCHER_ICON_MAX_BUDGET)
            .toInt(),
    ) {
        override fun sizeOf(key: String, value: ImageBitmap): Int = value.width * value.height * 4
    }

    private var launcherDetailJob: Job? = null

    /** One stable bundle for the panel; see [LauncherPanelCallbacks]'s doc. */
    private val launcherCallbacks by lazy {
        com.wasimaster.wmkeyboard.ime.ui.LauncherPanelCallbacks(
            onAppTap = ::onLauncherAppTap,
            onOpenDetail = ::onLauncherOpenDetail,
            onActivityTap = ::onLauncherActivityTap,
            onPinToggle = ::onLauncherPinToggle,
            onAppInfo = ::onLauncherAppInfo,
            onDetailClose = ::onLauncherDetailClose,
            onHideToggle = ::onLauncherHideToggle,
            iconFor = ::launcherIconFor,
            onAppOpen = ::onLauncherAppOpen,
            onComboTap = ::onLauncherComboTap,
            onComboAdd = ::onLauncherComboAdd,
            onComboRemove = ::onLauncherComboRemove,
            splitAvailable = { AppLaunchModes.splitSupported(this) },
            freeformAvailable = { AppLaunchModes.freeformSupported(this) },
            folders = com.wasimaster.wmkeyboard.ime.ui.LauncherFolderCallbacks(
                onOpen = ::onLauncherFolderOpen,
                onNew = ::onLauncherFolderNew,
                onAddTo = ::onLauncherFolderAddTo,
                onTakeOut = ::onLauncherFolderTakeOut,
                onRename = ::onLauncherFolderRename,
                onRenameDone = { onLauncherFolderRenameDone(keep = true) },
                onMove = ::onLauncherFolderMove,
                onDelete = ::onLauncherFolderDelete,
                onGroupByCategory = ::onLauncherGroupByCategory,
            ),
        )
    }

    /** Drops the app list and its icons; the next open, or this one, lists again. */
    private fun invalidateLauncherApps() {
        launcherAppsCache = null
        launcherIconCache.evictAll()
        _uiState.update { it.copy(launcherApps = emptyList(), launcherDetail = null) }
        if (_uiState.value.panel == PanelMode.APP_LAUNCHER) loadLauncherApps()
    }

    private val packageChangeReceiver = object : BroadcastReceiver() {
        override fun onReceive(context: Context, intent: Intent) {
            com.wasimaster.wmkeyboard.ime.floating.FloatingAppIcons.clear()
            invalidateLauncherApps()
        }
    }

    /**
     * The other profiles' installs and removals, and a work profile paused or
     * turned back on (#924): none of these reach [packageChangeReceiver],
     * whose broadcasts are this user's own.
     */
    private val launcherProfileCallback = object : android.content.pm.LauncherApps.Callback() {
        override fun onPackageRemoved(packageName: String, user: android.os.UserHandle) = changed(user)
        override fun onPackageAdded(packageName: String, user: android.os.UserHandle) = changed(user)
        override fun onPackageChanged(packageName: String, user: android.os.UserHandle) = changed(user)
        override fun onPackagesAvailable(names: Array<out String>, user: android.os.UserHandle, replacing: Boolean) =
            changed(user)
        override fun onPackagesUnavailable(names: Array<out String>, user: android.os.UserHandle, replacing: Boolean) =
            changed(user)

        private fun changed(user: android.os.UserHandle) {
            if (user != android.os.Process.myUserHandle()) invalidateLauncherApps()
        }
    }

    private val profileStateReceiver = object : BroadcastReceiver() {
        override fun onReceive(context: Context, intent: Intent) {
            if (launcherAppsCacheWork) invalidateLauncherApps()
        }
    }

    /**
     * Stays registered for the rest of the process's life, like the DND
     * observer ([startDndWatch]): an IME process dies with its receivers, and
     * an install/removal while the keyboard is up is exactly the case the
     * cache invalidation has to catch.
     */
    internal fun registerPackageChangeReceiver() {
        val filter = IntentFilter().apply {
            addAction(Intent.ACTION_PACKAGE_ADDED)
            addAction(Intent.ACTION_PACKAGE_REMOVED)
            addAction(Intent.ACTION_PACKAGE_REPLACED)
            addDataScheme("package")
        }
        registerReceiver(packageChangeReceiver, filter)
        // Sent to registered receivers of the parent profile only, and
        // protected, so nothing but the system can send them.
        val profiles = IntentFilter().apply {
            addAction(Intent.ACTION_MANAGED_PROFILE_ADDED)
            addAction(Intent.ACTION_MANAGED_PROFILE_REMOVED)
            addAction(Intent.ACTION_MANAGED_PROFILE_AVAILABLE)
            addAction(Intent.ACTION_MANAGED_PROFILE_UNAVAILABLE)
            addAction(Intent.ACTION_MANAGED_PROFILE_UNLOCKED)
        }
        runCatching { registerReceiver(profileStateReceiver, profiles) }
        runCatching {
            getSystemService(android.content.pm.LauncherApps::class.java)
                ?.registerCallback(launcherProfileCallback, android.os.Handler(mainLooper))
        }
    }

    /** Fills [KeyboardUiState.launcherApps] from the cache or a fresh query. */
    private fun loadLauncherApps() {
        val work = _uiState.value.settings.launcher.showWorkApps
        val cached = launcherAppsCache?.takeIf { launcherAppsCacheWork == work }
        if (cached != null) {
            _uiState.update { it.copy(launcherApps = cached, launcherLoading = false) }
            return
        }
        _uiState.update { it.copy(launcherLoading = true) }
        serviceScope.launch {
            // Failure handling lives inside loadApps (empty list), so nothing
            // here swallows a coroutine cancellation by accident.
            val apps = AppCatalog.loadAllApps(this@WMKeyboardService, otherProfiles = work)
            launcherAppsCache = apps
            launcherAppsCacheWork = work
            _uiState.update { it.copy(launcherApps = apps, launcherLoading = false) }
        }
    }

    /** One app's icon for the panel grid, through the LRU, decoded on IO. */
    internal suspend fun launcherIconFor(app: LauncherApp): ImageBitmap? {
        val key = "${app.key}/${app.activityName}"
        launcherIconCache.get(key)?.let { return it }
        val bitmap = withContext(Dispatchers.IO) {
            runCatching {
                val dp = com.wasimaster.wmkeyboard.core.settings.LauncherToolSettings
                    .ICON_SIZE_RANGE.last
                val px = (dp * resources.displayMetrics.density).toInt().coerceAtLeast(1)
                profileIcon(app)
                    ?: packageManager.getActivityIcon(app.component)
                        .toBitmap(px, px)
                        .asImageBitmap()
            }.getOrNull()
        } ?: return null
        launcherIconCache.put(key, bitmap)
        return bitmap
    }

    /**
     * Another profile's icon, unbadged: the panel draws its own briefcase,
     * outside the circle or square it clips icons to, where the system's
     * corner badge would be cut off. Null for the keyboard's own profile.
     */
    private fun profileIcon(app: LauncherApp): ImageBitmap? {
        val serial = app.profile ?: return null
        val user = AppCatalog.profileHandle(this, serial) ?: return null
        val info = getSystemService(android.content.pm.LauncherApps::class.java)
            ?.getActivityList(app.packageName, user)
            ?.firstOrNull { it.componentName.className == app.activityName }
            ?: return null
        val dp = com.wasimaster.wmkeyboard.core.settings.LauncherToolSettings.ICON_SIZE_RANGE.last
        val px = (dp * resources.displayMetrics.density).toInt().coerceAtLeast(1)
        return info.getIcon(resources.displayMetrics.densityDpi).toBitmap(px, px).asImageBitmap()
    }

    /** A plain tap opens the app the way the **Open apps** setting says. */
    fun onLauncherAppTap(app: LauncherApp) {
        onLauncherAppOpen(app, effectiveLauncherOpenMode())
    }

    /** One app in an explicit mode, from the hold menu or a plain tap. */
    fun onLauncherAppOpen(app: LauncherApp, mode: LauncherOpenMode) {
        val serial = app.profile
        if (serial != null) {
            launchInProfile(app.component, serial, app.key, mode)
            return
        }
        launchFromLauncherPanel(launcherIntentFor(app), app.key, mode)
    }

    fun onLauncherActivityTap(activity: LauncherActivity) {
        val serial = activity.profile
        if (serial != null) {
            launchInProfile(
                activity.component, serial, "${activity.packageName}@$serial", effectiveLauncherOpenMode(),
            )
            return
        }
        launchFromLauncherPanel(
            Intent().setComponent(activity.component),
            activity.packageName,
            effectiveLauncherOpenMode(),
        )
    }

    /**
     * Starts an app of another profile (#924) through [LauncherApps], the one
     * door into a work profile that needs no permission. A paused profile is
     * still asked: Android puts up its own "Turn on work apps?" dialog over
     * the launch. Split screen needs an intent flag this call has no room
     * for, so it opens full screen; a floating window keeps its options.
     */
    private fun launchInProfile(component: ComponentName, serial: Long, key: String, mode: LauncherOpenMode) {
        val user = AppCatalog.profileHandle(this, serial) ?: return
        val launcher = getSystemService(android.content.pm.LauncherApps::class.java) ?: return
        val started = runCatching {
            val options = AppLaunchModes.prepare(
                this, Intent().setComponent(component), mode.takeIf { it == LauncherOpenMode.FLOATING }
                    ?: LauncherOpenMode.NORMAL,
                null,
            )
            launcher.startMainActivity(component, user, null, options)
        }.isSuccess
        if (!started) return
        serviceScope.launch { settingsRepository.addLauncherRecent(key) }
        closeLauncherPanel()
    }

    /**
     * The tap setting, with split screen falling back to a plain open where it
     * cannot work: a setting restored from a newer phone must not leave every
     * tap doing nothing.
     */
    private fun effectiveLauncherOpenMode(): LauncherOpenMode {
        val mode = _uiState.value.settings.launcher.openMode
        return if (mode == LauncherOpenMode.SPLIT && !AppLaunchModes.splitSupported(this)) {
            LauncherOpenMode.NORMAL
        } else {
            mode
        }
    }

    private fun launcherIntentFor(app: LauncherApp): Intent =
        packageManager.getLaunchIntentForPackage(app.packageName)
            ?: Intent().setComponent(app.component)

    /** The launch intent of an installed package, or null when it is gone. */
    private fun launcherIntentFor(packageName: String): Intent? =
        runCatching { packageManager.getLaunchIntentForPackage(packageName) }.getOrNull()

    /**
     * Starts the target and closes the panel — the foreground app is about to
     * change, so a keyboard left showing the launcher would be stale. Failures
     * (a non-exported activity, an OEM background-start rule) just keep the
     * panel up.
     *
     * In split screen with the split-screen helper on, the helper first puts
     * the app in front into split screen and the launch follows once the free
     * half is up (see AppLaunchModes).
     */
    private fun launchFromLauncherPanel(
        intent: Intent,
        packageName: String,
        mode: LauncherOpenMode = LauncherOpenMode.NORMAL,
    ) {
        val foreground = currentInputEditorInfo?.packageName
        if (mode == LauncherOpenMode.SPLIT && AppLaunchModes.splitHelper()?.enterSplit() == true) {
            closeLauncherPanel()
            launcherComboJob?.cancel()
            launcherComboJob = serviceScope.launch {
                delay(AppLaunchModes.HELPER_LAUNCH_DELAY_MS)
                if (startLauncherIntent(intent, mode, foreground)) settingsRepository.addLauncherRecent(packageName)
            }
            return
        }
        if (!startLauncherIntent(intent, mode, foreground)) return
        serviceScope.launch { settingsRepository.addLauncherRecent(packageName) }
        closeLauncherPanel()
    }

    private fun startLauncherIntent(
        intent: Intent,
        mode: LauncherOpenMode,
        foregroundPackage: String?,
    ): Boolean = runCatching {
        val options = AppLaunchModes.prepare(this, intent, mode, foregroundPackage)
        startActivity(intent, options)
    }.isSuccess

    private fun closeLauncherPanel() {
        if (_uiState.value.panel == PanelMode.APP_LAUNCHER) {
            onPanelChange(PanelMode.APP_LAUNCHER)
        }
    }

    private var launcherComboJob: Job? = null

    /**
     * Opens a split pair: the first app full screen, then — once it is the
     * top task — the second with the launch-adjacent flag, which the system
     * split screen turns into a pair. Both launches run from here because the
     * keyboard stays the current input method (and so exempt from the
     * background-start rules) after the first app takes focus. With the
     * split-screen helper on, the helper presses the system's split-screen
     * switch between the two, and the second launch waits for the free half.
     */
    fun onLauncherComboTap(combo: LauncherSplitCombo) {
        val first = launcherIntentFor(combo.first) ?: return
        val second = launcherIntentFor(combo.second) ?: return
        if (!AppLaunchModes.splitSupported(this)) {
            launchFromLauncherPanel(first, combo.first)
            return
        }
        launcherComboJob?.cancel()
        if (!startLauncherIntent(first, LauncherOpenMode.NORMAL, null)) return
        closeLauncherPanel()
        launcherComboJob = serviceScope.launch {
            if (AppLaunchModes.splitHelper() != null) {
                delay(AppLaunchModes.helperComboDelayMs())
                if (AppLaunchModes.splitHelper()?.enterSplit() == true) delay(AppLaunchModes.HELPER_LAUNCH_DELAY_MS)
            } else {
                delay(AppLaunchModes.COMBO_SECOND_LAUNCH_DELAY_MS)
            }
            startLauncherIntent(second, LauncherOpenMode.SPLIT, combo.first)
            settingsRepository.addLauncherRecent(combo.second)
            settingsRepository.addLauncherRecent(combo.first)
        }
    }

    fun onLauncherComboAdd(combo: LauncherSplitCombo) {
        serviceScope.launch { settingsRepository.addLauncherCombo(combo) }
    }

    fun onLauncherComboRemove(combo: LauncherSplitCombo) {
        serviceScope.launch { settingsRepository.removeLauncherCombo(combo) }
    }

    /**
     * Opens the app's page. With **Open screens inside apps** off the page is
     * the pin/hide/App-info actions alone, so the activity query — a package
     * manager round trip — never runs.
     */
    fun onLauncherOpenDetail(app: LauncherApp) {
        launcherDetailJob?.cancel()
        if (!_uiState.value.settings.launcher.activityDrilldown) {
            _uiState.update { it.copy(launcherDetail = LauncherDetailUi(app, loading = false)) }
            return
        }
        _uiState.update { it.copy(launcherDetail = LauncherDetailUi(app)) }
        launcherDetailJob = serviceScope.launch {
            val activities = if (app.otherProfile) {
                AppCatalog.loadProfileActivities(this@WMKeyboardService, app)
            } else {
                AppCatalog.loadActivities(packageManager, app.packageName)
            }
            _uiState.update { state ->
                val detail = state.launcherDetail
                if (detail?.app?.key == app.key) {
                    state.copy(
                        launcherDetail = detail.copy(activities = activities, loading = false),
                    )
                } else {
                    state
                }
            }
        }
    }

    fun onLauncherDetailClose() {
        launcherDetailJob?.cancel()
        _uiState.update { it.copy(launcherDetail = null) }
    }

    /** [key] is the app's [LauncherApp.key], as for hiding. */
    fun onLauncherPinToggle(key: String) {
        serviceScope.launch { settingsRepository.toggleLauncherPin(key) }
    }

    /**
     * Hiding closes the detail view: the app just left the grid, so staying
     * on its page would leave the user looking at something they asked to
     * put away. Showing it again keeps the page open.
     */
    fun onLauncherHideToggle(key: String) {
        val hiding = key !in _uiState.value.settings.launcher.hidden
        serviceScope.launch { settingsRepository.toggleLauncherHidden(key) }
        if (hiding) onLauncherDetailClose()
    }

    /** The system's App info page; a work app's is the work profile's own. */
    fun onLauncherAppInfo(app: LauncherApp) {
        val serial = app.profile
        if (serial != null) {
            runCatching {
                val user = AppCatalog.profileHandle(this, serial) ?: return
                getSystemService(android.content.pm.LauncherApps::class.java)
                    ?.startAppDetailsActivity(app.component, user, null, null)
            }
            return
        }
        runCatching {
            startActivity(
                Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS)
                    .setData(android.net.Uri.fromParts("package", app.packageName, null))
                    .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK),
            )
        }
    }

    // ---- app launcher folders (#919) ----

    /** Opens a folder in the grid; null goes back up to the whole grid. */
    fun onLauncherFolderOpen(id: String?) {
        vibrate()
        _uiState.update {
            it.copy(launcherView = LauncherUi(folderOpen = id), launcherDetail = null, panelFocus = null)
        }
    }

    /**
     * A new folder holding [app], opened with its name box up and empty: what
     * is typed names it, and Enter on nothing keeps the placeholder name.
     */
    fun onLauncherFolderNew(app: LauncherApp) {
        vibrate()
        val folders = _uiState.value.settings.launcher.folders
        val id = folders.nextLauncherFolderId()
        val name = getString(R.string.ime_launcher_folder_default_name)
        serviceScope.launch {
            settingsRepository.updateLauncherFolders { it.withNewLauncherFolder(id, name, app.key) }
        }
        _uiState.update {
            it.copy(
                launcherView = LauncherUi(folderOpen = id, nameDraft = ""),
                mediaSearchActive = false,
                mediaQuery = "",
                panelFocus = null,
            )
        }
    }

    fun onLauncherFolderAddTo(app: LauncherApp, folderId: String) {
        vibrate()
        serviceScope.launch { settingsRepository.updateLauncherFolders { it.withLauncherAppIn(app.key, folderId) } }
    }

    /** Back to a cell of its own; a folder emptied by it goes, and the grid with it. */
    fun onLauncherFolderTakeOut(app: LauncherApp) {
        vibrate()
        val state = _uiState.value
        val open = state.settings.launcher.folders.launcherFolderById(state.launcherView.folderOpen)
        if (open != null && open.apps == listOf(app.key)) {
            _uiState.update { it.copy(launcherView = LauncherUi()) }
        }
        serviceScope.launch { settingsRepository.updateLauncherFolders { it.withoutLauncherApp(app.key) } }
    }

    /** The folder's name tapped, or Rename in its menu: the keys type a new one. */
    fun onLauncherFolderRename(id: String) {
        val folder = _uiState.value.settings.launcher.folders.launcherFolderById(id) ?: return
        vibrate()
        _uiState.update {
            it.copy(
                launcherView = LauncherUi(folderOpen = id, nameDraft = folder.name),
                mediaSearchActive = false,
                mediaQuery = "",
                panelFocus = null,
            )
        }
    }

    /** Ends a rename: [keep] saves the typed name unless it is blank; back drops it. */
    private fun onLauncherFolderRenameDone(keep: Boolean) {
        val view = _uiState.value.launcherView
        val draft = view.nameDraft ?: return
        _uiState.update { it.copy(launcherView = it.launcherView.copy(nameDraft = null)) }
        val id = view.folderOpen ?: return
        if (!keep || draft.isBlank()) return
        vibrate()
        serviceScope.launch { settingsRepository.updateLauncherFolders { it.renamedLauncherFolder(id, draft) } }
    }

    /** One place earlier (negative) or later among the folders. */
    fun onLauncherFolderMove(id: String, by: Int) {
        vibrate()
        serviceScope.launch { settingsRepository.updateLauncherFolders { it.movedLauncherFolder(id, by) } }
    }

    /** Removes the folder; its apps go back to the grid. */
    fun onLauncherFolderDelete(id: String) {
        vibrate()
        if (_uiState.value.launcherView.folderOpen == id) _uiState.update { it.copy(launcherView = LauncherUi()) }
        serviceScope.launch { settingsRepository.updateLauncherFolders { it.withoutLauncherFolder(id) } }
    }

    /**
     * Files every app in no folder yet into a folder per Play category, named
     * the way Android names the category in the phone's language. The home
     * screen's own folders would be the better source, but Android gives no
     * app but the home screen a way to read them; the categories are what
     * each app declares about itself, and many apps declare none.
     */
    fun onLauncherGroupByCategory() {
        vibrate()
        val apps = _uiState.value.launcherApps
        val titles = HashMap<Int, String?>()
        val groups = AppCatalog.categoryGroups(apps) { category ->
            titles.getOrPut(category) {
                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                    runCatching {
                        android.content.pm.ApplicationInfo.getCategoryTitle(this, category)?.toString()
                    }.getOrNull()
                } else {
                    null
                }
            }
        }
        if (groups.isEmpty()) {
            Toast.makeText(this, R.string.ime_launcher_group_none_toast, Toast.LENGTH_SHORT).show()
            return
        }
        serviceScope.launch { settingsRepository.updateLauncherFolders { it.withGroupedLauncherApps(groups) } }
    }

    /** Arms or clears the dead-key accent, keeping the strip chip in step. */
    private fun setPendingDeadKey(mark: Char?) {
        pendingDeadKey = mark
        val label = mark?.let { DeadKeys.standalone(it) }
        if (_uiState.value.pendingDeadKey != label) {
            _uiState.update { it.copy(pendingDeadKey = label) }
        }
    }

    /** Heuristic: a learned bigram successor that is an emoji, not a word. */
    private fun isEmojiCandidate(text: String): Boolean =
        text.isNotBlank() && text.none { it.isLetterOrDigit() } && text.any { it.code > 0x2000 }

    /**
     * The inline emoji query when the composing buffer is one — ":smi" gives
     * "smi". Null whenever inline search is off or the buffer is an ordinary
     * word, so callers can branch on it directly.
     */
    private fun inlineEmojiQuery(): String? {
        if (!_uiState.value.settings.suggestionSources.inlineEmojiSearch) return null
        val typed = composing.toString()
        return if (typed.startsWith(":")) typed.drop(1) else null
    }

    // ---- smart suggestions (inline tool answers) ----

    /**
     * Re-scans the text before the cursor for something a tool can answer —
     * a sum, an amount in a currency, a measurement, a tool keyword — and
     * parks the result in [KeyboardUiState.smart] for the strip to draw.
     *
     * Cheap enough to run inline on every keystroke: one short
     * `getTextBeforeCursor` plus a handful of anchored regexes over at most
     * [SmartSuggest.LOOKBEHIND] characters. It deliberately does not follow
     * `settings.suggestions` — someone who turned word prediction off may
     * still want "12*4" answered — but it does respect the field's own
     * refusal to take suggestions, and never runs in a password field.
     */
    /**
     * Text before the cursor as it stood right after a chip was accepted.
     * An inserted answer is often itself a trigger ("18,300.00 BDT" reads as
     * an amount to convert back), so the chip stays down until the field
     * changes again — matching on the text rather than a flag means any
     * edit at all, from anywhere, lifts the mute.
     */
    private var smartMutedAfter: String? = null

    /**
     * What a chip's gear took out of the field on its way into the tool, and
     * where that left the caret (-1 until the delete's own echo says). The
     * first backspace while the caret is still there puts the text back
     * instead of deleting (#665), the way backspace takes back an autocorrect.
     * Anything that moves the caret first — the tool typing its answer, a
     * letter, a tap elsewhere — drops it.
     */
    private var chipOpenRestore: ChipOpenRestore? = null

    private data class ChipOpenRestore(val text: String, val caret: Int)

    /**
     * Intent chips this field has already shown and moved past. An intent
     * chip is a hint, and a hint repeated is a nag: once the chip stops
     * matching (the user typed on, opened the tool, or a panel came up), the
     * same tool does not get to hint again until the next field.
     */
    private val intentChipsRetired = mutableSetOf<ToolbarTool>()

    /**
     * Contacts whose chip this field has already offered and moved past, by
     * display name. The same rule as [intentChipsRetired]: a name typed in a
     * chat is usually meant for the chat, so the offer to call comes once.
     */
    private val contactChipsRetired = mutableSetOf<String>()

    /**
     * Texts (lowercase) whose repeat chip this field has already shown and
     * moved past. Same rule again: "no no no" gets one offer, and typing on
     * past it is the answer.
     */
    private val repeatChipsRetired = mutableSetOf<String>()

    /** Records [next] replacing (or clearing) a shown intent or lookup chip. */
    private fun retireIntentChip(next: SmartSuggest.SmartHit?) {
        val prev = _uiState.value.smart ?: return
        if (prev.kind == SmartSuggest.Kind.REPEAT) {
            if (next == null || next.kind != prev.kind || !next.query.equals(prev.query, ignoreCase = true)) {
                repeatChipsRetired += prev.query.lowercase(Locale.ROOT)
            }
            return
        }
        if (prev.kind == SmartSuggest.Kind.VOCAB) {
            // Typed past, or another word took the chip: the same word does
            // not nudge again until the cooldown says so.
            if (next == null || next.kind != prev.kind || !next.query.equals(prev.query, ignoreCase = true)) {
                retireVocabNudge(prev.query)
            }
            return
        }
        if (prev.kind == SmartSuggest.Kind.CONTACT) {
            if (next == null || next.kind != prev.kind || next.query != prev.query) {
                contactChipsRetired += prev.query
            }
            return
        }
        if (prev.kind != SmartSuggest.Kind.INTENT && prev.kind != SmartSuggest.Kind.LOOKUP) return
        if (next != null && next.kind == prev.kind && next.tool == prev.tool) return
        intentChipsRetired += prev.tool
    }

    private fun clearSmartChip() {
        retireIntentChip(null)
        if (_uiState.value.smart != null) _uiState.update { it.copy(smart = null) }
    }

    private fun refreshSmartSuggestion() {
        // Every path that re-reads the text for a chip re-reads it for the
        // stickers too; they have their own gate, below.
        refreshStickerOffer()
        // And for the AI continuation, which waits for the typing to rest.
        scheduleAiSuggest()
        val state = _uiState.value
        val enabled = state.settings.smartSuggestions &&
            !state.secureField && !state.fieldNoSuggestions &&
            state.panel == PanelMode.NONE &&
            // A smart chip takes the whole strip, and in a conversion IME that
            // strip is the candidate list — losing it mid-reading would leave
            // the user with a composing buffer and nothing to commit it with.
            !state.composer.isConversion
        if (!enabled) {
            clearSmartChip()
            return
        }
        val ic = currentInputConnection
        if (ic == null) {
            clearSmartChip()
            return
        }
        // The lookbehind is a synchronous editor round-trip and this runs on
        // every keystroke, so it goes to a worker thread: with the target app
        // busy (first key into a just-opened field, especially) the blocking
        // read was the visible keypress lag — and the chip is advisory UI
        // that can afford to land a frame later.
        smartJob?.cancel()
        smartJob = serviceScope.launch {
            // Debounced before the read, not after. One keystroke reaches here
            // twice — once from refreshSuggestions and once from the
            // onUpdateSelection the commit provokes — and cancelling the first
            // job did not help, because by the time the selection update
            // arrives that job has already issued its round-trip into the
            // target app and been answered. Sleeping first means the second
            // scheduling cancels the first while it is still asleep, so a
            // keystroke costs one cross-process read instead of two. The chip
            // is advisory and lands about a frame later than it did.
            delay(SMART_SUGGEST_DEBOUNCE_MS)
            // The gate above was read before the sleep. A panel opening, or the
            // field turning out to be secure, does not cancel this job — so
            // re-read it, or the chip publishes into a state that refuses to
            // show one. The window is only as long as the debounce, but it is
            // the debounce that created it.
            val still = _uiState.value
            if (still.panel != PanelMode.NONE || still.secureField ||
                still.fieldNoSuggestions || !still.settings.smartSuggestions ||
                // Same list as the gate above, conversion composer included: a
                // layout switch inside the debounce window would otherwise let
                // a chip take the row the candidate list needs.
                still.composer.isConversion
            ) {
                clearSmartChip()
                return@launch
            }
            // The context is read here, on the main thread, where the state
            // it copies from is written; the detection itself — dates, sums,
            // units, currencies, keywords, vocabulary — is a scan over the
            // text that has no business on the thread drawing the keys, so it
            // runs beside the read that fetched the text.
            val ctx = smartContext(_uiState.value)
            val muted = smartMutedAfter
            val detected = withContext(Dispatchers.Default) {
                val before = ic.getTextBeforeCursor(smartLookbehind(), 0)?.toString().orEmpty()
                before to if (before == muted) null else SmartSuggest.detect(before, ctx)
            }
            if (detected.first == smartMutedAfter) {
                clearSmartChip()
                return@launch
            }
            smartMutedAfter = null
            var hit = detected.second
            // A retired hint stays down; answers (calc, dates, weather) are
            // immune — they carry information, not advice.
            if (hit != null &&
                (hit.kind == SmartSuggest.Kind.INTENT || hit.kind == SmartSuggest.Kind.LOOKUP) &&
                hit.tool in intentChipsRetired
            ) {
                hit = null
            }
            if (hit != null && hit.kind == SmartSuggest.Kind.CONTACT && hit.query in contactChipsRetired) {
                hit = null
            }
            retireIntentChip(hit)
            if (hit != _uiState.value.smart) _uiState.update { it.copy(smart = hit) }
            // Recognised but missing data: fetch it, and the completion
            // redraws the chip. With weather.autoFetch or rateSources.autoFetch
            // off, the chip waits for a tap instead. A weather hit is pending
            // too, so it must never fall through to the rates branch.
            val chipSettings = _uiState.value.settings
            when {
                hit?.pendingWeather == true -> if (chipSettings.weather.autoFetch) refreshWeather()
                hit?.pending == true -> if (chipSettings.rateSources.autoFetch) {
                    refreshCurrencyRates(wantCrypto = hit.pendingCrypto)
                }
            }
        }
    }

    /** Drops the AI chip and whatever request was on its way to it. */
    private fun clearAiSuggest() {
        aiSuggestSeq++
        aiSuggestJob?.cancel()
        aiSuggestJob = null
        if (_uiState.value.aiSuggest != null) _uiState.update { it.copy(aiSuggest = null) }
    }

    /** The gate for the AI continuation, read from [state] as it is now. */
    private fun aiSuggestField(state: KeyboardUiState): AiContinuation.Field =
        AiContinuation.Field(
            enabled = state.settings.ai.stripSuggest,
            providerConfigured = aiSuggestProviderReady(state.settings),
            secureField = state.secureField,
            noSuggestions = state.fieldNoSuggestions,
            incognito = state.incognitoOn,
            suppressed = aiSuggestSuppressed,
        )

    /**
     * Whether the AI tool's provider can answer a continuation without asking
     * anything: set up, and for a server, not held back by data saving. A
     * phone model has to be downloaded and in this build.
     */
    private fun aiSuggestProviderReady(settings: KeyboardSettings): Boolean {
        if (!AiClient.isConfigured(settings.ai)) return false
        if (settings.ai.provider == AiProvider.ON_DEVICE) {
            return BuildConfig.ENABLE_LOCAL_LLM && effectiveLocalModelFile(settings) != null
        }
        return dataSaverStatus.decide(MeteredFeature.CLOUD_AI) == MeteredDecision.ALLOWED
    }

    /**
     * Restarts the AI continuation's wait (#944). Every keystroke and caret
     * move lands here: the chip shown for the old text goes, the request in
     * flight for it is abandoned, and a new one is asked for only once a word
     * has ended and the typing has rested for [AiContinuation.IDLE_MS].
     */
    private fun scheduleAiSuggest() {
        clearAiSuggest()
        val state = _uiState.value
        if (!AiContinuation.allowed(aiSuggestField(state)) ||
            state.panel != PanelMode.NONE || readingInBuffer(state)
        ) {
            return
        }
        val ic = currentInputConnection ?: return
        val seq = aiSuggestSeq
        aiSuggestJob = serviceScope.launch {
            delay(AiContinuation.IDLE_MS)
            // Re-read after the pause: a panel, a password field or incognito
            // can have arrived without a keystroke to cancel this.
            val still = _uiState.value
            if (seq != aiSuggestSeq || !AiContinuation.allowed(aiSuggestField(still)) ||
                still.panel != PanelMode.NONE || readingInBuffer(still)
            ) {
                return@launch
            }
            val settings = still.settings
            val before = withContext(Dispatchers.Default) {
                ic.getTextBeforeCursor(settings.ai.stripSuggestChars + AiContinuation.READ_SLACK, 0)?.toString()
            } ?: return@launch
            // A selection is not a place to continue from.
            if (expectedSelStart != expectedSelEnd) return@launch
            if (!AiContinuation.atWordBoundary(before)) return@launch
            val context = AiContinuation.context(
                before, settings.ai.stripSuggestChars, settings.ai.stripSuggestWordOnly,
            ) ?: return@launch
            val answer = withContext(Dispatchers.IO) {
                runCatching { requestAiContinuation(context, settings, seq) }.getOrNull()
            } ?: return@launch
            if (seq != aiSuggestSeq || !AiContinuation.allowed(aiSuggestField(_uiState.value))) return@launch
            _uiState.update { it.copy(aiSuggest = answer) }
        }
    }

    /**
     * Whether a conversion layout has a reading waiting in its buffer, when
     * the strip is the candidate list and a continuation would fight it for
     * the row. Not the layout alone (#990): once the reading is committed the
     * strip is back to plain suggestions, and Chinese and Japanese want a
     * continuation there as much as English does.
     */
    private fun readingInBuffer(state: KeyboardUiState): Boolean =
        state.composer.isConversion && composing.isNotEmpty()

    /**
     * One continuation of [context], or null when none arrived in
     * [AiContinuation.TIMEOUT_MS], the text moved on, or
     * [AiContinuation.accept] turned the answer down. Blocking; call off the
     * main thread.
     */
    private fun requestAiContinuation(context: String, settings: KeyboardSettings, seq: Int): String? {
        // Thinking is asked off below, but not every provider can turn it off
        // (#991: DeepSeek's default model reasons regardless, OpenAI's go no
        // lower than "low"), and the think block comes out of the same budget
        // as the answer.
        val reasons = settings.ai.provider != AiProvider.ON_DEVICE && AiClient.expectsReasoning(settings.ai)
        val deadline = SystemClock.uptimeMillis() +
            if (reasons) AiContinuation.REASONING_TIMEOUT_MS else AiContinuation.TIMEOUT_MS
        val alive = { seq == aiSuggestSeq && SystemClock.uptimeMillis() < deadline }
        val answer = if (settings.ai.provider == AiProvider.ON_DEVICE) {
            // The phone's model cannot be stopped part way, so one request at
            // a time, and never beside a run the AI panel started.
            if (aiJob?.isActive == true) return null
            if (!aiSuggestOnDeviceBusy.compareAndSet(false, true)) return null
            try {
                val modelFile = effectiveLocalModelFile(settings) ?: return null
                LocalLlmEngine.generate(
                    context = applicationContext,
                    modelFile = modelFile,
                    backend = settings.ai.localBackend,
                    contextTokens = settings.ai.localContextTokens,
                    system = AiContinuation.prompt(),
                    user = context,
                )
            } finally {
                aiSuggestOnDeviceBusy.set(false)
            }
        } else {
            AiClient.completeStreaming(
                // A few words do not need a model to think first.
                config = AiClient.config(settings.ai).copy(reasoning = false),
                system = AiContinuation.prompt(),
                user = context,
                maxTokens = if (reasons) AiContinuation.REASONING_MAX_TOKENS else AiContinuation.MAX_TOKENS,
                onPhase = {},
                onPartial = {},
                isActive = alive,
            ).text
        }
        // A request stopped by [alive] hands back what it had so far, which
        // is a continuation cut short, or one for text that is gone.
        if (!alive()) return null
        return AiContinuation.accept(AiThinking.stripped(answer), context)
    }

    /** The AI chip was tapped: its continuation goes in after the caret's text. */
    fun onAiSuggestTapped() {
        val continuation = _uiState.value.aiSuggest ?: return
        clearAiSuggest()
        stopVoiceForManualInput()
        vibrate()
        val ic = currentInputConnection ?: return
        ic.beginBatchEdit()
        commitComposing(ic, autocorrect = false)
        val before = ic.getTextBeforeCursor(1, 0)?.toString().orEmpty()
        ic.commitText(AiContinuation.insertion(before, continuation), 1)
        ic.endBatchEdit()
        revision = null
        composing = StringBuilder()
        lastGestureWord = null
        _uiState.update {
            it.copy(
                composingPreview = "",
                suggestions = emptyList(), emojiSuggestions = emptyList(),
                octopus = emptyMap(),
            )
        }
        refreshSuggestions()
    }

    /** The AI chip was held: gone, and not offered again in this field. */
    fun onAiSuggestSuppressed() {
        vibrate()
        aiSuggestSuppressed = true
        clearAiSuggest()
    }

    private fun smartContext(state: KeyboardUiState): SmartSuggest.Context =
        SmartSuggest.Context(
            calcEnabled = state.settings.smartCalc,
            currencyEnabled = state.settings.smartCurrency,
            unitsEnabled = state.settings.smartUnits,
            keywordsEnabled = state.settings.smartToolKeywords,
            degrees = state.settings.calcDegrees,
            precision = state.settings.calcPrecision,
            rates = (state.currency as? CurrencyUi.Ready)?.rates,
            currencyFrom = state.settings.currencyFrom,
            currencyTo = state.settings.currencyTo,
            currencyDecimals = state.settings.currencyDecimals,
            currencyLabel = state.settings.currencyLabel,
            cryptoEnabled = state.settings.rateSources.cryptoEnabled,
            cryptoTickers = state.settings.rateSources.cryptoTickers,
            cryptoDecimals = state.settings.rateSources.cryptoDecimals,
            sendLinkChips = state.settings.send.detectLinks && ToolbarTool.SEND_FILES in state.settings.enabledTools,
            cryptoUnavailable = (state.currency as? CurrencyUi.Ready)?.cryptoFailed == true,
            // Fetching left to the tap: a chip missing its rates asks for one,
            // unless the fetch a tap started is still running.
            ratesOnTap = !state.settings.rateSources.autoFetch && currencyJob?.isActive != true,
            weatherOnTap = !state.settings.weather.autoFetch && weatherJob?.isActive != true,
            unitLast = state.settings.unitConvertLast,
            compoundUnits = state.settings.compoundUnits,
            enabledTools = usableTools(state.settings),
            keywordOverrides = state.settings.toolKeywords,
            caseSensitiveKeywords = state.settings.toolKeywordCase,
            dateChips = state.settings.smartChips.dates,
            todayJdn = todayJdn(),
            weatherChips = state.settings.smartChips.weather,
            weather = freshWeather(state),
            // A failed fetch must not leave the chip spinning forever, so a
            // weather error counts as "not available" until something else
            // refreshes it.
            weatherAvailable = state.settings.weather.latitude != null &&
                state.settings.weather.longitude != null &&
                state.weather !is WeatherUi.Error,
            weatherFahrenheit = state.settings.weather.fahrenheit,
            lookupChips = state.settings.smartChips.lookups,
            intentChips = state.settings.smartChips.intents,
            haReady = state.settings.let { it.homeAssistant.enabled && it.homeAssistant.smartChip && it.homeAssistant.assistEnabled && it.assistHome() != null },
            gifChips = state.settings.smartChips.gifs,
            // The nudges are the Vocabulary bundle's background work: off with it.
            vocabChips = state.settings.vocabulary.nudges && state.settings.extensionOn(Extension.VOCABULARY),
            vocabSelfChips = state.settings.vocabulary.nudgeOnVocabWord,
            vocab = vocabIndex,
            vocabScope = state.settings.vocabulary.nudgeScope,
            vocabMinGap = state.settings.vocabulary.nudgeLevel.minGap,
            vocabLearnt = vocabProgress::isLearnt,
            // A copy: detection runs off the main thread, and the retired
            // set is added to on it.
            vocabRetired = vocabRetired.toSet(),
            // Never in a field that asks for a number: an amount box, a card
            // form or a PIN wants the digits it asked for, and separators
            // would break the value the app parses back out.
            numberChips = state.settings.smartChips.numbers && !state.fieldKind.isNumericPad,
            numberGrouping = state.settings.smartChips.numberGrouping,
            numberLocale = state.language.localeTag,
            // The chip answers in whatever digits the keyboard is typing, so
            // a Bangla number does not come back in ASCII.
            numberDigits = resolveNumeralDigits(
                state.settings.layoutBehavior.numeralSystemFor(state.language.id),
                state.language,
            ),
            contacts = contactPhones.takeIf { state.settings.smartChips.contacts && !it.isEmpty },
            repeatChips = state.settings.smartChips.repeats,
            repeatAfter = state.settings.smartChips.repeatAfter,
            // A copy, for the same reason as vocabRetired.
            repeatRetired = repeatChipsRetired.toSet(),
        )

    private fun todayJdn(): Long = Calendar.getInstance().let {
        CalendarSystems.gregorianToJdn(
            it.get(Calendar.YEAR), it.get(Calendar.MONTH) + 1, it.get(Calendar.DAY_OF_MONTH),
        )
    }

    /** The fetched conditions, only while still within the cache window. */
    private fun freshWeather(state: KeyboardUiState): WeatherInfo? =
        (state.weather as? WeatherUi.Ready)?.info?.takeIf {
            System.currentTimeMillis() - it.fetchedAtMillis < weatherCacheMs()
        }

    /**
     * A chip that was waiting for the go-ahead to fetch what it is missing: the
     * forecast for a weather chip, the rates for a currency chip. The spinner
     * goes up only once a fetch is really running: data saving can refuse a
     * rates fetch, and a chip spinning with nothing in flight never stops.
     */
    private fun fetchForChip(hit: SmartSuggest.SmartHit) {
        vibrate()
        val job = if (hit.pendingWeather) {
            refreshWeather()
            weatherJob
        } else {
            refreshCurrencyRates(wantCrypto = hit.pendingCrypto)
            currencyJob
        }
        if (job?.isActive != true) return
        _uiState.update { if (it.smart == hit) it.copy(smart = hit.copy(awaitingTap = false)) else it }
    }

    /**
     * Chip tapped: swap the recognised text for the answer. The span is
     * whatever the trigger occupied, so "150usd" is replaced outright while
     * a trailing "=" keeps what was typed and appends the result.
     *
     * A weather or currency chip that is waiting for a tap before it fetches
     * (see [SmartSuggest.SmartHit.awaitingTap]) fetches instead.
     */
    fun onSmartSuggestionTapped() {
        val hit = _uiState.value.smart ?: return
        // A link chip has nothing to type; its face opens the panel on receiving (#729).
        if (hit.kind == SmartSuggest.Kind.SEND_LINK) {
            onSmartSuggestionOpen()
            onToolTap(ToolbarTool.SEND_FILES)
            return
        }
        if (hit.awaitingTap) {
            fetchForChip(hit)
            return
        }
        if (hit.kind == SmartSuggest.Kind.CONTACT) {
            startContactAction(hit, message = false)
            return
        }
        val insert = hit.insert ?: return
        if (hit.kind == SmartSuggest.Kind.VOCAB) retireVocabNudge(hit.query)
        stopVoiceForManualInput()
        vibrate()
        val ic = currentInputConnection ?: return
        ic.beginBatchEdit()
        commitComposing(ic, autocorrect = false)
        if (hit.replaceSpan > 0) ic.deleteSurroundingText(hit.replaceSpan, 0)
        ic.commitText(insert, 1)
        ic.endBatchEdit()
        smartMutedAfter = ic.getTextBeforeCursor(smartLookbehind(), 0)?.toString()
        revision = null
        composing = StringBuilder()
        lastGestureWord = null
        _uiState.update {
            it.copy(
                composingPreview = "", smart = null,
                suggestions = emptyList(), emojiSuggestions = emptyList(),
                octopus = emptyMap(),
            )
        }
        refreshSuggestions()
    }

    /**
     * Chip's open button: drop the recognised text (the tool is about to
     * type its own result there) and load it into the tool as a prefill.
     * The caller then taps the tool the normal way, so panel routing stays
     * in one place.
     */
    fun onSmartSuggestionOpen() {
        val hit = _uiState.value.smart ?: return
        if (hit.kind == SmartSuggest.Kind.CONTACT) {
            startContactAction(hit, message = true)
            return
        }
        // A hint that was taken has done its job for this field.
        if (hit.kind == SmartSuggest.Kind.INTENT || hit.kind == SmartSuggest.Kind.LOOKUP) {
            intentChipsRetired += hit.tool
        }
        if (hit.kind == SmartSuggest.Kind.VOCAB) retireVocabNudge(hit.query)
        if (hit.kind == SmartSuggest.Kind.REPEAT) repeatChipsRetired += hit.query.lowercase(Locale.ROOT)
        chipOpenRestore = null
        val ic = currentInputConnection
        if (ic != null) {
            // Kept on request (#665): "150 usd" or "calculator" stays where it
            // was typed, and the tool's answer lands after it.
            val keep = _uiState.value.settings.smartChips.keepTextOnOpen
            ic.beginBatchEdit()
            commitComposing(ic, autocorrect = false)
            // A vocabulary chip opens the card *about* the typed word; the word stays.
            if (hit.kind != SmartSuggest.Kind.VOCAB && hit.replaceSpan > 0 && !keep) {
                val removed = ic.getTextBeforeCursor(hit.replaceSpan, 0)?.toString()
                ic.deleteSurroundingText(hit.replaceSpan, 0)
                if (!removed.isNullOrEmpty()) {
                    val caret = expectedSelStart
                        .takeIf { it >= removed.length && expectedSelEnd == it }
                        ?.minus(removed.length) ?: -1
                    chipOpenRestore = ChipOpenRestore(removed, caret)
                }
            }
            ic.endBatchEdit()
            // The text that raised the chip is still there; the chip it raised
            // has been answered, and must not come straight back over the
            // panel's close.
            if (keep) smartMutedAfter = ic.getTextBeforeCursor(smartLookbehind(), 0)?.toString()
        }
        revision = null
        composing = StringBuilder()
        _uiState.update {
            it.copy(
                composingPreview = "", smart = null, toolPrefill = hit.prefill,
                suggestions = emptyList(), emojiSuggestions = emptyList(),
                octopus = emptyMap(),
            )
        }
    }

    /**
     * A contact chip was tapped (#656): the dialer with the number filled in,
     * or the messaging app addressed to it. The dialer, never a call placed
     * from here: the keyboard holds no call permission, and a call is the one
     * thing a stray tap must not start. The typed name stays where it is.
     */
    private fun startContactAction(hit: SmartSuggest.SmartHit, message: Boolean) {
        val contact = hit.prefill as? com.wasimaster.wmkeyboard.core.tools.ToolPrefill.Contact ?: return
        vibrate()
        contactChipsRetired += hit.query
        _uiState.update { it.copy(smart = null) }
        val intent = if (message) {
            Intent(Intent.ACTION_SENDTO, Uri.fromParts("smsto", contact.number, null))
        } else {
            Intent(Intent.ACTION_DIAL, Uri.fromParts("tel", contact.number, null))
        }
        startMacroActivity(intent)
    }

    /** A panel has loaded its prefill; drop it so reopening starts clean. */
    fun onToolPrefillConsumed() {
        if (_uiState.value.toolPrefill != null) _uiState.update { it.copy(toolPrefill = null) }
    }

    // ---- Search by meaning ----

    /**
     * The search boxes' second opinion: clips, notes, snippets, emoji and
     * stickers found by what a query means (see [MeaningSearch]). Every
     * answer is listed after the keyword matches, and with the feature off or
     * its model absent nothing here does anything.
     */
    private val meaningSearch by lazy { MeaningSearch(applicationContext, serviceScope) }

    /**
     * IndicXlit, for the phonetic languages whose strip offers its readings
     * (Neural suggestions on the language's page). Made the first time one
     * asks; with the model or ONNX Runtime absent it answers nothing.
     */
    private var indicXlit: IndicXlit? = null

    /**
     * Starts IndicXlit on [typed] when the layout's language has neural
     * suggestions on, or null. Started before the pass's own walk so the two
     * run side by side; [NEURAL_BUDGET_MS] is how long the pass then waits.
     */
    private fun requestNeuralReadings(state: KeyboardUiState, typed: String): Pair<String, java.util.concurrent.Future<List<String>>>? {
        val lang = state.composer.phoneticLanguage ?: return null
        if (typed.isEmpty() || !state.allowsTypingIntelligence) return null
        if (!state.settings.suggestionStrip.neuralPhoneticFor(lang) || !IndicXlitModels.supports(lang)) return null
        val xlit = indicXlit ?: IndicXlit(applicationContext).also { indicXlit = it }
        return lang to xlit.request(lang, typed)
    }

    /**
     * Whether IndicXlit may choose [lang]'s space-bar word (Neural suggestions
     * lead, on the language's page). Not on a fixed strip, whose head is the
     * buffer in Latin letters, nor with desktop Avro's candidate row drawn,
     * whose first word the space bar would then disagree with.
     */
    private fun neuralLeads(state: KeyboardUiState, lang: String): Boolean {
        val strip = state.settings.suggestionStrip
        return strip.neuralLeadsFor(lang) && IndicXlitModels.canLead(lang) &&
            suggestionEngine?.phoneticFixedStrip == null &&
            strip.phoneticCandidateListFor(lang) != PhoneticCandidateList.BAR
    }

    /**
     * The model's word for a space that would write [top], or null to keep it.
     * The strip normally has the answer already and led with it, and then this
     * agrees with it. A space that comes first, before the strip was drawn
     * with the answer, waits [NEURAL_COMMIT_WAIT_MS] at most for the request
     * that is running, so how fast the word was typed does not change what it
     * becomes. Only asked when it could matter: a native head that is not a
     * known word, with no spelling map entry.
     */
    private fun neuralCommit(state: KeyboardUiState, lang: String, typed: String, top: String): String? {
        if (typed.isEmpty() || !state.allowsTypingIntelligence || !neuralLeads(state, lang)) return null
        val engine = suggestionEngine ?: return null
        return engine.neuralCommit(lang, typed, top) {
            val xlit = indicXlit ?: IndicXlit(applicationContext).also { indicXlit = it }
            xlit.await(xlit.request(lang, typed), NEURAL_COMMIT_WAIT_MS)
        }
    }

    /** Indexes what [panel] searches, in the background. A no-op unless search by meaning is ready. */
    private fun indexMeaningFor(panel: PanelMode) {
        if (!userUnlocked || !meaningSearch.enabled) return
        when (panel) {
            PanelMode.CLIPBOARD -> {
                val clips = clipboardStore.items().filter { !it.sensitive }
                meaningSearch.index(
                    MeaningSpace.CLIPS,
                    clips.mapNotNull { clip ->
                        meaningTextOf(clip)?.let { MeaningSync.Item(clip.id.toString(), MeaningSearch.stampOf(it), it) }
                    },
                )
                meaningSearch.index(
                    MeaningSpace.CLIP_PICTURES,
                    clips.mapNotNull { clip ->
                        clip.imagePath?.takeIf { clip.kind == ClipKind.IMAGE }
                            ?.let { MeaningSync.Item(clip.id.toString(), MeaningSearch.stampOf(it), it) }
                    },
                )
            }
            PanelMode.SNIPPETS -> meaningSearch.index(
                MeaningSpace.SNIPPETS,
                snippetStore.items().map { snippet ->
                    val text = listOfNotNull(
                        snippet.label.takeIf { it.isNotBlank() },
                        snippet.text,
                        snippet.trigger,
                    ).joinToString("\n")
                    MeaningSync.Item(snippet.id.toString(), MeaningSearch.stampOf(text), text)
                },
            )
            // A locked note is never indexed: its vector would let a search
            // find what the keyboard otherwise masks.
            PanelMode.NOTES -> meaningSearch.index(
                MeaningSpace.NOTES,
                noteStore.items(com.wasimaster.wmkeyboard.core.notes.NoteFilter(includeLocked = false)).map { note ->
                    val text = listOf(note.title, note.tags.joinToString(" "), note.body)
                        .filter { it.isNotBlank() }
                        .joinToString("\n")
                    MeaningSync.Item(note.id.toString(), MeaningSearch.stampOf(text), text)
                },
            )
            PanelMode.STICKER -> indexMeaningStickers()
            else -> Unit
        }
    }

    /** What a clip is found by: its text (and a link's page title), a file's name. Pictures go to [MeaningSpace.CLIP_PICTURES]. */
    private fun meaningTextOf(clip: com.wasimaster.wmkeyboard.core.clipboard.ClipItem): String? =
        com.wasimaster.wmkeyboard.ime.semantic.MeaningLookup.clipText(clip)

    /**
     * The user's own stickers, by what they show; then, for the ones with no
     * title or keyword, tags read off the picture for the stickers offered
     * while typing.
     */
    private fun indexMeaningStickers() {
        val packs = stickerPackStore.packs()
        val items = packs.flatMap { pack ->
            pack.stickers.mapNotNull { sticker ->
                val file = stickerPackStore.fileFor(pack.id, sticker) ?: return@mapNotNull null
                MeaningSync.Item(
                    pack.id + "/" + sticker.id,
                    MeaningSearch.stampOf(file.path + ":" + file.length()),
                    file.path,
                )
            }
        }
        val untagged = packs.flatMap { pack ->
            pack.stickers.filter { it.name.isBlank() && it.keywords.isEmpty() }.map { pack.id + "/" + it.id }
        }.toSet()
        meaningSearch.index(MeaningSpace.STICKERS, items) { refreshMeaningStickerTags(untagged) }
        refreshMeaningStickerTags(untagged)
    }

    private fun refreshMeaningStickerTags(untagged: Set<String>) {
        if (untagged.isEmpty()) return
        val names = emojiEntries.associate { it.emoji to it.name }
        meaningSearch.refreshStickerTags(untagged, { names[it] }) { refreshStickerOffer() }
    }

    private fun queryMeaningClips(text: String) {
        val query = text.trim()
        meaningSearch.query(MeaningSpace.CLIPS, query, MeaningRank.TEXT) { byText ->
            meaningSearch.query(MeaningSpace.CLIP_PICTURES, query, MeaningRank.PICTURE) { byPicture ->
                _uiState.update { it.copy(meaning = it.meaning.copy(clips = MeaningHits.Found(query, byText + byPicture))) }
            }
        }
    }

    private fun queryMeaningSnippets(text: String) {
        val query = text.trim()
        meaningSearch.query(MeaningSpace.SNIPPETS, query, MeaningRank.TEXT) { keys ->
            _uiState.update { it.copy(meaning = it.meaning.copy(snippets = MeaningHits.Found(query, keys))) }
        }
    }

    private fun queryMeaningNotes(text: String) {
        val query = text.trim()
        meaningSearch.query(MeaningSpace.NOTES, query, MeaningRank.TEXT) { keys ->
            _uiState.update { it.copy(meaning = it.meaning.copy(notes = MeaningHits.Found(query, keys))) }
            publishNotes()
        }
    }

    /**
     * Adds to the emoji panel's results the emoji whose names mean what
     * [query] does, in any language, after the keyword ones: "বিড়াল" or
     * "gato" finds 🐈 with no keyword pack for either.
     */
    private fun appendMeaningEmoji(query: String, hidden: Set<String>) {
        meaningSearch.query(MeaningSpace.EMOJI, query, MeaningRank.EMOJI) { keys ->
            if (keys.isEmpty() || _uiState.value.emojiQuery != query) return@query
            val have = _uiState.value.emojiResults.mapTo(HashSet()) { it.emoji }
            val byEmoji = emojiEntries.associateBy { it.emoji }
            val extra = keys.filter { it !in have && it !in hidden }.mapNotNull { byEmoji[it] }
            if (extra.isNotEmpty()) _uiState.update { it.copy(emojiResults = it.emojiResults + extra) }
        }
    }

    /**
     * The sticker grid's own-packs results with what search by meaning finds
     * after them: stickers by what they show. On the provider dispatch's IO
     * thread, so it waits a moment for the answer and gives up rather than
     * hold the grid while the model loads.
     */
    private fun meaningStickers(query: String, packId: String?, byWords: List<GifItem>): List<GifItem> {
        if (query.isBlank()) return byWords
        val keys = meaningSearch.blockingQuery(
            MeaningSpace.STICKERS,
            query,
            MeaningRank.PICTURE,
            timeoutMs = MEANING_STICKER_WAIT_MS,
        ) { key -> packId == null || key.startsWith("$packId/") }
        if (keys.isEmpty()) return byWords
        val seen = byWords.mapTo(HashSet()) { it.id }
        val extra = keys.mapNotNull { key ->
            val pack = stickerPackStore.pack(key.substringBefore('/')) ?: return@mapNotNull null
            val sticker = pack.stickers.firstOrNull { it.id == key.substringAfter('/') } ?: return@mapNotNull null
            stickerPackStore.asGifItem(pack.id, sticker)
        }.filter { seen.add(it.id) }
        return byWords + extra
    }

    // ---- stickers offered while typing (#329) ----

    /** Triggers of every sticker the user owns, rebuilt when the packs change. */
    private var stickerTriggers = StickerTriggerIndex.EMPTY

    /** The pack store's [StickerPackStore.stateToken] [stickerTriggers] was built at. */
    private var stickerTriggersToken = Long.MIN_VALUE

    /** [MeaningSearch.stickerTagsVersion] [stickerTriggers] was built at. */
    private var stickerTriggersTagsVersion = -1
    private var stickerOfferJob: Job? = null

    /**
     * The text before the cursor when an offer was sent from or dismissed.
     * Until the text changes, the same trigger does not raise the same offer
     * again: with "keep the text" on, the word that asked is still there, and
     * a tray that comes straight back after every send would never let go.
     * Same one-shot shape as [smartMutedAfter].
     */
    private var stickerMutedAfter: String? = null

    /**
     * Whether stickers may be offered here at all: the setting on, and a
     * field that takes images, since an offer the field cannot receive would
     * dead-end in the clipboard fallback. The emoji panel is the one panel
     * that offers them, for an emoji picked in it.
     */
    private fun stickerOffersAllowed(state: KeyboardUiState): Boolean =
        state.settings.gif.stickerSuggest && state.acceptsRichMedia && !state.secureField &&
            (state.panel == PanelMode.NONE || state.panel == PanelMode.EMOJI)

    /**
     * Its own lock, not the service's: the glide key maps synchronize on the
     * service, and a rebuild here must never hold up a swipe.
     */
    private val stickerTriggerLock = Any()

    private fun stickerTriggerIndex(): StickerTriggerIndex = synchronized(stickerTriggerLock) {
        stickerPackStore.reloadIfChanged()
        val token = stickerPackStore.stateToken()
        val tagsVersion = meaningSearch.stickerTagsVersion
        if (token != stickerTriggersToken || tagsVersion != stickerTriggersTagsVersion) {
            stickerTriggers = StickerTriggerIndex.build(stickerPackStore.packs(), meaningSearch.stickerTags)
            stickerTriggersToken = token
            stickerTriggersTagsVersion = tagsVersion
        }
        stickerTriggers
    }

    private fun clearStickerOffer() {
        stickerOfferJob?.cancel()
        if (_uiState.value.stickerOffer != null) _uiState.update { it.copy(stickerOffer = null) }
    }

    /**
     * Re-reads the text before the cursor for a sticker's title, keyword or
     * emoji. Debounced and off the main thread like the smart chip's read, and
     * skipped outright for anybody with no packs, so a keyboard that has no
     * stickers to offer pays nothing per keystroke.
     */
    private fun refreshStickerOffer() {
        val state = _uiState.value
        val ic = currentInputConnection
        val stickersOn = stickerOffersAllowed(state) && !stickerPackStore.isEmpty()
        if (ic == null || (!stickersOn && !mixOffersAllowed(state))) {
            clearStickerOffer()
            return
        }
        stickerOfferJob?.cancel()
        stickerOfferJob = serviceScope.launch {
            delay(SMART_SUGGEST_DEBOUNCE_MS)
            val still = _uiState.value
            val stickersNow = stickerOffersAllowed(still) && !stickerPackStore.isEmpty()
            val mixesNow = mixOffersAllowed(still)
            if (!stickersNow && !mixesNow) {
                if (still.stickerOffer != null) _uiState.update { it.copy(stickerOffer = null) }
                return@launch
            }
            val inEmojiPanel = still.panel == PanelMode.EMOJI
            val (before, match) = withContext(Dispatchers.Default) {
                val text = ic.getTextBeforeCursor(StickerTriggerIndex.LOOKBEHIND, 0)?.toString().orEmpty()
                // In the emoji panel the text before the cursor was typed
                // before the panel opened; only the emoji picked in it counts.
                text to if (stickersNow) stickerTriggerIndex().match(text, emojiOnly = inEmojiPanel) else null
            }
            val offer = when {
                before == stickerMutedAfter -> null
                match == null -> null
                else -> {
                    stickerMutedAfter = null
                    val previous = _uiState.value.stickerOffer
                    val items = match.hits.mapNotNull { hit ->
                        stickerPackStore.asGifItem(hit.packId, hit.sticker)
                            ?.let { com.wasimaster.wmkeyboard.ime.StickerOfferItem(it, hit.span) }
                    }
                    items.takeIf { it.isNotEmpty() }?.let {
                        com.wasimaster.wmkeyboard.ime.StickerOffer(
                            trigger = match.trigger,
                            stickers = it,
                            // A tray opened by hand stays open while the same
                            // trigger is still being offered.
                            expanded = previous?.expanded == true && previous.trigger == match.trigger,
                            inEmojiPanel = inEmojiPanel,
                        )
                    }
                }
            }
            // The user's own stickers first; with none for this text, the
            // mixes of the emoji it ends in.
            val mixOffer = if (offer == null && mixesNow && before != stickerMutedAfter) {
                withContext(Dispatchers.Default) { emojiMixTool.offerFor(before, inEmojiPanel) }?.let { mix ->
                    val previous = _uiState.value.stickerOffer
                    mix.copy(expanded = previous?.expanded == true && previous.mix && previous.trigger == mix.trigger)
                }
            } else {
                null
            }
            if (match == null && mixOffer == null) stickerMutedAfter = null
            val shown = offer ?: mixOffer
            if (shown != _uiState.value.stickerOffer) _uiState.update { it.copy(stickerOffer = shown) }
        }
    }

    /**
     * Whether emoji mixes may be offered here: a source on, a field that takes
     * pictures, and the place the offer would show switched on (the strip for
     * typed emoji, the row over the emoji panel for picked ones).
     */
    private fun mixOffersAllowed(state: KeyboardUiState): Boolean {
        val mix = state.settings.emoji.mix
        if (!mix.active || !state.acceptsRichMedia || state.secureField) return false
        if (!emojiMixToolDelegate.isInitialized() || !emojiMixTool.usable) return false
        return when (state.panel) {
            PanelMode.NONE -> mix.typingSuggest
            PanelMode.EMOJI -> mix.panelStrip
            else -> false
        }
    }

    /**
     * A mix offered for emoji in the text, or for one picked in the emoji
     * panel, was tapped. It is fetched first; only once it is in hand are the
     * emoji taken back out, when the setting says so, so a failed fetch costs
     * the text nothing. The emoji are matched again against the text as it is
     * then, as a sticker's trigger is.
     */
    private fun onEmojiMixOfferPick(offer: com.wasimaster.wmkeyboard.ime.StickerOffer, item: GifItem) {
        val state = _uiState.value
        if (!state.acceptsRichMedia) {
            vibrate()
            return
        }
        stopVoiceForManualInput()
        val trigger = offer.trigger
        emojiMixBeforeSend = if (state.settings.emoji.mix.replaceTypedEmoji) {
            {
                val ic = currentInputConnection
                val before = ic?.getTextBeforeCursor(StickerTriggerIndex.LOOKBEHIND, 0)?.toString().orEmpty()
                if (ic != null && trigger.isNotEmpty() && before.endsWith(trigger)) {
                    ic.beginBatchEdit()
                    commitComposing(ic, autocorrect = false)
                    ic.deleteSurroundingText(trigger.length, 0)
                    ic.endBatchEdit()
                    revision = null
                    composing = StringBuilder()
                    lastGestureWord = null
                    _uiState.update {
                        it.copy(composingPreview = "", suggestions = emptyList(), emojiSuggestions = emptyList(), octopus = emptyMap())
                    }
                }
            }
        } else {
            null
        }
        stickerMutedAfter = currentInputConnection?.getTextBeforeCursor(StickerTriggerIndex.LOOKBEHIND, 0)?.toString()
        clearStickerOffer()
        emojiMixTool.sendOffered(item)
    }

    /** The emoji-mix row's button: the Mixes panel, on the emoji the row was for. */
    private fun onEmojiMixOpenFrom(offer: com.wasimaster.wmkeyboard.ime.StickerOffer) {
        emojiMixOpenWith = com.wasimaster.wmkeyboard.core.emoji.mix.MixSeq.trailingEmoji(offer.trigger, 1).firstOrNull()
        clearStickerOffer()
        onPanelChange(PanelMode.EMOJI_MIX)
    }

    /**
     * The monthly rebuild of each downloaded index, when the setting asks for
     * it: once per keyboard process, only on a connection that is not metered,
     * and only for an index more than a month old.
     */
    private fun maybeRefreshEmojiMixIndexes(mix: com.wasimaster.wmkeyboard.core.settings.EmojiMixSettings) {
        if (!mix.autoRefresh || emojiMixAutoRefreshed) return
        val network = networkWatcher.state.value
        if (!network.online || network.metered) return
        val now = System.currentTimeMillis()
        val stale = mix.sources.filter { source ->
            source.enabled && source.kind == com.wasimaster.wmkeyboard.core.settings.EmojiMixSourceKind.INDEX &&
                source.address.startsWith("http", ignoreCase = true) && now - source.refreshedAt > EMOJI_MIX_REFRESH_MS
        }
        emojiMixAutoRefreshed = true
        if (stale.isEmpty()) return
        serviceScope.launch(Dispatchers.IO) {
            for (source in stale) {
                val outcome = emojiMixTool.store.refresh(source)
                if (outcome is com.wasimaster.wmkeyboard.ime.emojimix.EmojiMixStore.Outcome.Done) {
                    settingsRepository.updateEmojiMixSource(source.id) {
                        it.copy(pairCount = outcome.pairs, refreshedAt = System.currentTimeMillis(), error = "")
                    }
                }
            }
            settingsRepository.bumpEmojiMixIndexVersion()
        }
    }

    /** Puts a fetched mix into the user's own stickers, in a pack of mixes, tagged with its two emoji. */
    private fun addEmojiMixToStickers(file: File, keywords: List<String>) {
        serviceScope.launch {
            val result = withContext(Dispatchers.IO) {
                val name = getString(R.string.ime_emoji_mix_pack_name)
                val target = stickerPackStore.packs().firstOrNull { it.name == name }?.id
                    ?: stickerPackStore.createPack(name)?.id
                    ?: return@withContext null
                when (val processed = StickerImage.process(file.readBytes())) {
                    is StickerImage.Result.Ok -> stickerPackStore.addSticker(target, processed.sticker, keywords = keywords)
                    StickerImage.Result.TooLarge, StickerImage.Result.NotAnImage -> StickerAddResult.WriteFailed
                }
            }
            _uiState.update { it.copy(stickerPacks = stickerPackStore.packs()) }
            val message = when (result) {
                is StickerAddResult.Added -> getString(R.string.ime_service_sticker_saved_toast)
                StickerAddResult.PackFull -> getString(R.string.ime_service_sticker_pack_full_toast)
                StickerAddResult.PackMissing -> getString(R.string.ime_service_sticker_pack_missing_toast)
                else -> getString(R.string.ime_service_sticker_save_error_toast)
            }
            Toast.makeText(this@WMKeyboardService, message, Toast.LENGTH_SHORT).show()
        }
    }

    /**
     * A sticker the text asked for was tapped: take the trigger back out when
     * the setting says so, then send the sticker the way the sticker panel
     * would, with the sticker tool's own send mode.
     *
     * The span is matched again against the text as it is now, not taken
     * from the offer: the offer is a debounce behind the keys, and deleting a
     * span that no longer ends in the trigger would eat whatever was typed
     * since.
     */
    fun onStickerOfferPick(pick: com.wasimaster.wmkeyboard.ime.StickerOfferItem) {
        val state = _uiState.value
        val offer = state.stickerOffer ?: return
        if (offer.mix) {
            onEmojiMixOfferPick(offer, pick.item)
            return
        }
        if (!state.acceptsRichMedia) {
            vibrate()
            return
        }
        stopVoiceForManualInput()
        val ic = currentInputConnection
        if (ic != null &&
            state.settings.gif.stickerSuggestTrigger == com.wasimaster.wmkeyboard.core.settings.StickerTriggerAction.DELETE
        ) {
            val before = ic.getTextBeforeCursor(StickerTriggerIndex.LOOKBEHIND, 0)?.toString().orEmpty()
            val span = stickerTriggerIndex().match(before, emojiOnly = offer.inEmojiPanel)
                ?.hits
                ?.firstOrNull { stickerPackStore.asGifItem(it.packId, it.sticker)?.id == pick.item.id }
                ?.span
            if (span != null && span > 0) {
                ic.beginBatchEdit()
                commitComposing(ic, autocorrect = false)
                ic.deleteSurroundingText(span, 0)
                ic.endBatchEdit()
                revision = null
                composing = StringBuilder()
                lastGestureWord = null
                _uiState.update {
                    it.copy(
                        composingPreview = "", suggestions = emptyList(),
                        emojiSuggestions = emptyList(), octopus = emptyMap(),
                    )
                }
            }
        }
        stickerMutedAfter = ic?.getTextBeforeCursor(StickerTriggerIndex.LOOKBEHIND, 0)?.toString()
        clearStickerOffer()
        vibrate()
        insertLocalSticker(pick.item, state.settings.stickerSendMode)
        refreshSuggestions()
    }

    /** The narrower styles' chip or "more" button: open the tray with every match. */
    fun onStickerOfferExpand() {
        vibrate()
        _uiState.update { state -> state.copy(stickerOffer = state.stickerOffer?.copy(expanded = true)) }
    }

    /** The tray's close button: this trigger is answered until the text changes. */
    fun onStickerOfferDismiss() {
        vibrate()
        stickerMutedAfter = currentInputConnection
            ?.getTextBeforeCursor(StickerTriggerIndex.LOOKBEHIND, 0)
            ?.toString()
        clearStickerOffer()
    }

    /**
     * True when the email-field contact-email path should drive the strip:
     * an email field, the feature and its email-field override both on, the
     * master strip on, not a password box, and some addresses to offer. This
     * deliberately ignores [KeyboardUiState.fieldNoSuggestions] — the whole
     * point is to complete addresses even where the field asked for a silent
     * strip (which email fields do).
     */
    private fun emailFieldForceActive(state: KeyboardUiState = _uiState.value): Boolean =
        state.fieldKind == FieldKind.EMAIL &&
            !state.secureField &&
            state.settings.suggestions &&
            (contactEmailsInEmailField(state) || typedEmailsInEmailField(state))

    private fun contactEmailsInEmailField(state: KeyboardUiState): Boolean =
        state.settings.suggestionSources.contactEmails &&
            state.settings.suggestionSources.contactEmailsInEmailFields &&
            !contactEmails.isEmpty

    /** Is [typedEmails] what the strip offers here? Its own switch is the email-field one too. */
    private fun typedEmailsInEmailField(state: KeyboardUiState): Boolean =
        state.settings.suggestionSources.typedEmails && !typedEmails.isEmpty

    /**
     * Keeps the address the email field is leaving with (#475). Read whole,
     * both sides of the caret, so an address corrected in the middle is kept
     * as it was finally written; [TypedEmails.record] drops anything that is
     * not a complete address.
     */
    private fun rememberTypedEmail() {
        val state = _uiState.value
        if (state.fieldKind != FieldKind.EMAIL || state.secureField || !userUnlocked) return
        if (!state.settings.suggestionSources.typedEmails) return
        val ic = currentInputConnection ?: return
        val before = ic.getTextBeforeCursor(EMAIL_FIELD_LOOKBEHIND, 0)?.toString() ?: return
        val after = ic.getTextAfterCursor(EMAIL_FIELD_LOOKBEHIND, 0)?.toString().orEmpty()
        typedEmails.record(before + after)
    }

    /** The email-address token immediately before the cursor (may be empty). */
    private fun emailTokenBeforeCursor(ic: InputConnection): String {
        val before = ic.getTextBeforeCursor(EMAIL_FIELD_LOOKBEHIND, 0)?.toString() ?: return ""
        return before.takeLastWhile { it.isLetterOrDigit() || it in EMAIL_TOKEN_EXTRA }
    }

    /**
     * Email-field completion: contact emails whose address starts with the
     * token before the cursor, pushed into the strip even though the field
     * suppresses the normal one. Email fields keep no composing buffer, so the
     * token is read straight from the connection.
     */
    private fun refreshEmailFieldSuggestions() {
        suggestionJob?.cancel()
        val ic = currentInputConnection
        val token = ic?.let { emailTokenBeforeCursor(it) }.orEmpty().lowercase()
        val state = _uiState.value
        // The user's own addresses need no prefix: an empty email field is
        // exactly where the one they always use belongs (#475). Contacts keep
        // theirs, since the whole address book is no answer to nothing.
        val typed = typedEmailsInEmailField(state)
        val contacts = contactEmailsInEmailField(state) && token.length >= EMAIL_FIELD_MIN_PREFIX
        if (!contacts && !typed) {
            _uiState.update {
                if (it.suggestions.isEmpty()) it
                else it.copy(suggestions = emptyList(), emojiSuggestions = emptyList(), octopus = emptyMap())
            }
            return
        }
        suggestionJob = serviceScope.launch {
            val results = withContext(Dispatchers.Default) {
                val own = if (typed) typedEmails.complete(token, EMAIL_FIELD_SUGGESTION_LIMIT) else emptyList()
                val book = if (contacts) contactEmails.complete(token, EMAIL_FIELD_SUGGESTION_LIMIT) else emptyList()
                (own + book).distinct().take(EMAIL_FIELD_SUGGESTION_LIMIT)
            }
            _uiState.update {
                it.copy(suggestions = results, emojiSuggestions = emptyList(), inlineEmoji = false)
            }
        }
    }

    /**
     * What one suggestion pass produces, all of it worked out off the main
     * thread. A Triple until the octopus needed a fourth thing, and four
     * unnamed positions is one too many to read.
     */
    private data class SuggestionFrame(
        val words: List<String>,
        val emojis: List<String>,
        val bias: Map<Char, Float>,
        val octopus: OctopusBoard,
    )

    /**
     * The words to float over the keys for this buffer, keyed by the key each
     * one belongs over (discussion #102).
     *
     * Handed the strip's own finished list, so the keys and the strip always
     * agree: whatever the strip is about to offer is what the keys offer, one
     * flick away instead of one look away. Only the keys the strip has no
     * opinion about are filled from the engine's own walk, and that walk is the
     * one [SuggestionEngine.suggest] just memoised, so it costs nothing extra.
     *
     * Off for a conversion or transliterating composer. Both compose through
     * their own machinery, and on a phonetic board the engine's candidates are
     * readings of what is already typed rather than words longer than it — so
     * there is no next key to hang anything off. Bengali wants a roman-side
     * completion source before it can join in.
     */
    /**
     * The words to float over the keys while a stroke is still being drawn, or
     * nothing, as [OctopusSettings.duringGlide] says (#166).
     *
     * The stroke's board and the buffer's board answer different questions and
     * now have different levers. This one picks between three answers; the
     * board published at the *lift* is not its business and never changes.
     */
    // Internal rather than private for `OctopusGlideKindsTest`: the gates below
    // are settings the stroke has to read, and the decode that would reach them
    // through `onGesturePreview` needs a loaded engine this module cannot build.
    internal suspend fun octopusForGlide(
        state: KeyboardUiState,
        words: List<String>,
    ): OctopusBoard {
        val octopus = state.settings.octopus
        if (!octopus.enabled || words.isEmpty()) return emptyMap()
        if (!state.allowsTypingIntelligence) return emptyMap()
        return when (octopus.duringGlide) {
            OctopusDuringGlide.NOTHING -> emptyMap()
            OctopusDuringGlide.ALTERNATES -> glideAlternateOctopus(state, words)
            OctopusDuringGlide.NEXT_WORD -> glideNextWordOctopus(state, words.first())
        }
    }

    /**
     * The alternates the decoder is still holding — Mokhyy's idea on discussion
     * #102, that the keys should update live the way the strip already does.
     *
     * The rule stays the one sentence it is when idle: the word over a key is
     * the one you reach by going there next. Mid-stroke the buffer is the
     * decoder's leader rather than anything typed, so each alternate hangs off
     * the key where it leaves the leader — steer to the p and you get "help"
     * instead of "hello". That is something neither the strip nor the picker
     * can say: they list the alternates, they cannot show the way to them.
     *
     * Nothing new is asked of the decoder. Divergence from the leader *is* the
     * next un-drawn letter, because a candidate only shares the stroke so far
     * as it shares the leader's spelling — which is what makes this exact
     * rather than an approximation of a number the beam does not report.
     */
    private fun glideAlternateOctopus(
        state: KeyboardUiState,
        words: List<String>,
    ): OctopusBoard {
        val octopus = state.settings.octopus
        // One reading is no alternates, and the leader itself is the word the
        // lift would type — the strip and the pill are already saying so.
        if (words.size < 2) return emptyMap()
        // What may appear applies to the stroke too (#209). Every alternate
        // here carries on the word the finger is drawing, so they are
        // completions by the same definition the idle board uses — and a user
        // who allowed only next words asked for a board that stays quiet until
        // a word has landed. This is the one place the setting was not read,
        // so the keys lit up mid-swipe and went bare again at the lift.
        if (OctopusKind.COMPLETION !in octopus.kinds) return emptyMap()
        val anchors = state.layouts.keyAnchors(octopus.longPressKeys)
        if (anchors.isEmpty()) return emptyMap()
        val leader = words.first()
        val alternates = words.drop(1).mapIndexed { place, word ->
            // Order-ranked, like every other list the decoder hands over.
            OctopusCandidate(word, -place.toDouble(), OctopusKind.COMPLETION)
        }
        return assignOctopus(
            typed = leader,
            candidates = alternates,
            keys = null,
            keyOf = { codePoint -> anchors[codePoint] ?: -1 },
            limit = octopus.density,
            // Every alternate the decoder still holds is worth showing: it has
            // already survived the beam, and quietening it here would hide the
            // one the stroke is about to be wrong about.
            scoreSpread = Double.POSITIVE_INFINITY,
            perKey = octopus.wordsPerKey,
        ).toOctopusBoard()
    }

    /**
     * The next-word board for a stroke still being drawn: what would follow
     * [leader], hung off the key that starts it (#166).
     *
     * The leading reading is handed in as the previous word, which is the whole
     * idea — the offer for the word *after* this one arrives while the finger
     * is still drawing this one, so it can be flicked without the look and the
     * reach the strip's own next-word offer costs. At the lift the same
     * prediction is what [nextWordOctopus] publishes, so the board does not
     * flicker or change its mind on a successful stroke: it simply stops being
     * a guess.
     *
     * Memoised on the leader for the life of the stroke. A preview arrives
     * every few samples and the leader changes a handful of times across a
     * word, so without this the engine would be asked the same question thirty
     * times a stroke; with it, once per reading. [clearGlidePreview] drops the
     * cache, which is every exit from a stroke.
     */
    private suspend fun glideNextWordOctopus(
        state: KeyboardUiState,
        leader: String,
    ): OctopusBoard {
        // Asked before the cache, because the answer is empty either way and a
        // board that forbids next words must not be handed a stale one after
        // the setting is changed mid-stroke.
        if (OctopusKind.NEXT_WORD !in state.settings.octopus.kinds) return emptyMap()
        glideNextWordBoard?.let { (word, board) -> if (word == leader) return board }
        val board = withContext(Dispatchers.Default) {
            octopusFor(
                state,
                typed = "",
                keys = null,
                pool = emptyList(),
                // The stroke's own word takes the place of the last committed
                // one, and the real previous word slides back a place, so the
                // trigram context is the one the lift will have.
                previous = leader,
                previous2 = previousWord,
            )
        }
        glideNextWordBoard = leader to board
        return board
    }

    private fun octopusFor(
        state: KeyboardUiState,
        typed: String,
        keys: KeySets?,
        pool: List<String>,
        previous: String? = previousWord,
        previous2: String? = previousWord2,
    ): OctopusBoard {
        val octopus = state.settings.octopus
        if (!octopus.enabled || !state.allowsTypingIntelligence) return emptyMap()
        if (state.composer.isConversion || state.composer.isTransliterating) return emptyMap()
        if (state.layoutMode != LayoutMode.LETTERS) return emptyMap()
        val engine = suggestionEngine ?: return emptyMap()
        val anchors = state.layouts.keyAnchors(octopus.longPressKeys)
        if (anchors.isEmpty()) return emptyMap()
        return engine.octopusWords(
            composing = typed,
            previousWord = previous,
            previousWord2 = previous2,
            keys = keys,
            limit = octopus.density,
            kinds = octopus.kinds,
            dense = octopus.dense,
            pool = pool,
            keyOf = { codePoint -> anchors[codePoint] ?: -1 },
            perKey = octopus.wordsPerKey,
        ).toOctopusBoard()
    }

    /**
     * The board for a caret that has just finished a word: the next-word offer,
     * hung off the keys that reach it.
     *
     * A glide is the one commit that does not go through [refreshSuggestions],
     * because the strip has to keep the stroke's own alternates so a wrong
     * reading can be tapped away — and the keys were being left behind with it.
     * They kept whatever they were carrying before the stroke, so gliding word
     * after word showed the same words over the same keys until a space was
     * typed by hand (#118). The strip and the board are answering different
     * questions here: the strip is still about the word that just landed, the
     * keys are about the one after it.
     */
    private suspend fun nextWordOctopus(): OctopusBoard {
        val state = _uiState.value
        // Off is the common case and this sits on the commit path, so it is
        // answered before the thread hop rather than inside [octopusFor].
        if (!state.settings.octopus.enabled) return emptyMap()
        return withContext(Dispatchers.Default) {
            octopusFor(state, typed = "", keys = null, pool = emptyList())
        }
    }

    /**
     * The emoji chips for a caret that has just finished a word: the emoji the
     * next-word prediction itself offers (a learned bigram can end in one), plus
     * the trigger emoji of the word that just landed.
     *
     * The other half of [nextWordOctopus], here for the same reason. A glide is
     * the one commit that does not go through [refreshSuggestions], and that is
     * the only place [KeyboardUiState.emojiSuggestions] is ever written — so the
     * chips beside the strip kept answering about the word before the stroke.
     * Swipe after swipe the same emoji sat there until a space was typed by
     * hand, which is exactly the shape #118 had on the keys (#125).
     */
    private suspend fun nextWordEmoji(): List<String> {
        val state = _uiState.value
        // Off is the common case and this sits on the commit path, so the hop
        // is skipped rather than taken and thrown away. The strip's own gates
        // come first: a secure or silent field offers nothing either way.
        if (!state.settings.emojiPrediction || !state.settings.suggestions ||
            state.secureField || state.fieldNoSuggestions
        ) {
            return emptyList()
        }
        val engine = suggestionEngine ?: return emptyList()
        val predicted = withContext(Dispatchers.Default) {
            engine
                .suggest(
                composing = "", previousWord = previousWord, previousWord2 = previousWord2,
                previousWord3 = previousWord3,
            )
                .filter { isEmojiCandidate(it) }
        }
        // Same tail as [refreshSuggestions]: drop what the font cannot draw,
        // then apply the default skin tone — filter first, since the hidden set
        // is keyed by the neutral base.
        val hidden = state.hiddenEmoji
        return (predicted + triggerEmojiForPreviousWord())
            .distinct()
            .let { list -> if (hidden.isEmpty()) list else list.filterNot { it in hidden } }
            .map { applyEmojiTone(it) }
    }

    /**
     * The strip for a conversion IME: the composer's own reading→character
     * candidates, plus the chip that says when the pack behind them is not on
     * the device.
     *
     * Split out of [refreshSuggestions] because it runs *ahead* of that
     * method's strip gates rather than inside them — see the comment at the
     * call for why a conversion IME cannot be silenced the way the strip is.
     */
    private fun refreshConversionCandidates(state: KeyboardUiState) {
        suggestionJob?.cancel()
        commitResolution = null
        val typed = composing.toString()
        val composer = state.composer
        // A new reading: what is written before it is the context its first
        // word is scored after (#580 follow-up). Read once per reading, from
        // the field, since the caret may have moved since the last commit.
        if (typed.length == 1) {
            // The reading itself is already in the field as the composing
            // text, right before the caret, so it is read and taken back off;
            // unless it is kept on the strip (#973), when the field has none.
            val shown = if (state.readingInKeyboard()) "" else composer.composeBuffer(typed)
            val before = currentInputConnection?.getTextBeforeCursor(CjkContext.KEEP + shown.length, 0)?.toString().orEmpty()
            CjkContext.before = before.removeSuffix(shown)
        }
        val gridOpen = state.panel == PanelMode.CANDIDATES
        refreshConversionPackOffer(state)
        // A new reading is a new list, so whatever the arrow keys had
        // highlighted in the old one no longer means anything. Reset here, on
        // the keystroke, rather than when the list lands: a stepping space
        // pressed in between has already moved on to the new list.
        if (state.candidateCursor != -1) _uiState.update { it.copy(candidateCursor = -1) }
        syncHardwareCandidateWindow()
        if (typed.isEmpty()) {
            refreshConversionStripAtCaret(state)
            return
        }
        conversionPredictions = null
        // A reading is being typed, so whatever backspace took out is not
        // being picked again.
        conversionRepick = null
        conversionDeleted = ""
        // The lattice decode runs off the main thread, with no debounce: the
        // candidates are how this language is typed at all, so they must not
        // wait. A key typed meanwhile cancels the job, and one still queued
        // never runs. What the space bar and a candidate tap commit is decided
        // against the buffer as it stands then, not against this list, so a
        // strip a keystroke behind can be shown but never committed from
        // (see [onCandidateTapped]). The composers keep their last decode, so
        // the space that follows this reads it back rather than decoding again.
        suggestionJob = serviceScope.launch {
            // The T9 pad's syllable column (#635), worked out on the same pass.
            var readings = emptyList<String>()
            val (cands, expanded, found) = withContext(suggestionDispatcher) {
                val cands = composer.candidates(typed)
                readings = composer.readings(typed)
                // The grid is a widening of the same ranking, so it only costs
                // anything while it is actually open.
                val grid = if (gridOpen) composer.candidates(typed, CANDIDATE_GRID_LIMIT) else emptyList()
                val english = conversionEnglish(state, typed)
                val emoji = conversionEmoji(state, cands.firstOrNull(), english.firstOrNull())
                Triple(cands, grid, ConversionFound(english, englishAt(composer, typed, cands, english), emoji))
            }
            // Committed or replaced while this ran: the list is for text that
            // is no longer being composed.
            if (composing.toString() != typed || _uiState.value.composer !== composer) return@launch
            // Drop what the font cannot draw, then apply the default skin
            // tone, the same tail the Latin strip's emoji take.
            val hidden = _uiState.value.hiddenEmoji
            val emoji = found.emoji
                .filterNot { (e, _) -> e in hidden }
                .map { (e, fromEnglish) -> applyEmojiTone(e) to fromEnglish }
            val extras = ConversionExtras(
                typed = typed,
                english = found.english,
                at = found.at,
                englishEmoji = emoji.filter { it.second }.mapTo(HashSet()) { it.first },
            )
            conversionExtras = extras
            _uiState.update {
                it.copy(
                    suggestions = extras.into(cands),
                    conversionReadings = readings,
                    autocorrectWord = null,
                    expandedCandidates = extras.into(expanded),
                    emojiSuggestions = emoji.map { e -> e.first },
                    punctuationSuggestions = emptyList(),
                    inlineEmoji = false,
                    octopus = emptyMap(),
                )
            }
        }
    }

    /** What a conversion pass found beyond the composer's own list, before the main thread shapes it. */
    private class ConversionFound(val english: List<String>, val at: Int, val emoji: List<Pair<String, Boolean>>)

    /**
     * What the conversion strip shows beyond the composer's own candidates
     * (#633): English words for the letters typed, sitting at [at] among the
     * conversions, and which of the emoji chips came from the first of them
     * rather than from the conversion. Kept for the reading it was built for,
     * so a tap can tell an English chip from a conversion and a strip
     * position from the composer's own.
     */
    private class ConversionExtras(
        val typed: String,
        val english: List<String>,
        val at: Int,
        val englishEmoji: Set<String>,
    ) {
        /** [candidates] with the English words in their place. */
        fun into(candidates: List<String>): List<String> {
            if (english.isEmpty()) return candidates
            val cut = at.coerceAtMost(candidates.size)
            return candidates.take(cut) + english + candidates.drop(cut)
        }

        /** The composer's own index for strip position [index]; -1 for an English chip. */
        fun composerIndex(index: Int): Int = when {
            english.isEmpty() || index < at -> index
            index < at + english.size -> -1
            else -> index - english.size
        }
    }

    /** The extras of the last conversion pass; see [ConversionExtras]. */
    private var conversionExtras: ConversionExtras? = null

    /**
     * English words for a conversion reading (#633). Pinyin, romaji and
     * Jyutping are typed on the same letters as English, so with English among
     * the language's secondaries the strip offers `hello` beside what the
     * reading converts to, the way Gboard and Sogou do. Under the strip's own
     * gates: unlike the conversions, these are suggestions.
     */
    private fun conversionEnglish(state: KeyboardUiState, typed: String): List<String> {
        if (!state.composer.readsLatinLetters || !state.allowsTypingIntelligence) return emptyList()
        if (!state.settings.suggestions || state.fieldNoSuggestions) return emptyList()
        val words = suggestionEngine?.englishCompletions(typed, CONVERSION_ENGLISH_WORDS).orEmpty()
        // The reading carries no case of its own, but a shifted first letter
        // is a capital the English word should keep.
        if (typed.firstOrNull()?.isUpperCase() != true) return words
        return words.map { word -> word.replaceFirstChar { it.uppercase() } }
    }

    /**
     * Where [english] goes among [cands]. Never first: the head is what the
     * space bar commits, and that stays the conversion. Second when the top
     * conversion covers only part of the buffer — `hello` is 和 and a tail of
     * letters, and the English is the likelier reading — and behind the first
     * few otherwise, where `hen` is 很 and the hen is a fallback.
     */
    private fun englishAt(composer: Composer, typed: String, cands: List<String>, english: List<String>): Int = when {
        english.isEmpty() || cands.isEmpty() -> 0
        composer.consumedForIndex(typed, 0) < typed.length -> 1
        else -> minOf(CONVERSION_ENGLISH_AFTER, cands.size)
    }

    /**
     * The emoji for a conversion reading: what the top conversion names in the
     * language's emoji keywords (笑 → 😄), then what the first English word
     * names. Each paired with whether it came from the English word, which an
     * appending tap needs to know what to write before it.
     */
    private fun conversionEmoji(state: KeyboardUiState, top: String?, english: String?): List<Pair<String, Boolean>> {
        if (!state.settings.emojiPrediction || !state.settings.suggestions) return emptyList()
        if (!state.allowsTypingIntelligence || state.fieldNoSuggestions) return emptyList()
        val suggester = emojiSuggester ?: return emptyList()
        val found = LinkedHashMap<String, Boolean>()
        top?.let { word -> suggester.suggest(word).forEach { found.putIfAbsent(it, false) } }
        english?.let { word -> suggester.suggest(word).forEach { found.putIfAbsent(it, true) } }
        return found.toList()
    }

    /**
     * Puts up — or takes down — the chip naming the conversion pack the
     * keyboard is missing.
     *
     * The conversion tables are too big to bundle, so a fresh install has none:
     * the composer still types, committing the raw reading, and no character is
     * ever offered for it. Nothing on screen said why, and the pack's own row
     * is several screens into Settings, so Chinese looked simply broken
     * (issue #260). Asked the moment a layout that converts comes up, the way
     * the missing-word-list chip is for glide, rather than only once a reading
     * has been typed and nothing came back: by then the user has already met
     * the broken keyboard the chip exists to explain.
     *
     * Not before the tables have been read once, though: until then every
     * table is empty whether its pack is on disk or not, and the chip would
     * go up, once and for good, for a user who has the pack.
     *
     * Once per pack per process, the same as the missing-word-list chip, and
     * never in a password field: a download offer is not what that field is
     * for.
     */
    private fun refreshConversionPackOffer(state: KeyboardUiState) {
        // A pack that would only improve the candidates (#580) is asked about
        // the same way, once nothing more basic is missing.
        val pack = state.composer.missingPack ?: state.composer.improvingPack
        if (pack == null) {
            // Downloaded since, or the layout moved to one that needs no pack.
            clearConversionPackOffer()
            return
        }
        if (loadedCjkPackToken == Int.MIN_VALUE || state.secureField) return
        if (state.conversionPackOffer != null || !conversionPackNoticed.add(pack)) return
        _uiState.update { it.copy(conversionPackOffer = pack) }
    }

    /** The chip was tapped: the pack's own language page, where it downloads. */
    private fun acceptConversionPackOffer() {
        val pack = _uiState.value.conversionPackOffer?.let(CjkDictCatalog::byId) ?: return
        clearConversionPackOffer()
        openRoute("language/${pack.langId}")
    }

    /** Takes the missing-pack chip down, answered or overtaken by typing. */
    private fun clearConversionPackOffer() {
        if (_uiState.value.conversionPackOffer != null) {
            _uiState.update { it.copy(conversionPackOffer = null) }
        }
    }

    /** The packs already named once, so the chip asks and then stays out of the way. */
    private val conversionPackNoticed = mutableSetOf<String>()

    /**
     * Whether a space would run [SuggestionEngine.decideCorrection] on [typed]:
     * a plain Latin board with autocorrect on. The same order of cases as the
     * precompute in [refreshSuggestions] and the commit in [commitComposing].
     */
    private fun latinResolution(state: KeyboardUiState, typed: String): Boolean =
        typed.isNotEmpty() && state.composer.phoneticLanguage == null && !state.layouts.ambiguousKeys &&
            // Khipro's keys spell the word exactly; there is nothing to correct.
            state.composer.completionLanguage == null &&
            // Vietnamese commits a composed word through its own branch, which
            // asks the engine about that word and not about the keystrokes. A
            // resolution computed over "tieengs" could only be discarded.
            !isVietnameseTransliterator(state) &&
            state.settings.correction.enabledFor(state.language.id) && state.allowsTypingIntelligence

    /**
     * Whether the composer writes Vietnamese by transliteration, Telex or VNI.
     *
     * These two commit a composed Vietnamese word, where every other
     * transliterator commits the reading itself — Hangul's buffer holds jamo,
     * and there is no list to rank that against. Asked by identity rather than
     * by a new flag on `Composer`: upstream retired `isBengaliPhonetic` in
     * favour of a language id the composer carries, and a second such flag
     * would be the branch that change set out to remove.
     */
    private fun isVietnameseTransliterator(state: KeyboardUiState): Boolean =
        state.composer === VietnameseTelexComposer || state.composer === VietnameseVniComposer

    /**
     * Starts working out what a space would make of [typed], now.
     *
     * It used to ride the strip pass, which waits out a debounce of up to
     * [MAX_SUGGESTION_DEBOUNCE_MS] first. A space typed inside that window —
     * which is most of them, typing at speed — found no answer and ran the
     * whole correction walk again on the main thread, between the keystroke
     * and its frame. Started here instead, the answer is usually in by the
     * time the space lands, and when it is still being worked out
     * [awaitCommitResolution] waits for it rather than starting over.
     *
     * One lane, and a job still queued when the next key cancels it never
     * runs, so a burst costs one walk at a time however fast it is typed.
     */
    private fun resolveCommitAhead(engine: SuggestionEngine, typed: String) {
        resolutionJob?.cancel()
        // Read now, while they still describe this word.
        val touch = composingTouchFrame()
        val keys = composingKeyFrame()
        val timing = timingMultiplier()
        val pending = PendingResolution(typed)
        pendingResolution = pending
        resolutionJob = serviceScope.launch(resolutionDispatcher) {
            pending.started = true
            try {
                val decision = engine.decideCorrection(typed, touch = touch, timingMultiplier = timing, keys = keys)
                // Withdrawn meanwhile — a word blocked mid-walk, say — lands nothing.
                if (pendingResolution !== pending) return@launch
                commitResolution = CommitResolution(
                    typed = typed,
                    isPhonetic = false,
                    phoneticTop = null,
                    correction = decision.apply?.takeIf { it != typed },
                    offer = decision.offer?.takeIf { it != typed },
                    certainty = decision.certainty,
                    complexity = decision.complexity,
                )
            } finally {
                pending.done.countDown()
            }
        }
    }

    /**
     * The resolution [resolveCommitAhead] is still working out for [typed],
     * waited for; null when nothing is working on this word, so the caller
     * resolves it itself. Waiting costs the main thread no more than the rest
     * of a walk that is already under way, where resolving afresh would cost
     * the whole of one. Capped, so a stalled worker cannot hold up a commit.
     */
    private fun awaitCommitResolution(typed: String): CommitResolution? {
        val pending = pendingResolution?.takeIf { it.typed == typed && it.started } ?: return null
        pending.done.await(COMMIT_RESOLUTION_WAIT_MS, TimeUnit.MILLISECONDS)
        return commitResolution?.takeIf { it.typed == typed }
    }

    private fun refreshSuggestions() = trace(ImeTrace.REFRESH_SUGGESTIONS) { refreshStrip() }

    private fun refreshStrip() {
        // Whether a word is being typed, for the compact dictation bar, which
        // gives the strip back while one is (#910). Here because every
        // keystroke and every commit rebuilds the strip, ahead of the early
        // returns below so none of them leaves it stale.
        val typing = composing.isNotEmpty()
        if (_uiState.value.wordComposing != typing) _uiState.update { it.copy(wordComposing = typing) }
        val state = _uiState.value
        if (emailFieldForceActive(state)) {
            refreshEmailFieldSuggestions()
            return
        }
        refreshSmartSuggestion()
        // Ahead of the engine check: a snippet offer is the user's own text
        // waiting on their own trigger, not a guess the dictionary made, so it
        // does not wait for a lexicon to have finished loading.
        refreshSnippetOffer(state)
        // The ladder's first rung is earned by the lexicon growing rather than
        // by any stroke, so nothing on the glide path notices it. Asked here,
        // where the strip is being rebuilt anyway and a chip has somewhere to
        // land.
        maybeOfferFirstSandboxRung()

        // Conversion IMEs (Chinese Pinyin, Japanese) show the composer's own
        // reading→character candidates in the strip, not dictionary word
        // suggestions. The lookup is a cheap map read, so it runs inline, and
        // it needs no lexicon — hence ahead of the engine check.
        //
        // Ahead of the strip gates below too, and that is the point: for a
        // conversion IME the candidate list *is* the input method, the way a
        // transliterator's composing buffer is (see [Composer.isConversion]).
        // Silencing it the way the strip is silenced does not hide a guess, it
        // makes the language untypeable — which is what a field carrying
        // NO_SUGGESTIONS, or a FILTER/URI/email variation, or the suggestion
        // strip simply switched off, used to do to every Chinese and Japanese
        // field in the app: the pinyin kept composing (it transliterates) and
        // no Hanzi was ever offered for it (issue #260). A password field is
        // included for the same reason — people whose language needs
        // conversion also have to type it into one — and learning stays out of
        // all of them through [learningAllowed], which never covers a secure
        // field.
        if (state.composer.isConversion) {
            refreshConversionCandidates(state)
            return
        }

        val engine = suggestionEngine ?: return
        if (!state.settings.suggestions || state.secureField || state.fieldNoSuggestions) return

        // Inline emoji search takes over the strip entirely: word suggestions
        // for ":smi" would be noise. A bare ":" shows nothing until there is
        // something to search for.
        inlineEmojiQuery()?.let { query ->
            suggestionJob?.cancel()
            suggestionJob = serviceScope.launch {
                delay(EMOJI_SEARCH_DEBOUNCE_MS)
                val results = if (query.length < 2) {
                    emptyList()
                } else {
                    withContext(Dispatchers.Default) {
                        emojiSearch?.search(query, limit = INLINE_EMOJI_LIMIT)
                            .orEmpty()
                            .map { it.emoji }
                    }
                }
                _uiState.update {
                    it.copy(
                        suggestions = results,
                        emojiSuggestions = emptyList(),
                        punctuationSuggestions = emptyList(),
                        inlineEmoji = true,
                    )
                }
            }
            return
        }

        val typed = composing.toString()

        // A caret touching a word it is not parked at the end of: the strip
        // answers about that word instead of predicting the next one (#32).
        // Nothing is composing, so none of the buffer machinery below — the
        // commit resolution, the next-letter bias, the join and revision chips
        // — has anything to say about it.
        val caret = caretWord
        if (typed.isEmpty() && caret != null && !state.composer.isTransliterating) {
            publishCaretWordSuggestions(engine, caret)
            return
        }

        // The caret right after digits typed on their own: the numbers the
        // user typed before that start with them (#431).
        val digitRun = numberRun
        if (typed.isEmpty() && digitRun != null && publishTypedNumbers(digitRun)) return

        if (latinResolution(state, typed)) {
            resolveCommitAhead(engine, typed)
        } else {
            resolutionJob?.cancel()
            pendingResolution = null
        }

        suggestionJob?.cancel()
        suggestionJob = serviceScope.launch {
            // Short adaptive debounce: fast bursts of keystrokes cancel the
            // job while it still sleeps here, so only the final state is
            // computed. The window tracks half the average compute cost.
            //
            // The ceiling used to be 40 ms, which quietly threw away the whole
            // point of measuring (#313). A burst only collapses here if the
            // next keystroke lands inside the window, so on a device where a
            // pass costs 400 ms — the keyboard knows it does, it is sitting in
            // [suggestionCostMs] — a 40 ms window let every single keystroke
            // launch a full pass and the debounce did nothing at all. It is
            // now allowed to grow with the cost it measures.
            //
            // The ceiling is what keeps it honest in the other direction: past
            // it the strip is visibly late, and a word committed before its
            // pass finishes falls back to resolving the commit synchronously
            // on the main thread (see [commitResolution] in commitComposing),
            // which is the cost this is trying to avoid. Devices that are fast
            // enough for cost/2 to stay under the old 40 ms are unaffected.
            delay((suggestionCostMs / 2).coerceIn(16L, MAX_SUGGESTION_DEBOUNCE_MS))
            val started = SystemClock.uptimeMillis()
            val touchFrame = composingTouchFrame()
            // Snapshot with the taps, for the same reason: the key sets belong
            // to the word as it stands now, not to whatever the buffer holds
            // by the time this runs.
            val keyFrame = composingKeyFrame()
            // Snapshot like the touch frame: the rhythm belongs to the word
            // as typed now, not to whatever the buffer holds when the async
            // precompute actually runs.
            val timingMultiplier = timingMultiplier()
            // And the number the keys spelled (#181), read here with the other
            // per-keystroke frames while they still describe this word.
            val number = predictedNumber(state)
            val recentSnapshot = recentWords.toList()
            // The strip shows a handful; the keys have room for far more, and
            // several ranked words often want the same key ("the", "they" and
            // "there" all continue with an e) so the ones that reach a key are
            // fewer still. Asking for a deeper list is how those keys get
            // filled with words the engine actually ranked, rather than with
            // whatever a raw trie walk finds once the good ones run out. The
            // strip is unaffected: a deeper ask does not reorder its head, and
            // it takes the same slice it always did.
            val octopusOn = state.settings.octopus.enabled && state.allowsTypingIntelligence
            // A strip that scrolls has room for every word the pass ranked,
            // not only the few that fit (#516): Avro's fourth reading is as
            // often the word as its first.
            // More slots for short words (#970) needs words past the usual five.
            val stripDepth = when {
                state.settings.suggestionStrip.scrollable -> SUGGEST_PAGES_POOL
                state.settings.suggestionStrip.fitMoreWords ->
                    maxOf(SUGGEST_LIMIT, state.settings.suggestionStrip.slotCount + com.wasimaster.wmkeyboard.ime.ui.FitMoreExtraSlots)
                else -> SUGGEST_LIMIT
            }
            val askFor = if (octopusOn) {
                maxOf(stripDepth, state.settings.octopus.density * OCTOPUS_POOL_DEPTH)
            } else {
                stripDepth
            }
            // Pages of suggestions (#385) want the deeper list the strip never
            // shows. Asked for in the same walk, so a swipe down has it at once;
            // the strip and the keys still take the head they always took.
            // The scrolling strip's arrow opens the same grid (#890).
            val pagesOn = (
                state.settings.suggestionStrip.swipeForMore || state.settings.suggestionStrip.swipeUpForMore ||
                    state.settings.suggestionStrip.scrollable
                ) &&
                state.composer.completionLanguage == null
            val askDeep = if (pagesOn) maxOf(askFor, SUGGEST_PAGES_POOL) else askFor
            // Desktop Avro's candidate list, for the row above the strip when
            // the language is set to draw it there.
            var candidateBar = emptyList<String>()
            // IndicXlit's readings, when the language has them on: asked now,
            // read after the walk, so the two overlap.
            val neural = if (state.composer.completionLanguage == null) requestNeuralReadings(state, typed) else null
            val (walkResults, emojis, bias, floating) = withContext(suggestionDispatcher) {
                // A layout whose keys already spell the word (Khipro) is
                // completed from what they spelled, not from the roman keys;
                // the tap and key frames belong to those keys, so they stay out.
                val completing = state.composer.completionLanguage
                val deepAll = trace(ImeTrace.SUGGEST) {
                    engine.suggest(
                        composing = if (completing != null) state.composer.composeBuffer(typed) else typed,
                        previousWord = previousWord,
                        phoneticLanguage = state.composer.phoneticLanguage,
                        limit = askDeep,
                        touch = touchFrame.takeIf { completing == null },
                        previousWord2 = previousWord2,
                        recentWords = recentSnapshot,
                        allowRerank = true,
                        keys = keyFrame.takeIf { completing == null },
                        previousWord3 = previousWord3,
                        phoneticSlots = state.settings.suggestionStrip.slotCount,
                        completionLanguage = completing,
                    )
                }.let { walked ->
                    val (lang, ask) = neural ?: return@let walked
                    val waited = SystemClock.uptimeMillis() - started
                    val readings = indicXlit?.await(ask, NEURAL_BUDGET_MS - waited).orEmpty()
                    // Too slow for this pass: the answer is cached when it
                    // comes, and the strip is drawn again for it if the word
                    // is still the one being typed.
                    if (!ask.isDone) {
                        serviceScope.launch {
                            withContext(Dispatchers.IO) { indicXlit?.await(ask, NEURAL_LATE_MS) }
                            if (ask.isDone && !ask.isCancelled && composing.toString() == typed) refreshSuggestions()
                        }
                    }
                    engine.withNeuralReadings(lang, walked, readings, typed, lead = neuralLeads(state, lang))
                }
                val deep = deepAll.take(askFor)
                state.composer.phoneticLanguage?.let { lang ->
                    val where = state.settings.suggestionStrip.phoneticCandidateListFor(lang)
                    if (typed.isNotEmpty() && where == PhoneticCandidateList.BAR) {
                        candidateBar = engine.phoneticCandidates(lang, typed, PHONETIC_CANDIDATE_BAR_MAX)
                    }
                }
                // The walk itself cannot be interrupted — the engine has no
                // suspension point in it — but everything after it can be, and
                // on a phonetic or autocorrecting board what follows is not
                // cheap: [commitResolution] below runs a second engine pass
                // (phoneticCommit, or decideCorrection), and the emoji and
                // octopus blocks after it walk again. A pass the user has
                // already typed past should pay for the walk it could not stop
                // and nothing more, so the seams between those phases are where
                // it is asked (#313).
                ensureActive()
                // An English word the space is about to commit as English
                // leads the strip, and what the keys spell sits right behind
                // it, one tap away (#487).
                val latin = if (completing != null) completionLatin(state, typed) else null
                // Otherwise the keys as typed still get a chip, right behind
                // the Bangla reading: all of them, `/` and `f` included, so
                // the user can see which modifier went in (#772), unless the
                // language turned that off. Then only a word of letters gets
                // one, for the English words no list knows (#594), and with
                // English mixing off there is none.
                val literal = when {
                    completing == null || latin != null || typed.isEmpty() -> null
                    state.settings.suggestionStrip.rawKeysChipFor(completing) -> typed
                    state.allowsTypingIntelligence ->
                        engine.completionLiteral(typed)?.let { sentenceCasedLatin(it, typed, state) }
                    else -> null
                }
                val ranked = if (latin != null) listOf(latin) + deep.filterNot { it == latin } else deep
                val suggested = (
                    if (literal != null && ranked.none { it == literal }) {
                        ranked.take(1) + literal + ranked.drop(1)
                    } else {
                        ranked
                    }
                    ).take(stripDepth)
                // A28: a personal-dictionary shortcut typed in full offers its
                // expansion as the top chip (e.g. "omw" → "on my way"). Prepended
                // so it wins the primary slot; deduped against the word list.
                // An imported dictionary's shortcuts ride the same chip.
                val shortcut = if (typed.isNotEmpty()) shortcutExpansion(state, typed) else null
                // A phonetic strip that keeps its first two chips still takes
                // the expansion right after them rather than in front.
                val fixedChips = if (engine.phoneticFixedStrip != null && state.composer.phoneticLanguage != null) {
                    FIXED_PHONETIC_CHIPS
                } else {
                    0
                }
                fun withShortcut(list: List<String>) = shortcut
                    ?.let { cut ->
                        val rest = list.filterNot { w -> w == cut }
                        val at = fixedChips.coerceAtMost(rest.size)
                        rest.take(at) + cut + rest.drop(at)
                    }
                    ?: list
                // Optionally leave out the word already typed, so all three
                // slots offer something new. The octopus drops it either way —
                // a word the buffer already spells has no next key — so this is
                // only about the strip.
                // Not on a phonetic layout: the buffer in Latin letters is not
                // the word being typed there, it is the way to write it in
                // English, and the only one.
                val skipTyped = state.settings.suggestionStrip.skipTypedWord && typed.isNotEmpty() &&
                    state.composer.phoneticLanguage == null && completing == null
                fun dropTyped(list: List<String>) =
                    if (skipTyped) list.filterNot { it.equals(typed, ignoreCase = true) } else list
                // The other half of that setting (#413): with it off the strip
                // keeps one slot for the word exactly as typed, which is what
                // the setting's own text has always promised — but the engine
                // only produced the word when it ranked it, and a long word it
                // does not know rarely was, so "invigorate" left the strip
                // empty. Put back in the second slot, which centre-primary
                // draws on the left: the place a typed word holds on every
                // keyboard. Never ahead of the first entry, for the reason the
                // comment below gives.
                //
                // On a board that builds its letters out of the keys (Hangul
                // from jamo, Cheonjiin from strokes) the word as typed is the
                // one in the field, not the keys: a chip reading ㄱㅣㆍ for 가
                // would commit the jamo when tapped (#598).
                val typedWord = if (state.composer.isTransliterating) state.composer.composeBuffer(typed) else typed
                val keepTyped = !skipTyped && typedWord.isNotEmpty() && typedWord[0].isLetterOrDigit() &&
                    state.composer.phoneticLanguage == null && completing == null &&
                    state.allowsTypingIntelligence
                fun withTyped(list: List<String>): List<String> =
                    if (keepTyped && list.none { it.equals(typedWord, ignoreCase = true) }) {
                        val at = minOf(1, list.size)
                        list.take(at) + typedWord + list.drop(at)
                    } else {
                        list
                    }
                // Deliberately unfiltered: commitResolution below reads this,
                // and on a Bengali or ambiguous board its first entry is what a
                // space commits. Dropping the typed word from *that* would make
                // the setting silently replace what was written, so the filter
                // is applied to the strip and the keys alone.
                val words = withTyped(withShortcut(suggested))
                // The same list, only longer, so the keys and the strip never
                // disagree about what is being offered — the keys just see
                // further down it.
                val pool = dropTyped(withShortcut(deep))
                // What a swipe down on the strip pages through (#385): the strip's
                // own words first, in its order, then the rest of the deep list.
                suggestionPages = if (pagesOn) typed to (words + withShortcut(deepAll)).distinct() else null
                // Next-letter distribution for smart key-hit detection. Only for
                // plain Latin composing — conversion/transliteration IMEs commit
                // through their own composer, where a Latin-letter nudge is wrong.
                // Read off the ranked list the strip is cut from, so the keys
                // grow toward the words the strip offers: the raw trie walk
                // knows only the primary dictionary, with no context, and on a
                // mixed board it enlarged "e a c" for "be" while the strip said
                // "beshi". The walk is the fallback for a list with nothing
                // that continues the buffer (only corrections, say).
                val bias = if (
                    state.settings.layoutBehavior.smartHitDetection &&
                    typed.isNotEmpty() &&
                    !state.composer.isTransliterating
                ) {
                    rankedNextLetters(typed, deepAll).ifEmpty { engine.nextLetterWeights(typed) }
                } else {
                    emptyMap()
                }
                // Precompute what a space/enter commit of this exact word would
                // resolve to, so the commit need not run the edit-distance
                // search (English) or transliteration ranking (Bengali) on the
                // main thread. commitComposing consumes it only on a typed match.
                ensureActive()
                commitResolution = when {
                    typed.isEmpty() -> null
                    state.composer.phoneticLanguage != null -> {
                        val commit = engine
                            .phoneticCommit(state.composer.phoneticLanguage.orEmpty(), typed, previousWord, previousWord2)
                        // The ordinary strip's head is what a space commits. A
                        // fixed strip's head is the buffer in Latin letters,
                        // whatever the space will do, so there the commit is
                        // asked for directly (the expansion still wins it).
                        val top = if (fixedChips > 0) shortcut ?: commit?.output else words.firstOrNull()
                        CommitResolution(
                            typed = typed,
                            isPhonetic = true,
                            phoneticTop = top,
                            // Only while the commit is the engine's own answer;
                            // a shortcut expansion was never a choice between
                            // scripts.
                            phoneticAlternate = commit?.takeIf { it.output == top }?.alternate,
                            correction = null,
                        )
                    }
                    // An ambiguous board's commit takes the reading rather than
                    // the buffer, so the reading is what there is to precompute
                    // — and autocorrect has nothing to say about anchor letters
                    // that the decode has not already said better.
                    state.layouts.ambiguousKeys -> CommitResolution(
                        typed = typed,
                        isPhonetic = false,
                        phoneticTop = null,
                        correction = null,
                        ambiguousTop = words.firstOrNull(),
                    )
                    // Worked out by [resolveCommitAhead] as the key landed,
                    // without this pass's debounce; left as it stands.
                    latinResolution(state, typed) -> commitResolution
                    else -> null
                }
                ensureActive()
                if (typed.isNotEmpty()) {
                    // Faces tagged with the word ("shrug", "tableflip") go in
                    // front when the user asked for them; they ride the emoji
                    // chips, and a tap on one is told apart by the library.
                    val faces = if (kaomojiToolDelegate.isInitialized()) kaomojiTool.suggestionsFor(typed) else emptyList()
                    val emojis = faces + if (state.settings.emojiPrediction) {
                        // The word before is passed for the two-word shortcodes
                        // ("alarm clock" → ⏰); one word can never reach them.
                        // Khipro's roman keys ("ami/") are not a word in any
                        // language; what they spelled is.
                        val query = if (state.composer.completionLanguage != null) {
                            state.composer.composeBuffer(typed)
                        } else {
                            typed
                        }
                        emojiSuggester?.suggest(query, previousWord.orEmpty()).orEmpty()
                    } else {
                        emptyList()
                    }
                    // A word the caret went back into that a glide had written:
                    // that stroke's other readings go in front of the strip's
                    // own answer, which is about the letters standing there and
                    // so cannot reach the word the finger actually drew (#115).
                    // Only while the buffer is still that word — a prefix of it,
                    // so deleting a letter to fix it keeps them and typing on
                    // past it does not.
                    val resumed = resumedWord
                        ?.takeIf { it.startsWith(typed, ignoreCase = true) }
                    val strip = dropTyped(words)
                    SuggestionFrame(
                        NumberPrediction.place(
                            resumed?.let { withGlideReadings(it, resumedWordStart, strip) } ?: strip,
                            number,
                            state.settings.suggestionStrip.slotCount,
                        ),
                        emojis, bias,
                        octopusFor(state, typed, keyFrame, pool = pool),
                    )
                } else {
                    // Next-word prediction: learned bigrams can end in an
                    // emoji ("you" → ❤️). Those belong in the emoji slot of
                    // the strip, not among the word chips — and so does the
                    // trigger emoji of the word that just committed.
                    val (emojiNext, wordNext) = words.partition { isEmojiCandidate(it) }
                    val poolNext = pool.filterNot { isEmojiCandidate(it) }
                    SuggestionFrame(
                        wordNext,
                        if (state.settings.emojiPrediction) {
                            (emojiNext + triggerEmojiForPreviousWord()).distinct()
                        } else {
                            emptyList()
                        },
                        bias,
                        // The strip's own words, hung off their first letters:
                        // whatever it is about to offer is what the keys offer.
                        octopusFor(state, typed, keyFrame, pool = poolNext),
                    )
                }
            }
            // Phrase suggestions: the context model's next few words as one
            // chip, after a space only, when it is sure of each of them.
            val results = if (typed.isEmpty() && state.settings.suggestionStrip.phraseCompletion && state.allowsTypingIntelligence) {
                withContext(suggestionDispatcher) { engine.phraseCompletion() }
                    ?.let { phrase -> if (phrase in walkResults) walkResults else walkResults + phrase }
                    ?: walkResults
            } else {
                walkResults
            }
            suggestionCostMs = (suggestionCostMs + (SystemClock.uptimeMillis() - started)) / 2
            // Drop emoji the device can't draw, then apply the default skin tone
            // (filter first — the hidden set is keyed by the neutral base).
            val hidden = _uiState.value.hiddenEmoji
            val shownEmojis = emojis
                .let { list -> if (hidden.isEmpty()) list else list.filterNot { it in hidden } }
                .map { applyEmojiTone(it) }
            // Quick-punctuation rides the tail beside the word candidates, but
            // only when there are candidates to ride (otherwise the strip is
            // idle and flips to the toolbar) and no emoji prediction is actually
            // drawn in the tail (gate on the shown set, not the raw one).
            val punct = if (
                state.settings.suggestionStrip.punctuation &&
                results.isNotEmpty() &&
                shownEmojis.isEmpty()
            ) {
                // The user's own marks, one chip per character, so a Bengali
                // danda or a Spanish inverted mark can sit here instead of the
                // English five. Blank has already fallen back to the shipped
                // set on the way out of the repository.
                state.settings.suggestionStrip.punctuationChips.map { it.toString() }
            } else {
                emptyList()
            }
            // Join chip: "some" committed, "thing" composing, "something" a
            // clearly better word. A handful of map hits — fine on main.
            val join = if (
                typed.isNotEmpty() && !state.composer.isTransliterating &&
                !state.composer.isConversion && state.allowsTypingIntelligence
            ) {
                engine.joinCandidate(previousWord, typed)
            } else {
                null
            }
            joinContext = join?.let { previousWord.orEmpty() to typed }
            // Revision chip: the word just committed sometimes proves the one
            // before it wrong ("their going" → "they're"). Empty-composing
            // only — the moment of the space is when the evidence lands — and
            // chip-only: it never rewrites anything by itself.
            var revision = if (
                typed.isEmpty() && state.allowsTypingIntelligence &&
                engine.englishSources && previousWord2 != null && previousWord != null
            ) {
                revisionAdvisor?.advise(previousWord2, previousWord)
            } else {
                null
            }
            revisionContext = revision?.let { previousWord2.orEmpty() to previousWord.orEmpty() }
            // The context model's re-reading of the word before, with the one
            // just committed in sight ("by a car" → "buy"): the same chip, the
            // same contract, for any pair the confusable table never listed.
            if (revision == null && typed.isEmpty() && state.allowsTypingIntelligence &&
                state.settings.suggestionStrip.contextRevision
            ) {
                engine.contextRevision()?.let { found ->
                    revision = found.replacement
                    revisionContext = found.wrong to found.followers.joinToString(" ")
                }
            }
            // And the last few words once the typing pauses: the same chip,
            // the model reading the whole tail. Nothing is offered while a
            // chip already stands, and the job dies with the next keystroke.
            pauseRevisionJob?.cancel()
            if (typed.isEmpty() && revision == null && state.allowsTypingIntelligence &&
                state.settings.suggestionStrip.contextRevision && engine.contextModel != null
            ) {
                pauseRevisionJob = serviceScope.launch {
                    delay(REVISION_PAUSE_MS)
                    val found = withContext(suggestionDispatcher) {
                        engine.contextRevision(SuggestionEngine.REVISION_PAUSE_BACK)
                    } ?: return@launch
                    if (composing.isNotEmpty() || _uiState.value.revisionSuggestion != null) return@launch
                    revisionContext = found.wrong to found.followers.joinToString(" ")
                    _uiState.update { it.copy(revisionSuggestion = found.replacement) }
                }
            }
            // The near-miss chip belongs to the word that was just committed,
            // so it only survives while the composing buffer is still empty:
            // start the next word and the offer about the last one is gone.
            val offer = pendingCorrectionOffer
                ?.takeIf { typed.isEmpty() && state.settings.suggestionStrip.offerNearMissCorrections }
            if (offer == null) {
                pendingCorrectionOffer = null
                correctionOfferFor = null
            }
            // The undo chip outlives its own commit, but only shows between
            // words. Its tap edits committed text behind the caret, and doing
            // that while a composing region is open is how a composition ends
            // up pointing at the wrong span — so it waits for the space rather
            // than risking the word being typed.
            val undo = undoChain.lastOrNull()?.typed?.takeIf { typed.isEmpty() }
            // Nothing typed after a sentence end or a line break: these are
            // openers, which rest behind the toolbar like the ones at the start
            // of the field (#889).
            val openers = typed.isEmpty() && previousWord == WordContext.SENTENCE_START
            val stripTyped = typed.takeIf { it.isNotEmpty() && !state.composer.isTransliterating }
            _uiState.update {
                it.copy(
                    suggestions = results,
                    stripTyped = stripTyped,
                    sentenceOpeners = if (openers) results else emptyList(),
                    phoneticCandidates = candidateBar,
                    emojiSuggestions = shownEmojis,
                    punctuationSuggestions = punct,
                    nextLetterBias = bias,
                    octopus = floating,
                    inlineEmoji = false,
                    joinSuggestion = join,
                    revisionSuggestion = revision,
                    correctionOffer = offer,
                    correctionUndo = undo,
                    // Only the correction this commit will keep (#90); a
                    // resolution left over from another word promises nothing.
                    // A fixed phonetic strip's head is not the commit, so the
                    // word a space will write is named there instead.
                    autocorrectWord = commitResolution?.takeIf { it.typed == typed }?.let {
                        if (it.isPhonetic && engine.phoneticFixedStrip != null) it.phoneticTop else it.correction
                    },
                )
            }
        }
    }

    /**
     * The strip for a caret sitting inside a word: the word itself, then
     * completions and corrections for it.
     *
     * The word leads because the strip is *about* it — proofreading is reading
     * a word back, and a chip is the only way to reach the held-word menu that
     * adds, opens or forgets it (#263). Tapping it changes nothing, which is
     * why it used to be dropped here; the hold is what it is for, and the tap
     * stands down in [onSuggestionTapped] rather than splicing the word over
     * itself. It is put in front rather than left wherever the engine ranked
     * it so that a word no dictionary knows — the one case where "add" is the
     * whole point — gets a chip at all, and it goes under the same setting
     * that governs the typed word's slot on the composing strip.
     *
     * Its own small path rather than a detour through the composing one. There
     * is no keystroke behind this, so there is no touch frame to rank against
     * and no typing rhythm to weigh; and there is nothing to commit, so the
     * space/enter resolution is cleared rather than computed.
     */
    private fun publishCaretWordSuggestions(engine: SuggestionEngine, caret: CaretWord) {
        val word = caret.word
        suggestionJob?.cancel()
        commitResolution = null
        val recentSnapshot = recentWords.toList()
        val skipWord = _uiState.value.settings.suggestionStrip.skipTypedWord
        suggestionJob = serviceScope.launch {
            val others = withContext(suggestionDispatcher) {
                engine.suggest(
                    composing = word,
                    previousWord = previousWord,
                    previousWord2 = previousWord2,
                    recentWords = recentSnapshot,
                    allowRerank = true,
                    previousWord3 = previousWord3,
                ).filterNot { it.equals(word, ignoreCase = true) }
            }
            // Filtered out above and put back here, so the word holds one slot
            // however the engine ranked it — or whether it ranked it at all.
            val suggested = if (skipWord) others else listOf(word) + others
            // A caret dropped on a swiped word is the user reading it back, and
            // what they want there is the swipe's other readings rather than
            // respellings of the one it picked (#115). Those still lead: the
            // word standing in the field is the one being doubted.
            val results = withGlideReadings(word, caret.start, suggested)
            // And when the readings were not enough — the sandbox had one
            // answer and it was wrong — the chip offers the stroke to the
            // whole dictionary. Only where the user asked for the chip; the
            // held-word menu reaches the same search without a slot (#135).
            val searchChip = word.takeIf {
                _uiState.value.settings.gesture.searchAllChip && caretStrokeWord() != null
            }
            _uiState.update {
                it.copy(
                    glideSearchChip = searchChip,
                    suggestions = results,
                    stripTyped = null,
                    emojiSuggestions = emptyList(),
                    punctuationSuggestions = emptyList(),
                    inlineEmoji = false,
                    joinSuggestion = null,
                    revisionSuggestion = null,
                    correctionOffer = null,
                    correctionUndo = null,
                    autocorrectWord = null,
                )
            }
        }
    }

    /**
     * A quick-punctuation chip in the suggestion strip was tapped. Routed
     * through the ordinary text path so it is indistinguishable from typing
     * that punctuation key — the composing word commits, auto-capitalise and
     * pending auto-space fire, and contextual-vowel handling all apply.
     */
    fun onPunctuationSuggestionTapped(mark: String) {
        onText(mark)
    }

    /**
     * How deep the expanded grid goes. Well under the composers' own lookup
     * depth, so every candidate it shows can still be resolved back to the input
     * length it consumes.
     */
    private val CANDIDATE_GRID_LIMIT = 100

    /** English words offered beside a conversion reading's candidates (#633). */
    private val CONVERSION_ENGLISH_WORDS = 2

    /** Fewest predictions asked for after a conversion commit; the strip scrolls. */
    private val CONVERSION_PREDICTIONS = 12

    /** Conversions a field remembers for backspace to re-pick (#711). */
    private val RECENT_CONVERSIONS = 32

    /** Longest run of backspaced text kept to match against them. */
    private val CONVERSION_DELETED_MAX = 32

    /** How many conversions keep their places ahead of the English words, at most. */
    private val CONVERSION_ENGLISH_AFTER = 3

    /**
     * The buffer the last suggestion pass ran for, and every word it ranked,
     * deepest first-to-last: what a swipe down on the strip shows (#385).
     * Written on the suggestion dispatcher, read on the main thread.
     */
    @Volatile
    private var suggestionPages: Pair<String, List<String>>? = null

    /**
     * A swipe on the word strip (#385): down opens the grid of every word the
     * last pass ranked, over the keys, reusing the conversion candidates' grid;
     * up, or a second swipe, closes it. Nothing happens when the pass that
     * filled the list was for a different word, or found nothing the strip
     * is not already showing.
     */
    fun onSuggestionPagesToggle(open: Boolean) {
        val state = _uiState.value
        if (state.composer.isConversion) return
        if (!open || state.panel == PanelMode.CANDIDATES) {
            if (state.panel == PanelMode.CANDIDATES) {
                _uiState.update { it.copy(panel = PanelMode.NONE, expandedCandidates = emptyList()) }
            }
            return
        }
        if (state.panel != PanelMode.NONE) return
        val (forWord, words) = suggestionPages ?: return
        if (forWord != composing.toString()) return
        // After the words, what else the word could become (#970): the emoji
        // that match it, more than the strip has room for, and the word in
        // every fancy style, so the look can be picked by looking at it.
        val strip = state.settings.suggestionStrip
        val emoji = if (strip.pagesEmoji && state.allowsTypingIntelligence && forWord.length >= 2) {
            emojiSearch?.search(forWord, limit = PAGES_EMOJI_MAX).orEmpty()
                .map { it.emoji }
                .filterNot { it in state.hiddenEmoji }
                .map { applyEmojiTone(it) }
                .distinct()
        } else {
            emptyList()
        }
        val fancy = if (strip.pagesFancy && ToolbarTool.FANCY in state.settings.enabledTools && !state.secureField) {
            FancyStyles.all.asSequence()
                .filter { it.id != FancyStyles.NORMAL_ID }
                .map { FancyStyles.transform(forWord, it) }
                .filter { it != forWord }
                .distinct()
                .toList()
        } else {
            emptyList()
        }
        if (words.size <= strip.slotCount && emoji.isEmpty() && fancy.isEmpty()) return
        pagesEmoji = emoji.toHashSet()
        pagesFancy = fancy.toHashSet()
        vibrate()
        _uiState.update { it.copy(panel = PanelMode.CANDIDATES, expandedCandidates = (words + emoji + fancy).distinct()) }
    }

    /**
     * The pages behind the strip a glide just filled with [words] (#979). A
     * swipe commits its word, so nothing composes afterwards, and the last
     * suggestion pass, the openers or next words from before the swipe, was
     * for that same empty buffer: a swipe down or up on the strip showed
     * those instead of the stroke's alternates.
     */
    private fun glideStripPages(words: List<String>) {
        suggestionPages = "" to words
    }

    /** The grid's emoji and fancy entries (#970), which a tap commits their own way, not as a word. */
    private var pagesEmoji: Set<String> = emptySet()
    private var pagesFancy: Set<String> = emptySet()

    /**
     * A fancy form of the word picked off the grid (#970): it goes in where
     * the word was, and nothing is learned from it, since the styled letters
     * are not a word of any language.
     */
    private fun commitFancyCandidate(text: String) {
        vibrate()
        val ic = currentInputConnection ?: return
        lastGestureWord = null
        ic.commitText(text, 1)
        composing = StringBuilder()
        _uiState.update { it.copy(composingPreview = "", suggestions = emptyList(), octopus = emptyMap(), emojiSuggestions = emptyList()) }
        refreshSuggestions()
    }

    /**
     * Opens or closes the swipe-up popup of more words over the strip. It
     * offers the same deeper list the pages grid does, less the words already
     * on the strip, and only for the word the list was filled for. Closed by
     * the strip's gesture when the finger lifts, picked or not.
     */
    fun onMoreSuggestionsPopup(open: Boolean) {
        val state = _uiState.value
        if (!open) {
            if (state.moreSuggestions.isNotEmpty()) _uiState.update { it.copy(moreSuggestions = emptyList()) }
            return
        }
        if (state.composer.isConversion || state.panel != PanelMode.NONE) return
        val (forWord, words) = suggestionPages ?: return
        if (forWord != composing.toString()) return
        val shown = state.suggestions.toSet()
        val more = words.filter { it !in shown }.take(MORE_SUGGESTIONS_MAX)
        if (more.isEmpty()) return
        vibrate()
        _uiState.update { it.copy(moreSuggestions = more) }
    }

    /** A word lifted on in the swipe-up popup: the popup goes, and the pick is an ordinary strip pick. */
    fun onMoreSuggestionPicked(word: String) {
        if (_uiState.value.moreSuggestions.isNotEmpty()) {
            _uiState.update { it.copy(moreSuggestions = emptyList()) }
        }
        onSuggestionTapped(word)
    }

    /**
     * A conversion candidate tapped in the strip or the expanded grid. Resolved
     * by position rather than by text — see [Composer.consumedForIndex].
     */
    fun onCandidateTapped(candidate: String, index: Int) {
        // The pages grid's own "back to the keys" row (#385).
        if (index < 0 && candidate.isEmpty()) {
            onSuggestionPagesToggle(false)
            return
        }
        val ic = currentInputConnection ?: return
        val composer = _uiState.value.composer
        if (!composer.isConversion) {
            // A word picked from the pages grid (#385): the grid goes, and the
            // pick is an ordinary strip pick.
            if (_uiState.value.panel == PanelMode.CANDIDATES) {
                _uiState.update { it.copy(panel = PanelMode.NONE, expandedCandidates = emptyList()) }
            }
            when (candidate) {
                in pagesEmoji -> onEmojiSuggestionTapped(candidate)
                in pagesFancy -> commitFancyCandidate(candidate)
                else -> onSuggestionTapped(candidate)
            }
            return
        }
        // The same tick a word picked from the strip gets in onSuggestionTapped,
        // which a conversion pick never passes through (#710).
        vibrate()
        // The strip is filled off the main thread and can be a keystroke
        // behind the buffer. A position is only good for the list it came
        // from, so it is trusted while the buffer's own ranking still has this
        // candidate there, and the tap falls back to matching by text when it
        // does not.
        // English words sit among the conversions (#633), so a strip position
        // is the composer's own only once they are counted out. An English chip
        // was spelled by the whole reading, which is what a pick with no
        // position in the composer's list consumes.
        val extras = conversionExtras?.takeIf { it.typed == composing.toString() }
        val composerIndex = extras?.composerIndex(index) ?: index
        if (extras != null && candidate in extras.english && (composerIndex < 0 || index < 0)) {
            if (learningAllowed) suggestionEngine?.learnEnglishPick(candidate)
            commitConversionPrefix(ic, candidate)
            return
        }
        val current = composer.candidates(composing.toString(), CANDIDATE_GRID_LIMIT).getOrNull(composerIndex)
        commitConversionPrefix(ic, candidate, if (current == candidate) composerIndex else -1)
    }

    /**
     * A held conversion candidate's menu was answered (#580): show it earlier,
     * later, or never. The composer records it in the reading space its picks
     * live in, and the list is decoded again at once, so the answer shows on
     * the strip the user is looking at rather than at the next keystroke.
     *
     * Resolved the way a tap is ([onCandidateTapped]): a strip position is
     * only trusted while the buffer's own ranking still has this candidate
     * there. An English word among the conversions (#633) is not the
     * composer's to adjust; "never" puts it on the suggestion blacklist, which
     * is where English words are kept off the strip, and the other two do
     * nothing for it.
     */
    private fun onCandidateAdjust(candidate: String, index: Int, adjustment: CandidateAdjustment) {
        val state = _uiState.value
        val composer = state.composer
        val typed = composing.toString()
        if (!composer.isConversion || typed.isEmpty()) return
        val gridOpen = state.panel == PanelMode.CANDIDATES
        val extras = conversionExtras?.takeIf { it.typed == typed }
        val composerIndex = extras?.composerIndex(index) ?: index
        if (extras != null && candidate in extras.english && composerIndex < 0) {
            if (adjustment == CandidateAdjustment.BLOCK) onSuggestionHeld(candidate)
            return
        }
        val list = composer.candidates(typed, CANDIDATE_GRID_LIMIT)
        val at = composerIndex.takeIf { list.getOrNull(it) == candidate } ?: list.indexOf(candidate)
        if (at < 0) return
        vibrate()
        // 以词定字: one character of the word, for the whole word's reading.
        if (adjustment == CandidateAdjustment.FIRST_CHARACTER || adjustment == CandidateAdjustment.LAST_CHARACTER) {
            val ic = currentInputConnection ?: return
            if (candidate.codePointCount(0, candidate.length) < 2) return
            val piece = if (adjustment == CandidateAdjustment.FIRST_CHARACTER) {
                candidate.substring(0, candidate.offsetByCodePoints(0, 1))
            } else {
                candidate.substring(candidate.offsetByCodePoints(candidate.length, -1))
            }
            if (gridOpen) _uiState.update { it.copy(panel = PanelMode.NONE, expandedCandidates = emptyList()) }
            commitConversionPrefix(ic, candidate, at, piece)
            return
        }
        composer.adjustChoice(typed, at, adjustment)
        CjkLearning.store?.let { store -> serviceScope.launch(Dispatchers.IO) { store.save() } }
        refreshConversionCandidates(_uiState.value)
        if (gridOpen) {
            val grid = composer.candidates(typed, CANDIDATE_GRID_LIMIT)
            _uiState.update {
                it.copy(expandedCandidates = conversionExtras?.takeIf { e -> e.typed == typed }?.into(grid) ?: grid)
            }
        }
    }

    /**
     * The candidate strip's chevron: opens the overflow grid, or closes it. A
     * scrolling word strip has the same arrow (#890), which opens the grid of
     * words a swipe down opens.
     */
    fun onCandidatesExpand() {
        val state = _uiState.value
        if (state.panel == PanelMode.CANDIDATES) {
            _uiState.update { it.copy(panel = PanelMode.NONE, expandedCandidates = emptyList()) }
            return
        }
        if (!state.composer.isConversion) {
            onSuggestionPagesToggle(true)
            return
        }
        if (!state.composer.isConversion || composing.isEmpty()) return
        val typed = composing.toString()
        val grid = state.composer.candidates(typed, CANDIDATE_GRID_LIMIT)
        _uiState.update {
            it.copy(
                panel = PanelMode.CANDIDATES,
                // The same positions as the strip, English words and all, so a
                // pick from either resolves the same way.
                expandedCandidates = conversionExtras?.takeIf { e -> e.typed == typed }?.into(grid) ?: grid,
            )
        }
    }

    /**
     * The capitals a pick replacing [word] should take from it (#893), for
     * [caseLike]: the word itself, unless its capitals are only its own
     * spelling, a name's or an acronym's, which the keyboard knows it by.
     * Those say nothing about the word replacing it, so they pass on nothing,
     * or a leading capital where the word [opensSentence], which any word
     * standing there would wear. For the picks that cannot ask the shift a
     * word was written under: one at the caret, and the recent-words row's.
     */
    private fun spelledCaseModel(word: String, opensSentence: Boolean): String? {
        val lower = word.lowercase()
        if (lower == word) return word
        val spelling = suggestionEngine?.displayOf(lower) ?: return word
        if (spelling != word) return word
        return if (opensSentence) String(Character.toChars(word.codePointAt(0))) else null
    }

    /**
     * Whether the word whose first [headLength] characters stand before the
     * caret opens a sentence: the start of the field, or a sentence end or a
     * line break before it (#893).
     */
    private fun wordOpensSentence(ic: InputConnection, headLength: Int): Boolean {
        val before = ic.getTextBeforeCursor(headLength + SENTENCE_OPENING_LOOKBACK, 0)?.toString() ?: return false
        if (before.length < headLength) return false
        return WordContext.completedWordBefore(before.dropLast(headLength), SENTENCE_ENDERS) ==
            WordContext.SENTENCE_START
    }

    /**
     * Avro's remembered picks (Telegram group): see [SuggestionEngine.phoneticPicks].
     * Device-protected storage is not where learned words live, so before the
     * first unlock the picks stay in memory.
     */
    private val phoneticPickStore by lazy {
        com.wasimaster.wmkeyboard.core.prediction.PhoneticPickStore(
            if (userUnlocked) File(filesDir, "learning/phonetic_picks.tsv") else null,
        )
    }

    /**
     * Remembers [suggestion] as the reading of the word being typed on a
     * phonetic layout, when it was picked from the list by hand. Not an
     * English chip, and not while learning is paused, the same rules every
     * other learned thing keeps.
     */
    private fun notePhoneticPick(suggestion: String) {
        val state = _uiState.value
        val lang = state.composer.phoneticLanguage ?: return
        val typed = composing.toString()
        if (typed.isEmpty() || suggestion == typed || suggestion.all { it.code < 0x80 }) return
        if (!state.settings.learnFromTyping || state.secureField ||
            (state.incognitoOn && state.settings.incognitoPausesLearning)
        ) {
            return
        }
        if (!phoneticPickStore.put(lang, typed, suggestion)) return
        suggestionEngine?.phoneticPicks = phoneticPickStore.snapshot()
        serviceScope.launch(Dispatchers.IO) { phoneticPickStore.save() }
    }

    fun onSuggestionTapped(suggestion: String) {
        replacedGlideShape = null
        stopVoiceForManualInput()
        vibrate()
        notePhoneticPick(suggestion)
        val ic = currentInputConnection ?: return
        // Every path below edits by position: a delete counted back from the
        // caret, or a commit that means "here". Neither is measured from the
        // caret while the field holds a composing region —
        // `deleteSurroundingText` widens its span to swallow the region before
        // it counts, and `commitText` replaces the region rather than the
        // selection — so a region the keyboard is not tracking moves the edit
        // somewhere else entirely: the old word keeps the half the widened
        // delete missed, and the new one lands over whatever the region
        // covered (#267).
        //
        // An empty buffer means no region in the field is the keyboard's: an
        // app can arm one over text it was just handed (#113), and an editor
        // that restyles as you type can leave one of ours behind. So drop it
        // before anything below measures a thing — the same rule
        // [dropComposingForSelectionEdit] applies to every other positional
        // edit in the service. A live buffer keeps its region, which is the
        // one the ordinary pick is *supposed* to replace.
        if (composing.isEmpty()) ic.finishComposingText()
        // The two-thumb split chip (#832): only while the word it splits is
        // still the one open, or still the one the pause just typed.
        duetSplit?.takeIf { it.chip == suggestion }?.let { split ->
            duetSplit = null
            val live = when {
                split.committed -> composing.isEmpty() && lastGestureWord != null && stripReplacesGestureWord
                // The swipe Backspace took off a word begun with taps (#870):
                // what is left is the letters, no longer gestures.
                split.head == null && !duetWord.active -> composing.isNotEmpty()
                else -> duetWord.active
            }
            if (live) {
                splitOffLastSwipe(ic, split)
                return
            }
        }
        // A word picked off a Retype's strip (#791) goes in at the caret like
        // any other pick, below. One of the swipe's other readings teaches the
        // stroke what picking it right after the swipe would have.
        retypeOffer?.let { offer ->
            retypeOffer = null
            if (composing.isEmpty() && suggestion != offer.word && suggestion in offer.readings) {
                noteGlidePreference(rejected = offer.word, chosen = suggestion)
            }
        }
        // Email-field completion: no composing region backs the tapped address,
        // so the partial token the user typed is removed by hand before the full
        // address is committed. Not learned — an address is not a dictionary word,
        // and no trailing space, since an email is usually the whole field.
        if (emailFieldForceActive() && '@' in suggestion) {
            // A transliterating composer (Avro) composes even in email fields;
            // finish it so the token delete counts real committed text and no
            // stale buffer survives the commit below.
            if (composing.isNotEmpty()) {
                ic.finishComposingText()
                revision = null
                composing = StringBuilder()
            }
            val token = emailTokenBeforeCursor(ic)
            if (token.isNotEmpty()) ic.deleteSurroundingText(token.length, 0)
            ic.commitText(suggestion, 1)
            lastGestureWord = null
            lastRevertible = null
            clearSwapOffer()
            _uiState.update {
                it.copy(
                    composingPreview = "",
                    suggestions = emptyList(),
                    octopus = emptyMap(),
                    emojiSuggestions = emptyList(),
                )
            }
            return
        }
        // A remembered number (#431): no composing region backs the digits it
        // completes either, so they come out by hand. Re-read first, the same
        // as a caret word below: a chip that has outlived its digits does
        // nothing rather than land somewhere they no longer are. No space
        // after it, since what follows a number is as often a mark as a word.
        val digitRun = numberRun
        if (digitRun != null && composing.isEmpty() && (
                suggestion.length > digitRun.length && suggestion.startsWith(digitRun) ||
                    // The same digits said in Klingon words replace them the same way.
                    suggestion == KlingonNumbers.spell(digitRun)
                )
        ) {
            numberRun = null
            if (TypedNumbers.runBefore(ic.getTextBeforeCursor(NUMBER_RUN_LOOKBEHIND, 0)) != digitRun) return
            ic.beginBatchEdit()
            ic.deleteSurroundingText(digitRun.length, 0)
            ic.commitText(suggestion, 1)
            ic.endBatchEdit()
            lastGestureWord = null
            lastRevertible = null
            clearSwapOffer()
            _uiState.update {
                it.copy(suggestions = emptyList(), octopus = emptyMap(), emojiSuggestions = emptyList())
            }
            return
        }
        // A caret sitting inside a word: the pick replaces that word where it
        // is rather than landing at the caret and splitting it in two (#32).
        // No composing region backs it (see [caretWord]), so the span is spliced
        // by hand — and re-read first, since the chip may have outlived the word
        // it was about. When it has, the tap does nothing: the strip was talking
        // about text that is no longer there, and committing the word at the
        // caret instead would be a worse guess than none.
        caretWord?.let { caret ->
            // The word the strip is about is on the strip (#263), and it is
            // there for the hold, not the tap. Splicing it over itself would
            // be a real delete-and-commit — one the app sees in its undo
            // stack and its text watchers, and one that snaps the caret to the
            // word's end — to change nothing, and it would count as a pick
            // that teaches the word it was already spelling. Take the strip
            // down instead, the same as any other pick leaves it.
            if (suggestion == caret.word) {
                clearCaretWord()
                _uiState.update {
                    it.copy(suggestions = emptyList(), emojiSuggestions = emptyList(), octopus = emptyMap())
                }
                return
            }
            // Read before [clearCaretWord] takes it down with the word it is
            // about (#135).
            val search = glideSearchOffer
            clearCaretWord()
            // The word was selected rather than parked in (#413): the pick
            // goes in over the selection, which is what a commit does with
            // one, and the splice below — which reads around a collapsed
            // caret — would read the wrong text.
            if (caret.tail.isEmpty() && expectedSelEnd > expectedSelStart &&
                ic.getSelectedText(0)?.toString() == caret.word
            ) {
                val replacement = displayCaseForShift(
                    caseLike(
                        suggestion,
                        spelledCaseModel(caret.word, wordOpensSentence(ic, 0)),
                        _uiState.value.language.letterCaseIsSpelling,
                    ),
                    _uiState.value.shiftState,
                )
                val spacing = splicedPickSpacing(ic.getTextAfterCursor(1, 0)?.firstOrNull())
                ic.commitText(replacement + spacing.tail, spacing.caretOffset)
                armSplicedPickSpace(spacing)
                invalidateExpectedSelection()
                recordStat { onWordsCommitted(1, System.currentTimeMillis()) }
                consumeShift()
                revision = null
                val fix = Revision(caret.word, suggestion, caret.start + suggestion.length)
                suggestionEngine?.noteCommit(suggestion, _uiState.value.suggestions)
                learn(
                    suggestion,
                    reinforcement = 2,
                    caseTrusted = false,
                    origin = WordOrigin.PICK,
                    replaces = resolveRevision(fix),
                )
                lastRevertible = null
                clearSwapOffer()
                _uiState.update {
                    it.copy(suggestions = emptyList(), emojiSuggestions = emptyList(), octopus = emptyMap())
                }
                return
            }
            val head = caret.head
            val tail = caret.tail
            val wordStart = expectedSelStart - head.length
            // One past the word, for the space the pick earns after it.
            val afterWord = ic.getTextAfterCursor(tail.length + 1, 0)?.toString().orEmpty()
            val stillThere =
                ic.getTextBeforeCursor(head.length, 0)?.toString().orEmpty() == head &&
                    afterWord.startsWith(tail)
            if (!stillThere) {
                refreshSuggestions()
                return
            }
            // Cased like the chip the user is looking at, the same as a pick
            // that lands at the caret — and, under it, like the word being
            // replaced, whose capital the live shift state can no longer
            // account for (#212).
            val replacement =
                displayCaseForShift(
                    caseLike(
                        suggestion,
                        spelledCaseModel(caret.word, wordOpensSentence(ic, head.length)),
                        _uiState.value.language.letterCaseIsSpelling,
                    ),
                    _uiState.value.shiftState,
                )
            val spacing = splicedPickSpacing(afterWord.getOrNull(tail.length))
            ic.beginBatchEdit()
            ic.deleteSurroundingText(head.length, tail.length)
            ic.commitText(replacement + spacing.tail, spacing.caretOffset)
            ic.endBatchEdit()
            armSplicedPickSpace(spacing)
            invalidateExpectedSelection()
            recordStat { onWordsCommitted(1, System.currentTimeMillis()) }
            consumeShift()
            // Deliberately picked, so it is learned like any other pick — the
            // base word, never the shift-cased form, and spelled the way the
            // engine offered it. Re-armed from text already in the field, so
            // nobody knows where its capital came from: untrusted (#100).
            // The word under the caret, replaced whole from the strip, is an
            // exact fix of it; whatever was following it by hand is overtaken.
            revision = null
            // One of the glide's own rejected readings, taken while reading
            // the text back: the same preference a pick right after the swipe
            // teaches (#115).
            if (suggestion in glideReadings.readingsAt(caret.word, caret.start)) {
                noteGlidePreference(rejected = caret.word, chosen = suggestion)
                glideReadings.forget(caret.word, caret.start)
            } else if (search != null && search.start == caret.start &&
                WordKey.of(search.word) == WordKey.of(caret.word) && suggestion in search.offered
            ) {
                // The full search's own answer (#135). Parked where a
                // backspaced glide's stroke waits, so [learn] below runs the
                // same three learners on it: the hand model, the shape store
                // and the pair. The word was never swiped as this spelling, so
                // this is the only chance the stroke gets to be taught it.
                undoneGlide = UndoneGlide(search.stroke, caret.word, SystemClock.uptimeMillis())
                glideReadings.forget(caret.word, caret.start)
            }
            // The words behind this one moved by the difference in length.
            glideReadings.onReplaced(wordStart, wordStart + caret.word.length, replacement.length + spacing.tail.length)
            val fix = Revision(caret.word, suggestion, wordStart + suggestion.length)
            suggestionEngine?.noteCommit(suggestion, _uiState.value.suggestions)
            learn(
                suggestion,
                reinforcement = 2,
                caseTrusted = false,
                origin = WordOrigin.PICK,
                replaces = resolveRevision(fix),
            )
            lastRevertible = null
            clearSwapOffer()
            _uiState.update {
                it.copy(suggestions = emptyList(), emojiSuggestions = emptyList(), octopus = emptyMap())
            }
            return
        }
        // After a swipe, the alternates replace the committed gesture word —
        // together with the space the swipe typed after it, so the trailing
        // space below lands in the same place rather than after a gap. Only
        // when the strip really is showing that word's alternates: a word
        // picked off the keys leaves next-word predictions there (#175).
        val gestureWord = lastGestureWord
        // The word this pick is overwriting, if it is overwriting one. Kept for
        // the commit below, which inherits its capitals (#212).
        var replacedWord: String? = null
        if (composing.isEmpty() && gestureWord != null && stripReplacesGestureWord) {
            val len = glideCommitLength(ic, gestureWord)
            if (len > 0) {
                replacedWord = gestureWord
                ic.deleteSurroundingText(len, 0)
                // The bigram for the pick below must chain off the word
                // *before* the replaced one, not off the word being replaced.
                syncPreviousWordFromField(ic)
                // The decode the user just overruled is not evidence of
                // anything. Explicit rather than left to the caret rule: the
                // replacement lands at the same place the old word ended, so
                // no caret move says it happened.
                learningBuffer.drop(gestureWord)
                // The pick over it is the clearest preference there is,
                // remembered against the pair so the same stroke reads the
                // chosen word first next time (issue #52).
                if (lastGestureStroke != null && WordKey.of(suggestion) != WordKey.of(gestureWord)) {
                    noteGlidePreference(rejected = gestureWord, chosen = suggestion)
                }
                // The shape that read it that way is marked against, and the
                // stroke's shape goes on to the word picked instead, once the
                // pick below has queued it.
                lastGestureStroke?.shape?.let { glideShapes.reject(it.layoutKey, gestureWord, it.shape) }
                replacedGlideShape = lastGestureStroke?.shape
                // Nor of where the finger lands — but the word picked in its
                // place is, and the stroke is still here to measure it by.
                unlearnHand()
                lastGestureStroke?.let { learnHand(it.points, it.keys, it.keyWidthPx, suggestion) }
            }
        }
        // A pick off the strip the deep retry filled after an undo is a
        // preference for the pick over the undone word. The offer is tied to
        // the list it drew, so any other strip since makes it inert.
        glideRetryOffer?.let { offer ->
            glideRetryOffer = null
            if (offer.offered === _uiState.value.suggestions && suggestion in offer.offered) {
                noteGlidePreference(rejected = offer.rejected, chosen = suggestion)
                // The same correction as a pick off the ordinary strip, made a
                // backspace later, so it teaches the same three things (issue
                // #213). No [unlearnHand] first: the undo already retracted
                // what the rejected word taught, so this is a fresh
                // observation rather than a correction of a standing one.
                learnHand(offer.stroke.points, offer.stroke.keys, offer.stroke.keyWidthPx, suggestion)
                // Rides to the pick's settle the way a strip replacement's
                // does; [replacedGlideShape] is consumed after [learn] below.
                replacedGlideShape = offer.stroke.shape
            }
        }
        lastGestureStroke = null
        lastGestureWord = null
        lastRevertible = null
        clearSwapOffer()
        pendingWordSpace = false
        deferredWordSpace = false

        // An emoji picked from inline search replaces the ":query" buffer
        // outright: no trailing space (emoji rarely start a new word) and no
        // word learned from the query. The emoji itself counts as used, the
        // same as a closing colon (see onText) and a panel tap: it lands in
        // Recent and the emoji row, and learns its word→emoji bigram. The
        // space the opening colon took back belongs to the emoji here too.
        if (inlineEmojiQuery() != null) {
            val restored = if (emojiQueryAteSpace) " " else ""
            emojiQueryAteSpace = false
            ic.commitText(restored + suggestion, 1)
            learnEmoji(suggestion)
            recordEmojiUse(suggestion)
            revision = null
            composing = StringBuilder()
            _uiState.update {
                it.copy(composingPreview = "", suggestions = emptyList(), emojiSuggestions = emptyList(), octopus = emptyMap())
            }
            return
        }

        // Conversion IMEs (Chinese Pinyin, Japanese kana→kanji): the tapped chip
        // is a character choice for the current reading. Commit it with no
        // trailing space (CJK runs words together) and no learning, then clear the
        // reading buffer so the next syllable starts fresh.
        if (_uiState.value.composer.isConversion) {
            commitConversionPrefix(ic, suggestion)
            return
        }

        // Normally the pick lands at the end of the text and earns a trailing
        // space to start the next word. But a word resumed mid-sentence (the
        // caret moved back onto it) already has a space after it — appending
        // another would leave a double gap, so the pick steps the caret over
        // that one instead, and the next word starts after it rather than
        // running into this one (#508). The trailing space itself is opt-out
        // (A26): off commits the word bare and leaves the caret on it.
        // A shortcut that expands to a gap — a tab, an em space — ends in one
        // already, so it earns no space of its own on top (#552).
        // A word typed into the middle of another one (a kar put back into
        // কিঞ্চ|ত) is a piece of that word, and a space after it would split
        // the word in two (#986).
        val pickState = _uiState.value
        val after = ic.getTextAfterCursor(1, 0)
        val autoSpace = pickState.settings.suggestionStrip.autoSpaceAfterSuggestionFor(pickState.language.id) &&
            suggestion.lastOrNull()?.isWhitespace() != true &&
            !spendNoSpaceOnPick() &&
            !composingInsideWord(ic, pickState, after)
        val spaced = autoSpace && spaceToStepOver(after)
        // In front of a mark that closes up onto the word ("question⌶?"), the
        // space waits for a letter instead of landing between them (#679).
        val deferSpace = autoSpace && !spaced && markHugsCaretWord(after)
        val tail = if (autoSpace && !spaced && !deferSpace) " " else ""
        // Commit in the case the strip is showing: a shift held over the strip
        // capitalizes the word the user is about to pick, matching the chip.
        // Under that, the capitals of the word being replaced: a pick that
        // overwrites a committed word lands in a place whose case was decided
        // when that word was written, and the shift that decided it is long
        // since spent — auto-capitalize's above all (#212).
        noteScriptPick(suggestion)
        val committed = _uiState.value.let { state ->
            val cased = displayCaseForShift(
                caseLike(suggestion, replacedWord?.takeIf { gestureWordShifted }, state.language.letterCaseIsSpelling),
                state.shiftState,
            )
            // An English word picked on a layout with no case of its own opens
            // a sentence with a capital the way a committed one does.
            if (composing.isNotEmpty() && isLatinOnPhonetic(cased, state)) {
                sentenceCasedLatin(cased, composing.toString(), state)
            } else {
                cased
            }
        }
        ic.commitText(committed + tail, pickCaretOffset(spaced))
        // That space is the keyboard's, so a mark typed next takes it back and
        // hugs the word — "word:" and not "word :" (issue #34). Same one-shot a
        // glide's space gets, and it needs the same guard: without it the
        // commit's own selection echo reads as a caret move and disarms it
        // before the next keystroke can spend it.
        if (tail.isNotEmpty()) {
            pendingWordSpace = true
            armRevertGuard()
        } else if (deferSpace) {
            deferredWordSpace = true
            armRevertGuard()
        }
        // Whole words landed without being typed out; this also disarms the
        // half-typed word so the next separator cannot count it again. A pick
        // over a glided word is fixing the glide, not predicting or finishing
        // anything, so it counts as a word and nothing more.
        recordStat {
            val words = suggestion.split(' ').size
            val now = System.currentTimeMillis()
            if (replacedWord == null) {
                onWordsPicked(words, composing.length, committed.length, tail.isNotEmpty(), now)
            } else {
                onWordsCommitted(words, now)
            }
        }
        // A one-shot shift is spent by the pick, the same as by a typed letter.
        consumeShift()
        // A reading the glide that wrote this word had offered and lost with:
        // taking it now is the clearest statement there is about that stroke,
        // and it is the same preference a pick straight after the swipe teaches
        // (issue #52) — only made while proofreading instead (#115).
        resumedWord?.let { came ->
            if (suggestion in glideReadings.readingsAt(came, resumedWordStart)) {
                noteGlidePreference(rejected = came, chosen = suggestion)
                glideReadings.forget(came, resumedWordStart)
            }
        }
        // Deliberately picked from the strip — a stronger signal than a
        // word that merely got committed. Learn the base word, not the
        // shift-cased form, so caps lock never teaches "HELLO" to the lexicon.
        // A contact email is the exception: it is never learned, so it stays
        // memory-only and off the disk-backed personal dictionary even when
        // tapped from an ordinary text field.
        // The chip was cased to match what was typed, and at a sentence start
        // that capital is auto-capitalize's, not the user's — so the pick
        // teaches a spelling only when the typed word's capital was trusted
        // (#100). A pick with nothing typed (a next-word prediction) carries
        // no case evidence at all. A gap (#552) is not a word, and must not
        // stand in as the previous word for the next one's n-grams either.
        if ('@' !in suggestion && suggestion.isNotBlank()) {
            // A word the user came back to, then finished from the strip: the
            // pick is what the word became.
            val replaces = revision?.takeIf { it.mode == WordRevision.Mode.COMPOSING }?.let { r ->
                revision = null
                r.finish(suggestion)?.let { resolveRevision(it) }
            }
            learn(
                suggestion,
                reinforcement = 2,
                caseTrusted = composing.isNotEmpty() && composingCaseTrusted &&
                    typedCarriesCase(composing, suggestion),
                origin = WordOrigin.PICK,
                replaces = replaces,
                typed = composing.toString(),
                taps = composingTouchFrame(),
                keys = suggestionEngine?.touchModel,
            )
        }
        // A glide this pick replaced: its stroke's shape now belongs to the
        // word picked, and rides it to its settle the way it would have
        // ridden the reading (issue #52).
        replacedGlideShape?.let { learningBuffer.attachGlide(suggestion, it) }
        replacedGlideShape = null
        composing = StringBuilder()
        _uiState.update {
            it.copy(
                composingPreview = "",
                suggestions = emptyList(),
                emojiSuggestions = emptyList(),
                octopus = emptyMap(),
            )
        }
        maybeAutoCapitalize()
        refreshSuggestions()
    }

    /**
     * Where a picked word leaves the caret, as [InputConnection.commitText]'s
     * `newCursorPosition`: 1 is right after the word, 2 is one past it. A pick
     * landing in front of a space that is already there ([spaced]) takes the 2,
     * so the caret ends up after that space the way it would after one the pick
     * had typed itself. Left in front of it, the next word ran straight into the
     * picked one: "auto⌶ space", pick "automatic", type on, and the field read
     * "automaticword space" (#508). The space is the user's own, so nothing arms
     * the take-back a typed one gets — a comma next lands after it.
     */
    private fun pickCaretOffset(spaced: Boolean): Int = if (spaced) 2 else 1

    /**
     * Whether [after], read from behind the caret, starts with a space the
     * keyboard may step over rather than type again ([stepOverFollowingSpace],
     * and a pick from the strip).
     *
     * Never in a web editor (#760). What a page reports after the caret is not
     * always text the user wrote: Gmail's compose body puts its Smart Compose
     * suggestion there as a grey, non-editable span (" back to you"), and the
     * connection hands it over as plain characters, so its leading space read
     * as one to step over. The forward delete, or the caret sent past it, then
     * landed in that span and Gmail took the keyboard down. A page cannot say
     * which characters are real, so there the space is typed as it is, the way
     * HeliBoard types it everywhere.
     */
    private fun spaceToStepOver(after: CharSequence?): Boolean = !isWebEditField() && spacedAfterCaret(after)

    /**
     * Whether the word being composed sits inside another one: a word
     * character on both sides of what the field shows for it, [after] being
     * what follows the caret. Read only for a pick, never per keystroke.
     */
    private fun composingInsideWord(ic: InputConnection, state: KeyboardUiState, after: CharSequence?): Boolean {
        if (composing.isEmpty() || after.isNullOrEmpty() || !continuesWordAhead(after[0])) return false
        val shown = composedPreview(state, composing.toString()).length
        val before = ic.getTextBeforeCursor(shown + 1, 0) ?: return false
        return before.length > shown && WordContext.isWordChar(before[before.length - shown - 1])
    }

    /** How a pick that replaces a word where it stands is spaced; see [splicedPickSpacing]. */
    private class PickSpacing(val tail: String, val caretOffset: Int, val deferred: Boolean)

    /**
     * The space a pick earns when it replaces a word where it stands (a caret
     * parked in or on the word, or the word highlighted), from [next], the
     * character that follows the word. The same three outcomes a pick at the
     * end of the text has: over a space already there the caret steps past it,
     * in front of a mark that closes up onto the word the space waits for a
     * letter ([deferredWordSpace]), and anywhere else one is typed. Before
     * this a word replaced in the middle of a sentence left the caret on it,
     * so the next word ran into it, and in a browser's address bar, where
     * every pick over a word came this way, auto-space never happened at all
     * (#508, #662, #679).
     */
    private fun splicedPickSpacing(next: Char?): PickSpacing {
        val state = _uiState.value
        if (!state.settings.suggestionStrip.autoSpaceAfterSuggestionFor(state.language.id) || spendNoSpaceOnPick()) {
            return PickSpacing("", 1, false)
        }
        val after = next?.toString()
        return when {
            spaceToStepOver(after) -> PickSpacing("", pickCaretOffset(spaced = true), false)
            markHugsCaretWord(after) -> PickSpacing("", 1, true)
            else -> PickSpacing(" ", 1, false)
        }
    }

    /** Arms the one-shot that goes with the space [spacing] typed or held back. */
    private fun armSplicedPickSpace(spacing: PickSpacing) {
        when {
            spacing.tail.isNotEmpty() -> {
                pendingWordSpace = true
                armRevertGuard()
            }
            spacing.deferred -> {
                deferredWordSpace = true
                armRevertGuard()
            }
        }
    }

    /**
     * A word taken off the keys (discussion #102), by a flick up or by a tap on
     * the word itself.
     *
     * Its own path rather than a detour through [onSuggestionTapped], and the
     * reason is a bug rather than a preference: that one carries a branch for
     * "the strip is replacing the word a glide just committed", which fires
     * whenever nothing is composing and a gesture word is behind the caret. Glide
     * "hello", then flick `w` for "world", and it would delete "hello " and put
     * "world" where it stood. Its caret-word branch is wrong here for the same
     * kind of reason. What an octopus pick means is narrower than either: finish
     * this word, here.
     *
     * The composing region is replaced rather than appended to, which comes free
     * — [InputConnection.commitText] replaces a live composing region by
     * contract, so a completion and a correction are both written correctly and
     * a pick with nothing composing simply inserts.
     *
     * [via] separates the flick from the tap for the statistics alone, so the two
     * gestures can be judged apart.
     */
    fun onOctopusPick(word: String, via: OctopusSource) {
        val ic = currentInputConnection ?: return
        if (word.isEmpty()) return
        stopVoiceForManualInput()
        vibrate()
        val state = _uiState.value
        val autoSpace = state.settings.suggestionStrip.autoSpaceAfterSuggestionFor(state.language.id) &&
            !spendNoSpaceOnPick()
        val after = ic.getTextAfterCursor(1, 0)
        val spaced = autoSpace && spaceToStepOver(after)
        val deferSpace = autoSpace && !spaced && markHugsCaretWord(after)
        val tail = if (autoSpace && !spaced && !deferSpace) " " else ""
        val committed = displayCaseForShift(word, state.shiftState)
        ic.commitText(committed + tail, pickCaretOffset(spaced))
        if (tail.isNotEmpty()) {
            // The keyboard's own space, so a mark typed next takes it back and
            // hugs the word (#34); the guard keeps the commit's selection echo
            // from reading as a caret move and disarming it first.
            pendingWordSpace = true
            armRevertGuard()
        } else if (deferSpace) {
            deferredWordSpace = true
            armRevertGuard()
        }
        recordStat {
            onWordsPicked(
                word.split(' ').size, composing.length, committed.length, tail.isNotEmpty(),
                System.currentTimeMillis(),
            )
        }
        consumeShift()
        // Deliberately chosen, so it carries a pick's weight. The base word, not
        // the shift-cased form, and a capital that auto-capitalize put there is
        // not evidence of a spelling (#100).
        learn(
            word,
            reinforcement = 2,
            caseTrusted = composing.isNotEmpty() && composingCaseTrusted &&
                typedCarriesCase(composing, word),
            origin = WordOrigin.OCTOPUS,
            typed = composing.toString(),
            taps = composingTouchFrame(),
            keys = suggestionEngine?.touchModel,
        )
        octopusPicks.merge(via, 1, Int::plus)
        // One backspace takes the whole pick back, word and space together,
        // through the machinery a glide's own commit already uses. With no
        // stroke attached, the parts of that path which re-decode a swipe sit
        // out, which is right: there is no swipe to re-read. The strip is
        // *not* told to replace the pick on a tap: the refresh below fills it
        // with what may follow the word, not with what it might have been, so
        // a tap there lands after the pick (#175).
        lastGestureWord = word
        stripReplacesGestureWord = false
        lastGestureStroke = null
        composing = StringBuilder()
        _uiState.update {
            it.copy(
                composingPreview = "",
                suggestions = emptyList(),
                emojiSuggestions = emptyList(),
                octopus = emptyMap(),
            )
        }
        maybeAutoCapitalize()
        refreshSuggestions()
    }

    /**
     * Spacebar drag: move the cursor one position left (-1) or right (+1). The
     * volume keys land here too when they are set to move the caret.
     *
     * With selection mode on — or a shift the user put up, lock included — the
     * step carries shift and drags the selection out instead, which is the
     * pairing the mode exists for: one finger holds the mode (or a tap left it
     * on) and the other scrubs the spacebar.
     */
    fun onCursorMove(delta: Int) {
        // A keyboard-owned field's own caret, asked before the field's is: a
        // scrub meant for a search query or a spelling draft used to walk the
        // app's caret behind the keyboard (#204, #161).
        if (_uiState.value.captureTarget() != null) {
            caretStepFeedback()
            onCaptureCaretMove(delta, extend = _uiState.value.caretExtendsSelection)
            return
        }
        val ic = currentInputConnection ?: return
        caretStepFeedback()
        // Mark the scrub so the caret's landing spot doesn't resume-compose the
        // word under it mid-drag (this same commit would then churn it).
        lastCaretScrubMs = SystemClock.uptimeMillis()
        endCompositionForCaretKey(ic)
        lastGestureWord = null
        // Under the setting a step sets the selection instead of pressing an
        // arrow (#505), a shifted one included: a search box reads Shift+Right
        // as a step through its dropdown just as it reads Right (#613).
        if (_uiState.value.settings.textEditing.spaceCursorDirect) {
            val moved = if (_uiState.value.caretExtendsSelection) {
                extendSelectionDirectly(ic, delta)
            } else {
                moveCaretDirectly(ic, delta)
            }
            if (moved) return
        }
        sendEditorKey(
            if (delta < 0) KeyEvent.KEYCODE_DPAD_LEFT else KeyEvent.KEYCODE_DPAD_RIGHT,
            shift = _uiState.value.caretExtendsSelection,
        )
    }

    /**
     * Moves the caret one character the way [delta] points by setting the
     * selection (#505). False when the field has not said where its caret is,
     * so the arrow key path runs instead. Steps over a whole surrogate pair,
     * so an emoji is one step and the caret never lands inside one; at either
     * end of the text the step is spent on nothing, as an arrow's would be.
     */
    private fun moveCaretDirectly(ic: InputConnection, delta: Int): Boolean {
        if (expectedSelStart < 0 || expectedSelStart != expectedSelEnd) return false
        val from = expectedSelStart
        val step = if (delta < 0) {
            val before = ic.getTextBeforeCursor(2, 0) ?: return false
            if (before.isEmpty()) return true
            if (before.length == 2 && Character.isSurrogatePair(before[0], before[1])) 2 else 1
        } else {
            val after = ic.getTextAfterCursor(2, 0) ?: return false
            if (after.isEmpty()) return true
            if (after.length == 2 && Character.isSurrogatePair(after[0], after[1])) 2 else 1
        }
        val to = (if (delta < 0) from - step else from + step).coerceAtLeast(0)
        if (!ic.setSelection(to, to)) return false
        expectedSelStart = to
        expectedSelEnd = to
        return true
    }

    /**
     * The shifted form of [moveCaretDirectly] (#613): the selection's moving
     * end goes one character the way [delta] points and its anchor stays put.
     * False when the field has not said where its selection is, or the
     * selection is too long to read the character beside its moving end, so
     * the Shift+arrow path runs instead.
     */
    private fun extendSelectionDirectly(ic: InputConnection, delta: Int): Boolean {
        val start = expectedSelStart
        val end = expectedSelEnd
        if (start < 0 || end < start) return false
        val anchor = anchorFor(start, end, delta)
        val focus = if (anchor == start) end else start
        // The character or two the moving end steps over: outside the
        // selection when it grows, its own first or last when it shrinks.
        val near = when {
            delta < 0 && focus == start -> ic.getTextBeforeCursor(2, 0)
            delta > 0 && focus == end -> ic.getTextAfterCursor(2, 0)
            end - start > DIRECT_SELECTION_READ_CAP -> null
            else -> ic.getSelectedText(0)?.let { if (delta < 0) it.takeLast(2) else it.take(2) }
        } ?: return false
        if (near.isEmpty()) return true
        val step = if (near.length == 2 && Character.isSurrogatePair(near[0], near[1])) 2 else 1
        val to = (if (delta < 0) focus - step else focus + step).coerceAtLeast(0)
        return setStretchedSelection(ic, anchor, to)
    }

    /**
     * Shift+Up or Shift+Down in a one-line field (#613): the moving end goes to
     * the start or the end of the text, which is what a desktop text box does
     * with them. The arrow itself is no line move there; a search box steps
     * into its dropdown and a plain field hands focus on, leaving nothing
     * selected. False unless [isOneLineField], where the arrow follows the
     * app's own wrapping, and when the field has not said where its selection
     * is.
     */
    private fun extendSelectionToEdgeDirectly(ic: InputConnection, up: Boolean): Boolean {
        if (!isOneLineField()) return false
        val start = expectedSelStart
        val end = expectedSelEnd
        if (start < 0 || end < start) return false
        val anchor = anchorFor(start, end, if (up) -1 else 1)
        val to = if (up) {
            val before = ic.getTextBeforeCursor(DIRECT_CARET_EDGE_REACH, 0) ?: return false
            if (before.hasLineBreak()) return false
            (start - before.length).coerceAtLeast(0)
        } else {
            val after = ic.getTextAfterCursor(DIRECT_CARET_EDGE_REACH, 0) ?: return false
            if (after.hasLineBreak()) return false
            end + after.length
        }
        return setStretchedSelection(ic, anchor, to)
    }

    /**
     * The field is a one-line box, where Up and Down are no line moves: it
     * flies no multi-line flag and declares an Enter action of its own, as a
     * TextView, a search box and a web page's `<input>` all do. The flag alone
     * was not enough (#800): Firefox's textarea and APKTool M's editor leave it
     * off, and Shift+Down there selected to the end of the text instead of
     * down a line. A multi-line box declares no action, or flies
     * IME_FLAG_NO_ENTER_ACTION over the one it declared. The callers also
     * stand down at a line break in the text they read, for an editor that
     * declares an action anyway.
     */
    private fun isOneLineField(): Boolean {
        val info = currentInputEditorInfo ?: return false
        if (info.inputType and InputType.TYPE_TEXT_FLAG_MULTI_LINE != 0) return false
        if (info.imeOptions and EditorInfo.IME_FLAG_NO_ENTER_ACTION != 0) return false
        val action = info.imeOptions and EditorInfo.IME_MASK_ACTION
        return action != EditorInfo.IME_ACTION_NONE && action != EditorInfo.IME_ACTION_UNSPECIFIED
    }

    private fun CharSequence.hasLineBreak(): Boolean = any { it == '\n' || it == '\r' || it == '\u2028' }

    /**
     * The panel's Start of text and End of text keys (#785), as a selection
     * change rather than Ctrl+Home / Ctrl+End. Those key events went nowhere
     * in many apps: a field that binds Ctrl shortcuts of its own, or one whose
     * key listener knows no whole-text move, ate them and the caret stayed
     * put. With [selecting] the moving end goes to the edge and the anchor
     * stays. The start is offset 0 in any field; the end is read after the
     * caret, and past [DIRECT_CARET_EDGE_REACH] from the extracted text. False
     * when the field has not said where its selection is or refuses the
     * change, and the caller sends the key events instead.
     */
    private fun moveToTextEdgeDirectly(ic: InputConnection, toEnd: Boolean, selecting: Boolean): Boolean {
        val start = expectedSelStart
        val end = expectedSelEnd
        if (start < 0 || end < start) return false
        val to = if (toEnd) {
            val after = ic.getTextAfterCursor(DIRECT_CARET_EDGE_REACH, 0) ?: return false
            if (after.length < DIRECT_CARET_EDGE_REACH) {
                end + after.length
            } else {
                val et = ic.getExtractedText(ExtractedTextRequest(), 0)
                val text = et?.text ?: return false
                maxOf(et.startOffset + text.length, end + after.length)
            }
        } else {
            0
        }
        if (!selecting) {
            if (start == to && end == to) return true
            return setStretchedSelection(ic, to, to)
        }
        noteSelectionAnchor()
        return setStretchedSelection(ic, anchorFor(start, end, if (toEnd) 1 else -1), to)
    }

    /**
     * Which end of the selection [start]..[end] stays put for a step the way
     * [delta] points: the one [selectionAnchor] kept, or, for a selection the
     * keyboard did not make, the end away from the step, so the first step
     * grows it.
     */
    private fun anchorFor(start: Int, end: Int, delta: Int): Int = when {
        start == end -> start
        selectionAnchor == start || selectionAnchor == end -> selectionAnchor
        delta < 0 -> end
        else -> start
    }

    /**
     * Sets the selection from [anchor] to [focus] in that order, so an editor
     * that keeps a direction keeps this one, and remembers both ends.
     */
    private fun setStretchedSelection(ic: InputConnection, anchor: Int, focus: Int): Boolean {
        if (!ic.setSelection(anchor, focus)) return false
        expectedSelStart = minOf(anchor, focus)
        expectedSelEnd = maxOf(anchor, focus)
        selectionAnchor = anchor
        return true
    }

    /**
     * Before a Shift+arrow goes out: a collapsed caret is where the selection
     * about to grow is anchored (#613). A selection already standing keeps
     * whatever anchor was noted for it.
     */
    private fun noteSelectionAnchor() {
        if (expectedSelStart >= 0 && expectedSelStart == expectedSelEnd) selectionAnchor = expectedSelStart
    }

    /**
     * Ends the composition ahead of a caret key, the spacebar scrub's steps
     * included. A word the caret only landed in, re-armed as composing and not
     * typed into since, is finished where it stands: committing it wrote the
     * same text back over itself before the key went out, and a web editor
     * that rebuilds its text from such a commit (CodeMirror, in ViolentMonkey)
     * dropped or shuffled characters under a run of Shift+arrows (#613).
     * Anything typed into the word is committed as before.
     *
     * With nothing in the buffer the region is finished anyway: an editor
     * that restyles its text can keep a span the keyboard has already let go
     * of, and a region left behind a moving caret is where the next commit
     * lands, replacing the word the drag passed through (#365).
     */
    private fun endCompositionForCaretKey(ic: InputConnection) {
        val resumed = resumedWord
        if (composing.isNotEmpty() && resumed != null &&
            _uiState.value.composer.resumeBuffer(resumed) == composing.toString()
        ) {
            dropComposingForSelectionEdit(ic)
            return
        }
        if (!commitComposing(ic, autocorrect = false)) ic.finishComposingText()
    }

    /**
     * The feedback for one step of the caret under a spacebar drag or a volume
     * key. The vibration has a switch of its own (#466): a drag across a line
     * is dozens of steps, and a buzz for each is what some people turn the
     * whole of haptics off to be rid of. The key sound is not part of that.
     */
    private fun caretStepFeedback() {
        if (_uiState.value.settings.haptics.onCursorMove) vibrate() else playKeySound()
    }

    /**
     * 2-D spacebar touchpad: move the cursor one line up (-1) or down (+1).
     * Mirrors [onCursorMove] but on the vertical axis, selection mode and a held
     * shift included.
     */
    fun onCursorMoveVertical(delta: Int) {
        // A one-line buffer: up is its start, down its end.
        if (_uiState.value.captureTarget() != null) {
            caretStepFeedback()
            onCaptureCaretToEdge(end = delta >= 0, extend = _uiState.value.caretExtendsSelection)
            return
        }
        val ic = currentInputConnection ?: return
        caretStepFeedback()
        lastCaretScrubMs = SystemClock.uptimeMillis()
        endCompositionForCaretKey(ic)
        lastGestureWord = null
        if (_uiState.value.settings.textEditing.spaceCursorDirect &&
            !_uiState.value.caretExtendsSelection && moveCaretToEdgeDirectly(ic, delta)
        ) {
            return
        }
        sendEditorKey(
            if (delta < 0) KeyEvent.KEYCODE_DPAD_UP else KeyEvent.KEYCODE_DPAD_DOWN,
            shift = _uiState.value.caretExtendsSelection,
        )
    }

    /**
     * The vertical half of [moveCaretDirectly] (#505), for a one-line field
     * only: up puts the caret at the start of the text, down at its end, with a
     * selection change. An up or down arrow in a one-line field is not a line
     * move at all; a search box takes it into its dropdown, and a plain field
     * hands focus to the view above or below. False unless [isOneLineField],
     * where the arrow is what follows the app's own line wrapping, and when
     * the field has not said where its caret is.
     */
    private fun moveCaretToEdgeDirectly(ic: InputConnection, delta: Int): Boolean {
        if (!isOneLineField()) return false
        if (expectedSelStart < 0 || expectedSelStart != expectedSelEnd) return false
        val to = if (delta < 0) {
            val before = ic.getTextBeforeCursor(DIRECT_CARET_EDGE_REACH, 0) ?: return false
            if (before.hasLineBreak()) return false
            (expectedSelStart - before.length).coerceAtLeast(0)
        } else {
            val after = ic.getTextAfterCursor(DIRECT_CARET_EDGE_REACH, 0) ?: return false
            if (after.hasLineBreak()) return false
            expectedSelStart + after.length
        }
        if (to == expectedSelStart) return true
        if (!ic.setSelection(to, to)) return false
        expectedSelStart = to
        expectedSelEnd = to
        return true
    }

    // ---- gesture typing ----

    /**
     * The letter grid for this layout, rebuilt only when the grid itself
     * changes. The UI hands the same key list back for every preview within a
     * stroke, so the equality check below is an identity check in the common
     * case.
     */
    @Synchronized
    private fun keyMapFor(keys: List<KeyCenter>, keyWidthPx: Float): GlideKeyMap {
        // The hand model moves the keys under the decoder (issue #52). Its
        // version is part of the cache key: every kept glide moves the grid.
        val hand = keyOffsets.takeIf { _uiState.value.settings.gesture.learnSwipeStyle && !it.isEmpty() }
        val version = hand?.version ?: -1
        val cached = cachedKeyMap
        if (cached != null && cachedKeyMapWidth == keyWidthPx && cachedKeyMapKeys == keys &&
            cachedKeyMapHand === hand && cachedKeyMapHandVersion == version
        ) {
            return cached
        }
        val centers = hand?.shifted(keys, keyWidthPx) ?: keys
        return GlideKeyMap.of(centers, keyWidthPx).also {
            cachedKeyMap = it
            cachedKeyMapKeys = keys
            cachedKeyMapWidth = keyWidthPx
            cachedKeyMapHand = hand
            cachedKeyMapHandVersion = version
        }
    }

    /** [keyMapFor] without the hand model: the grid as drawn. */
    @Synchronized
    private fun rawKeyMapFor(keys: List<KeyCenter>, keyWidthPx: Float): GlideKeyMap {
        val cached = cachedRawKeyMap
        if (cached != null && cachedRawKeyMapWidth == keyWidthPx && cachedRawKeyMapKeys == keys) {
            return cached
        }
        return GlideKeyMap.of(keys, keyWidthPx).also {
            cachedRawKeyMap = it
            cachedRawKeyMapKeys = keys
            cachedRawKeyMapWidth = keyWidthPx
        }
    }

    /**
     * Teaches [keyOffsets] where the finger went for each letter of [word],
     * the glide the user just kept — measured against the grid as drawn, so
     * a consistent miss reads as the same offset whatever the decoder was
     * already correcting for. Returns what changed, for an undo to retract.
     * Null when the setting is off, or the word cannot be laid on this grid
     * at all (a romanized stroke's Bengali answer, a restored apostrophe).
     */
    private fun learnHand(
        points: List<GesturePoint>,
        keys: List<KeyCenter>,
        keyWidthPx: Float,
        word: String,
    ): KeyOffsets.Adjustment? {
        if (!_uiState.value.settings.gesture.learnSwipeStyle) return null
        val observations = handObservations(points, keys, keyWidthPx, word) ?: return null
        return keyOffsets.observe(observations)
    }

    /** Where the finger went for each letter of [word] along [points], against the grid as drawn. */
    private fun handObservations(
        points: List<GesturePoint>,
        keys: List<KeyCenter>,
        keyWidthPx: Float,
        word: String,
    ): List<KeyOffsets.Observation>? {
        val engine = suggestionEngine ?: return null
        val raw = rawKeyMapFor(keys, keyWidthPx)
        val aligned = engine.alignGlide(word, points, raw, keyWidthPx) ?: return null
        return List(aligned.size) { i ->
            val k = aligned.keys[i]
            KeyOffsets.Observation(raw.keyX[k], raw.keyY[k], aligned.x[i], aligned.y[i])
        }
    }

    /** The gestures a two-thumb [word] was read off, as [commitComposing] found them. */
    private class DuetGestures(
        val tokens: List<GlideToken>,
        val keys: List<KeyCenter>,
        val keyWidthPx: Float,
        val complete: Boolean,
    )

    /**
     * What a two-thumb [word] teaches the gesture models, the way a kept
     * glide does (#741): each swipe teaches the hand model where the finger
     * went for the part of the word it drew, all of it as one adjustment an
     * undo takes back, and a word that is one swipe and nothing else teaches
     * the shape store too, riding the word to its settle as a glide's shape
     * does. A swipe that is only part of the word files no shape: the store
     * keeps shapes of whole words, and a piece of one would take a slot.
     *
     * The taps teach the touch model nothing. They are real touches, but they
     * do not line up one to one with the word's letters (one tap can be a
     * doubled letter, a swipe sits between two of them), and the touch model
     * learns by pairing each tap with the letter it typed.
     *
     * Nothing for a word nobody spelled: laid over letters the decoder only
     * fell back to, the swipes would teach the hand to miss.
     */
    private fun learnDuetGestures(word: String, gestures: DuetGestures) {
        if (!gestures.complete || !swipeStyleLearning) return
        val swipes = gestures.tokens.filterIsInstance<GlideToken.Swipe>()
        if (swipes.isEmpty()) return
        val keys = gestures.keys
        val keyWidthPx = gestures.keyWidthPx
        val lone = gestures.tokens.size == 1
        serviceScope.launch {
            val (hand, shape) = withContext(Dispatchers.Default) {
                if (lone) {
                    learnGlideStroke(swipes[0].points, keys, keyWidthPx, word, drawn = null)
                } else {
                    val map = rawKeyMapFor(keys, keyWidthPx)
                    val observations = swipes.flatMap { swipe ->
                        duetSwipeSpan(word, swipe.points.first(), swipe.points.last(), map, keyWidthPx)
                            ?.let { handObservations(swipe.points, keys, keyWidthPx, it) }
                            .orEmpty()
                    }
                    observations.takeIf { it.isNotEmpty() }?.let { keyOffsets.observe(it) } to null
                }
            }
            duetLearned?.invoke(word, hand, shape)
            lastHandAdjustment = hand
            shape?.let { learningBuffer.attachGlide(word, it) }
        }
    }

    /** Test seam: what each two-thumb word taught the hand model and the shape store (#741). */
    internal var duetLearned: ((String, KeyOffsets.Adjustment?, GlideShapeSample?) -> Unit)? = null

    /**
     * What a kept glide teaches: the hand model, on the spot, and the shape
     * for [word]'s settle. [drawn] is the part of [word] the stroke really
     * covered when the word was finished early, and null otherwise (#262).
     *
     * An early finish teaches the hand only the letters the finger drew. Laying
     * the whole word over a stroke that stopped at its fourth letter forces the
     * rest onto keys the finger never reached, and every one of them near
     * enough to its key reads as a miss of this hand. It teaches no shape at
     * all: the store keeps shapes of whole words, which a prefix stroke is not,
     * and each one filed would take a slot from a shape that is.
     */
    private fun learnGlideStroke(
        points: List<GesturePoint>,
        keys: List<KeyCenter>,
        keyWidthPx: Float,
        word: String,
        drawn: String?,
    ): Pair<KeyOffsets.Adjustment?, GlideShapeSample?> =
        if (drawn != null) {
            learnHand(points, keys, keyWidthPx, drawn) to null
        } else {
            learnHand(points, keys, keyWidthPx, word) to sampleGlideShape(points, keys, keyWidthPx, word)
        }

    /** Takes back what the last kept glide taught the hand model, if anything. */
    private fun unlearnHand() {
        lastHandAdjustment?.let { keyOffsets.retract(it) }
        lastHandAdjustment = null
    }

    /** Whether a glide's outcome may be remembered: the learning gate, and the swipe-style switch. */
    private val swipeStyleLearning: Boolean
        get() = learningAllowed && _uiState.value.settings.gesture.learnSwipeStyle

    /** The user took [chosen] in place of [rejected], the word a stroke was read as (issue #52). */
    private fun noteGlidePreference(rejected: String, chosen: String) {
        if (swipeStyleLearning) glideOutcomes.observeAlternative(rejected, chosen)
        glideCheckup.correct(rejected, chosen)
        learningBuffer.drop(rejected)
        pushRecentWord(chosen)
        previousWord = chosen
    }

    /** The user backspaced [word] the moment a glide committed it. */
    private fun noteGlideUndone(word: String) {
        if (swipeStyleLearning) glideOutcomes.observeImmediateUndo(word)
        glideCheckup.correct(word, null)
    }

    /**
     * The glide check-up's measurement (issue #966 §5.5): the stroke that
     * just typed [word] decoded again under every candidate weight, through
     * the same sources, blacklist and context as the decode that typed it,
     * and the one word each came back with handed to [glideCheckup] beside
     * [current], what the weights in force read, and the five-axis profile
     * of the stroke. Off the keyboard's thread, after the word is in the
     * field; a handful of decodes a swipe, and only while the check-up
     * screen's switch is on. No stroke is kept.
     */
    private fun measureGlideForCheckup(
        points: List<GesturePoint>,
        keys: List<KeyCenter>,
        keyWidthPx: Float,
        word: String,
        current: String,
        context: Pair<List<String?>, List<String>>,
    ) {
        val engine = suggestionEngine ?: return
        val checkup = glideCheckup
        val (previous, recent) = context
        serviceScope.launch(Dispatchers.Default) {
            val base = engine.glideTuningInForce
            val size = engine.glideVocabularySize()
            val candidates = GlideCheckup.candidates(base, size)
            if (candidates.isEmpty()) return@launch
            val map = keyMapFor(keys, keyWidthPx)
            val shapes = shapeSourceFor(keys, keyWidthPx)
            val under = HashMap<String, String>(candidates.size * 2)
            for (candidate in candidates) {
                val read = engine.glide(
                    path = points,
                    keys = map,
                    keyWidth = keyWidthPx,
                    limit = 1,
                    previousWord = previous.getOrNull(0),
                    previousWord2 = previous.getOrNull(1),
                    previousWord3 = previous.getOrNull(2),
                    recentWords = recent,
                    shapes = shapes,
                    tuning = candidate.applyTo(base),
                ).firstOrNull()?.word ?: continue
                under[candidate.id] = read
            }
            checkup.observe(
                fingerprint = GlideCheckup.fingerprintOf(base, size),
                candidates = candidates,
                currents = GlideCheckup.currents(base),
                committed = word,
                current = current,
                under = under,
                sample = GlideCheckup.profileOf(points, keys, keyWidthPx, word),
            )
        }
    }

    /**
     * One decision from the check-up screen (`GestureSettings.checkupDecision`):
     * `nonce:KIND:payload`. APPLY starts the confirmation window, DECLINE
     * buries the candidate, SETTLE closes the window. Saved at once, since
     * the screen reads the file back.
     */
    private fun actOnCheckupDecision(decision: String) {
        val parts = decision.split(':', limit = 3)
        if (parts.size < 2) return
        val payload = parts.getOrNull(2).orEmpty()
        when (parts[1]) {
            "APPLY" -> {
                val (candidate, from) = payload.split('|', limit = 2).let { it[0] to it.getOrElse(1) { "" } }
                if (candidate.isNotEmpty()) glideCheckup.applied(candidate, from)
            }
            "DECLINE" -> if (payload.isNotEmpty()) glideCheckup.decline(payload)
            "SETTLE" -> glideCheckup.settle()
            else -> return
        }
        serviceScope.launch(persistDispatcher) { glideCheckup.save() }
    }

    /**
     * [word] was just committed over a glide the user had backspaced away, so
     * the stroke waiting in [undoneGlide] has found its answer (issue #213):
     * the hand model learns where the finger went for this word's letters, the
     * stroke's shape rides [word] to its settle, and the pair is remembered.
     *
     * Exactly what a strip pick over an un-backspaced glide does, arriving by
     * the other route. Consumed at most once and only inside
     * [UNDONE_GLIDE_WINDOW_MS] of the undo: past that the user has moved on and
     * the next word they type is their next word, not this one retried.
     *
     * The same word again is not an answer — it is the reading they rejected —
     * and neither is a word whose first and last letters the stroke's ends
     * came nowhere near ([GlideStroke.endsFit], #805). That gate covers all
     * three learners: deleting "the" and typing "a" is an edit of the
     * sentence, and letting "a" claim the stroke taught the shape store and
     * the pair that a swipe for "the" meant "a".
     */
    private fun claimUndoneGlide(word: String) {
        val undone = undoneGlide ?: return
        undoneGlide = null
        if (SystemClock.uptimeMillis() - undone.atMs > UNDONE_GLIDE_WINDOW_MS) return
        if (WordKey.of(word) == WordKey.of(undone.rejected)) return
        val stroke = undone.stroke
        if (!stroke.endsFit(word, rawKeyMapFor(stroke.keys, stroke.keyWidthPx))) return
        lastHandAdjustment = learnHand(stroke.points, stroke.keys, stroke.keyWidthPx, word)
        stroke.shape?.let { learningBuffer.attachGlide(word, it) }
        noteGlidePreference(rejected = undone.rejected, chosen = word)
    }

    private var cachedShapeKeyKeys: List<KeyCenter>? = null
    private var cachedShapeKeyWidth = 0f
    private var cachedShapeKey = 0L

    /**
     * The shape store's key for [keys] as drawn. Cached the way the grids
     * are, since the UI hands the same list back for every preview of a
     * stroke.
     */
    @Synchronized
    private fun shapeKeyFor(keys: List<KeyCenter>, keyWidthPx: Float): Long {
        if (cachedShapeKeyKeys == keys && cachedShapeKeyWidth == keyWidthPx) return cachedShapeKey
        return GlideKeyMap.fingerprint(keys, keyWidthPx).also {
            cachedShapeKeyKeys = keys
            cachedShapeKeyWidth = keyWidthPx
            cachedShapeKey = it
        }
    }

    /** The user's own shapes for this grid, for the decoder; null while the setting is off or nothing is learned. */
    private fun shapeSourceFor(keys: List<KeyCenter>, keyWidthPx: Float): GlideShapeSource? {
        if (!_uiState.value.settings.gesture.learnSwipeStyle) return null
        return glideShapes.forLayout(shapeKeyFor(keys, keyWidthPx))
    }

    /**
     * [points] as a shape the learning buffer can carry to [word]'s settle,
     * or null when nothing should be learned: the setting or the learning
     * gate off, or a word the grid as drawn cannot spell (a romanized
     * stroke's Bengali answer, a restored apostrophe), whose shape could
     * never be matched.
     */
    private fun sampleGlideShape(
        points: List<GesturePoint>,
        keys: List<KeyCenter>,
        keyWidthPx: Float,
        word: String,
    ): GlideShapeSample? {
        if (!swipeStyleLearning) return null
        val engine = suggestionEngine ?: return null
        val raw = rawKeyMapFor(keys, keyWidthPx)
        var at = 0
        while (at < word.length) {
            val codePoint = word.codePointAt(at)
            at += Character.charCount(codePoint)
            if (raw.keyIndex(codePoint) < 0) return null
        }
        val shape = engine.glideShapeOf(points, keyWidthPx) ?: return null
        return GlideShapeSample(shapeKeyFor(keys, keyWidthPx), shape)
    }

    /** The glide that committed a word settles with it: its shape is now how this user draws the word. */
    private fun learnGlideShape(entry: LearningBuffer.Entry) {
        val sample = entry.glideShape ?: return
        if (!_uiState.value.settings.gesture.learnSwipeStyle) return
        glideShapes.learn(sample, entry.word)
    }


    /**
     * A decoded stroke: the words it could be, and whether the top two are a
     * close call under the user's sensitivity tier.
     */
    private class GlideReading(
        val words: List<String>,
        val closeCall: Boolean,
        /**
         * Whether the learned words alone produced the word this reading
         * leads with — the measurement the sandbox ladder promotes on. Null
         * when the stroke was not decoded under
         * [GlideSandboxPolicy.PREFER_LEARNED] and so measured nothing.
         *
         * Carried on the reading rather than kept in a field because a stroke
         * publishes a preview for every touch move: a field would be
         * overwritten by previews of the stroke still being drawn, and the
         * ladder would count each of them.
         */
        val sandboxAnswered: Boolean? = null,
        /**
         * Each word's decoder score, in nats, aligned with [words] — what the
         * preview's steadiness gate compares a challenger against.
         *
         * Only ever compared *within* one reading. Scores from two readings of
         * the same stroke are not comparable: a longer stroke has more samples
         * to explain and every candidate's cost grows with it, so "the leader
         * beat last frame's leader" says nothing while "the leader beats the
         * word on screen, right now, on this evidence" says exactly the right
         * thing.
         */
        val scores: List<Double> = emptyList(),
        /**
         * The words here that carry letters the stroke has not drawn: the
         * decoder guessing where the finger was going, kept apart from the
         * readings that spell themselves out (see [GlideBeam.Candidate.ahead]).
         * Each maps to the letters the stroke *did* draw, in the decoder's
         * spelling, which is what the strip fills from when a lift takes the
         * guess (#168). Empty whenever the user has the feature off, since
         * nothing then survives [admitLookAhead].
         */
        val guesses: Map<String, String> = emptyMap(),
        /**
         * The guesses the decoder is *sure* of: those beating the best
         * ordinary reading by [GlideLookAhead.CONFIDENT]'s margin, whichever
         * tier the user is on. On [GlideLookAhead.EAGER] that is a second,
         * stricter level for the strip to draw differently; on
         * [GlideLookAhead.CONFIDENT] every admitted guess is already in it.
         */
        val sure: Set<String> = emptySet(),
    ) {
        /** [word]'s score in this reading, or null when it is not in it. */
        fun scoreOf(word: String): Double? {
            val at = words.indexOfFirst { it.equals(word, ignoreCase = true) }
            return if (at >= 0) scores.getOrNull(at) else null
        }

        /** This reading with [word] moved to the front, for a gate that held it. */
        fun leading(word: String): GlideReading {
            val at = words.indexOfFirst { it.equals(word, ignoreCase = true) }
            if (at <= 0) return this
            val order = words.toMutableList().apply { add(0, removeAt(at)) }
            val rescored = scores.toMutableList().apply { if (at < size) add(0, removeAt(at)) }
            return GlideReading(order, closeCall, sandboxAnswered, rescored, guesses, sure)
        }

        companion object {
            val NONE = GlideReading(emptyList(), false)
        }
    }

    /**
     * How many words one stroke may come back with.
     *
     * The strip's own slot count, so a user who asked for six alternates gets
     * six rather than the four a hardcoded default used to give them (#54).
     * Floored at [GestureSettings.pickerChoices] so narrowing the strip to two
     * or three slots cannot starve the ambiguity picker, which shows its own
     * words under the fingertip and does not share the strip's width.
     *
     * Free: the decoder searches to `GLIDE_RERANK_POOL` whatever the caller
     * asks for, so this only decides how many survive the rerank.
     */
    private fun glideCandidateLimit(): Int {
        val settings = _uiState.value.settings
        return maxOf(settings.suggestionStrip.slotCount, settings.gesture.pickerChoices)
    }

    /**
     * One stroke's worth of evidence for the sandbox ladder, and the offer it
     * may have earned.
     *
     * Only ever called under [GlideSandboxPolicy.PREFER_LEARNED], which is the
     * only rung that measures anything, and only on [GlideSandbox.AUTOMATIC]
     * does an earned rung become an offer — someone who picked a policy by
     * hand has said what they want and should not be asked to change it.
     */
    private fun noteSandboxOutcome(answered: Boolean) {
        glideSandbox.observe(answered)
        if (_uiState.value.settings.gesture.sandbox != GlideSandbox.AUTOMATIC) return
        if (sandboxOfferPolicy != null) return
        val earned = glideSandbox.pending(userLexicon.wordCount()) ?: return
        sandboxOfferPolicy = earned
        _uiState.update { it.copy(sandboxOffer = earned) }
    }

    /**
     * The lexicon has grown enough to earn the first rung, which no stroke
     * measures — [noteSandboxOutcome] only runs once the ladder is already on
     * the measuring rung. Asked where the strip is refreshed, so the chip
     * appears at a word boundary rather than mid-stroke.
     */
    private fun maybeOfferFirstSandboxRung() {
        if (_uiState.value.settings.gesture.sandbox != GlideSandbox.AUTOMATIC) return
        if (sandboxOfferPolicy != null || _uiState.value.sandboxOffer != null) return
        if (glideSandbox.accepted() != GlideSandboxPolicy.OFF) return
        val earned = glideSandbox.pending(userLexicon.wordCount()) ?: return
        sandboxOfferPolicy = earned
        _uiState.update { it.copy(sandboxOffer = earned) }
    }

    /** Takes the sandbox chip down, whether or not it was answered. */
    private fun clearSandboxOffer() {
        sandboxOfferPolicy = null
        if (_uiState.value.sandboxOffer != null) _uiState.update { it.copy(sandboxOffer = null) }
    }

    /**
     * The language to put the missing-word-list chip up for, or null: glide
     * typing is off, so nobody is swiping; the state has moved on to another
     * language; or [languageId] has been told once already (#219).
     */
    private fun glideWordListOffer(languageId: String): LanguageDef? {
        val state = _uiState.value
        if (!state.settings.gestureTyping || state.language.id != languageId) return null
        // Slide-to-select (#658) types single keys; no word list is involved.
        if (state.settings.letterSwipeAction == LetterSwipeAction.SELECT_KEY) return null
        // Nothing to download for a language whose list is in the APK, so the
        // chip would open a page with nothing on it to press. Its words being
        // missing all the same means the list was switched off ("Only my word
        // lists") or failed to inflate, and a download answers neither
        // (discussion #364). Same for a language the user did switch off: a
        // list downloaded while that switch is off is not read either.
        if (languageId in bundledListLanguages) return null
        if (!shippedDictionaryEnabled(languageId)) return null
        if (!glideWordListNoticed.add(languageId)) return null
        return state.language
    }

    /**
     * The same chip for a phonetic layout running on its rules alone (#239).
     * Glide has nothing to do with it, so the glide switch is not asked; the
     * once-per-language memory is shared but keyed apart, since a user told
     * about glide has not been told about this.
     */
    private fun phoneticWordListOffer(languageId: String): LanguageDef? {
        val state = _uiState.value
        if (state.language.id != languageId) return null
        if (!glideWordListNoticed.add("phonetic:$languageId")) return null
        return state.language
    }

    /** The chip was tapped: the language's own page, where its list downloads. */
    private fun acceptGlideWordListOffer() {
        val language = _uiState.value.glideWordListOffer ?: return
        clearGlideWordListOffer()
        openRoute("language/${language.id}")
    }

    /** Takes the missing-word-list chip down, answered or overtaken by typing. */
    private fun clearGlideWordListOffer() {
        if (_uiState.value.glideWordListOffer != null) _uiState.update { it.copy(glideWordListOffer = null) }
    }

    /** "Yes": the ladder climbs, and the next stroke decodes under the new rung. */
    private fun acceptSandboxOffer() {
        val policy = sandboxOfferPolicy ?: return
        vibrate()
        clearSandboxOffer()
        glideSandbox.accept(policy)
        glideSandbox.save()
    }

    /** "No": the rung is never offered again. */
    private fun declineSandboxOffer() {
        val policy = sandboxOfferPolicy ?: return
        vibrate()
        clearSandboxOffer()
        glideSandbox.decline(policy)
        glideSandbox.save()
    }

    /**
     * The sandbox policy in force right now: the user's setting, with
     * [GlideSandbox.AUTOMATIC] resolving to whichever rung the ladder has
     * been allowed to reach.
     */
    private fun sandboxPolicy(): GlideSandboxPolicy =
        when (_uiState.value.settings.gesture.sandbox) {
            GlideSandbox.NORMAL -> GlideSandboxPolicy.OFF
            GlideSandbox.PREFER_LEARNED -> GlideSandboxPolicy.PREFER_LEARNED
            GlideSandbox.LEARNED_ONLY -> GlideSandboxPolicy.LEARNED_ONLY
            GlideSandbox.AUTOMATIC -> glideSandbox.accepted()
        }

    /** The sources a sandbox decode is restricted to: the words this user has written. */
    private val LEARNED_TIER = setOf(FuzzyBeamSearch.Tier.USER)

    /**
     * FUTO Swipe adapted to the decoder's model interface, and the loaded
     * model it wraps: a model deleted and downloaded again is a new one.
     */
    @Volatile
    private var futoGlide: Pair<FutoSwipeModel, NeuralGlide>? = null

    /**
     * Google's gesture library engine, made once the library has loaded into
     * this process; it keeps its dictionaries under noBackupFilesDir.
     */
    @Volatile
    private var latinImeGlide: LatinImeGlide? = null

    /** Whether this process has started loading the library; [LatinImeLibrary.load] runs once either way. */
    @Volatile
    private var latinImeLoading = false

    /**
     * The glide engine for the next decode, or null for the built-in one.
     * FUTO Swipe when the user picked it, the language is English, and the
     * models and the ExecuTorch runtime are on the phone; whether the layout
     * is QWERTY is the engine's own question, asked of each stroke's key map.
     * Google's gesture library when the user picked it and imported it, in
     * any language: it loads here, on the first stroke after a keyboard
     * start, and answers null for every stroke until its dictionary for the
     * language is built.
     */
    private fun glideEngineNow(): GlideDecoder? {
        val state = _uiState.value
        return when (state.settings.gesture.engine) {
            GlideEngine.BUILT_IN -> null
            GlideEngine.FUTO_SWIPE -> if (state.language.isEnglish) futoGlideNow() else null
            GlideEngine.GOOGLE_LIBRARY -> latinImeGlideNow(state.language.id)
        }
    }

    private fun latinImeGlideNow(languageId: String): GlideDecoder? {
        // The library and its dictionaries live in credential-encrypted
        // storage, which does not exist before the first unlock.
        if (!LatinImeLibrary.supported || !userUnlocked) return null
        if (!LatinImeLibrary.isLoaded) {
            // Hashing and loading the file takes a moment: off the stroke,
            // which the built-in decoder reads meanwhile.
            if (!latinImeLoading) {
                latinImeLoading = true
                serviceScope.launch(Dispatchers.IO) { LatinImeLibrary.load(noBackupFilesDir) }
            }
            return null
        }
        val glide = latinImeGlide ?: LatinImeGlide(noBackupFilesDir).also { latinImeGlide = it }
        glide.language = LatinImeGlide.aospLocale(languageId)
        return glide
    }

    private fun futoGlideNow(): NeuralGlide? {
        val model = FutoSwipe.model(filesDir) ?: return null
        futoGlide?.let { (loaded, glide) -> if (loaded === model) return glide }
        val glide = NeuralGlide(
            object : SwipeModel {
                override fun emissions(features: FloatArray): SwipeEmissions? =
                    model.emissions(features)?.let { SwipeEmissions(it.size / SwipeEmissions.CLASSES, it) }
            },
        )
        futoGlide = model to glide
        return glide
    }

    /** Decodes one stroke against the active language's word sources; see [decodeStroke]. */
    private fun glideDecode(
        points: List<GesturePoint>,
        keys: List<KeyCenter>,
        keyWidthPx: Float,
        guessAhead: Boolean = true,
        openHead: Int = 0,
        openTail: Int = 0,
    ): GlideReading = trace(ImeTrace.GLIDE_DECODE) { decodeStroke(points, keys, keyWidthPx, guessAhead, openHead, openTail) }

    private fun decodeStroke(
        points: List<GesturePoint>,
        keys: List<KeyCenter>,
        keyWidthPx: Float,
        /**
         * Whether this decode may answer with a word the stroke has not
         * finished spelling. True wherever the stroke *ends where the finger
         * lifted*: every preview, the decode behind a single glide, and the
         * last segment of a chained one. False for a chained stroke's earlier
         * segments, which end where the finger turned into the space bar, so
         * the word really was drawn to its last letter and a completion would
         * be guessing over evidence.
         */
        guessAhead: Boolean = true,
        /**
         * How many of the stroke's first and last samples are its walk from
         * or to the spacebar (#968): a chained stroke's segments end and
         * start at the bar's edge, not on a key, and the decoder is told so
         * rather than anchoring the word's first or last letter to whatever
         * bottom-row key the walk passed. 0 for a stroke that began and
         * ended on keys. See [GlideStroke.openRun].
         */
        openHead: Int = 0,
        openTail: Int = 0,
    ): GlideReading {
        val engine = suggestionEngine ?: return GlideReading.NONE
        engine.externalGlide = glideEngineNow()
        val policy = sandboxPolicy()
        val gesture = _uiState.value.settings.gesture
        // The lift decodes exactly what the previews decoded (#121). This used
        // to run without a look-ahead, on the reasoning that a finished stroke
        // has no reason to invent letters. But the whole point of the feature
        // is that the stroke is *not* finished: the user lifts part way through
        // a long word. A guess was therefore never among the candidates the
        // lift ranked, [GlidePreviewGate.commit] could not find the word it had
        // been holding on screen, and the lift fell back to the best ordinary
        // reading. The preview promised "dictionary" and the finger typed
        // something else, identically on both tiers, which is what made the two
        // look like one setting.
        //
        // Asked of the tier as well as of the stroke, so the prefix walk is not
        // paid for by everyone: with the feature off every completion would be
        // thrown away again by [admitLookAhead] a few lines below, and that is
        // the default.
        val lookAhead = if (guessAhead && gesture.lookAhead != GlideLookAhead.OFF) {
            glideCandidateLimit()
        } else {
            0
        }
        fun decode(tiers: Set<FuzzyBeamSearch.Tier>?, guessing: Int = lookAhead) = engine.glide(
            path = points,
            keys = keyMapFor(keys, keyWidthPx),
            keyWidth = keyWidthPx,
            limit = glideCandidateLimit(),
            previousWord = previousWord,
            previousWord2 = previousWord2,
            previousWord3 = previousWord3,
            recentWords = recentWords.toList(),
            shapes = shapeSourceFor(keys, keyWidthPx),
            tiers = tiers,
            lookAhead = guessing,
            openHead = openHead,
            openTail = openTail,
        )

        // Under LEARNED_ONLY the learned words are the whole search; under
        // PREFER_LEARNED they are a second, much smaller one run beside it.
        val learned = if (policy == GlideSandboxPolicy.OFF) {
            emptyList()
        } else {
            decode(LEARNED_TIER)
        }
        val decoded = when (policy) {
            GlideSandboxPolicy.LEARNED_ONLY -> learned
            GlideSandboxPolicy.OFF -> decode(null)
            GlideSandboxPolicy.PREFER_LEARNED -> {
                // The dictionary reads a stroke; it does not finish one. A
                // guess is only ever one of the learned words here, because
                // that is where guessing is worth anything — about twice as
                // accurate out of one person's vocabulary as out of a
                // dictionary (`GlideLookAheadEvalTest`) — and because the
                // dictionary's guesses were how a stroke that missed the
                // last letter of a learned word came back as some rare word
                // that happened to start where the finger stopped (#167).
                val full = decode(null, guessing = 0)
                // Only a learned *reading* may win the sandbox comparison, and
                // a learned guess that does not win it joins the full decode
                // instead of replacing it — see GlideGuessGate.preferLearned
                // for why a guess wins that comparison by construction (#317).
                GlideGuessGate.preferLearned(learned, full)
            }
        }
        if (decoded.isEmpty()) return GlideReading.NONE
        val kept = admitLookAhead(decoded, gesture.lookAhead)
        if (kept.isEmpty()) return GlideReading.NONE
        // What the ladder counts: whether the learned words alone produced the
        // word this stroke is about to put in. Asked of the list the gate left
        // standing, not of the one it was handed — a learned guess the user's
        // confidence tier throws out was never going to serve this stroke, and
        // counting it would promote the ladder on strokes the sandbox lost.
        val answered = if (policy == GlideSandboxPolicy.PREFER_LEARNED) {
            learned.firstOrNull()?.word.equals(kept.firstOrNull()?.word, ignoreCase = true)
        } else {
            null
        }
        val words = kept.map { restoreApostrophe(it.word) ?: it.word }
        val (offered, offeredScores) = offerApostrophes(words, kept.map { it.score })
        val declared = leadContraction(declareApostrophe(offered, points, keys, keyWidthPx))
        // Scores follow the words through every rewrite. An offered
        // contraction carries the score of the reading it was offered behind,
        // and `declareApostrophe` can put a spelling in front that the decoder
        // never ranked — "it's" read off a stroke that spelled "its" — and
        // that word stands exactly where the leader stood, so it inherits the
        // leader's score.
        val byWord = offered.zip(offeredScores).toMap()
        val leaderScore = kept.first().score
        // Which of the surviving words are guesses, and which of those the
        // decoder is sure of. Measured here against this decode's own best
        // ordinary reading, the only comparison the scores support, and carried
        // as words rather than positions because the steadiness gate reorders
        // the list before anything draws it. Best-scoring rather than
        // first-listed for the same reason the gate above says so: the context
        // rerank has already moved the front of this list (#317).
        val bestRead = kept.filter { it.ahead == 0 }.maxOfOrNull { it.score }
        val guesses = HashMap<String, String>()
        val sure = HashSet<String>()
        words.forEachIndexed { i, word ->
            if (kept[i].ahead == 0) return@forEachIndexed
            // The drawn letters come off the decoder's own spelling, before
            // any apostrophe was put back: that is the spelling the tries
            // are walked in.
            guesses[word] = kept[i].word.dropLast(kept[i].ahead)
            if (bestRead == null ||
                kept[i].score - bestRead >= GlideLookAhead.CONFIDENT.margin
            ) {
                sure += word
            }
        }
        return GlideReading(
            words = declared,
            closeCall = gesture.ambiguityPicker &&
                SuggestionEngine.glideIsAmbiguous(kept, gesture.pickerSensitivity.margin),
            sandboxAnswered = answered,
            scores = declared.map { byWord[it] ?: leaderScore },
            guesses = guesses,
            sure = sure,
        )
    }

    /**
     * [decoded] with the decoder's guesses — candidates carrying letters the
     * stroke has not drawn — kept only where they clear the user's confidence
     * tier, and dropped entirely when the tier is off.
     *
     * The measuring itself is [GlideGuessGate.admit], beside the sandbox half
     * of the same seam; this is the tier's translation into the nats that gate
     * speaks.
     */
    private fun admitLookAhead(
        decoded: List<GlideBeam.Candidate>,
        tier: GlideLookAhead,
    ): List<GlideBeam.Candidate> =
        GlideGuessGate.admit(decoded, if (tier == GlideLookAhead.OFF) null else tier.margin)

    /**
     * The deep search behind a glide undo (issue #52): [stroke] decoded again
     * with the vocabulary cap off and a wider pool, [rejected] — the word the
     * user just took back — removed, and the rest put on the strip for a tap.
     *
     * Runs as [suggestionJob], not [gestureJob], on purpose: the next keystroke
     * cancels [suggestionJob] and refreshes the strip for the letters being
     * typed, which is exactly what should happen to a list the user has moved
     * past. A glide starting meanwhile bumps [gestureGeneration] and the result
     * is dropped on landing rather than put over the new stroke's words.
     */
    private fun glideDeepRetry(stroke: GlideStroke, rejected: String) {
        val engine = suggestionEngine ?: return
        val generation = gestureGeneration.get()
        val slots = _uiState.value.settings.suggestionStrip.slotCount
        suggestionJob?.cancel()
        suggestionJob = serviceScope.launch {
            val offered = deepGlideWords(engine, stroke, rejected, slots)
            if (generation != gestureGeneration.get()) return@launch
            if (composing.isNotEmpty()) return@launch
            if (offered.isEmpty()) return@launch
            glideRetryOffer = GlideRetryOffer(rejected, offered, stroke)
            _uiState.update { it.copy(suggestions = offered) }
        }
    }

    /**
     * [stroke] read against everything: the vocabulary cap off, the sandbox's
     * word-source gate off with it, and the deep pool instead of the ordinary
     * one. [rejected] — the word the stroke was read as — is dropped, and the
     * rest are the strip, longest odds included.
     *
     * The one decode both doors to a full search go through: the undo right
     * after a swipe ([glideDeepRetry]) and the caret coming back to the word
     * later ([searchAllWordsForCaretWord]).
     */
    private suspend fun deepGlideWords(
        engine: SuggestionEngine,
        stroke: GlideStroke,
        rejected: String,
        slots: Int,
    ): List<String> = withContext(Dispatchers.Default) {
        engine.externalGlide = glideEngineNow()
        engine.glide(
            path = stroke.points,
            keys = keyMapFor(stroke.keys, stroke.keyWidthPx),
            keyWidth = stroke.keyWidthPx,
            // One over the strip, since the rejected word is in the list
            // it comes back with and leaves a slot when it goes.
            limit = slots + 1,
            previousWord = previousWord,
            previousWord2 = previousWord2,
            previousWord3 = previousWord3,
            recentWords = recentWords.toList(),
            deep = true,
            shapes = shapeSourceFor(stroke.keys, stroke.keyWidthPx),
        ).map { restoreApostrophe(it.word) ?: it.word }
            .filterNot { it.equals(rejected, ignoreCase = true) }
            .take(slots)
    }

    /**
     * The word the caret is inside, when a swipe wrote it and that swipe's
     * path is still kept; null when the word was tapped, or was swiped too
     * long ago to still be in [glideReadings].
     *
     * The path is the only part of a swipe the text cannot answer for: the
     * letters standing in the field are the ones the decoder chose, not the
     * ones the finger drew (#135).
     */
    private fun caretStrokeWord(): String? {
        val caret = caretWord ?: return null
        return caret.word.takeIf { glideReadings.strokeAt(caret.word, caret.start) != null }
    }

    /**
     * Read the swipe that wrote the word under the caret again, against every
     * word list there is (#135).
     *
     * This is the manual search behind "only my words". A sandbox that cannot
     * see a word cannot offer it, so a swipe for a word the user has never
     * written comes out as the nearest word they have — and by the time they
     * notice, the strip is answering about the letters standing in the field,
     * which are not the ones they drew. Asking here puts the stroke back in
     * front of the whole dictionary, once, for the one word being proofread.
     *
     * Deliberately asked for rather than automatic: the deep decode is the
     * slow, noisy one the cap and the sandbox exist to avoid, and running it
     * on every swiped word the caret touched would undo the setting it is
     * meant to rescue.
     */
    private fun searchAllWordsForCaretWord(word: String) {
        val engine = suggestionEngine ?: return
        val caret = caretWord ?: return
        // The menu can outlive the word it was opened over.
        if (WordKey.of(caret.word) != WordKey.of(word)) return
        val stroke = glideReadings.strokeAt(caret.word, caret.start) ?: return
        val rejected = caret.word
        val start = caret.start
        val generation = gestureGeneration.get()
        val slots = _uiState.value.settings.suggestionStrip.slotCount
        suggestionJob?.cancel()
        suggestionJob = serviceScope.launch {
            val offered = deepGlideWords(engine, stroke, rejected, slots)
            if (generation != gestureGeneration.get()) return@launch
            if (composing.isNotEmpty()) return@launch
            // The caret left the word while the search ran: its answer is
            // about text nobody is reading any more.
            if (caretWord?.start != start) return@launch
            if (offered.isEmpty()) return@launch
            glideSearchOffer = GlideSearchOffer(rejected, start, stroke, offered)
            _uiState.update { it.copy(suggestions = offered, glideSearchChip = null) }
        }
    }

    /**
     * The other half of the apostrophe key: a stroke that went through it spells
     * a contraction even when the word list holds only the plain form.
     *
     * With the key on the grid the decoder can read "it's" straight off the trie,
     * and where the list has the entry that is what happens and this does
     * nothing. Most word lists do not have it. So when the finger demonstrably
     * passed over the apostrophe key and the best reading came back without one,
     * the declared spelling is put in front — and the plain one is kept right
     * behind it on the strip, because a rewrite the user can't undo in one tap is
     * worse than no rewrite.
     *
     * English only, like [Apostrophes] itself. Every other language reaches the
     * apostrophe the honest way, through its own word list.
     */
    private fun declareApostrophe(
        words: List<String>,
        points: List<GesturePoint>,
        keys: List<KeyCenter>,
        keyWidthPx: Float,
    ): List<String> {
        val state = _uiState.value
        if (state.settings.gesture.apostropheKey == GlideApostropheKey.OFF) return words
        if (!state.language.isEnglish) return words
        val top = words.firstOrNull() ?: return words
        if (top.contains('\'') || top.contains('’')) return words
        if (!crossedApostrophe(points, keys, keyWidthPx)) return words
        val declared = Apostrophes.fixExplicit(top) ?: return words
        return buildList(words.size + 1) {
            add(declared)
            addAll(words.filterNot { it == declared })
        }
    }

    /**
     * Whether [points] passed over the key the glide grid has put the apostrophe
     * on. Only asked once the setting is on, so the `'` entry in [keys] is that
     * key and not the long-press alternate a layout may also hide one behind.
     *
     * A half-key radius, and never the first or last sample: a word starting or
     * ending on the punctuation key is a stroke that merely began there, and the
     * words this can rewrite are all drawn on the letter rows, well away from the
     * bottom row the comma and full stop sit on.
     */
    private fun crossedApostrophe(
        points: List<GesturePoint>,
        keys: List<KeyCenter>,
        keyWidthPx: Float,
    ): Boolean {
        if (keyWidthPx <= 0f || points.size < 3) return false
        val center = keys.firstOrNull { it.codePoint == '\''.code } ?: return false
        val reach = keyWidthPx * APOSTROPHE_CROSS_WIDTHS
        for (i in 1 until points.size - 1) {
            val dx = points[i].x - center.x
            val dy = points[i].y - center.y
            if (dx * dx + dy * dy <= reach * reach) return true
        }
        return false
    }

    /**
     * [words] led by the contraction their leader may stand for, where the word
     * before says which: `hell` drawn to start a sentence is "He'll" (#949).
     * The bare word stays right behind it, so the strip still offers it.
     */
    private fun leadContraction(words: List<String>): List<String> {
        val state = _uiState.value
        if (!state.settings.autoText.apostrophe || !state.allowsTypingIntelligence) return words
        if (!state.language.isEnglish) return words
        val top = words.firstOrNull() ?: return words
        val fixed = Apostrophes.leadsAfter(top, previousWord) ?: return words
        return buildList(words.size + 1) {
            add(fixed)
            add(top)
            addAll(words.drop(1).filterNot { it.equals(fixed, ignoreCase = true) })
        }
    }

    /**
     * "dont" swiped is "don't" committed, on the same terms as "dont" typed.
     *
     * The letters layer has no apostrophe key, so a contraction can only ever
     * be *drawn* without one — which makes this less of a correction than a
     * transcription. Deliberately applied here rather than inside the engine's
     * own decode: the setting lives at this level, and the offline harness
     * decodes through the engine, where a word coming back spelled differently
     * from the one the corpus drew would read as a miss.
     */
    private fun restoreApostrophe(word: String): String? {
        val state = _uiState.value
        if (!state.settings.autoText.apostrophe || !state.allowsTypingIntelligence) return null
        return suggestionEngine?.elide(word)
    }

    /**
     * [words] with the apostrophe spelling each one may also have been drawn
     * as right behind it: "id" swiped offers "I'd", as "id" typed does
     * (#384). The strip's half of [restoreApostrophe], for a spelling that is
     * a word of its own and so is committed as drawn.
     *
     * Behind every reading rather than only the leader's, because the same
     * argument holds for each: a contraction can only be drawn without its
     * apostrophe. [scores] are aligned with [words] and stay so; an offer
     * takes the score of the reading it was read off, and never leads one,
     * so neither the lift nor the preview's steadiness gate can type it.
     */
    private fun offerApostrophes(words: List<String>, scores: List<Double>): Pair<List<String>, List<Double>> {
        val state = _uiState.value
        if (!state.settings.autoText.apostrophe || !state.allowsTypingIntelligence) return words to scores
        val engine = suggestionEngine ?: return words to scores
        val seen = words.mapTo(HashSet()) { it.lowercase() }
        val offered = ArrayList<String>(words.size)
        val offeredScores = ArrayList<Double>(scores.size)
        words.forEachIndexed { i, word ->
            offered += word
            scores.getOrNull(i)?.let { offeredScores += it }
            val offer = engine.apostropheOffer(word) ?: return@forEachIndexed
            if (!seen.add(offer.lowercase())) return@forEachIndexed
            offered += offer
            scores.getOrNull(i)?.let { offeredScores += it }
        }
        return offered to offeredScores
    }

    /**
     * A quick flick up off a key that is carrying a word: commit that word and
     * tell the caller the stroke is spoken for.
     *
     * The key is found by nearest centre rather than by a radius, so "the key I
     * started on" has exactly one answer. Several entries of the glide grid
     * share a centre — a key's base letter, its shifted one, whatever its long
     * press holds — and the octopus is keyed by the anchor, so the one that
     * carries a word is the one to take.
     */
    private fun octopusFlickPick(
        state: KeyboardUiState,
        points: List<GesturePoint>,
        keys: List<KeyCenter>,
        keyWidthPx: Float,
    ): Boolean {
        val octopus = state.settings.octopus
        if (!octopus.enabled || !octopus.flickCommits) return false
        if (state.octopus.isEmpty() || points.isEmpty() || keyWidthPx <= 0f) return false
        val start = points.first()
        val centre = nearestOctopusKey(state, keys, start) ?: return false
        // The word nearest the key: a flick is aimed at the key, not at one of
        // the words stacked over it, and the stack's best sits closest (#136).
        val word = state.octopus.top(centre.codePoint) ?: return false
        val taken = octopusFlick(
            points = points,
            startX = centre.x,
            startY = centre.y,
            keyWidthPx = keyWidthPx,
            startReachPx = keyWidthPx * OCTOPUS_START_REACH_WIDTHS,
            // No slop clamp here: this path only runs on a stroke the glide
            // loop already accepted as begun, so the two cannot disagree.
            minTravelPx = keyWidthPx * OCTOPUS_MIN_TRAVEL_WIDTHS,
            sensitivity = octopus.flickSensitivity,
        )
        if (!taken) return false
        onOctopusPick(word.word, OctopusSource.FLICK)
        return true
    }

    /**
     * The key nearest [at] that is carrying a floating word, or null when the
     * nearest key has nothing to offer. Argmin over the grid rather than a
     * radius test, so a finger between two keys picks one of them and not both.
     */
    private fun nearestOctopusKey(
        state: KeyboardUiState,
        keys: List<KeyCenter>,
        at: GesturePoint,
    ): KeyCenter? {
        var best: KeyCenter? = null
        var bestDistance = Float.MAX_VALUE
        for (key in keys) {
            if (key.codePoint !in state.octopus) continue
            val dx = key.x - at.x
            val dy = key.y - at.y
            val distance = dx * dx + dy * dy
            if (distance < bestDistance) {
                bestDistance = distance
                best = key
            }
        }
        return best
    }

    /**
     * `'s` on the end of the word behind the caret, drawn as a short straight
     * swipe from the punctuation key [GestureSettings.possessiveKey] names to
     * `s` (issue #169). The grid judged the shape ([possessiveFlick]); this is
     * the edit. True when the possessive went in, which is what tells the grid
     * to keep the lift from the key the swipe began on.
     *
     * A gesture of its own rather than a glide's tail. The word may be one the
     * last glide committed, one tapped out and finished with a space, or the
     * one still being typed. A space after a finished word is taken back first
     * and put back after the possessive, whoever typed it, so the field reads
     * "developer's " and never "developer 's" — the request in one line. The
     * space put back is then the keyboard's, the way a glide's is: punctuation
     * typed straight after takes it back. A word still in the composing buffer
     * takes `'s` the way a popup pick would, so the suggestion machinery sees
     * exactly the word it would have seen typed.
     *
     * English words only, like [Apostrophes]: every other language forms its
     * possessive elsewhere. That is English as the layout's language, or
     * English among its secondaries and a word spelled in plain Latin letters
     * — the English word typed on a Banglish layout, never the Bengali one
     * beside it ([contractionLanguageAllows], #243). On a phonetic layout the
     * buffer being typed is a reading, not the word, so it is judged by what
     * a space would commit and committed first when that is English.
     *
     * [letter] is the key the swipe lifted on, and picks the suffix out of
     * [CONTRACTION_SUFFIXES] (issue #243): `s` for the possessive, `t` for
     * "don't", `l` for "we'll" and so on. `'t` only follows a stem ending in
     * n, which every English n't contraction has; anywhere else it is a typo
     * the swipe would be writing on the user's behalf.
     */
    fun onPossessiveFlick(letter: Char = 's'): Boolean {
        val state = _uiState.value
        val key = state.settings.gesture.possessiveKey
        if (key == GlideApostropheKey.OFF || key == GlideApostropheKey.SPACE) return false
        if (!state.language.isEnglish && !englishIsSecondary(state)) return false
        val suffix = CONTRACTION_SUFFIXES[letter] ?: return false
        if (composing.isNotEmpty() && state.composer.isTransliterating) {
            // Avro's buffer is roman letters whichever script it becomes, so
            // the preview (which is what a space would commit) is what is
            // judged. An English one is committed, and extended below like any
            // word behind the caret.
            val shown = composedPreview(state, composing.toString())
            if (!takesContraction(shown, letter) || !contractionLanguageAllows(shown, state)) return false
            if (state.captureTarget() != null) return false
            commitComposing(currentInputConnection ?: return false, autocorrect = false)
        } else if (composing.isNotEmpty()) {
            if (!takesContraction(composing, letter) || !contractionLanguageAllows(composing, state)) return false
            onText(contractionCased(composing, suffix))
            return true
        }
        // The keyboard's own fields take a typed character before the field
        // sees it; a possessive has nothing to attach to in any of them. Three
        // of the dozen used to be named here, so the flick reached into the
        // app behind the other nine.
        if (state.captureTarget() != null) return false
        val ic = currentInputConnection ?: return false
        val before = ic.getTextBeforeCursor(POSSESSIVE_CONTEXT_CHARS, 0)?.toString() ?: return false
        val spaces = before.takeLastWhile { it == ' ' }.length
        val stem = before.dropLast(spaces)
        val word = stem.takeLastWhile(::isComposingWordChar)
        if (!takesContraction(word, letter) || !contractionLanguageAllows(word, state)) return false
        val gestureWord = lastGestureWord?.takeIf { stem.endsWith(it) }
        val cased = contractionCased(word, suffix)

        vibrate()
        ic.beginBatchEdit()
        if (spaces > 0) ic.deleteSurroundingText(spaces, 0)
        ic.commitText(cased, 1)
        if (spaces > 0) ic.commitText(" ", 1)
        ic.endBatchEdit()
        pendingWordSpace = spaces > 0
        val possessive = word + cased
        // After a glide, backspace still takes the whole thing back in one
        // press, stem included, which is what the swipe built. The stroke on
        // record drew the stem, not the possessive, so it is not offered a
        // second look. After anything else there is no stroke to keep.
        lastGestureWord = if (gestureWord != null) possessive else null
        lastGestureStroke = null
        lastHandAdjustment = null
        lastRevertible = null
        clearSwapOffer()
        learn(possessive)
        armRevertGuard()
        // It rewrote the word behind the caret, so the keys and the emoji chips
        // are answering about a word that is no longer there.
        gestureJob?.cancel()
        gestureJob = serviceScope.launch {
            val floating = nextWordOctopus()
            val chips = nextWordEmoji()
            _uiState.update { it.copy(octopus = floating, emojiSuggestions = chips) }
        }
        return true
    }

    /**
     * Whether [word] can take the suffix [letter] names: it ends on a letter,
     * carries no apostrophe yet (straight or curly — "what's" is not extended
     * to "what's'd"), and for `'t` ends in n.
     */
    private fun takesContraction(word: CharSequence, letter: Char): Boolean =
        word.isNotEmpty() && word.last().isLetter() &&
            word.none { it == '\'' || it == '\u2019' } &&
            (letter != 't' || word.last().lowercaseChar() == 'n')

    /** English is one of the layout language's secondaries. */
    private fun englishIsSecondary(state: KeyboardUiState): Boolean =
        "en" in state.settings.secondaryLanguages[state.language.id].orEmpty()

    /**
     * Whether [word] is English enough to take an English contraction: any
     * word on an English layout; on another layout with English among its
     * secondaries, a word spelled in plain Latin letters only. Banglish types
     * "What" and "কেমন" on one layout, and only the first is asking for 's.
     */
    private fun contractionLanguageAllows(word: CharSequence, state: KeyboardUiState): Boolean =
        state.language.isEnglish ||
            englishIsSecondary(state) && word.all { it in 'a'..'z' || it in 'A'..'Z' }

    /** [suffix] in capitals after a word typed in capitals: "WHAT'S", not "WHAT's". */
    private fun contractionCased(word: CharSequence, suffix: String): String =
        if (word.length > 1 && word.all { !it.isLetter() || it.isUpperCase() }) suffix.uppercase() else suffix

    /**
     * Whether a glide may run right now. During a typing test the test's own
     * switch decides, not the keyboard's gesture setting or the field: the
     * test exists to compare tapping against gliding, and the word never
     * reaches the field behind the panel, so the field's say does not apply.
     * Readiness — a word list, a letter layout, enough keys — applies always.
     */
    private fun glideAllowed(state: KeyboardUiState): Boolean = when {
        !state.glideReady -> false
        state.typingTestActive -> state.settings.typingTest.glide
        // A keyboard-owned field takes the stroke into its own buffer, at its
        // own caret (#161) — so, as in a test, the *field's* say does not
        // apply: [KeyboardUiState.allowsGestureTyping] is about the app behind
        // the panel, which is not where this word is going. The two numeric
        // fields have no use for a word list and are not glided into.
        state.captureTarget() != null ->
            state.settings.gestureTyping && state.captureTarget()?.takesWords == true
        else -> state.settings.gestureTyping && state.allowsGestureTyping
    }

    /**
     * What decides whether the active language and layout can be glided. A
     * value class rather than three fields so the watcher below is one
     * `distinctUntilChanged` rather than a hand-rolled comparison that would
     * quietly stop noticing a new input the day one gets added.
     */
    private data class GlideGate(
        val languageId: String,
        /** The layout turns keystrokes into something other than the letters
         * pressed — Avro, Hangul, Vietnamese, every CJK method. A stroke over
         * such a grid spells a reading, not a word. */
        val converts: Boolean,
        /** Avro: it converts, but into a script the keyboard has a romanization
         * for, so the reading a stroke spells can be turned back into words.
         * The language that romanization belongs to, null on every other layout. */
        val phonetic: String?,
        val alphabet: Set<Int>,
        /** Bumped when the word sources change under us, so a finished
         * dictionary download re-asks the coverage question. */
        val sources: Int,
    )

    /**
     * Keeps [KeyboardUiState.glideReady] in step with the language, the layout
     * and the word lists.
     *
     * The three conditions it enforces replace two older ones that disagreed
     * with each other: a `gestureLexicon` flag set on exactly one language, and
     * an `isEnglish` check in each of the three gesture handlers. Neither was
     * about anything real — glide works wherever there is a word list, a layout
     * that types letters rather than converting them, and enough keys to spell
     * the language.
     */
    private fun startGlideReadinessWatcher() {
        serviceScope.launch {
            combine(_uiState, glideSourcesEpoch) { state, epoch ->
                GlideGate(
                    languageId = state.language.id,
                    converts = state.composer.isTransliterating || state.composer.isConversion,
                    phonetic = state.composer.phoneticLanguage
                        // Dark glides on Classic's spellings too: a stroke
                        // can't draw Dark's `/` joins, and the keys are the
                        // same, so it commits the word Classic would.
                        ?: KHIPRO_GLIDE.takeIf { state.composer is KhiproComposer }
                        // Full pinyin spells readings on QWERTY (#580). Not
                        // Double Pinyin, whose two keys per syllable no
                        // swipe of a reading draws.
                        ?: PINYIN_GLIDE.takeIf {
                            state.composer === PinyinComposer &&
                                state.settings.cjk.pinyinDoublePinyin == DoublePinyinScheme.OFF
                        }
                        // Kana JIS spells readings in kana (#958). Only a board
                        // with a key for most kana: romaji and the flick pad
                        // compose the same readings and draw none of them.
                        ?: KANA_GLIDE.takeIf {
                            state.composer.glidesKanaReadings &&
                                state.layouts.letterAlphabet.count { it in KANA_GLIDE_RANGE } >= KANA_GLIDE_MIN_KEYS
                        },
                    alphabet = state.layouts.letterAlphabet + state.composer.glideKeys +
                        // The glide grid puts the apostrophe on the `'` key for
                        // these (see KeyboardScreen), so their words count as
                        // drawable: most of Klingon's commonest end in one.
                        if (state.language.apostropheIsLetter) APOSTROPHE_LETTERS else emptySet(),
                    sources = epoch,
                )
            }
            .distinctUntilChanged()
                .collect { gate ->
                    // Handed over before coverage is asked, because on a
                    // phonetic layout coverage is a question about the
                    // romanization rather than about the Bengali word list.
                    val engine = suggestionEngine
                    if (gate.phonetic == KHIPRO_GLIDE) ensureKhiproGlide()
                    if (gate.phonetic == PINYIN_GLIDE) ensurePinyinGlide()
                    if (gate.phonetic == KANA_GLIDE) ensureKanaGlide()
                    engine?.glideRomanization =
                        gate.phonetic?.let { romanizedGlides[it] } ?: RomanizedIndex.EMPTY
                    val allowed = gate.phonetic != null || !gate.converts
                    val ready = allowed && engine != null && withContext(Dispatchers.Default) {
                        engine.glideCoverage(gate.alphabet) >= GlideCoverage.THRESHOLD
                    }
                    // Nothing of the language's own to decode against — its
                    // word list was never downloaded — so a swipe either
                    // fails or, with a secondary language's list loaded, comes
                    // back in that language (#219). Asked whatever the gate
                    // said: readiness can be earned on the secondary's words,
                    // and that is exactly when the chip is needed. A list that
                    // does not cover the layout is the other silent case, and
                    // the docs are what explain that one.
                    // Asked of the engine only while the engine is answering
                    // for the language in the gate. The binding follows a
                    // language switch a beat behind the state it is read from
                    // ([bindEngineToLayout] runs after the update that moves
                    // the language), and across that beat the word lists on
                    // hand are the ones of the language just left — which
                    // raised the chip for a language that has a list, and the
                    // once-per-language memory below then made that moment
                    // stick (discussion #364). The settings pass that binds
                    // bumps the epoch, so the question is re-asked the moment
                    // the engine has caught up.
                    val missingList = allowed && gate.phonetic == null &&
                        engine != null && engine.primaryLanguageId == gate.languageId &&
                        !engine.hasLanguageWords()
                    // A phonetic layout with no word list behind it still types —
                    // the rules and the spelling map see to that — but it is
                    // guessing at every word the map does not list, and nothing
                    // on screen says a download would stop the guessing (#239).
                    // Only once the backend is really loaded: before that an
                    // empty index means "not yet", not "nothing to load". And
                    // not for a language the user set to its own lists alone.
                    val phoneticBare = gate.phonetic != null && engine != null &&
                        engine.extraPhonetic[gate.phonetic]?.index?.isEmpty == true &&
                        shippedDictionaryEnabled(gate.phonetic)
                    val offer = when {
                        missingList -> glideWordListOffer(gate.languageId)
                        phoneticBare -> phoneticWordListOffer(gate.languageId)
                        else -> null
                    }
                    _uiState.update {
                        if (it.glideReady == ready && it.glideWordListOffer == offer &&
                            it.wordListOfferIsPhonetic == (offer != null && phoneticBare)
                        ) {
                            it
                        } else {
                            it.copy(
                                glideReady = ready,
                                glideWordListOffer = offer,
                                wordListOfferIsPhonetic = offer != null && phoneticBare,
                            )
                        }
                    }
                }
        }
    }

    /**
     * Mid-swipe: show the current best candidates without committing.
     * [capitals] is how many times the stroke has crossed the shift key so
     * far, so the preview is cased the way the lift will case the word (#162).
     */
    fun onGesturePreview(
        points: List<GesturePoint>,
        keys: List<KeyCenter>,
        keyWidthPx: Float,
        case: GlideCase = GlideCase.None,
    ) {
        // The two-thumb loop's signals that the last finger lifted (#638) or
        // the first one landed (#674), and the bars' own (#743): no stroke, so
        // nothing to preview. Counted whether or not a glide may run now, so a
        // lift is never lost to a field that changed under the finger.
        if (points.isEmpty()) {
            // Every thumb up: no stroke is still being drawn.
            if (keyWidthPx == DUET_PING_ALL_UP) liveDuetStrokes.clear()
            when (keyWidthPx) {
                DUET_PING_DOWN -> onKeyboardTouch(down = true, onKeys = true)
                DUET_PING_BAR_DOWN -> onKeyboardTouch(down = true)
                DUET_PING_BAR_UP -> onKeyboardTouch(down = false)
                else -> onKeyboardTouch(down = false, onKeys = true)
            }
            return
        }
        val state = _uiState.value
        if (!glideAllowed(state)) return
        if (keys.isEmpty()) return
        // A Pinyin or kana swipe previews nothing: what it decodes is a
        // reading, which the strip shows converted once the finger lifts
        // (#580, #958).
        if (state.composer === PinyinComposer || state.composer.glidesKanaReadings) return
        syncGlideTriggers(state)
        if (swipeJoinsWord(state)) noteLiveDuetStroke(points)
        gesturePreviews.trySend(
            GesturePreviewRequest(
                points, keys, keyWidthPx, case, gestureGeneration.get(),
                tokens = duetPreviewTokens(state, points, keys, keyWidthPx),
            ),
        )
    }

    /**
     * Every two-thumb stroke still being drawn, by when it landed, with its
     * latest points (#849). A preview of one thumb's stroke reads the whole
     * word: the lifted gestures, then each of these in the order they began.
     * Read with only its own stroke, a preview alternated between "the word
     * plus thumb A" and "the word plus thumb B" while both thumbs moved, and
     * the strip flipped back and forth with them.
     */
    private val liveDuetStrokes = java.util.TreeMap<Long, List<GesturePoint>>()

    private fun noteLiveDuetStroke(points: List<GesturePoint>) {
        val first = points.firstOrNull() ?: return
        liveDuetStrokes[first.t] = points
        // A stroke that ended without its lift reaching here (a tap after
        // all, a stolen pointer) is dropped once it has gone quiet.
        val newest = points.last().t
        liveDuetStrokes.entries.removeAll { (_, live) -> newest - live.last().t > LIVE_STROKE_QUIET_MS }
    }

    /**
     * Drains [gesturePreviews] for the life of the service. One coroutine
     * instead of a cancel-and-relaunch per preview, and the generation check is
     * what the cancel used to buy: a preview decoded before the swipe committed
     * must not put its own candidates back on the strip afterwards.
     */
    private fun startGesturePreviewConsumer() {
        serviceScope.launch {
            for (request in gesturePreviews) {
                if (request.generation != gestureGeneration.get()) continue
                val reading = withContext(Dispatchers.Default) {
                    // Same sources as the final decode, so the previewed word
                    // never differs from the one that commits on finger-up.
                    request.tokens?.let { duetReading(it, request.points, request.keys, request.keyWidthPx) }
                        ?: glideDecode(request.points, request.keys, request.keyWidthPx)
                }
                if (reading.words.isEmpty()) {
                    // A two-thumb word whose gestures finish no word yet: the
                    // floating word shows how far it has got, the way the
                    // composing text does between gestures, instead of
                    // holding on to a reading from before (#678).
                    val tokens = request.tokens ?: continue
                    val prefix = withContext(Dispatchers.Default) {
                        duetPrefix(tokens, request.keys, request.keyWidthPx)
                    } ?: continue
                    if (request.generation != gestureGeneration.get()) continue
                    _uiState.update {
                        it.copy(
                            glideWord = prefix,
                            glideCase = GlideCase.None,
                            glideCased = emptyMap(),
                            glideChoices = emptyList(),
                            glideCloseCall = false,
                        )
                    }
                    continue
                }
                // Re-checked after the decode: the finger may have lifted and
                // the word committed while this was running.
                if (request.generation != gestureGeneration.get()) continue
                val gesture = _uiState.value.settings.gesture
                // Applied before anything is published, so the strip, the keys,
                // the pill and the picker all show the same word: they are all
                // built from this one list.
                val steadied = steadyPreview(reading, gesture.previewSteadiness)
                // The side slots held too (#849), for the strip alone: the
                // pill, the picker and the lift all follow [steadied].
                val strip = previewGate.steadySides(
                    steadied.words, steadied.scores, gesture.previewSteadiness, SystemClock.elapsedRealtime(),
                )
                val floating = octopusForGlide(_uiState.value, steadied.words)
                // Per-letter capitals need the decoder's placement of each
                // word along the stroke, which is one small alignment a word
                // — off the main thread with the decode, not on it.
                val cased = if (request.case is GlideCase.Letters) {
                    withContext(Dispatchers.Default) {
                        glideLetterCases(request.case, steadied.words, request.points, request.keys, request.keyWidthPx)
                    }
                } else {
                    emptyMap()
                }
                if (request.generation != gestureGeneration.get()) continue
                val expansions = glideExpansionsFor(_uiState.value, steadied.words)
                _uiState.update {
                    it.copy(
                        suggestions = strip,
                        octopusGlide = floating,
                        glideWord = steadied.words.first(),
                        // Published raw and cased at the draw sites, through
                        // the same ladder the commit uses (#162). Casing the
                        // words here would title-case a picked word twice on
                        // the way back in, and would leave the pill's own
                        // board-shift pass to shout a word the stroke only
                        // asked a capital of.
                        glideCase = request.case,
                        glideCased = cased,
                        glideExpansions = expansions,
                        // The word a lift would type, published as the promise
                        // it is rather than left as one more bold suggestion
                        // (#121). [KeyboardUiState.autocorrectWord] is already
                        // "the word the next commit will really put in", and
                        // the strip already draws that word in the user's own
                        // colour, so the whole feature is this one line plus
                        // the two surfaces that opt into the same colour.
                        autocorrectWord = glideCommitPromise(steadied, gesture),
                        // Every preview carries choices while the picker is
                        // on: a stroke that is not a close call can still be
                        // asked about by holding longer, so the popup needs
                        // the words either way. The flag is what picks the
                        // short dwell over the long one.
                        glideChoices = if (gesture.ambiguityPicker) {
                            steadied.words.take(gesture.pickerChoices)
                        } else {
                            emptyList()
                        },
                        glideCloseCall = steadied.closeCall,
                    )
                }
            }
        }
    }

    /**
     * [reading], with the word already on screen kept in front of it unless a
     * challenger has earned the swap — see [GlidePreviewGate].
     */
    private fun steadyPreview(
        reading: GlideReading,
        steadiness: GlidePreviewSteadiness,
    ): GlideReading {
        val at = previewGate.steady(
            reading.words, reading.scores, steadiness, SystemClock.elapsedRealtime(),
        )
        return if (at == 0) reading else reading.leading(reading.words[at])
    }

    /**
     * The word [reading] leads with, when the user has asked for it to be
     * drawn in the strip's own colour rather than merely bolded, and null when
     * bold is all it gets. See [GlideCommitColor].
     *
     * A guess is only *sure* against the stroke it was read off, so the
     * question is asked of the reading that is about to be published rather
     * than of the setting alone: the same word can be a certainty one frame
     * and a coin toss the next, and the colour has to say so.
     */
    private fun glideCommitPromise(reading: GlideReading, gesture: GestureSettings): String? {
        val leader = reading.words.firstOrNull() ?: return null
        return when (gesture.commitColor) {
            GlideCommitColor.OFF -> null
            GlideCommitColor.CONFIDENT -> leader.takeIf { it in reading.sure }
            GlideCommitColor.GUESS -> leader.takeIf { it in reading.guesses }
            GlideCommitColor.ALWAYS -> leader
        }
    }

    /**
     * [word] cased the way its stroke asked: [shift] first — the board's own,
     * or the whole-word ladder a crossing walked up (#115) — and then the
     * per-letter capitals a [GlideCase.Letters] named (#163), laid onto the
     * word where the decoder places its keys along [points]. The same call
     * cases the preview and the commit, so the word on screen is the word
     * that lands.
     */
    private fun glideCased(
        word: String,
        shift: ShiftState,
        case: GlideCase,
        points: List<GesturePoint>,
        keys: List<KeyCenter>,
        keyWidthPx: Float,
    ): String {
        val based = when (shift) {
            ShiftState.CAPS_LOCK -> word.uppercaseKeepingLength()
            ShiftState.ON -> word.replaceFirstChar { it.uppercase() }
            ShiftState.OFF -> word
        }
        // A shout already went through [shift] as caps lock.
        if (case !is GlideCase.Letters || case.shout || case.cuts.isEmpty()) return based
        val alignment = suggestionEngine?.alignGlide(word, points, keyMapFor(keys, keyWidthPx), keyWidthPx)
        return case.caseWord(based, alignment)
    }

    /** Each of [words] as [case] cases it, keyed by the raw word, for the pill and the strip (#163). */
    private fun glideLetterCases(
        case: GlideCase.Letters,
        words: List<String>,
        points: List<GesturePoint>,
        keys: List<KeyCenter>,
        keyWidthPx: Float,
    ): Map<String, String> {
        val shift = shiftForGlide(_uiState.value.shiftState, case)
        return words.associateWith { glideCased(it, shift, case, points, keys, keyWidthPx) }
    }

    /**
     * Retires the previews a stroke published — the floating word, the
     * picker's choices and its close-call flag — the way a commit does. The
     * strip's suggestions are left to the caller: a commit replaces them, a
     * cancel restores them.
     */
    private fun clearGlidePreview() {
        // Every exit from a stroke comes through here, so the steadiness gate
        // is reset here too: a new stroke must never inherit the last one's
        // word, or its first reading would be judged against a stranger.
        previewGate.reset()
        glideExpansionCache.clear()
        glideNextWordBoard = null
        _uiState.update { state ->
            state.copy(
                glideWord = null,
                glideCase = GlideCase.None,
                glideCased = emptyMap(),
                glideExpansions = emptyMap(),
                glideChoices = emptyList(),
                glideCloseCall = false,
                // Only the promise this stroke made. A flick short enough to
                // publish no preview at all leaves whatever the composing word
                // had claimed, which is still true of the field behind it.
                autocorrectWord = state.autocorrectWord
                    ?.takeUnless { it.equals(state.glideWord, ignoreCase = true) },
                // Every exit from a stroke comes through here, so one line
                // covers the commit, the cancel and the picker alike. Only the
                // stroke's own words go: the idle ones belong to the buffer,
                // which this stroke has not changed, and clearing them here is
                // what used to leave the flick with nothing to pick.
                octopusGlide = emptyMap(),
            )
        }
    }

    /**
     * The picker was dragged out of and the finger lifted: the stroke types
     * nothing and teaches nothing. Retires the previews the way a commit does,
     * then puts the strip back to what the field was showing before the swipe,
     * since the previews overwrote it with the stroke's own words. Nothing else
     * moves: the composing text was never committed, the revert guard is not
     * armed, and the last glided word is still the previous, real one.
     */
    private fun cancelGlide() {
        gestureGeneration.incrementAndGet()
        suggestionJob?.cancel()
        gestureJob?.cancel()
        clearGlidePreview()
        refreshSuggestions()
    }

    // ---- words built from several gestures (#638 two thumbs, #595 typed + swipe) ----

    /**
     * Whether a swipe lifting now joins the word in progress rather than being
     * a word of its own: always under two-thumb typing, and under the #595
     * switch whenever letters are already typed. Never on a board whose buffer
     * is not the word itself (a transliterator, a conversion IME, a keypad).
     */
    private fun swipeJoinsWord(state: KeyboardUiState): Boolean {
        if (state.composer.isTransliterating || state.composer.isConversion) return false
        if (state.layouts.ambiguousKeys) return false
        val gesture = state.settings.gesture
        return gesture.twoThumbGlide || (gesture.swipeContinuesTyped && composingIsTyped())
    }

    /**
     * Whether [composing] holds letters typed into it, rather than a word the
     * caret only landed on that nobody has touched since — the same line
     * [onSpace] draws. A swipe continues the first and never the second: tap
     * at the end of "Hello" and swipe "world", and the swipe is a new word,
     * not "Hello" read as five more taps of it (#742). A letter typed or
     * deleted there first is a deliberate edit, and the swipe joins it.
     */
    private fun composingIsTyped(): Boolean = composing.isNotEmpty() && composing.toString() != resumedWord

    /**
     * A lifted swipe that joins the word in progress: added to its gestures and
     * the whole word read again. False when the swipe does not join one, and
     * the caller decodes it as a word of its own.
     */
    private fun duetSwipe(
        state: KeyboardUiState,
        points: List<GesturePoint>,
        keys: List<KeyCenter>,
        keyWidthPx: Float,
        shift: ShiftState,
    ): Boolean {
        if (!swipeJoinsWord(state)) return false
        // A swipe begun straight after an all-thumbs-up space may carry the
        // word before it on (#747), the way a tapped letter may: the word is
        // open again, as typed letters, for the swipe to finish below.
        val allUpSpaceBehind = allUpSpace.takeIf { pendingWordSpace }
        allUpSpace = null
        if (allUpSpaceBehind != null && !duetWord.active && composing.isEmpty()) {
            currentInputConnection?.let {
                reopenAfterAllUpSpace(it, state, allUpSpaceBehind, swipeStartLetters(points.first(), keys, keyWidthPx))
            }
        }
        if (!duetWord.active) {
            if (composingIsTyped()) {
                if (!duetWord.seed(composing, composingTouchFrame(), keys, keyWidthPx)) return false
                // The typed letters already carry the word's case.
                duetShift = when {
                    composing.length > 1 && composing.all { !it.isLetter() || it.isUpperCase() } ->
                        ShiftState.CAPS_LOCK
                    composing.first().isUpperCase() -> ShiftState.ON
                    else -> ShiftState.OFF
                }
            } else {
                // A word the caret only landed on goes in as it stands: it is
                // the field's own text, with nothing to correct (#742).
                if (composing.isNotEmpty()) {
                    currentInputConnection?.let { commitComposing(it, autocorrect = false) }
                }
                // A new word. What Backspace or the strip would still take back
                // belongs to the word before it, and goes as after a typed
                // letter: left armed, a Backspace before this word's first
                // reading lands would undo that word instead (#732).
                lastGestureWord = null
                lastGestureStroke = null
                lastRevertible = null
                clearSwapOffer()
                pendingWordSpace = false
                // The space in front of a glided word goes in front of this one
                // too, so it is not glued to the text before it ("Hi,there")
                // (#735). A word that starts with taps keeps typing rules.
                currentInputConnection?.let { commitGestureLeadingSpace(it, state) }
                duetWord.clear()
                duetShift = shift
                consumeShift()
            }
        }
        duetWord.addSwipe(points, keys, keyWidthPx)
        allUpArmed = true
        // Ordinary glide with #595 types the word at the lift, as any glide
        // does; two-thumb typing keeps it open until the word end it uses.
        redecodeDuet(commit = !state.settings.gesture.twoThumbGlide)
        return true
    }

    /**
     * A stroke under two-thumb typing too small to be a swipe (#738): a fast
     * tap that rolled past the swipe start distance, whose key press the loop
     * had already given up. It types the letter of the key it started on, as
     * the tap it was: into the word in progress, or as the start of one.
     * False when two-thumb typing is off or the stroke is a real swipe.
     */
    private fun duetStrokeAsTap(
        state: KeyboardUiState,
        points: List<GesturePoint>,
        keys: List<KeyCenter>,
        keyWidthPx: Float,
    ): Boolean {
        if (!state.settings.gesture.twoThumbGlide || !swipeJoinsWord(state)) return false
        if (!isTapSizedStroke(points, keyWidthPx)) return false
        val down = points.first()
        val key = keys.minByOrNull { (it.x - down.x) * (it.x - down.x) + (it.y - down.y) * (it.y - down.y) }
            ?: return false
        if (!Character.isLetter(key.codePoint)) return false
        onKeyTouch(down.x, down.y, down.t)
        onKey(Key(String(Character.toChars(Character.toLowerCase(key.codePoint)))))
        return true
    }

    /**
     * A letter tapped while a two-thumb word is open: one more gesture in it,
     * and the word read again. False when no such word is open, and the letter
     * is typed the ordinary way.
     */
    private fun duetTap(text: String): Boolean {
        if (!duetWord.active) return false
        if (text.length != 1 || !text[0].isLetter() || !duetWord.addTap(text, pendingTouch)) {
            // Something the gestures cannot hold — a digit, a mark, a letter
            // off this grid. The word on screen goes on as typed text.
            duetWord.clear()
            return false
        }
        pendingTouch = null
        pendingKeyLetters = null
        pendingKeyHint = null
        allUpArmed = true
        redecodeDuet(commit = false)
        return true
    }

    /**
     * Backspace on a two-thumb word takes back its latest tap or swipe. When
     * no swipe is left, what remains is the letters as they were typed.
     *
     * With "Backspace undoes swipe" off (#455) the word stops being gestures
     * instead, and the press takes one letter of it, as after a glide (#732):
     * false, so the caller's buffer delete runs.
     */
    private fun duetBackspace(ic: InputConnection): Boolean {
        if (!duetWord.active) return false
        if (!_uiState.value.settings.gesture.backspaceUndoesGlide) {
            // Settled first, so a swipe still being read is not lost; dropped
            // without the setter, which would take the word's text and its
            // all-up pause with the gestures.
            if (duetShownGeneration != duetGeneration) settleDuet(ic)
            duetJob?.cancel()
            duetGeneration++
            duetWord.clear()
            // Nothing could be shown at all: the gestures were the whole word.
            return composing.isEmpty()
        }
        val removed = duetWord.snapshot().lastOrNull() as? GlideToken.Swipe
        duetWord.removeLast()
        if (duetWord.active) {
            // The swipe just taken out can come back as the next word (#832).
            redecodeDuet(commit = false, backspaced = removed)
            return true
        }
        val keys = duetWord.keys
        val keyWidthPx = duetWord.keyWidthPx
        val typed = duetWord.typedText().orEmpty()
        // The setter ends the gestures and any decode of them.
        composing = StringBuilder(typed)
        updateComposingText(ic)
        // The swipe just taken out off a word begun with taps can come back as
        // the next word too (#870), and the strip's merged reading is stale
        // from this moment: picked, it would type the swipe back in.
        if (removed != null && typed.isNotEmpty() && _uiState.value.settings.gesture.twoThumbGlide) {
            offerBackspacedSwipe(typed, removed, keys, keyWidthPx)
        } else {
            refreshSuggestions()
        }
        return true
    }

    /**
     * The "↪ tail" chip for [removed], read off the main thread, once the
     * word left behind it is [typed] letters with no swipe (#870). Until it
     * is read the strip is empty; a swipe that reads as nothing gets the
     * ordinary strip for the letters.
     */
    private fun offerBackspacedSwipe(typed: String, removed: GlideToken.Swipe, keys: List<KeyCenter>, keyWidthPx: Float) {
        suggestionJob?.cancel()
        _uiState.update { it.copy(suggestions = emptyList(), emojiSuggestions = emptyList(), octopus = emptyMap()) }
        val generation = duetGeneration
        duetJob = serviceScope.launch {
            val tail = withContext(Dispatchers.Default) { loneSwipeWord(removed.points, keys, keyWidthPx) }
            if (generation != duetGeneration || composing.toString() != typed) return@launch
            if (tail.isNullOrEmpty()) {
                refreshSuggestions()
                return@launch
            }
            val split = DuetSplit("↪ $tail", null, tail, removed, keys, keyWidthPx)
            duetSplit = split
            _uiState.update { it.copy(suggestions = listOf(split.chip)) }
        }
    }

    /**
     * The last finger on the keyboard lifted, off the keys or a bar (#743):
     * under [TwoThumbWordEnd.ALL_UP], the word is typed once no thumb has landed for
     * [GestureSettings.twoThumbPauseMs].
     *
     * Not at once: thumbs that take turns lift one before the other lands, so
     * a word typed that way — "movement", "probably", the second e of "heed"
     * off the other thumb — used to end at the first gap between them and come
     * out in pieces (#674). And a word of taps alone ends here too, with the
     * same automatic space (#676, #734); `T`, lift, `o` stays "To" because the
     * `o` lands inside the pause.
     */
    private fun onAllThumbsUp() {
        if (keysTouched || barsTouched > 0) return
        val state = _uiState.value
        if (!glideAllowed(state)) return
        val gesture = state.settings.gesture
        if (!gesture.twoThumbGlide || gesture.twoThumbWordEnd != TwoThumbWordEnd.ALL_UP) return
        allUpJob?.cancel()
        if (!allUpArmed) return
        // Swiped and tapped words wait their own pauses, and a word of one
        // letter at least the floor (#747).
        val pause = allUpPauseMs(
            gesture,
            swiped = duetWord.active,
            letters = composing.codePointCount(0, composing.length),
        )
        val countdown = if (gesture.twoThumbPauseBand) AllUpCountdown(pause, ++allUpCountdownId) else null
        if (countdown != null) _uiState.update { it.copy(allUpCountdown = countdown) }
        allUpJob = serviceScope.launch {
            try {
                delay(pause)
                // The lift that sent this may still be decoding, and a newer
                // decode may have replaced it meanwhile: wait for whichever is
                // last. Waiting is only the cheap way; the commit settles
                // anything still pending itself.
                while (true) {
                    val job = duetJob ?: break
                    if (!job.isActive) break
                    job.join()
                }
                if (!allUpArmed || composing.isEmpty()) return@launch
                val ic = currentInputConnection ?: return@launch
                // Letters that reopened a word and finish none with it go back
                // to being a word of their own, which is what ends here (#747).
                if (reopenedWord != null && !duetWord.active && !isKnownWord(composing.toString())) {
                    splitReopenedWord(ic)
                }
                if (duetWord.active) {
                    commitDuet(ic)
                } else {
                    // A word of taps alone has no gestures to reopen as; an
                    // older two-thumb word spelled the same must not stand in.
                    committedDuet = null
                    endTappedWordAtPause(ic)
                }
                armAllUpSpace(ic, gesture)
            } finally {
                if (countdown != null) clearAllUpCountdown(countdown.id)
            }
        }
    }

    /**
     * Notes the space the all-thumbs-up pause has just typed after a word, so
     * a letter landing inside the retraction window may take it back (#747).
     * Only a space that is really there and really ours: none under a mode
     * with automatic spaces off, and none after a snippet that left the caret
     * inside its text.
     */
    private fun armAllUpSpace(ic: InputConnection, gesture: GestureSettings) {
        allUpSpace = null
        val window = allUpRetractWindowMs(gesture)
        if (window <= 0 || !pendingWordSpace) return
        val before = ic.getTextBeforeCursor(ALL_UP_RETRACT_LOOKBACK, 0)?.toString() ?: return
        if (!before.endsWith(' ')) return
        // The whole word, apostrophes and all (#818): `it's` and not its `s`,
        // or `on` would take the space back to make "it'son". An opening
        // quote is not part of the word, so `'car` still reopens as `car`.
        val run = before.dropLast(1).takeLastWhile { isComposingWordChar(it) }
        // A word that fills the whole look-back may go on past it.
        if (run.length == ALL_UP_RETRACT_LOOKBACK - 1) return
        val word = run.trimStart { WordContext.isApostrophe(it) }
        if (word.isEmpty()) return
        allUpSpace = AllUpSpace(word, SystemClock.uptimeMillis(), window)
    }

    /**
     * Takes back the all-thumbs-up [space] the caret sits behind, and opens
     * the word before it again as typed letters, for the letter or swipe
     * about to come to join (#747). Only inside the window, measured to when
     * the thumb landed, and only when the word and one of [starts] still lead
     * to a dictionary word: `car` then `p` reopens "car", `car` then `x`
     * leaves "car " alone. A capital waiting on the shift key is a new word.
     * True when the word is open again.
     */
    private fun reopenAfterAllUpSpace(
        ic: InputConnection,
        state: KeyboardUiState,
        space: AllUpSpace,
        starts: Set<String>,
    ): Boolean {
        val gesture = state.settings.gesture
        if (!gesture.twoThumbGlide || gesture.twoThumbWordEnd != TwoThumbWordEnd.ALL_UP) return false
        if (state.shiftState != ShiftState.OFF) return false
        val landed = space.landedAt.takeIf { it >= 0 } ?: SystemClock.uptimeMillis()
        if (!insideRetractWindow(space.at, landed, space.windowMs)) return false
        // A transliterator's buffer is not the word on screen.
        if (state.composer.resumeBuffer(space.word) != space.word) return false
        val engine = suggestionEngine ?: return false
        if (!continuesWord(space.word, starts, engine::isLivePrefix)) return false
        val typed = space.word + " "
        if (ic.getTextBeforeCursor(typed.length, 0)?.toString() != typed) return false
        // A two-thumb word comes back as the gestures it was, so a Backspace
        // after the next one takes back a swipe, not a letter (#858). Not
        // asked of lastGestureWord: a tapped letter has cleared that by now
        // (#895), and the text check above already says the word behind the
        // caret is this one.
        val duet = committedDuet?.takeIf { it.word == space.word }
        committedDuet = null
        if (duet != null) {
            reopenCommittedDuet(ic, duet, typed.length, dropLast = false)
            reopenedWord = ReopenedWord(space.word, starts, headGestures = duet.gestures.snapshot().size)
            return true
        }
        ic.beginBatchEdit()
        ic.deleteSurroundingText(typed.length, 0)
        pendingWordSpace = false
        // What Backspace or the strip would have taken back was that word,
        // which is not finished after all; nor is it evidence of anything yet.
        lastGestureWord = null
        lastGestureStroke = null
        stripReplacesGestureWord = false
        lastRevertible = null
        learningBuffer.drop(space.word)
        syncPreviousWordFromField(ic)
        composing = StringBuilder(space.word)
        resumedWord = null
        updateComposingText(ic)
        ic.endBatchEdit()
        reopenedWord = ReopenedWord(space.word, starts)
        return true
    }

    /**
     * Takes back the [length] characters of [duet]'s word and its space behind
     * the caret and opens the word again as its gestures (#858), less the
     * latest one when [dropLast]: what [duetBackspace] does to a word still
     * open. Gestures that are only taps once that one is gone come back as the
     * letters they typed.
     */
    private fun reopenCommittedDuet(ic: InputConnection, duet: CommittedDuet, length: Int, dropLast: Boolean) {
        val gestures = duet.gestures.copy()
        val removed = if (dropLast) gestures.snapshot().lastOrNull() as? GlideToken.Swipe else null
        if (dropLast) gestures.removeLast()
        ic.beginBatchEdit()
        ic.deleteSurroundingText(length, 0)
        pendingWordSpace = false
        // The word is not finished after all, nor evidence of anything yet.
        lastGestureWord = null
        lastGestureStroke = null
        stripReplacesGestureWord = false
        lastRevertible = null
        learningBuffer.drop(duet.word)
        syncPreviousWordFromField(ic)
        resumedWord = null
        if (gestures.active) {
            duetWord.restore(gestures)
            duetShift = duet.shift
            keepDuet = true
            try {
                // The word as it was until the read below lands; one gesture
                // shorter, the gestures' own letters.
                composing = StringBuilder(if (dropLast) gestures.literal() else duet.word)
            } finally {
                keepDuet = false
            }
            updateComposingText(ic)
            ic.endBatchEdit()
            if (dropLast) redecodeDuet(commit = false, backspaced = removed)
            return
        }
        composing = StringBuilder(gestures.typedText().orEmpty())
        updateComposingText(ic)
        ic.endBatchEdit()
        refreshSuggestions()
    }

    /**
     * Whether the word an all-thumbs-up space was taken back from still holds
     * together with what now follows it (see the top-level
     * [reopenedWordHolds]); true when no word was reopened.
     */
    private fun reopenedHolds(complete: Boolean): Boolean {
        val reopened = reopenedWord ?: return true
        val engine = suggestionEngine ?: return true
        return reopenedWordHolds(reopened.word, composing.toString(), reopened.starts, complete, engine::isLivePrefix)
    }

    /**
     * The reopened word and what followed it make no word: the word goes back
     * in with its space, as the pause typed it, and the rest carries on as a
     * word of its own (#747). Its gestures stay gestures, read again without
     * the letters in front; typed letters stay typed.
     */
    private fun splitReopenedWord(ic: InputConnection) {
        val reopened = reopenedWord ?: return
        reopenedWord = null
        val state = _uiState.value
        val head = reopened.word
        val rest = if (duetWord.active) {
            duetWord.copy().takeIf { it.dropFirst(reopened.headGestures) }
        } else {
            null
        }
        val tail = composing.toString().let { if (it.startsWith(head, ignoreCase = true)) it.substring(head.length) else "" }
        ic.beginBatchEdit()
        // The setter ends the gestures, so the word goes in as the typed text
        // it was before the space came out.
        composing = StringBuilder(head)
        updateComposingText(ic)
        commitComposing(ic, autocorrect = false)
        commitGestureSpace(ic, state)
        // A letter is already typed past that space.
        pendingWordSpace = false
        if (rest != null && rest.active) {
            duetWord.restore(rest)
            keepDuet = true
            try {
                composing = StringBuilder(rest.literal())
            } finally {
                keepDuet = false
            }
            allUpArmed = true
            updateComposingText(ic)
            ic.endBatchEdit()
            redecodeDuet(commit = false)
            return
        }
        composing = StringBuilder(rest?.typedText() ?: tail)
        allUpArmed = composing.isNotEmpty()
        updateComposingText(ic)
        ic.endBatchEdit()
        refreshSuggestions()
    }

    /** The letters a swipe that starts at [start] may have meant to begin on: its key and those within a key width. */
    private fun swipeStartLetters(start: GesturePoint, keys: List<KeyCenter>, keyWidthPx: Float): Set<String> {
        val reach = keyWidthPx * keyWidthPx
        val nearest = keys.minByOrNull { (it.x - start.x) * (it.x - start.x) + (it.y - start.y) * (it.y - start.y) }
        return keys.filter {
            it === nearest || (it.x - start.x) * (it.x - start.x) + (it.y - start.y) * (it.y - start.y) <= reach
        }
            .filter { Character.isLetter(it.codePoint) }
            .mapTo(HashSet()) { String(Character.toChars(Character.toLowerCase(it.codePoint))) }
    }

    /** Takes the all-thumbs-up band off the strip, if it is still pause [id]'s. */
    private fun clearAllUpCountdown(id: Int) {
        _uiState.update { if (it.allUpCountdown?.id == id) it.copy(allUpCountdown = null) else it }
    }

    /**
     * Ends a word of taps alone at the all-thumbs-up pause (#676) the way a
     * swiped word ends there: corrected as a Space would correct it, then
     * followed by [commitGestureSpace]. That space is the keyboard's own, so a
     * mode with automatic spaces off gets none, and a habitual Space press or a
     * full stop straight afterwards takes it back. Not [onSpace]: that is the
     * user's own press, which types a space in every mode and arms the
     * double-space full stop (#734).
     */
    private fun endTappedWordAtPause(ic: InputConnection) {
        val state = _uiState.value
        pendingWordSpace = false
        // The word and its space are one edit, as in [onSpace], which keeps a
        // correction's backspace-to-revert window armed.
        ic.beginBatchEdit()
        val committed = commitComposing(
            ic,
            autocorrect = state.settings.correction.enabledFor(state.language.id),
            fixApostrophes = state.settings.autoText.apostrophe,
            expandPatterns = true,
        )
        if (swallowTerminatorAfterCommit) {
            // An expansion left the caret at its {cursor} marker, inside the
            // text it inserted: a space there would split the snippet.
            swallowTerminatorAfterCommit = false
        } else if (committed) {
            commitGestureSpace(ic, state)
            if (pendingWordSpace) recordStat { onSeparator(System.currentTimeMillis(), SystemClock.uptimeMillis()) }
        }
        ic.endBatchEdit()
        maybeAutoCapitalize()
        refreshSuggestions()
    }

    /**
     * A finger landed on, or the last one lifted off, the key grid
     * ([onKeys]) or one of the bars around it. Any finger down anywhere holds
     * the all-thumbs-up pause off (#674), and it starts from the last one up
     * (#743): a thumb reaching for the strip's second reading must not see the
     * first typed under it, with its tap landing on next-word predictions. A
     * strip touch that picks replaces the word, which disarms the pause; one
     * dragged off or cancelled starts it again from its lift, so the word
     * still ends.
     */
    internal fun onKeyboardTouch(down: Boolean, onKeys: Boolean = false) {
        when {
            onKeys -> keysTouched = down
            down -> barsTouched++
            else -> barsTouched = (barsTouched - 1).coerceAtLeast(0)
        }
        // The retraction window is measured to the landing, not to the letter
        // it types (#747). A finger on the strip types no letter.
        if (down && onKeys) allUpSpace?.let { if (it.landedAt < 0) it.landedAt = SystemClock.uptimeMillis() }
        if (down) onThumbDown() else onAllThumbsUp()
    }

    /** A thumb landed: a word waiting out its all-up pause carries on instead (#674). */
    private fun onThumbDown() {
        allUpJob?.cancel()
        allUpJob = null
        // The band goes with the pause it showed (#747).
        if (_uiState.value.allUpCountdown != null) _uiState.update { it.copy(allUpCountdown = null) }
    }

    /**
     * Types the two-thumb word on screen and its space, the way a glided word
     * is — and under two-thumb typing leaves it the way a glided word is left
     * (#733): Backspace straight afterwards takes it back with its space, and a
     * pick from its alternates on the strip replaces it. No stroke rides with
     * it: undo has no one stroke to re-read. What its swipes taught the hand
     * model is taken back by the undo, as a glide's is (#741).
     */
    private fun commitDuet(ic: InputConnection) {
        val state = _uiState.value
        // Settled here rather than inside the commit, so the word and the
        // alternates kept below are the ones about to be typed.
        if (duetWord.active && duetShownGeneration != duetGeneration) settleDuet(ic)
        val word = composing.toString()
        val alternates = duetShownAlternates
        // The split the word was offering stays on offer once it is typed (#832).
        val split = duetSplit?.takeIf { it.head != null }
        // Copied before the commit, whose setter clears them (#858).
        val gestures = duetWord.copy().takeIf { it.active && it.snapshot().size > 1 }
        val shift = duetShift
        commitComposing(ic, autocorrect = false, fixApostrophes = state.settings.autoText.apostrophe)
        val undoable = state.settings.gesture.twoThumbGlide && word.isNotEmpty()
        // Read back against the field's text, so an apostrophe the commit put
        // in (#240) leaves the record unused rather than reopening the wrong word.
        committedDuet = gestures?.takeIf { undoable }?.let { CommittedDuet(word, it, shift) }
        if (undoable) {
            // Armed before the space, as the glide commit arms it (#113).
            lastGestureWord = word
            gestureWordShifted = shift != ShiftState.OFF
            lastGestureStroke = null
            // Not [lastHandAdjustment]: what the swipes taught the hand is on
            // its way from the commit above, for an undo to take back (#741).
            // Only while the strip shows this word's alternates may a pick
            // there replace it; otherwise it offers the next word (#175).
            stripReplacesGestureWord = alternates.isNotEmpty() || split != null
        }
        commitGestureSpace(ic, state)
        if (undoable) armRevertGuard()
        if (undoable && (alternates.isNotEmpty() || split != null)) {
            if (alternates.isNotEmpty()) glideReadings.remember(word, alternates)
            val committed = split?.let {
                DuetSplit(it.chip, it.head, it.tail, it.swipe, it.keys, it.keyWidthPx, committed = true)
            }
            duetSplit = committed
            _uiState.update { it.copy(suggestions = withSplitChip(alternates, committed)) }
        } else {
            refreshSuggestions()
        }
    }

    /**
     * What a word in progress shows. [complete] says whether [word] is a word:
     * when the gestures so far finish none, it is instead the start of one they
     * fit, or failing that the letters under them — never nothing, so no
     * gesture is dropped from the screen or from the buffer before the word
     * ends (#640).
     */
    private class DuetShown(val word: String, val alternates: List<String>, val complete: Boolean)

    /**
     * Reads the gestures. Null only when there is nothing to show at all.
     *
     * Safe off the main thread, and run off it everywhere except
     * [settleDuet]: a key that ends the word waits for the read in flight
     * instead ([deferBehindDuet], #744), so only a word ended some other way
     * mid-read (a cursor move, a panel opening) is read on the main thread.
     */
    private fun readDuet(
        tokens: List<GlideToken>,
        lone: List<GesturePoint>?,
        keys: List<KeyCenter>,
        keyWidthPx: Float,
        literal: String,
    ): DuetShown? {
        val reading = if (lone != null) {
            glideDecode(lone, keys, keyWidthPx, guessAhead = false)
        } else {
            duetReading(tokens, null, keys, keyWidthPx)
        }
        reading.words.firstOrNull()?.let { return DuetShown(it, reading.words, complete = true) }
        val shown = duetPrefix(tokens, keys, keyWidthPx) ?: literal.takeIf { it.isNotEmpty() } ?: return null
        return DuetShown(shown, emptyList(), complete = false)
    }

    /** The start of a word [tokens] are on their way to, when they finish none yet (#640); safe off the main thread. */
    private fun duetPrefix(tokens: List<GlideToken>, keys: List<KeyCenter>, keyWidthPx: Float): String? =
        suggestionEngine?.glideTokens(
            tokens = tokens,
            keys = keyMapFor(keys, keyWidthPx),
            keyWidth = keyWidthPx,
            limit = 1,
            partial = true,
        )?.firstOrNull()?.word

    /**
     * Reads the word's gestures again, off the main thread, and puts the best
     * reading in the composing region with the rest on the strip. [commit]
     * then types it at once, for #595 in ordinary glide.
     */
    private fun redecodeDuet(commit: Boolean, backspaced: GlideToken.Swipe? = null) {
        val tokens = duetWord.snapshot()
        // Backspace has taken the word back to the gestures it was reopened
        // with, or fewer (#895): that is an undo, not a continuation that
        // failed, so the word stays open without its space rather than being
        // split back off with it.
        if (reopenedWord?.let { tokens.size <= it.headGestures } == true) reopenedWord = null
        val keys = duetWord.keys
        val keyWidthPx = duetWord.keyWidthPx
        val lone = duetWord.loneSwipe()
        val literal = duetWord.literal()
        // The split chip (#832): the word without its last swipe, and that
        // swipe on its own. Only under two-thumb typing, and only when the
        // last gesture is a swipe with something in front of it.
        duetSplit = null
        val twoThumb = _uiState.value.settings.gesture.twoThumbGlide
        val headWord = duetWord.copy().takeIf {
            !commit && twoThumb && backspaced == null && tokens.size >= 2 && tokens.last() is GlideToken.Swipe
        }?.also { it.removeLast() }
        val lastSwipe = tokens.lastOrNull() as? GlideToken.Swipe
        val offerBack = backspaced?.takeIf { twoThumb && !commit }
        // The other thumb is still drawing a stroke, whose preview is on
        // screen: this tap joins the word under it, and the stroke's next
        // preview already reads it in. Clearing that preview here, and putting
        // a reading without the stroke on the strip, is what made the two
        // thumbs' feedback flicker against each other (#678). Previews from
        // before this tap are still retired by the generation below.
        val strokeLive = !commit && _uiState.value.glideWord != null
        val generation = ++duetGeneration
        gestureGeneration.incrementAndGet()
        suggestionJob?.cancel()
        duetJob?.cancel()
        if (!strokeLive) clearGlidePreview()
        duetJob = serviceScope.launch {
            val shown = withContext(Dispatchers.Default) { readDuet(tokens, lone, keys, keyWidthPx, literal) }
            val split = withContext(Dispatchers.Default) {
                when {
                    offerBack != null -> loneSwipeWord(offerBack.points, keys, keyWidthPx)?.let { tail ->
                        DuetSplit("↪ $tail", null, tail, offerBack, keys, keyWidthPx)
                    }
                    headWord != null && lastSwipe != null -> {
                        val head = if (headWord.active) {
                            readDuet(
                                headWord.snapshot(), headWord.loneSwipe(), keys, keyWidthPx, headWord.literal(),
                            )?.word
                        } else {
                            headWord.typedText()
                        }
                        val tail = loneSwipeWord(lastSwipe.points, keys, keyWidthPx)
                        if (head.isNullOrEmpty() || tail.isNullOrEmpty()) {
                            null
                        } else {
                            DuetSplit("$head $tail", head, tail, lastSwipe, keys, keyWidthPx)
                        }
                    }
                    else -> null
                }
            }
            if (generation != duetGeneration) return@launch
            duetSplit = split
            val ic = currentInputConnection ?: return@launch
            if (commit && shown?.complete != true) {
                // #595 in ordinary glide, where the lift *is* the word's end:
                // typed letters and a swipe that make no word together are two
                // words after all, which is what ordinary glide would have made
                // of them. A lone swipe that reads as nothing types nothing.
                val last = tokens.lastOrNull() as? GlideToken.Swipe
                duetWord.clear()
                if (last == null || tokens.size < 2 || composing.isEmpty()) return@launch
                commitComposing(ic, autocorrect = false)
                commitGestureLeadingSpace(ic, _uiState.value)
                duetShift = _uiState.value.shiftState
                duetWord.addSwipe(last.points, keys, keyWidthPx)
                redecodeDuet(commit)
                return@launch
            }
            // Two-thumb typing never drops a gesture here: an unfinished word
            // shows what it has, and only its end decides what is typed.
            shown ?: return@launch
            showDuet(ic, shown, generation)
            // A reopened word the swipe did not carry on is two words (#747).
            if (!strokeLive && !commit && !reopenedHolds(shown.complete)) {
                splitReopenedWord(ic)
                return@launch
            }
            when {
                commit -> commitDuet(ic)
                strokeLive && _uiState.value.glideWord != null -> Unit
                shown.complete -> _uiState.update { it.copy(suggestions = withSplitChip(shown.alternates, split)) }
                // Two words that make none together: the split is the offer.
                split != null -> _uiState.update { it.copy(suggestions = listOf(split.chip)) }
                // Nothing finishes yet: the strip offers what the start on
                // screen completes to, as it does for typed letters, rather
                // than going blank until a gesture makes a word (#678).
                else -> refreshSuggestions()
            }
        }
    }

    /** [swipe] read on its own, as a one-swipe word is; off the main thread. */
    private fun loneSwipeWord(swipe: List<GesturePoint>, keys: List<KeyCenter>, keyWidthPx: Float): String? =
        glideDecode(swipe, keys, keyWidthPx, guessAhead = false).words.firstOrNull()

    /**
     * [words] with the split chip after the merged reading and the one beside
     * it (#832): offered every time, never the word a Space would type.
     */
    private fun withSplitChip(words: List<String>, split: DuetSplit?): List<String> {
        if (split == null || split.chip in words) return words
        return words.toMutableList().apply { add(minOf(2, size), split.chip) }
    }

    /**
     * Splits the last swipe off a two-thumb word (#832): the head goes in as
     * written, with the gesture space, and the swipe starts the next word,
     * open and composing, so taps and swipes join it and its own word end
     * types it. After the all-thumbs-up pause the merged word and its space
     * come back out first, and what they taught is taken back the way a pick
     * over a gesture word takes it back.
     */
    private fun splitOffLastSwipe(ic: InputConnection, split: DuetSplit) {
        val state = _uiState.value
        val shift = duetShift
        ic.beginBatchEdit()
        if (split.committed) {
            val merged = lastGestureWord
            val len = merged?.let { glideCommitLength(ic, it) } ?: 0
            if (merged == null || len <= 0) {
                ic.endBatchEdit()
                return
            }
            ic.deleteSurroundingText(len, 0)
            learningBuffer.drop(merged)
            unlearnHand()
            syncPreviousWordFromField(ic)
        }
        lastGestureWord = null
        lastGestureStroke = null
        lastRevertible = null
        stripReplacesGestureWord = false
        val raw = split.head ?: composing.toString()
        val head = if (split.head == null) {
            raw
        } else {
            when (shift) {
                ShiftState.CAPS_LOCK -> raw.uppercaseKeepingLength()
                ShiftState.ON -> raw.replaceFirstChar { it.uppercase() }
                ShiftState.OFF -> raw
            }
        }
        // The setter ends the gestures and any read of them still running.
        composing = StringBuilder(head)
        updateComposingText(ic)
        commitComposing(ic, autocorrect = false, fixApostrophes = state.settings.autoText.apostrophe)
        commitGestureSpace(ic, state)
        // A letter's worth of word already follows that space: the next Space
        // ends the new word rather than confirming this one's space.
        pendingWordSpace = false
        allUpSpace = null
        // The tail is its own word, in lower case unless caps lock is on.
        duetShift = if (shift == ShiftState.CAPS_LOCK) ShiftState.CAPS_LOCK else ShiftState.OFF
        duetWord.clear()
        duetWord.addSwipe(split.swipe.points, split.keys, split.keyWidthPx)
        allUpArmed = true
        ic.endBatchEdit()
        redecodeDuet(commit = false)
        // After the pause every thumb is already up: the new word's pause starts now.
        if (split.committed) onAllThumbsUp()
    }

    /** Puts [shown] in the composing region as the reading of [generation]. */
    private fun showDuet(ic: InputConnection, shown: DuetShown, generation: Int) {
        val word = when (duetShift) {
            ShiftState.CAPS_LOCK -> shown.word.uppercaseKeepingLength()
            ShiftState.ON -> shown.word.replaceFirstChar { it.uppercase() }
            ShiftState.OFF -> shown.word
        }
        keepDuet = true
        try {
            composing = StringBuilder(word)
        } finally {
            keepDuet = false
        }
        duetShownGeneration = generation
        duetShownAlternates = shown.alternates
        duetShownComplete = shown.complete
        composingCaseTrusted = duetShift == ShiftState.OFF
        updateComposingText(ic)
    }

    /**
     * The word is ending while its latest gesture is still being read: read it
     * here, on the spot, and show that, so the commit that follows types the
     * whole word (#640). The decode in flight is cancelled; it was reading the
     * same gestures.
     */
    private fun settleDuet(ic: InputConnection) = trace(ImeTrace.SETTLE_DUET) {
        duetJob?.cancel()
        duetSettles++
        val generation = duetGeneration
        val shown = readDuet(
            duetWord.snapshot(), duetWord.loneSwipe(), duetWord.keys, duetWord.keyWidthPx, duetWord.literal(),
        ) ?: return@trace
        showDuet(ic, shown, generation)
    }

    /** Test seam: how many times a two-thumb word was read on the main thread (#744). */
    internal var duetSettles = 0

    /**
     * The word's gestures with [points] as one more swipe, for a preview of a
     * stroke still being drawn — or null when the stroke does not join a word,
     * and is previewed as one of its own.
     */
    private fun duetPreviewTokens(
        state: KeyboardUiState,
        points: List<GesturePoint>,
        keys: List<KeyCenter>,
        keyWidthPx: Float,
    ): List<GlideToken>? {
        if (!swipeJoinsWord(state)) return null
        val word = when {
            duetWord.active -> duetWord.copy()
            composingIsTyped() ->
                DuetWord().takeIf { it.seed(composing, composingTouchFrame(), keys, keyWidthPx) } ?: return null
            // A new word whose first strokes overlap (#871): both thumbs'
            // strokes from the start, not one until the other lifts.
            composing.isEmpty() && liveDuetStrokes.size > 1 -> DuetWord()
            else -> return null
        }
        // The whole word: every stroke still down, this one among them, in
        // the order they began (#849).
        val live = liveDuetStrokes.values.ifEmpty { listOf(points) }
        for (stroke in live) word.addSwipe(stroke, keys, keyWidthPx)
        return word.snapshot()
    }

    /**
     * A word built from several gestures, read like a stroke: the same sources,
     * blacklist, rerank and casing. A lone swipe in [tokens] is read by the
     * stroke decoder, which also reads its pauses and loops; [points] is that
     * swipe where the caller has it to hand.
     */
    private fun duetReading(
        tokens: List<GlideToken>,
        points: List<GesturePoint>?,
        keys: List<KeyCenter>,
        keyWidthPx: Float,
    ): GlideReading {
        if (!DuetBeam.needsDuet(tokens)) {
            val stroke = points ?: (tokens.singleOrNull() as? GlideToken.Swipe)?.points
                ?: return GlideReading.NONE
            return glideDecode(stroke, keys, keyWidthPx)
        }
        val engine = suggestionEngine ?: return GlideReading.NONE
        val decoded = engine.glideTokens(
            tokens = tokens,
            keys = keyMapFor(keys, keyWidthPx),
            keyWidth = keyWidthPx,
            limit = glideCandidateLimit(),
            previousWord = previousWord,
            previousWord2 = previousWord2,
            previousWord3 = previousWord3,
            recentWords = recentWords.toList(),
        )
        if (decoded.isEmpty()) return GlideReading.NONE
        val (words, scores) = offerApostrophes(
            decoded.map { restoreApostrophe(it.word) ?: it.word },
            decoded.map { it.score },
        )
        return GlideReading(
            words = words,
            closeCall = false,
            scores = scores,
        )
    }

    /**
     * Decodes a swipe drawn over the letter keys and commits the best word.
     * Alternates go to the suggestion bar; tapping one replaces the word.
     */
    fun onGesture(
        points: List<GesturePoint>,
        keys: List<KeyCenter>,
        keyWidthPx: Float,
        /**
         * The ambiguity picker's answer. A [GlideVerdict.Word] is committed in
         * place of the decoder's own first choice — unconditionally, since the
         * stroke was frozen the moment the picker opened and the word was on
         * screen when the finger lifted — and otherwise treated identically:
         * it is still learned, still spaced, still revertible, and its
         * alternates still reach the strip with it in front. A
         * [GlideVerdict.Cancel] types nothing.
         */
        verdict: GlideVerdict = GlideVerdict.Leader(),
    ) {
        // This stroke is lifted: it joins the word's gestures, not the live ones.
        points.firstOrNull()?.let { liveDuetStrokes.remove(it.t) }
        stopVoiceForManualInput()
        val state = _uiState.value
        if (!glideAllowed(state)) return
        if (keys.isEmpty()) return
        syncGlideTriggers(state)
        if (verdict is GlideVerdict.Cancel) {
            cancelGlide()
            return
        }
        // A test run takes the word: the field behind the panel never sees it.
        if (state.typingTestActive) {
            typingTestGlide(listOf(points), keys, keyWidthPx, verdict)
            return
        }
        // The word card's spelling bar takes the word, at its own caret (#204).
        if (state.wordSpellActive) {
            wordSpellGlide(points, keys, keyWidthPx, verdict, shiftForGlide(state.shiftState, verdict.caseAt(0)))
            return
        }
        // Every other keyboard-owned field takes it at its own caret (#161):
        // the search queries, the AI instruction, a plugin's box, the Find
        // fields, the Learn speller. Nothing reaches the app behind the panel.
        state.captureTarget()?.let { target ->
            // A tap that rolled into a swipe under two thumbs is the tap
            // there too (#831), not a one-letter glide spaced off its word.
            if (verdict is GlideVerdict.Leader && duetStrokeAsTap(state, points, keys, keyWidthPx)) return
            captureGlide(
                target, listOf(points), keys, keyWidthPx, verdict,
                shiftForGlide(state.shiftState, verdict.caseAt(0)),
            )
            return
        }

        val shiftAtGesture = shiftForGlide(state.shiftState, verdict.caseAt(0))
        // Retires every preview from this stroke, in flight or queued, once
        // the word on screen is read: the lift owes it the word (#816).
        gestureGeneration.incrementAndGet()
        suggestionJob?.cancel()
        gestureJob?.cancel()
        val shownAtLift = previewGate.shown
        clearGlidePreview()
        // A quick flick straight up off a key carrying a word takes that word.
        // Asked here, at the lift: a flick is over in a tenth of a second, so
        // there is nothing to win by claiming the pointer on the way down, and
        // claiming it there would mean fighting this loop for every upward
        // stroke instead of letting it decode the ones that are glides.
        //
        // Only when the picker did not answer. A frozen stroke was the user
        // choosing, and what they chose is not a key's word.
        if (verdict is GlideVerdict.Leader && octopusFlickPick(state, points, keys, keyWidthPx)) return
        // A tap that rolled into a swipe under two thumbs is still the tap.
        if (duetStrokeAsTap(state, points, keys, keyWidthPx)) return
        // Two-thumb typing, or a swipe finishing typed letters: the stroke
        // joins the word in progress instead of being one (#638, #595).
        if (duetSwipe(state, points, keys, keyWidthPx, shiftAtGesture)) return
        if (state.composer === PinyinComposer || state.composer.glidesKanaReadings) {
            readingGlide(points, keys, keyWidthPx)
            return
        }
        gestureJob = serviceScope.launch {
            val reading = withContext(Dispatchers.Default) {
                glideDecode(points, keys, keyWidthPx)
            }
            val candidates = reading.words
            // The words before this one, as the decode saw them, for the
            // check-up's replay below: by then the commit has moved them on.
            val checkupContext = if (state.settings.gesture.checkupMeasure) {
                listOf(previousWord, previousWord2, previousWord3) to recentWords.toList()
            } else {
                null
            }
            // One stroke, one observation: recorded here on the committing
            // decode rather than in `glideDecode`, which also runs for every
            // preview of a stroke still being drawn.
            reading.sandboxAnswered?.let { noteSandboxOutcome(it) }
            // Debug builds only: typed content must never be logged in release.
            if (applicationInfo.flags and android.content.pm.ApplicationInfo.FLAG_DEBUGGABLE != 0) {
                android.util.Log.d(
                    "WMKeyboard",
                    "gesture shift=$shiftAtGesture candidates=$candidates",
                )
            }
            // An explicit pick survives an empty decode: the picker showed the
            // word, and the finger lifted on it.
            val chosen = (verdict as? GlideVerdict.Word)?.word
            if (candidates.isEmpty() && chosen == null) return@launch
            val ic = currentInputConnection ?: return@launch
            // A word swiped over a highlighted one replaces it where it stands,
            // so what follows it is the field's own text (#955).
            val overSelection = hasSelection(ic)

            // The tapped word this glide is finishing gets the same treatment
            // a space would have given it: without this a tapped "i" followed
            // by a glided word committed in lower case, because the glide's own
            // space never goes through onSpace (#46).
            commitComposing(ic, autocorrect = false, fixApostrophes = state.settings.autoText.apostrophe)
            // Lifting on a picker word that was not the leader is a pick over
            // the leader, remembered against the pair (issue #52).
            if (chosen != null && candidates.isNotEmpty() && chosen != candidates.first()) {
                noteGlidePreference(rejected = candidates.first(), chosen = chosen)
            }
            // An explicit pick beats everything. Otherwise the word on
            // screen wins the lift while the finished stroke still ranks it
            // near its own leader, so what was shown is what gets typed.
            val picked = chosen
                ?: previewGate.commit(
                    candidates, reading.scores, state.settings.gesture.previewSteadiness, shownAtLift,
                )
                ?: candidates.first()
            val drawn = reading.guesses[picked]
            val strip = when {
                drawn != null -> glideEarlyLiftStrip(picked, drawn, candidates)
                chosen != null -> glideStripOrder(candidates, chosen)
                else -> candidates
            }
            val word = glideCased(picked, shiftAtGesture, verdict.caseAt(0), points, keys, keyWidthPx)
            gestureWordShifted = shiftAtGesture != ShiftState.OFF || verdict.caseAt(0) != GlideCase.None
            commitGestureLeadingSpace(ic, state)
            // A stroke that read a text-expansion trigger types what the
            // trigger stands for, as a space after the typed trigger would.
            glidedExpansion(ic, state, word)?.let { expanded ->
                if (expanded.cursorOffset >= expanded.text.length) commitGestureSpace(ic, state)
                armRevertGuard()
                consumeShift()
                return@launch
            }
            ic.commitText(word, 1)
            // The word and the space that finishes it are one edit, and
            // nothing may suspend between them. `commitText` replaces the
            // composing region whenever there is one, and the commit's own
            // selection echo arms a region over this very word — instantly
            // when the editor shares this process, as the setup wizard's
            // "try your keyboard" box does. Every yield in between let that
            // echo in first, and the space then overwrote the word instead
            // of following it: the field kept a lone space, and the word
            // itself only surfaced when the next stroke flushed the
            // stranded buffer, one swipe late (#113).
            //
            // Arming [lastGestureWord] here is the other half of the same
            // fix. It is the flag [restartSuggestionsAtCursor] tests before
            // it arms a region at all, and it too was being set after the
            // learning hop below, so the guard that exists for exactly this
            // could not win the race it was written for.
            lastGestureWord = word
            stripReplacesGestureWord = true
            commitGestureSpace(ic, state, overSelection)
            armRevertGuard()
            recordStat {
                onGlideWord(
                    word.length,
                    glideDistanceMm(points),
                    System.currentTimeMillis(),
                    startUptimeMs = points.firstOrNull()?.t ?: 0L,
                )
            }
            learn(
                word,
                caseTrusted = glideCaseTrusted(shiftAtGesture, state, verdict.caseAt(0)),
                origin = WordOrigin.GLIDE,
            )
            // What the stroke could have been, kept against the word it
            // became, so coming back to this word offers the swipe's own
            // readings instead of spellings of the word standing there (#115).
            glideReadings.remember(word, strip)
            // The stroke's shape rides with the word in the learning buffer
            // and reaches the shape store only when the word settles; the
            // hand model learns on the spot and retracts on undo instead.
            // A word finished early teaches only what was drawn (#262).
            val (hand, shape) = withContext(Dispatchers.Default) {
                learnGlideStroke(points, keys, keyWidthPx, word, drawn)
            }
            if (shape != null) {
                val targetWord = chosen ?: word
                learningBuffer.attachGlide(targetWord, shape)
            }
            val stroke = GlideStroke(points, keys, keyWidthPx, shape)
            lastGestureStroke = stroke
            // The path itself rides the same entry the readings went into, so
            // coming back to this word can search it against every list, not
            // only the one the decode was allowed to see (#135).
            glideReadings.attach(word, stroke)
            lastHandAdjustment = hand
            // The check-up replays the stroke under the candidate weights,
            // off this thread, and keeps only the words that come out (#966).
            if (checkupContext != null) {
                measureGlideForCheckup(points, keys, keyWidthPx, word, candidates.first(), checkupContext)
            }
            consumeShift()
            val floating = nextWordOctopus()
            val chips = nextWordEmoji()
            glideStripPages(strip)
            _uiState.update {
                it.copy(suggestions = strip, octopus = floating, emojiSuggestions = chips)
            }
        }
    }

    /**
     * The strip after a lift that took [word] on the strength of a guess,
     * the stroke having drawn only [drawn] of it (issue #168).
     *
     * Lifting early is a choice, the same one a tap on a suggestion makes:
     * the user took the word they were shown. The stroke's other readings —
     * [candidates], words that end where the finger stopped — are then
     * beside the point, because the finger did not stop at the end of
     * anything. What the user may still want is a neighbour of the word:
     * "dictionaries" beside "dictionary", "functional" beside
     * "functionality". Those go first, and the readings fill whatever
     * slots are left, so a lift that was not a choice after all still has
     * them.
     */
    private suspend fun glideEarlyLiftStrip(
        word: String,
        drawn: String,
        candidates: List<String>,
    ): List<String> {
        val engine = suggestionEngine ?: return glideStripOrder(candidates, word)
        val kin = withContext(Dispatchers.Default) {
            engine.glideKin(drawn, word, glideCandidateLimit() - 1)
        }
        val seen = HashSet<String>(kin.map { it.lowercase() }).apply { add(word.lowercase()) }
        return listOf(word) + kin + candidates.filterNot { it.lowercase() in seen }
    }

    /**
     * [suggested] with the readings of the glide that wrote the [word] starting
     * at [start] in front of it.
     *
     * This is what makes proofreading a swipe *correcting* rather than
     * retyping. The strip's own answer is about the letters standing in the
     * field, and after a misread swipe those letters are not the ones the
     * finger drew, so the word the user wants is nowhere in it. The stroke's
     * own runners-up are exactly that word, and the pick that takes one is
     * already wired to teach the pair (see `noteGlidePreference`), so the
     * keyboard learns the stroke as well as fixing the word (#115).
     */
    private fun withGlideReadings(word: String, start: Int, suggested: List<String>): List<String> {
        val readings = glideReadings.readingsAt(word, start)
        if (readings.isEmpty()) return suggested
        val seen = HashSet<String>(readings.map { it.lowercase() })
        return readings + suggested.filterNot { it.lowercase() in seen }
    }

    /**
     * Whether a glided word's capitals are the user's own.
     *
     * Only a shift the user pressed themselves. A glide types no capital: the
     * finger draws letters and the *keyboard* decides how to spell what it
     * read, out of the very case memory this answer feeds. Treating an
     * unshifted stroke as evidence closed that loop — "Mark" came back off the
     * decoder, was learned as a capital, and voted its own capital up again on
     * every swipe, so a word that is written both ways could never be written
     * the plain way again and the personal dictionary filled with proper nouns
     * the user never capitalized (#115).
     *
     * Caps lock is out for the reason it always was: it says the letters are
     * upper case, not that the word is. So is auto-capitalize's shift at a
     * sentence start, which is the keyboard's capital and not the user's.
     *
     * A word whose only spelling anywhere is capitalized keeps it regardless —
     * that comes from the dictionary at display time
     * ([SuggestionEngine.displayForm]) and needs no vote here.
     */
    private fun glideCaseTrusted(
        shiftAtGesture: ShiftState,
        state: KeyboardUiState,
        case: GlideCase,
    ): Boolean = when (case) {
        // Drawn through the shift key on the way: as deliberate as pressing it,
        // and the whole point of the gesture is to say "this word is a name".
        // Twice is a shout, and a shout is not a spelling — the rule caps lock
        // has always been under.
        is GlideCase.Word -> case.times == 1
        // Letters drawn one by one are a spelling — `LeanType` is exactly the
        // kind of word this vote exists for (#163) — and a stroke that ended
        // on the key is the shout again.
        is GlideCase.Letters -> !case.shout && case.cuts.isNotEmpty()
        // Not at a sentence start, where a capital is the sentence's (#679).
        GlideCase.None -> shiftAtGesture == ShiftState.ON && state.shiftPressedByUser &&
            previousWord != WordContext.SENTENCE_START
    }

    /**
     * Whether every capital in [suggestion] is one [typed] already carried.
     *
     * The same question [glideCaseTrusted] asks, for a word taken off the
     * strip. The chip is drawn in the spelling the engine offers, so tapping
     * "Mark" after typing "mark" is choosing the word, not the capital — and
     * counting it as a spelling let the strip vote its own suggestion into the
     * user's case memory (#115). A capital past the end of what was typed
     * ("mac" → "MacDonald") is the dictionary's for the same reason.
     *
     * Surrogate pairs answer false to [Char.isUpperCase] and so are simply
     * skipped: an unanswerable character must not read as evidence.
     */
    private fun typedCarriesCase(typed: CharSequence, suggestion: String): Boolean {
        for ((at, ch) in suggestion.withIndex()) {
            if (!ch.isUpperCase()) continue
            if (typed.getOrNull(at)?.isUpperCase() != true) return false
        }
        return true
    }

    /**
     * Keeps [SuggestionEngine.glideTriggers] in step with the snippets and the
     * personal dictionary's shortcuts, so a stroke can read a trigger (#170).
     *
     * Asked before every stroke on the main thread, where the snippet store is
     * read. Both inputs come back as the same objects until they change, so the
     * usual answer is three identity checks and nothing rebuilt.
     */
    private fun syncGlideTriggers(state: KeyboardUiState) {
        val engine = suggestionEngine ?: return
        val snippets = snippetStore.expandingTriggers()
        val shortcuts = if (state.settings.suggestionStrip.expandUserDictShortcuts) {
            userDictShortcuts
        } else {
            emptyMap()
        }
        val imported = activeImportedShortcuts()
        if (engine === glideTriggersEngine && snippets === glideTriggerSnippets &&
            shortcuts === glideTriggerShortcuts && imported === glideTriggerImported
        ) {
            return
        }
        glideTriggersEngine = engine
        glideTriggerSnippets = snippets
        glideTriggerShortcuts = shortcuts
        glideTriggerImported = imported
        engine.glideTriggers = SuggestionEngine.triggerSource(snippets + shortcuts.keys + imported.keys)
    }

    /** Whether a glided trigger expands at all: not under a transliterating or converting composer. */
    private fun glideExpands(state: KeyboardUiState): Boolean =
        !state.composer.isTransliterating && !state.composer.isConversion

    /** The snippet a glided [word] fires, or null. A snippet that asks first never fires on a glide. */
    private fun glidedSnippet(word: String): Snippet? =
        snippetStore.matchTrigger(word)?.takeIf { !snippetStore.offers(it) }
            // A glide's lift is the keystroke an immediate trigger waits for.
            ?: snippetStore.matchImmediateWord(word)

    /** The shortcut phrase a glided [word] expands to, or null. */
    private fun glidedShortcut(state: KeyboardUiState, word: String): String? = shortcutExpansion(state, word)

    /**
     * What typing [word] in full offers as a shortcut: the personal
     * dictionary's (A28) when that setting is on, else an imported
     * dictionary's for a language feeding the strip.
     */
    private fun shortcutExpansion(state: KeyboardUiState, word: String): String? {
        val key = word.lowercase()
        if (state.settings.suggestionStrip.expandUserDictShortcuts) userDictShortcuts[key]?.let { return it }
        return activeImportedShortcuts()[key]
    }

    /**
     * [importedShortcuts] for the languages feeding the strip, merged with the
     * one on screen winning. The same object comes back until either input
     * changes, which is what lets [syncGlideTriggers] skip its rebuild.
     */
    private fun activeImportedShortcuts(): Map<String, String> {
        val all = importedShortcuts
        if (all.isEmpty()) return emptyMap()
        val langs = stripListLanguages()
        activeShortcutsMemo?.let { (from, forLangs, merged) ->
            if (from === all && forLangs == langs) return merged
        }
        val merged = HashMap<String, String>()
        for (id in langs.asReversed()) all[id]?.let(merged::putAll)
        activeShortcutsMemo = Triple(all, langs, merged)
        return merged
    }

    /**
     * What a lift would type for each of [words] that is a trigger, keyed by
     * the raw word, so the pill and the strip can show the expansion rather
     * than a trigger that never lands (#205). Read through
     * [glideExpansionCache], so a snippet with choices is not re-rolled on
     * every preview frame.
     */
    private fun glideExpansionsFor(
        state: KeyboardUiState,
        words: List<String>,
    ): Map<String, GlideExpansion> {
        if (!glideExpands(state)) return emptyMap()
        return buildMap {
            for (word in words) {
                val expansion = if (glideExpansionCache.containsKey(word)) {
                    glideExpansionCache[word]
                } else {
                    glideExpansionOf(state, word).also { glideExpansionCache[word] = it }
                }
                if (expansion != null) put(word, expansion)
            }
        }
    }

    /**
     * [word]'s expansion in each casing a stroke can ask for, cased the way
     * [glidedExpansion] would type it, or null when [word] is not a trigger.
     * Types nothing. The selection is left out of a snippet's context: reading
     * it is a round trip to the app for every new word a stroke reads.
     */
    private fun glideExpansionOf(state: KeyboardUiState, word: String): GlideExpansion? {
        glidedSnippet(word)?.let { snippet ->
            val text = SnippetStore.expandWithCursor(
                snippet.text,
                context = snippetContext(currentInputConnection, withSelection = false),
            ).text
            return GlideExpansion(
                plain = text,
                capitalized = SnippetStore.casingFor(snippet, word.replaceFirstChar { it.uppercase() }).apply(text),
                shouted = SnippetStore.casingFor(snippet, word.uppercase()).apply(text),
            )
        }
        val phrase = glidedShortcut(state, word) ?: return null
        return GlideExpansion(
            plain = phrase,
            capitalized = casedLikeTrigger(phrase, word.replaceFirstChar { it.uppercase() }),
            shouted = casedLikeTrigger(phrase, word.uppercase()),
        )
    }

    /**
     * Types the expansion of a glided [word] that is a text-expansion trigger —
     * a snippet's trigger or a shortcut from Android's personal dictionary — in
     * place of the word, and returns it. Null, having typed nothing, when
     * [word] is not a trigger (#170).
     *
     * A typed trigger expands on the space that ends it. A glide has no such
     * key: it commits the moment the finger lifts, so the expansion happens
     * here instead. A dictionary shortcut, which a typed one only offers as a
     * chip, expands outright for the same reason: a stroke's reading is
     * committed, not offered, and the shortcut is what the stroke read.
     *
     * Revertible to [word] with one backspace, which the typed plain trigger
     * is not. A stroke is a guess in a way a typed word is not, and "I meant
     * the word" has to be one key away.
     */
    private fun glidedExpansion(
        ic: InputConnection,
        state: KeyboardUiState,
        word: String,
    ): SnippetStore.Companion.Expanded? {
        if (!glideExpands(state)) return null
        val snippet = glidedSnippet(word)
        val shortcut = if (snippet == null) glidedShortcut(state, word) else null
        val expanded = when {
            snippet != null -> SnippetStore.expandWithCursor(
                snippet.text,
                context = snippetContext(ic),
                casing = SnippetStore.casingFor(snippet, word),
            )
            shortcut != null -> casedLikeTrigger(shortcut, word)
                .let { SnippetStore.Companion.Expanded(it, it.length) }
            else -> return null
        }
        commitSplitAtCaret(ic, expanded.text, expanded.cursorOffset)
        // Never arms the terminator swallow: that exists for the space that
        // fired a typed trigger, and a glide pressed no space to swallow.
        afterSnippetExpansion(inserted = expanded.text, original = word, caretParked = false)
        if (snippet != null) {
            publishSwapSet(
                snippet = snippet,
                typed = word,
                inserted = expanded.text,
                insertedCaret = expanded.cursorOffset,
                original = word,
            )
        }
        return expanded
    }

    /**
     * [phrase] with the capitals the glide put on [trigger]: a shouted trigger
     * shouts its phrase, and a capital from shift or a sentence start lands on
     * the phrase's first letter.
     */
    private fun casedLikeTrigger(phrase: String, trigger: String): String {
        val letters = trigger.filter(Char::isLetter)
        return when {
            letters.length > 1 && letters.all(Char::isUpperCase) -> phrase.uppercase()
            letters.firstOrNull()?.isUpperCase() == true -> phrase.replaceFirstChar { it.uppercase() }
            else -> phrase
        }
    }

    /**
     * Types the space that follows a glided word, so the next word — glided or
     * tapped — does not run into it. Skipped when the text already continues
     * with one: a word glided back into the middle of a sentence has a space
     * after it already, and a second would leave a double gap. A line break
     * after the caret is not one of those — see [spacedAfterCaret].
     *
     * Arms [pendingWordSpace], which is what lets punctuation typed straight
     * afterwards take the space back and a space press be swallowed rather than
     * doubled.
     *
     * [replacedSelection] is a word swiped over a highlighted one. A web editor
     * steps over nothing ([spaceToStepOver]) because its text after the caret
     * may be a suggestion that is not there, but none shows while a word is
     * highlighted, so the space after a replaced word is the field's own and
     * is stepped over there too rather than doubled (#955).
     */
    private fun commitGestureSpace(ic: InputConnection, state: KeyboardUiState, replacedSelection: Boolean = false) {
        if (!state.settings.gesture.autoSpaceAfterGlide) return
        // A word glided back into the middle of a sentence lands in front of
        // the space that was already there; the caret goes past it, ready for
        // the next word, the same as after a typed one (#662).
        if (stepOverFollowingSpace(ic, trustWeb = replacedSelection)) return
        // In front of a mark that closes up onto the word ("question⌶?") the
        // space waits for a letter, as a strip pick's does (#679): typed now,
        // a word glided back in before a full stop read "word ." (#974).
        if (markHugsCaretWord(ic.getTextAfterCursor(1, 0))) {
            deferredWordSpace = true
            armRevertGuard()
            return
        }
        ic.commitText(" ", 1)
        pendingWordSpace = true
    }

    /**
     * Types the space that goes *in front* of a glided word, so two swiped words
     * do not run together and a word swiped onto the end of typed text does not
     * either.
     *
     * Not every character earns one: a word swiped after an opening bracket or
     * quote belongs against it, and `he said "` then a glided "hello" used to
     * come out as `he said " hello` (issue #34). [spacesBeforeGlidedWord] holds
     * that rule, and reads a line's worth of text rather than one character
     * because the double quote is only an opener or a closer by what came before
     * it.
     *
     * Its own gate, not [GestureSettings.autoSpaceAfterGlide]'s: that switch
     * names the space that follows a glide and only that one. This one is off
     * only under a keyboard mode whose auto-space override says every space in
     * the field is the user's (#184).
     */
    private fun commitGestureLeadingSpace(ic: InputConnection, state: KeyboardUiState) {
        // A space owed to the next letter after a closing mark (#974) is owed
        // no longer: this word brings its own, or joins on as asked.
        deferredWordSpace = false
        // No space asked for this word to join the one before it (#851), or
        // was armed for whatever comes next, which this word is (#863).
        if (glueNextWord || _uiState.value.noSpaceArmed) {
            // Armed rather than tapped: a hold only arms, so the keyboard's own
            // space after the word before is still there. This word is the
            // armed key and joins on, glide `foot`, hold, glide `ball` giving
            // "football", so that space comes back out. A space the user typed
            // stays, as it does in front of an armed mark (`best .tld`).
            if (!glueNextWord && pendingWordSpace && ic.getTextBeforeCursor(1, 0)?.toString() == " ") {
                ic.deleteSurroundingText(1, 0)
                pendingWordSpace = false
            }
            glueNextWord = false
            setNoSpaceArmed(false)
            return
        }
        if (!state.settings.gesture.autoSpaceBeforeGlide) return
        val before = ic.getTextBeforeCursor(QUOTE_CONTEXT_CHARS, 0)?.toString().orEmpty()
        if (spacesBeforeGlidedWord(before, state.fieldKind)) ic.commitText(" ", 1)
    }

    /**
     * How many characters the last glided [word] occupies right behind the
     * caret, space included — see the top-level [glideCommitLength] for what
     * the measurement means and why both callers need it.
     */
    private fun glideCommitLength(ic: InputConnection, word: String): Int {
        // Measured as the field holds the word: styled, under Fancy Text (#950).
        val field = fieldForm(word)
        return glideCommitLength(
            ic.getTextBeforeCursor(field.length + 1, 0)?.toString().orEmpty(),
            field,
        )
    }

    /**
     * Multi-word glide: one continuous stroke that crossed the spacebar was
     * split into a word segment per crossing. Decodes and commits them in
     * order, spacing between them, so the whole phrase lands from one swipe.
     * Only the first word honours a held shift; the alternates of the last
     * word go to the suggestion bar, so tapping one fixes the final word — the
     * same as a single glide. The ambiguity picker's [verdict] is about that
     * last word too: a stroke can only pause to ask on the segment it is
     * drawing when it stops.
     */
    fun onGestureWords(
        segments: List<List<GesturePoint>>,
        keys: List<KeyCenter>,
        keyWidthPx: Float,
        verdict: GlideVerdict = GlideVerdict.Leader(),
    ) {
        stopVoiceForManualInput()
        val state = _uiState.value
        if (!glideAllowed(state)) return
        if (keys.isEmpty() || segments.isEmpty()) return
        syncGlideTriggers(state)
        if (verdict is GlideVerdict.Cancel) {
            cancelGlide()
            return
        }
        // A test run takes the words: the field behind the panel never sees them.
        if (state.typingTestActive) {
            typingTestGlide(segments, keys, keyWidthPx, verdict)
            return
        }
        // …and so does every other keyboard-owned field, one word per segment
        // at its own caret (#161).
        state.captureTarget()?.let { target ->
            captureGlide(
                target, segments, keys, keyWidthPx, verdict,
                shiftForGlide(state.shiftState, verdict.caseAt(0)),
            )
            return
        }

        val shiftAtGesture = shiftForGlide(state.shiftState, verdict.caseAt(0))
        // Retires every preview from this stroke, in flight or queued.
        gestureGeneration.incrementAndGet()
        suggestionJob?.cancel()
        gestureJob?.cancel()
        clearGlidePreview()
        val chosen = (verdict as? GlideVerdict.Word)?.word
        gestureJob = serviceScope.launch {
            val ic = currentInputConnection ?: return@launch
            // Flush any composing text before the first glided word, finished
            // the way a space would have finished it (see onGesture).
            commitComposing(ic, autocorrect = false, fixApostrophes = state.settings.autoText.apostrophe)
            var lastWords: List<String> = emptyList()
            var committedAny = false
            // Whether the last thing typed was a snippet that left the caret
            // inside itself, where a trailing space does not belong.
            var caretParked = false
            segments.forEachIndexed { index, segment ->
                // Every segment but the last ends where the finger turned
                // into the space bar, and every one but the first starts
                // where it came back out (#968). Those walks are not letters:
                // the decoder is told how many samples they are, so the
                // word's first and last letters are placed by the stroke's
                // shape and not anchored to the bottom-row key the walk
                // happened to pass.
                val openTail = if (index < segments.lastIndex) GlideStroke.openRun(segment, keyWidthPx, atEnd = true) else 0
                val openHead = if (index > 0) GlideStroke.openRun(segment, keyWidthPx, atEnd = false) else 0
                // Decoded inside the loop, not before it: each word is committed
                // and learned as it lands, so the next segment is decoded with
                // the one before it as context.
                var reading = withContext(Dispatchers.Default) {
                    // Only the segment the finger lifted on may finish a word
                    // early: every earlier one ends at the space bar, drawn to
                    // its last letter (#121).
                    glideDecode(
                        segment, keys, keyWidthPx, guessAhead = index == segments.lastIndex,
                        openHead = openHead, openTail = openTail,
                    )
                }
                // A segment the open ends could not read falls back to the
                // stroke with its walks cut off, so a word is not dropped from
                // the middle of a phrase without a second look.
                if (reading.words.isEmpty() && (openHead > 0 || openTail > 0)) {
                    val cut = segment.subList(openHead, segment.size - openTail)
                    if (cut.size >= GLIDE_FALLBACK_MIN_POINTS) {
                        reading = withContext(Dispatchers.Default) {
                            glideDecode(cut, keys, keyWidthPx, guessAhead = index == segments.lastIndex)
                        }
                    }
                }
                val candidates = reading.words
                // The pick belongs to the last segment, and survives an empty
                // decode of it the way a single glide's pick does.
                val picked = chosen?.takeIf { index == segments.lastIndex }
                if (candidates.isEmpty() && picked == null) return@forEachIndexed
                if (picked != null && candidates.isNotEmpty() && picked != candidates.first()) {
                    noteGlidePreference(rejected = candidates.first(), chosen = picked)
                }
                val leader = picked ?: candidates.first()
                // Only the first word honours the board's shift; a later
                // word's own crossings still reach it (#163).
                val case = verdict.caseAt(index)
                val wordShift = if (index == 0) shiftAtGesture else shiftForGlide(ShiftState.OFF, case)
                val word = glideCased(leader, wordShift, case, segment, keys, keyWidthPx)
                gestureWordShifted = wordShift != ShiftState.OFF || case != GlideCase.None
                commitGestureLeadingSpace(ic, state)
                val expanded = glidedExpansion(ic, state, word)
                if (expanded != null) {
                    caretParked = expanded.cursorOffset < expanded.text.length
                    // An expansion is not a reading: nothing to learn, and no
                    // alternates for the strip to offer in its place.
                    lastWords = emptyList()
                    committedAny = true
                    return@forEachIndexed
                }
                caretParked = false
                ic.commitText(word, 1)
                // Both before the learning hop below, for the reason spelled
                // out in [onGesture]: this is what stops the commit's own echo
                // arming a composing region over the word, which the next
                // segment's leading space — or this stroke's trailing one —
                // would then replace instead of follow (#113). The guard needs
                // the revert anchor as much as the word: an echo that arrives
                // with [lastGestureWord] set but the anchor still pointing at
                // the last stroke reads as a real caret move and disarms the
                // very flag that was just set.
                lastGestureWord = word
                stripReplacesGestureWord = true
                armRevertGuard()
                recordStat {
                    onGlideWord(
                        word.length,
                        glideDistanceMm(segment),
                        System.currentTimeMillis(),
                        startUptimeMs = segment.firstOrNull()?.t ?: 0L,
                    )
                }
                learn(
                    word,
                    // Only the first word of the stroke could have been shifted
                    // at all; the rest carry whatever capitals the dictionary
                    // gave them, which is not evidence — see [glideCaseTrusted].
                    caseTrusted = index == 0 &&
                        glideCaseTrusted(shiftAtGesture, state, verdict.caseAt(index)),
                    origin = WordOrigin.GLIDE,
                )
                // A chained segment teaches nothing about the hand or the
                // word's shape (#968): its ends are the spacebar's edge, and
                // learning from them taught the hand model that every last
                // letter sits at the bar. The word itself is still learned
                // above, as any committed word is.
                val chained = openHead > 0 || openTail > 0
                val (hand, shape) = if (chained) {
                    null to null
                } else {
                    withContext(Dispatchers.Default) {
                        learnGlideStroke(segment, keys, keyWidthPx, word, reading.guesses[leader])
                    }
                }
                if (shape != null) {
                    val targetWord = picked ?: word
                    learningBuffer.attachGlide(targetWord, shape)
                }
                val stroke = GlideStroke(segment, keys, keyWidthPx, shape)
                lastGestureStroke = stroke
                // Each word teaches; only the last is on the undo's reach.
                lastHandAdjustment = hand
                lastWords = if (picked != null) glideStripOrder(candidates, picked) else candidates
                // Only the last word of a chained stroke keeps its readings:
                // it is the one whose alternates are on the strip, and the
                // one a proofreading pass comes back to (#115).
                glideReadings.remember(word, lastWords)
                // And its own segment of the path, for a later full search (#135).
                glideReadings.attach(word, stroke)
                committedAny = true
            }
            if (committedAny) {
                // Only the last word earns one: the words before it were spaced
                // by the leading rule above as each new segment landed.
                if (!caretParked) commitGestureSpace(ic, state)
                armRevertGuard()
                consumeShift()
                val floating = nextWordOctopus()
                val chips = nextWordEmoji()
                glideStripPages(lastWords)
                _uiState.update {
                    it.copy(suggestions = lastWords, octopus = floating, emojiSuggestions = chips)
                }
            }
        }
    }

    // ---- panels ----

    /**
     * A tool the user asked for from the toolbar: the strip's button, the
     * toolbox cell, and the physical keyboard's picker all land here, so a
     * shortcut can never drift from what the button does.
     *
     * Most tools open a panel; the rest are one-shot actions with no panel of
     * their own (a toggle, a cursor move, the settings app).
     */
    fun onToolTap(tool: ToolbarTool) {
        // The toolbar never renders a tool the user has switched off, but a
        // shortcut can still name one: a stored binding outlives the tool
        // leaving the strip. The device-level tests are in [runTool], which the
        // key-bound path ([runToolFromKey]) reaches without this one.
        if (tool !in _uiState.value.settings.enabledTools) return
        runTool(tool)
    }

    /**
     * A tool fired by something that is not the toolbar: a key bound to
     * [KeyAction.Tool], or one of its long-press alternates.
     *
     * Skips the "is it on the toolbar" test [onToolTap] makes, and only that
     * one. A key an author put on their layout is its own reason for the tool to
     * run — the toolbar's set is about what the strip shows, and a layout that
     * had to keep a tool on the strip to reach it from a key would be paying
     * twice for the same thing. Everything the *device* decides still applies:
     * a tool the build lacks and an unusable tool both come out as a key that does
     * nothing, exactly as they do on the toolbar.
     *
     * No focus ring: that is for a physical keyboard ([openToolByKey]). A
     * flick or a key on the screen put it on the first clip, snippet or note,
     * which read as that item being pinned (#612, #665).
     */
    private fun runToolFromKey(tool: ToolbarTool) {
        runTool(tool)
        ensureInputViewShown()
    }

    /**
     * A tool fired by a press and hold on a toolbar button the user bound it to.
     *
     * Skips [onToolTap]'s "is it on the toolbar" test for the reason
     * [runToolFromKey] does: the binding is its own reason for the tool to run.
     * It used to go through [onToolTap], so a hold bound to any tool the user
     * had not also put on the bar — Select line, say, on a fresh install whose
     * setup left most tools off — was dropped without a word (#31). The device's
     * own gates in [runTool] still apply.
     */
    private fun runToolFromHold(tool: ToolbarTool) {
        runTool(tool)
    }

    /**
     * Which of emoji, GIFs and stickers was open last, for the emoji key to
     * reopen when that setting is on (issue #366). The session's memory only:
     * a keyboard that restarts opens on emoji, as a fresh one does.
     */
    private var lastMediaPanel: PanelMode = PanelMode.EMOJI

    /** The panel the emoji key and the emoji tool open; see [mediaOpenerTarget]. */
    private fun emojiOpenerTarget(): PanelMode = _uiState.value.let {
        mediaOpenerTarget(it.panel, lastMediaPanel, it.settings)
    }

    /**
     * The dispatch itself, once the caller's own gating has passed, plus the two
     * tests every caller shares: F-Droid's build ships fewer tools than the enum
     * lists, and a search tool loses its key the moment it is cleared.
     */
    private fun runTool(tool: ToolbarTool) {
        if (!isSupportedTool(tool)) return
        val settings = _uiState.value.settings
        if (!isUsableTool(tool, settings)) return
        toolUsage.record(tool)
        when (tool) {
            ToolbarTool.EMOJI -> onPanelChange(emojiOpenerTarget())
            ToolbarTool.CLIPBOARD -> {
                if (isClipboardAccessible()) onPanelChange(PanelMode.CLIPBOARD)
            }
            ToolbarTool.CLIPBOARD_SEARCH -> onClipboardOpenSearching()
            ToolbarTool.RECENT_COPIES -> onRecentClipsToggle()
            ToolbarTool.LEAVE_FIELD -> onLeaveField()
            ToolbarTool.QUICK_NOTE -> onQuickNote()
            ToolbarTool.READ_BACK -> toggleReadBack()

            ToolbarTool.SNIPPETS -> onPanelChange(PanelMode.SNIPPETS)
            ToolbarTool.TEXT_EDIT -> onPanelChange(PanelMode.TEXT_EDIT)
            ToolbarTool.TRACKPAD -> onPanelChange(PanelMode.TRACKPAD)
            ToolbarTool.SETTINGS -> openSettings()
            ToolbarTool.ONE_HANDED -> {
                val landscape =
                    resources.configuration.orientation == Configuration.ORIENTATION_LANDSCAPE
                val variant = ScreenVariant.of(
                    landscape = landscape,
                    unfolded = resources.configuration.smallestScreenWidthDp >= ScreenVariant.UNFOLDED_MIN_DP,
                )
                if (!settings.oneHandedAllowedOn(variant)) {
                    // "Portrait only" (#503) or this screen shape's own gate
                    // (#611) holds the mode off here, so a press would change
                    // nothing visible: say why instead.
                    Toast.makeText(
                        this,
                        getString(
                            if (settings.sizingOverrides[variant]?.allowOneHanded == false) {
                                R.string.ime_service_one_handed_screen_off_toast
                            } else {
                                R.string.ime_service_one_handed_portrait_only_toast
                            },
                        ),
                        Toast.LENGTH_SHORT,
                    ).show()
                } else {
                    onOneHandedChange(
                        if (settings.oneHandedMode == OneHandedMode.OFF) {
                            // Enable on this orientation's preferred side.
                            settings.oneHanded.forLandscape(landscape).side.toMode()
                        } else OneHandedMode.OFF,
                    )
                }
            }
            ToolbarTool.SPLIT -> onToggleSplit()
            ToolbarTool.FLOATING -> onFloatingChange(!settings.floatingFor(landscapeNow()))
            ToolbarTool.PERSISTENT -> onPersistentChange(!settings.persistentKeyboard)
            ToolbarTool.RESIZE -> onResizeToggle()
            ToolbarTool.FLASHLIGHT -> onFlashlightToggle()
            ToolbarTool.COMPASS -> onPanelChange(PanelMode.COMPASS)
            ToolbarTool.LEVEL -> onPanelChange(PanelMode.LEVEL)
            ToolbarTool.UNDO -> onUndoRedo(false)
            ToolbarTool.REDO -> onUndoRedo(true)
            ToolbarTool.MOON_PHASE -> onPanelChange(PanelMode.MOON_PHASE)
            ToolbarTool.WEATHER -> onPanelChange(PanelMode.WEATHER)
            ToolbarTool.CALENDAR -> onPanelChange(PanelMode.CALENDAR)
            ToolbarTool.INCOGNITO -> onIncognitoToggle()
            ToolbarTool.POWER_SAVING -> onPowerSavingToggle()
            ToolbarTool.THEMES -> onPanelChange(PanelMode.THEMES)
            ToolbarTool.AUTOCORRECT -> onAutocorrectToggle()
            ToolbarTool.SELECTION_ACTIONS -> onSelectionActionsToggle()
            ToolbarTool.PHONETIC_ENGLISH -> onPhoneticEnglishToggle()
            ToolbarTool.FANCY -> onFancyToggle()
            ToolbarTool.CUSTOM_LAYOUT -> onCustomLayoutToggle()
            ToolbarTool.SOUND_HAPTICS -> onPanelChange(PanelMode.SOUND_HAPTICS)
            ToolbarTool.NUMPAD -> {
                releaseUserShift()
                onPanelChange(PanelMode.NUMPAD)
            }
            ToolbarTool.HANDWRITING -> onPanelChange(PanelMode.HANDWRITING)
            ToolbarTool.CAMERA -> onPanelChange(PanelMode.CAMERA)
            ToolbarTool.DICTIONARY -> onPanelChange(PanelMode.DICTIONARY)
            ToolbarTool.VOCABULARY -> onPanelChange(PanelMode.VOCABULARY)
            ToolbarTool.TRANSLATE -> onPanelChange(PanelMode.TRANSLATE)
            ToolbarTool.GIF -> onPanelChange(PanelMode.GIF)
            ToolbarTool.STICKER -> onPanelChange(PanelMode.STICKER)
            ToolbarTool.EMOJI_MIX -> onPanelChange(PanelMode.EMOJI_MIX)
            ToolbarTool.WEB_SEARCH -> openSearchTab(SearchTab.ALL)
            ToolbarTool.IMAGE_SEARCH -> openSearchTab(SearchTab.IMAGES)
            ToolbarTool.OCR -> onPanelChange(PanelMode.OCR)
            ToolbarTool.QR_SCAN -> onPanelChange(PanelMode.QR_SCAN)
            // Not a panel: the scanner is a full-screen Google activity.
            ToolbarTool.DOC_SCAN -> onDocScanStart()
            ToolbarTool.VOICE -> when {
                // A keyboard-owned field has the keys: the tool dictates into it (#353).
                _uiState.value.captureTarget()?.takesDictation == true -> onCaptureVoice(CaptureVoiceAction.TOGGLE)
                !endVoiceFromTool() -> onPanelChange(PanelMode.VOICE)
            }
            ToolbarTool.GRAMMAR -> onPanelChange(PanelMode.GRAMMAR)
            ToolbarTool.WIKIPEDIA -> onPanelChange(PanelMode.WIKIPEDIA)
            ToolbarTool.SYMBOLS -> onPanelChange(PanelMode.SYMBOLS)
            ToolbarTool.CALCULATOR -> onPanelChange(PanelMode.CALCULATOR)
            ToolbarTool.UNIT_CONVERT -> onPanelChange(PanelMode.UNIT_CONVERT)
            ToolbarTool.CURRENCY -> onPanelChange(PanelMode.CURRENCY)
            ToolbarTool.QR_GEN -> onPanelChange(PanelMode.QR_GEN)
            ToolbarTool.PASSWORD_GEN -> onPanelChange(PanelMode.PASSWORD_GEN)
            ToolbarTool.TEXT_REPEAT -> onPanelChange(PanelMode.TEXT_REPEAT)
            ToolbarTool.TYPING_TEST -> onPanelChange(PanelMode.TYPING_TEST)
            ToolbarTool.SPEED_TEST -> onPanelChange(PanelMode.SPEED_TEST)
            // Not a panel: the levels, achievements and heatmap live on the
            // settings app's Statistics screen, and this is a shortcut to it (#390).
            ToolbarTool.STATISTICS -> openRoute(STATISTICS_ROUTE)
            ToolbarTool.LEARN_FROM_TEXT -> onPanelChange(PanelMode.LEARN_FROM_TEXT)
            ToolbarTool.FIND_REPLACE -> openFindReplaceTool()
            ToolbarTool.NOTES -> onPanelChange(PanelMode.NOTES)
            ToolbarTool.TODO -> onPanelChange(PanelMode.TODO)
            ToolbarTool.LOCATION -> onPanelChange(PanelMode.LOCATION)
            ToolbarTool.CLOCK -> onPanelChange(PanelMode.CLOCK)
            ToolbarTool.MUSIC_ID -> onPanelChange(PanelMode.MUSIC_ID)
            ToolbarTool.HOME_ASSISTANT -> onPanelChange(PanelMode.HOME_ASSISTANT)
            ToolbarTool.GALLERY -> openGalleryTool()
            ToolbarTool.SEND_FILES -> openSendTool()
            ToolbarTool.MEDIA_CONTROL -> onPanelChange(PanelMode.MEDIA_CONTROL)
            ToolbarTool.KDE_CONNECT -> onPanelChange(PanelMode.KDE_CONNECT)
            ToolbarTool.PLUGINS -> onPanelChange(PanelMode.PLUGINS)
            ToolbarTool.APP_LAUNCHER -> onPanelChange(PanelMode.APP_LAUNCHER)
            ToolbarTool.AI -> onPanelChange(PanelMode.AI)
            ToolbarTool.AI_REPLY -> onPanelChange(PanelMode.AI_REPLY)
            ToolbarTool.MODES -> onPanelChange(PanelMode.MODES)
            // Same moves the text-editing panel offers, one tap deep instead
            // of two. Selection still extends when the panel's select mode is
            // on, since onTextEdit reads that state itself — and also while
            // shift is up, which [onCursorTool] folds in.
            ToolbarTool.CURSOR_LEFT -> onCursorTool(TextEditAction.LEFT)
            ToolbarTool.CURSOR_RIGHT -> onCursorTool(TextEditAction.RIGHT)
            ToolbarTool.CURSOR_WORD_LEFT -> onCursorTool(TextEditAction.WORD_LEFT)
            ToolbarTool.CURSOR_WORD_RIGHT -> onCursorTool(TextEditAction.WORD_RIGHT)
            ToolbarTool.CURSOR_UP -> onCursorTool(TextEditAction.UP)
            ToolbarTool.CURSOR_DOWN -> onCursorTool(TextEditAction.DOWN)
            ToolbarTool.CURSOR_HOME -> onCursorTool(TextEditAction.HOME)
            ToolbarTool.CURSOR_END -> onCursorTool(TextEditAction.END)
            ToolbarTool.PAGE_UP -> onCursorTool(TextEditAction.PAGE_UP)
            ToolbarTool.PAGE_DOWN -> onCursorTool(TextEditAction.PAGE_DOWN)
            ToolbarTool.SELECT_WORD -> onTextEdit(TextEditAction.SELECT_WORD)
            ToolbarTool.SELECT_LINE -> onTextEdit(TextEditAction.SELECT_LINE)
            ToolbarTool.SELECT_ALL -> onTextEdit(TextEditAction.SELECT_ALL)
            ToolbarTool.SELECT_MODE -> onSelectModeTap()
            // The same three operations the text-edit panel's keys run, so the
            // selection bookkeeping (copy and cut end select mode, paste checks
            // the clipboard is readable) is the one implementation (issue #41).
            ToolbarTool.COPY -> onTextEdit(TextEditAction.COPY)
            ToolbarTool.CUT -> onTextEdit(TextEditAction.CUT)
            ToolbarTool.PASTE -> onTextEdit(TextEditAction.PASTE)
            ToolbarTool.HIDE_KEYBOARD -> onHideKeyboard()
            // The 🌐 key's own switch (#667).
            ToolbarTool.LANGUAGE -> switchLanguage()
        }
    }

    /**
     * Edits an open panel's search buffer. Every query change drops the hardware
     * focus ring: once the results are filtered differently, index 3 is a
     * different item, and Enter on a stale ring would insert something the user
     * never looked at. Cheaper and safer than trying to follow an item across a
     * refiltered list.
     *
     * Typing also ends a category: the grid is about to answer the query, not
     * the chip, so no chip should keep reading as the selected one.
     */
    private inline fun updateQuery(crossinline block: (KeyboardUiState) -> KeyboardUiState) {
        _uiState.update { block(it).copy(panelFocus = null, mediaCategory = null) }
    }

    /**
     * Opens (or closes) a panel. [haptic] is false when a key on the grid did
     * it: the UI's pointer-down callback already buzzed for that press, and a
     * second buzz on release read as one long double tick on the emoji key.
     * The toolbar, the chrome shortcut and the hardware shortcuts have no
     * press-time feedback of their own, so they keep it.
     */
    fun onPanelChange(panel: PanelMode, haptic: Boolean = true) {
        // Image search is web search's Images tab now (#879). Whatever still
        // asks for its panel, a key, a macro or a docs shot, lands there.
        if (panel == PanelMode.IMAGE_SEARCH) {
            openSearchTab(SearchTab.IMAGES, haptic)
            return
        }
        if (panel == PanelMode.CLIPBOARD && !isClipboardAccessible()) return
        // Voice typing switched off (#578): nothing opens the panel. One
        // already open still closes, through the toggle below.
        if (panel == PanelMode.VOICE && _uiState.value.panel != PanelMode.VOICE &&
            !_uiState.value.settings.voiceBar.enabled
        ) {
            return
        }
        if (rerouteVoiceTool(panel)) return
        dismissVoiceSurfacesFor(panel)
        if (panel == PanelMode.TOOLBOX) publishToolUsage()
        // Panels have their own key semantics — the panel would eat the
        // modified key — so a pending latch does not survive opening one.
        clearModifiers()
        // Same for a half-typed braille chord or morse sequence: the panel
        // takes the keys out from under it.
        resetChordInputs()
        // And for a word being respelled: a panel can take the strip's row the
        // spelling bar draws in, and a buffer that owns the keys with nothing
        // on screen to say so is exactly the trap `pluginTypingActive` documents.
        cancelWordSpell(haptic = false)
        if (haptic) vibrate()
        // The settings app edits snippets in the same file; re-read on open.
        if (panel == PanelMode.SNIPPETS) reloadSnippetsIfChanged()
        // Same for sticker packs, which the settings app owns outright.
        if (panel == PanelMode.STICKER) stickerPackStore.reloadIfChanged()
        // Same again: the Storage screen can delete the history out from under
        // this list, and saving a stale one would undo that.
        if (panel == PanelMode.CLIPBOARD) {
            clipboardStore.reload()
            fetchLinkPreviews()
        }
        // Search by meaning catches up on what this panel searches, in the
        // background, so the box is ready by the time anything is typed.
        indexMeaningFor(panel)
        // Leaving the Notes panel, by closing it or opening another: the draft
        // is saved and the editor, the search and the Undo bar go (#560).
        if (_uiState.value.panel == PanelMode.NOTES) notesLeavePanel()
        if (_uiState.value.panel == PanelMode.LOCATION) locationTool.onPanelClose()
        // Leaving the emoji panel: the kaomoji tab's box gives the keys back.
        if (_uiState.value.panel == PanelMode.EMOJI) {
            kaomojiTool.onPanelClose()
            _uiState.update { it.copy(kaomojiText = null) }
        }
        // Leaving the Clock panel: its text box gives the keys back.
        if (_uiState.value.panel == PanelMode.CLOCK) {
            clockTool.onPanelClose()
            _uiState.update { it.copy(clockText = null) }
        }
        // Leaving the Music ID panel: the microphone goes with it.
        if (_uiState.value.panel == PanelMode.MUSIC_ID) musicTool.onPanelClose()
        // Leaving the share sheet, by any way out: the share it was open for goes with it (#970).
        if (_uiState.value.panel == PanelMode.SHARE && shareToolDelegate.isInitialized()) shareTool.onPanelClose()
        // Leaving the To-do panel: the same (#920). Every change is saved as it is made.
        if (_uiState.value.panel == PanelMode.TODO) {
            todoTool.onPanelClose()
            _uiState.update { it.copy(todoText = null) }
        }
        // Leaving the Home Assistant panel: its text box gives the keys back, the socket lingers.
        if (_uiState.value.panel == PanelMode.HOME_ASSISTANT) {
            haTool.onPanelClose()
            _uiState.update { it.copy(haText = null) }
        }
        // Leaving the Calendar panel: the composer's box gives the keys back; a draft is kept.
        if (_uiState.value.panel == PanelMode.CALENDAR) {
            calendarTool.onPanelClose()
            _uiState.update { it.copy(calendarText = null) }
        }
        // Leaving the gallery: its caption box gives the keys back (#708).
        if (_uiState.value.panel == PanelMode.GALLERY) {
            galleryTool.onPanelClose()
            _uiState.update { it.copy(galleryText = null) }
        }
        // Leaving Text repeat: its boxes give the keys back and the chip's run
        // is forgotten; the text itself stays for the next visit.
        if (_uiState.value.panel == PanelMode.TEXT_REPEAT) textRepeatLeavePanel()
        // Leaving the Send files panel: its boxes give the keys back (#729).
        if (_uiState.value.panel == PanelMode.SEND_FILES) {
            sendTool.onPanelClose()
            _uiState.update { it.copy(sendText = null) }
        }
        // Leaving the reply panel, by closing it or opening another: the
        // screenshot watcher goes back to what the clipboard setting says (#234).
        if (_uiState.value.panel == PanelMode.AI_REPLY) {
            updateScreenshotObserver(_uiState.value.settings.clipboard.userScreenshots)
        }
        // Whatever the GIF/sticker panel was showing survives it closing.
        stashMediaSearch(_uiState.value)
        _uiState.update {
            val closing = it.panel == panel
            val next = if (closing) PanelMode.NONE else panel
            val restored = savedMediaSearch(next)
            it.copy(
                panel = next,
                // The strip is hidden behind the panel; a stale chip would
                // reappear on close pointing at text that has since moved.
                smart = null,
                vocabDaily = null,
                // The card survives closing; only the tab and the back stack reset.
                vocab = if (next == PanelMode.VOCABULARY) it.vocab.copy(tab = VocabTab.CARD, stack = emptyList()) else it.vocab,
                // A ring indexed into the panel being left would point at
                // whatever happens to sit at that index in the new one; the
                // keyboard path re-seeds it after this (see [openToolByKey]).
                panelFocus = null,
                // Arming is spent the moment a tool opens, however it opened.
                toolPicker = null,
                // The find fields exist exactly while their panel does (see
                // findReplaceTypingActive); a fresh open starts them empty.
                findReplace = if (next == PanelMode.FIND_REPLACE) FindReplaceUi() else null,
                // The filter and the open note survive; the rest is per visit.
                notes = if (next == PanelMode.NOTES) {
                    it.notes.copy(searchActive = false, query = "", editing = null, held = null, confirm = null, undo = null, quick = false, recent = emptyList())
                } else {
                    it.notes
                },
                // A fresh open reads the text again (see [scanForLearning]).
                learnFromText = if (next == PanelMode.LEARN_FROM_TEXT) LearnFromTextUi() else null,
                textEditSelecting = false,
                // Every tool's fields open with the keys (#665), and up (#961).
                captureToApp = null,
                captureLowered = null,
                emojiSearchActive = false,
                emojiQuery = "",
                emojiResults = emptyList(),
                clipboardItems = clipboardStore.items(),
                snippets = snippetStore.items(),
                snippetFolders = snippetStore.folders(),
                snippetCandidateCounts = snippetCandidateCounts(),
                // Every open of the snippets panel starts at the folders. A
                // panel that reopened three levels into where it was last week
                // is a panel that looks broken. Same for a held tile's list.
                snippetFolderOpen = null,
                snippetPicker = null,
                snippetSearchActive = false,
                snippetQuery = "",
                // The toolbox opens at its top level every time, search closed.
                toolboxView = ToolboxUi(),
                // The strip is behind the panel, so its chips go with it for
                // the reason [smart] does.
                snippetOffers = null,
                dictionarySearchActive = false,
                clipboardSearchActive = false,
                clipboardQuery = "",
                // An edit belongs to the panel it was opened in.
                clipEdit = null,
                clipCombine = null,
                // Stacked over the keys is for the visit it was asked for in
                // (#612): the panel opens full again next time.
                clipboardWithKeys = false,
                // GIF/sticker reopen on their last search — unless a
                // celebration chip staged one, which outranks it; everything
                // else starts blank. A Wikipedia lookup chip seeds the search
                // box the same way.
                mediaQuery = when (next) {
                    PanelMode.GIF, PanelMode.STICKER ->
                        (it.toolPrefill as? ToolPrefill.Gif)?.query ?: restored.query
                    PanelMode.WIKIPEDIA ->
                        (it.toolPrefill as? ToolPrefill.Lookup)?.term ?: restored.query
                    PanelMode.WEB_SEARCH -> keptSearchQuery(it) ?: restored.query
                    else -> restored.query
                },
                // Web search and translate open straight into their search box
                // (there is nothing to show yet), unless the last search's
                // results are still there to read (#347); gif/sticker open on
                // their previous search, or trending. Wikipedia keeps a
                // previous article/results if it has one.
                mediaSearchActive = next == PanelMode.TRANSLATE || next == PanelMode.QR_GEN ||
                    (next == PanelMode.WEB_SEARCH && keptSearchQuery(it) == null) ||
                    (next == PanelMode.WIKIPEDIA && it.wiki !is WikiUi.Article && it.wiki !is WikiUi.SearchResults),
                mediaDownloadingId = null,
                mediaDownloadProgress = null,
                stickerPacks = stickerPackStore.packs(),
                stickerPackId = null,
                gifFavouriteIds = if (next == PanelMode.GIF) gifCollections.favouriteIds() else it.gifFavouriteIds,
                // The service owns these buffers now, so the seed happens here:
                // the calculator consumes its chip prefill outright, while the
                // converters take only the amount — the panel still reads the
                // category and unit pair from the prefill it consumes itself.
                calcExpression = if (next == PanelMode.CALCULATOR) {
                    (it.toolPrefill as? ToolPrefill.Calc)?.expression.orEmpty()
                } else {
                    ""
                },
                converterValue = when (next) {
                    PanelMode.UNIT_CONVERT -> (it.toolPrefill as? ToolPrefill.Units)?.value ?: "1"
                    PanelMode.CURRENCY -> (it.toolPrefill as? ToolPrefill.Currency)?.amount ?: "1"
                    else -> "1"
                },
                toolPrefill = when (next) {
                    // Consumed above, into the expression or the search box.
                    PanelMode.CALCULATOR, PanelMode.GIF, PanelMode.STICKER -> null
                    else -> it.toolPrefill
                },
                mediaAction = null,
                mediaCategories = emptyList(),
                mediaCategory = restored.category,
                translate = TranslateUi(),
                grammar = GrammarUi(available = grammarAvailable || grammarProbePending()),
                // Leaving the Plugins panel must hand the keys straight back to
                // the field. This is the reset that guarantees it: whatever the
                // panel was routing, the next state has nowhere to route to.
                pluginFocusedInput = null,
                pluginInputs = if (next == PanelMode.PLUGINS) it.pluginInputs else emptyMap(),
                plugins = if (next == PanelMode.PLUGINS) it.plugins else PluginPanelUi.List(emptyList()),
                // The drill-down never outlives the panel: reopening the tool
                // lands on the grid, not on whatever app was open last time.
                launcherDetail = if (next == PanelMode.APP_LAUNCHER) it.launcherDetail else null,
                // And reopening it lands on the whole grid, not inside a folder (#919).
                launcherView = if (next == PanelMode.APP_LAUNCHER) it.launcherView else LauncherUi(),
                // Only the search panel's camera button opens the camera for
                // searching (#349); every other way in is for sending.
                cameraSearchOnly = next == PanelMode.CAMERA && it.panel == PanelMode.WEB_SEARCH,
                // Only a clip's Extract text sets this, after the change (#371).
                ocrImage = null,
                // Only a clip's Translate sets this, after the change (#807).
                cameraImage = null,
            )
        }
        // Whichever of emoji, GIFs and stickers is now up is the one the
        // emoji key reopens next time, when that setting is on (#366).
        _uiState.value.panel.takeIf { it in MediaTabPanels }?.let { lastMediaPanel = it }
        // Leaving the panel ends the plugin session outright. Not paused, not
        // backgrounded: the Globals are dropped and the thread is shut down, so
        // after this there is no plugin left in the process to receive
        // anything the user types.
        if (_uiState.value.panel != PanelMode.PLUGINS) pluginRuntime?.close()
        // Either direction is a history surface changing hands — the emoji
        // panel's grids coming up, or the emoji row it hid coming back — so
        // this is where a ranking moved by earlier taps lands.
        publishEmojiHistory()
        translateJob?.cancel()
        if (_uiState.value.panel == PanelMode.TRANSLATE) watchTranslateModels() else releaseTranslateEngine()
        grammarJob?.cancel()
        rephraseJob?.cancel()
        learnJob?.cancel()
        mediaFetchJob?.cancel()
        mediaLiveSearchJob?.cancel()
        mediaCategoryJob?.cancel()
        when (_uiState.value.panel) {
            PanelMode.WEATHER -> refreshWeather()
            PanelMode.LOCATION -> locationTool.onPanelOpen()
            PanelMode.CLOCK -> clockTool.onPanelOpen()
            PanelMode.MUSIC_ID -> musicTool.onPanelOpen()
            PanelMode.TODO -> todoTool.onPanelOpen()
            // A "next friday" chip lands on its day; "Add to calendar" on a
            // selection opens the composer filled in.
            PanelMode.CALENDAR -> {
                val prefill = _uiState.value.toolPrefill
                calendarTool.onPanelOpen(prefill)
                if (prefill is ToolPrefill.Calendar || prefill is ToolPrefill.CalendarEvent) onToolPrefillConsumed()
            }
            PanelMode.EMOJI -> if (_uiState.value.settings.emoji.kaomojiTabs) kaomojiTool.onPanelOpen()
            PanelMode.HOME_ASSISTANT -> {
                haTool.onPanelOpen()
                (_uiState.value.toolPrefill as? ToolPrefill.Assist)?.let { prefill ->
                    haTool.prefillAssist(prefill.sentence)
                    onToolPrefillConsumed()
                }
            }
            PanelMode.GALLERY -> galleryTool.onPanelOpen()
            PanelMode.SEND_FILES -> {
                // A link chip staged the link; the panel opens on receiving it (#729).
                (_uiState.value.toolPrefill as? ToolPrefill.SendLink)?.let {
                    sendTool.receive(it.url)
                    onToolPrefillConsumed()
                }
                sendTool.onPanelOpen()
            }
            PanelMode.VOCABULARY -> {
                val prefill = _uiState.value.toolPrefill as? ToolPrefill.Vocab
                if (prefill != null) onToolPrefillConsumed()
                serviceScope.launch {
                    reloadVocabIndex()
                    // The cards are dropped while the keyboard is hidden;
                    // read them back off the main thread before the panel
                    // asks for one on it.
                    vocabIndex?.let { index -> withContext(Dispatchers.IO) { index.packs } }
                    openVocabulary(prefill?.word)
                }
            }
            PanelMode.DICTIONARY -> {
                openDictionary()
                // A "define serendipity" chip: straight to the word.
                (_uiState.value.toolPrefill as? ToolPrefill.Lookup)?.let {
                    onDictionaryLookup(it.term)
                    onToolPrefillConsumed()
                }
            }
            PanelMode.GIF, PanelMode.STICKER -> {
                refreshMedia(_uiState.value.mediaQuery.trim())
                refreshMediaCategories()
            }
            // A "who is …" chip: the search runs as the panel opens. The
            // query is already in the search box (see the copy above).
            PanelMode.WIKIPEDIA -> (_uiState.value.toolPrefill as? ToolPrefill.Lookup)?.let {
                runWikiSearch(it.term)
                onToolPrefillConsumed()
            }
            // A finished search is still on screen when the panel comes back
            // (#347): reading one result in the browser and returning for the
            // next must not cost a second request, or return different links.
            PanelMode.WEB_SEARCH -> _uiState.update {
                it.copy(
                    webSearch = when {
                        !hasSearchKey() -> WebSearchUi.NeedKey
                        it.webSearch is WebSearchUi.Ready -> it.webSearch
                        else -> WebSearchUi.Idle
                    },
                    imageSearch = when {
                        !hasSearchKey() -> ImageSearchUi.NeedKey
                        it.imageSearch is ImageSearchUi.Ready -> it.imageSearch
                        else -> ImageSearchUi.Idle
                    },
                )
            }
            PanelMode.GRAMMAR -> {
                currentInputConnection?.let { commitComposing(it, autocorrect = false) }
                scheduleGrammarCheck(immediate = true)
            }
            // The coin table is only worth fetching when the pair the panel
            // opens on actually holds a coin.
            PanelMode.CURRENCY -> refreshCurrencyRates(wantCrypto = pairHasCoin())
            PanelMode.QR_GEN -> {
                currentInputConnection?.let { commitComposing(it, autocorrect = false) }
                // Seed the editable buffer with the field text as a convenience,
                // but from here the user edits it freely — the QR no longer
                // tracks the field.
                _uiState.update { it.copy(mediaQuery = extractFieldText().trim()) }
            }
            PanelMode.FIND_REPLACE -> {
                currentInputConnection?.let { commitComposing(it, autocorrect = false) }
            }
            PanelMode.TEXT_REPEAT -> openTextRepeatPanel()
            PanelMode.NOTES -> openNotesPanel()
            PanelMode.EMOJI_MIX -> {
                emojiMixTool.onOpen(emojiMixOpenWith)
                emojiMixOpenWith = null
            }
            PanelMode.LEARN_FROM_TEXT -> {
                // The half-typed word is part of the text being read.
                currentInputConnection?.let { commitComposing(it, autocorrect = false) }
                scanForLearning()
            }
            PanelMode.AI -> {
                // A half-typed word is part of what the actions would run on,
                // so it has to be in the field before the chips are judged
                // enabled or not.
                currentInputConnection?.let { commitComposing(it, autocorrect = false) }
                _uiState.update { it.copy(ai = aiInitialState(it.settings)) }
                refreshAiHasText()
                prepareAiChat()
            }
            PanelMode.AI_REPLY -> prepareAiReply()
            PanelMode.TRANSLATE -> prefillTranslateFromSelection()
            PanelMode.PLUGINS -> openPluginList()
            PanelMode.APP_LAUNCHER -> loadLauncherApps()
            PanelMode.TYPING_TEST -> {
                // Flush the half-typed word first: the test swallows every
                // key from here, so a composing word would otherwise hang
                // uncommitted until the panel closed.
                currentInputConnection?.let { commitComposing(it, autocorrect = false) }
                startTypingTest()
            }
            PanelMode.SPEED_TEST -> speedTest.onOpen()
            else -> {}
        }
        if (_uiState.value.panel != PanelMode.TYPING_TEST) stopTypingTest()
        // Leaving the panel stops a run: nobody is watching, and it costs data.
        if (_uiState.value.panel != PanelMode.SPEED_TEST && speedTestDelegate.isInitialized()) speedTest.onClose()
        if (_uiState.value.panel == PanelMode.HANDWRITING) {
            // Flush any half-typed word so handwriting appends after it.
            currentInputConnection?.let { commitComposing(it, autocorrect = false) }
            refreshHandwritingStatus()
        } else if (hwJob != null || _uiState.value.handwriting.strokes.isNotEmpty()) {
            // Leaving the panel abandons pending ink and recognition.
            hwJob?.cancel()
            hwJob = null
            hwGeneration++
            _uiState.update {
                it.copy(handwriting = it.handwriting.copy(strokes = emptyList(), recognizing = false))
            }
        }
        if (_uiState.value.panel == PanelMode.VOICE) {
            // Opening the tool is the intent to speak: listen right away.
            startVoice()
        } else {
            cancelVoice()
        }
        syncMediaTracking()
        syncKdeConnect()
        syncHomeAssistant()
    }

    // ---- KDE Connect (issue #285) ----

    private var kdeEventsJob: Job? = null

    /**
     * Tells [KdeConnectHub] what this service currently amounts to — alive,
     * on screen, showing the panel — and lets it decide whether a link should
     * exist. The one owner of those holds, called from the same four places
     * [syncMediaTracking] is, for the same reason: each of them changes the
     * answer, and none of them should have to know the rule.
     */
    private fun syncKdeConnect() {
        val state = _uiState.value
        val kde = state.settings.kdeConnect
        KdeConnectHub.attach(this)
        val panelOpen = keyboardVisible && state.panel == PanelMode.KDE_CONNECT
        fun hold(reason: KdeConnectHub.Reason, on: Boolean) =
            if (on) KdeConnectHub.hold(reason) else KdeConnectHub.release(reason)
        // One reconcile for the lot, not one per change: this runs on every
        // show and hide.
        KdeConnectHub.batch {
            KdeConnectHub.applySettings(kde)
            hold(KdeConnectHub.Reason.SERVICE, kde.enabled)
            hold(KdeConnectHub.Reason.KEYBOARD, kde.enabled && keyboardVisible)
            hold(KdeConnectHub.Reason.PANEL, kde.enabled && panelOpen)
            // The list of nearby devices is up when nothing is paired yet, or when
            // the user opened it: only then are strangers on the network linked.
            KdeConnectHub.setBrowsing(
                KdeConnectHub.Reason.PANEL,
                kde.enabled && panelOpen && (state.kde.showDevices || !KdeConnectHub.hasPairedDevices()),
            )
        }
        // A computer may type only into a keyboard that is on screen, over a
        // device that is unlocked.
        KdeConnectHub.engine?.setKeyboardShown(kde.enabled && keyboardVisible && !state.deviceLocked)
        if (!panelOpen && (state.kde.typing || state.kde.hostEntry || state.kde.line.isNotEmpty())) {
            _uiState.update { it.copy(kde = it.kde.copy(typing = false, hostEntry = false, hostDraft = "", line = "")) }
        }
        if (kde.enabled && kdeEventsJob == null) {
            kdeEventsJob = serviceScope.launch { KdeConnectHub.events.collect(::onKdeEvent) }
        } else if (!kde.enabled) {
            kdeEventsJob?.cancel()
            kdeEventsJob = null
        }
    }

    /** The paired computer the panel is about: the one picked, else the first connected. */
    private fun kdeDeviceId(): String? {
        val hub = KdeConnectHub.state.value
        val picked = _uiState.value.kde.deviceId
        return hub.device(picked)?.takeIf { it.paired && it.reachable }?.id ?: hub.connected.firstOrNull()?.id
    }

    private fun kdeNotice(text: String) {
        _uiState.update { it.copy(kde = it.kde.copy(notice = text, noticeAtMs = SystemClock.uptimeMillis())) }
    }

    fun onKdeAction(action: KdeAction) {
        when (action) {
            KdeAction.TurnOn -> serviceScope.launch { settingsRepository.setKdeEnabled(true) }
            is KdeAction.SetTab -> {
                _uiState.update { it.copy(kde = it.kde.copy(tab = action.tab, typing = false, line = "")) }
                serviceScope.launch { settingsRepository.setKdeLastTab(action.tab.name) }
            }
            is KdeAction.SelectDevice ->
                _uiState.update { it.copy(kde = it.kde.copy(deviceId = action.deviceId, showDevices = false)) }
            is KdeAction.ShowDevices -> {
                _uiState.update { it.copy(kde = it.kde.copy(showDevices = action.show, hostEntry = false, hostDraft = "")) }
                syncKdeConnect()
                if (action.show) KdeConnectHub.refresh()
            }
            is KdeAction.SetTyping -> {
                // Whatever was half-typed for the app goes to the app first:
                // the keys are about to belong to someone else.
                if (action.on) currentInputConnection?.let { commitComposing(it, autocorrect = false) }
                _uiState.update { it.copy(kde = it.kde.copy(typing = action.on, line = "")) }
            }
            is KdeAction.SetCompose -> {
                _uiState.update { it.copy(kde = it.kde.copy(line = "")) }
                serviceScope.launch { settingsRepository.setKdeComposeMode(action.on) }
            }
            is KdeAction.ToggleModifier -> _uiState.update {
                val m = it.kde.mods
                it.copy(
                    kde = it.kde.copy(
                        mods = when (action.key) {
                            KdeModKey.SHIFT -> m.copy(shift = !m.shift)
                            KdeModKey.CTRL -> m.copy(ctrl = !m.ctrl)
                            KdeModKey.ALT -> m.copy(alt = !m.alt)
                            KdeModKey.META -> m.copy(meta = !m.meta)
                        },
                    ),
                )
            }
            is KdeAction.HostEntry ->
                _uiState.update { it.copy(kde = it.kde.copy(hostEntry = action.open, hostDraft = "")) }
            KdeAction.SubmitHost -> {
                val host = _uiState.value.kde.hostDraft.trim()
                if (host.isNotEmpty()) {
                    serviceScope.launch { settingsRepository.addKdeHost(host) }
                    KdeConnectHub.engine?.announceTo(host)
                }
                _uiState.update { it.copy(kde = it.kde.copy(hostEntry = false, hostDraft = "")) }
            }
            KdeAction.SendClipboard -> {
                val text = if (isClipboardAccessible()) {
                    (getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager)
                        .primaryClip?.takeIf { it.itemCount > 0 }?.getItemAt(0)?.coerceToText(this)?.toString().orEmpty()
                } else {
                    ""
                }
                val sent = if (text.isEmpty()) 0 else KdeConnectHub.engine?.clipboard?.push(text, kdeDeviceId()) ?: 0
                kdeNotice(getString(if (sent > 0) R.string.ime_kde_notice_clipboard_sent else R.string.ime_kde_notice_clipboard_empty))
            }
            is KdeAction.PauseClipboard -> KdeConnectHub.pauseClipboard(this, action.deviceId, action.minutes)
            is KdeAction.ResumeClipboard -> KdeConnectHub.resumeClipboard(this, action.deviceId)
            KdeAction.SendFieldText -> {
                val ic = currentInputConnection
                val text = ic?.getSelectedText(0)?.toString()?.takeIf { it.isNotEmpty() }
                    ?: ic?.getExtractedText(ExtractedTextRequest(), 0)?.text?.toString().orEmpty()
                val id = kdeDeviceId()
                val ok = text.isNotEmpty() && id != null && KdeConnectHub.engine?.share?.sendText(id, text) == true
                kdeNotice(getString(if (ok) R.string.ime_kde_notice_text_sent else R.string.ime_kde_notice_nothing_to_send))
            }
            KdeAction.PickFiles -> kdeDeviceId()?.let { id ->
                runCatching {
                    startActivity(
                        Intent().setClassName(packageName, KdeConnectHub.PICKER_ACTIVITY)
                            .putExtra(KdeConnectHub.EXTRA_DEVICE, id)
                            .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK),
                    )
                }
            }
            is KdeAction.Insert -> commitToField(action.text)
            is KdeAction.Copy -> {
                KeyboardClipboard.copy(this, action.text)
                maybeToastCopied()
            }
            is KdeAction.Open -> runCatching {
                startActivity(
                    Intent(Intent.ACTION_VIEW)
                        .setDataAndType(
                            android.net.Uri.parse(action.location),
                            com.wasimaster.wmkeyboard.ime.kdeconnect.KdeReceivedFiles.mimeOf(action.fileName) ?: "*/*",
                        )
                        .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_GRANT_READ_URI_PERMISSION),
                )
            }
            is KdeAction.Notice -> kdeNotice(action.text)
            KdeAction.OpenSettings -> openToolSettings(ToolbarTool.KDE_CONNECT)
            KdeAction.OpenDevices -> openRoute(KdeConnectHub.DEVICES_ROUTE)
            KdeAction.ScanPairCode -> onPanelChange(PanelMode.QR_SCAN)
        }
    }

    /**
     * The line the computer has been sent became [next]: replay the difference
     * there. This is the whole of "type on the computer with this keyboard" —
     * a glide, a strip pick and an autocorrection are all just a new [next].
     */
    private fun kdeRemoteLine(next: String) {
        val sent = _uiState.value.kde.line
        val edit = RemoteTextDiff.between(sent, next)
        val id = kdeDeviceId()
        val pad = KdeConnectHub.engine?.mousepad
        if (id != null && pad != null && !edit.isEmpty) {
            if (edit.backspaces > 0) pad.special(id, KdeSpecialKey.BACKSPACE, times = edit.backspaces)
            if (edit.insert.isNotEmpty()) pad.text(id, edit.insert)
        }
        // Only the tail is ever diffed, so the head can go once it is long.
        _uiState.update { it.copy(kde = it.kde.copy(line = next.takeLast(KdeConnectHub.LINE_MAX))) }
    }

    /** A key that is not text, sent to the computer; the local line no longer describes what is before its caret. */
    private fun kdeSendSpecial(key: KdeSpecialKey, modifiers: KdeModifiers = KdeModifiers.None, times: Int = 1, keepLine: Boolean = false) {
        val id = kdeDeviceId() ?: return
        KdeConnectHub.engine?.mousepad?.special(id, key, modifiers, times)
        if (!keepLine && _uiState.value.kde.line.isNotEmpty()) {
            _uiState.update { it.copy(kde = it.kde.copy(line = ""), captureCaret = null) }
        }
    }

    /** From the panel's special-key strip: the key, under whatever is armed there, which it spends. */
    fun onKdeSpecialKey(key: KdeSpecialKey, modifiers: KdeModifiers) {
        kdeSendSpecial(key, modifiers)
        if (_uiState.value.kde.mods.any) _uiState.update { it.copy(kde = it.kde.copy(mods = KdeModifiers.None)) }
    }

    /**
     * Text typed while the panel's strip has Ctrl, Alt or Super armed: a chord
     * for the computer rather than a character for the line. True when spent.
     */
    private fun kdeTypedUnderModifiers(target: CaptureTarget, text: String): Boolean {
        if (target != CaptureTarget.KDE_REMOTE && target != CaptureTarget.KDE_COMPOSE) return false
        val mods = _uiState.value.kde.mods
        if (!mods.ctrl && !mods.alt && !mods.meta) return false
        kdeDeviceId()?.let { id -> KdeConnectHub.engine?.mousepad?.chord(id, text, mods) }
        _uiState.update { it.copy(kde = it.kde.copy(mods = KdeModifiers.None, line = ""), captureCaret = null) }
        return true
    }

    /**
     * A key pressed with Ctrl, Alt or Meta armed while the keys belong to the
     * computer: sent there as the chord it is. False when they do not, so the
     * shortcut goes to the app as it always has.
     */
    private fun kdeSendChord(key: Key, modifiers: Modifiers): Boolean {
        val target = _uiState.value.captureTarget()
        if (target != CaptureTarget.KDE_REMOTE && target != CaptureTarget.KDE_COMPOSE) return false
        val id = kdeDeviceId() ?: return true
        val label = (key.output ?: key.label)
        val held = KdeModifiers(
            shift = _uiState.value.shiftState != ShiftState.OFF,
            ctrl = modifiers.ctrl != ModifierState.OFF,
            alt = modifiers.alt != ModifierState.OFF,
            meta = modifiers.meta != ModifierState.OFF,
        )
        val pad = KdeConnectHub.engine?.mousepad ?: return true
        when (key.action) {
            KeyAction.Delete -> pad.special(id, KdeSpecialKey.BACKSPACE, held)
            KeyAction.Enter -> pad.special(id, KdeSpecialKey.ENTER, held)
            KeyAction.Space -> pad.chord(id, " ", held)
            else -> if (label.isNotEmpty()) pad.chord(id, label, held)
        }
        // A chord moves things on the computer; the line no longer describes them.
        _uiState.update { it.copy(kde = it.kde.copy(line = ""), captureCaret = null) }
        return true
    }

    /** Compose mode's Enter, and its Send button ([withEnter] false). */
    fun kdeSendComposed(withEnter: Boolean) {
        val id = kdeDeviceId() ?: return
        val line = _uiState.value.kde.line
        val pad = KdeConnectHub.engine?.mousepad ?: return
        if (line.isNotEmpty()) pad.text(id, line)
        if (withEnter) pad.special(id, KdeSpecialKey.ENTER)
        _uiState.update { it.copy(kde = it.kde.copy(line = ""), captureCaret = null) }
    }

    private fun onKdeEvent(event: KdeEvent) {
        val state = _uiState.value
        when (event) {
            is KdeEvent.RemoteKey -> onKdeRemoteKey(event)
            is KdeEvent.ClipboardReceived -> kdeClipboardArrived(event.text, event.deviceName)
            // Shared text is a clipboard delivery with a different name on the
            // desktop's menu; the desktops treat it the same way.
            is KdeEvent.TextReceived -> kdeClipboardArrived(event.text, event.deviceName)
            is KdeEvent.UrlReceived -> kdeClipboardArrived(event.url, event.deviceName)
            is KdeEvent.FileReceived -> {
                runCatching {
                    clipboardStore.addUri(
                        uriString = event.location,
                        displayName = event.fileName,
                        mimeType = com.wasimaster.wmkeyboard.ime.kdeconnect.KdeReceivedFiles.mimeOf(event.fileName) ?: "application/octet-stream",
                        isDirectory = false,
                        size = 0,
                        sourceApp = event.deviceName,
                    )
                    saveClipboardSoon()
                    _uiState.update { it.copy(clipboardItems = clipboardStore.items()) }
                }
                if (state.panel == PanelMode.KDE_CONNECT) kdeNotice(getString(R.string.ime_kde_notice_file_received, event.fileName))
            }
            is KdeEvent.Ping -> if (keyboardVisible) {
                val text = event.message.ifBlank { getString(R.string.ime_kde_ping_default) }
                if (state.panel == PanelMode.KDE_CONNECT) {
                    kdeNotice(getString(R.string.ime_kde_notice_ping, event.deviceName, text))
                } else {
                    Toast.makeText(this, getString(R.string.ime_kde_notice_ping, event.deviceName, text), Toast.LENGTH_SHORT).show()
                }
            }
            is KdeEvent.LockResult -> if (state.panel == PanelMode.KDE_CONNECT) {
                kdeNotice(getString(if (event.success) R.string.ime_kde_notice_locked else R.string.ime_kde_notice_lock_failed))
            }
            is KdeEvent.Paired -> {
                _uiState.update { it.copy(kde = it.kde.copy(deviceId = event.deviceId, showDevices = false)) }
                syncKdeConnect()
            }
            is KdeEvent.Unpaired -> syncKdeConnect()
            else -> Unit
        }
    }

    /** Clears the last password received from the computer, once its time is up (#704). */
    private var kdeSecretClearJob: Job? = null

    /**
     * Text from the computer's clipboard. The engine has already recorded it as
     * the current content, so the listener that fires for the write below finds
     * nothing new to send back.
     *
     * A clip that looks like a password or a code is marked sensitive, which is
     * what a password manager on the phone would do: Android 13 hides it from
     * the copy preview, and clipboard history handles it as a secret. It is also
     * cleared after the `clearSecretsMinutes` setting (#704): it came over
     * for one paste, and every app can read the clipboard while it sits there.
     */
    private fun kdeClipboardArrived(text: String, from: String) {
        if (text.isEmpty() || !isClipboardAccessible()) return
        val secret = ClipSensitivity.looksSensitive(text)
        runCatching {
            val clip = android.content.ClipData.newPlainText(from, text)
            if (secret) {
                clip.description.extras = android.os.PersistableBundle().apply {
                    putBoolean(EXTRA_IS_SENSITIVE, true)
                }
            }
            (getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager).setPrimaryClip(clip)
        }
        // A newer clip from the computer replaces the old one, so the old timer
        // has nothing left to clear.
        kdeSecretClearJob?.cancel()
        kdeSecretClearJob = null
        val minutes = _uiState.value.settings.kdeConnect.clearSecretsMinutes
        if (!secret || minutes <= 0) return
        kdeSecretClearJob = serviceScope.launch {
            delay(minutes * 60_000L)
            clearKdeSecret(text)
        }
    }

    /**
     * Takes [text] off the system clipboard and out of clipboard history. Only
     * while the clipboard still holds it: whatever was copied since is the
     * user's and stays. A pinned history copy stays too, since a pin says keep.
     */
    private fun clearKdeSecret(text: String) {
        kdeSecretClearJob = null
        val manager = runCatching {
            getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager
        }.getOrNull() ?: return
        val current = runCatching { manager.primaryClip?.getItemAt(0)?.text?.toString() }.getOrNull()
        if (current != text) return
        runCatching {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
                manager.clearPrimaryClip()
            } else {
                manager.setPrimaryClip(android.content.ClipData.newPlainText("", ""))
            }
        }
        val stored = text.trim()
        val gone = clipboardStore.items().filter { it.kind.isTextual && !it.pinned && it.text.trim() == stored }
        if (gone.isNotEmpty()) {
            gone.forEach { clipboardStore.remove(it.id) }
            saveClipboardSoon()
            _uiState.update { it.copy(clipboardItems = clipboardStore.items()) }
        }
        if (_uiState.value.clipboardSuggestion?.text?.trim() == stored) clearClipboardSuggestion()
    }

    /**
     * The computer's keyboard, typing here. Literal by default: what was sent
     * is what lands. With the pipeline switch on it takes the path a hardware
     * keyboard's keys take, so a Latin keyboard on the desk writes Bengali
     * through Avro the way the one on the glass does.
     */
    private fun onKdeRemoteKey(key: KdeEvent.RemoteKey) {
        val state = _uiState.value
        if (!keyboardVisible || state.deviceLocked || !state.settings.kdeConnect.remoteTyping) return
        val special = key.special
        if (special == null) {
            if (key.ctrl && !key.alt) {
                when (key.text.lowercase()) {
                    "a" -> { onTextEdit(TextEditAction.SELECT_ALL, haptic = false); return }
                    "c" -> { onTextEdit(TextEditAction.COPY, haptic = false); return }
                    "v" -> { onTextEdit(TextEditAction.PASTE, haptic = false); return }
                    "x" -> { onClipboardKey(ClipboardKeyAction.CUT, selectAllIfEmpty = false); return }
                    "z" -> { onUndoRedo(redo = key.shift); return }
                    "y" -> { onUndoRedo(redo = true); return }
                }
            }
            if (key.ctrl || key.alt) {
                // Any other chord goes to the app as the key event it is.
                val code = key.text.singleOrNull()?.let(::keyCodeForChar) ?: return
                val ic = currentInputConnection ?: return
                commitComposing(ic, autocorrect = false)
                var meta = 0
                if (key.ctrl) meta = meta or KeyEvent.META_CTRL_ON or KeyEvent.META_CTRL_LEFT_ON
                if (key.alt) meta = meta or KeyEvent.META_ALT_ON or KeyEvent.META_ALT_LEFT_ON
                if (key.shift) meta = meta or KeyEvent.META_SHIFT_ON or KeyEvent.META_SHIFT_LEFT_ON
                val time = SystemClock.uptimeMillis()
                ic.sendKeyEvent(shortcutEvent(time, KeyEvent.ACTION_DOWN, code, meta))
                ic.sendKeyEvent(shortcutEvent(time, KeyEvent.ACTION_UP, code, meta))
                return
            }
            when {
                state.captureTarget() != null -> captureTyped(key.text)
                state.settings.kdeConnect.remoteTypingPipeline -> for (ch in key.text.codePoints().toArray()) {
                    val s = String(Character.toChars(ch))
                    if (s == " ") onSpace() else processTypedText(s, applyDeadKeys = false)
                }
                else -> commitToField(key.text)
            }
            return
        }
        val action = when (special) {
            KdeSpecialKey.LEFT -> if (key.ctrl) TextEditAction.WORD_LEFT else TextEditAction.LEFT
            KdeSpecialKey.RIGHT -> if (key.ctrl) TextEditAction.WORD_RIGHT else TextEditAction.RIGHT
            KdeSpecialKey.UP -> TextEditAction.UP
            KdeSpecialKey.DOWN -> TextEditAction.DOWN
            KdeSpecialKey.HOME -> if (key.ctrl) TextEditAction.DOC_START else TextEditAction.HOME
            KdeSpecialKey.END -> if (key.ctrl) TextEditAction.DOC_END else TextEditAction.END
            KdeSpecialKey.PAGE_UP -> TextEditAction.PAGE_UP
            KdeSpecialKey.PAGE_DOWN -> TextEditAction.PAGE_DOWN
            else -> null
        }
        when {
            action != null -> onTextEdit(action, extendSelection = key.shift, haptic = false)
            special == KdeSpecialKey.BACKSPACE -> if (key.ctrl) onDeleteWord() else onDelete()
            special == KdeSpecialKey.DELETE -> onForwardDelete()
            special == KdeSpecialKey.ENTER -> onEnter()
            special == KdeSpecialKey.TAB -> sendDownUpKeyEvents(KeyEvent.KEYCODE_TAB)
            special == KdeSpecialKey.ESCAPE -> sendDownUpKeyEvents(KeyEvent.KEYCODE_ESCAPE)
            special.code in KdeSpecialKey.F1.code..KdeSpecialKey.F12.code ->
                sendDownUpKeyEvents(KeyEvent.KEYCODE_F1 + (special.code - KdeSpecialKey.F1.code))
            else -> Unit
        }
    }

    // ---- media control ----

    /**
     * Whether a media session is being watched right now, and why.
     *
     * Two independent reasons want the tracking on: the panel being open, and
     * the toolbar's auto-pin watching for an allowlisted player to start. This
     * is the one place that decides, so neither reason can switch the other's
     * tracking off. Called from the panel switch, from both ends of the
     * keyboard's visible life, and whenever the settings change.
     */
    private fun syncMediaTracking() {
        val state = _uiState.value
        val forPanel = state.panel == PanelMode.MEDIA_CONTROL
        val forPin = state.settings.mediaControl.pinWhilePlaying &&
            ToolbarTool.MEDIA_CONTROL in state.settings.enabledTools
        // Nothing on screen is worth a session listener, panel included: the
        // panel is not being looked at either, and onStartInputView re-syncs
        // (and so rebinds) before the keyboard is shown again.
        if (!keyboardVisible || (!forPanel && !forPin)) {
            stopMedia()
            return
        }
        startMedia()
        // Settings can change under a live session — the allowlist edited, the
        // switch turned off, power saving arriving — so re-decide the pin here
        // instead of waiting for the player to do something.
        val pinned = pinsFor(_uiState.value.mediaControl)
        if (pinned != _uiState.value.mediaPinned) {
            _uiState.update { it.copy(mediaPinned = pinned) }
        }
    }

    /** Begin mirroring the active media session into [KeyboardUiState.mediaControl]. */
    private fun startMedia() {
        mediaController.start { snapshot ->
            // Decided before the update: [pinsFor] reads the *previous* frame
            // to hold the latch across a pause, so it must not see the new one.
            val pinned = pinsFor(snapshot)
            _uiState.update { it.copy(mediaControl = snapshot, mediaPinned = pinned) }
        }
    }

    /** Stop tracking and clear the now-playing snapshot. */
    private fun stopMedia() {
        mediaController.stop()
        if (_uiState.value.mediaControl != null || _uiState.value.mediaPinned) {
            _uiState.update { it.copy(mediaControl = null, mediaPinned = false) }
        }
    }

    /**
     * Whether [snapshot] should hold the media tool on the toolbar.
     *
     * Arms on playback from an app the user counts as a music player, then
     * stays armed while that same app keeps its session — so pausing to reply
     * to a message leaves the transport where the thumb last saw it, and the
     * pin only goes when the player does. A session handed to a different app
     * has to earn the pin again by playing.
     */
    private fun pinsFor(snapshot: MediaSnapshot?): Boolean {
        val settings = _uiState.value.settings
        if (!settings.mediaControl.pinWhilePlaying) return false
        if (ToolbarTool.MEDIA_CONTROL !in settings.enabledTools) return false
        if (snapshot == null) return false
        if (snapshot.packageName !in settings.mediaControl.musicApps) return false
        if (snapshot.playing) return true
        // Paused: hold the pin only for the app that armed it.
        return _uiState.value.mediaPinned &&
            _uiState.value.mediaControl?.packageName == snapshot.packageName
    }

    fun onMediaPlayPause() {
        vibrate()
        mediaController.playPause()
    }

    fun onMediaNext() {
        vibrate()
        mediaController.next()
    }

    fun onMediaPrevious() {
        vibrate()
        mediaController.previous()
    }

    fun onMediaSeek(positionMs: Long) {
        mediaController.seekTo(positionMs)
    }

    /**
     * The panel re-checks notification access when the keyboard returns to the
     * foreground; if it was just granted, this is what binds to the active
     * session — [MediaControlManager.start] refuses to do anything without it,
     * so every earlier attempt was a no-op.
     */
    fun onMediaResume() {
        syncMediaTracking()
    }

    /**
     * IMEs cannot show the grant dialog, and notification access is granted on a
     * system screen rather than by a dialog at all — so this goes through the
     * disclosure trampoline, which explains what the listener does (and does
     * not) read before opening the per-app notification-access page.
     */
    fun onMediaAccessRequest() {
        val component = ComponentName(this, MediaNotificationListener::class.java)
        runCatching {
            startActivity(
                SpecialAccessActivity.intent(this, SpecialAccess.NOTIFICATIONS, component)
                    .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK),
            )
        }
    }

    // ---- voice input ----

    /**
     * The languages dictation listens for (#416), the one it starts in first:
     * the input language, like handwriting, unless the user picked their own
     * on the Voice typing screen or off the panel's language chip.
     *
     * A romanized language is listened for as the language itself (#948):
     * Hinglish is heard as Hindi, by every engine and with Hindi's engine
     * settings, and [voiceRomanizedIds] writes what comes back in Latin
     * letters.
     */
    private fun voiceLanguageIds(): List<String> = RomanizedSpeech.heard(voicePickedIds())

    /** The languages dictation is in as picked, Hinglish still Hinglish; see [voiceLanguageIds]. */
    private fun voicePickedIds(): List<String> =
        _uiState.value.settings.whisper.dictationLanguages(_uiState.value.language.id)

    /** The picked languages whose script dictation writes in Latin letters (#948). */
    private fun voiceRomanizedIds(): List<String> = RomanizedSpeech.targets(voicePickedIds())

    /** Writes the native script of a romanized dictation in Latin letters (#948). */
    private val romanizedDictation by lazy { RomanizedDictation { assets.open(it) } }

    /**
     * IndicXlit's Indic-to-Latin model, which spells a romanized dictation's
     * words the maps do not know ([respellVoiceThen]). Opened by the first
     * dictation that can use it, kept until the service goes.
     */
    private val latinXlitDelegate = lazy { IndicXlit(applicationContext, IndicXlitModels.LATIN) }
    private val latinXlit by latinXlitDelegate

    /**
     * [text] as heard, with the script of each romanized language picked
     * written in Latin letters. A partial goes through it as well as the
     * finished phrase, so the words do not change script as they land.
     * Idempotent: the Latin it writes is left alone a second time.
     */
    private fun romanizedVoiceText(text: String): String {
        val ids = voiceRomanizedIds()
        return if (ids.isEmpty()) text else romanizedDictation.romanize(text, ids)
    }

    /** The language a dictation starts in; see [voiceLanguageIds]. */
    private fun voiceLanguageId(): String = voiceLanguageIds().first()

    /**
     * The engine, and the model when one is pinned, that dictation in
     * [voiceLanguageId] uses: that language's own pick from settings or the
     * panel's engine chip, else the engine picked for every language.
     */
    private fun voiceChoice(): VoiceChoiceRef = _uiState.value.settings.whisper.voiceFor(voiceLanguageId())

    /** [voiceChoice]'s engine, as a `voice_engine` value. */
    private fun voiceEngine(): String = voiceChoice().engine

    /**
     * Brings the voice state's engine, and the engine chip's list when that
     * chip is on, in line with the language about to be dictated. The list
     * walks the model folders, so it is only built for the chip.
     */
    private fun refreshVoiceEngineChoices() {
        val s = _uiState.value.settings
        val languageId = voiceLanguageId()
        val engine = voiceEngine()
        val choices = if (s.voiceBar.enginePicker) {
            VoiceChoices.choices(
                filesDir, languageId,
                whisperEnabled = isWhisperEnabled(),
                serverConfigured = s.whisper.serverFor(languageId).url.isNotBlank(),
            )
        } else {
            emptyList()
        }
        val own = s.whisper.voiceByLang[languageId].orEmpty()
        _uiState.update {
            it.copy(
                voice = it.voice.copy(
                    engine = engine, engineLanguage = languageId, engineChoices = choices, engineChoice = own,
                ),
            )
        }
    }

    /** BCP-47 tag of [voiceLanguageId], as the recognizer takes it. */
    private fun voiceLanguageTag(): String = voiceTagOf(voiceLanguageId())

    private fun voiceTagOf(languageId: String): String {
        val keyboard = _uiState.value.language
        return if (languageId == keyboard.id) keyboard.localeTag else LanguageRegistry.byId(languageId).localeTag
    }

    /**
     * The languages [startVoice] last opened the microphone for. A layout
     * switch that leaves them as they are, because dictation has its own
     * languages or the new layout types the same one, leaves the session be.
     */
    private var voiceSessionLanguages: List<String> = emptyList()

    /**
     * A pick off the voice panel's language chip (#416): [ids] become the
     * languages dictation listens for, empty to follow the keyboard again.
     * The state moves ahead of the DataStore write, as in [onVoiceModePick],
     * so a session restarted for it is already in the new language. Only a
     * microphone that is listening restarts: a phrase being transcribed or
     * tidied was said in the old language and finishes in it.
     */
    private fun onVoiceLanguagePick(ids: List<String>) {
        vibrate()
        _uiState.update {
            it.copy(settings = it.settings.copy(whisper = it.settings.whisper.copy(languages = ids)))
        }
        serviceScope.launch { settingsRepository.setVoiceLanguages(ids) }
        if (_uiState.value.voice.status == VoiceStatus.LISTENING) {
            voiceSilentRetries = 0
            startVoice()
        } else if (!voiceActive()) {
            // The offline-model chip speaks for the language on the panel.
            _uiState.update {
                it.copy(voice = it.voice.copy(languageTag = voiceLanguageTag(), modelState = VoiceModelState.UNKNOWN))
            }
        }
    }

    /** Mic button on the voice panel/strip: start, or finish the session. */
    fun onVoiceToggle() {
        vibrate()
        when (_uiState.value.voice.status) {
            VoiceStatus.LISTENING -> finishVoiceUtterance()
            // The result is coming, so there is nothing to stop — but the
            // recognizer now reaches FINISHING by itself at every pause (#315),
            // and continuous dictation would start the next phrase after it.
            // A press here means "that was the last one".
            VoiceStatus.FINISHING -> {
                voiceStopRequested = true
                dropCarriedMic()
            }
            // A phrase with the AI being tidied (#499) is the same case as
            // FINISHING: it has been heard, so the press can only mean that
            // no phrase follows it. A clip being transcribed keeps its old
            // meaning of nothing to do: the microphone carried on under it
            // (#957) is the next phrase's, and a press then finishes that.
            VoiceStatus.TRANSCRIBING -> if (_uiState.value.voice.tidying) {
                voiceStopRequested = true
                dropCarriedMic()
            }
            else -> {
                if (voiceMeteredAsked) grantMetered(MeteredFeature.CLOUD_VOICE)
                voiceSilentRetries = 0
                startVoice()
            }
        }
    }

    /** The user is done talking: what was heard so far becomes the result. */
    private fun finishVoiceUtterance() {
        voiceStopRequested = true
        if (whisperRecorder != null) {
            // Whisper: stop recording and transcribe this clip.
            finishWhisper(userStopped = true)
        } else {
            _uiState.update { it.copy(voice = it.voice.copy(status = VoiceStatus.FINISHING)) }
            voiceEngine.finish()
        }
    }

    /**
     * The voice tool pressed while a dictation runs on the strip or the panel:
     * there it is the stop button (#283). The phrase is finished the way the
     * surface's own microphone finishes it, and the surface closes once the
     * words have landed ([settleVoiceToolEnding]), so the one button that
     * starts a dictation also ends it.
     *
     * The press used to close the surface through [cancelVoice]. A clip engine
     * has nothing in the field until its clip is transcribed, so for Whisper
     * and the server that threw away everything just said. Abandoning a
     * session is still there to be had: the strip's close button and the
     * panel's keyboard key. False when no dictation is running, and the press
     * opens or closes the tool as it always did.
     */
    private fun endVoiceFromTool(): Boolean {
        val state = _uiState.value
        if (!state.voice.strip && state.panel != PanelMode.VOICE) return false
        if (!voiceActive()) return false
        vibrate()
        voiceToolEnding = true
        // Also for a clip already finishing on its own (the 30 s cap): the
        // press asked for the end of the session, not for the next clip.
        voiceStopRequested = true
        dropCarriedMic()
        if (state.voice.status == VoiceStatus.LISTENING) finishVoiceUtterance()
        return true
    }

    /**
     * A session has come to rest. If the voice tool is what ended it
     * ([endVoiceFromTool]) and the words are in the field, the surface goes
     * too. Anything else it came to rest on, an error or a blocked microphone,
     * is something the surface has to stay up to say.
     */
    private fun settleVoiceToolEnding() {
        if (!voiceToolEnding) return
        voiceToolEnding = false
        val state = _uiState.value
        if (state.voice.status != VoiceStatus.IDLE) return
        if (state.voice.strip) {
            _uiState.update { it.copy(voice = it.voice.copy(strip = false, canUndo = false)) }
        } else if (state.panel == PanelMode.VOICE) {
            // The finger left the tool a while ago: no second buzz.
            onPanelChange(PanelMode.VOICE, haptic = false)
        }
    }

    /**
     * A voice typing mode picked off the Voice tool's hold menu (#173): it
     * becomes the mode, and dictation starts in it at once.
     *
     * The state is updated ahead of the DataStore write, the way
     * [toggleVoiceBar] does for the bar: every reader of the mode
     * ([interactiveVoice], [plainVoice], the strip's chip-or-bar choice) goes
     * through `_uiState.value.settings`, and the first result of the session
     * about to start must not be judged under the mode the user just left.
     * The collector then lands the same value a frame or two later.
     *
     * A session already up restarts under the new mode — [startVoice] cancels
     * first — and otherwise the tool opens the way a tap opens it, so the
     * strip and bar reroutes still apply.
     */
    fun onVoiceModePick(mode: String) {
        if (mode !in VoiceTypingModes) return
        vibrate()
        _uiState.update {
            it.copy(settings = it.settings.copy(voiceBar = it.settings.voiceBar.copy(typingMode = mode)))
        }
        serviceScope.launch { settingsRepository.setVoiceTypingMode(mode) }
        if (voiceSessionAlive()) {
            voiceSilentRetries = 0
            startVoice()
        } else {
            runTool(ToolbarTool.VOICE)
        }
    }

    /** IMEs cannot show permission dialogs; bounce through the trampoline. */
    fun onVoicePermissionRequest() {
        startActivity(
            Intent(this, MicPermissionActivity::class.java).apply {
                addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
            }
        )
    }

    /**
     * Starts one dictation session. In block voice typing, partial results
     * stream into the editor as composing text; interactive voice typing shows
     * them on the surface only and puts nothing in the field until the phrase
     * is finished. Either way the final result commits and is learned like a
     * typed word. Dictated text arrives in final script, so the Avro
     * transliteration pipeline is bypassed entirely.
     */
    /** Whether a dictation surface is still up to receive the next utterance. */
    private fun voiceSessionAlive(): Boolean =
        _uiState.value.panel == PanelMode.VOICE || _uiState.value.voice.strip ||
            voiceBarShowing()

    private fun startVoice() {
        // A microphone held open across the last clip's transcription (#957)
        // is the new capture's to take over. However else this start ends,
        // by a refusal or by a capture that wants another microphone, it shuts.
        adoptingMic = true
        try {
            openVoiceSession()
        } finally {
            adoptingMic = false
            dropCarriedMic()
        }
    }

    private fun openVoiceSession() {
        cancelVoice()
        // The last gate for every way in (#578): with voice typing switched
        // off the microphone never opens, whatever surface asked.
        if (!_uiState.value.settings.voiceBar.enabled) return
        voiceStopRequested = false
        voiceSessionForField = fieldVoice()
        val languageIds = voiceLanguageIds()
        voiceSessionLanguages = languageIds
        refreshVoiceEngineChoices()
        // The spelling maps a romanized dictation writes with, read while the
        // first phrase is still being said.
        voiceRomanizedIds().takeIf { it.isNotEmpty() }?.let { ids ->
            serviceScope.launch(Dispatchers.Default) { romanizedDictation.prepare(ids) }
            // And the model that spells what they do not know, when it is here.
            if (latinXlitApplies(ids)) latinXlit.prepare()
        }
        val tag = voiceTagOf(languageIds.first())
        fun fail(status: VoiceStatus, message: String? = null) {
            _uiState.update {
                it.copy(
                    voice = it.voice.copy(
                        status = status, languageTag = tag, errorMessage = message,
                        partial = "", level = 0f,
                    ),
                )
            }
        }
        if (_uiState.value.secureField && !fieldVoice()) {
            // The panel shows its own notice; never open the mic here. A
            // keyboard-owned field is not the password field, so dictating
            // into one is not refused (#353).
            fail(VoiceStatus.IDLE)
            return
        }
        if (checkSelfPermission(Manifest.permission.RECORD_AUDIO) !=
            PackageManager.PERMISSION_GRANTED
        ) {
            fail(VoiceStatus.NEED_PERMISSION)
            return
        }
        var server = serverVoiceSelected()
        if (server && _uiState.value.settings.whisper.serverFor(languageIds.first()).url.isBlank()) {
            // The server engine is chosen but has no address: say so, with the
            // same way out the missing Whisper model gets.
            _uiState.update {
                it.copy(
                    voice = it.voice.copy(
                        status = VoiceStatus.IDLE, languageTag = tag, remote = true,
                        serverNeedsSetup = true, whisper = false, whisperNeedsModel = false,
                        partial = "", level = 0f, errorMessage = null,
                    ),
                )
            }
            return
        }
        // No connection, and the user asked for the device to stand in (#452):
        // a downloaded Whisper model for this language, else the system
        // recognizer, instead of a clip nobody can send.
        val offlineVoice = server && offlineFallbackNow()
        if (offlineVoice) server = false
        if (offlineVoice) noteOfflineFallback(OFFLINE_FALLBACK_VOICE, true)
        voiceMeteredAsked = false
        if (server) {
            val decision = dataSaverStatus.decide(MeteredFeature.CLOUD_VOICE)
            if (decision != MeteredDecision.ALLOWED) {
                voiceMeteredAsked = decision == MeteredDecision.ASK
                fail(
                    VoiceStatus.ERROR,
                    getString(
                        if (voiceMeteredAsked) {
                            R.string.ime_voice_server_metered_ask
                        } else {
                            R.string.ime_voice_server_metered_blocked
                        },
                    ),
                )
                return
            }
        }
        val onDevice = if (offlineVoice) fallbackOnDeviceVoice() else onDeviceVoice()
        val engine = voiceEngine()
        val whisperSelected = isWhisperEnabled() && engine == "whisper"
        // Whistle only answers for its seven languages (#548). Any other is
        // the system recognizer's, with no prompt: there is no model that
        // would help.
        val whistleSelected = engine == "whistle" && whistleCoversVoice()
        // The ExecuTorch engines (Asr4All and Moonshine English, Parakeet 25
        // European languages) leave any other language the same way.
        val etSelected = EtEngine.byId(engine)?.let(::etCoversVoice) == true
        if ((whisperSelected || whistleSelected || etSelected) && onDevice == null) {
            // An offline engine is chosen but its model is not downloaded —
            // prompt for one instead of opening the mic to no purpose.
            _uiState.update {
                it.copy(
                    voice = it.voice.copy(
                        status = VoiceStatus.IDLE, languageTag = tag, whisper = true,
                        whisperNeedsModel = true, remote = false, serverNeedsSetup = false,
                        partial = "", level = 0f, errorMessage = null,
                    ),
                )
            }
            return
        }
        // Another app's recognition service, when the user picked one (#993).
        voiceEngine.service = _uiState.value.settings.whisper.systemService
            .takeIf { it.isNotBlank() }
            ?.let(android.content.ComponentName::unflattenFromString)
        if (!server && onDevice == null && !voiceEngine.isAvailable()) {
            fail(VoiceStatus.UNAVAILABLE)
            return
        }
        if (onDevice is OnDeviceVoice.Whisper && !onDevice.model.ggml && !WhisperEngine.ready) {
            // Play only: the interpreter is an on-demand part that is not here
            // yet. Said now rather than after the phrase, which would be
            // recorded for nothing. Data saver holding downloads leaves the
            // fetch to the settings screen, which asks properly.
            if (dataSaverStatus.allows(MeteredFeature.DOWNLOADS)) WhisperEngine.requestModule()
            fail(VoiceStatus.ERROR, getString(VoiceR.string.core_voice_whisper_module_downloading))
            return
        }
        val sherpa = (onDevice as? OnDeviceVoice.Et)?.model?.engine?.onnx == true
        val needsSpeechLibs = (onDevice is OnDeviceVoice.Whisper && onDevice.model.ggml) ||
            onDevice == OnDeviceVoice.Whistle
        if (needsSpeechLibs && !WhisperCpp.moduleReady) {
            // The same way where the libraries are fetched rather than
            // carried: whisper.cpp's and Whistle's are the :feature:speech part.
            if (dataSaverStatus.allows(MeteredFeature.DOWNLOADS)) WhisperCpp.requestModule()
            fail(VoiceStatus.ERROR, getString(VoiceR.string.core_voice_whisper_module_downloading))
            return
        }
        if (sherpa && !SherpaNative.moduleReady) {
            // Sherpa's and Omnilingual's runtime is its own part, ONNX Runtime
            // and the bridge (:feature:onnx on Play, the onnx gate elsewhere).
            if (dataSaverStatus.allows(MeteredFeature.DOWNLOADS)) SherpaNative.requestModule()
            fail(VoiceStatus.ERROR, getString(VoiceR.string.core_voice_whisper_module_downloading))
            return
        }
        if (onDevice is OnDeviceVoice.Et && !sherpa && !FeatureModules.executorch.installed) {
            // ExecuTorch is its own part (:feature:executorch), shared with
            // the FUTO Swipe glide engine.
            if (dataSaverStatus.allows(MeteredFeature.DOWNLOADS)) FeatureModules.executorch.requestInstall()
            fail(VoiceStatus.ERROR, getString(VoiceR.string.core_voice_whisper_module_downloading))
            return
        }
        if (!voiceSessionForField) {
            val ic = currentInputConnection ?: return
            // Flush the half-typed word so dictation appends after it.
            commitComposing(ic, autocorrect = false)
            refreshVoiceContext()
        }
        val generation = ++voiceGeneration
        voiceListenStartedAt = SystemClock.uptimeMillis()
        // Offline-model chip: check once per language, not per utterance
        // (continuous mode restarts sessions constantly).
        val modelKnown = _uiState.value.voice.modelState != VoiceModelState.UNKNOWN &&
            _uiState.value.voice.languageTag == tag
        _uiState.update {
            it.copy(
                voice = it.voice.copy(
                    status = VoiceStatus.LISTENING, languageTag = tag,
                    partial = "", level = 0f, errorMessage = null, secondsLeft = 0, clipHeard = false,
                    whisper = onDevice != null,
                    remote = server,
                    translate = _uiState.value.settings.whisper.translate && onDevice is OnDeviceVoice.Whisper,
                    whisperNeedsModel = false,
                    serverNeedsSetup = false,
                ),
            )
        }
        // The microphone picked on the panel or in settings (#581), when it is
        // plugged in. Taken before either engine opens the microphone, so the
        // first words already come through the headset.
        val mic = voiceMicKind()
        voiceMicRoute.hold(mic)
        if (onDevice != null || server) {
            startWhisperCapture(onDevice, generation, mic)
            return
        }
        noteVoiceMic(VoiceMics.deviceFor(this, mic) ?: VoiceMics.autoDevice(this))
        if (!modelKnown) refreshVoiceModelState(tag)
        voiceEngine.start(
            tag,
            // The phone's own recognizer first unless the user turned that
            // off; VoiceInputEngine also leaves it for one it hears stall.
            allowOnDevice = _uiState.value.settings.whisper.systemOnDevice,
            // Plain voice typing wants the words and nothing else, so the
            // recognizer is asked for no punctuation and no capital letters.
            formatting = !plainVoice(),
            bias = recognizerBias(),
            alsoListenFor = languageIds.drop(1).map(::voiceTagOf),
            listener = object : VoiceInputEngine.Listener {
                override fun onListening() {
                    if (generation != voiceGeneration) return
                    // The recognizer records in its own process, so there is no
                    // session id to narrow to. Starting only now, with its
                    // capture open, keeps a stale capture from being blamed.
                    micBlockWatcher.start(audioSessionId = null) { onMicBlocked(generation) }
                }

                override fun onLevel(level: Float) {
                    if (generation != voiceGeneration) return
                    // Quantized so the pulse ring doesn't force a state
                    // update (and recomposition) per rms callback.
                    val quantized = (level * 8).toInt() / 8f
                    _uiState.update {
                        if (it.voice.level == quantized) it
                        else it.copy(voice = it.voice.copy(level = quantized))
                    }
                }

                override fun onEndOfSpeech() {
                    if (generation != voiceGeneration) return
                    // The recognizer has stopped hearing and is only working
                    // out the words now. Left on "listening", the mic kept
                    // looking open while the user talked into nothing (#315).
                    _uiState.update {
                        if (it.voice.status != VoiceStatus.LISTENING) {
                            it
                        } else {
                            it.copy(voice = it.voice.copy(status = VoiceStatus.FINISHING, level = 0f))
                        }
                    }
                }

                override fun onPartial(text: String) {
                    if (generation != voiceGeneration) return
                    val shown = romanizedVoiceText(text)
                    // Interactive voice typing never writes a partial into the
                    // field. A partial is cumulative — the next one rewrites
                    // the whole composing region — so keeping one there is
                    // exactly what stops the keys being used at the same time.
                    // The phrase lands whole at the next pause; until then it
                    // is only in the status line.
                    // Nor does a dictation into one of the keyboard's own
                    // fields (#353): its words were never going to the app.
                    if (!interactiveVoice() && !voiceSessionForField) {
                        currentInputConnection
                            ?.setComposingText(spacedVoiceText(casedVoiceText(shown)), 1)
                    }
                    _uiState.update { it.copy(voice = it.voice.copy(partial = shown)) }
                }

                override fun onFinal(text: String) {
                    if (generation != voiceGeneration) return
                    voiceGeneration++
                    micBlockWatcher.stop()
                    val landed = commitVoiceUtterance(text, tag)
                    voiceSilentRetries = 0
                    tidyVoiceThen(landed) { afterVoiceFinal() }
                }

                /** The phrase is in the field, tidied or not: chain or come to rest. */
                private fun afterVoiceFinal() {
                    if (voiceChains() && !voiceStopRequested && voiceSessionAlive()) {
                        // Continuous dictation: chain straight into the next
                        // utterance until the user stops or leaves. Deferred
                        // to the next looper tick — starting a new recognizer
                        // synchronously from inside the old one's onResults
                        // callback races its teardown and spuriously fires
                        // onError (ERROR_CLIENT) on some OEM builds even
                        // though this utterance already succeeded.
                        _uiState.update { it.copy(voice = it.voice.copy(partial = "", level = 0f, canUndo = true)) }
                        serviceScope.launch(Dispatchers.Main) { startVoice() }
                    } else {
                        _uiState.update {
                            it.copy(
                                voice = it.voice.copy(
                                    status = VoiceStatus.IDLE, partial = "", level = 0f, canUndo = !voiceSessionForField,
                                ),
                            )
                        }
                        settleVoiceToolEnding()
                    }
                }

                override fun onError(kind: VoiceInputEngine.ErrorKind) {
                    if (generation != voiceGeneration) return
                    voiceGeneration++
                    micBlockWatcher.stop()
                    // A network drop mid-utterance keeps whatever was heard.
                    // Interactive voice typing owns no composing region, and
                    // the one in the field may be a word the user is typing
                    // right now — leave it alone.
                    if (!interactiveVoice() && !voiceSessionForField) currentInputConnection?.finishComposingText()
                    // Silence in continuous mode restarts quietly — but not
                    // forever, so an abandoned open mic winds down.
                    if (kind == VoiceInputEngine.ErrorKind.NO_SPEECH &&
                        voiceChains() &&
                        !voiceStopRequested && voiceSessionAlive() &&
                        voiceSilentRetries < voiceSilentRetryLimit()
                    ) {
                        voiceSilentRetries++
                        serviceScope.launch(Dispatchers.Main) { startVoice() }
                        return
                    }
                    val (status, message) = when (kind) {
                        VoiceInputEngine.ErrorKind.NO_SPEECH -> VoiceStatus.IDLE to null
                        VoiceInputEngine.ErrorKind.PERMISSION -> VoiceStatus.NEED_PERMISSION to null
                        VoiceInputEngine.ErrorKind.NETWORK ->
                            VoiceStatus.ERROR to getString(CommonR.string.common_error_network)
                        VoiceInputEngine.ErrorKind.BUSY ->
                            VoiceStatus.ERROR to getString(R.string.ime_service_voice_error_busy)
                        VoiceInputEngine.ErrorKind.LANGUAGE ->
                            VoiceStatus.ERROR to getString(R.string.ime_service_voice_error_language)
                        VoiceInputEngine.ErrorKind.OTHER ->
                            VoiceStatus.ERROR to getString(R.string.ime_service_voice_error_other)
                    }
                    _uiState.update {
                        it.copy(
                            voice = it.voice.copy(
                                status = status, languageTag = tag, errorMessage = message,
                                partial = "", level = 0f,
                            ),
                        )
                    }
                    // Nothing heard after the tool's stop is still a finished
                    // session; a real error keeps the surface up to say so.
                    settleVoiceToolEnding()
                }
            },
        )
    }

    /**
     * The offline Whisper model to run for the language currently being typed in,
     * or null when Whisper isn't the selected engine, isn't built into this
     * flavor, or has no model downloaded yet.
     *
     * Resolving per language rather than globally is what lets dictation follow
     * the layout the way the system recognizer's locale does: switching to the
     * German layout switches to whatever model handles German.
     */
    /** The transcription server is the chosen engine (#286). Every flavour has it. */
    private fun serverVoiceSelected(): Boolean =
        voiceEngine() == "server"

    /**
     * Whether a request that would go to a server goes to the device instead
     * before it is even tried (#452): the user asked for that, and there is no
     * connection to send it over.
     */
    private fun offlineFallbackNow(): Boolean =
        _uiState.value.settings.dataSaver.offlineFallback && !networkWatcher.state.value.online

    /** The features [noteOfflineFallback] has already told the user about. */
    private val offlineFallbackNoted = HashSet<String>()

    /**
     * Tells the user, once, that [feature] has moved to the on-device model
     * (#452) when [fellBack], or forgets that it had when the server answered
     * again, so the next move is told too. Once rather than per request: a
     * continuous dictation or a translation typed a letter at a time would
     * otherwise put a message up for every phrase. Main thread.
     */
    private fun noteOfflineFallback(feature: String, fellBack: Boolean) {
        if (!fellBack) {
            offlineFallbackNoted -= feature
            return
        }
        if (!offlineFallbackNoted.add(feature)) return
        Toast.makeText(this, getString(R.string.ime_offline_fallback_toast), Toast.LENGTH_SHORT).show()
    }

    /**
     * The on-device model for dictation to fall back on (#452), whichever
     * engine is picked: Whistle when it covers what is being dictated and is
     * downloaded, since it is the quicker of the two, else the downloaded
     * Whisper model for the language being typed in. Null when there is
     * neither, or no runtime to run that model with yet (a LiteRT graph on
     * Play before its part has arrived; whisper.cpp is always in the app).
     */
    private fun fallbackOnDeviceVoice(): OnDeviceVoice? {
        if (whistleCoversVoice() && WhistleModelStore.isDownloaded(filesDir)) return OnDeviceVoice.Whistle
        for (engine in EtEngine.entries) {
            if (etCoversVoice(engine)) {
                EtStore.active(filesDir, engine, voiceLanguageIds())?.let { return OnDeviceVoice.Et(it) }
            }
        }
        if (!isWhisperEnabled()) return null
        val s = _uiState.value.settings
        return WhisperStore.modelForLanguage(
            filesDir,
            voiceLanguageId(),
            s.whisper.modelId,
            s.whisper.modelByLang,
        )?.takeIf { it.ggml || WhisperEngine.ready }?.let { OnDeviceVoice.Whisper(it) }
    }

    /**
     * Whistle can run here and knows every language the dictation listens for
     * (#548). It takes one language or detects among its own seven, so a
     * dictation in several (#416) is Whistle's only when all of them are.
     */
    private fun whistleCoversVoice(): Boolean =
        WhistleEngine.shipped && voiceLanguageIds().all(WhistleLanguages::supports)

    /** [engine] can run here and transcribes every language the dictation listens for. */
    private fun etCoversVoice(engine: EtEngine): Boolean =
        engine.runtimeShipped && voiceLanguageIds().all(engine::supports)

    /**
     * Whether [engine] decodes while the user speaks rather than when the clip
     * ends. Omnilingual counts: it decodes each phrase at the pause after it.
     */
    private fun liveEngine(engine: EtEngine): Boolean =
        engine == EtEngine.ASR4ALL || engine == EtEngine.SHERPA || engine == EtEngine.OMNILINGUAL

    /** The one thread [engine]'s model calls run on. */
    private fun liveDispatcher(engine: EtEngine): CoroutineDispatcher =
        if (engine.onnx) SherpaNative.dispatcher else EtNative.dispatcher

    /**
     * A fresh streaming utterance on [model], which ends by itself after the
     * pause set in "Stop after a pause", heard by the phrase end detector the
     * user picked (#976). Sherpa listens for [words] ([liveBias]). On
     * [liveDispatcher] only.
     */
    private fun newLiveStream(model: EtModel, words: List<String>): VoiceStream {
        val settings = _uiState.value.settings
        val pauseMs = settings.voiceBar.silenceStopMs
        val vad = VoiceVad.Setup(settings.whisper.vad, settings.whisper.vadThreshold, settings.whisper.smartTurn)
        return when (model.engine) {
            EtEngine.SHERPA -> SherpaEngine.newStream(filesDir, model, pauseMs, words, vad)
            EtEngine.OMNILINGUAL -> OmnilingualEngine.newStream(filesDir, model, pauseMs, voiceLanguageIds(), vad)
            // Its model carries no Silero; the detector picks from what is here.
            else -> VoiceVad.endpointed(
                Asr4AllEngine.newStream(filesDir, model),
                VoiceVad.phraseEnd(filesDir, vad, null, pauseMs),
            )
        }
    }

    /**
     * Frees a streaming utterance nobody will finish. Only Sherpa's and
     * Omnilingual's hold native memory (asr4all's is the heap's), and they are
     * closed on their own thread, after the feeding job's last call.
     */
    private fun dropLiveCapture(capture: Asr4AllCapture?) {
        val stream = capture?.stream as? AutoCloseable ?: return
        serviceScope.launch(SherpaNative.dispatcher) { runCatching { stream.close() } }
    }

    /**
     * The words a [model] that streams is told to listen for: the system
     * recognizer's list for Sherpa, whose transducers take hotwords; none for
     * the others. Read on the main thread, where the list is kept.
     */
    private fun liveBias(model: EtModel): List<String> =
        if (model.engine == EtEngine.SHERPA) recognizerBias().words else emptyList()

    /** [pcm] through a [model] that downloads file by file, in one go. On [liveDispatcher] only. */
    private fun transcribeWithEt(model: EtModel, pcm: FloatArray, words: List<String>): String = when (model.engine) {
        // The streaming loop run to its end.
        EtEngine.ASR4ALL, EtEngine.SHERPA, EtEngine.OMNILINGUAL -> newLiveStream(model, words).run {
            feed(pcm)
            finish()
        }
        EtEngine.PARAKEET -> ParakeetEngine.transcribe(filesDir, model, pcm)
        EtEngine.MOONSHINE -> MoonshineEngine.transcribe(filesDir, model, pcm)
    }

    /**
     * Whether [model]'s phrases get marks and capitals from
     * [DictationPunctuation]: it writes none of its own, Add punctuation and
     * capitals is on, and the typing mode is not plain, which types the words
     * exactly as they were said. Nor in the keyboard's own boxes (#353): a
     * search is a phrase, not a sentence.
     */
    private fun voicePunctuates(model: EtModel): Boolean =
        DictationPunctuation.needed(model) && _uiState.value.settings.whisper.punctuate && !plainVoice() &&
            !voiceSessionForField

    /**
     * [text], a finished phrase from [model] in [languages], punctuated when
     * [voicePunctuates] says so and a model for the languages is on the
     * phone; as it was otherwise, or when the model fails. The model runs on
     * [SherpaNative.dispatcher].
     *
     * Spoken punctuation goes first, here rather than only at the commit:
     * "comma" typed as a word would get a mark of the model's after it, and
     * then its own. The model puts nothing after a mark already there, and
     * the commit's own pass finds nothing left to turn into one.
     */
    private suspend fun punctuateDictation(model: EtModel, text: String, languages: List<String>, tag: String): String {
        if (text.isBlank() || !voicePunctuates(model)) return text
        val spoken = if (_uiState.value.settings.voiceSpokenPunctuation) VoicePunctuation.apply(text, tag) else text
        return withContext(SherpaNative.dispatcher) {
            runCatching { DictationPunctuation.punctuate(filesDir, spoken, languages) }.getOrDefault(text)
        }
    }

    /**
     * Names in a punctuated phrase spelled the way the keyboard's word lists
     * and its memory of the user's capitals spell them ("london" becomes
     * "London"): the punctuation model writes only sentence capitals. Only
     * words with no capital yet are asked about. Main thread, where the
     * suggestion engine is used.
     */
    private fun withListCapitals(text: String): String {
        val engine = suggestionEngine ?: return text
        return VOICE_CASED_WORD.replace(text) { match ->
            val word = match.value
            if (word.any { it.isUpperCase() } || word.none { it.isLowerCase() }) {
                word
            } else {
                engine.displayOf(word).takeIf { it != word && it.equals(word, ignoreCase = true) } ?: word
            }
        }
    }

    /**
     * [pcm] transcribed by [model] the way [finishWhisper] does it, for a clip
     * recorded for the server that could not be sent (#452). Blocking; call off
     * the main thread.
     */
    private fun transcribeOnDevice(voice: OnDeviceVoice, pcm: FloatArray, languages: List<String>, tag: String): String {
        val model = when (voice) {
            is OnDeviceVoice.Whisper -> voice.model
            OnDeviceVoice.Whistle -> return transcribeWithWhistle(pcm, languages, recognizerBias().words)
            is OnDeviceVoice.Et -> {
                val words = liveBias(voice.model)
                return runBlocking(liveDispatcher(voice.model.engine)) {
                    punctuateDictation(voice.model, transcribeWithEt(voice.model, pcm, words), languages, tag)
                }
            }
        }
        if (model.ggml) {
            val translate = _uiState.value.settings.whisper.translate && model.supportsTranslate
            return transcribeWithCpp(model, pcm, languages, recognizerBias().words, translate).orEmpty()
        }
        // As in [finishWhisper]: a choice of several languages is left to the
        // model to tell apart.
        val langToken = languages.singleOrNull()?.let(model::langTokenFor)
        val translate = _uiState.value.settings.whisper.translate && model.supportsTranslate
        val text = WhisperEngine.transcribe(
            WhisperStore.modelFile(filesDir, model),
            WhisperStore.vocabFile(filesDir, model),
            pcm,
            translate,
            langToken,
        ).trim()
        // As in [finishWhisper]: only a graph left to detect the language can
        // answer in the wrong script.
        return if (langToken == null && model.fixedLang == null) WhisperScript.rescueAmong(text, languages) else text
    }

    /**
     * [pcm] transcribed by Whistle (#548). One language is named to it; a
     * dictation in several (#416) is left for it to tell apart. [keywords] are
     * the same words the system recognizer is told to listen for. Blocking;
     * call off the main thread.
     */
    private fun transcribeWithWhistle(pcm: FloatArray, languages: List<String>, keywords: List<String>): String =
        WhistleEngine.transcribe(
            WhistleModelStore.modelFile(filesDir),
            pcm,
            language = languages.singleOrNull(),
            keywords = keywords,
        ).trim()

    /**
     * [pcm] transcribed by a whisper.cpp [model] (#440), or null when
     * [cancelVoice] stopped it part way. Unlike a LiteRT graph it is told every
     * language of the dictation by name: one is forced, several are the only
     * ones it chooses among. [words] become its prompt, so names and terms come
     * out spelled the user's way. A language Whisper does not know leaves it
     * to detect among all of its own, and only then can it answer in the wrong
     * script. Blocking; call off the main thread.
     */
    private fun transcribeWithCpp(
        model: WhisperModel,
        pcm: FloatArray,
        languages: List<String>,
        words: List<String>,
        translate: Boolean,
    ): String? {
        val codes = WhisperCppPlan.languages(model, languages)
        val result = WhisperCpp.transcribe(
            WhisperStore.modelFile(filesDir, model),
            pcm,
            codes,
            translate,
            WhisperCppPlan.prompt(words),
            WhisperCppPlan.beamSize(model),
            WhisperCppPlan.wantsGpu(model, _uiState.value.settings.whisper.compute),
        ) ?: return null
        val detected = model.multilingual && codes.isEmpty()
        return if (detected) WhisperScript.rescueAmong(result.text, languages) else result.text
    }

    /**
     * What the system recognizer is told to listen for (#305): the user's own
     * list first, then their words from [voiceBiasPersonal]. Asks for another
     * look at those for next time, if the last one is old.
     */
    private fun recognizerBias(): VoiceBiasRequest {
        val whisper = _uiState.value.settings.whisper
        refreshVoiceBias()
        val personal = if (whisper.biasPersonalWords) voiceBiasPersonal else emptyList()
        return VoiceBiasRequest(
            words = VoiceBias.select(VoiceBias.parseList(whisper.biasWords), personal, VoiceBias.RECOGNIZER_LIMIT),
            // The recognizer's own knowledge of the phone (contacts, apps) is
            // the "on the device" half of the same wish, and never passes
            // through the keyboard.
            deviceContext = whisper.biasPersonalWords,
        )
    }

    /**
     * Gathers [voiceBiasPersonal] again off the main thread, at most every
     * [VOICE_BIAS_TTL_MS], and only while it can be used: the setting on and
     * an engine that takes a hint picked (the system recognizer, Whistle's
     * keywords, a whisper.cpp model's prompt, or Sherpa's hotwords; a LiteRT
     * graph takes none, but which kind a clip goes to is only known per
     * language). The server
     * engine gathers its own at the moment it sends, since it is already off
     * the main thread then.
     */
    private fun refreshVoiceBias() {
        val whisper = _uiState.value.settings.whisper
        if (!whisper.biasPersonalWords || voiceEngine() !in VOICE_BIAS_ENGINES) return
        val now = SystemClock.elapsedRealtime()
        if (voiceBiasJob?.isActive == true) return
        if (voiceBiasStamp != 0L && now - voiceBiasStamp < VOICE_BIAS_TTL_MS) return
        voiceBiasStamp = now
        voiceBiasJob = serviceScope.launch(Dispatchers.Default) {
            voiceBiasPersonal = runCatching { personalVoiceWords(VoiceBias.RECOGNIZER_LIMIT) }
                .getOrDefault(emptyList())
        }
    }

    /**
     * The user's own words for dictation to listen for (#305), most telling
     * first, at most about [limit] of the learned ones:
     *
     * 1. Words added by hand: the user said outright these are words.
     * 2. Android's personal dictionary, when the keyboard reads it at all.
     * 3. Words the keyboard learned from typing that no loaded word list has,
     *    most used first. Those are the names and the jargon a recognizer
     *    spells its own way; a common word it already knows is no help.
     *
     * Never contacts: the recognizer is told it may use the phone's own
     * context instead, and a server has no business with the address book.
     * Blocking; call off the main thread.
     */
    private fun personalVoiceWords(limit: Int): List<String> {
        val state = _uiState.value
        val lexicon = userLexicon.allWords()
        val byHand = lexicon
            .filter { userLexicon.isAddedByHand(it.first) }
            .sortedByDescending { it.second }
            .map { it.first }
        val system = if (state.settings.suggestionStrip.useSystemDictionary) {
            runCatching { SystemUserDictionary.spellings(applicationContext) }.getOrDefault(emptyList())
        } else {
            emptyList()
        }
        val engine = suggestionEngine
        val unlisted = lexicon.asSequence()
            .filter { (word, _) -> word.length > 1 && !userLexicon.isAddedByHand(word) }
            .sortedByDescending { it.second }
            .map { it.first }
            .filter { engine?.inDictionaries(it.lowercase(), includePlatform = false) != true }
            .take(limit)
            .toList()
        return byHand + system + unlisted
    }

    private fun onDeviceVoice(): OnDeviceVoice? {
        val s = _uiState.value.settings
        val choice = voiceChoice()
        return when (choice.engine) {
            "whisper" -> if (!isWhisperEnabled()) {
                null
            } else {
                // A model pinned to the language off the engine chip or the
                // per-language setting, while it is still on the phone.
                (
                    choice.modelId?.let(WhisperCatalog::byId)?.takeIf { WhisperStore.isDownloaded(filesDir, it) }
                        ?: WhisperStore.modelForLanguage(
                            filesDir,
                            voiceLanguageId(),
                            s.whisper.modelId,
                            s.whisper.modelByLang,
                        )
                    )?.let { OnDeviceVoice.Whisper(it) }
            }
            "whistle" -> OnDeviceVoice.Whistle.takeIf {
                whistleCoversVoice() && WhistleModelStore.isDownloaded(filesDir)
            }
            else -> EtEngine.byId(choice.engine)
                ?.takeIf(::etCoversVoice)
                ?.let { engine ->
                    choice.modelId?.let(EtCatalog::byId)
                        ?.takeIf { model ->
                            model.engine == engine && voiceLanguageIds().all(model::supports) &&
                                EtStore.isDownloaded(filesDir, model)
                        }
                        ?: EtStore.active(filesDir, engine, voiceLanguageIds())
                }
                ?.let { OnDeviceVoice.Et(it) }
        }
    }

    /**
     * Records audio for offline Whisper. Unlike the streaming system recognizer,
     * Whisper transcribes a whole clip, so nothing commits until recording stops
     * (a mic tap, or the 30-second window filling). The pulse ring follows the
     * mic level while recording.
     *
     * A null [model] records the clip for the transcription server instead:
     * the capture is the same, only [finishWhisper] sends it somewhere else.
     */
    private fun startWhisperCapture(model: OnDeviceVoice?, generation: Int, mic: String) {
        val languages = voiceLanguageIds()
        val languageId = languages.first()
        whisperCapture = model?.let { it to languageId }
        serverCapture = if (model == null) languageId else null
        captureLanguages = languages
        // whisper.cpp reads past one 30-second window, so its clips get room,
        // and so do the engines that decode as they hear.
        val live = (model as? OnDeviceVoice.Et)?.model?.engine?.let(::liveEngine) == true
        val cpp = (model as? OnDeviceVoice.Whisper)?.model?.ggml == true || live
        val maxSeconds = when {
            cpp -> WhisperCppPlan.MAX_CLIP_SECONDS
            (model as? OnDeviceVoice.Et)?.model?.engine == EtEngine.PARAKEET -> ParakeetEngine.MAX_CLIP_SECONDS
            else -> WhisperMel.CHUNK_SECONDS
        }
        // A clip that ends by itself leaves the microphone open for the next
        // one (#957), unless the engine decodes the clip as it records. When
        // the next clip is sure to follow, the window's last seconds end it
        // at a pause, and nothing said after the window is lost, so there is
        // nothing to count down to either.
        val rolls = !live && voiceChains()
        // An engine that decodes as it hears ends the clip by its own phrase
        // end detector (#976); the recorder's loudness stop would cut in
        // ahead of a model the user picked over it.
        val silenceStopMs = if (live) 0 else _uiState.value.settings.voiceBar.silenceStopMs
        val denoiseLevel = _uiState.value.settings.whisper.denoise
        val setup = CaptureSetup(
            mic = mic,
            maxSeconds = maxSeconds,
            silenceStopMs = silenceStopMs,
            pauseCutSeconds = if (rolls) VOICE_PAUSE_CUT_SECONDS else 0,
            denoise = if (model != null) denoiseLevel else VoiceDenoise.OFF,
        )
        // The microphone the last clip left open, holding what was said while
        // that clip was transcribed. One that stopped meanwhile with nothing
        // worth transcribing is left for [startVoice] to shut.
        val carried = carriedMic?.takeIf { !live && it.setup == setup }?.recorder
            ?.takeIf { it.isRecording || it.sampleCount >= VoiceClipGate.MIN_SAMPLES }
        if (carried != null) carriedMic = null
        // Reduce background noise in front of an on-device engine, never the
        // server, which gets the microphone as it is. Light (RNNoise) rides
        // the speech libraries, Strong (DPDFNet) ONNX Runtime and a model of
        // its own; Strong without them runs as Light, and a level whose
        // libraries are not here yet lets the phrase through as recorded.
        // Either way the missing libraries are fetched for the next one; the
        // model only ever downloads from the settings screen. A carried
        // microphone keeps the denoiser it has.
        val denoise = if (carried == null && model != null && denoiseLevel != VoiceDenoise.OFF) {
            VoiceDenoise.newStream(denoiseLevel, filesDir).also {
                val downloads = dataSaverStatus.allows(MeteredFeature.DOWNLOADS)
                if (denoiseLevel == VoiceDenoise.STRONG && !SherpaNative.moduleReady && downloads) {
                    SherpaNative.requestModule()
                }
                if (it == null && !WhisperCpp.moduleReady && downloads) WhisperCpp.requestModule()
            }
        } else {
            null
        }
        lateinit var recorder: WhisperRecorder
        val onLevel: (Float) -> Unit = level@{ level ->
            if (generation != voiceGeneration) return@level
            val quantized = (level * 8).toInt() / 8f
            // The clip ends by itself when the window fills, and words said
            // after that are lost, so its last seconds count down (#315).
            val left = recorder.secondsLeft.takeIf { !rolls && it <= VOICE_COUNTDOWN_SECONDS } ?: 0
            val heard = recorder.heardSpeech
            _uiState.update {
                if (it.voice.level == quantized && it.voice.secondsLeft == left && it.voice.clipHeard == heard) it
                else it.copy(voice = it.voice.copy(level = quantized, secondsLeft = left, clipHeard = heard))
            }
        }
        // Buffer full (30 s, or longer for whisper.cpp), or a pause (#500),
        // which ends the clip the way it ends a sentence for the system
        // recognizer; with "Keep listening" off that also ends the session,
        // the hands-free stop the setting is for. Either way this clip is
        // transcribed, and continuous mode then starts the next one on its
        // own. Called on the reader thread, which carries on recording when
        // the clip carries over, so the clip is finished on the main one.
        val onClipEnd: () -> Unit = {
            serviceScope.launch(Dispatchers.Main) {
                if (generation == voiceGeneration && whisperRecorder === recorder) finishWhisper(userStopped = false)
            }
        }
        val onLost: () -> Unit = { onWhisperCaptureLost(generation) }
        recorder = carried?.also { it.resume(onLevel, onClipEnd, onLost, onClipEnd) } ?: WhisperRecorder(
            onLevel = onLevel,
            onMaxReached = onClipEnd,
            onLost = onLost,
            silenceStopMs = silenceStopMs,
            onSilence = onClipEnd,
            preferredDevice = VoiceMics.deviceFor(this, mic),
            maxSeconds = maxSeconds,
            denoise = denoise,
            carryOver = !live,
            pauseCutSeconds = setup.pauseCutSeconds,
        )
        if (carried == null && !recorder.start()) {
            _uiState.update {
                it.copy(
                    voice = it.voice.copy(
                        status = VoiceStatus.ERROR, partial = "", level = 0f,
                        errorMessage = getString(R.string.ime_service_voice_mic_error),
                    ),
                )
            }
            return
        }
        whisperRecorder = recorder
        captureSetup = setup
        // The carried clip filled, or the microphone went, while the last one
        // was transcribed: what it holds goes to be transcribed now, and the
        // phrase after it gets a microphone of its own.
        if (carried != null && !recorder.isRecording) onClipEnd()
        noteVoiceMic(recorder.routedDevice ?: VoiceMics.deviceFor(this, mic) ?: VoiceMics.autoDevice(this))
        // A blocked mic records zeros, and Whisper turns a silent clip into
        // confident filler text, so catch it before anything is transcribed.
        micBlockWatcher.start(recorder.audioSessionId) { onMicBlocked(generation) }
        // The graph loads while the phrase is being said rather than after it.
        when (model) {
            is OnDeviceVoice.Whisper -> serviceScope.launch(Dispatchers.Default) {
                if (model.model.ggml) {
                    // A damaged file throws here; transcribing says so properly.
                    runCatching {
                        WhisperCpp.warm(
                            WhisperStore.modelFile(filesDir, model.model),
                            WhisperCppPlan.wantsGpu(model.model, _uiState.value.settings.whisper.compute),
                        )
                    }
                } else {
                    WhisperEngine.warm(
                        WhisperStore.modelFile(filesDir, model.model),
                        WhisperStore.vocabFile(filesDir, model.model),
                    )
                }
            }
            // A damaged file throws here; transcribing says so properly.
            OnDeviceVoice.Whistle -> serviceScope.launch(Dispatchers.Default) {
                runCatching { WhistleEngine.warm(WhistleModelStore.modelFile(filesDir)) }
            }
            is OnDeviceVoice.Et -> if (liveEngine(model.model.engine)) {
                startAsr4AllStream(model.model, recorder, generation)
            } else {
                // A damaged file throws here; transcribing says so properly.
                serviceScope.launch(EtNative.dispatcher) {
                    runCatching {
                        when (model.model.engine) {
                            EtEngine.PARAKEET -> ParakeetEngine.warm(filesDir, model.model)
                            else -> MoonshineEngine.warm(filesDir, model.model)
                        }
                    }
                }
            }
            null -> Unit
        }
    }

    /**
     * Decodes the clip in [recorder] while it is still being said (#289): every
     * [VOICE_PARTIAL_POLL_MS] the new samples go into an asr4all or Sherpa
     * stream, and what it has heard so far goes on the line under the
     * microphone. When the clip ends, [finishAsr4All] needs only decode the
     * last moment. A model that will not load is left for [finishAsr4All] to
     * report. The stream also hears the phrase end (the detector picked in
     * settings, #976), and ends the clip there the way the recorder's own
     * silence stop does for the engines that record a whole clip.
     *
     * In block voice typing the words also go into the field as composing
     * text, underlined and rewritten as they grow, exactly like the system
     * recognizer's partials; the finished phrase then replaces them. Typing
     * while you speak keeps them on the line only, for the same reason it does
     * for the recognizer, and so does a dictation into one of the keyboard's
     * own boxes.
     */
    private fun startAsr4AllStream(model: EtModel, recorder: WhisperRecorder, generation: Int) {
        asr4allCapture = null
        asr4allComposed = false
        asr4allJob?.cancel()
        val words = liveBias(model)
        asr4allJob = serviceScope.launch(liveDispatcher(model.engine)) {
            val stream = runCatching { newLiveStream(model, words) }.getOrNull() ?: return@launch
            val capture = Asr4AllCapture(stream)
            asr4allCapture = capture
            var shown = ""
            // Until the clip is handed over: [finishWhisper] takes the recorder
            // away, then [finishAsr4All] or a cancel ends this job.
            while (isActive && generation == voiceGeneration && whisperRecorder === recorder) {
                val count = recorder.sampleCount
                if (count > capture.fed) {
                    stream.feed(recorder.samples(capture.fed, count))
                    capture.fed = count
                    val text = romanizedVoiceText(stream.text())
                    if (text != shown) {
                        shown = text
                        withContext(Dispatchers.Main) {
                            if (generation != voiceGeneration) return@withContext
                            // Once the clip is handed over its words wait in the
                            // field for the finished phrase; nothing rewrites them.
                            if (_uiState.value.voice.status != VoiceStatus.LISTENING) return@withContext
                            if (!interactiveVoice() && !voiceSessionForField) {
                                currentInputConnection?.let { ic ->
                                    ic.setComposingText(spacedVoiceText(casedVoiceText(text)), 1)
                                    asr4allComposed = true
                                }
                            }
                            _uiState.update { it.copy(voice = it.voice.copy(partial = text)) }
                        }
                    }
                    if (stream.endpoint) {
                        withContext(Dispatchers.Main) {
                            if (generation == voiceGeneration && whisperRecorder === recorder) {
                                finishWhisper(userStopped = false)
                            }
                        }
                        break
                    }
                }
                delay(VOICE_PARTIAL_POLL_MS)
            }
        }
    }

    /**
     * The rest of an asr4all clip after the microphone closed: whatever the
     * stream has not had yet, then its finish, which settles punctuation and
     * capitals. Most of the clip is decoded by then, so this is quick.
     */
    private suspend fun finishAsr4All(model: EtModel, pcm: FloatArray, words: List<String>): String {
        asr4allJob?.cancelAndJoin()
        asr4allJob = null
        return withContext(liveDispatcher(model.engine)) {
            val capture = asr4allCapture ?: Asr4AllCapture(newLiveStream(model, words))
            asr4allCapture = null
            if (pcm.size > capture.fed) capture.stream.feed(pcm.copyOfRange(capture.fed, pcm.size))
            capture.stream.finish()
        }
    }

    /**
     * The microphone stopped delivering in the middle of a clip. Whatever was
     * said before it went is still worth typing, so a clip with anything in it
     * is transcribed as if the user had pressed stop; one that died at the start
     * has nothing to offer and says the microphone failed. Called from the
     * recorder's own thread.
     */
    private fun onWhisperCaptureLost(generation: Int) {
        serviceScope.launch(Dispatchers.Main) {
            if (generation != voiceGeneration) return@launch
            val recorder = whisperRecorder ?: return@launch
            if (recorder.sampleCount >= VoiceClipGate.MIN_SAMPLES) {
                finishWhisper(userStopped = true)
                return@launch
            }
            voiceGeneration++
            whisperRecorder = null
            whisperCapture = null
            serverCapture = null
            micBlockWatcher.stop()
            dropCarriedMic()
            serviceScope.launch(Dispatchers.IO) { runCatching { recorder.stop() } }
            _uiState.update {
                it.copy(
                    voice = it.voice.copy(
                        status = VoiceStatus.ERROR, partial = "", level = 0f,
                        errorMessage = getString(R.string.ime_service_voice_mic_error),
                    ),
                )
            }
        }
    }

    /**
     * Whether the microphone of the clip in [recorder] stays open for the
     * next one (#957): the clip ended by itself or by a rail key, and the
     * session goes on after it the way [commitWhisperResult] will decide.
     * A stop, a key on the keyboard or a surface going all end it instead.
     */
    private fun micCarriesOn(recorder: WhisperRecorder, userStopped: Boolean): Boolean =
        recorder.carryOver && recorder.isRecording && !userStopped && !voiceStopRequested &&
            voiceSessionAlive() && (voiceResumeAfterClip || voiceChains())

    /** The clip [recorder] has heard, while its microphone goes on into [carriedMic]. */
    private fun carryMic(recorder: WhisperRecorder): FloatArray {
        dropCarriedMic()
        carriedMic = CarriedMic(recorder, captureSetup)
        return recorder.hold()
    }

    /** Shuts the microphone [carriedMic] kept open, and what it heard with it. */
    private fun dropCarriedMic() {
        val carried = carriedMic ?: return
        carriedMic = null
        serviceScope.launch(Dispatchers.IO) { runCatching { carried.recorder.stop() } }
    }

    /**
     * Stops the Whisper recording and transcribes it off the main thread, then
     * commits exactly like a system final (spoken punctuation, spacing, learn,
     * undo). [userStopped] suppresses the continuous-mode chain. Safe to call
     * from any thread; no-op if no recording is active.
     */
    private fun finishWhisper(userStopped: Boolean) {
        val recorder = whisperRecorder ?: return
        whisperRecorder = null
        micBlockWatcher.stop()
        val capture = whisperCapture
        whisperCapture = null
        val serverLanguage = serverCapture
        serverCapture = null
        // A clip that ended by itself, with the next one to follow, leaves
        // the microphone listening while it is transcribed (#957).
        val held = if ((capture != null || serverLanguage != null) && micCarriesOn(recorder, userStopped)) {
            carryMic(recorder)
        } else {
            null
        }
        if (serverLanguage != null) {
            clipInFlight = true
            finishServerClip(recorder, held, serverLanguage, userStopped)
            return
        }
        val model = capture?.first
        val whisper = (model as? OnDeviceVoice.Whisper)?.model
        val languageId = capture?.second ?: voiceLanguageId()
        val languages = captureLanguages.ifEmpty { listOf(languageId) }
        val gen = voiceGeneration
        val tag = _uiState.value.voice.languageTag
        // Grouped graphs take the language as an input, so hand them the language
        // being typed in rather than letting them guess from a short clip. A
        // dictation that listens for several (#416) is the one case where the
        // guess is wanted: the graph can only be told one.
        val langToken = if (languages.size == 1) whisper?.langTokenFor(languageId) else null
        // Only ask for the translate task where the model was actually trained for
        // it. A graph can carry the signature without it being any good: turbo was
        // exported with one and trained for transcription alone, and running that
        // task returns confident nonsense instead of failing.
        val translate = _uiState.value.settings.whisper.translate && whisper?.supportsTranslate == true
        if (model == null) {
            serviceScope.launch(Dispatchers.IO) { runCatching { recorder.stop() } }
            voiceResumeAfterClip = false
            typeVoiceKeysAfterClip()
            _uiState.update { it.copy(voice = it.voice.copy(status = VoiceStatus.IDLE, level = 0f, clipHeard = false)) }
            settleVoiceToolEnding()
            return
        }
        val cpp = whisper?.ggml == true
        // Read here, on the main thread, where the bias list is kept.
        val keywords = when {
            model is OnDeviceVoice.Whistle || cpp -> recognizerBias().words
            model is OnDeviceVoice.Et -> liveBias(model.model)
            else -> emptyList()
        }
        clipInFlight = true
        _uiState.update {
            it.copy(voice = it.voice.copy(status = VoiceStatus.TRANSCRIBING, partial = "", level = 0f, clipHeard = false))
        }
        // whisper.cpp can say what it has so far: the line under the
        // microphone shows the words as they decode instead of a spinner.
        val partials = if (cpp) watchCppPartials(gen) else null
        serviceScope.launch(Dispatchers.Default) {
            val pcm = held ?: runCatching { recorder.stop() }.getOrDefault(FloatArray(0))
            if (gen != voiceGeneration) return@launch
            // Whisper has no way to say "nothing": a silent window comes back
            // as "Thank you." So a clip with nothing in it is never shown to it.
            val faint = VoiceClipGate.isFaint(pcm)
            val result = if (!VoiceClipGate.hasSpeech(pcm)) {
                Result.success("")
            } else {
                runCatching {
                    when (model) {
                        // Null from whisper.cpp: stopped part way, by a cancel
                        // that already moved the session on, so nothing is typed.
                        is OnDeviceVoice.Whisper -> if (cpp) {
                            transcribeWithCpp(model.model, pcm, languages, keywords, translate).orEmpty()
                        } else {
                            WhisperEngine.transcribe(
                                WhisperStore.modelFile(filesDir, model.model),
                                WhisperStore.vocabFile(filesDir, model.model),
                                pcm,
                                translate,
                                langToken,
                            )
                        }
                        OnDeviceVoice.Whistle -> transcribeWithWhistle(pcm, languages, keywords)
                        is OnDeviceVoice.Et -> punctuateDictation(
                            model.model,
                            if (liveEngine(model.model.engine)) {
                                finishAsr4All(model.model, pcm, keywords)
                            } else {
                                withContext(liveDispatcher(model.model.engine)) { transcribeWithEt(model.model, pcm, keywords) }
                            },
                            languages,
                            tag,
                        )
                    }
                }
            }
            partials?.cancel()
            // A graph told which language to use, or built for exactly one, cannot
            // answer in the wrong script. Only the auto-detecting ones can, and
            // Bangla misread as Hindi is the case worth repairing. Whistle has no
            // language that could be misread as one in another script, and
            // whisper.cpp's repair is made inside [transcribeWithCpp].
            val detected = whisper != null && !cpp && langToken == null && whisper.fixedLang == null
            val punctuated = (model as? OnDeviceVoice.Et)?.model?.let(::voicePunctuates) == true
            withContext(Dispatchers.Main) {
                if (gen != voiceGeneration) return@withContext
                result
                    .map { if (detected) WhisperScript.rescueAmong(it.trim(), languages) else it.trim() }
                    .map { VoiceClipGate.clean(it, faint) }
                    .map { if (punctuated) withListCapitals(it) else it }
                    .onSuccess { commitWhisperResult(it, tag, userStopped) }
                    .onFailure { e ->
                        // The session stops on the error, so nothing hears
                        // the microphone left open for the next clip.
                        dropCarriedMic()
                        // What asr4all typed as it heard stays, as the system
                        // recognizer's partial stays through an error.
                        if (asr4allComposed) {
                            asr4allComposed = false
                            currentInputConnection?.finishComposingText()
                        }
                        // The keys pressed for after the words still go in.
                        typeVoiceKeysAfterClip()
                        // A WhisperException carries a resource id instead of a
                        // message, so its own message is null on purpose.
                        val text = if (e is WhisperException) {
                            getString(e.messageRes, e.messageArg)
                        } else {
                            e.message ?: getString(R.string.ime_service_voice_transcribe_error)
                        }
                        _uiState.update {
                            it.copy(
                                voice = it.voice.copy(
                                    status = VoiceStatus.ERROR, partial = "", level = 0f,
                                    errorMessage = text,
                                ),
                            )
                        }
                    }
            }
        }
    }

    /**
     * Reads what whisper.cpp has decoded so far into [VoiceUi.partial] while
     * the clip of session [gen] transcribes, for the voice surfaces to show.
     * Cancelled once the transcription returns.
     */
    private fun watchCppPartials(gen: Int): Job = serviceScope.launch(Dispatchers.Main) {
        while (isActive && gen == voiceGeneration) {
            delay(VOICE_PARTIAL_POLL_MS)
            val text = romanizedVoiceText(WhisperCpp.partial())
            if (gen != voiceGeneration || text.isEmpty()) continue
            _uiState.update {
                if (it.voice.status != VoiceStatus.TRANSCRIBING || it.voice.partial == text) it
                else it.copy(voice = it.voice.copy(partial = text))
            }
        }
    }

    /**
     * Sends a finished clip to the transcription server (#286) and commits what
     * comes back through [commitWhisperResult], so it is punctuated, spaced,
     * learned and undoable exactly like an offline Whisper phrase. The request
     * runs on IO and is dropped if the session moved on meanwhile; a network
     * failure lands as the panel's error line.
     */
    private fun finishServerClip(recorder: WhisperRecorder, held: FloatArray?, languageId: String, userStopped: Boolean) {
        val gen = voiceGeneration
        val tag = _uiState.value.voice.languageTag
        val server = _uiState.value.settings.whisper
        val languages = captureLanguages.ifEmpty { listOf(languageId) }
        // The server detects the language itself when told nothing, and a code
        // Whisper does not know would get the request refused. The request
        // names one language, so a dictation in several (#416) names none.
        val language = if (server.serverSendLanguage && languages.size == 1) {
            WhisperLanguages.codeForLanguage(languageId)
        } else {
            null
        }
        _uiState.update {
            it.copy(voice = it.voice.copy(status = VoiceStatus.TRANSCRIBING, partial = "", level = 0f, clipHeard = false))
        }
        serviceScope.launch(Dispatchers.IO) {
            val pcm = held ?: runCatching { recorder.stop() }.getOrDefault(FloatArray(0))
            if (gen != voiceGeneration) return@launch
            // A tap-and-release or a silent clip is not speech; uploading it
            // only earns a server's filler text ("Thank you.") for a phrase
            // nobody said.
            val faint = VoiceClipGate.isFaint(pcm)
            val result = if (!VoiceClipGate.hasSpeech(pcm)) {
                Result.success("")
            } else {
                runCatching {
                    // Gathered here rather than cached: this is already off
                    // the main thread, and a word learned a minute ago counts.
                    val personal = if (server.biasPersonalWords) {
                        runCatching { personalVoiceWords(VoiceBias.PROMPT_WORD_LIMIT) }.getOrDefault(emptyList())
                    } else {
                        emptyList()
                    }
                    val words = VoiceBias.select(
                        VoiceBias.parseList(server.biasWords),
                        personal,
                        VoiceBias.PROMPT_WORD_LIMIT,
                    )
                    // The language's own model or server, if it has one (#389).
                    val target = server.serverFor(languageId)
                    TranscriptionClient.transcribe(
                        target.url,
                        target.key,
                        target.model,
                        language,
                        pcm,
                        prompt = VoiceBias.serverPrompt(words, server.serverPrompt),
                        path = target.path,
                    )
                }
            }
            // The server could not be reached, and the user asked for the
            // device to stand in (#452): the clip is already recorded, so a
            // downloaded Whisper model transcribes it here rather than the
            // phrase being lost to an error line.
            val failure = result.exceptionOrNull()
            val local = if (failure != null && ToolHttp.isUnreachable(failure) &&
                _uiState.value.settings.dataSaver.offlineFallback
            ) {
                fallbackOnDeviceVoice()
            } else {
                null
            }
            val heard = if (local != null) runCatching { transcribeOnDevice(local, pcm, languages, tag) } else result
            val punctuated = (local as? OnDeviceVoice.Et)?.model?.let(::voicePunctuates) == true
            withContext(Dispatchers.Main) {
                if (gen != voiceGeneration) return@withContext
                // Told on the move, and forgotten once the server answers again.
                if (local != null || heard.isSuccess) noteOfflineFallback(OFFLINE_FALLBACK_VOICE, local != null)
                heard
                    .map { VoiceClipGate.clean(it, faint) }
                    .map { if (punctuated) withListCapitals(it) else it }
                    .onSuccess { commitWhisperResult(it, tag, userStopped) }
                    .onFailure { e ->
                        dropCarriedMic()
                        typeVoiceKeysAfterClip()
                        _uiState.update {
                            it.copy(
                                voice = it.voice.copy(
                                    status = VoiceStatus.ERROR, partial = "", level = 0f,
                                    errorMessage = ToolHttp.friendlyMessage(this@WMKeyboardService, e),
                                ),
                            )
                        }
                    }
            }
        }
    }

    /** Commits a finished Whisper transcription and continues or ends the session. */
    private fun commitWhisperResult(text: String, tag: String, userStopped: Boolean) {
        val resume = voiceResumeAfterClip
        voiceResumeAfterClip = false
        val chain = (resume || (!userStopped && voiceChains())) &&
            !voiceStopRequested && voiceSessionAlive()
        if (text.isBlank()) {
            // The finished phrase is the last word: asr4all's live words for a
            // clip that turned out to hold nothing go, as a recognizer's empty
            // final takes its partial with it.
            if (asr4allComposed) {
                asr4allComposed = false
                currentInputConnection?.commitText("", 1)
            }
            typeVoiceKeysAfterClip()
            // Nothing heard. In continuous mode keep listening — but not
            // forever, so an abandoned open mic winds down the way it does
            // for the system recognizer; otherwise idle. A clip a key ended
            // was the user's doing, not a silence, and is not counted.
            if (chain && (resume || voiceSilentRetries < voiceSilentRetryLimit())) {
                if (!resume) voiceSilentRetries++
                _uiState.update { it.copy(voice = it.voice.copy(partial = "", level = 0f)) }
                serviceScope.launch(Dispatchers.Main) { startVoice() }
            } else {
                dropCarriedMic()
                _uiState.update { it.copy(voice = it.voice.copy(status = VoiceStatus.IDLE, partial = "", level = 0f)) }
                settleVoiceToolEnding()
            }
            return
        }
        voiceSilentRetries = 0
        val landed = commitVoiceUtterance(text, tag)
        tidyVoiceThen(landed) {
            typeVoiceKeysAfterClip()
            afterWhisperCommit(chain)
        }
    }

    /**
     * The clip's words are in, or there were none: the rail keys pressed
     * while it was being transcribed go in after them, in the order they were
     * pressed (#921), the way a streamed phrase split by a key reads.
     */
    private fun typeVoiceKeysAfterClip() {
        clipInFlight = false
        if (voiceKeysAfterClip.isEmpty()) return
        voiceRailKeyInFlight = true
        try {
            while (voiceKeysAfterClip.isNotEmpty()) onKey(voiceKeysAfterClip.removeFirst())
        } finally {
            voiceRailKeyInFlight = false
        }
    }

    /**
     * The clip's words are in the field, tidied or not: continue the session or
     * end it. A stop pressed while they were being tidied is still a stop.
     */
    private fun afterWhisperCommit(chain: Boolean) {
        if (chain && !voiceStopRequested && voiceSessionAlive()) {
            _uiState.update { it.copy(voice = it.voice.copy(partial = "", level = 0f, canUndo = true)) }
            serviceScope.launch(Dispatchers.Main) { startVoice() }
        } else {
            dropCarriedMic()
            _uiState.update {
                it.copy(
                    voice = it.voice.copy(status = VoiceStatus.IDLE, partial = "", level = 0f, canUndo = !voiceSessionForField),
                )
            }
            settleVoiceToolEnding()
        }
    }

    /**
     * Voice typing shares the field with the keys: the microphone stays open
     * while the user types, so nothing is composed and each phrase lands as
     * finished text ([VoiceBarSettings.TYPING_INTERACTIVE] and
     * [VoiceBarSettings.TYPING_PLAIN]).
     */
    private fun interactiveVoice(): Boolean =
        _uiState.value.settings.voiceBar.interactiveTyping()

    /** Dictated text goes in exactly as it was heard ([VoiceBarSettings.TYPING_PLAIN]). */
    private fun plainVoice(): Boolean = _uiState.value.settings.voiceBar.plainTyping()

    /**
     * Whether the next utterance follows this one without another press of the
     * microphone. Interactive voice typing always chains: a session that ended
     * at the first pause would leave the user typing into a closed microphone,
     * which is the one thing the mode exists to avoid.
     *
     * A dictation into one of the keyboard's own fields never chains (#353):
     * a search is one phrase, and a microphone left open under a panel would
     * go on typing into it while the user reads the results.
     */
    private fun voiceChains(): Boolean =
        !voiceSessionForField && (_uiState.value.settings.voiceContinuous || interactiveVoice())

    /** See [VOICE_SILENT_RETRIES]. */
    private fun voiceSilentRetryLimit(): Int =
        if (interactiveVoice()) VOICE_SILENT_RETRIES_INTERACTIVE else VOICE_SILENT_RETRIES

    /**
     * Puts one finished utterance into the field, however it was recognised.
     *
     * Interactive voice typing reads the spacing and the capital here instead
     * of at the start of the session: the cursor has been moving under the
     * open microphone the whole time, so where the words go is only known now.
     * Plain voice typing takes neither the spoken-punctuation pass nor the
     * spacing, because there the point is the words exactly as they were said.
     *
     * The capital is not one of those rules. Plain voice typing asks the
     * recognizer for no formatting, so a recognizer that honours it hands over
     * nothing to lower; the capital only ever appears when one puts it on
     * regardless — the system recognizer's default, and Whisper, which has no
     * such switch at all and transcribes in sentence case. Taking it off
     * unconditionally lowered the first word of a dictation into an empty
     * field, which is not a rule anyone asked for either. So the capital is
     * judged by the same place rule as every other mode.
     *
     * Returns what went into the app's field, for [tidyVoiceThen] to rewrite,
     * or null when nothing did.
     */
    private fun commitVoiceUtterance(text: String, tag: String): VoiceLanding? {
        val settings = _uiState.value.settings
        val plain = settings.voiceBar.plainTyping()
        // Spoken punctuation is read in the language heard, before its words
        // go into Latin letters (#948).
        val heard = if (!plain && settings.voiceSpokenPunctuation) VoicePunctuation.apply(text, tag) else text
        val processed = romanizedVoiceText(heard)
        if (voiceSessionForField) {
            commitFieldVoice(processed)
            return null
        }
        val ic = currentInputConnection ?: return null
        // asr4all's live words are the composing region the commit below
        // replaces, as the recognizer's partial is.
        asr4allComposed = false
        // A word still being composed — typed under the microphone, or resumed
        // by a caret tap while a transcription was in flight — has to commit
        // first, or the dictated text replaces it.
        commitComposing(ic, autocorrect = false)
        if (settings.voiceBar.interactiveTyping()) refreshVoiceContext()
        val sentenceStart = voiceSentenceStart
        val cased = casedVoiceText(processed, raise = !plain)
        val spaced = if (plain) cased else spacedAfterVoiceMark(ic, spacedVoiceText(cased))
        ic.commitText(spaced, 1)
        // The phrase may have ended a sentence: a letter typed next on the keys
        // takes the capital a typed full stop would have given it.
        if (!plain) refreshShiftForContext()
        learn(cased)
        lastVoiceCommit = spaced
        // Counted beside the typing, never in it (#761).
        val listened = voiceListenStartedAt.takeIf { it > 0L }?.let { SystemClock.uptimeMillis() - it } ?: 0L
        voiceListenStartedAt = 0L
        recordStat { onVoicePhrase(TypingStatsMath.spokenWords(cased), listened, System.currentTimeMillis()) }
        // A chained session's next utterance lands after this one, so what it
        // needs in front of it — a space, a capital — is read now that the
        // field holds it, not from wherever the session began (#182).
        refreshVoiceContext()
        return VoiceLanding(spaced, sentenceStart, heard.takeIf { processed != it })
    }

    /**
     * One phrase as it went into the field: [text] exactly as committed,
     * spaces included, and whether the caret stood at a sentence start when
     * it did, so a rewrite of it is cased by the same rule ([VoiceCasing]).
     * [heard] is the phrase in the script it was heard in when [text] is its
     * romanized spelling still to be checked by [respellVoiceThen], else null.
     */
    private class VoiceLanding(val text: String, val sentenceStart: Boolean, val heard: String? = null)

    /**
     * Runs [then] once the phrase that just [landed] has been tidied by the AI
     * tool's model (#499), or at once when it is not to be.
     *
     * The raw words go into the field first and stay there while the model
     * works, and the answer only replaces them if they are still exactly what
     * is in front of the caret. So nothing that was said can be lost to a slow,
     * failed or wrong answer, or to the user typing, moving the caret or
     * leaving the field in the meantime: the phrase just stays as heard.
     *
     * [then] chains the next phrase or ends the session, and is held back
     * until the answer is in. A new phrase starting under the request would
     * put its own partial in front of the caret, and the rewrite could no
     * longer find the old one. A session cancelled meanwhile never runs it:
     * [cancelVoice] has already brought the surfaces to rest.
     */
    private fun tidyVoiceThen(landed: VoiceLanding?, then: () -> Unit) {
        // A romanized phrase gets its spellings first, so the tidy reads the
        // words as they will stay.
        if (landed?.heard != null) {
            respellVoiceThen(landed) { tidyVoiceThen(it, then) }
            return
        }
        val settings = _uiState.value.settings
        if (landed == null || !voiceTidyApplies(settings, landed.text)) {
            then()
            return
        }
        val generation = voiceGeneration
        _uiState.update {
            it.copy(voice = it.voice.copy(status = VoiceStatus.TRANSCRIBING, tidying = true, partial = "", level = 0f))
        }
        serviceScope.launch {
            val tidied = withContext(Dispatchers.IO) {
                runCatching { tidyDictation(landed.text, settings, generation) }.getOrNull()
            }
            if (generation != voiceGeneration) return@launch
            // FINISHING, the state a phrase is in between being heard and the
            // next one starting, so nothing still reads "Tidying up" or
            // "Transcribing" in the moment before [then] moves it on.
            _uiState.update { it.copy(voice = it.voice.copy(status = VoiceStatus.FINISHING, tidying = false)) }
            if (tidied != null) replaceVoiceLanding(landed, tidied)
            then()
        }
    }

    /**
     * Romanized dictation's second pass (#948). The words of [landed] the
     * spelling maps did not know went in as the rules spell them; this asks
     * IndicXlit's Latin model ([IndicXlitModels.LATIN]) how people write them,
     * puts the phrase in again with its answers, and runs [then] with the
     * phrase as the field now has it.
     *
     * At the commit only, never on a partial: a partial is written again with
     * every word heard, and the model's few milliseconds a word would land on
     * each of them. The rules' phrase stays when the model is not downloaded,
     * has not answered within [VOICE_RESPELL_BUDGET_MS], or the phrase is no
     * longer what sits in front of the caret ([replaceVoiceLanding]). [then]
     * is held back meanwhile, for the reason [tidyVoiceThen] holds its own.
     */
    private fun respellVoiceThen(landed: VoiceLanding, then: (VoiceLanding) -> Unit) {
        val asCommitted = VoiceLanding(landed.text, landed.sentenceStart)
        val heard = landed.heard
        val ids = voiceRomanizedIds()
        if (heard == null || !latinXlitApplies(ids)) {
            then(asCommitted)
            return
        }
        val generation = voiceGeneration
        serviceScope.launch {
            val respelled = withContext(Dispatchers.Default) {
                val unmapped = romanizedDictation.unmapped(heard, ids).filterKeys(IndicXlitModels.LATIN::supports)
                if (unmapped.isEmpty()) return@withContext null
                val deadline = SystemClock.uptimeMillis() + VOICE_RESPELL_BUDGET_MS
                val readings = unmapped.mapValues { (languageId, words) ->
                    latinXlit.readingsOf(languageId, words, deadline - SystemClock.uptimeMillis())
                }
                romanizedDictation.romanize(heard, ids, readings)
                    .takeIf { it != romanizedDictation.romanize(heard, ids) }
            }
            if (generation != voiceGeneration) return@launch
            val replaced = respelled?.let { replaceVoiceLanding(landed, it) }
            then(replaced?.let { VoiceLanding(it, landed.sentenceStart) } ?: asCommitted)
        }
    }

    /**
     * Whether any of the romanized languages [ids] has the Latin model to
     * spell its unknown words, and the model and its runtime are here.
     */
    private fun latinXlitApplies(ids: List<String>): Boolean =
        ids.any { id -> RomanizedSpeech.spokenAs(id)?.let(IndicXlitModels.LATIN::supports) == true } &&
            IndicXlitLatinDownloads.ready(applicationContext)

    /**
     * Whether the phrase [text] goes to the model at all. Not in plain voice
     * typing, which is the words exactly as said; not into the keyboard's own
     * boxes, which hold a search or a short phrase; never from a password
     * field; and only when the AI tool can answer without asking anything,
     * which rules out a provider that is not set up and data saver holding
     * cloud AI back. Silently: the phrase is in the field already, and a
     * notice on every phrase of a long dictation would be worse than the
     * filler it failed to take out.
     */
    private fun voiceTidyApplies(settings: KeyboardSettings, text: String): Boolean {
        if (!settings.voiceBar.aiTidy || settings.voiceBar.plainTyping()) return false
        if (voiceSessionForField || _uiState.value.secureField) return false
        if (!VoiceTidy.worthTidying(text)) return false
        if (voiceTidyOnDevice(settings)) {
            return BuildConfig.ENABLE_LOCAL_LLM && effectiveLocalModelFile(settings) != null
        }
        return AiClient.isConfigured(settings.ai) &&
            dataSaverStatus.decide(MeteredFeature.CLOUD_AI) == MeteredDecision.ALLOWED
    }

    /**
     * The tidy runs on the downloaded model: it is the AI tool's provider, or
     * it stands in for a server there is no connection to reach (#452).
     */
    private fun voiceTidyOnDevice(settings: KeyboardSettings): Boolean =
        settings.ai.provider == AiProvider.ON_DEVICE ||
            (aiOfflineStandIn(settings) && !networkWatcher.state.value.online)

    /**
     * The model's tidied [landed] phrase, or null when there is no answer to
     * use: none in [VOICE_TIDY_TIMEOUT_MS], the session moved on, or
     * [VoiceTidy.accept] turned it down. Blocking; call off the main thread.
     */
    private fun tidyDictation(landed: String, settings: KeyboardSettings, generation: Int): String? {
        val heard = landed.trim()
        // A romanized dictation is tidied in Latin letters (#948).
        val romanized = voiceRomanizedIds().firstOrNull()
            ?.let(RomanizedSpeech::spokenAs)
            ?.let { LanguageRegistry.byId(it).englishName }
        val system = AiPrompts.dictationPrompt(romanized)
        val deadline = SystemClock.uptimeMillis() + VOICE_TIDY_TIMEOUT_MS
        val alive = { generation == voiceGeneration && SystemClock.uptimeMillis() < deadline }
        val answer = if (voiceTidyOnDevice(settings)) {
            val modelFile = effectiveLocalModelFile(settings) ?: return null
            LocalLlmEngine.generate(
                context = applicationContext,
                modelFile = modelFile,
                backend = settings.ai.localBackend,
                contextTokens = settings.ai.localContextTokens,
                system = system,
                user = heard,
            )
        } else {
            AiClient.completeStreaming(
                config = AiClient.config(settings.ai),
                system = system,
                user = heard,
                maxTokens = AiClient.effectiveMaxTokens(settings.ai),
                onPhase = {},
                onPartial = {},
                isActive = alive,
            ).text
        }
        // A request stopped by [alive] hands back what it had so far, which
        // is a phrase cut short, not a tidied one.
        if (!alive()) return null
        return VoiceTidy.accept(AiThinking.stripped(answer), heard)
    }

    /**
     * Puts [tidied] where [landed] went in, if [landed] is still exactly what
     * sits in front of the caret with nothing selected. The undo chip then
     * takes back the tidied phrase, which is what is in the field. Returns
     * what went in, spaces included, or null when nothing did.
     */
    private fun replaceVoiceLanding(landed: VoiceLanding, tidied: String): String? {
        val ic = currentInputConnection ?: return null
        val old = landed.text
        if (ic.getTextBeforeCursor(old.length, 0)?.toString() != old) return null
        if (!ic.getSelectedText(0).isNullOrEmpty()) return null
        val replacement = VoiceTidy.land(old, VoiceCasing.apply(tidied, sentenceStart = landed.sentenceStart))
        ic.beginBatchEdit()
        ic.deleteSurroundingText(old.length, 0)
        ic.commitText(replacement, 1)
        ic.endBatchEdit()
        if (lastVoiceCommit == old) lastVoiceCommit = replacement
        refreshVoiceContext()
        return replacement
    }

    /** Intelligent leading and trailing spaces when dictation starts mid-text or replaces selection. */
    private fun spacedVoiceText(text: String): String =
        VoiceSpacing.format(text, voiceNeedsLeadingSpace, voiceNeedsTrailingSpace)

    /**
     * The recognizer's automatic capital kept only where the text in front of
     * the caret opens a sentence — in every voice typing mode, plain included
     * (see [commitVoiceUtterance]). [raise] also puts one on where the
     * recognizer left it off, which plain voice typing does not ask for.
     */
    private fun casedVoiceText(text: String, raise: Boolean): String =
        VoiceCasing.apply(text, sentenceStart = voiceSentenceStart, raise = raise)

    /**
     * [text] with the space [AutoTextSettings.spaceAfterPunctuation] types
     * after a mark, when the phrase ends on one. Without it a dictated "Done."
     * left the caret against the full stop, and the next word typed on the
     * keys went in as "Done.Then". Only where the setting would space a typed
     * mark: a prose field, and not in front of a space already there.
     */
    private fun spacedAfterVoiceMark(ic: InputConnection, text: String): String {
        val state = _uiState.value
        if (!state.settings.autoText.spaceAfterPunctuation || !state.allowsTypingIntelligence) return text
        if (text.lastOrNull()?.let { it in AUTO_SPACE_PUNCTUATION } != true) return text
        val after = ic.getTextAfterCursor(1, 0)?.firstOrNull()
        return if (after != null && after.isWhitespace()) text else "$text "
    }

    /**
     * Reads the characters around the cursor to decide whether dictated text
     * needs a space in front of it or behind it, and whether it opens a
     * sentence. Run at the start of a session, after every utterance lands,
     * and again after an edit made from the panel's own rail — a space typed
     * there must not turn into two once the transcription lands, and a full
     * stop typed there means the next phrase does start a sentence.
     *
     * The capital is a question about the text, not about the shift key:
     * [VoiceCasing.startsSentence] reads what is written in front of the
     * caret. Asking [shouldAutoCapitalize] instead answered no in every field
     * that never requests sentence capitals — a plain `inputType="text"`, a
     * terminal's null field — and whenever Automatic capitals is off, which
     * took the capital off the first word of a dictation into an empty field.
     * It also spends a [InputConnection.getCursorCapsMode] round-trip into the
     * focused app that this no longer needs.
     */
    private fun refreshVoiceContext() {
        val ic = currentInputConnection ?: return
        val before = ic.getTextBeforeCursor(VoiceCasing.CONTEXT_CHARS, 0)
        val beforeChar = before?.lastOrNull()
        val afterChar = ic.getTextAfterCursor(1, 0)?.firstOrNull()
        voiceNeedsLeadingSpace = VoiceSpacing.needsLeadingSpace(beforeChar, afterChar)
        voiceNeedsTrailingSpace = VoiceSpacing.needsTrailingSpace(beforeChar, afterChar)
        voiceSentenceStart = VoiceCasing.startsSentence(before)
    }

    /**
     * Space, backspace or enter pressed on the voice panel's action rail. Those
     * keys belong to the dictation surface, not to the keyboard: the keys are not
     * even on screen, so reaching for space there means "put a space in", never
     * "I have finished talking". They leave the session running.
     *
     * The exception is a partial already sitting in the editor as composing text.
     * The system recognizer's and asr4all's partials are cumulative and each one
     * rewrites the whole composing region, so a character typed inside it is
     * either duplicated or swallowed; that case lands what was heard so far,
     * types the key after it and listens again ([splitVoicePhrase]). Whisper has
     * no partial — its audio is in the recorder, not the editor — so a rail key
     * never costs a recording.
     */
    fun onVoiceRailKey(action: VoiceBarAction) {
        when (action) {
            is VoiceBarAction.RailKey -> onVoiceSurfaceKey(action.key)
            is VoiceBarAction.SetVertical -> {
                vibrate()
                // The old orientation's rectangle must not shape the new
                // one's insets — one clean whole-window pass until the
                // reshaped pill publishes, instead of two app reflows.
                voiceBarBounds = null
                window?.window?.decorView?.requestLayout()
                serviceScope.launch { settingsRepository.setVoiceBarVertical(action.vertical) }
            }
            is VoiceBarAction.SetRest ->
                serviceScope.launch {
                    settingsRepository.setVoiceBarRest(
                        action.snap, action.rightEdge, action.yBias, action.dockBias,
                    )
                }
            is VoiceBarAction.SwitchSurface -> switchVoiceSurface(action.mode)
            VoiceBarAction.CloseStrip -> closeVoiceStrip()
            is VoiceBarAction.Bounds -> onVoiceBarBounds(action)
            is VoiceBarAction.PickLanguages -> onVoiceLanguagePick(action.ids)
            VoiceBarAction.CycleMic -> cycleVoiceMic()
            is VoiceBarAction.PickEngine -> onVoiceEnginePick(action.languageId, action.choice)
        }
    }

    /**
     * The microphone this session listens through (#581): the stored pick
     * while one of its kind is plugged in, else automatic. A headset that
     * dropped out does not leave dictation pointed at nothing.
     */
    private fun voiceMicKind(): String {
        // The switch turned off leaves the microphone to Android.
        if (!_uiState.value.settings.voiceBar.micSwitch) return VoiceMics.AUTO
        val picked = _uiState.value.settings.voiceBar.mic
        return if (picked != VoiceMics.AUTO && picked in VoiceMics.available(this)) picked else VoiceMics.AUTO
    }

    /**
     * The voice panel's microphone chip (#581): the next of the microphones
     * plugged in, stored as the pick so it holds for every session after this
     * one. Mirrored into the state ahead of the write, as the typing mode is,
     * so a session restarted for it already uses it. A microphone that is
     * listening restarts on the new one; a phrase being transcribed was
     * already heard and finishes as it is.
     */
    private fun cycleVoiceMic() {
        val state = _uiState.value
        val next = VoiceMics.next(state.settings.voiceBar.mic, VoiceMics.choices(state.voice.mics, voiceOwnCapture()))
        _uiState.update {
            it.copy(settings = it.settings.copy(voiceBar = it.settings.voiceBar.copy(mic = next)))
        }
        serviceScope.launch { settingsRepository.setVoiceMic(next) }
        forceMicNotice = true
        if (state.voice.status == VoiceStatus.LISTENING) {
            voiceSilentRetries = 0
            startVoice()
        } else {
            // Nothing is recording, so say what the next session will use.
            noteVoiceMic(VoiceMics.deviceFor(this, voiceMicKind()) ?: VoiceMics.autoDevice(this))
        }
    }

    /**
     * Publishes the microphone a session listens through, and asks the
     * surfaces to say so ("Using Bluetooth mic (X7)") when it is news: a
     * different microphone, a press of the chip, or the first session since
     * the keyboard came up. Continuous dictation restarts for every phrase,
     * and saying the same thing each time would be noise.
     */
    private fun noteVoiceMic(device: AudioDeviceInfo?) {
        val kind = device?.let(VoiceMics::kindOf).orEmpty()
        val name = device?.productName?.toString().orEmpty()
        val key = "$kind|$name"
        val show = _uiState.value.settings.voiceBar.micSwitch && (forceMicNotice || key != lastMicNotice)
        forceMicNotice = false
        lastMicNotice = key
        _uiState.update {
            it.copy(
                voice = it.voice.copy(
                    micKind = kind,
                    micName = name,
                    micNoticeAt = if (show) SystemClock.uptimeMillis() else it.voice.micNoticeAt,
                ),
            )
        }
    }

    /**
     * Dictation records with the keyboard's own microphone capture (Whisper
     * or the server), which can be pointed at any microphone. The system
     * recognizer records in its own process and can only be moved to a
     * Bluetooth headset.
     */
    private fun voiceOwnCapture(): Boolean =
        _uiState.value.voice.clipBased || voiceEngine() != "system"

    /**
     * A pick off the voice panel's engine chip: [languageId] dictates with
     * [choice] from now on, the same per-language choice the settings screen
     * edits. Mirrored into the state ahead of the write, as the microphone
     * pick is, so the session restarted for it already uses it.
     */
    private fun onVoiceEnginePick(languageId: String, choice: String) {
        vibrate()
        _uiState.update {
            val whisper = it.settings.whisper
            val byLang = if (choice.isBlank()) {
                whisper.voiceByLang - languageId
            } else {
                whisper.voiceByLang + (languageId to choice)
            }
            it.copy(settings = it.settings.copy(whisper = whisper.copy(voiceByLang = byLang)))
        }
        serviceScope.launch { settingsRepository.setVoiceForLanguage(languageId, choice) }
        if (voiceActive()) {
            voiceSilentRetries = 0
            startVoice()
        } else {
            refreshVoiceEngineChoices()
        }
    }

    /** The phrase in hand, as the voice surfaces' own tools see it (#758, #921). */
    private fun voicePhraseState(): VoicePhraseState {
        val voice = _uiState.value.voice
        return VoicePhraseState(
            status = voice.status,
            livePartial = voice.partial.isNotEmpty(),
            clipHeard = whisperRecorder?.heardSpeech == true,
            clipInFlight = clipInFlight,
            liveWordsComposed = asr4allComposed,
            sharesField = interactiveVoice() || voiceSessionForField,
        )
    }

    private fun onVoiceSurfaceKey(key: Key) {
        when (voicePhraseState().keyRoute()) {
            // asr4all's words wait in the field while the clip's last moment
            // decodes, and the key would land inside them. They stay as heard,
            // the finish is dropped, and the key goes after them.
            VoiceKeyRoute.SETTLE_LIVE -> cancelVoice()
            VoiceKeyRoute.SPLIT_LIVE -> {
                splitVoicePhrase(key)
                return
            }
            VoiceKeyRoute.SPLIT_CLIP -> {
                splitVoiceClip(key)
                return
            }
            VoiceKeyRoute.AFTER_CLIP -> {
                voiceKeysAfterClip.addLast(key)
                return
            }
            VoiceKeyRoute.KEYBOARD -> {
                onKey(key)
                return
            }
            VoiceKeyRoute.TYPE -> Unit
        }
        voiceRailKeyInFlight = true
        try {
            onKey(key)
        } finally {
            voiceRailKeyInFlight = false
        }
        if (voiceActive()) refreshVoiceContext()
    }

    /**
     * A rail key pressed while a phrase is still being heard in block voice
     * typing (#758): a comma, a full stop, a backspace said by hand in the
     * middle of dictating. The partial in the field is cumulative, so the key
     * cannot go into it, and ending the dictation for it would make every
     * correction cost a tap on the mic. Instead the phrase lands as heard so
     * far, through the same path as a finished one, the key goes after it,
     * and listening starts again for what comes next.
     */
    private fun splitVoicePhrase(key: Key) {
        val voice = _uiState.value.voice
        // Replaces the partial, which is the composing region, before the
        // cancel below would settle that as it stands.
        commitVoiceUtterance(voice.partial, voice.languageTag)
        cancelVoice()
        voiceRailKeyInFlight = true
        try {
            onKey(key)
        } finally {
            voiceRailKeyInFlight = false
        }
        if (voiceSessionAlive()) {
            voiceSilentRetries = 0
            startVoice()
        }
    }

    /**
     * [splitVoicePhrase] for an engine that records a clip (#921): Whisper, a
     * transcription server, Parakeet and the rest have no words until the
     * clip is transcribed, so the clip ends where the key was pressed, the key
     * waits for its words, and listening starts again once both are in. The
     * microphone stays open while the clip transcribes (#957), so what is
     * said in that moment opens the next clip.
     */
    private fun splitVoiceClip(key: Key) {
        voiceKeysAfterClip.addLast(key)
        voiceResumeAfterClip = true
        finishWhisper(userStopped = false)
    }

    /** A dictation session is mid-flight: recording, finishing, or transcribing. */
    /** Whether [holdMediaFocus] has the audio focus now. */
    private var mediaFocusHeld = false

    /** Nothing to do when focus moves on: dictation ends by its own rules. */
    private val mediaFocusListener = AudioManager.OnAudioFocusChangeListener { }

    /**
     * Takes the audio focus for a dictation, or gives it back. A transient
     * request is the one players answer by pausing and resume from on their
     * own when it is returned.
     */
    @Suppress("DEPRECATION")
    private fun holdMediaFocus(hold: Boolean) {
        if (hold == mediaFocusHeld) return
        val audio = getSystemService(Context.AUDIO_SERVICE) as? AudioManager ?: return
        if (hold) {
            val granted = audio.requestAudioFocus(
                mediaFocusListener,
                AudioManager.STREAM_MUSIC,
                AudioManager.AUDIOFOCUS_GAIN_TRANSIENT,
            )
            mediaFocusHeld = granted == AudioManager.AUDIOFOCUS_REQUEST_GRANTED
        } else {
            audio.abandonAudioFocus(mediaFocusListener)
            mediaFocusHeld = false
        }
    }

    private fun voiceActive(): Boolean = when (_uiState.value.voice.status) {
        VoiceStatus.LISTENING, VoiceStatus.FINISHING, VoiceStatus.TRANSCRIBING -> true
        else -> false
    }

    /**
     * Android is feeding the session silence: the Microphone access or Sensors
     * off tile in Quick Settings is on (#193). Ends the session without
     * transcribing, since there is nothing to hear, and says why. Nothing
     * chains from MIC_BLOCKED; a mic tap is what tries again.
     */
    private fun onMicBlocked(generation: Int) {
        if (generation != voiceGeneration) return
        voiceGeneration++
        whisperCapture = null
        serverCapture = null
        whisperRecorder?.let { rec ->
            whisperRecorder = null
            serviceScope.launch(Dispatchers.IO) { runCatching { rec.stop() } }
        }
        dropCarriedMic()
        voiceEngine.cancel()
        asr4allComposed = false
        if (!interactiveVoice() && !voiceSessionForField) currentInputConnection?.finishComposingText()
        _uiState.update {
            it.copy(
                voice = it.voice.copy(
                    status = VoiceStatus.MIC_BLOCKED, partial = "", level = 0f, errorMessage = null,
                ),
            )
        }
    }

    /**
     * Abandons any running dictation: the mic is released and the partial
     * already on screen stays as committed text (the user said it — losing
     * it on a panel switch would be worse than keeping it).
     */
    private fun cancelVoice() {
        val status = _uiState.value.voice.status
        // Bumping first invalidates any in-flight Whisper transcription.
        voiceGeneration++
        // An abandoned session has no landing for the tool's stop to wait on.
        voiceToolEnding = false
        // Nor do keys that were waiting to go in after a clip's words: the
        // words are not coming, and a mark on its own is not what was asked.
        clipInFlight = false
        voiceKeysAfterClip.clear()
        voiceResumeAfterClip = false
        micBlockWatcher.stop()
        whisperRecorder?.let { rec ->
            whisperRecorder = null
            serviceScope.launch(Dispatchers.IO) { runCatching { rec.stop() } }
        }
        if (!adoptingMic) dropCarriedMic()
        // whisper.cpp stops at its next step instead of finishing a
        // transcription nobody will see, which on a long clip is most of the
        // battery it would cost.
        if (status == VoiceStatus.TRANSCRIBING) WhisperCpp.abort()
        asr4allJob?.cancel()
        asr4allJob = null
        // Sherpa's and Omnilingual's streams hold native memory; asr4all's is the heap's.
        dropLiveCapture(asr4allCapture)
        asr4allCapture = null
        // Its live words are settled below with the recognizer's partial.
        asr4allComposed = false
        if (status != VoiceStatus.LISTENING && status != VoiceStatus.FINISHING &&
            status != VoiceStatus.TRANSCRIBING
        ) {
            return
        }
        voiceEngine.cancel()
        // The composing region is the dictated partial in block voice typing,
        // so ending the session settles it. In interactive voice typing it is
        // whatever word the user is typing this second, and finishing it here
        // would strand the keyboard's own buffer against a field that is no
        // longer composing.
        if (!interactiveVoice() && !voiceSessionForField) currentInputConnection?.finishComposingText()
        _uiState.update {
            it.copy(
                voice = it.voice.copy(
                    status = VoiceStatus.IDLE, partial = "", level = 0f, tidying = false, clipHeard = false,
                ),
            )
        }
    }

    // ---- dictation into the keyboard's own fields (#353) ----

    /**
     * The last session [startVoice] began was for a keyboard-owned field. What
     * [endFieldVoice] asks before it cancels anything, since by then the field
     * has usually gone and [fieldVoice] can no longer say.
     */
    private var voiceSessionForField = false

    /**
     * The dictation, running or resting, belongs to a keyboard-owned field
     * rather than the app's. Asked of the field that has the keys *now*, not
     * only of [VoiceUi.field], so a mark left behind for a moment by a field
     * that has just closed can never send an app-field session's words to a
     * box that is no longer there ([startFieldVoiceWatcher] clears it).
     */
    private fun fieldVoice(): Boolean {
        val state = _uiState.value
        val field = state.voice.field ?: return false
        return field == state.captureKey()
    }

    /**
     * The microphone on a keyboard-owned field's strip (#353), and the Voice
     * tool pressed while one of those fields has the keys.
     *
     * Every other voice surface types into the app: the panel would take the
     * place of the panel this field is on, and the strip and the bar write
     * through the input connection. So this is a session of its own, marked by
     * [VoiceUi.field]. It runs the same engine with the same language, puts
     * nothing in the app while it listens, ends at the first pause, and lands
     * the phrase at the field's caret ([commitFieldVoice]).
     */
    fun onCaptureVoice(action: CaptureVoiceAction) {
        when (action) {
            CaptureVoiceAction.TOGGLE -> {
                val state = _uiState.value
                val key = state.captureKey() ?: return
                if (state.captureTarget()?.takesDictation != true || !state.settings.voiceBar.enabled) return
                if (state.voice.field != key) {
                    // One microphone, one destination: whatever was listening
                    // for the app's field stops first.
                    cancelVoice()
                    _uiState.update { it.copy(voice = it.voice.copy(field = key, canUndo = false)) }
                }
                onVoiceToggle()
            }
            CaptureVoiceAction.CLOSE -> {
                vibrate()
                endFieldVoice()
            }
            CaptureVoiceAction.PERMISSION -> onVoicePermissionRequest()
            CaptureVoiceAction.SETTINGS -> onOpenVoiceSettings()
        }
    }

    /**
     * The field's dictation put away: the microphone released, a phrase still
     * being transcribed dropped, and the strip given its words back.
     */
    private fun endFieldVoice() {
        if (_uiState.value.voice.field == null) return
        if (!voiceSessionForField) {
            // The session running now was started for the app's field: only
            // the mark goes, and that session carries on untouched.
            _uiState.update { it.copy(voice = it.voice.copy(field = null)) }
            return
        }
        cancelVoice()
        voiceSessionForField = false
        _uiState.update {
            it.copy(
                voice = it.voice.copy(
                    field = null, status = VoiceStatus.IDLE, partial = "", level = 0f, errorMessage = null,
                    whisperNeedsModel = false, serverNeedsSetup = false, canUndo = false,
                ),
            )
        }
    }

    /**
     * A field's dictation ends with the field (#353): the panel closing, the
     * chat composer handing the keys back, another box taking them. Whatever
     * was still to come of the phrase would otherwise land in the wrong place.
     */
    private fun startFieldVoiceWatcher() {
        serviceScope.launch {
            _uiState
                .map { it.voice.field to it.captureKey() }
                .distinctUntilChanged()
                .collect { (field, key) -> if (field != null && field != key) endFieldVoice() }
        }
    }

    /**
     * One finished phrase put in at the field's caret (#353), in place of the
     * selection if there is one, through the same path a paste takes, so each
     * field filters it as it filters keys.
     *
     * Spaced and capitalised by the rules a dictation into the app's field
     * follows, read off the field's own text either side of the caret rather
     * than through the input connection. Nothing is learned, as nothing typed
     * into these fields is. A search box loses the full stop a recognizer ends
     * a phrase with, which would otherwise be searched for.
     */
    private fun commitFieldVoice(text: String) {
        val state = _uiState.value
        val target = state.captureTarget() ?: return
        if (state.voice.field != state.captureKey()) return
        val before = state.captureCaretText() ?: return
        val words = text.trim().let { if (target.isSearch) it.removeSuffix(".") else it }
        if (words.isEmpty()) return
        val head = before.text.substring(0, before.selectionStart)
        val tail = before.text.substring(before.selectionEnd)
        val cased = VoiceCasing.apply(
            words,
            sentenceStart = VoiceCasing.startsSentence(head.takeLast(VoiceCasing.CONTEXT_CHARS)),
            // A search is not a sentence.
            raise = !plainVoice() && !target.isSearch,
        )
        val spaced = if (plainVoice()) {
            cased
        } else {
            val beforeChar = head.lastOrNull()
            val afterChar = tail.firstOrNull()
            VoiceSpacing.format(
                cased,
                VoiceSpacing.needsLeadingSpace(beforeChar, afterChar),
                VoiceSpacing.needsTrailingSpace(beforeChar, afterChar),
            )
        }
        captureTyped(spaced)
    }

    /**
     * Manual input (keys, swipes, suggestion taps) during block voice typing
     * ends the utterance: partial results are cumulative, so keystrokes woven
     * into the composing region would corrupt it. The partial is kept; the
     * panel/strip stays open to resume with a mic tap.
     *
     * Interactive voice typing keeps the session instead. See the body.
     */
    private fun stopVoiceForManualInput() {
        // The panel's own rail keys are part of the dictation surface and are
        // handled in [onVoiceRailKey], which dispatches through here.
        if (voiceRailKeyInFlight) return
        // Interactive voice typing is the whole point of this check being
        // conditional: the microphone stays open through typing, glides,
        // suggestions and layout switches, because nothing of the utterance
        // is in the field to be corrupted. Spacing is read again when the
        // phrase lands ([commitVoiceUtterance]), not now — this runs before
        // the key that called it has been applied. A dictation into one of the
        // keyboard's own fields is the same case (#353): nothing of it is
        // anywhere until the phrase lands, at the field's caret.
        if (interactiveVoice() || voiceSessionForField) return
        val status = _uiState.value.voice.status
        // A Whisper clip already off the mic and inside the decoder is not
        // something a keystroke should throw away: the audio is captured, the mic
        // is shut, and the words land after whatever was typed. Only the
        // continuous-mode chain is called off, so the mic does not reopen on top
        // of typing that has started.
        if (status == VoiceStatus.TRANSCRIBING) {
            voiceStopRequested = true
            // Nor does the microphone stay open under the typing (#957).
            dropCarriedMic()
            // Except asr4all's: its words are in the field as composing text
            // while the last moment decodes, and the key's own word would
            // replace them. They stay as heard, and the finish is dropped.
            if (asr4allComposed) cancelVoice()
            return
        }
        if (status == VoiceStatus.LISTENING || status == VoiceStatus.FINISHING) {
            voiceStopRequested = true
            // A clip that has heard speech holds a phrase as surely as a
            // partial does, only not yet as words (#921). Dropping it threw
            // away everything said; it is finished instead, and its words land
            // after the typing the way a clip already transcribing does.
            if (voicePhraseState().keyboardKeyFinishesClip()) {
                finishWhisper(userStopped = true)
                return
            }
            cancelVoice()
        }
    }

    /**
     * Strip and bar modes reroute the voice tool: no panel — the compact bar
     * over the keys, or the collapsed bar in the keyboard's place. A voice
     * panel already open (setting flipped mid-session) still closes normally
     * through [onPanelChange]. True when the tap was taken.
     */
    /**
     * [switchVoiceSurface] is mid-flight: the surfaces are being swapped by
     * hand, so [rerouteVoiceTool] must not bounce its onPanelChange call back
     * to the bar the settings flow still says is the mode.
     */
    private var voiceSurfaceSwitch = false

    private fun rerouteVoiceTool(panel: PanelMode): Boolean {
        if (voiceSurfaceSwitch) return false
        if (panel != PanelMode.VOICE || _uiState.value.panel == PanelMode.VOICE) return false
        return when (_uiState.value.settings.voiceBar.mode) {
            VoiceBarSettings.MODE_STRIP -> {
                toggleVoiceStrip()
                true
            }
            VoiceBarSettings.MODE_BAR -> {
                toggleVoiceBar()
                true
            }
            else -> false
        }
    }

    /**
     * A panel is opening: the dictation strip closes outright, and the
     * collapsed bar — which the keyboard needs the window back from (hardware
     * shortcuts can do this) — ends its session but stays armed, so it
     * returns when the panel closes.
     */
    private fun dismissVoiceSurfacesFor(panel: PanelMode) {
        if (_uiState.value.voice.strip) closeVoiceStrip()
        if (panel != PanelMode.VOICE && voiceBarShowing()) cancelVoice()
    }

    /**
     * Voice tool tap in strip mode: dictate over the keys, no panel. A tap over
     * a running dictation is taken by [endVoiceFromTool] first, so the close
     * below is an idle strip being put away.
     */
    private fun toggleVoiceStrip() {
        if (_uiState.value.voice.strip) {
            closeVoiceStrip()
            return
        }
        vibrate()
        if (_uiState.value.secureField) {
            Toast.makeText(
                this,
                getString(R.string.ime_service_voice_secure_field_toast),
                Toast.LENGTH_SHORT,
            ).show()
            return
        }
        _uiState.update { it.copy(voice = it.voice.copy(strip = true)) }
        voiceSilentRetries = 0
        startVoice()
    }

    /**
     * Voice typing was switched off (#578) while a voice surface may be up: the
     * mic is released and the panel, the strip and a field's dictation all go.
     * The collapsed bar goes by itself, since [VoiceBarSettings.armed] reads
     * the switch. Cheap when nothing is up, which is every call but the first.
     */
    private fun putVoiceAway() {
        val state = _uiState.value
        if (state.panel == PanelMode.VOICE) onPanelChange(PanelMode.VOICE, haptic = false)
        cancelVoice()
        if (state.voice.strip || state.voice.field != null) {
            _uiState.update { it.copy(voice = it.voice.copy(strip = false, field = null, canUndo = false)) }
        }
    }

    /**
     * The voice view on screen as the keyboard goes away, when the user has
     * asked for it back on the next show (#699): [VOICE_RESUME_PANEL],
     * [VOICE_RESUME_STRIP] or [VOICE_RESUME_BAR], else null. Leaving the view
     * by hand — Back, its close key, the tool — is how this is switched off, so
     * no separate toggle is needed for the times dictation is not wanted.
     */
    private fun voiceSurfaceToResume(state: KeyboardUiState): String? {
        val voice = state.settings.voiceBar
        if (!voice.enabled || !voice.resumeOnShow || state.secureField) return null
        return when {
            state.panel == PanelMode.VOICE -> VOICE_RESUME_PANEL
            state.voice.strip -> VOICE_RESUME_STRIP
            voiceBarShowing() -> VOICE_RESUME_BAR
            else -> null
        }
    }

    /**
     * Opens the voice view [voiceSurfaceToResume] recorded and starts
     * listening. Recorded in a file rather than a field, because the keyboard
     * that comes back is often a new process (see [PersistentSurfacePrefs]);
     * so it waits for the stored settings, and asks again whether the switch
     * is still on and the field still takes dictation.
     */
    private fun resumeVoiceSurface() {
        val kind = persistentSurface.voice ?: return
        persistentSurface.saveVoice(null)
        serviceScope.launch {
            storedSettingsApplied.await()
            val state = _uiState.value
            val voice = state.settings.voiceBar
            if (!keyboardVisible || state.secureField || !voice.enabled || !voice.resumeOnShow) return@launch
            voiceSilentRetries = 0
            when (kind) {
                VOICE_RESUME_PANEL -> if (state.panel == PanelMode.NONE) onPanelChange(PanelMode.VOICE, haptic = false)
                VOICE_RESUME_STRIP -> if (state.panel == PanelMode.NONE && !state.voice.strip) {
                    _uiState.update { it.copy(voice = it.voice.copy(strip = true)) }
                    startVoice()
                }
                VOICE_RESUME_BAR -> if (voiceBarShowing() && !voiceActive()) startVoice()
            }
        }
    }

    private fun closeVoiceStrip() {
        if (!_uiState.value.voice.strip) return
        vibrate()
        cancelVoice()
        _uiState.update { it.copy(voice = it.voice.copy(strip = false, canUndo = false)) }
    }

    // ---- collapsed voice bar (Gboard-style toolbar) ----

    /**
     * The collapsed bar is on screen right now. Armed but hidden does not
     * count: a panel a hardware shortcut opened, or a password field, puts the
     * keyboard back up without disarming the bar.
     */
    private fun voiceBarShowing(): Boolean {
        val state = _uiState.value
        return state.voice.bar && state.panel == PanelMode.NONE && !state.secureField
    }

    /** Voice tool tap in bar mode: collapse the keyboard to the bar, or restore it. */
    private fun toggleVoiceBar() {
        val state = _uiState.value
        if (state.secureField) {
            vibrate()
            Toast.makeText(
                this,
                getString(R.string.ime_service_voice_secure_field_toast),
                Toast.LENGTH_SHORT,
            ).show()
            return
        }
        if (state.voice.bar) {
            if (voiceBarShowing()) {
                closeVoiceBar()
            } else if (state.panel != PanelMode.NONE) {
                // Armed but hidden behind a panel (a hardware shortcut can
                // open one over the bar): the tap asks for the bar back, not
                // for disarming it. Closing the panel through onPanelChange
                // keeps that path's cleanup; the reroute cannot recurse here
                // because the closing panel is never VOICE.
                onPanelChange(state.panel)
                voiceSilentRetries = 0
                startVoice()
            }
            return
        }
        vibrate()
        // The state flag first so the bar is up this frame; the persisted flag
        // is what brings it back on the next field ([VoiceUi.bar] doc). The
        // exit button follows the stored origin: a tool tap with bar as the
        // settings-chosen mode keeps the keyboard button.
        _uiState.update {
            it.copy(
                voice = it.voice.copy(bar = true, barInline = it.settings.voiceBar.inline),
            )
        }
        serviceScope.launch { settingsRepository.setVoiceBarActive(true) }
        voiceSilentRetries = 0
        startVoice()
    }

    /** The bar's keyboard button (or the voice tool again): bring the keys back. */
    private fun closeVoiceBar() {
        if (!_uiState.value.voice.bar) return
        vibrate()
        cancelVoice()
        voiceBarBounds = null
        _uiState.update { it.copy(voice = it.voice.copy(bar = false, canUndo = false)) }
        serviceScope.launch { settingsRepository.setVoiceBarActive(false) }
    }

    /**
     * The bar published its rectangle. Kept apart from [floatingPanelBounds]:
     * the settings collector clears that one whenever floating mode is off,
     * which is exactly when the bar needs its own region to survive.
     */
    private var voiceBarBounds: android.graphics.Rect? = null

    /**
     * Inline switch between the voice surfaces, from the panel's and strip's
     * collapse buttons and the bar's expand button. Persists the choice as
     * the new default in one write; the ui state moves first so the swap is
     * this frame, not a DataStore round trip later.
     */
    private fun switchVoiceSurface(target: String) {
        val state = _uiState.value
        if (state.secureField) return
        if (target == VoiceBarSettings.MODE_BAR) {
            val from = state.settings.voiceBar.mode
            val returnMode = if (from == VoiceBarSettings.MODE_STRIP) {
                VoiceBarSettings.MODE_STRIP
            } else {
                VoiceBarSettings.MODE_PANEL
            }
            vibrate()
            _uiState.update {
                it.copy(
                    panel = PanelMode.NONE,
                    panelFocus = null,
                    voice = it.voice.copy(strip = false, bar = true, barInline = true),
                )
            }
            serviceScope.launch {
                settingsRepository.setVoiceSurface(
                    mode = VoiceBarSettings.MODE_BAR,
                    barActive = true,
                    returnMode = returnMode,
                )
            }
            voiceSilentRetries = 0
            startVoice()
            return
        }
        // Expanding back to the surface the bar replaced.
        voiceBarBounds = null
        serviceScope.launch {
            settingsRepository.setVoiceSurface(mode = target, barActive = false)
        }
        if (target == VoiceBarSettings.MODE_STRIP) {
            vibrate()
            // One update for the whole swap: dropping the bar first put a
            // bare keyboard on screen for a frame before the strip arrived.
            _uiState.update {
                it.copy(voice = it.voice.copy(bar = false, barInline = false, strip = true))
            }
            voiceSilentRetries = 0
            startVoice()
        } else {
            // The panel opens through onPanelChange so its side effects run;
            // the flag stops the reroute from reading the stale "bar" mode
            // out of the not-yet-updated settings and bouncing straight back.
            // The panel goes up BEFORE the bar flag drops for the same
            // one-frame reason as the strip above: `panel != NONE` already
            // hands the window back to the keyboard, so the intermediate
            // frame shows the panel, never bare keys.
            voiceSurfaceSwitch = true
            try {
                onPanelChange(PanelMode.VOICE)
            } finally {
                voiceSurfaceSwitch = false
            }
            _uiState.update { it.copy(voice = it.voice.copy(bar = false, barInline = false)) }
        }
    }

    private fun onVoiceBarBounds(bounds: VoiceBarAction.Bounds) {
        val rect = android.graphics.Rect(bounds.left, bounds.top, bounds.right, bounds.bottom)
        if (rect != voiceBarBounds) {
            voiceBarBounds = rect
            // Same trick as [onFloatingBounds]: insets are only re-queried on
            // a window layout pass, so force one.
            window?.window?.decorView?.requestLayout()
        }
    }

    /**
     * Asks the on-device recognizer where [tag]'s model stands, for the
     * panel's offline-model chip. UNKNOWN (chip hidden) below API 33 or
     * when the language can't run on-device at all.
     */
    private fun refreshVoiceModelState(tag: String) {
        voiceEngine.checkOnDeviceModel(tag) { result ->
            val state = when (result) {
                VoiceInputEngine.ModelCheckResult.INSTALLED -> VoiceModelState.INSTALLED
                VoiceInputEngine.ModelCheckResult.DOWNLOADABLE -> VoiceModelState.DOWNLOADABLE
                VoiceInputEngine.ModelCheckResult.PENDING -> VoiceModelState.DOWNLOADING
                VoiceInputEngine.ModelCheckResult.UNSUPPORTED -> VoiceModelState.UNKNOWN
            }
            _uiState.update {
                if (it.voice.languageTag != tag) it
                else it.copy(voice = it.voice.copy(modelState = state, modelProgress = -1))
            }
        }
    }

    /** Offline-model chip on the voice panel: download the active language. */
    fun onVoiceModelDownload() {
        vibrate()
        val tag = _uiState.value.voice.languageTag
        _uiState.update {
            it.copy(voice = it.voice.copy(modelState = VoiceModelState.DOWNLOADING, modelProgress = -1))
        }
        // The panel is gone the moment the user goes back to the app they were
        // typing in, and the system's own model download can take minutes.
        val notify = DownloadNotifications.start(
            this,
            DownloadKeys.voiceModel(tag),
            getString(
                CommonR.string.common_notify_download_voice,
                LanguageRegistry.byLocale(tag)?.displayName ?: tag,
            ),
        )
        voiceEngine.downloadModel(
            tag,
            object : VoiceInputEngine.ModelDownloadCallback {
                override fun onProgress(percent: Int) {
                    notify.progress(percent.toLong(), PERCENT_SCALE)
                    _uiState.update {
                        if (it.voice.languageTag != tag) it
                        else it.copy(voice = it.voice.copy(modelProgress = percent))
                    }
                }

                override fun onSuccess() {
                    notify.done()
                    _uiState.update {
                        if (it.voice.languageTag != tag) it
                        else it.copy(voice = it.voice.copy(modelState = VoiceModelState.INSTALLED, modelProgress = -1))
                    }
                }

                override fun onScheduled() {
                    // Queued by the system (Wi-Fi / idle) or fire-and-forget
                    // on API 33. Stays "downloading"; reopening the panel
                    // re-checks and settles the state.
                }

                override fun onError() {
                    notify.failed(getString(R.string.ime_service_voice_model_download_error))
                    Toast.makeText(
                        this@WMKeyboardService,
                        getString(R.string.ime_service_voice_model_download_error),
                        Toast.LENGTH_SHORT,
                    ).show()
                    _uiState.update {
                        if (it.voice.languageTag != tag) it
                        else it.copy(voice = it.voice.copy(modelState = VoiceModelState.DOWNLOADABLE, modelProgress = -1))
                    }
                }
            },
        )
    }

    /**
     * "Use the system recognizer" chip, shown when offline Whisper is selected but
     * has no model downloaded. Switches the engine back to the system recognizer
     * and starts listening, so dictation works from the same tap instead of
     * sending the user to settings for a download they may not want.
     *
     * The change is persisted, the same as picking the engine in settings: a
     * silent one-session override would leave the mic dead again next time.
     */
    fun onVoiceUseSystemEngine() {
        vibrate()
        // A language with its own engine is moved on its own; the rest keep theirs.
        val languageId = voiceLanguageId()
        val own = _uiState.value.settings.whisper.voiceByLang.containsKey(languageId)
        serviceScope.launch {
            if (own) {
                settingsRepository.setVoiceForLanguage(languageId, "system")
            } else {
                settingsRepository.setVoiceEngine("system")
            }
            // Settings arrive through the state flow, so starting has to wait for
            // the new value to land or startVoice would read "whisper" again and
            // put the same prompt back up. Bounded, so a write that never surfaces
            // leaves the panel as it is now rather than a coroutine parked here.
            withTimeoutOrNull(ENGINE_SWITCH_TIMEOUT_MS) {
                _uiState.first { it.settings.whisper.voiceFor(languageId).engine == "system" }
            }
            _uiState.update { it.copy(voice = it.voice.copy(serverNeedsSetup = false, remote = false)) }
            // The panel could have been closed while that landed, and a mic opened
            // with no dictation surface on screen is a privacy dot nobody asked for.
            if (!voiceSessionAlive()) return@launch
            voiceSilentRetries = 0
            startVoice()
        }
    }

    /** Translate chip on the Whisper voice panel: flip translate-to-English. */
    fun onWhisperTranslateToggle() {
        vibrate()
        val next = !_uiState.value.settings.whisper.translate
        serviceScope.launch { settingsRepository.setWhisperTranslate(next) }
    }

    /** "Get a voice model" chip: open the Voice tool settings to download one. */
    fun onOpenVoiceSettings() = openToolSettings(ToolbarTool.VOICE)

    /**
     * Undo chip: removes the last dictated utterance if still at the cursor.
     * Pressed while a phrase is still being heard (#758), it takes back that
     * phrase instead: its words go, and listening starts again, so a sentence
     * that came out wrong is said again without the microphone closing.
     */
    fun onVoiceUndo() {
        vibrate()
        val voice = _uiState.value.voice
        if (voicePhraseState().undoRelistens()) {
            // The partial is the composing region in block voice typing;
            // anywhere else it was only ever on the surface. A clip's
            // recording is dropped by the restart, untranscribed (#921).
            if (voice.partial.isNotEmpty() && !interactiveVoice() && !voiceSessionForField) {
                currentInputConnection?.setComposingText("", 1)
            }
            voiceSilentRetries = 0
            startVoice()
            return
        }
        val last = lastVoiceCommit
        lastVoiceCommit = null
        _uiState.update { it.copy(voice = it.voice.copy(canUndo = false)) }
        if (last == null) return
        val ic = currentInputConnection ?: return
        val before = ic.getTextBeforeCursor(last.length, 0)?.toString()
        if (before == last) ic.deleteSurroundingText(last.length, 0)
    }

    // ---- handwriting ----

    /**
     * The ink model to recognize against. ML Kit and zinnia between them cover
     * most but not all of the keyboard's languages (in F-Droid's build, only
     * Chinese and Japanese), so a language neither can recognize hands over to
     * the first enabled one that can — writing something is better than a
     * panel that offers a download which could never succeed. With none at
     * all, the tag has no model and the panel says so.
     */
    private fun hwLanguageTag(): String {
        val state = _uiState.value
        HandwritingModels.tagFor(state.language)?.let { return it }
        state.settings.enabledLanguages.firstNotNullOfOrNull { HandwritingModels.tagFor(it) }
            ?.let { return it }
        return HandwritingModels.tagForLangId("en")
    }

    /**
     * Handwriting is being taken without the panel: either letter-area swipes
     * draw ink ([swipeHandwriteActive]) or the layout itself is a writing
     * canvas ([handwritingLayoutActive], issue #557). Model readiness is
     * checked separately so this can also gate the "download the model" hint.
     */
    private fun keyboardHandwriteActive(state: KeyboardUiState): Boolean =
        swipeHandwriteActive(state) || handwritingLayoutActive(state)

    /**
     * Letter-area swipes are drawing handwriting (rather than gliding a word):
     * gesture typing on with the swipe action set to HANDWRITE, on the letter
     * layer with no panel open.
     */
    private fun swipeHandwriteActive(state: KeyboardUiState): Boolean =
        !state.layouts.handwriting &&
            state.settings.gestureTyping &&
            state.settings.letterSwipeAction == LetterSwipeAction.HANDWRITE &&
            state.layoutMode == LayoutMode.LETTERS &&
            state.panel == PanelMode.NONE

    /**
     * The active layout is a handwriting one and its canvas is on screen:
     * letters layer, no panel over it. No gesture setting is involved; picking
     * the layout is the opt-in.
     */
    private fun handwritingLayoutActive(state: KeyboardUiState): Boolean =
        state.layouts.handwriting &&
            state.layoutMode == LayoutMode.LETTERS &&
            state.panel == PanelMode.NONE

    /**
     * A swipe finished on the key grid while [keyboardHandwriteActive]. With
     * the model ready it feeds the same pipeline as the handwriting panel;
     * otherwise it points the user at the model download (once) instead of
     * silently gliding a word they didn't ask for.
     */
    fun onKeyboardHandwritingStroke(stroke: HwStroke, canvasSize: IntSize) {
        val state = _uiState.value
        if (!keyboardHandwriteActive(state)) return
        if (state.handwriting.status != HandwritingStatus.READY) {
            // CHECKING/DOWNLOADING resolve on their own; only nag once the
            // absence is confirmed. UNSUPPORTED has nothing to download, and
            // the canvas of a writing layout already says so.
            if (state.handwriting.status == HandwritingStatus.NEED_MODEL ||
                state.handwriting.status == HandwritingStatus.ERROR
            ) {
                if (!hwModelHintShown) {
                    hwModelHintShown = true
                    Toast.makeText(
                        this,
                        getString(R.string.ime_service_handwriting_need_model_toast),
                        Toast.LENGTH_LONG,
                    ).show()
                }
                refreshHandwritingStatus()
            }
            return
        }
        onHandwritingStroke(stroke, canvasSize)
    }

    /**
     * Throw away handwriting ink drawn on the keys — used when the letter
     * layer (and with it the on-keyboard writing surface) goes away, so the
     * strokes don't reappear when the user comes back to the letters.
     */
    private fun dropKeyboardHandwritingInk() {
        hwStylusInk = false
        if (_uiState.value.handwriting.strokes.isEmpty()) return
        hwJob?.cancel()
        hwGeneration++
        _uiState.update {
            it.copy(handwriting = it.handwriting.copy(strokes = emptyList(), recognizing = false))
        }
    }

    /**
     * Re-checks whether the active language's recognition model is on the
     * device, resetting the panel (ink, errors) in the process.
     */
    private fun refreshHandwritingStatus() {
        hwJob?.cancel()
        hwDownloadJob?.cancel()
        hwDownloadJob = null
        hwGeneration++
        val tag = hwLanguageTag()
        _uiState.update {
            it.copy(
                handwriting = HandwritingUi(
                    status = HandwritingStatus.CHECKING,
                    languageTag = tag,
                    fullScreen = it.handwriting.fullScreen,
                    fullScreenInk = it.handwriting.fullScreenInk,
                ),
            )
        }
        serviceScope.launch {
            // No recogniser in this build reads any of the enabled languages
            // (F-Droid's build with only Bangla, say): nothing to fetch.
            if (!HandwritingModels.hasModel(tag)) {
                _uiState.update {
                    if (it.handwriting.languageTag != tag) return@update it
                    it.copy(handwriting = it.handwriting.copy(status = HandwritingStatus.UNSUPPORTED))
                }
                return@launch
            }
            val downloaded = HandwritingModels.isDownloaded(tag)
            // Read off ML Kit's shipped manifest (or zinnia's pinned pack
            // size), so the "needs a download of about N" line quotes this
            // language's real size rather than one rounded figure for all.
            val size = HandwritingModelSizes.installedBytes(applicationContext, tag)
            _uiState.update {
                if (it.handwriting.languageTag != tag) return@update it
                it.copy(
                    handwriting = it.handwriting.copy(
                        status = if (downloaded) HandwritingStatus.READY else HandwritingStatus.NEED_MODEL,
                        modelBytes = size,
                    ),
                )
            }
        }
    }

    /**
     * The button under the handwriting canvas. It fetches the active
     * language's model, and while that is running it is the way back out —
     * one control rather than two, so the panel gains no new callback and
     * a download can always be abandoned.
     */
    fun onHandwritingDownload() {
        vibrate()
        if (_uiState.value.handwriting.status == HandwritingStatus.DOWNLOADING) {
            hwDownloadJob?.cancel()
            hwDownloadJob = null
            // The same control cancels, so the shade's row goes with it rather
            // than reporting a download nobody is doing any more.
            hwDownloadNotify?.gone()
            hwDownloadNotify = null
            refreshHandwritingStatus()
            return
        }
        val tag = _uiState.value.handwriting.languageTag
        _uiState.update {
            it.copy(
                handwriting = it.handwriting.copy(
                    status = HandwritingStatus.DOWNLOADING,
                    errorMessage = null,
                    download = HandwritingDownloadProgress(),
                ),
            )
        }
        // ML Kit's ink models come through Mobile Data Download, which can sit
        // there for a minute and a half before HandwritingModels gives up on
        // it — nobody watches the panel that long.
        val notify = DownloadNotifications.start(
            this,
            DownloadKeys.handwriting(tag),
            getString(
                CommonR.string.common_notify_download_handwriting,
                HandwritingModels.displayName(tag),
            ),
        )
        hwDownloadNotify = notify
        hwDownloadJob = serviceScope.launch {
            val result = runCancellable {
                HandwritingModels.download(applicationContext, tag) { progress ->
                    notify.progress(progress.bytes, progress.totalBytes)
                    _uiState.update {
                        if (it.handwriting.languageTag != tag ||
                            it.handwriting.status != HandwritingStatus.DOWNLOADING
                        ) {
                            return@update it
                        }
                        it.copy(handwriting = it.handwriting.copy(download = progress))
                    }
                }
            }
            hwDownloadJob = null
            hwDownloadNotify = null
            // A failure the user can act on (library downloads switched off)
            // says what to do; any other says only that it failed.
            val failure = (result.exceptionOrNull() as? HandwritingDownloadException)?.message
                ?: getString(R.string.ime_service_handwriting_download_error)
            if (result.isSuccess) {
                notify.done()
            } else {
                notify.failed(failure)
            }
            _uiState.update {
                if (it.handwriting.languageTag != tag) return@update it
                it.copy(
                    handwriting = if (result.isSuccess) {
                        it.handwriting.copy(status = HandwritingStatus.READY, download = null)
                    } else {
                        it.handwriting.copy(
                            status = HandwritingStatus.ERROR,
                            download = null,
                            errorMessage = failure,
                        )
                    },
                )
            }
        }
    }

    /** A stroke was finished on the canvas; recognize after a short pause. */
    fun onHandwritingStroke(stroke: HwStroke, canvasSize: IntSize) {
        val state = _uiState.value
        if (!handwritingInkAccepted(state) || state.handwriting.status != HandwritingStatus.READY) {
            return
        }
        hwCanvasSize = canvasSize
        _uiState.update {
            it.copy(
                handwriting = it.handwriting.copy(strokes = it.handwriting.strokes + stroke, recognizing = false),
                // Stale candidates from the previous word must not be
                // tappable while new ink is on the canvas.
                suggestions = emptyList(),
                octopus = emptyMap(),
                emojiSuggestions = emptyList(),
            )
        }
        scheduleHandwritingRecognition()
    }

    /** Undo button: drop the last stroke and re-recognize what remains. */
    fun onHandwritingUndo() {
        vibrate()
        hwJob?.cancel()
        hwGeneration++
        _uiState.update {
            it.copy(handwriting = it.handwriting.copy(strokes = it.handwriting.strokes.dropLast(1), recognizing = false))
        }
        if (_uiState.value.handwriting.strokes.isNotEmpty()) scheduleHandwritingRecognition()
    }

    private fun scheduleHandwritingRecognition() {
        hwJob?.cancel()
        val generation = ++hwGeneration
        hwJob = serviceScope.launch {
            delay(handwritingRecognitionDelayMs())
            recognizeAndCommitHandwriting(generation)
        }
    }

    /**
     * Quiet time after the last stroke before recognizing and committing.
     * Bengali glyphs are built from several strokes — conjuncts, the matra,
     * vowel signs — and the writer lifts the finger between them; the global
     * default is short enough that a natural mid-glyph pause commits a
     * half-written character. A kanji, a hanzi or a hangul block is the same
     * case, often ten strokes or more (issue #557). Give these a higher floor
     * so a comfortable inter-stroke pause never triggers an early commit,
     * while still honouring a longer pause the user set for themselves.
     */
    private fun handwritingRecognitionDelayMs(): Long {
        val state = _uiState.value
        var delay = state.settings.handwritingCommitDelayMs.toLong()
        if (state.handwriting.languageTag.substringBefore('-') in MULTI_STROKE_HW_LANGUAGES) {
            delay = maxOf(delay, MULTI_STROKE_HW_MIN_COMMIT_DELAY_MS)
        }
        // Writing on the keys: for the dot leeway after a stroke, a tap over
        // the letters is grabbed as the dot on an i/j/t. Committing while that
        // window is still open would leave the dot with no character to join —
        // it would neither type the key (the leeway already claimed the touch)
        // nor land on the glyph. So the ink waits at least as long as the
        // leeway the user set for it.
        if (swipeHandwriteActive(state)) {
            delay = maxOf(delay, state.settings.gesture.handwriteDotCooldownMs.toLong())
        }
        return delay
    }

    /**
     * Runs ML Kit recognition over the accumulated ink and commits the top
     * candidate. Alternates go to the suggestion strip; tapping one
     * replaces the committed word (same mechanics as gesture typing).
     * A [generation] mismatch afterwards means new ink arrived or the
     * panel closed while recognizing — the result is stale, drop it.
     */
    private suspend fun recognizeAndCommitHandwriting(generation: Int) {
        val state = _uiState.value
        val strokes = state.handwriting.strokes
        if (strokes.isEmpty()) return
        val tag = state.handwriting.languageTag
        _uiState.update { it.copy(handwriting = it.handwriting.copy(recognizing = true)) }
        val ic = currentInputConnection
        val preContext = ic?.getTextBeforeCursor(20, 0)?.toString().orEmpty()
        val result = runCancellable {
            hwRecognizer.recognize(
                tag = tag,
                strokes = strokes,
                preContext = preContext,
                writingAreaWidth = hwCanvasSize.width.toFloat(),
                writingAreaHeight = hwCanvasSize.height.toFloat(),
            )
        }
        if (generation != hwGeneration || !handwritingInkAccepted(_uiState.value)) {
            return
        }

        val candidates = result.getOrNull()
        if (candidates == null) {
            // Model gone mid-session (deleted from settings) or ML Kit
            // failure: re-check instead of silently eating ink forever.
            refreshHandwritingStatus()
            return
        }
        if (candidates.isEmpty()) {
            hwStylusInk = false
            _uiState.update {
                it.copy(handwriting = it.handwriting.copy(strokes = emptyList(), recognizing = false))
            }
            return
        }

        var word = candidates.first()
        val settings = state.settings
        // Sentence-start capitalization: English through ML Kit, and the
        // scripts with capitals through PaddleOCR. Bengali has no case.
        if (HandwritingModels.capitalizesSentences(tag) && settings.autoText.capitalize && !state.secureField &&
            word.firstOrNull()?.isLowerCase() == true && shouldAutoCapitalize()
        ) {
            word = word.replaceFirstChar { it.uppercase() }
        }
        // Space between consecutively written words, but never before
        // punctuation ("," "." "?" …), and never on either side of a script
        // written without spaces: two kanji written one after the other are
        // one run of Japanese, not two words (issue #557).
        val needsSpace = settings.handwritingAutoSpace &&
            word.firstOrNull()?.isLetterOrDigit() == true &&
            preContext.isNotEmpty() && !WordContext.isSpaceLike(preContext.last()) &&
            !TextWordScan.isSpaceless(word.codePointAt(0)) &&
            !TextWordScan.isSpaceless(preContext.codePointBefore(preContext.length))
        val connection = currentInputConnection ?: run {
            // Input connection lost between recognition and commit. Clear the
            // spinner and drop the ink instead of leaving the panel stuck in
            // "recognizing" with stale strokes that would be re-recognized
            // together with the next glyph.
            _uiState.update {
                it.copy(handwriting = it.handwriting.copy(strokes = emptyList(), recognizing = false))
            }
            return
        }
        // A half-typed word (write-on-keys mode interleaves taps and ink) or a
        // word the caret settle re-armed as composing commits first, so the
        // recognized word appends instead of replacing the composing region.
        commitComposing(connection, autocorrect = false)
        connection.commitText(if (needsSpace) " $word" else word, 1)
        learn(word)
        lastGestureWord = word
        // Only auto-capitalize's capital is the shift's; the recogniser's own is the word's.
        gestureWordShifted = word != candidates.first()
        // The recogniser's other readings go on the strip below, so a tap
        // there is a correction of this word, as after a glide.
        stripReplacesGestureWord = true
        // Ink, not a swipe: there is no stroke a deep retry could re-decode,
        // and nothing the hand model learned that an undo should take back.
        lastGestureStroke = null
        lastHandAdjustment = null
        armRevertGuard()
        hwStylusInk = false
        _uiState.update {
            it.copy(
                handwriting = it.handwriting.copy(strokes = emptyList(), recognizing = false),
                suggestions = if (state.secureField) emptyList() else candidates,
            )
        }
    }

    /**
     * Somewhere is taking ink right now: the panel (docked, floating or full
     * screen), the keys themselves, or a stylus session Android started over
     * a text field. Both ends of recognition check it, so ink that lost its
     * surface is never committed.
     */
    private fun handwritingInkAccepted(state: KeyboardUiState): Boolean =
        state.panel == PanelMode.HANDWRITING || keyboardHandwriteActive(state) || hwStylusInk

    // ---- stylus handwriting (Android 14+, issue #386 "automatic" mode) ----

    /**
     * Ink from Android's stylus handwriting window is pending recognition.
     * Outlives the session itself on purpose: the session can time out or
     * end on a stroke outside it while the last word is still recognising.
     */
    private var hwStylusInk = false

    /** The view drawing ink in Android's stylus handwriting window. */
    private var stylusInkView: StylusInkView? = null

    /** The ink window [stylusInkView] was last attached to; the platform remakes it. */
    private var stylusInkWindow: android.view.Window? = null

    /**
     * Android saw a stylus start writing over a text field and offers us the
     * session. Taken only in a build with ML Kit, with the stylus mode picked and
     * the model on the phone: the platform then routes stylus events to the
     * ink window over the whole screen while fingers keep reaching the app,
     * which is exactly the split the stylus mode promises.
     */
    override fun onStartStylusHandwriting(): Boolean {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.UPSIDE_DOWN_CAKE) return false
        if (!BuildConfig.ENABLE_ML_KIT_HANDWRITING) return false
        val state = _uiState.value
        if (state.settings.handwritingFullScreenMode != HandwritingFullScreenMode.AUTOMATIC) return false
        if (state.handwriting.status != HandwritingStatus.READY) {
            // Never checked in this process (the panel was never opened), or
            // the model is missing. The check is quick once ML Kit is up, so
            // the next stroke over a field gets its session.
            if (state.handwriting.status != HandwritingStatus.DOWNLOADING) refreshHandwritingStatus()
            return false
        }
        val inkWindow = stylusHandwritingWindow ?: return false
        val view = stylusInkView ?: StylusInkView(this, ::onStylusInkStroke).also { view ->
            stylusInkView = view
            serviceScope.launch {
                _uiState.map { it.handwriting.strokes }.distinctUntilChanged().collect { strokes ->
                    view.setStrokes(strokes)
                }
            }
        }
        if (inkWindow !== stylusInkWindow) {
            (view.parent as? android.view.ViewGroup)?.removeView(view)
            inkWindow.setContentView(view)
            stylusInkWindow = inkWindow
        }
        // Ink from the panel's canvas is in that canvas's coordinates.
        if (!hwStylusInk) dropKeyboardHandwritingInk()
        hwStylusInk = true
        // Long enough to think between words. Fingers pass through the
        // whole time, so a long session costs nothing.
        setStylusHandwritingSessionTimeout(java.time.Duration.ofMillis(STYLUS_SESSION_TIMEOUT_MS))
        return true
    }

    private fun onStylusInkStroke(stroke: HwStroke, canvasSize: IntSize) {
        hwStylusInk = true
        onHandwritingStroke(stroke, canvasSize)
    }

    // ---- tools: flashlight, undo/redo, weather ----

    /** Camera with a flash unit, or null when the device has none. */
    private var torchCameraId: String? = null

    /**
     * The camera enumeration that resolves [torchCameraId], so the flashlight
     * tool can wait for it instead of racing it.
     *
     * Finding the camera with a flash is a call into the camera service per
     * camera, so it runs off the main thread at service create — which leaves
     * a window where [torchCameraId] is null because the answer is not in yet,
     * not because the device has no flash. The tool's own "no flash on this
     * device" message would be a lie during that window, so it joins this
     * first.
     */
    private var torchProbe: Job? = null

    /** Whether a flashlight tap is already parked on [torchProbe]. */
    private var flashlightWaitingOnProbe = false

    /**
     * Whether the Harper grammar library loaded, cached off the hot path.
     *
     * Asking [GrammarChecker] directly is not a field read: the answer comes
     * from a `System.loadLibrary`, and libharper_jni.so is 11 MB. It was being
     * asked on every keyboard show — from the state [onStartInputView] builds
     * and again from the panel-change path — so the first show in each process
     * mapped and relocated the whole library between the field being focused
     * and the keyboard appearing, whether or not the Grammar tool was ever
     * opened. Resolved once at service create instead, on a worker.
     *
     * Only ever set to true, and only the tool's greyed-out state reads it. The
     * tool's own handlers still ask [GrammarChecker] directly — by then the
     * library has to load anyway — so this flag decides chrome, never whether
     * a check can run. See [grammarProbePending] for the window before it
     * settles.
     */
    @Volatile
    private var grammarAvailable = false

    /**
     * The probe that resolves [grammarAvailable].
     *
     * Unlike [torchProbe] nothing joins this one: the flashlight has to know
     * the answer before it can act, whereas the grammar flag only decides
     * whether the tool draws itself as unavailable, and [grammarProbePending]
     * answers that without blocking. Kept so that question can be asked.
     */
    private var grammarProbe: Job? = null

    private val torchCallback = object : CameraManager.TorchCallback() {
        override fun onTorchModeChanged(cameraId: String, enabled: Boolean) {
            if (cameraId == torchCameraId) {
                if (!enabled) torchLitHere = false
                _uiState.update { it.copy(torchOn = enabled) }
            }
        }
    }

    fun onFlashlightToggle() {
        vibrate()
        val probe = torchProbe
        if (probe != null && !probe.isCompleted) {
            // Still working out which camera has the flash — see [torchProbe].
            // Answering now would report "no flash on this device" for a device
            // that has one.
            //
            // At most one tap waits. Two would both resume in the same main-
            // thread drain, before the torch callback had reported the first,
            // so both would read the same `torchOn` and ask for the same state
            // — a double tap would turn the torch on and leave it on.
            if (flashlightWaitingOnProbe) return
            flashlightWaitingOnProbe = true
            serviceScope.launch {
                try {
                    probe.join()
                    toggleFlashlightResolved()
                } finally {
                    flashlightWaitingOnProbe = false
                }
            }
            return
        }
        toggleFlashlightResolved()
    }

    /**
     * Whether the grammar library's availability is still being worked out.
     *
     * The tool's chrome treats "still working it out" as available, rather than
     * waiting: the alternative is telling the user the feature is not in this
     * build when it is, and the wait would be the APK read this all exists to
     * keep off the show path. Safe to be optimistic because the tool's own
     * handlers read [GrammarChecker] directly, so an over-eager answer here
     * cannot make it try to lint without a library — and the probe's own update
     * settles [grammarAvailable] either way.
     */
    private fun grammarProbePending(): Boolean = grammarProbe?.isCompleted == false

    /** [onFlashlightToggle] once [torchCameraId] is known to be settled. */
    private fun toggleFlashlightResolved() {
        if (torchCameraId == null) {
            Toast.makeText(
                this,
                getString(R.string.ime_service_flashlight_missing_toast),
                Toast.LENGTH_SHORT,
            ).show()
            return
        }
        setTorch(!_uiState.value.torchOn)
    }

    private fun setTorch(on: Boolean) {
        val id = torchCameraId ?: return
        // Fails if another app holds the camera; the torch callback keeps
        // the icon truthful either way.
        runCatching {
            (getSystemService(Context.CAMERA_SERVICE) as CameraManager).setTorchMode(id, on)
        }.onSuccess { if (on) torchLitHere = true }
    }

    /**
     * Whether the torch that is on was switched on by the flashlight tool,
     * which is the only torch "Turn off with the keyboard" puts out on hide.
     * Cleared by the torch callback the moment it goes off, from anywhere.
     */
    private var torchLitHere = false

    /**
     * Sends the editor's undo/redo keyboard shortcut (Ctrl+Z / Ctrl+Shift+Z
     * or Ctrl+Y per settings). Editors without shortcut support ignore it —
     * the IME has no way to reach their private undo stacks.
     */
    fun onUndoRedo(redo: Boolean) {
        // A keyboard-owned field has the keys (#612): its own history steps,
        // rather than Ctrl+Z reaching the app behind the panel.
        if (_uiState.value.captureTarget() != null) {
            onCaptureSelectionAction(if (redo) CaptureSelectionAction.REDO else CaptureSelectionAction.UNDO)
            return
        }
        val ic = currentInputConnection ?: return
        vibrate()
        commitComposing(ic, autocorrect = false)
        lastGestureWord = null
        if (!redo && unCleanPastedLink(ic)) return
        val settings = _uiState.value.settings
        val code = if (redo && settings.redoUsesCtrlY) KeyEvent.KEYCODE_Y else KeyEvent.KEYCODE_Z
        var meta = KeyEvent.META_CTRL_ON or KeyEvent.META_CTRL_LEFT_ON
        if (redo && !settings.redoUsesCtrlY) {
            meta = meta or KeyEvent.META_SHIFT_ON or KeyEvent.META_SHIFT_LEFT_ON
        }
        val time = SystemClock.uptimeMillis()
        ic.sendKeyEvent(KeyEvent(time, time, KeyEvent.ACTION_DOWN, code, 0, meta))
        ic.sendKeyEvent(KeyEvent(time, time, KeyEvent.ACTION_UP, code, 0, meta))
    }

    /**
     * Undo on a link the copy listener cleaned (#762): when the clean text is
     * what sits right before the caret, it is swapped for the link as copied,
     * which goes back on the system clipboard too, so the next paste is the
     * original as well. Anything else leaves Undo to the editor.
     */
    private fun unCleanPastedLink(ic: InputConnection): Boolean {
        val (original, clean) = lastCleanedCopy ?: return false
        if (!ic.getSelectedText(0).isNullOrEmpty()) return false
        if (ic.getTextBeforeCursor(clean.length, 0)?.toString() != clean) return false
        lastCleanedCopy = null
        ic.beginBatchEdit()
        ic.deleteSurroundingText(clean.length, 0)
        ic.commitText(original, 1)
        ic.endBatchEdit()
        restoringSystemClipText = original
        runCatching {
            (getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager)
                .setPrimaryClip(android.content.ClipData.newPlainText(null, original))
        }
        return true
    }

    /** Incognito tool: pause learning + clipboard capture with one tap. */
    fun onIncognitoToggle() {
        vibrate()
        val state = _uiState.value
        // The field itself asked for incognito, so the switch has nothing to
        // turn off — say so instead of leaving the tool looking stuck on.
        if (state.fieldIncognito) {
            showFieldIncognitoToast()
            return
        }
        val next = !state.settings.incognito
        Toast.makeText(
            this,
            if (next) {
                getString(R.string.ime_service_incognito_on_toast)
            } else {
                getString(R.string.ime_service_incognito_off_toast)
            },
            Toast.LENGTH_SHORT,
        ).show()
        serviceScope.launch { settingsRepository.setIncognito(next) }
    }

    /**
     * The toolbar's incognito badge tapped (#665). The badge also shows when
     * the field asked for it, which some apps do outside any private tab, and
     * a badge nobody switched on read as a bug. Names who did: the app, or
     * the Incognito switch.
     */
    private fun onIncognitoBadge() {
        if (_uiState.value.fieldIncognito) {
            showFieldIncognitoToast()
        } else {
            Toast.makeText(this, getString(R.string.ime_service_incognito_switch_toast), Toast.LENGTH_SHORT).show()
        }
    }

    /** Which app's field asked for incognito, so the user knows where it came from. */
    private fun showFieldIncognitoToast() {
        val pkg = currentInputEditorInfo?.packageName
        val text = if (pkg.isNullOrEmpty()) {
            getString(R.string.ime_service_incognito_field_toast)
        } else {
            getString(R.string.ime_service_incognito_field_app_toast, appLabel(pkg))
        }
        Toast.makeText(this, text, Toast.LENGTH_LONG).show()
    }

    /**
     * The toolbar's power-saving switch. Flips the manual override, which is
     * what [PowerSavingSettings.appliesTo] reads first — so tapping it on works
     * on a full battery, and tapping it off while an automatic trigger is
     * live only clears the manual half.
     */
    fun onPowerSavingToggle() {
        vibrate()
        val state = _uiState.value
        val config = state.settings.powerSaving
        val next = !config.manual
        // Turning the manual switch *off* while the battery is still low leaves
        // the automatic trigger holding it on, which would read as a dead
        // button. Say which one is in charge instead.
        val stillOn = !next && config.copy(manual = false).appliesTo(powerSaver.state.value)
        Toast.makeText(
            this,
            when {
                next && !config.dropsAnything ->
                    getString(R.string.ime_service_power_saving_on_empty_toast)
                next -> getString(R.string.ime_service_power_saving_on_toast)
                stillOn -> getString(R.string.ime_service_power_saving_still_on_toast)
                else -> getString(R.string.ime_service_power_saving_off_toast)
            },
            Toast.LENGTH_SHORT,
        ).show()
        serviceScope.launch { settingsRepository.setPowerSavingManual(next) }
    }

    /**
     * Enters or leaves the inline resize mode. A second tap while the mode is
     * open is a cancel — the hardware shortcut path can re-trigger the tool,
     * and "tap again to leave without saving" is the least surprising reading.
     */
    fun onResizeToggle() {
        vibrate()
        if (_uiState.value.resize) {
            onSizingAction(SizingAction.ResizeCancel)
            return
        }
        val settings = _uiState.value.settings
        if (floatingNow()) {
            // Floating has its own drag-to-resize grip; the inline handles are
            // laid out against the docked frame and mean nothing here.
            Toast.makeText(
                this,
                getString(R.string.ime_service_resize_floating_toast),
                Toast.LENGTH_SHORT,
            ).show()
            return
        }
        if (voiceBarShowing()) return
        if (settings.oneHandedMode != OneHandedMode.OFF) onOneHandedChange(OneHandedMode.OFF)
        // Through the full close path, not a bare `panel = NONE`: a panel
        // leaves media searches, focus rings and edit buffers behind it.
        if (_uiState.value.panel != PanelMode.NONE) {
            onPanelChange(PanelMode.NONE, haptic = false)
        }
        _uiState.update {
            it.copy(resize = true, toolPicker = null, languageSwitch = null)
        }
    }

    fun onAutocorrectToggle() {
        vibrate()
        val state = _uiState.value
        val correction = state.settings.correction
        val langId = state.language.id
        // Lit only where it corrects, so a press on a language switched off in
        // its own settings (#802) means "correct here": that language comes
        // back on rather than every language going off.
        val next = !correction.enabledFor(langId)
        Toast.makeText(
            this,
            if (next) {
                getString(R.string.ime_service_autocorrect_on_toast)
            } else {
                getString(R.string.ime_service_autocorrect_off_toast)
            },
            Toast.LENGTH_SHORT,
        ).show()
        serviceScope.launch {
            if (next && langId in correction.offLanguages) {
                settingsRepository.setAutocorrectForLanguage(langId, true)
            }
            if (next != correction.enabled) settingsRepository.setAutocorrect(next)
        }
    }

    /**
     * The toolbar's English words switch: whether a phonetic layout keeps an
     * English word in Latin letters. The same setting as Typing → Type English
     * words as English, a tap away because the moment it is wanted is the
     * middle of a Bengali word the keyboard has just read as English. The
     * settings collector redraws that word once the write lands
     * ([syncPhoneticAutoEnglish]).
     *
     * Says why instead of switching when it could not do anything: on a layout
     * that is not phonetic, or with English not among the language's secondary
     * suggestion languages, the switch would flip and nothing would change.
     */
    fun onPhoneticEnglishToggle() {
        vibrate()
        val state = _uiState.value
        val language = state.composer.phoneticLanguage
        val next = !state.settings.suggestionStrip.phoneticEnglishFor(language)
        val message = when {
            language == null -> getString(R.string.ime_service_phonetic_english_needs_layout_toast)
            next && "en" !in state.settings.secondaryLanguages[language].orEmpty() ->
                getString(R.string.ime_service_phonetic_english_needs_secondary_toast, state.language.displayName)
            next -> getString(R.string.ime_service_phonetic_english_on_toast)
            else -> getString(R.string.ime_service_phonetic_english_off_toast)
        }
        Toast.makeText(this, message, Toast.LENGTH_SHORT).show()
        val blocked = language == null ||
            (next && "en" !in state.settings.secondaryLanguages[language].orEmpty())
        if (!blocked && language != null) {
            serviceScope.launch { settingsRepository.setPhoneticEnglish(language, next) }
        }
    }

    /**
     * The strip's ANSI button on a Bengali layout: write Bijoy-era ANSI
     * (আ as Av) or Unicode. The settings collector switches the output once
     * the write lands ([syncLegacyOutput]). A word still being typed commits in
     * the output it was started in only if it commits before that; it is
     * committed here first, so the switch starts cleanly at the next word.
     */
    fun onAnsiOutputToggle() {
        vibrate()
        val state = _uiState.value
        val strip = state.settings.suggestionStrip
        if (!strip.bengaliAnsiAllowed) return
        currentInputConnection?.let { commitComposing(it, autocorrect = false) }
        val next = !strip.bengaliAnsiOn
        Toast.makeText(
            this,
            if (next) {
                getString(R.string.ime_service_ansi_on_toast, BijoyAnsi.Version.of(strip.bengaliAnsiVersion).number)
            } else {
                getString(R.string.ime_service_ansi_off_toast)
            },
            Toast.LENGTH_SHORT,
        ).show()
        serviceScope.launch { settingsRepository.setBengaliAnsiOn(next) }
    }

    /**
     * The strip's Zawgyi button on a Burmese layout: write Zawgyi or Unicode,
     * the same way [onAnsiOutputToggle] does for Bengali. Turning it off also
     * ends a Zawgyi field the strip's offer started, so the button always
     * means what it shows.
     */
    fun onZawgyiOutputToggle() {
        vibrate()
        val strip = _uiState.value.settings.suggestionStrip
        if (!strip.burmeseZawgyiAllowed) return
        currentInputConnection?.let { commitComposing(it, autocorrect = false) }
        val next = !(strip.burmeseZawgyiOn || zawgyiField)
        if (!next) zawgyiField = false
        Toast.makeText(
            this,
            getString(if (next) R.string.ime_service_zawgyi_on_toast else R.string.ime_service_zawgyi_off_toast),
            Toast.LENGTH_SHORT,
        ).show()
        serviceScope.launch { settingsRepository.setBurmeseZawgyiOn(next) }
        // Switched here too, not only by the collector once the write lands:
        // turning off a field the offer started writes a setting that already
        // reads off, which the collector never sees.
        if (_uiState.value.language.id == "my") setOutputEncoding(if (next) OutputEncoding.ZawgyiOutput else null)
    }

    /**
     * Chinese candidates in Simplified or Traditional characters (#962): the
     * strip's 繁 button and the [KeyAction.HanScript] key, over the same
     * setting as the Chinese screen's Traditional characters row.
     *
     * Unlike the ANSI and Zawgyi buttons nothing is committed first: what is
     * composing is a reading, not text, and the candidates for it are drawn
     * again in the new script on the spot. The composers read
     * [CjkConfig.traditionalOutput] at call time, so it is switched here
     * rather than when the settings write comes back, which also keeps a
     * quick second tap from reading the old value.
     */
    fun onTraditionalOutputToggle() {
        vibrate()
        val next = !CjkConfig.traditionalOutput
        CjkConfig.traditionalOutput = next
        if (next) loadHanVariantTables()
        Toast.makeText(
            this,
            getString(if (next) R.string.ime_service_traditional_on_toast else R.string.ime_service_traditional_off_toast),
            Toast.LENGTH_SHORT,
        ).show()
        serviceScope.launch { settingsRepository.setCjkTraditionalOutput(next) }
        val state = _uiState.value
        if (state.composer.isConversion && composing.isNotEmpty()) refreshConversionCandidates(state)
    }

    /**
     * The toolbar's Selection actions switch (issue #177). The same setting as
     * Advanced → Selection actions, so the bar can be kept for the moments it
     * is wanted without a trip to the settings app. The settings collector
     * clears or offers the bar once the write lands.
     */
    fun onSelectionActionsToggle() {
        vibrate()
        val next = !_uiState.value.settings.selectionMacros.enabled
        Toast.makeText(
            this,
            if (next) {
                getString(R.string.ime_service_selection_actions_on_toast)
            } else {
                getString(R.string.ime_service_selection_actions_off_toast)
            },
            Toast.LENGTH_SHORT,
        ).show()
        serviceScope.launch { settingsRepository.setSelectionMacrosEnabled(next) }
    }

    /**
     * One of the current app's colours pressed in the Themes tool, or
     * [AppColorSettings.PICK_OFF] for "this app keeps the plain theme".
     * Remembered for that app alone.
     */
    fun onAppColorPick(packageName: String, pick: Int) {
        vibrate()
        serviceScope.launch { settingsRepository.setAppColorPick(packageName, pick) }
    }

    /** A palette style pressed in the Themes tool; applies to every app. */
    fun onAppColorStyle(style: PaletteStyle) {
        vibrate()
        serviceScope.launch { settingsRepository.setAppColorsStyle(style) }
    }

    /**
     * A theme pressed in the Themes tool: the manual selection normally, and
     * the live half of the auto pair while that owns the choice.
     *
     * The redirect is what makes the press mean anything at all under the pair.
     * `effectiveThemeId` ignores `keyboardThemeId` outright while auto-theme is
     * on, so writing it there was a press that changed a stored value nothing
     * reads and left the board exactly as it was — indistinguishable, from the
     * user's side, from the tool being broken.
     *
     * Turning the pair off instead was the other way to make the press work,
     * and it is the wrong one: the user configured two themes and a trigger,
     * and a quick panel must not throw that away to answer one press. Setting
     * the half on screen keeps the pair and does what was asked.
     *
     * The panel refuses the press in the two states this cannot serve (a mode's
     * theme, and a random half), so those never arrive here.
     */
    fun onThemeSelect(id: String) {
        vibrate()
        val settings = _uiState.value.settings
        // Resolving the slot walks the clock and possibly the sun, so it is
        // asked for only when the pair is on and the answer can matter.
        val darkSlot = settings.autoTheme.enabled && activeDarkSlot(settings)
        val target = settings.themeSelectionTarget(
            darkSlot = darkSlot,
            modeOwnsTheme = settings.modeThemeOwner(_uiState.value.activeModeId) != null,
        )
        serviceScope.launch {
            when (target) {
                ThemeSelectionTarget.MANUAL -> settingsRepository.setKeyboardThemeId(id)
                ThemeSelectionTarget.AUTO_DARK -> settingsRepository.setAutoThemeDarkId(id)
                ThemeSelectionTarget.AUTO_LIGHT -> settingsRepository.setAutoThemeLightId(id)
                ThemeSelectionTarget.NONE -> Unit
            }
        }
    }

    /** Blank id means the built-in icons; the board redraws on its own. */
    fun onIconPackSelect(id: String) {
        vibrate()
        serviceScope.launch { settingsRepository.setIconPack(id) }
    }

    /**
     * Emoji face picked from the themes panel.
     *
     * Two writes rather than one, because the setting is two fields: which kind
     * of face, and — for a face out of the font library — which one. Going
     * through [com.wasimaster.wmkeyboard.core.settings.SettingsRepository.setInstalledEmojiFont]
     * for the library case is what pairs them in a single edit, so the board
     * never sees a frame where the choice says INSTALLED and the id still names
     * the previous font.
     */
    fun onEmojiFontSelect(choice: EmojiFontChoice, installedId: String) {
        vibrate()
        serviceScope.launch {
            if (choice == EmojiFontChoice.INSTALLED) {
                settingsRepository.setInstalledEmojiFont(installedId)
            } else {
                settingsRepository.setEmojiFont(choice)
            }
        }
    }

    /**
     * Key label font picked from the appearance panel.
     *
     * Which setting it writes is the same split the font settings screen makes:
     * a script with a curated list of its own gets a per-script override, and
     * every other script — Latin, and the Cyrillic and Greek that ride it —
     * shares the keyboard's one `keyFontId`. Asking [KeyboardFonts] rather than
     * testing for LATIN keeps the two screens from disagreeing about which
     * scripts have an override to write.
     */
    fun onFontSelect(script: ScriptId, fontId: String) {
        vibrate()
        serviceScope.launch {
            if (KeyboardFonts.scriptFontChoices(script) == null) {
                settingsRepository.setKeyFontId(fontId)
            } else {
                settingsRepository.setScriptFontId(script.name, fontId)
            }
        }
    }

    /** Sound & haptics quick panel writes straight into the shared settings. */
    fun onSoundHaptic(action: SoundHapticAction) {
        serviceScope.launch {
            when (action) {
                is SoundHapticAction.Haptics -> settingsRepository.setHapticFeedback(action.on)
                is SoundHapticAction.HapticStyleChange -> settingsRepository.setHapticStyle(action.style)
                is SoundHapticAction.HapticAmplitude -> settingsRepository.setHapticAmplitude(action.amplitude)
                is SoundHapticAction.HapticDuration -> settingsRepository.setHapticStrengthMs(action.durationMs)
                is SoundHapticAction.Sound -> settingsRepository.setKeySound(action.on)
                is SoundHapticAction.SoundStyleChange -> settingsRepository.setKeySoundStyle(action.style)
                is SoundHapticAction.SoundVolume -> settingsRepository.setKeySoundVolume(action.volume)
                is SoundHapticAction.SoundCustomChange ->
                    settingsRepository.setKeySoundCustomId(action.id)
                is SoundHapticAction.SoundPackChange ->
                    settingsRepository.setKeySoundPackId(action.id)
            }
        }
        // Preview the result right away so the user can dial it in by feel.
        // The DataStore write above lands asynchronously, so previews pass
        // the new value explicitly instead of re-reading settings. The
        // player's debounce keeps slider drags from buzz-sawing the motor.
        val settings = _uiState.value.settings
        when (action) {
            is SoundHapticAction.Haptics -> if (action.on) {
                HapticPlayer.preview(
                    this, settings.haptics.style, settings.haptics.amplitude, settings.haptics.strengthMs,
                    inputRootView,
                )
            }
            is SoundHapticAction.HapticStyleChange -> HapticPlayer.preview(
                this, action.style, settings.haptics.amplitude, settings.haptics.strengthMs, inputRootView,
            )
            is SoundHapticAction.HapticAmplitude -> HapticPlayer.preview(
                this, settings.haptics.style, action.amplitude, settings.haptics.strengthMs, inputRootView,
            )
            is SoundHapticAction.HapticDuration -> HapticPlayer.preview(
                this, settings.haptics.style, settings.haptics.amplitude, action.durationMs, inputRootView,
            )
            is SoundHapticAction.Sound -> if (action.on) playKeySound(force = true)
            is SoundHapticAction.SoundStyleChange -> playKeySound(style = action.style, force = true)
            is SoundHapticAction.SoundVolume -> playKeySound(volume = action.volume, force = true)
            // Style and id both passed, because the write above has not landed
            // yet: the preview has to be of the sound just pressed, not of the
            // one the settings still name.
            is SoundHapticAction.SoundCustomChange -> playKeySound(
                style = KeySoundStyle.CUSTOM, id = action.id, force = true,
            )
            is SoundHapticAction.SoundPackChange -> playKeySound(
                style = KeySoundStyle.PACK, id = action.id, force = true,
            )
        }
    }

    private var weatherJob: Job? = null

    /**
     * Fetches current conditions when the weather panel opens; cached for
     * 15 minutes unless [force]d from the refresh button.
     */
    private fun refreshWeather(force: Boolean = false) {
        val settings = _uiState.value.settings
        val latitude = settings.weather.latitude
        val longitude = settings.weather.longitude
        if (latitude == null || longitude == null) {
            _uiState.update { it.copy(weather = WeatherUi.NoLocation) }
            return
        }
        val cached = (_uiState.value.weather as? WeatherUi.Ready)?.info
        if (!force && cached != null &&
            System.currentTimeMillis() - cached.fetchedAtMillis < weatherCacheMs()
        ) {
            return
        }
        weatherJob?.cancel()
        _uiState.update { it.copy(weather = WeatherUi.Loading) }
        weatherJob = serviceScope.launch {
            val info = withContext(Dispatchers.IO) {
                runCatching { WeatherClient.fetch(latitude, longitude) }.getOrNull()
            }
            _uiState.update {
                it.copy(weather = if (info != null) WeatherUi.Ready(info) else WeatherUi.Error)
            }
            // A weather chip may be sitting on the strip waiting for exactly
            // this — redraw it with the numbers (or drop it on an error).
            if (_uiState.value.smart?.pendingWeather == true) refreshSmartSuggestion()
        }
    }

    // ---- wikipedia tool ----

    private var wikiJob: Job? = null

    /** The results an open article came from, for the back arrow. */
    private var wikiLastResults: WikiUi.SearchResults? = null

    /**
     * The line a panel shows when a tool request fails. A [ToolHttpException]
     * holds a resource id and, when the provider sent one, its own words, so it
     * goes through [ToolHttp.friendlyMessage]; anything else keeps its own
     * message, or [fallbackRes] when it has none.
     */
    private fun requestErrorText(t: Throwable, @StringRes fallbackRes: Int): String =
        if (t is ToolHttpException) {
            ToolHttp.friendlyMessage(this, t)
        } else {
            t.message?.takeIf { it.isNotBlank() } ?: getString(fallbackRes)
        }

    private fun runWikiSearch(query: String) {
        if (query.isBlank()) return
        wikiJob?.cancel()
        _uiState.update { it.copy(wiki = WikiUi.Loading) }
        wikiJob = serviceScope.launch {
            val lang = _uiState.value.settings.webSearch.wikiLanguage
            val result = withContext(Dispatchers.IO) {
                runCatching { WikipediaClient.search(query, lang) }
            }
            _uiState.update {
                it.copy(
                    wiki = result.fold(
                        onSuccess = { r -> WikiUi.SearchResults(r, query) },
                        onFailure = { e ->
                            WikiUi.Error(requestErrorText(e, R.string.ime_service_search_error))
                        },
                    ),
                )
            }
        }
    }

    /** Search result or article link tapped: load that article's summary. */
    fun onWikiOpen(title: String) {
        vibrate()
        (_uiState.value.wiki as? WikiUi.SearchResults)?.let { wikiLastResults = it }
        wikiJob?.cancel()
        _uiState.update { it.copy(wiki = WikiUi.Loading) }
        wikiJob = serviceScope.launch {
            val lang = _uiState.value.settings.webSearch.wikiLanguage
            val result = withContext(Dispatchers.IO) {
                runCatching { WikipediaClient.summary(title, lang) }
            }
            _uiState.update {
                it.copy(
                    wiki = result.fold(
                        onSuccess = { s ->
                            WikiUi.Article(s, canGoBack = wikiLastResults != null)
                        },
                        onFailure = { e ->
                            WikiUi.Error(
                                requestErrorText(e, R.string.ime_service_wiki_article_error),
                            )
                        },
                    ),
                )
            }
        }
    }

    fun onWikiBack() {
        vibrate()
        _uiState.update { it.copy(wiki = wikiLastResults ?: WikiUi.Idle) }
    }

    /** Links tab opened for the first time: fetch the article's links. */
    fun onWikiLoadLinks() {
        val article = _uiState.value.wiki as? WikiUi.Article ?: return
        if (article.links != null || article.loadingExtra) return
        _uiState.update { it.copy(wiki = article.copy(loadingExtra = true)) }
        serviceScope.launch {
            val lang = _uiState.value.settings.webSearch.wikiLanguage
            val result = withContext(Dispatchers.IO) {
                runCatching {
                    WikipediaClient.links(
                        article.summary.title,
                        lang,
                        _uiState.value.settings.toolLimits.wikiLinkLimit,
                    )
                }
            }
            _uiState.update { state ->
                val current = state.wiki as? WikiUi.Article ?: return@update state
                if (current.summary.title != article.summary.title) return@update state
                state.copy(
                    wiki = current.copy(
                        links = result.getOrDefault(emptyList()),
                        loadingExtra = false,
                    ),
                )
            }
        }
    }

    /** Full-article tab opened for the first time: fetch the plain text. */
    fun onWikiLoadFull() {
        val article = _uiState.value.wiki as? WikiUi.Article ?: return
        if (article.fullText != null || article.loadingExtra) return
        _uiState.update { it.copy(wiki = article.copy(loadingExtra = true)) }
        serviceScope.launch {
            val lang = _uiState.value.settings.webSearch.wikiLanguage
            val result = withContext(Dispatchers.IO) {
                runCatching { WikipediaClient.fullText(article.summary.title, lang) }
            }
            _uiState.update { state ->
                val current = state.wiki as? WikiUi.Article ?: return@update state
                if (current.summary.title != article.summary.title) return@update state
                state.copy(
                    wiki = current.copy(
                        fullText = result.getOrDefault(""),
                        loadingExtra = false,
                    ),
                )
            }
        }
    }

    // ---- currency tool ----

    private var currencyJob: Job? = null

    /** The fiat table on its own, so coins can be re-merged without refetching it. */
    private var fiatRates: CurrencyClient.Rates? = null

    /** The coin table as the provider sent it, before the user's picks are applied. */
    private var cryptoRaw: Map<String, Double> = emptyMap()

    /**
     * Rates refresh at most every cache-TTL setting (they update daily
     * upstream anyway). Coins are a separate fetch on a separate, much
     * shorter clock, and only when something actually needs them — a user
     * who never types a ticker never touches the coin provider.
     */
    private fun refreshCurrencyRates(force: Boolean = false, wantCrypto: Boolean = false) {
        val settings = _uiState.value.settings
        val ready = _uiState.value.currency as? CurrencyUi.Ready
        val now = System.currentTimeMillis()
        val fiatTtlMs = settings.currencyCacheHours * 60L * 60L * 1000L
        val sources = settings.rateSources
        val cryptoTtlMs = sources.cryptoCacheMinutes * 60L * 1000L
        val needFiat = force || ready == null || now - ready.fetchedAtMs >= fiatTtlMs
        val needCrypto = sources.cryptoEnabled && (force || wantCrypto) &&
            (force || ready == null || now - ready.cryptoFetchedAtMs >= cryptoTtlMs)
        if (!needFiat && !needCrypto) return
        // Data saving, when the user has asked for it here: the rate table is
        // small enough to be allowed by default, and a refusal costs nothing
        // visible — whatever was last fetched stays on the panel and the chip
        // keeps converting with it.
        if (!dataSaverStatus.allows(MeteredFeature.CURRENCY_RATES)) return
        currencyJob?.cancel()
        // Only a fiat fetch with nothing cached blanks the panel: a coin
        // refresh must never take a working rate table off the screen.
        if (needFiat && ready == null) _uiState.update { it.copy(currency = CurrencyUi.Loading) }
        currencyJob = serviceScope.launch {
            val fiat = if (needFiat) {
                withContext(Dispatchers.IO) {
                    runCatching { CurrencyClient.fetchRates(settings.fiatRateProviders().ifEmpty { throw NoRateProviderException() }) }
                }
            } else {
                null
            }
            val coins = if (needCrypto) {
                withContext(Dispatchers.IO) {
                    runCatching {
                        CurrencyClient.fetchCryptoRates(
                            settings.cryptoRateProviders().ifEmpty { throw NoRateProviderException() },
                            CryptoCatalog.enabled(sources.cryptoTickers),
                        )
                    }
                }
            } else {
                null
            }
            fiat?.getOrNull()?.let { fiatRates = it }
            coins?.getOrNull()?.let { cryptoRaw = it }
            val merged = mergedRates()
            val stamp = System.currentTimeMillis()
            _uiState.update { state ->
                val previous = state.currency as? CurrencyUi.Ready
                val next = if (merged == null) {
                    CurrencyUi.Error(getString(R.string.ime_service_currency_error))
                } else {
                    CurrencyUi.Ready(
                        rates = merged,
                        // A failed fiat fetch keeps the old table and the old
                        // clock, so the next open tries again rather than
                        // dropping the panel back to an error.
                        fetchedAtMs = if (fiat?.isSuccess == true) stamp else previous?.fetchedAtMs ?: stamp,
                        // A failed coin fetch still stamps its clock: that is
                        // the backoff that stops a dead source being asked
                        // again on every keystroke.
                        cryptoFetchedAtMs = if (coins != null) stamp else previous?.cryptoFetchedAtMs ?: 0L,
                        cryptoFailed = coins?.isFailure == true,
                    )
                }
                state.copy(currency = next)
            }
            // A "150 usd" chip may be sitting on the strip waiting for these
            // rates to arrive before it can show an amount.
            if (_uiState.value.smart?.pending == true) refreshSmartSuggestion()
        }
    }

    /** The fiat table with the coins the user has turned on folded into it. */
    private fun mergedRates(): CurrencyClient.Rates? {
        val fiat = fiatRates ?: return null
        val sources = _uiState.value.settings.rateSources
        if (!sources.cryptoEnabled || cryptoRaw.isEmpty()) return fiat.copy(crypto = emptySet())
        return CurrencyClient.withCrypto(fiat, cryptoRaw, sources.cryptoTickers)
    }

    /** Re-applies the coin picks to the cached tables, with no network at all. */
    private fun remergeCurrencyRates() {
        val merged = mergedRates() ?: return
        _uiState.update { state ->
            val ready = state.currency as? CurrencyUi.Ready ?: return@update state
            if (ready.rates == merged) state else state.copy(currency = ready.copy(rates = merged))
        }
    }

    fun onCurrencyPairChange(from: String, to: String) {
        vibrate()
        serviceScope.launch { settingsRepository.setCurrencyPair(from, to) }
        val sources = _uiState.value.settings.rateSources
        if (sources.cryptoEnabled) {
            val coins = CryptoCatalog.enabled(sources.cryptoTickers)
            if (from in coins || to in coins) refreshCurrencyRates(wantCrypto = true)
        }
    }

    /** True when either side of the saved pair is a coin. */
    private fun pairHasCoin(): Boolean {
        val settings = _uiState.value.settings
        val sources = settings.rateSources
        if (!sources.cryptoEnabled) return false
        val coins = CryptoCatalog.enabled(sources.cryptoTickers)
        return settings.currencyFrom in coins || settings.currencyTo in coins
    }

    // ---- QR generator tool ----

    /** Renders the panel's typed QR content at the configured size and commits the PNG. */
    fun onQrSend() {
        val state = _uiState.value
        val content = state.mediaQuery
        if (content.isBlank()) return
        vibrate()
        serviceScope.launch {
            val file = withContext(Dispatchers.IO) {
                runCatching {
                    val bitmap = QrCodeGen.bitmap(
                        content, state.settings.scanner.qrSizePx, state.settings.scanner.qrEcc.name,
                    ) ?: error("Too much text for one QR code")
                    val dir = File(cacheDir, "media").apply { mkdirs() }
                    val target = File(dir, "qr_${content.hashCode().toUInt()}.png")
                    target.outputStream().use {
                        bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG, 100, it)
                    }
                    target
                }.getOrNull()
            }
            if (file == null) {
                Toast.makeText(
                    this@WMKeyboardService,
                    getString(R.string.ime_service_qr_error),
                    Toast.LENGTH_SHORT,
                ).show()
                return@launch
            }
            saveToGalleryIfEnabled(
                file,
                MediaMime.PNG,
                state.settings.scanner.qrSaveToGallery,
                "QR",
            )
            commitImageFile(file, MediaMime.PNG, state.settings.scanner.qrSendMode)
        }
    }

    /**
     * Copies a produced image into Pictures/WM Keyboard when the tool's
     * save option is on. Runs off the main thread; a failure only costs the
     * gallery copy, never the send that follows. [confirm] says so in a toast
     * when it worked, for a save that is the whole action.
     */
    private fun saveToGalleryIfEnabled(
        file: File,
        mimeType: String,
        enabled: Boolean,
        namePrefix: String,
        confirm: Boolean = false,
    ) {
        if (!enabled) return
        if (!GallerySaver.canSave(this)) {
            // Pre-Q needs WRITE_EXTERNAL_STORAGE, which an IME cannot ask
            // for itself — bounce through the trampoline and let the user
            // retry once it is granted.
            startActivity(
                Intent(this, StoragePermissionActivity::class.java).apply {
                    addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                },
            )
            return
        }
        val stamp = java.text.SimpleDateFormat("yyyyMMdd_HHmmss", java.util.Locale.US)
            .format(java.util.Date())
        val name = "${namePrefix}_$stamp.${MediaMime.extension(mimeType)}"
        serviceScope.launch(Dispatchers.IO) {
            val saved = GallerySaver.save(this@WMKeyboardService, file, mimeType, name) != null
            if (!saved || confirm) {
                withContext(Dispatchers.Main) {
                    Toast.makeText(
                        this@WMKeyboardService,
                        getString(if (saved) R.string.ime_camera_saved_toast else R.string.ime_service_gallery_save_error),
                        Toast.LENGTH_SHORT,
                    ).show()
                }
            }
        }
    }

    // ---- symbols / calculator / converter inserts ----

    /**
     * Modes panel: apply a mode manually (null = back to automatic,
     * [NoKeyboardModeId] = no mode at all). The pick sticks for the current
     * app and resets on the next app switch.
     */
    fun onModeSelect(id: String?) {
        vibrate()
        applyManualMode(id)
    }

    /**
     * A mode key (see [KeyAction.Mode]): a toggle against the mode that is on
     * (#795, #834). When another mode is on, or none, it picks its mode the way
     * the Modes panel does; when its mode is already on it goes back to
     * automatic. So a press on a mode its app or field already chose leaves
     * no hand pick behind to beat the field bindings that follow. A key naming
     * a mode that has since been deleted does nothing. No haptic here: the key
     * press already gave one.
     */
    private fun onModeKey(id: String) {
        val base = baseSettings ?: return
        if (id.isBlank() || base.keyboardModes.none { it.id == id }) return
        applyManualMode(modeKeyPick(id, _uiState.value.activeModeId))
    }

    private fun applyManualMode(id: String?) {
        manualModeId = id
        saveManualMode(id)
        val base = baseSettings ?: return
        val mode = resolveKeyboardMode(
            base.keyboardModes, currentPackage, currentModeFields, manualModeId,
            currentFieldHint,
        )
        val settings = base.applyMode(mode)
        // A mode that turns the swipes or two-thumb typing off ends an open
        // two-thumb word as it stands, under the settings it was begun with:
        // left open, nothing under the new mode would ever end it (#753).
        if (duetWord.active && (!settings.gestureTyping || !settings.gesture.twoThumbGlide)) {
            currentInputConnection?.let { ic ->
                allUpJob?.cancel()
                allUpJob = null
                settleDuet(ic)
                commitDuet(ic)
            }
        }
        _uiState.update {
            it.copy(
                settings = settings,
                activeModeId = mode?.id,
                noModePicked = manualModeId == NoKeyboardModeId,
                // The mode brings its own default set; drop the session pick.
                activeSymbolSetId = null,
            )
        }
    }

    /** Symbol row's picker chip: switch the visible set. */
    fun onSymbolSetSelect(id: String) {
        vibrate()
        val state = _uiState.value
        _uiState.update { it.copy(activeSymbolSetId = id) }
        // While a mode prescribes its own set list the pick is session-only —
        // it shouldn't rewrite the global row's default set.
        val modeSets = baseSettings?.keyboardModes
            ?.firstOrNull { it.id == state.activeModeId }?.symbolSetIds
        if (modeSets == null) {
            serviceScope.launch { settingsRepository.setSymbolRowActiveSet(id) }
        }
    }

    /** The symbol row's picker and its held-entry menu, bundled (#323). */
    private val symbolRowCallbacks by lazy {
        com.wasimaster.wmkeyboard.ime.ui.SymbolRowCallbacks(
            onSetSelect = ::onSymbolSetSelect,
            onAction = ::onSymbolRowAction,
        )
    }

    /**
     * An item of the menu a held symbol row entry opens (#323). Every one of
     * them is a settings write, and the row redraws from the settings flow, so
     * nothing here touches the UI state directly.
     */
    private fun onSymbolRowAction(action: SymbolRowAction) {
        vibrate()
        when (action) {
            is SymbolRowAction.RemoveEntry -> serviceScope.launch {
                settingsRepository.removeSymbolSetEntry(action.setId, action.index, action.entry)
            }
            is SymbolRowAction.HideInMode -> {
                // The stored mode, not the applied view of it: the write
                // replaces the whole mode, and only the row switch changes.
                val mode = baseSettings?.keyboardModes?.firstOrNull { it.id == action.modeId } ?: return
                serviceScope.launch {
                    settingsRepository.upsertKeyboardMode(mode.copy(symbolRowEnabled = false))
                }
            }
            is SymbolRowAction.DeleteSet -> serviceScope.launch {
                settingsRepository.deleteSymbolSet(action.setId)
            }
            SymbolRowAction.OpenSettings -> openSymbolRowSettings()
        }
    }

    /**
     * The settings behind the symbol row as it stands. The active mode's
     * editor when the row is the mode's doing (the row is off globally, or
     * the mode names its own sets), scrolled to the row that did it; the
     * global Symbol row page otherwise.
     */
    private fun openSymbolRowSettings() {
        val base = baseSettings
        val mode = base?.keyboardModes?.firstOrNull { it.id == _uiState.value.activeModeId }
        val intent = if (base != null && mode != null && (!base.symbolRowEnabled || mode.symbolSetIds != null)) {
            MainActivityContract.intent(
                this,
                route = "mode_edit/${mode.id}",
                setting = if (mode.symbolSetIds != null) "modes_symbol_sets_title" else "modes_symbol_row_title",
            )
        } else {
            MainActivityContract.intent(this, route = com.wasimaster.wmkeyboard.ime.ui.SYMBOL_ROW_SETTINGS_ROUTE)
        }
        startActivity(intent)
    }

    /** Symbol cell tapped: type it and remember it under Recents. */
    fun onSymbolInsert(symbol: String) {
        vibrate()
        val ic = currentInputConnection ?: return
        commitComposing(ic, autocorrect = false)
        ic.commitText(symbol, 1)
        serviceScope.launch { settingsRepository.addSymbolRecent(symbol) }
    }

    /** Insert chip on the calculator/converter/generator panels. */
    fun onToolTextInsert(text: String) {
        if (text.isEmpty()) return
        vibrate()
        val ic = currentInputConnection ?: return
        commitComposing(ic, autocorrect = false)
        ic.commitText(text, 1)
    }

