    /** The panel's deg/rad chip — same persisted setting as the tool's page. */
    fun onCalcDegreesToggle() {
        vibrate()
        val next = !_uiState.value.settings.calcDegrees
        serviceScope.launch { settingsRepository.setCalcDegrees(next) }
    }

    /**
     * Edits to the calculator's expression, from the soft keypad and the
     * physical keys alike. The ring is dropped on every edit, the same rule as
     * [updateQuery]: the Insert chip appears and disappears with the result's
     * validity, and a stale index would activate the wrong thing.
     */
    private fun calcEdit(transform: (String) -> String) {
        _uiState.update {
            it.copy(calcExpression = transform(it.calcExpression), panelFocus = null)
        }
    }

    fun onCalcExpressionChange(value: String) {
        calcEdit { value }
    }

    /**
     * The calculator engine's spellings for the keys a physical keyboard has:
     * ASCII operators arrive as the keypad's typographic ones. Everything else
     * passes through — `sin(`, digits, brackets — and a genuinely wrong
     * character surfaces in the display's own error line, where it can be seen
     * and backspaced, rather than being silently eaten.
     */
    private fun mapCalcChars(text: String): String =
        text.map { c ->
            when (c) {
                '*' -> '×'
                '/' -> '÷'
                '-' -> '−'
                else -> c
            }
        }.joinToString("")

    private fun converterEdit(transform: (String) -> String) {
        _uiState.update {
            it.copy(converterValue = transform(it.converterValue), panelFocus = null)
        }
    }

    fun onConverterValueChange(value: String) {
        converterEdit { value }
    }

    /** Enter in the calculator is the `=` key: collapse to the result. */
    private fun calcEvaluate() {
        val state = _uiState.value
        val expression = state.calcExpression
        if (expression.isBlank()) return
        val result = runCatching {
            CalcEngine.format(
                CalcEngine.evaluate(expression, state.settings.calcDegrees),
                state.settings.calcPrecision,
            )
        }
        result.onSuccess { collapsed -> calcEdit { collapsed } }
    }

    // ---- plugins ----

    /** Cap on one plugin text box, so a paste cannot be unbounded. */
    private val PLUGIN_INPUT_MAX = 8 * 1024

    /**
     * The Lua runtime, created the first time the Plugins panel opens.
     *
     * Callbacks come back on the plugin thread, so every one of them is posted
     * to [serviceScope] before it touches state — the keyboard's UI is only ever
     * built on the main thread, and a plugin must never be able to change that.
     */
    private var pluginRuntime: PluginRuntime? = null

    private fun requirePluginRuntime(): PluginRuntime =
        pluginRuntime ?: PluginRuntime(
            store = PluginStore.get(this),
            listener = pluginListener,
            post = { body -> serviceScope.launch { body() } },
            onRemindersChanged = { PluginReminderAlarms.requestRearm(this) },
        ).also { pluginRuntime = it }

    private val pluginListener = object : PluginRuntime.Listener {
        override fun onUi(pluginId: String, ui: RenderedUi) {
            _uiState.update { state ->
                val running = state.plugins as? PluginPanelUi.Running ?: return@update state
                if (running.plugin.id != pluginId) return@update state
                // Buffers for boxes the plugin no longer draws are dropped, so a
                // renamed widget cannot leave typed text hanging around.
                val live = ui.inputIds()
                state.copy(
                    plugins = running.copy(ui = ui, error = null),
                    pluginInputs = state.pluginInputs.filterKeys { it in live },
                    pluginFocusedInput = state.pluginFocusedInput?.takeIf { it in live },
                )
            }
        }

        override fun onBusy(pluginId: String, busy: Boolean) {
            _uiState.update { state ->
                val running = state.plugins as? PluginPanelUi.Running ?: return@update state
                if (running.plugin.id != pluginId) state else state.copy(plugins = running.copy(busy = busy))
            }
        }

        override fun onError(pluginId: String, message: PluginText) {
            // The runtime has no Context, so it hands the reason over as a
            // resource id. The service is a Context, so it does the wording.
            val text = message.resolve(this@WMKeyboardService)
            _uiState.update { state ->
                val running = state.plugins as? PluginPanelUi.Running ?: return@update state
                if (running.plugin.id != pluginId) state else state.copy(plugins = running.copy(error = text))
            }
        }

        override fun onInputWrite(pluginId: String, inputId: String, text: String) {
            _uiState.update { it.copy(pluginInputs = it.pluginInputs + (inputId to text)) }
        }

        override fun onStopped(pluginId: String, message: PluginText, disabled: Boolean) {
            // Back to the list, with the reason. Anything the user was typing
            // into the stopped plugin goes with it.
            val text = message.resolve(this@WMKeyboardService)
            _uiState.update {
                it.copy(
                    plugins = PluginPanelUi.List(PluginStore.get(this@WMKeyboardService).plugins(), text),
                    pluginInputs = emptyMap(),
                    pluginFocusedInput = null,
                )
            }
        }
    }

    /** Shows the installed list. The panel's home screen. */
    private fun openPluginList() {
        pluginRuntime?.close()
        val store = PluginStore.get(this)
        store.reconcile()
        // The subsystem is off until the user asks for it, so the panel says so
        // rather than looking like an empty feature.
        // runnablePlugins, not plugins: a plugin switched off is one the user
        // asked not to see here, and the runtime refuses to open it anyway — so
        // listing it only offers a row that leads to "That plugin is turned off."
        val runnable = if (store.subsystemEnabled()) store.runnablePlugins() else emptyList()
        val notice = when {
            !store.subsystemEnabled() ->
                getString(R.string.ime_service_plugins_off_notice)
            // Otherwise the empty state would read "No plugins yet" at someone
            // who has several and switched them all off.
            runnable.isEmpty() && store.plugins().isNotEmpty() ->
                getString(R.string.ime_service_plugins_all_off_notice)
            else -> null
        }
        _uiState.update {
            it.copy(
                plugins = PluginPanelUi.List(
                    runnable,
                    notice,
                ),
                pluginInputs = emptyMap(),
                pluginFocusedInput = null,
            )
        }
    }

    /**
     * Leaves the running plugin for the installed list — the panel header's
     * back button one level in. Closing the runtime is [openPluginList]'s
     * job, so a plugin never keeps running behind the list.
     */
    fun onPluginBack() {
        vibrate()
        openPluginList()
    }

    /** Loads and runs a plugin, replacing whatever was open. */
    fun onPluginOpen(pluginId: String) {
        vibrate()
        val store = PluginStore.get(this)
        if (!store.subsystemEnabled()) return openPluginList()
        val plugin = store.plugin(pluginId) ?: return openPluginList()
        _uiState.update {
            it.copy(
                plugins = PluginPanelUi.Running(plugin),
                pluginInputs = emptyMap(),
                pluginFocusedInput = null,
            )
        }
        requirePluginRuntime().open(pluginId)
    }

    /** Hands a tap, toggle or tab change to the running script. */
    fun onPluginEvent(event: PluginEvent) {
        vibrate()
        pluginRuntime?.dispatch(event)
    }

    /**
     * Points the keys at one of the plugin's text boxes, or back at the field.
     *
     * The one switch that decides where what the user types goes, so it is
     * deliberately the only way [KeyboardUiState.pluginFocusedInput] is ever
     * set, and it refuses while anything but a plugin is on screen.
     */
    fun onPluginInputFocus(inputId: String?) {
        vibrate()
        _uiState.update { state ->
            if (inputId != null && state.plugins !is PluginPanelUi.Running) return@update state
            state.copy(pluginFocusedInput = inputId)
        }
    }

    /**
     * Puts the clipboard's text into one of the plugin's boxes.
     *
     * This is how a plugin gets text the user already had, and it is a host
     * action rather than an API: the user taps Paste, sees exactly what landed,
     * and the plugin is told the contents of its own box. Nothing here is
     * reachable from Lua.
     */
    fun onPluginPaste(inputId: String) {
        if (!isClipboardAccessible()) return
        vibrate()
        val clip = KeyboardClipboard.held ?: clipboardStore.latestText().orEmpty()
        if (clip.isEmpty()) return
        pluginInputSet(inputId, clip.take(PLUGIN_INPUT_MAX))
    }

    /** Copies a plugin's output to the clipboard. */
    fun onPluginCopy(text: String) {
        vibrate()
        if (text.isEmpty()) return
        KeyboardClipboard.copy(this, text)
    }

    /**
     * Ends any plugin session and takes the keys back.
     *
     * Called when the keyboard leaves the screen and when the focused field
     * changes. Both matter: a plugin input that stayed focused across either one
     * would send the user's next sentence to a script instead of to their app,
     * which is the single failure this whole design exists to prevent.
     */
    private fun stopPlugins() {
        pluginRuntime?.close()
        if (_uiState.value.pluginFocusedInput == null && _uiState.value.pluginInputs.isEmpty()) return
        _uiState.update { it.copy(pluginFocusedInput = null, pluginInputs = emptyMap()) }
    }

    private fun pluginInputEdit(transform: (String) -> String) {
        val id = _uiState.value.pluginFocusedInput ?: return
        val current = _uiState.value.pluginInputs[id].orEmpty()
        pluginInputSet(id, transform(current).take(PLUGIN_INPUT_MAX))
    }

    private fun pluginInputSet(id: String, text: String) {
        _uiState.update { it.copy(pluginInputs = it.pluginInputs + (id to text)) }
        pluginRuntime?.dispatch(PluginEvent.InputChanged(id, text))
    }

    // ---- typing speed test ----

    /**
     * Drives the elapsed clock and the once-a-second sampler while a run is
     * live. The panel renders [TypingTestUi.elapsedMs] rather than reading
     * the system clock itself, so a recomposition can never disagree with
     * the score.
     */
    private var typingTestJob: Job? = null

    /** Deals the prompt off the main thread; see [startTypingTest]. */
    private var typingPromptJob: Job? = null

    /** Identifies the latest deal, so a slow one cannot land on a newer run. */
    private var typingDealSeq = 0

    /** The debounced suggestion lookup for the word being typed. */
    private var typingSuggestJob: Job? = null

    /**
     * The last prompt pool built out of a dictionary, keyed by language id
     * and the dictionary state it was built from. One entry is enough: the
     * user runs tests in one language at a time, and a download or import
     * changes the token and so rebuilds it.
     */
    private var typingPoolCache: Triple<String, Int, TypingWordPool?>? = null

    /**
     * Deals a fresh prompt from the current settings and arms the run.
     *
     * The prompt is dealt in the language the keyboard is in — the user types
     * it on the keys on screen, so there is no other language it could be in.
     * English and Bengali ship their word lists; every other language builds
     * its pool out of its dictionary, which is a walk over a memory-mapped
     * trie and so happens off the main thread. The panel shows an empty
     * prompt for the beat that takes, and nothing typed in that beat counts.
     */
    private fun startTypingTest() {
        typingTestJob?.cancel()
        typingTestJob = null
        typingPromptJob?.cancel()
        typingSuggestJob?.cancel()
        val state = _uiState.value
        val language = state.language
        // A conversion layout (pinyin, kana) spells readings the prompt's
        // characters cannot be compared against keystroke by keystroke, so
        // the test stands down rather than scoring every key as a miss.
        val converts = state.composer.isConversion
        // Force shift off: the prompt is lowercase, and a field's auto-cap
        // would otherwise uppercase the first keystroke into a miss.
        _uiState.update {
            it.copy(
                typingTest = TypingTestUi(languageId = language.id, unavailable = converts),
                shiftState = ShiftState.OFF,
                shiftPressedByUser = false,
            )
        }
        if (converts) return
        val options = state.settings.typingTest
        val digits = resolveNumeralDigits(
            state.settings.layoutBehavior.numeralSystemFor(language.id),
            language,
        )
        val fullStop = state.script.fullStop
        val seq = ++typingDealSeq
        typingPromptJob = serviceScope.launch {
            val pool = withContext(Dispatchers.Default) { typingWordPool(language.id) }
            val words = pool?.let {
                buildTypingPrompt(
                    mode = options.mode,
                    duration = options.duration,
                    wordCount = options.wordCount,
                    punctuation = options.punctuation,
                    numbers = options.numbers,
                    pool = it,
                    digits = digits,
                    fullStop = fullStop,
                )
            }.orEmpty()
            if (seq != typingDealSeq) return@launch
            _uiState.update { s ->
                if (s.typingTest.result != null) {
                    s
                } else {
                    s.copy(typingTest = s.typingTest.copy(words = words, unavailable = words.isEmpty()))
                }
            }
            refreshTypingSuggestions()
        }
    }

    /**
     * The prompt material for [languageId]: the shipped list where there is
     * one, otherwise the most common words of the language's downloaded and
     * imported dictionaries — or null when there is nothing to deal from.
     * Runs off the main thread; the dictionary walk is the expensive part.
     */
    private fun typingWordPool(languageId: String): TypingWordPool? {
        TypingWordPools.bundled(languageId)?.let { return it }
        val token = loadedDictToken
        typingPoolCache?.let { (id, cachedToken, pool) ->
            if (id == languageId && cachedToken == token) return pool
        }
        val words = customDictionaries[languageId]
            ?.topWords(TypingWordPools.DICTIONARY_POOL_SIZE, accept = TypingWordPools::acceptsPromptWord)
            .orEmpty()
        val pool = if (words.size >= TypingWordPools.DICTIONARY_POOL_MIN) TypingWordPool(words) else null
        typingPoolCache = Triple(languageId, token, pool)
        return pool
    }

    /**
     * What the raw keystrokes of a test word read as on the current layout:
     * the composed text on a transliterating one (Avro spells Bengali out of
     * Latin keys), the keystrokes themselves everywhere else.
     */
    private fun typingComposed(state: KeyboardUiState, buffer: String): String =
        if (state.composer.isTransliterating) state.composer.composeBuffer(buffer) else buffer

    /** Cancels the clock; used when the panel closes mid-run. */
    private fun stopTypingTest() {
        typingTestJob?.cancel()
        typingTestJob = null
        typingPromptJob?.cancel()
        typingPromptJob = null
        typingSuggestJob?.cancel()
        typingSuggestJob = null
    }

    /**
     * Starts the clock on the first keystroke — not when the panel opens.
     * Otherwise the seconds spent reading the prompt would count against
     * the score.
     */
    private fun armTypingClock() {
        if (typingTestJob != null) return
        val startedAt = System.currentTimeMillis()
        _uiState.update { it.copy(typingTest = it.typingTest.copy(startedAtMs = startedAt)) }
        typingTestJob = serviceScope.launch {
            var nextSecond = 1
            while (isActive) {
                delay(100)
                val state = _uiState.value
                val test = state.typingTest
                if (state.panel != PanelMode.TYPING_TEST || test.result != null) return@launch
                val elapsed = System.currentTimeMillis() - startedAt
                val limit = state.settings.typingTest.duration * 1000L
                val timed = state.settings.typingTest.mode == TypingTestMode.TIME
                val capped = if (timed) elapsed.coerceAtMost(limit) else elapsed

                // One sample per whole second, catching up if a frame was
                // dropped, so the result graph never has holes in it.
                val samples = test.samples.toMutableList()
                while (capped >= nextSecond * 1000L) {
                    samples += typingSample(test, nextSecond)
                    nextSecond++
                }
                _uiState.update {
                    it.copy(typingTest = it.typingTest.copy(elapsedMs = capped, samples = samples))
                }
                if (timed && elapsed >= limit) {
                    finishTypingTest()
                    return@launch
                }
            }
        }
    }

    /**
     * A speed reading for the second that just ended: cumulative correct
     * characters over cumulative time. Cumulative rather than per-interval
     * because a one-second window is too short to be anything but noise.
     */
    private fun typingSample(test: TypingTestUi, second: Int): WpmSample {
        var correct = 0
        var typedWrong = 0
        var missed = 0
        for (word in test.typedWords) {
            for (state in compareWord(word.expected, word.typed, live = false)) {
                when (state) {
                    CharState.CORRECT -> correct++
                    CharState.WRONG, CharState.EXTRA -> typedWrong++
                    CharState.MISSING -> missed++
                    CharState.PENDING -> Unit
                }
            }
            if (word.typed == word.expected) correct++
        }
        val minutes = second / 60.0
        // Raw counts characters that ended up in the prompt, the same set
        // scoreTypingTest measures. Using the keystroke counter instead
        // would include corrected typing and leave the graph disagreeing
        // with the headline figure it sits under.
        val typed = correct + typedWrong
        return WpmSample(
            second = second,
            wpm = if (minutes > 0) (correct / 5.0) / minutes else 0.0,
            raw = if (minutes > 0) (typed / 5.0) / minutes else 0.0,
            errors = typedWrong + missed,
        )
    }

    /** One character key, scored against the letter the prompt expects. */
    private fun typingTestType(text: String) {
        if (text.isEmpty()) return
        // Nothing to type against yet: the prompt is still being dealt, or
        // the language has none. The keystroke is dropped rather than scored.
        if (_uiState.value.typingTest.words.isEmpty()) return
        armTypingClock()
        _uiState.update { state ->
            val test = state.typingTest
            val expected = test.words.getOrNull(test.wordIndex).orEmpty()
            val buffer = test.buffer + text
            val current = typingComposed(state, buffer)
            // Right first time only if it lands on the position it was typed
            // at; anything past the end of the word is an overshoot.
            //
            // A transliterating layout cannot be scored that way, and was:
            // one keystroke reshapes the letter before it (k then h is খ, not
            // কh; kkh is ক্ষ and neither of its first two keys spells any part
            // of it), so asking whether the composed text is already on course
            // marked the first key of every aspirate and every conjunct wrong.
            // On Bengali that is most of the word. The keys are held here and
            // judged in typingTestSpace, once the word they were building is
            // whole.
            val pending = state.composer.isTransliterating
            val hit = !pending && expected.getOrNull(test.current.length)?.toString() == text
            state.copy(
                typingTest = test.copy(
                    buffer = buffer,
                    current = current,
                    totalKeystrokes = test.totalKeystrokes + 1,
                    correctKeystrokes = test.correctKeystrokes + if (hit) 1 else 0,
                    pendingKeystrokes = if (pending) test.pendingKeystrokes + 1 else 0,
                ),
            )
        }
        refreshTypingSuggestions()
        finishIfPromptTyped()
    }

    /**
     * Word and quote runs finish on the last word without waiting for a
     * trailing space: once its final letter lands and the word matches,
     * there is nothing left to type. The closing space never counted for
     * the last word anyway (scoreTypingTest only credits it for earlier
     * words), so ending here costs the run nothing.
     */
    private fun finishIfPromptTyped() {
        val state = _uiState.value
        val test = state.typingTest
        if (state.settings.typingTest.mode != TypingTestMode.TIME &&
            test.wordIndex == test.words.lastIndex &&
            test.current == test.words.getOrNull(test.wordIndex)
        ) {
            finishTypingTest()
        }
    }

    /**
     * Backspace inside the current word. It deliberately does not walk back
     * into a finished word: reopening one would mean re-scoring keystrokes
     * already counted, and the accuracy figure is meant to remember the
     * mistakes rather than let them be edited away.
     *
     * Removes one keystroke, not one composed character: on Avro that is
     * how backspace behaves in a field too, and it is what lets খ go back
     * to ক rather than to nothing.
     */
    private fun typingTestBackspace() {
        _uiState.update { state ->
            val test = state.typingTest
            if (test.buffer.isEmpty()) {
                state
            } else {
                val buffer = test.buffer.dropLast(1)
                state.copy(
                    typingTest = test.copy(buffer = buffer, current = typingComposed(state, buffer)),
                )
            }
        }
        refreshTypingSuggestions()
    }

    /** Space closes the current word and moves the caret to the next one. */
    private fun typingTestSpace() {
        val state = _uiState.value
        val test = state.typingTest
        // Leading spaces would silently score an empty word as wrong.
        if (test.current.isEmpty()) return
        armTypingClock()

        val expected = test.words.getOrNull(test.wordIndex).orEmpty()
        // The space is a correct keystroke only when it closed a word that
        // was actually right — matching how scoreTypingTest credits it.
        // Comparing lengths instead would score "teh" for "the" as a hit.
        val hit = test.current == expected
        // A transliterating layout's keys were held rather than scored as
        // they landed; the word is whole now, so they settle here.
        val settled = settledKeystrokes(
            expected = expected,
            composed = test.current,
            standing = test.buffer.length.coerceAtMost(test.pendingKeystrokes),
        )
        val typedWords = test.typedWords + TypedWord(expected, test.current)
        _uiState.update {
            it.copy(
                typingTest = it.typingTest.copy(
                    typedWords = typedWords,
                    current = "",
                    buffer = "",
                    pendingKeystrokes = 0,
                    totalKeystrokes = it.typingTest.totalKeystrokes + 1,
                    correctKeystrokes = it.typingTest.correctKeystrokes + settled +
                        if (hit) 1 else 0,
                ),
            )
        }
        // Word and quote runs end on the last word rather than on a clock.
        if (state.settings.typingTest.mode != TypingTestMode.TIME &&
            typedWords.size >= test.words.size
        ) {
            finishTypingTest()
        } else {
            refreshTypingSuggestions()
        }
    }

    /**
     * A whole word landing at once — a glide, or a suggestion chip — and the
     * space that follows it, the same as the gesture or the chip would give
     * a field. Scored as [keystrokes] presses (one per letter for a glide,
     * one tap for a chip), credited in proportion to how many of the word's
     * letters match the prompt's, so a glide that decoded to the wrong word
     * costs what mistyping it would have.
     *
     * A half-tapped word is closed first, which is what happens in a field
     * too: the glide's leading space ends whatever was being typed.
     */
    private fun typingTestWholeWord(word: String, keystrokes: Int) {
        if (word.isEmpty() || keystrokes <= 0) return
        if (_uiState.value.typingTest.words.isEmpty()) return
        if (_uiState.value.typingTest.current.isNotEmpty()) typingTestSpace()
        if (!_uiState.value.typingTestActive) return
        armTypingClock()
        _uiState.update { state ->
            val test = state.typingTest
            val expected = test.words.getOrNull(test.wordIndex).orEmpty()
            val matched = word.indices.count { expected.getOrNull(it) == word[it] }
            val hits = keystrokes * matched / word.length
            state.copy(
                typingTest = test.copy(
                    buffer = word,
                    current = word,
                    totalKeystrokes = test.totalKeystrokes + keystrokes,
                    correctKeystrokes = test.correctKeystrokes + hits,
                ),
            )
        }
        typingTestSpace()
    }

    /**
     * A glide drawn during a run, when the test's glide option is on. Decoded
     * exactly as a field glide is — same engine, same word list — and then
     * typed into the test as a whole word. A multi-word stroke lands one
     * word per segment. [verdict] is the ambiguity picker's answer for the
     * last segment; a cancel types nothing.
     */
    private fun typingTestGlide(
        segments: List<List<GesturePoint>>,
        keys: List<KeyCenter>,
        keyWidthPx: Float,
        verdict: GlideVerdict,
    ) {
        // Retires every preview from this stroke, in flight or queued.
        gestureGeneration.incrementAndGet()
        gestureJob?.cancel()
        clearGlidePreview()
        if (verdict is GlideVerdict.Cancel) return
        val chosen = (verdict as? GlideVerdict.Word)?.word
        gestureJob = serviceScope.launch {
            for ((index, segment) in segments.withIndex()) {
                val candidates = withContext(Dispatchers.Default) {
                    glideDecode(segment, keys, keyWidthPx, guessAhead = index == segments.lastIndex)
                }.words
                val picked = chosen?.takeIf { index == segments.lastIndex }
                if (candidates.isEmpty() && picked == null) continue
                val word = picked ?: candidates.first()
                typingTestWholeWord(word, keystrokes = word.length)
            }
        }
    }

    /**
     * Refreshes the test's own suggestion row for the word being typed, or
     * the next-word predictions between words. The same engine and the same
     * lookup the strip uses, so the test measures the real thing; only the
     * destination differs, because the strip belongs to the field and this
     * word must never reach it.
     */
    private fun refreshTypingSuggestions() {
        val state = _uiState.value
        val test = state.typingTest
        typingSuggestJob?.cancel()
        if (!state.typingTestActive || !state.settings.typingTest.suggestions || test.words.isEmpty()) {
            if (test.suggestions.isNotEmpty()) {
                _uiState.update { it.copy(typingTest = it.typingTest.copy(suggestions = emptyList())) }
            }
            return
        }
        val engine = suggestionEngine ?: return
        val phonetic = state.composer.phoneticLanguage
        val avro = phonetic != null
        // The engine takes the romanised keystrokes on Avro and the word
        // itself everywhere else — the same split the field path makes.
        val typed = if (avro) test.buffer else test.current
        val previous = test.typedWords.lastOrNull()?.typed
        val previous2 = test.typedWords.getOrNull(test.typedWords.size - 2)?.typed
        val wordIndex = test.wordIndex
        val buffer = test.buffer
        val suggestionSlots = state.settings.suggestionStrip.slotCount
            .coerceAtLeast(TYPING_TEST_SUGGESTION_SLOTS)
        typingSuggestJob = serviceScope.launch {
            delay(TYPING_TEST_SUGGEST_DEBOUNCE_MS)
            // The typing test's row is the field path's pile-up in miniature —
            // a pass per keystroke, cancelled but unstoppable — so it shares
            // the one thread the field path runs on (#313).
            val words = withContext(suggestionDispatcher) {
                engine.suggest(
                    composing = typed,
                    previousWord = previous,
                    phoneticLanguage = phonetic,
                    limit = suggestionSlots,
                    previousWord2 = previous2,
                )
            }
            _uiState.update { s ->
                val now = s.typingTest
                // Only for the word it was asked about.
                if (now.wordIndex != wordIndex || now.buffer != buffer || now.result != null) {
                    s
                } else {
                    s.copy(typingTest = now.copy(suggestions = words))
                }
            }
        }
    }

    /**
     * Scores the run, stores the result, and files it against the personal
     * bests. A run with no keystrokes is thrown away instead of recorded —
     * an accidental panel open should not land a zero in the history.
     */
    private fun finishTypingTest() {
        typingTestJob?.cancel()
        typingTestJob = null
        typingSuggestJob?.cancel()
        val state = _uiState.value
        val test = state.typingTest
        if (test.result != null) return

        // Whatever is half-typed still counts; the clock stopped mid-word.
        val unfinished = test.words.getOrNull(test.wordIndex).orEmpty()
        val words = if (test.current.isEmpty()) {
            test.typedWords
        } else {
            test.typedWords + TypedWord(unfinished, test.current)
        }
        // …and so do the keystrokes a transliterating layout was still
        // holding for it: without this an Avro run that ran out the clock
        // mid-word threw that word's keys away as misses.
        val correctKeystrokes = test.correctKeystrokes + settledKeystrokes(
            expected = unfinished,
            composed = test.current,
            standing = test.buffer.length.coerceAtMost(test.pendingKeystrokes),
        )
        val elapsed = test.startedAtMs?.let { test.elapsedMs.coerceAtLeast(1) } ?: 0L
        if (words.isEmpty() || elapsed <= 0) {
            _uiState.update { it.copy(panel = PanelMode.NONE, typingTest = TypingTestUi()) }
            return
        }

        val options = state.settings.typingTest
        val configKey = typingConfigKey(
            options.mode, options.duration, options.wordCount, test.languageId,
        )
        val result = scoreTypingTest(
            words = words,
            elapsedMs = elapsed,
            totalKeystrokes = test.totalKeystrokes,
            correctKeystrokes = correctKeystrokes,
            samples = test.samples,
            mode = options.mode,
            configKey = configKey,
        )
        val improved = TypingBests.improve(options.bests, configKey, result.wpm)
        // Badges the run earns; only the never-before-seen ones get the "New"
        // accent on the results screen. The prompt text decides the pangram.
        val earned = TypingAchievements.evaluate(
            result,
            testsCompleted = options.completed + 1,
            isPangram = TypingAchievements.isPangram(test.words.joinToString(" ")),
        )
        val newBadges = earned - TypingAchievements.decode(options.achievements)
        _uiState.update {
            it.copy(
                typingTest = it.typingTest.copy(
                    result = result,
                    personalBest = improved != null,
                    earnedAchievements = newBadges,
                    suggestions = emptyList(),
                ),
            )
        }
        serviceScope.launch {
            settingsRepository.recordTypingResult(
                history = TypingHistory.append(options.history, result.wpm),
                bests = improved?.let { TypingBests.encode(it) },
                achievements = earned,
            )
        }
    }

    /** Panel controls. Everything here persists — the panel is the settings. */
    fun onTypingTestAction(action: TypingTestAction) {
        vibrate()
        when (action) {
            TypingTestAction.Restart -> {
                startTypingTest()
                return
            }
            TypingTestAction.InsertResult -> {
                val result = _uiState.value.typingTest.result ?: return
                onToolTextInsert(typingResultText(result))
                // Closing the panel puts the user back in the field they
                // just wrote the score into.
                onPanelChange(PanelMode.TYPING_TEST)
                return
            }
            is TypingTestAction.Suggestion -> {
                typingTestWholeWord(action.word, keystrokes = 1)
                return
            }
            is TypingTestAction.Language -> {
                // The layout switch re-deals the prompt itself (see
                // onLayoutSelected): the test follows the keyboard's
                // language, and this is the same switch the spacebar makes.
                onLayoutSelected(action.layoutId)
                return
            }
            else -> Unit
        }
        // A settings change invalidates the prompt in front of the user, so
        // persist first and re-deal from the saved value rather than racing
        // the settings flow back into the panel.
        serviceScope.launch {
            when (action) {
                is TypingTestAction.Mode -> settingsRepository.setTypingTestMode(action.value)
                is TypingTestAction.Duration -> settingsRepository.setTypingTestDuration(action.seconds)
                is TypingTestAction.WordCount -> settingsRepository.setTypingTestWordCount(action.value)
                is TypingTestAction.Punctuation -> settingsRepository.setTypingTestPunctuation(action.on)
                is TypingTestAction.Numbers -> settingsRepository.setTypingTestNumbers(action.on)
                is TypingTestAction.Glide -> settingsRepository.setTypingTestGlide(action.on)
                is TypingTestAction.Suggestions -> settingsRepository.setTypingTestSuggestions(action.on)
                else -> return@launch
            }
            // settingsRepository.settings has already pushed the new value
            // into _uiState by the time the edit completes.
            settingsRepository.settings.first()
            startTypingTest()
        }
    }

    /** The shareable one-liner the "Insert" chip writes into the field. */
    private fun typingResultText(result: TypingResult): String {
        val state = _uiState.value
        val options = state.settings.typingTest
        var config = typingConfigLabel(this, result.mode, options.duration, options.wordCount)
        // English is the test's home language and goes unnamed, as in the
        // personal-best keys; any other language is part of the score.
        val languageId = state.typingTest.languageId
        if (languageId != "en") {
            config = getString(
                R.string.ime_service_typing_config_language,
                config,
                LanguageRegistry.byId(languageId).displayName,
            )
        }
        return getString(
            R.string.ime_service_typing_result_text,
            result.wpm.roundToInt(),
            result.accuracy.roundToInt(),
            config,
        )
    }

    // ---- AI tool ----

    private var aiJob: Job? = null

    /**
     * Identifies the latest [runAi] call. On-device streaming callbacks
     * arrive from a blocking native call that outlives job cancellation, so
     * stale runs must be ignored rather than relied on to stop.
     */
    private var aiRunSeq = 0

    /**
     * Where an AI action's MCP call waits while the panel asks the user to
     * allow it (#573). The chat has its own, in `AiChatController`.
     */
    private val aiToolGate = AiToolApprovalGate()

    /**
     * The last instruction each ask-each-run action was given, so reopening its
     * input box starts from what the user typed last time.
     *
     * Only a prefill. What a run *used* rides on the [AiUi] state itself, which
     * is what makes a retry rebuild the right prompt: holding it here as well
     * used to mean that running any action after a Custom generate left the
     * generate flag set, and retrying then rebuilt the wrong prompt entirely.
     */
    private val aiLastInstruction = mutableMapOf<String, String>()

    /**
     * The on-device model to run: the explicit selection, or — when nothing
     * (valid) is selected — the only model on disk. So the first download
     * just works without a selection step, and a deleted selection heals
     * itself while a sole alternative exists.
     */
    private fun effectiveLocalModelId(settings: KeyboardSettings): String? =
        settings.ai.localModelId
            .takeIf { LocalLlmStore.selectedModelFile(filesDir, it) != null }
            ?: LocalLlmStore.soleDownloadedId(filesDir)

    private fun effectiveLocalModelFile(settings: KeyboardSettings): java.io.File? =
        effectiveLocalModelId(settings)?.let { LocalLlmStore.selectedModelFile(filesDir, it) }

    /**
     * Whether the model streams Qwen3-style implicit reasoning (no opening
     * tag, just bare thought ending in `</think>`). Catalog models declare
     * it; imported files fall back to a name sniff.
     */
    private fun isReasoningModel(modelId: String?): Boolean {
        if (modelId == null) return false
        LocalLlmCatalog.byId(modelId)?.let { return it.reasoning }
        val name = modelId.removePrefix(LocalLlmStore.CUSTOM_PREFIX).lowercase()
        return "qwen3" in name || "deepseek" in name
    }

    /**
     * Is there anything for an AI action to run on — a selection, or any text
     * in the field? Drives [KeyboardUiState.aiHasText], which greys out the
     * action chips; an action on an empty field has nothing to rewrite and
     * would only make the model invent something.
     */
    private fun aiFieldHasText(): Boolean {
        // Never out of a password field: the action chips stay greyed out
        // however the editor answers. Same rule the chat attachment follows
        // (see [aiChatAttachmentFromField]).
        if (_uiState.value.secureField) return false
        val ic = currentInputConnection ?: return false
        if (!ic.getSelectedText(0).isNullOrBlank()) return true
        return extractFieldText().isNotBlank()
    }

    /**
     * Re-reads the field for [KeyboardUiState.aiHasText]. Called when the AI
     * panel opens and on every cursor/text change while it is open — typing
     * the first character has to enable the chips without a panel reopen.
     */
    private fun refreshAiHasText() {
        val hasText = aiFieldHasText()
        _uiState.update { if (it.aiHasText == hasText) it else it.copy(aiHasText = hasText) }
    }

    /**
     * Whether the AI actions have an on-device model to fall back on when the
     * server they are set to cannot be reached (#452): the user asked for it,
     * the provider is a server, and a local model is downloaded.
     */
    private fun aiOfflineStandIn(settings: KeyboardSettings): Boolean =
        settings.dataSaver.offlineFallback && BuildConfig.ENABLE_LOCAL_LLM &&
            settings.ai.provider != AiProvider.ON_DEVICE && effectiveLocalModelFile(settings) != null

    /** What the AI panel should show before any action runs. */
    private fun aiInitialState(settings: KeyboardSettings): AiUi = when {
        settings.ai.provider == AiProvider.ON_DEVICE && BuildConfig.ENABLE_LOCAL_LLM &&
            effectiveLocalModelFile(settings) == null -> AiUi.NeedModel
        settings.ai.provider == AiProvider.ON_DEVICE && !BuildConfig.ENABLE_LOCAL_LLM ->
            AiUi.NeedSetup
        !AiClient.isConfigured(settings.ai) -> AiUi.NeedSetup
        else -> AiUi.Idle
    }

    /**
     * Model-picker row on the AI panel: switch to another row of the AI list.
     * [pick] is the downloaded model for [AiProvider.ON_DEVICE], else the
     * row's key.
     */
    fun onAiPickModel(provider: AiProvider, pick: String?) {
        vibrate()
        val onDevice = provider == AiProvider.ON_DEVICE
        val localModelId = pick.takeIf { onDevice }
        val rowKey = if (onDevice) ProviderTypes.ON_DEVICE_AI.id else pick ?: AiProviders.type(provider).id
        serviceScope.launch {
            if (localModelId != null) settingsRepository.setAiLocalModelId(localModelId)
            settingsRepository.setAiProviderKey(rowKey, provider)
            // Re-derive the panel state for the new choice; the settings flow
            // update races this tap, so compute from the edited values.
            val current = _uiState.value.settings
            val row = current.aiRows().firstOrNull { it.key == rowKey }
            val picked = row?.let { current.ai.through(it) } ?: current.ai.copy(provider = provider)
            val updated = current.copy(
                ai = picked.copy(localModelId = localModelId ?: current.ai.localModelId),
            )
            _uiState.update {
                it.copy(
                    ai = aiInitialState(updated),
                    // The reply panel's Picture chip follows the model: a
                    // switch to one without eyes takes it away (#234).
                    aiReply = it.aiReply.copy(canSendPicture = replyCanSendPicture(updated)),
                )
            }
        }
    }

    /**
     * The text an action runs on.
     *
     * A selection always wins, whatever the action's input mode says: the user
     * has pointed at exactly what they mean. Only with no selection does the
     * mode decide, and "carry this on" then reads what is *before* the cursor,
     * because the words after it are not part of what came before.
     */
    /** How long a weather reading counts as fresh, from the user's setting. */
    private fun weatherCacheMs(): Long =
        _uiState.value.settings.toolLimits.weatherRefreshMinutes * 60_000L

    /** What an action runs on, and whether that was the selection rather than the field. */
    private class AiInput(val text: String, val fromSelection: Boolean)

    private fun aiInputText(spec: AiActionSpec): AiInput {
        val ic = currentInputConnection ?: return AiInput("", fromSelection = false)
        ic.getSelectedText(0)?.toString()?.takeIf { it.isNotBlank() }?.let { return AiInput(it, fromSelection = true) }
        val text = if (spec.inputMode == AiInputMode.BEFORE_CURSOR) {
            ic.getTextBeforeCursor(_uiState.value.settings.ai.beforeCursorChars, 0)
                ?.toString().orEmpty()
        } else {
            extractFieldText()
        }
        return AiInput(text, fromSelection = false)
    }

    /**
     * One of the selection bar's AI buttons: [actionId] run on the selection
     * at once, with the result landing in the AI panel ready to apply. The
     * panel opens first, so a provider that is not set up shows its own
     * screen instead of a silent nothing.
     */
    fun onSelectionAiAction(actionId: String) {
        val offer = _uiState.value.selectionMacros ?: return
        val spec = offer.aiDirect.firstOrNull { it.id == actionId } ?: return
        vibrate()
        if (_uiState.value.panel != PanelMode.AI) onPanelChange(PanelMode.AI, haptic = false)
        if (_uiState.value.panel != PanelMode.AI || _uiState.value.ai !is AiUi.Idle) return
        currentInputConnection?.let { commitComposing(it, autocorrect = false) }
        runAi(spec, offer.text, fromSelection = true)
    }

    fun onAiAction(spec: AiActionSpec) {
        vibrate()
        val initial = aiInitialState(_uiState.value.settings)
        if (initial is AiUi.NeedModel || initial is AiUi.NeedSetup) {
            _uiState.update { it.copy(ai = initial) }
            return
        }
        // No stored prompt: open the input box and let the key rows compose the
        // instruction; the run happens on Enter or the Run chip.
        if (spec.askEachRun) {
            val opening = aiInitialInstruction(
                spec,
                lastInstruction = aiLastInstruction[spec.id].orEmpty(),
                translateTo = _uiState.value.settings.ai.translateTo,
            )
            _uiState.update { it.copy(ai = AiUi.CustomInput(spec, opening)) }
            return
        }
        currentInputConnection?.let { commitComposing(it, autocorrect = false) }
        val input = aiInputText(spec)
        val source = input.text.trim()
        if (source.isNotEmpty()) {
            runAi(spec, source, fromSelection = input.fromSelection)
            return
        }
        if (!spec.worksWithoutText) {
            // Backstop for the chips being disabled: an empty field gives the
            // model nothing to work from, so it would invent text rather than
            // rewrite any. Never send the request.
            refreshAiHasText()
            _uiState.update {
                it.copy(ai = AiUi.Error(spec, getString(R.string.ime_ai_error_no_text)))
            }
            return
        }
        // An action that works on nothing writes from its own task instead. The
        // task becomes the user message, because several providers reject an
        // empty user turn outright.
        val task = AiPrompts.resolvedTask(spec, _uiState.value.settings.ai.translateTo).trim()
        if (task.isEmpty()) {
            _uiState.update {
                it.copy(ai = AiUi.Error(spec, getString(R.string.ime_ai_error_no_text)))
            }
            return
        }
        runAi(spec, task, generated = true)
    }

    /** Backspace/character edits to the typed-instruction buffer. */
    private fun aiCustomInputEdit(transform: (String) -> String) {
        val ai = _uiState.value.ai as? AiUi.CustomInput ?: return
        _uiState.update { it.copy(ai = AiUi.CustomInput(ai.action, transform(ai.instruction))) }
    }

    // ---- AI reply (#234) ----
    //
    // The tool that answers somebody else's message. Everything above in the AI
    // section works on text the user wrote and the keyboard can read; this one
    // works on text the keyboard cannot reach at all — it is in the app above,
    // in a bubble nothing can select. So the first half of this section is
    // about getting the other person's words in (a clip, a screenshot, the
    // panel's own box), and only the second half is about asking a model.
    //
    // The run itself reuses [AiUi]: Loading, Error and the phase readout are
    // the AI tool's, because only one panel is open at a time and a second copy
    // of them would be a second thing to keep right.

    /** The style one run is written to, from the settings and what can run it. */
    private fun replyStyle(settings: KeyboardSettings, onDevice: Boolean): ReplyStyle {
        val reply = settings.ai.reply
        return ReplyStyle(
            // A small on-device model asked for three variants writes one
            // three times, and loses the one-per-line format doing it. Ask it
            // for the one it can actually give — unless it is one of the
            // recommended models, which keep the format, and whose drafts now
            // arrive one at a time rather than after the whole answer.
            count = if (onDevice && !strongLocalModel(settings)) 1 else reply.count,
            length = reply.length,
            emoji = reply.emoji,
            persona = reply.persona,
            language = reply.language,
        )
    }

    /** A catalog model ranked Recommended: big enough to write several drafts in one go. */
    private fun strongLocalModel(settings: KeyboardSettings): Boolean =
        effectiveLocalModelId(settings)?.let { LocalLlmCatalog.byId(it) }?.tier == ModelTier.RECOMMENDED

    /**
     * The on-device model whose engine refused a picture this session (#234).
     * Its screenshots go straight to the on-device reader from then on, rather
     * than each one paying for a failed attempt first.
     */
    private var replyVisionRefusedModel: String? = null

    /**
     * Whether a screenshot can go to the model as a picture.
     *
     * Cloud: the provider's own word ([AiClient.supportsImages]). On the
     * device: a model the catalog says has eyes, or an imported one nobody
     * has told us about yet — the engine answers that cleanly by trying, and
     * [readShotsInstead] picks up the pieces if it cannot.
     */
    private fun replyCanSendPicture(settings: KeyboardSettings): Boolean {
        if (settings.ai.provider != AiProvider.ON_DEVICE) return AiClient.supportsImages(settings.ai.provider)
        if (!BuildConfig.ENABLE_LOCAL_LLM) return false
        val id = effectiveLocalModelId(settings) ?: return false
        if (id == replyVisionRefusedModel) return false
        return LocalLlmCatalog.canSee(id) != false
    }

    /**
     * The reply the user had already begun in the field, as the drafts' brief:
     * "cant fri, busy" becomes three polished ways of saying exactly that.
     * Blank in a password field and in an empty one.
     */
    private fun replyDraftFromField(): String {
        if (_uiState.value.secureField) return ""
        return extractFieldText().trim().take(AiPrompts.MAX_DRAFT)
    }

    /** Opens the reply panel: the run state reset, the tidy-up switch seeded. */
    private fun prepareAiReply() {
        // The half-typed word is part of the draft the run reads as its brief.
        currentInputConnection?.let { commitComposing(it, autocorrect = false) }
        replyOpenedAtSec = System.currentTimeMillis() / 1000
        // Screenshots are caught while this panel is open whatever the
        // clipboard's own screenshot setting says.
        refreshScreenshotObserver()
        val draft = replyDraftFromField()
        val settings = _uiState.value.settings
        val initial = aiInitialState(settings)
        _uiState.update {
            it.copy(
                ai = if (it.ai is AiUi.Loading) it.ai else initial,
                aiReply = it.aiReply.copy(
                    tidyUp = settings.ai.reply.tidyUp,
                    candidates = emptyList(),
                    picking = false,
                    typing = false,
                    notice = null,
                    draft = draft,
                    canSendPicture = replyCanSendPicture(settings),
                    editing = null,
                    askTone = null,
                ),
            )
        }
        addRecentClipsForReply()
        if (settings.ai.reply.catchScreenshots && canReadImages()) {
            serviceScope.launch {
                val shot = withContext(Dispatchers.IO) {
                    ReplyShots.newest(this@WMKeyboardService, REPLY_RECENT_WINDOW_SEC)
                } ?: return@launch
                if (_uiState.value.panel != PanelMode.AI_REPLY) return@launch
                addReplyShot(shot.uri.toString(), null, boardTopAt(shot.addedAt))
            }
        }
    }

    /**
     * What was copied in the last couple of minutes, added as the panel opens
     * (#234): the usual order is copy their message, then open the tool, and
     * a copy made just before opening is the message to answer. From the
     * clipboard history when it is on, oldest first; otherwise the one copy
     * the keyboard saw last, which it notes whether or not history is kept.
     */
    private fun addRecentClipsForReply() {
        if (_uiState.value.secureField) return
        val cutoff = System.currentTimeMillis() - REPLY_RECENT_WINDOW_SEC * 1000
        val settings = _uiState.value.settings
        if (settings.clipboard.history && isClipboardAccessible()) {
            clipboardStore.items()
                .filter { it.kind.isTextual && !it.sensitive && it.timestamp >= cutoff && it.text.isNotBlank() }
                .sortedBy { it.timestamp }
                .forEach { item ->
                    addReplyEntry(ReplyEntry(text = item.text.trim(), source = ReplySource.CLIPBOARD, clipId = item.id))
                }
            return
        }
        val copied = lastCopiedText ?: return
        if (lastCopiedAt >= cutoff) addReplyEntry(ReplyEntry(text = copied, source = ReplySource.CLIPBOARD))
    }

    /**
     * The last text the keyboard saw copied, and when (#234). Kept whatever
     * the clipboard history setting says, in memory only, so the reply tool
     * can pick up "the message I just copied" for someone who keeps no
     * history at all.
     */
    private var lastCopiedText: String? = null
    private var lastCopiedAt = 0L

    /**
     * Adds one message to the conversation being replied to.
     *
     * Appended, never replacing: the whole gathering flow is "copy, add, copy,
     * add", and the order they arrive in is the order they were said in.
     */
    private fun addReplyEntry(entry: ReplyEntry) {
        if (entry.text.isBlank() && !entry.image) return
        _uiState.update {
            val existing = it.aiReply.entries
            // The same clip added twice — the user pressed the button after it
            // had already arrived on its own — is one message, not two.
            if (entry.clipId != 0L && existing.any { e -> e.clipId == entry.clipId }) return@update it
            if (entry.shotUri != null && existing.any { e -> e.shotUri == entry.shotUri }) return@update it
            // A copy seen twice — live, and again from the history when the
            // panel opens — is one message.
            if (entry.source == ReplySource.CLIPBOARD &&
                existing.any { e -> e.source == ReplySource.CLIPBOARD && e.text == entry.text }
            ) {
                return@update it
            }
            val marked = if (entry.image) entry else entry.copy(unclear = replyLooksUnclear(entry.text))
            it.copy(
                aiReply = it.aiReply.copy(
                    entries = (existing + marked).takeLast(MAX_REPLY_ENTRIES),
                    notice = null,
                    // A new message makes the drafts on screen answers to a
                    // conversation that has moved on.
                    candidates = emptyList(),
                ),
            )
        }
    }

    /**
     * Every copy, for the reply tool (#234), before the clipboard history's
     * own gates: remembered as "the last thing copied" for the panel to pick
     * up when it opens, and handed straight to an open panel when the history
     * will not hand it over itself (history off, or paused) — copying their
     * message while the panel is open must work for somebody who keeps no
     * clipboard history. Secrets are skipped by the same tests the history
     * uses.
     */
    private fun noteCopyForReply(state: KeyboardUiState) {
        if (!isClipboardAccessible()) return
        val clip = runCatching {
            (getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager).primaryClip
        }.getOrNull() ?: return
        if (clipMarkedSensitive(clip)) return
        val text = clip.getItemAt(0)?.text?.toString()?.trim().orEmpty()
        if (text.isEmpty() || ClipSensitivity.looksSensitive(text)) return
        lastCopiedText = text.take(MAX_REPLY_CHARS)
        lastCopiedAt = System.currentTimeMillis()
        val historyHandsItOver = state.settings.clipboard.history && !clipCapturePaused(state)
        if (!historyHandsItOver && state.panel == PanelMode.AI_REPLY && !state.secureField) {
            addReplyEntry(ReplyEntry(text = text.take(MAX_REPLY_CHARS), source = ReplySource.CLIPBOARD))
        }
    }

    /** No word the keyboard knows in [text]; see [ReplyText.looksUnclear]. */
    private fun replyLooksUnclear(text: String): Boolean = ReplyText.looksUnclear(text, ::isKnownWord)

    /** The red-marked messages, all at once. */
    fun onReplyRemoveUnclear() {
        vibrate()
        _uiState.update {
            it.copy(
                aiReply = it.aiReply.copy(
                    entries = it.aiReply.entries.filterNot { e -> e.unclear },
                    candidates = emptyList(),
                    editing = null,
                ),
            )
        }
    }

    /** Opens message [index] in the message box, to fix what OCR or a copy got wrong. */
    fun onReplyEdit(index: Int) {
        vibrate()
        _uiState.update {
            val entry = it.aiReply.entries.getOrNull(index) ?: return@update it
            if (entry.image) return@update it
            it.copy(aiReply = it.aiReply.copy(typing = true, typed = entry.text, editing = index, askTone = null))
        }
    }

    /**
     * A clip copied while the reply panel is open joins the conversation on its
     * own (#234).
     *
     * This is what "add several messages one after another" actually is: the
     * user long-presses each bubble in the chat app, copies it, and it lands
     * here. Asking them to come back to the keyboard and press Add between each
     * one would be the same number of taps as typing the message out.
     */
    private fun noteClipForReply(item: com.wasimaster.wmkeyboard.core.clipboard.ClipItem) {
        val state = _uiState.value
        if (state.panel != PanelMode.AI_REPLY) return
        if (!item.kind.isTextual || item.sensitive) return
        addReplyEntry(
            ReplyEntry(
                text = item.text.trim(),
                source = ReplySource.CLIPBOARD,
                clipId = item.id,
            ),
        )
    }

    /** The Paste button: the newest clip, for a message copied before the panel opened. */
    fun onReplyAddClip() {
        vibrate()
        val item = clipboardStore.items().firstOrNull { it.kind.isTextual && !it.sensitive }
        if (item == null || item.text.isBlank()) {
            replyNotice(R.string.ime_reply_notice_no_clip)
            return
        }
        addReplyEntry(ReplyEntry(text = item.text.trim(), source = ReplySource.CLIPBOARD, clipId = item.id))
    }

    /**
     * The selection in the field, for the apps where the conversation is
     * selectable. Rare, and free when it works.
     */
    fun onReplyAddSelection() {
        vibrate()
        val selected = currentInputConnection?.getSelectedText(0)?.toString()?.trim()
        if (selected.isNullOrBlank()) {
            replyNotice(R.string.ime_reply_notice_no_selection)
            return
        }
        addReplyEntry(ReplyEntry(text = selected, source = ReplySource.SELECTION))
    }

    /** Keystrokes into the panel's own message box. */
    private fun aiReplyTyped(text: String) {
        _uiState.update { it.copy(aiReply = it.aiReply.copy(typed = text.take(MAX_REPLY_CHARS))) }
    }

    /** The box takes the keys, or gives them back. */
    fun onReplyTypeFocus(on: Boolean) {
        vibrate()
        _uiState.update {
            // Closing the box drops an edit or a pending instruction with it:
            // the box opened for one of those, and a later open is for a new
            // message.
            if (on) it.copy(aiReply = it.aiReply.copy(typing = true))
            else it.copy(aiReply = it.aiReply.copy(typing = false, editing = null, askTone = null, typed = ""))
        }
    }

    /** Enter, and the box's own Add button: what is typed becomes a message. */
    fun onReplyTypedDone() {
        val reply = _uiState.value.aiReply
        val typed = reply.typed.trim()
        // The box was the instruction for a tone that asks each run.
        reply.askTone?.let { tone ->
            if (typed.isEmpty()) return
            _uiState.update { it.copy(aiReply = it.aiReply.copy(typing = false, typed = "", askTone = null)) }
            runAiReply(tone, instruction = typed)
            return
        }
        // The box was editing a message: replace it, or drop it when emptied.
        reply.editing?.let { index ->
            _uiState.update {
                val entries = it.aiReply.entries
                val updated = when {
                    index !in entries.indices -> entries
                    typed.isEmpty() -> entries.filterIndexed { i, _ -> i != index }
                    else -> entries.toMutableList().also { list ->
                        list[index] = list[index].copy(text = typed, unclear = replyLooksUnclear(typed))
                    }
                }
                it.copy(
                    aiReply = it.aiReply.copy(
                        entries = updated,
                        typing = false,
                        typed = "",
                        editing = null,
                        candidates = emptyList(),
                    ),
                )
            }
            return
        }
        if (typed.isEmpty()) {
            _uiState.update { it.copy(aiReply = it.aiReply.copy(typing = false)) }
            return
        }
        addReplyEntry(ReplyEntry(text = typed, source = ReplySource.TYPED))
        // Cleared rather than kept: the next message is a different one, and
        // this is the gather-several flow.
        _uiState.update { it.copy(aiReply = it.aiReply.copy(typed = "")) }
    }

    /** Flips one message between "they said it" and "I said it". */
    fun onReplyToggleSide(index: Int) {
        vibrate()
        _uiState.update {
            val entries = it.aiReply.entries
            if (index !in entries.indices) return@update it
            val updated = entries.toMutableList()
            updated[index] = updated[index].copy(fromMe = !updated[index].fromMe)
            it.copy(aiReply = it.aiReply.copy(entries = updated, candidates = emptyList()))
        }
    }

    /** Takes one message back out of the conversation. */
    fun onReplyRemove(index: Int) {
        vibrate()
        _uiState.update {
            val entries = it.aiReply.entries
            if (index !in entries.indices) return@update it
            it.copy(
                aiReply = it.aiReply.copy(
                    entries = entries.filterIndexed { i, _ -> i != index },
                    candidates = emptyList(),
                ),
            )
        }
    }

    /** Starts over, without touching what the tidy-up would have removed. */
    fun onReplyClear() {
        vibrate()
        _uiState.update {
            it.copy(
                ai = aiInitialState(it.settings),
                aiReply = it.aiReply.copy(
                    entries = emptyList(),
                    candidates = emptyList(),
                    typed = "",
                    typing = false,
                    notice = null,
                ),
            )
        }
    }

    /** The per-run tidy-up switch. The setting it was seeded from is left alone. */
    fun onReplyTidyUp(on: Boolean) {
        vibrate()
        _uiState.update { it.copy(aiReply = it.aiReply.copy(tidyUp = on)) }
    }

    private fun replyNotice(@StringRes res: Int?) {
        _uiState.update { it.copy(aiReply = it.aiReply.copy(notice = res)) }
    }

    /** Whether this build and this grant can list the screenshots on the device. */
    private fun canReadImages(): Boolean {
        val permission = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            android.Manifest.permission.READ_MEDIA_IMAGES
        } else {
            android.Manifest.permission.READ_EXTERNAL_STORAGE
        }
        return androidx.core.content.ContextCompat.checkSelfPermission(this, permission) ==
            android.content.pm.PackageManager.PERMISSION_GRANTED
    }

    /** Opens (or closes) the screenshot picker, reading the gallery once as it opens. */
    fun onReplyPickShots(open: Boolean) {
        vibrate()
        if (!open) {
            _uiState.update { it.copy(aiReply = it.aiReply.copy(picking = false)) }
            return
        }
        if (!canReadImages()) {
            // Asked straight away rather than explained: pressing Screenshot
            // is the request. The notice stays behind with its own Allow
            // button for the user who said no and changed their mind.
            replyNotice(R.string.ime_reply_notice_no_images_permission)
            onReplyAllowImages()
            return
        }
        _uiState.update { it.copy(aiReply = it.aiReply.copy(picking = true, notice = null)) }
        serviceScope.launch(Dispatchers.IO) {
            val shots = ReplyShots.recent(this@WMKeyboardService, REPLY_SHOT_CHOICES)
                .map { ReplyShot(it.uri.toString(), it.name, it.addedAt) }
            _uiState.update { it.copy(aiReply = it.aiReply.copy(recentShots = shots)) }
            if (shots.isEmpty()) replyNotice(R.string.ime_reply_notice_no_shots)
        }
    }

    /**
     * A screenshot taken while the reply panel is open joins the conversation
     * on its own.
     *
     * The keyboard cannot take the picture — screen capture needs a consent
     * dialog, which is an activity, and an input method that starts one loses
     * the field it was typing into. What it can do is notice the one the user
     * takes with the hardware keys, which is this.
     */
    private fun noteScreenshotForReply(uri: android.net.Uri, copy: java.io.File?) {
        if (_uiState.value.panel != PanelMode.AI_REPLY) return
        // Taken with this panel on screen, so the keyboard is in the picture.
        // Taken with this panel on screen, so the keyboard is in the picture —
        // where it was at that moment, from the board's own history.
        addReplyShot(uri.toString(), copy?.absolutePath, boardTopAt(System.currentTimeMillis() / 1000))
    }

    /**
     * The images permission, through the trampoline: an input method cannot
     * show the system dialog itself. The picker opens on its own when the
     * keyboard comes back with the grant ([resumeReplyShotsAfterGrant]).
     */
    fun onReplyAllowImages() {
        replyShotsAfterGrant = true
        startActivity(
            Intent(this, com.wasimaster.wmkeyboard.app.ImagesPermissionActivity::class.java).apply {
                addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
            },
        )
    }

    /** The other half of [onReplyAllowImages], from [onStartInputView]. */
    private fun resumeReplyShotsAfterGrant() {
        if (!replyShotsAfterGrant) return
        if (_uiState.value.panel != PanelMode.AI_REPLY) {
            replyShotsAfterGrant = false
            return
        }
        // Refused: leave the flag set, so a second Allow that succeeds still
        // lands in the picker.
        if (!canReadImages()) return
        replyShotsAfterGrant = false
        onReplyPickShots(true)
    }

    /**
     * Which part of a screenshot is the conversation, as fractions of its
     * height.
     *
     * The top cut is the status bar and the chat app's own bar — the contact's
     * name and "Active now" — measured from this device's status bar plus a
     * standard app bar. The bottom cut is where the keyboard started, and only
     * when the keyboard was in the picture: otherwise the panel's own buttons
     * and notices come back as messages the other person sent.
     */
    private fun replyOcrFrame(boardTopPx: Int): ReplyOcrLines.ReplyOcrFrame {
        val screen = screenHeightPx().takeIf { it > 0 } ?: return ReplyOcrLines.ReplyOcrFrame()
        val statusId = resources.getIdentifier("status_bar_height", "dimen", "android")
        val status = if (statusId > 0) resources.getDimensionPixelSize(statusId) else 0
        val appBar = (REPLY_APP_BAR_DP * resources.displayMetrics.density).toInt()
        val top = ((status + appBar).toFloat() / screen).coerceIn(0f, REPLY_MAX_TOP_CUT)
        val bottom = boardTopPx.takeIf { it > 0 }?.let { it.toFloat() / screen }
        return ReplyOcrLines.ReplyOcrFrame(
            topCut = top,
            bottomCut = bottom?.takeIf { it > top }?.coerceAtMost(1f) ?: 1f,
        )
    }

    /**
     * Where the docked keyboard's top edge has been on screen, and since when
     * (#234): pairs of wall-clock millis and screen pixels, 0 for "not on
     * screen" (hidden or floating). A screenshot only says when it was taken,
     * so this is how the reply tool knows what part of it was the keyboard.
     */
    private val boardTopHistory = ArrayDeque<LongArray>()

    private fun noteBoardTop(topPx: Int) {
        val last = boardTopHistory.lastOrNull()
        if (last != null && last[1].toInt() == topPx) return
        boardTopHistory.addLast(longArrayOf(System.currentTimeMillis(), topPx.toLong()))
        while (boardTopHistory.size > BOARD_TOP_HISTORY) boardTopHistory.removeFirst()
    }

    /**
     * The keyboard's top edge on screen when a screenshot saved at [epochSec]
     * was taken, or 0 when it was not on screen. MediaStore keeps whole
     * seconds and stamps the moment the file was written, a beat after the
     * capture, so the board is read a moment before that.
     */
    private fun boardTopAt(epochSec: Long): Int {
        if (epochSec <= 0) return 0
        val at = epochSec * 1000 - SHOT_WRITE_LAG_MS
        val sample = boardTopHistory.lastOrNull { it[0] <= at } ?: return 0
        return sample[1].toInt()
    }

    /** The docked keyboard's top edge in screen pixels, or null when floating or unmeasured. */
    private fun boardTopOnScreen(): Int? {
        if (floatingNow()) return null
        val decor = window?.window?.decorView ?: return null
        val top = boardTopInWindow.takeIf { it > 0 } ?: return null
        val at = IntArray(2)
        decor.getLocationOnScreen(at)
        return at[1] + top
    }

    /** The whole screen's height, the size a screenshot is taken at. */
    private fun screenHeightPx(): Int {
        val wm = getSystemService(android.view.WindowManager::class.java) ?: return 0
        return if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {
            wm.maximumWindowMetrics.bounds.height()
        } else {
            val size = android.graphics.Point()
            @Suppress("DEPRECATION")
            wm.defaultDisplay.getRealSize(size)
            size.y
        }
    }

    /**
     * Joins message [index] onto the one before it: one bubble that OCR, or
     * the user copying it in two goes, turned into two.
     *
     * The earlier message keeps its side — it is the one the user was
     * reading when they pressed the join between them.
     */
    fun onReplyMerge(index: Int) {
        vibrate()
        _uiState.update {
            val entries = it.aiReply.entries
            if (index !in 1 until entries.size) return@update it
            val first = entries[index - 1]
            val second = entries[index]
            if (first.image || second.image) return@update it
            val merged = first.copy(
                text = (first.text.trimEnd() + " " + second.text.trimStart()).trim(),
                clipId = first.clipId.takeIf { id -> id != 0L } ?: second.clipId,
                shotUri = first.shotUri ?: second.shotUri,
                shotFile = first.shotFile ?: second.shotFile,
            )
            val updated = entries.toMutableList()
            updated[index - 1] = merged
            updated.removeAt(index)
            it.copy(aiReply = it.aiReply.copy(entries = updated, candidates = emptyList()))
        }
    }

    /** Back from the drafts to the messages, to fix one before trying again. */
    fun onReplyShowMessages() {
        vibrate()
        _uiState.update { it.copy(aiReply = it.aiReply.copy(candidates = emptyList())) }
    }

    /** The picker's rows. */
    fun onReplyAddShot(uri: String) {
        vibrate()
        val shot = _uiState.value.aiReply.recentShots.firstOrNull { it.uri == uri }
        _uiState.update { it.copy(aiReply = it.aiReply.copy(picking = false)) }
        // A screenshot taken since this panel opened was taken with it on
        // screen — the usual flow is open the panel, screenshot the chat,
        // pick it — so the keyboard is in the picture and must not be read.
        // Where the keyboard was when it was taken — not where it is now: a
        // shot of the chat with the plain keyboard up, picked from this taller
        // panel, has to be cut at the plain keyboard's top, and one taken
        // with the keyboard down is not cut at all.
        addReplyShot(uri, null, shot?.let { boardTopAt(it.addedAt) } ?: 0)
    }

    /**
     * Puts a screenshot into the conversation, by whichever route this
     * provider allows.
     *
     * Sent as a picture where the provider has somewhere to put one: the model
     * then reads the bubbles' own alignment, which is the only reliable signal
     * of who said what. Where it has not — an on-device model, Brave, or a user
     * who asked for it to stay on the device — the picture is read here instead
     * and arrives as lines the user can relabel.
     */
    private fun addReplyShot(uriString: String, copyPath: String?, boardTopPx: Int) {
        // The same screenshot twice, as a picture or as lines already read,
        // is one screenshot.
        if (_uiState.value.aiReply.entries.any { it.shotUri == uriString || it.fromShot == uriString }) return
        val settings = _uiState.value.settings
        val mode = settings.ai.reply.imageMode
        val sendable = replyCanSendPicture(settings)
        val asImage = when (mode) {
            ReplyImageMode.IMAGE -> true
            ReplyImageMode.OCR -> false
            ReplyImageMode.AUTO -> sendable
        }
        if (asImage) {
            if (!sendable) {
                replyNotice(R.string.ime_reply_notice_no_vision)
                return
            }
            addReplyEntry(
                ReplyEntry(
                    text = "",
                    source = ReplySource.SCREENSHOT,
                    shotUri = uriString,
                    shotFile = copyPath,
                    image = true,
                    boardTopPx = boardTopPx,
                ),
            )
            return
        }
        if (!ReplyOcr.available) {
            replyNotice(R.string.ime_reply_notice_no_ocr)
            return
        }
        _uiState.update { it.copy(aiReply = it.aiReply.copy(reading = true, notice = null)) }
        val frame = replyOcrFrame(boardTopPx)
        serviceScope.launch {
            val turns = withContext(Dispatchers.IO) {
                val bitmap = ReplyShots.bitmap(this@WMKeyboardService, android.net.Uri.parse(uriString))
                    ?: return@withContext emptyList()
                ReplyOcr.read(bitmap, frame, OcrLanguages.mlKitRecognizer(_uiState.value.language))
            }
            _uiState.update { it.copy(aiReply = it.aiReply.copy(reading = false)) }
            if (turns.isEmpty()) {
                replyNotice(R.string.ime_reply_notice_nothing_read)
                return@launch
            }
            // One entry per line, each carrying the screenshot it came from, so
            // the tidy-up removes the picture once rather than per line.
            var first = true
            for (turn in turns) {
                addReplyEntry(
                    ReplyEntry(
                        text = turn.text,
                        fromMe = turn.fromMe,
                        source = ReplySource.SCREENSHOT,
                        shotUri = if (first) uriString else null,
                        shotFile = if (first) copyPath else null,
                        boardTopPx = boardTopPx,
                        fromShot = uriString,
                    ),
                )
                first = false
            }
        }
    }

    /** A tone chip: the run, or the box for a tone whose instruction is typed. */
    fun onReplyTone(spec: AiActionSpec) {
        vibrate()
        val state = _uiState.value
        val initial = aiInitialState(state.settings)
        if (initial is AiUi.NeedModel || initial is AiUi.NeedSetup) {
            _uiState.update { it.copy(ai = initial) }
            return
        }
        if (!state.aiReply.hasContext) {
            replyNotice(R.string.ime_reply_notice_no_context)
            return
        }
        // A tone whose instruction is typed each run has nowhere to type it
        // here: the panel's own box is for the other person's message, and the
        // AI tool's instruction box belongs to its own panel. A tone the user
        // writes carries its task, which is the shape that fits this surface.
        if (spec.askEachRun) {
            // The message box becomes the instruction box for this run.
            _uiState.update {
                it.copy(aiReply = it.aiReply.copy(askTone = spec, typing = true, typed = "", editing = null, notice = null))
            }
            return
        }
        runAiReply(spec, instruction = "")
    }

    /**
     * Asks for the drafts.
     *
     * Its own path rather than [runAi]'s: a reply is several answers that
     * have to be split apart. They are drawn as each one finishes
     * ([AiReplyParse.settled]) — only lines that have ended, so a card never
     * changes after it appears — and the full parse replaces them at the end.
     */
    private fun runAiReply(tone: AiActionSpec, instruction: String) {
        // Somebody else's message is never worth less care than the user's own.
        if (_uiState.value.secureField) return
        // A GGUF model's answer stops at its next token instead of running on
        // behind the new request (LiteRT-LM's cannot, and runs to its end).
        if (aiJob?.isActive == true) LocalLlmEngine.stop()
        aiJob?.cancel()
        val settings = _uiState.value.settings
        val onDevice = settings.ai.provider == AiProvider.ON_DEVICE
        // Pictures gathered for one model and a run on another that cannot
        // take them — the user switched model in between. Read them on the
        // phone and go on, rather than sending a picture to be refused.
        val pending = _uiState.value.aiReply.images
        if (pending.isNotEmpty() && !replyCanSendPicture(settings)) {
            if (ReplyOcr.available) {
                readShotsInstead(tone, instruction, pending)
            } else {
                replyNotice(R.string.ime_reply_notice_no_vision)
            }
            return
        }
        if (!onDevice) {
            val decision = dataSaverStatus.decide(MeteredFeature.CLOUD_AI)
            if (decision != MeteredDecision.ALLOWED) {
                _uiState.update {
                    it.copy(
                        ai = AiUi.Error(
                            tone,
                            getString(
                                if (decision == MeteredDecision.ASK) R.string.ime_ai_error_metered_ask
                                else R.string.ime_ai_error_metered_blocked,
                            ),
                        ),
                    )
                }
                return
            }
        }
        val reply = _uiState.value.aiReply
        val style = replyStyle(settings, onDevice)
        val context = reply.context(app = currentPackage)
        val transcript = context.transcript(settings.ai.reply.contextChars)
        val shots = reply.images
        if (transcript.isBlank() && shots.isEmpty()) {
            replyNotice(R.string.ime_reply_notice_no_context)
            return
        }
        val draft = replyDraftFromField()
        val seq = ++aiRunSeq
        val startedAt = SystemClock.uptimeMillis()
        _uiState.update {
            it.copy(
                ai = AiUi.Loading(tone, startedAtMs = startedAt),
                aiReply = it.aiReply.copy(tone = tone, candidates = emptyList(), notice = null, draft = draft),
            )
        }
        // Drafts as they finish. Called from the stream's own thread, so the
        // count is atomic; only a longer list is published, which also keeps
        // a late partial from undoing the final parse.
        val shown = java.util.concurrent.atomic.AtomicInteger(0)
        val onPartial: (String) -> Unit = { partial ->
            val settled = AiReplyParse.settled(partial, style.count)
            val before = shown.get()
            if (seq == aiRunSeq && settled.size > before && shown.compareAndSet(before, settled.size)) {
                _uiState.update {
                    if (it.ai is AiUi.Loading) it.copy(aiReply = it.aiReply.copy(candidates = settled)) else it
                }
            }
        }
        val incognito = _uiState.value.incognitoOn
        aiJob = serviceScope.launch {
            val memory = aiMemoryFor(settings, onDevice, incognito, listOf(instruction, transcript, draft))
            val system = withAiMemory(
                AiPrompts.replyPrompt(tone, style, instruction, hasImage = shots.isNotEmpty(), draft = draft),
                memory,
            )
            val config = AiClient.config(settings.ai)
            val outcome = withContext(Dispatchers.IO) {
                runCatching {
                    // A picture with nothing said about it still needs a user
                    // message: several providers reject an empty one outright.
                    val user = transcript.ifBlank { REPLY_IMAGE_ONLY_MESSAGE }
                    if (onDevice) {
                        val pictures = shots.mapNotNull { entry ->
                            entry.shotUri?.let { ReplyShots.jpeg(this@WMKeyboardService, android.net.Uri.parse(it)) }
                        }
                        runReplyOnDevice(seq, system, user, pictures, settings, onPartial)
                    } else {
                        val images = shots.mapNotNull { entry ->
                            val uri = entry.shotUri ?: return@mapNotNull null
                            ReplyShots.encode(this@WMKeyboardService, android.net.Uri.parse(uri))
                                ?.let { AiClient.AiImage(it.mimeType, it.base64) }
                        }
                        AiClient.completeStreaming(
                            config = config,
                            system = system,
                            turns = listOf(
                                AiClient.ChatTurn(AiClient.ChatRole.USER, user, images = images),
                            ),
                            maxTokens = AiClient.effectiveMaxTokens(settings.ai),
                            onPhase = { phase -> applyAiPhase(seq, phase) },
                            onPartial = onPartial,
                            isActive = { seq == aiRunSeq },
                        )
                    }
                }
            }
            if (seq != aiRunSeq) return@launch
            outcome.fold(
                onSuccess = { completion ->
                    val drafts = AiReplyParse.candidates(completion.text, style.count)
                    if (drafts.isEmpty()) {
                        _uiState.update {
                            it.copy(ai = AiUi.Error(tone, getString(R.string.ime_ai_error_empty_result)))
                        }
                    } else {
                        _uiState.update {
                            it.copy(
                                ai = aiInitialState(it.settings),
                                aiReply = it.aiReply.copy(candidates = drafts, tone = tone),
                            )
                        }
                    }
                    if (settings.ai.reply.keepHistory) {
                        recordAiHistory(
                            action = tone,
                            source = transcript,
                            instruction = instruction,
                            settings = settings,
                            config = config,
                            state = AiUi.Ready(tone, drafts.joinToString("\n"), transcript),
                            reasoningChars = 0,
                            durationMs = SystemClock.uptimeMillis() - startedAt,
                        )
                    }
                },
                onFailure = { e ->
                    // The on-device model has no eyes: read the screenshots on
                    // the phone instead and run again, rather than stopping at
                    // an error about something the user did not choose.
                    if (e is VisionUnsupportedException && onDevice && shots.isNotEmpty() && ReplyOcr.available) {
                        replyVisionRefusedModel = effectiveLocalModelId(settings)
                        readShotsInstead(tone, instruction, shots)
                        return@fold
                    }
                    _uiState.update {
                        it.copy(
                            ai = AiUi.Error(
                                tone,
                                requestErrorText(e, R.string.ime_ai_error_request_failed),
                            ),
                        )
                    }
                },
            )
        }
    }

    /**
     * The on-device half of [runAiReply]. Pictures go to the model itself when
     * there are any — a Gemma 4 model reads the bubbles' alignment the way a
     * cloud model does — and the engine throws [VisionUnsupportedException]
     * when this model cannot.
     */
    private fun runReplyOnDevice(
        seq: Int,
        system: String,
        user: String,
        pictures: List<ByteArray>,
        settings: KeyboardSettings,
        onPartial: (String) -> Unit,
    ): AiClient.Completion {
        val modelFile = effectiveLocalModelFile(settings)
            ?: throw IOException(getString(R.string.ime_ai_error_model_missing))
        applyAiPhase(seq, AiPhase.PREPARING)
        val text = if (pictures.isEmpty()) {
            LocalLlmEngine.generate(
                context = applicationContext,
                modelFile = modelFile,
                backend = settings.ai.localBackend,
                contextTokens = settings.ai.localContextTokens,
                system = system,
                user = user,
                onPartial = onPartial,
            )
        } else {
            LocalLlmEngine.generateWithImages(
                context = applicationContext,
                modelFile = modelFile,
                backend = settings.ai.localBackend,
                contextTokens = settings.ai.localContextTokens,
                system = system,
                user = user,
                images = pictures,
                onPartial = onPartial,
            )
        }
        return AiClient.Completion(text)
    }

    /**
     * Turns the picture entries into lines read on the phone, then runs the
     * same tone again — the fallback for an on-device model that turned out
     * not to see. Each picture's lines take its place in the conversation,
     * the first carrying the screenshot so the tidy-up still finds it.
     */
    private fun readShotsInstead(
        tone: AiActionSpec?,
        instruction: String,
        shots: List<ReplyEntry>,
        @StringRes notice: Int? = R.string.ime_reply_notice_reading_instead,
    ) {
        _uiState.update {
            it.copy(
                ai = aiInitialState(it.settings),
                aiReply = it.aiReply.copy(
                    reading = true,
                    notice = notice,
                    candidates = emptyList(),
                    canSendPicture = replyCanSendPicture(it.settings),
                ),
            )
        }
        serviceScope.launch {
            val frames = shots.associateWith { replyOcrFrame(it.boardTopPx) }
            val read = withContext(Dispatchers.IO) {
                shots.associateWith { entry ->
                    val uri = entry.shotUri ?: return@associateWith emptyList()
                    val bitmap = ReplyShots.bitmap(this@WMKeyboardService, android.net.Uri.parse(uri))
                        ?: return@associateWith emptyList()
                    ReplyOcr.read(bitmap, frames.getValue(entry), OcrLanguages.mlKitRecognizer(_uiState.value.language))
                }
            }
            var anyText = false
            _uiState.update { state ->
                val rebuilt = state.aiReply.entries.flatMap { entry ->
                    val turns = read[entry] ?: return@flatMap listOf(entry)
                    if (turns.isNotEmpty()) anyText = true
                    turns.mapIndexed { i, turn ->
                        ReplyEntry(
                            text = turn.text,
                            fromMe = turn.fromMe,
                            source = ReplySource.SCREENSHOT,
                            shotUri = if (i == 0) entry.shotUri else null,
                            shotFile = if (i == 0) entry.shotFile else null,
                            boardTopPx = entry.boardTopPx,
                            fromShot = entry.shotUri,
                        )
                    }
                }
                state.copy(aiReply = state.aiReply.copy(entries = rebuilt.takeLast(MAX_REPLY_ENTRIES), reading = false))
            }
            if (!anyText) {
                replyNotice(R.string.ime_reply_notice_nothing_read)
                return@launch
            }
            if (tone != null) runAiReply(tone, instruction)
        }
    }

    /**
     * The panel's Picture/Text switch for screenshots (#234). Remembered as
     * the "How screenshots are read" setting — Picture as Automatic, so a
     * later switch to a model without eyes falls back to text instead of
     * failing — and applied to the screenshots already gathered: pictures are
     * read into lines, or a screenshot's lines go back to being its picture.
     */
    fun onReplySendPictures(pictures: Boolean) {
        vibrate()
        val state = _uiState.value
        if (state.ai is AiUi.Loading || state.aiReply.reading) return
        if (pictures) {
            if (!replyCanSendPicture(state.settings)) {
                replyNotice(R.string.ime_reply_notice_no_vision)
                return
            }
            serviceScope.launch { settingsRepository.setAiReplyImageMode(ReplyImageMode.AUTO) }
            _uiState.update { current ->
                val entries = current.aiReply.entries
                val rebuilt = ArrayList<ReplyEntry>(entries.size)
                val seen = HashSet<String>()
                for (entry in entries) {
                    val shot = entry.fromShot
                    if (shot == null) {
                        rebuilt += entry
                        continue
                    }
                    // The whole screenshot comes back once, where its first
                    // line was; the rest of its lines fold into it.
                    if (!seen.add(shot)) continue
                    val group = entries.filter { it.fromShot == shot }
                    rebuilt += ReplyEntry(
                        text = "",
                        source = ReplySource.SCREENSHOT,
                        shotUri = shot,
                        shotFile = group.firstNotNullOfOrNull { it.shotFile },
                        image = true,
                        boardTopPx = entry.boardTopPx,
                    )
                }
                current.copy(aiReply = current.aiReply.copy(entries = rebuilt, candidates = emptyList(), notice = null))
            }
        } else {
            if (!ReplyOcr.available) {
                replyNotice(R.string.ime_reply_notice_no_ocr)
                return
            }
            serviceScope.launch { settingsRepository.setAiReplyImageMode(ReplyImageMode.OCR) }
            val shots = state.aiReply.images
            if (shots.isNotEmpty()) readShotsInstead(null, "", shots, notice = null)
        }
    }

    /**
     * Puts one draft into the field, and clears away what it was built from.
     *
     * When the run was written from a draft the user had started, the chosen
     * reply replaces that draft — it is the same message, said better — but
     * only while the field still holds exactly what was read; anything typed
     * since wins, and the reply lands at the cursor instead.
     *
     * The tidy-up happens here rather than when the panel closes, because this
     * is the moment the reply has served its purpose. A panel closed without
     * picking anything leaves everything alone: the user may be going back to
     * copy one more message.
     */
    fun onReplyInsert(text: String) {
        if (text.isBlank()) return
        val state = _uiState.value
        val draft = state.aiReply.draft
        if (draft.isNotBlank() && !state.secureField && extractFieldText().trim() == draft) {
            replaceFieldText(text)
        } else {
            onToolTextInsert(text)
        }
        if (state.aiReply.tidyUp) tidyUpReply(state.aiReply.entries)
        _uiState.update {
            it.copy(
                ai = aiInitialState(it.settings),
                aiReply = it.aiReply.copy(
                    entries = emptyList(),
                    candidates = emptyList(),
                    typed = "",
                    typing = false,
                    draft = "",
                ),
            )
        }
    }

    /**
     * Takes back the clips and screenshots a finished reply was built from.
     *
     * Only what this reply used. The clipboard rows are the keyboard's own and
     * always go. A screenshot's gallery entry is the user's: from Android 11 an
     * app may only delete media it created, so what the plain delete could not
     * remove goes to Android's own consent dialog, through a trampoline
     * ([ReplyShotDeleteActivity]) — the reply is already in the field, so
     * losing it for the length of one dialog costs nothing. Where there is no
     * such dialog (a photo-picker grant, Android 10) the panel says the
     * picture was kept rather than pretending it is gone.
     */
    private fun tidyUpReply(entries: List<ReplyEntry>) {
        val clipIds = entries.mapNotNull { it.clipId.takeIf { id -> id != 0L } }.distinct()
        val shots = entries.filter { it.shotUri != null }.distinctBy { it.shotUri }
        if (clipIds.isEmpty() && shots.isEmpty()) return
        serviceScope.launch(Dispatchers.IO) {
            for (id in clipIds) clipboardStore.remove(id)
            val kept = ArrayList<android.net.Uri>()
            for (shot in shots) {
                val uri = shot.shotUri?.let { android.net.Uri.parse(it) }
                val removed = ReplyShots.delete(
                    this@WMKeyboardService,
                    uri,
                    shot.shotFile?.let { java.io.File(it) },
                )
                if (!removed && uri != null) kept += uri
            }
            if (clipIds.isNotEmpty()) {
                saveClipboardSoon()
                _uiState.update { it.copy(clipboardItems = clipboardStore.items()) }
            }
            if (kept.isEmpty()) return@launch
            val request = ReplyShots.deleteRequest(this@WMKeyboardService, kept)
            if (request == null) {
                replyNotice(R.string.ime_reply_notice_shot_kept)
                return@launch
            }
            withContext(Dispatchers.Main) {
                runCatching { com.wasimaster.wmkeyboard.app.ReplyShotDeleteActivity.start(this@WMKeyboardService, request) }
                    .onFailure { replyNotice(R.string.ime_reply_notice_shot_kept) }
            }
        }
    }

    // ---- AI chat (#280) ----
    //
    // The panel's chat mode. The conversation itself is AiChatController's: the
    // same object, store and live run the chat screen in the settings app
    // draws, so everything here is only what the keyboard adds — a composer its
    // own keys write into, and the field behind it to quote from and insert to.

    /** The composer's text, written by the capture ladder. */
    private fun aiChatDraft(text: String) {
        _uiState.update {
            // A chat's new name is typed through the same field (#882).
            if (it.aiChat.renaming >= 0) {
                it.copy(aiChat = it.aiChat.copy(renameDraft = text.take(AiChatStore.MAX_RENAME)))
            } else {
                it.copy(aiChat = it.aiChat.copy(draft = text.take(AiChatStore.MAX_TEXT)))
            }
        }
    }

    /** The model the next message goes to: the one picked, else the last used. */
    private fun aiChatChoice(): AiChatController.ModelChoice? {
        val state = _uiState.value
        val available = AiChatController.choices(this, state.settings)
        return available.firstOrNull { it.key == state.aiChat.modelKey }
            ?: AiChatController.initialChoice(AiChatController.store(this), available)
    }

    /**
     * Puts the chat mode in order as the AI panel opens: whether it may be
     * offered at all, which mode the panel was left in, and a conversation that
     * still exists. The composer never opens with the keys — a panel that
     * swallowed the first keystroke after opening would be a trap.
     */
    private fun prepareAiChat() {
        // Conversations are in credential-encrypted storage, and a transcript
        // is not something to draw over a keyguard.
        val offered = userUnlocked && !isDeviceLocked()
        if (!offered) {
            _uiState.update { it.copy(aiChat = it.aiChat.copy(available = false, composing = false)) }
            return
        }
        val store = AiChatController.store(this)
        // An answer still forming is the conversation to come back to, whichever
        // of the two surfaces started it.
        val live = AiChatController.run.value?.conversationId
        _uiState.update {
            val chat = it.aiChat
            val id = live ?: chat.conversationId.takeIf { id -> id >= 0 && store.get(id) != null } ?: -1L
            it.copy(
                aiChat = chat.copy(
                    available = true,
                    open = it.settings.ai.panelChat,
                    conversationId = id,
                    composing = false,
                    showSessions = false,
                ),
            )
        }
        val keep = _uiState.value.settings.ai.keepChats
        serviceScope.launch { AiChatController.applyPersistSetting(this@WMKeyboardService, keep) }
    }

    /** The selection, or else the field's text, for quoting along with a message. */
    private fun aiChatAttachmentFromField(): AiChatAttachment? {
        // Never out of a password field, whatever the user pressed.
        if (_uiState.value.secureField) return null
        val ic = currentInputConnection ?: return null
        commitComposing(ic, autocorrect = false)
        val selected = ic.getSelectedText(0)?.toString()?.takeIf { it.isNotBlank() }
        val text = (selected ?: extractFieldText()).trim()
        if (text.isEmpty()) return null
        return AiChatAttachment(text.take(AiChatStore.MAX_TEXT), fromSelection = selected != null)
    }

    /** The key a conversation's last model has in the picker. */
    private fun aiChatModelKeyOf(conversationId: Long): String? {
        val conversation = AiChatController.store(this).get(conversationId) ?: return null
        return when {
            conversation.provider.isEmpty() -> null
            conversation.provider == AiProvider.ON_DEVICE.name ->
                AiChatStore.ON_DEVICE_KEY_PREFIX + conversation.localModelId
            else -> conversation.provider
        }
    }

    fun onAiChatAction(action: AiChatAction) {
        val state = _uiState.value
        val chat = state.aiChat
        // The tools' selection bars copy and insert through here too (#352),
        // and neither needs the chat; Ask AI checks for itself.
        when (action) {
            is AiChatAction.AskAbout -> { askAiAbout(action); return }
            // The AI panel's actions ask through here as well as the chat.
            is AiChatAction.ToolApproval -> {
                vibrate()
                answerAiTool(action.choice)
                return
            }
            is AiChatAction.Copy, is AiChatAction.Insert -> Unit
            else -> if (!chat.available) return
        }
        // openRoute buzzes on its own.
        if (action !is AiChatAction.OpenInApp) vibrate()
        // Two halves rather than one `when`: each branch that copies the ui
        // state inlines a call carrying every one of its fields, and the
        // single `when` took this method past the 10,000 dex instructions at
        // which ART stops compiling it.
        if (aiChatSessionAction(action, chat)) return
        if (aiChatOptionAction(action)) return
        when (action) {
            is AiChatAction.SetMode -> {
                _uiState.update {
                    it.copy(
                        aiChat = it.aiChat.copy(open = action.chat, composing = false, showSessions = false),
                        // One field with the keys at a time: a half-typed
                        // instruction does not keep them under the chat.
                        ai = if (action.chat && it.ai is AiUi.CustomInput) AiUi.Idle else it.ai,
                    )
                }
                serviceScope.launch { settingsRepository.setAiPanelChat(action.chat) }
            }
            AiChatAction.FocusComposer ->
                _uiState.update { it.copy(aiChat = it.aiChat.copy(composing = true)) }
            AiChatAction.BlurComposer ->
                // Putting the keys away while naming a chat drops the name.
                _uiState.update { it.copy(aiChat = it.aiChat.copy(composing = false, renaming = -1L, renameDraft = "")) }
            AiChatAction.Send -> aiChatSend()
            AiChatAction.Stop -> AiChatController.stop(this)
            AiChatAction.Retry -> aiChatChoice()?.let {
                AiChatController.retry(this, state.settings, chat.conversationId, it, incognito = state.incognitoOn)
            }
            AiChatAction.Regenerate -> aiChatChoice()?.let {
                AiChatController.regenerate(this, state.settings, chat.conversationId, it, incognito = state.incognitoOn)
            }
            is AiChatAction.UndoMemory ->
                AiChatController.undoMemory(this, chat.conversationId, action.messageIndex, action.useIndex)
            AiChatAction.EditLast -> {
                val taken = AiChatController.editLast(this, chat.conversationId) ?: return
                _uiState.update {
                    it.copy(
                        aiChat = it.aiChat.copy(
                            draft = taken.content,
                            attachment = taken.attachment.takeIf(String::isNotEmpty)
                                ?.let { text -> AiChatAttachment(text, fromSelection = false) },
                            // Its pictures come back with its words; the
                            // clear-out's grace keeps their files.
                            images = taken.images,
                            files = taken.files,
                            mode = taken.chatMode.id,
                            format = taken.answerFormat.id,
                            composing = true,
                        ),
                    )
                }
            }
            is AiChatAction.PickModel ->
                _uiState.update { it.copy(aiChat = it.aiChat.copy(modelKey = action.key)) }
            AiChatAction.ToggleAttachment -> {
                val next = if (chat.attachment != null) null else aiChatAttachmentFromField()
                _uiState.update { it.copy(aiChat = it.aiChat.copy(attachment = next, attachMenu = false)) }
            }
            AiChatAction.Paste -> {
                if (!isClipboardAccessible()) return
                val clip = KeyboardClipboard.held ?: clipboardStore.latestText().orEmpty()
                if (clip.isEmpty()) return
                // Through the ladder, so it lands at the caret like typed text.
                _uiState.update { it.copy(aiChat = it.aiChat.copy(composing = true, attachMenu = false)) }
                captureTyped(clip)
            }
            is AiChatAction.Insert -> commitToField(
                if (action.raw) action.text else AiMarkdown.strip(action.text).ifBlank { action.text },
            )
            is AiChatAction.Copy -> KeyboardClipboard.copy(this, action.text)
            is AiChatAction.Starter -> {
                // Read outside the update: it flushes the composing word, and
                // an update's block can run more than once.
                val quoted = chat.attachment ?: if (action.attach) aiChatAttachmentFromField() else null
                _uiState.update {
                    it.copy(aiChat = it.aiChat.copy(draft = action.text, attachment = quoted, composing = true))
                }
            }
            is AiChatAction.OpenInApp ->
                openRoute(
                    if (action.list || chat.conversationId < 0) "ai_chat" else "ai_chat/${chat.conversationId}",
                )
            is AiChatAction.Report -> aiChatReport(action.index)
            AiChatAction.ToggleAttachMenu ->
                _uiState.update {
                    it.copy(aiChat = it.aiChat.copy(attachMenu = !it.aiChat.attachMenu, optionsMenu = false, pictureNotice = null))
                }
            is AiChatAction.PickFromSystem -> aiChatPickFromSystem(action.mode)
            AiChatAction.ToggleReasoning -> {
                val on = !state.settings.ai.chatReasoning
                serviceScope.launch { settingsRepository.setAiChatReasoning(on) }
            }
            is AiChatAction.RemoveFile ->
                _uiState.update { it.copy(aiChat = it.aiChat.copy(files = it.aiChat.files - action.file)) }
            is AiChatAction.AddPicture -> aiChatAddPicture(action.fromClipboard)
            is AiChatAction.RemovePicture -> {
                chatPictureFrom.remove(action.name)
                _uiState.update { it.copy(aiChat = it.aiChat.copy(images = it.aiChat.images - action.name)) }
            }
            is AiChatAction.AskAbout, is AiChatAction.ToolApproval -> Unit
            // The conversation list's, handled by aiChatSessionAction above.
            else -> Unit
        }
    }

    /**
     * [onAiChatAction]'s message-box options: the mode and answer format of
     * the next message, the row that picks them, and Share under an answer.
     * Their own method for the dex-size reason [onAiChatAction] gives. False
     * when [action] is not one of them.
     */
    private fun aiChatOptionAction(action: AiChatAction): Boolean {
        when (action) {
            AiChatAction.ToggleOptions ->
                _uiState.update {
                    it.copy(aiChat = it.aiChat.copy(optionsMenu = !it.aiChat.optionsMenu, attachMenu = false))
                }
            is AiChatAction.SetChatMode -> _uiState.update { it.copy(aiChat = it.aiChat.copy(mode = action.id)) }
            is AiChatAction.SetAnswerFormat -> _uiState.update { it.copy(aiChat = it.aiChat.copy(format = action.id)) }
            is AiChatAction.Share -> {
                val conversation = AiChatController.store(this).get(_uiState.value.aiChat.conversationId) ?: return true
                val answer = conversation.messages.getOrNull(action.index) ?: return true
                val question = conversation.messages.take(action.index).lastOrNull { it.role == AiChatMessage.ROLE_USER }
                val shared = AiChatExport.share(
                    this, AiChatExport.Kind.MARKDOWN, conversation.title, question?.content.orEmpty(), answer.content,
                    open = { shareVia(it) },
                )
                if (!shared) {
                    Toast.makeText(this, getString(R.string.ime_ai_chat_share_failed), Toast.LENGTH_SHORT).show()
                }
            }
            else -> return false
        }
        return true
    }

    /** [onAiChatAction]'s conversation list: new, open, delete, pick, rename. False when [action] is not one of them. */
    private fun aiChatSessionAction(action: AiChatAction, chat: AiChatUi): Boolean {
        when (action) {
            AiChatAction.NewChat ->
                _uiState.update {
                    it.copy(
                        aiChat = it.aiChat.copy(
                            conversationId = -1L,
                            showSessions = false,
                            composing = true,
                            picked = emptySet(),
                            renaming = -1L,
                        ),
                    )
                }
            is AiChatAction.Open ->
                _uiState.update {
                    it.copy(
                        aiChat = it.aiChat.copy(
                            conversationId = action.conversationId,
                            showSessions = false,
                            composing = false,
                            picked = emptySet(),
                            renaming = -1L,
                            // A conversation comes back on the model it was
                            // last had with, when that model is still here.
                            modelKey = aiChatModelKeyOf(action.conversationId) ?: it.aiChat.modelKey,
                        ),
                    )
                }
            is AiChatAction.Delete -> {
                AiChatController.deleteConversation(this, action.conversationId)
                if (chat.conversationId == action.conversationId) {
                    _uiState.update { it.copy(aiChat = it.aiChat.copy(conversationId = -1L)) }
                }
            }
            AiChatAction.ToggleSessions ->
                _uiState.update {
                    it.copy(
                        aiChat = it.aiChat.copy(
                            showSessions = !it.aiChat.showSessions,
                            composing = false,
                            picked = emptySet(),
                            renaming = -1L,
                            renameDraft = "",
                        ),
                    )
                }
            is AiChatAction.TogglePick ->
                _uiState.update {
                    val picked = it.aiChat.picked
                    val id = action.conversationId
                    it.copy(aiChat = it.aiChat.copy(picked = if (id in picked) picked - id else picked + id))
                }
            AiChatAction.PickAll -> {
                val all = AiChatController.store(this).items().mapTo(HashSet()) { it.id }
                _uiState.update { it.copy(aiChat = it.aiChat.copy(picked = all)) }
            }
            AiChatAction.ClearPicks -> _uiState.update { it.copy(aiChat = it.aiChat.copy(picked = emptySet())) }
            AiChatAction.DeletePicked -> {
                val doomed = chat.picked
                AiChatController.deleteConversations(this, doomed)
                _uiState.update {
                    it.copy(
                        aiChat = it.aiChat.copy(
                            picked = emptySet(),
                            conversationId = if (it.aiChat.conversationId in doomed) -1L else it.aiChat.conversationId,
                        ),
                    )
                }
            }
            is AiChatAction.StartRename -> {
                val title = AiChatController.store(this).get(action.conversationId)?.title.orEmpty()
                _uiState.update {
                    it.copy(
                        aiChat = it.aiChat.copy(
                            renaming = action.conversationId,
                            renameDraft = title,
                            picked = emptySet(),
                            composing = true,
                        ),
                    )
                }
            }
            AiChatAction.CommitRename -> {
                if (chat.renaming >= 0) AiChatController.renameConversation(this, chat.renaming, chat.renameDraft)
                _uiState.update { it.copy(aiChat = it.aiChat.copy(renaming = -1L, renameDraft = "", composing = false)) }
            }
            AiChatAction.CancelRename ->
                _uiState.update { it.copy(aiChat = it.aiChat.copy(renaming = -1L, renameDraft = "", composing = false)) }
            else -> return false
        }
        return true
    }

    /**
     * Where each picture waiting in the chat's composer came from (a clip's
     * file, a screenshot's address), so asking for the same one twice adds it
     * once. Each import gets a fresh name, so the names alone cannot tell.
     */
    private val chatPictureFrom = HashMap<String, String>()

    /**
     * A picture for the chat's next message (#698), from the sources the reply
     * tool reads: the newest image in the clipboard history, or the newest
     * screenshot in the gallery. Never in incognito or in a password field,
     * where the panel does not offer it either.
     */
    private fun aiChatAddPicture(fromClipboard: Boolean) {
        val state = _uiState.value
        if (state.incognitoOn || state.secureField) return
        if (state.aiChat.images.size >= AiChatStore.MAX_IMAGES) return
        // A Play build declares no photos permission to read screenshots with.
        if (!fromClipboard && !com.wasimaster.wmkeyboard.app.ChannelFeatures.SCREENSHOT_CLIPS) return
        val clipFile = if (fromClipboard) {
            val item = if (isClipboardAccessible()) {
                clipboardStore.items().firstOrNull { it.kind == ClipKind.IMAGE && !it.sensitive }
            } else {
                null
            }
            val file = item?.imagePath?.let(::File)?.takeIf { it.isFile }
            if (file == null) {
                aiChatPictureNotice(R.string.ime_ai_chat_picture_no_clip)
                return
            }
            file
        } else {
            if (!canReadImages()) {
                // Asked straight away, as the reply tool's Screenshot does:
                // pressing the chip is the request.
                aiChatPictureNotice(R.string.ime_ai_chat_picture_no_permission)
                chatShotAfterGrant = true
                startActivity(
                    Intent(this, com.wasimaster.wmkeyboard.app.ImagesPermissionActivity::class.java).apply {
                        addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                    },
                )
                return
            }
            null
        }
        val keep = AiChatController.store(this).persist
        serviceScope.launch {
            val shot = if (clipFile == null) {
                withContext(Dispatchers.IO) { ReplyShots.recent(this@WMKeyboardService, limit = 1).firstOrNull() }
            } else {
                null
            }
            val source = clipFile?.absolutePath ?: shot?.uri?.toString()
            if (source == null) {
                aiChatPictureNotice(R.string.ime_ai_chat_picture_no_shot)
                return@launch
            }
            // Already waiting above the composer: nothing to add.
            if (_uiState.value.aiChat.images.any { chatPictureFrom[it] == source }) {
                _uiState.update { it.copy(aiChat = it.aiChat.copy(attachMenu = false, pictureNotice = null)) }
                return@launch
            }
            // Scaled and copied in off the main thread: a screenshot takes a
            // moment to decode.
            val name = withContext(Dispatchers.IO) {
                if (clipFile != null) {
                    AiChatImages.import(this@WMKeyboardService, clipFile, keep)
                } else {
                    shot?.let { AiChatImages.import(this@WMKeyboardService, it.uri, keep) }
                }
            }
            if (name == null) {
                aiChatPictureNotice(R.string.ime_ai_chat_picture_unreadable)
                return@launch
            }
            chatPictureFrom[name] = source
            _uiState.update {
                val images = it.aiChat.images
                if (images.size >= AiChatStore.MAX_IMAGES) return@update it
                it.copy(aiChat = it.aiChat.copy(images = images + name, attachMenu = false, pictureNotice = null))
            }
        }
    }

    private fun aiChatPictureNotice(@StringRes res: Int) {
        _uiState.update { it.copy(aiChat = it.aiChat.copy(attachMenu = true, pictureNotice = res)) }
    }

    /**
     * The "+" menu's Image, File and Photo (#882), through
     * [com.wasimaster.wmkeyboard.app.AiChatPickActivity]: each is a system
     * screen an input method cannot open for a result itself. What comes back
     * is taken in by [takeAiChatPicks] once the field returns.
     */
    private fun aiChatPickFromSystem(mode: Int) {
        val state = _uiState.value
        // The same rule the picture buttons keep: nothing from incognito,
        // whose chats are not kept, and nothing over a password field.
        if (state.incognitoOn || state.secureField) return
        val files = mode == com.wasimaster.wmkeyboard.app.AiChatPickActivity.MODE_FILES
        val room = if (files) {
            AiChatStore.MAX_FILES - state.aiChat.files.size
        } else {
            AiChatStore.MAX_IMAGES - state.aiChat.images.size
        }
        if (room <= 0) {
            aiChatPictureNotice(R.string.ime_ai_chat_attach_full)
            return
        }
        _uiState.update { it.copy(aiChat = it.aiChat.copy(attachMenu = false, pictureNotice = null)) }
        val keep = AiChatController.store(this).persist
        runCatching {
            startActivity(com.wasimaster.wmkeyboard.app.AiChatPickActivity.intent(this, mode, room, keep))
        }.onFailure { aiChatPictureNotice(R.string.ime_ai_chat_attach_no_picker) }
    }

    /** What the "+" menu's last trip to a picker brought back, added to the draft. */
    private fun takeAiChatPicks() {
        val picks = com.wasimaster.wmkeyboard.app.AiChatPickActivity.consume() ?: return
        _uiState.update {
            val chat = it.aiChat
            val images = (chat.images + picks.images).take(AiChatStore.MAX_IMAGES)
            val files = (chat.files + picks.files).take(AiChatStore.MAX_FILES)
            val dropped = chat.images.size + picks.images.size > images.size || chat.files.size + picks.files.size > files.size
            val notice = when {
                picks.notice != 0 -> picks.notice
                dropped -> R.string.ime_ai_chat_attach_full
                else -> null
            }
            it.copy(aiChat = chat.copy(images = images, files = files, pictureNotice = notice, attachMenu = notice != null))
        }
    }

    /** The other half of [aiChatAddPicture]'s permission request, from [onStartInputView]. */
    private fun resumeChatShotAfterGrant() {
        if (!chatShotAfterGrant) return
        val state = _uiState.value
        if (state.panel != PanelMode.AI || !state.aiChat.open) {
            chatShotAfterGrant = false
            return
        }
        // Refused: leave the flag set, so a second try that succeeds still
        // adds the screenshot.
        if (!canReadImages()) return
        chatShotAfterGrant = false
        aiChatAddPicture(fromClipboard = false)
    }

    /**
     * Ask AI from a tool (#352): the AI panel, in chat mode, on a new chat,
     * with the tool's text attached and the composer taking the keys, so the
     * question is the next thing typed.
     */
    private fun askAiAbout(action: AiChatAction.AskAbout) {
        // The chats are in credential-encrypted storage; the panel says so on
        // the lock screen, and the tools do not offer this there.
        if (!userUnlocked || isDeviceLocked()) return
        val text = action.text.trim()
        if (text.isEmpty()) return
        vibrate()
        if (_uiState.value.panel != PanelMode.AI) onPanelChange(PanelMode.AI, haptic = false)
        if (_uiState.value.panel != PanelMode.AI || !_uiState.value.aiChat.available) return
        _uiState.update {
            it.copy(
                // One field with the keys at a time, as the mode switch has it.
                ai = if (it.ai is AiUi.CustomInput) AiUi.Idle else it.ai,
                aiChat = it.aiChat.copy(
                    open = true,
                    conversationId = -1L,
                    showSessions = false,
                    draft = "",
                    attachment = AiChatAttachment(
                        text.take(AiChatStore.MAX_TEXT),
                        fromSelection = action.fromSelection,
                        label = action.label,
                    ),
                    composing = true,
                ),
            )
        }
    }

    private fun aiChatSend() {
        val state = _uiState.value
        val chat = state.aiChat
        val text = chat.draft.trim()
        // Pictures or files alone are a message, as on the chat screen.
        if ((text.isEmpty() && chat.images.isEmpty() && chat.files.isEmpty()) || AiChatController.isGenerating) return
        val choice = aiChatChoice() ?: return
        val store = AiChatController.store(this)
        // Written on the first send and not before, like the chat screen: a
        // chat opened and left leaves no row behind.
        val id = chat.conversationId.takeIf { it >= 0 && store.get(it) != null }
            ?: store.newConversation(System.currentTimeMillis(), ephemeral = state.incognitoOn).id
        AiChatController.send(
            this, state.settings, id, choice, text, chat.attachment?.text.orEmpty(), chat.images,
            incognito = state.incognitoOn,
            files = chat.files,
            mode = AiChatMode.of(chat.mode),
            format = AiAnswerFormat.of(chat.format),
        )
        chatPictureFrom.clear()
        _uiState.update {
            it.copy(
                aiChat = it.aiChat.copy(
                    conversationId = id,
                    draft = "",
                    attachment = null,
                    modelKey = choice.key,
                    images = emptyList(),
                    files = emptyList(),
                    attachMenu = false,
                    optionsMenu = false,
                    pictureNotice = null,
                ),
            )
        }
    }

    /** The chat's form of [onAiReport]: the same draft, quoting the answer at [index]. */
    private fun aiChatReport(index: Int) {
        val messages = AiChatController.store(this).get(_uiState.value.aiChat.conversationId)
            ?.messages ?: return
        val answer = messages.getOrNull(index) ?: return
        val prompt = messages.take(index).lastOrNull { it.role == AiChatMessage.ROLE_USER }
        val provider = AiProvider.entries.firstOrNull { it.name == answer.provider }
        val sent = Support.email(
            this,
            "WM Keyboard: AI chat report",
            Support.aiGenerationReport(
                action = "Chat",
                provider = provider?.let { getString(it.labelRes) } ?: answer.provider.ifBlank { "(unknown)" },
                model = answer.model,
                input = prompt?.promptText().orEmpty(),
                output = answer.content,
            ),
        )
        if (!sent) {
            Toast.makeText(
                this,
                getString(R.string.ime_service_no_email_app_toast, Support.EMAIL),
                Toast.LENGTH_LONG,
            ).show()
        }
    }

    /** Runs an ask-each-run action with the instruction the user just typed. */
    fun onAiRunCustom() {
        val ai = _uiState.value.ai as? AiUi.CustomInput ?: return
        val instruction = ai.instruction.trim()
        if (instruction.isEmpty()) return
        vibrate()
        currentInputConnection?.let { commitComposing(it, autocorrect = false) }
        val input = aiInputText(ai.action)
        val source = input.text.trim()
        aiLastInstruction[ai.action.id] = instruction
        if (source.isNotEmpty()) {
            runAi(ai.action, source, instruction, fromSelection = input.fromSelection)
            return
        }
        if (!ai.action.worksWithoutText) {
            _uiState.update {
                it.copy(ai = AiUi.Error(ai.action, getString(R.string.ime_ai_error_no_text)))
            }
            return
        }
        // Nothing to transform, so the instruction is the whole request and the
        // model writes from nothing. Gated on the field being genuinely empty,
        // not on the flag alone: the prompt this takes carries no injection
        // guard, so field text must never reach it.
        runAi(ai.action, instruction, instruction, generated = true)
    }

    /**
     * The AI memory a keyboard AI run is handed, as a block for its system
     * prompt, or empty: see [AiMemoryRecall] for who gets it. [about] is what
     * the run is about, for picking the closest facts when there are many.
     * Off the main thread, since picking may embed the request.
     */
    private suspend fun aiMemoryFor(
        settings: KeyboardSettings,
        onDevice: Boolean,
        incognito: Boolean,
        about: List<String>,
    ): String = withContext(Dispatchers.IO) {
        val query = about.filter { it.isNotBlank() }.joinToString("\n")
        val recall = AiMemoryRecall.recall(this@WMKeyboardService, settings, onDevice, incognito, query)
        AiMemoryRecall.promptTail(recall, forChat = false, withTools = false)
    }

    /**
     * [system] with [memory] in front of it. In front, not after: an action's
     * prompt ends on what to reply with, and that has to stay the last word.
     */
    private fun withAiMemory(system: String, memory: String): String =
        if (memory.isBlank()) system else memory.trim() + "\n\n" + system

    /** Whether the AI panel's next run goes to the phone's own model. */
    private fun aiRunsOnDevice(settings: KeyboardSettings, offlineFirst: Boolean): Boolean =
        settings.ai.provider == AiProvider.ON_DEVICE || offlineFirst

    private fun runAi(
        action: AiActionSpec,
        source: String,
        instruction: String = "",
        generated: Boolean = false,
        fromSelection: Boolean = false,
    ) {
        // A password field's text never leaves the device, whatever the user
        // pressed. The guard [aiChatAttachmentFromField] already carries for
        // chat, applied to every AI run: the chips are greyed out in such a
        // field ([aiFieldHasText]), so this is the backstop.
        if (_uiState.value.secureField) return
        if (aiJob?.isActive == true) LocalLlmEngine.stop()
        aiJob?.cancel()
        // A downloaded on-device model the user asked to stand in for the
        // server (#452): tried first with no connection, and again if the
        // server turns out not to answer.
        val localStandIn = aiOfflineStandIn(_uiState.value.settings)
        val offlineFirst = localStandIn && !networkWatcher.state.value.online
        // Data saving, for the providers that are a request over the network.
        // An on-device model costs nothing to reach, so it is never held.
        val aiSettings = _uiState.value.settings.ai
        if (aiSettings.provider != AiProvider.ON_DEVICE && !offlineFirst) {
            val decision = dataSaverStatus.decide(MeteredFeature.CLOUD_AI)
            if (decision != MeteredDecision.ALLOWED) {
                _uiState.update {
                    it.copy(
                        ai = AiUi.Error(
                            action,
                            getString(
                                if (decision == MeteredDecision.ASK) {
                                    R.string.ime_ai_error_metered_ask
                                } else {
                                    R.string.ime_ai_error_metered_blocked
                                },
                            ),
                        ),
                    )
                }
                return
            }
        }
        val seq = ++aiRunSeq
        val startedAt = SystemClock.uptimeMillis()
        _uiState.update {
            it.copy(
                ai = AiUi.Loading(action, startedAtMs = startedAt),
                // An action can start from outside the panel (the selection
                // bar's AI buttons) while the panel was left on its chat (#280).
                // Its result has to be seen, so the panel shows the actions for
                // this opening; what the user chose stays saved.
                aiChat = if (it.aiChat.open) it.aiChat.copy(open = false, composing = false) else it.aiChat,
            )
        }
        aiJob = serviceScope.launch {
            val settings = _uiState.value.settings
            // Tools reach the network on their own account (#470), so a user
            // who is holding web search back on mobile data is holding the
            // model's searches back with it — the run itself still goes.
            val runner = AiToolRunner(applicationContext, settings, aiToolApprover(seq), aiToolHost(settings))
            val tools = if (dataSaverStatus.decide(MeteredFeature.WEB_SEARCH) == MeteredDecision.ALLOWED) {
                runner.tools()
            } else {
                emptyList()
            }
            val framed = when {
                // Writing from nothing: the request rides in the user message,
                // so the system prompt only has to frame it. No injection guard
                // here by design, which is why the callers only reach this with
                // an empty field.
                generated -> AiPrompts.generatePrompt()
                action.askEachRun -> AiPrompts.customPrompt(instruction)
                else -> AiPrompts.systemPrompt(action, settings.ai.translateTo)
            }
            // Read, never written: an action's input is the field's text,
            // which may be anyone's words, so nothing in it is taken as a fact
            // about the user. A fall back to the phone's model keeps what the
            // server was allowed, which is never more.
            val memory = aiMemoryFor(
                settings,
                onDevice = aiRunsOnDevice(settings, offlineFirst),
                incognito = _uiState.value.incognitoOn,
                about = listOf(instruction, source),
            )
            val system = withAiMemory(framed, memory)
            val config = AiClient.config(settings.ai)
            var fellBack = offlineFirst
            val result = withContext(Dispatchers.IO) {
                runCatching {
                    if (config.provider == AiProvider.ON_DEVICE || offlineFirst) {
                        runAiOnDevice(seq, action, source, system, settings, generated, fromSelection, tools, runner)
                    } else {
                        runAiRemote(
                            seq, action, source, system, settings, config,
                            startedAt, generated, fromSelection, tools, runner,
                        )
                    }
                }.recoverCatching { e ->
                    // Only a server that could not be reached, and only when a
                    // run on the device was not already the one that failed.
                    if (!localStandIn || fellBack || seq != aiRunSeq || !ToolHttp.isUnreachable(e)) throw e
                    fellBack = true
                    runAiOnDevice(seq, action, source, system, settings, generated, fromSelection, tools, runner)
                }
            }
            // A superseded or cancelled run never gets past here, so it is
            // never recorded either.
            if (seq != aiRunSeq) return@launch
            if (localStandIn && (fellBack || result.isSuccess)) noteOfflineFallback(OFFLINE_FALLBACK_AI, fellBack)
            // What the model looked up stays over the finished answer.
            val toolUses = aiToolsOf(_uiState.value.ai)
            val next = result.fold(
                onSuccess = { completion ->
                    val raw = completion.text
                    val text =
                        if (settings.ai.showThinking) raw.trim()
                        else AiThinking.stripped(raw)
                    when {
                        text.isNotBlank() -> AiUi.Ready(
                            action, text, source,
                            instruction = instruction,
                            generated = generated,
                            sourceFromSelection = fromSelection,
                            stripMarkdown = aiStripMarkdownDefault(),
                            truncated = completion.truncated,
                            showDiff = settings.ai.diffView &&
                                settings.ai.diffOpensFirst &&
                                aiDiffable(action, generated),
                            diffable = aiDiffable(action, generated),
                            tools = toolUses,
                        )
                        raw.isBlank() -> AiUi.Error(
                            action,
                            getString(R.string.ime_ai_error_empty_result),
                        )
                        else -> AiUi.Error(
                            action,
                            getString(R.string.ime_ai_error_only_reasoning),
                        )
                    }
                },
                onFailure = { e ->
                    AiUi.Error(action, requestErrorText(e, R.string.ime_ai_error_request_failed))
                },
            )
            _uiState.update { it.copy(ai = next) }
            recordAiHistory(
                action = action,
                source = source,
                instruction = instruction,
                settings = settings,
                config = config,
                state = next,
                reasoningChars = result.getOrNull()?.let { completion ->
                    (completion.text.length - AiThinking.stripped(completion.text).length)
                        .coerceAtLeast(0)
                } ?: 0,
                durationMs = SystemClock.uptimeMillis() - startedAt,
            )
        }
    }

    /**
     * Id of the record for the run on screen, so committing its answer can be
     * noted against it. Zero when the run was not recorded.
     */
    private var lastAiHistoryId = 0L

    /**
     * Writes one finished run to the history, if the user turned it on and this
     * field allows it.
     *
     * A failed run is recorded too, with the message the panel showed: "the AI
     * tool keeps failing" is the most likely reason anyone opens the screen, and
     * the message carries nothing the record does not already hold.
     */
    private fun recordAiHistory(
        action: AiActionSpec,
        source: String,
        instruction: String,
        settings: KeyboardSettings,
        config: AiClient.Config,
        state: AiUi,
        reasoningChars: Int,
        durationMs: Long,
    ) {
        lastAiHistoryId = 0L
        val allowed = AiHistoryGuard.shouldRecord(
            enabled = settings.ai.historyEnabled,
            unlocked = userUnlocked,
            secureField = _uiState.value.secureField,
            incognito = _uiState.value.incognitoOn,
        )
        if (!allowed) return
        val ready = state as? AiUi.Ready
        val error = (state as? AiUi.Error)?.message.orEmpty()
        val entry = AiHistoryEntry(
            id = 0,
            timestamp = System.currentTimeMillis(),
            actionId = action.id,
            actionName = aiActionLabel(action),
            provider = settings.ai.provider.name,
            // The model name only. The connection details that carry the key
            // are never part of a record.
            model = config.model,
            input = source,
            output = ready?.result.orEmpty(),
            durationMs = durationMs,
            instruction = instruction,
            reasoningChars = reasoningChars,
            streamed = config.provider != AiProvider.ON_DEVICE,
            error = error,
            truncated = ready?.truncated == true,
        )
        serviceScope.launch(Dispatchers.IO) {
            // The settings app holds its own instance of this store, so a
            // "Delete all history" over there has to be seen before writing or
            // it would come straight back.
            aiHistoryStore.reload()
            aiHistoryStore.trimTo(settings.ai.historyMax)
            lastAiHistoryId = aiHistoryStore.add(entry).id
            aiHistoryStore.save()
        }
    }

    /** Notes that the user put this answer into the field. */
    private fun noteAiCommitted(how: String) {
        val id = lastAiHistoryId
        if (id == 0L) return
        serviceScope.launch(Dispatchers.IO) {
            aiHistoryStore.markCommitted(id, how)
            aiHistoryStore.save()
        }
    }

    /**
     * Blocking on-device generation, streaming partial text into
     * [AiUi.Ready] with [AiUi.Ready.generating] set so the panel can render
     * the response as it forms. Call under [Dispatchers.IO].
     */
    /** A shipped action's translated name, or the name the user gave it. */
    /**
     * What the keyboard lends the AI's own tools (#698): its on-device
     * translator, reading the languages the user types in as its hints, the
     * app launcher's list, and the KDE Connect link.
     */
    private fun aiToolHost(settings: KeyboardSettings): KeyboardAiToolHost = KeyboardAiToolHost(
        applicationContext,
        hints = listOf(_uiState.value.language.id) + settings.enabledLanguages.map { it.id },
        kdeConnect = settings.kdeConnect,
        homePrefs = settings.homeAssistant,
        homes = settings.homes(),
        semantic = settings.semanticSearch,
    )

    private fun aiActionLabel(spec: AiActionSpec): String =
        BuiltInAiActions.labelRes(spec)?.let { getString(it) } ?: spec.name

    private fun runAiOnDevice(
        seq: Int,
        action: AiActionSpec,
        source: String,
        system: String,
        settings: KeyboardSettings,
        generated: Boolean,
        fromSelection: Boolean = false,
        tools: List<AiToolSpec> = emptyList(),
        runner: AiToolRunner = AiToolRunner(applicationContext, settings),
    ): AiClient.Completion {
        val modelId = effectiveLocalModelId(settings)
        val modelFile = effectiveLocalModelFile(settings)
            ?: throw IOException(getString(R.string.ime_ai_error_model_missing))
        val implicitThink = isReasoningModel(modelId)
        val startedAt = SystemClock.uptimeMillis()
        var lastPartialAt = 0L
        val text = AiToolLoop.run(
            system = system,
            turns = listOf(AiClient.ChatTurn(AiClient.ChatRole.USER, source)),
            tools = tools,
            // No on-device runtime offers function calling, so a local model
            // can only be told about tools in prose; see AiToolProtocol.
            native = false,
            executor = runner::run,
            maxRounds = settings.ai.toolMaxRounds,
            onPhase = { phase -> applyAiPhase(seq, phase) },
            onPartial = { raw ->
                val now = SystemClock.uptimeMillis()
                if (seq == aiRunSeq && now - lastPartialAt >= AI_PARTIAL_INTERVAL_MS) {
                    lastPartialAt = now
                    applyAiPartial(
                        seq, action, source, raw, settings,
                        implicitThink, startedAt, generated, fromSelection,
                    )
                }
            },
            onToolCall = { call -> applyAiTools(seq) { it + runner.activityFor(call) } },
            onToolResult = { result -> applyAiTools(seq) { AiToolActivity.record(it, result) } },
            isActive = { seq == aiRunSeq },
        ) { roundSystem, roundTurns, _, roundPartial ->
            AiClient.Completion(
                LocalLlmEngine.generate(
                    context = applicationContext,
                    modelFile = modelFile,
                    backend = settings.ai.localBackend,
                    contextTokens = settings.ai.localContextTokens,
                    system = roundSystem,
                    // The engine takes one user string, so a loop that has
                    // run a tool folds its rounds into a transcript.
                    user = AiClient.foldedPrompt("", roundTurns),
                    onPartial = roundPartial,
                ),
            )
        }.text
        // The on-device engine reports no stop reason, so an answer that ran out
        // of context window looks the same as one that finished. Never claim it
        // was cut off, rather than claiming it wrongly either way.
        return AiClient.Completion(text)
    }

    /**
     * Moves a still-loading run to [phase]. A partial may already have
     * promoted it to Ready, and a late phase report must not drag it back to
     * a spinner — which is also what makes "Using a tool" invisible once the
     * model has begun writing, correctly: the answer is more use than the step.
     */
    private fun applyAiPhase(seq: Int, phase: AiPhase) {
        if (seq != aiRunSeq) return
        _uiState.update {
            val loading = it.ai as? AiUi.Loading
            if (loading == null) it else it.copy(ai = loading.copy(phase = phase))
        }
    }

    /**
     * Rewrites the tool record of the run on screen, whichever view it is in:
     * a model that wrote "let me check" before searching is already showing
     * its streaming result, and the search belongs over that.
     */
    private fun applyAiTools(seq: Int, change: (List<AiToolActivity>) -> List<AiToolActivity>) {
        if (seq != aiRunSeq) return
        _uiState.update {
            if (seq != aiRunSeq) return@update it
            when (val ai = it.ai) {
                is AiUi.Loading -> it.copy(ai = ai.copy(tools = change(ai.tools)))
                is AiUi.Ready -> it.copy(ai = ai.copy(tools = change(ai.tools)))
                else -> it
            }
        }
    }

    /**
     * Asks the user, on the panel, before an MCP call whose tool says so
     * (#573). The question sits on the running call's line until
     * [answerAiTool] or a newer run.
     */
    private fun aiToolApprover(seq: Int): AiToolApprover = aiToolGate.approver(
        isActive = { seq == aiRunSeq },
        show = { ask -> applyAiTools(seq) { AiToolActivity.replaceRunning(it, ask) } },
        shown = { done -> applyAiTools(seq) { AiToolActivity.replaceRunning(it, done) } },
    )

    /**
     * The user's answer to a call that asked first, from the AI panel or the
     * keyboard's chat. Only one of the two can be asking at a time.
     */
    private fun answerAiTool(choice: AiToolApproval) {
        if (!aiToolGate.answer(choice)) AiChatController.answerTool(choice)
    }

    /** The tool record of the run on screen, to carry into the state that replaces it. */
    private fun aiToolsOf(ai: AiUi): List<AiToolActivity> = when (ai) {
        is AiUi.Loading -> ai.tools
        is AiUi.Ready -> ai.tools
        else -> emptyList()
    }

    /**
     * Streaming cloud/server generation. Same shape as [runAiOnDevice] — the
     * response is rendered as it forms — plus the connection phases, which
     * only a network request has. Call under [Dispatchers.IO].
     */
    private fun runAiRemote(
        seq: Int,
        action: AiActionSpec,
        source: String,
        system: String,
        settings: KeyboardSettings,
        config: AiClient.Config,
        startedAt: Long,
        generated: Boolean,
        fromSelection: Boolean = false,
        tools: List<AiToolSpec> = emptyList(),
        runner: AiToolRunner = AiToolRunner(applicationContext, settings),
    ): AiClient.Completion {
        var lastPartialAt = 0L
        return AiClient.completeWithTools(
            config = config,
            system = system,
            turns = listOf(AiClient.ChatTurn(AiClient.ChatRole.USER, source)),
            maxTokens = AiClient.effectiveMaxTokens(settings.ai),
            tools = tools,
            executor = runner::run,
            maxRounds = settings.ai.toolMaxRounds,
            onPhase = { phase -> applyAiPhase(seq, phase) },
            onPartial = { raw ->
                val now = SystemClock.uptimeMillis()
                if (seq == aiRunSeq && now - lastPartialAt >= AI_PARTIAL_INTERVAL_MS) {
                    lastPartialAt = now
                    // Cloud reasoning is wrapped in explicit <think> tags by
                    // AiClient, so it never needs the implicit-think fallback.
                    applyAiPartial(
                        seq, action, source, raw, settings,
                        implicitThink = false, startedAt, generated, fromSelection,
                    )
                }
            },
            onToolCall = { call -> applyAiTools(seq) { it + runner.activityFor(call) } },
            onToolResult = { result -> applyAiTools(seq) { AiToolActivity.record(it, result) } },
            // A superseded or closed run stops reading here rather than holding
            // the socket — and paying for tokens — until the model finishes.
            isActive = { seq == aiRunSeq },
        )
    }

    /**
     * Renders one streamed partial: reasoning keeps the progress view (with a
     * live character count, the only sign a silent reasoning model is alive),
     * and the first answer text switches the panel to the streaming result.
     */
    private fun applyAiPartial(
        seq: Int,
        action: AiActionSpec,
        source: String,
        raw: String,
        settings: KeyboardSettings,
        implicitThink: Boolean,
        startedAt: Long,
        generated: Boolean,
        fromSelection: Boolean = false,
    ) {
        // Reasoning models: keep the progress view (marked "thinking") until
        // real output starts, unless the user wants the raw stream.
        val shown = if (settings.ai.showThinking) {
            AiThinking.Split(raw, thinking = false)
        } else {
            AiThinking.split(raw, implicitThink)
        }
        _uiState.update {
            if (seq != aiRunSeq) return@update it
            it.copy(
                ai = when {
                    shown.output.isBlank() && shown.thinking -> AiUi.Loading(
                        action,
                        phase = AiPhase.THINKING,
                        thinkingChars = raw.length,
                        startedAtMs = startedAt,
                        tools = aiToolsOf(it.ai),
                    )
                    shown.output.isBlank() -> it.ai // nothing visible yet
                    // showDiff stays false while this streams: a half-finished
                    // result compares as "the whole tail was deleted", which
                    // would flash a block of red that then vanishes.
                    else -> AiUi.Ready(
                        action, shown.output, source,
                        generating = true,
                        sourceFromSelection = fromSelection,
                        stripMarkdown = (it.ai as? AiUi.Ready)?.stripMarkdown ?: true,
                        diffable = aiDiffable(action, generated),
                        tools = aiToolsOf(it.ai),
                    )
                },
            )
        }
    }

    /** Re-runs the last action on the text it originally saw. */
    fun onAiRetry() {
        when (val ai = _uiState.value.ai) {
            // Everything the prompt was built from rides on the state, so a
            // retry rebuilds exactly the same request.
            is AiUi.Ready -> {
                vibrate()
                runAi(ai.action, ai.sourceText, ai.instruction, ai.generated, ai.sourceFromSelection)
            }
            // A failed ask-each-run action reopens its input prefilled so the
            // user can adjust the instruction; onAiAction does exactly that.
            // A retry on the data-saver message means the same thing it means
            // on a media panel: yes, use the connection.
            is AiUi.Error -> {
                if (dataSaverStatus.decide(MeteredFeature.CLOUD_AI) == MeteredDecision.ASK) {
                    grantMetered(MeteredFeature.CLOUD_AI)
                }
                onAiAction(ai.action)
            }
            else -> {}
        }
    }

    /**
     * Puts the result into the field: in place of the text the action ran on,
     * or after it for an action that adds to the text rather than replacing it.
     * "Carry this on" is the case that needs the second one, where replacing
     * would delete the very text the user asked to have continued.
     */
    fun onAiReplace() {
        val ai = _uiState.value.ai as? AiUi.Ready ?: return
        vibrate()
        noteAiCommitted(AiHistoryEntry.COMMITTED_REPLACE)
        if (ai.action.insertMode == AiInsertMode.APPEND) {
            commitToField(aiInsertableText(ai))
            return
        }
        // A run on a selection replaces that selection, never the field
        // around it, and only while the selection is still what it ran on;
        // once it is gone the result goes in at the caret instead.
        if (ai.sourceFromSelection) {
            val now = currentInputConnection?.getSelectedText(0)?.toString()
            if (now != null && now.trim() == ai.sourceText.trim()) {
                rewriteSelection(aiInsertableText(ai))
            } else {
                commitToField(aiInsertableText(ai))
            }
            return
        }
        replaceFieldText(aiInsertableText(ai))
    }

    fun onAiInsert() {
        val ai = _uiState.value.ai as? AiUi.Ready ?: return
        vibrate()
        noteAiCommitted(AiHistoryEntry.COMMITTED_INSERT)
        commitToField(aiInsertableText(ai))
    }

    /**
     * "Report" on a result: opens a mail draft to the maintainer holding the
     * action, the model behind it, and the text either side of the generation.
     *
     * Nothing leaves the device here. The draft lands in the user's mail app,
     * where they can read every line of it — including their own text, which a
     * useful report has to quote — and edit or abandon it before sending. A
     * keyboard that can produce text on demand needs somewhere for the bad
     * results to go, and Play asks for exactly this on generated content.
     */
    fun onAiReport() {
        val state = _uiState.value
        val ai = state.ai as? AiUi.Ready ?: return
        vibrate()
        val sent = Support.email(
            this,
            "WM Keyboard: AI generation report",
            Support.aiGenerationReport(
                action = aiActionLabel(ai.action),
                provider = getString(state.settings.ai.provider.labelRes),
                model = AiClient.config(state.settings.ai).model,
                input = ai.sourceText,
                output = ai.result,
                instruction = ai.instruction,
            ),
        )
        if (!sent) {
            Toast.makeText(
                this,
                getString(R.string.ime_service_no_email_app_toast, Support.EMAIL),
                Toast.LENGTH_LONG,
            ).show()
        }
    }

    /**
     * Whether comparing this run's result with what it read means anything.
     *
     * An action that adds to the text read only what came before it, and a run
     * that wrote from nothing had no source text at all — its "source" is the
     * instruction. Comparing either would draw a wall of insertions.
     */
    private fun aiDiffable(action: AiActionSpec, generated: Boolean): Boolean =
        !generated &&
            action.insertMode == AiInsertMode.REPLACE &&
            action.inputMode == AiInputMode.FIELD

    /**
     * Carries the panel's "plain text" checkbox across runs: on by default,
     * but a user who turned it off means it for the next result too.
     */
    private fun aiStripMarkdownDefault(): Boolean =
        (_uiState.value.ai as? AiUi.Ready)?.stripMarkdown ?: true

    /** Panel's Result / Changes switch. */
    fun onAiSetShowDiff(show: Boolean) {
        val ai = _uiState.value.ai as? AiUi.Ready ?: return
        if (ai.showDiff == show) return
        vibrate()
        _uiState.update { it.copy(ai = ai.copy(showDiff = show)) }
    }

    /** Panel's "plain text" checkbox. */
    fun onAiToggleStripMarkdown() {
        val ai = _uiState.value.ai as? AiUi.Ready ?: return
        vibrate()
        _uiState.update { it.copy(ai = ai.copy(stripMarkdown = !ai.stripMarkdown)) }
    }

    /**
     * What Replace/Insert actually commit: even when the panel shows a
     * reasoning model's think block (verbose mode), only the trimmed answer
     * belongs in the text field — with markdown syntax removed unless the
     * user unchecked it.
     */
    private fun aiInsertableText(ai: AiUi.Ready): String {
        val answer = AiThinking.stripped(ai.result).ifBlank { ai.result.trim() }
        return if (ai.stripMarkdown) AiMarkdown.strip(answer) else answer
    }

    // ---- tools: vocabulary ----

    /** The merged pack index, swapped by reference off the main thread; null until loaded. */
    @Volatile
    private var vocabIndex: VocabIndex? = null

    /** Created blind (direct boot) and pointed at its file in [attachPersonalStores]. */
    private val vocabProgress = VocabProgress(null)
    private val vocabPrefs by lazy { VocabPrefs(this) }

    /** Typed words (lowercase) that already nudged in this field; see [retireVocabNudge]. */
    private val vocabRetired = mutableSetOf<String>()
    private var vocabSpeaker: VocabSpeaker? = null

    private fun vocabToday(): Int =
        TypingStatsMath.localEpochDay(System.currentTimeMillis(), TimeZone.getDefault())

    /**
     * Rebuilds the index when a pack or sidecar on disk changed (the settings
     * app downloads, imports, edits and deletes them) and re-reads the learning
     * record the settings app may have written. Token-guarded, so a call per
     * field focus costs a directory listing and nothing more.
     */
    private suspend fun reloadVocabIndex() {
        if (!userUnlocked) return
        if (ToolbarTool.VOCABULARY !in usableTools(_uiState.value.settings)) return
        val current = vocabIndex
        val settings = _uiState.value.settings
        // The glosses in the user's languages are triggers too, so the index
        // is keyed on them; it is the process's one copy, shared with the
        // settings app's screens.
        val codes = VocabLanguages.wantedCodes(settings.vocabulary.translationLangList, settings.enabledLanguages.map { it.id })
        val next = withContext(Dispatchers.IO) {
            vocabProgress.reloadIfChanged()
            // Without the cards: the keyboard reads them only when its panel
            // opens, and this runs on every field focus.
            VocabIndexCache.get(filesDir, codes, cards = false)
        }
        val available = !next.isEmpty
        // A fresh index arrives with its cards; the keyboard only wants them
        // while the vocabulary panel is up.
        if (_uiState.value.panel != PanelMode.VOCABULARY) next.releaseRecords()
        if (next !== current) {
            vocabIndex = next
            _uiState.update { it.copy(vocab = it.vocab.copy(available = available)) }
            if (_uiState.value.panel == PanelMode.VOCABULARY) refreshVocabViews()
        } else if (_uiState.value.vocab.available != available) {
            _uiState.update { it.copy(vocab = it.vocab.copy(available = available)) }
        }
    }

    /** Panel just opened: the chip's word, else the word at the cursor, else what was there. */
    private fun openVocabulary(prefillWord: String?) {
        val index = vocabIndex
        val word = prefillWord
            ?: currentWordForLookup()?.lowercase(Locale.ROOT)?.takeIf { index?.containsAnyForm(it) == true }
        when {
            word != null -> showVocabCard(word, push = false)
            _uiState.value.vocab.card is VocabCardUi.Ready -> Unit
            else -> _uiState.update { it.copy(vocab = it.vocab.copy(tab = VocabTab.BROWSE)) }
        }
        refreshVocabViews()
    }

    private fun vocabCardFor(record: VocabWord): VocabCardUi.Ready {
        val index = vocabIndex
        val state = vocabProgress.stateOf(record.word)
        val names = record.sources.map { id -> index?.sources?.get(id)?.name ?: id }
        val inMyList = index?.packs?.any { pack ->
            pack.id == VocabPacks.MY_WORDS_ID && pack.words.any { it.word == record.word }
        } == true
        return VocabCardUi.Ready(
            word = record,
            learnt = state.learnt,
            box = if (state.seen) state.box else null,
            sources = names,
            inMyList = inMyList,
        )
    }

    private fun showVocabCard(lemma: String, push: Boolean) {
        val index = vocabIndex ?: return
        val record = index.lookupAnyForm(lemma)
        _uiState.update {
            val current = (it.vocab.card as? VocabCardUi.Ready)?.word?.word
            val stack = if (push && current != null && current != record?.word) it.vocab.stack + current else it.vocab.stack
            it.copy(
                vocab = it.vocab.copy(
                    tab = VocabTab.CARD,
                    card = record?.let(::vocabCardFor) ?: VocabCardUi.NotFound(lemma),
                    stack = stack,
                ),
                panelFocus = null,
                mediaSearchActive = false,
            )
        }
    }

    fun onVocabOpen(word: String) {
        vibrate()
        showVocabCard(word, push = true)
    }

    fun onVocabBack() {
        vibrate()
        val stack = _uiState.value.vocab.stack
        if (stack.isEmpty()) {
            onPanelChange(PanelMode.VOCABULARY, haptic = false)
            return
        }
        _uiState.update { it.copy(vocab = it.vocab.copy(stack = stack.dropLast(1))) }
        showVocabCard(stack.last(), push = false)
    }

    fun onVocabTab(tab: VocabTab) {
        vibrate()
        _uiState.update {
            it.copy(vocab = it.vocab.copy(tab = tab), panelFocus = null, mediaSearchActive = false)
        }
        refreshVocabViews()
    }

    /**
     * Rebuilds the Browse rows and, unless a review session is under way, the
     * Review queue, off the main thread: a pack is a couple of thousand
     * records and the filter reads the learning record for each.
     */
    private fun refreshVocabViews() {
        val index = vocabIndex ?: return
        val today = vocabToday()
        serviceScope.launch(Dispatchers.Default) {
            val vocab = _uiState.value.vocab
            val browse = vocab.browse
            val pool = if (browse.packId != null) index.byPack(browse.packId) else index.allWords.toList()
            val learnt = pool.mapNotNullTo(HashSet()) { record -> record.word.takeIf { vocabProgress.isLearnt(it) } }
            val rows = when (browse.filter) {
                VocabBrowseFilter.ALL -> pool
                VocabBrowseFilter.UNLEARNT -> pool.filter { it.word !in learnt }
                VocabBrowseFilter.LEARNT -> pool.filter { it.word in learnt }
            }.sortedBy { it.word }
            val packs = index.packs.map { it.meta }
            val sessionLive = vocab.review.current != null
            val review = if (sessionLive) vocab.review else buildVocabReviewQueue(index, today)
            _uiState.update {
                it.copy(
                    vocab = it.vocab.copy(
                        browse = it.vocab.browse.copy(packs = packs, rows = rows, learnt = learnt),
                        review = review,
                    ),
                )
            }
        }
    }

    /** Everything due, then up to the daily goal of new words in a day-seeded shuffle. */
    private fun buildVocabReviewQueue(index: VocabIndex, today: Int): VocabReviewUi {
        val goal = _uiState.value.settings.vocabulary.dailyGoal
        val due = vocabProgress.dueWords(today, index.lemmas)
        val fresh = vocabProgress.unseen(index.lemmas).shuffled(java.util.Random(today.toLong())).take(goal)
        val queue = (due + fresh).mapNotNull { index.lookup(it) }
        return VocabReviewUi(queue = queue, total = queue.size)
    }

    fun onVocabInsert(text: String) {
        vibrate()
        val ic = currentInputConnection ?: return
        commitComposing(ic, autocorrect = false)
        ic.commitText(text, 1)
    }

    fun onVocabRelated(word: String) {
        when (_uiState.value.settings.vocabulary.relatedTap) {
            VocabRelatedTap.INSERT -> onVocabInsert(word)
            VocabRelatedTap.DICTIONARY_LOOKUP -> onVocabFullDictionary(word)
            VocabRelatedTap.OPEN_CARD_ELSE_INSERT ->
                if (vocabIndex?.containsAnyForm(word) == true) onVocabOpen(word) else onVocabInsert(word)
        }
    }

    fun onVocabMarkLearnt(word: String, learnt: Boolean) {
        vibrate()
        vocabProgress.markLearnt(word, learnt, vocabToday())
        vocabProgress.save()
        val card = _uiState.value.vocab.card
        if (card is VocabCardUi.Ready && card.word.word == word) {
            _uiState.update { it.copy(vocab = it.vocab.copy(card = vocabCardFor(card.word))) }
        }
        refreshVocabViews()
    }

    /** "Add to my list" on a card: the record goes into the "My words" pack, made on first use. */
    fun onVocabAddToList(word: String) {
        vibrate()
        val record = vocabIndex?.lookupAnyForm(word) ?: return
        addToMyWords(record)
    }

    private fun addToMyWords(record: VocabWord) {
        val langId = vocabIndex?.packOf(record.word)?.langId ?: "en"
        val name = getString(ToolsR.string.core_tools_vocab_my_words)
        serviceScope.launch {
            withContext(Dispatchers.IO) { VocabPacks.addToMyWords(filesDir, langId, record, name, 0, "") }
            reloadVocabIndex()
            val card = _uiState.value.vocab.card
            if (card is VocabCardUi.Ready && card.word.word == record.word) {
                _uiState.update { it.copy(vocab = it.vocab.copy(card = vocabCardFor(card.word))) }
            }
        }
    }

    /** The Dictionary panel's "Add to vocab" chip: a pack record if one exists, else the lookup on screen. */
    fun onDictionaryAddToVocab(word: String) {
        vibrate()
        val lemma = VocabPackFile.normalizeLemma(word) ?: return
        val entries = (_uiState.value.dictionary as? DictionaryUi.Ready)?.entries
        val record = vocabIndex?.lookupAnyForm(lemma)
            ?: entries?.let { VocabAutofill.fromDictionary(it, lemma) }
            ?: VocabWord(lemma)
        addToMyWords(record)
    }

    fun onVocabFlip() {
        vibrate()
        _uiState.update {
            it.copy(
                vocab = it.vocab.copy(review = it.vocab.review.copy(flipped = !it.vocab.review.flipped)),
                panelFocus = null,
            )
        }
    }

    fun onVocabReview(grade: ReviewGrade) {
        vibrate()
        val review = _uiState.value.vocab.review
        val current = review.current ?: return
        vocabProgress.review(current.word, grade, vocabToday(), _uiState.value.settings.vocabulary.scheduler)
        vocabProgress.save()
        _uiState.update {
            it.copy(
                vocab = it.vocab.copy(review = review.copy(index = review.index + 1, flipped = false, done = review.done + 1)),
                panelFocus = null,
            )
        }
    }

    /** The speaker button: Wiktionary's recording when the setting and the network allow, else the synthesiser. */
    fun onVocabSpeak(word: VocabWord) {
        val settings = _uiState.value.settings.vocabulary
        val url = word.audioFor(settings.accent)?.takeIf {
            settings.audioSource != VocabAudioSource.TTS &&
                dataSaverStatus.decide(MeteredFeature.VOCAB_AUDIO) == MeteredDecision.ALLOWED
        }
        val speaker = vocabSpeaker ?: VocabSpeaker(this).also { vocabSpeaker = it }
        // The speaker is shared: this word ends Read back's reading.
        if (_uiState.value.readingBack) _uiState.update { it.copy(readingBack = false) }
        speaker.speak(word.word, url, settings.ttsRate, settings.ttsPitch, settings.accent.locale)
    }

    /** The strip's word-of-the-day chip: stage the card; the strip then taps the tool. */
    fun onVocabDailyOpen() {
        val daily = _uiState.value.vocabDaily ?: return
        _uiState.update { it.copy(toolPrefill = ToolPrefill.Vocab(daily.word), vocabDaily = null) }
    }

    fun onVocabDailyDismiss() {
        vibrate()
        _uiState.value.vocabDaily?.let { vocabPrefs.chipDismissedSlot = it.slot }
        _uiState.update { it.copy(vocabDaily = null) }
    }

    fun onVocabFullDictionary(word: String) {
        _uiState.update { it.copy(toolPrefill = ToolPrefill.Lookup(word)) }
        onPanelChange(PanelMode.DICTIONARY)
    }

    fun onVocabBrowsePack(packId: String?) {
        vibrate()
        _uiState.update { it.copy(vocab = it.vocab.copy(browse = it.vocab.browse.copy(packId = packId)), panelFocus = null) }
        refreshVocabViews()
    }

    fun onVocabBrowseFilter(filter: VocabBrowseFilter) {
        vibrate()
        _uiState.update { it.copy(vocab = it.vocab.copy(browse = it.vocab.browse.copy(filter = filter)), panelFocus = null) }
        refreshVocabViews()
    }

    /** A nudge was shown and moved past: the cooldown setting says whether it may return. */
    private fun retireVocabNudge(typed: String) {
        val key = typed.lowercase(Locale.ROOT)
        when (_uiState.value.settings.vocabulary.cooldown) {
            VocabCooldown.EVERY_TIME -> Unit
            VocabCooldown.ONCE_PER_FIELD -> vocabRetired += key
            VocabCooldown.ONCE_PER_DAY -> {
                vocabRetired += key
                vocabPrefs.markNudged(vocabToday(), key)
            }
        }
    }

    /**
     * A new field may get the word-of-the-day chip: a few times per word
     * (the setting says how many), spread across the word's slot so one
     * field typed past does not lose the word, and never again once it was
     * dismissed. The draw itself is pinned in the learning record, so the
     * chip and the settings-home card agree.
     */
    private fun maybeOfferWordOfTheDay() {
        val state = _uiState.value
        val settings = state.settings.vocabulary
        if (!settings.wordOfTheDayChip || state.secureField || state.fieldNoSuggestions) return
        if (ToolbarTool.VOCABULARY !in usableTools(state.settings)) return
        val index = vocabIndex ?: return
        if (index.isEmpty) return
        val now = System.currentTimeMillis()
        val slot = WordOfDay.slot(now, TimeZone.getDefault(), settings.wordInterval)
        val minGap = settings.wordInterval.millis / (settings.chipTimesPerWord + 1)
        if (!vocabPrefs.mayOfferChip(slot, now, settings.chipTimesPerWord, minGap)) return
        val word = vocabProgress.wordOfTheDay(slot, index.lemmas) ?: return
        vocabProgress.save()
        vocabPrefs.recordChipShown(slot, now)
        _uiState.update { it.copy(vocabDaily = VocabDailyChip(word, slot)) }
    }

    private fun vocabCallbacks() = com.wasimaster.wmkeyboard.ime.ui.VocabCallbacks(
        onOpen = ::onVocabOpen,
        onBack = ::onVocabBack,
        onTab = ::onVocabTab,
        onInsert = ::onVocabInsert,
        onRelated = ::onVocabRelated,
        onMarkLearnt = ::onVocabMarkLearnt,
        onAddToList = ::onVocabAddToList,
        onFlip = ::onVocabFlip,
        onReview = ::onVocabReview,
        onSpeak = ::onVocabSpeak,
        onDailyOpen = ::onVocabDailyOpen,
        onDailyDismiss = ::onVocabDailyDismiss,
        onFullDictionary = ::onVocabFullDictionary,
        onDictionaryAddToVocab = ::onDictionaryAddToVocab,
        onBrowsePack = ::onVocabBrowsePack,
        onBrowseFilter = ::onVocabBrowseFilter,
    )

    // ---- tools: dictionary & camera ----

    private var dictionaryJob: Job? = null

    /**
     * Dictionary panel just opened: look up the selected word (or the word
     * around the cursor) per the auto-lookup setting; with nothing to look
     * up, drop straight into the search field so typing starts a query.
     */
    private fun openDictionary() {
        val word = if (_uiState.value.settings.dictionaryAutoLookup) currentWordForLookup() else null
        if (word != null) {
            onDictionaryLookup(word)
        } else if (_uiState.value.dictionary is DictionaryUi.Ready) {
            // No word at the cursor but a previous lookup is still on
            // screen — keep it; the search chip is one tap away.
        } else {
            updateQuery { it.copy(dictionarySearchActive = true, dictionaryQuery = "") }
        }
    }

    /** Selection first; else the run of word characters around the cursor. */
    private fun currentWordForLookup(): String? {
        val ic = currentInputConnection ?: return null
        fun sanitize(raw: String): String? {
            val word = raw.trim().trim('\'', '-', '“', '”', '"')
            return word.takeIf {
                it.isNotEmpty() && it.length <= 40 &&
                    it.any(Char::isLetter) &&
                    // The API is English-only; skip Bengali (or any
                    // non-Latin) words instead of showing "not found".
                    it.all { ch -> ch.code < 0x250 || ch == '’' }
            }
        }
        ic.getSelectedText(0)?.toString()?.let { return sanitize(it) }
        val before = ic.getTextBeforeCursor(48, 0)?.toString().orEmpty()
        val after = ic.getTextAfterCursor(48, 0)?.toString().orEmpty()
        fun isWordChar(c: Char) = c.isLetter() || c == '\'' || c == '’' || c == '-'
        return sanitize(before.takeLastWhile(::isWordChar) + after.takeWhile(::isWordChar))
    }

    fun onDictionaryLookup(rawWord: String) {
        val word = rawWord.trim()
        if (word.isEmpty()) {
            _uiState.update { it.copy(dictionarySearchActive = false) }
            return
        }
        dictionaryJob?.cancel()
        _uiState.update {
            it.copy(
                dictionaryQuery = word,
                dictionarySearchActive = false,
                dictionary = DictionaryUi.Loading(word),
            )
        }
        val settings = _uiState.value.settings
        // The Dictionary tool's provider list, rows that are off or cannot be asked left out;
        // in pick mode, only the row the panel's chooser is on.
        val sources = settings.resolveProviders(ProviderTool.DICTIONARY, pick = ProviderPicks.of(ProviderTool.DICTIONARY))
            .mapNotNull { DictionarySource.of(it.typeId) }
        if (sources.isEmpty()) {
            _uiState.update { it.copy(dictionary = DictionaryUi.NoSources) }
            return
        }
        val codes = VocabLanguages.wantedCodes(
            settings.vocabulary.translationLangList,
            settings.enabledLanguages.map { it.id },
        )
        val translationCodes = dictionaryTranslationCodes(settings)
        dictionaryJob = serviceScope.launch {
            // The packs' index is the vocabulary tool's when it has one
            // loaded; otherwise the same shared copy, read with the same codes
            // so the cache is not thrashed.
            val index = vocabIndex ?: if (DictionarySource.VOCAB_PACKS in sources && userUnlocked) {
                withContext(Dispatchers.IO) { VocabIndexCache.get(filesDir, codes) }.takeUnless { it.isEmpty }
            } else {
                null
            }
            val fetch = DictionaryLookup.fetcher({ index }, translationCodes)
            val ui = when (val result = DictionaryLookup.resolve(word, sources, fetch)) {
                is DictionaryLookup.Result.Found -> {
                    val translations = result.entries.firstOrNull()
                        ?.let { DictionaryLookup.translationsFor(it, translationCodes) }
                        .orEmpty()
                    DictionaryUi.Ready(
                        result.entries,
                        result.source,
                        dictionaryMeaning(result.entries.firstOrNull()?.word ?: word, index, codes, settings),
                        translations = translations,
                        translationsLoading = translations.isEmpty() &&
                            askWiktionaryForTranslations(result.source, translationCodes, settings),
                    )
                }
                DictionaryLookup.Result.NotFound -> DictionaryUi.NotFound(word)
                DictionaryLookup.Result.NotOnDevice -> DictionaryUi.NotOnDevice(word)
                DictionaryLookup.Result.Failed -> DictionaryUi.Error(word)
            }
            _uiState.update { it.copy(dictionary = ui) }
            // The source that answered had no translations (a pack, WordNet,
            // the free dictionary API): Wiktionary's page has them, so the
            // entry shows now and the translations follow it.
            if (ui is DictionaryUi.Ready && ui.translationsLoading) {
                val headword = ui.entries.first().word
                val found = withContext(Dispatchers.IO) { DictionaryLookup.translations(headword, translationCodes) }
                val rows = DictionaryLookup.translationsFor(ui.entries.first().copy(translations = found), translationCodes)
                _uiState.update { state ->
                    val current = state.dictionary as? DictionaryUi.Ready
                    if (current == null || current.entries !== ui.entries) {
                        state
                    } else {
                        state.copy(dictionary = current.copy(translations = rows, translationsLoading = false))
                    }
                }
            }
        }
    }

    /**
     * The languages the Dictionary tool translates a word into (#764): the
     * user's picks, else the keyboard's languages other than English. Empty
     * with translations off.
     */
    private fun dictionaryTranslationCodes(settings: KeyboardSettings): List<String> =
        com.wasimaster.wmkeyboard.ime.lookup.WordLookup.translationCodes(settings)

    /**
     * Whether an entry from [answered] should send its word on to Wiktionary
     * for translations: there are languages to ask for, Wiktionary is not
     * the source that already answered (its page carried them), and the user
     * left Wiktionary on in the tool's sources, so the word goes nowhere
     * they did not allow.
     */
    private fun askWiktionaryForTranslations(
        answered: DictionarySource,
        codes: List<String>,
        settings: KeyboardSettings,
    ): Boolean = com.wasimaster.wmkeyboard.ime.lookup.WordLookup.asksWiktionaryForTranslations(answered, codes, settings)

    /**
     * The looked-up word's meaning in the user's language (#651), when an
     * installed vocabulary pack has the word and a translation for it. Reads
     * the shared index only when the vocabulary tool is on and the card
     * shows translations in the keyboard; a word outside the packs gets none.
     */
    private suspend fun dictionaryMeaning(
        word: String,
        loaded: VocabIndex?,
        codes: List<String>,
        settings: KeyboardSettings,
    ): VocabMeaning? {
        val fields = VocabCardFields.resolve(settings.vocabulary.cardFields)
        if (fields[VocabCardField.TRANSLATIONS] != FieldVisibility.KEYBOARD) return null
        if (ToolbarTool.VOCABULARY !in usableTools(settings) || !userUnlocked) return null
        return withContext(Dispatchers.IO) {
            val index = loaded ?: VocabIndexCache.get(filesDir, codes).takeUnless { it.isEmpty } ?: return@withContext null
            val record = index.lookupAnyForm(word) ?: return@withContext null
            VocabLanguages.primaryMeaning(record, codes, settings.enabledLanguages.map { it.id })
        }
    }

    fun onDictionarySearchToggle() {
        vibrate()
        _uiState.update { it.copy(dictionarySearchActive = !it.dictionarySearchActive) }
    }

    /** Snippets panel search tapped (#471): route keys into [KeyboardUiState.snippetQuery]. */
    fun onSnippetSearchToggle() {
        vibrate()
        _uiState.update {
            val active = !it.snippetSearchActive
            // Closing the search clears it, so the folders and the whole list
            // are back the way the panel opened.
            it.copy(
                snippetSearchActive = active,
                snippetQuery = if (active) it.snippetQuery else "",
                panelFocus = null,
            )
        }
    }

    // ---- toolbox search and folders (#687, #709) ----

    private fun toolboxCallbacks() = com.wasimaster.wmkeyboard.ime.ui.ToolboxCallbacks(
        onSearchToggle = ::onToolboxSearchToggle,
        onFolderOpen = ::onToolboxFolderOpen,
        onRename = ::onToolboxFolderRename,
        onRenameDone = { onToolboxFolderRenameDone(keep = true) },
        onPinToggle = ::onToolboxFolderPinToggle,
        onUngroup = ::onToolboxFolderUngroup,
        onMerge = ::onToolboxMerge,
        onAddToFolder = ::onToolboxAddToFolder,
        onTakeOut = ::onToolboxFolderTakeOut,
        onFolderOrder = ::onToolboxFolderOrder,
    )

    /** The toolbox's search tapped (#687): route keys into [ToolboxUi.query], or close and clear it. */
    fun onToolboxSearchToggle() {
        vibrate()
        _uiState.update {
            val active = !it.toolboxView.searchActive
            // Searching lists every tool, folders or not, so it starts from the
            // top level; closing it puts the grid back the way the panel opened.
            it.copy(
                toolboxView = ToolboxUi(searchActive = active),
                panelFocus = null,
            )
        }
    }

    /** Enter in the toolbox search: close it and run the first tool it lists. */
    private fun onToolboxSearchEnter() {
        val first = com.wasimaster.wmkeyboard.ime.ui.toolboxSearchMatches(_uiState.value) { tool ->
            getString(com.wasimaster.wmkeyboard.ime.ui.toolLabelRes(tool))
        }.firstOrNull() ?: return
        _uiState.update { it.copy(toolboxView = ToolboxUi(), panelFocus = null) }
        onToolTap(first)
    }

    /**
     * Opens a toolbox folder (#709), from its cell in the grid or its button on
     * the toolbar, which opens the toolbox first; null goes back up a level.
     */
    fun onToolboxFolderOpen(id: String?) {
        if (id != null && _uiState.value.panel != PanelMode.TOOLBOX) {
            onPanelChange(PanelMode.TOOLBOX)
            if (_uiState.value.panel != PanelMode.TOOLBOX) return
        } else {
            vibrate()
        }
        _uiState.update { it.copy(toolboxView = ToolboxUi(folderOpen = id), panelFocus = null) }
    }

    /** The open folder's name tapped: the keys type a new one into it. */
    fun onToolboxFolderRename() {
        val state = _uiState.value
        val folder = state.settings.toolbox.folders.folderById(state.toolboxView.folderOpen) ?: return
        vibrate()
        _uiState.update {
            it.copy(
                toolboxView = it.toolboxView.copy(nameDraft = folder.name, searchActive = false, query = ""),
                panelFocus = null,
            )
        }
    }

    /** Ends a rename: [keep] saves the typed name unless it is blank; back drops it. */
    private fun onToolboxFolderRenameDone(keep: Boolean) {
        val state = _uiState.value
        val draft = state.toolboxView.nameDraft ?: return
        val id = state.toolboxView.folderOpen
        _uiState.update { it.copy(toolboxView = it.toolboxView.copy(nameDraft = null)) }
        val name = draft.trim().take(TOOLBOX_FOLDER_NAME_MAX)
        if (!keep || name.isEmpty() || id == null) return
        vibrate()
        serviceScope.launch {
            settingsRepository.updateToolboxFolders { folders ->
                folders.map { if (it.id == id) it.copy(name = name) else it }
            }
        }
    }

    /** Puts the folder on the toolbar, or takes it off. The tools inside stay where they are. */
    fun onToolboxFolderPinToggle(id: String) {
        vibrate()
        serviceScope.launch {
            settingsRepository.updateToolboxFolders { folders ->
                folders.map { if (it.id == id) it.copy(pinned = !it.pinned) else it }
            }
        }
    }

    /** Ungroups the folder: its tools go back to cells of their own, in the order they had. */
    fun onToolboxFolderUngroup(id: String) {
        vibrate()
        _uiState.update {
            if (it.toolboxView.folderOpen == id) it.copy(toolboxView = ToolboxUi(), panelFocus = null) else it
        }
        serviceScope.launch { settingsRepository.updateToolboxFolders { folders -> folders.filterNot { it.id == id } } }
    }

    /**
     * A tool dropped on another tool in the toolbox grid: the two become a
     * folder, or [dropped] joins [target]'s. The drag has already unpinned a
     * tool that came off the toolbar.
     */
    fun onToolboxMerge(dropped: ToolbarTool, target: ToolbarTool) {
        val name = getString(R.string.ime_toolbox_folder_default_name)
        placeToolboxToolAfter(dropped, target)
        serviceScope.launch {
            settingsRepository.updateToolboxFolders { it.withMerge(dropped, target, name) }
        }
    }

    /** A tool dropped on a folder's cell: filed at the end of that folder. */
    fun onToolboxAddToFolder(dropped: ToolbarTool, folderId: String) {
        val folder = _uiState.value.settings.toolbox.folders.folderById(folderId) ?: return
        placeToolboxToolAfter(dropped, folder.tools.last())
        serviceScope.launch { settingsRepository.updateToolboxFolders { it.withAdded(dropped, folderId) } }
    }

    /**
     * Moves [tool] to just after [anchor] in the toolbox order. A folder sits
     * where its first tool ranks, so without this a tool that ranked above the
     * one it was dropped on would carry the whole folder up to its own old
     * place, away from where the finger let go.
     */
    private fun placeToolboxToolAfter(tool: ToolbarTool, anchor: ToolbarTool) {
        val order = _uiState.value.settings.toolboxOrder
        val next = order.toMutableList().apply {
            remove(tool)
            val at = indexOf(anchor)
            add(if (at < 0) size else at + 1, tool)
        }
        if (next != order) onToolboxOrderChange(next) else vibrate()
    }

    /** A tool dragged out of the open folder onto its header: back to a cell of its own. */
    fun onToolboxFolderTakeOut(tool: ToolbarTool) {
        vibrate()
        val folders = _uiState.value.settings.toolbox.folders
        val folder = folders.folderOf(tool) ?: return
        // The last tool but one leaving dissolves the folder, so there is no
        // folder left to be standing in.
        if (folder.tools.size - 1 < TOOLBOX_FOLDER_MIN_TOOLS) {
            _uiState.update { it.copy(toolboxView = ToolboxUi(), panelFocus = null) }
        }
        serviceScope.launch { settingsRepository.updateToolboxFolders { it.withoutTool(tool) } }
    }

    /** The open folder's tools rearranged by a drag inside it. */
    fun onToolboxFolderOrder(id: String, tools: List<ToolbarTool>) {
        vibrate()
        serviceScope.launch {
            settingsRepository.updateToolboxFolders { folders ->
                folders.map { folder ->
                    if (folder.id != id) return@map folder
                    // Only the folder's own tools, each once, and none lost: a
                    // tool pinned to the bar is in the folder but not in the drag.
                    val kept = tools.filter { it in folder.tools }.distinct()
                    folder.copy(tools = kept + (folder.tools - kept.toSet()))
                }
            }
        }
    }

    /** Clipboard panel search bar tapped: route keys into [clipboardQuery]. */
    /**
     * The Clipboard search action (#612): the clipboard opens with its search
     * already taking the keys, or, already open there, closes the way a
     * second tap on a tool does. Turns the search bar on for good if it was
     * off: the action is that bar, a gesture away.
     */
    private fun onClipboardOpenSearching() {
        if (!isClipboardAccessible()) return
        val state = _uiState.value
        if (state.panel == PanelMode.CLIPBOARD && state.clipboardSearchActive) {
            onPanelChange(PanelMode.CLIPBOARD)
            return
        }
        if (!state.settings.clipboard.search) serviceScope.launch { settingsRepository.setClipboardSearch(true) }
        if (state.panel != PanelMode.CLIPBOARD) onPanelChange(PanelMode.CLIPBOARD)
        if (_uiState.value.panel != PanelMode.CLIPBOARD) return
        _uiState.update {
            it.copy(
                clipboardSearchActive = true,
                clipEdit = null,
                clipCombine = null,
                panelFocus = null,
            )
        }
    }

    fun onClipboardSearchToggle() {
        vibrate()
        _uiState.update {
            val active = !it.clipboardSearchActive
            // Closing search clears the filter so the full history is back.
            it.copy(
                clipboardSearchActive = active,
                clipboardQuery = if (active) it.clipboardQuery else "",
                panelFocus = null,
            )
        }
    }

    /** Insert chip on a dictionary entry: type the word into the editor. */
    fun onDictionaryInsert(word: String) {
        vibrate()
        val ic = currentInputConnection ?: return
        commitComposing(ic, autocorrect = false)
        ic.commitText(word, 1)
    }

    /**
     * Camera tool captured a photo: send it into the editor as an image, or,
     * with [search], search by it (#349).
     */
    fun onCameraSend(file: File, search: Boolean) {
        if (search) {
            searchByPhoto(file)
            return
        }
        vibrate()
        saveCaptureToGallery(file)
        commitImageFile(file, MediaMime.JPEG)
        // The photo is on its way (or on the clipboard) — the tool's job is
        // done, give the keys back.
        _uiState.update { it.copy(panel = PanelMode.NONE) }
    }

    /**
     * The last capture copied into the gallery. Search and then Send on the
     * same photo is one photo, and the gallery should get it once.
     */
    private var captureInGallery: File? = null

    private fun saveCaptureToGallery(file: File) {
        if (file == captureInGallery) return
        captureInGallery = file
        saveToGalleryIfEnabled(file, MediaMime.JPEG, _uiState.value.settings.camera.saveToGallery, "IMG")
    }

    // ---- search by photo (#349) ----

    private var photoSearchJob: Job? = null

    /**
     * The photo a data saver question is waiting on. The camera has no notice
     * to ask in, so the question goes in a toast, and pressing Search again on
     * the same photo is the yes.
     */
    private var photoSearchAsked: File? = null

    /**
     * Search on the camera's confirm step. Lens and the share sheet hand the
     * photo to another app and need no network of ours; the web route uploads
     * it and opens the site's results in the browser.
     *
     * The panel closes only once the search is on its way, so a search that
     * could not start leaves the photo up to try again, or to send instead.
     */
    private fun searchByPhoto(file: File) {
        vibrate()
        val camera = _uiState.value.settings.camera
        val started = when (camera.searchWith) {
            PhotoSearchTarget.LENS -> openPhotoInLens(file) || sharePhoto(file)
            PhotoSearchTarget.SHARE -> sharePhoto(file)
            PhotoSearchTarget.WEB -> {
                uploadPhotoForSearch(file, camera)
                return
            }
        }
        if (started) photoSearchStarted(file) else toast(R.string.ime_service_photo_search_no_app)
    }

    private fun photoSearchStarted(file: File) {
        photoSearchAsked = null
        saveCaptureToGallery(file)
        _uiState.update { it.copy(panel = PanelMode.NONE) }
    }

    /** An image share of [file], readable by whichever app takes it. */
    private fun photoShareIntent(file: File): Intent? {
        val uri = runCatching {
            FileProvider.getUriForFile(this, clipboardFileProviderAuthority, file)
        }.getOrNull() ?: return null
        return Intent(Intent.ACTION_SEND)
            .setType(MediaMime.JPEG)
            .putExtra(Intent.EXTRA_STREAM, uri)
            .addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
            // The grant travels on the clip, and a chooser copies it across.
            .apply { clipData = ClipData.newRawUri(null, uri) }
    }

    /**
     * Straight into Lens, through the Google app's own "search image" share
     * target. False when the Google app is not installed or takes no images,
     * which is every phone without Google's apps.
     */
    private fun openPhotoInLens(file: File): Boolean {
        val intent = photoShareIntent(file)?.setPackage(GOOGLE_APP_PACKAGE) ?: return false
        @Suppress("DEPRECATION")
        val targets = runCatching { packageManager.queryIntentActivities(intent, 0) }.getOrNull().orEmpty()
        // The Google app may list more than one image share; Lens is the one
        // that searches.
        val lens = targets.firstOrNull { it.activityInfo.name.contains("lens", ignoreCase = true) }
            ?: targets.firstOrNull()
            ?: return false
        intent.setClassName(lens.activityInfo.packageName, lens.activityInfo.name)
        return runCatching { startActivity(intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)) }.isSuccess
    }

    /** The Android share sheet, for any app that searches with a photo. */
    private fun sharePhoto(file: File): Boolean {
        val intent = photoShareIntent(file) ?: return false
        return startMacroActivity(intent, chooser = true)
    }

    private fun uploadPhotoForSearch(file: File, camera: CameraSettings) {
        if (photoSearchJob?.isActive == true) return
        when (dataSaverStatus.decide(MeteredFeature.WEB_SEARCH)) {
            MeteredDecision.ALLOWED -> Unit
            MeteredDecision.ASK -> {
                if (photoSearchAsked != file) {
                    photoSearchAsked = file
                    toast(R.string.ime_service_photo_search_metered_ask)
                    return
                }
                grantMetered(MeteredFeature.WEB_SEARCH)
            }
            MeteredDecision.BLOCKED -> {
                toast(R.string.ime_service_photo_search_blocked)
                return
            }
        }
        photoSearchAsked = null
        toast(R.string.ime_service_photo_search_sending)
        photoSearchJob = serviceScope.launch {
            val page = withContext(Dispatchers.IO) {
                runCatching {
                    val jpeg = photoSearchJpeg(file)
                    when (camera.searchEngine) {
                        PhotoSearchEngine.GOOGLE_LENS ->
                            ReverseImageClient.googleLens(jpeg, Locale.getDefault().toLanguageTag())
                        PhotoSearchEngine.BING -> ReverseImageClient.bing(jpeg)
                        PhotoSearchEngine.YANDEX -> ReverseImageClient.yandex(jpeg)
                        PhotoSearchEngine.TINEYE -> ReverseImageClient.tinEye(jpeg)
                        PhotoSearchEngine.CUSTOM ->
                            ReverseImageClient.custom(jpeg, camera.searchCustomUrl, camera.searchCustomField)
                    }
                }
            }
            page.fold(
                onSuccess = { url ->
                    val opened = runCatching {
                        startActivity(
                            Intent(Intent.ACTION_VIEW, Uri.parse(url)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK),
                        )
                    }.isSuccess
                    if (opened) photoSearchStarted(file) else toast(R.string.ime_service_photo_search_no_browser)
                },
                onFailure = { e ->
                    Toast.makeText(
                        this@WMKeyboardService,
                        ToolHttp.friendlyMessage(this@WMKeyboardService, e),
                        Toast.LENGTH_LONG,
                    ).show()
                },
            )
        }
    }

    /**
     * The photo to upload: at most 1280 px on its longest side. The sites
     * shrink a photo to about that before they search it, so anything larger
     * is upload that buys nothing, on what may be mobile data.
     */
    private fun photoSearchJpeg(file: File): ByteArray {
        val edge = 1280
        val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
        BitmapFactory.decodeFile(file.path, bounds)
        val longest = maxOf(bounds.outWidth, bounds.outHeight)
        if (longest <= edge) return file.readBytes()
        // Halved on the way in, never decoded whole. The bounds above already
        // say the picture is bigger than we want, and decoding it at full size
        // first was one allocation of width x height x 4 bytes in the
        // keyboard's process: 48 MB for an ordinary 12 MP photo and over 400 MB
        // for a 108 MP one, which is most of why this process could be seen
        // holding hundreds of megabytes. The sample stops while the long edge
        // still covers [edge], so scaling to it afterwards loses nothing — the
        // same shape as `decodeClipImage` in the scanner panels.
        var sample = 1
        while (longest / (sample * 2) >= edge) sample *= 2
        val options = BitmapFactory.Options().apply { inSampleSize = sample }
        val bitmap = BitmapFactory.decodeFile(file.path, options) ?: return file.readBytes()
        val decoded = maxOf(bitmap.width, bitmap.height)
        val scale = if (decoded <= edge) 1f else edge.toFloat() / decoded
        val scaled = if (scale >= 1f) {
            bitmap
        } else {
            Bitmap.createScaledBitmap(
                bitmap,
                (bitmap.width * scale).toInt().coerceAtLeast(1),
                (bitmap.height * scale).toInt().coerceAtLeast(1),
                true,
            )
        }
        if (scaled != bitmap) bitmap.recycle()
        return java.io.ByteArrayOutputStream().use { out ->
            scaled.compress(Bitmap.CompressFormat.JPEG, 88, out)
            scaled.recycle()
            out.toByteArray()
        }
    }

    /** IMEs cannot show permission dialogs; bounce through the trampoline. */
    fun onCameraPermissionRequest() {
        startActivity(
            Intent(this, CameraPermissionActivity::class.java).apply {
                addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
            }
        )
    }

    /**
     * Doc-scan tool: hand off to a full-screen scanner activity. ML Kit's
     * (edge detection, crop, filters — all Google's UI) where Play services
     * can run it and the user has not picked the built-in one; the built-in
     * OpenCV scanner ([com.wasimaster.wmkeyboard.app.PageScanActivity])
     * everywhere else. Either way the
     * scanned pages come back through [DocScanActivity.consumePendingPages]
     * in [onStartInputView], once the target app has focus again.
     */
    fun onDocScanStart() {
        vibrate()
        _uiState.update { it.copy(panel = PanelMode.NONE) }
        val google = BuildConfig.ENABLE_ML_KIT_SCANNERS && PlayServices.available &&
            !_uiState.value.settings.scanner.docBuiltIn
        startActivity(
            if (google) {
                Intent(this, DocScanActivity::class.java).apply {
                    addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                }
            } else {
                // Its library may still need fetching; it asks the way data
                // saver says to, which only the keyboard knows.
                com.wasimaster.wmkeyboard.app.PageScanActivity.intent(
                    this,
                    dataSaverStatus.decide(MeteredFeature.DOWNLOADS),
                )
            },
        )
    }

    /** OCR/QR tools: insert recognized text like a (long) key press. */
    fun onScannedTextInsert(text: String) {
        vibrate()
        val ic = currentInputConnection ?: return
        commitComposing(ic, autocorrect = false)
        ic.commitText(text, 1)
    }

    /** Hand a scanned QR/barcode's text to another app (#987). */
    fun onScannedTextShare(text: String) {
        vibrate()
        shareVia(
            Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT, text),
            insertable = true,
        )
    }

    /** Open a scanned QR/barcode URL in the browser (leaves the keyboard). */
    fun onScannedUrlOpen(url: String) {
        vibrate()
        runCatching {
            startActivity(
                Intent(Intent.ACTION_VIEW, Uri.parse(url)).apply {
                    addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                },
            )
        }
    }

    // ---- translate / gif / sticker / web & image search tools ----

    /** Whether the web/image search tools have a backend to ask. */
    private fun hasSearchKey(): Boolean =
        ToolApiKeys.hasSearchProvider(_uiState.value.settings)

    /** Search-bar tap on a media panel: toggle typing-into-the-query mode. */
    fun onMediaQueryTap() {
        vibrate()
        _uiState.update { it.copy(mediaSearchActive = !it.mediaSearchActive, mediaAction = null) }
    }

    /**
     * The query behind the search results the panel would reopen on, or null
     * when there are none to keep: the open tab's first, else the other's.
     * Results live in memory only, until a new search or the clear button
     * replaces them (#347).
     */
    private fun keptSearchQuery(state: KeyboardUiState): String? {
        if (!ToolApiKeys.hasSearchProvider(state.settings)) return null
        val web = (state.webSearch as? WebSearchUi.Ready)?.query
        val images = (state.imageSearch as? ImageSearchUi.Ready)?.query
        return if (state.searchTab == SearchTab.IMAGES) images ?: web else web ?: images
    }

    /**
     * The web and image search tools (#879): one panel, opened on [tab]. While
     * the panel is up on that tab this closes it, as any tool's second press
     * does; on the other tab it switches over.
     */
    private fun openSearchTab(tab: SearchTab, haptic: Boolean = true) {
        val state = _uiState.value
        if (state.panel == PanelMode.WEB_SEARCH && state.searchTab != tab) {
            onSearchTab(tab)
            return
        }
        if (state.panel != PanelMode.WEB_SEARCH) _uiState.update { it.copy(searchTab = tab) }
        onPanelChange(PanelMode.WEB_SEARCH, haptic)
    }

    /**
     * A tab of the search panel tapped (#879). The query already searched is
     * searched on the new tab too, unless that tab holds its results already
     * or the box is still being typed into.
     */
    fun onSearchTab(tab: SearchTab) {
        val state = _uiState.value
        if (state.searchTab == tab) return
        vibrate()
        _uiState.update { it.copy(searchTab = tab, panelFocus = null) }
        val query = state.mediaQuery.trim()
        if (query.isEmpty() || state.mediaSearchActive) return
        val (shown, loading) = when (tab) {
            SearchTab.ALL -> (state.webSearch as? WebSearchUi.Ready)?.takeIf { it.category == searchCategory(state) }
                ?.query to (state.webSearch == WebSearchUi.Loading)
            SearchTab.IMAGES -> (state.imageSearch as? ImageSearchUi.Ready)?.query to (state.imageSearch == ImageSearchUi.Loading)
        }
        if (shown != query && !loading) runSearch(tab, query)
    }

    /**
     * A SearXNG category chip tapped (#934), or All for [category] null: the
     * All tab, searching in that category. The query already searched is
     * searched again there, as a tab change does.
     */
    fun onSearchCategory(category: String?) {
        val state = _uiState.value
        if (state.searchTab == SearchTab.ALL && state.searchCategory == category) return
        vibrate()
        _uiState.update { it.copy(searchTab = SearchTab.ALL, searchCategory = category, panelFocus = null) }
        val query = state.mediaQuery.trim()
        if (query.isEmpty() || state.mediaSearchActive) return
        val now = _uiState.value
        val shown = (now.webSearch as? WebSearchUi.Ready)?.takeIf { it.category == searchCategory(now) }?.query
        if (shown != query) runWebSearch(query)
    }

    /**
     * The category the All tab searches in (#934): the chip picked, while it
     * is still one of the chosen and a SearXNG instance is the one asked.
     * Null is the general search.
     */
    private fun searchCategory(state: KeyboardUiState): String? =
        state.searchCategory?.takeIf {
            it in state.settings.webSearch.searxCategories &&
                SearchProviders.searxFirst(state.settings, ProviderPicks.of(ProviderTool.SEARCH))
        }

    /**
     * More results at the end of the open tab (#879): the same search again,
     * for its next page, added under what is shown. Pressed again, it fetches
     * the page after; when one brings nothing new the button goes. A failure
     * keeps what is shown and says why in a toast.
     */
    fun onSearchMore() {
        val state = _uiState.value
        if (state.panel != PanelMode.WEB_SEARCH) return
        if (dataSaverStatus.decide(MeteredFeature.WEB_SEARCH) != MeteredDecision.ALLOWED) {
            toast(R.string.ime_service_search_more_metered)
            return
        }
        vibrate()
        when (state.searchTab) {
            SearchTab.ALL -> loadMoreWeb(state.webSearch as? WebSearchUi.Ready ?: return)
            SearchTab.IMAGES -> loadMoreImages(state.imageSearch as? ImageSearchUi.Ready ?: return)
        }
    }

    private fun loadMoreWeb(shown: WebSearchUi.Ready) {
        if (shown.loadingMore || shown.noMore) return
        val settings = _uiState.value.settings
        val more = SearchMore(shown.page + 1, shown.results.map { searchDomain(it.url) })
        _uiState.update { it.copy(webSearch = shown.copy(loadingMore = true)) }
        webSearchJob = serviceScope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching {
                    SearchProviders.web(
                        settings,
                        shown.query,
                        settings.webSearch.resultCount,
                        settings.webSearch.safe,
                        answer = false,
                        pick = ProviderPicks.of(ProviderTool.SEARCH),
                        more = more,
                        category = shown.category,
                    )
                }
            }
            val now = _uiState.value.webSearch as? WebSearchUi.Ready
            // A new search or a cleared bar while this was out: it is no longer wanted.
            if (now == null || now.query != shown.query) return@launch
            result.onFailure { toast(requestErrorText(it, R.string.ime_service_search_error)) }
            val seen = now.results.mapTo(HashSet()) { it.url }
            val added = result.getOrNull()?.results.orEmpty().filter { seen.add(it.url) }
            _uiState.update {
                it.copy(
                    webSearch = now.copy(
                        results = now.results + added,
                        page = if (result.isSuccess) more.page else now.page,
                        loadingMore = false,
                        noMore = result.isSuccess && added.isEmpty(),
                    ),
                )
            }
        }
    }

    private fun loadMoreImages(shown: ImageSearchUi.Ready) {
        if (shown.loadingMore || shown.noMore) return
        val settings = _uiState.value.settings
        val more = SearchMore(
            shown.page + 1,
            shown.results.map { searchDomain(it.contextUrl.ifEmpty { it.imageUrl }) },
        )
        _uiState.update { it.copy(imageSearch = shown.copy(loadingMore = true)) }
        imageSearchJob = serviceScope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching {
                    SearchProviders.images(
                        settings,
                        shown.query,
                        settings.webSearch.resultCount,
                        settings.webSearch.safe,
                        pick = ProviderPicks.of(ProviderTool.SEARCH),
                        more = more,
                    )
                }
            }
            val now = _uiState.value.imageSearch as? ImageSearchUi.Ready
            if (now == null || now.query != shown.query) return@launch
            result.onFailure { toast(requestErrorText(it, R.string.ime_service_search_error)) }
            val seen = now.results.mapTo(HashSet()) { it.imageUrl }
            val added = result.getOrNull().orEmpty().filter { seen.add(it.imageUrl) }
            _uiState.update {
                it.copy(
                    imageSearch = now.copy(
                        results = now.results + added,
                        page = if (result.isSuccess) more.page else now.page,
                        loadingMore = false,
                        noMore = result.isSuccess && added.isEmpty(),
                    ),
                )
            }
        }
    }

    /** Insert on the engine's answer or one of its code blocks (#879). */
    fun onSearchInsertText(text: String) {
        vibrate()
        commitToField(text)
    }

    /** Copy in the search panel (#879): the engine's answer, or a result's link. */
    fun onSearchCopy(text: String) {
        vibrate()
        KeyboardClipboard.copy(this, text)
        maybeToastCopied()
    }

    /** The site of [url] as Tavily's `exclude_domains` takes it: the host, without "www.". */
    private fun searchDomain(url: String): String =
        url.substringAfter("://").substringBefore('/').substringBefore(':').removePrefix("www.")

    /** Runs [query] on the search panel's [tab]. */
    private fun runSearch(tab: SearchTab, query: String) = when (tab) {
        SearchTab.ALL -> runWebSearch(query)
        SearchTab.IMAGES -> runImageSearch(query)
    }

    /**
     * The clear button in the web/image, GIF and sticker search bars: drops
     * the kept results and the query, and hands the keys to the search box for
     * a new search. GIF and sticker go back to trending (#907).
     */
    fun onMediaQueryClear() {
        vibrate()
        val panel = _uiState.value.panel
        if (panel == PanelMode.WEB_SEARCH) {
            webSearchJob?.cancel()
            imageSearchJob?.cancel()
        }
        if (panel == PanelMode.GIF || panel == PanelMode.STICKER) {
            mediaLiveSearchJob?.cancel()
            captureComposition = null
        }
        val idle = hasSearchKey()
        _uiState.update {
            it.copy(
                mediaQuery = "",
                mediaSearchActive = true,
                mediaAction = null,
                panelFocus = null,
                webSearch = if (panel == PanelMode.WEB_SEARCH && idle) WebSearchUi.Idle else it.webSearch,
                imageSearch = if (panel == PanelMode.WEB_SEARCH && idle) ImageSearchUi.Idle else it.imageSearch,
            )
        }
        if (panel == PanelMode.GIF || panel == PanelMode.STICKER) refreshMedia("")
    }

    /**
     * GIF/sticker searches are cheap on KLIPY/GIPHY, so results follow the
     * query live. Web/image search waits for enter — the free Programmable
     * Search tier is 100 queries a day.
     */
    private fun scheduleMediaLiveSearch() {
        val state = _uiState.value
        // Translate is free-tier friendly too: its result follows the typed
        // query live, on its own (400 ms) debounce.
        if (state.panel == PanelMode.TRANSLATE) {
            scheduleTranslate()
            return
        }
        if (state.panel != PanelMode.GIF && state.panel != PanelMode.STICKER) return
        mediaLiveSearchJob?.cancel()
        val query = state.mediaQuery.trim()
        mediaLiveSearchJob = serviceScope.launch {
            delay(450)
            refreshMedia(query)
        }
    }

    /** Enter (or the search action) in a media panel's search box. */
    private fun runMediaSearch() {
        val state = _uiState.value
        val query = state.mediaQuery.trim()
        _uiState.update { it.copy(mediaSearchActive = false) }
        when (state.panel) {
            PanelMode.GIF, PanelMode.STICKER -> {
                mediaLiveSearchJob?.cancel()
                refreshMedia(query)
            }
            PanelMode.WEB_SEARCH -> runSearch(state.searchTab, query)
            PanelMode.WIKIPEDIA -> runWikiSearch(query)
            PanelMode.TRANSLATE -> scheduleTranslate(immediate = true)
            else -> {}
        }
    }

    /** Retry button on media/search panels: re-run whatever failed. */
    fun onMediaRetry() {
        vibrate()
        // A retry on a data-saver notice is the user saying yes to the fetch,
        // so it grants first and then falls through to make it.
        grantMeteredForPanel(_uiState.value)
        when (_uiState.value.panel) {
            PanelMode.GIF, PanelMode.STICKER -> refreshMedia(_uiState.value.mediaQuery.trim())
            PanelMode.WEB_SEARCH -> runSearch(_uiState.value.searchTab, _uiState.value.mediaQuery.trim())
            PanelMode.WIKIPEDIA -> {
                val query = _uiState.value.mediaQuery.trim()
                if (query.isNotEmpty()) runWikiSearch(query)
                else _uiState.update { it.copy(wiki = WikiUi.Idle, mediaSearchActive = true) }
            }
            PanelMode.TRANSLATE -> scheduleTranslate(immediate = true)
            else -> {}
        }
    }

    /**
     * Fetches GIFs or stickers for [query] from every active provider
     * (blank query = trending).
     */
    private fun refreshMedia(query: String) {
        val state = _uiState.value
        val sticker = state.panel == PanelMode.STICKER
        if (!sticker && state.panel != PanelMode.GIF) return
        val setUi: (MediaUi) -> Unit = { ui ->
            _uiState.update { if (sticker) it.copy(sticker = ui) else it.copy(gif = ui) }
        }
        val settings = state.settings
        // The favourites and recent chips (#597) are the panel's own lists:
        // no provider, no key and no network to ask. A typed query ends them
        // (see updateQuery), so a blank one is the only one they see here.
        val collection = state.mediaCategory?.takeIf { !sticker && MediaCategories.isCollection(it) }
        if (collection != null) {
            if (collection == MediaCategories.RECENT && !settings.gif.recentGifs) {
                // Turned off since the panel last showed it: back to trending.
                _uiState.update { it.copy(mediaCategory = null) }
            } else {
                showGifCollection(collection)
                return
            }
        }
        // The user's list for the tool, rows that are off or cannot be asked
        // left out. Stickers start with the user's own packs, which need no
        // key, so it is usually the GIF tool that can end up with nothing.
        val sources = MediaProviders.targets(settings, sticker)
        if (sources.isEmpty()) {
            setUi(MediaUi.NeedKey)
            return
        }
        val mode = MediaProviders.mode(settings, sticker)
        val targets = GifSources.targets(sources, state.mediaProvider, mode)
        if (mode == ChainMode.TABS) {
            val selected = targets.first().key
            if (selected != state.mediaProvider) _uiState.update { it.copy(mediaProvider = selected) }
        }
        // Data saving. Only the online providers count: the user's own sticker
        // packs and imported GIF packs are files on disk, and a panel that
        // refused to show them on mobile data would be refusing to open a folder.
        if (targets.any { !it.onDevice }) {
            val decision = dataSaverStatus.decide(MeteredFeature.MEDIA_SEARCH)
            if (decision != MeteredDecision.ALLOWED) {
                mediaFetchJob?.cancel()
                setUi(MediaUi.Metered(canAllow = decision == MeteredDecision.ASK))
                return
            }
        }
        mediaFetchJob?.cancel()
        setUi(MediaUi.Loading)
        val panel = state.panel
        mediaFetchJob = serviceScope.launch {
            // One at a time: the first provider with something to show is the
            // grid, and the next is asked only when it fails or has nothing.
            if (mode == ChainMode.FALLBACK && targets.size > 1) {
                val outcome = withContext(Dispatchers.IO) {
                    ProviderRunner.fallback(
                        targets,
                        key = { it.key },
                        isEmpty = { items: List<GifItem> -> items.isEmpty() },
                    ) { target -> fetchGifs(target, query, sticker, settings) }
                }
                if (_uiState.value.panel != panel) return@launch
                setUi(
                    when (outcome) {
                        is ProviderRunner.Outcome.Found -> MediaUi.Ready(outcome.value.take(settings.gif.resultLimit), query)
                        ProviderRunner.Outcome.NotFound -> MediaUi.Ready(emptyList(), query)
                        is ProviderRunner.Outcome.Failed -> MediaUi.Error(
                            outcome.error?.let { ToolHttp.friendlyMessage(this@WMKeyboardService, it) }
                                ?: getString(R.string.ime_service_media_fetch_error),
                        )
                    },
                )
                return@launch
            }
            val results = withContext(Dispatchers.IO) {
                ProviderRunner.all(targets, key = { it.key }) { target -> fetchGifs(target, query, sticker, settings) }
            }.map { it.second }
            if (_uiState.value.panel != panel) return@launch
            val successes = results.mapNotNull { it.getOrNull() }
            setUi(
                if (successes.isEmpty()) {
                    MediaUi.Error(
                        results.firstNotNullOfOrNull { it.exceptionOrNull() }
                            ?.let { ToolHttp.friendlyMessage(this@WMKeyboardService, it) }
                            ?: getString(R.string.ime_service_media_fetch_error),
                    )
                } else {
                    val merged = GifSources.interleave(successes)
                    // The limit is per fetch: in mixed mode each provider
                    // returns up to the limit, so cap the merged grid back
                    // down to it. The user's own packs are never truncated.
                    val limited = if (targets.all { it.onDevice }) {
                        merged
                    } else {
                        merged.take(settings.gif.resultLimit)
                    }
                    MediaUi.Ready(limited, query)
                },
            )
        }
    }

    /**
     * Blocking; call on an IO dispatcher. A target with backups (a second
     * key of the same kind, kept as one provider) hands the query to the next
     * of them when it fails or has nothing.
     */
    private fun fetchGifs(
        target: MediaTarget,
        query: String,
        sticker: Boolean,
        settings: com.wasimaster.wmkeyboard.core.settings.KeyboardSettings,
    ): List<GifItem> {
        if (target.backups.isEmpty()) return fetchGifsFrom(target, query, sticker, settings)
        val outcome = ProviderRunner.fallback(
            target.withBackups,
            key = { it.key },
            isEmpty = { items: List<GifItem> -> items.isEmpty() },
        ) { fetchGifsFrom(it, query, sticker, settings) }
        return when (outcome) {
            is ProviderRunner.Outcome.Found -> outcome.value
            ProviderRunner.Outcome.NotFound -> emptyList()
            is ProviderRunner.Outcome.Failed -> throw checkNotNull(outcome.error)
        }
    }

    /** Blocking provider dispatch; call on an IO dispatcher. */
    private fun fetchGifsFrom(
        target: MediaTarget,
        query: String,
        sticker: Boolean,
        settings: com.wasimaster.wmkeyboard.core.settings.KeyboardSettings,
    ): List<GifItem> = when (target.source) {
        GifSource.KLIPY -> KlipyClient.search(
            query, target.apiKey, sticker, settings.gif.contentFilter,
            limit = settings.gif.resultLimit,
        )
        GifSource.GIPHY -> GiphyClient.search(
            query, target.apiKey, sticker, settings.gif.contentFilter,
            limit = settings.gif.resultLimit,
        )
        GifSource.LOCAL ->
            meaningStickers(query, _uiState.value.stickerPackId, stickerPackStore.searchAsGifItems(query, _uiState.value.stickerPackId))
        GifSource.OFFLINE ->
            if (sticker) emptyList()
            else com.wasimaster.wmkeyboard.core.tools.offlinegif.OfflineGifPacks.search(query, OFFLINE_GIF_LIMIT)
        // Commons has no sticker corpus at all, so the sticker tab stays empty
        // rather than answering it with animations that are not stickers.
        GifSource.COMMONS ->
            if (sticker) emptyList()
            else CommonsClient.searchGifs(
                query,
                limit = settings.gif.resultLimit,
                // Blank is Wikimedia Commons itself; a row of its own is another wiki.
                endpoint = target.url,
            )
        // GIF-only: the sticker list never offers it.
        GifSource.GIFCITIES ->
            if (sticker) emptyList()
            else com.wasimaster.wmkeyboard.core.tools.GifCitiesClient.search(query, limit = settings.gif.resultLimit)
    }

    /** Provider chip on the GIF/sticker panel; [key] is the provider row's. */
    fun onGifSourceSelect(key: String) {
        vibrate()
        if (_uiState.value.mediaProvider == key) return
        _uiState.update { it.copy(mediaProvider = key, mediaAction = null, stickerPackId = null) }
        refreshMedia(_uiState.value.mediaQuery.trim())
        // Categories belong to a provider, so the row follows the chip.
        refreshMediaCategories()
    }

    /**
     * Fills the category row for the panel's default view.
     *
     * A function of the provider and the panel, never of the query: that is
     * what keeps a keystroke from costing a request. Called on panel open and
     * on a provider switch, and nowhere else — not from the live-search
     * debounce, the enter search, retry, or the pack filter.
     *
     * The bundled list goes up straight away, before anything is fetched. The
     * row has to be there in the first frame; a row that pops in a second
     * later reflows the grid under the user's finger.
     */
    private fun refreshMediaCategories() {
        val state = _uiState.value
        val sticker = state.panel == PanelMode.STICKER
        if (!sticker && state.panel != PanelMode.GIF) return
        val settings = state.settings
        val sources = MediaProviders.targets(settings, sticker)
        val mode = MediaProviders.mode(settings, sticker)
        // One provider, not every target: two taxonomies interleaved are a
        // row of near-duplicates for twice the requests. Local packs have no
        // categories at all — the pack chips are their equivalent.
        val target = GifSources.targets(sources, state.mediaProvider, mode)
            .firstOrNull { it.source != GifSource.LOCAL }
        if (target == null) {
            _uiState.update { it.copy(mediaCategories = emptyList(), mediaCategory = null) }
            return
        }
        _uiState.update { it.copy(mediaCategories = MediaCategories.bundled(sticker)) }
        mediaCategoryJob?.cancel()
        val panel = state.panel
        mediaCategoryJob = serviceScope.launch {
            // Imported packs change under the cache's day-long lifetime, and
            // reading their categories costs a query, not a request.
            val cached = if (target.source == GifSource.OFFLINE) {
                null
            } else {
                MediaCategoryCache.get(target.source, sticker, System.currentTimeMillis())
            }
            val fetched = cached ?: withContext(Dispatchers.IO) {
                runCatching { fetchCategories(target, sticker) }
            }.onSuccess {
                // Cache the empty answer too: a provider with no categories
                // endpoint is then asked once a day, not once per open. Only
                // on success — a cancelled fetch must not poison the entry.
                MediaCategoryCache.put(target.source, sticker, it, System.currentTimeMillis())
            }.getOrNull()
            if (_uiState.value.panel != panel) return@launch
            _uiState.update {
                it.copy(mediaCategories = MediaCategories.normalise(fetched.orEmpty(), sticker))
            }
        }
    }

    /** Blocking provider dispatch; call on an IO dispatcher. */
    private fun fetchCategories(
        target: MediaTarget,
        sticker: Boolean,
    ): List<MediaCategory> = when (target.source) {
        GifSource.KLIPY -> KlipyClient.categories(target.apiKey, sticker)
        GifSource.GIPHY -> GiphyClient.categories(target.apiKey, sticker)
        GifSource.LOCAL -> emptyList()
        // No category endpoint: Commons is a search index, not a curated feed.
        GifSource.COMMONS -> emptyList()
        // No categories either; the bundled row stands in.
        GifSource.GIFCITIES -> emptyList()
        GifSource.OFFLINE -> com.wasimaster.wmkeyboard.core.tools.offlinegif.OfflineGifPacks.categories()
    }

    /** Category chip in the GIF/sticker default view: runs it as a search. */
    fun onGifCategorySelect(term: String) {
        vibrate()
        val state = _uiState.value
        if (state.panel != PanelMode.GIF && state.panel != PanelMode.STICKER) return
        // A category is a search, so it cancels a debounce that would land
        // 450 ms later and overwrite the grid with a half-typed query.
        mediaLiveSearchJob?.cancel()
        val next = term.trim().takeIf { it.isNotEmpty() && it != state.mediaCategory }
        _uiState.update {
            it.copy(
                mediaCategory = next,
                // The search pill reads back what the grid is showing, so a
                // category shows as the search that it is. Favourites and
                // recent are no search, so the box stays empty for them.
                mediaQuery = next?.takeUnless(MediaCategories::isCollection).orEmpty(),
                mediaSearchActive = false,
                mediaAction = null,
                panelFocus = null,
            )
        }
        refreshMedia(next?.takeUnless(MediaCategories::isCollection).orEmpty())
    }

    /**
     * Fills the GIF grid from the panel's own favourites or recent GIFs (#597).
     * A file read, so no spinner; the favourites then fetch any copies the
     * setting wants kept and do not have yet.
     */
    private fun showGifCollection(term: String) {
        mediaFetchJob?.cancel()
        val panel = _uiState.value.panel
        mediaFetchJob = serviceScope.launch {
            val items = withContext(Dispatchers.IO) {
                if (term == MediaCategories.FAVOURITES) gifCollections.favourites() else gifCollections.recents()
            }
            if (_uiState.value.panel != panel || _uiState.value.mediaCategory != term) return@launch
            _uiState.update { it.copy(gif = MediaUi.Ready(items, "")) }
            if (term == MediaCategories.FAVOURITES) saveFavouriteCopies()
        }
    }

    /** The one run of [saveFavouriteCopies] at a time. */
    private var gifCopyJob: Job? = null

    /**
     * Downloads a copy of each favourite that the setting wants on the phone
     * and that has none yet (#597). Quietly: no cell spins, and a failure
     * leaves that favourite on the provider's address until the next try.
     * Data saving decides as it does for the search, and an answer of "ask"
     * waits for the search's own prompt rather than raising a second one.
     */
    private fun saveFavouriteCopies() {
        if (!_uiState.value.settings.gif.favouritesOffline) return
        if (gifCopyJob?.isActive == true) return
        if (dataSaverStatus.decide(MeteredFeature.MEDIA_SEARCH) != MeteredDecision.ALLOWED) return
        gifCopyJob = serviceScope.launch {
            val saved = withContext(Dispatchers.IO) {
                var any = false
                for (item in gifCollections.missingCopies()) {
                    val file = downloadMediaFile(item.fullUrl, item.mime) ?: continue
                    if (gifCollections.keepCopy(item.id, file)) any = true
                }
                any
            }
            // Point the grid at the copies, unless it has moved on.
            val state = _uiState.value
            if (saved && state.panel == PanelMode.GIF && state.mediaCategory == MediaCategories.FAVOURITES) {
                val items = withContext(Dispatchers.IO) { gifCollections.favourites() }
                _uiState.update { it.copy(gif = MediaUi.Ready(items, "")) }
            }
        }
    }

    /**
     * "Add to favourites" or "Remove from favourites" on a GIF's long-press
     * menu (#597). Taking one out while the favourites are showing takes it
     * off the grid there and then.
     */
    fun onGifFavouriteToggle(item: GifItem) {
        vibrate()
        _uiState.update { it.copy(mediaAction = null) }
        serviceScope.launch {
            val added = withContext(Dispatchers.IO) { gifCollections.toggleFavourite(item) }
            val ids = withContext(Dispatchers.IO) { gifCollections.favouriteIds() }
            _uiState.update { it.copy(gifFavouriteIds = ids) }
            Toast.makeText(
                this@WMKeyboardService,
                getString(if (added) R.string.ime_service_gif_favourite_added_toast else R.string.ime_service_gif_favourite_removed_toast),
                Toast.LENGTH_SHORT,
            ).show()
            val state = _uiState.value
            if (state.panel != PanelMode.GIF) return@launch
            if (state.mediaCategory == MediaCategories.FAVOURITES) {
                showGifCollection(MediaCategories.FAVOURITES)
            } else if (added) {
                saveFavouriteCopies()
            }
        }
    }

    /** A panel's chooser moved to another provider: ask it what the panel last asked. */
    private fun onProviderPicked(tool: ProviderTool) {
        val state = _uiState.value
        when {
            tool == ProviderTool.TRANSLATE && state.panel == PanelMode.TRANSLATE ->
                scheduleTranslate(immediate = true, force = true)
            tool == ProviderTool.SEARCH && state.panel == PanelMode.WEB_SEARCH ->
                runSearch(state.searchTab, state.mediaQuery.trim())
            tool == ProviderTool.DICTIONARY && state.panel == PanelMode.DICTIONARY &&
                state.dictionaryQuery.isNotBlank() -> onDictionaryLookup(state.dictionaryQuery)
        }
    }

    private fun runWebSearch(query: String) {
        if (query.isBlank()) return
        val settings = _uiState.value.settings
        if (!ToolApiKeys.hasSearchProvider(settings)) {
            _uiState.update { it.copy(webSearch = WebSearchUi.NeedKey) }
            return
        }
        val decision = dataSaverStatus.decide(MeteredFeature.WEB_SEARCH)
        if (decision != MeteredDecision.ALLOWED) {
            webSearchJob?.cancel()
            _uiState.update {
                it.copy(
                    webSearch = WebSearchUi.Metered(
                        canAllow = decision == MeteredDecision.ASK,
                    ),
                )
            }
            return
        }
        webSearchJob?.cancel()
        val category = searchCategory(_uiState.value)
        // The engine's answer belongs to the general search; a category's results stand alone.
        val wantAnswer = settings.webSearch.showAnswer && category == null
        _uiState.update { it.copy(webSearch = WebSearchUi.Loading) }
        webSearchJob = serviceScope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching {
                    // The search provider list in its order, the next one
                    // asked when one fails; see SearchProviders.
                    SearchProviders.web(
                        settings,
                        query,
                        settings.webSearch.resultCount,
                        settings.webSearch.safe,
                        answer = wantAnswer,
                        pick = ProviderPicks.of(ProviderTool.SEARCH),
                        category = category,
                    )
                }
            }
            _uiState.update {
                it.copy(
                    webSearch = result.fold(
                        onSuccess = { page ->
                            val answer = page.answer.takeIf { wantAnswer }
                            WebSearchUi.Ready(
                                page.results,
                                query,
                                answer = answer,
                                category = category,
                                // Under the answer (#879): Tavily's own, else the
                                // Images tab's for this query when it has them.
                                images = if (answer == null) emptyList() else page.images.ifEmpty {
                                    (it.imageSearch as? ImageSearchUi.Ready)?.takeIf { shown -> shown.query == query }
                                        ?.results.orEmpty().take(TavilySearchClient.ANSWER_IMAGES)
                                },
                            )
                        },
                        onFailure = { e ->
                            WebSearchUi.Error(
                                requestErrorText(e, R.string.ime_service_search_error),
                            )
                        },
                    ),
                )
            }
        }
    }

    private fun runImageSearch(query: String) {
        if (query.isBlank()) return
        val settings = _uiState.value.settings
        if (!ToolApiKeys.hasSearchProvider(settings)) {
            _uiState.update { it.copy(imageSearch = ImageSearchUi.NeedKey) }
            return
        }
        // Image results carry thumbnails, so this is the heavier of the two
        // searches; both answer to one setting, since a user who does not want
        // search over mobile data does not want half of it either.
        val decision = dataSaverStatus.decide(MeteredFeature.WEB_SEARCH)
        if (decision != MeteredDecision.ALLOWED) {
            imageSearchJob?.cancel()
            _uiState.update {
                it.copy(
                    imageSearch = ImageSearchUi.Metered(
                        canAllow = decision == MeteredDecision.ASK,
                    ),
                )
            }
            return
        }
        imageSearchJob?.cancel()
        _uiState.update { it.copy(imageSearch = ImageSearchUi.Loading) }
        imageSearchJob = serviceScope.launch {
            val result = withContext(Dispatchers.IO) {
                runCatching {
                    SearchProviders.images(
                        settings,
                        query,
                        settings.webSearch.resultCount,
                        settings.webSearch.safe,
                        pick = ProviderPicks.of(ProviderTool.SEARCH),
                    )
                }
            }
            _uiState.update {
                it.copy(
                    imageSearch = result.fold(
                        onSuccess = { r -> ImageSearchUi.Ready(r, query) },
                        onFailure = { e ->
                            ImageSearchUi.Error(
                                requestErrorText(e, R.string.ime_service_search_error),
                            )
                        },
                    ),
                )
            }
        }
    }

    /**
     * Tapped a GIF/sticker cell: download the full file and commit it. The
     * two panels share this path, so which send mode applies depends on
     * which one is open.
     *
     * Taps while one is still on its way queue up behind it rather than being
     * dropped, and go out one by one in the order they were tapped; each
     * waiting cell wears its place in the line. Tapping a waiting cell again
     * takes it back out.
     */
    fun onGifSelect(item: GifItem) {
        val state = _uiState.value
        val settings = state.settings
        // The field advertises what it can receive; when it advertises nothing
        // the send has nowhere to land. Stop here rather than downloading the
        // file and dead-ending in the clipboard fallback and its "copied,
        // paste it instead" toast — the panel already shows a standing notice
        // (see GifPanel), so a silent no-op is the honest answer.
        if (!state.acceptsRichMedia) {
            vibrate()
            return
        }
        // The one on its way can't be called back; a second tap on it is a slip.
        if (mediaSending?.item?.id == item.id) return
        vibrate()
        if (mediaSendQueue.removeAll { it.item.id == item.id }) {
            publishMediaQueue()
            return
        }
        val sendMode = if (state.panel == PanelMode.STICKER) {
            settings.stickerSendMode
        } else {
            settings.gif.sendMode
        }
        if (item.source != GifSource.LOCAL) recordRecentGif(item)
        val editor = currentInputEditorInfo
        mediaSendQueue.addLast(QueuedMedia(item, sendMode, editor?.packageName, editor?.fieldId))
        publishMediaQueue()
        if (mediaQueueJob?.isActive != true) mediaQueueJob = serviceScope.launch { drainMediaQueue() }
    }

    /**
     * One tapped GIF/sticker waiting its turn, with the send mode of the panel
     * it was tapped on and the field it was meant for.
     */
    private class QueuedMedia(
        val item: GifItem,
        val sendMode: MediaSendMode,
        val packageName: String?,
        val fieldId: Int?,
    )

    /** Tapped GIFs/stickers not yet started, oldest first. Main thread only. */
    private val mediaSendQueue = ArrayDeque<QueuedMedia>()

    /** The queued send being downloaded or committed right now, if any. */
    private var mediaSending: QueuedMedia? = null
    private var mediaQueueJob: Job? = null

    /**
     * A sticker [commitAnimatedAsGif] is still converting. The queue waits for
     * it, so a still sticker tapped after an animated one can't overtake it.
     */
    private var gifConversionJob: Job? = null

    private fun publishMediaQueue() {
        val ids = mediaSendQueue.map { it.item.id }
        _uiState.update { if (it.mediaQueue == ids) it else it.copy(mediaQueue = ids) }
    }

    /** Drops every waiting send, for a field that is no longer the one they were tapped in. */
    private fun clearMediaQueue() {
        if (mediaSendQueue.isEmpty()) return
        mediaSendQueue.clear()
        publishMediaQueue()
    }

    private fun isSameField(packageName: String?, fieldId: Int?): Boolean {
        val now = currentInputEditorInfo ?: return false
        return now.packageName == packageName && now.fieldId == fieldId
    }

    /**
     * Sends the queue in tap order, one at a time. Each one is checked against
     * the field it was tapped in just before it commits: once the user has
     * moved on, the rest of the line goes too, rather than landing somewhere
     * it was never sent to.
     */
    private suspend fun drainMediaQueue() {
        try {
            while (true) {
                val next = mediaSendQueue.removeFirstOrNull() ?: break
                publishMediaQueue()
                if (!isSameField(next.packageName, next.fieldId)) {
                    clearMediaQueue()
                    break
                }
                mediaSending = next
                val item = next.item
                if (item.source == GifSource.LOCAL) {
                    insertLocalSticker(item, next.sendMode)
                } else {
                    startMediaDownload(item.id)
                    val file = withContext(Dispatchers.IO) {
                        downloadMediaFile(item.fullUrl, item.mime, trackProgress = true)
                    }
                    endMediaDownload()
                    if (file == null) {
                        Toast.makeText(
                            this@WMKeyboardService,
                            getString(R.string.ime_service_media_download_error_toast),
                            Toast.LENGTH_SHORT,
                        ).show()
                    } else if (isSameField(next.packageName, next.fieldId)) {
                        commitImageFile(file, item.mime, next.sendMode)
                    } else {
                        clearMediaQueue()
                        break
                    }
                }
                mediaSending = null
                gifConversionJob?.join()
                // A breath between sends, so a chat app that is still taking
                // one picture in doesn't get the next on top of it.
                if (mediaSendQueue.isNotEmpty()) delay(MEDIA_QUEUE_GAP_MS)
            }
        } finally {
            mediaSending = null
        }
    }

    /**
     * Puts a GIF sent from the GIF panel at the front of its Recent chip (#597),
     * when that is on. Incognito keeps no record of it, as with the emoji history.
     */
    private fun recordRecentGif(item: GifItem) {
        val state = _uiState.value
        if (state.panel != PanelMode.GIF || !state.settings.gif.recentGifs) return
        if (state.incognitoOn && state.settings.incognitoPausesLearning) return
        serviceScope.launch(Dispatchers.IO) { gifCollections.recordSent(item) }
    }

    /**
     * Commits a sticker the user owns. Nothing to download, so this skips the
     * cache and the cell spinner entirely. A file that went missing behind the
     * store's back (manual wipe, restore) heals the manifest instead of
     * failing silently.
     */
    private fun insertLocalSticker(item: GifItem, sendMode: MediaSendMode) {
        val found = stickerPackStore.findByItemId(item.id)
        val file = found?.let { (pack, sticker) -> stickerPackStore.fileFor(pack.id, sticker) }
        if (found == null || file == null || !file.exists()) {
            found?.let { (pack, sticker) -> stickerPackStore.removeSticker(pack.id, sticker.id) }
            Toast.makeText(
                this,
                getString(R.string.ime_service_sticker_missing_toast),
                Toast.LENGTH_SHORT,
            ).show()
            _uiState.update { it.copy(stickerPacks = stickerPackStore.packs()) }
            refreshMedia(_uiState.value.mediaQuery.trim())
            return
        }
        commitImageFile(file, item.mime, sendMode)
    }

    /** Pack chip on the "My stickers" tab; null means every pack. */
    fun onStickerPackFilter(packId: String?) {
        vibrate()
        if (_uiState.value.stickerPackId == packId) return
        _uiState.update { it.copy(stickerPackId = packId, mediaAction = null) }
        refreshMedia(_uiState.value.mediaQuery.trim())
    }

    /** Long-pressed a GIF or sticker cell: open its action sheet. */
    fun onMediaLongPress(item: GifItem) {
        val panel = _uiState.value.panel
        if (panel != PanelMode.STICKER && panel != PanelMode.GIF) return
        vibrate()
        _uiState.update { it.copy(mediaAction = item) }
    }

    fun onMediaActionDismiss() {
        _uiState.update { it.copy(mediaAction = null) }
    }

    /**
     * "Copy" on a GIF or sticker: puts the file on the system clipboard
     * instead of into the field.
     *
     * The tap path already falls back to the clipboard when a field refuses
     * the file, but that only happens *after* choosing a field that won't take
     * it. This is the deliberate version — grab the file now, paste it
     * somewhere the keyboard isn't focused on.
     */
    fun onMediaCopy(item: GifItem) {
        if (_uiState.value.mediaDownloadingId != null) return
        vibrate()
        _uiState.update { it.copy(mediaAction = null) }
        if (item.source == GifSource.LOCAL) {
            val found = stickerPackStore.findByItemId(item.id)
            val file = found?.let { (pack, sticker) -> stickerPackStore.fileFor(pack.id, sticker) }
            if (found == null || file == null || !file.exists()) {
                // Same self-heal as insertLocalSticker: a file that vanished
                // behind the store's back leaves the manifest lying.
                found?.let { (pack, sticker) -> stickerPackStore.removeSticker(pack.id, sticker.id) }
                Toast.makeText(
                    this,
                    getString(R.string.ime_service_sticker_missing_toast),
                    Toast.LENGTH_SHORT,
                ).show()
                _uiState.update { it.copy(stickerPacks = stickerPackStore.packs()) }
                refreshMedia(_uiState.value.mediaQuery.trim())
                return
            }
            copyImageFileToClipboard(file)
            return
        }
        startMediaDownload(item.id)
        mediaInsertJob = serviceScope.launch {
            val file = withContext(Dispatchers.IO) {
                downloadMediaFile(item.fullUrl, item.mime, trackProgress = true)
            }
            endMediaDownload()
            if (file == null) {
                Toast.makeText(
                    this@WMKeyboardService,
                    getString(R.string.ime_service_media_download_error_toast),
                    Toast.LENGTH_SHORT,
                ).show()
                return@launch
            }
            copyImageFileToClipboard(file)
        }
    }

    /**
     * "Report" on a GIF or sticker: opens a mail draft naming the result and
     * where it came from.
     *
     * Klipy and GIPHY answer a query out of their own catalogues, so the
     * keyboard shows content nobody here has vetted. Play wants a reporting
     * route on a surface like that, and this is it. As with the AI report,
     * nothing is sent from the device — the draft lands in the user's mail
     * app for them to read, edit, or drop.
     */
    fun onMediaReport(item: GifItem) {
        val state = _uiState.value
        vibrate()
        _uiState.update { it.copy(mediaAction = null) }
        val kind = if (state.panel == PanelMode.STICKER) "sticker" else "GIF"
        val sent = Support.email(
            this,
            "WM Keyboard: $kind report",
            Support.mediaReport(
                kind = kind,
                provider = getString(GifSources.displayNameRes(item.source)),
                query = state.mediaQuery.trim(),
                id = item.id,
                url = item.fullUrl,
            ),
        )
        if (!sent) {
            Toast.makeText(
                this,
                getString(R.string.ime_service_no_email_app_toast, Support.EMAIL),
                Toast.LENGTH_LONG,
            ).show()
        }
    }

    /** Hands a media file to the system clipboard, saying so out loud. */
    private fun copyImageFileToClipboard(file: File) {
        val uri = runCatching {
            FileProvider.getUriForFile(this, clipboardFileProviderAuthority, file)
        }.getOrNull()
        if (uri == null) {
            Toast.makeText(
                this,
                getString(R.string.ime_service_file_copy_error_toast),
                Toast.LENGTH_SHORT,
            ).show()
            return
        }
        copyUriToSystemClipboard(uri, "image")
        Toast.makeText(
            this,
            getString(R.string.ime_service_copied_paste_toast),
            Toast.LENGTH_SHORT,
        ).show()
    }

    /**
     * "Save to pack" on a provider sticker: download it, normalise it to the
     * sticker spec, and file it under [packId] (null creates a first pack).
     */
    fun onStickerSaveToPack(item: GifItem, packId: String?) {
        if (_uiState.value.mediaDownloadingId != null) return
        vibrate()
        _uiState.update { it.copy(mediaAction = null) }
        startMediaDownload(item.id)
        mediaInsertJob = serviceScope.launch {
            val result = withContext(Dispatchers.IO) {
                val target = packId
                    ?: stickerPackStore.packs().firstOrNull()?.id
                    ?: stickerPackStore
                        .createPack(getString(R.string.ime_service_sticker_pack_default_name))?.id
                    ?: return@withContext null
                val bytes = runCatching {
                    val dir = File(cacheDir, "media").apply { mkdirs() }
                    val temp = File(dir, "sticker_${item.fullUrl.hashCode().toUInt()}")
                    ToolHttp.download(
                        item.fullUrl,
                        temp,
                        maxBytes = StickerImage.MAX_SOURCE_BYTES,
                        onProgress = ::publishMediaProgress,
                        source = NetSource.MEDIA_IMAGES,
                    )
                    temp.readBytes().also { temp.delete() }
                }.getOrNull() ?: return@withContext null
                when (val processed = StickerImage.process(bytes)) {
                    is StickerImage.Result.Ok ->
                        stickerPackStore.addSticker(target, processed.sticker)
                    StickerImage.Result.TooLarge -> StickerAddResult.WriteFailed
                    StickerImage.Result.NotAnImage -> StickerAddResult.WriteFailed
                }
            }
            endMediaDownload()
            _uiState.update { it.copy(stickerPacks = stickerPackStore.packs()) }
            val message = when (result) {
                is StickerAddResult.Added ->
                    getString(R.string.ime_service_sticker_saved_toast)
                StickerAddResult.PackFull ->
                    getString(R.string.ime_service_sticker_pack_full_toast)
                StickerAddResult.PackMissing ->
                    getString(R.string.ime_service_sticker_pack_missing_toast)
                else -> getString(R.string.ime_service_sticker_save_error_toast)
            }
            Toast.makeText(this@WMKeyboardService, message, Toast.LENGTH_SHORT).show()
        }
    }

    /** Tapped an image-search cell: download the full image and commit it. */
    fun onImageResultSelect(result: ImageResult) {
        insertDownloadedImage(result.imageUrl, result.imageUrl, searchImageMime(result))
    }

    /** What an image result is sent and saved as: its own type when it is one we know. */
    private fun searchImageMime(result: ImageResult): String = when (result.mime) {
        "image/gif", "image/png", "image/webp", "image/jpeg" -> result.mime
        else -> "image/jpeg"
    }

    /**
     * Save to gallery on an image result's menu (#879): the full picture,
     * downloaded with the cell's spinner over it, into Pictures/WM Keyboard.
     */
    fun onSearchImageSave(result: ImageResult) {
        if (_uiState.value.mediaDownloadingId != null) return
        vibrate()
        val mime = searchImageMime(result)
        startMediaDownload(result.imageUrl)
        mediaInsertJob = serviceScope.launch {
            val file = withContext(Dispatchers.IO) {
                downloadMediaFile(result.imageUrl, mime, trackProgress = true)
            }
            endMediaDownload()
            if (file == null) {
                toast(R.string.ime_service_media_download_error_toast)
                return@launch
            }
            saveToGalleryIfEnabled(file, mime, enabled = true, namePrefix = "Search", confirm = true)
        }
    }

    /** Long-pressed an image-search cell: insert the image's URL as text. */
    fun onImageResultLink(result: ImageResult) {
        vibrate()
        commitToField(result.imageUrl)
    }

    /**
     * Tapped a web result, or Insert the link on a result's menu: insert its
     * URL at the cursor. The answer box inserts through [onSearchInsertText].
     */
    fun onWebResultSelect(result: WebResult) {
        vibrate()
        commitToField(result.url.ifEmpty { result.snippet })
    }

    /** Open a web result in the browser (leaves the keyboard). */
    fun onWebResultOpen(result: WebResult) = openSearchLink(result.url)

    /** Opens [url] in the browser, from the search panel (leaves the keyboard). */
    private fun openSearchLink(url: String) {
        vibrate()
        runCatching {
            startActivity(
                Intent(Intent.ACTION_VIEW, Uri.parse(url)).apply {
                    addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                },
            )
        }
    }

    /**
     * Downloads a remote image into the media cache and commits it through
     * the same commitContent path as clipboard images. One insert at a
     * time; the panel shows a spinner over the tapped cell meanwhile.
     */
    private fun insertDownloadedImage(
        id: String,
        url: String,
        mime: String,
        sendMode: MediaSendMode = MediaSendMode.IMAGE,
    ) {
        if (_uiState.value.mediaDownloadingId != null) return
        vibrate()
        startMediaDownload(id)
        mediaInsertJob = serviceScope.launch {
            val file = withContext(Dispatchers.IO) {
                downloadMediaFile(url, mime, trackProgress = true)
            }
            endMediaDownload()
            if (file == null) {
                Toast.makeText(
                    this@WMKeyboardService,
                    getString(R.string.ime_service_media_download_error_toast),
                    Toast.LENGTH_SHORT,
                ).show()
                return@launch
            }
            commitImageFile(file, mime, sendMode)
        }
    }

    /**
     * Downloads a GIF/sticker/image into the media cache, or null if it
     * failed. Blocking — call it off the main thread.
     *
     * The cache name is stable per URL, so picking the same result twice
     * (insert, then copy) skips the second download.
     *
     * [trackProgress] publishes how far the transfer has got for the cell the
     * user tapped; it belongs to whoever also published [KeyboardUiState.mediaDownloadingId],
     * so the preview fetches that spin on their own flags leave it off.
     */
    private fun downloadMediaFile(
        url: String,
        mime: String,
        trackProgress: Boolean = false,
    ): File? = runCatching {
        // An imported GIF pack's file is already on the device.
        if (url.startsWith("file://")) {
            return@runCatching File(java.net.URI(url)).takeIf { it.isFile }
                ?: throw java.io.FileNotFoundException(url)
        }
        val extension = MediaMime.extension(mime)
        val dir = File(cacheDir, "media").apply { mkdirs() }
        pruneMediaCache(dir)
        val target = File(dir, "media_${url.hashCode().toUInt()}.$extension")
        if (!target.exists() || target.length() == 0L) {
            ToolHttp.download(
                url,
                target,
                onProgress = if (trackProgress) ::publishMediaProgress else null,
                source = NetSource.MEDIA_IMAGES,
            )
        }
        target
    }.getOrNull()

    /**
     * The last whole percent published for the running media download, so the
     * ~200 buffer reads of a 1.5 MB GIF turn into at most 100 state updates
     * instead of one per 8 KB.
     */
    private var mediaDownloadPercent = -1

    /**
     * Publishes download progress for the spinning cell. Called from the
     * download thread; [MutableStateFlow.update] is what makes that safe.
     *
     * A server that declared no size gets null rather than a made-up fraction —
     * the cell then keeps the indeterminate spinner it had before.
     */
    private fun publishMediaProgress(read: Long, expected: Long) {
        if (expected <= 0L) return
        val percent = (read * 100L / expected).coerceIn(0L, 100L).toInt()
        if (percent == mediaDownloadPercent) return
        mediaDownloadPercent = percent
        _uiState.update { it.copy(mediaDownloadProgress = percent / 100f) }
    }

    /**
     * Marks the start of a media download for [id]: the cell spins from here,
     * with no progress until the first bytes say how far there is to go.
     */
    private fun startMediaDownload(id: String) {
        mediaDownloadPercent = -1
        _uiState.update { it.copy(mediaDownloadingId = id, mediaDownloadProgress = null) }
    }

    /** The download ended, one way or another: the cell stops spinning. */
    private fun endMediaDownload() {
        mediaDownloadPercent = -1
        _uiState.update { it.copy(mediaDownloadingId = null, mediaDownloadProgress = null) }
    }

    /** Keeps the media cache bounded (newest ~30 files). */
    private fun pruneMediaCache(dir: File) {
        val files = dir.listFiles()?.sortedByDescending { it.lastModified() } ?: return
        files.drop(30).forEach { it.delete() }
    }

    // ---- translate tool ----

    /**
     * Where index 0 of the last [extractFieldText] result sits in the field,
     * or null when that could not be worked out.
     *
     * Null is the stitched fallback below: the string starts an unknown
     * distance into the field, so an offset into it maps onto nothing the
     * InputConnection understands. Callers that address the field by offset
     * (the grammar fixes) fall back to rewriting the whole field then.
     */
    private var fieldTextOrigin: Int? = null

    /**
     * Whether the last [extractFieldText] saw the whole field. The stitched
     * fallback reads a window either side of the cursor, and a field longer
     * than the window must never be rewritten from that window: the part
     * outside it would be lost.
     */
    private var fieldTextComplete: Boolean = true

    /** Everything in the focused field, for the grammar strip. */
    private fun extractFieldText(): String {
        val ic = currentInputConnection ?: return ""
        val extracted = runCatching {
            ic.getExtractedText(ExtractedTextRequest(), 0)
        }.getOrNull()
        if (extracted?.text != null) {
            // startOffset is where the editor began extracting. It is 0 for
            // every editor that hands over the whole field, and -1 from the
            // ones that don't track it — which is a "don't know", not a 0.
            fieldTextOrigin = extracted.startOffset.takeIf { it >= 0 }
            fieldTextComplete = true
            return extracted.text.toString()
        }
        // Some editors don't implement extraction; stitch around the cursor.
        val before = ic.getTextBeforeCursor(TranslateClient.MAX_CHARS, 0)?.toString().orEmpty()
        val after = ic.getTextAfterCursor(TranslateClient.MAX_CHARS, 0)?.toString().orEmpty()
        fieldTextOrigin = null
        fieldTextComplete = before.length < TranslateClient.MAX_CHARS && after.length < TranslateClient.MAX_CHARS
        return before + after
    }

    /** The engine in force. A build and phone with no on-device engine has only the one. */
    private fun translateEngine(settings: KeyboardSettings): TranslateEngine =
        if (OfflineTranslation.available) settings.translate.engine else TranslateEngine.ONLINE

    /**
     * Translates the panel's typed query after a short debounce, so the
     * result follows the typing without a request per keystroke. The query
     * lives in [KeyboardUiState.mediaQuery] — the panel is its own window
     * and never reads the focused field.
     *
     * [targetOverride] and [engineOverride] carry a choice the user has just
     * made in the panel: the settings flow catches up asynchronously, and a
     * retranslate that read the old value would undo the tap on screen.
     * [force] retranslates text that already has a result, for the changes
     * that make the same text come out differently.
     */
    private fun scheduleTranslate(
        immediate: Boolean = false,
        targetOverride: String? = null,
        engineOverride: TranslateEngine? = null,
        force: Boolean = false,
    ) {
        translateJob?.cancel()
        translateJob = serviceScope.launch {
            if (!immediate) delay(400)
            val state = _uiState.value
            if (state.panel != PanelMode.TRANSLATE) return@launch
            val source = state.mediaQuery.trim()
            if (source.isEmpty()) {
                _uiState.update { it.copy(translate = it.translate.cleared()) }
                return@launch
            }
            if (!force && source == state.translate.sourceText &&
                state.translate.translated.isNotEmpty() && state.translate.error == null
            ) {
                return@launch
            }
            _uiState.update {
                it.copy(
                    translate = it.translate.copy(
                        sourceText = source,
                        translating = true,
                        error = null,
                        meteredAsk = false,
                        licenceAsk = false,
                    ),
                )
            }
            val target = targetOverride ?: state.settings.translateTargetLang
            val sourceLang = state.translate.sourceOverride
            val engine = engineOverride ?: translateEngine(state.settings)
            // Pick mode: the provider the panel's chooser is on, alone, whatever the engine.
            val picking = state.settings.providerMode(ProviderTool.TRANSLATE) == ChainMode.PICK
            val outcome: (TranslateUi) -> TranslateUi =
                if (picking) {
                    val pick = ProviderPicks.of(ProviderTool.TRANSLATE)
                    translateChainUi(state, TranslateProviders.rows(state.settings, engine, pick = pick), source, target, sourceLang)
                } else if (engine == TranslateEngine.ONLINE) {
                    onlineOrStandInTranslateUi(state, source, target, sourceLang)
                } else {
                    translateChainUi(state, TranslateProviders.rows(state.settings, engine), source, target, sourceLang)
                }
            if (_uiState.value.panel != PanelMode.TRANSLATE) return@launch
            _uiState.update { it.copy(translate = outcome(it.translate)) }
        }
    }

    /**
     * The translate list in the user's order, cut by the engine switch: on
     * the device where the list says so, and each run of online rows as one
     * fallback walk. The first that translates is the answer.
     *
     * When nothing translates, a pair that only needs its models (or the
     * engine its module) is the one failure the user can fix from here, so
     * that offer outranks "no connection".
     */
    private suspend fun translateChainUi(
        state: KeyboardUiState,
        rows: List<ResolvedProvider>,
        source: String,
        target: String,
        sourceLang: String,
    ): (TranslateUi) -> TranslateUi {
        var offline: OfflineTranslateResult? = null
        var online: Result<Translation>? = null
        var index = 0
        while (index < rows.size) {
            if (rows[index].type?.onDevice == true) {
                // ML Kit or Bergamot, whichever this row is. A pair the first
                // has no models for goes on to the next, so with both on the
                // list the one that has the pair downloaded answers.
                val engine = OfflineTranslation.engineOf(rows[index].typeId)
                val local = engine?.let { translateOnDevice(state, source, target, sourceLang, it) }
                if (local is OfflineTranslateResult.Success) return offlineTranslateUi(source, local)
                // The first answer is kept, unless a later engine only needs
                // its models: that is the one failure the panel can fix.
                if (local != null &&
                    (offline == null || (offline !is OfflineTranslateResult.NeedsModels && local is OfflineTranslateResult.NeedsModels))
                ) {
                    offline = local
                }
                index++
                continue
            }
            val run = rows.drop(index).takeWhile { it.type?.onDevice != true }
            val answer = translateOnline(state.settings, source, target, sourceLang, run)
            if (answer.isSuccess) return onlineTranslateUi(source, answer)
            online = answer
            index += run.size
        }
        val fixable = offline is OfflineTranslateResult.NeedsModels || offline is OfflineTranslateResult.ModuleMissing
        return when {
            offline != null && (online == null || fixable) -> offlineTranslateUi(source, offline)
            online != null -> onlineTranslateUi(source, online)
            else -> onlineTranslateUi(source, Result.failure(OnlineTranslate.NoProviderException()))
        }
    }

    /** The online part of the list (#435, #331), shared with the AI's translate tool (#698). */
    private suspend fun translateOnline(
        settings: KeyboardSettings,
        source: String,
        target: String,
        sourceLang: String,
        rows: List<ResolvedProvider> = TranslateProviders.rows(settings, TranslateEngine.ONLINE),
    ): Result<Translation> = withContext(Dispatchers.IO) {
        val job = coroutineContext[Job]
        runCancellable {
            OnlineTranslate.translate(
                rows = rows,
                text = source,
                target = target,
                source = sourceLang,
                isActive = { job?.isActive != false },
            )
        }
    }

    /**
     * [engine] alone, or with none named every on-device engine on the
     * translate list in its order, the first that translates answering.
     */
    private suspend fun translateOnDevice(
        state: KeyboardUiState,
        source: String,
        target: String,
        sourceLang: String,
        engine: OfflineTranslation.Engine? = null,
    ): OfflineTranslateResult {
        translateEngineLoaded = true
        // What the identifier falls back on when a word or two is not
        // enough to go by: the language being typed in, then the others.
        val hints = listOf(state.language.id) + state.settings.enabledLanguages.map { it.id }
        if (engine != null) {
            return OfflineTranslation.translate(engine, applicationContext, source, target, sourceLang, hints)
        }
        val order = TranslateProviders.rows(state.settings, TranslateEngine.ON_DEVICE)
            .mapNotNull { OfflineTranslation.engineOf(it.typeId) }
            .distinct()
            .ifEmpty { OfflineTranslation.engines }
        return OfflineTranslation.translateAny(applicationContext, source, target, sourceLang, hints, order)
    }

    /**
     * The online engine's answer, or the on-device engine's when the user asked
     * it to stand in (#452) and there is no connection or the service could not
     * be reached. Only a finished on-device translation replaces the online
     * result: a pair with no models downloaded keeps the online error, which
     * says what is actually wrong. Text that goes to the device goes nowhere,
     * so this keeps the promise of the user's own server (#435) too.
     */
    private suspend fun onlineOrStandInTranslateUi(
        state: KeyboardUiState,
        source: String,
        target: String,
        sourceLang: String,
    ): (TranslateUi) -> TranslateUi {
        val standIn = state.settings.dataSaver.offlineFallback && OfflineTranslation.available
        // Runs on the main thread (the translate job is the service's), so the
        // notice can be put up from here.
        if (standIn && !networkWatcher.state.value.online) {
            val local = translateOnDevice(state, source, target, sourceLang)
            if (local is OfflineTranslateResult.Success) noteOfflineFallback(OFFLINE_FALLBACK_TRANSLATE, true)
            return offlineTranslateUi(source, local, standIn = true)
        }
        val online = translateOnline(state.settings, source, target, sourceLang)
        val failure = online.exceptionOrNull()
        if (standIn && failure != null && ToolHttp.isUnreachable(failure)) {
            val local = translateOnDevice(state, source, target, sourceLang)
            if (local is OfflineTranslateResult.Success) {
                noteOfflineFallback(OFFLINE_FALLBACK_TRANSLATE, true)
                return offlineTranslateUi(source, local, standIn = true)
            }
        } else if (standIn && online.isSuccess) {
            noteOfflineFallback(OFFLINE_FALLBACK_TRANSLATE, false)
        }
        return onlineTranslateUi(source, online)
    }

    private fun onlineTranslateUi(source: String, result: Result<Translation>): (TranslateUi) -> TranslateUi =
        { current ->
            result.fold(
                onSuccess = { t ->
                    current.cleared().copy(
                        sourceText = source,
                        translated = t.text,
                        detectedSource = t.detectedSource,
                        viaDeepL = t.viaDeepL,
                        viaServer = t.viaServer,
                    )
                },
                onFailure = { e ->
                    current.copy(
                        translating = false,
                        missingModels = emptyList(),
                        moduleMissing = false,
                        error = if (e is OnlineTranslate.NoProviderException) {
                            getString(com.wasimaster.wmkeyboard.tools.R.string.core_tools_provider_none_on)
                        } else {
                            requestErrorText(e, R.string.ime_service_translate_error)
                        },
                    )
                },
            )
        }

    private fun offlineTranslateUi(
        source: String,
        result: OfflineTranslateResult,
        standIn: Boolean = false,
    ): (TranslateUi) -> TranslateUi =
        { current ->
            val base = current.cleared().copy(sourceText = source)
            when (result) {
                is OfflineTranslateResult.Success -> base.copy(
                    translated = result.text,
                    detectedSource = result.source,
                    sourceGuessed = result.guessed,
                    onDevice = true,
                    offlineStandIn = standIn,
                )
                is OfflineTranslateResult.NeedsModels -> base.copy(
                    detectedSource = result.source,
                    missingModels = result.missing,
                )
                is OfflineTranslateResult.Unsupported -> base.copy(
                    error = getString(
                        if (result.romanized) {
                            R.string.ime_translate_offline_romanized_error
                        } else {
                            R.string.ime_translate_offline_unsupported_error
                        },
                        TranslateClient.languageName(
                            if (result.romanized) {
                                OfflineTranslateLanguages.baseLanguage(result.language)
                            } else {
                                result.language
                            },
                        ),
                    ),
                )
                OfflineTranslateResult.Undetermined ->
                    base.copy(error = getString(R.string.ime_translate_offline_undetermined_error))
                OfflineTranslateResult.ModuleMissing -> base.copy(moduleMissing = true)
                is OfflineTranslateResult.Failed -> {
                    DebugLog.w("translate", "on-device engine failed: ${result.cause}")
                    base.copy(error = getString(R.string.ime_translate_offline_failed_error))
                }
            }
        }

    /** Whether an on-device translator may be sitting in memory. See [releaseTranslateEngine]. */
    private var translateEngineLoaded = false

    private var translateModelsJob: Job? = null

    /**
     * Mirrors the on-device models' states into the panel while it is open,
     * and retranslates the moment the models a query was waiting on are all
     * here, so a download ends in a translation rather than in a button that
     * has quietly become pressable.
     */
    private fun watchTranslateModels() {
        translateModelsJob?.cancel()
        if (!OfflineTranslation.available) return
        translateModelsJob = serviceScope.launch {
            if (translateEngine(_uiState.value.settings) != TranslateEngine.ONLINE) {
                launch { OfflineTranslation.refresh(applicationContext) }
            }
            // The engine's own module, where there is one to wait for (Play).
            // It landing is the same event as a model landing: whatever was
            // waiting on it gets translated, or gets its next offer.
            launch {
                OnDeviceTranslator.moduleState.collect { module ->
                    val waiting = _uiState.value.translate.moduleMissing
                    _uiState.update { it.copy(translate = it.translate.copy(module = module)) }
                    if (waiting && module == TranslateModuleState.Installed) {
                        OnDeviceTranslator.refresh(applicationContext)
                        scheduleTranslate(immediate = true, force = true)
                    }
                }
            }
            OfflineTranslation.models.collect { models ->
                val waitingOn = _uiState.value.translate.missingModels
                _uiState.update { it.copy(translate = it.translate.copy(models = models)) }
                if (waitingOn.isNotEmpty() && waitingOn.all { models[it] is OfflineModelState.Downloaded }) {
                    scheduleTranslate(immediate = true, force = true)
                }
            }
        }
    }

    /**
     * Lets the translators go. Each loaded pair is tens of megabytes, and a
     * keyboard holding that for a panel nobody has open is first in line when
     * Android wants memory back.
     */
    private fun releaseTranslateEngine() {
        translateModelsJob?.cancel()
        translateModelsJob = null
        if (!translateEngineLoaded) return
        translateEngineLoaded = false
        OfflineTranslation.release()
    }

    fun onTranslateTargetChange(code: String) {
        vibrate()
        serviceScope.launch { settingsRepository.setTranslateTargetLang(code) }
        _uiState.update { it.copy(translate = it.translate.cleared()) }
        // The settings flow updates asynchronously; pass the new target
        // directly so this retranslate can't race it.
        scheduleTranslate(immediate = true, targetOverride = code)
    }

    /** The source chip: a picker code, or "" to go back to detecting it. */
    fun onTranslateSourceChange(code: String) {
        vibrate()
        _uiState.update { it.copy(translate = it.translate.cleared().copy(sourceOverride = code)) }
        scheduleTranslate(immediate = true, force = true)
    }

    fun onTranslateEngineChange(engine: TranslateEngine) {
        vibrate()
        serviceScope.launch { settingsRepository.setTranslateEngine(engine) }
        _uiState.update { it.copy(translate = it.translate.cleared()) }
        if (engine != TranslateEngine.ONLINE) {
            // Picking an engine that needs the module is asking for the
            // module. Held only by data saver, in which case the panel's own
            // offer does the asking.
            if (dataSaverStatus.allows(MeteredFeature.DOWNLOADS)) OnDeviceTranslator.requestModule()
            serviceScope.launch { OfflineTranslation.refresh(applicationContext) }
        }
        scheduleTranslate(immediate = true, engineOverride = engine, force = true)
    }

    /**
     * Turns the translation round: what came out becomes the text, its
     * language the source, and the language it was read as the new target.
     */
    fun onTranslateSwap() {
        val state = _uiState.value
        val ui = state.translate
        if (ui.translated.isEmpty()) return
        val newTarget = TranslateClient.pickerCode(ui.detectedSource) ?: return
        val oldTarget = state.settings.translateTargetLang
        if (newTarget.equals(oldTarget, ignoreCase = true)) return
        vibrate()
        serviceScope.launch { settingsRepository.setTranslateTargetLang(newTarget) }
        _uiState.update {
            it.copy(
                mediaQuery = ui.translated.take(TranslateClient.MAX_CHARS),
                translate = it.translate.cleared().copy(sourceOverride = oldTarget),
            )
        }
        scheduleTranslate(immediate = true, targetOverride = newTarget, force = true)
    }

    /**
     * The panel's download button. It fetches every model the current query
     * is waiting for, and while any of them is on its way it is the way back
     * out: one control, as under the handwriting canvas.
     */
    fun onTranslateDownload() {
        vibrate()
        val ui = _uiState.value.translate
        if (ui.missingModels.isEmpty() && !ui.moduleMissing) return
        // Play cancels a module by session, and the panel holds none; the
        // button is simply inert while the module is on its way.
        if (ui.moduleMissing && ui.module is TranslateModuleState.Installing) return
        val running = ui.missingModels.filter { ui.models[it] is OfflineModelState.Downloading }
        if (running.isNotEmpty()) {
            running.forEach { OfflineTranslation.cancelDownload(applicationContext, it) }
            return
        }
        when (dataSaverStatus.decide(MeteredFeature.DOWNLOADS)) {
            MeteredDecision.ALLOWED -> Unit
            MeteredDecision.BLOCKED -> {
                _uiState.update {
                    it.copy(translate = it.translate.copy(error = getString(R.string.ime_metered_off_body)))
                }
                return
            }
            // Asked once, on the button itself; pressing it again is the yes.
            MeteredDecision.ASK -> if (ui.meteredAsk) {
                grantMetered(MeteredFeature.DOWNLOADS)
            } else {
                _uiState.update { it.copy(translate = it.translate.copy(meteredAsk = true)) }
                return
            }
        }
        // NLLB's weights come under a non-commercial licence, shown on the
        // panel before the first download; pressing again is agreeing to it.
        if (OfflineTranslation.needsLicence(ui.missingModels)) {
            if (!ui.licenceAsk) {
                _uiState.update { it.copy(translate = it.translate.copy(meteredAsk = false, licenceAsk = true, error = null)) }
                return
            }
            NativeConsent.set(NativeConsent.NLLB, true)
        }
        _uiState.update { it.copy(translate = it.translate.copy(meteredAsk = false, licenceAsk = false, error = null)) }
        if (ui.moduleMissing) {
            OnDeviceTranslator.requestModule()
            return
        }
        for (code in ui.missingModels) {
            if (ui.models[code] is OfflineModelState.Downloaded) continue
            OfflineTranslation.downloadNotified(
                context = this,
                key = code,
                title = getString(
                    CommonR.string.common_notify_download_translate,
                    OfflineTranslation.label(code, TranslateClient::languageName, getString(R.string.ime_translate_bergamot_engine_name)),
                ),
            )
        }
    }

    /**
     * One stable bundle for the translate panel, built outside
     * [ServiceKeyboardContent] for the reason [converterCallbacks] is.
     */
    private val translateCallbacks by lazy {
        com.wasimaster.wmkeyboard.ime.ui.TranslateCallbacks(
            onTarget = ::onTranslateTargetChange,
            onSource = ::onTranslateSourceChange,
            onEngine = ::onTranslateEngineChange,
            onSwap = ::onTranslateSwap,
            onDownload = ::onTranslateDownload,
            onReplace = ::onTranslateReplace,
            onInsert = ::onTranslateInsert,
            onPaste = ::onTranslatePaste,
        )
    }

    /**
     * The paste button in Translate's text box (#474): the clipboard's text
     * goes in at the box's caret, through the same path a paste key takes.
     * Pasted into a box that was not being typed in, it translates straight
     * away and leaves the result showing, the way a selection opens it.
     */
    fun onTranslatePaste() {
        vibrate()
        val typing = _uiState.value.mediaSearchActive
        if (!typing) _uiState.update { it.copy(mediaSearchActive = true, mediaAction = null) }
        capturePaste()
        if (!typing && _uiState.value.mediaQuery.isNotBlank()) runMediaSearch()
    }

    /**
     * Opens Translate on the field's selection, when there is one (#434). A
     * passage in a language the user cannot read is exactly the text they
     * could not have typed into the box by hand. Read once, here, and never
     * again: from this point the box is the user's to edit.
     */
    private fun prefillTranslateFromSelection() {
        val state = _uiState.value
        if (state.mediaQuery.isNotEmpty()) return
        if (currentInputEditorInfo.isSecureField()) return
        // A collapsed caret the editor has already reported is nothing
        // selected, and saves the IPC.
        if (expectedSelStart >= 0 && expectedSelStart == expectedSelEnd) return
        val ic = currentInputConnection ?: return
        val selected = runCatching { ic.getSelectedText(0)?.toString() }.getOrNull()?.trim()
        if (selected.isNullOrEmpty() || selected.length > MAX_MACRO_SELECTION) return
        _uiState.update { it.copy(mediaQuery = selected, translate = it.translate.copy(selection = selected)) }
        // Straight to the result, the way the selection bar's Translate opens
        // it; a tap on the box starts editing the text.
        runMediaSearch()
    }

    /**
     * Replaces the whole field with the translation, or only the selection the
     * panel opened on while that is still what is selected (#434). A
     * selection that has gone since puts the translation in at the caret, as
     * the AI tool does: replacing the whole field would take the text around
     * the passage with it.
     */
    fun onTranslateReplace() {
        val translate = _uiState.value.translate
        val translated = translate.translated
        if (translated.isEmpty()) return
        vibrate()
        if (translate.selection.isNotEmpty()) {
            val now = runCatching { currentInputConnection?.getSelectedText(0)?.toString() }.getOrNull()
            if (now != null && now.trim() == translate.selection) {
                rewriteSelection(translated)
            } else {
                commitToField(translated)
            }
            return
        }
        val ic = currentInputConnection ?: return
        // End any editor-side composition too: with a region alive, the
        // commitText below targets the region instead of the select-all,
        // splicing the translation over one word.
        ic.finishComposingText()
        revision = null
        composing = StringBuilder()
        ic.beginBatchEdit()
        val length = runCatching {
            ic.getExtractedText(ExtractedTextRequest(), 0)?.text?.length
        }.getOrNull()
        if (length != null) {
            ic.setSelection(0, length)
        } else {
            ic.performContextMenuAction(android.R.id.selectAll)
        }
        ic.commitText(translated, 1)
        ic.endBatchEdit()
    }

    /** Inserts the translation at the cursor, keeping the original text. */
    fun onTranslateInsert() {
        val translated = _uiState.value.translate.translated
        if (translated.isEmpty()) return
        vibrate()
        commitToField(translated)
    }

    // ---- grammar tool (offline, Harper via JNI) ----

    /**
     * Play only: the Harper library is the on-demand `:feature:grammar` part.
     * Asks for it unless data saver holds downloads, says so in the panel,
     * and checks again once it lands, if the panel is still open.
     */
    private suspend fun awaitGrammarModule() {
        if (!dataSaverStatus.allows(MeteredFeature.DOWNLOADS)) {
            _uiState.update { it.copy(grammar = GrammarUi(moduleHint = R.string.ime_grammar_module_data_saver_info)) }
            return
        }
        _uiState.update {
            it.copy(grammar = GrammarUi(checking = true, moduleHint = R.string.ime_grammar_module_installing_info))
        }
        val here = GrammarChecker.awaitModule()
        if (_uiState.value.panel != PanelMode.GRAMMAR) return
        if (here) {
            _uiState.update { it.copy(grammar = GrammarUi()) }
            scheduleGrammarCheck(immediate = true)
        } else {
            _uiState.update { it.copy(grammar = GrammarUi(moduleHint = R.string.ime_grammar_module_failed_info)) }
        }
    }

    /**
     * Re-extracts the field and lints it after a short debounce. Linting is
     * local and fast, but the debounce keeps the strip from churning on
     * every keystroke mid-word.
     */
    private fun scheduleGrammarCheck(immediate: Boolean = false) {
        grammarJob?.cancel()
        grammarJob = serviceScope.launch {
            if (!immediate) {
                // A server reads every check, so give typing a longer pause
                // before one goes out than the phone's own engine needs.
                val debounce = _uiState.value.settings.grammarDebounceMs.toLong()
                delay(if (grammarPlan().online) maxOf(debounce, GRAMMAR_ONLINE_DEBOUNCE_MS) else debounce)
            }
            val state = _uiState.value
            if (state.panel != PanelMode.GRAMMAR) return@launch
            val source = extractFieldText()
            if (source.isBlank()) {
                _uiState.update { it.copy(grammar = GrammarUi()) }
                return@launch
            }
            if (source == state.grammar.sourceText && state.grammar.checkedOnce) return@launch
            _uiState.update {
                it.copy(grammar = it.grammar.copy(sourceText = source, checking = true))
            }
            val outcome = lintField(source, _uiState.value.settings.grammarDialect)
            if (_uiState.value.panel != PanelMode.GRAMMAR) return@launch
            showGrammarOutcome(source, outcome)
        }
    }

    /** What one check came to, for [showGrammarOutcome]. */
    private sealed interface GrammarOutcome {
        /** [via] is the server's name when one answered, null for Harper. */
        data class Found(val lints: List<GrammarLint>, val via: String? = null) : GrammarOutcome

        /** Nothing could answer; [notice] says why, in the panel's place for the issues. */
        data class Notice(val notice: String) : GrammarOutcome

        /** Harper was the one to ask and its Play part is not here yet. */
        data object HarperPending : GrammarOutcome

        /** Harper was the one to ask and this build has none. */
        data object HarperMissing : GrammarOutcome
    }

    /** The grammar list as it stands for the field in front of the keyboard. */
    private fun grammarPlan() = _uiState.value.let { state ->
        GrammarProviders.plan(
            // Nothing on the disk to look at for this list, and it is read on every pause.
            rows = state.settings.resolveProviders(ProviderTool.GRAMMAR, com.wasimaster.wmkeyboard.core.settings.choiceEnv()),
            languageTag = state.language.localeTag,
            // Neither a password nor anything typed in incognito goes to a server.
            privateField = state.secureField || state.incognitoOn,
            dataSaverAllows = dataSaverStatus.allows(MeteredFeature.CLOUD_GRAMMAR),
        )
    }

    /**
     * Checks [text] with the grammar list's checkers in turn: the first that
     * knows the keyboard's language, then the next when that one cannot
     * answer (Harper not in this build, a server that is down). See
     * [GrammarProviders.plan] for the order and for what is never sent.
     */
    private suspend fun lintField(text: String, dialect: GrammarDialect): GrammarOutcome {
        val plan = grammarPlan()
        val languageTag = _uiState.value.language.localeTag
        var failure: Throwable? = null
        var harperPending = false
        var harperMissing = false
        for (step in plan.steps) {
            when (step) {
                GrammarStep.Harper -> {
                    if (!GrammarChecker.moduleReady) {
                        harperPending = true
                        continue
                    }
                    if (!GrammarChecker.available) {
                        harperMissing = true
                        continue
                    }
                    return GrammarOutcome.Found(GrammarChecker.check(text, dialect.ordinal))
                }
                is GrammarStep.LanguageTool -> try {
                    val language = LanguageToolLanguages.codeFor(languageTag, dialect)
                    val result = LanguageToolChecker.check(text, language, step.server)
                    return GrammarOutcome.Found(result.lints, via = step.name)
                } catch (e: kotlinx.coroutines.CancellationException) {
                    throw e
                } catch (e: Exception) {
                    failure = e
                }
            }
        }
        return when {
            // A server that failed says why, even when Harper is missing too.
            failure != null -> GrammarOutcome.Notice(ToolHttp.friendlyMessage(this, failure))
            harperPending -> GrammarOutcome.HarperPending
            harperMissing -> GrammarOutcome.HarperMissing
            else -> GrammarOutcome.Notice(
                getString(
                    when (plan.held) {
                        GrammarHeld.PRIVATE -> R.string.ime_grammar_languagetool_private_info
                        GrammarHeld.DATA_SAVER -> R.string.ime_grammar_languagetool_data_saver_info
                        GrammarHeld.NOTHING_ON, null -> R.string.ime_grammar_nothing_on_info
                    },
                ),
            )
        }
    }

    /** Puts one check's [outcome] for [source] in the panel. */
    private suspend fun showGrammarOutcome(source: String, outcome: GrammarOutcome) {
        when (outcome) {
            is GrammarOutcome.Found -> _uiState.update {
                it.copy(
                    grammar = GrammarUi(
                        sourceText = source,
                        lints = outcome.lints,
                        checking = false,
                        checkedOnce = true,
                        via = outcome.via,
                    ),
                )
            }
            // checkedOnce, so a caret move does not ask again; the next edit does.
            is GrammarOutcome.Notice -> _uiState.update {
                it.copy(grammar = GrammarUi(sourceText = source, checking = false, checkedOnce = true, notice = outcome.notice))
            }
            GrammarOutcome.HarperPending -> awaitGrammarModule()
            GrammarOutcome.HarperMissing -> _uiState.update { it.copy(grammar = GrammarUi(available = false)) }
        }
    }

    /** Replaces the whole field with [newText] (same mechanics as translate). */
    private fun replaceFieldText(newText: String) {
        val ic = currentInputConnection ?: return
        // See onTranslateReplace: an active composing region would hijack the
        // commitText away from the select-all and splice instead of replace.
        ic.finishComposingText()
        revision = null
        composing = StringBuilder()
        ic.beginBatchEdit()
        val length = runCatching {
            ic.getExtractedText(ExtractedTextRequest(), 0)?.text?.length
        }.getOrNull()
        if (length != null) {
            ic.setSelection(0, length)
        } else {
            ic.performContextMenuAction(android.R.id.selectAll)
        }
        ic.commitText(newText, 1)
        ic.endBatchEdit()
    }

    /**
     * Applies [edits] to the focused field in place, touching only the spans
     * they name and leaving the rest of the field exactly as the editor has
     * it — every style span intact, nothing re-committed.
     *
     * This is what a grammar fix uses instead of [replaceFieldText]. Select-all
     * plus commit is a rewrite of the whole note: in an editor that carries
     * formatting (Google Keep, any rich-text field) it lands as one flat run of
     * plain text, and even in a plain field it churns text the fix never
     * touched. Selecting the span and committing over it is the minimal edit.
     *
     * [edits] must be back-to-front, which is what [GrammarChecker.editsAll]
     * returns: every edit shifts the offsets after it, so working right to left
     * keeps the remaining offsets valid.
     *
     * Returns false when the field's offsets cannot be addressed at all (see
     * [fieldTextOrigin]), so the caller can fall back to the whole-field
     * rewrite rather than splicing at the wrong place.
     */
    private fun replaceFieldSpans(edits: List<GrammarEdit>): Boolean {
        val origin = fieldTextOrigin ?: return false
        val ic = currentInputConnection ?: return false
        if (edits.isEmpty()) return true
        // See replaceFieldText: a live composing region would hijack the
        // commitText away from the selection and splice at the cursor instead.
        ic.finishComposingText()
        revision = null
        composing = StringBuilder()
        ic.beginBatchEdit()
        for (edit in edits) {
            ic.setSelection(origin + edit.start, origin + edit.end)
            ic.commitText(edit.text, 1)
        }
        ic.endBatchEdit()
        // The last edit applied is the leftmost one, so the caret ends at the
        // first thing that changed. Mirror it into the cache, or a backspace
        // before the editor echoes the new selection targets the old spot.
        val last = edits.last()
        val caret = origin + last.start + last.text.length
        expectedSelStart = caret
        expectedSelEnd = caret
        return true
    }

    /**
     * Re-lints [text] directly, without the InputConnection round-trip.
     * Used right after a fix is applied: extracting the field again races the
     * batch edit (the editor may still report the old text, which matches
     * [GrammarUi.sourceText] and skips the check), so lint the string we just
     * committed instead. checkedOnce stays false until this completes so the
     * selection-update recheck re-lints rather than skipping if this job gets
     * cancelled mid-check.
     */
    private fun relintAfterFix(text: String) {
        grammarJob?.cancel()
        grammarJob = serviceScope.launch {
            _uiState.update {
                it.copy(
                    grammar = it.grammar.copy(
                        sourceText = text,
                        checking = true,
                        checkedOnce = false,
                    ),
                )
            }
            val outcome = lintField(text, _uiState.value.settings.grammarDialect)
            if (_uiState.value.panel != PanelMode.GRAMMAR) return@launch
            showGrammarOutcome(text, outcome)
        }
    }

    /**
     * The grammar panel's service callbacks as one [KeyboardScreen] parameter,
     * built outside `ServiceKeyboardContent` for the reason
     * [translateCallbacks] is: that call sits against the 64K method ceiling.
     */
    private val grammarCallbacks by lazy {
        com.wasimaster.wmkeyboard.ime.ui.GrammarCallbacks(
            onFix = ::onGrammarFix,
            onFixAll = ::onGrammarFixAll,
            onDismiss = ::onGrammarDismiss,
            onDialect = ::onGrammarDialectChange,
            onFocus = ::onGrammarFocus,
            onKindShown = ::onGrammarKindShown,
            onCategoryShown = ::onGrammarCategoryShown,
            onShowAllKinds = ::onGrammarShowAllKinds,
            onRephrase = ::onGrammarRephrase,
            onRephraseApply = ::onGrammarRephraseApply,
            onRephraseDismiss = ::onGrammarRephraseDismiss,
        )
    }

    private var rephraseJob: Job? = null

    /** DeepL Write, blocking on [Dispatchers.IO]; the style is the user's (#331). */
    private suspend fun deeplRephrase(text: String, deepl: DeepLSettings): Result<DeepLClient.Rephrase> =
        withContext(Dispatchers.IO) {
            runCancellable {
                DeepLClient.rephrase(
                    text = text,
                    apiKey = deepl.apiKey,
                    endpoint = deepl.endpoint,
                    writingStyle = deepl.writeStyle.writingStyle,
                    tone = deepl.writeStyle.tone,
                )
            }
        }

    /**
     * The DeepL Write chip in the grammar panel: ask DeepL to rewrite the
     * field (the first [DeepLClient.MAX_CHARS] of it) and show the result as a
     * card above the issues. Nothing changes in the field until Replace.
     */
    fun onGrammarRephrase() {
        val state = _uiState.value
        val deepl = state.settings.deeplLive
        if (!deepl.writeActive || state.grammar.rephrase?.working == true) return
        // The whole field goes to DeepL, so a password field is refused here
        // the same way the AI actions and chat refuse it.
        if (state.secureField) return
        vibrate()
        val text = state.grammar.sourceText.ifBlank { extractFieldText() }.take(DeepLClient.MAX_CHARS)
        if (text.isBlank()) return
        val pending = DeepLWriteUi(source = text)
        _uiState.update { it.copy(grammar = it.grammar.copy(rephrase = pending)) }
        rephraseJob?.cancel()
        rephraseJob = serviceScope.launch {
            val result = deeplRephrase(text, deepl)
            _uiState.update { s ->
                // A lint of changed text has dropped the request; its answer
                // would describe text that is no longer there.
                if (s.panel != PanelMode.GRAMMAR || s.grammar.rephrase?.let { it.working && it.source == text } != true) {
                    return@update s
                }
                val done = result.fold(
                    onSuccess = { pending.copy(result = it.text, working = false) },
                    onFailure = { e ->
                        pending.copy(working = false, error = requestErrorText(e, R.string.ime_grammar_deepl_error))
                    },
                )
                s.copy(grammar = s.grammar.copy(rephrase = done))
            }
        }
    }

    /** Replace on the DeepL Write card: the text sent becomes DeepL's text. */
    fun onGrammarRephraseApply() {
        val grammar = _uiState.value.grammar
        val rephrase = grammar.rephrase ?: return
        if (rephrase.working || rephrase.result.isEmpty()) return
        vibrate()
        val field = grammar.sourceText.ifBlank { rephrase.source }
        // Only the part that was sent is swapped: the field can run past what
        // one request carries, and the rest of it stays exactly as it is.
        if (!field.startsWith(rephrase.source)) return
        val rewritten = rephrase.result + field.substring(rephrase.source.length)
        if (!replaceFieldSpans(listOf(GrammarEdit(0, rephrase.source.length, rephrase.result)))) {
            // Offsets unknown: a whole-field rewrite is only safe when the
            // extraction saw the whole field.
            if (!fieldTextComplete) return toast(R.string.ime_grammar_deepl_replace_failed_toast)
            replaceFieldText(rewritten)
        }
        relintAfterFix(rewritten)
    }

    /** The X on the DeepL Write card. */
    fun onGrammarRephraseDismiss() {
        rephraseJob?.cancel()
        _uiState.update { it.copy(grammar = it.grammar.copy(rephrase = null)) }
    }

    /** Tapped one fix chip: apply it and re-lint the result. */
    fun onGrammarFix(lint: GrammarLint, fix: GrammarFix) {
        vibrate()
        val source = _uiState.value.grammar.sourceText
        val edit = GrammarChecker.edit(source, lint, fix) ?: return
        val fixed = source.replaceRange(edit.start, edit.end, edit.text)
        if (fixed == source) return
        // The fix rewrites one span, so that is all the editor is asked to
        // change; the whole-field rewrite is only for fields whose offsets we
        // cannot address.
        if (!replaceFieldSpans(listOf(edit))) replaceFieldText(fixed)
        relintAfterFix(fixed)
    }

    /**
     * Tapped a card body (not a fix chip): jump the field cursor to the issue.
     * A multi-word span (sentence-level lint) parks the cursor at its start; a
     * word that needs swapping gets selected ready to overtype; a small fix
     * (add punctuation, recase) parks the cursor at the word's end. Offsets are
     * UTF-16 into [GrammarUi.sourceText], which [fieldTextOrigin] shifts onto
     * the field's own coordinates (a no-op for every editor that hands over the
     * whole field, which is nearly all of them).
     */
    fun onGrammarFocus(lint: GrammarLint) {
        vibrate()
        val ic = currentInputConnection ?: return
        val source = _uiState.value.grammar.sourceText
        val from = lint.start.coerceIn(0, source.length)
        val to = lint.end.coerceIn(from, source.length)
        val span = source.substring(from, to)
        val hasReplacement = lint.suggestions.any { fix ->
            fix.kind == "replace" && !fix.text.isNullOrEmpty() &&
                !fix.text.equals(span, ignoreCase = true)
        }
        val multiWord = span.trim().any { it.isWhitespace() }
        val origin = fieldTextOrigin ?: 0
        val start = origin + from
        val end = origin + to
        // Mirror each placement into the cache too, so a backspace before
        // the editor echoes the new selection hits the right target.
        when {
            multiWord -> {
                ic.setSelection(start, start)
                expectedSelStart = start
                expectedSelEnd = start
            }
            hasReplacement -> {
                ic.setSelection(start, end)
                expectedSelStart = start
                expectedSelEnd = end
            }
            else -> {
                ic.setSelection(end, end)
                expectedSelStart = end
                expectedSelEnd = end
            }
        }
    }

    /**
     * Tapped "Fix all": apply the top suggestion of every issue the panel is
     * showing. Issues the filter hides are left alone — the button says how
     * many it will fix, and that count is of the visible ones.
     */
    fun onGrammarFixAll() {
        vibrate()
        val source = _uiState.value.grammar.sourceText
        val edits = GrammarChecker.editsAll(source, _uiState.value.visibleGrammarLints)
        var fixed = source
        for (edit in edits) fixed = fixed.replaceRange(edit.start, edit.end, edit.text)
        if (fixed == source) return
        // Back-to-front, in one batch edit: the untouched text between the
        // issues is never re-committed, so it keeps its styling.
        if (!replaceFieldSpans(edits)) replaceFieldText(fixed)
        relintAfterFix(fixed)
    }

    /** Dismissed a card: hide the lint until the field text changes again. */
    fun onGrammarDismiss(lint: GrammarLint) {
        vibrate()
        _uiState.update { it.copy(grammar = it.grammar.copy(lints = it.grammar.lints - lint)) }
    }

    /** Toggled one issue kind in the panel's filter. */
    fun onGrammarKindShown(kind: GrammarLintKind, shown: Boolean) {
        vibrate()
        serviceScope.launch { settingsRepository.setGrammarKindShown(kind, shown) }
    }

    /** Toggled a whole category in the panel's filter — every kind inside it. */
    fun onGrammarCategoryShown(category: GrammarCategory, shown: Boolean) {
        vibrate()
        serviceScope.launch { settingsRepository.setGrammarCategoryShown(category, shown) }
    }

    /** Cleared the panel's filter: every kind of issue is worth showing again. */
    fun onGrammarShowAllKinds() {
        vibrate()
        serviceScope.launch { settingsRepository.setGrammarHiddenKinds(emptySet()) }
    }

    fun onGrammarDialectChange(dialect: GrammarDialect) {
        vibrate()
        serviceScope.launch { settingsRepository.setGrammarDialect(dialect) }
        // Force a fresh lint: clear checkedOnce so the same text re-checks
        // under the new dialect (the settings flow updates asynchronously,
        // so check directly with the new value).
        _uiState.update { it.copy(grammar = it.grammar.copy(checkedOnce = false, checking = true)) }
        grammarJob?.cancel()
        grammarJob = serviceScope.launch {
            val source = extractFieldText()
            if (source.isBlank()) {
                _uiState.update { it.copy(grammar = GrammarUi()) }
                return@launch
            }
            val outcome = lintField(source, dialect)
            if (_uiState.value.panel != PanelMode.GRAMMAR) return@launch
            showGrammarOutcome(source, outcome)
        }
    }

    /**
     * The toolbar's caret-moving tools, which are the panel's moves one tap deep
     * instead of two. Holding shift turns them into shift+arrow: the move
     * extends the selection instead of collapsing it, exactly as a physical
     * keyboard's would.
     *
     * The shift is read but not spent. Repeated taps have to keep extending —
     * one character of selection is no use — and a shift the user pressed is
     * theirs to end, by pressing it again or by putting the caret somewhere
     * else. Nor does it touch the panel's own select mode: that toggle belongs
     * to the panel, and quietly leaving it on would keep these tools selecting
     * long after the shift went away.
     *
     * Only the toolbar reads shift this way. Inside the text-editing panel the
     * shift key isn't even on screen, so a shift left armed there is a leftover,
     * not an instruction, and the panel's select toggle stays the only answer.
     */
    private fun onCursorTool(action: TextEditAction) {
        onTextEdit(action, extendSelection = _uiState.value.shiftSelectsText)
    }

    /** Counts presses of the Selection mode tool into a tap, a double or a triple. */
    private val selectionTaps = SelectionTapCounter(SHIFT_DOUBLE_TAP_MS)

    /**
     * A press of the toolbar's Selection mode tool.
     *
     * One tap turns the mode on, and the next one turns it off: while it is on
     * every caret move extends the selection instead of collapsing it, wherever
     * the move comes from — the arrow tools, the text-editing panel, the
     * spacebar cursor swipe, the volume keys, a layout's own arrow keys. That is
     * the whole point of the mode over a held shift: the hand that moves the
     * caret is free.
     *
     * Two quick taps select the word at the cursor and three select the line,
     * both of which leave the mode on so the selection can be adjusted from
     * there. The first tap of a double has already toggled by then, which is
     * what the shift key's double tap does too and is the price of a mode that
     * comes on the instant it is asked for.
     *
     * Turning the mode off does not touch the selection. Only the extending
     * stops; what is selected stays selected, ready for copy or for typing over.
     */
    private fun onSelectModeTap() {
        val multiTap = _uiState.value.settings.textEditing.selectionModeMultiTap
        when (selectionTaps.tap(SystemClock.uptimeMillis(), multiTap)) {
            SelectionTap.TOGGLE -> {
                vibrate()
                if (_uiState.value.selectingText) clearSelectionArm() else armSelectionMode()
            }
            // These two buzz and commit through onTextEdit, the same path the
            // Select word and Select line tools take.
            SelectionTap.WORD -> {
                onTextEdit(TextEditAction.SELECT_WORD)
                armSelectionMode()
            }
            SelectionTap.LINE -> {
                onTextEdit(TextEditAction.SELECT_LINE)
                armSelectionMode()
            }
        }
    }

    /** The same ladder for a panel layout's Select key, counted separately. */
    private val selectKeyTaps = SelectionTapCounter(SHIFT_DOUBLE_TAP_MS)

    /**
     * A press of a Select key on a panel layout — the text-edit pad's own
     * toggle (issue #41).
     *
     * The Selection mode tool's ladder, on its own counter: two buttons that
     * share one would read a tap on each as a double and select a word nobody
     * asked for. One tap toggles, two select the word at the cursor, three the
     * line, and the two selecting rungs leave the arm on so the selection can
     * be nudged from there.
     *
     * Deliberately not [onSelectModeTap]: the plain toggle stays on the panel's
     * own [KeyboardUiState.textEditSelecting], which dies with the panel, while
     * the tool's sticky mode outlives it. Only the rung changes here, never
     * which flag the key owns.
     *
     * Silent: the key buzzed on the way down like every other panel key.
     */
    private fun onSelectKeyTap() {
        val multiTap = _uiState.value.settings.textEditing.selectionModeMultiTap
        when (selectKeyTaps.tap(SystemClock.uptimeMillis(), multiTap)) {
            SelectionTap.TOGGLE -> onTextEdit(TextEditAction.SELECT, haptic = false)
            SelectionTap.WORD -> {
                onTextEdit(TextEditAction.SELECT_WORD, haptic = false)
                _uiState.update { it.copy(textEditSelecting = true) }
            }
            SelectionTap.LINE -> {
                onTextEdit(TextEditAction.SELECT_LINE, haptic = false)
                _uiState.update { it.copy(textEditSelecting = true) }
            }
        }
    }

    /**
     * The Selection mode tool held down (true) and let go (false): selection
     * mode for exactly as long as the finger stays on the button.
     *
     * The release leaves the selection alone and the sticky mode alone. It ends
     * this hold and nothing else, so a hold inside a mode the user had already
     * switched on gives the mode back on release rather than taking it away.
     */
    fun onSelectionHold(down: Boolean) {
        // A hold is not a tap. Without this, the tap after a hold would count as
        // the second of a double and select a word nobody asked for. Both
        // counters, because either button's hold reaches this.
        selectionTaps.reset()
        selectKeyTaps.reset()
        _uiState.update { it.copy(selectionHold = down) }
    }

    /**
     * What a press and hold on a tool reaches, built outside
     * [ServiceKeyboardContent] for the reason [converterCallbacks] is: that
     * method sits against the JVM's 64K size ceiling, so the two callbacks
