    /**
     * What the Location tool's Found tab reads for places somebody sent: the
     * text around the caret, never in a password field, and the recent clips
     * that are not marked sensitive.
     */
    private fun locationFoundTexts(): List<Pair<String, com.wasimaster.wmkeyboard.ime.location.FoundOrigin>> = buildList {
        val ic = currentInputConnection
        if (ic != null && !currentInputEditorInfo.isSecureField()) {
            val around = ic.getTextBeforeCursor(LOCATION_FIELD_CHARS, 0)?.toString().orEmpty() +
                ic.getTextAfterCursor(LOCATION_FIELD_CHARS, 0)?.toString().orEmpty()
            if (around.isNotBlank()) add(around to com.wasimaster.wmkeyboard.ime.location.FoundOrigin.FIELD)
        }
        if (isClipboardAccessible()) {
            clipboardStore.items().asSequence()
                .filter { it.kind.isTextual && !it.sensitive }
                .take(LOCATION_CLIPS)
                .forEach { add(it.text.take(LOCATION_CLIP_CHARS) to com.wasimaster.wmkeyboard.ime.location.FoundOrigin.CLIPBOARD) }
        }
    }

    /**
     * The weather location was just written from a reading. The settings flow
     * brings it to [_uiState] a moment later; an open weather panel refetches
     * once it has, rather than with the old place.
     */
    private fun onWeatherLocationSaved(latitude: Float, longitude: Float) {
        if (_uiState.value.panel != PanelMode.WEATHER) return
        serviceScope.launch {
            withTimeoutOrNull(2_000) {
                _uiState.first { it.settings.weather.latitude == latitude && it.settings.weather.longitude == longitude }
            }
            refreshWeather(force = true)
        }
    }

    // ---- Notes tool (#560) ----

    private fun notesCallbacks() = com.wasimaster.wmkeyboard.ime.ui.NotesCallbacks(
        onFilter = ::onNotesFilter,
        onSearchToggle = ::onNotesSearchToggle,
        onSearchClear = ::onNotesSearchClear,
        onOpen = ::onNoteOpen,
        onBack = ::onNotesBack,
        onReadExpand = ::onNotesReadExpand,
        onNew = ::onNotesNew,
        onEditStart = ::onNoteEditStart,
        onEditFocus = ::onNoteEditFocus,
        onEditDone = ::onNoteEditDone,
        onEditCancel = ::onNoteEditCancel,
        onMarkdown = ::onNoteMarkdown,
        onTagToggle = ::onNoteTagToggle,
        onTagPickerToggle = ::onNoteTagPickerToggle,
        onTagTypeStart = ::onNoteTagTypeStart,
        onTagCommit = ::onNoteTagCommit,
        onTagTypeCancel = ::onNoteTagTypeCancel,
        onInsert = ::onNoteInsert,
        onCopy = ::onNoteCopy,
        onShare = ::onNoteShare,
        onPin = ::onNotePin,
        onArchive = ::onNoteArchive,
        onLock = ::onNoteLock,
        onTrash = ::onNoteTrash,
        onRestore = ::onNoteRestore,
        onDeleteForever = ::onNoteDeleteForever,
        onEmptyTrash = ::onNotesEmptyTrash,
        onConfirmDismiss = ::onNotesConfirmDismiss,
        onTaskToggle = ::onNoteTaskToggle,
        onHold = ::onNoteHold,
        onUndo = ::onNotesUndo,
        onUndoDismiss = ::onNotesUndoDismiss,
        onQuickPick = ::onNotesQuickPick,
    )

    /**
     * Recomputes what the panel lists from the store, after [transform] has
     * changed the rest of its state. Everything the list is a function of —
     * the filter, the query, the sort, whether the device is locked — is read
     * here, so no handler has to remember to refresh the rows itself.
     */
    private fun publishNotes(transform: (NotesPanelUi) -> NotesPanelUi = { it }) {
        _uiState.update { state ->
            val notes = transform(state.notes)
            val deviceLocked = state.deviceLocked
            // An open note that was deleted for good, in the app or by the
            // trash's timer, has nothing left to show.
            val open = notes.open?.takeIf { noteStore.item(it) != null }
            val sort = state.settings.notes.sort
            val byWords = NotesLogic.visible(noteStore, notes.filter, notes.query, sort, deviceLocked)
            // Then the notes only search by meaning found, from the same shelf.
            val meaningIds = state.meaning.notes.forQuery(notes.query)
            val items = if (meaningIds.isEmpty()) {
                byWords
            } else {
                MeaningHits.append(byWords, NotesLogic.visible(noteStore, notes.filter, "", sort, deviceLocked), meaningIds) { it.id.toString() }
            }
            state.copy(
                notes = notes.copy(
                    available = userUnlocked,
                    items = items,
                    tags = noteStore.tags(),
                    counts = NotesLogic.counts(noteStore, deviceLocked),
                    open = open,
                    editing = notes.editing?.takeIf { open != null || it.isNew },
                    recent = if (notes.quick) NotesLogic.recent(noteStore) else emptyList(),
                ),
            )
        }
    }

    /** Writes the notes file on [persistDispatcher]; the store encodes outside its lock. */
    private fun saveNotesSoon() {
        serviceScope.launch(persistDispatcher) { noteStore.save() }
    }

    /**
     * Re-reads the file when the settings app wrote it since this process
     * last did, and lets an open edit meet the change (see
     * [NotesLogic.resolveConflict]).
     */
    private fun reloadNotesIfChanged() {
        if (!noteStore.reloadIfChanged()) return
        val edit = _uiState.value.notes.editing ?: return
        val resolved = NotesLogic.resolveConflict(edit, noteStore.item(edit.id))
        _uiState.update { it.copy(notes = it.notes.copy(editing = resolved)) }
    }

    /** The panel just opened: the file is read again, and the setting says where it lands. */
    private fun openNotesPanel() {
        reloadNotesIfChanged()
        publishNotes { notes ->
            val start = notes.open
                ?: if (_uiState.value.settings.notes.panelOpensOn == NotesPanelStart.LAST_NOTE) noteStore.lastEdited()?.id else null
            notes.copy(open = start, readExpanded = false)
        }
    }

    /** Leaving the panel: the draft is written, and the editor, search, confirmation and Undo bar go. */
    private fun notesLeavePanel() {
        notesFlushEdit(leaveEditor = true)
        notesUndoJob?.cancel()
        notesUndoJob = null
        notesConfirmJob?.cancel()
        notesConfirmJob = null
        _uiState.update {
            it.copy(
                notes = it.notes.copy(searchActive = false, query = "", held = null, confirm = null, undo = null, quick = false, recent = emptyList()),
            )
        }
    }

    /** An edit to one of the editor's drafts; the store is written once the typing pauses. */
    private fun noteEditDraft(transform: (NoteEdit) -> NoteEdit) {
        _uiState.update { state ->
            val edit = state.notes.editing ?: return@update state
            state.copy(notes = state.notes.copy(editing = transform(edit)))
        }
        notesAutosaveJob?.cancel()
        notesAutosaveJob = serviceScope.launch {
            delay(NOTES_AUTOSAVE_MS)
            notesAutosaveJob = null
            notesFlushEdit()
        }
    }

    /**
     * Writes the editor's drafts to the store. With [leaveEditor] the editor
     * closes as well, and a new note left blank is thrown away rather than
     * kept as an empty row. A note deleted for good while it was open is
     * added back from the draft: the words are the user's.
     */
    private fun notesFlushEdit(leaveEditor: Boolean = false) {
        notesAutosaveJob?.cancel()
        notesAutosaveJob = null
        val edit = _uiState.value.notes.editing ?: return
        var current = edit
        if (edit.dirty) {
            val stored = noteStore.item(edit.id)
            val draft = (stored ?: edit.original).copy(title = edit.titleDraft, body = edit.bodyDraft, tags = edit.tags)
            val saved = noteStore.update(draft) ?: noteStore.add(draft.copy(deletedAt = null))
            current = edit.copy(id = saved.id, original = saved, tags = saved.tags)
            saveNotesSoon()
        }
        if (leaveEditor && current.isNew && current.blank) {
            noteStore.deleteForever(current.id)
            saveNotesSoon()
            publishNotes { it.copy(editing = null, open = null) }
            return
        }
        publishNotes { notes ->
            notes.copy(
                editing = if (leaveEditor) null else current,
                open = if (notes.open == edit.id) current.id else notes.open,
            )
        }
    }

    fun onNotesFilter(filter: NotesFilter) {
        vibrate()
        publishNotes { it.copy(filter = filter, held = null, confirm = null) }
        _uiState.update { it.copy(panelFocus = null) }
    }

    /** The search pill tapped: it takes the keys, or gives them back and forgets the query. */
    fun onNotesSearchToggle() {
        vibrate()
        if (_uiState.value.notes.editing != null) notesFlushEdit(leaveEditor = true)
        publishNotes {
            if (it.searchActive) it.copy(searchActive = false, query = "") else it.copy(searchActive = true, held = null, confirm = null)
        }
        _uiState.update { it.copy(panelFocus = null) }
    }

    fun onNotesSearchClear() {
        vibrate()
        publishNotes { it.copy(query = "") }
    }

    fun onNoteOpen(id: Long) {
        vibrate()
        if (noteStore.item(id) == null) return
        publishNotes { it.copy(open = id, readExpanded = false, held = null, confirm = null) }
        _uiState.update { it.copy(panelFocus = null) }
    }

    /** The header's back: out of the editor, then out of the note, then out of the panel. */
    fun onNotesBack() {
        val notes = _uiState.value.notes
        when {
            notes.editing != null -> onNoteEditDone()
            notes.open != null -> {
                vibrate()
                publishNotes { it.copy(open = null, readExpanded = false, confirm = null) }
                _uiState.update { it.copy(panelFocus = null) }
            }
            else -> onPanelChange(PanelMode.NOTES)
        }
    }

    fun onNotesReadExpand() {
        vibrate()
        _uiState.update { it.copy(notes = it.notes.copy(readExpanded = !it.notes.readExpanded)) }
    }

    /** New note, optionally born with [tag]: made in the store at once, so it has an id to autosave under. */
    fun onNotesNew(tag: String?) = startNewNote(tag, NoteEditField.TITLE)

    /**
     * The Quick note action (#864): the Notes panel opens on a new note with
     * the keys already in its body, and the editor carries the row of the
     * latest notes. Fired again while that is up, it closes the panel, the
     * way a second tap on a tool does. The new note is the panel's ordinary
     * one, so left blank it is thrown away like any other.
     */
    private fun onQuickNote() {
        if (!userUnlocked) {
            toast(R.string.ime_notes_unlock_toast)
            return
        }
        val state = _uiState.value
        if (state.panel == PanelMode.NOTES && state.notes.quick) {
            onPanelChange(PanelMode.NOTES)
            return
        }
        if (state.panel != PanelMode.NOTES) onPanelChange(PanelMode.NOTES)
        if (_uiState.value.panel != PanelMode.NOTES) return
        _uiState.update { it.copy(notes = it.notes.copy(quick = true)) }
        startNewNote(tag = null, focus = NoteEditField.BODY)
    }

    /**
     * A chip on the quick row: a note to add to, its caret at the end, or
     * null for a fresh note. The note being left is saved, and a new one left
     * blank goes, as leaving the editor any other way does.
     */
    fun onNotesQuickPick(id: Long?) {
        val edit = _uiState.value.notes.editing
        if (edit?.focused == NoteEditField.TAG) onNoteTagCommit()
        if (id == null) {
            if (edit?.isNew == true && edit.blank) return
            startNewNote(tag = null, focus = NoteEditField.BODY)
            return
        }
        if (edit?.id == id) return
        notesFlushEdit(leaveEditor = true)
        onNoteEditStart(id, line = null)
    }

    /** A new note in the editor, the keys in [focus]: the title from New, the body from Quick note. */
    private fun startNewNote(tag: String?, focus: NoteEditField) {
        if (!userUnlocked) {
            toast(R.string.ime_notes_unlock_toast)
            return
        }
        vibrate()
        notesFlushEdit(leaveEditor = true)
        currentInputConnection?.let { commitComposing(it, autocorrect = false) }
        val note = noteStore.add("", tags = listOfNotNull(tag))
        saveNotesSoon()
        publishNotes {
            it.copy(
                open = note.id,
                editing = NoteEdit(note.id, isNew = true, original = note, focused = focus, startedAt = System.currentTimeMillis()),
                searchActive = false,
                query = "",
                held = null,
                confirm = null,
                readExpanded = false,
            )
        }
        _uiState.update { it.copy(panelFocus = null) }
    }

    /**
     * Edit the open note, the caret at the start of [line] when a block was
     * tapped. Locked notes and notes past the editor's size are refused; the
     * panel's Edit chip already says where they can be edited.
     */
    fun onNoteEditStart(id: Long, line: Int?) {
        val note = noteStore.item(id) ?: return
        if (note.locked) {
            toast(R.string.ime_notes_locked_toast)
            return
        }
        if (note.body.length > NoteEdit.EDITOR_MAX_LENGTH) {
            toast(R.string.ime_notes_too_long_info)
            return
        }
        vibrate()
        currentInputConnection?.let { commitComposing(it, autocorrect = false) }
        val at = if (line != null) NotesLogic.lineStartOffset(note.body, line) else note.body.length
        publishNotes {
            it.copy(
                open = id,
                editing = NoteEdit(id, isNew = false, original = note, focused = NoteEditField.BODY, startedAt = System.currentTimeMillis()),
                searchActive = false,
                query = "",
                held = null,
                confirm = null,
            )
        }
        _uiState.update {
            it.copy(panelFocus = null, captureCaret = CaptureCaret(CaptureTarget.NOTE_BODY.name, at, note.body))
        }
    }

    /** A tap on the title or the body: that field takes the keys, the caret where the finger landed. */
    fun onNoteEditFocus(field: NoteEditField, caret: Int?) {
        val edit = _uiState.value.notes.editing ?: return
        if (edit.focused == NoteEditField.TAG && field != NoteEditField.TAG) onNoteTagCommit()
        _uiState.update { state ->
            val current = state.notes.editing ?: return@update state
            val next = current.copy(focused = field)
            val text = when (field) {
                NoteEditField.TITLE -> next.titleDraft
                NoteEditField.BODY -> next.bodyDraft
                NoteEditField.TAG -> next.tagDraft
            }
            val target = when (field) {
                NoteEditField.TITLE -> CaptureTarget.NOTE_TITLE
                NoteEditField.BODY -> CaptureTarget.NOTE_BODY
                NoteEditField.TAG -> CaptureTarget.NOTE_TAG
            }
            state.copy(
                notes = state.notes.copy(editing = next),
                captureCaret = CaptureCaret(target.name, (caret ?: text.length).coerceIn(0, text.length), text),
            )
        }
    }

    /** Done: the draft is kept and the editor closes onto the note. */
    fun onNoteEditDone() {
        if (_uiState.value.notes.editing == null) return
        vibrate()
        if (_uiState.value.notes.editing?.focused == NoteEditField.TAG) onNoteTagCommit()
        val edit = _uiState.value.notes.editing
        notesFlushEdit(leaveEditor = true)
        if (edit != null && edit.isNew && edit.blank) toast(R.string.ime_notes_empty_discarded)
        _uiState.update { it.copy(panelFocus = null) }
    }

    /** Cancel: the note goes back to how it was when the editor opened; a new one goes away. */
    fun onNoteEditCancel() {
        val edit = _uiState.value.notes.editing ?: return
        vibrate()
        notesAutosaveJob?.cancel()
        notesAutosaveJob = null
        if (edit.isNew) {
            noteStore.deleteForever(edit.id)
        } else {
            noteStore.update(edit.original)
        }
        saveNotesSoon()
        publishNotes { it.copy(editing = null, open = if (edit.isNew) null else it.open) }
        _uiState.update { it.copy(panelFocus = null) }
    }

    /** One of the editor's helper chips: the Markdown goes in at the caret or round the selection. */
    fun onNoteMarkdown(action: NoteMarkdownAction) {
        val state = _uiState.value
        if (state.captureTarget() != CaptureTarget.NOTE_BODY) {
            onNoteEditFocus(NoteEditField.BODY, caret = null)
        }
        val before = _uiState.value.captureCaretText() ?: return
        vibrate()
        captureWrite(CaptureTarget.NOTE_BODY, before, NotesLogic.applyMarkdown(before, action))
    }

    /**
     * A tag chip on a note: on or off. [colour] is the palette index a
     * suggested tag is born with; an existing tag keeps its own.
     */
    fun onNoteTagToggle(id: Long, name: String, colour: Int) {
        vibrate()
        val edit = _uiState.value.notes.editing
        val canonical = noteStore.addTag(name, colour)?.name ?: return
        if (edit != null && edit.id == id) {
            noteEditDraft { e ->
                val has = e.tags.any { it.equals(canonical, ignoreCase = true) }
                e.copy(tags = if (has) e.tags.filterNot { it.equals(canonical, ignoreCase = true) } else e.tags + canonical)
            }
            publishNotes()
            return
        }
        val note = noteStore.item(id) ?: return
        val tags = if (note.hasTag(canonical)) note.tags.filterNot { it.equals(canonical, ignoreCase = true) } else note.tags + canonical
        noteStore.setTags(id, tags)
        saveNotesSoon()
        publishNotes()
    }

    fun onNoteTagPickerToggle() {
        vibrate()
        if (_uiState.value.notes.editing?.focused == NoteEditField.TAG) onNoteTagTypeCancel()
        _uiState.update { s ->
            val e = s.notes.editing ?: return@update s
            s.copy(notes = s.notes.copy(editing = e.copy(tagPickerOpen = !e.tagPickerOpen)))
        }
    }

    /** "New…" in the tag row: a pill takes the keys for the tag's name. */
    fun onNoteTagTypeStart() {
        vibrate()
        _uiState.update { s ->
            val e = s.notes.editing ?: return@update s
            s.copy(
                notes = s.notes.copy(editing = e.copy(focused = NoteEditField.TAG, tagDraft = "", tagPickerOpen = true)),
                captureCaret = CaptureCaret(CaptureTarget.NOTE_TAG.name, 0, ""),
            )
        }
    }

    /** Enter in the tag pill: the name becomes a tag on the note, and the keys go back to the body. */
    fun onNoteTagCommit() {
        val edit = _uiState.value.notes.editing ?: return
        val name = edit.tagDraft.trim()
        if (name.isEmpty()) {
            onNoteTagTypeCancel()
            return
        }
        val canonical = noteStore.addTag(name)?.name
        noteEditDraft { e ->
            e.copy(
                tags = if (canonical != null && e.tags.none { it.equals(canonical, ignoreCase = true) }) e.tags + canonical else e.tags,
                tagDraft = "",
                focused = NoteEditField.BODY,
            )
        }
        _uiState.update { it.copy(captureCaret = null) }
        publishNotes()
    }

    fun onNoteTagTypeCancel() {
        _uiState.update { s ->
            val e = s.notes.editing ?: return@update s
            if (e.focused != NoteEditField.TAG) return@update s
            s.copy(notes = s.notes.copy(editing = e.copy(tagDraft = "", focused = NoteEditField.BODY)), captureCaret = null)
        }
    }

    /** The note's text into the field, as typed. A locked note never leaves the panel this way. */
    fun onNoteInsert(id: Long) {
        val note = noteStore.item(id) ?: return
        if (note.locked) {
            toast(R.string.ime_notes_locked_toast)
            return
        }
        vibrate()
        val ic = currentInputConnection ?: return
        commitComposing(ic, autocorrect = false)
        ic.commitText(note.body.ifBlank { note.title }, 1)
    }

    fun onNoteCopy(id: Long) {
        val note = noteStore.item(id) ?: return
        if (note.locked) {
            toast(R.string.ime_notes_locked_toast)
            return
        }
        vibrate()
        KeyboardClipboard.copy(this, note.body.ifBlank { note.title })
        toast(R.string.ime_notes_copied_toast)
    }

    fun onNoteShare(id: Long) {
        val note = noteStore.item(id) ?: return
        if (note.locked) {
            toast(R.string.ime_notes_locked_toast)
            return
        }
        vibrate()
        shareVia(
            Intent(Intent.ACTION_SEND)
                .setType("text/plain")
                .putExtra(Intent.EXTRA_SUBJECT, note.displayTitle())
                .putExtra(Intent.EXTRA_TEXT, note.body.ifBlank { note.title }),
            insertable = true,
        )
    }

    fun onNotePin(id: Long, pinned: Boolean) {
        vibrate()
        noteStore.setPinned(id, pinned) ?: return
        saveNotesSoon()
        publishNotes { it.copy(held = null) }
    }

    /** Archiving offers an Undo; an archived note that was open closes onto the list. */
    fun onNoteArchive(id: Long, archived: Boolean) {
        vibrate()
        if (_uiState.value.notes.editing?.id == id) notesFlushEdit(leaveEditor = true)
        noteStore.setArchived(id, archived) ?: return
        saveNotesSoon()
        publishNotes { it.copy(held = null, open = if (archived && it.open == id) null else it.open) }
        if (archived) offerNotesUndo(NotesUndoKind.ARCHIVED, id)
    }

    /**
     * Lock a note from the keyboard. One way only: unlocking asks for the
     * fingerprint, which an input method cannot raise, so that is the
     * settings app's.
     */
    fun onNoteLock(id: Long) {
        vibrate()
        if (_uiState.value.notes.editing?.id == id) notesFlushEdit(leaveEditor = true)
        noteStore.setLocked(id, true) ?: return
        saveNotesSoon()
        publishNotes { it.copy(held = null) }
    }

    /** To the trash, with an Undo bar; the trash itself is the longer undo. */
    fun onNoteTrash(id: Long) {
        vibrate()
        if (_uiState.value.notes.editing?.id == id) {
            notesAutosaveJob?.cancel()
            notesAutosaveJob = null
            _uiState.update { it.copy(notes = it.notes.copy(editing = null)) }
        }
        noteStore.trash(id) ?: return
        saveNotesSoon()
        publishNotes { it.copy(held = null, open = if (it.open == id) null else it.open, confirm = null) }
        _uiState.update { it.copy(panelFocus = null) }
        offerNotesUndo(NotesUndoKind.TRASHED, id)
    }

    fun onNoteRestore(id: Long) {
        vibrate()
        noteStore.restore(id) ?: return
        saveNotesSoon()
        publishNotes { it.copy(held = null, confirm = null) }
    }

    /** Two taps: the first arms the chip, the second within a few seconds deletes. */
    fun onNoteDeleteForever(id: Long) {
        vibrate()
        val confirm = _uiState.value.notes.confirm
        if (confirm is NotesConfirm.DeleteForever && confirm.id == id) {
            notesConfirmJob?.cancel()
            notesConfirmJob = null
            noteStore.deleteForever(id)
            saveNotesSoon()
            publishNotes { it.copy(confirm = null, held = null, open = if (it.open == id) null else it.open) }
            return
        }
        armNotesConfirm(NotesConfirm.DeleteForever(id))
    }

    fun onNotesEmptyTrash() {
        vibrate()
        if (_uiState.value.notes.confirm == NotesConfirm.EmptyTrash) {
            notesConfirmJob?.cancel()
            notesConfirmJob = null
            noteStore.emptyTrash()
            saveNotesSoon()
            publishNotes { it.copy(confirm = null, held = null, open = null) }
            return
        }
        armNotesConfirm(NotesConfirm.EmptyTrash)
    }

    private fun armNotesConfirm(confirm: NotesConfirm) {
        _uiState.update { it.copy(notes = it.notes.copy(confirm = confirm)) }
        notesConfirmJob?.cancel()
        notesConfirmJob = serviceScope.launch {
            delay(NOTES_CONFIRM_MS)
            notesConfirmJob = null
            _uiState.update { it.copy(notes = it.notes.copy(confirm = null)) }
        }
    }

    fun onNotesConfirmDismiss() {
        notesConfirmJob?.cancel()
        notesConfirmJob = null
        _uiState.update { it.copy(notes = it.notes.copy(confirm = null)) }
    }

    /** A task box tapped in the reading view, or in the editor's own note. */
    fun onNoteTaskToggle(id: Long, line: Int) {
        val edit = _uiState.value.notes.editing
        if (edit != null && edit.id == id) {
            val body = NoteChecklist.toggleTask(edit.bodyDraft, line) ?: return
            vibrate()
            noteEditDraft { it.copy(bodyDraft = body) }
            return
        }
        val note = noteStore.item(id) ?: return
        if (note.locked) return
        val body = NoteChecklist.toggleTask(note.body, line) ?: return
        vibrate()
        noteStore.update(note.copy(body = body))
        saveNotesSoon()
        publishNotes()
    }

    /** A long press on a row shows its action chips; null puts them away. */
    fun onNoteHold(id: Long?) {
        if (id != null) vibrate()
        _uiState.update { it.copy(notes = it.notes.copy(held = id, confirm = null)) }
    }

    private fun offerNotesUndo(kind: NotesUndoKind, id: Long) {
        _uiState.update { state ->
            val previous = state.notes.undo?.takeIf { it.kind == kind }
            state.copy(notes = state.notes.copy(undo = NotesUndo(kind, previous?.ids.orEmpty() + id)))
        }
        notesUndoJob?.cancel()
        notesUndoJob = serviceScope.launch {
            delay(clipUndoTimeoutMillis())
            notesUndoJob = null
            _uiState.update { it.copy(notes = it.notes.copy(undo = null)) }
        }
    }

    /** The Undo bar's button: every note it names goes back where it was. */
    fun onNotesUndo() {
        val undo = _uiState.value.notes.undo ?: return
        notesUndoJob?.cancel()
        notesUndoJob = null
        vibrate()
        for (id in undo.ids) {
            when (undo.kind) {
                NotesUndoKind.TRASHED -> noteStore.restore(id)
                NotesUndoKind.ARCHIVED -> noteStore.setArchived(id, false)
            }
        }
        saveNotesSoon()
        publishNotes { it.copy(undo = null) }
    }

    fun onNotesUndoDismiss() {
        notesUndoJob?.cancel()
        notesUndoJob = null
        _uiState.update { it.copy(notes = it.notes.copy(undo = null)) }
    }

    /**
     * The selection bar's Save as note: the selection becomes a new note, or
     * the end of the last note edited when the setting says so. Nothing from a
     * password field, and nothing before the first unlock, where there is no
     * file to write to.
     */
    private fun saveSelectionAsNote(text: String) {
        if (!userUnlocked) {
            toast(R.string.ime_notes_unlock_toast)
            return
        }
        if (_uiState.value.secureField || text.isBlank()) return
        reloadNotesIfChanged()
        val last = if (_uiState.value.settings.notes.saveSelectionAppends) noteStore.lastEdited() else null
        if (last != null) noteStore.append(last.id, text) else noteStore.add(body = text)
        saveNotesSoon()
        publishNotes()
        toast(if (last != null) R.string.ime_notes_appended_toast else R.string.ime_notes_saved_toast)
    }

    // ---- Learn from text (#174) ----

    /** The last scan behind the Learn from text panel: every word and pair in the text it read. */
    private var learnScan: TextWordScan.Result = TextWordScan.Result.EMPTY
    private var learnJob: Job? = null
    private var learnSeq = 0

    /**
     * Reads the selection, or the whole field when nothing is selected, and
     * lists the words in it the keyboard does not know. Nothing is read from a
     * password field. The scan runs off the main thread; the known-word check
     * runs back on it, where the engine lives.
     */
    private fun scanForLearning() {
        learnJob?.cancel()
        val seq = ++learnSeq
        if (_uiState.value.secureField) {
            updateLearnFromText { it.copy(scanning = false, blocked = true) }
            return
        }
        val ic = currentInputConnection
        val hasSelection = expectedSelStart >= 0 && expectedSelEnd >= 0 && expectedSelStart != expectedSelEnd
        // A selection too big for the binder comes back null: read the field instead.
        val selected = if (ic != null && hasSelection) {
            runCatching { ic.getSelectedText(0)?.toString() }.getOrNull()
        } else {
            null
        }
        val text: String
        val origin: Int?
        val partial: Boolean
        if (!selected.isNullOrEmpty()) {
            text = selected
            origin = minOf(expectedSelStart, expectedSelEnd)
            partial = false
        } else {
            text = extractFieldText()
            origin = fieldTextOrigin
            partial = !fieldTextComplete
        }

        learnJob = serviceScope.launch {
            val scan = withContext(Dispatchers.Default) { TextWordScan.scan(text, SENTENCE_ENDERS) }
            if (seq != learnSeq || _uiState.value.panel != PanelMode.LEARN_FROM_TEXT) return@launch
            learnScan = scan
            val settings = _uiState.value.settings
            val found = LearnFromText.sorted(
                LearnFromText.rowsFor(
                    scan,
                    isKnown = ::isKnownWord,
                    blacklist = settings.suggestionSources.blacklist,
                    sightings = pendingLearn::sightings,
                ),
                settings.suggestionStrip.learnFromTextSort,
            )
            updateLearnFromText {
                it.copy(
                    scanning = false,
                    rows = found.take(LearnFromText.MAX_ROWS),
                    capped = found.size > LearnFromText.MAX_ROWS,
                    origin = origin,
                    partial = partial,
                )
            }
        }
    }

    private fun updateLearnFromText(transform: (LearnFromTextUi) -> LearnFromTextUi) {
        _uiState.update { state -> state.learnFromText?.let { state.copy(learnFromText = transform(it)) } ?: state }
    }

    private fun onLearnToggle(key: String) = updateLearnFromText { ui ->
        ui.copy(rows = ui.rows.map { if (it.key == key) it.copy(checked = !it.checked) else it }, result = null)
    }

    private fun onLearnToggleAll() = updateLearnFromText { ui ->
        val all = ui.rows.all { it.checked }
        ui.copy(rows = ui.rows.map { it.copy(checked = !all) }, result = null)
    }

    private fun onLearnSort(sort: com.wasimaster.wmkeyboard.core.settings.LearnFromTextSort) {
        updateLearnFromText { it.copy(rows = LearnFromText.sorted(it.rows, sort)) }
        serviceScope.launch { settingsRepository.setLearnFromTextSort(sort) }
    }

    private fun onLearnPairs(on: Boolean) {
        serviceScope.launch { settingsRepository.setLearnFromTextPairs(on) }
    }

    /** Hides a row for this scan only; the next scan lists the word again. */
    private fun onLearnIgnore(key: String) = updateLearnFromText { ui ->
        ui.copy(rows = ui.rows.filterNot { it.key == key }, result = null)
    }

    private fun onLearnNeverSuggest(key: String) {
        val row = _uiState.value.learnFromText?.rows?.firstOrNull { it.key == key } ?: return
        onLearnIgnore(key)
        serviceScope.launch { settingsRepository.addSuggestionBlacklistWord(row.finalSpelling) }
    }

    /** Selects the word's first occurrence in the field, so the user sees it in context. */
    private fun onLearnShow(key: String) {
        val ui = _uiState.value.learnFromText ?: return
        val row = ui.rows.firstOrNull { it.key == key } ?: return
        val origin = ui.origin ?: return
        val ic = currentInputConnection ?: return
        ic.finishComposingText()
        ic.setSelection(origin + row.start, origin + row.start + row.length)
        expectedSelStart = origin + row.start
        expectedSelEnd = origin + row.start + row.length
    }

    private fun onLearnEdit(key: String) = updateLearnFromText { ui ->
        val row = ui.rows.firstOrNull { it.key == key }
        if (row == null) ui else ui.copy(editing = key, editText = row.finalSpelling, result = null)
    }

    /** The spelling editor's buffer; the keys type here while [KeyboardUiState.learnEditActive]. */
    private fun learnEdit(transform: (String) -> String) = updateLearnFromText { ui ->
        if (ui.editing == null) ui else ui.copy(editText = transform(ui.editText).take(UserLexicon.MAX_WORD_LENGTH))
    }

    private fun onLearnEditDone() = updateLearnFromText { ui ->
        val key = ui.editing
        if (key == null || !ui.editValid) {
            ui
        } else {
            val spelling = ui.editText.trim()
            ui.copy(
                editing = null,
                editText = "",
                rows = ui.rows.map {
                    if (it.key == key) it.copy(edited = spelling.takeUnless { s -> s == it.spelling }, checked = true) else it
                },
            )
        }
    }

    private fun onLearnEditCancel() = updateLearnFromText { it.copy(editing = null, editText = "") }

    /**
     * Adds every checked word to the personal dictionary as a word the user
     * vouched for, then, with the Word pairs chip on, teaches the pairs the
     * text holds between words the keyboard now knows. Pairs follow the
     * learning switches typing does: off with learning off or paused.
     */
    private fun onLearnAdd() {
        val ui = _uiState.value.learnFromText ?: return
        val chosen = ui.rows.filter { it.checked }
        vibrate()
        val settings = _uiState.value.settings
        val scan = learnScan
        val blacklist = settings.suggestionSources.blacklist

        // Capture data and renames from main thread
        val renames = LearnFromText.renamesOf(chosen)
        val handAddBatch = chosen.map { row ->
            val spelling = row.finalSpelling.trim()
            spelling to (row.edited != null || row.caseEvidence)
        }

        serviceScope.launch {
            val (wordsAdded, pairsAdded) = withContext(Dispatchers.Default) {
                // Batch add unknown words on default thread if chosen
                if (handAddBatch.isNotEmpty()) {
                    addWordsByHand(handAddBatch)
                }

                if (learningAllowed) {
                    val chosenKeys = chosen.mapTo(HashSet()) { it.key }
                    // Learn additional occurrences for user-added words
                    for (row in chosen) {
                        val spelling = row.finalSpelling.trim()
                        if (row.count > 1) {
                            userLexicon.learnWord(
                                spelling,
                                count = row.count - 1,
                                caseEvidence = (row.edited != null || row.caseEvidence),
                            )
                        }
                    }

                    // Learn unigrams for known words in the scanned text (excluding newly added words)
                    for (word in scan.words) {
                        if (word.key !in chosenKeys &&
                            word.key.length in 2..UserLexicon.MAX_WORD_LENGTH &&
                            word.key !in blacklist &&
                            isKnownWord(word.key)
                        ) {
                            val spelling = renames[word.key] ?: word.spelling
                            userLexicon.learnWord(
                                spelling,
                                count = word.count,
                                caseEvidence = word.caseEvidence,
                            )
                        }
                    }
                }

                var pairCount = 0
                if (settings.suggestionStrip.learnFromTextPairs && learningAllowed) {
                    val plan = LearnFromText.plan(
                        scan,
                        renames = renames,
                        isKnown = ::isKnownWord,
                        blacklist = blacklist,
                    )
                    for ((pair, count) in plan.pairCounts) {
                        repeat(count) { userLexicon.learnBigram(pair.first, pair.second) }
                    }
                    for ((triple, count) in plan.tripleCounts) {
                        repeat(count) { userLexicon.learnTrigram(triple.first, triple.second, triple.third) }
                    }
                    for ((skip, count) in plan.skipCounts) {
                        repeat(count) { userLexicon.learnSkip1gram(skip.first, skip.second) }
                    }
                    for ((skip2, count) in plan.skip2Counts) {
                        repeat(count) { userLexicon.learnSkip2gram(skip2.first, skip2.second) }
                    }
                    pairCount = plan.pairs.size
                }
                chosen.size to pairCount
            }

            val addedKeys = chosen.mapTo(HashSet()) { it.key }
            updateLearnFromText {
                it.copy(rows = it.rows.filterNot { row -> row.key in addedKeys }, result = LearnResult(wordsAdded, pairsAdded))
            }
            refreshSuggestions()
        }
    }

    /**
     * [addTypedWord] for a batch: each word is the user's own answer, so it
     * leaves the waiting room and the settle queue, goes in marked as added by
     * hand, comes off the never-suggest list, and is mirrored to Android's
     * dictionary when that is on — in one pass of provider writes.
     */
    private fun addWordsByHand(words: List<Pair<String, Boolean>>) {
        val settings = _uiState.value.settings
        val mirrored = ArrayList<String>()
        for ((word, caseEvidence) in words) {
            if (word.isEmpty()) continue
            pendingLearn.forget(word)
            learningBuffer.drop(word)
            userLexicon.addWord(word, caseEvidence = caseEvidence)
            if (word.lowercase() in settings.suggestionSources.blacklist) {
                serviceScope.launch { settingsRepository.removeSuggestionBlacklistWord(word) }
            }
            mirrored.add(word)
        }
        if (settings.addWordsToSystemDictionary && mirrored.isNotEmpty()) {
            serviceScope.launch(Dispatchers.IO) {
                for (word in mirrored) SystemUserDictionary.add(applicationContext, word)
            }
        }
    }


    /**
     * Whether the trackpad panel is open because the toolbar's Trackpad tool is
     * being held, so the release closes exactly what the press opened and
     * leaves a panel the user opened with a tap alone.
     */
    private var trackpadHeld = false

    /**
     * The Trackpad tool held down (true) and let go (false): the trackpad panel
     * for as long as the finger stays on the button, for a quick nudge with the
     * other thumb (issue #39). A hold over a panel a tap already opened does
     * nothing on either end, so the tap's panel outlives it.
     */
    fun onTrackpadHold(down: Boolean) {
        if (down) {
            if (_uiState.value.panel != PanelMode.TRACKPAD) {
                trackpadHeld = true
                onPanelChange(PanelMode.TRACKPAD)
            }
        } else if (trackpadHeld) {
            trackpadHeld = false
            // onPanelChange toggles: asking for the open panel closes it. Only
            // while it is still the one the hold opened, so a tool tapped mid-
            // hold keeps its own panel.
            if (_uiState.value.panel == PanelMode.TRACKPAD) {
                onPanelChange(PanelMode.TRACKPAD, haptic = false)
            }
        }
    }

    /**
     * A trackpad or spacebar drag started (true) or stopped (false) moving the
     * caret: the magnifier over it (discussion #303), when that surface has it
     * switched on. Not for a keyboard-owned field, whose caret is on the
     * keyboard already.
     */
    fun onCaretDrag(source: CaretDragSource, down: Boolean) {
        if (!down) {
            caretMagnifier.end(source)
            return
        }
        val state = _uiState.value
        val enabled = when (source) {
            CaretDragSource.TRACKPAD -> state.settings.trackpad.magnifier
            CaretDragSource.SPACEBAR -> state.settings.textEditing.spaceCursorMagnifier
        }
        if (!enabled || state.captureTarget() != null) return
        val ic = currentInputConnection ?: return
        val mask = hidesTypedText(currentInputEditorInfo?.inputType ?: 0)
        caretMagnifier.begin(source, ic, expectedSelStart, expectedSelEnd, mask)
    }

    override fun onUpdateCursorAnchorInfo(cursorAnchorInfo: CursorAnchorInfo) {
        super.onUpdateCursorAnchorInfo(cursorAnchorInfo)
        caretMagnifier.onCursorAnchor(cursorAnchorInfo)
    }

    /** Arms the toolbar's selection mode, whatever the panel's own toggle says. */
    private fun armSelectionMode() {
        _uiState.update { it.copy(selectionMode = true) }
    }

    /**
     * Disarms selection mode from every source at once.
     *
     * Both surfaces that switch it off — the tool and the panel's Select key —
     * clear all three flags rather than their own, because the button the user
     * pressed reads as "selecting: off" and leaving another flag holding it on
     * would make the next arrow key extend a selection they just ended.
     */
    private fun clearSelectionArm() {
        _uiState.update {
            it.copy(textEditSelecting = false, selectionMode = false, selectionHold = false)
        }
    }

    // ---- selection macros ----

    /**
     * Whether WhatsApp is on the device, resolved once and kept.
     *
     * Null until the first selected phone number asks. The app's own
     * `<queries>` block already makes every launcher app visible (the app
     * launcher tool reads the same list), so this needs no new package query
     * permission.
     */
    private var whatsAppInstalled: Boolean? = null

    private fun hasWhatsApp(): Boolean = whatsAppInstalled ?: runCatching {
        WHATSAPP_PACKAGES.any { packageManager.getLaunchIntentForPackage(it) != null }
    }.getOrDefault(false).also { whatsAppInstalled = it }

    /**
     * Re-reads the selection and republishes the macro bar for it.
     *
     * Called from the two places a selection can change under the keyboard:
     * every [onUpdateSelection], and each fresh input view (where the field the
     * user came back to may already have one), and the settings collector when the
     * feature is switched on or off. Every gate that can be answered
     * without reading the field is asked first — the feature off, a password
     * field, no range selected, a range longer than the cap (see
     * [publishUnread]) — because `getSelectedText` is an IPC to the target
     * app and this runs on every caret move.
     */
    private fun refreshSelectionMacros(
        selStart: Int = expectedSelStart,
        selEnd: Int = expectedSelEnd,
        settings: KeyboardSettings = _uiState.value.settings,
    ) {
        fun clear() {
            caretRevealJob?.cancel()
            if (_uiState.value.selectionMacros != null) {
                _uiState.update { it.copy(selectionMacros = null) }
            }
            // With the selection gone, so is everything the undo stack
            // described, and there is nothing left to read aloud. The find
            // panel keeps its session: it moves the selection itself.
            if (_uiState.value.panel != PanelMode.FIND_REPLACE) macroUndo.clear()
            stopReadAloud()
            closeSelectionWordCard()
        }
        // Publishes [offer], or takes the bar down when it is null, and asks
        // the app to scroll the caret clear of a bar that has just arrived on
        // a row of its own: that row grows the keyboard by its height, which
        // takes the same height off the app, and nothing in the framework
        // scrolls the caret back out from under it (#525). The strip
        // placement borrows a row that was already there and costs nothing,
        // and so does an open panel, which keeps the row away (#414).
        fun publish(offer: SelectionMacroOffer?) {
            if (offer == null) return clear()
            // The card Edit word opened is about the text that was selected.
            if (offer.text != _uiState.value.selectionMacros?.text) closeSelectionWordCard()
            if (offer == _uiState.value.selectionMacros) return
            val arriving = _uiState.value.selectionMacros == null
            _uiState.update { it.copy(selectionMacros = offer) }
            // A bare caret's row (#763) is left to [noteBoardGrowth], which
            // puts a caret back in view after any growth of the board.
            if (arriving && selStart != selEnd &&
                settings.selectionMacros.placement == SelectionMacroPlacement.OWN_ROW &&
                _uiState.value.panel == PanelMode.NONE
            ) {
                revealCaretAfterGrowth(selStart, selEnd)
            }
        }
        if (!settings.selectionMacros.enabled) return clear()
        // A password is never a number to dial or text to share, and putting a
        // field's contents in front of a Share chooser is exactly the mistake
        // this bar must not make. No setting reaches past this one.
        if (currentInputEditorInfo.isSecureField()) return clear()
        // A collapsed caret has nothing to act on, and a selection past the cap
        // is a document rather than a fragment. Both are answered from the
        // reported positions, before the read that costs an IPC to the target
        // app; unknown positions (-1) fall through to it, which is the state
        // right after a field opens.
        val rangeReported = selStart >= 0 && selEnd >= 0
        if (rangeReported) {
            if (selStart == selEnd) return publishCaret(settings, ::clear) { publish(it) }
            if (selEnd - selStart > MAX_MACRO_SELECTION) return publishUnread(selStart, selEnd, settings) { publish(it) }
        }
        val ic = currentInputConnection ?: return clear()
        val selected = runCatching { ic.getSelectedText(0)?.toString() }.getOrNull().orEmpty()
        val text = selected.trim()
        // Nothing came back. Where the editor has reported a range, that is an
        // editor which will not hand the text over rather than an empty
        // selection, and the actions it carries out itself still work on it;
        // where it has reported nothing either, there is no selection to be
        // sure of.
        if (text.isEmpty()) {
            return if (rangeReported) {
                publishUnread(selStart, selEnd, settings) { publish(it) }
            } else {
                publishCaret(settings, ::clear) { publish(it) }
            }
        }
        // The same cap again, for the path that could not check it up front.
        if (selected.length > MAX_MACRO_SELECTION) return publishUnread(selStart, selEnd, settings) { publish(it) }
        // A selection moved onto other text is a new session: the rewrites
        // remembered were about the old one. Our own rewrite's echo passes,
        // because what is selected is exactly what was committed.
        if (_uiState.value.panel != PanelMode.FIND_REPLACE) {
            macroUndo.peek()?.let { if (!MacroUndo.stillHolds(it, selected)) macroUndo.clear() }
        }
        publish(selectionMacroOffer(text, settings, selectionSpansField(ic, selStart, selEnd), _uiState.value.selectionMacros))
    }

    /**
     * The bar for a selection the keyboard has not read: one past
     * [MAX_MACRO_SELECTION], or one an editor reports but will not hand over.
     *
     * Off by default the bar goes away, which is what the cap has always
     * meant: reading a selection that large is an IPC and an allocation to
     * match, and every action that needs the text is therefore unavailable.
     * With `inEverySelection` on, the actions that need neither the text nor a
     * scan of it stay ([SelectionMacros.textFreeMacros]) — the editor does
     * their work — so the bar's Copy and Paste survive the one case where the
     * app's own toolbar is least likely to be enough (#525).
     *
     * Nothing here reads the selection. The offer carries no text, which is
     * precisely why only the text-free actions may be on it; every handler for
     * those goes through the editor's own clipboard and selection (see
     * [onSelectionMacro]). The undo stack goes with it: a span this long is
     * not the fragment a remembered rewrite was about, and it cannot be
     * checked against one without the read.
     */
    private fun publishUnread(
        selStart: Int,
        selEnd: Int,
        settings: KeyboardSettings,
        publish: (SelectionMacroOffer?) -> Unit,
    ) {
        // Taking the bar down does both of these itself, so they belong on the
        // path that keeps it up.
        if (!settings.selectionMacros.inEverySelection) return publish(null)
        val ic = currentInputConnection ?: return publish(null)
        if (_uiState.value.panel != PanelMode.FIND_REPLACE) macroUndo.clear()
        stopReadAloud()
        val wholeField = selectionSpansField(ic, selStart, selEnd)
        val macros = SelectionMacros.offer(
            kind = SelectionKind.TEXT,
            allowed = settings.selectionMacros.macros.intersect(SelectionMacros.textFreeMacros),
            gates = MacroGates(wholeField = wholeField, clipboardHasText = clipboardHasText()),
            order = settings.selectionMacros.order,
        )
        publish(
            if (macros.isEmpty()) {
                null
            } else {
                SelectionMacroOffer(text = "", kind = SelectionKind.TEXT, macros = macros, wholeField = wholeField)
            },
        )
    }

    /**
     * The row for a bare caret, when it is set to stay up with nothing
     * selected (#763): Select all and Paste, out of
     * [SelectionMacros.caretMacros]. Otherwise [clear], which is what a
     * collapsed caret has always meant.
     *
     * Only on a row of its own. The strip placement would hand the
     * suggestion strip to the macros for as long as the caret sat anywhere,
     * which is all the time somebody types.
     *
     * Paste is drawn whatever the clipboard holds. The point of the switch is
     * a row that stays put, and one that lost a chip each time the clipboard
     * emptied would move under the thumb; a paste of nothing does nothing.
     * Nothing is read from the field, so this costs nothing per caret move.
     */
    private fun publishCaret(
        settings: KeyboardSettings,
        clear: () -> Unit,
        publish: (SelectionMacroOffer?) -> Unit,
    ) {
        val prefs = settings.selectionMacros
        if (!prefs.withoutSelection || prefs.placement != SelectionMacroPlacement.OWN_ROW) return clear()
        // The selection is gone, so is what the undo stack and the reader
        // were about; the same housekeeping [clear] does, minus the row.
        if (_uiState.value.panel != PanelMode.FIND_REPLACE) macroUndo.clear()
        stopReadAloud()
        val macros = SelectionMacros.offer(
            kind = SelectionKind.TEXT,
            allowed = prefs.macros.intersect(SelectionMacros.caretMacros),
            gates = MacroGates(clipboardHasText = true),
            order = prefs.order,
        )
        publish(
            if (macros.isEmpty()) {
                null
            } else {
                SelectionMacroOffer(text = "", kind = SelectionKind.TEXT, macros = macros)
            },
        )
    }

    /** Pending [scrollCaretIntoView], cancelled by anything that moves on. */
    private var caretRevealJob: Job? = null

    /**
     * The docked board's top on screen when [noteBoardGrowth] last saw it, or
     * -1 before the first measure of this showing.
     */
    private var boardTopForReveal = -1

    /**
     * The offsets a caret nudge ([revealCaret]) parks the selection at for a
     * moment, so [updateSelection] can let that echo pass without reading it as
     * the user moving the caret; -1 when no nudge is out.
     */
    private var revealDetourStart = -1
    private var revealDetourEnd = -1

    /**
     * The caret [noteBoardGrowth] last nudged into view, or -1. The same
     * caret is not nudged twice in a row: in an editor that answers the nudge
     * with a re-layout (a code editor, #679), the board can shrink and grow
     * again on the nudge's own echo, and every round moved the caret again.
     * Cleared when the caret goes anywhere else.
     */
    private var lastRevealedCaret = -1

    /**
     * Puts the caret back on screen when the keyboard grows under it (#662).
     *
     * A caret placed by a tap starts the strip for the word it landed on, the
     * strip unfolds, and the board gets taller by a row. Nothing tells the app
     * the caret was covered: an editor scrolls to a caret that *moves*, and
     * this one did not, so in notes.futo.tech and many others the line stayed
     * under the keys until the first letter typed. The first showing is not
     * this case; the app scrolls for that itself.
     *
     * Not while a word is being typed, which the editor follows on its own, nor
     * while a commit's one-shot undo is armed: the nudge moves the caret, which
     * would disarm it.
     */
    private fun noteBoardGrowth(top: Int) {
        val last = boardTopForReveal
        boardTopForReveal = top
        if (last < 0 || top >= last || !keyboardVisible) return
        val state = _uiState.value
        if (state.panel != PanelMode.NONE && state.panel != PanelMode.FIND_REPLACE) return
        if (composing.isNotEmpty() && composing.toString() != resumedWord) return
        if (lastRevertible != null || lastGestureWord != null || pendingAutoSpace || pendingWordSpace) return
        val start = expectedSelStart
        val end = expectedSelEnd
        if (start < 0 || end < 0) return
        // A selection is one the user just made on screen, by hand or with
        // Select all, and the bar that arrives for it reveals it its own way
        // ([revealCaretAfterGrowth]). Nudging it here as well sent arrow keys
        // into a web page with the selection still live, which a code editor
        // took as a move: Select all lit up and went straight out (#679).
        if (start != end) return
        if (start == lastRevealedCaret) return
        lastRevealedCaret = start
        scheduleCaretReveal(start, end)
    }

    /**
     * [revealCaret] once the board has finished growing and the app has laid
     * itself out again, if the selection is still [start]..[end] by then.
     */
    private fun scheduleCaretReveal(start: Int, end: Int) {
        caretRevealJob?.cancel()
        caretRevealJob = serviceScope.launch {
            delay(MACRO_ROW_REVEAL_DELAY_MS)
            if (expectedSelStart == start && expectedSelEnd == end) revealCaret()
        }
    }

    /**
     * Asks the editor to scroll its caret, or its selection, into view.
     *
     * A selection goes through [scrollCaretIntoView]. A caret cannot be set
     * reversed, so it takes one step aside and back: an editor scrolls to a
     * caret that moved. In a web page the step is an arrow key, the one move a
     * page scrolls for (a selection set from the keyboard is not), and a
     * selection there is stepped the same way with shift. The step's own echo
     * is let through unread ([revealDetourStart]).
     */
    private fun revealCaret() {
        val ic = currentInputConnection ?: return
        val start = expectedSelStart
        val end = expectedSelEnd
        if (start < 0 || end < 0) return
        val web = isWebEditField()
        if (start != end && !web) {
            scrollCaretIntoView()
            return
        }
        if (start != end) {
            // Its moving end goes in a step and back out.
            revealDetourStart = minOf(start, end)
            revealDetourEnd = maxOf(start, end) - 1
            runCatching {
                sendShiftedArrow(ic, KeyEvent.KEYCODE_DPAD_LEFT)
                sendShiftedArrow(ic, KeyEvent.KEYCODE_DPAD_RIGHT)
            }
            return
        }
        // The mirror can trail the editor: a Select all whose echo has not
        // landed still reads as a caret here, and the arrow below would
        // collapse it. Asked of the editor before anything is sent.
        if (web && !runCatching { ic.getSelectedText(0) }.getOrNull().isNullOrEmpty()) return
        val back = start > 0
        val step = if (back) {
            val before = ic.getTextBeforeCursor(2, 0) ?: return
            if (before.length == 2 && Character.isSurrogatePair(before[0], before[1])) 2 else 1
        } else {
            val after = ic.getTextAfterCursor(2, 0) ?: return
            if (after.isEmpty()) return
            if (after.length == 2 && Character.isSurrogatePair(after[0], after[1])) 2 else 1
        }
        val aside = if (back) start - step else start + step
        revealDetourStart = aside
        revealDetourEnd = aside
        runCatching {
            if (web) {
                sendDownUpKeyEvents(if (back) KeyEvent.KEYCODE_DPAD_LEFT else KeyEvent.KEYCODE_DPAD_RIGHT)
                sendDownUpKeyEvents(if (back) KeyEvent.KEYCODE_DPAD_RIGHT else KeyEvent.KEYCODE_DPAD_LEFT)
            } else {
                ic.setSelection(aside, aside)
                ic.setSelection(start, start)
            }
        }
    }

    /** One press of [code] with shift held, for [revealCaret]'s selection step. */
    private fun sendShiftedArrow(ic: InputConnection, code: Int) {
        val now = SystemClock.uptimeMillis()
        val meta = KeyEvent.META_SHIFT_ON or KeyEvent.META_SHIFT_LEFT_ON
        ic.sendKeyEvent(KeyEvent(now, now, KeyEvent.ACTION_DOWN, code, 0, meta))
        ic.sendKeyEvent(KeyEvent(now, now, KeyEvent.ACTION_UP, code, 0, meta))
    }

    /**
     * Waits for the row to have opened and the app to have re-laid out, then
     * puts the caret back on screen — but only if the selection it was asked
     * about is still the one standing, so a handle still being dragged is left
     * alone.
     */
    private fun revealCaretAfterGrowth(selStart: Int, selEnd: Int) {
        // A web page does not scroll for a selection set from the keyboard
        // (see [revealCaret]), so the round trip below bought nothing there,
        // and an editor that keeps its own model of the selection (a code
        // editor in a page, #679) could read the reversed half as a new one.
        if (isWebEditField()) return
        caretRevealJob?.cancel()
        caretRevealJob = serviceScope.launch {
            delay(MACRO_ROW_REVEAL_DELAY_MS)
            if (expectedSelStart == selStart && expectedSelEnd == selEnd) scrollCaretIntoView()
        }
    }

    /**
     * Asks the focused editor to scroll the caret back into view.
     *
     * There is no API for this, so it goes through the one thing every editor
     * reacts to: a selection that *changes* is scrolled to (TextView registers
     * a pre-draw pass that calls `bringPointIntoView`; Compose's field asks its
     * own scroller). Setting the identical range back is a no-op the editor
     * ignores, so the range goes in reversed first — the same highlight on
     * screen, which is what a backwards drag leaves — and then forwards again.
     * Deliberately not inside a batch edit: an editor that coalesces a batch
     * compares only the value it ends on, which is the value it started with.
     *
     * Only ever called with a range live (the macro bar is the caller), so
     * there is no collapsed case to handle: reversing a caret would be the
     * same no-op.
     *
     * It lands on the direction the selection had. Always ending forwards
     * turned a selection Shift had grown up or to the left around, so the next
     * Shift+arrow moved its other end and the highlight vanished (#613).
     */
    private fun scrollCaretIntoView() {
        val ic = currentInputConnection ?: return
        val start = expectedSelStart
        val end = expectedSelEnd
        if (start < 0 || end < 0 || start == end) return
        val (anchor, focus) = if (selectionAnchor == end) end to start else start to end
        runCatching {
            ic.setSelection(focus, anchor)
            ic.setSelection(anchor, focus)
        }
    }

    /**
     * Whether the live selection runs from the field's first character to its
     * last, which is when Select all has nothing left to take.
     *
     * The start comes from the reported offsets where they are known, so the
     * one-character read past the end — an IPC like the selection read itself —
     * is only paid by a selection that already begins at the top of the field.
     * Unknown offsets (-1, right after a field opens) ask the field for both.
     * An editor that cannot answer leaves the chip up: a Select all that does
     * nothing costs less than one that is missing.
     */
    private fun selectionSpansField(ic: InputConnection, selStart: Int, selEnd: Int): Boolean {
        val atStart = if (selStart >= 0 && selEnd >= 0) {
            minOf(selStart, selEnd) == 0
        } else {
            runCatching { ic.getTextBeforeCursor(1, 0) }.getOrNull()?.isEmpty() == true
        }
        return atStart && runCatching { ic.getTextAfterCursor(1, 0) }.getOrNull()?.isEmpty() == true
    }

    /**
     * The offer for [text], or null when nothing survives the user's switches.
     * [wholeField] is whether the selection already spans the field (see
     * [selectionSpansField]); [carry] is the offer being replaced, whose
     * running work and speech state outlive one rebuild.
     */
    private fun selectionMacroOffer(
        text: String,
        settings: KeyboardSettings,
        wholeField: Boolean,
        carry: SelectionMacroOffer?,
    ): SelectionMacroOffer? {
        val prefs = settings.selectionMacros
        val masks = settings.clipboard.phoneFormats.toList()
        val kind = if (prefs.detectEntities) {
            SelectionMacros.detect(text, masks)
        } else {
            SelectionKind.TEXT
        }
        // A macro that opens a tool is only offered while that tool exists:
        // the same enabled-tools list power saving and direct boot have
        // already taken their entries out of.
        val allowed = prefs.macros.filterTo(mutableSetOf()) { macroToolAvailable(it, settings) }
        // Plain text always has the case ladder behind Format; an entity offers
        // it only when the rewrite would actually change something. On a link
        // whose whole rewrite is dropping trackers, Remove trackers already
        // says that, and two chips doing one thing is one too many.
        val formatted = if (kind == SelectionKind.TEXT) null else SelectionMacros.format(text, kind, masks)
        val formattable = kind == SelectionKind.TEXT || (
            formatted != null &&
                !(SelectionMacro.STRIP_TRACKERS in allowed && formatted == SelectionMacros.stripTrackers(text))
            )
        // The dearer detectors run only while a macro that needs them is on.
        val content = SelectionMacros.detectContent(
            text,
            DetectOptions(
                dateTime = SelectionMacro.CALENDAR in allowed || SelectionMacro.TIME_ZONES in allowed,
                place = SelectionMacro.MAP in allowed,
                nowMillis = System.currentTimeMillis(),
                extraTrackers = settings.clipboard.extraTrackers,
            ),
        )
        val aiReady = ToolbarTool.AI in settings.enabledTools && aiInitialState(settings) == AiUi.Idle
        val gates = MacroGates(
            whatsAppInstalled = hasWhatsApp(),
            qrAvailable = ToolbarTool.QR_GEN in settings.enabledTools,
            formattable = formattable,
            wholeField = wholeField,
            clipboardHasText = clipboardHasText(),
            undoAvailable = !macroUndo.isEmpty,
            grammarAvailable = BuildConfig.ENABLE_GRAMMAR && ToolbarTool.GRAMMAR in settings.enabledTools &&
                (grammarAvailable || grammarProbePending()),
            aiAvailable = aiReady,
            // DeepL Write only when the user set it up, and only for what one
            // request carries: a longer selection would come back cut short.
            deeplWriteAvailable = settings.deeplLive.writeActive &&
                text.trim().length <= DeepLClient.MAX_CHARS,
            bengaliLoaded = suggestionEngine != null && bengaliListLoaded(),
            hindiLoaded = suggestionEngine?.extraPhonetic?.containsKey(PhoneticSchemes.HINDI.languageId) == true,
            chatSyntax = ChatSyntax.forPackage(currentPackage),
            oneWord = selectedWord(text) != null,
            content = content,
        )
        val macros = SelectionMacros.offer(kind, allowed, gates, prefs.order)
        if (macros.isEmpty()) return null
        // The direct buttons ride the AI chip: one switch hides both.
        val aiDirect = if (SelectionMacro.AI in macros) {
            val visible = visibleAiActions(settings.ai.customActions, settings.ai.actionOrder, settings.ai.hiddenActions)
            prefs.aiDirectActions.mapNotNull { id -> visible.firstOrNull { it.id == id && !it.askEachRun } }
        } else {
            emptyList()
        }
        return SelectionMacroOffer(
            text = text,
            kind = kind,
            macros = macros,
            wholeField = wholeField,
            content = content,
            aiDirect = aiDirect,
            caseLadder = SelectionMacros.caseLadder(allowed),
            undoDepth = macroUndo.size,
            busy = carry?.busy,
            speaking = carry?.speaking ?: false,
        )
    }

    /**
     * Whether the tool a macro opens is switched on; the rest are always
     * available. QR is not here: [SelectionMacros.offer] asks about it by name,
     * so it is answered at that call instead of twice.
     */
    private fun macroToolAvailable(macro: SelectionMacro, settings: KeyboardSettings): Boolean = when (macro) {
        SelectionMacro.SEARCH -> ToolbarTool.WEB_SEARCH in settings.enabledTools
        SelectionMacro.TRANSLATE -> ToolbarTool.TRANSLATE in settings.enabledTools
        SelectionMacro.GRAMMAR_FIX -> ToolbarTool.GRAMMAR in settings.enabledTools
        SelectionMacro.AI -> ToolbarTool.AI in settings.enabledTools
        SelectionMacro.SAVE_NOTE -> ToolbarTool.NOTES in settings.enabledTools
        SelectionMacro.REPEAT -> ToolbarTool.TEXT_REPEAT in settings.enabledTools
        else -> true
    }

    /**
     * Whether the clipboard holds text to paste over the selection. Asked of
     * the clip's description only: reading the clip itself is what makes
     * Android 12 announce a clipboard read, and this runs on every caret move.
     */
    private fun clipboardHasText(): Boolean {
        if (!isClipboardAccessible()) return false
        if (KeyboardClipboard.held != null) return true
        val manager = getSystemService(Context.CLIPBOARD_SERVICE) as? ClipboardManager ?: return false
        return runCatching {
            manager.hasPrimaryClip() && manager.primaryClipDescription?.let {
                it.hasMimeType(ClipDescription.MIMETYPE_TEXT_PLAIN) || it.hasMimeType(ClipDescription.MIMETYPE_TEXT_HTML)
            } == true
        }.getOrDefault(false)
    }

    // ---- selection macros: the undo session and the async work ----

    /** The rewrites made to the live selection, newest last. */
    private val macroUndo = MacroUndoStack()

    /** Bumped whenever the selection the async macros were started for is gone. */
    private var macroSeq = 0
    private var macroJob: Job? = null

    /**
     * The romanized converters by language, each beside what it was built
     * over, so one is rebuilt when the engine or its sources change — the
     * inverted spelling map inside is the expensive part.
     */
    private val romanizedConverters = HashMap<String, Pair<PhoneticBackendKey, RomanizedConverter>>()

    /** Identity of what a converter was built from: the spelling map and the index. */
    private class PhoneticBackendKey(val spellings: Any, val index: Any) {
        fun sameAs(other: PhoneticBackendKey) = spellings === other.spellings && index === other.index
    }

    /**
     * A macro chip was tapped.
     *
     * The text acted on is the offer's own, not a fresh read: the chips were
     * drawn for that text, and re-reading here would act on whatever the field
     * holds by the time the finger lands. A macro whose target app is missing
     * says so in a toast and leaves the bar up.
     */
    fun onSelectionMacro(macro: SelectionMacro) {
        val offer = _uiState.value.selectionMacros ?: return
        vibrate()
        val settings = _uiState.value.settings
        val masks = settings.clipboard.phoneFormats.toList()
        val text = offer.text
        when (macro) {
            SelectionMacro.UNDO -> onSelectionUndo()
            // The field answers with a selection update, and the offer that
            // brings is for the whole text, without this chip on it.
            SelectionMacro.SELECT_ALL -> onTextEdit(TextEditAction.SELECT_ALL, haptic = false)
            SelectionMacro.COPY -> onTextEdit(TextEditAction.COPY, haptic = false)
            SelectionMacro.CUT -> onTextEdit(TextEditAction.CUT, haptic = false)
            // The editor's own paste replaces a selection; the clipboard gates
            // and the password purge ride along.
            SelectionMacro.PASTE -> onTextEdit(TextEditAction.PASTE, haptic = false)
            SelectionMacro.DELETE -> deleteSelection()
            SelectionMacro.SHARE -> shareVia(Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT, text))
            SelectionMacro.SAVE_NOTE -> saveSelectionAsNote(text)
            SelectionMacro.REPEAT -> openTextRepeatTool(seed = text)
            SelectionMacro.FORMAT -> SelectionMacros.format(text, offer.kind, masks)?.let(::rewriteSelection)
            SelectionMacro.CASE_LOWER, SelectionMacro.CASE_TITLE, SelectionMacro.CASE_UPPER, SelectionMacro.CASE_SENTENCE,
            SelectionMacro.CASE_CAMEL, SelectionMacro.CASE_SNAKE, SelectionMacro.CASE_KEBAB, SelectionMacro.CASE_CONSTANT ->
                SelectionMacros.applyCase(text, macro)?.let(::rewriteSelection)
            SelectionMacro.FIND -> findNextOccurrence(offer)
            SelectionMacro.REPLACE -> openFindReplace(offer.text)
            SelectionMacro.LINES_SORT -> LineEdits.sort(text)?.let(::rewriteSelection)
            SelectionMacro.LINES_DEDUPE -> LineEdits.dedupe(text)?.let(::rewriteSelection)
            SelectionMacro.LINES_NUMBER -> LineEdits.number(text)?.let(::rewriteSelection)
            SelectionMacro.LINES_BULLET -> LineEdits.bullet(text)?.let(::rewriteSelection)
            SelectionMacro.LINES_CHECKBOX -> LineEdits.checkbox(text)?.let(::rewriteSelection)
            SelectionMacro.LINES_UP -> moveSelectedLines(up = true)
            SelectionMacro.LINES_DOWN -> moveSelectedLines(up = false)
            SelectionMacro.DIGITS_LATIN -> DigitScripts.toAsciiDigits(text)?.let(::rewriteSelection)
            SelectionMacro.ZAWGYI -> convertZawgyiSelection(offer, text)
            SelectionMacro.JSON_FORMAT -> JsonReformat.toggle(text)?.let(::rewriteSelection)
            SelectionMacro.BASE64_DECODE -> TextCodecs.base64Decode(text)?.let(::rewriteSelection)
            SelectionMacro.URL_DECODE -> TextCodecs.urlDecode(text)?.let(::rewriteSelection)
            SelectionMacro.STRIP_TRACKERS ->
                SelectionMacros.stripTrackersInText(text, _uiState.value.settings.clipboard.extraTrackers)
                    ?.let(::rewriteSelection)
            SelectionMacro.CHAT_BOLD -> chatToggle(text, ChatStyle.BOLD)
            SelectionMacro.CHAT_ITALIC -> chatToggle(text, ChatStyle.ITALIC)
            SelectionMacro.CHAT_STRIKE -> chatToggle(text, ChatStyle.STRIKE)
            SelectionMacro.CHAT_MONO -> chatToggle(text, ChatStyle.MONO)
            SelectionMacro.GRAMMAR_FIX -> fixGrammarInSelection(offer)
            SelectionMacro.DEEPL_WRITE -> rephraseSelection(offer)
            SelectionMacro.AI -> onPanelChange(PanelMode.AI)
            SelectionMacro.EDIT_WORD -> selectedWord(text)?.let { publishWordCard(it, fromSelection = true) }
            SelectionMacro.READ_ALOUD -> toggleReadAloud(offer)
            SelectionMacro.TO_BANGLA, SelectionMacro.TO_BANGLISH,
            SelectionMacro.TO_HINDI, SelectionMacro.TO_HINGLISH,
            -> convertRomanized(offer, macro)
            SelectionMacro.SEARCH -> openMacroSearch(PanelMode.WEB_SEARCH, text)
            SelectionMacro.TRANSLATE -> openMacroSearch(PanelMode.TRANSLATE, text)
            SelectionMacro.QR -> onPanelChange(PanelMode.QR_GEN)
            SelectionMacro.CALL -> startMacroActivity(
                Intent(Intent.ACTION_DIAL, Uri.parse("tel:" + SelectionMacros.dialDigits(text, masks))),
            )
            SelectionMacro.SMS -> startMacroActivity(
                Intent(Intent.ACTION_SENDTO, Uri.parse("smsto:" + SelectionMacros.dialDigits(text, masks))),
            )
            SelectionMacro.WHATSAPP -> startMacroActivity(
                Intent(Intent.ACTION_VIEW, Uri.parse("https://wa.me/" + SelectionMacros.dialDigits(text, masks))),
            )
            SelectionMacro.EMAIL -> startMacroActivity(Intent(Intent.ACTION_SENDTO, Uri.parse("mailto:$text")))
            // The bar resolves the same list to draw the target app's icon.
            SelectionMacro.OPEN -> startMacroActivity(*macroOpenIntents(offer.kind, text).toTypedArray())
            SelectionMacro.ADD_CONTACT -> addContact(offer)
            SelectionMacro.MAP -> openMap(offer)
            SelectionMacro.CALENDAR -> addCalendarEvent(offer)
            // Doors to ladders: the bar opens them and never sends the tap.
            SelectionMacro.FANCY, SelectionMacro.COLOUR, SelectionMacro.TIME_ZONES -> {}
        }
    }

    /**
     * A pick on one of the bar's ladders (see `SelectionMacroBar`).
     *
     * [source] is the selection as it stood when the ladder opened, not what
     * is selected now: the previous pick's rewrite republished the offer with
     * its own output, and converting that again would do nothing (the fancy
     * tables are keyed by plain letters) or drift. Every pick therefore
     * replaces the last one rather than stacking on it, and each converter
     * reads [source] afresh rather than the live offer.
     */
    fun onSelectionPick(macro: SelectionMacro, arg: String, source: String) {
        if (_uiState.value.selectionMacros == null) return
        val out = when (macro) {
            SelectionMacro.FANCY -> FancyStyles.byId(arg)?.let { FancyStyles.transform(source, it) }
            SelectionMacro.COLOUR -> ColourCodes.parse(source)?.let { colour ->
                ColourForm.entries.firstOrNull { it.name == arg }?.let { ColourCodes.render(colour, it) }
            }
            SelectionMacro.TIME_ZONES -> DateTimes.parse(source, System.currentTimeMillis(), TimeZone.getDefault(), Locale.getDefault())
                ?.let { hit ->
                    DateTimes.renderInZone(
                        hit.startMillis, arg, hit.zoneId, hit.hasDate,
                        android.text.format.DateFormat.is24HourFormat(this), System.currentTimeMillis(),
                    )
                }
            else -> null
        } ?: return
        vibrate()
        // The pick is the text it should be; Fancy Text's field styling would
        // restyle it in the keyboard's own style (#950).
        val fancy = currentInputConnection as? FancyOutputConnection
        fancy?.passThrough = true
        try {
            rewriteSelection(out)
        } finally {
            fancy?.passThrough = false
        }
    }

    /** Put back the last rewrite, when the field still holds it. */
    private fun onSelectionUndo() {
        val entry = macroUndo.peek() ?: return
        val ic = currentInputConnection ?: return
        when (entry) {
            is MacroUndoEntry.Selection -> {
                var now = runCatching { ic.getSelectedText(0)?.toString() }.getOrNull()
                // The find panel walks on to the next match after each
                // replace, so the rewrite to undo is usually behind the
                // selection: go back to where it was made and look there.
                if (now != entry.replacement && entry.start >= 0) {
                    ic.finishComposingText()
                    ic.setSelection(entry.start, entry.start + entry.replacement.length)
                    expectedSelStart = entry.start
                    expectedSelEnd = entry.start + entry.replacement.length
                    now = runCatching { ic.getSelectedText(0)?.toString() }.getOrNull()
                }
                if (now != entry.replacement) {
                    macroUndo.clear()
                    republishSelectionMacros(now)
                    toast(R.string.ime_selection_macro_nothing_to_undo_toast)
                    return
                }
                macroUndo.pop()
                rewriteSelection(entry.original, record = false, raw = true)
            }
            is MacroUndoEntry.WholeField -> {
                val field = extractFieldText()
                if (field != entry.after) {
                    macroUndo.clear()
                    republishSelectionMacros(runCatching { ic.getSelectedText(0)?.toString() }.getOrNull())
                    toast(R.string.ime_selection_macro_nothing_to_undo_toast)
                    return
                }
                macroUndo.pop()
                val inverse = MacroUndo.invert(entry.before, entry.edits).map { GrammarEdit(it.start, it.end, it.text) }
                if (!replaceFieldSpans(inverse)) {
                    if (!fieldTextComplete) return
                    replaceFieldText(entry.before)
                }
                val origin = fieldTextOrigin ?: 0
                ic.setSelection(origin + entry.selStart, origin + entry.selEnd)
                expectedSelStart = origin + entry.selStart
                expectedSelEnd = origin + entry.selEnd
                republishSelectionMacros(entry.before.substring(entry.selStart, entry.selEnd))
            }
        }
    }

    /**
     * Swaps the selection for [core] and selects the result.
     *
     * Keeping it selected is what lets the case chips chain: lower, then Title,
     * then back, without reselecting between taps. It also keeps the bar itself
     * on screen, which would otherwise vanish under the user's finger the
     * moment the first chip did its job.
     *
     * The chips act on the trimmed text, so the raw selection's own leading
     * and trailing whitespace is put back around the result rather than
     * eaten; [raw] commits [core] exactly as given, which is what undo needs.
     * The rewrite is remembered for Undo unless [record] says otherwise, and
     * the offer is republished for the new text at once rather than waiting
     * for the editor's echo, which some editors never send.
     */
    /**
     * Selection actions' Move up and Move down (#679): the lines the selection
     * covers trade places with the line above or below, and the selection
     * moves with them, so a second tap moves them on. Read from the editor's
     * extracted text, so a field that gives none, or gives only part of a
     * long text, is left alone rather than spliced from a guess.
     */
    private fun moveSelectedLines(up: Boolean) {
        val ic = currentInputConnection ?: return
        val extracted = ic.getExtractedText(ExtractedTextRequest(), 0) ?: return
        val text = extracted.text?.toString() ?: return
        if (extracted.partialStartOffset >= 0 || extracted.selectionStart < 0) return
        val origin = extracted.startOffset
        val start = minOf(extracted.selectionStart, extracted.selectionEnd)
        val end = maxOf(extracted.selectionStart, extracted.selectionEnd)
        val move = LineEdits.moved(text, start, end, up) ?: return
        ic.beginBatchEdit()
        ic.finishComposingText()
        revision = null
        composing = StringBuilder()
        ic.setSelection(origin + move.from, origin + move.to)
        ic.commitText(move.text, 1)
        ic.setSelection(origin + move.selStart, origin + move.selEnd)
        ic.endBatchEdit()
        expectedSelStart = origin + move.selStart
        expectedSelEnd = origin + move.selEnd
    }

    private fun rewriteSelection(core: String, record: Boolean = true, raw: Boolean = false) {
        val ic = currentInputConnection ?: return
        // A selection dragged right to left is reported with its ends the other
        // way round by some editors, and the commit always lands at the lower
        // offset whichever way it was made.
        val start = if (expectedSelStart < 0 || expectedSelEnd < 0) {
            -1
        } else {
            minOf(expectedSelStart, expectedSelEnd)
        }
        val original = runCatching { ic.getSelectedText(0)?.toString() }.getOrNull()
            ?: _uiState.value.selectionMacros?.text
            ?: return
        val replacement = if (raw) {
            core
        } else {
            val lead = original.takeWhile { it.isWhitespace() }
            val trail = if (lead.length == original.length) "" else original.takeLastWhile { it.isWhitespace() }
            lead + core + trail
        }
        ic.beginBatchEdit()
        // A live composing region would take the commit instead of the
        // selection, splicing the replacement over one word.
        ic.finishComposingText()
        revision = null
        composing = StringBuilder()
        ic.commitText(replacement, 1)
        if (start >= 0) {
            ic.setSelection(start, start + replacement.length)
            // Mirror it, or a backspace before the editor echoes the new
            // selection targets the old range.
            expectedSelStart = start
            expectedSelEnd = start + replacement.length
        }
        ic.endBatchEdit()
        if (record && replacement != original) macroUndo.push(MacroUndoEntry.Selection(original, replacement, start))
        republishSelectionMacros(replacement)
    }

    /** The offer for [selected] as it now stands, without another read of the field. */
    private fun republishSelectionMacros(selected: String?) {
        val text = selected?.trim().orEmpty()
        val previous = _uiState.value.selectionMacros
        val offer = if (text.isEmpty()) {
            null
        } else {
            selectionMacroOffer(text, _uiState.value.settings, previous?.wholeField == true, previous)
        }
        _uiState.update { it.copy(selectionMacros = offer) }
    }

    // ---- find and replace ----

    /** The field as last extracted for the panel, and where its offset 0 sits in the editor. */
    private var findText: String = ""
    private var findOrigin: Int? = null
    private var findJob: Job? = null
    private var findSeq = 0

    /** Opens the panel with [query] as the query and its first match selected. */
    private fun openFindReplace(query: String, haptic: Boolean = false) {
        onPanelChange(PanelMode.FIND_REPLACE, haptic = haptic)
        if (_uiState.value.panel != PanelMode.FIND_REPLACE) return
        _uiState.update {
            it.copy(findReplace = FindReplaceUi(query = query, undoDepth = macroUndo.size, history = findHistoryEntries()))
        }
        refreshFindMatches(reselect = query.isNotEmpty())
    }

    /**
     * The toolbar tool (#627): the same panel with no selection needed. A
     * short one-line selection becomes the query, the way an editor's Ctrl+F
     * takes it; anything else opens it empty. A second tap closes it.
     */
    private fun openFindReplaceTool() {
        if (_uiState.value.panel == PanelMode.FIND_REPLACE) {
            onPanelChange(PanelMode.FIND_REPLACE)
            return
        }
        if (currentInputEditorInfo.takeIf { currentInputStarted }.isSecureField()) {
            toast(R.string.ime_find_secure_field)
            return
        }
        val selected = if (expectedSelStart >= 0 && expectedSelEnd >= 0 && expectedSelStart != expectedSelEnd) {
            runCatching { currentInputConnection?.getSelectedText(0)?.toString() }.getOrNull()
        } else {
            null
        }
        openFindReplace(selected?.takeIf { it.isNotBlank() && '\n' !in it && it.length <= FIND_MAX_QUERY }.orEmpty(), haptic = true)
    }

    /** What the panel offers as recent searches; nothing while nothing may be remembered. */
    private fun findHistoryEntries(): List<String> = if (findHistoryPaused()) emptyList() else findHistory.entries()

    /** Incognito, a field that asks not to be learnt from, or a password field: no history. */
    private fun findHistoryPaused(): Boolean {
        val field = currentInputEditorInfo?.takeIf { currentInputStarted }
        val settings = _uiState.value.settings
        return settings.incognito || fieldWantsIncognito(settings, field) ||
            field.isSecureField()
    }

    /** Remembers the query once it has been used for something, not on every keystroke. */
    private fun recordFindQuery() {
        val query = _uiState.value.findReplace?.query ?: return
        if (findHistoryPaused()) return
        val history = findHistory.record(query)
        _uiState.update { it.copy(findReplace = it.findReplace?.copy(history = history)) }
    }

    /** A recent search tapped: it becomes the query, matched at once. */
    fun onFindHistoryPick(query: String) {
        vibrate()
        _uiState.update {
            it.copy(findReplace = it.findReplace?.copy(query = query, focused = FindReplaceField.FIND))
        }
        refreshFindMatches(reselect = true)
    }

    fun onFindHistoryClear() {
        vibrate()
        findHistory.clear()
        _uiState.update { it.copy(findReplace = it.findReplace?.copy(history = emptyList())) }
    }

    /** The current match in its line, for the panel; null with none current. */
    private fun findPreview(index: Int, matches: List<IntRange>): MatchPreview? =
        matches.getOrNull(index)?.let { FindReplaceGlue.preview(findText, it) }

    /** Backspace and character edits to whichever field is focused. */
    private fun findReplaceEdit(transform: (String) -> String) {
        val fr = _uiState.value.findReplace ?: return
        val next = if (fr.focused == FindReplaceField.FIND) {
            fr.copy(query = transform(fr.query).take(FIND_MAX_QUERY))
        } else {
            fr.copy(replacement = transform(fr.replacement).take(FIND_MAX_QUERY))
        }
        _uiState.update { it.copy(findReplace = next) }
        // A pattern is matched after a pause, since every keystroke of one
        // is a compile; plain text is cheap enough to follow the keys.
        if (fr.focused == FindReplaceField.FIND) refreshFindMatches(reselect = true, immediate = !next.regex)
    }

    /** The × in a field: empties it and puts the keys there. */
    fun onFindReplaceClear(field: FindReplaceField) {
        vibrate()
        val fr = _uiState.value.findReplace ?: return
        _uiState.update {
            it.copy(
                findReplace = if (field == FindReplaceField.FIND) {
                    fr.copy(query = "", focused = field)
                } else {
                    fr.copy(replacement = "", focused = field)
                },
            )
        }
        if (field == FindReplaceField.FIND) refreshFindMatches(reselect = false)
    }

    fun onFindReplaceFocus(field: FindReplaceField) {
        _uiState.update { it.copy(findReplace = it.findReplace?.copy(focused = field)) }
    }

    fun onFindReplaceToggle(option: FindOption) {
        vibrate()
        _uiState.update { state ->
            val fr = state.findReplace ?: return@update state
            state.copy(
                findReplace = when (option) {
                    FindOption.CASE -> fr.copy(caseSensitive = !fr.caseSensitive)
                    FindOption.WHOLE_WORD -> fr.copy(wholeWord = !fr.wholeWord)
                    FindOption.REGEX -> fr.copy(regex = !fr.regex)
                    FindOption.PRESERVE_CASE -> fr.copy(preserveCase = !fr.preserveCase)
                },
            )
        }
        refreshFindMatches(reselect = true)
    }

    private fun onFindReplaceEnter() {
        val fr = _uiState.value.findReplace ?: return
        if (fr.focused == FindReplaceField.FIND) onFindNext() else onFindReplaceOne()
    }

    fun onFindNext() = stepMatch(+1)

    fun onFindPrevious() = stepMatch(-1)

    /**
     * Next or previous match. The field is read again first: an editor that
     * draws only the part of a long text on screen (a code editor, a notes
     * app's) re-draws when a match is selected, and the offsets taken when
     * the panel opened then point at other text. Every step after the first
     * landed further off the word (#679).
     */
    private fun stepMatch(delta: Int) {
        val fr = _uiState.value.findReplace ?: return
        if (findOrigin == null || fr.matches.isEmpty()) return
        vibrate()
        recordFindQuery()
        findJob?.cancel()
        val seq = ++findSeq
        findJob = serviceScope.launch {
            val text = extractFieldText()
            val origin = fieldTextOrigin ?: return@launch refreshFindMatches(reselect = false)
            var matches = fr.matches
            var current = fr.current
            if (text != findText || origin != findOrigin) {
                findText = text
                findOrigin = origin
                val result = withContext(Dispatchers.Default) {
                    FindReplace.find(text, fr.query, fr.options(), FIND_BUDGET_MS)
                }
                if (seq != findSeq || _uiState.value.panel != PanelMode.FIND_REPLACE) return@launch
                matches = (result as? FindResult.Matches)?.ranges.orEmpty()
                current = if (expectedSelStart < 0 || expectedSelEnd < 0) {
                    -1
                } else {
                    FindReplaceGlue.currentMatchIndex(
                        matches, minOf(expectedSelStart, expectedSelEnd) - origin, maxOf(expectedSelStart, expectedSelEnd) - origin,
                    )
                }
                _uiState.update {
                    it.copy(
                        findReplace = it.findReplace?.copy(
                            matches = matches, current = current,
                            truncated = (result as? FindResult.Matches)?.truncated == true,
                            preview = findPreview(current, matches),
                        ),
                    )
                }
                if (matches.isEmpty()) return@launch
            }
            val selStart = if (expectedSelStart < 0 || expectedSelEnd < 0) 0 else minOf(expectedSelStart, expectedSelEnd) - origin
            selectMatch(FindReplaceGlue.stepIndex(matches, current, selStart, delta))
        }
    }

    /**
     * Re-extracts the field and matches the query over it, off the main
     * thread and under the matcher's time budget. [reselect] selects the
     * first match when none is the selection already; a refresh after the
     * user's own caret move must not.
     */
    private fun refreshFindMatches(reselect: Boolean, immediate: Boolean = true) {
        findJob?.cancel()
        val seq = ++findSeq
        findJob = serviceScope.launch {
            if (!immediate) delay(FIND_DEBOUNCE_MS)
            if (_uiState.value.panel != PanelMode.FIND_REPLACE) return@launch
            val fr = _uiState.value.findReplace ?: return@launch
            val text = extractFieldText()
            findText = text
            findOrigin = fieldTextOrigin
            val origin = findOrigin
            if (fr.query.isEmpty()) {
                _uiState.update {
                    it.copy(
                        findReplace = it.findReplace?.copy(
                            matches = emptyList(), current = -1, truncated = false, error = null,
                            addressable = origin != null, searching = false, undoDepth = macroUndo.size,
                            preview = null,
                        ),
                    )
                }
                return@launch
            }
            _uiState.update { it.copy(findReplace = it.findReplace?.copy(searching = true)) }
            val result = withContext(Dispatchers.Default) {
                FindReplace.find(text, fr.query, fr.options(), FIND_BUDGET_MS)
            }
            if (seq != findSeq || _uiState.value.panel != PanelMode.FIND_REPLACE) return@launch
            val matches = (result as? FindResult.Matches)?.ranges.orEmpty()
            val error = when (result) {
                is FindResult.BadPattern -> getString(R.string.ime_find_regex_error, result.reason.lineSequence().first())
                FindResult.TimedOut -> getString(R.string.ime_find_timeout)
                is FindResult.Matches -> if (origin == null) getString(R.string.ime_find_not_addressable) else null
            }
            val current = if (origin == null || expectedSelStart < 0 || expectedSelEnd < 0) {
                -1
            } else {
                FindReplaceGlue.currentMatchIndex(
                    matches, minOf(expectedSelStart, expectedSelEnd) - origin, maxOf(expectedSelStart, expectedSelEnd) - origin,
                )
            }
            _uiState.update {
                it.copy(
                    findReplace = it.findReplace?.copy(
                        matches = matches, current = current, truncated = (result as? FindResult.Matches)?.truncated == true,
                        error = error, addressable = origin != null, searching = false, undoDepth = macroUndo.size,
                        preview = findPreview(current, matches),
                    ),
                )
            }
            if (reselect && current < 0 && matches.isNotEmpty() && origin != null) selectMatch(0)
        }
    }

    /** Selects match [index] in the field and remembers it as the current one. */
    private fun selectMatch(index: Int) {
        val fr = _uiState.value.findReplace ?: return
        val origin = findOrigin ?: return
        val range = fr.matches.getOrNull(index) ?: return
        val ic = currentInputConnection ?: return
        ic.finishComposingText()
        selectFieldMatch(ic, origin + range.first, origin + range.last + 1, findText.substring(range.first, range.last + 1))
        _uiState.update { it.copy(findReplace = it.findReplace?.copy(current = index, preview = findPreview(index, fr.matches))) }
    }

    /**
     * Selects [start]..[end] in the editor, where [wanted] is expected to be,
     * brings it into view, and then checks that it is [wanted] that ended up
     * selected.
     *
     * Not every editor counts offsets the way it extracts its text. A web
     * editor that keeps its document in a model of its own (CodeMirror,
     * ProseMirror) can hand over text whose line breaks or hidden parts do
     * not line up with the offsets its selection takes, and the highlight
     * came out a few characters to the side of the word, or on another line
     * altogether (#679). So the selection is read back after the editor has
     * had a moment, and when it holds something else, [wanted] is looked for
     * in the text around where it landed, measured from the editor's own
     * caret, and selected there instead. Once: a second miss is left as it is.
     */
    private fun selectFieldMatch(ic: InputConnection, start: Int, end: Int, wanted: String) {
        ic.setSelection(start, end)
        expectedSelStart = start
        expectedSelEnd = end
        // Many editors leave a selection set from outside where it is, off
        // screen or under the keyboard, so the match is brought into view the
        // way a caret the board grew over is (#662).
        scheduleCaretReveal(start, end)
        if (wanted.isEmpty()) return
        findVerifyJob?.cancel()
        findVerifyJob = serviceScope.launch {
            delay(FIND_VERIFY_DELAY_MS)
            val live = currentInputConnection ?: return@launch
            // The user, or the reveal's own step, has moved on from it.
            if (minOf(expectedSelStart, expectedSelEnd) != start || maxOf(expectedSelStart, expectedSelEnd) != end) return@launch
            val selected = runCatching { live.getSelectedText(0)?.toString() }.getOrNull() ?: return@launch
            if (selected == wanted) return@launch
            val before = runCatching { live.getTextBeforeCursor(FIND_VERIFY_WINDOW, 0)?.toString() }.getOrNull() ?: return@launch
            val after = runCatching { live.getTextAfterCursor(FIND_VERIFY_WINDOW, 0)?.toString() }.getOrNull() ?: return@launch
            val window = before + selected + after
            val at = nearestOccurrence(window, wanted, before.length)
            if (at < 0) return@launch
            val fixed = start - before.length + at
            if (fixed < 0 || fixed == start) return@launch
            live.setSelection(fixed, fixed + wanted.length)
            expectedSelStart = fixed
            expectedSelEnd = fixed + wanted.length
            scheduleCaretReveal(expectedSelStart, expectedSelEnd)
        }
    }

    /** The match check [selectFieldMatch] has out, cancelled by the next selection. */
    private var findVerifyJob: Job? = null

    /** Where [needle] occurs in [text] closest to [near], or -1. */
    private fun nearestOccurrence(text: String, needle: String, near: Int): Int {
        var best = -1
        var i = text.indexOf(needle)
        while (i >= 0) {
            if (best < 0 || kotlin.math.abs(i - near) < kotlin.math.abs(best - near)) best = i
            i = text.indexOf(needle, i + 1)
        }
        return best
    }

    /**
     * Replaces the current match and walks on to the next. The field is
     * checked first: the match must still be where the last extraction put
     * it, or the panel re-reads instead of splicing blind.
     */
    fun onFindReplaceOne() {
        val fr = _uiState.value.findReplace ?: return
        val origin = findOrigin ?: return toast(R.string.ime_find_not_addressable)
        val index = fr.current
        val range = fr.matches.getOrNull(index) ?: return
        val ic = currentInputConnection ?: return
        val selected = runCatching { ic.getSelectedText(0)?.toString() }.getOrNull()
        if (selected != findText.substring(range.first, range.last + 1)) {
            refreshFindMatches(reselect = true)
            return
        }
        vibrate()
        recordFindQuery()
        val edit = FindReplace.replaceOne(findText, range, fr.replacement, fr.query, fr.options())
        rewriteSelection(edit.text, raw = true)
        findText = findText.replaceRange(edit.start, edit.end, edit.text)
        val remaining = FindReplaceGlue.shiftMatches(fr.matches, index, edit.text.length - (edit.end - edit.start))
        _uiState.update {
            it.copy(findReplace = it.findReplace?.copy(matches = remaining, current = -1, undoDepth = macroUndo.size, preview = null))
        }
        // The match that followed now sits where the replaced one was.
        if (remaining.isNotEmpty()) selectMatch(index.coerceAtMost(remaining.lastIndex))
        // The origin is unchanged by a splice; a re-extract only confirms it.
        if (origin < 0) refreshFindMatches(reselect = false)
    }

    /**
     * Replaces every match in one batch, back to front, as one undo entry.
     * The replacement at the current match stays selected so the bar and its
     * Undo are there when the panel closes.
     */
    fun onFindReplaceAll() {
        val fr = _uiState.value.findReplace ?: return
        if (fr.matches.isEmpty() || fr.truncated) return
        val ic = currentInputConnection ?: return
        val origin = findOrigin
        val before = findText
        val edits = FindReplace.replaceAll(before, fr.matches, fr.replacement, fr.query, fr.options())
        val after = FindReplace.apply(before, edits)
        val anchor = fr.matches.getOrNull(fr.current) ?: fr.matches.first()
        vibrate()
        recordFindQuery()
        if (origin != null) {
            if (!replaceFieldSpans(edits.map { GrammarEdit(it.start, it.end, it.text) })) return
        } else if (fieldTextComplete) {
            replaceFieldText(after)
        } else {
            toast(R.string.ime_find_not_addressable)
            return
        }
        macroUndo.push(MacroUndoEntry.WholeField(before, after, edits, anchor.first, anchor.last + 1))
        findText = after
        val newStart = FindReplaceGlue.afterOffset(edits, anchor.first)
        val newEnd = newStart + edits.first { it.start == anchor.first }.text.length
        if (origin != null && newEnd > newStart) {
            ic.setSelection(origin + newStart, origin + newEnd)
            expectedSelStart = origin + newStart
            expectedSelEnd = origin + newEnd
            republishSelectionMacros(after.substring(newStart, newEnd))
        } else {
            republishSelectionMacros(null)
        }
        _uiState.update {
            it.copy(findReplace = it.findReplace?.copy(matches = emptyList(), current = -1, undoDepth = macroUndo.size, preview = null))
        }
        // A replacement that contains the query matches again; count it.
        refreshFindMatches(reselect = false)
    }

    /** The panel's Undo: the bar's, then the matches read again. */
    fun onFindReplaceUndo() {
        if (macroUndo.isEmpty) return
        vibrate()
        onSelectionUndo()
        refreshFindMatches(reselect = false)
    }

    /** Removes the selected text, the way a backspace over a selection does. */
    private fun deleteSelection() {
        val ic = currentInputConnection ?: return
        dropComposingForSelectionEdit(ic)
        noteDeletedForLearning(expectedSelStart, expectedSelEnd)
        invalidateExpectedSelection()
        ic.commitText("", 1)
    }

    private fun chatToggle(text: String, style: ChatStyle) {
        val markup = ChatSyntax.forPackage(currentPackage) ?: return
        ChatSyntax.toggle(text, markup, style)?.let(::rewriteSelection)
    }

    /**
     * Selects the next occurrence of the selection in the field, wrapping to
     * the top. The echo republishes an offer for the same text, so the bar
     * stays as it is and a second tap walks on.
     */
    private fun findNextOccurrence(offer: SelectionMacroOffer) {
        val ic = currentInputConnection ?: return
        val field = extractFieldText()
        val origin = fieldTextOrigin ?: return toast(R.string.ime_find_not_addressable)
        if (expectedSelStart < 0 || expectedSelEnd < 0) return toast(R.string.ime_selection_macro_find_none_toast)
        val selStart = minOf(expectedSelStart, expectedSelEnd)
        val selEnd = maxOf(expectedSelStart, expectedSelEnd)
        val range = FindReplace.next(field, offer.text, FindOptions(), from = selEnd - origin)
            ?: return toast(R.string.ime_selection_macro_find_none_toast)
        if (origin + range.first == selStart) return toast(R.string.ime_selection_macro_find_none_toast)
        ic.finishComposingText()
        selectFieldMatch(ic, origin + range.first, origin + range.last + 1, field.substring(range.first, range.last + 1))
    }

    /** Runs the grammar checker over the selection alone and commits every first suggestion. */
    private fun fixGrammarInSelection(offer: SelectionMacroOffer) {
        if (!BuildConfig.ENABLE_GRAMMAR) return
        // Harper's own state is only in the way when Harper is the one to ask:
        // a LanguageTool server first on the list checks the selection itself.
        if (grammarPlan().steps.firstOrNull() == GrammarStep.Harper) {
            if (!GrammarChecker.moduleReady) {
                // Play, before the library's part is here.
                if (dataSaverStatus.allows(MeteredFeature.DOWNLOADS)) GrammarChecker.requestModule()
                toast(R.string.ime_grammar_module_installing_toast)
                return
            }
            if (!GrammarChecker.available && grammarProbePending()) return
        }
        if (offer.busy != null) return
        val seq = ++macroSeq
        setMacroBusy(SelectionMacro.GRAMMAR_FIX)
        macroJob?.cancel()
        macroJob = serviceScope.launch {
            val outcome = lintField(offer.text, _uiState.value.settings.grammarDialect)
            if (!offerStillLive(offer, seq)) return@launch
            setMacroBusy(null)
            val lints = when (outcome) {
                is GrammarOutcome.Found -> outcome.lints
                is GrammarOutcome.Notice -> {
                    Toast.makeText(this@WMKeyboardService, outcome.notice, Toast.LENGTH_SHORT).show()
                    return@launch
                }
                GrammarOutcome.HarperPending -> return@launch toast(R.string.ime_grammar_module_installing_toast)
                GrammarOutcome.HarperMissing -> return@launch toast(R.string.ime_selection_macro_grammar_unavailable_toast)
            }
            val fixed = GrammarChecker.applyAll(offer.text, lints)
            if (fixed == offer.text) toast(R.string.ime_selection_macro_grammar_clean_toast) else rewriteSelection(fixed)
        }
    }

    /** DeepL Write over the selection alone, committed in place (#331). */
    private fun rephraseSelection(offer: SelectionMacroOffer) {
        val deepl = _uiState.value.settings.deeplLive
        if (!deepl.writeActive || offer.busy != null) return
        val text = offer.text.trim()
        if (text.isEmpty()) return
        val seq = ++macroSeq
        setMacroBusy(SelectionMacro.DEEPL_WRITE)
        macroJob?.cancel()
        macroJob = serviceScope.launch {
            val result = deeplRephrase(text, deepl)
            if (!offerStillLive(offer, seq)) return@launch
            setMacroBusy(null)
            result.fold(
                onSuccess = { r ->
                    val better = r.text.trim()
                    if (better.isEmpty() || better == text) {
                        toast(R.string.ime_selection_macro_deepl_clean_toast)
                    } else {
                        rewriteSelection(better)
                    }
                },
                onFailure = { e ->
                    Toast.makeText(
                        this@WMKeyboardService,
                        requestErrorText(e, R.string.ime_grammar_deepl_error),
                        Toast.LENGTH_SHORT,
                    ).show()
                },
            )
        }
    }

    /** Reads the selection aloud, or stops a reading in progress. */
    private fun toggleReadAloud(offer: SelectionMacroOffer) {
        if (offer.speaking) {
            stopReadAloud()
            return
        }
        val speaker = vocabSpeaker ?: VocabSpeaker(this).also { vocabSpeaker = it }
        val locale = when {
            offer.content.hasBengali -> Locale("bn", "BD")
            // Devanagari is not only Hindi, but Hindi is the voice every device has.
            offer.content.hasDevanagari -> Locale("hi", "IN")
            else -> Locale.getDefault()
        }
        val vocab = _uiState.value.settings.vocabulary
        // The speaker is shared: this reading ends Read back's.
        if (_uiState.value.readingBack) _uiState.update { it.copy(readingBack = false) }
        setSpeaking(true)
        speaker.speak(offer.text, null, vocab.ttsRate, vocab.ttsPitch, locale) {
            // The engine calls back on its own thread.
            serviceScope.launch { setSpeaking(false) }
        }
    }

    private fun stopReadAloud() {
        vocabSpeaker?.stop()
        if (_uiState.value.selectionMacros?.speaking == true) setSpeaking(false)
    }

    /**
     * Read back: the selection, or else the whole field, read aloud in the
     * keyboard's language; tapped while reading, it stops. A downloaded MMS
     * voice reads it when there is one for the language, the phone's own
     * voice otherwise (see [VocabSpeaker]). Never a password field.
     */
    private fun toggleReadBack() {
        val state = _uiState.value
        if (state.readingBack) {
            stopReadBack()
            return
        }
        if (state.secureField) return
        val text = (selectedFieldText() ?: readBackFieldText())?.take(READ_BACK_MAX_CHARS)
        if (text.isNullOrBlank()) return
        val speaker = vocabSpeaker ?: VocabSpeaker(this).also { vocabSpeaker = it }
        if (state.selectionMacros?.speaking == true) setSpeaking(false)
        val vocab = state.settings.vocabulary
        _uiState.update { it.copy(readingBack = true) }
        speaker.speak(text, null, vocab.ttsRate, vocab.ttsPitch, Locale.forLanguageTag(state.language.localeTag)) {
            // The engine calls back on its own thread.
            serviceScope.launch { _uiState.update { it.copy(readingBack = false) } }
        }
    }

    /** The field's text for Read back: all of it when the editor hands it over, else a window around the caret. */
    private fun readBackFieldText(): String? {
        val ic = currentInputConnection ?: return null
        val whole = runCatching { ic.getExtractedText(ExtractedTextRequest(), 0)?.text?.toString() }.getOrNull()
        val text = whole ?: runCatching {
            ic.getTextBeforeCursor(READ_BACK_MAX_CHARS, 0)?.toString().orEmpty() +
                ic.getTextAfterCursor(READ_BACK_MAX_CHARS, 0)?.toString().orEmpty()
        }.getOrNull()
        return text?.takeIf { it.isNotBlank() }
    }

    private fun stopReadBack() {
        if (!_uiState.value.readingBack) return
        vocabSpeaker?.stop()
        _uiState.update { it.copy(readingBack = false) }
    }

    /**
     * The converter for [languageId]'s current sources, built when they change,
     * or null while that language is not loaded: Bengali with no word list at
     * all, or a phonetic language whose layout is not enabled.
     */
    private fun romanizedConverter(languageId: String): RomanizedConverter? {
        val engine = suggestionEngine ?: return null
        val bengali = languageId == PhoneticSchemes.BENGALI.languageId
        if (bengali && !bengaliListLoaded()) return null
        if (!bengali && languageId !in engine.extraPhonetic) return null
        val backend = engine.phoneticBackend(languageId) ?: return null
        val key = PhoneticBackendKey(backend.spellings, backend.index)
        romanizedConverters[languageId]?.let { (builtFrom, converter) -> if (builtFrom.sameAs(key)) return converter }
        return RomanizedConverter(backend.scheme, backend.spellings, backend.index)
            .also { romanizedConverters[languageId] = key to it }
    }

    /**
     * The selection between Zawgyi and Unicode, whichever way the detector
     * reads it. Written past the field's own conversion: the result is already
     * in the encoding the user asked for, and a field written in Zawgyi would
     * otherwise convert it a second time.
     */
    private fun convertZawgyiSelection(offer: SelectionMacroOffer, text: String) {
        if (offer.busy != null) return
        val seq = ++macroSeq
        setMacroBusy(SelectionMacro.ZAWGYI)
        macroJob?.cancel()
        macroJob = serviceScope.launch {
            val out = withContext(Dispatchers.Default) { Zawgyi.convertEitherWay(text) }
            if (!offerStillLive(offer, seq)) return@launch
            setMacroBusy(null)
            if (out == text) return@launch
            val legacy = currentInputConnection as? LegacyOutputConnection
            legacy?.passThrough = true
            try {
                rewriteSelection(out)
            } finally {
                legacy?.passThrough = false
            }
        }
    }

    /** Both directions of both languages: [macro] says which. */
    private fun convertRomanized(offer: SelectionMacroOffer, macro: SelectionMacro) {
        val hindi = macro == SelectionMacro.TO_HINDI || macro == SelectionMacro.TO_HINGLISH
        val scheme = if (hindi) PhoneticSchemes.HINDI else PhoneticSchemes.BENGALI
        val converter = romanizedConverter(scheme.languageId) ?: return toast(
            if (hindi) {
                R.string.ime_selection_macro_hindi_unavailable_toast
            } else {
                R.string.ime_selection_macro_bengali_unavailable_toast
            },
        )
        val toNative = macro == SelectionMacro.TO_BANGLA || macro == SelectionMacro.TO_HINDI
        if (offer.busy != null) return
        val seq = ++macroSeq
        setMacroBusy(macro)
        macroJob?.cancel()
        macroJob = serviceScope.launch {
            val out = withContext(Dispatchers.Default) {
                if (toNative) converter.toNative(offer.text) else converter.toRoman(offer.text)
            }
            if (!offerStillLive(offer, seq)) return@launch
            setMacroBusy(null)
            if (out != null) rewriteSelection(out)
        }
    }

    private fun addContact(offer: SelectionMacroOffer) {
        val extra = if (offer.kind == SelectionKind.PHONE) ContactsContract.Intents.Insert.PHONE else ContactsContract.Intents.Insert.EMAIL
        val started = startMacroActivity(
            Intent(ContactsContract.Intents.Insert.ACTION)
                .setType(ContactsContract.RawContacts.CONTENT_TYPE)
                .putExtra(extra, offer.text),
            Intent(Intent.ACTION_INSERT_OR_EDIT)
                .setType(ContactsContract.Contacts.CONTENT_ITEM_TYPE)
                .putExtra(extra, offer.text),
        )
        if (!started) toast(R.string.ime_selection_macro_no_app_toast)
    }

    private fun openMap(offer: SelectionMacroOffer) {
        val place = offer.content.place ?: Place.Address(offer.text)
        val query = when (place) {
            is Place.Coordinates -> "${place.point.lat},${place.point.lng}"
            is Place.Address -> place.text
        }
        val started = startMacroActivity(
            Intent(Intent.ACTION_VIEW, Uri.parse(Places.geoUri(place))),
            Intent(Intent.ACTION_VIEW, Uri.parse("https://www.google.com/maps/search/?api=1&query=" + Uri.encode(query))),
        )
        if (!started) toast(R.string.ime_selection_macro_no_app_toast)
    }

    private fun addCalendarEvent(offer: SelectionMacroOffer) {
        val hit = offer.content.dateTime ?: return
        val settings = _uiState.value.settings
        // In the keyboard's own composer, filled in, unless the user set Save to
        // hand events to the calendar app (or the Calendar tool is off).
        if (settings.calendarTool.saveMode == com.wasimaster.wmkeyboard.core.settings.CalendarSaveMode.KEYBOARD &&
            ToolbarTool.CALENDAR in settings.enabledTools
        ) {
            _uiState.update {
                it.copy(
                    toolPrefill = ToolPrefill.CalendarEvent(
                        title = offer.text.take(MAX_EVENT_TITLE),
                        start = hit.startMillis,
                        end = hit.endMillis,
                        allDay = hit.allDay,
                        zoneId = hit.zoneId,
                    ),
                )
            }
            if (_uiState.value.panel == PanelMode.CALENDAR) {
                // Already open: onPanelChange would close it, so hand the prefill over here.
                calendarTool.onPanelOpen(_uiState.value.toolPrefill)
                onToolPrefillConsumed()
            } else {
                onPanelChange(PanelMode.CALENDAR)
            }
            return
        }
        val intent = Intent(Intent.ACTION_INSERT)
            .setData(CalendarContract.Events.CONTENT_URI)
            .putExtra(CalendarContract.EXTRA_EVENT_BEGIN_TIME, hit.startMillis)
            .putExtra(CalendarContract.EXTRA_EVENT_END_TIME, hit.endMillis)
            .putExtra(CalendarContract.EXTRA_EVENT_ALL_DAY, hit.allDay)
            .putExtra(CalendarContract.Events.TITLE, offer.text.take(MAX_EVENT_TITLE))
        // The zone the text named is the zone the event is in; otherwise the
        // calendar's own default is the right one.
        if (hit.zoneNamed) intent.putExtra(CalendarContract.Events.EVENT_TIMEZONE, hit.zoneId)
        if (!startMacroActivity(intent)) toast(R.string.ime_selection_macro_no_app_toast)
    }

    private fun setMacroBusy(macro: SelectionMacro?) {
        _uiState.update { state ->
            state.selectionMacros?.takeIf { it.busy != macro }?.let { state.copy(selectionMacros = it.copy(busy = macro)) } ?: state
        }
    }

    private fun setSpeaking(on: Boolean) {
        _uiState.update { state ->
            state.selectionMacros?.takeIf { it.speaking != on }?.let { state.copy(selectionMacros = it.copy(speaking = on)) } ?: state
        }
    }

    /** Whether an async macro's result still describes what is selected. */
    private fun offerStillLive(offer: SelectionMacroOffer, seq: Int): Boolean =
        seq == macroSeq && _uiState.value.selectionMacros?.let { it.text == offer.text && it.kind == offer.kind } == true

    private fun toast(@StringRes id: Int) {
        Toast.makeText(this, getString(id), Toast.LENGTH_SHORT).show()
    }

    private fun toast(text: String) {
        Toast.makeText(this, text, Toast.LENGTH_SHORT).show()
    }

    /** Opens a search-style panel already carrying [query], and runs it. */
    private fun openMacroSearch(panel: PanelMode, query: String) {
        if (panel == PanelMode.WEB_SEARCH && _uiState.value.panel != panel) {
            _uiState.update { it.copy(searchTab = SearchTab.ALL, searchCategory = null) }
        }
        onPanelChange(panel)
        if (_uiState.value.panel != panel) return
        _uiState.update { it.copy(mediaQuery = query) }
        runMediaSearch()
    }

    /**
     * Starts the first of [intents] that any app will take, wrapped in a
     * chooser when the macro is a share (which is what a share is: the user
     * picking who gets it). True when one of them started.
     *
     * Several intents because one action does not always reach the app that
     * handles a scheme: a mail client may claim `mailto:` for SENDTO and not
     * for VIEW. Nothing starting at all leaves the bar up and the field
     * untouched, which is what every other activity start here does.
     */
    private fun startMacroActivity(vararg intents: Intent, chooser: Boolean = false): Boolean {
        for (intent in intents) {
            val target = if (chooser) Intent.createChooser(intent, null) else intent
            val started = runCatching {
                startActivity(target.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))
            }.isSuccess
            if (started) return true
        }
        return false
    }

    /**
     * Text-editing panel buttons. Cursor moves go through the editor as key
     * events so apps handle them natively; while selection mode is on the
     * moves carry shift and extend the selection.
     *
     * [extendSelection] forces that on for a single call, for callers that have
     * their own reason to extend — see [onCursorTool]. It never turns extending
     * *off*: selection mode still wins when it is on, from whichever surface
     * armed it (see [KeyboardUiState.selectingText]).
     */
    fun onTextEdit(action: TextEditAction, extendSelection: Boolean = false, haptic: Boolean = true) {
        // An arrow or a backspace pressed while one of the keyboard's own
        // fields has the keys is about *that* field's caret (#161). Asked
        // first, and before the input-connection check, so it works in a
        // window with no editor focused at all.
        if (captureTextEdit(action, extendSelection, haptic)) return
        // A delete key is the delete key, whichever action an author reached
        // for (issue #226). Straight to the real deletions rather than to a
        // bare key event: that is where the autocorrect undo, the emoji
        // cluster, the morse buffer and the ink-in-progress all live, and a ⌫
        // on the pad that skipped them behaved unlike the one on the letters.
        // Ahead of the input-connection check because both cope without one.
        if (action == TextEditAction.BACKSPACE || action == TextEditAction.FORWARD_DELETE) {
            if (haptic) vibrate()
            if (action == TextEditAction.BACKSPACE) onDelete() else onForwardDelete()
            return
        }
        // A word at a time (#980): one step of the delete key's word swipe,
        // which already copes with the keyboard's own boxes and a null field.
        if (action == TextEditAction.DELETE_WORD || action == TextEditAction.DELETE_WORD_FORWARD) {
            if (haptic) vibrate()
            if (action == TextEditAction.DELETE_WORD) onDeleteWord() else onForwardDeleteWord()
            return
        }
        // Before the composing text is committed below: the word still being
        // typed is the one it ends without a space (#851).
        if (action == TextEditAction.NO_SPACE) {
            if (haptic) vibrate()
            // A second tap close behind the first arms it for the next key
            // (#863), the way a double tap locks Shift; a tap with it armed
            // calls it off.
            val now = SystemClock.uptimeMillis()
            val second = lastNoSpaceTapAt?.let { now - it < SHIFT_DOUBLE_TAP_MS } == true
            lastNoSpaceTapAt = if (second) null else now
            when {
                _uiState.value.noSpaceArmed -> setNoSpaceArmed(false)
                second -> {
                    noSpace()
                    setNoSpaceArmed(true)
                }
                else -> noSpace()
            }
            return
        }
        // What a hold of No space runs (#863): the next key typed, or word
        // picked, gets no space. A modifier, like a held Shift, so it leaves
        // what is already there alone: the word being typed stays open for
        // the strip, and a space already typed stays. Again calls it off.
        if (action == TextEditAction.NO_SPACE_NEXT) {
            if (haptic) vibrate()
            lastNoSpaceTapAt = null
            setNoSpaceArmed(!_uiState.value.noSpaceArmed)
            return
        }
        // Before the composing text is committed below: a word still being
        // typed is the word to retype.
        if (action == TextEditAction.RETYPE_WORD) {
            if (haptic) vibrate()
            retypeWord()
            return
        }
        val ic = currentInputConnection ?: return
        if (haptic) vibrate()
        if (stepSegment(action, extendSelection || _uiState.value.selectingText)) return
        endCompositionForCaretKey(ic)
        lastGestureWord = null
        val selecting = extendSelection || _uiState.value.selectingText
        if (action in CARET_EDIT_ACTIONS) lastCaretScrubMs = SystemClock.uptimeMillis()
        when (action) {
            TextEditAction.LEFT -> sendEditorKey(KeyEvent.KEYCODE_DPAD_LEFT, selecting)
            TextEditAction.RIGHT -> sendEditorKey(KeyEvent.KEYCODE_DPAD_RIGHT, selecting)
            TextEditAction.UP -> sendEditorKey(KeyEvent.KEYCODE_DPAD_UP, selecting)
            TextEditAction.DOWN -> sendEditorKey(KeyEvent.KEYCODE_DPAD_DOWN, selecting)
            TextEditAction.HOME -> sendEditorKey(KeyEvent.KEYCODE_MOVE_HOME, selecting)
            TextEditAction.END -> sendEditorKey(KeyEvent.KEYCODE_MOVE_END, selecting)
            TextEditAction.PAGE_UP -> sendEditorKey(KeyEvent.KEYCODE_PAGE_UP, selecting)
            TextEditAction.PAGE_DOWN -> sendEditorKey(KeyEvent.KEYCODE_PAGE_DOWN, selecting)
            // Ctrl+Arrow is the editor's move-by-word shortcut; with the panel's
            // select mode on it carries shift too and extends word by word.
            // Measured by the keyboard instead when the user set where a word
            // ends (#662); the key event is the fallback for a field that will
            // not say where its caret is.
            TextEditAction.WORD_LEFT ->
                if (!moveByWordDirectly(ic, back = true, selecting = selecting)) {
                    sendEditorKey(KeyEvent.KEYCODE_DPAD_LEFT, selecting, ctrl = true)
                }
            TextEditAction.WORD_RIGHT ->
                if (!moveByWordDirectly(ic, back = false, selecting = selecting)) {
                    sendEditorKey(KeyEvent.KEYCODE_DPAD_RIGHT, selecting, ctrl = true)
                }
            TextEditAction.SELECT_WORD -> selectWordAtCursor(ic)
            TextEditAction.SELECT_LINE -> selectLineAtCursor(ic)
            // Reads the armed state rather than `selecting`, which a caller may
            // have forced on for this one call. Switching it on is the panel's
            // own flag, which dies with the panel; switching it off clears every
            // flag, so the key means what it says even when the toolbar's mode
            // is the one holding selection on.
            TextEditAction.SELECT ->
                if (_uiState.value.selectingText) {
                    clearSelectionArm()
                } else {
                    _uiState.update { it.copy(textEditSelecting = true) }
                }
            // Selects, and nothing else. This used to arm the panel's select
            // mode as well, which lit the Select key and the toolbar's mode
            // tool for a press that never asked for them, and left a mode on
            // that the user then had to find and switch off (#40).
            TextEditAction.SELECT_ALL -> selectAllInField(ic)
            TextEditAction.COPY -> {
                if (refuseNullFieldCopy()) return
                flushLearningBuffer(verifyCorrections = false)
                // With nothing selected, the whole field, the way holding C
                // does it (#970): a copy key that copies nothing is a dead key.
                val whole = if (ic.getSelectedText(0).isNullOrEmpty()) selectWholeField(ic) else null
                if (!privateCopy(ic, cut = false, whole)) ic.performContextMenuAction(android.R.id.copy)
                maybeToastCopied()
                _uiState.update { it.copy(textEditSelecting = false) }
            }
            TextEditAction.PASTE -> {
                if (!isClipboardAccessible()) return
                releaseUserShift()
                if (privatePaste(ic) || pasteIntoNullField(ic)) return
                ic.performContextMenuAction(android.R.id.paste)
                purgeAfterPasswordPaste()
            }
            // Handled above, before the composing text was committed.
            TextEditAction.BACKSPACE, TextEditAction.FORWARD_DELETE, TextEditAction.RETYPE_WORD,
            TextEditAction.NO_SPACE, TextEditAction.NO_SPACE_NEXT,
            TextEditAction.DELETE_WORD, TextEditAction.DELETE_WORD_FORWARD,
            -> Unit
            // Ctrl+Home / Ctrl+End are the editor's whole-text moves, the same
            // way Ctrl+Arrow is its word move; with select mode on they carry
            // shift too and extend to the end.
            // Set directly first, the way Gboard does it (#785): plenty of
            // fields take Ctrl+Home / Ctrl+End as a shortcut or drop it.
            TextEditAction.DOC_START ->
                if (!moveToTextEdgeDirectly(ic, toEnd = false, selecting = selecting)) {
                    sendEditorKey(KeyEvent.KEYCODE_MOVE_HOME, selecting, ctrl = true)
                }
            TextEditAction.DOC_END ->
                if (!moveToTextEdgeDirectly(ic, toEnd = true, selecting = selecting)) {
                    sendEditorKey(KeyEvent.KEYCODE_MOVE_END, selecting, ctrl = true)
                }
            // Like copy, it ends the panel's select mode: the selection is gone.
            TextEditAction.CUT -> {
                flushLearningBuffer(verifyCorrections = false)
                if (!privateCopy(ic, cut = true)) ic.performContextMenuAction(android.R.id.cut)
                _uiState.update { it.copy(textEditSelecting = false) }
                releaseUserShift()
            }
        }
    }

    /**
     * Copy or cut the selection by hand, for while incognito keeps the
     * keyboard's clipboard private (#392). The editor's own copy action would
     * put the text on the system clipboard for every app to read, so the
     * selection is read and kept in [KeyboardClipboard] instead, and a cut
     * deletes it by committing nothing over it. False when that mode is off,
     * and the caller asks the editor as usual.
     *
     * A private copy has none of the feedback a system one gets: no system
     * "Copied" bubble, no clipboard listener putting the paste chip on the
     * strip. So the selection is let go after it, the caret left at its end,
     * the way FlorisBoard does it; the chip comes from [recordPrivateCopy].
     * Without either, a copy that worked looked like a tap that did nothing
     * (#679).
     */
    private fun privateCopy(ic: InputConnection, cut: Boolean, whole: CharSequence? = null): Boolean {
        if (!KeyboardClipboard.isPrivate) return false
        // An editor that cannot report its selection gets nothing copied,
        // rather than a fallback to its own copy that would leak it. [whole]
        // is the field the hold shortcut just selected, read before the
        // selection landed, for an editor slow to report it back.
        val selected = ic.getSelectedText(0)?.takeIf { it.isNotEmpty() } ?: whole
        if (!selected.isNullOrEmpty()) {
            KeyboardClipboard.copy(this, selected)
            if (cut) ic.commitText("", 1) else collapseSelectionToEnd(ic)
        }
        return true
    }

    /**
     * Drops the selection, leaving the caret where it ended. The offset comes
     * from the selection mirror, then from the editor; an editor that gives
     * neither gets a right arrow, which every text view and web page reads as
     * "collapse to the end".
     */
    private fun collapseSelectionToEnd(ic: InputConnection) {
        val end = if (expectedSelStart >= 0 && expectedSelEnd >= 0 && expectedSelStart != expectedSelEnd) {
            maxOf(expectedSelStart, expectedSelEnd)
        } else {
            ic.getExtractedText(ExtractedTextRequest(), 0)
                ?.takeIf { it.selectionStart >= 0 && it.selectionEnd >= 0 }
                ?.let { it.startOffset + maxOf(it.selectionStart, it.selectionEnd) }
        }
        if (end == null) {
            sendDownUpKeyEvents(KeyEvent.KEYCODE_DPAD_RIGHT)
            return
        }
        ic.setSelection(end, end)
        expectedSelStart = end
        expectedSelEnd = end
    }

    /**
     * Pastes the private clip (#392). False when there is none, and the
     * editor pastes from the system clipboard as usual: the keyboard reads
     * nothing there itself, the app does.
     */
    private fun privatePaste(ic: InputConnection): Boolean {
        val held = KeyboardClipboard.held ?: return false
        ic.commitText(held, 1)
        return true
    }

    /**
     * Paste in a terminal (#1007). A field with no type, Termux's, ignores the
     * context-menu paste and says nothing, so the text goes in as typed text,
     * which it does take. False anywhere else, or with no text to paste.
     */
    private fun pasteIntoNullField(ic: InputConnection): Boolean {
        if (!isNullField()) return false
        val text = (getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager).primaryClip
            ?.takeIf { it.itemCount > 0 }?.getItemAt(0)?.coerceToText(this)
        if (text.isNullOrEmpty()) return false
        ic.commitText(text, 1)
        return true
    }

    /**
     * Copy in a terminal (#1007): a selection there lives in the app's own
     * view, where no keyboard can read it. True, with a word saying so, rather
     * than a copy key that does nothing.
     */
    private fun refuseNullFieldCopy(): Boolean {
        if (!isNullField()) return false
        Toast.makeText(this, R.string.ime_service_null_field_copy_toast, Toast.LENGTH_SHORT).show()
        return true
    }

    /**
     * The movement half of [onTextEdit], for a keyboard-owned field.
     *
     * The caret moves, the backspace and Paste: those are what the field has,
     * and routing them here is what stops an arrow key pressed over a search
     * box from walking the caret in the app behind the panel. Paste joined
     * them in #434: the keys are typing into the box, so a Paste key means
     * the box too, and the Translate tool's text is the one people paste.
     * Select all, copy and cut followed in #612. Every action a key can run
     * goes to the box while it has the keys; to act on the app's text with
     * a tool open, the focus switch on the box hands the keys over (#665),
     * and this returns false for all of them until it takes them back.
     */
    private fun captureTextEdit(
        action: TextEditAction,
        extendSelection: Boolean,
        haptic: Boolean,
    ): Boolean {
        if (_uiState.value.captureTarget() == null) return false
        val extend = extendSelection || _uiState.value.selectingText
        if (_uiState.value.captureTarget() == CaptureTarget.KDE_REMOTE) {
            // Every caret key has an exact counterpart on the computer, so
            // they are sent as themselves rather than folded into "the ends".
            val shift = KdeModifiers(shift = extend)
            val ctrl = KdeModifiers(shift = extend, ctrl = true)
            val sent = when (action) {
                TextEditAction.LEFT -> KdeSpecialKey.LEFT to shift
                TextEditAction.RIGHT -> KdeSpecialKey.RIGHT to shift
                TextEditAction.UP -> KdeSpecialKey.UP to shift
                TextEditAction.DOWN -> KdeSpecialKey.DOWN to shift
                TextEditAction.HOME -> KdeSpecialKey.HOME to shift
                TextEditAction.END -> KdeSpecialKey.END to shift
                TextEditAction.PAGE_UP -> KdeSpecialKey.PAGE_UP to shift
                TextEditAction.PAGE_DOWN -> KdeSpecialKey.PAGE_DOWN to shift
                TextEditAction.WORD_LEFT -> KdeSpecialKey.LEFT to ctrl
                TextEditAction.WORD_RIGHT -> KdeSpecialKey.RIGHT to ctrl
                TextEditAction.DOC_START -> KdeSpecialKey.HOME to ctrl
                TextEditAction.DOC_END -> KdeSpecialKey.END to ctrl
                else -> null
            }
            if (sent != null) {
                kdeSendSpecial(sent.first, sent.second)
                if (haptic) vibrate()
                return true
            }
        }
        val handled = when (action) {
            TextEditAction.LEFT -> onCaptureCaretMove(-1, extend)
            TextEditAction.RIGHT -> onCaptureCaretMove(1, extend)
            // A one-line buffer, so up/Home is its start and down/End its end.
            TextEditAction.UP, TextEditAction.HOME, TextEditAction.PAGE_UP,
            TextEditAction.DOC_START,
            -> onCaptureCaretToEdge(end = false, extend = extend)
            TextEditAction.DOWN, TextEditAction.END, TextEditAction.PAGE_DOWN,
            TextEditAction.DOC_END,
            -> onCaptureCaretToEdge(end = true, extend = extend)
            // A word at a time (#612), by the rule a held delete measures words with.
            TextEditAction.WORD_LEFT -> captureWordStep(back = true, extend = extend)
            TextEditAction.WORD_RIGHT -> captureWordStep(back = false, extend = extend)
            TextEditAction.BACKSPACE -> captureBackspace()
            TextEditAction.PASTE -> capturePaste()
            // The selection keys and their flicks and holds (#612): Select
            // all, Copy and Cut did nothing in the clip editor or Combine's
            // boxes, or reached the app behind the panel, where nothing showed.
            TextEditAction.SELECT_ALL -> captureSelect { it.selectedAll() }
            TextEditAction.SELECT_WORD -> captureSelect { it.selectedWordAt(it.at) }
            TextEditAction.SELECT_LINE -> captureSelect { caret ->
                val start = caret.text.lastIndexOf('\n', (caret.at - 1).coerceAtLeast(0)).let { if (it < 0 || caret.at == 0) 0 else it + 1 }
                val end = caret.text.indexOf('\n', caret.at).let { if (it < 0) caret.text.length else it }
                caret.selected(start, end)
            }
            TextEditAction.COPY, TextEditAction.CUT -> {
                onCaptureSelectionAction(if (action == TextEditAction.CUT) CaptureSelectionAction.CUT else CaptureSelectionAction.COPY)
                return true
            }
            // Retyping takes a word out of the app's text; with the keys in
            // the box it would reach behind the panel, which is the focus
            // switch's job now (#665), so it does nothing here.
            TextEditAction.RETYPE_WORD -> true
            // A box of the keyboard's own adds no spaces to take back.
            TextEditAction.NO_SPACE, TextEditAction.NO_SPACE_NEXT -> true
            else -> false
        }
        if (handled && haptic) vibrate()
        return handled
    }

    /** The focused keyboard-owned field's selection set by [select]; false where it has none to set. */
    private fun captureSelect(select: (CaretText) -> CaretText): Boolean {
        val state = _uiState.value
        val target = state.captureTarget() ?: return false
        if (!target.movableCaret || target == CaptureTarget.WORD_SPELL) return false
        val before = state.captureCaretText() ?: return false
        captureCaretTo(select(before))
        return true
    }

    /** The caret a word back or on in the focused keyboard-owned field (#612). */
    private fun captureWordStep(back: Boolean, extend: Boolean): Boolean {
        val state = _uiState.value
        val target = state.captureTarget() ?: return false
        if (!target.movableCaret) return true
        if (target == CaptureTarget.WORD_SPELL) return onCaptureCaretToEdge(end = !back, extend = extend)
        val before = state.captureCaretText() ?: return false
        val at = before.at
        val to = if (back) {
            at - WordDelete.lengthBefore(before.text.substring(0, at), deleteWordBreaks())
        } else {
            at + WordDelete.lengthAfter(before.text.substring(at), deleteWordBreaks())
        }
        captureCaretTo(before.caretAt(to, extend))
        return true
    }

    /**
     * Toast confirming text landed on the clipboard, for the users who opt in
     * (some fields give no copy feedback of their own). Off by default.
     */
    private fun maybeToastCopied() {
        if (_uiState.value.settings.feedback.toastOnCopy) {
            Toast.makeText(
                this,
                getString(R.string.ime_service_copied_toast),
                Toast.LENGTH_SHORT,
            ).show()
        }
    }

    /**
     * Clipboard/undo/redo shortcuts fired by long-pressing A/C/V/X/Z/Y. Copy
     * and cut act on the current selection when one exists; with nothing
     * selected they select all first, so a bare long press copies or cuts the
     * whole field. Undo/redo delegate to [onUndoRedo], the same path the
     * toolbar's Undo/Redo tools use.
     *
     * [selectAllIfEmpty] is what makes that select-all convenience opt-out. It
     * suits a long press, which is a deliberate one-off gesture, and not a Mac
     * user's `Cmd+C`, where it would silently copy the whole message instead of
     * doing nothing the way every other keyboard on that machine does.
     */
    fun onClipboardKey(action: ClipboardKeyAction, selectAllIfEmpty: Boolean = true) {
        if (action == ClipboardKeyAction.UNDO || action == ClipboardKeyAction.REDO) {
            onUndoRedo(redo = action == ClipboardKeyAction.REDO)
            return
        }
        // A long-pressed V over one of the keyboard's own boxes pastes into
        // the box, as the Paste key does (#434).
        if (action == ClipboardKeyAction.PASTE && capturePaste()) return
        // And the rest act on the box too (#612): long-pressed A, C and X
        // selected and copied the app's text behind the panel instead.
        val boxAction = when (action) {
            ClipboardKeyAction.SELECT_ALL -> CaptureSelectionAction.SELECT_ALL
            ClipboardKeyAction.COPY -> CaptureSelectionAction.COPY
            ClipboardKeyAction.CUT -> CaptureSelectionAction.CUT
            else -> null
        }
        if (boxAction != null && _uiState.value.captureTarget() != null) {
            // Copy and cut with nothing selected take the whole box, as they
            // take the whole field.
            if (boxAction != CaptureSelectionAction.SELECT_ALL && selectAllIfEmpty &&
                _uiState.value.captureCaretText()?.hasSelection == false
            ) {
                captureSelect { it.selectedAll() }
            }
            onCaptureSelectionAction(boxAction)
            return
        }
        val ic = currentInputConnection ?: return
        commitComposing(ic, autocorrect = false)
        lastGestureWord = null
        val hasSelection = ic.getSelectedText(0)?.isNotEmpty() == true
        when (action) {
            ClipboardKeyAction.SELECT_ALL -> {
                selectAllInField(ic)
                _uiState.update { it.copy(textEditSelecting = true) }
            }
            ClipboardKeyAction.COPY -> {
                if (refuseNullFieldCopy()) return
                val whole = if (!hasSelection && selectAllIfEmpty) selectWholeField(ic) else null
                if (!privateCopy(ic, cut = false, whole)) ic.performContextMenuAction(android.R.id.copy)
                maybeToastCopied()
                _uiState.update { it.copy(textEditSelecting = false) }
            }
            ClipboardKeyAction.CUT -> {
                val whole = if (!hasSelection && selectAllIfEmpty) selectWholeField(ic) else null
                if (!privateCopy(ic, cut = true, whole)) ic.performContextMenuAction(android.R.id.cut)
                _uiState.update { it.copy(textEditSelecting = false) }
                releaseUserShift()
            }
            ClipboardKeyAction.PASTE -> {
                if (!isClipboardAccessible()) return
                releaseUserShift()
                if (privatePaste(ic) || pasteIntoNullField(ic)) return
                ic.performContextMenuAction(android.R.id.paste)
                purgeAfterPasswordPaste()
            }
            ClipboardKeyAction.UNDO, ClipboardKeyAction.REDO -> Unit
        }
    }

    /**
     * Selects the whole field for a hold copy or cut with nothing selected,
     * and returns its text when the editor would give it.
     *
     * Selection by offsets rather than the editor's own Select all: a web
     * field ignores that context-menu action, so a bare hold on C copied
     * nothing and the selection had to be made first. A web field, or one
     * too long to read in one go, gets [selectAllInField] instead, which
     * sends Ctrl+A to a page.
     */
    private fun selectWholeField(ic: InputConnection): CharSequence? {
        val before = ic.getTextBeforeCursor(WHOLE_FIELD_LIMIT, 0)
        val after = ic.getTextAfterCursor(WHOLE_FIELD_LIMIT, 0)
        if (before == null || after == null || isWebEditField() ||
            before.length >= WHOLE_FIELD_LIMIT || after.length >= WHOLE_FIELD_LIMIT
        ) {
            selectAllInField(ic)
            return null
        }
        val end = before.length + after.length
        if (end == 0) return null
        ic.setSelection(0, end)
        expectedSelStart = 0
        expectedSelEnd = end
        return android.text.TextUtils.concat(before, after)
    }

    /**
     * DPAD/home/end navigation; with [shift] the move extends the selection,
     * and with [ctrl] it moves by whole words (the editor's Ctrl+Arrow binding).
     */
    /**
     * The Select all key and tool. In a web page it goes in as Ctrl+A, so the
     * page's own editor runs its select-all (#679). The platform action
     * selects the editable's DOM instead, and a code editor that only draws
     * the lines in view (CodeMirror, in ViolentMonkey) read that as a
     * selection of those lines, redrew, and lost it: Select all lit up and
     * went straight out again. Ctrl+A is select all in any page that does not
     * handle it itself, so a plain web field is no worse off.
     */
    private fun selectAllInField(ic: InputConnection) {
        if (isWebEditField()) {
            sendEditorKey(KeyEvent.KEYCODE_A, shift = false, ctrl = true)
        } else {
            ic.performContextMenuAction(android.R.id.selectAll)
        }
    }

    private fun sendEditorKey(code: Int, shift: Boolean, ctrl: Boolean = false) {
        if (!shift && !ctrl) {
            sendDownUpKeyEvents(code)
            return
        }
        val ic = currentInputConnection ?: return
        if (shift) {
            noteSelectionAnchor()
            val vertical = code == KeyEvent.KEYCODE_DPAD_UP || code == KeyEvent.KEYCODE_DPAD_DOWN
            if (vertical && !ctrl && extendSelectionToEdgeDirectly(ic, up = code == KeyEvent.KEYCODE_DPAD_UP)) {
                return
            }
        }
        val time = android.os.SystemClock.uptimeMillis()
        var meta = 0
        if (shift) meta = meta or KeyEvent.META_SHIFT_ON or KeyEvent.META_SHIFT_LEFT_ON
        if (ctrl) meta = meta or KeyEvent.META_CTRL_ON or KeyEvent.META_CTRL_LEFT_ON
        // A bare meta flag isn't enough for every editor: TextView tracks
        // modifier state from the modifier keys' own down/up events, so wrap
        // the arrow in real shift/ctrl presses like a hardware keyboard would.
        if (shift) {
            ic.sendKeyEvent(
                KeyEvent(time, time, KeyEvent.ACTION_DOWN, KeyEvent.KEYCODE_SHIFT_LEFT, 0, meta)
            )
        }
        if (ctrl) {
            ic.sendKeyEvent(
                KeyEvent(time, time, KeyEvent.ACTION_DOWN, KeyEvent.KEYCODE_CTRL_LEFT, 0, meta)
            )
        }
        ic.sendKeyEvent(KeyEvent(time, time, KeyEvent.ACTION_DOWN, code, 0, meta))
        ic.sendKeyEvent(KeyEvent(time, time, KeyEvent.ACTION_UP, code, 0, meta))
        if (ctrl) {
            ic.sendKeyEvent(
                KeyEvent(time, time, KeyEvent.ACTION_UP, KeyEvent.KEYCODE_CTRL_LEFT, 0, meta)
            )
        }
        if (shift) {
            ic.sendKeyEvent(
                KeyEvent(time, time, KeyEvent.ACTION_UP, KeyEvent.KEYCODE_SHIFT_LEFT, 0, meta)
            )
        }
    }

    /**
     * Selects the word straddling the cursor: walks out to the word boundaries
     * on either side of the caret and sets the selection to span them. A caret
     * on whitespace or punctuation (no word to grab) is left untouched. The
     * offsets from [getExtractedText] are used directly as document positions,
     * matching how the rest of this service treats them.
     *
     * Selects, and nothing else: it does not arm selection mode. It used to,
     * which meant the trackpad's double tap and the Select word tool switched
     * on a mode nobody asked for and left it on (#78). The two callers that do
     * want the mode after selecting — the Selection mode tool's ladder and a
     * panel's Select key — arm it themselves, the same split [TextEditAction.SELECT_ALL]
     * got in #40.
     */
    private fun selectWordAtCursor(ic: InputConnection) {
        val et = ic.getExtractedText(ExtractedTextRequest(), 0) ?: return
        val text = et.text ?: return
        val n = text.length
        val origin = et.startOffset
        val selStart = et.selectionStart.coerceIn(0, n)
        val selEnd = et.selectionEnd.coerceIn(0, n)
        val breaks = cursorWordBreaks()
        // Pressed again over a selection it made: the selection grows by the
        // word on each side, and with shift down it gives the last growth back
        // (#662). Any other selection is a fresh start.
        val grown = selectWordSteps.lastOrNull()
        if (selStart != selEnd && grown != null &&
            grown.first == origin + minOf(selStart, selEnd) && grown.last + 1 == origin + maxOf(selStart, selEnd)
        ) {
            val shrinking = _uiState.value.shiftSelectsText
            val next = if (shrinking) {
                // The word the first press took is as small as it goes.
                if (selectWordSteps.size < 2) return
                selectWordSteps.removeAt(selectWordSteps.lastIndex)
                selectWordSteps.last()
            } else {
                // Out a ring at a time, the parts touching the selection
                // before anything past a space (#679): see [SelectWordGrowth].
                val ring = SelectWordGrowth.next(text, minOf(selStart, selEnd), maxOf(selStart, selEnd)) ?: return
                (origin + ring.first until origin + ring.last + 1).also { selectWordSteps += it }
            }
            if (shrinking) consumeShift()
            setWordSelection(ic, next.first, next.last + 1)
            return
        }
        selectWordSteps.clear()
        // Anchor at the caret (selection end); clamp defensively.
        val caret = et.selectionEnd.let { if (it in 0..n) it else et.selectionStart }
        if (caret !in 0..n) return
        val word = if (breaks == null) {
            fun isWord(c: Char) = c.isLetterOrDigit() || c == '\'' || c == '_'
            var start = caret
            var end = caret
            while (start > 0 && isWord(text[start - 1])) start--
            while (end < n && isWord(text[end])) end++
            if (start == end) null else start until end
        } else {
            WordDelete.wordAround(text, caret, breaks)
        }
        // No word at the caret, only marks: what sits between the spaces
        // around it, so "example@⌶" selects "example@" (#679).
        val range = word ?: SelectWordGrowth.tokenAt(text, caret) ?: return
        val picked = origin + range.first until origin + range.last + 1
        selectWordSteps += picked
        setWordSelection(ic, picked.first, picked.last + 1)
    }

    /**
     * The selections successive Select word presses made, smallest first, so
     * the next press grows the last one and a shifted press steps back to the
     * one before (#662). Cleared by a press over anything else.
     */
    private val selectWordSteps = ArrayList<IntRange>()

    private fun setWordSelection(ic: InputConnection, start: Int, end: Int) {
        ic.setSelection(start, end)
        // The range is known; recording it directly closes the window where
        // the cache still said "collapsed" and a fast backspace would have
        // deleted the character before the selection instead of it.
        expectedSelStart = start
        expectedSelEnd = end
    }

    /** What ends a word for the delete keys' word steps (#662). */
    private fun deleteWordBreaks(): WordBreaks = _uiState.value.settings.textEditing.let {
        WordBreaks(
            punctuation = it.deleteWordStopsAtPunctuation,
            capitals = it.deleteWordStopsAtCapitals,
            digits = it.deleteWordStopsAtDigits,
        )
    }

    /**
     * What ends a word for the word cursor moves and Select word, or null when
     * the app's own word moves are wanted ([CursorWordSteps.APP]).
     */
    private fun cursorWordBreaks(): WordBreaks? = _uiState.value.settings.textEditing.let {
        when (it.cursorWordSteps) {
            CursorWordSteps.APP -> null
            CursorWordSteps.SPACES ->
                WordBreaks(punctuation = false, capitals = it.cursorWordStopsAtCapitals, digits = it.cursorWordStopsAtDigits)
            CursorWordSteps.PUNCTUATION ->
                WordBreaks(punctuation = true, capitals = it.cursorWordStopsAtCapitals, digits = it.cursorWordStopsAtDigits)
        }
    }

    /**
     * Word left or Word right, measured by the keyboard rather than handed to
     * the app as Ctrl and an arrow (#662): the app's own idea of a word is what
     * the user set [CursorWordSteps] to get away from. Left lands at the start
     * of the word behind the caret, right at the end of the one ahead of it,
     * spaces in between included, the same step a word delete takes.
     *
     * With [selecting], the selection's moving end goes and its anchor stays,
     * as a shifted step does. False, so the key event runs, under
     * [CursorWordSteps.APP] and when the field has not said where its caret is.
     */
    private fun moveByWordDirectly(ic: InputConnection, back: Boolean, selecting: Boolean): Boolean {
        val breaks = cursorWordBreaks() ?: return false
        val start = expectedSelStart
        val end = expectedSelEnd
        if (start < 0 || end < start) return false
        if (selecting) noteSelectionAnchor()
        val anchor = if (selecting) anchorFor(start, end, if (back) -1 else 1) else -1
        // Without a selection being stretched, a word move from a range starts
        // at the range's edge on the side it goes, like an arrow key's.
        val focus = when {
            selecting -> if (anchor == start) end else start
            back -> start
            else -> end
        }
        val distance = if (back) {
            val before = ic.getTextBeforeCursor(WORD_MOVE_REACH, 0) ?: return false
            // The read is measured from the selection's start; a moving end at
            // its far side reads the selection itself too.
            val upTo = if (focus == end && end > start) {
                val selected = ic.getSelectedText(0) ?: return false
                "$before$selected"
            } else {
                before
            }
            WordDelete.lengthBefore(upTo, breaks)
        } else {
            val after = ic.getTextAfterCursor(WORD_MOVE_REACH, 0) ?: return false
            val from = if (focus == start && end > start) {
                val selected = ic.getSelectedText(0) ?: return false
                "$selected$after"
            } else {
                after
            }
            WordDelete.lengthAfter(from, breaks)
        }
        if (distance == 0) return true
        val to = if (back) (focus - distance).coerceAtLeast(0) else focus + distance
        if (selecting) return setStretchedSelection(ic, anchor, to)
        if (!ic.setSelection(to, to)) return false
        expectedSelStart = to
        expectedSelEnd = to
        return true
    }

    /**
     * Selects the entire line the cursor sits on: walks out to the nearest
     * newline on either side and sets the selection to span the line content
     * (newlines themselves are excluded). An empty line leaves the caret
     * untouched, matching [selectWordAtCursor]'s no-op on bare whitespace, and
     * like it this arms no mode of its own (#78).
     */
    private fun selectLineAtCursor(ic: InputConnection) {
        val et = ic.getExtractedText(ExtractedTextRequest(), 0) ?: return
        val text = et.text ?: return
        val n = text.length
        val caret = et.selectionEnd.let { if (it in 0..n) it else et.selectionStart }
        if (caret !in 0..n) return
        fun isLineBreak(c: Char) = c == '\n' || c == '\r'
        var start = caret
        var end = caret
        while (start > 0 && !isLineBreak(text[start - 1])) start--
        while (end < n && !isLineBreak(text[end])) end++
        if (start == end) return
        ic.setSelection(start, end)
        expectedSelStart = start
        expectedSelEnd = end
    }

    /**
     * One stable bundle for the snippets panel, built outside
     * [ServiceKeyboardContent] for the reason [converterCallbacks] is: that
     * method sits against the JVM's 64K size ceiling, and folders needed two
     * callbacks more than the one parameter it used to spend.
     */
    private val snippetPanelCallbacks by lazy {
        com.wasimaster.wmkeyboard.ime.ui.SnippetPanelCallbacks(
            onSnippet = ::onSnippetTapped,
            onSnippetHold = ::onSnippetHeld,
            onFolderOpen = ::onSnippetFolderOpen,
            onFolderToggle = ::onSnippetFolderToggle,
            onPickerPick = ::onSnippetPickerPick,
            onPickerDrill = ::onSnippetPickerDrill,
            onPickerBack = ::onSnippetPickerBack,
            onSearchToggle = ::onSnippetSearchToggle,
        )
    }

    /** Drills the snippets panel into a folder, or backs out of one with null. */
    fun onSnippetFolderOpen(folderId: Long?) {
        vibrate()
        _uiState.update { it.copy(snippetFolderOpen = folderId, snippetPicker = null) }
    }

    /**
     * Long press on a folder in the panel: arms or disarms its triggers.
     *
     * Written straight through to the shared file, because the settings app
     * reads it as its own source of truth and would otherwise show the folder
     * still on. [snippetsStamp] is caught up in the same breath so the write
     * this process just made does not read back as somebody else's edit and
     * cost a needless reload.
     */
    fun onSnippetFolderToggle(folderId: Long) {
        val folder = snippetStore.folder(folderId) ?: return
        snippetStore.setFolderEnabled(folderId, !folder.enabled)
        _uiState.update { it.copy(snippetFolders = snippetStore.folders()) }
        serviceScope.launch {
            withContext(Dispatchers.IO) { snippetStore.save() }
            snippetsStamp = snippetsFile?.lastModified() ?: snippetsStamp
        }
    }

    /**
     * Hold on a snippet tile: shows everything that snippet has to offer,
     * instead of inserting the first thing.
     *
     * A tap stays the fast path — one tile, one insertion, no decision — and
     * this is where the rest of a snippet's expansions and the snippets it
     * links to live. Nothing happens for a tile with only one thing to say.
     */
    fun onSnippetHeld(snippet: Snippet) {
        val rows = snippetPickerRows(snippet)
        if (rows.size < 2) return
        vibrate()
        _uiState.update {
            it.copy(
                snippetPicker = SnippetPickerUi(
                    rootId = snippet.id,
                    title = snippet.label,
                    rows = rows,
                ),
            )
        }
    }

    /**
     * What the panel's picker lists for [snippet].
     *
     * A pattern snippet's captures are blanks here, exactly as a tap on its
     * tile leaves them: there is no typed text for them to have caught.
     */
    private fun snippetPickerRows(snippet: Snippet): List<SnippetChip> {
        val patternOnly = snippet.trigger.isNullOrBlank() && !snippet.triggerPattern.isNullOrBlank()
        return snippetStore
            .candidates(snippet, context = snippetContext(currentInputConnection), blank = patternOnly)
            .map(::chipOf)
    }

    /** Inserts the row the picker was holding, and closes the panel. */
    fun onSnippetPickerPick(index: Int) {
        val picker = _uiState.value.snippetPicker ?: return
        val chip = picker.rows.getOrNull(index) ?: return
        insertSnippetText(chip.text, chip.cursorOffset)
    }

    /** Shows what the linked snippet in row [index] offers. */
    fun onSnippetPickerDrill(index: Int) {
        val picker = _uiState.value.snippetPicker ?: return
        val chip = picker.rows.getOrNull(index) ?: return
        if (!chip.drillable || !picker.canDrill(chip.snippetId)) return
        val child = snippetStore.item(chip.snippetId) ?: return
        val rows = snippetPickerRows(child)
        if (rows.isEmpty()) return
        vibrate()
        _uiState.update {
            it.copy(
                snippetPicker = picker.copy(
                    title = child.label,
                    rows = rows,
                    path = picker.path + chip.snippetId,
                ),
            )
        }
    }

    /** Back out of the picker: one level up, then back to the tiles. */
    fun onSnippetPickerBack() {
        val picker = _uiState.value.snippetPicker ?: return
        if (picker.path.isEmpty()) {
            _uiState.update { it.copy(snippetPicker = null) }
            return
        }
        val path = picker.path.dropLast(1)
        val root = snippetStore.item(path.lastOrNull() ?: picker.rootId) ?: run {
            _uiState.update { it.copy(snippetPicker = null) }
            return
        }
        _uiState.update {
            it.copy(
                snippetPicker = picker.copy(
                    title = root.label,
                    rows = snippetPickerRows(root),
                    path = path,
                ),
            )
        }
    }

    fun onSnippetTapped(snippet: Snippet) {
        vibrate()
        val ic = currentInputConnection
        val context = snippetContext(ic)
        // A pattern snippet is written around what its capture groups will
        // hold, and a tap has nothing to put in them. It goes in with the
        // blanks left empty and the caret in the first one, so the user types
        // the missing part where it belongs. A plain snippet takes the ordinary
        // path, where a "$1" in its text is a dollar sign and a one.
        val text: String
        val caret: Int
        if (snippet.trigger.isNullOrBlank() && !snippet.triggerPattern.isNullOrBlank()) {
            val blank = SnippetMatcher.blankTemplate(snippet.text, context = context)
            text = blank.text
            caret = blank.blankCaret
        } else {
            val expanded = SnippetStore.expandWithCursor(snippet.text, context = context)
            text = expanded.text
            caret = expanded.cursorOffset
        }
        insertSnippetText(text, caret)
    }

    /**
     * Puts an already-expanded snippet in the field and closes the panel, or
     * leaves it open on the grid when the user asked for that (#970).
     */
    private fun insertSnippetText(text: String, caret: Int) {
        val ic = currentInputConnection
        if (ic != null) {
            ic.beginBatchEdit()
            // A word still composing commits first — a bare commitText would
            // replace the composing region with the snippet and leave the
            // stale buffer to resurrect the word at the next keystroke.
            commitComposing(ic, autocorrect = false)
            commitSplitAtCaret(ic, text, caret)
            ic.endBatchEdit()
            invalidateExpectedSelection()
            invalidateRecentWords()
        }
        val stays = _uiState.value.settings.suggestionStrip.snippetPanelStays
        _uiState.update { it.copy(panel = if (stays) it.panel else PanelMode.NONE, snippetPicker = null) }
    }

    /**
     * The app, clipboard and selection a snippet's variables expand against.
     *
     * [withSelection] is false on the typing path, where reading the selection
     * costs a blocking round-trip to answer a question already settled: a word
     * only reaches a trigger with the caret collapsed, since space and the
     * punctuation keys replace a selection and return long before this.
     */
    private fun snippetContext(
        ic: InputConnection?,
        withSelection: Boolean = true,
    ): SnippetStore.Companion.Context {
        val pkg = currentPackage
        return SnippetStore.Companion.Context(
            clipboard = clipboardStore.latestText().takeIf { isClipboardAccessible() },
            appName = pkg?.let(::appLabel),
            packageName = pkg,
            selection = if (withSelection) ic?.getSelectedText(0)?.toString() else null,
            location = locationTool::snippetLocation,
            place = locationTool::snippetPlace,
            homeAssistant = { id, attribute -> haTool.snippetValue(id, attribute) },
        )
    }

    /**
     * Re-reads the snippets file when the settings app has written to it.
     *
     * The two processes share one file with no change feed between them, so the
     * keyboard watches the modification time. Cheap enough to check whenever a
     * field opens, which is what stops a snippet saved a moment ago from
     * looking broken until the panel happens to be opened.
     */
    /**
     * How many things each snippet has to offer, for the tiles that say so.
     *
     * Only the ones with more than one are listed: the map is published into
     * the UI state on every reload, and a snippet with a single expansion —
     * which is nearly all of them — has nothing for a tile to draw.
     */
    private fun snippetCandidateCounts(): Map<Long, Int> {
        val out = HashMap<Long, Int>()
        for (snippet in snippetStore.items()) {
            if (!snippet.hasChoices()) continue
            val count = snippetStore.candidateCount(snippet)
            if (count > 1) out[snippet.id] = count
        }
        return out
    }

    private fun reloadSnippetsIfChanged() {
        val file = snippetsFile ?: return
        val stamp = file.lastModified()
        if (stamp == snippetsStamp) return
        snippetsStamp = stamp
        snippetStore.reload()
        _uiState.update {
            it.copy(
                snippets = snippetStore.items(),
                snippetFolders = snippetStore.folders(),
                snippetCandidateCounts = snippetCandidateCounts(),
                snippetPicker = null,
            )
        }
    }

    /** Human-readable label for [pkg], falling back to the package name. */
    private fun appLabel(pkg: String): String = runCatching {
        val info = packageManager.getApplicationInfo(pkg, 0)
        packageManager.getApplicationLabel(info).toString()
    }.getOrDefault(pkg)

    /**
     * Resolves the face to show for a suggested/searched emoji: the global
     * default skin tone, unless the "override with last used" option is on and
     * a variant was picked for this base (see [KeyboardSettings.emoji]).
     */
    private fun applyEmojiTone(emoji: String): String {
        val emojiSettings = _uiState.value.settings.emoji
        return _uiState.value.emojiVariants.tonedDisplay(
            base = emoji,
            tone = emojiSettings.defaultSkinTone.toneIndex,
            preferred = if (emojiSettings.toneOverrideByLastUsed) {
                emojiUsage.preferredVariant(emoji)
            } else {
                null
            },
            overrideWithPreferred = emojiSettings.toneOverrideByLastUsed,
        )
    }

    /**
     * Recomputes [KeyboardUiState.hiddenEmoji] — the emoji nothing on the
     * device can draw — for the current font and toggle, and reads the chosen
     * font's coverage tables while it is off the main thread anyway.
     *
     * The warm-up is not conditional on the toggle: every emoji drawn goes
     * through [EmojiFontShaping], so the tables are needed either way, and the
     * only question is whether the frame that draws the first emoji pays for
     * them.
     */
    private fun recomputeHiddenEmoji(settings: KeyboardSettings) {
        val catalog = emojiEntries
        val fontFile = KeyboardFonts.emojiFontFile(
            this,
            settings.emojiFont,
            settings.emojiFontInstalled.installedId,
        )
        if (!settings.emoji.hideUnrenderable || catalog.isEmpty()) {
            if (_uiState.value.hiddenEmoji.isNotEmpty()) {
                _uiState.update { it.copy(hiddenEmoji = emptySet()) }
            }
            serviceScope.launch {
                withContext(Dispatchers.Default) { EmojiFontShaping.warm(fontFile) }
            }
            return
        }
        serviceScope.launch {
            // A hand-added emoji is never hidden, drawable or not: the user
            // asked for that face by name, usually because the phone's font is
            // the thing that is behind, and the app it is sent to may draw it.
            val added = settings.emoji.added.mapTo(HashSet()) { it.emoji }
            val hidden = withContext(Dispatchers.Default) {
                EmojiFontShaping.warm(fontFile)
                EmojiRenderCheck.unrenderable(catalog.map { it.emoji }, fontFile) - added
            }
            _uiState.update { it.copy(hiddenEmoji = hidden) }
        }
    }

    /**
     * Copies [emojiUsage]'s history into the UI state — the recents and
     * most-used grids plus the favourites they pin.
     *
     * Only ever called when a history surface is off screen or about to come
     * into view (a fresh field, a panel opening or closing, the emoji row
     * being unfolded), so the grids never re-sort while the user is tapping
     * through them; a tap only marks the snapshot stale (see
     * [emojiHistoryStale]). [force] is for the panel's own history edits —
     * favouriting, removing, clearing — where the whole point of the tap is to
     * see the list change.
     */
    private fun publishEmojiHistory(force: Boolean = false) {
        if (!force && !emojiHistoryStale) return
        emojiHistoryStale = false
        _uiState.update {
            it.copy(
                emojiRecents = emojiUsage.recents(),
                emojiFrequents = emojiUsage.frequents(),
                emojiFavourites = emojiUsage.favourites(),
            )
        }
    }

    /**
     * Copies [toolUsage]'s rankings into the UI state for the toolbox's
     * orders by use. Only as the toolbox opens, the way [publishEmojiHistory]
     * waits for a history surface to come into view: a tool that runs in
     * place, Flashlight say, would otherwise reshuffle the grid it was tapped in.
     */
    private fun publishToolUsage() {
        val recent = toolUsage.recent()
        val mostUsed = toolUsage.mostUsed()
        // By the names the grid shows, so the order follows the keyboard's
        // language; a collator, so "Échange" files under E, not after Z.
        val collator = java.text.Collator.getInstance(resources.configuration.locales[0])
        val alphabetical = ToolbarTool.entries.sortedWith(
            compareBy(collator) { tool: ToolbarTool -> getString(com.wasimaster.wmkeyboard.ime.ui.toolLabelRes(tool)) },
        )
        _uiState.update { it.copy(toolsRecent = recent, toolsMostUsed = mostUsed, toolsAlphabetical = alphabetical) }
    }

    fun onEmojiTapped(emoji: String) {
        vibrate()
        commitToField(emoji)
        learnEmoji(emoji)
        recordEmojiUse(emoji)
        // An emoji one of the user's stickers carries offers that sticker, in
        // the panel as well as on the keys (#329).
        refreshStickerOffer()
        // "Return to keyboard after emoji": one insertion from the panel drops
        // straight back to the keys instead of keeping the panel open for a run.
        val closeAfter = _uiState.value.settings.emoji.closeAfterInsert &&
            _uiState.value.panel == PanelMode.EMOJI
        _uiState.update {
            it.copy(
                panel = if (closeAfter) PanelMode.NONE else it.panel,
                emojiSearchActive = if (closeAfter) false else it.emojiSearchActive,
                emojiQuery = if (closeAfter) "" else it.emojiQuery,
                emojiResults = if (closeAfter) emptyList() else it.emojiResults,
                // The ring belongs to the panel it indexes into; the panel
                // folding away takes it along.
                panelFocus = if (closeAfter) null else it.panelFocus,
            )
        }
        // The panel just uncovered the emoji row, so the row is free to take
        // the new ranking now instead of waiting for the next field.
        if (closeAfter) publishEmojiHistory()
    }

    /**
     * A kaomoji or emoticon tapped in the emoji panel's text-art tabs.
     *
     * Committed as plain text and deliberately kept out of the emoji history
     * and the bigram lexicon: "(╯°□°）╯︵ ┻━┻" is not an emoji, and both the
     * recents grid and the emoji row size their cells for a single glyph.
     */
    fun onTextArtTapped(art: String) {
        vibrate()
        commitToField(art)
        // Same "return to keyboard after emoji" courtesy as a real emoji tap.
        if (_uiState.value.settings.emoji.closeAfterInsert &&
            _uiState.value.panel == PanelMode.EMOJI
        ) {
            _uiState.update {
                it.copy(
                    panel = PanelMode.NONE,
                    emojiSearchActive = false,
                    emojiQuery = "",
                    emojiResults = emptyList(),
                )
            }
        }
    }

    /**
     * A variant picked from the long-press popup: commit it and remember it
     * as the preferred face of [base] so the grid shows it from now on.
     * Picking the plain base resets the preference.
     */
    fun onEmojiVariantPicked(base: String, variant: String) {
        emojiUsage.setPreferredVariant(base, variant)
        _uiState.update { it.copy(emojiVariantPrefs = emojiUsage.variantPrefs()) }
        onEmojiTapped(variant)
    }

    /**
     * A long-press popup opened on [emoji]: fetch its animated version, if
     * Google publishes one, so the popup can loop it.
     *
     * The preview is the WebP, which is a third of the GIF for the same
     * animation — a long press is also how skin tones and favourites are
     * reached, so most of them never send anything and shouldn't cost 800 KB.
     * The GIF is fetched only if the send button is actually pressed.
     */
    fun onEmojiLongPressed(emoji: String) {
        val key = animatedEmojiKey(emoji) ?: return
        // The preview is the part nobody asked for — most long presses are
        // after a skin tone — so data saving holds it unless it is outright
        // allowed. The send button still works: pressing it is the answer.
        animatedEmojiJob?.cancel()
        if (!dataSaverStatus.allows(MeteredFeature.ANIMATED_EMOJI)) {
            _uiState.update {
                it.copy(animatedEmojiFile = null, animatedEmojiLoading = false, animatedEmojiNoPreview = true)
            }
            return
        }
        val url = animatedEmoji.webpUrl(key)
        _uiState.update {
            it.copy(animatedEmojiFile = null, animatedEmojiLoading = true, animatedEmojiNoPreview = false)
        }
        animatedEmojiJob = serviceScope.launch {
            val file = withContext(Dispatchers.IO) { downloadMediaFile(url, MediaMime.WEBP) }
            _uiState.update {
                it.copy(animatedEmojiFile = file, animatedEmojiLoading = false, animatedEmojiNoPreview = file == null)
            }
        }
    }

    /** The popup closed: stop the fetch and drop the preview. */
    fun onEmojiLongPressDismissed() {
        animatedEmojiJob?.cancel()
        animatedEmojiJob = null
        _uiState.update {
            it.copy(animatedEmojiFile = null, animatedEmojiLoading = false, animatedEmojiNoPreview = false)
        }
    }

    /**
     * The animated key for [emoji], honouring the setting and the field: a
     * field that takes no images has nowhere to put a GIF.
     */
    private fun animatedEmojiKey(emoji: String): String? {
        val state = _uiState.value
        if (!state.settings.emoji.animated || !state.acceptsRichMedia) return null
        return state.animatedEmoji.keyFor(emoji)
    }

    /**
     * "Send animated emoji" in the long-press popup: fetches the 512×512 GIF
     * and commits it through the same content path as a sticker. Counts as
     * using the emoji, so it lands in recents like a plain tap would.
     *
     * The GIF rather than the WebP already in hand: an app that accepts
     * `image/webp` may still draw only its first frame, and a still emoji is
     * not what the button promised.
     */
    fun onAnimatedEmojiSend(emoji: String) {
        val key = animatedEmojiKey(emoji) ?: return
        when (dataSaverStatus.decide(MeteredFeature.ANIMATED_EMOJI)) {
            // Pressing send on a metered connection is the yes the setting
            // asked for, and it holds for the rest of the session.
            MeteredDecision.ASK -> grantMetered(MeteredFeature.ANIMATED_EMOJI)
            // The button is not drawn in this case; guarded anyway, since a
            // hardware shortcut could still reach here.
            MeteredDecision.BLOCKED -> return
            MeteredDecision.ALLOWED -> Unit
        }
        recordEmojiUse(emoji)
        // The popup deliberately stays open, preview and all: sending one
        // animation is usually not the last thing someone wants to do with it,
        // and a popup that empties itself on the way out reads as a glitch.
        // The ordinary media path from here: it vibrates, publishes the id the
        // popup spins on while the file comes down, and toasts if it doesn't.
        insertDownloadedImage(
            key,
            animatedEmoji.gifUrl(key),
            MediaMime.GIF,
            _uiState.value.settings.gif.sendMode,
        )
    }

    /**
     * "Send as sticker" in the long-press popup: draws [emoji] itself at
     * 512×512 in the keyboard's own emoji font and commits it as a WebP
     * sticker, so a face the receiving app has no font for still arrives as
     * the picture the sender saw.
     *
     * Rendered rather than downloaded — the glyph is already on the device —
     * so this works offline and sends nothing anywhere.
     */
    fun onEmojiStickerSend(emoji: String) {
        val state = _uiState.value
        if (!state.settings.emoji.sendAsSticker || !state.acceptsRichMedia) return
        if (state.mediaDownloadingId != null) return
        vibrate()
        recordEmojiUse(emoji)
        startMediaDownload(emojiStickerJobId(emoji))
        mediaInsertJob = serviceScope.launch {
            // Off the main thread as far as the provider call, which can be a
            // download the very first time Noto is asked for on a device.
            val typeface = KeyboardFonts.emojiTypeface(
                this@WMKeyboardService,
                state.settings.emojiFont,
                state.settings.emojiFontInstalled.installedId,
            )
            val file = withContext(Dispatchers.Default) { renderEmojiSticker(emoji, typeface) }
            endMediaDownload()
            if (file == null) {
                Toast.makeText(
                    this@WMKeyboardService,
                    getString(R.string.ime_service_media_download_error_toast),
                    Toast.LENGTH_SHORT,
                ).show()
                return@launch
            }
            // The sticker tool's own send mode, so one preference governs
            // every sticker the keyboard sends and WhatsApp keeps getting real
            // ones. Anybody an app treats badly for it has a lever already.
            commitImageFile(file, MediaMime.WEBP, state.settings.stickerSendMode)
        }
    }

    /**
     * Draws one emoji into a square transparent WebP, in whichever font the
     * keyboard draws it with — an imported or installed face by its own file,
     * anything else by the phone's own emoji font, which is what "System" and
     * "Google" both come down to once there is no file to load.
     *
     * Blocking; call it off the main thread. Cached per emoji *and* font, so
     * changing the font doesn't keep sending the old face.
     */
    private fun renderEmojiSticker(emoji: String, chosen: Typeface?): File? = runCatching {
        val settings = _uiState.value.settings
        val fontFile = KeyboardFonts.emojiFontFile(
            this,
            settings.emojiFont,
            settings.emojiFontInstalled.installedId,
        )
        // The same spelling the panel draws: a font with no variation-selector
        // table cannot resolve ❤️, and the shaper's answer is to strip the
        // selector or hand the glyph back to the system font. Only a font with
        // a file has tables to read; Noto and the system font are trusted with
        // the emoji as written.
        val spelling = EmojiFontShaping.forFontFile(fontFile).spelling(emoji)
        val typeface = chosen?.takeIf { !spelling.systemFont }

        val dir = File(cacheDir, "media").apply { mkdirs() }
        pruneMediaCache(dir)
        val stamp = "$STICKER_RENDER_VERSION|${spelling.text}|" +
            "${settings.emojiFont}|${settings.emojiFontInstalled.installedId}"
        // Digested, not hashCode()'d. A 32-bit hash over a couple of thousand
        // emoji collides in practice, not in theory: 😘 and 🧹 land on the same
        // number, so whoever sent the broom second got a kiss out of the cache.
        val target = File(dir, "emoji_${digest(stamp)}.webp")
        if (target.exists() && target.length() > 0L) return@runCatching target

        val bitmap = createBitmap(StickerImage.TARGET_SIZE, StickerImage.TARGET_SIZE)
        val paint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
            this.typeface = typeface
            textAlign = Paint.Align.CENTER
            textSize = STICKER_GLYPH_PX
        }
        // Emoji fonts vary in how much of the em square they fill, so the size
        // is measured rather than assumed: draw once at a nominal size, then
        // scale by what came back so every sticker fills its frame the same.
        val bounds = Rect()
        paint.getTextBounds(spelling.text, 0, spelling.text.length, bounds)
        if (bounds.width() > 0 && bounds.height() > 0) {
            val scale = STICKER_GLYPH_PX / maxOf(bounds.width(), bounds.height()).toFloat()
            paint.textSize *= scale
            paint.getTextBounds(spelling.text, 0, spelling.text.length, bounds)
        }
        Canvas(bitmap).drawText(
            spelling.text,
            StickerImage.TARGET_SIZE / 2f,
            StickerImage.TARGET_SIZE / 2f - bounds.exactCenterY(),
            paint,
        )
        // Encoded by the sticker tool's own encoder rather than by hand, so
        // what leaves here has the same shape as a sticker from a pack: same
        // size, same lossy WebP, same 100 KB ceiling. A difference between the
        // two is a difference in how apps treat them, and there is no reason
        // for one to exist.
        val png = ByteArrayOutputStream().also {
            bitmap.compress(Bitmap.CompressFormat.PNG, 100, it)
        }.toByteArray()
        bitmap.recycle()
        val processed = (StickerImage.process(png) as? StickerImage.Result.Ok)?.sticker
            ?: return@runCatching null
        target.writeBytes(processed.bytes)
        target
    }.getOrNull()

    /** A short, collision-free name for a cache key of any shape. */
    private fun digest(key: String): String =
        java.security.MessageDigest.getInstance("SHA-256")
            .digest(key.toByteArray())
            .take(8)
            .joinToString("") { "%02x".format(it) }




